INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gece', 'ey-gece-ali-osman-yilmaz-r6i60', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur altında sırılsıklam,

Her yan karanlık,

Sen beni görürsün,gece,

Ben seni görürüm,

Sen ve ben yapayalnız,

Güneşin kayalıklardan,

Parlamasını bekleriz.

Ey gece,

Ne gariptir ki,

Sen benim için bir baba gibisin,

Bense hayalperest oğlun.

Sana umutlarımı,arzularımı anlattım,

Sesin,çiçeklerin fısıltısı gibi tatlı,

Yürek yatıştırıcı bir ezgi gibi,

Korkularımı sende yitirdim,

Kuşlardan bile daha huzurluyum,

Gözlerimle seni görmeyi,

Kulaklarımla seni duymayı,

Dudaklarımla seninle konuşmayı,

Nefret dolu yüreğime sevmeyi,

Aşkın kollarında dans etmeyi,

Sen öğrettin bana.

Şefkat dolu ellerinle,

Düşüncelerime dokundun,

Şimdi düşlerim,nehir gibi akıyor,

Ateşler içindeki ruhuma,

Kondurduğun öpüşünle,

Kavrulmakta olan ruhum,

Bir meşale gibi ışıldıyor.

Ve yüreğimde düşlerimin,

Alaylarını ışıtan ay parlıyor,

Sessizlik,uykusuz ruhuma,

Aşkımın sırlarını açıklıyor,

Ve bilirmisin artık biz? 

Birbirimize benziyoruz.', 'Yağmur altında sırılsıklam, Her yan karanlık, Sen beni görürsün,gece, Ben seni görürüm, Sen ve ben yapayalnız, Güneşin kayalıklardan, Parlam...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ey-gece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkibin dört', 'i-kibin-dort-sabit-i-nce-qq2uv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Keşke gelmeseydin kara getirdin,

dostlarımı bir bir alıp götürdün,

kolum kanadımı kırdın bitirdin,

ikibin dört yılı karalı dostlar.

Sefil selimi''yi aldın elimden,

Nezahat Bayramı çaldın dilimden,

Atila İçli''yi sildin filimden,

İkibin dört yılı yaralı dostlar.

Garip Ozan''ımdı sustu çalmıyor,

Soyuersiz artık şiir olmuyor,

hayırsız dostlarım haber vermiyor,

sazımda tellerim duralı dostlar.

Ne şeytan isterim ne de bir melek 

yanan yüreğimde  kalmadı dilek 

Bana mı zorun var ey kahpe felek,

İnce bir canım var sıralı dostlar.

Sabit ince Kayseri 19.02.2004', 'Keşke gelmeseydin kara getirdin, dostlarımı bir bir alıp götürdün, kolum kanadımı kırdın bitirdin, ikibin dört yılı karalı dostlar. Sefil se...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ikibin-dort-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara Kaldı', 'bahara-kaldi-i-brahim-ethem-bingul-s5pnw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selâmımı yolladım sevgiliye 

Bir gül ile 

Gözü kör, kulağı sağır 

Yüreği demir, kanadı kurşun kuş ile 

Onu ne kadar sevdiğimi anlasın diye 

Selâmımı almış gül ile 

Gül, bülbül olmuş yâr ile 

Anlatmış beni sevgiliye 

Sevgili üzülmüş halime 

Almış gülü eline 

Demiş ki güle; 

Git sevgiliye söyle 

Geleceğim baharda sevgim ile 

Öpmüş de gülü geri yollamış selâm ile 

Selâm gelmiş, gül gelmiş 

Lâkin ağlamada gül 

Geriye döndü diye 

Aşk ile gitmişti sevgiliye 

Gönderildi öpülerek öylesine bir haberle 

Gül ağlar, yâr ağlar 

Baharlar da beklemekten ağlar şimdi halimize', 'Selâmımı yolladım sevgiliye  Bir gül ile  Gözü kör, kulağı sağır  Yüreği demir, kanadı kurşun kuş ile  Onu ne kadar sevdiğimi anlasın diye  ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bahara-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinde Sen Kaldın', 'i-cinde-sen-kaldin-vahittin-bozgeyik-vcu96', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Giysilerce diktin gönlümü; 

Mezada saldın...

Dikmemeliydin terzinin kızı

İçinde sen kaldın.', 'Giysilerce diktin gönlümü;  Mezada saldın... Dikmemeliydin terzinin kızı İçinde sen kaldın....', ARRAY['Türk Edebiyatı','Şiir','Vahittin Bozgeyik']::text[], 8.5, '{"poet":"Vahittin Bozgeyik","poet_slug":"vahittin-bozgeyik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/icinde-sen-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-gokhan-oflazoglu-u5evb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gündelik gerçeğimiz

sihirli ölçeğimiz.

Kimseye zarar vermiyorsa,

neden söylemiyim.

Aslında severiz

sanki aşımız,

ne ayıp deriz.

Çok sıkışmışsam,

neden söylemiyim.

En çalışkanımız

bazen can yoldaşımız.

Şurda üç beş kişiyiz,

yalan söylemeyin.

Birbirimizi biliriz.

18/02/2004', 'Gündelik gerçeğimiz sihirli ölçeğimiz. Kimseye zarar vermiyorsa, neden söylemiyim. Aslında severiz sanki aşımız, ne ayıp deriz. Çok sıkışmış...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalan-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedim Dilber Gel Bir Pazar Edelim', 'dedim-dilber-gel-bir-pazar-edelim-ruhsati-tfqkt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dedim dilber gel bir pazar edelim

Dedi ben alışı verişi bilmem

Dedim muhabbetten kuralım çarşı

Dedi ben tenhada görüşü bilmem

Dedim işittin mi Ferhat-Şirin''i

Dedi aşk yoluna vermiş varını

Dedim Ferhat vermedi mi serini

Dedi düşmanım çok, şer işi bilmem

Dedim Kerem yanmış Aslı yoluna

Dedi Aslı düşmüş elin diline

Dedim Kamber ölmüş Arzu yoluna

Dedi ben inkisar, kargışı bilmem

Dedim Ruhsat sana olmuş mülâzim

Dedi bir ruhsat da olsun ne lazım

Dedim eğer kabul olsa niyazım

Dedi ben oraya varışı bilmem', 'Dedim dilber gel bir pazar edelim Dedi ben alışı verişi bilmem Dedim muhabbetten kuralım çarşı Dedi ben tenhada görüşü bilmem Dedim işittin ...', ARRAY['Türk Edebiyatı','Şiir','Ruhsati']::text[], 8.5, '{"poet":"Ruhsati","poet_slug":"ruhsati","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dedim-dilber-gel-bir-pazar-edelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçları Kıvırcık Çocuk', 'saclari-kivircik-cocuk-zafer-zengin-etnika-06ojz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'saçları kıvırcık çocuk

gelişi bayram

gidişi isyan

son bakışında

        cabuk pes etti

dayanamadı

dünyanın ağırlığına...

şimdi

deliliğe söylüyor son türküsünü...

bu ne şiddet

            bu ne yalnızlık

bu ne sahipsiz hayat

kimliğini unutuyor felsefe içinde...

yazıyor feryadını,ferman ferman

isyan isyan...

delilerin gülüşü şizofren güller açar

           her açan gül yalnızlığa bakar

tutun ellerinden,insanı gül yakar...

gözledikçe hayatı,sancısı artıyor

en kötüsüde çaresizlik...

19 subat 2004', 'saçları kıvırcık çocuk gelişi bayram gidişi isyan son bakışında         cabuk pes etti dayanamadı dünyanın ağırlığına... şimdi deliliğe söyl...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/saclari-kivircik-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Eğlenir Mi Gurbet Ellerde', 'gonul-eglenir-mi-gurbet-ellerde-ruhsati-lgytq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül eğlenir mi gurbet ellerde

On dokuz bölüklü kız olmayınca

Garip bülbül gibi öter dillerde

Açılıp gülleri yaz olmayınca

Ne müşküldür karlı dağı devirmek

Yönün sevdiğine doğru çevirmek

Âşıka şayeste türkü çağırmak

Onun da tadı yok saz olmayınca

Sevda dolu Ruhsati''nin meyinde

Ah ü zârım kaldı kaşı yayında

Sevdiğim Hafik''in Gulam köyünde

Bu yıl da gidemem yaz olmayınca', 'Gönül eğlenir mi gurbet ellerde On dokuz bölüklü kız olmayınca Garip bülbül gibi öter dillerde Açılıp gülleri yaz olmayınca Ne müşküldür kar...', ARRAY['Türk Edebiyatı','Şiir','Ruhsati']::text[], 8.5, '{"poet":"Ruhsati","poet_slug":"ruhsati","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-eglenir-mi-gurbet-ellerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AYNAMIZI Kırdılar!', 'aynamizi-kirdilar-ozan-si-ar-agdasan-315wv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaynaştık ''bir resim'' olduk

''KIRDILAR'' aynamızı

İki can ''bir kalbe'' dolduk

''YARDILAR'' aynamızı...

Kafesime poyraz esti

Düştü camı, elim kesti

Aşk alevim dilim kesti

''VURDULAR'' aynamızı

ŞİAR umut, sevgi candan

Işık şavkı, yansır camdan

Haramiler dört bir yandan

''SARDILAR'' aynamızı! ...

KIRDILAR aynamızı

YARDILAR aynamızı! ...

Söz ve Müzik: ŞİAR Ağdaşan   ''İnadına Sevdamız'' Kitabı  www.siarcan.com

Yorum ve aranje: Ozan ŞAH TURNA ''ŞAHTURNA KÜLTÜR ve SANAT EVİ''

www.sahturna.com    ''Klasikler'' Müzik albümü', 'Kaynaştık ''bir resim'' olduk ''KIRDILAR'' aynamızı İki can ''bir kalbe'' dolduk ''YARDILAR'' aynamızı... Kafesime poyraz esti Düştü camı, elim kest...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aynamizi-kirdilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hele Bir Düşün Ki Gözümün Nuru', 'hele-bir-dusun-ki-gozumun-nuru-ruhsati-0d84g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hele bir düşün ki gözümün nuru

Bu kadar parayı sana kim verdi

Bazı fukaraya bulma kusuru

Mesti kundurayı sana kim verdi

Anadan doğunca kürkün var mıydı

Üryan gelmedin mi börkün var mıydı

Torba torba mecidiyen var mıydı

Tükenmez parayı sana kim verdi

Kuş tüyü döşekte yattın uzandın

Haftada bir çeşit geydin özendin

Aferin aklına sen mi kazandın

Şu tompu tarlayı sana kim verdi

Dinle Ruhsati''yi ne diyom sana

İyi bir öğüttür sanma ki çene

Çalışmayla verse verirdi bana

Bu köşkü sarayı sana kim verdi', 'Hele bir düşün ki gözümün nuru Bu kadar parayı sana kim verdi Bazı fukaraya bulma kusuru Mesti kundurayı sana kim verdi Anadan doğunca kürkü...', ARRAY['Türk Edebiyatı','Şiir','Ruhsati']::text[], 8.5, '{"poet":"Ruhsati","poet_slug":"ruhsati","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hele-bir-dusun-ki-gozumun-nuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Sabah Her Sabah Dertli Esersin', 'her-sabah-her-sabah-dertli-esersin-ruhsati-wg3zu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her sabah her sabah dertli esersin

Bilmem ki muradın ne seher yeli

Kerem eyle dost köyüne gidersen

Benim de halimi de seher yeli

Hasret kıyamete kalıyor deyu

Yaralar vücudum alıyor deyu

Derd ü firkat i le ölüyor deyu

İsmimi deftere ko seher yeli

Bozuk dünya sefasına erilmez

Adûlar içinde bir gün görülmez

Bizim bu işimiz burda görülmez

Çekelim ah ile hu seher yeli

Ne acayip dumanlıdır başımız

Kırk yediye yüz döndürdü yaşımız

Kerbelâ cengine döndü işimiz

El-aman bir damla su seher yeli

Kerem eyle Medine''ye varasın

Arzıhalim doğru dosta sunasın

Varsın Ruhsatî''yi eller kınasın

Akıyor gözümden su seher yeli', 'Her sabah her sabah dertli esersin Bilmem ki muradın ne seher yeli Kerem eyle dost köyüne gidersen Benim de halimi de seher yeli Hasret kıya...', ARRAY['Türk Edebiyatı','Şiir','Ruhsati']::text[], 8.5, '{"poet":"Ruhsati","poet_slug":"ruhsati","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/her-sabah-her-sabah-dertli-esersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keklik Gibi Taştan Taşa Sekerek', 'keklik-gibi-tastan-tasa-sekerek-ruhsati-pb8hu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Keklik gibi taştan taşa sekerek

Gerdan açıp gelişini sevdiğim

Sağa sola taksim etmiş örgüsün

Onar onar bölüşünü sevdiğim

Onaltıya karar verdim yaşını

Yenice sevdaya salmış başını

El yanında yıkar gider kaşını

Tenhalarda gülüşünü sevdiğim

Sarardı gül benzim soldu diyerek

Hasret kıyamete kaldı diyerek

Hani Ruhsati de n''oldu diyerek

Arayıp da buluşunu sevdiğim', 'Keklik gibi taştan taşa sekerek Gerdan açıp gelişini sevdiğim Sağa sola taksim etmiş örgüsün Onar onar bölüşünü sevdiğim Onaltıya karar verd...', ARRAY['Türk Edebiyatı','Şiir','Ruhsati']::text[], 8.5, '{"poet":"Ruhsati","poet_slug":"ruhsati","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/keklik-gibi-tastan-tasa-sekerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasımpatılar', 'kasimpatilar-zafer-zengin-etnika-6q2yc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kasımpatılar ektim gözlerine

gül de

açılsınlar

sarı

kırmızı

beyaz

bana askerliğimi hatırlatırlar

hatıralar,sebepsiz geliyorlar düşlerimize...Gülümsüyoruz

19 subat 2004', 'Kasımpatılar ektim gözlerine gül de açılsınlar sarı kırmızı beyaz bana askerliğimi hatırlatırlar hatıralar,sebepsiz geliyorlar düşlerimize.....', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kasimpatilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideyim ben artık..', 'gideyim-ben-artik-hasan-basri-kale-ks5zm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Odam yine ıssız aylar sonra

Duvarlar sağır..

Uzaklaşan ayak sesleri

kulağımda..ağır ağır.

Günün neresindeyiz

Yoksa gece mi oldu..? 

Daha dün bütün canlılığıyla

vazomdaydı gülüm..

Birdenbire neden soldu.? 

Unuttum şiiri,sözü,sazı..

Geçmiş ve gelecek zamanı.

Gong çaldı...Perde kapandı

Vakit geldi canlar..gideyim ben artık

Şimdi gitme zamanı..', 'Odam yine ıssız aylar sonra Duvarlar sağır.. Uzaklaşan ayak sesleri kulağımda..ağır ağır. Günün neresindeyiz Yoksa gece mi oldu..?  Daha dün...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gideyim-ben-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-serdar-safran-ef2wq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizim köyü bir binaya tıkmışlar

Baktım dostluğa,ilgiye açlar

Birbirinden habersiz vatandaşlar

Ben köyümü özledim…

Selam vermekten yoksunlar

Gelip bizim köye baksınlar

Biraz misafir kalsınlar

Ben köyümü özledim…

Gece,gündüz debdebeye

Kapılmışlar  hengameye

Olmuşlar kul,sermaye ye

Ben köyümü özledim…

Olmuş herkes birer ağa

Ayak uydurmuşlar çağa

Değişmem hiç,bizim dağa

Ben köyümü özledim…

Selam verince yadırganır

Hemen çıkar aranır

Tanışlık! ...büyük hata sanır

Ben köyümü özledim….

Moda nedir anlamadım

Alamadım,giyemedim

İstediğim yiyemedim

Ben köyümü özledim…

Komşusundan habersiz

Bilmem neler yersiniz

Bir gün göçer,gidersiniz

Ben köyümü özledim…

Hasta,sökel,ihtiyaç

Herkes kendine ilaç

İnsan insana muhtaç

Ben köyümü özledim…

Yaşarım onurumla

Paylaşırım komşumla

Ekmeğim ortak benim

Ben köyümü özledim…

2004(Kastamonu)', 'Bizim köyü bir binaya tıkmışlar Baktım dostluğa,ilgiye açlar Birbirinden habersiz vatandaşlar Ben köyümü özledim… Selam vermekten yoksunlar ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ozledim-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henüz bitmedi….! ! !', 'henuz-bitmedi-nazife-abayli-mmqw0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğuştan başlamış yaşamla savaşım,

Dokuz aylıkken, bilinmeyen bir derde yakalanmışım.

Koma halinde bulmuş annem beni ocak başında,

Götürmedikleri doktor,hastane kalmamış.

Çaresi yok demişler,günlerce başımda beklemişler

Seferber olmuş köy halkı,dağ bayır yürümüşler,

Hocalara bile götürmüşler.

On beş gün sonra açmışım gözlerimi,bayram etmişler.

Sonra şehre yerleşmiş babam,

Bıkmış sanırım,dağ yollarının yamaçlarından…

Anımsıyorum dün gibi,

Zindan Mahallesi ve Boztepe’yi,

İki katlı,sarı boyalı evi.

Alman bir komşumuz vardı,

Yıllardır yalnız yaşardı.

Adı Hans’tı.

Kırk beş,elli yaşlarındaydı.

Bilirdim çok severdi beni,

Bazen elimden tutup gezdirirdi.

Pazara gittiğinde annem,

Pencerenin önüne oturur,dışarıyı izlerdim,

Hans’ı gördüğümde,nasıl da sevinirdim.

Beş yaşındaydım.

Oynarken bir gün kapının önünde,

Anımsamıyorum,annem anlatır sonrasını,

Mahalleden uzaklaşmışım.

Çiçek toplayacakmışım..

Boztepe’nin,küçük limana bakan yamacında,

Altı deniz,dik uçurumun başında,

Elimde çiçekler,kaymışım.

Otlara tutunmuşum tek elimle,on beş metre kaydıktan sonra.

Zindan kapısından geçenlerden birisi,

Duyunca ağlama seslerimi,

Koşmuş ama……

Kurtarması imkansızmış..

Tüm mahalleyi ayağa kaldırmış,

Annem de beni ararmış.

Koşanları görünce uçurumun başına,

Ben olduğumu anlamış,

Uzun bir ip bulmuşlar,

Hans’ın beline bağlamışlar,

Aşağı salmışlar,

Kurtarmış,

Çekmeden içine deniz beni…

Görünce elimden bırakmadığım çiçekleri,

Almış birkaç tanesini.

En son on iki yaşımda gördüm Hans’ı,

Elimden aldığı kır çiçeklerini,

Kitap arasında,halen sakladığını söyledi..

Ülkesine dönecekti,

Ailemden evlatlık istedi beni,

Babam vermedi.

Vedalaşırken bana,

“Alırken uçurumdan seni,

Gözlerini gördüm..

Biliyorum..

O gözleri…

Kimse ağlatamayacak,

Güçlüsün sen! ” dedi.

Halen çok severim kır çiçeklerini,

Hans’ın da dediği gibi,

Kimse ağlatamadı gözlerimi,

Ama yaşamla savaşım,

Ocak başı ve uçurumda başladı…

Yıllarca devam etti…

Ve………

Henüz bitmedi….! ! !', 'Doğuştan başlamış yaşamla savaşım, Dokuz aylıkken, bilinmeyen bir derde yakalanmışım. Koma halinde bulmuş annem beni ocak başında, Götürmedi...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/henuz-bitmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henüz Bitmedi Demiştim!', 'henuz-bitmedi-demistim-nazife-abayli-afxum', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Henüz bitmedi demiştim,

Yaşamla savaşım..

İlkinde bebektim,

Büyüdüm çocuk oldum.

Genç kız oldum sonra,

Ne zorluklar varmış daha daha…

Gördüm…

Ve….

Yenilmedim…

Savaştım..

Çirkinliklerle,fesatlıklarla…

Bükemediler,

Yazmayı bilmeyenler,

Kalem tutan elimi.

Susturamadılar,

Konuşmayı beceremeyenler,

Sevda türküleri söyleyen dilimi.

Kin,nefret ve kötülükle dolduramadılar,

İyilikten anlamayanlar,

Dost hasretiyle yanan yüreğimi.

Kadın oldum sonrasında.

Anne oldum.

Yeni yeni güzellikleri gördüm.

Çirkinlikleri de…

Daha da doldum…

Şimdi Hazan’ı yaşıyorum.

Savaş bitmedi biliyorum..

Her türlü çirkinliğin,

Üstesinden gelecek kadar da..

Cesurum….', 'Henüz bitmedi demiştim, Yaşamla savaşım.. İlkinde bebektim, Büyüdüm çocuk oldum. Genç kız oldum sonra, Ne zorluklar varmış daha daha… Gördüm...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/henuz-bitmedi-demistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Bir Geceyi Daha Atlattım! !', 'karanlik-bir-geceyi-daha-atlattim-nazife-abayli-xchme', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık bir geceyi daha atlattım.

Tan yeri uyanırken yine,

Yeni doğan güneşi selamladım.

Üşümüştü bedenim,

Isındım.

Aydınlığıyla…..

Karanlıktan gelen,

Korkularımdan sıyrıldım.

Çünkü…

Titreyen yüreğimi dinginleştiren,

Cesaret veren,

Canıma can katan,

Sesinle uyandım.

Ve ben….

Her yeni günde,

Karanlığın ardından,

Selamlarım güneşi.

Duyabilmek için,

Sesime ses veren…

Sesini…

Ve o sesteki,

Sevgi sözcüklerini…

18.02.2002      08:50', 'Karanlık bir geceyi daha atlattım. Tan yeri uyanırken yine, Yeni doğan güneşi selamladım. Üşümüştü bedenim, Isındım. Aydınlığıyla….. Karanlı...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/karanlik-bir-geceyi-daha-atlattim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle dünyaya', 'boyle-dunyaya-burhan-kucuk-c3hx6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Böyle dünyaya

Umutsuzluk içini kaplamışsa

Yarınlar cam gibi kırılmışsa

Aldanışlar Art arda geliyorsa

Bıçak gibi saplanıyorsa

İhanetler yüreğini parçalarcasına

Kurşunlar çıkmışsa

Güvendiğin ellerden

Yüreğine saplanmışsa

Kalabalığın ortasında

Yapayalnızsan..

Yüreğin ağustosta üşümüş

Zemheride yanmışsa

Küçülmüşsen,ufalmışsan

Sevmekten..

Tutma gözyaşlarını aksın

Ve tükür geç böyle dünyaya...

Burhan KÜÇÜK

Kdz.Ereğli-2000', 'Böyle dünyaya Umutsuzluk içini kaplamışsa Yarınlar cam gibi kırılmışsa Aldanışlar Art arda geliyorsa Bıçak gibi saplanıyorsa İhanetler yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/boyle-dunyaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahane', 'bahane-selami-selok-czr4p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz başlayan her güne,

lanet etmektense, 

ölmek daha dürüstçe olur,

dizlerimin kırıldığı yerde.

Ama ben ne yapıp edip,

beni sevmediğini bilsem de,

bir bahane bulmalıyım.

Yaşamak için bir bahane.', 'Sensiz başlayan her güne, lanet etmektense,  ölmek daha dürüstçe olur, dizlerimin kırıldığı yerde. Ama ben ne yapıp edip, beni sevmediğini b...', ARRAY['Türk Edebiyatı','Şiir','Selami Selok']::text[], 8.5, '{"poet":"Selami Selok","poet_slug":"selami-selok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahane-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancı', 'sanci-selami-selok-ms7xv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstediğim sensin.

Başkalarını görmüyor gözüm,

benim istediğim sensin.

Herşeyi anlattın biliyorum.

Nasıl birşey bu,

kendime söz geçiremiyorum.

Zehirli duygular bunlar,

öldürseler iyi ama,

öldürmüyor kitapsızlar.

Ne yapayım, hala seni bekliyor bir yanım.

Ama bir bilsen,

nasıl sancıyor öbür yanım.', 'İstediğim sensin. Başkalarını görmüyor gözüm, benim istediğim sensin. Herşeyi anlattın biliyorum. Nasıl birşey bu, kendime söz geçiremiyorum...', ARRAY['Türk Edebiyatı','Şiir','Selami Selok']::text[], 8.5, '{"poet":"Selami Selok","poet_slug":"selami-selok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanci-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarnıç', 'sarnic-selami-selok-bf19r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzun yolculukların adamıyım ben,

uzun yolculukların.

İlk mola yerinde unutulduğum,

uzun yolculukların.

Pembe rüyaların adamıyım ben,

pembe rüyaların.

En güzel yerinde uyandığım,

pembe rüyaların.

Yaşanmamış aşkların adamıyım ben,

tutulmamış ellerin,

öpülmemiş dudakların.

Unutmak isteyip de unutamadığım,

hazin hatıraların,

sarnıcıyım ben.', 'Uzun yolculukların adamıyım ben, uzun yolculukların. İlk mola yerinde unutulduğum, uzun yolculukların. Pembe rüyaların adamıyım ben, pembe r...', ARRAY['Türk Edebiyatı','Şiir','Selami Selok']::text[], 8.5, '{"poet":"Selami Selok","poet_slug":"selami-selok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sarnic-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güçlü ve güçsüz Anım*', 'guclu-ve-gucsuz-anim-bayram-tunca-h8262', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En güçlü ânım, nefis ve şeytana yenilmediğim an 

En güçsüz anımsa nefis ve şeytana yenildiğim an 

İsterim ki; onlara mağlup olacağıma çıksın canım 

Akacaksa, bu uğurda varsın aksın terim ve kanım 

16.02.2004-16.02', 'En güçlü ânım, nefis ve şeytana yenilmediğim an  En güçsüz anımsa nefis ve şeytana yenildiğim an  İsterim ki; onlara mağlup olacağıma çıksın...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guclu-ve-gucsuz-anim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat Emelimdir', 'vuslat-emelimdir-engin-namli-bc0v4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretin kokusunu kesmeyin rüzgarlar

Tütsün göklerde gönlüme gelene kadar

İnmesin hiç bir yere çiğnemesin kullar	

Yoluna baş koyduğum vuslat emelimdir

Çekilsin semaya seyre dalsın güneşi	

Gelip geçsin bulutlar yakmasın ateşi	

Yıldızlar arasında beklesin bu eşi	

Yoluna baş koyduğum vuslat emelimdir

Tanın aydınlığında ufkun göbeğinde

Görsün bu gözler hep onu gözbebeğinde

Bağlanıp ta kalsın kirpiğim ilmeğinde

Yoluna baş koyduğum vuslat emelimdir

ENGİN NAMLI   10.02.2004  22:18', 'Hasretin kokusunu kesmeyin rüzgarlar Tütsün göklerde gönlüme gelene kadar İnmesin hiç bir yere çiğnemesin kullar	 Yoluna baş koyduğum vuslat...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vuslat-emelimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-esma-ozdemir-2mb33', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat, bir çatı

Sen ise, o çatının altında

Bir temel direk olmalısın

Dünya evinde.

Ve yaşamak, direnmektir 

Unutma! 

Direndiğin kadar varsın

Bu kısa hayatta...

Bana göre hayat, bir rüya

Yaşamak, gülümsemektir

Sevgi ise tek gerçektir; 

Sevildiğin kadar uzun yaşarsın

Sevgili hayatta...', 'Hayat, bir çatı Sen ise, o çatının altında Bir temel direk olmalısın Dünya evinde. Ve yaşamak, direnmektir  Unutma!  Direndiğin kadar varsın...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gercek-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani,... Atları da Vururlar Ya....!', 'hani-atlari-da-vururlar-ya-mine-ozdemirtas-r1i43', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim Çocukluğumda,

Boğaz’da

Bir Beykoz karakolu vardı

Tam deniz kıyısında.

İçinde hüküm sürerdi

Pos bıyıklı, şişman

Kırmızı yanaklı

Komser Amca.

Bir akşam

Camdan boğaza

Saldığı oltasına

8 yaşındaki ben,

Cılız bacaklarımdan 

Yakalanınca

Çok  paniklemişti önce

Sonra, kükreyerek

Sarılmıştı ilaca.

Kanayan yarama 

Üfleyerek

Oksijeni basınca

Ağlamıştım da

Silince sümüklerimi kolumla

Gülmüştü dakikalarca.

Ve kulağıma eğilip

“Umarım bundan ders alır

Ve bir daha

Gözü kara

Dalmazsın karanlık sulara”

Diye fısıldamıştı usulca.

Kim ben mi? 

Ben mi ders alacağım

Hay allah

Sen çok yaşa emi

Komser Amca.

Yıllar geçti aradan,

Büyüdüm büyümesine ama,

Hep sakar bir yüzücü

Olarak kaldım.

Hayatım boyunca.

Gene, Balıklama ve Gözü kara

Atlamayı sürdürüyorum

Dibi görünmeyen

Karanlık sulara.

Hala inanıyorum 

Yakamozlarla ilgili masallara.

Yine, bacağım dolanık oltalara

Yine,etimde paslı kanca

Kanırtıp kanatmakta.

Bükülüp,kırıldığımı

Ve tükendiğini soluğumun

Senden başka,

Ne Gören var Ne de bilen

Komser amca.

Eğer hayattaysan,

Geçmişin hatırına,

Şöyle bir baksan diyorum 

Tozlu raflara.

Belki o eski,

Yakan ve acıtan ilacından

Birkaç damla

Duruyordur hala? ? ? ? ? ? ? ? ? ? 

Eğer yoksa! ....

Söylemeye dilim varmıyor ama,

Cins olsam da

Tendon koptu bir kez.

Hani.....Atları da vururlar ya? 

Belki de  kolaydadır hıı? 

Beylik tabanca................! 

19/02/2004..ist. (Eğer hala yaşıyorsan, sağlık ve esenlik diliyorum. Kulakların çınlasın Komiser  amca.Eğer, yoksan artık.... ruhun şad olsun)', 'Benim Çocukluğumda, Boğaz’da Bir Beykoz karakolu vardı Tam deniz kıyısında. İçinde hüküm sürerdi Pos bıyıklı, şişman Kırmızı yanaklı Komser ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/hani-atlari-da-vururlar-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaller', 'hayaller-ozan-ozel-j6vly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hergün geçtiğim ruhsuz yollar

Neşeme öfke saçan birikintiler

Hızıma gem vuran kasistler

Teybimde çalan slow müzik

Yanımda oturan güzel hatun

Kulaklarımda şuh kahkahalar

Ve uyanıyorum uykumdan

Nereden çıktı bu saçmalıklar? 

Ozan Özel

wwww.ozelsiirler.tr.gs', 'Hergün geçtiğim ruhsuz yollar Neşeme öfke saçan birikintiler Hızıma gem vuran kasistler Teybimde çalan slow müzik Yanımda oturan güzel hatun...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayaller-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Romantik Serseri', 'romantik-serseri-hakki-hakan-kaya-pbwmk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tanır gözle bakarlar

Tanımadan oysa hiçbiri

Faydasız kalır sevdam

Önyargılıysa gözleri

Bağlanır hayaller

Kıramazlar zinciri

Aşığın hali anlaşılmaz

Dinlenmiyorsa sözleri

Siyah beyaz hayaller

Avucuma dolar herbiri

Sevgi bağlarında koşan

Bir romantik serseri', 'Tanır gözle bakarlar Tanımadan oysa hiçbiri Faydasız kalır sevdam Önyargılıysa gözleri Bağlanır hayaller Kıramazlar zinciri Aşığın hali anla...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/romantik-serseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman o kadar kısaydı ki', 'zaman-o-kadar-kisaydi-ki-osman-nuri-j7frm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tarih bin dokuz yüz altmış sekiz

Temmuzun on yedisi.

İki katlı tahta evin üst katında

Bir çığlık sesi.

Odada; 

Bir ebe, bir oğul ve onun annesi.

Kadının; 

Acılı bir gülüşle kaplı yüzü,

Boncuk, boncuk ter tanesi.

Beş kez daha çekmişti bu sancıyı,

Bu ise altıncısı.

Sadece; 

Bir buçuk sene sürecek bir beraberliğin

kalleş hikayesi.

Ne sarılmak mümkün oldu gönlümce

Nede Yaslanıp göğsüne,

Dinlemek kalbinin ritmini.

Ne ağlaya bildim giderken ardından

Nede doya, doya sevebildim anneyi

Zaman o kadar kısaydı ki....', 'Tarih bin dokuz yüz altmış sekiz Temmuzun on yedisi. İki katlı tahta evin üst katında Bir çığlık sesi. Odada;  Bir ebe, bir oğul ve onun ann...', ARRAY['Türk Edebiyatı','Şiir','Osman Nuri']::text[], 8.5, '{"poet":"Osman Nuri","poet_slug":"osman-nuri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaman-o-kadar-kisaydi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Buyum', 'ben-buyum-orhun-basat-d05es', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dekor: bilmem ne kentinde bir otel odası.. 

pervazlarından yalnızlık sızan.. 

perdeler kataraktlı, öteler görünmüyor.. 

konu: bir özlemin perde arkası.. 

yazdıkça çoğalan.. 

orkestrada dokunuşlarınken çalan.. 

yalnızlık nöbetleri.. maestrodan habersiz.. 

özlediğin şiir bu değil.. 

sen, odama dolan huzur.. 

ama ben buyum.. 

özledikçe çoğalan bir tutkuyum. 

batmışken, tüm teknelerim, 

okyanusun öbür kıyısı.. 

'' çiçek açtığında her ağaç, 

bizim türkülerimizi söylemeli, 

ve her renk, gecenin tualine 

yalnızca bizi çizmeli..'' 

gecelerim uykusuz direnişlerde.. 

ben buyum.. 

alkol buğulu düşlerim. 

ve gündüz düştüğünde sokaklarıma, 

gözlerini arayan, deli bir uykuyum.. 

sarı saçlarına, boncuklar dizmedeyim. 

sabah ezanlarında, 

aşk şiirleri okurken müezzinler.... 

bir şarkı tuttururum bazen, 

bazen, dizelerle ufka gözlerini çizerim.. 

bir düş olurum, bir masal.. 

göremezsin ayak izlerimi, 

yüreğinin kuytularında gezerim.. 

bir şiir ölür uzaklarda..', 'dekor: bilmem ne kentinde bir otel odası..  pervazlarından yalnızlık sızan..  perdeler kataraktlı, öteler görünmüyor..  konu: bir özlemin pe...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ben-buyum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aferim Oğlum Balta Sana da Prafo Sopa!', 'aferim-oglum-balta-sana-da-prafo-sopa-bekir-mutlu-gokcesu-04ay2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canım ağaç,

kul, köle oldu,

kök, kök sarıldı

toprağa inançla.

Yaşamak

ve yaşatmak uğruna.

Toprak da ana elbette

su verdi, can verdi ona,

yuva oldu kuşlara.

Hem göze, hem gönle 

hitap oldu,

çiçek, çiçek 

konu oldu bahara,

şifa oldu, tat oldu,

meyve oldu tabağa.

Resim oldu,

hayat oldu,

nefes oldu,

gölge oldu,

oldu da oldu...

Ne yalanı, ne yılanı

barındırmadı koynunda.

Yine de yaranamadı

insanoğluna.

Ya kül oldu

ya da sap oldu

bir baltaya

maalesef sonunda...

(Eğitim Şart)', 'Canım ağaç, kul, köle oldu, kök, kök sarıldı toprağa inançla. Yaşamak ve yaşatmak uğruna. Toprak da ana elbette su verdi, can verdi ona, yuv...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aferim-oglum-balta-sana-da-prafo-sopa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cosacagım', 'cosacagim-ayse-birgul-yilmaz-j4quq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep böyle dargın mı bakışacağız

Sen bir tebessüm et ben güleceğim

Hep böyle kırgın mı konuşacağız

Sen damla ol ben çözüleceğim

Kollarını aç ben sarılacağım

Sabrım bitiyor ah yorulacağım

Sen bir adım at ben koşacağım

Yeter ki sen çağla ben coşacağım

Bilirim sık dokur ince elersin

Her zaman ilgili benden beklersin

Artık aramızdaki buzlar erisin

Sen damla ol  ben çözüleceğim.

Kollarını aç ben sarılacağım

Sabrım bitiyor ah yorulacağım

Sen bir adım at ben koşacağım

Yeter ki sen çağla ben coşacağım', 'Hep böyle dargın mı bakışacağız Sen bir tebessüm et ben güleceğim Hep böyle kırgın mı konuşacağız Sen damla ol ben çözüleceğim Kollarını aç ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cosacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Çan Sesleri', 'yitik-can-sesleri-reyhan-sur-2cow4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'siste yankılanan yitik çan sesleridir

duyduğunuz

lacivert akşamların kül kulelerindeki

salıncağımdan

gelir uçurumlarında kurduğum

şarap mışıl mışıllığındayım şimdi 

mahzenlerde

körsük yanan bir fitil gibi

yanarken lambam

ay ışığından

çarşısında

mahşerin öte yakasının

donmak ve

yanmak arasında

gidip gelirken bedenim

taşar gölgeler karanlık camlardan

birbirine not taşıyan

kuryeler gibi

boz bulanık gezinirken iki yıldız

ikiz sözcükler dökülür sızı kıvamında

seğiren dudaklarımın

alaca çerçevesinden

ıslık gibi iner

sevginin en koyusu için

alıç gülleri dökülür

mayalanmış yaralarımdan...', 'siste yankılanan yitik çan sesleridir duyduğunuz lacivert akşamların kül kulelerindeki salıncağımdan gelir uçurumlarında kurduğum şarap mışı...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yitik-can-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu ne hal!', 'bu-ne-hal-ozan-ozel-dq5vq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessiz sedasız geçtin yanımdan 

Gözlerin yerde, boynun eğik 

Umarsız ve mutsuz gidiyordun 

Sen hiç böyle yapmazdın 

Beni görünce mutlu olurdun, oynardın 

Şaşırdım! 

Soruyorum ''bu ne hal sevgili sokak köpeği? '' 

Ozan Özel 

www.ozelsiirler.tr.gs', 'Sessiz sedasız geçtin yanımdan  Gözlerin yerde, boynun eğik  Umarsız ve mutsuz gidiyordun  Sen hiç böyle yapmazdın  Beni görünce mutlu olurd...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-ne-hal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'You Can Fly', 'you-can-fly-ali-soyyigit-kvhy9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nothing is nice without you

If you want every one loves you

Leave me alone unless you want

Angles are free you know

You can fly where you want.', 'Nothing is nice without you If you want every one loves you Leave me alone unless you want Angles are free you know You can fly where you wa...', ARRAY['Türk Edebiyatı','Şiir','Ali Soyyiğit']::text[], 8.5, '{"poet":"Ali Soyyiğit","poet_slug":"ali-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/you-can-fly-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar', 'i-ntihar-tabir-gokce-x5xd7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlmiğinde haykırış canhıraş

(Urgan, yağlı mı bilinmez ya…)

İmiğinde tükenmiş dünya

Mor ötesi rengi güneşin

Yansıdığı ufukta

Kadın; dudakları mor, 

           Yanakları kor.

Ayazı teninde buz kesmiş

(Donan kirpiklerdeki damlalar ya…)

Gözlerinde üçü beş para halkalar

İnadına rüzgar, inadına rüzgar

Uçuşur etekler, bluz dar, havar

Kadın; ağıtları çok

            Umutları yok

İrdelenmiş, örselenmiş, kırılmış

(Buhran anlarında anımsanır ya…)

Bir hayata bir de can’a darılmış

Zaman dar, aralıkları kapamış

Ölüm hak, o da Hak’a sarılmış

Kadın; dudakları mor

           Yanakları kor

Sebep; umut tükenmişse 

	  Sevgi bitmişse

	  Yaşamak çok zor

Sevginizi ve umudunuzu tüketmeyin.', 'İlmiğinde haykırış canhıraş (Urgan, yağlı mı bilinmez ya…) İmiğinde tükenmiş dünya Mor ötesi rengi güneşin Yansıdığı ufukta Kadın; dudakları...', ARRAY['Türk Edebiyatı','Şiir','Tabir Gökçe']::text[], 8.5, '{"poet":"Tabir Gökçe","poet_slug":"tabir-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/intihar-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni sevmeye yüreğin yetmez', 'beni-sevmeye-yuregin-yetmez-kubilay-enginol-4up5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalga,dalga sevgi yayılır içimde

Sevgin çığlık,çığlık yaşar sesimde

Dağları geçer sevgim

Sınır tanımaz,bitmez tükenmez

Beni sevmeye yüreğin yetmez

Her yağmur damlasında aşkım yazar

Yer gökkubbe seni anar

Hasretinden ciğerim yanar

Sana olan sevgim,aşkım bitmez

Beni sevmeye yüreğin yetmez

Senin adınla sahile vurur dalgalar

Adını söyler martılar

Yüreğimde kor olmuş aşkın

Hiç bir zaman sönmez

Beni sevmeye yüreğin yetmez', 'Dalga,dalga sevgi yayılır içimde Sevgin çığlık,çığlık yaşar sesimde Dağları geçer sevgim Sınır tanımaz,bitmez tükenmez Beni sevmeye yüreğin ...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beni-sevmeye-yuregin-yetmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüner', 'huner-mustafa-engin-karatay-yybsz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir avuç şarlatanın hoşuna gitsin diye,

Şiir sayılıyorsa, martaval sıralamak; 

Ver kâğıdı, kalemi, Üç yaşında sabîye,

O''na dâhi zor değil; hünerse, karalamak...

07.02.2004 Münih 01:40', 'Bir avuç şarlatanın hoşuna gitsin diye, Şiir sayılıyorsa, martaval sıralamak;  Ver kâğıdı, kalemi, Üç yaşında sabîye, O''na dâhi zor değil; h...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/huner-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun Eritmeyi Sürdüreceğim Yüreğimde', 'kursun-eritmeyi-surdurecegim-yuregimde-mine-ozdemirtas-g2fmn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Bir lokma, bir hırka” türünden ya sevdan.! 

Geçinip gidiyorum işte arada,

Yarı aç, yarı tok. Pek doymadan.

Elimde yırtık bir yorgan,

Sensizliği örtmeye çalışıyorum

Utanarak yokluğundan.

Yine de; ortalık çoğu kez,

Mahşer yeri gibi tozla,duman.

Asla bitmeyecek olsa da; 

Güneşi balçıkla sıvaman,

Ben yine de, Kurşun eritmeyi 

Sürdüreceğim yüreğimde.

Hiç durmadan.

19/02/2004   ist.', '“Bir lokma, bir hırka” türünden ya sevdan.!  Geçinip gidiyorum işte arada, Yarı aç, yarı tok. Pek doymadan. Elimde yırtık bir yorgan, Sensiz...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kursun-eritmeyi-surdurecegim-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-ayten-ozlem-yesilcali-r1gaz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar ondan hiçbirşey götürmemişti

Hala aynı hala gençti

Döndüm aynaya korkarak baktım

Ve korkunç gerçegi gördüm

sevgideki gençlik benimdi.

Giderken onuda çalıp gitmişti....

Gördüm ondaki herşey bana aitti

Yirmi yıl sonra gördüm sevgiyi

Ahhh... görmez olaydım o halini

Her şeyimi çalıp giden o aşkı o sevgiyi

Görmezseydim keşke o yalan gözleri

Şimdiden söylüyorum ey sevgi

Artık alabilecegin ne gençligim nede

senelerim kaldı.

Bilirim dayanamazsın sevgi

Sen gideli zaten yaşamadımki

Gelde al artık bu sefil bedeni', 'Yıllar ondan hiçbirşey götürmemişti Hala aynı hala gençti Döndüm aynaya korkarak baktım Ve korkunç gerçegi gördüm sevgideki gençlik benimdi....', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgi-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '41 Kere Maşaallah’ımsın benim...', '41-kere-masaallah-imsin-benim-muammer-celik-gbmop', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

Hem duygularıma kaynak

Hem şiirlerime ilham''ımsın…

II

Hem gözümde bebeğim

Hem gönlümde Sultan''ımsın…

III

Hem rüyalarımda baş tacı

Hem düşlerimdeki  Perisin…

IV

Hem dünyalığım

Hemde ahiretliğimsin…

V

Hem ulaşılmazım

Hem vazgeçilmezimsin…

VI

Hem ilkim

Hemde hiç olmayacak sonumsun…

Sen, bedenime can veren RUHUMSUN…! 

BirDeli

19.02.2004', 'I Hem duygularıma kaynak Hem şiirlerime ilham''ımsın… II Hem gözümde bebeğim Hem gönlümde Sultan''ımsın… III Hem rüyalarımda baş tacı Hem düşl...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/41-kere-masaallah-imsin-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Mesîh Geliyor...', 'kutlu-mes-h-geliyor-mustafa-engin-karatay-azzyf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Müjde eyy Müslümânlar; sevinin İnananlar! 

Zulmeti, karanlığı; muazzâm nûr deliyor

Asırlardır vuslatın aşkı ile yananlar; 

Alâmetler tas-tamam, Kutlu Mesîh geliyor...

Pek yakında Âlem''i, muhabbetle kucaklar; 

Yeryüzü''nü küfürden, şirkten, isyândan paklar

Zâlimlerden alınır, mazlûma âit haklar

Adâletle hükmeden, Kutlu Mesîh geliyor...

Tebşîr ihâtâ etti, Gökler''i ve Yerler''i

Üzülmeyin, nûş edin, Çağ''ın gönül erleri

Silin gözlerden yaşı, bitirin kederleri! ..

Yüzyıllardır beklenen, Kutlu Mesîh geliyor...

19.02.2004   Münih   03:05', 'Müjde eyy Müslümânlar; sevinin İnananlar!  Zulmeti, karanlığı; muazzâm nûr deliyor Asırlardır vuslatın aşkı ile yananlar;  Alâmetler tas-tam...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kutlu-mesih-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte', 'sahte-hami-unal-q9mpk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boşuna uğraşmaların 

emanet duruyor

yüzündeki perde,

yalan tebessüm yakışmıyor

nemli gözlerine.

Er ya da geç

dağılacak kara bulutlar,

çiçekler açacak. 

Çare yok,

yeniden yaşanacak 

unutulan günler

biraz yorgun

biraz yaşlı

biraz da uykulu', 'Boşuna uğraşmaların  emanet duruyor yüzündeki perde, yalan tebessüm yakışmıyor nemli gözlerine. Er ya da geç dağılacak kara bulutlar, çiçekl...', ARRAY['Türk Edebiyatı','Şiir','Hami Ünal']::text[], 8.5, '{"poet":"Hami Ünal","poet_slug":"hami-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sahte-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamân', 'zam-n-mustafa-engin-karatay-p09u0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamân, girdâb içinde dönen çengel bulmaca

Perdeyi aşmak için, say ki engel bulmaca...

Rûhuma darlık veren, zamân denilen örtü

Fenâ-fillâh öncesi, canın tenle flörtü...

19.02.2004    Münih    03:20', 'Zamân, girdâb içinde dönen çengel bulmaca Perdeyi aşmak için, say ki engel bulmaca... Rûhuma darlık veren, zamân denilen örtü Fenâ-fillâh ön...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zaman-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-ayten-ozlem-yesilcali-w649f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen sözler yetmez seni anlatmaya...

Gözlerine işte o an bakmak istemem hiç

Sen gideceksin...

Ben yine sensiz,yine kimsesiz.

Biliyorum! 

Gitme; Sözcügü burada basit ve anlamsız kalacak

Merak etme; 

Zaten o ''''GİTME'''' sözcüğü yüreğimi kanatsada

Çıkarmamak için yıllarca içimde hapis kalacak....

Kapıyı vurmak; 

aslında bakarsan aşktan kaçmak kolaydır.

Degilmi? 

Yani sana........

Bense arkandan bagıra bagıra sana olan sevgimi; 

Haykırsamda.

Oysa başka gözler çoktan girmiştir kanına...

Alışkınsındır bilirim yalan sahte aşklara...

Sana ''''GİTME'''' demeyecegim.

Git ki anla  sevgiyi aşkı.....

Git ki anla gerçek sevdayı.

Git ki dönmek istediginde arkana bakma

ve döndügünde o çıkarken çarptıgın kapının; 

Sana bir daha açılacagını sanma..', 'Bazen sözler yetmez seni anlatmaya... Gözlerine işte o an bakmak istemem hiç Sen gideceksin... Ben yine sensiz,yine kimsesiz. Biliyorum!  Gi...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/git-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-ayten-ozlem-yesilcali-h5j7i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilirmisin? 

Yıllar önce vazgeçtim ben; 

Sevmekten,özlemekten,hasret çekmekten....

Bilirmisin? 

Neler gördü gözlerim.

İhaneti,kahpeliği,şu dünyanın gerçek halini.

Yıllar önce  vaz geçtim ben,

Sevdalardan,hasretlerden.....

Bilirmisin? 

Yagan yagmur hep bana aglıyor.....

Kayan yıldızlar tıpkı yıllarım gibi kayıyor.

Dönüp baktıgımda geleceye; 

Göremiyorum ne seni,nede sevdiklerimi; 

Oysa zaman durmadan gelip geçiyor.

Bana aldırmadan ilerliyor saniye denen illet; 

Bırakmadı yakamı ugursuz felek.

Bilirmisin? 

Vaz geçmeme ragmen sevmekten,özlemekten; 

Hasret çekmekten.

Bunlara ragmen

Vazgeçmedim seni sevmekten; 

Özlemekten,hasretini çekmekten.

Bana bunların hepsinin acı verdigini bilerekten......', 'Bilirmisin?  Yıllar önce vazgeçtim ben;  Sevmekten,özlemekten,hasret çekmekten.... Bilirmisin?  Neler gördü gözlerim. İhaneti,kahpeliği,şu d...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bilirmisin-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Utanıyorum...', 'utaniyorum-mustafa-engin-karatay-pqdfq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yâ Rasûlallah, utanıyorum Sen''den... 

Utanıyorum, Ümmetin olduğunu iddiâ etmekten 

Utanıyorum, karşına çıkmaktan 

Utanıyorum, yüzüne bakmaktan 

Hangi yüzle, hangi çehre ile olur ki bu? 

Neyimle sevdireyim ki kendimi sana? 

Günâhlarımla mı, tembelliğimle mi, pisliğimle mi? 

Kapımı çalıp, misâfir olmak istesen; 

Sana liyâkatimi sergileyeceğim neyim var hânemde? 

Evimde, ocağımda Sünnetin''e uyan neyim var? 

Boynum bükülür, diyemem burası Müslümân evi 

Buyur edip sana bir yer gösteremem 

Mihmândârın olup da bir döşek seremem 

Karşına çıkıp, iki cümle söz edemem 

Yalan söyleyen, kalp kıran, nifâk saçan lisânla mı? 

Kîni, öfkeyi, buğzu yeğleyen kalple mi? 

Kaldırıp başımı, yüzümü sana çeviremem 

Nasıl bakabilirim ki nûr dağıtan vechine? 

Harâmları gören, insanları kibirle seyreden gözle mi? 

Bana vereceğin öğütleri, nasîhâtleri işitemem 

Ne ile olsun ki? 

Gıybet, mâlâyânî ve şehevî sözleri dinleyen kulakla mı? 

Belki de gitmeni isterim bir an evvel 

Belki bundan rahatlık duyarım 

İstemem belki de bir daha Sen''inle karşılaşmayı 

Dedim ya; 

Sen''i sevdiğim, Ümmetin olduğum kuru bir iddiâ 

Bu uğurda yok bir zerre gayretim 

Utanıyorum bu hâlimden Allah''ın Sevgili Dostu 

Sen''in Yüz-ü Suyun Hürmeti''ne halkedilen bu Dünyâ''da, 

Rabb''in Nîmetleri''nden yiyip-içmekten utanıyorum 

Nefes almaktan utanıyorum 

Utanıyorum... 

21.04.2000   Landsberg   04:20', 'Yâ Rasûlallah, utanıyorum Sen''den...  Utanıyorum, Ümmetin olduğunu iddiâ etmekten  Utanıyorum, karşına çıkmaktan  Utanıyorum, yüzüne bakmakt...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/utaniyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '100. Şiir', '100-siir-gulay-yildiz-p0r1f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalanları düşünüyorum

Kimsesizliğimi ve yanlızlığımı

Güneşten daha yakıcı olan geceyi

Düşüncelerimi aydınlatan karanlığı...

Bilmem kaçıncı şiirmiş bu

Kalbimdeki dert ortak, şiirlerim de! 

Apansız kalışların ayak sesleri

Ve bir de kalbimi acıtan haksızlık

İkisi bir olmuş tepiniyorlar gecemde

Karmaşık bir patika ama labirent değil

İçinde kaybolmadan ilerliyorsun, dert değil

Üç adım sağa ve sonra beş adım sola

Geri dön bul beni! 

Yanlızlıklardayım...', 'Kalanları düşünüyorum Kimsesizliğimi ve yanlızlığımı Güneşten daha yakıcı olan geceyi Düşüncelerimi aydınlatan karanlığı... Bilmem kaçıncı ş...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/100-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlâhî, Ben Sen''i Çok Seviyorum', 'i-l-h-ben-sen-i-cok-seviyorum-mustafa-engin-karatay-n0uoi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '........................(Hüzzâm ilâhî)

Ne denir bu coşkuların adına? 

Doyamadım Zikrullâh''ın tadına 

Erdi gönlüm, muhabbet murâdına 

İlâhî, ben Sen''i çok seviyorum 

Kalbim huzûr buldukça gitti keder 

Tasalarım silinip oldu heder 

İste Aşkın yüreğime yer eder 

İlâhî, ben Sen''i çok seviyorum 

Lezzetinden imrenir bal, hem şeker 

Tılsımıyla en''âniyyeti söker 

Tüm vücûdum doymaz hâlâ HÛ çeker 

İlâhî, ben Sen''i çok seviyorum 

Kuşlar gibi uçtum, geçtim perdeler 

Seyreyledim; ebrâr dostlar nerdeler? .. 

Sultânlarım keşfolunan yerdeler 

İlâhî, ben Sen''i çok seviyorum 

Nâsîb et ki; devâmı böyle sürsün 

Aşk perçini, sîneme nakış örsün 

Âciz Engin (kulun) , hep Tecellîn''i görsün 

İlâhî, ben Sen''i çok seviyorum 

30.03.2001   Landsberg   04:05', '........................(Hüzzâm ilâhî) Ne denir bu coşkuların adına?  Doyamadım Zikrullâh''ın tadına  Erdi gönlüm, muhabbet murâdına  İlâhî, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ilahi-ben-sen-i-cok-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-ayten-ozlem-yesilcali-033vk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasret koma beni; 

Anlamsız sevgilere itme,

sabahlarımın seninle olmasını; 

Ay ışıgını seninle seyretmek istiyorum.

Nemli geceleri seninle yaşamak.

Anlam katmak sevgimize

Lekesiz temiz bir sevgi istiyorum.

İkimize.....

Seni sen oldugun için sevmek.

Elveda degil,merhaba demek.

Neonların altında

Dans etmek sevginle

Erimek aşkınla sarhoş olmak

Ne dersin birtanem........

Hayatı bir kaç gün değil.

Oluruna bırakmadan

Sarhoş olmak istiyorum.

Lakin senin ne düşündügünü bilmiyorum.

Aşkımızın sevgimizin büyük olmasını istemiyorum.

Nedensiz sebepsiz

İçimden geleni söylüyorum.

Yalansız.

Olurlarla dopdolu.....

Riyasız tertemiz

Umut dolu

Mutluluklarla sonsuza dek birliktelik istiyorum', 'Hasret koma beni;  Anlamsız sevgilere itme, sabahlarımın seninle olmasını;  Ay ışıgını seninle seyretmek istiyorum. Nemli geceleri seninle y...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istiyorum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-gul-ulupinar-1akxt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerine hasret ellerim,

Yapayalnız...

Yüreğine hasret yüreğim,

Çaresiz...

Gözlerine hasret gözlerim,

Üzgün...

Sesine hasret günlerim,

Bomboş...

Sevgine hasret benliğim,

Sana hasret...', 'Ellerine hasret ellerim, Yapayalnız... Yüreğine hasret yüreğim, Çaresiz... Gözlerine hasret gözlerim, Üzgün... Sesine hasret günlerim, Bombo...', ARRAY['Türk Edebiyatı','Şiir','Gül Ulupınar']::text[], 8.5, '{"poet":"Gül Ulupınar","poet_slug":"gul-ulupinar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hasret-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymuyor musun?', 'duymuyor-musun-gul-ulupinar-w7wku', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne duruyorsun sevdiğim! 

Bak karşındayım işte.

Gözlerini gözlerime kenetle.

Uzatsana ellerini hadi.

Parmaklarının ucunda ellerim,

Tutsana onları.

Ne kadar sana hasret olduklarını

Görmüyor musun hala? 

Anlamıyor musun? 

Sende beni seviyorsun.

Tut ellerimi,

Yanındayım işte,

''Seni seviyorum'' diyorum,

Duymuyor musun?', 'Ne duruyorsun sevdiğim!  Bak karşındayım işte. Gözlerini gözlerime kenetle. Uzatsana ellerini hadi. Parmaklarının ucunda ellerim, Tutsana on...', ARRAY['Türk Edebiyatı','Şiir','Gül Ulupınar']::text[], 8.5, '{"poet":"Gül Ulupınar","poet_slug":"gul-ulupinar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/duymuyor-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-gul-ulupinar-428qc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sevmek,

Dünyadaki en güzel manzarayı izlemek.

Seni sevmek,

O manzarayı bir resim haline dönüştürebilmek.

Seni sevmek,

Her yeri rengarenk çiçeklerle donatmak.

Seni sevmek,

O çiçeklerde seni görebilmek.

Seni sevmek,

Bir türkü söylemek.

Seni sevmek,

O türküde seni yaşayabilmek.

Seni sevmek,

En güzel duyguları sana beslemek.

Seni sevmek,

Seni görmeden o duyguları yaşayabilmek.

Seni sevmek,

Bir dilek tutmak.

Seni sevmek,

O dilek için mücadele edebilmek.

Seni sevmek,

Mutlu bir rüyayla uyanmak.

Seni sevmek,

O rüyada yanında olmak.

Seni sevmek,

Sınırsızı istemek.

Seni sevmek,

İmkansızı başarmak.', 'Seni sevmek, Dünyadaki en güzel manzarayı izlemek. Seni sevmek, O manzarayı bir resim haline dönüştürebilmek. Seni sevmek, Her yeri rengaren...', ARRAY['Türk Edebiyatı','Şiir','Gül Ulupınar']::text[], 8.5, '{"poet":"Gül Ulupınar","poet_slug":"gul-ulupinar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seni-sevmek-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Referandum', 'referandum-ferit-teksoy-sippm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''''paralı insan''''

ikisi beraberken hoş geliyor kulağa

bir terazi koyacaksın ortaya

seç birini diyeceksin yurdumun insanına

''''paralı''''diyen sağ kefeye,

''''insan''''diyense sola

hangi kefe ağır basar,

diğerini havaya fırlatırdı acaba? ..', '''''paralı insan'''' ikisi beraberken hoş geliyor kulağa bir terazi koyacaksın ortaya seç birini diyeceksin yurdumun insanına ''''paralı''''diyen sa...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/referandum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-gul-ulupinar-icdg5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni aşka yazmalı aşkım,

Adını bir ağacın her yaprağına yazmalı,

Yüreğimi yüreğina sürgün etmeli,

Bir daha dönmesine izin vermemeli.

Seni aşka yazmalı aşkım,

Olmadığında yanımda seni hissetmeli,

Soluğunu hep içimde duymalı,

Her an özlemeli beklemeli seni.

Seni aşka yazmalı aşkım,

Sımsıkı sarmalı seni sonsuzluk gibi,

Şaşırtmalı herkesi kıskandırmalı,

Korkmalı kaybetmekten ona ağlayabilmeli.

Seni yüreğe yazmalı aşkım,

Seni sonsuzluk gibi sevmeli,

Yarınlara umutla sevgiyle bakmalı,

Seni işte böyle doyasıya sevmeli...', 'Seni aşka yazmalı aşkım, Adını bir ağacın her yaprağına yazmalı, Yüreğimi yüreğina sürgün etmeli, Bir daha dönmesine izin vermemeli. Seni aş...', ARRAY['Türk Edebiyatı','Şiir','Gül Ulupınar']::text[], 8.5, '{"poet":"Gül Ulupınar","poet_slug":"gul-ulupinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askim-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurdumun Hali', 'yurdumun-hali-abdulkadir-karaman-6x35e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herkes birbiriyle küskün,dâvalı

Hayret! Ağa ırgat ile kavgalı,

Düşmanlar bu hâle çalar kavalı,

İhânetin çok ağırdır vebali,

Ne olacak benim yurdumun hali? 

	

Sokaklarım teslim yılan,çiyana,

Görseniz yurdumu soyan soyana,

İmkansız rastlamak kâni,doyana,

Hâlinden habersiz mağdur ahâli,

Ne olacak benim yurdumun hâli? 

Âdalet oyuncak olmuş,oynarlar,

Dürüst kimse yandı,tutup kıyarlar,

Ne yapsan yap düzen tutmaz ayarlar,

Yitirmişiz,çok zor bulmak kemâli,

Ne olacak benim yurdumun hâli? 

	

Yapanın yanına kalır yaptığı,

Büyüklerin helal haram kaptığı,

Kulların belirsiz kime taptığı,

Hiç kimse düşünmez sorgu,suâli,

Ne olacak benim yurdumun hâli? 

Dillerden hiç düşmez Allah’ın adı,

Tesiri mi? Yoktur,bir adı kaldı,

Kim inkar ederse makbul,yaşadı,

Çok yakında gibi hakkın zevâli,

Ne olacak benim yurdumun hâli? 

	

Büyük gibi olsa idi büyükler,

Sırtımıza vurulmazdı bu yükler,

Fırsatını bulan yükler de yükler,

Tükendi milletin sabrı,mecâli,

Ne olacak benim yurdumun hâli? 

Ayaklar altına düşmüş yüceler,

Onlara tahakküm eder cüceler,

Sardı her yanı gardiyan geceler,

Dolaşır dururuz esir misâli,

Ne olacak benim yurdumun hâli? 

Düşkünlerin kâlbi köz,kan ağlıyor,

Fark etmiyor kimse,hicran çağlıyor,

Umudunu Yaradan’a bağlıyor,

O bilir, perişan yurdumun hali.

Kurtar esaretten artık  hilâli,

01.10.1998', 'Herkes birbiriyle küskün,dâvalı Hayret! Ağa ırgat ile kavgalı, Düşmanlar bu hâle çalar kavalı, İhânetin çok ağırdır vebali, Ne olacak benim ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yurdumun-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-abdullah-karaduman-zop5x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazen gözlerine baktığımda

Orada bir ışık görüyorum

İçindeki özlemi ve

Beni sevdiğini görüyorum

Gecenin karanlığında parlayan

Bir yıldız gibi gözlerin

Bazen denizde bir yakamoz çırpınıyor

Kırptıkça gözlerini

Sadece sen varsın

Bu uçsuz bucaksız gökyüzünde

Birtek sana uzanır ellerim

Ta ki sabah olup gün ağarana dek.

Ne olur güzelim

Kapatma gözlerini

Unutma yeryüzünde

Sana tutsak biri var.

22/01/2004', 'Bazen gözlerine baktığımda Orada bir ışık görüyorum İçindeki özlemi ve Beni sevdiğini görüyorum Gecenin karanlığında parlayan Bir yıldız gib...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tutsak-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dön', 'geri-don-abdullah-karaduman-lww40', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geri dön

Kapat kapıyı ve gözlerime bak

Ne olur sevgilim yanımda kal

Seni çok sevdiğimi biliyorsun

Geri dön

Bırak geçmişte yaşananları

Dur gitme yanımda kal

Ne kadar acı çektiğimi görmüyormusun? 

Geri dön

Dudaklarımdan dökülen isyanı

Gözlerimden akan pişmanlığımı

Kalbimin kafeste çırpınışını görmüyormusun? 

Geri dön

Bileğime kelepçe vurma

Kırıp kalbimin zincirini

Sana sarılmama izin ver

Biliyorsun, gidersen ben ölürüm...

22/01/2004', 'Geri dön Kapat kapıyı ve gözlerime bak Ne olur sevgilim yanımda kal Seni çok sevdiğimi biliyorsun Geri dön Bırak geçmişte yaşananları Dur gi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/geri-don-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Beyaz', 'kar-beyaz-abdullah-karaduman-didsy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hava beyaz, yer beyaz

Saç, sakal yüz beyaz

Be ne soğuk ya Rab,

Bu ne ayaz.

Sokakta çocuklar evsiz

Altındaki kaldırım beyaz

Üzerine örtecek karton yok

Onunda battaniyesi kar beyaz.

Sessiz çığlıkları duyulmaz

Rüzgârın sesinden uyunmaz

Uyudumu bir daha uyanmaz

Soğuktan ölse kimse duymaz.

Evinde oturanın elektriği yok

Hem elektrik hem su yok

Bu duruma şükreden yok

Sokaktakinin bir evi bile yok

Sessiz çığlıklarımı duyan yok...

23/01/2003', 'Hava beyaz, yer beyaz Saç, sakal yüz beyaz Be ne soğuk ya Rab, Bu ne ayaz. Sokakta çocuklar evsiz Altındaki kaldırım beyaz Üzerine örtecek k...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kar-beyaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş gölgeler', 'bos-golgeler-sedat-tuvar-xfh7d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk gölgen düşer köşeden

Ben her akşam seni beklerim

En büyük merakım neredesin

Boş gölgeler başımı döndürür

Durmaz ayak sesleri

Yürür gider kapım önünden

Birtanesi çalmaz kapımı

Boş gölgeler başımı döndürür

Son gemide yanaşır iskeleye

Dağalır sokaklarda gölgeler

Birtaneside çalmaz kapımı

Boş gölgeler başımı döndürür', 'İlk gölgen düşer köşeden Ben her akşam seni beklerim En büyük merakım neredesin Boş gölgeler başımı döndürür Durmaz ayak sesleri Yürür gider...', ARRAY['Türk Edebiyatı','Şiir','Sedat Tüvar']::text[], 8.5, '{"poet":"Sedat Tüvar","poet_slug":"sedat-tuvar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bos-golgeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhabbet Tezâhürü', 'muhabbet-tez-huru-mustafa-engin-karatay-oobci', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acâib bir huzûr,

Acâib bir sevinç...

Sâdece Hamd etmenin çok yetersiz kalacağı bir hissiyât

Asl''a ric''ât, mükemmele doğru atılan adımın semeresi

Bütün bedeni ihtivâ eden bir mesrûriyyet

Dünyâ''daki tüm keder ve sıkıntıların görülmediği ân

Nefsî sükûnete erişip, mânevî hazza karşı olan doyumsuzluk

Herkesin iç bünyesinde kasırgalar koparken, benim ise bu yönde tasam yok

Nihâyet; Aylar''ı, Seneler''i saydıran buhrânın azalması

Ve, arzulanan, tahayyûl edilen o ân...

O''nun Lütfu''na mazhâriyyetin belirgin tezâhürü

Şükürler olsun ki, bu kapıyı aralamama imkân sağladı

Ve yine şükürler olsun ki, atılan adımın karşılıgı âşikâr

En''âniyyetten sıyrılıp, samîmiyyete müdâvim olmanın mükâfâtı

Sabrın hakîkaten cemîl olusunun delîli

İbâdetlerdeki lezzetin, iliklere kadar hissedilişi

Ne cihete nazar edilse, her şey O''nun işâreti

Bir uç ve kutup noktada kayboluş

Kimbilir kaç mü''minin hayâlini süsleyen bulunmaz bir cevher

Vâr olduğunu ve Merhametli olduğunu damarlarımda akıtıyor âdetâ

Yersiz mübâlağaya hiç gerek yok, yaşıyorum, tadıyorum...

Doyamıyorum...

Daha da istiyorum...

Bitmesin diyorum...

Hücrelerime nüfûz ve duhûl eyliyor muhabbet

Acziyyetimi ikrâr ediyorum...

İhsânı''na diyecek söz bulamıyorum

İstiyorum herkese nasîb olsun

Çünkü O, kerkesin Hâlık''ı

Bu tebessüm neden başka bu sefer? 

Coşuyorum yaa...

Şimdi niyâzım, hitâmım da böyle olsun...

Bu aşk başka

Çok başka

Hem de dilin telaffuzda zorlanacağı kadar

Bir de her yüreğin taşıyamayacagı sıcaklıkta

Değdiği yerdeki kayaları, kumsala dönüştürüyor

Azgın dalgaları sırtlayan ummânları, süt-limân eyliyor

Şu ân düşünüyorum, Cihân tümüyle teklif edilse nâfile...

Bundan büyük in''âm mı ola ki? 

Mansûr''u, Muhyiddîn''i anlayabiliyorum...

Eşi benzeri olmayan Bir ve Tek...

Muhtâc olmayan Samed...

Eriyip bitiyorum...

Seviyorum...

02.08.2000   Landsberg    03:50', 'Acâib bir huzûr, Acâib bir sevinç... Sâdece Hamd etmenin çok yetersiz kalacağı bir hissiyât Asl''a ric''ât, mükemmele doğru atılan adımın seme...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/muhabbet-tezahuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız kurusu', 'kiz-kurusu-kubilay-enginol-o7j6b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kız kurusu,kuru kayısı

Kaderi antika semaverin aynısı

Armudun sapı,üzümün çöpü

Ayırdı heyhat

Baktıki geçivermiş

Acımasızca hayat

Gezmek isterdi belkide elele

İbretle baktı hep sevgililere

Sarı semaverle yaşıttı

Ne gizli karşılıksız aşklar yaşamıştı

Kurulu saat gibi giderdi işine

Yaşantısı açıktı sıkıntıya, beise

Kırıntılarla yetindi hep,hayatı boyunca

Gözyaşları eşlik ederdi,akşam olunca

Vakit geldi,aniden sinsice

Gidiverdi,geldiği gibi sessizce', 'Kız kurusu,kuru kayısı Kaderi antika semaverin aynısı Armudun sapı,üzümün çöpü Ayırdı heyhat Baktıki geçivermiş Acımasızca hayat Gezmek iste...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiz-kurusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Gülmüyor', 'gozlerim-gulmuyor-hifzi-ozbekmez-lzeh5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlemin içimde bir kor oluyor

Dinmiyor hasretin dinmiyor gülüm

Sen yoksun yanımda halim perişan

Gülsem de içime sinmiyor gülüm

Başımı taşlara vururum her gün

Hasretin öldürür beni de bir gün

Sensiz buralara olmuşum sürgün

Ağlıyor gözlerim gülmüyor gülüm

Gönül hasretinle her an yanıyor

Hayalde rüyada seni arıyor

İnsanlar hep beni deli sanıyor

Kimseler halimden bilmiyor gülüm

Latifi bir gün yanına varacak

İnce bellerini hemen saracak

Senin kollarında mutlu olacak

Gelmiyor o günler gelmiyor gülüm

2003', 'Özlemin içimde bir kor oluyor Dinmiyor hasretin dinmiyor gülüm Sen yoksun yanımda halim perişan Gülsem de içime sinmiyor gülüm Başımı taşlar...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerim-gulmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makas', 'makas-semih-tanriver-sh16b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir makas olacaksam

diğer yanım sen olmalısın

birlikte şekil verebilmeliyiz her şeye

yada bir bıçak

sen keskin yanım olmalısın

yada kör yanım olarak kalmalı

hiçbir lekeye 

bulaşmamalısın...', 'Bir makas olacaksam diğer yanım sen olmalısın birlikte şekil verebilmeliyiz her şeye yada bir bıçak sen keskin yanım olmalısın yada kör yanı...', ARRAY['Türk Edebiyatı','Şiir','Semih Tanrıver']::text[], 8.5, '{"poet":"Semih Tanrıver","poet_slug":"semih-tanriver","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/makas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezde Geç Beni', 'ezde-gec-beni-hifzi-ozbekmez-z4mko', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda yollarında olsam da kömür

Yar senin yoluna versem de ömür

Ayaklar altında olayım çamur

Her gün üzerimden ezde geç beni

Güzel gözlerinden aldım ilhamı

Aşkınla unuttum kederi gamı

Sorarsam vuslatın var mı zamanı

Her gün kaderine yazda geç beni

Latifi yanıyor sevda yolunda

Murada erer mi bilmem sonunda

Ellerim bağlıdır gurbet dalında

Her gün kollarımı çözde geç beni

13 KASIM 2003 PERŞEMBE SAAT: 04:00', 'Sevda yollarında olsam da kömür Yar senin yoluna versem de ömür Ayaklar altında olayım çamur Her gün üzerimden ezde geç beni Güzel gözlerind...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ezde-gec-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilence', 'dilence-hatice-ari-65ilt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçindeki kibritleri çak hadi,

Karanlıkta bağırma; 

Korkuyorum,

Yanındaki çocuk nerede? 

Ekmek saçlı hani,

Çekirdek gözlü,

Zeytin yiyen; 

Çekirdekten korkan

Be adam! 

Çak şu kibritleri,

Ellerini ovuşturup durma; 

Üşüyorum,

Saçların ipek gibi,

Ne güzel yağıyor kar,

Üstüne; 

Annem de böyle güzeldi...

Gözlerim kapanıyor,

Senin adın ne? 

Uyumak istemiyorum; 

Bari bir türkü tuttur; 

Orta Anadolu,

Memleket havası; 

Açlığımı unuttur,

Bilmiyorsan bile,

İstediğini söyle..

Yabancı mısın yoksa? 

Sen de mi taptın bu kente? 

Öyle ana yüreği gibi değildir,

Bak; 

Kaç gündür açım,

Canımı alacak utanmasa; 

Kibritleri diyorum,

Çak artık, çak; 

Tüm güzelliklerimi de 

Beraberinde yak,

Kabülüm,

Ellerim mi? 

Heyhat,

Asıl yüreğim çatlak! 

Sen de mi yeminlisin? 

Yazık, günah,

Dişlerimin arasında çiğnedim 

Yıldızları,

Sabah yakın mı,

Söylemediler.

Güneş doğar mı,

Bilmiyorlar.

Hadi, diyorum sana

Çak şu kibritleri; 

Yıldızlar da yansın,

Ya da 

Güneş çıksın..', 'İçindeki kibritleri çak hadi, Karanlıkta bağırma;  Korkuyorum, Yanındaki çocuk nerede?  Ekmek saçlı hani, Çekirdek gözlü, Zeytin yiyen;  Çek...', ARRAY['Türk Edebiyatı','Şiir','Hatice Arı']::text[], 8.5, '{"poet":"Hatice Arı","poet_slug":"hatice-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/dilence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi Öğrenmek', 'sevgiyi-ogrenmek-i-brahim-ethem-bingul-7z42n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgiyi,seni seviyorum demeyi

Öğrenmişim ruhumdan

Ama ne olduğunu öğrendim

Bir sevda tanımazdan

Olsun dedim mecbur mu

Herkes sevgiyi bilmeye

Ben devam ederim sevmeye

Sevile sevile sevmeyi öğrenir

Kim bilir belki bir gün sever beni diye', 'Sevgiyi,seni seviyorum demeyi Öğrenmişim ruhumdan Ama ne olduğunu öğrendim Bir sevda tanımazdan Olsun dedim mecbur mu Herkes sevgiyi bilmeye...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgiyi-ogrenmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-adnan-ferit-0qjat', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dallarımı kırdınız  ses etmedim

Çocuktunuz sonuçta,

Çakılarla oydunuz göğsümü  ses etmedim,

Biliyordum ki,

Gençtiniz, aşıktınız,deli doluydunuz 

Aklınız da bir karış havada.

Baltalarla saldırdınız gıkım çıkmadı,

Tek duam köküm kalsındı.

Oysa ben sığınak oldum kimi zaman

Gölge oldum korudum,

Yastık oldum uyuttum,

Omuz verdim gözyaşlarınıza

İçtim yudum yudum.

Söylesenize  ne zaman  size karşı durdum.

Susmayın Allah aşkına konuşun

Nedir yetemediğim bileyim,

Nedeni nedir  bu çektiklerimin,

Amacı nedir beni böylesine yok etme isteğinizin.

Ah canlarım! durun bir dakika

Bensiz dünyayı düşleyin

Hala içiniz rahatsa ben göğüs gererim siz devam edin..

Ama dedim ya,ayırın bir dakikanızı

düşünün tek bir ağacın olmadığı   dünyayı..', 'Dallarımı kırdınız  ses etmedim Çocuktunuz sonuçta, Çakılarla oydunuz göğsümü  ses etmedim, Biliyordum ki, Gençtiniz, aşıktınız,deli doluydu...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/agac-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevenin Halleri', 'sevenin-halleri-i-brahim-ethem-bingul-wa3y2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşündüm de kimi sever

Sevdiğini sadece gözleriyle

Kimi bakar yüzüne tebessümle

Anlamazsın kopar kıyamet içinde

Kimi sever,haykırır sevgisini

Duyurur Zümrüt-ü Anka''ya bile

Kimi ne söyler,ne söylemez

Bir yanar,bir söner

Kimi yanar durur,döner durur

Döndükçe yanar,yandıkça döner

Sevgide kaybolmak istercesine

İster öyle,ister böyle

Sev yeter ki sevda ile

Yay sevgini tüm sevenlere

Olsun sevgin sevgililere

En güzel hediye', 'Düşündüm de kimi sever Sevdiğini sadece gözleriyle Kimi bakar yüzüne tebessümle Anlamazsın kopar kıyamet içinde Kimi sever,haykırır sevgisin...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevenin-halleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Ben Yapacak', 'beni-ben-yapacak-i-brahim-ethem-bingul-stc4j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yürek istiyorum

Benimle,benim için atacak

Bende kaybolacak

Canıma can katacak

Verdiğim sevgiyi kaldıracak

Can verince şüphe duymayacak

Gökkuşağını hiçe sayıp

Renkleri kendi yapacak

Yıldızlara kafa tutup

Kendi yıldız olacak

Güneşe bakıp,güneşi yakacak

Ayı kıskandıracak

Denizleri toplayıp yağmur yapacak

Bulutları döşek yapacak

Sadece bana bir ömür sevgiyle

Aşkla bakıp

Beni ben yapacak..', 'Bir yürek istiyorum Benimle,benim için atacak Bende kaybolacak Canıma can katacak Verdiğim sevgiyi kaldıracak Can verince şüphe duymayacak G...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beni-ben-yapacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sûzinâk Şarkı', 's-zin-k-sarki-hakan-kose-yjcym', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne hatırlarım ne de aklımdan çıkar

Olsa olsa Sûzinâk bir şarkı o kadın

Gözleri yabancı bir melodi, yepyeni

Hicazkâr''a kaçıyordu elleri ama değil 

Ne var, ne de yok bir şehrâyin gibi

Olsa olsa Sûzinâk bir şarkı o kadın

Ben ona bir bahar sabahı rastladım

Ekim usulca ağaçlara dokunuyordu

Gün lîme lîme yapraklara düşüyordu

O gördü ilkin, öylece oturuyordum

Tuttu kaldırdı nasıl da sarsılmıştım

Ne var, ne de yok bir şehrâyin gibi

Sanki bahar sadece bize geliyordu

Yine bir bahar o kadını kaybettim

Geceydi, olabildiğince ağlıyordum

Mayıs aniden ellerime dökülmüştü

Bir kitap sonuna dek okunmuştu

Hicazkâr''a kaçıyordu elleri ama değil 

Olsa olsa Sûzinâk bir şarkı o kadın...

Klasik Türk Musikisi''nde Rast kararlı makamlardan biri Sûzinâk, güzel, hüzünlü, bu şiire merhum Osman Nihat Akın''ın ''Ellere Uzaktan Bak'' şarkısı vesile oldu, rahmetle anısını selamlıyorum...', 'Ne hatırlarım ne de aklımdan çıkar Olsa olsa Sûzinâk bir şarkı o kadın Gözleri yabancı bir melodi, yepyeni Hicazkâr''a kaçıyordu elleri ama d...', ARRAY['Türk Edebiyatı','Şiir','Hakan Köse']::text[], 8.5, '{"poet":"Hakan Köse","poet_slug":"hakan-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/suzinak-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-sahin-yenilmez-tdgup', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessizliğin rüzgarları esiyor şimdi buralarda

Hava ne soğuk nede sıcak

Kilit vurdum artık sözlerime

Konuşmak artık günah ve yasak

Yalanlarla dost oluyorsun burda

Gerçek insanlardan çok uzak.

Hafızamdan silindi bildiğim bütün güzel şarkılar

Meğer mutlu olunca tat veriyormuş melodiler

Yalnızlık ise sadece içki mezesi.

Avunduğum bütün düşleri unuttum

Ve gözlerimi artık kapatmıyorum

Ne zaman uyuymaya çalışsam yine o bilinmez rüzgarlar esiyor

Yitik ve sebepsiz ölümler geliyor bazen aklıma

Terkedilmiş sevdalar

Ölüme mahkum edilen tutkular

Ve sahibine teslim edilemeden kuruyan güller

Hepsinin bir sebebi vardı belki

Yada belki de sebepsiz bir sebepti.

Sessziliğin rüzgarları esiyor şimdi buralarda

Amacım eğer mutlu olmak olsaydı

Belki bir şansım olabilirdi

Bilirsin bazen mutlu olmak için

Herşeyi kabul ettiğim gibi görmen gerek.

Mululuk yalandır bence

Gerçeklerin ardına gizlienmiş bir avuç yalan.', 'Sessizliğin rüzgarları esiyor şimdi buralarda Hava ne soğuk nede sıcak Kilit vurdum artık sözlerime Konuşmak artık günah ve yasak Yalanlarla...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalan-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ve hüzün kitlendi', 've-huzun-kitlendi-seyit-ahmet-duzen-3iq9w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '... ve hüzün kitlendi

sevda çıkmazında

iki çaresiz 

kuluz şimdi

omuz omuza

iki yabancı

gri sokak

mavi gökyüzü

ve gözü kamaştıran

altın sarısı güneş

aşkı çagrıştıran

herşey vardı

yine de 

omzuna dokunan

yabanci bir eldi

...ve hüzün kitlendi

sandığın kilidini

aralamadı

hiçbir anahtar

aşkı çağrıştıran

ne varsa

naftaline harmanlanmış

duruyordu aramızda

yinede uzanamadık

sevda duvarına

...ve hüzün kilitli', '... ve hüzün kitlendi sevda çıkmazında iki çaresiz  kuluz şimdi omuz omuza iki yabancı gri sokak mavi gökyüzü ve gözü kamaştıran altın sarıs...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ve-huzun-kitlendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Ekili Tarlalar', 'kar-ekili-tarlalar-goktu-kara-875zn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ormanda gezerken bugün

(Perşembe) 

karlara basarken sizi düşündüm yavrularım

ellerinizde kuru ekmekli

mutlu bakışlarınızı

aşağıya indim biraz

yoksulun vadisini görmek için

(Denize düşmüş takunyadır benim vapurum) 

sonra kar ekili tarlalar uçsuz bucaksız

yeşilleniverir gülücükler 

çıkar gözyaşları toprağın derinliklerinden

yavrularım doğayı gözlerinizle görmek ne güzel

yavrularım insanı kollarınızla sarmak ne muhteşem', 'Ormanda gezerken bugün (Perşembe)  karlara basarken sizi düşündüm yavrularım ellerinizde kuru ekmekli mutlu bakışlarınızı aşağıya indim bira...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kar-ekili-tarlalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız Adam', 'issiz-adam-halil-ozcelik-a8kzn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herkesin bir ıssız adası var.

Kiminin adası yalnızlık denizleriyle çevrili, 

Kiminin ki mutluluk okyanuslarıyla.

Benim ıssız adamın 

Dört yanında 

Dört ayrı deniz var.

Sabahın ilk ışıklarıyla

Özlem denizine dalarım ilkin. 

Her kayanın ardında bir yüz 

Her çakıl taşında senden bir iz ararım.

Yosunlardan balıklara 

Canlı cansız kabuklara seni sorarım.

Kolum kanadım kırık çıkınca özlem denizinden

Üzüntü denizine atarım kendimi. 

Beni en iyi anlayan bu denizdir. 

Ben ağladıkça o hırçınlaşıyor.

Dalga dalga dövünerek

Üzüntümü paylaşıyor.

Issız adamın kumsalında 

Biraz dinlenince yorgun bedenim

Ölüm denizinin kıyısında 

Dimdik dururum. 

Ölüme meydan okur gibi.

Kalbimle beynim savaşa tutuşur.

Beynim yılgınlıklara yer yok derken 

Kalbim

Sana kavuşmak için yanar tutuşur.

Sonra uzaklaşırım oradan

Gün batımına doğru.

Hiç sevmesem de bu saatleri

Seni bulmanın umuduyla 

Dalarım umut denizinin koynuna.

 Yüreğim umutla dolar yeniden.

Kurduğum hayaller 

Rüyalarıma eklenir.

Umut oldukça yüreklerde diyorum

Sevgililer ömür boyu beklenir.', 'Herkesin bir ıssız adası var. Kiminin adası yalnızlık denizleriyle çevrili,  Kiminin ki mutluluk okyanuslarıyla. Benim ıssız adamın  Dört ya...', ARRAY['Türk Edebiyatı','Şiir','Halil Özçelik']::text[], 8.5, '{"poet":"Halil Özçelik","poet_slug":"halil-ozcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/issiz-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Laura''nın şarkısı', 'laura-nin-sarkisi-mustafa-sen-l240j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Tenesse Williams''a saygılarımla''

1

Asfaltlar soğuk ve yalnız

gece mavi

Ümitlerine saklandım 

mevsimlik aşkların

2

Uçan halının altında 

kuruttuğum çiçeklerim 

yıldızlara özenirmiş 

cennet bahçesinden gelen jazz tadında

3

Sırça biblolar 

göz yaşı döker mi 

aşk için? 

4

Yüreğim 

mavi gecede

uçan halının üzerinde 

sırça biblo 

usulca git 

kırılmasın', '''Tenesse Williams''a saygılarımla'' 1 Asfaltlar soğuk ve yalnız gece mavi Ümitlerine saklandım  mevsimlik aşkların 2 Uçan halının altında  kur...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen']::text[], 8.5, '{"poet":"Mustafa Şen","poet_slug":"mustafa-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/laura-nin-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçe Böldüm Yüreğimi', 'uce-boldum-yuregimi-halil-ozcelik-e3bwi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlemlerle yoğurduğum

Sevdadan sevdaya vurduğum

Yüreğimi üç parçaya böldüm.

Biriyle seni sevdim; 

Aramızdaki yıllara bakmadan

Yıllardan uzak yollara bakmadan 

Seni sevdim.

Özlem parçası dedim adına.

Umutlarla beslediğim

Hayallerle süslediğim

Yüreğimi üç parçaya böldüm.

Biriyle seni sevdim; 

Yaz gününde yağmur yüklü bulut sanarak

Bir gülüşünü umut sanarak

Seni sevdim

Umut parçası dedim adına.

Zamana korkmadan direnen

Direndikçe sabretmeyi öğrenen 

Yüreğimi üç parçaya böldüm.

Biriyle seni sevdim; 

Beklemekten yakınmadan

Yalnız  yaşamaktan sakınmadan

Seni sevdim; 

Sabır parçası dedim adına.

Özlem parçası, umut parçası sabır parçası

Birleştirdim bütün parçaları

Tek parça yaptım yüreğimi yeniden.

Şimdi özlemle, umutla, sabırla seviyorum seni.', 'Özlemlerle yoğurduğum Sevdadan sevdaya vurduğum Yüreğimi üç parçaya böldüm. Biriyle seni sevdim;  Aramızdaki yıllara bakmadan Yıllardan uzak...', ARRAY['Türk Edebiyatı','Şiir','Halil Özçelik']::text[], 8.5, '{"poet":"Halil Özçelik","poet_slug":"halil-ozcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uce-boldum-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem baladları 1', 'ozlem-baladlari-1-mustafa-sen-wqx4o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1

Geceye yıldızlara direndim durdum

Acımasızdı yıldızlar

Yıldızları tutup adını yazdım

öptüm

yüreğini,terini ve de tenini 

bir dua gibi anıyorum

özledim…', '1 Geceye yıldızlara direndim durdum Acımasızdı yıldızlar Yıldızları tutup adını yazdım öptüm yüreğini,terini ve de tenini  bir dua gibi anıy...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen']::text[], 8.5, '{"poet":"Mustafa Şen","poet_slug":"mustafa-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlem-baladlari-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge Çiçeği', 'golge-cicegi-ali-gencay-xlgay', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'perdeni kıvırıp bak

bembeyaz karlarla karşında

ali dağı...

bu sendeki yanı gecenin

bu gece ayaz var

ay dolunay

bu gece bir gariplik var

yıldızlar

sanki parlaklığın da gözlerin var

uzanıp tutacağım

bu gece bende bir gariplik var

bozulmasın isitiyorum tılsımım

sen bende olduğun da

zaten bende hep bir gariplik var

ellerim değmeden sevmek seni

burnumda kokunu duymadan koklamak

güneşi değdirmeden tenine

yaşatmak yüreğimde 

beni sana adamak gibi

bende bir garip senlik var 

çıkartıp esbablarımı seni giyinmek gibi

korktuğunu biliyorum

acı rüzgar vurmuş gibi tenine

titriyorsun tüm bedeninle

ruhunu ayaza verip

gözyaşlarını donduyorsun

ve soluyorsun

bu gece bende bir gariplik var

neden biliyormusun

bende kimsede olmayan

yüreğimin ta kuytularında

kimsenin bilmediği

bilmesini istemediğim

gölgelerde

çiçeğim var

bu da gecenin bendeki yanı....

a.gencay', 'perdeni kıvırıp bak bembeyaz karlarla karşında ali dağı... bu sendeki yanı gecenin bu gece ayaz var ay dolunay bu gece bir gariplik var yıld...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/golge-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviyse Umutlar', 'maviyse-umutlar-sadik-softa-vm73b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavilere gözüm takılır oldu,

Bir sebebi var mı? .. Bilemez oldum.

Bu sıra maziye bakılır oldu,

Çıkmazlaradan yolu bulamaz oldum.

Umut mavilerle kalbime akar; 

Efedir gözlerin, gözüme bakar; 

Gönüle bıraksam dünyayı yıkar; 

Durduğum yerlerde duramaz oldum.

Fersah fersah uzadıkça uzuyor.

Sanki felek yazım yeni yazıyor.

Dur! ... Dedikçe gönlüm bana kızıyor; 

Yüreğiyle coşan yaramaz oldum.

Ne haldeyim, bunu nasıl söyleyim? 

Kahıra gömüldüm ondan böyleyim.

Yürek seni parça parça böleyim.

Varacağım yere varamaz oldum.

Bıktırdıkça bıktırıyor zamanlar.

Sıra sıra diziliyor amanlar,

Anlayan olurmu, bimem kim anlar? 

Sorulara cevap alamaz oldum.

Uzadıkça sözüm, gönlümü yakar.

Avazım uzar da ayyuka çıkar.

Maviler de artık yüzüme bakar.

Kendimi kendimde bulamaz oldum.

Çankırı-19.02.2004', 'Mavilere gözüm takılır oldu, Bir sebebi var mı? .. Bilemez oldum. Bu sıra maziye bakılır oldu, Çıkmazlaradan yolu bulamaz oldum. Umut mavile...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/maviyse-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkindinin Gül Kokan Gölgesi', 'i-kindinin-gul-kokan-golgesi-hasan-akin-a243d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ip bağladım kiraz ağaçlarına 

salıncaklarda yüreğimi uçurdum gün boyu

kilim serdim ayvanın serinliğine

tabakada tütün sarıp ağ düşürdüm ağrıyan saçlarıma

kırık üzüm bağları görürsem düşünde

dere otu kokan bahçelerden geçersen

ikindinin gül kokan gölgesine çiz resimlerimizi

sakın korkma 

bir daha harmalara götürmem seni nazlı yar

saman tozlarına boğmam kızıl saçlarını

şimdi gelirsen

gece vakti ansızın gel

unuttuğumuz bütün türküleri söyleyerek

çal kapımı', 'ip bağladım kiraz ağaçlarına  salıncaklarda yüreğimi uçurdum gün boyu kilim serdim ayvanın serinliğine tabakada tütün sarıp ağ düşürdüm ağrı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akın']::text[], 8.5, '{"poet":"Hasan Akın","poet_slug":"hasan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ikindinin-gul-kokan-golgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün güzel yüzü', 'olumun-guzel-yuzu-yagmur-damlasi-3as9r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ay bulutların ardına gizlendiğin de

Zifir geceler pusu atar yüreğime

Evlat acısı gibi kor yokluğun

Oturur ciğerlerime

Son kibrit

Son sigara

Son nefes bu işte

Ben ölümü anarım bir eski dost gibi

Ölüm beni arar kaybolmuş bir yar sanki

Ve sen

Hep aramıza girersin o an da

Son parçası da kırılan o aynanın

O son hatırasında

Ne ses gelir senden ne bir seda

Yaşıyor musun öldük mü yoksa

Böyle bir zulmü Allah vermesin dosta

Varlığın yokluğundan 

Yokluğun varlığından da

Bin betermiş anladım be yosma

Sen ölümün güzel yüzü

Artık yeter olsun

Çok çektim biliyorsun

Sen al beni koynuna', 'Ay bulutların ardına gizlendiğin de Zifir geceler pusu atar yüreğime Evlat acısı gibi kor yokluğun Oturur ciğerlerime Son kibrit Son sigara ...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olumun-guzel-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Var Eden', 'seni-var-eden-yagmur-damlasi-d162t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay yüzün karanlığa dönmüş

Sen bulanık suların balığı

Son mumdu yüreğimde yanan sönmüş

Aldım kabul ettim hediyen olan yalnızlığı

Bu gece mehtabı koynuma alıp

Uyumak vardı ya neyse

Yalnızlığına sarılıp

Uzandım soğuk döşeğime

Kokun çok uzaklardan

Geliyorken baş ucuma

Uyanıp seyre daldım

Bir prensesi hayaller dünyasında

Soru sorma bana sakın

Alacağın cevap hoşuna gitmeyebilir

Sebepsiz değil yalnızlığın

Bir gece bütün olmazların olabilir

Umut aşkı var edendir', 'Ay yüzün karanlığa dönmüş Sen bulanık suların balığı Son mumdu yüreğimde yanan sönmüş Aldım kabul ettim hediyen olan yalnızlığı Bu gece meht...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-var-eden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızsınız', 'yalnizsiniz-yagmur-damlasi-hxw3c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sizin şiirleriniz var yalnız değilsiniz

Sonra! 

Bir eski tükenmez sevdanız

Güzel anılarınız, atınız arabanız

Ha bir de yanıp kül olan yalınız

Dostlarınız var çokça 

Kimi 

İçten içe size sevdalı

Kimi ben gibi pervasız patavatsız 

Ve en çok yüreğinizde bir başınasınız

Ve en çok o yürek sizin belanız

Hiç umursamaz gibi dursanız da

Bir çürük elmanın içinde ki 

Kurt gibi

Kemirip durmakta sizi

Yalnızlığınız......................................

Doğru değil hayatı

Bu kadar ciddiye almanız

Bir sabah emin olun ki

İsteseniz de uyanamayacaksınız

Ne derseniz deyin bana bir gün anlayacaksınız

Bensiz olduğunuz her an

Yapayalnızsınız.', 'Sizin şiirleriniz var yalnız değilsiniz Sonra!  Bir eski tükenmez sevdanız Güzel anılarınız, atınız arabanız Ha bir de yanıp kül olan yalını...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yalnizsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cogaliyorsun', 'cogaliyorsun-deniz-guney-0gh0a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilesin ki çoğalıyorsun

Güneş öksüzü penceremde...

Suretini asabildiğim gözlerimin

Aslına uzanamadığındandır

Çanak tutmuşluğu

Islak öpüşmesine kirpiklerimin…

Ki her gün

Bakışı da degişiyor

Güneşin var mı? 

Bilesin ki çoğalıyorsun

Ağıyorsun sarmaşıklar gibi..

Ömrümün 

İmzamla onaylanmış

Depreme dayanıklı ibaresi ile

Yosun rengi duvarında

Bu yüzden hep rutubet sanılır

Güneş müsrifleri tarafından

Sarmaşık dibinin serinliği

Yosunun var mı? 

Bilesin ki çoğalıyorsun

Yalnız kalabalıklarımda..

Sabah serininde 

Taze umutlu yer tezgahları kurulan

Öğleyin

Uyduruk tente üstlerinde

Sarı sıcakla toz toprağın seviştiği

Panayır alanı yüreğimde

Horoz döğüşüne bakan çocukların

Horoz şekeri bulaşığı ellerinde

Hangi yüzden bulunmaz sabit pazarlarda

O şekerden? 

Şekere bulanmışlığın var mı?', 'Bilesin ki çoğalıyorsun Güneş öksüzü penceremde... Suretini asabildiğim gözlerimin Aslına uzanamadığındandır Çanak tutmuşluğu Islak öpüşmesi...', ARRAY['Türk Edebiyatı','Şiir','Deniz Guney']::text[], 8.5, '{"poet":"Deniz Guney","poet_slug":"deniz-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cogaliyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunma!', 'dokunma-zafer-zengin-etnika-3ib94', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dokunma! 

Kendime erteledim hayatı

dokunma

ağlayacağım...

imdadım sessiz

imdadım sensiz

dokunma! 

ağlayacağım...

bugün', 'Dokunma!  Kendime erteledim hayatı dokunma ağlayacağım... imdadım sessiz imdadım sensiz dokunma!  ağlayacağım... bugün...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dokunma-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözün Büyüsü', 'sozun-buyusu-semih-tanriver-1ibn0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen var isen yar isen

İçimdeki bu yokluk ne! 

Yok isen değil isen

İçimdeki bu varlık ne!', 'Sen var isen yar isen İçimdeki bu yokluk ne!  Yok isen değil isen İçimdeki bu varlık ne!...', ARRAY['Türk Edebiyatı','Şiir','Semih Tanrıver']::text[], 8.5, '{"poet":"Semih Tanrıver","poet_slug":"semih-tanriver","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sozun-buyusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgacı Güzel II', 'kavgaci-guzel-ii-hakan-sarkdemir-tnp0f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Merhaba türkülerim,

gel, biraz dertleşelim.

Çıkalım rutubetin bu harap konağından.

Bize dar bir vakit de kalsa,

sade bir hırka alarak üstümüze,

hadi gel, söyleşelim 

yıldızların altında.

“Korkma hiç türkülerim! 

Kırpışan yıldızlardır,

bu garip söyleşinin biricik konukları,

bir de vahşi ormanlar 

bize belki katılır,

kabarırsa iştahı

ve dilerse o rüzgar.

“Meğerse türkülerim,

bir rüyaymış yaşanan.

Kimse öpmemiş beni, inanmışım o kadar.

Hiçbir şey göründüğü 

gibi değil gerçekten.

Bir bela çatana dek

ikna olmuyor insan.', '“Merhaba türkülerim, gel, biraz dertleşelim. Çıkalım rutubetin bu harap konağından. Bize dar bir vakit de kalsa, sade bir hırka alarak üstüm...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şarkdemir']::text[], 8.5, '{"poet":"Hakan Şarkdemir","poet_slug":"hakan-sarkdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kavgaci-guzel-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlar için', 'yalnizlar-icin-guzin-eye-dundar-z4sbe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günleri tekdüze yalnızlar için 

en gizli sığınak en kuytu körfez 

bekler zaman süzgecinde güzelleşerek 

bir düş gibi yinelenir anılar

ne kaybolan sevgililer ihtiyar

ne uzaklar engel ne ayrılıklar

teni kışa durur yüreği bahar

her vurgun gidişe bir sayfa açar

gizli  bir bahçesinde suskun anılar…', 'Günleri tekdüze yalnızlar için  en gizli sığınak en kuytu körfez  bekler zaman süzgecinde güzelleşerek  bir düş gibi yinelenir anılar ne kay...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizlar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahmur Saatler', 'mahmur-saatler-faruk-tak-s82qe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim günü yarıladığım saatler

Senin mahmur saatlerin

Sana dair geliştirdiklerimi bir bilsen

                                        sen uykudayken

Kan ter dökerdin sırılsıklam severdin

Severdin de, ah bir uyanabilsen', 'Benim günü yarıladığım saatler Senin mahmur saatlerin Sana dair geliştirdiklerimi bir bilsen                                         sen uyk...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tak']::text[], 8.5, '{"poet":"Faruk Tak","poet_slug":"faruk-tak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mahmur-saatler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Günlüğü', 'sevginin-gunlugu-turgay-kadiroglu-fxnu6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'birgün seversek eğer

 bir gün sevmeyiz

 seneyi üç yüz altmış beşe böler

 her birinde yeniden diriliriz...

 aşkı kırmızı gül diye

 elimize süs yapmayız,

 akşam kızılı diye yüreğimize çalar

 şafağa dek korunda ısınır

 ışığında aydınlanırız...

 aşkı Yaratan''a Hamd,

 bir güne boğana sitem olsun...', 'birgün seversek eğer  bir gün sevmeyiz  seneyi üç yüz altmış beşe böler  her birinde yeniden diriliriz...  aşkı kırmızı gül diye  elimize sü...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevginin-gunlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Mahmurluğu', 'kalp-mahmurlugu-faruk-tak-37yku', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben uyandım dinliyorum seni dedin

Gözlerinle beni yutarak

Her şeyin farkında gibi duruyordun

Sevdiğimi unutarak

Ben uyandım dinliyorum seni dedin

Kalbinin mahmurluğunu saymazsak', 'Ben uyandım dinliyorum seni dedin Gözlerinle beni yutarak Her şeyin farkında gibi duruyordun Sevdiğimi unutarak Ben uyandım dinliyorum seni ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tak']::text[], 8.5, '{"poet":"Faruk Tak","poet_slug":"faruk-tak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kalp-mahmurlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-faruk-tak-rbyi0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sahnede olmak

en güzeli; 

Sıran gelince oynamak rolünü,

Ve oyun bitince

Kapatmak perdeyi

Yeni oyuna kadar; 

Oyun oynamak en güzeli', 'Bir sahnede olmak en güzeli;  Sıran gelince oynamak rolünü, Ve oyun bitince Kapatmak perdeyi Yeni oyuna kadar;  Oyun oynamak en güzeli...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tak']::text[], 8.5, '{"poet":"Faruk Tak","poet_slug":"faruk-tak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/oyun-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendiyle Barışık Olmalı Aşk', 'kendiyle-barisik-olmali-ask-yuksel-ozbek-h1bnn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklımın yaylasında uçan güvercinim

Ağzında özlem 

Gönlünde sevgi 

gözünde aşk taşıdın,

Kondun gönlüme.

Hiç bilmediğim kıtanın 

Adını öğrenemediğim şehrindesin oysa.

Boyutlar ötesi yaşanan

Ve

Yaşanacak olan ne varsa

Evcilleştirici değil

Olabildiğince özgür olmalı.

Yüzünü usuma çizdiğim güzel

Sen yaşam ağacımın sevgili meyvesi

Sen ufuk çizgimsin

Ne bitip-ne başlayabildiğim

O kadar uzak-o kadar yakın

Olanımsın

Biliyorum güzel

Aşkı tutsak almamalı beden

Beyinde sever

Sende takılı kalmam

“düşün”güzelliğinde

sendeki bedeni değil

bedenindeki seni seviyorum bende

kendiyle barışık olmalı aşk

ölüm kokmamalı yaşam 

hüzün kokmamalı sevinç

Düşün sevgili

İnsanlar

Bedelsiz ve bedensiz de sevebilir

Seni sevdiğim gibi', 'Aklımın yaylasında uçan güvercinim Ağzında özlem  Gönlünde sevgi  gözünde aşk taşıdın, Kondun gönlüme. Hiç bilmediğim kıtanın  Adını öğrenem...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Özbek']::text[], 8.5, '{"poet":"Yüksel Özbek","poet_slug":"yuksel-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kendiyle-barisik-olmali-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-faruk-tak-vcx6u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Virgül

Noktalı virgül

Son nokta.', 'Virgül Noktalı virgül Son nokta....', ARRAY['Türk Edebiyatı','Şiir','Faruk Tak']::text[], 8.5, '{"poet":"Faruk Tak","poet_slug":"faruk-tak","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yasam-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haklısınız', 'haklisiniz-yagmur-damlasi-mxgr7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben dünyadan bakıyorken size

Yıldızlardan salıncağınızda siz ise

Neşe ve mutluluklar içerisinde

Gülümsüyordunuz yüreğime

Biliyorum bu gece de

Her gece olduğu gibi ayı aynı yerine

Siz koydunuz,

Kim bilir belki de 

Kokunuz,

Dünyada ki sevginin bitişine

Karşı koyamamaktı gönlünüzce

Bu sebepledir ki direnemeyip sevgime

Kal yada git diyemediniz

Oysa ben yüreğimi alıp elime

Rüyalarınıza girmek üzereyken

Halimi çamura batmış bir balık gibi

Size anlatamadım,

Kim bilir belki de anladınız

Ben yanıldım,

Balıkla gök yüzü bir araya gelemez di ya

hep siz haklıydınız ya

bu sefer de siz haklısınız.', 'Ben dünyadan bakıyorken size Yıldızlardan salıncağınızda siz ise Neşe ve mutluluklar içerisinde Gülümsüyordunuz yüreğime Biliyorum bu gece d...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/haklisiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hür akıl', 'hur-akil-abdullah-garip-c0vrs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hür akıl çıplak kalır sevgiden

Hür akıl nasipsizmiş iradeden

Hür akıl ufuk bulamaz mesafeden

Hür akıl, bedelsiz bir düşünceden

Akıl hastasını tedavi ederler

Düşünce hastasını taltif ederler

Akıl hayatın bütünüyle var olan

Sevgiyi-bilgiyi bulan akl-ı selim olan', 'Hür akıl çıplak kalır sevgiden Hür akıl nasipsizmiş iradeden Hür akıl ufuk bulamaz mesafeden Hür akıl, bedelsiz bir düşünceden Akıl hastasın...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hur-akil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-abdullah-garip-f6754', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün olur sözü bitirmek değil,

Dil bağlayıp, gül bitirmek zor

Düğünü-ölümü bayramı değil,

Anılarda dostları hatırlamak zor.

Kalpte sevgileri taşımak değil,

Uzaklarda hasretini çekmek zor.

Huzurda ki gülmeyi unutmak değil,

Sensiz ağlamaya alışmak zor.

Anlasana yaşamak değil, ölmek değil

Özleyipte görememek zor.

Kahvenin kırk yıl hatırı değil,

Dostun hatırını yıkmak zor', 'Gün olur sözü bitirmek değil, Dil bağlayıp, gül bitirmek zor Düğünü-ölümü bayramı değil, Anılarda dostları hatırlamak zor. Kalpte sevgileri ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zor-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umursanmaz', 'umursanmaz-abdullah-garip-tr3s9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aç oldukları umursanmaz

Suçlu oldukları yanlarına kalır 

İnsanlar gider hasreti kalır

Sofralar dağılır, resmi kalır

Düğün olur, ölüm olur, bayram olur

Anılar kalır, dostluklar hatırlanır

Gün olur söz biter

Dil bağlanır, gül biter', 'Aç oldukları umursanmaz Suçlu oldukları yanlarına kalır  İnsanlar gider hasreti kalır Sofralar dağılır, resmi kalır Düğün olur, ölüm olur, b...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umursanmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-abdullah-garip-98irn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizim toprağımız gül toprağıdır

Ne sevdasına bir toz kondurur

Ne de bir gonca gül soldurur

Bizim toprağımız gül toprağıdır

Dostluklarımız yollara benzer

Yolcu biter ama yol bitmez

Ömür biter ama dostluk bitmez

Dostluklarımız yollara benzer

Gökkuşağının rengi umudumuza yol olur

Yıldızlarımız yollarımıza ışık olur

Gönüllerimiz, güzelliklere teşne olur

Gökkuşağının rengi, umudumuza yol olur', 'Bizim toprağımız gül toprağıdır Ne sevdasına bir toz kondurur Ne de bir gonca gül soldurur Bizim toprağımız gül toprağıdır Dostluklarımız yo...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anadolu-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum!', 'seni-seviyorum-nazife-abayli-wpwwa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yoğun enerji ile yüklüyüm bugün,

Çatlıyacağım,

Yüreğime sığmıyor,

Her yanımdan sevgi akıyor sanki....

Yolda sokakta,

Çarşıda pazarda okulda,

Gördüğüm tüm insanlara,

Dosta,düşmana,

Şu karşıki çamlığa,

İçindeki kurda kuşa,

Denizdeki balığa,

Seni seviyorum,

Demek geliyor içimden.

Evimin neşesi,

Gönlümün gülleri,

Canımın canları,

Canım çocuklarım.

Sizleri seviyorum.

Komşularım, meslektaşlarım,

Öğrencilerim, arkadaşlarım,

Buradaki tüm dostlarım,

Sizleri de seviyorum.

Biliyorsun değil mi aşkım? 

Bu sevginin kaynağı SEN''sin...

SEN dolduruyorsun yüreğimi....

Canıma can,

Sesime ses,

Yüreğime yürek katan,

SEN! 

Seni seviyorum! 

Bıkmamacasına,

Doymamacasına,

Seni Seviyorum!', 'Yoğun enerji ile yüklüyüm bugün, Çatlıyacağım, Yüreğime sığmıyor, Her yanımdan sevgi akıyor sanki.... Yolda sokakta, Çarşıda pazarda okulda,...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/seni-seviyorum-168-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisizlik', 'sevgisizlik-abdullah-garip-nwj4v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biri var, eften püften bir şeye ağlıyor

Sevgisizlikten nefsi acımış

Biri var, en hicranlı meseleye kayıtsız kalıyor

Bencillikten nefsin ağına takılmış

Sevgi, düşünmenin ilk şartı

Samimiyetin bereketi, sevginin ilk şartı

Varsa insanda eğitim-kültür-fikir 

Sevgisizlik, şeytan-i üçgenin ilk şartı', 'Biri var, eften püften bir şeye ağlıyor Sevgisizlikten nefsi acımış Biri var, en hicranlı meseleye kayıtsız kalıyor Bencillikten nefsin ağın...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgisizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medya1', 'medya1-abdullah-garip-iry7e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zevk için avlanmaya çıkmış

Efendilerine yaltaklanma izini sürüyor

Meslekleri medya tetikçiliğine çıkmış

Kanlı gözlerle dişlerini bileniyorlar

Son darbeyi vurmak için çıkmış

Her halleriyle pitbull oluyorlar

Efendileri nefisleri öne çıkmış

Her halleriyle fino oluyorlar

Ne kinleri sahici olmuş

Ne de sevgide sahici oluyorlar

Akşam evlerine nasıl dönmüş

Acaba insana nasıl dönüyorlar

Herkesin mazisinde bir nakısa vardır

Didik didik nakıssalar arıyorlar

İlk bulduğuna azı dişini geçirmiş

Kendilerine hiç mi hiç dönüp bakmıyorlar

Vicdan, merhamet, insana duyarlılık ölmüş

Kendi geçmişlerini ne zamana saklıyorlar

Kendinden, efendisinden harici incelenmiş

Bir koku alınca köpek balığına dönüyorlar

Bilmem kaç yıl önce abc demiş

Hayrat kazan içinde bir vecettü diyorlar

Bir su-i zan, bir iftira edilmiş

Ne soruyor ne de fırsat veriyorlar', 'Zevk için avlanmaya çıkmış Efendilerine yaltaklanma izini sürüyor Meslekleri medya tetikçiliğine çıkmış Kanlı gözlerle dişlerini bileniyorla...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Garip']::text[], 8.5, '{"poet":"Abdullah Garip","poet_slug":"abdullah-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/medya1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çiçek Açar', 'bir-cicek-acar-hasan-huseyin-ozak-3ppmw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir çiçek açar,

pencere kenarında, saksıda

Her gün sevgili olur, 

yalnızlıkları paylaşır, sevilir, okşanır

Açtı diye bayram yapılır

Bir çiçek açar

Yüce dağ başında.............

Adına türküler yakılır', 'Bir çiçek açar, pencere kenarında, saksıda Her gün sevgili olur,  yalnızlıkları paylaşır, sevilir, okşanır Açtı diye bayram yapılır Bir çiçe...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-cicek-acar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapma Can', 'yapma-can-i-brahim-ethem-bingul-lh07x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alınmaz olmuş selamımız

Ne de yürekle yazılmıştı kelamımız

Bilmeyiz, neymiş hatamız

Sevgimiz candır, candan öte

Sevgili nazdadır,artık nazdan geçe

Yıldızları indirme yere

Karışmam kaldıramam bir daha göğe', 'Alınmaz olmuş selamımız Ne de yürekle yazılmıştı kelamımız Bilmeyiz, neymiş hatamız Sevgimiz candır, candan öte Sevgili nazdadır,artık nazda...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yapma-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Durağı', 'askin-duragi-i-brahim-ethem-bingul-84yze', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susarsa sevgililer,gül ağlar,bülbül susar

Aşkın bittiği yerde başlar,utançtan duvar

Sev, aşkı öğren burda,kalptir onun okulu

Sevmenin yaşı yoktur,bunun ötesi aşktır

Sevgilime göz deyse,gönlüme hicran olur

Sevdiğim bensiz gülse,ölümüm o an olur

Yer yüzü sevgililere,aşklara olsa fuar

Yetmez sevdama alan,ona kalp mekan olur', 'Susarsa sevgililer,gül ağlar,bülbül susar Aşkın bittiği yerde başlar,utançtan duvar Sev, aşkı öğren burda,kalptir onun okulu Sevmenin yaşı y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askin-duragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ak Güvercin', 'ak-guvercin-vahittin-bozgeyik-74wk1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutulmuş bir kentten geldim ak güvercinim,

Kutuptan kutuba yaya gitmişim sanki

Sendeki beni arıyorum,

Yorgunum...

Ak bir kentin,ak güverciniydin sen,

Dönümsüz uçuşlara çıkmazdın ne oldu

Güvenme göklerin özgürlüğüne,

Konduğun ağaçlara tepelere güvenme! ...

Mevsimler değişiverir birgün ak güvercinim...

Tek bir şey var değişmeyen,

Ak kentin aklığı ve bendeki sen...

Yuvanın sıcaklığını bozmadı,

Unuttuğun ak bir tel,

Kanadın kırılsa da bir gün

Gel...', 'Unutulmuş bir kentten geldim ak güvercinim, Kutuptan kutuba yaya gitmişim sanki Sendeki beni arıyorum, Yorgunum... Ak bir kentin,ak güvercin...', ARRAY['Türk Edebiyatı','Şiir','Vahittin Bozgeyik']::text[], 8.5, '{"poet":"Vahittin Bozgeyik","poet_slug":"vahittin-bozgeyik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ak-guvercin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Aşkımın Odak Noktası', 'gozlerin-askimin-odak-noktasi-vahittin-bozgeyik-sw6a7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne deniz mavisi ne dağ yeşili

Gözlerin aşkımın odak noktası

Sevgi yağmurunun ebemkuşağı

Gözlerin aşkımın odak noktası

Gönlümün çağrısız konuğu olan

Sevgi yumağında kendini bulan

Aşk bulvarındaki çıkmazım olan

Gözlerin aşkımın odak noktası.

Yunus''un aşkıyla gönüller çelen

Aydınlık düşlerden özlemle gelen

Bahar bahar bakan,benimle gülen

Gözlerin aşkımın odak noktası.', 'Ne deniz mavisi ne dağ yeşili Gözlerin aşkımın odak noktası Sevgi yağmurunun ebemkuşağı Gözlerin aşkımın odak noktası Gönlümün çağrısız konu...', ARRAY['Türk Edebiyatı','Şiir','Vahittin Bozgeyik']::text[], 8.5, '{"poet":"Vahittin Bozgeyik","poet_slug":"vahittin-bozgeyik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerin-askimin-odak-noktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı', 'kirmizi-zafer-zengin-etnika-i9azi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırmızı

gül

açardı

gözlerim

taç yaprağı...

20 subat 2004', 'Kırmızı gül açardı gözlerim taç yaprağı... 20 subat 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kirmizi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahvehane önü', 'kahvehane-onu-zafer-zengin-etnika-iehoq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kahvehane önünden toplardık

çocukluğumuzu

yarım izmaritler

yarım aşklar

yarım sevgili gülüşleri

kavuşamadım tamlara

yarım,yarımsınız

çocuk.. çocuk.

bir güzel bakardı ki; 

çocuk yüzü

büyürdüm ellerinde; 

çocuk çocuk 

tüm yarım izmaritlere..yarım kalan öykülere.sevilen dostlara.. ve unutulmayanlara

20 subat 2004 sabah oldu ellerimde..insanlığım uyku ister..uyu..uyu.uyu.uy..u', 'Kahvehane önünden toplardık çocukluğumuzu yarım izmaritler yarım aşklar yarım sevgili gülüşleri kavuşamadım tamlara yarım,yarımsınız çocuk.....', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kahvehane-onu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dostun', 'bir-dostun-zafer-zengin-etnika-zgo1c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dostun,

Gülüşünü sevdik...

Dudağım; 

Sen oldun...

20 subat 2004', 'Bir dostun, Gülüşünü sevdik... Dudağım;  Sen oldun... 20 subat 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-dostun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-zafer-zengin-etnika-kf18d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Defterimiz 

gül kokar...

İnsan yanımız

can...

can...', 'Defterimiz  gül kokar... İnsan yanımız can... can......', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/can-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur', 'huzur-fikret-bese-x1d4c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerim bir deniz kenarında

Kumlarla haşır neşir,

Gözlerim ufkun civarında

Gezinen teknelerle eyleşir; 

Kulağım kıpırdayan suda

Gezinen nağmeleri arar,

Yanağım esen uğultuda

Serin bir huzuru yakalar; 

Ayaklarım ıslanır bazen

Dalgaların köpüğüyle bezenir,

Dilim kanatlarını süzen

Kuşlardan şarkı özenir; 

Ruhum buraya ait,

Her şey gönlümce güzel; 

Vakit de oldukça müsait

Saadetim ömre bedel...

(Ankara/1983)', 'Ellerim bir deniz kenarında Kumlarla haşır neşir, Gözlerim ufkun civarında Gezinen teknelerle eyleşir;  Kulağım kıpırdayan suda Gezinen nağm...', ARRAY['Türk Edebiyatı','Şiir','Fikret Beşe']::text[], 8.5, '{"poet":"Fikret Beşe","poet_slug":"fikret-bese","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzur-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yazarım,Şair Değilim..! !', 'siir-yazarim-sair-degilim-nazife-abayli-izcq9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir yazarım,

Şair değilim.

Süslemeli sözler bilmem,

Sadedir dilim.

Çünkü öğretmenim.

Nefret ile tanışmadım,

Kin, kibir bilmem,

Sadece severim.

Safım,temizdir yüreğim,

Ama aptal değilim.

Deli de değilim,

Birazcık asabiyim.

Çılgınlık yaparım ara sıra,

On beş  yaşında liseliyim.

Olgunlaşıveririm birden,

Yetmiş  yaşında nineyim.

Kendimi severim.

Barışığım yaşamla.

isyanlarım olur fenalıklara ama,

Yaşamayı da severim.

Türkü dinler,

Türkü söylerim.

Evde okulda her yerde.

Çocuklarıma da öğretirim.

İnsan gibi insan olmaları içindir,

Verdiğim emeklerim.

Sevgi eker yüreklere,

Sevgi biçerim.

Aşk ile dolu yüreğim,

Seveni de sevmeyeni de severim.

Koyduklarında bir gün mezara,

Sevgi dolu yürekler bırakmaktır,

Sadece dileğim.

Sevgi delisi,bir garip Nazife'' yim...', 'Şiir yazarım, Şair değilim. Süslemeli sözler bilmem, Sadedir dilim. Çünkü öğretmenim. Nefret ile tanışmadım, Kin, kibir bilmem, Sadece sever...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/siir-yazarim-sair-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Hicret yerim', 'hicret-yerim-sair-ahrazi-tk112', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin gölgen bana benden beridir,

Yolun cihân olur hâlden göçerim,

Hayâlin sînemin hicret yeridir,

Adın dergâh olur dilden göçerim.', 'Senin gölgen bana benden beridir, Yolun cihân olur hâlden göçerim, Hayâlin sînemin hicret yeridir, Adın dergâh olur dilden göçerim....', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hicret-yerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Babam Ah*', 'ah-babam-ah-bayram-tunca-k0mij', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kınamayın, böyle garip garip baktığıma

Ne edeyim yine babam geliverdi aklıma

Yitirdim babamı, kalakaldım tek başıma

Hâlâ babamı arıyorum bakmayın yaşıma

Öldüğümde, onun yanına koyun naaşımı

Sakın ola silmeyiniz hicranlı gözyaşlarımı

Muhtemel ona mukabil görürüm babamı

Yaşasaydı, verirdim uğrunda tatlı canımı

Ah garip babam ah sen zorlukların adamı

Sen gidince, akbabalar yağma etti obamı

Hiç unutmadım unutamam ki ben babamı

Yaş kemale erse de çırayla ararım babamı

Belleğimin ilk satırına yazdım onun ismini

Hiç unutamadım, unutamam onun cismini

Korkmasın asla lekeletmem ben onun adını

Olsaydı hayatta verirdim ona kanımı/canımı

www.baysab.com/18.01.2003-18.01

Duygu Harmanı 14. sayfasında yayınlanmıştır', 'Kınamayın, böyle garip garip baktığıma Ne edeyim yine babam geliverdi aklıma Yitirdim babamı, kalakaldım tek başıma Hâlâ babamı arıyorum bak...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ah-babam-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öz Ağlamayınca Göz Ağlamaz', 'oz-aglamayinca-goz-aglamaz-hakki-hakan-kaya-x5k57', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gündüz rüyasını iyiye yormalı,

Şer insana hayr sağlamaz,

Laf kemiksizdir önce bir sormalı,

Dil dönmeyince söz bağlamaz,

Aşkı aşk gibi yoğun yaşamalı,

Ateş har olmayınca et dağlamaz,

Hisler arşa değmeli duygu patlamalı,

Öz ağlamayınca göz ağlamaz.', 'Gündüz rüyasını iyiye yormalı, Şer insana hayr sağlamaz, Laf kemiksizdir önce bir sormalı, Dil dönmeyince söz bağlamaz, Aşkı aşk gibi yoğun ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oz-aglamayinca-goz-aglamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ILGAZ Özür Dilerim...', 'ilgaz-ozur-dilerim-adnan-ferit-f64rp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ilgaz özür dilerim senden

O kocaman yüreğin,

Küçücük ellerin

Sarılırken sımsıkı yaşama

Bin dost çevrendeyken bu yaşında

Evime haciz gelecek,

Soğuk duvarlar ardında yaşamım sürecek

Para denilen fahişe yüzünden evime kabuslar çökecek

Diye,

Küstüğüm için yaşama 

Çabucak bıraktığım için umutlarımı ardımda

Özür dilerim.

Bu gün bu saatte bile sonumun ne olacağını bilmesemde

Bana yolları uzak

Ruhu yakın o şehirde

Savaşını verirken sen hastahanede

Umut oldun açtın yüreğimde

Kavgaya devam dedin güzel yüreklim

Ben buradan bile hissettim.

Galip sayılır bu yolda mağlup bile.

Sen bu gücü verdin abine.,

Allah senin yanında olsun

Sevenlerinle birlikte.', 'Ilgaz özür dilerim senden O kocaman yüreğin, Küçücük ellerin Sarılırken sımsıkı yaşama Bin dost çevrendeyken bu yaşında Evime haciz gelecek,...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ilgaz-ozur-dilerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzini Sürdüm Aşkın…', 'i-zini-surdum-askin-muammer-celik-iaee7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İzdüşümünde aşkın

tam yediyüzbin yılı aşkın

süregeldim taaa Altay yaylalarından

Babil’den

Anadolu’dan

Balkanlar’a kadar...

Yetmedi, 

devam ettim 

sürdüm izdüşümünü aşkın

tam yediyüz yılı daha aşkın

kuzeyin buzdan denizine

denizdeki buzdağının tepesine kadar… 

Dibine inmeye korktum, eyyy sevgili

dibinde dağdan büyük sen vardın...! 

BirDeli

20.02.2004

(Nilgün Gürbüz dostumun “Hasret“ isimli şiirine yazdığım yorumdan çikarım yapılmış nazire’dir)', 'İzdüşümünde aşkın tam yediyüzbin yılı aşkın süregeldim taaa Altay yaylalarından Babil’den Anadolu’dan Balkanlar’a kadar... Yetmedi,  devam e...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/izini-surdum-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumarda Kazanan.... / Aşk ta kaybeder.', 'kumarda-kazanan-ask-ta-kaybeder-mine-ozdemirtas-le9me', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son bir  oyun istiyorum senden,

Tek bir el. /Kural katı olacak.

Sevgiden ilk bahseden........... / Gider.

Var mısın? 

Ama...... her şeyine.? 

Sen,

Yasakları kaldıracaksın önce.

Uzanıp dokunma hakkımı istiyorum.

Ayrıca bir de......... / Süresiz  Vize.

Karşılığında Ben,

Hayatımı süreceğim önüne.

Yetmezse.......... Şiirlerim devreye girer.

Son bir el dedim.

Haydi gel.

Zaten bütün kumarbazlar gibi,

Şah ve mat değil mi? ....hedefin.

Ha şimdi...... ha sonra...... / Ne fark eder? 

Ama unutma! 

Kumarda kazanan....... / Aşk ta kaybeder.

Son bir  oyun istiyorum senden,

Tek bir el. /Kural katı olacak.

Sevgiden ilk bahseden........... / Gider.

20/02/2004  ist.', 'Son bir  oyun istiyorum senden, Tek bir el. /Kural katı olacak. Sevgiden ilk bahseden........... / Gider. Var mısın?  Ama...... her şeyine.?...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kumarda-kazanan-ask-ta-kaybeder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manol', 'manol-kubilay-enginol-42pv2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beyoğlunun ara sokaklarından birinde

Evinin merdivenlerinden iniyordu 

                                           Manol

Yıllara meydan okumuş elbisesini

Bilmem kaç bininci kez ütülemişti

Garsondu kendini bildi bileli

Bilirdi bahşiş almanın ince hilelerini

Kimlere servis yapmamıştıki

Hatırladı, yine hafifçe gülümsedi

Ne çabuk geçivermişti yıllar

Ah birde olmasa şu ağrılar

Beyoğlunun ara sokaklarının birinde

Evinden manol çıkıyordu

Hiç birşeyden habersiz

Kimse onu göremiyordu

Artık ütüye gerek yoktu', 'Beyoğlunun ara sokaklarından birinde Evinin merdivenlerinden iniyordu                                             Manol Yıllara meydan okumu...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/manol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Doğası Ebedi...', 'askin-dogasi-ebedi-bekir-mutlu-gokcesu-5kupi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her neye

Ve her kimeyse

Aşk; 

En çok doğallık

İster...

O, kalpten hissediş

Biraz da gizleyiş

İster...

Tutkunu tanır

Yolunu bulur o

Su misali

Kıpır, kıpır akar

Coşar, coşar

Kendi bendinde

Coşar da durulur

Akar yine

Kendi halinde...

İnansın yeter ki

Ebedi ömrünü verir

Seven bir gönüle...

Fakat abartılmaya

Gelmez aşk

Bir düşe konar

Gerçeği arar

Bir gerçeğe

Sırtını dayar

Bir düşe uçar

Kuş misali

Çok sıkarsan şaşar

İlk fırsatta kaçar

Fazla hırpalanmaya

Gelmez aşk...', 'Her neye Ve her kimeyse Aşk;  En çok doğallık İster... O, kalpten hissediş Biraz da gizleyiş İster... Tutkunu tanır Yolunu bulur o Su misali...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/askin-dogasi-ebedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gönül', 'ey-gonul-engin-namli-3vbpv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gün ne kadar durgunsun ey gönül

Gün akşam etti güneş uğurluyor

O tatlı hazza takılıp kalalı

Gözlerin hala bir düş ağırlıyor

Sırra kadem mi bastın bugün böyle 

Aşk mıdır seni düşüren bu hale

Yaşanmış nice aşklar dursun şöyle

Gözlerin hala bir düş ağırlıyor

Asırlık bir taş misali ağırsın

Evveli duyan,şimdiye sağırsın

Yana yakıla kim nasıl çağırsın

Gözlerin hala bir düş ağırlıyor

Boy pos çakılmış durduğun o yere

Derman ummuştur kimbilir kaç kere

Yorulmuşsa da göğüs gere gere

Gözlerin hala bir düş ağırlıyor

22:48 17.02.2004', 'Bu gün ne kadar durgunsun ey gönül Gün akşam etti güneş uğurluyor O tatlı hazza takılıp kalalı Gözlerin hala bir düş ağırlıyor Sırra kadem m...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ey-gonul-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-adem-tiras-t0ffu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başımda altın taç

Gönlüm ona muhtaç

Gözüm tok olsa da

Ruhum anneme aç

Hayatımın başı

Gözlerimin kaşı

sevdiğimden yana

Dünyada yok eşi

Cihanda bir ve tek

Bal''dır  petek petek

Gönlümde açılmış

Nadide bir çiçek', 'Başımda altın taç Gönlüm ona muhtaç Gözüm tok olsa da Ruhum anneme aç Hayatımın başı Gözlerimin kaşı sevdiğimden yana Dünyada yok eşi Cihand...', ARRAY['Türk Edebiyatı','Şiir','Adem Tıraş']::text[], 8.5, '{"poet":"Adem Tıraş","poet_slug":"adem-tiras","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/annem-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-kubilay-enginol-3f3b3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerimin rengi sevgi

Saçlarımın hüzün

Okşama sakın saçlarımı

                           üzülürsün

Göğsümde yanar aşkımın ateşi

Arar gözlerim sevgi güneşi

Gözlerime bak rengi sevgi

Saçlarımın rengi hüzün', 'Gözlerimin rengi sevgi Saçlarımın hüzün Okşama sakın saçlarımı                            üzülürsün Göğsümde yanar aşkımın ateşi Arar gözler...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ölüyor muyum? ....', 'ben-oluyor-muyum-orkun-isik-aydgl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar önce bugünün tarihinde doğmuşum

Babam kız olmadım diye içerlenmiş anama :-)) 

O,gün ağlaya ağlaya yorulmuşum

Anam melhem olmuş kanayan yarama…

Kundağım da olmamış her nedense

Yerde duran battaniye ye sarmışlar bu canı

Bir kuş ağlıyormuş bana kafeste

Çığlıklar basmış evin her yanını…

Yalancı emzik almamışım hiç ağzıma

İllaki anamın sütünü istermişim

Haram lokma inmemiş boğazıma

Evimizin en suskun sesiymişim….

Okullar açıldığında, kara önlüğüm varmış

Şöyle ütülüsünden birde arkadan pileli

Her yanımı bir korku sarmış

Yoklukta okuyamamak pek çileli….

İlk kokladığı olmuş, lavanta kokusu

Neredeyse yıllarca aramıştır lavantasını

Ya bulamazsa olmuştur hep  korkusu

Bulamamışta, takamamış hiç koluna manitasını

Meşe oynarmışım, hep dağ deniz

Meşeyi atmak için ellerimi çamura koyarmışım

Ah be çocukluğumu bir bilseniz

Elâ gözlü, kömür saçlı, yay kaşlıymışım..

Vallahi anam öyle demiş öylece kalmışım

Çiko demişler her seferinde adıma

Her sokağa çıkmamda yalınmış ayağım

Sokaklarımın, lağım izi kaldı ayaklarımda….

Büyüdük, güya adam olmadık/olduk

Benimle beraber çocukluğumda büyüdü içimde

Hep çocukluğumuzla dolduk/vurulduk

Halen yaşıyoruz çocukluğumuzu o biçimde…

Payına cenkce atılmış hep, çocukken bile

Kâh yenilmiş Kâh yenmiş, hiç ağlamamış

Sarmış sarmalamış yüreğini bu çile

Çocukken ağlamayan adam, şimdi ağlamış…

E K S E L A N S ‘ın Çocukluğu Gelir aklına.. Kaçıncı yaşandıysa şimcik…', 'Yıllar önce bugünün tarihinde doğmuşum Babam kız olmadım diye içerlenmiş anama :-))  O,gün ağlaya ağlaya yorulmuşum Anam melhem olmuş kanaya...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ben-oluyor-muyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldönümü', 'yildonumu-sema-aka-7vmmh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki bilinmezin bir araya gelmesi bu

Merhaba ile başlayan, hoşçakalla biten sohbetler

Ardından yenilen yemekler, mutlu gülümsemeler

Birbirini tanıma çabaları, hoş sohbetler

Arkadaşlık, dostluk derken kalbe atılan sevgi tohumları

Bir gece yarısı koyu mavilikler arasında kız kulesi

Hani ışıl ışıl yanıyordu karşımızda 

Ve biz yorgun ama huzurlu karşısında

Ben ise ilk kez senin kollarında

Büyülü bir geceydi yaşadığım

Sonrasında süre gelen buluşmalar

Korkulu, endişeli ama bir o kadar da zevkli

Tatlı yalanlarla bezeli heyecanlardı yaşananlar

İlk yakınlaşmalar geldi ardından

Birlikteyken yaşanan duygu dolu dakikalar

Hızla geçen doyumsuz saatler 

Buruk ayrılıklar…

Ara ara yaşanan kıskançlıklar 

Gittikçe bağlanan ben, ben bağlandıkça kaçan sen

Sevgimi, aşk mı adını koyamadığım duygular

Araya giren eski sevdalar, bitmez tükenmez ızdıraplar

Yapılanların doğrumu yanlış mı olduğu duygu karmaşası

Değer veren seven ben

Beni hiçbir zaman sevemeyen sen

Karşılıksız ama gönülden sevdim seni

İçinde ki buzdan dağları eritememiş olsam da

Bir yerim var biliyorum kalbinde

Anlamanı umut ederek beklentisiz özlem dolu

Birlikte geçen saniyelerin mutlu yaşanması dileği gönlümde

Sen başımın tacı, gönlümün sultanı

Sen güvendiğim, inandığım, yüreğine sevdalandığım

Ve bugün,

Mutluluğu bulduğum günün yıldönümü

Seni sevişimin ikinci yılı

Ben ise hala sana sevdalı, tutkulu

Nice yıllara bir tanem.....

20.02.2004', 'İki bilinmezin bir araya gelmesi bu Merhaba ile başlayan, hoşçakalla biten sohbetler Ardından yenilen yemekler, mutlu gülümsemeler Birbirini...', ARRAY['Türk Edebiyatı','Şiir','Sema Aka']::text[], 8.5, '{"poet":"Sema Aka","poet_slug":"sema-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yildonumu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düşüm Vardı', 'bir-dusum-vardi-mehmet-husnu-yakut-741pq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I

Bir düşüm vardı

Sıcak mı sıcak

Tatlı mı tatlı

Gözlerimi kapayıp,

yorganıma sığındığımda

kırmızıydı gece...

Hafiften yağmur sesi

Tatlı bir esinti,

İçimde...

Dalıyorum gecenin sessizliğine

Sokaklar bomboş,

girintili çıkıntılı

Küçük bir avlu

Duvarları yıkık dökük

Karşıda ahşaptan bir kapı

iki odalı

birinde ışık var

Sabahın üçü

Kadın bağdaş kurmuş

Kucağında dört yaşında bir çocuk

Gözleri kan kırmızı kadının

ve altın sarısı damlalar

“ağlama anne”

sadece dudaklarım kıpırdıyor

duyamıyor beni...

II

Bir düşüm vardı

Top oynarken sokakta

Eskimiş ayakkabılarım

Ayak parmaklarım isyanda

Çorabım örtemiyor

Dizlerimde renkli yamalar

Ve üç numara kesilmiş

Saçlarım...

Ama ben başka bir dünyada

Akşam dersleri bambaşka

hiç değişmeyen ders

nasihat...

“önce adam olacaksın”

tabi ki babamın sesi

dünya güllük gülistanlık

bulsan da etme

hep iyi olacaksın

hep susacaksın

tek laf gelmeyecek

konu komşudan...

Oh be bitti

III

Bir düşüm vardı

Tahta masalarda

Sığmıyor

sığdıramıyorum beynimi

kafatasımın içine...

Adalar, kıyılar, iklimler

coğrafik harita

hele suyun kaldırma kuvveti

Yetmiyor bana

kesirler, ondalık sayılar...

Ne olurdu gökyüzüne

dokunabilseydim...

IV

Bir düşüm vardı

Henüz on beşinde

Bıyıklarım yeni terlemiş

Liseli diyorlardı sokakta

Sadece adı vardı bende

Yaşam denilen sinsi arkadaşın

Paylaşmayı öğrenmiştim

Bir de yokluğu...

Ama gel gör ki

Durmuyordu kafesinde kuşum

Uçmak, hep uçmak istiyordu...

Yorulana kadar

yorulur muydu acaba...

V

Bir düşüm vardı

Fakülteliydim artık,

genç bir delikanlı

Küçük dağları ben yarattım

göğsüm ileride geziyordum

ta ki polis, kovalayana kadar

Ama ne istiyorlardı benden

Sadece halay çekmiştik ağabeylerimizle

bir de türkü söylemiştik...

Öğrenmiştim artık

kamufle edilmiş aşkları,

deşifre edilmiş sözlerle yaşamayı...

VI

Bir düşüm vardı

Ekmek tutan ellerime

dokunurken, hayatın gerçekleri...

Ve acıyan yüreğimi

hiçe sayan yalancı aşklar,

düğümlenirken boğazımda.

Bir düşüm vardı

Hala bir düşüm var...', 'I Bir düşüm vardı Sıcak mı sıcak Tatlı mı tatlı Gözlerimi kapayıp, yorganıma sığındığımda kırmızıydı gece... Hafiften yağmur sesi Tatlı bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hüsnü Yakut']::text[], 8.5, '{"poet":"Mehmet Hüsnü Yakut","poet_slug":"mehmet-husnu-yakut","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/bir-dusum-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-kubilay-enginol-rqa2k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbulun orospu kokan

Sokaklarını aradı adam

Sevdiğinden bir iz bulacağına inanmış

Yoğun nefret yağmuruna aldırmadan

Taşlara tek,tek sordu,yanıt alamadı

Haykırırdı belki ismini ama

Utandı

Anlamsız yüzlerde,her yerde

Aradı,aradı bulamadı

Umudunu yitirmiş gidiyordu

Batan güneş,alay ediyordu', 'İstanbulun orospu kokan Sokaklarını aradı adam Sevdiğinden bir iz bulacağına inanmış Yoğun nefret yağmuruna aldırmadan Taşlara tek,tek sordu...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yitik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-adem-tiras-profv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Genç yaşımda gençlik çağımda

Kalbimdeki sevgi  ağımda

Açılmamış gönül bağımda

Bil ki; gonca gonca sen varsın

Yaylaların gür pınarında 

Nazlı suların kenarında

Genç hayatımın baharında

Bil ki; çiçek çiçek sen varsın

Kelimelerde hecelerde

Kuşlar misali yücelerde

Yazın mehtaplı gecelerde

Işık ışık sen varsın

Dermanım olarak dizimde

Dilimden dökülen sözümde

Hasretten ağlayan  gözümde

Bil ki; damla damla sen varsın

Gökyüzündeki bulutlarda

Gözlerimdeki buutlarda

Hasretinle yanan odlarda

Bil ki; duman duman sen varsın

Adem Tıraş  14.05.1985  Trablusgarp

Bu şiir Şairin ''PİŞMANLIĞIN GÖZYAŞLARI'' ismli ramanından alınmıştır.Kitabın temin adresi ''Fazilet Kitabevi Ş.M. Eroğlu cad. Giritlioğlu pasajı Osmaniye', 'Genç yaşımda gençlik çağımda Kalbimdeki sevgi  ağımda Açılmamış gönül bağımda Bil ki; gonca gonca sen varsın Yaylaların gür pınarında  Nazlı...', ARRAY['Türk Edebiyatı','Şiir','Adem Tıraş']::text[], 8.5, '{"poet":"Adem Tıraş","poet_slug":"adem-tiras","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-varsin-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-sirma-mersin-wp1o8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yaz gecesinde; 

Ateşböceklerinin sesini özledim...

Sahilde el elle oturduğumuz o yerde; 

Kayan yıldızlardan fal tutup,

Çocuksu gülüşünü özledim...

Ay''la deniz raks ederken; 

Bedenlerimizin birbirine yapışık dans etmesini özledim.......

Saçlarında dağılan rüzgarı,

Gözlerinde yanan ışığı özledim....

Soğuk kış gecelerinde; 

Özlediğim yalnızca sendin....

20.02.04', 'Bir yaz gecesinde;  Ateşböceklerinin sesini özledim... Sahilde el elle oturduğumuz o yerde;  Kayan yıldızlardan fal tutup, Çocuksu gülüşünü ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozledim-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mimoza', 'mimoza-sirma-mersin-qsw0k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçmiş bahar mimozalarında! 

Yaşadığım mutluluğu anımsadığımda; 

Kalbimin her atışında, adını heceledim...

İçimden defalarca...

Geçmiş bahar mimozalarına, her baktığımda; 

Kıştan uyanmış çiceklerin arasında , 

Gülen yüzünü hatırladım! ...

Güneşsiz bir sabahın ayazında ise; 

Savurdum mimozalarımı....

20.02.04', 'Geçmiş bahar mimozalarında!  Yaşadığım mutluluğu anımsadığımda;  Kalbimin her atışında, adını heceledim... İçimden defalarca... Geçmiş bahar...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mimoza-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask Dedigin...', 'ask-dedigin-baris-guc-qyw2k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nereye çikacagi belli olmayan bir yoldur ask; 

Kader yolunda ilerledigimiz,süprizlerle dolu

Bazen bir yagmurdur ask; gözlerimizi islatan

Bazen bir günestir ask,yüregimizi isitan bazen kavuran

Kimi zaman kar gibidir ask önceleri seyretmesi güzel

Ancak sonralari hayati felç eden 

O’nun adini her andiginda yüreginin hoplamasidir ask dedigin

Ask dedigin; mantigin hükmetmemesidir akla 

Mangal gibi bir yürek olmali sevende,gözü kapali dikenli yollarda ilerlemeli

Aska dair bütün kelimeleri  tek hecede söyleyebilmeli sevdigine

Ifade edebilmeli tüm sevgisini anlatabilmeli sadece bir bakis ile

Sözlerin anlamini yitirmesidir ask,bakislarin büyüleyici etkisidir 

Teslim olmaktir ask,yüreginde hapis yatmaktir sevgilinin 

Aglarken gülmek degildir ask; gülerken aglamaya hazirlik yapmaktir.

Nedendir bilinmez bir gülücükle baslayip gözyasiyla biter hep 

Bir savas alanidir ask; kaybedeni ve kazanani hiç olmayan 

Bir yangin yeridir ask; söndüremeden küle çeviren 

Ask dedigin içmeden sarhos etmeli insani

Bilmedigi sarkilar söyletmeli adama 

Öyle çok sevmeli ki,seveni sair yapabilmeli ask dedigin..................

18.02.2004 sda ozlt   MSN:      [email protected]', 'Nereye çikacagi belli olmayan bir yoldur ask;  Kader yolunda ilerledigimiz,süprizlerle dolu Bazen bir yagmurdur ask; gözlerimizi islatan Baz...', ARRAY['Türk Edebiyatı','Şiir','Barış Güç']::text[], 8.5, '{"poet":"Barış Güç","poet_slug":"baris-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-dedigin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam İki Sarmaşık Gülü', 'sevdam-i-ki-sarmasik-gulu-gulay-yildiz-5f9l9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki sarmaşık gülü vücuduma dolanan

Dikenleri; adımları

Uçları garip değnek anlayacağın

Büyütmek istesen, sevgin güneş olsa

Büyüdükçe adımlayan; 

Adımladıkça acıtan sevda

Gözyaşlarımla daha da büyüyen

Büyüdükçe kana boğan yara', 'İki sarmaşık gülü vücuduma dolanan Dikenleri; adımları Uçları garip değnek anlayacağın Büyütmek istesen, sevgin güneş olsa Büyüdükçe adımlay...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevdam-iki-sarmasik-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamla Sevişmek,', 'yasamla-sevismek-hikmet-feridun-demir-wl0sj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmeyenler,

Sevilmediler,

Korkaklar,

Korkuttular,

Aceleleri vardı,

Çabuk gittiler....

Sevenler, 

Sevildiler...

Yaşamla,

Seviştiler...

10.10.2003

Köln, Ren nehri..

Almanya', 'Sevmeyenler, Sevilmediler, Korkaklar, Korkuttular, Aceleleri vardı, Çabuk gittiler.... Sevenler,  Sevildiler... Yaşamla, Seviştiler... 10.10...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasamla-sevismek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular', 'duygular-sirma-mersin-f2xuk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sözcüklerin sessizliğe çekildiği anda; 

Kendimle konuşamadığım duygularımı bile, paylaştım seninle...

Sense! Sırların koynunda; ruhumla değil, suskunluğunla paylaştın duygularını...

Duygularım duygularına tercüman olamamışken; seni seviyorum demenin...

Bir anlamı olur mu? 

Söylesene....

19.02.04', 'Sözcüklerin sessizliğe çekildiği anda;  Kendimle konuşamadığım duygularımı bile, paylaştım seninle... Sense! Sırların koynunda; ruhumla deği...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/duygular-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen bilirsin', 'sen-bilirsin-kubilay-enginol-ek06q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkımızı zaman bırakalım

Böylece gözyaşların dinsin

Biliyorum şimdi buruk bir sesle

Sen bilirsin diyeceksin

Gözyaşların akacak belki

Aşkını bile silecek inanki

Limanda kalmış gibi kalacağım geride

Sen gemiye binip gideceksin

Kırıntılarını verirsin belki kuşlara

Kimbilir bana benzeterek

Anılar gözünde canlanacak

Çoğunu anımsayacaksın gülümseyerek', 'Aşkımızı zaman bırakalım Böylece gözyaşların dinsin Biliyorum şimdi buruk bir sesle Sen bilirsin diyeceksin Gözyaşların akacak belki Aşkını ...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-bilirsin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-sirma-mersin-7kwfc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat!

Aynı hızla devam ediyor...

Ama; hep yarım, hep eksik...

Senin gidişinden bu yana....

Kahredici gerçek! 

Bu yürek; sensizliğe alışamamışken...

Sen! 

Mutlu bi hayatın içinde; 

Bi başka yürekle,

Sevginin en güzelini yaşarken.

Ben! 

Ayrılamadım hatıralardan...

19.2.04', 'Hayat! Aynı hızla devam ediyor... Ama; hep yarım, hep eksik... Senin gidişinden bu yana.... Kahredici gerçek!  Bu yürek; sensizliğe alışamam...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dicle', 'dicle-kubilay-enginol-pscvs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinin pırıltısı bana rehber olur

Uzun kıvrak yollarda

Billur sesin okşar saçımı

Varlığın unutturur yanlızlığımı

Yıldızlı gecelerde harran ovasında

Gözlerine benzeyen yıldızı arayacağım

Diclenin akışında,sesini anacağım

Ağrı dağının eteklerine bakıp

Güzelliğini bulacağım

Vuslata kavuşamamanın üzüntüsüyle

Yine karşında olacağım', 'Gözlerinin pırıltısı bana rehber olur Uzun kıvrak yollarda Billur sesin okşar saçımı Varlığın unutturur yanlızlığımı Yıldızlı gecelerde harr...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dicle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesimde ki Hüznü Soracaksanız?', 'sesimde-ki-huznu-soracaksaniz-mine-ozdemirtas-mdxg2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni sual eden olursa,

Ben hala  Çocuğum.

Bir kere,

Yüzümdeki çizgiler bana ait değil.

Sözde onları, yıllardan ödünç almışım.

Ben, kimseden hiçbir şey almadım.

Vallahi yalan.

İftira ettikleri için; 

Nefret ediyorum aynalardan.

Evet,..... bu Afacan; 

Cicozda, mızıkır her zaman.

Ebe de/ sobe de inkarı........ olabilir.

Zaten, şakacı yanını alem bilir.

Evet......, halıda ki çamurlu ayak izleri bana ait.

Aşureye  tuzu da, ben döktüm.

Tamam,... izinsiz  kapı çalmış ta olabilirim.

Ama,........ Bu hırs,bu öfke niye? 

Ne yani? 

Kapıyı açanı......Zorlamı öptüm? 

Beni sual eden olursa,

Ben hala, çocuğum. / Bunu; zaten söyledim.

Büyümek için /  özenmedim  /Hiç heves etmedim.

Ben........    kreşe de gitmedim.

İşte bu yüzdendir ki,

P a y l a ş m a y ı........../ Ö ğ r e n m e d i m.

Ama beni değil de,

Sesimde ki hüznü soracaksanız? 

O zaman......... Tamam! / Tamam,

İtiraf ediyorum ki,........... /.......

O  hüzün bana; 

Çoktan  büyümüş bir kadına ait olan,

Ve,/ Bir asker postalının içinde,

Susuzluktan.....solmaya yüz tutan

Kırılgan, Kır çiçeklerinden..........   A r m a ğ a n.

20/02/2004  istanbul', 'Beni sual eden olursa, Ben hala  Çocuğum. Bir kere, Yüzümdeki çizgiler bana ait değil. Sözde onları, yıllardan ödünç almışım. Ben, kimseden ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sesimde-ki-huznu-soracaksaniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık 2', 'yalnizlik-2-umran-er-oe979', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlık çiçeğin susuz 

İnsanın mutsuz olmasıdır

Yalnızlık bulutun yağmursuz

İnsanın sevgisiz kalmasıdır

Yahut çöldeki bir kaktüs

Dağdaki kırçiçeği

Yalnız tek başına

ve sessiz

Ne acı bir hayattır  ki

Kaktüs dikenleşmiş

Kır çiçeği sertleşmiş

                YALNIZLIKTAN', 'Yalnızlık çiçeğin susuz  İnsanın mutsuz olmasıdır Yalnızlık bulutun yağmursuz İnsanın sevgisiz kalmasıdır Yahut çöldeki bir kaktüs Dağdaki k...', ARRAY['Türk Edebiyatı','Şiir','Ümran Er']::text[], 8.5, '{"poet":"Ümran Er","poet_slug":"umran-er","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlik-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Hücresinde Duyuyorum Seni Yüreğinin…!', 'her-hucresinde-duyuyorum-seni-yureginin-muammer-celik-9uyjy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duymuyor muyum sanıyorsun 

feryadını, ah-u figanını 

yattığım hücreden

duvarlara vurduğumu başımı

yoluk yoluk yolduğumu bağrımı… 

Bilmiyor muyum saniyorsun

yüreğinin kabardığını

göğsünden ok gibi fırladığını

okudukca, içimi delen şiirlerini

kendimden geçip geçip bayıldığımı 

sen karşıma dikilince ayıldığımı…

Bilmiyor musun peki 

beni yüreğine hapsettiğini

hapsettiğin hücrelerinden 

hiç çıkamadığımı, eyyy sevgili…

BirDeli

20.02.2004

(Sude Son dostumun ”Duy Beni Sevgili” isimli Şiirine yazdığım yorumdan çıkarım yaptığım bir nazire’dir)', 'Duymuyor muyum sanıyorsun  feryadını, ah-u figanını  yattığım hücreden duvarlara vurduğumu başımı yoluk yoluk yolduğumu bağrımı…  Bilmiyor m...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/her-hucresinde-duyuyorum-seni-yureginin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Kalmanı İstemişim', 'i-cimde-kalmani-i-stemisim-gozdecan-bezirci-zn3ok', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde kalmanı istemişim...

Yolda yürürken omuzundan düşen,

Farkına bile varamadığın yağmur damlası olmamak için.

Benimde bilmediğim bir zamanda bir dilek tutmuşum

Benden hiç gitme diye.

Bir gece olmuş, çatılara bakmışız, bağırmışız

Utanmışım...

Gözlerine bakmışım, ellerime bile kazınmış gözlerin,

Kokun kahveler olmuş,

Dumanlar o uzun konuşmalarımızın şeklini almış,

Sesimizle  yanmışız, hem de nasıl...

Geceler oluyor,

Sensiz uzun geceler,

Aklıma geliyorsun, adını sessizce fısıldıyorum...

Ağaçlarda, kelebeklerde, parmak uçlarımda sen varsın.

Bizim üstümüzde parmak uçlarımda yürüdüm ben,

Sen anlayamadan

Bizi nasıl yaşadım bilemeden

Senin içimde kalmanı istedim

İlk geldiğin gün bana

Mucizeler de geldi seninle, nehirler geldi, agaçlar geldi periler geldi...

Galiba kavuşamayan o iki nehri çok sevdim ben

Seni içime gitme diye aldım

Bencillik burda başladı...', 'İçimde kalmanı istemişim... Yolda yürürken omuzundan düşen, Farkına bile varamadığın yağmur damlası olmamak için. Benimde bilmediğim bir zam...', ARRAY['Türk Edebiyatı','Şiir','Gözdecan Bezirci']::text[], 8.5, '{"poet":"Gözdecan Bezirci","poet_slug":"gozdecan-bezirci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/icimde-kalmani-istemisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemek', 'ozlemek-yakup-cakir-h2e88', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özlemek	 

Özlemek nedir bilir misin sen? 

Çöl sıcağında suyu arzulamak gibi, 

Özlemek nedir bilir misin sen? 

Süt bebeğinin feryadındaki süt içme arzusu gibi.

Özlemek nedir bilir misin sen? 

Çiçeğin, suya ve güneşe olan arzusu gibi.

Özlemek nedir bilir misin sen? 

Seni böyle arzuladığımı, böyle özlediğimi bilir misin.? 

Sendeki özlemlerin o kadar çokki,

gökkuşağındaki renkleri düşün anlarsın.

Her geçen gün, saat ve saniye, özlemlerim daha da artmaktadır.

Yokuluğun dayanılmaz bir hal alırken,

Yüreğim için için yanmaktadır.

Belki bir köroğlu, karacaoğlan ve ferhat gibi destanlar yazamam

Ama bu yürekle ebediyen seni sevebilir ve sana bağlı kalabilirim.

Seninle ölüme el ele gidebilirim. 

Ben seninle nefes almayı, seninle uyumayı, seninle uyanmayı istiyorum.

Seni çok değil, yüreğime sığmayan hislerle seviyorum.

Seni özlüyorum bir tanem.

Özlemek nedir bilir misin sen? 

09.01.2003

saat:11:55', 'Özlemek	  Özlemek nedir bilir misin sen?  Çöl sıcağında suyu arzulamak gibi,  Özlemek nedir bilir misin sen?  Süt bebeğinin feryadındaki süt...', ARRAY['Türk Edebiyatı','Şiir','Yakup Çakır']::text[], 8.5, '{"poet":"Yakup Çakır","poet_slug":"yakup-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ozlemek-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın..', 'sen-varsin-yakup-cakir-xpowd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEN VARSIN.....

Aylardan OCAK, ve soğuk bir PAZAR gecesinde,

Cam kenarında oturmuş, yağan yağmurun damla damla cama vurmasını seyrediyorum.

Herzaman olduğu gibi, yine seni düşünüyorum.

Papatya falını, yağmur damlalarıyla açıyorum.

Seviyor sevmiyor, seviyor sevmiyor diye sayıyorum.Ne çareki falın sonunu getiremiyorum.

Zaman ilerledikçe, gözlerim kısılıp ufaldığı anda,

Sen düşlerimden çıkıp, rüyalarıma girmeye başlıyorsun.

O an içimi bir titreme kaplıyor. Belki üşümekten, belkide seni özlemekten.

Anlayamıyorum neden, yarı uyuyor olmaktan.

Ama bildiğim birşey var. 

Artık seni düşlerime, uykularıma ve özlemlerime ekledim.

Her saniye sesini duymayı istemek,

Konuşmaya başladığında ise duyguları ifade edememek.

Söylenecek çok söz varken, onları söyleyememek.

Söyleyemediklerimi kağıda dökmek istiyorum.

Kelem, yüreğimin klavuzu olmuş, yürek hissediyor, kalemde yazmaya başlıyor.

Özlenen, düşlenen, düşünülen biri var.

İçimde bir ürperti, bir kıpırtı var.

Aylar sonra yaşanan bir mutluluk var.

Seninle varolmak ve seninle yaşamak var.

Yaşıyorsam artık, bir sebebim ve o sebebin bir anlamı var.

SEN VARSIN, YANLIZ SEN.

06.01.2003

Saat: 01.55', 'SEN VARSIN..... Aylardan OCAK, ve soğuk bir PAZAR gecesinde, Cam kenarında oturmuş, yağan yağmurun damla damla cama vurmasını seyrediyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Yakup Çakır']::text[], 8.5, '{"poet":"Yakup Çakır","poet_slug":"yakup-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-varsin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmezdi Diyorduk...', 'bitmezdi-diyorduk-yakup-cakir-6jalh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİTMEZDİ DİYORDUK...

Yorgun, mutsuz, umutsuz bir dönemde, aniden girmiştin hayatıma.

Yıllar sonra, ilk defa içimin coştuğunu, 

hayata zevkle ve umutla baktığımı hissettim.

Baharın gelişiyle, kış uykusundan uyanan çiçekler gibiydim.

Artık benim için, kış hiç gelmeyecek diyordum.

Seninleyken güneş bir başka güzel doğuyordu.

Seni saatlerde değil, saniyelerde yaşıyordum,

Ağlamayı bile unutmuştum artık, Ağladığım o güne kadar.

Sana borçluydum, yaşadığım tarifsiz hisleri ve güzellikleri 

Herşeyimi sana borçluydum.

Oysa Tanrıdan çok şey istememiştim, ama seninle çok şeyi yaşamıştım.

Yaşadıklarımızı hakediyorduk en ufak noktasına kadar, hakkımızdıda zaten.

Zaman bizim zamanımız, sevgi bizim sevgimizdi.

Bizim olmayan evrenin, mutluluk diyarının tek sahibiydik.

Biz bunları koruyamadık, sahiplenemedik. oysa zor kazanmıştık.

Ağlamayacağız diyorduk, ağlıyorum artık

Tükenmez diyorduk, tükendi,

Bitmez diyorduk, bitti.

Bitmeyen, hala bakışlarındaki o masumiyet.

Ve senden sonra yaşanan ızdırap.

22.04.2003

Salı   16.00', 'BİTMEZDİ DİYORDUK... Yorgun, mutsuz, umutsuz bir dönemde, aniden girmiştin hayatıma. Yıllar sonra, ilk defa içimin coştuğunu,  hayata zevkle...', ARRAY['Türk Edebiyatı','Şiir','Yakup Çakır']::text[], 8.5, '{"poet":"Yakup Çakır","poet_slug":"yakup-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bitmezdi-diyorduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrenci Çilesi', 'ogrenci-cilesi-engin-ataman-th7e0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ezildim ezildim yapıştım yere,

Kahroldum belkide binlerce kere.

Düşündüm yazmaktan yok başka çare,

Parasızlık,ızdırabı gurbetin

Tesellisi öyle zor ki bu derdin.

Kalem, yazmam diye isyan ediyor

Kâğıt,yazma diye kaçıp gidiyor.

Titrek parmaklarım,yazamam diyor.

Parasızlık,ızdırabı gurbetin,

Tesellisi öyle zor ki bu derdin.

Kahrolursun ''''para gönderin''''derken.

Izdırap duyarsın alıp harcarken.

Zaten birşey kalmaz,bunca borç varken.

Parasızlık,ızdırabı gurbetin

Tesellisi öyle zor ki bu derdin.

Çocuk değil artık ''''yirmi''''sindesin

Bu çileyi çeken yalnız sen misin? 

''''BABA PARA GÖNDER''''dememelisin.

Parasızlık ızdırabı gurbetin,

Tesellisi öyle zor ki bu derdin.

                                 1984-Konya.', 'Ezildim ezildim yapıştım yere, Kahroldum belkide binlerce kere. Düşündüm yazmaktan yok başka çare, Parasızlık,ızdırabı gurbetin Tesellisi öy...', ARRAY['Türk Edebiyatı','Şiir','Engin Ataman']::text[], 8.5, '{"poet":"Engin Ataman","poet_slug":"engin-ataman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ogrenci-cilesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tavsiye', 'tavsiye-engin-ataman-itzux', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', ',Başını omzuna koyamıyorsan

Yüreği ne diyor duyamıyorsan

Bu benim erkeğim diyemiyorsan

Bu ilşki sevgi değil,bitmeli

Bir daha yanına hiç gitmemeli.

Gel demeden sana gelemiyorsa

Neler çektiğini bilemiyorsa

Devamlı yanında kalamıyorsa

Böyle sevgi olmaz olsun demeli.

Bir daha yanına hiç gitmemeli

Bire bir ruhuna inemiyorsa

Seni kazanmayı denemiyorsa

Ve senin dünyanı tanımıyorsa

Herkes dünyasında kalsın demeli

Bir daha yanına hiç gitmemeli.

Oduncuya altın,değersiz gelir.

Onun kıymetini sarraflar bilir.

Değerli varlıklar zor edinilir.

Kolay gelen,kolay gider bilmeli

Bir daha yanına hiç gitmemeli.

                             03-05-2003 Ankara', ',Başını omzuna koyamıyorsan Yüreği ne diyor duyamıyorsan Bu benim erkeğim diyemiyorsan Bu ilşki sevgi değil,bitmeli Bir daha yanına hiç gitm...', ARRAY['Türk Edebiyatı','Şiir','Engin Ataman']::text[], 8.5, '{"poet":"Engin Ataman","poet_slug":"engin-ataman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tavsiye-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gitme', 'sen-gitme-tulay-sustam-99cua', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git... Hadi git... 

Nasıl olsa bekleyenin var.

Arkana bakmadan hızlı adımlarla git...

Elveda deme, hoşçakal deme

Ne istersen onu söyle...

Gidipte dönmeyeceğinden korkuyorum

Daha burdasın, birazdan gideceksin.

Seni; şimdiden özlüyorum

Kitapların, kazakların gitsin

Sen gitme, gitme...

Ben sensiz yapamam biliyorsun.

Ben senin yanındayken güzelim

Seninle aynalar da bir başkayım

Ne olur gitme, gitme...

Vakit geldi, birazdan gideceksin

Yine kahrolası kahırları yazacağım

Yalnızlığıma sarılıp bir başıma yatacağım

Uykuyu kendime zehir edip, kâbuslarla uyanacağım

Kahretsin... Sensiz bir güne daha karışacağım

Herkes gitsin hayatımdan ama sen gitme, gitme...', 'Git... Hadi git...  Nasıl olsa bekleyenin var. Arkana bakmadan hızlı adımlarla git... Elveda deme, hoşçakal deme Ne istersen onu söyle... Gi...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyamola', 'heyamola-kubilay-enginol-6xufl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne hayallerle çıkıyordu maviliklere

Heyamola sesleri uğurladı onu

Yırtarken çarşafları teknenin burnu

O sigarasını içiyordu

Torlara savurdu dumanını keyiflice

Oğluna alacağı bisikleti

Karısına alacağı entariyi gördü

Bir an ağların üzerinde

Denizdi bu 

Hem iyi hem kalleş

Gözlerinde batıyordu şimdi güneş

Pinezlerle savaşarak aldılar ekmeklerini

Bereket,ısıttı yüreklerini

Fırtına patladı birden

Çığlıklar,haykırışlar geldi derinden

Güneş doğarken yeni bir güne

Hayalleri de aydınlattı,suyun yüzünde', 'Ne hayallerle çıkıyordu maviliklere Heyamola sesleri uğurladı onu Yırtarken çarşafları teknenin burnu O sigarasını içiyordu Torlara savurdu ...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/heyamola-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-tulay-sustam-o7u25', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'l.

Sen özgürlük nedir bilir misin? 

Özgürlüğü yaşatmadın ki bana nereden bileceksin...

Bence özgürlük! ...

Bir dalga gibidir...

Ne zaman karaya vuracağı belli olmayan

Bir kibrit gibidir...

Islandığında bir daha hiç yanmayan

Bir ateş gibidir...

Ne zaman yakıp, kül edeceği belli olmayan

Bir dost gibidir...

Ne zaman hayatınıza girip, ne zaman çıkacağı belli olmayan

Ve özgürlük dostum; 

Başkasının özgürlüğünü kısıtlamadan, 

Özgürce yaşamayı bilenindir...

II.

Kafese kapatılmış bir kuş gibiyim

Artık bu kafesten kurtulmak, özgürlüğüme kavuşmak

Ve eskisi gibi uçmak istiyorum...

Ve beni bu kafesten kurtarmanı bekliyorum.

Ama sen özgürlüğü bana çok gördün

Artık kafesin kapısını açıp beni azat etmesen de olur

Nasıl olsa uzun zaman oldu bu kafeste kalalı

Alıştım artık böyle yaşamaya...

Aslında benim yerimde sen olmalıydın ya neyse...

Ben artık bu kafesten çıkmak istemiyorum

Görüyorum ki; 

Dışarısı yaşadığım kafesten daha kötü

Herkesin özgürlüğü kısıtlanmış durumda

Artık kafesten çıkmak istemiyorum

Zaten uçmayı da unutalı çok oldu

Mavi gökyüzü yabancı bana...

Ben artık uçamam

Beni kafese kapatarak kanatlarımı da kırmış oldun

Daha ben nasıl uçabilirim? 

Bana mavi gökyüzünü geri ver...

Bana kanatlarımı geri ver...

Benden almış olduğun özgürlüğümü geri ver...

Benim tek istediğim; 

Başkasının özgürlüğünü kısıtlamadan özgürce yaşamak...', 'l. Sen özgürlük nedir bilir misin?  Özgürlüğü yaşatmadın ki bana nereden bileceksin... Bence özgürlük! ... Bir dalga gibidir... Ne zaman kar...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ozgurluk-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmeyecek ti', 'gelmeyecek-ti-erol-sen-gzzab', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bostancı sahili kara rağmen yine dolu

Sevgililer camları buharlanmış  araçlarda

Kimisi sarılmış sıkıca

Kaçmasın sevdiği diye

Kimisi adalara bakıyor sevdiğinin omuzunda

Aşk nağmeleri kulaklarında

Kasette sevgi sözleri çalıyor umarsızca

Belki yarın ayrılacak sevdiğinden

Birisi öpüyor şehvetiyle sevdiğini

Sevdiği sarılmış karşılık veriyor

Denize aşık sevenler de var güne

Sadece deli mavi ye bakarken gözler

Ben röntgenci değilim millet

Zincirlerimi takmış Pazar günü 

Komşumun aracını teslime gidiyoruz servise

Bunlar düşünceme gözlerime takılanlar

Bir siyah jip yanaşıyor sahile

İçinde sadece bir bayan var

Kontak kapatıp duruyor denize

Uzaklara bakıyor düşünceli

Aracından çıkarak sahile yöneldi

Kimbilir neler var aklında

Ürkek gözlerle diğer araçlara baktı

Belki bir tanıdık aradı gözleri

Yoktu gelmeyecek dedi belki de

Tekrar denize döndü ne düşündüyse

Başını öne eğdi sessizce, çantasına attı elini

Bir sigara çıkardı ve yaktı kendince

İki duman dan sonra yarılamıştı 

Belli dertliydi düşüncelerdey di

Kafasını salladı kendince ufka

Belki de dank etti bir şey

Arabasına döndü aniden

Cep telefonuyla birini aradı

Uzun uzun konuştu gülüyordu

Belki de mutlu olmuştu haberlerle

Çalıştırdı jipini sakince geri geri geldi

Tekrar diğer araçlara baktı

Kimbilir neler hatırladı seven gönlüne

Bastı gaza gözden kayboldu…

20.02.2004', 'Bostancı sahili kara rağmen yine dolu Sevgililer camları buharlanmış  araçlarda Kimisi sarılmış sıkıca Kaçmasın sevdiği diye Kimisi adalara ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gelmeyecek-ti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıdık', 'tanidik-cigdem-bir-genc-ckjrt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tanıdık geliyor yüzün bana

Kirpiklerinde takılıp  kalmış kelebekler  bir yerlerden aşina

Zamanın seyri seferlerinde   yitirdiğim

Eski dostum

çocukluğum.....', 'Tanıdık geliyor yüzün bana Kirpiklerinde takılıp  kalmış kelebekler  bir yerlerden aşina Zamanın seyri seferlerinde   yitirdiğim Eski dostum...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tanidik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilki Hasretinden', 'bilki-hasretinden-hifzi-ozbekmez-yfovg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün bu vücudum heder olursa

Bilki hasretinden olur sevdiğim

Gecem gündüzümde keder olursa

Bilki hasretinden olur sevdiğim

Dünya alem bana delidir derse

Aldığım nefesler bir gün biterse

Canım bedenimden uçup giderse

Bilki hasretinden olur sevdiğim

Latifin konuşan dilleri susar

Dünyanın dertleri omzuna basar

Bir gün bu garipte hayata küser

Bilki hasretinden olur sevdiğim

2003', 'Bir gün bu vücudum heder olursa Bilki hasretinden olur sevdiğim Gecem gündüzümde keder olursa Bilki hasretinden olur sevdiğim Dünya alem ban...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilki-hasretinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilerdim', 'dilerdim-hifzi-ozbekmez-2bxx1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir dakika bile ayrılmayalım

Hasretle özlemle hiç yanmayalım

Sımsıkı sarılıp öyle kalalım

Dilerdim Allahtan bunu dilerdim

Senin kollarında uyanmayayım

Hasret bal olsa da ben almayayım

Sensiz bir dünyada ben olmayayım

Dilerdim Allahtan bunu dilerdim

Senden başkasına yanmasın özüm

Senin gül sinende kapansın gözüm

Hem ilk göz ağrımsın hem de son sözüm

Dilerdim Allahtan bunu dilerdim

Latifim kapında kölen olsaydım

Senin kollarında esir kalsaydım

Yalnız senden gülüm murat alsaydım

Dilerdim Allahtan bunu dilerdim

2003', 'Bir dakika bile ayrılmayalım Hasretle özlemle hiç yanmayalım Sımsıkı sarılıp öyle kalalım Dilerdim Allahtan bunu dilerdim Senin kollarında u...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dilerdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paha Biçemem', 'paha-bicemem-hifzi-ozbekmez-g36ki', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlümde hasretin günlerdir bitmez

Hayalin gözümden bir anda gitmez

Ruhumu satsam beş para etmez

Aşkına pahalar biçemem canım

Diyorlar ki bana güzele kanma

Bu özlem bir günde bitecek sanma

Ellerinden zehir içerim amma

Başkasından su da içemem canım

Sevdayın yüzünden çekerim çile

Bülbülde aşıktı bir gonca güle

İster hayatımdan vaz geçsem bile

O gözlerinden vaz geçemem canım

Latifi söylüyor derdi derinde

Senin yerin gönlün orta yerinde

Adın bir hecedir her an dilimde

Kendime yeni yar seçemem canım

2003', 'Gönlümde hasretin günlerdir bitmez Hayalin gözümden bir anda gitmez Ruhumu satsam beş para etmez Aşkına pahalar biçemem canım Diyorlar ki ba...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/paha-bicemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkdördüncü Kapı', 'kirkdorduncu-kapi-yildiz-yildiz-okqsm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırküç dönüşsüz kapı geçtim,

Kırkdördüncü kapının önündeyim dim dik ayakta

Kapı çetin, her daim inatta

Aklım karışık gönlüm merakta

Ruhum çoktan eridi ırmak olmuş akmakta

Bulursa küçük meyiller  kapı ardına sızmakta

Ayan olmuş çoğu, gizler tuzakta

Yüreğim pır pır,  bedenim sakin

Duygularım aklı vurmakta', 'Kırküç dönüşsüz kapı geçtim, Kırkdördüncü kapının önündeyim dim dik ayakta Kapı çetin, her daim inatta Aklım karışık gönlüm merakta Ruhum ço...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kirkdorduncu-kapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-oguzkan-bolukbasi-tyv50', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yanar ışıkları ulaşılmaz kentlerin gözlerimden uzakta

karanlık gecelerin umuda yolculuğudur hasret

yokluğun getirir içinden çıkılmaz sevda masallarını

gökten bir elma düşse de gönüllerde bölüşsek', 'yanar ışıkları ulaşılmaz kentlerin gözlerimden uzakta karanlık gecelerin umuda yolculuğudur hasret yokluğun getirir içinden çıkılmaz sevda m...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dilek-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-oguz-altun-5478b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu sefer

daha bir hızlı çarpıyor

tipili, karlı

bildiği dönüş

yolunda

tril tril titreyen kalbi

yıkılmış köprü başında

once aşağı koşturuyor

sonra dere yukarı

acaba? 

bir hamle! 

minik parmakları

sızım sızım sızlıyor

yırtık burunlu pabucu 

değer değmez suya

anlıyor

çelik gibi soğuk

bi o kadar da derin

           karşısını göremediği nehir

iğne iğne batıyor

yüzüne tipen kar

soluğu buhar bile olmuyor

göz gözü

kulak kulağı ve de hiçbir uzuv

görmüyor

duymuyor

	dokunmuyor...

tipen kar değil

tipmeyen ruhlarımızıdır

çatlayan, kuruyan, buruşan elleri ile

göğsüne bastırdığı karnesi kadar

koruyamadığımız

ve de

cinayetine seyirci kaldığımız...

Vah Atalay bebecik!', 'bu sefer daha bir hızlı çarpıyor tipili, karlı bildiği dönüş yolunda tril tril titreyen kalbi yıkılmış köprü başında once aşağı koşturuyor s...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Altun']::text[], 8.5, '{"poet":"Oğuz Altun","poet_slug":"oguz-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/agit-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trafik Işığındaki Çocuk', 'trafik-isigindaki-cocuk-oguz-altun-qw6yp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'lan bu kaç para? 

dedim,

mıncıklanmaktan yamulmuş,

kirlenmiş mendili tutan	

	buruşuk paket kağıdı misali

			çizgili 

	demir örselemiş

			 nasırlı

				ellerine bakarken

	asfaltın isi 

		yüzünün derisi olmuş

				ihtiyar çocuğun…

ne verirsen amca? ! 

dedi.

bunun bir fiyatı yok mu 

diyecek oldum...

madenci beyazı gözünün akı

	“bedelidir 

	  sattığım geleceğimin, 

	  yaşanmamışlığı çocukluğumun”

diyiverdi.', 'lan bu kaç para?  dedim, mıncıklanmaktan yamulmuş, kirlenmiş mendili tutan	 	buruşuk paket kağıdı misali 			çizgili  	demir örselemiş 			 na...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Altun']::text[], 8.5, '{"poet":"Oğuz Altun","poet_slug":"oguz-altun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/trafik-isigindaki-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-necmi-unsal-12vcq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben

Biz''in   içinde

Biz   benim   içimde

Yalnız   tek   bir   biçimde

Ben bir sevda eri

Ben

Kah cennete gül atan

Kah cehennemi yıkıp çıkan

Ben  dünyaya çelme takan

Ben  adem oğlundan biri

Ben

Ölümle kolkola

Canlarla çıkan yola

Huzurda veren mola

Ben  ecelle  yaşayan diri

Ben

Beni kendinde soran

Aklını varlığa yoran

Çileye dimdik duran

Benim baş tacı eden bir''i



19.02.2004 Danimarka-Køge', 'Ben Biz''in   içinde Biz   benim   içimde Yalnız   tek   bir   biçimde Ben bir sevda eri Ben Kah cennete gül atan Kah cehennemi yıkıp çıkan B...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garipler', 'garipler-arthur-rimbaud-0uess', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece soğuk, kar serpiyor

Fırıncı ekmek yapıyor,

     Beş küçük çocuk

Bakıyorlar somunlara,

Yazık değil mi bunlara

     Donları delik! 

Ve fırıncının kolları

Çeviriyor somunları

     Harlı fırında.

Somunların çıtırtısı,

Fırıncının zevzek sesi

     Kulaklarında.

Büzülmüşler o daracık

Ana göğsü gibi sıcak

     Delik önünde.

Ekmek, iftar sofrasının

Çörekleri gibi, bakın

     Çıkıyor işte.

Delikten yaşam tütüyor

Böcekler ile ötüyor

     Kızaran ekmek

Çarpıyor, nasıl iştahla

Yırtık giysiler altında

     Beş çocuk yürek.

Toplanmış kuşluk vaktinde,

Kırağı, çiyler içinde

     Yoksul İsalar.

Küçük delikte yüzleri,

Ekmeklerde aç gözleri

     Ne söylüyorlar? 

Büzülmüşler, bu alaca

Tan vaktinde, budalaca

     Dualar kime? 

Yırtık donlar patlıyor

Bağırmaktan. Savruluyor

     Gömlekleri kış yelinde.

(Fransızcadan çeviren:Erdoğan Alkan)', 'Gece soğuk, kar serpiyor Fırıncı ekmek yapıyor,      Beş küçük çocuk Bakıyorlar somunlara, Yazık değil mi bunlara      Donları delik!  Ve fı...', ARRAY['Türk Edebiyatı','Şiir','Arthur Rimbaud']::text[], 8.5, '{"poet":"Arthur Rimbaud","poet_slug":"arthur-rimbaud","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/garipler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın Adamı', 'yangin-adami-hikmet-feridun-demir-341oe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yangın adamıyım, 

Alevimi göremezsin.

Yandığımı göremezsin,

Külümü hic göremezsin.

Ben,

bir yangın Adamıyım,

Sakın haa....

Dokunma, 

sen de yanarsın.

Alevın görünmez, 

yandığın görünmez, 

Külün hic görünmez...

22.07.2000

Köln, Almanya', 'Yangın adamıyım,  Alevimi göremezsin. Yandığımı göremezsin, Külümü hic göremezsin. Ben, bir yangın Adamıyım, Sakın haa.... Dokunma,  sen de ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yangin-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üfleme', 'ufleme-dogan-ulkekul-772q4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Rüzgarsız yelkenlerle geldim sana 

Taaa yıllar once… ''

Üfleme 

Üfleme artık o küllenmiş mangalı 

O sönmeye yüz tutmuş korlar 

Bırak eriyip gitsin 

Yerinde kalsın 

O ne varsa elimizde olanlar 

Üfleme ne olursun 

O unutulmuş günler 

Bırak yerinde dursun 

Belki yorgun gözlerden 

Akıp giden bir anı yağmurudur onlar 

Belki yarım kalmış güftesi 

O gençlik şarkılarının 

Belki de sönmeyen o sokak lambaları 

O gözlerden gitmeyen denizler 

O denizlerin yorgun martıları 

Beyaz çiçekler açmış dalgacıklar 

Bırak yerinde kalsın üfleme 

Sen de kal benimle 

Ellerini tutmak istediğimde 

Zaman eriyen bir kar gibi 

Akıp gitsin isterse 

Ama Üfleme 

Bir gece lambası gibi bakma 

O yarım kalmış günlere 

Yalvarıp 

Zamana dur diyemem 

Çekip getiremem eski günleri 

Bir uçurtma ipiyle 

Güneş doğmadan gitmişse zaman zaman 

Kusur bende mi 

Bırak kaybolup gitsin

Kaldırımlardan ayak sesleri 

Üfleme

Yakma o mangalı yeniden 

Ateş zaten 

Hep senin gözlerindeydi 

Unuttun mu 

Bırak yerli yerinde kalsın herşey 

O bir kaç söz 

O küllenmiş ateş 

O hiç bitmeyecek sevgi

O yara 

Bırak bende kalsın 

O herşeye bedel kumral saçların 

Hatıran 

Yorgun gözlerime yapışmış 

O güzel gözlerin 

Ellerime kenetlenmiş ellerin 

Yastığımın yanıbaşındaki yerin 

Bırak herşey öyle kalsın

1994', '''Rüzgarsız yelkenlerle geldim sana  Taaa yıllar once… '' Üfleme  Üfleme artık o küllenmiş mangalı  O sönmeye yüz tutmuş korlar  Bırak eriyip ...', ARRAY['Türk Edebiyatı','Şiir','Doğan Ülkekul']::text[], 8.5, '{"poet":"Doğan Ülkekul","poet_slug":"dogan-ulkekul","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ufleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soyunsun,', 'soyunsun-ali-osman-yilmaz-a4ga7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soyunsun,

Gözlerinin maviliğinde,

Ve akşam aydınlığında.

Soyunsun bütün endamıyla,

Çıplak / Arzularının utancıyla,

Giysin tutkuların elbisesini,

Harman olalım,sarmaş dolaş,

Karışsın kokusu sevişmelerimizin,

Tek bir ten / tek bir beden,

 Sırılsıklam olsun terden,

Bir ömür sürsün sevişmelerimiz,

Gözlerimizin maviliklerinde.', 'Soyunsun, Gözlerinin maviliğinde, Ve akşam aydınlığında. Soyunsun bütün endamıyla, Çıplak / Arzularının utancıyla, Giysin tutkuların elbises...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soyunsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak artık diyor Güneyden,', 'birak-artik-diyor-guneyden-ali-osman-yilmaz-mvzqm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bırak artık diyor Güneyden,

Böyle ölümü düşünmeyi,

Her acıda döktüğün,

Şairin göz yaşına bak,

Her damlası şiir değil mi? 

Her damlada ayrı bir öykü 

Günlerce okuduğumuz.

Her damlasında,göz yaşının.

Hem yaşarız,hem ölürüz,

Tuz tadında aşk şarabımız.

Ne garip değil mi Güneyden? 

Sevinirken de,ağlarken de,

Damla damla nehir gibi akan,

Göz yaşının her damlasında,

Aynı tad,aynı tuzluluk var,

Ve nasıl ayıracağız bilir misin? 

Nehir olup akan göz yaşının,

Hangi damlası ölümdür,

Yaşam hangi damlasıdır,

Öyleyse ikisi de birdir,

Yaşamla ölüm ayrılmaz,

İkiz kardeştir,

Karışır nehir olur,

Akar denizlere bir damla damla,

Demek ki o yüzden,

Denizlerde tuzlu değil midir?', 'Bırak artık diyor Güneyden, Böyle ölümü düşünmeyi, Her acıda döktüğün, Şairin göz yaşına bak, Her damlası şiir değil mi?  Her damlada ayrı b...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/birak-artik-diyor-guneyden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğanın Oğluyum Ben', 'doganin-ogluyum-ben-ali-osman-yilmaz-4oxpa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğa ananın şarkısıyım ben,

Söyler gümbür,gümbür,

Fısıldayarak bazen,

Ve yüreğinde saklar beni,

Her bahar söyler yeniden,

Göklerin maviliklerinden,

Toprağın üstüne düşen,

Yemyeşil halıyım ben.

Dağların,derelerin,çiçeklerin,

Doğanın oğluyum ben,

Kışın kükrerim doruklardan,

Çiçek açarım bahar geldiğinde,

Yazın sarı başaklarda gülümserim,

Hayyam’ım mahzeninde,

Demlenirim sonbaharda,

Sonra aşıklara bir armağan olurum,

Düğünlerde gelinin başında tac,

Sabahın doğuşuyla,günle el ele,

Tatlı bir meltem esintisiyle,

Yeniden doğuşu ve ışığı müjdelerim,

Ve akşama,kuşlarla ben,

Kanatlanır,veda ederiz,

Yaşamı sunduğum gibi,

Son çağrısı olurum ölümün.', 'Doğa ananın şarkısıyım ben, Söyler gümbür,gümbür, Fısıldayarak bazen, Ve yüreğinde saklar beni, Her bahar söyler yeniden, Göklerin mavilikle...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/doganin-ogluyum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Güneş Doğarken', 'yeni-bir-gunes-dogarken-sair-ediz-aiwvm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeni Bir Güneş Doğarken

Bak ey can gönül; 

saatler ilerliyor,zaman geçiyor 

Spil dağının doğusundan yeni bir güneş doğacakken 

bu yeni güneş,insanlar için yeni bir günün başlangıcı olacak 

bu yeni günde nice devletler yeni kararlar alıp, 

yeni anlaşmalar yapacaklar 

belki de yeni bir paylaşım savaşının tohumları atılacak bugün de 

belki de yeni bebekler hayata merhaba diyecekler, 

kimileri bu hayattan göçerken 

belki de yeni aşkların tohumları serpilecek gönüllere, 

uzun vadeli olması dileğiyle 

belki de nice aşklar,Leyla Mecnunun aşkı gibi, 

tarihe karışacak bugünde 

belki de niceleri hasret türküleri, 

yalnızlık şarkıları dinleyecek eskisi gibi 

belki niceleri de yeni günü dün gibi 

dünden daha umutlu veya daha karamsar geçecek 

belki kimileri vatanına,hayallerine, 

sevdiklerine kavuşacaklar, yine bugünde 

belki de bu yeni günde şairler 

şiirlerine bir yenisini ekleyecekler 

kimileri hayatına devam ederken 

bu yok olanların diyarında 

bilinmesi gereken bir gerçekte var ki 

bu yeni doğacak güneş, 

hayatımızdan bize sormadan bir gün daha çalacak 

bak ey can gönül, 

yeni bir güneşle gelen yeni bir günde 

kısa vadeli de olsa bunlar gerçekleşecekken 

bense gecenin bu derin sessizliğinde 

seni düşünüyorum beni anlamadığını, 

sevgime karşılık vermediğini düşünüyorum. 

Bu soğuk şehrin insanlarının uyuduğu bu saatte 

soğuk geceler yoldaşım ve sırdaşım olmuştu, 

senin bana söylediklerini düşünürken 

gözüme uyku girmiyor 

cigaralar ardarda yanıyor 

yeni bir güneş doğarken 

ben, yine umutsuz,yine mutsuz 

niçin ben,niçin benim gibi insanlar 

bahara yakın hüzün ayı yaşasınlar niçin,niçin 

bu soruyu defalarca sordum bu gece kendime 

cevap olarak da koca çınar gibi 

soru işaretleri oluştu beynimde 

sen böyle değildin,böyle olmamalıydın 

sevgime bu şekilde karşılık vermemeliydin 

beni isyankar,umutsuz,ufuksuz bırakmamalıydın 

bu sağır ve dilsiz şehirde 

bak felek bir gün daha çalacak benden 

bense seni hayal ediyorum umut ovasında 

umutsuz hülyalarla birlikte 

sana dünümü,bugünümü,yarınlarımı vermiştim 

ama sen,anlamak istedim beni 

mavi düşlerin arka sokağında 

karşılığı bu mu olmalıydı? 

belki kendine göre çok haklısın,haksız olan benim 

belki düşüncelerini tutarlı söyleyip tutarsız anlayan bendim 

karanlık düşlerin sokağında 

kalemi elime,kağıdı önüme aldığımda 

bunları yazmamak için kendimle, 

saatlerce,günlerce,haftalarca,aylarca savaştım 

ama nafile, nereye kadar dedim 

çünkü bende artık sana yetecek ben kalmamıştı 

anla beni anla diye defalarca yalvardım sana 

ama sen anlamadın,anlamak istemedin beni 

yaşarken bu yok oluş diyarında 

hem beni hem kendini üzdün 

yeryüzündeki ağaçlar,taşlar,kuşlar,dağlar gibi 

yalnız bırakmaya meyletmiştin beni 

neydi seni bu acımasız düşüncelere sürükleyen rüya 

onu da bilmiyorum 

bildiğim tek gerçek şu Manisa''nın yalancı sessizliğinde 

seni sevmem ve beni anlamamandır 

bak can gönül, 

yeni bir güneşle birlikte yeni bir güne başlarken 

bırak da bu yeni güneş bizim umut ışığımız olsun 

şu kısa vadeli hayatta 

umudum,ışığım,yoldaşım,her şeyim ol 

hayatımın baharında beni bensiz bırakma 

gönlümün yarınlarını karanlık gecelerde sorgulatma bana 

beni ufku açık denizlerde rotasız dolaştırma 

beni; 

sen olduğun için anla,anla ne olur 

bırak da şu kısa vadeli yok oluş dünyasında 

umutla yaşayalım', 'Yeni Bir Güneş Doğarken Bak ey can gönül;  saatler ilerliyor,zaman geçiyor  Spil dağının doğusundan yeni bir güneş doğacakken  bu yeni güneş...', ARRAY['Türk Edebiyatı','Şiir','Şair Ediz']::text[], 8.5, '{"poet":"Şair Ediz","poet_slug":"sair-ediz","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/yeni-bir-gunes-dogarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Angelico', 'angelico-dogan-ulkekul-hubp4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben saf bir çocuğum Angelico

Aşk nedir bilmem

Şarap yerine su içerim çok zaman

Ağlarken de gülmem

Ben bir şiir bilirim Angelico

“Sin sina tina mina”

Ağlayınca seni hatırlarım

Ve destanlara yazarım sana

“Sin sina tina mina Angelico

Ne demektir ben de unuttum

Sen benimken bir zamanlar

Bunu okudukça sarhoş olurdum

Ben çok şeyler bilirim Angelico

Darılmayı, unutmayı, sitem etmeyi

Aşkı ise çoktan unuttum

Sen kalbini başkasına vereli

Böyle söylediğime darılma Angelico

Biliyorum zaman artık değişti

Sen kimi istersen sev bundan böyle

Bana bakma bu işler bizden geçti 

1954', 'Ben saf bir çocuğum Angelico Aşk nedir bilmem Şarap yerine su içerim çok zaman Ağlarken de gülmem Ben bir şiir bilirim Angelico “Sin sina ti...', ARRAY['Türk Edebiyatı','Şiir','Doğan Ülkekul']::text[], 8.5, '{"poet":"Doğan Ülkekul","poet_slug":"dogan-ulkekul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/angelico-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşça Kal Kader,Hoşça Kal,', 'hosca-kal-kader-hosca-kal-ali-osman-yilmaz-4j6hc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve akşam indiğinde,

Tepeler karanlığın elbisesini,

Giyindiği  bir anda,

Bembeyaz saçları,

Omuzlarından göğsüne dökülen,

Yaşlı bir adam belirdi önümde.

Sağ elinde keskin bir tırpan,

Yavaşça seslendi kulağıma,

Barış seninle olsun dostum,

Şaşkın ve korku dolu,

Bakışlarımı görünce,

Ben kaderim dedi.

Ürkek bir sesle; 

Ne istiyorsun benden ey kader,

Tanrıdan da korkmaz mısın? 

Yaptığın eziyetler yetmedi mi? 

Beni yaşamaktan soğutan,

Ölümü bana sevgili kılan,

Sen değil misin? 

Beni kendi yalnızlığımla,

Yalnız bırak artık,

Yaşam şarabı yerine,

Göz yaşlarımı içmem için,

Yaşam nefesi yerine,

Aşkın kederini solumam için,

Hoşça kal kader,hoşça kal,

Diyerek hızla uzaklaştım,

Gün ışıdığında yeniden,

Yeni sevdalara kanatlanmak,

İstiyorum çünkü ben.', 'Ve akşam indiğinde, Tepeler karanlığın elbisesini, Giyindiği  bir anda, Bembeyaz saçları, Omuzlarından göğsüne dökülen, Yaşlı bir adam belir...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hosca-kal-kader-hosca-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Bana', 'anlat-bana-dogan-ulkekul-we8au', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sessizliğinde kuşkuluyum

Konuştuğunda ise

sanki susuyorsun

Oysa gözlerin anlatıyor bana herşeyi

Uzun uzun

Doğan Ülkekul

2000', 'Sessizliğinde kuşkuluyum Konuştuğunda ise sanki susuyorsun Oysa gözlerin anlatıyor bana herşeyi Uzun uzun Doğan Ülkekul 2000...', ARRAY['Türk Edebiyatı','Şiir','Doğan Ülkekul']::text[], 8.5, '{"poet":"Doğan Ülkekul","poet_slug":"dogan-ulkekul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anlat-bana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-dogan-ulkekul-16rjv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana yazmalıyım bu sabah

Yalnızlığımı

Yanımda olmadığın her an

Yalnızım ben

Kuşlar

Sisli gürültüsüne karışmıyor sokakların

Bu erken saatlerde

Yarım kalmış rakı şişeleri gibi

Ağzım paslanmış sigaralardan

Uyku yapışıyor gözlerime

Ama

Sana yazmak istiyorum

Uzaklarda

Ayı siliyor aydınlanan bulutlar

Gökyüzünden

Yaramaz çocuklar gibi

Yüzleri kızaran çatılarda

Sabah oluyor

Yazmalıyım sana

Bir kez daha anlatmalıyım yalnızlığımı

Yanımda olmadığın sabahları

Sisli gürültüsünü

Bulvarların

Sana yazmak istiyorum

Bıkmadıysan eğer

Yorulmadıysan okumaktan

Denizlerin dipleri kadar karanlık

Akşamları

Uykularımı çalıp giden

O terlemiş yastığımı

Boğazıma sarılan yalnızlığıma

karışan yatıktaki kokunu

Seni

Öyle özlüyorum ki', 'Sana yazmalıyım bu sabah Yalnızlığımı Yanımda olmadığın her an Yalnızım ben Kuşlar Sisli gürültüsüne karışmıyor sokakların Bu erken saatlerd...', ARRAY['Türk Edebiyatı','Şiir','Doğan Ülkekul']::text[], 8.5, '{"poet":"Doğan Ülkekul","poet_slug":"dogan-ulkekul","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/seni-dusunmek-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-haluk-ozdemir-74s84', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arada özlemde duymuyor 

Değilim hani

Yaşıyor dilediği gibi

Oh be ne kira,ne vergi

Ne hayat mücadelesi

Ne yaşam derdi

Ona her gün bayram

Ne cehennem var ne de haram', 'Arada özlemde duymuyor  Değilim hani Yaşıyor dilediği gibi Oh be ne kira,ne vergi Ne hayat mücadelesi Ne yaşam derdi Ona her gün bayram Ne c...', ARRAY['Türk Edebiyatı','Şiir','Haluk Özdemir']::text[], 8.5, '{"poet":"Haluk Özdemir","poet_slug":"haluk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/keske-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski eşe', 'eski-ese-haluk-ozdemir-o8s83', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kadar mı meraklıydın ayrılmaya

Hakimin boşanma kararıyla

Fırsatı ganimet bildin

Yok oldun gittin sen neredesin? 

Bizi hiç mi merak etmedin

Gelmez mi aklına hiç bir hatıra

Oh ne hoştu keyifler keka

Güzeldi benimle beraber sürmek sefa

Aman arayıpta bir kere bile sorma

Sana göre sadece İstanbul''da bir semt Vefa', 'Bu kadar mı meraklıydın ayrılmaya Hakimin boşanma kararıyla Fırsatı ganimet bildin Yok oldun gittin sen neredesin?  Bizi hiç mi merak etmedi...', ARRAY['Türk Edebiyatı','Şiir','Haluk Özdemir']::text[], 8.5, '{"poet":"Haluk Özdemir","poet_slug":"haluk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eski-ese-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Poyraz', 'poyraz-cem-berk-r48ya', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu akşam bunu anladım,

Meğersem hep karanlıkmış akşamlar,

Hep dağınıkmış bulutlar, aşıklar, dünyalar,

Meğersem poyraz dağıtırmış onları, kimselere sormadan

Geçermiş dalgasını, uzaklara vura vura...', 'Bu akşam bunu anladım, Meğersem hep karanlıkmış akşamlar, Hep dağınıkmış bulutlar, aşıklar, dünyalar, Meğersem poyraz dağıtırmış onları, kim...', ARRAY['Türk Edebiyatı','Şiir','Cem Berk']::text[], 8.5, '{"poet":"Cem Berk","poet_slug":"cem-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/poyraz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Vakti', 'ayrilik-vakti-engin-ertug-lq6bs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim yıldızım parlıyordu

Azalan ışığı zayıflıyordu

İçinde bir ateş sönüyordu

Artık ayrılık vaktiydi

Bu bulutlu kara geceden

Bir yıldız kaydı gökyüzünden

Bir sevda çıktı hayatımdan

Ölümüm ayrılık vaktinden', 'Benim yıldızım parlıyordu Azalan ışığı zayıflıyordu İçinde bir ateş sönüyordu Artık ayrılık vaktiydi Bu bulutlu kara geceden Bir yıldız kayd...', ARRAY['Türk Edebiyatı','Şiir','Engin Ertuğ']::text[], 8.5, '{"poet":"Engin Ertuğ","poet_slug":"engin-ertug","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-vakti-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islanmış bir sonbahar kadını', 'islanmis-bir-sonbahar-kadini-i-brahim-derin-2h8ps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar

çok acı çekiyordum

sevda yüzünden

şimdi susturdum

rüzğarı

yagmuru

kilt vurdum kalbime

yinede dinmedi sancılar

ben unuturum dedim kalbime

ama unutturmuyor seni şarkılar

gözlerimdeki yaşları

birkez olsun hiç silmediler

ellerim hep boş kaldı

ne kadar beklediysem 

o kadar gelmediler

aslında

hayatımda kaldırmıyor ikinci kişiyi

ben bana yetiyorum

bu asırlık şehrin karanlıgında

bende kalbimin alt nüshası var

aslı kaldı

ıslanmış bir sonbahar kadınında

bütün ömrümün sade bir ortalaması vardı

ve hiçbir zaman degişmedi

bu düpedüz bir yalnızlıktı

                                antalya', 'Bir zamanlar çok acı çekiyordum sevda yüzünden şimdi susturdum rüzğarı yagmuru kilt vurdum kalbime yinede dinmedi sancılar ben unuturum dedi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Derin']::text[], 8.5, '{"poet":"İbrahim Derin","poet_slug":"i-brahim-derin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/islanmis-bir-sonbahar-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezer Geçerim!', 'ezer-gecerim-ceyda-ayfer-oz-4xztp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnce ince iner dibe 

Yağan yağmurlar

Denizden bakmak gibidir gökyüzüne

Sabah seninle buluşmalar...

Tutmasan beni kollarımdan, tutmasan

Sen bir kere ölürsün de

Ben her sabah sana doğar,

Yaprak yaprak sana düşerim her akşam…

İnançlarını toparlarsın sıvanmış duvarlardan

Kutsamazsın sevdanı bilirim 

Çoktan tersidir adres elinin 

Dilim sus derken susmaz yüreğim...

Ben senin gibileri çok iyi bilirim...

Laftır bu değişir çevirdiğince 

Lastik olur da uzar gönlünce

Yalanı biçersin kendi istediğince

Ben hepsini sineye çekerim de...

Yoluma koyduğun başını ezer geçerim!', 'İnce ince iner dibe  Yağan yağmurlar Denizden bakmak gibidir gökyüzüne Sabah seninle buluşmalar... Tutmasan beni kollarımdan, tutmasan Sen b...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Ayfer Öz']::text[], 8.5, '{"poet":"Ceyda Ayfer Öz","poet_slug":"ceyda-ayfer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ezer-gecerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güneş', 'bir-gunes-ayca-aydemir-u3r1j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir güneş gibi geçti yanımdan 

Ona bakınca içim ferahladı

Bir daha bakınca 

ne olduğunu anladım

O benim geleceğimdi

Benim geleceğim 

Sadece benim geleceğim', 'Bir güneş gibi geçti yanımdan  Ona bakınca içim ferahladı Bir daha bakınca  ne olduğunu anladım O benim geleceğimdi Benim geleceğim  Sadece ...', ARRAY['Türk Edebiyatı','Şiir','Ayça Aydemir']::text[], 8.5, '{"poet":"Ayça Aydemir","poet_slug":"ayca-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-ferit-teksoy-gtpnw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Muzip,sevecen,ışıklı

Sevgisi okunan bakışlarında

Ayrılırken gölgeli

Gözlerini özledim..

Siyah,sarı,kumral

Nemli,gölgeli

Kıvır kıvır,mis kokulu

Saçlarını özledim..

Akpak,bakımlı,küçük

Oyunda maharetli,yemekte marifetli

Sararken doyumsuz

Ellerini özledim..

O tadına doyamadığım

İçkiye tat,aşka doyumsuzluk veren

İmzamı taşıyan

Dudaklarını özledim..

Sevgi saçan dostuna,sevdiğine

Sohbette,şarkıda bir başka güzel

Kulağıma sevgisini fısıldayan,

Sesini özledim..

Kokunu,tenini..

Dokunmayı,sevmeyi

Elimden tutup gidişimizi

Seni özledim..', 'Muzip,sevecen,ışıklı Sevgisi okunan bakışlarında Ayrılırken gölgeli Gözlerini özledim.. Siyah,sarı,kumral Nemli,gölgeli Kıvır kıvır,mis koku...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ozledim-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seraptı okuduğun şey', 'serapti-okudugun-sey-temel-beydi-80kzj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seraptı okuduğun şey 

Ellere dokunan kitapta

İnce ve tutkun bir kadın 

Çıplak tenini çekerdi kendine

Büyür de çocuk olurdu

Eteğinde biriken zaman

Irmağın en sığ akarında

Üşüyen yelken

Kollarında son yazın kumu

Sarıldıkça çoğaldı çöl ve ten

İzin vermedin sürgüne

Gidelim birimizden', 'Seraptı okuduğun şey  Ellere dokunan kitapta İnce ve tutkun bir kadın  Çıplak tenini çekerdi kendine Büyür de çocuk olurdu Eteğinde biriken ...', ARRAY['Türk Edebiyatı','Şiir','Temel Beydi']::text[], 8.5, '{"poet":"Temel Beydi","poet_slug":"temel-beydi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/serapti-okudugun-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyse...', 'neyse-nilgun-ozkan-e658x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '..........güzeldi, hiç olmak kadar

bahar '' a inat

hiç kıpırtısız bir yürekle

görmeyen gözlerle bakmak neyse,

renklerin alaca sarhoşluğunu

bir celsede yitirmek neyse,

su yeşiline, kızıl maviye, buzul sarıya

gözünü yummak neyse,

son gülümsemeye

soluğunun kesildiği en bildik an'' a 

uzak bakışlara

uçuşkan gecelere

üşüten sabahlara

adı yok yalnızlıklara

arkanı dönmek neyse,

..........sonsuzca, sayısızca yazmalarını okumak

tüm bencil yanlarımla

seni özlemek neyse,

.......tadını bildiğim, sevdiğim, kokladığım

gizil cümlelerine ansızın 

yol almak neyse,

bir kelimene duraksayıp,

buruk gülümsemek neyse,

seni anmak, seni düşünmek

seni, seni................neyse.......

ötesi neyse.....

her neyse.....', '..........güzeldi, hiç olmak kadar bahar '' a inat hiç kıpırtısız bir yürekle görmeyen gözlerle bakmak neyse, renklerin alaca sarhoşluğunu bi...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Özkan']::text[], 8.5, '{"poet":"Nilgün Özkan","poet_slug":"nilgun-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/neyse-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gişeler önünde bekleyen', 'giseler-onunde-bekleyen-temel-beydi-9sudk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gişeler önünde bekleyen 

Ünsüzleriz

İsmini bulmak için 

Sedalar satın alan

Başka şehirlere bırak dönüşleri

Alkışları tükenmiş bizi bekleyen yolcuların,

Büyük dünya atlasıyız düşlerde.

Yitirdik Türkçe''nin en derin limanında

Anıların coğrafyasını', 'Gişeler önünde bekleyen  Ünsüzleriz İsmini bulmak için  Sedalar satın alan Başka şehirlere bırak dönüşleri Alkışları tükenmiş bizi bekleyen ...', ARRAY['Türk Edebiyatı','Şiir','Temel Beydi']::text[], 8.5, '{"poet":"Temel Beydi","poet_slug":"temel-beydi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/giseler-onunde-bekleyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapaneus', 'kapaneus-zafer-zengin-etnika-zgs9o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapaneus

- sen hala burdamısın? 

cehennemin ve cennetin sahibi sessiz

yükselir,ateşin rengi...

ve şair

şiirler bırakır sağa sola

dönüşünde 

yol kolay olsa

bak işte gördün mü! 

ters bakıyor hayat''a yine

-korkmuyorum ateşten, kendimden korktuğum kadar

çeviktir gülümsemesi,aldırmaz

yine sorar! 

- sen burda mısın hala

- git cennetine..! 

senin benim yok,onun var,onbir sahipsiz,kimse üstlenmez günahları.

20 subat 2004', 'Kapaneus - sen hala burdamısın?  cehennemin ve cennetin sahibi sessiz yükselir,ateşin rengi... ve şair şiirler bırakır sağa sola dönüşünde  ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kapaneus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Mevsim', 'i-ki-mevsim-erkin-gedik-6yp8r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yoksun diye

Yine bana uğramadan geçti bahar

Sensiz gönlümde iki mevsim yaşar

Yalnız kış, yanlış bahar...', 'Sen yoksun diye Yine bana uğramadan geçti bahar Sensiz gönlümde iki mevsim yaşar Yalnız kış, yanlış bahar......', ARRAY['Türk Edebiyatı','Şiir','Erkin Gedik']::text[], 8.5, '{"poet":"Erkin Gedik","poet_slug":"erkin-gedik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iki-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Bulacaksın', 'sicak-bulacaksin-zafer-zengin-etnika-9igxi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'üstümü ört 

giderken

üşümesin 

senli düşlerim

üstümü ört 

aralanmış

gülümseyen 

dudağınla

üşümesin 

yanağım

üstümü ört 

giderken

seni bekleyeceğim

üşümesin ellerim

üstümü ört

yangınlar çıkmasın

döndüğünde 

sıcak bulasın...

gittin,

biter mi sanırsın hasret! 

bitermi sanırsın gurbet! 

üzerimi ört,sen devam et! 

geldiğinde selamet...

döndün mü! 

perdeleri ört

sıcak geliyor sesin

bu minik eller 

demek senin

gel 

sokul 

anlatacağım; 

bir kadın ve 

bir adam varmış

birbirilerini görmeden 

yaşayamazmış

biri kadın,

biri adammış

gözlerini ört

gerisini kimse duymasın

yaşanmamış...

arsızdır 

gece vakti insanın içi

dünya değişsede 

değişmez niyeti

sonra bir kadın ve 

bir adam sureti

onlar olmasa 

dünya ne yapacak dönmeyi...

20 subat 2004', 'üstümü ört  giderken üşümesin  senli düşlerim üstümü ört  aralanmış gülümseyen  dudağınla üşümesin  yanağım üstümü ört  giderken seni bekley...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sicak-bulacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heykel', 'heykel-gokcen-duran-sf442', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen, buzdan oyulsan

Gün ışığından mahrum kuytularımda

Saklarım seni mutluluk nöbetlerim boyunca

Sen, buzdan oyulsan

Kırk haramilerin hasis gözlerinde

Ay ışığının solduğu

Açıl susam açıl vakitlerinde

Kavuşurum sana

Sen, buzdan oyulsan

Her depresif durumumda

Bir taşın soğuk,merhametsiz, yüzü

Bölemez umutsuzluğumu 

En incelmiş yerinden

Rodin’in gözbebekleriyle

Taştan  oyduğu nazenin tanrıçam

Bırakalım heykel, heykeltıraşların işi

Gel biz eksik bedenlerimizle sevişelim', 'Sen, buzdan oyulsan Gün ışığından mahrum kuytularımda Saklarım seni mutluluk nöbetlerim boyunca Sen, buzdan oyulsan Kırk haramilerin hasis g...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/heykel-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm seni kayıplardan giyindim', 'omrum-seni-kayiplardan-giyindim-temel-beydi-naxbi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömrüm seni kayıplardan giyindim

Yalnız bir kuş tenime dokundu

Sevda yokluğuna adresmiş anladım

Bir şiir onu cebinde unuttu

Yüzüne asıldım üzüntülerimin

Çocukluğumun maskesi büzüldü

Dağlar seni sevdiğimi bilirsin

Kanıma martı kanadı durdu

Eksildim de güneşin kızardığı yerde

Annemin eli güneşe döndü

Yandığım şu ki tanıdım aşkı, hasedi

Aşk da haset de düşmanım oldu

Ömrüm seni neyledim de giyindim

Eşiğine sığındım kapılar yüzüme vurdu', 'Ömrüm seni kayıplardan giyindim Yalnız bir kuş tenime dokundu Sevda yokluğuna adresmiş anladım Bir şiir onu cebinde unuttu Yüzüne asıldım üz...', ARRAY['Türk Edebiyatı','Şiir','Temel Beydi']::text[], 8.5, '{"poet":"Temel Beydi","poet_slug":"temel-beydi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/omrum-seni-kayiplardan-giyindim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Son Cigligi', 'gecenin-son-cigligi-nilgun-ozkan-thx8l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Depreşen her sağanağın

koyu tavanlara sinen silueti

en kozmik bakışla mordeniz

kopuk yanılsamalar,

dışsal duyumların izdüşümüne

merasim kıvamında değiyor..

dönerek dibe vuran

sınırlarıyla saydamlaşmış zerreler

birer birer ayrılırken

özvarlıklarından

harflerin şekli karışıyor

sığ''a parçalanan gökyüzünde

sonsuz esinti..', 'Depreşen her sağanağın koyu tavanlara sinen silueti en kozmik bakışla mordeniz kopuk yanılsamalar, dışsal duyumların izdüşümüne merasim kıva...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Özkan']::text[], 8.5, '{"poet":"Nilgün Özkan","poet_slug":"nilgun-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gecenin-son-cigligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şamdan', 'samdan-abdullah-atay-my4fq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzünlü bir güz akşamında,

Mum olsam şamdanında; 

Mehtaba inat! 

Aydınlatsam yalnız gecelerini...

Kollarının arasında tutuşsam...

Güneşe inat! 

Bakışlarınla eriyip tükensem...

Saatlerden geçen,

Zamana inat! ...

Damla damla dökülsem yüreğine:

Yağmurlara inat,

Karlara inat! ..

Saklar mısın beni?', 'Hüzünlü bir güz akşamında, Mum olsam şamdanında;  Mehtaba inat!  Aydınlatsam yalnız gecelerini... Kollarının arasında tutuşsam... Güneşe ina...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/samdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düs(ün) ce', 'dus-un-ce-nilgun-ozkan-nrdni', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüreğimi eyleme iten

ay soldu o gece

ben başka soldum

sıcak soluğum ayaz''a vurdu

bir çığlık dondu

yere düşen cam sesiyle kesildi sesim

uzaktan seslenirken

.........yaydı da

o tınıyı ova''ya

yarım bakışların eksik kokusu kaldı..

bir ses olsa yağmurdu..

bir söz olsa  sukuttu...', 'yüreğimi eyleme iten ay soldu o gece ben başka soldum sıcak soluğum ayaz''a vurdu bir çığlık dondu yere düşen cam sesiyle kesildi sesim uzakt...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Özkan']::text[], 8.5, '{"poet":"Nilgün Özkan","poet_slug":"nilgun-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dus-un-ce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devimim an''i', 'devimim-an-i-nilgun-ozkan-jdedb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'benim gibi görünen uzak yüz

bakma bana öyle yabansıl

zamansız bozulmuş pusula

yok ol sen de derinde..

soluğum hiç''e karışma

dönüşün sıfırda dönüşüm''e bölünür

tüm asal sayılar, asil sayılar

olup; mekansız mekanlara dağılır

sokağın en bildik anlaşılmaz sesiyle

susamlar çığlık çığlık simitlerin üstünde

öyle kalın, öylece..

iç-dış uyaranların tepkili seslerini

sessizliğimle boğmanın

habersiz tadıyla buluştum

uyku ile uyanıklık arası

kısa metrajlı uzun bir film

karmakarışık karelere bölündü sesler ve

görünmeyenler..

düşselin damla-damla çığ-çığ

parça-parça su-sel akıtıp yitirdikleri

kalan''ı selamladı

hiçlikle son kez..', 'benim gibi görünen uzak yüz bakma bana öyle yabansıl zamansız bozulmuş pusula yok ol sen de derinde.. soluğum hiç''e karışma dönüşün sıfırda ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Özkan']::text[], 8.5, '{"poet":"Nilgün Özkan","poet_slug":"nilgun-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/devimim-an-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece sanrisi', 'gece-sanrisi-nilgun-ozkan-drbz3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sana bu gece

en sevdiğim çiçeğin kokusunu

yolladım ay''ın gölgeli yüzünde

sana bu gece

düşlediğin bir bakışı yolladım

retinanın aksinde

sana bu gece

özlemlerimi yolladım

sarı duvarın üstündeki çizgide

sana bu gece

ve ilk gece

ve tek gece

hayalimi yolladım

bak dilediğince..', 'sana bu gece en sevdiğim çiçeğin kokusunu yolladım ay''ın gölgeli yüzünde sana bu gece düşlediğin bir bakışı yolladım retinanın aksinde sana ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Özkan']::text[], 8.5, '{"poet":"Nilgün Özkan","poet_slug":"nilgun-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gece-sanrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-nilgun-ozkan-1gu00', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bazen ruhunu yıkamaktır o'' nun sesi

bazen bilinmez boşluklar

yolların yıllara mesafesi

kat edildikçe uzayan

dokunmadan tuttuğum

bir şiirin her mısrası

yüreğimin görünmezlerine nüfuz ettiğinde

ayrımına varılmaz bir düş-gerçek 

arası hikayen..', 'bazen ruhunu yıkamaktır o'' nun sesi bazen bilinmez boşluklar yolların yıllara mesafesi kat edildikçe uzayan dokunmadan tuttuğum bir şiirin h...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Özkan']::text[], 8.5, '{"poet":"Nilgün Özkan","poet_slug":"nilgun-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ses-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Cinayet Tutanağıdır', 'bir-cinayet-tutanagidir-osman-velioglu-iqfd0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir güz akşamıydı, hava serindi,

Yağmur yağıyordu,ıslanıyordum.

Ağzımda sigara, yaram derindi,

Gökyüzü donuyor, ben yanıyordum.

Bir mahkeme kurdum denize karşı,

Suyun üzerinden baktım maziye,

Derinden gelirken cenaze marşı,

Ben kalemi kırdım aşka, sevgiye.

Saygıdeğer heyet bilmeli şunu

Ben bu aşkı ondan şuursuz aldım

Böyle bir mevsimde tanıdım onu

Kara gözlerine asılı kaldım

Rastgele savurdu bakışlarını,

Ruhumu kevgire çevirdi benim.

Yıldızlar kapattı ışıklarını

Sevda zindanına yakıldı tenim.

Sevdim diyebilmeyi beceremedik,

Arabesk hüzünler sığınak oldu...

İncindik bilerek, boşveremedik,

Zaman süsümüzü çok çabuk yoldu.

''Sen'' dedim ve onda beni yitirdim

Aradım umarsız kaybolan beni,

Kırıldım,ulaşmaz sana çıtırtım,

Ölü varlığımla öldürdüm seni.

Şimdi bir merasim yapar yüreğim

Bunca yılı heder etti ardında

Üzerine ömür yığdı küreğim

Yatar ölü aşklar mezarlığında.

Teslim oluyorum.Kaçamam artık,

Onu ben öldürdüm.Pişman değilim.

Ömür defterimde sayfası yırtık

Bir daha adını anamaz dilim.', 'Bir güz akşamıydı, hava serindi, Yağmur yağıyordu,ıslanıyordum. Ağzımda sigara, yaram derindi, Gökyüzü donuyor, ben yanıyordum. Bir mahkeme ...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-cinayet-tutanagidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzüne bakıyorum', 'yuzune-bakiyorum-temel-beydi-v4mqx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzüne bakıyorum 

Aydınlıksın, çocuksun

Gözünde halka şeker

Annem gibi üzül bana 

Halkada kalsın şeker

Ayakkabımı çekiyorsun

Boyacı bir çocuksun

-Elinde tüyleri dökük bir fırça olacak-

Ah, geceler saydamlanıyor

Karanlık ayakkabımda saçak 

Verdiğin çay dökülüyor

Rengi boyanıyor düşüme; 

Sıcak ve füme

Af diliyorum

Hiç gereği yokken

Bakmıyorsun yüzüme', 'Yüzüne bakıyorum  Aydınlıksın, çocuksun Gözünde halka şeker Annem gibi üzül bana  Halkada kalsın şeker Ayakkabımı çekiyorsun Boyacı bir çocu...', ARRAY['Türk Edebiyatı','Şiir','Temel Beydi']::text[], 8.5, '{"poet":"Temel Beydi","poet_slug":"temel-beydi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuzune-bakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyam', 'papatyam-ahmet-kemaloglu-cui82', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karlı; 

Ama beyaz bir kış gününde..

Seni düşünmek...

Seni düşünmek seni.

Sarı papatyam seni.

Sesini,gülüşünü.

Ve kızışını.

Seni düşünmek....! 

Sarı papatyam seni..

Sebebi belli,

Tarifi zor.

Bu gecenin de tarifi zaten zor.

Ama,

Sebebi sevgi...

Yüreğim serçe kalbi.

Gözlerim oluk oluk...

Ve.oradan yüreğime akana,

Sen su de,ben SEVGİ..', 'Karlı;  Ama beyaz bir kış gününde.. Seni düşünmek... Seni düşünmek seni. Sarı papatyam seni. Sesini,gülüşünü. Ve kızışını. Seni düşünmek.......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kemaloğlu']::text[], 8.5, '{"poet":"Ahmet Kemaloğlu","poet_slug":"ahmet-kemaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/papatyam-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür Olmak', 'ozgur-olmak-i-brahim-ethem-bingul-38hed', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bıktım bıçak sırtı yaşamlardan

Çimlere basmak istiyorum,yalın ayak

Koşmak, yemyeşil bir ovada

Ya da asil bir kısrağın sırtında,dört nala

Dilimde sevda türküleri,hoyratça

Ve günlerce kaybolmak

Kendimi bile bulamayacak kadar

Kaybolmak, yeşilin ruhunda

Tabi,sevdiğim öbür yarımda', 'Bıktım bıçak sırtı yaşamlardan Çimlere basmak istiyorum,yalın ayak Koşmak, yemyeşil bir ovada Ya da asil bir kısrağın sırtında,dört nala Dil...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozgur-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak Bakışlar', 'tutsak-bakislar-vahittin-bozgeyik-i5c65', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gemi kalkar bazan,denizsiz bir limandan

Bir tek ben kalırım sahilde,mendil sallayan

Kimin için sallarım,niçin sallarım? 

Bilmem sallarım işte.

Güney yelleri okşar sonra saçlarımı delice

Gizli selamlar dökülür dudaklarımdan ister istemez

Kimin için yollarım,niçin yollarım? 

Bilmem,yollarım işte.

Yanıtlanmaz acı da olsa gizli selamlarım

Yaşardığını duyarım fersiz gözlerimin

Kimin için ağlarım,niçin ağlarım? 

Bilmem,ağlarım işte.

Alır gider tutsak bakışlarımı yeşil umutlar

Umutsuzlukla bakarım umutlarıma neden? 

Kimin için bakarım,niçin bakarım

Bilmem bakarım işte.

Tüm özlemler biter orada,benimki başlar

Alır giderim başımı,bilinmeyen bir yöne

Kimin için giderim,niçin giderim

Bilmem giderim işte.', 'Bir gemi kalkar bazan,denizsiz bir limandan Bir tek ben kalırım sahilde,mendil sallayan Kimin için sallarım,niçin sallarım?  Bilmem sallarım...', ARRAY['Türk Edebiyatı','Şiir','Vahittin Bozgeyik']::text[], 8.5, '{"poet":"Vahittin Bozgeyik","poet_slug":"vahittin-bozgeyik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tutsak-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Giriş Beş Şiir', 'bir-giris-bes-siir-ahmet-aksoy-9avh9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Amip-

kıymasız köfteler gibi yavan bir ömür

umudu kara dul

kederi gametsiz zihinler

içlerindeki hayvan

kıyma kıyma üç kere kıyma köftene diyenler

önce kendi ruhlarına yansın

işte felsefe

kıymasız köfte yavandır.

-Şair Meleği-

yüreğim asri acılar geçidi,

bir sevda yok acıtmadan uğrasın,

bir mutluluk tanımadım, acısına han olmadığım.

ben şair meleği, çilekeş büyük keşiş.

hep ama hep dert ereği,

sende yetiş,  er bana

şayet bir an dahi anarsan kederi,

bırak kucağıma onu, ben taşırım,

sonra, sonra tomurcuk çiçek olduğunda,

dikenleri gönlüme basıp, ekerim toprağına.

unutma ben şair meleği,

yüreğim asri,  hep ama hep

acılar geçidi.

-Kum Canavarı-

zincirlenmiş sonsuzluk simgesinde

saatteki kum canavarı

üstünde mintan 

altında basma etek

saatteki kum canavarı

erkeğe kadın kadına erkek

ah bir geçmese önümüzden

kumlarımızla rahat oynasak 

-Giz-

ben yıllardan yetim zamansız ölü

şimdi kurumuş parmaklarımda bir gül

eksilmiş dişlerimde cihana inat bir gülüş

ah neden sonra bugün çıktı meydana 

aşkmış! içimde gizlediğim troya

ben öksüz ölü, nice zamanlar yitirdim toprakta

oysa hala derin bir sızı var şuramda

toprak ayırmış olsada canı benden

ah içimdeki saklı giz, gün bugün

gel bana sevdiğim gül yoksa kar kaçağı mısın

-Kibrit-

retinasına kurşun dökülmüş

bir adam kadar deli

cinnet içinde yaşa benimle

bir kibrit gibi yan ve bit

yani insan gibi

her an yandığını bilerek.', '-Amip- kıymasız köfteler gibi yavan bir ömür umudu kara dul kederi gametsiz zihinler içlerindeki hayvan kıyma kıyma üç kere kıyma köftene di...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/bir-giris-bes-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Dörtlükler II', 'yeni-dortlukler-ii-ahmet-aksoy-urq90', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sayeler Arasınsda II

ah özge karanlıklar, kendi karanlığımdan 

sıyrılmadan uğradığım, aydınlıkta öküz soğuğu,

nasıl da egemen olurlar düşlerime,

ve bir engel gibi biterler sevişlerimde.

Son Damla

kırmızı ayaz rüzgarı gözlerinden süzülen öfke

bir kara buluttan yağıyor kederle

oysa o hep mahsun ve zarif olan

bu kez elindeki kılıcı kaldırıyor kötüye 

Sultanım

alçak gönüllü bir sultan gibi  tuttun saçlarımdan,

ey büyük cihnalar sultanı, girdin en iç hisarlarıma kadar, 

benim uyruğunda ölmeyi emel saydığım; ne olur 

uzat bana fermanını, tutayım, tutayım, ölene kadar! 

Aşkım Ol

yüreğimde bir serzeniş ol

yalvarırım ağlat onu

sen desin yanarak

aklım halt etmiş, aşkım ol

Oyun Arkadaşı

hey dostum uzaklaşma masadan

otur bir ucuna  kaçma bizden

mademki hep aynı salondayız

el ele oynamayalım neden', 'Sayeler Arasınsda II ah özge karanlıklar, kendi karanlığımdan  sıyrılmadan uğradığım, aydınlıkta öküz soğuğu, nasıl da egemen olurlar düşler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yeni-dortlukler-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-umit-kilislioglu-ozger-1cjt2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözünün ışığında gördüm kendimi,

Sesinin ahenginde.

Dalar, dalar giderim aşk dendi mi

Bir şey var âşina kokunda, saçının renginde.

Kim bu içimdeki efkârlı şair? 

Ötelerden gelen müziği kim çalıyor? 

Neden sancılarım sen şarkı söylerken azalıyor? 

Bir şey var sanki aramızda, geçmişe dair.', 'Gözünün ışığında gördüm kendimi, Sesinin ahenginde. Dalar, dalar giderim aşk dendi mi Bir şey var âşina kokunda, saçının renginde. Kim bu iç...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-340-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznü Vuracaklar...', 'huznu-vuracaklar-bekir-mutlu-gokcesu-ikxi9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl yorgunum

Hani

Bıraksam kendimi

Döküleceğim

Olduğum yere

Fakat direniyorum

İllaki seyredeceğim

Zira

Bu yağan son kar

Belki de

Fakat yorgunum

Göz kapaklarımda kurşunlar

Ne kadar gizlesem de

Menzili bulacaklar

Az sonra

İçimdeki hüznü vuracaklar...', 'Nasıl yorgunum Hani Bıraksam kendimi Döküleceğim Olduğum yere Fakat direniyorum İllaki seyredeceğim Zira Bu yağan son kar Belki de Fakat yor...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huznu-vuracaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmemiş ki', 'sevmemis-ki-canan-ucer-h638o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tanımadığım insanlara sunmuştu

Uçarı yalnızlığımı

O''naydı oysa, yüzümdeki gölgeler

Duvarların dibinden çıkarıp

Avuçlarına vermiştim hikayemi....

Gün gözçukurlarımda hüzün

Gün öfkeye kesti...

Ucundan tutmasa öksüz ellerim

Yakacak bu şehri.....

Ah, tanrıçalar söyleyin Zeus''a

Zincire vursun beni

O beni sevmemiş, hiç sevmemiş ki

.............................................................

(Zeus uzaktan görünür haşmetiyle

Der ki........

-Sevemez kimse seni, benim sevdiğim kadar........

Çözün ellerimi, çözün hadi....................................)', 'Tanımadığım insanlara sunmuştu Uçarı yalnızlığımı O''naydı oysa, yüzümdeki gölgeler Duvarların dibinden çıkarıp Avuçlarına vermiştim hikayemi...', ARRAY['Türk Edebiyatı','Şiir','Canan Üçer']::text[], 8.5, '{"poet":"Canan Üçer","poet_slug":"canan-ucer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevmemis-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Olmayacak Gençliğinin Bedeli', 'bu-olmayacak-gencliginin-bedeli-melih-coskun-3iv68', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dik tut başını

Bu olmayacak gençliğinin bedeli

Talan mevsiminde açan çiçeğisin sen yurdumun 

Sürgünsün doğduğun topraklarda 

Ekmek ve aşk 

Hürriyet kadar zordur sana yaşamak 

Doğum ve ölümün yüzleştiği 

Dar ve soğuk koridorlarda

Erken yazılmış bir hikayesin şimdi 

Ne yazabilmek mümkün seni 

Ne de çıkarabilmek bir an beynimden 

Umudunu kaybettiğin anlarda olacak elbet

Hayat, ağır bir yük gibi çökecek omuzlarına 

Asıl işin 

İşte öyle anlarda ayakta kalabilmek olacak, 

Ve ne olursa olsun 

Teslim olmayacaksın

Esir düşsen de, 

Tokat gibi çarpabileceksin yüzlerine öfkeni 

Sen yine de dik tut başını 

Bu olmayacak 

Yiten gençliğinin bedeli...', 'Dik tut başını Bu olmayacak gençliğinin bedeli Talan mevsiminde açan çiçeğisin sen yurdumun  Sürgünsün doğduğun topraklarda  Ekmek ve aşk  H...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-olmayacak-gencliginin-bedeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünce', 'dusunce-ayca-aydemir-51u4u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklımın içinde gizli o 

Bazen düşünmeme yarar 

Bazen hayallerimi gerçekleştirmeye

O benim düşüncem 

Onu ben yarattım

Sadece ben 

Ve düşüncem

Biz ikiliyiz

Ben düşüncemi kullanmazsam

O zaman ikili değil sadece insan olurum

Düşüncemle iyi anlaştım

O zaman

Bu zaman

Bir takım olduk', 'Aklımın içinde gizli o  Bazen düşünmeme yarar  Bazen hayallerimi gerçekleştirmeye O benim düşüncem  Onu ben yarattım Sadece ben  Ve düşüncem...', ARRAY['Türk Edebiyatı','Şiir','Ayça Aydemir']::text[], 8.5, '{"poet":"Ayça Aydemir","poet_slug":"ayca-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dusunce-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Şiirleri Yakılmış Şair Çaresizliğim', 'benim-siirleri-yakilmis-sair-caresizligim-melih-coskun-6unjj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim şiirleri yakılmış 

Şair çaresizliğim 

Her şiir eksilen bir gündür artık ömrümüzden 

Her dize bir yaşanmamışlık hikayesi

Tüm kapılar kilitlenmiştir hayatımda

Masmavi kan gibi akıyor

Damarlarımdan silinen şiirlerim

Sana ulaşamayıp ağladığımda değil 

Sana şiir yazmaktan vazgeçtiğim gün kaybediyorum seni...

Şimdi ruhumu alevlendirecek 

Bir an gerek 

Bir anki 

Boşa geçen bütün zamanlara eş

Yapılmış bir resmi yeniden boyamak değil 

Tükenmiş bir umudu yeniden diriltmek değil 

Yeni resimler

Yeni umutlar

Ve binlerce yaşanmamış hikayeyi yazmak yeniden...

Savaşıp yeniden kazanmak bütün kaybettiklerini 

Daha güzelini yazmak şiirin 

Bütün imkansızlarını tüketip ömrün 

En yüreklisini yaşamak sevdanın 

Akan mavi kan şiirimin değil 

Kanayan benim yağmur altında 

Deryadan usanmış bir balık gibi

Sonu olmayan yolların yolcusuyum 

Bir ses bekliyorum sadece 

Uyuklarken yorgun otobüs camlarında 

“bu son durağı acının 

İşte güzelim çocuk 

Acıların bittiği yer burası 

İşte burası alın terinin hürriyeti 

Yasak kitaplarımın yeniden yazıldığı şehir 

İşte o yer çocuk, 

Hayallerinin başkenti 

Şiirlerinin yeşile boyanmış memleketi

Bekle beni 

Geleceğim yeniden yazıp öksüz şiirlerimi

Haykıracağım yine güzelliğini 

Bekle beni hayal şehrim...', 'Benim şiirleri yakılmış  Şair çaresizliğim  Her şiir eksilen bir gündür artık ömrümüzden  Her dize bir yaşanmamışlık hikayesi Tüm kapılar ki...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/benim-siirleri-yakilmis-sair-caresizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşmak', 'paylasmak-ahmet-kemaloglu-hjzao', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben neleri paylaştım,

Namustan,silahtan gayrı.

Bırak ben ekmeğimi...

O çakıl taşını.

Bırak ben uçlu cıgaramı,

O ızmarıtı...

Paylaşalım dost gibi,

Paylaşalım arkadaş gibi..

Lakin! 

Ben Ahmet....

Sen....? 

Bırak böyle olsun..

Bırak böyle bitsin..

Dost gibi,

Arkadaş gibi.', 'Ben neleri paylaştım, Namustan,silahtan gayrı. Bırak ben ekmeğimi... O çakıl taşını. Bırak ben uçlu cıgaramı, O ızmarıtı... Paylaşalım dost ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kemaloğlu']::text[], 8.5, '{"poet":"Ahmet Kemaloğlu","poet_slug":"ahmet-kemaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/paylasmak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Oldum Bu Günlerde', 'garip-oldum-bu-gunlerde-melih-coskun-caeow', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir garip oldum bu günlerde 

Üşürken  yüzümde ateş 

Gülerken bile

Müthiş bir keder içimde 

Hiçbir cümlemin sonunu getiremez oldum 

Bütün kelimelerim eksik 

İçimdeki çocuk her zamankinden fazla direniyor dönmek için 

Bir parça olsun insan gibi yaşamak 

Sevmek, gülebilmek 

Ve ağlamak gerektiği yerde 

Günlerim sonbaharda savrulan bir sarı yaprak 

Nerelere götürür şimdi bu deli fırtına beni bilinmez 

İçimdeki çocuk daha da fazla direniyor yaşamak için 

Kavuşmak hak ettiğine 

Karışmadan alın teri gözyaşlarına 

Sular çekildi artık bu denizlerden 

Son kıpırtısını duydum parmaklarımın arasında 

Soluksuz kalmış hayatların

Bir garip oldum son günlerde 

Bitişin hüznümü 

Yoksa başlangıcın heyecanımı anlayamadım

Haksızlıklar çelikten duvarlar gibi dikildi önüme 

Gülümsedim sadece 

Bakıp gözlerinin içine, 

Dedim kendi kendime

Gün gelir başka gemiler yanaşır limana 

Gün gelir bizden yana eser bütün rüzgarlar 

Güçsüz haklı olur bir gün elbet 

Ve bulur karşılığını kuşkusuz 

Karşılıksız sevmek 

Kurtulur zalimin elinden gelecek 

Varır mutlaka tüm geceler sabaha 

İçimdeki çocuk öğrenir 

Ayakta kalmayı hiçbir omuza yaslanmadan 

Ağlamayı yeri geldiği zaman 

Ama asla uzun uzun kanamamayı...', 'Bir garip oldum bu günlerde  Üşürken  yüzümde ateş  Gülerken bile Müthiş bir keder içimde  Hiçbir cümlemin sonunu getiremez oldum  Bütün kel...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/garip-oldum-bu-gunlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Yine Savurmakta Yorgun Bedenimi', 'hayat-yine-savurmakta-yorgun-bedenimi-melih-coskun-q6g6x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat yine savurmakta yorgun bedenimi

Hiç bilmediğim uzak limanlara 

Bu sefer her zamankinden farklı 

Beynimi de götürüyorum beraberimde

Ve beni ben yapan tüm heyecanlarımı 

Tüm şiirlerimi sökerek almak istiyorum

Bütün sokaklarından bu köhnemiş kentin 

Ve bütün sevinçlerimi bitirmeden 

Bu düş teröristi şehir 

Bir karşı eylem gibi gidiyorum buralardan 

Ve başlamadan biten aşklarımı yazarak çatlamış duvarlara

Birkaç yıkık dize bırakarak ardımda...', 'Hayat yine savurmakta yorgun bedenimi Hiç bilmediğim uzak limanlara  Bu sefer her zamankinden farklı  Beynimi de götürüyorum beraberimde Ve ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-yine-savurmakta-yorgun-bedenimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Tüketiyor Günden Güne İyi Çocuklarını', 'hayat-tuketiyor-gunden-gune-i-yi-cocuklarini-melih-coskun-sk1cq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat tüketiyor günden güne iyi çocuklarını 

Türküsüz bir güne dönüyor gökyüzü 

Her gün biraz daha karşılıksız kalıyor sevmelerim 

Saklayamaz oluyor artık yüzüm solukluğunu 

Alın terim 

Can suyum 

Güzel çocuk 

Ne olur çevirme yüzünü ötelere 

Sensiz sahipsiz kalır acılarım,

Günden güne daha da çoğalıyor omuzlarında

İnsan olmanın ağırlığı 

Ve sadece iyi çocuklarını böyle hırpalar hayat.

Şarkılarda kalmayacak kadar gerçektir 

Güzellikten yanmak 

Ve bunun için garip bir haz duymak... 

(İnanmak; 

Gerçekten de inanmak mıdır? 

Bedelini göze almamışsan.)', 'Hayat tüketiyor günden güne iyi çocuklarını  Türküsüz bir güne dönüyor gökyüzü  Her gün biraz daha karşılıksız kalıyor sevmelerim  Saklayama...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayat-tuketiyor-gunden-gune-iyi-cocuklarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-onur-hanic-2uhbv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Konuşamıyorduk daha

İlk Kandırıldığımızda

Belki de 

konuşmayalım diye 

hiç

Sahte memeler tıktılar

Ağzımıza', 'Konuşamıyorduk daha İlk Kandırıldığımızda Belki de  konuşmayalım diye  hiç Sahte memeler tıktılar Ağzımıza...', ARRAY['Türk Edebiyatı','Şiir','Onur Haniç']::text[], 8.5, '{"poet":"Onur Haniç","poet_slug":"onur-hanic","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalan-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç Değil Fidandım', 'agac-degil-fidandim-melih-coskun-z7km9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağaç değil fidandım 

Bükülmedim kırıldım 

Yaralandım 

Gizli gizli kanadım gecelerce

Kimseye anlatamadım 

Hiçbir yara acımazdı ilk anında 

Zaman geçtikçe anladım 

İnfazlara yenik düştü en güzel düşüm 

Morarmış bir urgan izi boğazımı saran 

Aşkın bayrağına sar 

Gel göm beni kendi topraklarına...', 'Ağaç değil fidandım  Bükülmedim kırıldım  Yaralandım  Gizli gizli kanadım gecelerce Kimseye anlatamadım  Hiçbir yara acımazdı ilk anında  Za...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/agac-degil-fidandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ressam', 'ressam-i-smail-ari-xc6rc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşık gözünü yumar

Ve işte süzülür bir gözyaşı

Acele eder kavuşmak için yâre

Lâkin kara toprak girer araya

Çeker gözyaşını karanlığa

Bitti herşey derken

Şahlanır bir anda kara toprak

Ve yarılır ortasından

Önce gözyaşı çıkar

Ardından da baharın müjdecisi renkler

Herşeyi çizer aşık

Ama içinde bir boşluk kalır:

Toplasa da baharın bütün renklerini

Korkar, çizemez aşık elâ gözlerini', 'Aşık gözünü yumar Ve işte süzülür bir gözyaşı Acele eder kavuşmak için yâre Lâkin kara toprak girer araya Çeker gözyaşını karanlığa Bitti he...', ARRAY['Türk Edebiyatı','Şiir','İsmail Arı']::text[], 8.5, '{"poet":"İsmail Arı","poet_slug":"i-smail-ari","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ressam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığında', 'ay-isiginda-i-brahim-ethem-bingul-ttk07', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul gözlerimin içine bakıyor

Ben İstanbul''un güzelliğine

Hava soğuk delice

İnceden kar yağıyor güzelim şehrime

Gökkuşağı, ay ışığında dans ediyor

O da ne! 

Yoksa gönlümün neşesi mi vuruyor

Gözlerimin görüşüne', 'İstanbul gözlerimin içine bakıyor Ben İstanbul''un güzelliğine Hava soğuk delice İnceden kar yağıyor güzelim şehrime Gökkuşağı, ay ışığında d...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ay-isiginda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke..', 'keske-hasan-basri-kale-ecwd1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güllerim soldu.

Açmasalardı keşke.! 

Umutlar da bitti sonunda

Doğmasalardı keşke.! 

Bulmasaydım seni keşke; 

Bir gün kaybetmekse kaderim..

Sensizlik bir kor gibi

çöktü içime eyy yar..! 

Aşkın bittiği yerde

ahhh..ölmek olmasaydı..

Keşke..!', 'Güllerim soldu. Açmasalardı keşke.!  Umutlar da bitti sonunda Doğmasalardı keşke.!  Bulmasaydım seni keşke;  Bir gün kaybetmekse kaderim.. S...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/keske-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir', 'bir-siir-zafer-zengin-etnika-thv48', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Şiir

bırakıp

gitsem sana,

büyütürmüsün! 

gülen gözlerinle...

21 subat 2004', 'Bir Şiir bırakıp gitsem sana, büyütürmüsün!  gülen gözlerinle... 21 subat 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-siir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Dörtlükler III', 'yeni-dortlukler-iii-ahmet-aksoy-rjks3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Otomasyon

nereye baksak bilinçlerimiz uyutuluyor

sanki hissettiren hissedeni hipnoz ediyor

nereye baksak makineleşmiş duyumsamalar

ruhları hep aynı çarkın dişleri kemiriyor

Şimendifer

ben bir buruk şimendifer

nereye kadar nereye kadar

ardıma takmış gidiyorum anıları

tabiki kömür bitene kadar

Bumerang

yine bir bumerang gibi fırlattım adımı 

döndü dolaştı bütün dünyayı bana kaldı

sade bir isim yaşatır mı insanı,yoksa

öldürür mü bir mezar taşına yazılınca.

Dönüşünde

dön yine geçmişe, sonra dur inan bana

ah canım öyle bir saracağımki seni

bir daha gidemeyeceksin karanlığa

hapisanen olacak kalbim kapanarak

Paradoks VI

zekalarımızla ördüğümüz mesafe duvarları

aramızda sevgi ayırıcıları gibi yükselirken

düşünmez miyiz bir kez olsun kandırıldığımızı

bizler birbirimizden uzakta mutsuzluğa düşerken.', 'Otomasyon nereye baksak bilinçlerimiz uyutuluyor sanki hissettiren hissedeni hipnoz ediyor nereye baksak makineleşmiş duyumsamalar ruhları h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yeni-dortlukler-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmansız Şarkılar', 'i-mansiz-sarkilar-zafer-zengin-etnika-uakh2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İmansız Şarkılar

Çalıyor 

içimde,

salıyorum

kendimi

deliliğin 

içine,

şiirlerin

döşüne...

şiir oluyorsun gece vakti

yeni

uyanmış

gözlerimde..

21 subat 2004', 'İmansız Şarkılar Çalıyor  içimde, salıyorum kendimi deliliğin  içine, şiirlerin döşüne... şiir oluyorsun gece vakti yeni uyanmış gözlerimde....', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/imansiz-sarkilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sevdim', 'seni-sevdim-ercan-otaci-nl49x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevdim

Cicekli yaprakli daluclarini

Mor daglarin yamaclarini

Seyreder gibi

Seni sevdim

Otelere meyleder gibi

Hayalin bir gul gibi duserken icimdeki ucurumlara

Seni sevdim

Olur gibi yasamalara', 'Seni sevdim Cicekli yaprakli daluclarini Mor daglarin yamaclarini Seyreder gibi Seni sevdim Otelere meyleder gibi Hayalin bir gul gibi duser...', ARRAY['Türk Edebiyatı','Şiir','Ercan Otaci']::text[], 8.5, '{"poet":"Ercan Otaci","poet_slug":"ercan-otaci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-sevdim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini Kapadığında', 'gozlerini-kapadiginda-zafer-zengin-etnika-l3ipl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benden

saklandığını

gözlerini

ellerinle

kapadığında anladım..

ben de

sana

iki 

parmağımın

arasından

baktım...

yalnızdım...

yalnızdın...

21 subat 2004', 'benden saklandığını gözlerini ellerinle kapadığında anladım.. ben de sana iki  parmağımın arasından baktım... yalnızdım... yalnızdın... 21 s...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerini-kapadiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak seslerim', 'ayak-seslerim-ercan-otaci-kb785', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herkes gider biz kaliriz burada

Bir gece,bir sanci,birde yuregim

Bir kanli cesettir golgem duvarda

Bir cocuk sesidir ayak seslerim', 'Herkes gider biz kaliriz burada Bir gece,bir sanci,birde yuregim Bir kanli cesettir golgem duvarda Bir cocuk sesidir ayak seslerim...', ARRAY['Türk Edebiyatı','Şiir','Ercan Otaci']::text[], 8.5, '{"poet":"Ercan Otaci","poet_slug":"ercan-otaci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayak-seslerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen hiç', 'sen-hic-zafer-zengin-etnika-nho3g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen hiç

benim

sevdiğim

şarkıları

sevdin mi! 

Minikti

sevdiğim 

şarkılar

mavi

bir

kedi

gibi..

hüzünlü...

ve

sevimli...

Sen

hiç

beni

sevdin mi! 

Mavi

bir

kedi

gibi...

Saçlarım sarı, minik ellerim,kahverengi gözlerim benimdi...

21 subat 2004', 'Sen hiç benim sevdiğim şarkıları sevdin mi!  Minikti sevdiğim  şarkılar mavi bir kedi gibi.. hüzünlü... ve sevimli... Sen hiç beni sevdin mi...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-hic-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Besinci mevsim', 'besinci-mevsim-ercan-otaci-tpxr4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazgim sen degilsen sonumdan once

Askindan gecmekten cok korkuyorum

Gozlerin yaktigi yere dusunce

Agzimi acmaktan cok korkuyorum

Bende hazan sende kavak yelleri

Bolusmek ne mumkun toz pembeleri

Saci ak gozu yas ihtimalleri

Ufkuna sacmaktan cok korkuyorum

Sen ne bir adressin sen ne bir isim

Sen tutsak bir hayal yasak bir resim

Sen hic yasanmamis besinci mevsim

Ben sana gocmekten cok korkuyorum', 'Yazgim sen degilsen sonumdan once Askindan gecmekten cok korkuyorum Gozlerin yaktigi yere dusunce Agzimi acmaktan cok korkuyorum Bende hazan...', ARRAY['Türk Edebiyatı','Şiir','Ercan Otaci']::text[], 8.5, '{"poet":"Ercan Otaci","poet_slug":"ercan-otaci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/besinci-mevsim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonullu yasaklar', 'gonullu-yasaklar-ercan-otaci-gpv0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalip dalip gidiyor

Gozlerim uzaklara

Daha yeni anladim

Yurek tasidigimi

Dusunce duygularim

Gonullu yasaklara', 'Dalip dalip gidiyor Gozlerim uzaklara Daha yeni anladim Yurek tasidigimi Dusunce duygularim Gonullu yasaklara...', ARRAY['Türk Edebiyatı','Şiir','Ercan Otaci']::text[], 8.5, '{"poet":"Ercan Otaci","poet_slug":"ercan-otaci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gonullu-yasaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli Benli', 'senli-benli-zafer-zengin-etnika-zdcxk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir 

sen,

Bir 

ben,

varız,

Bakarmısın! 

Dünya

ne 

kadar

yalnız...

İki

başımıza,

bir

dünyayız...

senli benliyiz, dünyamızla, yalnızlığımızla...

21 subat 2004', 'Bir  sen, Bir  ben, varız, Bakarmısın!  Dünya ne  kadar yalnız... İki başımıza, bir dünyayız... senli benliyiz, dünyamızla, yalnızlığımızla....', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senli-benli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iki adam', 'iki-adam-ercan-otaci-1beiz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Iki adam iki baba yuruyoruz

Yuruyoruz yol yakisiyor

Agzimiz burnumuza 

Yuzumuz gozumuze

Ne giysek ustumuze yakisiyor

Amma bu dert  ah bu dert hic yakismiyor

Duruyoruz sehrin bir yakasinda

Sanki bir pustun yakasinda

Kan kirmizi iki karanfil

Iki adam 

Iki baba...', 'Iki adam iki baba yuruyoruz Yuruyoruz yol yakisiyor Agzimiz burnumuza  Yuzumuz gozumuze Ne giysek ustumuze yakisiyor Amma bu dert  ah bu der...', ARRAY['Türk Edebiyatı','Şiir','Ercan Otaci']::text[], 8.5, '{"poet":"Ercan Otaci","poet_slug":"ercan-otaci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iki-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-ercan-otaci-59ugg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Iki yetim yavrusuyum babamin

Babam ruzgar

Babam gokyuzu

Ben babami avutacak kadar buyugum

Babam bensiz olamayacak kadar kucuk

Bir yani hep kahir

Bir yani hep tebessum babamin

En yeni gulusleri ogrendim ondan

En eski turkuleri

En derin sulari gormek mumkundu

En uzak guzellikleri 

Ta yerden cennete kadar guzeldi

Kizdiginda bile gozleri

Adim kerim

Adim asli

Iki minik yavrusuyuz babamin

Kus yuvasi kalbinde', 'Iki yetim yavrusuyum babamin Babam ruzgar Babam gokyuzu Ben babami avutacak kadar buyugum Babam bensiz olamayacak kadar kucuk Bir yani hep k...', ARRAY['Türk Edebiyatı','Şiir','Ercan Otaci']::text[], 8.5, '{"poet":"Ercan Otaci","poet_slug":"ercan-otaci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/babam-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medine', 'medine-ercan-otaci-laxdd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akreplere biraktim simdi hicranlarimi

Bir hayat kokluyorum gonul tepelerinden

Adin merve olsun adin medine...

Bir golge gibi gectim kanli harabelerden

Canimi dislerime taktigim gunden beri

Kan damladi icimin mercan kadehlerinden

Sana nasil baktigimi bir kerecik gorseydin

Bir kerecik medine

Oksuz kirpiklerimden.

Yuregimi yedirme vahsi kedilerine

Kahreden bir nazarmi sendeki haramiler

Bende yildim hulyani sinemde tasimaktan

Seni gormeden yandi iman yuklu gemiler

Sende olmek telasi biktirdi yasamaktan

Benki senin yolunda sevdali kara cali

Sahra gozlerinde surunuyorum

Cek artik onumden firtinalari

Medine

Sana yoneliyorum

Yuregimi yedirme kirli kedilerine', 'Akreplere biraktim simdi hicranlarimi Bir hayat kokluyorum gonul tepelerinden Adin merve olsun adin medine... Bir golge gibi gectim kanli ha...', ARRAY['Türk Edebiyatı','Şiir','Ercan Otaci']::text[], 8.5, '{"poet":"Ercan Otaci","poet_slug":"ercan-otaci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/medine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ek Dörtlükler I', 'ek-dortlukler-i-ahmet-aksoy-h660y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Paradoks V

ey sönük med cezir

.....kırık dökük imge

neden yanıltırsın usları

.....bir gelecekde.

Varlık

var mıyım yok muyum

...........bilki ölmüşüm

ama bilmiyorum 

var mıyım yok muyum

Günah

hiç bir ateş yakmadı

senin beni yaktığın gibi

ey umarsız günah

keşke sen olmasaydın

Kumsala Saçılmış Taşlar Gibiyim

kumsala saçılmış taşlar gibiyim darmadağınık

sanki kopmuş hücrelerim dağılmış sahile

oysa toplanıp dört satıra sığmalıyım

yoksa sensizlikte izsiz parçalanacağım', 'Paradoks V ey sönük med cezir .....kırık dökük imge neden yanıltırsın usları .....bir gelecekde. Varlık var mıyım yok muyum ...........bilki...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ek-dortlukler-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ek Dörtlükler II', 'ek-dortlukler-ii-ahmet-aksoy-ofjsi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aort

zamanın küstah bakışları altında

onurlu adam yaşayan adam

ki her ölen kendi kavminde

onursal başkan.

Geçer Geçmez

her biten mum gibi bir gün ömrümde bitecek 

ve kimbilir ne kalacak benden geri 

söylenmiş sözlerden başka, ki içimdeki

en büyük çelişkidir sözcüklerin anlamsızlığı

Andımdır Adın

bir gün unutacak yağmur damlalarını

bir gün unutacak analar doğurdukları canlarını

ve bir gün unutacak aşk varlığını

ama ben unutmayacağım andımı

Hınç

önce kan otursun gözlerine sonra 

kırmızıdan siyaha çal! kör olusun ufkun 

son kez uğra yanıma el yordamıyla 

tutun omuzuma gözlerim senin olsun

Külce

kül süzülüyor doğduğunda

terk ediyor cinayet mahlaini

belki de bildiğinden kabahatini

kaçıyor yananın sorumluğundan', 'Aort zamanın küstah bakışları altında onurlu adam yaşayan adam ki her ölen kendi kavminde onursal başkan. Geçer Geçmez her biten mum gibi bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ek-dortlukler-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ek Dörtlükler III', 'ek-dortlukler-iii-ahmet-aksoy-3p2c9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daimi aşk

aşkları çirkinleştiren

zaman, aslında göçmese

vuslat saatlerinde,

hiç ayrılık, olmayacak

Bence

gölgem dumandır benim

çünkü hep yanar varlığım

bu yüzden durağan olamam

ve er geç olacağıma varırım

Herşeyime

sana her şeyim diyorum ve hiçbir şeyle 

sınırlamıyorum. sende aklına ne gelirse 

koy içine. nasıl istiyorsan öyle olsun,

yüzünü ak çıkartmazsam taş olayım

Işık

gecenin uyku sarhoşluğunda

zihne düşen kırılgan fikir

taşır mı taşımaz mı mahmur

yorgunluğun ağırlığını

Mübremdir Aydınlık

küstah sabahların gecesi

belki sen bilmezsin ve 

kızarsın ama ben bilirim 

aydınlık güneşin kıymetini', 'Daimi aşk aşkları çirkinleştiren zaman, aslında göçmese vuslat saatlerinde, hiç ayrılık, olmayacak Bence gölgem dumandır benim çünkü hep yan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ek-dortlukler-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrim', 'devrim-ahmet-aksoy-um22e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...........''hız içinde tüketiyoruz yavaşlıklarımızı''

bugün düştüğümüz yerden kalkmalıyız

çünkü kehanette yol açık, 

hazırsak; geç gelinmiş bir tren kırgınlığında

başlıyor karabasanlarla raksımız.

ah budapeşte köprüsünde bir yetim gibi

geçiyor zamanlarımız,

tutsak alırken zihinlerimizde kendimizi

kırçıllaşıyor umutlarımız.

işte devrim! hazırsak tükeniyoruz,hooooop! 

hep birlikte el ele verip yerin dibine değiyoruz.

sonra, sonra birimiz yükselecek.

işte kehanetin özü; biri çıkarken iner diğerleri,

öyleyse çemkirmek yok,

timsahlar ağlamaz bunlar kurpiyer gözyaşları.', '...........''hız içinde tüketiyoruz yavaşlıklarımızı'' bugün düştüğümüz yerden kalkmalıyız çünkü kehanette yol açık,  hazırsak; geç gelinmiş b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/devrim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki Sen..', 'bendeki-sen-hasan-basri-kale-65kpn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben ben değilim..

Ama ben sen olabilirim..

tepeden tırnağa

Seni bende görürsün her an.

Yakına da baksan

Baksan da uzağa..

Ben sen olurum karşında..

Sendeki ben de..seni görür

Bana özlemle 

her bakışında..

Yıldızlardan tac

yaparım başına..

Hüzünlerine de

garip gönlümden ilac..

Sendeki bana bir bak.

Görmüyor musun.? 

İliklerine kadar sana muhtac..!', 'Ben ben değilim.. Ama ben sen olabilirim.. tepeden tırnağa Seni bende görürsün her an. Yakına da baksan Baksan da uzağa.. Ben sen olurum kar...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bendeki-sen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harun', 'harun-ali-arslan-a1q83', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün Harun’u (*) 

kaybettik! 

Kanserdi.

Paslı tel örgülerden miras.

Bir kolsuz

Gitti...

Gencecikti,

diğerlerinden farksız.

Karanlığın perdesini araladığımız

günlerde ışıktı! 

Sönmedi! 

Sene

On Beş Ağustos

Bin Dokuz Yüz Yetmiş Beş ti...

____________________________________________

(*) Harun Karadeniz. İnşaat Y. Mühendisi (İTÜ)

68 Kuşağının engin bir muhakeme ve hitabet gücüne sahip, sağduyulu ve yürekli bir öğrenci lideriydi.    Yukarıdaki dizeler, onun ölümünü öğrenince İstanbul''a dönerken, Yalova- İstanbul Arabalı vapurunda yazılmıştır.', 'Bugün Harun’u (*)  kaybettik!  Kanserdi. Paslı tel örgülerden miras. Bir kolsuz Gitti... Gencecikti, diğerlerinden farksız. Karanlığın perde...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olumunun-ardindan-yillar-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Anahtarı', 'yurek-anahtari-zafer-zengin-etnika-isbws', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canım; 

anahtar 

bıraktım 

sana

paspasın

altına 

baksana! 

Gözlerini

aç

Yürek

Anahtarı

mısraların

arasında

Sen

bulasın 

diye 

dedim

paspasın altında..gözlerini açsana..bulursan..kimseye söyleme ha......! 

21 Subat 2004  03.50', 'Canım;  anahtar  bıraktım  sana paspasın altına  baksana!  Gözlerini aç Yürek Anahtarı mısraların arasında Sen bulasın  diye  dedim paspasın...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yurek-anahtari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk..', 'ask-ahmet-kemaloglu-iowxh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk dediğin…

Ne yirmi santimlik bir zurna..

Ne minik bir şeftali..

Aşk..sonsuzluk..

Aşk..:

Koca bir dünya…', 'Aşk dediğin… Ne yirmi santimlik bir zurna.. Ne minik bir şeftali.. Aşk..sonsuzluk.. Aşk..: Koca bir dünya…...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kemaloğlu']::text[], 8.5, '{"poet":"Ahmet Kemaloğlu","poet_slug":"ahmet-kemaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-211-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarifim.', 'tarifim-ahmet-kemaloglu-7695q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Esasen,

Üstün meziyetlerim yok benim…

Zekam da çok gelişkin değil.

Kemalede ermiş sayılmam..

Ama! 

Samimi, gülen  gözlerim..

Düşünen bir beynim..

Daima açık ellerim..

Ve…

Sevgiyi seven sıcacık yüreğim var.', 'Esasen, Üstün meziyetlerim yok benim… Zekam da çok gelişkin değil. Kemalede ermiş sayılmam.. Ama!  Samimi, gülen  gözlerim.. Düşünen bir bey...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kemaloğlu']::text[], 8.5, '{"poet":"Ahmet Kemaloğlu","poet_slug":"ahmet-kemaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tarifim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Sen', 'ah-sen-egemen-bilgin-fxpmr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceleri başımı yastığa koyduğum vakit

Sen gelirsin aklıma apansız.

Senin için ve diğer tüm sevdiklerim için

Dua mırıldanırım sessizce.

Sonra da senli rüyalara dalarım

Sensiz karanlik gecelerde.

Hasretinle kavrulduğum soğuk kış gecelerinde

Yorgan yaparım sana kavuşma hayalimi

Sererim üstüme,

Sırf sana hasret ölmeyeyim diye...', 'Geceleri başımı yastığa koyduğum vakit Sen gelirsin aklıma apansız. Senin için ve diğer tüm sevdiklerim için Dua mırıldanırım sessizce. Sonr...', ARRAY['Türk Edebiyatı','Şiir','Egemen Bilgin']::text[], 8.5, '{"poet":"Egemen Bilgin","poet_slug":"egemen-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ah-sen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki-2-*', 'i-yi-ki-2-bayram-tunca-aaklk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İyi ki iyi kötü bir işim var 

İyi ki böylesi bir eşim var 

Sağda/solda, benim ne işim var 

Ne ararsam helal dairesinde var 

İşsizlere/güçsüzlere dünya olur dar 

Tâ arşa yükselir içlerindeki ah u zar 

Çaresizlikten kalpleri yanar har har 

Çünkü, günümüzde geçim derdi var 

18.02.2004-18.02', 'İyi ki iyi kötü bir işim var  İyi ki böylesi bir eşim var  Sağda/solda, benim ne işim var  Ne ararsam helal dairesinde var  İşsizlere/güçsüz...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iyi-ki-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harami', 'harami-tevfik-mengulluoglu-0eb9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşin güzelliğine bak,

kim çaldı bu günü Ağustostan? 

hemde en güzelini,çalmışlar

Senin doğduğun güne benziyor daha çok

tıpkı sen...

Senmisin yoksa çalan? 

Bırakma öyle ellerime,

şiirimin dili tutulur,

buz gibi olur çocukluğum,

bir titreme tutar düşlerimi,

biliyorum aşkımsın,çocukluğumsun daha çok

Gençliğinim,özlemlerim,kavgalarım,

hepsi sende biliyorum.

Bunların ötesinde,kimsin sen? 

Kimin güzelliği,Bu gözlerindeki? 

Kim gördü özlemlerini? 

Söylemeseydin adını kuşlara,

Sümbülüm,akzambağım,deseydin 

bozkırlarda yetişen,

bana baksaydın,daha çok.

Mülteci olsaydın gözlerimde; 

bırak öylece dursun,maviler,

deniz mavisi,gök mavisi,dokunma onlara,

dengesi bozulur beynimin...

bir kaygı dolanır, saçlarıma

tanıyamazsın bu halimi,

güneşin nabzı atmaya başlar avuçlarımda,

yüz defa aşık olurum sana

Sulu sepken  bir özlem ıslatır her yanımı,

bakar bakar tanıyamam seni

ufkumun boşluğunda yuvarlanır,

ellerine tutulurum yine.', 'Güneşin güzelliğine bak, kim çaldı bu günü Ağustostan?  hemde en güzelini,çalmışlar Senin doğduğun güne benziyor daha çok tıpkı sen... Senmi...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/harami-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfır Atmak Kolaysa.', 'sifir-atmak-kolaysa-adnan-ferit-1hc77', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllarımızı zehir ederek eklediğiniz sıfırları

Atıyorsunuz kolayca liranın arkasından.

Bir sıfırda,

Ruhumuzda hasar 

Tenimizde derin çizgiler bıraktırdığınız

Yaşımızdan da  atsanıza.', 'Yıllarımızı zehir ederek eklediğiniz sıfırları Atıyorsunuz kolayca liranın arkasından. Bir sıfırda, Ruhumuzda hasar  Tenimizde derin çizgile...', ARRAY['Türk Edebiyatı','Şiir','Adnan Ferit']::text[], 8.5, '{"poet":"Adnan Ferit","poet_slug":"adnan-ferit","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sifir-atmak-kolaysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı geçmeden', 'zamani-gecmeden-kubilay-enginol-k0yxk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimde açan çiçekleri

Topla istersen

Renklerin adını sen koy

Ne renk görürsen

Sevgi çiçeklerine iyi bak

Hepsi senin

Bunları sen suladın senin eserin

Kimi zaman sevginden

Kimi zaman pınarlarından suladın

Kopan fırtınalardan korudun

Besledin melteminle

Yüreğimde açan çiçekleri

Topla istersen

Topla,zamanı geçmeden', 'Yüreğimde açan çiçekleri Topla istersen Renklerin adını sen koy Ne renk görürsen Sevgi çiçeklerine iyi bak Hepsi senin Bunları sen suladın s...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zamani-gecmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah', 'sabah-zafer-zengin-etnika-hwbu1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahlarıma

akdeniz 

gibisin

..

Mutlu

oluyorum

maviliğinle

..

Bir

Gülümse

Sessizliğime

..

Saklanmasın

gövdem

düşeyim

güllerinin içine

..

gelip kokla

nasıl yaman,yaz yanıklarım,dirhem dirhem melhem ol..senle yanan yüreğime.

21 subat 2004', 'Sabahlarıma akdeniz  gibisin .. Mutlu oluyorum maviliğinle .. Bir Gülümse Sessizliğime .. Saklanmasın gövdem düşeyim güllerinin içine .. gel...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sabah-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitapsız Şiirler', 'kitapsiz-siirler-zulfikar-yapar-kaleli-nc5dj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eyvah! Ruhumu kemirirler, beynimi yerler,

Bu ruhsuz, merhametsiz, bu kitapsız şiirler.', 'Eyvah! Ruhumu kemirirler, beynimi yerler, Bu ruhsuz, merhametsiz, bu kitapsız şiirler....', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/aa-kitapsiz-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ol Sevdiğim', 'sen-ol-sevdigim-alaettin-isik-0tr72', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen olunca bahar olur, yaz olur..

Yüreğimde çiçekler  açar önce,

Sonra sevgilere koşarım senle,

Ben bende değilim artık hep sende..

İstediğin yağmur kokan düşler mi,

Ya bir de gerçek sevişler? 

Ardından deniz kokan sevinçler

Ve armağanım  soluksuz öpüşler..

Yeter ki sen ol, sevdiğim SEN,

Ne kadar sevdiğimi bir bilsen..

Benim doğduğum yerlerde ol,

Sevincim ol, kaderim ol benim ol..

20/02/2004', 'Sen olunca bahar olur, yaz olur.. Yüreğimde çiçekler  açar önce, Sonra sevgilere koşarım senle, Ben bende değilim artık hep sende.. İstediği...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-ol-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Kurtlar Sofrası...', 'kurtlar-sofrasi-naime-erlacin-qbvyr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '”Güçlüdür ve insafsız,

kurtların hayatı 

ve bizim hayatımız” 

(Carl Zuckmayer - “Kurtlar” şiirinden…)    

inikti perde

uzanıyordu eller

tutunamıyordum

kurt sürüsüydü acı

vahşi ve parçalayıcı

deri değiştiriyordum durmaksızın

ağrı ateş ve küller

sonra yeniden o acayip döngü

ödemekle bitmiyor hesap

tespih dayanmıyordu 

şafağı özledim geceler boyu

perdenin kalkışını 

ışık tutuşunu yüzümün

uzandım boylu boyunca taşlara 

hayat zor ve soğuk

yol uzuyor

uzuyordu

yaşanması gereken 

hayata dair acılardan biri işte

aydınlığı sevmek 

karanlığı bilmekle oluyor zahir 

yalnızlıkta büyüyor ışık

içimizdeki sancı siyahı geçtikten sonra 

kurtlar sofrasında bile insan

kaderinin bekçisi kendi kapısında

(21 Şubat 2004)', '”Güçlüdür ve insafsız, kurtların hayatı  ve bizim hayatımız”  (Carl Zuckmayer - “Kurtlar” şiirinden…)     inikti perde uzanıyordu eller tutu...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kurtlar-sofrasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takoz', 'takoz-hizir-azakli-s3ofa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Takoz

Be hey! ! hamakat zevat,

        … pösteki saydıran zat,

İster anayasayı, ister yasayı fırlat 

“ % 50’miz aç

ölü derilerimiz çatlak” 

       kurak bir toprağın 

bir damla suya hasreti kadar

          umuda muhtaç.

              ve  üzerinde umudun yeşeremediği,

               ve açlığın kıtlıktan geberdiği 

dört mevsim toprak, 

 ve “baştan başa

emperyalizmin

     talim meydanı olan memleket! ” 

duran,

dibe vuran 

               bu memleket.

                  …bizim memleketimiz! 

ve biz, 

omuz omuza direnirken,

“talan var! 

    yağmalanan var! ” derken,

                          haykırırken! ! 

Bir avuç şarlatan, bir avuç yılan,

Fırtına yarattı, tabu yarattı,

Gücü tutan ile, gündemi tutan! 

Soyduran pezevenk, soyan kavattı.

Konjonktürü saygın, zevata uyup,

Hakkı mahkûm etti, hukuku sattı,

Sevgiyi, şefkati, aşkı, uyutup,

Sarhoş sofrasında bebek oynattı

Be hey! anlamsız surat,

            … pösteki saydıran zat,

İster anayasayı, ister yasayı fırlat.

“ % 50’miz aç

ölü derilerimiz çatlak” 

               ve açlığın kıtlıktan geberdiği 

“dört mevsim toprak…

memleketimin son karış toprağında

“kardeşlerimin

                 vebalı,

                        sarı

                               karınları

sinekli et parçaları gibi sürünürken; ”

sen,

“Tarihsel, sosyal, ekonomik şartların

                         zaruri neticesidir bu! ”

                               diyemezsin! 

dersen; 

biz, 

hepimiz,

hep bir ağızdan

        beklemeden

                 hemen 

                  cevap veririz.

“Demokrasi: üretimdir, verimdir,

Yaşamaktır hep beraber, bire bir…

Elit demek, yetke demek, baş demek, 

İvmedir, momenttir, ahenk demektir.”

Be hey! takoz, hamakat 

         … pösteki saydıran zat,

İster anayasayı, ister yasayı fırlat.

geçmişe bir göz at, 

Birisi fötrlü zat, 

birisi de şapkalı, 

  ve de  “onların yağlı dostları

                   gıdığı sarkmış dostları,

                         eli şampanyalı, 

başı külahlı, beli silahlı dostları.”

                                 …malum zevat.

şu harabat, onlardan.

                   … bu zevat da onlardandı…                                

onlar başımıza, 

bir baş oldukları, 

bir baş belası oldukları

                             andan beri

hiç değişmedi memleketin kaderi…

bazen soldan budandı,

              bazen sağdan budandı.

       bu zevat da budayanlardandı,

       her birisini iyi tanır.

vardır her birisinin her bir kuruştan haberi… 

“yüz iki milyar dolar…”

              insan olan utanır be utanır… 

-Adalet dediğin, hukuk dediğin 

Keyfiyet değildir, hakkaniyettir.

Sindiremediğin o direndiğin; 

Halkın iradesi, halka diyettir! 

Be hey! Yüzde yüz inat,

        … pösteki saydıran zat, 

İster anayasayı, ister yasayı fırlat.

Beni dinle,

kalk,

husumeti bırak,

geçmişi sorgulayarak

- “çıkar

göğsünün kafesinden yüreğini; 

şu güneşten 

            düşen 

               ateşe fırlat; 

yüreğini yüreklerimizin yanına  at! ”

birlik var,

seferberlik var.

gerildi çengeli yıldızlara takılan yaylar

          …gemilerimizi yaktık,

     zaman az.

     bu enkaz 

           kaldırılacak,

           yeniden yapılandırılacaktır.

                          bir takoz gibi durma! 

                                -duramazsın! ! 

                    …bu kervanı durdurmazsın…

Her gün içindeyiz, her an zindeyiz. 

Antroposantrizmin merkezindeyiz,

Tanrı’nın en çağdaş en son mesajı,

Çelişki bilmeyiz, boşluk bilmeyiz

H. Azaklıhoca', 'Takoz Be hey! ! hamakat zevat,         … pösteki saydıran zat, İster anayasayı, ister yasayı fırlat  “ % 50’miz aç ölü derilerimiz çatlak”  ...', ARRAY['Türk Edebiyatı','Şiir','Hızır Azaklı']::text[], 8.5, '{"poet":"Hızır Azaklı","poet_slug":"hizir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":118,"source_url":"https://www.antoloji.com/takoz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Mavi...', 'suskun-mavi-baki-son-vtnny', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yılarsa bir gün, 

En güçlüleri. 

Bütün yolcuları, inerse 

Bu didinmenin. 

Terkedilmiş, bir boşlukta 

Tek başıma, 

Uğraşmak bıkkınlığı 

Yığılır üzerime. 

Güven duyduğum, doğrular, 

Yıkılır... 

İnsanlar... 

Benim dostlarım, 

Üşürse 

Ellerim bir gün, 

Yarı gölgelerde, 

Tek başıma kalıverirsem. 

Güçsüz yangelişlere, 

Saparsa herkez. 

Bu kadar yükü çekemem. 

Bilin... 

Ezilir, kaybolursam, 

Susmuşluğumda... 

Beni affedin...!', 'Yılarsa bir gün,  En güçlüleri.  Bütün yolcuları, inerse  Bu didinmenin.  Terkedilmiş, bir boşlukta  Tek başıma,  Uğraşmak bıkkınlığı  Yığıl...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/suskun-mavi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sigara Kadar…', 'bir-sigara-kadar-ensar-aktas-vimn2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sigara kadar değerim yok mu senin gözünde

Acemi tiryakiler gibi çekip çekip üflüyorsun

Beş dakika olsun tutamıyorsun ciğerlerinde

Dumanım rüzgarla bir yok oluyor gökyüzünde

Küllerim yerlerde, izmaritimi çiğneyip duruyorsun

Bir parça nikotin lekesinden farksızım dişlerinde

Kurtulmak için sabah akşam hep fırçalıyorsun

Oysa ben kök salmak isterdim mavi düşlerinde

Alabora olmak, kaybolmak isterdim gülüşlerinde

Sense beni eşine dostuna haybeden dağıtıyorsun

Sevmediğin bir şeyi neden saat başı öpüp kokluyorsun

İçine çekip çekip ''tek dert ortağı'' muamelesi yapıyorsun

Yok seviyorum diyorsan, niçin yakıp yakıp kül ediyorsun

Sahiden kurtulmak istiyorsan benden, a hazan gülüm

Hadi sıyrıl da parmaklarının arasından gelsin ölüm 

Nasılsa bir tütün bahçesinde yeniden serpilir köküm

Rotterdam, 25.01.2004', 'Bir sigara kadar değerim yok mu senin gözünde Acemi tiryakiler gibi çekip çekip üflüyorsun Beş dakika olsun tutamıyorsun ciğerlerinde Dumanı...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-sigara-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlama', 'kutlama-abdulsamet-gokhan-f7w2y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaf dağının sevgilisi

Dayanılmazlığın zirvesi

Bugün doğum günün

Unuttuğumu sanmayasın

Yirmidördün kutlu olsun...', 'Kaf dağının sevgilisi Dayanılmazlığın zirvesi Bugün doğum günün Unuttuğumu sanmayasın Yirmidördün kutlu olsun......', ARRAY['Türk Edebiyatı','Şiir','Abdülsamet Gökhan']::text[], 8.5, '{"poet":"Abdülsamet Gökhan","poet_slug":"abdulsamet-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kutlama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söze Biat', 'soze-biat-naime-erlacin-g3odj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- söz’le suç ortaklığıdır yazmak-

sözün kölesiyim 

suçuma bile beni 

ey söz! 

hiçten tutarım yolu

tefekkürde çakar şimşeğim

var oluşun 

ışığına doğru

âheste giderim

kıldan incedir boynum

izimin izinde ancak

izimi 

sözle bulurum

sözle bir suç ortaklığıdır

tek dileğim 

(21 Şubat 2004)       

(*)      Sevgili Ayşe Keskin''e sonsuz  teşekkürlerimle :)))', '- söz’le suç ortaklığıdır yazmak- sözün kölesiyim  suçuma bile beni  ey söz!  hiçten tutarım yolu tefekkürde çakar şimşeğim var oluşun  ışığ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soze-biat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık Suskun', 'i-nsanlik-suskun-halil-manap-6wkk6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeni bir yaşama on kala

Düşün kentler yıkık

Çiçekler solgun

Deniz durgun

İnsanlık suskun

Ve ölüm... 

Ülkemde çok ucuz gülüm...

Sıska cılız insanlarımız 

Bir ağaç dalını budar gibi 

Budarlar birbirlerini 

Acımasızca 

Düşün...

Denizler durgun

Çiçekler solgun

İnsanlık suskun

Ve ölüm...

Ülkemde çok ucuz gülüm...

03.07.1992

Şanlıurfa', 'Yeni bir yaşama on kala Düşün kentler yıkık Çiçekler solgun Deniz durgun İnsanlık suskun Ve ölüm...  Ülkemde çok ucuz gülüm... Sıska cılız i...', ARRAY['Türk Edebiyatı','Şiir','Halil Manap']::text[], 8.5, '{"poet":"Halil Manap","poet_slug":"halil-manap","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/insanlik-suskun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Hayatı', 'i-nsan-hayati-adem-tiras-z1oo6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsan hayatı bu, tıpkı mevsimler misali

Bazan firgat, bazan da ümit eder visali.

Acı, ızdırap,çile; neşe,sevinç, muhabbet,

Hepsi gizlenmiş onda; tıpkı peri masalı 

                              

                                          Adem Tıraş    12.12.1985

                                                       (TRABLUSGARP)', 'İnsan hayatı bu, tıpkı mevsimler misali Bazan firgat, bazan da ümit eder visali. Acı, ızdırap,çile; neşe,sevinç, muhabbet, Hepsi gizlenmiş o...', ARRAY['Türk Edebiyatı','Şiir','Adem Tıraş']::text[], 8.5, '{"poet":"Adem Tıraş","poet_slug":"adem-tiras","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/insan-hayati-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın 2', 'sen-varsin-2-adem-tiras-6yohm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah oldu güneş doğup yayıldı

Işıkları sağnak sağnak sağıldı

Güller açtı misk-i amber dağıldı

Nefesimde ciğerimde sen varsın

Kara toprak kazma ile kazıldı

Ak tohumlar sere serpe yazıldı

Hasat oldu deste deste dizildi

Tınazımda başağımda sen varsın

Nazik kalbim yorulmaktan  buruldu 

Orta yere büyük sofra kuruldu

Yufka ekmek dürüm dürüm dürüldü

Tabağımda kaşığımda sen varsın

Nazlı sular yaylalardan koyruldu

Taştan taşa seke seke yoruldu

Yatak olan havuzlarda duruldu

Bardağımda yudumumda sen varsın

Akşam oldu el ve etek çekildi

İsli lamba çakmak çakmak yakıldı

Gönül bağım harap olup yıkıldı 

Viranımda enkazımda sen varsın

                                     Adem Tıraş        

                                      15.8.1998

Bu şiir şairin ''PİŞMANLIĞIN GÖZYAŞLARI'' isimli romanından alınmıştır. Kitabın temin adresi: Fazilet Kitabevi Ş.M.Eroğlu cad. Giritlioğlu Pasajı Osmaniye', 'Sabah oldu güneş doğup yayıldı Işıkları sağnak sağnak sağıldı Güller açtı misk-i amber dağıldı Nefesimde ciğerimde sen varsın Kara toprak ka...', ARRAY['Türk Edebiyatı','Şiir','Adem Tıraş']::text[], 8.5, '{"poet":"Adem Tıraş","poet_slug":"adem-tiras","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-varsin-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-arthur-rimbaud-6ngml', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi yaz akşamlarında, özgür, gezeceğim,

Ayaklarımın altında nemli, serin kırlar; 

Başakları devşirip otları ezeceğim,

Yıkayıp arıtacak çıplak başımı rüzgar.

Ne bir söz, ne düşünce, yalnız bitmeyen düş

Ve yüreğimde sevgi; büyük, sonsuz, umutlu,

Çekip gideceğim, çingene gibi, başıboş

Doğada, -bir kadınla birlikte gibi mutlu.

(20 Nisan 1870) 

(Fransızcadan çeviren:Erdoğan Alkan)', 'Mavi yaz akşamlarında, özgür, gezeceğim, Ayaklarımın altında nemli, serin kırlar;  Başakları devşirip otları ezeceğim, Yıkayıp arıtacak çıpl...', ARRAY['Türk Edebiyatı','Şiir','Arthur Rimbaud']::text[], 8.5, '{"poet":"Arthur Rimbaud","poet_slug":"arthur-rimbaud","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozlem-143-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-adem-tiras-eh6rb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan Türkçede tek kelime iki hece

Ve tüm varlığı ile bilinmez bilmece

                                                   15.8.1995', 'İnsan Türkçede tek kelime iki hece Ve tüm varlığı ile bilinmez bilmece                                                    15.8.1995...', ARRAY['Türk Edebiyatı','Şiir','Adem Tıraş']::text[], 8.5, '{"poet":"Adem Tıraş","poet_slug":"adem-tiras","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/insan-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ofelya', 'ofelya-arthur-rimbaud-59ww3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızların uyuduğu, sessiz, kara

Dalgalarda Ofelya iri bir zambak,

Yüzüyor duvaklı, uzanmış sulara...

-Avcı borularının ezgisinde bak.

Bin yıl geçti, Ofelya yine üzgün,

Uzun sularda kefen gibi akıyor.

Bin yıldır, gündüz gece, deli gönlünün

Hüznünü meltem yellerine döküyor.

Açıp sularda salınan tüllerini

Beyaz göğüslerini öpüyor rüzgar,

Söğütler eğmiş omzuna dallarını

Ağlıyor. Uykulu alnında kamışlar.

Yöresinde üzgün nilüferler bazan

Dağıtıyor Ofelya kızılağacın uykusunu,

Bir kanat vuruşuyla dallar yuvadan

-Salıyor yıldızların altın şarkısını.

Sen ey solgun Ofelya, kar gibi güzel! 

Sulara gelin oldun ergen çağlarda! 

-Çünkü Norveç doruklarında esen yel

Acı özgürlüğün tadını öğretti sana:

Savuran bir soluk gür perçemlerini

Büyüyordu düşlerinin akışında; 

Dinliyordun doğanın ezgilerini

Ağacın, gecelerin yakınışında; 

Çünkü boğuk sesi çılgın denizlerin

O tatlı, çocuk göğsüne vuruyordu; 

Bir nisan sabahı, yorgun bir atlı senin

Dizlerinde sessizce oturuyordu! 

Gök! Aşk! Özgürlük! Bu nasıl düş Deli Kız! 

Güneş vuran kar gibi eriyip gittin; 

Konuşma, sus! Seviyi bizlere dilsiz

O mavi gözlerinle çoktan öğrettin! 

-Ve diyor ki Ozan: Aydın gecelerde

Ofelyam çiçekler devşiriyorsun; 

Hep böyle yüz, ak gelinliğinle suda

Dalgalar beşiğini sallayıp dursun.

(15 Mayıs 1870) 

(Fransızcadan çeviren:Erdoğan Alkan)', 'Yıldızların uyuduğu, sessiz, kara Dalgalarda Ofelya iri bir zambak, Yüzüyor duvaklı, uzanmış sulara... -Avcı borularının ezgisinde bak. Bin ...', ARRAY['Türk Edebiyatı','Şiir','Arthur Rimbaud']::text[], 8.5, '{"poet":"Arthur Rimbaud","poet_slug":"arthur-rimbaud","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ofelya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
