INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Uzak İstedin', 'beni-uzak-i-stedin-taner-besen-r1rxx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yosunlar gibi kapladın,

Senin için ıslanmış olanı

Bir hakim gibi cezalandırdın,

Sana fedakarlıklarla adanmış olanı...

Önce kalemi elime verdin,

Mürekkebimi ilham eyledin! 

Sonra yırttın kağıdı,

Beni uzak istedin...', 'Yosunlar gibi kapladın, Senin için ıslanmış olanı Bir hakim gibi cezalandırdın, Sana fedakarlıklarla adanmış olanı... Önce kalemi elime verd...', ARRAY['Türk Edebiyatı','Şiir','Taner Besen']::text[], 8.5, '{"poet":"Taner Besen","poet_slug":"taner-besen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beni-uzak-istedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* * * Allah Dostu', 'allah-dostu-mustafa-engin-karatay-7e63e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bekledim; ummânları, kasırga yutsun diye 

Fırtınanın kolları, tayfun uyutsun diye 

Mast kökünden çatlayıp, yelkenlerle devrildi 

Güverte alabora, tepe-taklak çevrildi 

Ters-yüz olmuş hâline düşerken yıldırımlar; 

Ne görsem? Su yüzünde, patika-kaldırımlar 

Allah Allah... Tuhaf şey, gördüklerim doğrusu 

Gözümü ovaladım, gitsin diye buğusu 

Demek hikmeti buymuş, Pâk Hüdâî Yolu''nun 

Üftâde silsilesi, Celvetiyye Kolu''nun 

Bir müddet tefekkür ve ince ince hesaptan, 

Sonrasında anladım; rûh gemisine kaptan 

Farketti hislerimi; vakûr, mânidâr sustu 

Derdime devâ oldu, karşımda Allah Dostu... 

21.02.2004    Münih   05:55', 'Bekledim; ummânları, kasırga yutsun diye  Fırtınanın kolları, tayfun uyutsun diye  Mast kökünden çatlayıp, yelkenlerle devrildi  Güverte ala...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/allah-dostu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
