INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvarlarım', 'duvarlarim-tugba-gurelli-e8xn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizliği yazıyorum ince ince dilimin küfürlerine

Beyoğlu''nun arka sokağında -hani o küf kokanında-

Gençliğimi bırakıp,kalan yanlarımla gidip geliyorum ya kendime

Ah ne de çok seviyorum bunu ben...

Peki; 

Neden hep içimde bir kilise mumu yanıyo! 

Koca bir bıçak sallıyorum en ipince yerlerime

Kendi yaralarıma oturup kahkaha inceliğinde seviniyorum

Hayatın ayıp yanları mı bir ucundan tuttuğum hep

Yoksa bir dudak boyu yalnızlığı mı boyayan tepeden tırnağa...

Peki; 

Neden hep gündüzler buzlanıyo içimde! 

İçimden küller sızıyor kimse farketmeden

Tanrının yüzünü yıkıyorum ten ağlamalarımla

Gitgide kısalmanın keskin çığlığıyla bağırıyorum

Ve gidip gelip içimin ''''Edip Cansever''ine'''' çarpıyorum...

Peki; 

Neden hala ''''Mendilimde Kan Sesleri''''.', 'Sensizliği yazıyorum ince ince dilimin küfürlerine Beyoğlu''nun arka sokağında -hani o küf kokanında- Gençliğimi bırakıp,kalan yanlarımla gid...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Gürelli']::text[], 8.5, '{"poet":"Tuğba Gürelli","poet_slug":"tugba-gurelli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duvarlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AYRI-LIK (KARA''nın Siyaha Hükmettiği zamanlarda)', 'ayri-lik-kara-nin-siyaha-hukmettigi-zamanlarda-firat-kucuk-azluv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gecenin erk-ek saatinde

erk-eklere İNAT  bir kadı-n

kaldırımı olmayan caddeleri

adı-m adı-m adı-mlamakta

trafik lambasının sarısı

yağmurla dans etmekte

kırmızı ve yeşili kıskandırırcasına 

ve 

göz kırpmakta kadı-na

bütün erk-eklere İNAT...

açık-koyu turuncu tişört, beyaz pantolon, kızıl saçlar ve muz-çilek kokusuyla 

tropikal bir ağacı andıran kadı-n 

farkında 

erk-eklerin ve kadı-nlığının...

adı kara olan denizin

güneşten ve insana dair olandan sakladığı mahrem yerinde

ço(k) cuk  ses(ler) i...

VE... yükseklik korkusu

soru: erk-ek ve kadı-n neden korkar yükseklikten / yükseklerden? 

yanıt: her kesimin yanıtı kendine... 

serin mayıs gecesinin asfaltı üzerinde

insan bedeni: canı, kanı ve KOKUSUUUUU 

her balkondan bir kafa

her kafadan bir balon

gülün dikenine İNAT tüy(ler) 

sesler: çığlık – küfür – ağıt – cık cık – vah vah – soru işareti vs...

adı-mlar hızlı...birden çok

kadı-n ve erk-ek (ler) 

yağmur

rüzgar tiner yüklü

dikkat uzun araç

ilaç yüklü on sekiz teker üzerinde...

VE... altında kadı-n

küflü tahta kokusu

erk-ek elleri üstünde

ıslak toprak / kaya kokusu, güneş ışığı…

VE... içinde kadı-n                           ayrı

                    erk-ek                                   (lık)   

                    ço(k) cuk                       ayrı

son söz yerine: en sevdiğim bağla-ç  “VE”... 

eytişimsel... 

bkz. Tdk sözlüğü cilt bir 

sayfa dört yüz seksen bir...

her şeyin özeti:

(kırmızıyla yazılacak siyaha İNAT) 	

bütün kişiler – onlar karşılar kahraman(cık) lara –

bir biçimde ölürler

KARA’nın siyaha hükmettiği zamanlarda... 

                                                                                                             

Fırat Küçük', 'gecenin erk-ek saatinde erk-eklere İNAT  bir kadı-n kaldırımı olmayan caddeleri adı-m adı-m adı-mlamakta trafik lambasının sarısı yağmurla d...', ARRAY['Türk Edebiyatı','Şiir','Fırat Küçük']::text[], 8.5, '{"poet":"Fırat Küçük","poet_slug":"firat-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ayri-lik-kara-nin-siyaha-hukmettigi-zamanlarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar-dı', 'sonbahar-di-firat-kucuk-j23fm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bulutlar hüznünü bırakırken kentin üzerine 

aşk, sayılara küstü

ve bütün köprüleri dinamitledi şair…

diğerleri duymadı, hissetmedi, görmedi bu dizeleri; 

umursamadı da…

erken mi geldiği 

geç mi kaldığı bilinmeyenler, 

saygıyla eğildiler gecenin önünde…

aranıp da bulunamayan Hint kumaşı değildi 

zaman denizinde yitirdiklerimiz; 

her zaman kalan bir  şeyler oldu kaybedilenlere karşı 

içsel isyanlar ve dışsal hüzünler toplamından…

hüzün her mevsim başımızın tacıydı,

içerde bir yerde kırık dökük, yaralı bereli bir düşbaz…

bizim çocuklardan…

sonbahardı…

                                                                                                    Fırat KÜÇÜK', 'bulutlar hüznünü bırakırken kentin üzerine  aşk, sayılara küstü ve bütün köprüleri dinamitledi şair… diğerleri duymadı, hissetmedi, görmedi ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Küçük']::text[], 8.5, '{"poet":"Fırat Küçük","poet_slug":"firat-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sonbahar-di-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Tersleri (ya da kırılmalar...)', 'hayat-tersleri-ya-da-kirilmalar-firat-kucuk-2rajw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“şimdiki zaman geniş zaman olursa

                                     intihar çağırır yaz(g) ıcıyı...”

ter kokulu mevsimin mülk edindiği

bir salı gecesinin bilinmeyen bir anında

kırık dökük bir uyku

ve mürekkepli ellerin çizmeye çalıştığı 

üç yazgı...

hiç görmediği korkuluğa sevdalı

kentli bir serçenin

		     tragedyası

- mahremiyet, masumiyet ve cesaret üçgeni –

köylü bir kargayı kıskanma isterisi

yani ismin en kör hâli...

gecenin uzun gölgesinde

üzüm buğusunun kokusu

kentin geniş caddelerini dolaşmakta

kuzey rüzgârıyla ve

fail-i meçhul bir ezgi doluşmakta

sağır kulaklara...

yıllar önce, çok çok önce

hatta marangozdan önce

umudu yük edinip gelinen

bu boğaz kentlerinde

umutsuzluğun sarmaş dolaş olduğu 

kanserli bir yalnızlık...

buzlu suyun kucağında 

dna’sız hücre yığınları 

yanaklardan süzülüp magmayı sulayan 

sürrealist göz yaşları...

randevusuna hep erken gelen siyah pelerinli celladın ko(r) kusu

ve ölümcül soğuk...

billy kid mi red kid mi ikilemi

çizgi roman tadında ve foto roman bayalığında 

gerçekaltı yaşamlar

bizi biz ettiğini sandığımız amanlı  sevdalar...

ve

İNAT’ın 

              kırılma noktası…	

Fırat Küçük', '“şimdiki zaman geniş zaman olursa                                      intihar çağırır yaz(g) ıcıyı...” ter kokulu mevsimin mülk edindiği bi...', ARRAY['Türk Edebiyatı','Şiir','Fırat Küçük']::text[], 8.5, '{"poet":"Fırat Küçük","poet_slug":"firat-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hayat-tersleri-ya-da-kirilmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deneme', 'deneme-oguzkan-bolukbasi-e0gkr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bana bakma öyle sıramı savdım

aşkı şu gönlüme hep yasak saydım

sen küçüksün sevdiceğim korkma sakın

senin gibi severdim yerinde olsaydım

dudakların büzülmüş ağlıyor musun

gözyaşın biter mi ne sanıyorsun

sözümü hikmetten saymıyor musun

ya ben de sana aşık olsaydım

zülüfün perçemi düşmüş gönlüme

heyecanlar getirdin sakin ömrüme

seninle giderim bil ki ölüme

gönlünde yanan ateş olsaydım', 'bana bakma öyle sıramı savdım aşkı şu gönlüme hep yasak saydım sen küçüksün sevdiceğim korkma sakın senin gibi severdim yerinde olsaydım dud...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deneme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-kerem-ulukir-6bkcb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanatları var süslü süslü

Temsil eder özğürlüğü

Özgürlük mutluluk ile bağlı

Mutluluk ise sevgi ve saygı

Kelebeklerin ömrü çok kısa

Ama doludur hayatları aslında

Çok mutlu yaşarlar ömürleri azda olsa

Kelebek kadar özgür canlı varmıdır dünyada

(18 şubat 2004)', 'Kanatları var süslü süslü Temsil eder özğürlüğü Özgürlük mutluluk ile bağlı Mutluluk ise sevgi ve saygı Kelebeklerin ömrü çok kısa Ama dolud...', ARRAY['Türk Edebiyatı','Şiir','Kerem Ulukır']::text[], 8.5, '{"poet":"Kerem Ulukır","poet_slug":"kerem-ulukir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kelebek-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dile tamâh etme gönül', 'dile-tam-h-etme-gonul-sair-ahrazi-v8led', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dile tamâh etme gönül,

Bazı derde söz gerekmez.

Rûhu fikre katma gönül,

Aşık ferde haz gerekmez.

Gök konuşsa ufku yanar,

İsli közü külü kınar,

Yağmur isen vuslat pınar,

Akan yerde iz gerekmez.

Gizli haber ilhâm ile,

Suâl etmez hale bile,

Renk bilmeden açan güle,

Cismi sor da yüz gerekmez.

Ey Ahrâzi hasret deme,

Yaş gözünde kanla yuma,

Senlik benlik yoldur ama,

İsmi yarda biz gerekmez.

*  *  *

Aşktan güzel bir hâl var mı ki,

Varsa eğer ismi yâr mı ki?', 'Dile tamâh etme gönül, Bazı derde söz gerekmez. Rûhu fikre katma gönül, Aşık ferde haz gerekmez. Gök konuşsa ufku yanar, İsli közü külü kına...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dile-tamah-etme-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zenginlik', 'zenginlik-kerem-ulukir-y7ubf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zenliği Allah verir

Bunu her zaman böyle bil

Allah yolunda kullan paranı

Fakirlere ver sadakanı

Zengin ve fakir olmak kötü

Zor bir sınavdır bundan ötürü

Herşeyde sabırlı olmayı öğrenmelisin

Hiç bir şeyde isyan etmemelisin

Zengin olunca insan unutur Allahı

Paraları sayar tatlı tatlı

Zengin olunca yaparsan bunları

Ya dünyada ya da ahirette çekersin acısını

Zenginlik için Allaha dua etme

Cehenneme aceleden gitme', 'Zenliği Allah verir Bunu her zaman böyle bil Allah yolunda kullan paranı Fakirlere ver sadakanı Zengin ve fakir olmak kötü Zor bir sınavdır ...', ARRAY['Türk Edebiyatı','Şiir','Kerem Ulukır']::text[], 8.5, '{"poet":"Kerem Ulukır","poet_slug":"kerem-ulukir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zenginlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu dünya', 'bu-dunya-ferit-teksoy-f9s8v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karlı dağda yangın yeri gibiyken

Ekvator sıcağında donuyor içim

Dev bir şehrin kalabalıkları içinde

Issız bir adada yaşar gibiyim

İliklerime işliyor şu esen rüzgar

Yağan tüm yağmurlar ruhumda sanki

Kayalara çarpan dalgalar gibi

Bir böcek giriyor,yiyor beynimi

Anlamsız geliyor dün gibi bugün

Yarını bilmiyorum gebe hangi acıya

En büyük üzüntüler daimi misafirim

Yüreğim han,ben benzerim hancıya

Pişmek için yanmak gerekiyormuş

O yangın içimde,hissediyorum

Öyle sanıyorum ki,bu dünya çilehane

Bu çilehanede ben,çile dolduruyorum', 'Karlı dağda yangın yeri gibiyken Ekvator sıcağında donuyor içim Dev bir şehrin kalabalıkları içinde Issız bir adada yaşar gibiyim İliklerime...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-dunya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aile', 'aile-kerem-ulukir-b4rnk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anne baba kardeş abi

Severler birbirini deliler gibi

Aileye hiçbirşey olmasın isterler

Çok fazla iyimserler

Çocuklar büyür adam olur

Büyüklere göre onlar çocuk ruhludur

Her zaman anneni babanı dinle

Tecrübe edinin Dünya günlerinde

Gelelim şimdi çocuklara

Renk katarlar aileye aslında

Hiçbir zaman bölünmez aile

Bunu kavra bir kerede', 'Anne baba kardeş abi Severler birbirini deliler gibi Aileye hiçbirşey olmasın isterler Çok fazla iyimserler Çocuklar büyür adam olur Büyükle...', ARRAY['Türk Edebiyatı','Şiir','Kerem Ulukır']::text[], 8.5, '{"poet":"Kerem Ulukır","poet_slug":"kerem-ulukir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aile-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüdüğüm yollara sarı yapraklar tünemiş', 'yurudugum-yollara-sari-yapraklar-tunemis-mustafa-sen-qgt72', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yağmur düşü gördüm

anladım

son baharın içimdeki esaretini

Gözlerim

aynasında durgun suların 

sağanak

Yalnızlığa

             bulanmış

                          bedenim

Ey canımın gölgesi

        karanlığa   batırıp 

                         gökyüzünü

                                   yıldızlara boyarsam

                A

                ğ

                 l

                a

                ş

                 ı

                r

           

             mıyız

martı kanatlarında 

                           kana

                                  kana?', 'Bir yağmur düşü gördüm anladım son baharın içimdeki esaretini Gözlerim aynasında durgun suların  sağanak Yalnızlığa              bulanmış   ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen']::text[], 8.5, '{"poet":"Mustafa Şen","poet_slug":"mustafa-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yurudugum-yollara-sari-yapraklar-tunemis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem baladları 2', 'ozlem-baladlari-2-mustafa-sen-d91n1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zümrüt yeşili 

kahpe gecelerin

tükeniyor 

         sigaramın 

                   dumanıyla

Mavi 

      buğulanmış 

                     penceremde 

                                         umutlar 

                                                     ağarıyor

Gece  kuşları

                   dallardan  uçuyor

                                          kanat  kanat

Rüzgar 

        gözlerini 

                    öteye 

                          götürmüş

Zavallı gözlerim....', 'Zümrüt yeşili  kahpe gecelerin tükeniyor           sigaramın                     dumanıyla Mavi        buğulanmış                       penc...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen']::text[], 8.5, '{"poet":"Mustafa Şen","poet_slug":"mustafa-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozlem-baladlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-sair-x-factor-51dta', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tren çığlukları duyulur yakınlardan 

Sevda şarkıları dinlenir martılardan 

Geceler koynumda simsiyah yar 

Avuçlarım da yıldızların koparılmış halimi 

Kafeste kuş özgürlüğün muhalimi 

Umut bende duvarda ezik böcek gibi 

Bir yar ki hep uzaktan sevecek gibi 

Ömrümü koyduğum sevdam yürekten gitmezde 

Can beden de emanet sanki gidecek gibi 

Yüreğim kanat çırpar sana seherde 

Ve sen başlarsın şarkıların sustuğu yerde 

Sevdam fecre kadar ardından gider de 

Yine seni bulurum gecenin bittiği yerde', 'Tren çığlukları duyulur yakınlardan  Sevda şarkıları dinlenir martılardan  Geceler koynumda simsiyah yar  Avuçlarım da yıldızların koparılmı...', ARRAY['Türk Edebiyatı','Şiir','Şair X_factor']::text[], 8.5, '{"poet":"Şair X_factor","poet_slug":"sair-x-factor","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vuslat-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırlara Çıksam', 'kirlara-ciksam-safure-yildirim-xdulo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şöyle kendimi alıp

bir, kırlara çıksam

yerle göğün söyleştiği

bir noktada dursam,

eteğinde siyah,beyaz

kuzular, keçiler otlasa.

kuzularla konuşsam,

keçilerle koşsam, koşsam.

yorgunluktan düşüp

çimlere uzansam.

göz kırpsam güneşe,

çiçek toplasam eteğime,

yok yok, hayır

kıyamam hiç birine,

zarar veremem 

tek bir yaprağına bile

ben onları dalında syredip,

gözlerimle okşasam..

nisan 1996   İlkim', 'şöyle kendimi alıp bir, kırlara çıksam yerle göğün söyleştiği bir noktada dursam, eteğinde siyah,beyaz kuzular, keçiler otlasa. kuzularla ko...', ARRAY['Türk Edebiyatı','Şiir','Safure Yıldırım']::text[], 8.5, '{"poet":"Safure Yıldırım","poet_slug":"safure-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kirlara-ciksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitap Seni İstemedi', 'kitap-seni-i-stemedi-su-yaprak-azvrd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acıyı reçel yaptım, sürdüm ekmeğime

Aç kedi bile yemedi

Hasretini kolye yaptım, taktım boynuma,

Gelen geçen gülümsedi

Bir tek yaprak kalmış senden geriye,

                                   koydum kitabıma,

Kapanmadı kitap, seni istemedi.', 'Acıyı reçel yaptım, sürdüm ekmeğime Aç kedi bile yemedi Hasretini kolye yaptım, taktım boynuma, Gelen geçen gülümsedi Bir tek yaprak kalmış ...', ARRAY['Türk Edebiyatı','Şiir','Su Yaprak']::text[], 8.5, '{"poet":"Su Yaprak","poet_slug":"su-yaprak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kitap-seni-istemedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başımı Döndürsün', 'basimi-dondursun-murat-berk-btbpa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçlarını savur da

Bakırköy''ün denizinden

Güzgarlar dolsun göğsüme..

Deli deli dolu dolu,

Usum karışsın,

Sana  söyleyeceklerim 

Benimde başımı döndürsün

Senin de...', 'Saçlarını savur da Bakırköy''ün denizinden Güzgarlar dolsun göğsüme.. Deli deli dolu dolu, Usum karışsın, Sana  söyleyeceklerim  Benimde başı...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/basimi-dondursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gururun Nerde', 'gururun-nerde-memet-zeki-ates-ae6em', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdanla kavrulup küle dönmüştüm,

Ben Aşkı her derde deva sanmıştım.

Yalan sözlerine nasıl kanmıştım,

Aşkın gözlerime çekmişti perde.

Meğer şeytan imiş ben Melek gördüm,

Ne aslın aradım ne soyun sordum.

Kötü düşler görüp hayıra yordum,

Fitnelik fesatlık yoktuki serde.

Onur yaraladın bıraktın darda,

Hinlikler saklıymış iltifatlarda.

O buyun o posun endamın varda

Hani senin onurun gururun nerde.

Sadece kediler nankörlük yapmaz,

Asaleti olan özünden sapmaz.

Soysuz u silince kıyamet kopmaz,

Umarım Allahtan düşersin derde.', 'Sevdanla kavrulup küle dönmüştüm, Ben Aşkı her derde deva sanmıştım. Yalan sözlerine nasıl kanmıştım, Aşkın gözlerime çekmişti perde. Meğer ...', ARRAY['Türk Edebiyatı','Şiir','Memet Zeki Ateş']::text[], 8.5, '{"poet":"Memet Zeki Ateş","poet_slug":"memet-zeki-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gururun-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutabilseydim İsyanımı', 'tutabilseydim-i-syanimi-su-yaprak-veysb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tutabilseydim isyanımı,

Yedi renge boyar, gökkuşağı yapardım

Süzülürdü her bir renk damla damla,

Hangisi gözyaşım, kimse anlamazdı

Hangisi gözyaşım, bilemezdi kimse

Sevgimin adını saklardım

Borç verirdim gelecek günlerimi,

Bugünü yastığa koyar, öyle yatardım

Binbir tohum ekerdim yüreğime,

Hangisi sızı, aldırmazdım

Dostu dosta katıp avunurdum,

Tutabilseydim isyanımı..', 'Tutabilseydim isyanımı, Yedi renge boyar, gökkuşağı yapardım Süzülürdü her bir renk damla damla, Hangisi gözyaşım, kimse anlamazdı Hangisi g...', ARRAY['Türk Edebiyatı','Şiir','Su Yaprak']::text[], 8.5, '{"poet":"Su Yaprak","poet_slug":"su-yaprak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tutabilseydim-isyanimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkar Yüreğinin Kılıfını', 'cikar-yureginin-kilifini-su-yaprak-59mk4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıkar yüreğinin kılıfını

Kılıcı kınından sıyırır gibi,

Kapat ışığını tüm dünyanın,

Karanlıkta seyret sevgini

Silkele geçmişin tozlarını

Bak, sabahın kokusu yakın

Tüm ağıtlar bitti şimdi,

Bırak sevgin nefes alsın..', 'Çıkar yüreğinin kılıfını Kılıcı kınından sıyırır gibi, Kapat ışığını tüm dünyanın, Karanlıkta seyret sevgini Silkele geçmişin tozlarını Bak,...', ARRAY['Türk Edebiyatı','Şiir','Su Yaprak']::text[], 8.5, '{"poet":"Su Yaprak","poet_slug":"su-yaprak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cikar-yureginin-kilifini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Umutsuzluk Kaldı', 'bana-umutsuzluk-kaldi-su-yaprak-o8abe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgimin üstüne sevgiyi giydirdim,

                                              yakışmadı.

Sıyırıp çıkardım onu,

                                ruhum açıkta kaldı.

Hangi renge hangisini katacağımı bilemedim,

                              ortalığı griler sardı.

Günışığını özledim, turuncu yan baktı bana.

Beyaz pek bir kibirliydi,

                                   dokunamadım.

Özlemlerim şaha kalktı, kırmızı örttüm üzerlerine

Siyah titrek, ağlıyordu,

                              yüz vermedim kederine.

Sarı sıvadım geçmiş sevgililerime,

                             bir şeye benzesin yüzleri diye

Yeşil yoncalarım dört yapraklı olsun istedim.

Bana ise, kala kala umutsuzluk kaldı.

Onu da öylece bıraktım, renksizliğinden utansın diye..', 'Sevgimin üstüne sevgiyi giydirdim,                                               yakışmadı. Sıyırıp çıkardım onu,                           ...', ARRAY['Türk Edebiyatı','Şiir','Su Yaprak']::text[], 8.5, '{"poet":"Su Yaprak","poet_slug":"su-yaprak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bana-umutsuzluk-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozan', 'ozan-ahmet-kemaloglu-j1xqp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne saz çalarım,

Ne türkü söylerim.

Ben bir garip ozanım..

Ben yürek söylerim….', 'Ne saz çalarım, Ne türkü söylerim. Ben bir garip ozanım.. Ben yürek söylerim…....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kemaloğlu']::text[], 8.5, '{"poet":"Ahmet Kemaloğlu","poet_slug":"ahmet-kemaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecel', 'ecel-ahmet-kemaloglu-xelfm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün gideceğim buralardan….

Beni bülbüller arayacak…

Başına yemeni bağladığım güzeller..

Beni ve gidişimi ecelden soracak…', 'Bir gün gideceğim buralardan…. Beni bülbüller arayacak… Başına yemeni bağladığım güzeller.. Beni ve gidişimi ecelden soracak…...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kemaloğlu']::text[], 8.5, '{"poet":"Ahmet Kemaloğlu","poet_slug":"ahmet-kemaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ecel-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-ahmet-kemaloglu-fmgak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne sen beni

Ne ben seni…

Ne sen parayı.

Ne ben sevdayı..

Bulamadık bir türlü…

Bulamadık dünyayı…', 'Ne sen beni Ne ben seni… Ne sen parayı. Ne ben sevdayı.. Bulamadık bir türlü… Bulamadık dünyayı…...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kemaloğlu']::text[], 8.5, '{"poet":"Ahmet Kemaloğlu","poet_slug":"ahmet-kemaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dunya-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Ha Hadi Gel Deme', 'sakin-ha-hadi-gel-deme-metin-yalti-dd85s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.............................“Yaşadıklarımdan öğreneceklerim var” 

YILLARDIR PEŞİNDEN KOŞUP DURDUM YA 

SAKIN HA BU GÜNLER 

-HADİ GEL, DEME 

HER ZAMAN AKLIMDAN ÇIKMASAN BİLE 

İŞLERİM ÇOK YOĞUN SANA GELEMEM 

GELSEM DE BU STRES ALTINDA MUTLU OLAMAM 

BİLİYORUM SANA SÖZÜM ÇOK BORCUM BİRİKTİ 

YÜREKTE ÖZLEMİN ZATEN HEP YÜKTÜ 

MASAMIN ÜSTÜNDE İŞLER BİRİKTİ 

İŞİN İÇ YÜZÜNÜ NERDEN BİLECEK, MÜŞTERİ BOZUK. 

SENİNDE BİR KARARIN YOK BENİM GİBİSİN 

NE TAMAM DİYORSUN NE VAZGEÇİYORSUN 

BUNUN BENCİLLİK OLDUĞUNU ELBET BİLİYORSUN 

RADYODA BİR TÜRKÜ ÜSTÜNE ÜSTLÜK 

“ EY SEVDİĞİM SENDEN ŞİKÂYETİM VAR 

NE SEVDİĞİN BELLİ NE SEVMEDİĞİN”. 

UYKUYLA ARAMIZ AÇIK GECELER UZUN. DÜŞÜN, DÜŞÜN DUR 

EVDE ÇOLUK ÇOCUĞUN YÜZÜNE BAKMAK BİLE ZOR 

BİRAZ ZAMAN VERSELER TOPARLAYACAĞIM

İNATLA SABIRLA DİRENİYORUM 

YA BİR GÜN KIRILIRSA BU DİRENÇ ÇOK KORKUYORUM. 

MİDEMDE SANCILARLA MİGRENİMİ SAYMAZSAK EĞER 

SAĞLIĞIM ŞİMDİLİK İDARE EDER 

İYİ DE BİLMİYORUM NEREYE KADAR 

ANLAYACAĞIN ÜST ÜSTE GELİYOR HER ŞEY 

HAYATTA İSTEDİĞİM TEK KİŞİ SENDİN 

BU YÜZDEN ARDINDAN HEP KOŞUP DURDUM 

BU GÜNLER SAKIN OLA Kİ 

- SENİ SEVİYORUM HADİ GEL, DEME 

BİR DE SEN DERSEN TAMAM OLACAK. 

 18.2.2004', '.............................“Yaşadıklarımdan öğreneceklerim var”  YILLARDIR PEŞİNDEN KOŞUP DURDUM YA  SAKIN HA BU GÜNLER  -HADİ GEL, DEME  ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sakin-ha-hadi-gel-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Yüreğim ve Hançer**', 'yuregim-ve-hancer-ahmet-kemaloglu-ciou2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar önce tanımıştım…

Tozlu radyo skeçlerinde

LEYLA-MECNUN

Mecnun bendim hep dinlerken

Ama Leyla yoktu..

Ama hep vardı…

Bazen yeşildi gözleri 

Bazen üzüm karası,

Bazen kızgın bazen güleç

Ama hep bana sevdalı…

Bazen kısa boylu  idi..

Bazen uzun..

Bazen çok güzeldi tarifsiz…

Bazen özel..

Ama hep yüreğimde vardı..

Şimdi tozlu radyolar 

42 yıl daha  eskidi..

Ne yeşil gözler girdi yüreğime..

Ne üzüm karaları.

Hep hayal olup,

Hep yıkıp geçtiler..

Bir tek sen sarı papatyam..

Bir tek SEN…

Seni yüreğime hançerle geçtiler…', 'Yıllar önce tanımıştım… Tozlu radyo skeçlerinde LEYLA-MECNUN Mecnun bendim hep dinlerken Ama Leyla yoktu.. Ama hep vardı… Bazen yeşildi gözl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kemaloğlu']::text[], 8.5, '{"poet":"Ahmet Kemaloğlu","poet_slug":"ahmet-kemaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yuregim-ve-hancer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla Deniz Doğurur', 'damla-deniz-dogurur-sadik-softa-cx0s7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalga döner tersine,

Geldiği yere geri.

Bahar damlaya döner,

Damla deniz doğurur.

Su ve toprak sevişir; 

Ateş yakar, yel eser; 

Suda parlar yakomoz; 

Gül de şebnem doğrur.

Hep aşkı hatırlatır; 

Hep sevgiye yönelir; 

Sevda saygı dalında; 

Kalb sevdayı doğurur.', 'Dalga döner tersine, Geldiği yere geri. Bahar damlaya döner, Damla deniz doğurur. Su ve toprak sevişir;  Ateş yakar, yel eser;  Suda parlar ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/damla-deniz-dogurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler..1..', 'maniler-1-ali-osman-yilmaz-n88wp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kara kara kazanlar...........................Ben saçımı uzattım			

Kara yazı yazanlar.............................Her gün öreyim diye		

Cennet yüzü görmesin......................Mahalleden yar sevdim	

Aramızı bozanlar.     .........................Her gün göreyim diye	

Fazla su içme sakın............................Yeşil yayla camisi

Dokunur böbreklere............................Parlıyor minaresi

Benim kaynanam................................Eski sevgilim ölmüş

Benziyor ördeklere.............................Geçiyor cenazesi.', 'Kara kara kazanlar...........................Ben saçımı uzattım			 Kara yazı yazanlar.............................Her gün öreyim diye		 Cenn...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maniler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler..2..', 'maniler-2-ali-osman-yilmaz-go822', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaynana kazan karası.........................Saçımı yan taradım

Kaynata baş belası..............................Modaya uydum yarim

Oğulcuğun sorarsan............................Ellerle geziyorsun

Baklavanın ortası................................Saklama duydum yarim.

Kaynanam çıksın duvara....................Ben örtümü yıkadım

Görümce kaçsın kocaya.....................Niye kuruttun anne 

Kaynatamı allah alsın.........................Sevdiğime vermedin

Oğulcuğu bana kalsın.........................Niye büyüttün anne.', 'Kaynana kazan karası.........................Saçımı yan taradım Kaynata baş belası..............................Modaya uydum yarim Oğulcuğun...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maniler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler..3..', 'maniler-3-ali-osman-yilmaz-qf1e1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu uzun tarla tarla..............................Eteğimin pilesi

Parla çiçeğim parla............................Yıkıyom buruşmuyor 

Yanıma gelemezsen..........................Yarimin resmine bende

Uzaktan mendil salla.........................Bakıyor konuşmuyor.

Bahçenin kapısını..............................Eteğimin pilesi

Bir vuruşta açarım.............................Yana bakıyor yana

İstet yarim bir kere............................Aret senin sevdiğin 

Vermezlerse kaçarım.........................Bana bakıyor bana.', 'Şu uzun tarla tarla..............................Eteğimin pilesi Parla çiçeğim parla............................Yıkıyom buruşmuyor  Yanıma g...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maniler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler..4..', 'maniler-4-ali-osman-yilmaz-dmvhn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahçenin kapısını...............................Darbukamın sesini

Açamıyorum yarim............................Gelsin annem dinlesin

Babama duyurmuşlar.........................Sevdiğime vermezse

Kaçamıyorum yarim..........................Evladım var demesin.

Kolumdaki saati.................................Camı var perdesi yok

Her isteyen kuramaz..........................Ben ona şaşıyorum

Ben annemin kızıyım.........................Sevdiğine varmayan

Her isteyen alamaz............................Demesin yaşıyorum.', 'Bahçenin kapısını...............................Darbukamın sesini Açamıyorum yarim............................Gelsin annem dinlesin Babama d...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maniler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler..5..', 'maniler-5-ali-osman-yilmaz-qoe2i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hoca geliyor hoca.............................Yeşil yayla camisi

Pantolonu bol paça............................Otuz iki basamak

Bizi küçük sanmayın..........................Erkeklerle konuşmak

Biz de isteriz koca..............................Namaz kılmaktan sevap.

Masa üstünde dutlar..........................Kamyon geliyor kamyon

Dutlar dalında patlar..........................Arkasında üç oda

Askerdeki yarime...............................Yare esmer diyorlar

Gölge olsun bulutlar...........................Şimdi esmerler moda.', 'Hoca geliyor hoca.............................Yeşil yayla camisi Pantolonu bol paça............................Otuz iki basamak Bizi küçük s...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maniler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler..6..', 'maniler-6-ali-osman-yilmaz-2y0w4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Darbuka çala çala.............................Minarenin ucunda

Olacağım bir çengi............................Baykuşa bak baykuşa

Yarimin elbisesi................................Annem verse ben gitmem

Vallahi kahverengi............................Senin gibi berduşa.

Kamyon geliyor kamyon................. Mısır ektim azmasın

Arkası tenekeli................................Gelen geçen kazmasın 

Yapma yarim şöförlük.....................Yar üstüne yar sevdim 

Şoförlük tehlikeli..............................Mevlam günah yazmasın', 'Darbuka çala çala.............................Minarenin ucunda Olacağım bir çengi............................Baykuşa bak baykuşa Yarimin elb...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maniler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler..7..', 'maniler-7-ali-osman-yilmaz-hn82h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizin kenarına...............................Kolunda ki saatin

Sofra kuralım yarim..........................Kayışı ben olayım

Askerliğin zor ise..............................Askerdeki yarimin

Beraber yapalım yarim.....................Çavuşu ben olayım. 

Minarenin üstünden..........................Hoca çıkmış camiye

Ezan okunur yarim...........................Sayıyor ışıkları  

Sana bir şey deseler..........................Hoca sevap istersen

Bana dokunur yarim.........................Kavuştur aşıkları.', 'Denizin kenarına...............................Kolunda ki saatin Sofra kuralım yarim..........................Kayışı ben olayım Askerliğin z...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/maniler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maniler..8..', 'maniler-8-ali-osman-yilmaz-au30t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Masa üstünde pekmez......................Şu Bursaya giderken

Bu pekmez bize yetmez...................İki paket çay aldım 

Yeşil yaylanın kızları.......................Utanmadın mı aret? 

Kösteksiz gelin gitmez.....................Ben bıraktım sen aldın.

Yeşil yayla yolları...........................Kolumdaki saati

Taşlı diyorlar taşlı...........................Sen kur ben kullanayım

Askerden gelenlere..........................İki yıllık yarimden

Yaşlı diyorlar yaşlı..........................Ben nasıl ayrılayım? 

Hoca ezan okuyor

Sesi beni yakıyor

Benim sevdiğim oğlan

Fakültede okuyor.', 'Masa üstünde pekmez......................Şu Bursaya giderken Bu pekmez bize yetmez...................İki paket çay aldım  Yeşil yaylanın kız...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/maniler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup ve Ayrılık', 'mektup-ve-ayrilik-oguzkan-bolukbasi-274jb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sakin bir gecedeyim

Merhamet zamanı

Birileri söylemeli sana 

Ben istemedim yalnız kalmanı

Aşk

Her umudunu mutluluğa çıkarmaz bilmeliydin

Ve hele ben gibi birini hiç sevmemeliydin  küçüğüm

Anlamalısın 

Seni çok sevdiğim için sevdiğimi söylemiyorum 

Seni sevmeyecek kadar çok seviyorum', 'Sakin bir gecedeyim Merhamet zamanı Birileri söylemeli sana  Ben istemedim yalnız kalmanı Aşk Her umudunu mutluluğa çıkarmaz bilmeliydin Ve ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mektup-ve-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelemem', 'gelemem-zafer-zengin-etnika-ui72d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gelemem

sana

dünya''yı 

bırakıp

hemen öyle

önce

ismini

söyle

bakışın kimliğinmidir..resim seninmidir..sözün aşk''a emirmidir..nerden bileyim..! 

evraklar lütfen..! 

gönül zaptiyesi..teftiş ediyor hayatı..

21 Subat 2004', 'gelemem sana dünya''yı  bırakıp hemen öyle önce ismini söyle bakışın kimliğinmidir..resim seninmidir..sözün aşk''a emirmidir..nerden bileyim.....', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelemem-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-melih-coskun-lj2le', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidiyorum 

Artık anmayın adımı bu şehirde

Yollarınızdan adımlarımı 

Ve silerek duvarlarınızdan bütün şiirlerimi 

Gidiyorum,

Farz edin hiç gelmedim bu şehre 

Aldanıp yalancı bir mavinin gülümsemesine

Şiirler yazmadım sabahlara kadar

Gidiyorum,

Suları çekildi artık içimdeki denizin 

Belki ilk adım silinir hafızalarınızdan

Sonra yüzüm kaybolur gider gözlerinizden 

Gidiyorum 

Farz edin ki hiç oturmadım şu limana karşı 

Taşlar savurmadım geceler boyu 

Karanlığın koynuna...

Gidiyorum 

Farz et ki 

Hiç yazılmadı bu şiir...', 'Gidiyorum  Artık anmayın adımı bu şehirde Yollarınızdan adımlarımı  Ve silerek duvarlarınızdan bütün şiirlerimi  Gidiyorum, Farz edin hiç ge...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gidiyorum-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildiğimi okuyorum', 'bildigimi-okuyorum-zafer-zengin-etnika-8pw94', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bildiğimi 

okuyorum; 

hayatı

Hayat''da 

bildiğini; 

''canıma okuyor''

şimdi

sayfa otuz yedi''de..cabuk okusada..uyusam..cok yorgunum zira..ders çalışmam lazım cennete..sana saklıyorum huriliği..gülme..gülümsen

21 Subat 2004', 'Bildiğimi  okuyorum;  hayatı Hayat''da  bildiğini;  ''canıma okuyor'' şimdi sayfa otuz yedi''de..cabuk okusada..uyusam..cok yorgunum zira..ders ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bildigimi-okuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanemsin', 'birtanemsin-hasan-gencer-b4gry', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sana güzelsin diyemem 

Çünkü güzelliğin yok olur

Ben sana gülüm diyemem 

Çünkü güllerin ömrü az olur

Ben sana aşkımsın diyemem

Çünkü yaşanan aşklar kısa olur

Ben sana kabimdesin diyemem

Çünkü kalplerin ömrü az olur

Peki biliyormusun sen benim neyimsin

Sakın aramızda biri var diye dilin söyelenmesin

Sen benim duam arzum yaşama sebebim

Sen benim bu dünyada birtanemsin', 'Ben sana güzelsin diyemem  Çünkü güzelliğin yok olur Ben sana gülüm diyemem  Çünkü güllerin ömrü az olur Ben sana aşkımsın diyemem Çünkü yaş...', ARRAY['Türk Edebiyatı','Şiir','Hasan Gencer']::text[], 8.5, '{"poet":"Hasan Gencer","poet_slug":"hasan-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birtanemsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Örttünüz Beyaz Örtüleri Şiirimin Üstüne', 'neden-orttunuz-beyaz-ortuleri-siirimin-ustune-melih-coskun-tw2tg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden örttünüz beyaz örtüleri

Şiirimin üstüne,

Şimdi ruhsuz beton yığınları arasında ezilmekte bedenim 

Gel benim heyecanım 

Sensiz özgürlükten bahsetmek bile zindan bana

Daha da çok sancıyor bugün sol yanım 

Başımda ağrı gibi hala o haksızlıklar 

Dur düşün yüreğim 

Sor kendi kendine 

Böyle yaşamak niye 

Neden bu kadar dertlenmek

Karartmak isteyenlere inat 

Maviyse hala gökyüzü 

Ve hala soluk alıyorsak bizi yok etmek isteyenlere inat 

Daha yenilmedik demektir...', 'Neden örttünüz beyaz örtüleri Şiirimin üstüne, Şimdi ruhsuz beton yığınları arasında ezilmekte bedenim  Gel benim heyecanım  Sensiz özgürlük...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/neden-orttunuz-beyaz-ortuleri-siirimin-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Omuz Omuza', 'omuz-omuza-i-brahim-ethem-bingul-iy5kj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlattım defalarca

Anlamadın ey sevgili,kayıtsızca

Benim yüreğim bir dünya

Aşkımsa,enginlere uzanan derya

Acısı da olacak

Tatlısı da,tuzlusu da

Eğer sen bağlarsan şartlara

Nerde kaldı bu sevda

Peri kızı masalı değil

Hayat bu ya

Göreceğiz herşeyi

Birlikte omuz,omuza', 'Anlattım defalarca Anlamadın ey sevgili,kayıtsızca Benim yüreğim bir dünya Aşkımsa,enginlere uzanan derya Acısı da olacak Tatlısı da,tuzlusu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/omuz-omuza-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama', 'arama-zafer-zengin-etnika-m47pl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arama





Ellerim burda işte..sıcacıklar..sevin işte..gözlerim de sende...', 'Arama Ellerim burda işte..sıcacıklar..sevin işte..gözlerim de sende......', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/arama-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahi, Ya Gelirsen', 'sahi-ya-gelirsen-turgay-kadiroglu-ldjwz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şubatı beyaza

 temmuzu kızıla çalardın,

 kararırdı gecem

 sen, yıldız olur yağardın...

 eylül sarıyla

 nisan sancılarla gelirdi,

 güneşin daldığı gözlerini

 hilal, rahim bilirdi...

 en hiddetli anında bulut

 yumuşacık kar olurdu,

 sen geldin mi dünleri unutup

 içimde kar taneleri kor olurdu...

 ellerinden gelir yağmurun kokusu

 rüzgarındır nefesim

 fısıldanır sesinin buğusu

 erguvan ıslanır, menekşe titrer,

 fesleğenler suskun, 

 içimde ''ya gelmezsen! '' korkusu...

 fersahlarca kulaç açtım

 düşlerimin denizinde,

 mercanlarla kucaklaştım

 ayağının tozu üzerimde,

 ben sana kanatlandım

 düşersem vebalim üzerinde...', 'şubatı beyaza  temmuzu kızıla çalardın,  kararırdı gecem  sen, yıldız olur yağardın...  eylül sarıyla  nisan sancılarla gelirdi,  güneşin da...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sahi-ya-gelirsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köşe Kaçmaca', 'kose-kacmaca-zafer-zengin-etnika-wzj11', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köşe         

                                                                                                    Kaçmaca

oynuyoruz

                                                                                                     seninle! 

Hep ben sobeleniyorum... ey aşk..mabedim...', 'Köşe                                                                                                              Kaçmaca oynuyoruz         ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kose-kacmaca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur İçen Kız', 'yagmur-i-cen-kiz-tunay-karaca-m4s59', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YAĞMUR İÇEN KIZ

Baldırı çıplak bir akşamüstüydü

Kime selam verdiysem yüzüme küstüydü.

Yalnızlığa susmuştum, yağmura üşümüştüm..

Belli belirsiz ve hiçbir makamsız,

Hiçbir kelimesiz ve hiçbir anlamsız,

Kırılgan bir şarkıydı, tılsımına düşmüştüm..

Ve ben sanki ömrümde yaşamadığım

Ve yaşamadan yaşlandığım bütün aşkları

Bu ilk defa karşılaştığım, bu ilk defa yabancı,

Ve bu son defa tutunduğum kızla bölüşmüştüm..

Yağmur içen kız.. gece kuşu

Atmacaya benzer duruşu..

Bir omuzu el-ense çekerken azraile

Bir omuzu sokak lambasından da biçare..

Kimliğini sorarsan; 

Barbar sokakların en barbar kızı,

Ve hortumlu karakolların en arsızı..

O destursuz yağmur, taş gibi iniyordu,

O fütursuz cadde, pür-telaş deviniyordu.

Başını çevirip bakıyordu ara sıra

Hiçbir şey sormadan gidiyordum ardı sıra..

Bir karyola, bir sobadan ibaret 102 nolu odada

Buluştu gözlerimiz, sırları dökülmüş tozlu aynada..

Cebimdeki şişeyi yudumlarken sessizce

Saçlarını okşadım yavaşça ve teklifsizce..

Azıcık huylanmıştı, söylemedi ama şaşırmıştı.

Sanırım ki o, hep değişen tiplere

Ve fakat hiç değişmeyen triplere alışmıştı..

Yağmur içen kız.. vahşi kısrak

Göğsü falçata krizi, öfkesi tavlı bıçak..

Soluğunda ıslak çimenlerin buğusu

Soluduğunda kundaklanmış ormanların yalazı.

Güzelliğini sorarsan; 

Dişleri kar kuşundan da beyaz

Dudakları vampirden de kırmızı..

Alışkın bir otel odasıydı, kenarda soba yanıyordu,

Tutkunun tasma koparan köpekleri

Arsız bir çarşaf gibi üstümüze abanıyordu..

Küçücük ama çok küçücük bir ağzı vardı,

Küçücük ama çok küçücük bir öpüşte bile

Bir vişne ısırığı gibi kanıyordu..

Çaparinin çengelinde çırpınan çipuranın

Yakaran gözlerindeki o tarifsiz kederle,

Bu küçücük ömründe, belki de ilk defa

Birisinin gözlerine bakmaktan utanıyordu..

Yağmur içen kız.. kaldırım meleği

Hüznün yirmidört saatlik beyhude kelebeği..

Her akşam sunarak kendini hoyrat ağızlara

Ve her sabah yunarak bedenini yağmurla

Ve boğarak o narin göğsünde hıçkırıklarını

Bir çalpara gibi yeniledi kopan yanlarını..

Yağmur içen kız.. çılgın kedi

Komalara girdi, jiletler yedi, ölmedi..

Hiç sormadım adını, kendisi de söylemedi.

Ben şişeyi boşalttım, o ağzını sürmedi.

Gitme vakti gelince uzatıp küçücük elini

Hoşça kal, dedi, almadan o malum bedelini..

Boş bir şişeden daha aptalca ne olabilirdi hediye? 

Uzun uzun bakakaldı, bu adam deli mi ne, diye..

İyi ama bu şişe boş be arkadaş, dedi, bu şişe boş! 

Her şey boş güzelim, dedim, her şey boş! 

Sen de yağmur koyarsın belki bu şişenin içine,

Ve güneşin ışırsa bir gün, bir yerlerde, bir ihtimal,

Düşlerini yudumlarsın artık yağmurun yerine...

Yağmur içen kız.. gönül hırsızı

Hiç kimseler bilmeyecek sırrımızı..

Sen tutunmaya çalışırken gecenin eteklerine

Yine acıtacak güzelliğini, o çirkin maça papazı..

Ve yine kıyacaksın belki, o incecik bileklerine..

Yağmur içen kız.. sahipsiz bebek

Elbette bir gün herkes bir şekilde gidecek.

Ama bu yağmur var ya, bu yağmur, inan ki

Nereye gidersen git, hep ardından gelecek..

Ne zaman tokatlasa yağmurlar penceremi,

NE zaman sersem ve buruşuk bir pardösü gibi

Dökülsem kaldırımlarına bu duman karası kentin; 

Hep o kıza rastlarım, aynı kuytu köşede.

Gözyaşlarını biriktirir usanmadan

Düşleriyle aynı şişede..

Hatırını sorarım, sessizce kaldırır yüzünü,

Tablolardan çalınmış gizemli bir gülücüktür.

Yağmur içer yudum-yudum, kanasıya.

Mezesi, eski bir geceden, vişne yarığı kırmızı

Ve hala kanayan o vişne ısırığı öpücüktür..

Yağmur içen kız.. mağrur yürek

Bu yağmurlar yalan ama ölüm gerçek..

Sen yine avucunda sakla, çaldırma cevherini.

Ve sakın gösterme kimseye, o yağmur incilerini

Hep şarkını söyle; hiçbir kelimesiz ve makamsız,

Hep orda bekle; bir akşam belki apansız,

Gelir de alırım şişemi senden geriye:

O biriken yaşlarını içmek için damla-damla

Ve geciken bedelini ödemek için kendi hayatımla...', 'YAĞMUR İÇEN KIZ Baldırı çıplak bir akşamüstüydü Kime selam verdiysem yüzüme küstüydü. Yalnızlığa susmuştum, yağmura üşümüştüm.. Belli belirs...', ARRAY['Türk Edebiyatı','Şiir','Tunay Karaca']::text[], 8.5, '{"poet":"Tunay Karaca","poet_slug":"tunay-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/yagmur-icen-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal ve Perest', 'hayal-ve-perest-bekir-mutlu-gokcesu-x4tqp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Büyür

Kalp çarpıntılarımın

Dalga boyu

Bir siren öncesi

Sessizlikte...

Büyür

Gözümün bebekleri

Karanlığa yürür bakışlarım

Bir projektör tarayışı

Çaresizlikte...

Az sonra içeride

Bir koşuşturmaca başlayacak

Ve bir fısıltı yayılacak

Kulaktan kulağa

Mahkumlar arasında

“Hayal ve Perest firar etmiş”

Diyecekler

Oysa ben salıverdim

Bilmeyecekler...', 'Büyür Kalp çarpıntılarımın Dalga boyu Bir siren öncesi Sessizlikte... Büyür Gözümün bebekleri Karanlığa yürür bakışlarım Bir projektör taray...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayal-ve-perest-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaldıranda Umut Çiçekleri', 'caldiranda-umut-cicekleri-turgay-akbulut-ytdqs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umut ateşidir yüreğimizde tutuşan

İnsanın içine düşmeyi versin bir tutam

Umut denen o kıvılcım, alt üst eder tüm yaşamınızı

Bir de ülkenizde, kara bir zihniyet çökmüşse tepenize

Özgürlük tüter tüter de kimi olasılıklar içinde, çoluk  çocuk, bir bilinmeyen yöne,

Bir bilinmeyen içinde, ama ihtimal olan güneş, güneşi batmayan yöne! 

Batıya doğru uzanır umutlarınız.

Kalır geçmişiniz, bir tutam buruk içinde

Gelecekse, küme küme bulutlar gibi geçer ufuktan

Bir ışık süzülür arasından...bir ışık! vardır her zaman

Işığa doğru akar  insan

Onlarında umutları, sevdaları vardı

Yarınlara bırakacakları mirasları 

Dağları, ovaları, yaylaları hem de en alasından 

Atalarından kalan toprakları, vatanları vardı

Bir anda bırakamaz insan

Kolay değildir kaçak bir yaşamda kurtuluşu aramak

Kolay değildir karanlık ellerde umutla yaşamak

Hangi koşullarda, hangi ızdırapları çekerek geldiler, kim bilir...

Afganlı on sekiz umut yolcusu, dördü çocuk! 

Simsarların açtığı koridordan uzanmışlar, Çaldıran Dağına

Kapılar kapalı ardında miğferler

Simsarlar her ülkede aynı, aynı  dili konuşurlar, aynı renkteler, aynı şeyin peşindeler

Issız bucaksız dağlarda, kurda kuşa yem olacak çok insan 

Umurunda mı çocuklar! 

 Bu dağın ardı demişler

Dağlarda fırtına, karlar yağdı umutlarına

On sekiz kişi kucak kucağa, kayboldular

Bahar gelmiş karlar erimiş

Bir çobanın değneğinin ucunda, kenetlenmiş eller, sarılmış bedenler

Kucak kucağa...

Hala gülümsüyordu yüzleri

Uzatsaydınız elinizi... gireceklerdi içeri

Uzaydınız elinizi...

Çaldıranda onsekiz kişi, dördü çocuk

Çocukların gözleri hala gülümsüyordu

Yanı başında açan kır çiçeklerinde 

Karlar eridi

İki bin bir yılının birinci baharında

Ali Kırca''nın iki dudağı arasında

Hepsi hepsi bir dakika haberdi

Gelip geçti...

Çocukların gözleri...hala gülümsüyordu

Yanı başında açan kır çiçeklerinde...

(mart 03)', 'Umut ateşidir yüreğimizde tutuşan İnsanın içine düşmeyi versin bir tutam Umut denen o kıvılcım, alt üst eder tüm yaşamınızı Bir de ülkenizde...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/caldiranda-umut-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Şiirler', 'kisa-siirler-mehmet-ali-ates-c70ad', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanımı içiyorum bu gece

Bırakın beni ne olur

Bambaşka bir alemdeyim

Gün biter

Kaybolur gece

Sevdan

Bıraktığın sevda

Büyür çiçekle

Sabah soğuk

Seni düşünmek sıcak

Yumuşak

Alıp koynuma 

Yatsam geceyi

Sabahlara doğsam

Uçup gökyüzüne

Assam kendimi

Uzanıp yıldızlara

Vursam kendimi

Akşamlar tütün kokar

Deme duruyor çay

Sonra

Uyanır sabah

Tütün kokulu

Uyuyorum

Senli sabahlara

         Günlere

         Gecelere

Uyuyorum

Senli uyanmak için', 'Kanımı içiyorum bu gece Bırakın beni ne olur Bambaşka bir alemdeyim Gün biter Kaybolur gece Sevdan Bıraktığın sevda Büyür çiçekle Sabah soğu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Ateş']::text[], 8.5, '{"poet":"Mehmet Ali Ateş","poet_slug":"mehmet-ali-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kisa-siirler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerlik borcu', 'askerlik-borcu-serdar-safran-5xx80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mantığın bittiği yerde mi başlar

Uğurlanır asker,gözde yaşlar

Vatan,namus borcudur arkadaşlar

Çürük olmayanlar! ...Mutlak yapacak

İçinde ararsan mantık bulursun

Kaçmaya çalışma ha,yorulursun

Askerlikte sabırla yoğrulursun

Sabret! ..Adam sınıfına konursun

Bütün planlarının önünde engel

Hele sen askerliğini yap da gel

Olmasın bir daha,askerlik engel

Gayret bir an önce yapıver de gel

En büyük hatayı,ben kendim ettim

Evlendikten sonra,askere gittim.

Sıla,yâr ve çocuk hasreti çektim

Ders alın,sakın siz çekmeyin gençler', 'Mantığın bittiği yerde mi başlar Uğurlanır asker,gözde yaşlar Vatan,namus borcudur arkadaşlar Çürük olmayanlar! ...Mutlak yapacak İçinde ara...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askerlik-borcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıksız başlık (AğlaMahzunSırıtGül)', 'basliksiz-baslik-aglamahzunsiritgul-mutlu-ayar-lraoc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ağlamak, gülmek 

kardeş derler

peki ya sırıtmak, 

mahzunlaşmak

onların babaları mı ayrı? 

Anneleri mi üvey?', 'ağlamak, gülmek  kardeş derler peki ya sırıtmak,  mahzunlaşmak onların babaları mı ayrı?  Anneleri mi üvey?...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/basliksiz-baslik-aglamahzunsiritgul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarını Tara', 'saclarini-tara-mehmet-ali-ates-ex9jw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni bir günün

Titrek ışıltılarında gördüm

Solgun yüzün kayboluyordu

Bukleli gür saçlarında

Okyanus gibisin boylu boyunca

Gözlerin ok gibi hızlı

Duruşun kurşun gibi ağırdı

Saç tellerine şiirler asılı

Vücudunun zambakları açmıştı

Sessizliğine sokulmak istedim

Sana dair bir mısra denedim

Şiir kesti saçının telini

Gözlerin

Çok uzakta bir ezgi

Gözlerin gözlerin

Öylesine güzel ki

Kapama ne olur

Onlar ki

görmek isterler güneşi

Alaşafağında sevdanın

Seni bir günün sularında

Üşümüş buldum

Yosun kokusu bulaşmış tenine

Poseidon sularında ıslanmış saçların

Beynimin rüzğarlarımıydı dağıtan

Sürgün ışıltılarıyla saçlarını

Çiçekler kusmuyor kelimelerim

Senliğine sarılı bedenim

Soğuk ırmaklarda bir damla

A  y  n  a  n   o  l  a  y  ı  m

S  a  ç  l  a  r  ı  n  ı    t  a  r  a', 'Seni bir günün Titrek ışıltılarında gördüm Solgun yüzün kayboluyordu Bukleli gür saçlarında Okyanus gibisin boylu boyunca Gözlerin ok gibi h...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Ateş']::text[], 8.5, '{"poet":"Mehmet Ali Ateş","poet_slug":"mehmet-ali-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/saclarini-tara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçları Siyah Kadın', 'saclari-siyah-kadin-zafer-zengin-etnika-l5o3m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kokumu 

bıraktım 

ellerine

şaçları 

siyah 

kadın

sen

nerdeydin! 

Yakarım bakışlarımı...

sigaram duman duman..sevdan cıkmıyor aklımdan

uzuyor gece..sen aklıma düşünce

seninle konuşmak..beş kişiyle konuşmak gibiydi

biri sendin de..diğerleri kimdi

sizmiydiniz! 

21 Subat 2004', 'kokumu  bıraktım  ellerine şaçları  siyah  kadın sen nerdeydin!  Yakarım bakışlarımı... sigaram duman duman..sevdan cıkmıyor aklımdan uzuyor...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/saclari-siyah-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yolculuk', 'son-yolculuk-mehmet-ali-ates-8yuwa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '...

ömür

dakikaları kovalayan 

saniyelerde bitiyor

...

Kağıt beyazı ömür

Mürekkep mavisi bir

Ölüm taşır

Şair daktilosunun tuşlarında

Şiirine can verir

Son senfonisini dinler yazar

Mürekkep bulaşmış sayfalarda

Kalleş namlu uçlarında

Nice

Mumcular uğurlanır

Son yolculuğuna', '... ömür dakikaları kovalayan  saniyelerde bitiyor ... Kağıt beyazı ömür Mürekkep mavisi bir Ölüm taşır Şair daktilosunun tuşlarında Şiirine...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Ateş']::text[], 8.5, '{"poet":"Mehmet Ali Ateş","poet_slug":"mehmet-ali-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-yolculuk-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinç', 'bilinc-ahmet-aksoy-u4au1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '...........''Öz varlık hissedilen değil 

...............................hissedendir''

I

yaşarken kendine geç kal

sonra çıldır ölürken. terk et! 

öldüğünde fark edemediğini.fark et! 

ruhunun hükmettiği bilincini.

II

sen kırıl, hislerin kırılsın,

ama özün sağlam kalsın 

göreceksin eksilenlerin çoğalttığını

yeter ki bilincin açık kalsın.', '...........''Öz varlık hissedilen değil  ...............................hissedendir'' I yaşarken kendine geç kal sonra çıldır ölürken. terk et...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilinc-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylece Sabah Olsun', 'oylece-sabah-olsun-mehmet-ali-ates-xou2f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kokun bulaşmış tenime

Gece sesime titriyor

Artık git

Dinginliğime dokunma

Öylece sabah olsun

Çığlıkların 

Ayıplarına sığınamıyorum

Güneşin ilk ışığı

Alıp götürsün seni

Her şeyleri suya bırak

Kalmasın geride izi', 'Kokun bulaşmış tenime Gece sesime titriyor Artık git Dinginliğime dokunma Öylece sabah olsun Çığlıkların  Ayıplarına sığınamıyorum Güneşin i...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Ateş']::text[], 8.5, '{"poet":"Mehmet Ali Ateş","poet_slug":"mehmet-ali-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oylece-sabah-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mukozo', 'mukozo-ahmet-aksoy-3er0n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'düş sepetinden geri düş

klişelerinde mahsur kalınmış bir yarın

gibi dağıl heybetinde

ah de ukdeleşmiş hayallerinde

sırılsıklam sıyrıl toprağından

sonra sonra tekrar ol zamanın boşluğunda

hoşgelsin hoşgitsin misafirlerin

herkesten bir tuğla al ve tekrar inşa ol', 'düş sepetinden geri düş klişelerinde mahsur kalınmış bir yarın gibi dağıl heybetinde ah de ukdeleşmiş hayallerinde sırılsıklam sıyrıl toprağ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mukozo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil Koy Özlemine', 'karanfil-koy-ozlemine-mehmet-ali-ates-xnqln', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk öpüş 

Dudaklarında yosunlaşır

Yarin

Denizleri yırtarak

Saçlarına çıldırır dalgalar

Karanfil koy özlemine

Umut dikiyorum sevdama

Sevdandan yana', 'İlk öpüş  Dudaklarında yosunlaşır Yarin Denizleri yırtarak Saçlarına çıldırır dalgalar Karanfil koy özlemine Umut dikiyorum sevdama Sevdanda...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Ateş']::text[], 8.5, '{"poet":"Mehmet Ali Ateş","poet_slug":"mehmet-ali-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karanfil-koy-ozlemine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okuyana Dokunan', 'okuyana-dokunan-kamil-aydemir-34osp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalan ne kadar taşır bir insanı

mutluluğa(mı)   ulaşır insan

acıtarak bir canı

körleştirir insanı büyüdükçe nefrat

ben size hep dert

sıkışınca kapınızdan içeri dalan

ve sizi de dertleriyle yoran

asimi asi

estikçe kafası

kendini hasretlere vuran

büyümemiş bir çocuğum

yürek tezgahında hep umut dokunan

emanet gülücük taşıyorsunuz

             gözlerinizden okunan

sevgiyle yıkıyorum kini

şiirlerde suratıma kapatırsa kapılarını

çöle bırakılan gül gibi

yaşamın dalında kururum

ben kerem 

     ben mecnun

         ben ferhat olurum

bulabilsem aşkımı taşıyacak birini

bilirim

aşk öyküleri hep yaşıyacak

ancak

yirminci asrın göbeğinde kirlendi insan

bir insanı ne kadar taşır yalan

şiirler benim kapınızı çalan

herkesin kaçtığı bir zulası vardır

kapılarını ihanete kapatan dağlardır

günlerin girişinde asık

okuyana dokunan hayatım

kırlangıçlar sevmez kışları

bundan kırlangıçsız kaldı kederli suratım

yoksulluk büyüten sokaklarda

avera voltalar attım

balkonlardan damlayan gözyaşlarında

yorgun yüreğimi ıslattım

gırtlağa dayanan bozulmuşluğun hiç mi suçu yok

kendimi hep ben mi kanattım

ben kendime cehennemlerden cennet yarattım

hazan mevsimidir kapımı çalan

geri versin benden güzelliklerimi alan

dönüşe randevuludur gidişlerim

sakıncalı düşlerim

günleri ışıkla işlerim

hayat okyanusunda ilerlerken pupa yelken

çocuklarla paylaştım sevinçlerimi

ve yalnız onlar anladı beni

mutluluk koksun istiyorum hayat onca garibana

sevdiğimin gönlü yeter bana

terk etmeyince düşlerimi

kaç kere yan yattım

bazen de battım

otuzumda saçlarımı ağarttım

yok halimi soran

yine fırtına

yine boran

şiirler yine koynunuza kaçtım

suçum çok büyük belki de

kardeşlik limanına yanaştım

kendimi aydınlığa açtım

insanlığımızı görmemizi engelliyor

dünyayı saran karanlık

bir avuç ışık olsun istiyorum

benden arda kalan

belki çıkar o ışıkta insanlığını gören', 'yalan ne kadar taşır bir insanı mutluluğa(mı)   ulaşır insan acıtarak bir canı körleştirir insanı büyüdükçe nefrat ben size hep dert sıkışın...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/okuyana-dokunan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengi Yitmiş Baharlardan', 'rengi-yitmis-baharlardan-mehmet-ali-ates-588cp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şarap tadında 

bir kızı öpmek istiyorum

kuş yuvası 

dudaklarından

...

Uçurum mavisi ölümlerden çıkarıp

Gelincik tazeliğinde

Mevsimlerin kıyısına iliştirdim

Utangaçlığımı

Paslı akşamların

Oksit kokuları tütsüledi

Düşlerimi

Rengi yitmiş baharlardan

Çiçekler topladım

               Allı

                    Yeşilli

Dilsiz bir sokak lambasının

Gözlerine gizledim

Çıplak Sokaklara giydirdim

Yalnızlığı', 'şarap tadında  bir kızı öpmek istiyorum kuş yuvası  dudaklarından ... Uçurum mavisi ölümlerden çıkarıp Gelincik tazeliğinde Mevsimlerin kıyı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Ateş']::text[], 8.5, '{"poet":"Mehmet Ali Ateş","poet_slug":"mehmet-ali-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/rengi-yitmis-baharlardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Sen Gidersen...', 'eger-sen-gidersen-canan-ucer-z69s3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce melekti, düşlerim

Pembeye çalardı hafiften...

Beynimde eski film müzikleri

.......''İf you go away''

Perilerde gitti, senin izinden

Sabah, kavga etmeden doğmaz ki.........

Gidersen, ne mi yaparım

Bir dram bekleme..........

Yüzlerce ''Kırıkkale hasret geceleri''

Şarabın burukluğu gözlerimde

Ve elimde hüzün, tutkulara sarılırım.......

Duvarlara resimler çizerim

Tuvallerimi parçalayıp.

Komşu çocuklarını uyandırırım

-Bir fincanlık oyuncak verin

Belki,

Bir serseri bulurum benim gibi

Köşedeki meyhaneden

Beynimi karartsın eroin çöküntüsü

Siniflerim kağıdı sonuna kadar...........

Gidersen git, 

Bütün kitaplarımı bağışlarım

İsmetpaşa''da ki tinercilere

Düşlerim vardı......alın diye.

Ve çiçekler kuruturum bakışlarımda

Gözlerimi oyarım, yedi benekli ela gözlerimi

Git, hadi şimdi

Gözün arkada kalmasın

Bir melekti düşlerim

Öpme boynumdan öyle, öpme

Ağlarım.................................................', 'Önce melekti, düşlerim Pembeye çalardı hafiften... Beynimde eski film müzikleri .......''İf you go away'' Perilerde gitti, senin izinden Sabah...', ARRAY['Türk Edebiyatı','Şiir','Canan Üçer']::text[], 8.5, '{"poet":"Canan Üçer","poet_slug":"canan-ucer","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/eger-sen-gidersen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-mehmet-ali-ates-04lfh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Terkedilmiş zamanlar 

Karalıyorum

Takvimden

Kendi gözlerimde

Yaşlanıyorum

Bir kış penceresinde', 'Terkedilmiş zamanlar  Karalıyorum Takvimden Kendi gözlerimde Yaşlanıyorum Bir kış penceresinde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Ateş']::text[], 8.5, '{"poet":"Mehmet Ali Ateş","poet_slug":"mehmet-ali-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/omur-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımı Çok Seviyorum', 'askimi-cok-seviyorum-i-brahim-ethem-bingul-qkec8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeni açmış frezyanın duruluğunda sevdam

Buram buram sen kokan

Kanlı değil sevdam

Kanuni''nin Hürrem''e sevdası gibi

Dağlar aşası değil sevdam

Ferhat''ın şirine sevdası gibi

Sırlara karışmış,sır olmuşların sevdası gibi

Bir sevgi yumağı sevdam

Biraz yoruldum anlaşılamamaktan

Sorun bende mi bilmiyorum

Ben ulaşamazsam da aşkıma

Onu çok seviyorum', 'Yeni açmış frezyanın duruluğunda sevdam Buram buram sen kokan Kanlı değil sevdam Kanuni''nin Hürrem''e sevdası gibi Dağlar aşası değil sevdam ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askimi-cok-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık Çiçeğim', 'sarmasik-cicegim-mehmet-ali-ates-j6n9s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen

Yeşil yapraklarında

Eflatun hüzünler

Yüreğinde sevinçler taşıyan

Hüznümün güz mevsimi

Sevincim 

Baharda yeşillenen

Sen 

Sarmaşık çiçeğim benim

Sende

Yaprağın adı hüzün

Kalbimde açan bir güldür yüzün

                                                           Şubat 2000

                                                           Şubat 2000', 'Sen Yeşil yapraklarında Eflatun hüzünler Yüreğinde sevinçler taşıyan Hüznümün güz mevsimi Sevincim  Baharda yeşillenen Sen  Sarmaşık çiçeğim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Ateş']::text[], 8.5, '{"poet":"Mehmet Ali Ateş","poet_slug":"mehmet-ali-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sarmasik-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keyif', 'keyif-haluk-ozdemir-4p05u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mekanı kapatıyormuş

Kapatsın; Benim gibi

Sarhoşun kaprisini kim çeker

Meyhaneci bile isyanlarda

Gözümün içine bakan gözleri

Hadi kalk git demekte

İnat değil mi oğlum gtimeyecem

Beni kimse beklememekte

Kim tanır beni burda

Sadece adını bildiğim şehirde

İçtiğim rakının sonunda

Keyif kahvemi içerken

Oturuyorum öylesine,anlamsız

Boşca bakan gözlerimle

Anlaşılmaz sözlerimle

Sürüyorum keyfini,sarhoşluğumun', 'Mekanı kapatıyormuş Kapatsın; Benim gibi Sarhoşun kaprisini kim çeker Meyhaneci bile isyanlarda Gözümün içine bakan gözleri Hadi kalk git de...', ARRAY['Türk Edebiyatı','Şiir','Haluk Özdemir']::text[], 8.5, '{"poet":"Haluk Özdemir","poet_slug":"haluk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/keyif-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Günlük Sevda', 'i-ki-gunluk-sevda-erol-dogan-widvn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'At binip kılıç kuşanırlarmış zamanında

  Ölüme meydan okurlarmış cenk meydanında

  Sevenleri kalırmış arkalarında bir dünya

  Birde bir dünyaya sığmayan koskoca bir sevda.

  Bir bakışı yetermiş ömür boyu ona

  Hele bir sözü alıp götürürmüş onu bambaşka dünyalara

  Belli ettirmezmiş öyle dosta düşmana

  Öyleki hissettirirmiş sadece cana canana.

  Kimse göremezmiş onları el ele kol kola

  Nasıl bakarlarmış sonra insanların suratına

  Büyürmüş yüreklerindeki sevda uzaktan uzağa

  Farkında olmasalarda aslında herbiri bir mecnun bir leyla.

  Yokmuş öyle aldatma,yarı yolda koyma

  Nedir bilmezlermiş doyumluk sevda

  O kadar inanırlarmış ki aşka

  Hiçbir güç ayıramazmış onları birlikte çıkınca yola.

  Yumunca biri gözlerini hayata

  Duramazmış diğeri onsuz bir dakika

  Çünkü değilmiş onlarınki iki günlük sevda

  Sığarmış belkide kocaman bir asıra.', 'At binip kılıç kuşanırlarmış zamanında   Ölüme meydan okurlarmış cenk meydanında   Sevenleri kalırmış arkalarında bir dünya   Birde bir düny...', ARRAY['Türk Edebiyatı','Şiir','Erol Doğan']::text[], 8.5, '{"poet":"Erol Doğan","poet_slug":"erol-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-gunluk-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramdan bayrama', 'bayramdan-bayrama-haluk-ozdemir-goch2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakacağım ki son duraktayım

Aman Allahım ne acelesi vardı

Her şey ortada, öylece yarım kaldı

Kazanacağım paralar

Ödeyeceğim borçlar

Hem taksidi bile bitmemişti

Kooperatifteki evimin

Hep beni bekler,işlerim

Ya çocuğum

Çocuğumu bile doyasıya sevemedim

Anlaşıldı farklı olacak bundan sonra derdim,

Gerisini kalanlar düşünsün

Fazla değil iki hafta daha üzülsün

Sonra bayramdan bayrama

O da hava iyiyse

Çamurlu değilse yerler

Belki ziyarete gelirler

Vazgeçtim övgüyü felan

Laf olsun diye iyi bilirdik desinler

O dahi bana yeter', 'Bakacağım ki son duraktayım Aman Allahım ne acelesi vardı Her şey ortada, öylece yarım kaldı Kazanacağım paralar Ödeyeceğim borçlar Hem taks...', ARRAY['Türk Edebiyatı','Şiir','Haluk Özdemir']::text[], 8.5, '{"poet":"Haluk Özdemir","poet_slug":"haluk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bayramdan-bayrama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-fikret-bese-vmioh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece artık,

Camlarda son ışıklar da tükendi; 

Sokak lambaları

Sessizliği aydılatmada sanki,

Boş kaldırımlarda ruhlar geziyor,

Kuşların her biri, bir izbede; 

Damlardan yollara kadar

Tam bir sükûn.

Gece artık

Ve ben

Ayaktayım hâlâ,

Seni düşünüyorum

Biliyor musun? ..

(1988/Ankara)', 'Gece artık, Camlarda son ışıklar da tükendi;  Sokak lambaları Sessizliği aydılatmada sanki, Boş kaldırımlarda ruhlar geziyor, Kuşların her b...', ARRAY['Türk Edebiyatı','Şiir','Fikret Beşe']::text[], 8.5, '{"poet":"Fikret Beşe","poet_slug":"fikret-bese","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gece-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinç II', 'bilinc-ii-ahmet-aksoy-8jwm0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '......................''havayı ısırdı adam ama 

.............................havadan bir tat alamadı

...........................................hava tatsızdı

devrik ruh iklimlerinde yamur çağı,

kimbilir, belki de bu son çağrı,

ah! fertler ormanında bilinçsiz,

aheste geçen trenler durağı,

kap kaç ikindisinde kont ve kontes,

gizlenmiş düşlerde düşes,

ah! bu kaçıncı toplumcu manifesto

kendinden habersiz ruhlar ovasında,

öz; tekler uyanınca, genleşir 

bütün mukaddes değerler', '......................''havayı ısırdı adam ama  .............................havadan bir tat alamadı ...........................................', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilinc-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Güçler', 'karanlik-gucler-fikret-bese-1bz8w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece

Deniz uyur,

Gök uyur,

Yer uyur.

Uyur dünya,

Durulur; 

Sessizlik

Tahtına kurulur

Ve her yer, her şey

Karanlıklardan sorulur...

(Ankara/6.3.2002)', 'Gece Deniz uyur, Gök uyur, Yer uyur. Uyur dünya, Durulur;  Sessizlik Tahtına kurulur Ve her yer, her şey Karanlıklardan sorulur... (Ankara/6...', ARRAY['Türk Edebiyatı','Şiir','Fikret Beşe']::text[], 8.5, '{"poet":"Fikret Beşe","poet_slug":"fikret-bese","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/karanlik-gucler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçemem Senden', 'gecemem-senden-guner-kaymak-rotc9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yusuf gibi kuyulara atilsam 

Köle diye pazarlar''da satilsam 

Ibrahim gibi atese''de atilsam 

Yine''de geçemem senden sevgilim 

Canli canli derimi''de yüzseler 

Isa gibi çarmiha''da gerseler 

Vazgeç diye dünyayi da verseler 

Yine''de geçemem senden sevgilim 

Apdal olup diyar diyar dolassam 

Ferhat gibi kayalar''la ugrassam 

Zalimlerin zulumüne de ugrasam 

Yine''de geçemem senden sevgilim 

Birer birer tirnaklari''mi sökseler 

Agzimdaki tüm disleri çekseler 

Vatanim''dan bile sürgün etseler 

Yine''de geçemem senden sevgilim 

Eyup''ün sabrina mahruz kalsam da 

Kerem gibi ateslere yansam da 

Senden daha güzelini bulsam da 

Yine''de geçemem senden sevgilim 

Cahil ile yobazlarla ugrassam 

Siyasetin çamuruna bulassam 

Dört iklim yedi bucak dolassam 

Yine''de geçemem senden sevgilim 

Geçtigim yollara barikatlar kurul sa 

Tutundugum bütün dallar kiril sa 

Güner der katlime karar kilin sa 

Yine''de geçemem senden sevgilim 

Güner Kaymak / Amsterdam 21.02.2004', 'Yusuf gibi kuyulara atilsam  Köle diye pazarlar''da satilsam  Ibrahim gibi atese''de atilsam  Yine''de geçemem senden sevgilim  Canli canli der...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gecemem-senden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Dörtlükler IV', 'yeni-dortlukler-iv-ahmet-aksoy-wf39l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İronik Teşbih II

allegro ritminde kör topal gibi

dans etme zorunluğunda bir rakkas

sarkıt ironiye alegoridir

parametresi kendi içindedir

Korsan

düş kaçkını us kaçmazı kor demir

kalk sonra tekrar yüreğime eğil

ve diri diri yak beni istersen

tekerrür olsun çektiğim çileler

Mış Gibi Bir Dörtlük

zihnim doğurganlıktan ikmale kalmış

bu kaçıncı detay sırra kadem basmış

fikrin hikmetinin sureti ara bozan

gelişimi yanına alıp uzaklaşmış

Sek

nicedir bir silah fabrikası gibi beynim; 

kendime yönelik silahlar üretiyor.

örgüt evi gibi yüreğim; ne zaman

baskın yese yakılıyor, sevmediklerim

Sabotaj

hey sabotajcı! boımbayı bırak

arkana bakmadan çık sonrada

beni yüreğimde yalnız bırak

söz! bu sefer öleceğim sana', 'İronik Teşbih II allegro ritminde kör topal gibi dans etme zorunluğunda bir rakkas sarkıt ironiye alegoridir parametresi kendi içindedir Kor...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yeni-dortlukler-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serilir odamın dört duvarına', 'serilir-odamin-dort-duvarina-temel-beydi-yfrqr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Serilir odamın dört duvarına

Gözlerinden akşama ayırdığım hüzün

Hava sıcak ve kaygılı

Rüzgar soyunur ve titrer yatağımda

Öyle bir yalnızlık olur ki

Aşk bile yorgun ve uykuludur

Ey penceremde seğiren kız,

Ey resmimdeki negatif

Ey ses ve gecede unutkan aydınlık,

Sancılı derman

Al beni sıkılganlığımdan', 'Serilir odamın dört duvarına Gözlerinden akşama ayırdığım hüzün Hava sıcak ve kaygılı Rüzgar soyunur ve titrer yatağımda Öyle bir yalnızlık ...', ARRAY['Türk Edebiyatı','Şiir','Temel Beydi']::text[], 8.5, '{"poet":"Temel Beydi","poet_slug":"temel-beydi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/serilir-odamin-dort-duvarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Gözler', 'yorgun-gozler-vahittin-bozgeyik-3aaab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorgun gözlerimin bakışı sensin,

Çöldeki serabın yakışı sensin,

Sevda kiliminin nakışı sensin; 

Beni yumak yumak dokusana yar...

Aşığım,gözümden okusana yar! ...

Çağır da geleyim,dağlardan aşır,

Olmayan aklımı yeniden şaşır,

Yaralı bir kuşum,tuzağa düşür

Hadi bülbül gibi şakısana yar; 

Aşığım gözümden okusana yar! ...', 'Yorgun gözlerimin bakışı sensin, Çöldeki serabın yakışı sensin, Sevda kiliminin nakışı sensin;  Beni yumak yumak dokusana yar... Aşığım,gözü...', ARRAY['Türk Edebiyatı','Şiir','Vahittin Bozgeyik']::text[], 8.5, '{"poet":"Vahittin Bozgeyik","poet_slug":"vahittin-bozgeyik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yorgun-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlerde aynalı bir gardıroptur odalar', 'evlerde-aynali-bir-gardiroptur-odalar-temel-beydi-j1kvl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evlerde aynalı bir gardıroptur odalar

Camlarında siyah gölgeler tenin utangaç katranı

Bazen zikri bir şair silüeti loş ışıklarda duman

Ses ve çizgide anlam çökerten sis

Bazen kahir bir adam bağırtısı

Odalarda fısıltılı telaş

Sokakta ürkek zabit

Perdelere vurur esrik tütsüsü

Geceye fırlatılmış izmarit 

Gibi yavaşça sönmekteyken ay

Evlerde aynalı bir gardıroptur odalar

Öpüşü yaka cebinde unutulmuş

Dudak tenli gömlekler asılan

Ki rast gele gezinirken ellerimiz

Yapışır tene

Eski bir aşkın yangını', 'Evlerde aynalı bir gardıroptur odalar Camlarında siyah gölgeler tenin utangaç katranı Bazen zikri bir şair silüeti loş ışıklarda duman Ses v...', ARRAY['Türk Edebiyatı','Şiir','Temel Beydi']::text[], 8.5, '{"poet":"Temel Beydi","poet_slug":"temel-beydi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evlerde-aynali-bir-gardiroptur-odalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Artık Ne Olur...', 'aglama-artik-ne-olur-hasan-basri-kale-yau5o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatımın değişmez tek gerçeği

Sevincin ardından gelen hüzün..

Belki de değişmiştir diye sevinirken..

Baktım..duruyor yerinde değişmeden

Bir kez daha anladım bugün..

Bir içten gülüşe hasret yüzünde.

Aynı ızdırap vardı dün de bugün de..

Yine gözyaşların gözümün önünde.

Ağlama artık ne olur dur sözünde...

Dünyayı seninle buldum yaşanmaya değer

Kabulümdür acı adına ne varsa sendense eğer..

Titreyen sesini duysa ağlar melekler

Ağlatanlar hesabı nasıl verecekler..? 

Bırak başkasının olsun sevinçler 

Nasıl olsa Sevdalar bizim..

Dağlar taşlar adını söyler

Gün onlarınsa yarınlar bizim..

22.02.2004 01.30', 'Hayatımın değişmez tek gerçeği Sevincin ardından gelen hüzün.. Belki de değişmiştir diye sevinirken.. Baktım..duruyor yerinde değişmeden Bir...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aglama-artik-ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Kondu Şiir', 'gece-kondu-siir-zafer-zengin-etnika-auml1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gerci yazmadım daha

proje aşamasında

kaçak satırlar atacağım arasına

gecekondu şiirlerim olacak

varoş kokacak bir nevi

bir nevi hasret

sıcak sobalar da kestane patlaması

ciğerlerin dağlanması

bir nevi komsuluk

yoldaşlık iste

kapı önü sohbet

kaçak katlar cıkamadık

bahceler de serpildi şiirlerimiz..domates tadında...

22 subat 2004', 'gerci yazmadım daha proje aşamasında kaçak satırlar atacağım arasına gecekondu şiirlerim olacak varoş kokacak bir nevi bir nevi hasret sıcak...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gece-kondu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bereket', 'bereket-zafer-zengin-etnika-u1or0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bereket 

demek 

göbeğin

anadolu da..

Harman

yeri işte

göbek

kadında...

Tarihi yazanlara...

22 Subat 2004', 'Bereket  demek  göbeğin anadolu da.. Harman yeri işte göbek kadında... Tarihi yazanlara... 22 Subat 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bereket-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yazgının Öyküsü', 'bir-yazginin-oykusu-musa-h-b-yj80q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '...........

bir günbatımı

kucağında zehirlenince biricik tutkusu

dudağında titreyen bir dilekçe

Sonsuz''a yücelince sonlunun ağıtları

alevlenince bir yerlinin göğe sevdası

ve tamamlanınca gönlün yarım kalan şarkısı

bir ulu ışık sızacaktı

umutların can çekiştiği kuytudan

üstü-başı sırılsıklam

güneşin gözyaşları bir ışık

bu nasıl evren, bu nasıl devrandı

sağına baktı: ağlayıncaya kadar güldü

soluna baktı: gülünceye kadar ağladı

her şey Varın yoka yazgısıydı çünkü

ağlatan da O''ydu güldüren de

ben güneşin çocuğuyum

tanrılara meydan okumuşum

yarasalar sevmez beni diyordu.

sahi o şafaksökümü

bir ulu ışık doğmuştu tanrılar mezarlığından

bir derviş belirmişti manastırın kapısında

melekler bile süzülmüştü tapınağın yanaklarına

ve bir yolculuk görünmüştü mağaradan

Hızır''la Tûr dağına

hayır hayır bir gök bûsesiydi bu

öksüz toprağın efsunlu gözlerine konmuştu.

...........

elveda! 

MUSA HÛB

27 Aralık 1998 Pazar

Altunizade/İstanbul', '........... bir günbatımı kucağında zehirlenince biricik tutkusu dudağında titreyen bir dilekçe Sonsuz''a yücelince sonlunun ağıtları alevlen...', ARRAY['Türk Edebiyatı','Şiir','Musa Hûb']::text[], 8.5, '{"poet":"Musa Hûb","poet_slug":"musa-h-b","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-yazginin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Caglayan Irmağım Kızım.', 'caglayan-irmagim-kizim-orhan-balta-ql7xp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ceylan gözlü...tilki bakışlı...

kısrak belli, aslan yurekli, kaplan pençeli..

dogru sözlü kızım; 

Yaşanmazları yaşamış, yaşadıklarından uslanmamış..

sevda yüreklim..

Bir yetim yureğin esareti..

bir ananın cesareti..

sevdanın gülüşü.. mazlumun bakışı...

kor ateşin yakışı var sende..

Sende bir anlam var da! 

anlaşılmazlıkların, tümü sende..

Dün yok..bugünü yaşadın bitti..yarın nasılsa yaşanacak..,

gelecekte..belki sevdan...belki de yaşadıkların kazanacak..

buna garantim yok.

senin de olamaz.

birinin var mı dersen..

elbet bunu bana kimse soramaz..

En cok sevdiğim yanın..gözlerindeki ışıltılar..

hele sevdalı..yureğindeki kıpırtılar..

bazen depremler gibi. sarsıyor beni

ve ben..

yeni baştan başlıyorum seni tanımaya..

eksik kalan bir duvarı tamamlar gibi..

bazen harcını fazla..

bazen de tuğlayı.. yanlış koyduğumu düşünüyorum..

Belki de sen her şeyin doğrusunu yapıyorsun..

ben yanılıyorum.

Ama....bir şeyden eminim.

ceylan gözlü, ürkek uykulu.. evcimenim..

yavrusunun anası

yuvasının dişi kuşu,

Seni seviyorum...

Şafak tenli..kavga yürekli kızıma.. Sevgilerimle.

Orhan Balta', 'Ceylan gözlü...tilki bakışlı... kısrak belli, aslan yurekli, kaplan pençeli.. dogru sözlü kızım;  Yaşanmazları yaşamış, yaşadıklarından usla...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/caglayan-irmagim-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Endişesi+', 'dost-endisesi-bayram-tunca-k11oj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen şöyle düşünmekten alıkoyamam kendimi

Hacı Bayram Veli misali sınasam tüm dostlarımı

Acaba. bir tane dahi sadık dostum kalır mıydı ki

Bazı kaygılarım nedeniyle, ertelerim bu isteğimi

20.02.2004-20:02

''Aşk Ateşten Gömlek''

İtiraf 

Hacı Bayram Veli makamında olamadığımdan,

Dostlarımı da sınamaya hakkım olmasa gerek

Sütten ağzı yananların, ayranı üfleyerek içmeleri 

Çok da anormal görülmemesi gerekir zannındayım', 'Bazen şöyle düşünmekten alıkoyamam kendimi Hacı Bayram Veli misali sınasam tüm dostlarımı Acaba. bir tane dahi sadık dostum kalır mıydı ki B...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dost-endisesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yüzlü Kar', 'i-ki-yuzlu-kar-kerem-ulukir-4lxjy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoğun bir beyazlık

Hiç durmadan yağıyor

Bu beyazlık iki yüzlü

Pencereden güzel dışarıda kötü

Kaç araba yolda kaldı

Kaç insan ruhunu yolladı

Soğuk büyük küçük tanımıyor

Kimsesizleri sokak çocuklarını öldürüyor

Allah ın takdiri ilahisi

Karında var bir çok iyiliği

Kar soğuk ve beyaz

Çok soğuk elde tutulmaz

Karın iyiliği

Çocuklar için tatili

Tümseklerden kayması arkadaşa atması

Kar hiçbir zaman değişilmez olsada cani', 'Yoğun bir beyazlık Hiç durmadan yağıyor Bu beyazlık iki yüzlü Pencereden güzel dışarıda kötü Kaç araba yolda kaldı Kaç insan ruhunu yolladı ...', ARRAY['Türk Edebiyatı','Şiir','Kerem Ulukır']::text[], 8.5, '{"poet":"Kerem Ulukır","poet_slug":"kerem-ulukir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iki-yuzlu-kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimizle Can Vereceğiz', 'sevgimizle-can-verecegiz-cuneyt-sahinoz-u5v6c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsan sevilmeli

Kusurları olsa da sevilmeli insan

Onu güzelleştiren

Biraz da kusurları değil mi? 

Mümkün müdür? Ki

İnsanların tam mükemmelliği.

Dünya o zaman çekilir miydi? 

Sıkıntı yaratmaz mıydı? Mükemmellik.

Çirkinin olmadığı yerde

Kim bilebilirdi? Ki  güzelliği.

Yaşadığımız zıtlıklar dünyası değil mi? 

Her yerin kapkara olduğu yerde

Kim bilebilirdi? Ki aydınlığı.

İnsanlar birbirlerine sımsıkı sarılmalı,

Sevgi bağları ile kördüğüm olmalı.

Kusurlu insana şefkat beslemeli

Sevgi ile sarmalı her bir yanını.

İnsanda meziyet aramaya gerek olmamalı,

Sadece insan olması yetmeli.

Yaratılmışların en güzeli,

Yüce Allah’ın en güzel eseri

Olduğundan sevilmeli insan.

Zaten Allah her şeyi sevgiden yaratmadı mı? 

Bedenimizde ki organlar gibi

Birbirine bağlanmalı insan.

Birinin derdi hepsinin olduğu gibi

Birinin sevinci de hepsinin olmalı.

Bu cazibe bir araya getirmeli

Kardeş yapmalı insanları.

Sevgi delil ister,ispat ister,

Sevdiğinden bitip tükenmek ister,

Belası çoktur sevgi duygusunun,

Aşmadan ulaşmak zordur sevgiye.

Yolun zorluğu ise

Sevgilinin kim olduğuna bağlıdır.

Sevmek değerini bilene madalyadır,rütbedir.

Onun tarafından sevilmekte “miraç”tır.

Sen ne kadar çok seviyorsan

Sevgin o kadar çok karşılık görür.

Kalplerimizdeki sevgiyi evrenselleştirmeliyiz.

Ozonu dahi sevgimizle tıkayabilmeliyiz.

Bu şehirden taşmalı sevgi,

Taşmalı ve sarmalı bütün ülkeleri.

İnsanların sevgi ile dolmalı yürekleri,

İşte o zaman

Güzellikleri düşündüğümüzde

Anlayacağız güzel gördüğümüzü

Ve ne kadar güzel göründüğümüzü.

Lezzet alacağız yaşadığımız hayattan,

Suçluları dahi bağışlayacağız,

Hisse hisse paylaşarak suçları.

Günah için suçluya az bir hisse bırakarak

Şeytanı bile şaşkına çevireceğiz

O kadar küçülecek ki suçlar,

Af edilebilir olduğunu göreceğiz,

O kadar ki; 

Canımıza kast edenleri bile af edeceğiz,

Onlara can vereceğiz sevgimizle…', 'İnsan sevilmeli Kusurları olsa da sevilmeli insan Onu güzelleştiren Biraz da kusurları değil mi?  Mümkün müdür? Ki İnsanların tam mükemmelli...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Şahinöz']::text[], 8.5, '{"poet":"Cüneyt Şahinöz","poet_slug":"cuneyt-sahinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sevgimizle-can-verecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Mendirek Mezarlığı...', 'mendirek-mezarligi-naime-erlacin-49u7n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- C.Baudelaire anısına…

yüreğin mendireği küstü

suya kapılıyor taşlar

içime alıyorum dalgaları

soğuk ve acımasızlar

deniz üşütüyorum bağrımda

işgâldesiniz kıyılarım ey! 

Albatros* hükmündeki ruhun 

kaptansız fırtınasında 

direkler paramparça

ufkumda bir mendirek yıkılıyor

ölümle dinerdi acılar 

varsın kadere kalsın yazmak

susacağım artık 

dimdik duracağım 

ağulu yürek intiharımda

pullarda ağıt seğirten 

son masum balığa 

gümüşi bir iz bırakmaya gidiyorum

ölü bir mendirekten fermanlı

meleklerin yittiği azgın sulara

mendirek mezarlığına... 

(*)      Baudelaire’in ''Albatros'' şiirinde, albatros şairi simgeler. Çağrışımlarla şiirini oluşturur. Kendini sürgünde gibi hisseder. Hep başka bir yerin özlemi ve arayışı içindedir. Çocukluğundan beri yalnızlık duygusu yakasını bırakmamış ve yazgısı olmuş, herkesten farklı olduğunu duyumsamıştır. ''Herkesin tersine ve herkese karşı vardım kendi varlığımın bilincine''. Her zaman kendi özelliğini ve varlığını aramış ve kendi içine dalmıştır. Kendisini gereksiz biri olarak gördüğünden sık sık intiharı düşünmüştür…(Kaynak: Hürriyetim: 11 Haziran 2001)   

(22 Şubat 2004)', '- C.Baudelaire anısına… yüreğin mendireği küstü suya kapılıyor taşlar içime alıyorum dalgaları soğuk ve acımasızlar deniz üşütüyorum bağrımd...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mendirek-mezarligi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sa', 'sa-senol-denizci-hvwai', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gür sesli karşilaşmalar 

çınladı odalarda 

aynı anda

şiirler sürgün edildi kanıma

derin dalış, ağır vurgun

hızın baş döndüren travması

Sonra 

çivili tahta, yalınayak Akdeniz (...) 

yalnızlığıma geldiniz.

Keşke

sonsuzluğuma da gelseniz...

20.02.2004', 'Gür sesli karşilaşmalar  çınladı odalarda  aynı anda şiirler sürgün edildi kanıma derin dalış, ağır vurgun hızın baş döndüren travması Sonra...', ARRAY['Türk Edebiyatı','Şiir','Şenol Denizci']::text[], 8.5, '{"poet":"Şenol Denizci","poet_slug":"senol-denizci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi', 'yedi-senol-denizci-4eo9k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yediydi, sabahtı, eksikti

kırışık yüz, ütülü yastık

karıncalanmış eklemler çoğaltıyor

yabancılıyordu birbirini

İçsel karanlığın deliliydi

Aynada ki 

ötenazi eğilimi

20.02.2004', 'Yediydi, sabahtı, eksikti kırışık yüz, ütülü yastık karıncalanmış eklemler çoğaltıyor yabancılıyordu birbirini İçsel karanlığın deliliydi Ay...', ARRAY['Türk Edebiyatı','Şiir','Şenol Denizci']::text[], 8.5, '{"poet":"Şenol Denizci","poet_slug":"senol-denizci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yedi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Hayallerin Çocuğu Oldu', 'dusler-hayallerin-cocugu-oldu-sadik-softa-c22hb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömrüm gecelerin içinde uzar; 

Düşler hayallerin çocuğu oldu.

İçimi titretir senden gelenler; 

Gizli kapıların eşiği oldu.

Gizli bir anahtar açar kalbimi,

Uzanır gelir de seçer kalbimi,

Sanki deler deler geçer kalbimi,

Gece düşlerimin beşiği oldu.

Sırra kadem basar, gözlerin sonra,

Mısralarda koşar sözlerin sonra,

Seni her dem her dem özlerim sonra,

Senden gelenlerin keşiği oldu.

Sırça sarayımın sırrı bozuldu,

Yürek yangın yeri dili çözüldü,

Nedeni bellidir, neden üzüldü? 

Sinem sevda delik deşiği oldu.', 'Ömrüm gecelerin içinde uzar;  Düşler hayallerin çocuğu oldu. İçimi titretir senden gelenler;  Gizli kapıların eşiği oldu. Gizli bir anahtar ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dusler-hayallerin-cocugu-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıtlar Ağlıyor', 'agitlar-agliyor-sadik-softa-2dzlk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağıtlar sıraya geçmiş ağlıyor; 

Sevda yüreğimi biçmiş ağlıyor; 

Gözüm gözlerini seçmiş ağlıyor; 

Ağladıkça gözüm, ağlar ağıtlar.

Temmuz güneşinde sam vurur gibi; 

Akıldan, mantıkdan dem vurur gibi; 

Sanki duygulara gem vurur gibi; 

Ağladıkça gözüm, ağlar ağıtlar.

Bereketi akar şiire bile; 

Ağıtlar söyletir şaire bile; 

Yaya kalır fasit daire bile; 

Ağladıkça gözüm, ağlar ağıtlar.

Çökerse kapıma kalkmaz bir daha; 

Donyağ gibi olur akmaz bir daha; 

Yapşır gönlüme çıkmaz bir daha; 

Ağladıkça gözüm, ağlar ağıtlar.

Ağıtlar sıraya geçmiş ağlıyor.

Gözlerim gözünü seçmiş ağlıyor.

Damla damla kan yaş içmiş ağlıyor.

Ağladıkça gözüm, ağlar ağıtlar.', 'Ağıtlar sıraya geçmiş ağlıyor;  Sevda yüreğimi biçmiş ağlıyor;  Gözüm gözlerini seçmiş ağlıyor;  Ağladıkça gözüm, ağlar ağıtlar. Temmuz güne...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/agitlar-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastalık', 'hastalik-umit-mutlu-1fqla', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Humma içinde yanar iken

İçimde gaip bir ses duyuluyor

Ayalarım kızarmış pişiyor

Diyarlar gezdim çaresi bulunmuyor

Hayatım olmuş yatakta mahküm

Ömrün sonu geliyor malüm

Sarp yolundan geçmem mümkün

Ben hoşnut um bu hayattan

                                       malüm.', 'Humma içinde yanar iken İçimde gaip bir ses duyuluyor Ayalarım kızarmış pişiyor Diyarlar gezdim çaresi bulunmuyor Hayatım olmuş yatakta mahk...', ARRAY['Türk Edebiyatı','Şiir','Ümit Mutlu']::text[], 8.5, '{"poet":"Ümit Mutlu","poet_slug":"umit-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hastalik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemiyorum', 'bilemiyorum-sadik-softa-ftwnx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yak istersen gönlündeki alevle; 

Senden sevgi, sevda dilenmiyorum.

Sana sevdalanmak elimde değil; 

Nedenini ben de bilemiyorum.

Gelecek ne olur, dediğim anda? 

Ya önümde durdun, ya da yanımda; 

Olacaklar oldu işte sonunda; 

Seni yüreğimden silemiyorum.

Çıkamam geceden, uzakta gündüz; 

Artık mantık durdu, akıllar dümdüz; 

Seni de sararsa sevda görürüz; 

Gel desen de bitti, gelemiyorum.

Çıkar şu dilinden, baklayı şöyle; 

Sebepsiz, izahsız, bırakma öyle; 

Beni bu hallerde bırakma böyle; 

Yüreğim yanıyor, gülemiyorum.

Yüreğim yanıyor, gülemiyorum.

Seni yüreğimden silemiyorum.

Gel desen de bitti, gelemiyorum.

Nedenini ben de bilemiyorum.

Senden sevgi, sevda dilemiyorum.

Çankırı-22.02.2004', 'Yak istersen gönlündeki alevle;  Senden sevgi, sevda dilenmiyorum. Sana sevdalanmak elimde değil;  Nedenini ben de bilemiyorum. Gelecek ne o...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bilemiyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalmiş', 'hayalmis-umit-mutlu-g1ff1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'senin gibi giyinmiş bir kız

aynı boyda aynı yaşlarda

elbisesi aynı seninkisi gibi

sarı saçları örtüyor gözlerini

birde durakta bekleyişi varya

senin beni beklediğin gibiydi oda

kaçıncı otobüs geçti binmedi hala

sen sandım soracaktım bir anda

sabır ile devam ettim izlemeye

belki sensin beni bekliyorsun diye

saatler geçti sen duraktasın yine

otobüsleri sayamadım binmedin birine

başladım sana doğru yürümeye

artık ananmıştım o sensin diye

bana bakıyordun,elimi uzattım yüzüne

bir anda kayboldun elim kaldı nefsinde', 'senin gibi giyinmiş bir kız aynı boyda aynı yaşlarda elbisesi aynı seninkisi gibi sarı saçları örtüyor gözlerini birde durakta bekleyişi var...', ARRAY['Türk Edebiyatı','Şiir','Ümit Mutlu']::text[], 8.5, '{"poet":"Ümit Mutlu","poet_slug":"umit-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayalmis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşantım Ellerinde Saklı (süveyda)', 'yasantim-ellerinde-sakli-suveyda-garip-teymur-12kr6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Murathan MunganınYalnız Operasına 

Tek kişilik bilet almıştık

Ama iki kişiydik

İkimizde aslında Cezmi Ersözün 

Birer şizofreniydik.

Her zaman küçük harflerle başlar aşk

Heceler kelimelere dönüşürken 

Kelimelere cümle olmak yasak.

Dilek tutmak yasaklanmıştı bize

artık yıldız kaysa görmeyecektik

Ve duymayacaktık 

Aşkın çırpınışlar içindeki 

Nefes alış-verişini

Gece yarıları salaş meyhanelerden ayrılıp

Aya doğru yolculuk yapardım

Hele birde yağmur yağsın

Bir çocuk gibi gelip kapında ağlardım

devrik cümleler kurarak çıkmıştım yola 

devrik yaşantılar kurmuştum oysa

bulutlara perde çekmiştim senin yokluğunda

intiharlar kuşanıp öylece gelmiştim kapına

ölüm sözcüğü dudaklarımda 

ve yaşamak namına ne varsa bırakmıştım

kapalı kapılar ardında 

blöftü sana göre

bana göre gencecik bir ömrün son demleri

bir damla yaştın halbuki

ya kuruyup gidecektin 

ya da hayatımda bırakavaktın tüm izlerini

gecenin bir yarısında 

parmak izlerini buldun hayatımda

sen arkana dönüp baktığında 

belki de sebebini hiçbir zaman öğrenemeyeceğin 

bir ölüm

ve boynu bükük bir aşk yatıyordu

kör karanlığın tam ortasında 

dirilişimdin oysa 

dünyaya yeniden gelişim

ey süveyda

bu son b(ölüm) dür benim için

ey süveyda 

kendine vebana aşkı öğretmeden usulca çekip gittin.

sevdiğim

tarihi yargıladığım bir dönemdeyim

şairlere anlam veremediğim 

her şeye rağmen seni sevdiğim 

kimseciklerin bilmediği bir yerdeyim

sevdiğim ellerini uzatmazsan öleceğim

(süveydam tek kelimeden oluşan

kocaman bir klabalıktır.

kalabalık olduğu kadar

sessizlik ve yalnızlıktır...)', 'Murathan MunganınYalnız Operasına  Tek kişilik bilet almıştık Ama iki kişiydik İkimizde aslında Cezmi Ersözün  Birer şizofreniydik. Her zama...', ARRAY['Türk Edebiyatı','Şiir','Garip Teymur']::text[], 8.5, '{"poet":"Garip Teymur","poet_slug":"garip-teymur","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yasantim-ellerinde-sakli-suveyda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak', 'yasak-vahittin-bozgeyik-trvfx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hoşgeldin,taşralı Hüseyin

İyi etmedin geldiğine bilesin...

Oturabilirsin en büyük köşesine,

En büyük kahvenin,

Bir çay içebilirsin en demlisinden,

Yirmibeşkuruş varsa cebinde,

Yasak değil...

Hoşgeldin,taşralı Hüseyin 

İyi etmedin geldiğine bilesin...

Kum torbası taşıyabilirsin

En büyük inşaatlarda,

Kazabilirsin toprağı akşama değin...

Güç kaldıysa kollarında

Yasak değil...

Hoşgeldin,taşralı Hüseyin

İyi etmedin geldiğine bilesin...

Umutlarını yiyebilirsin soğan ekmek yerine,

Adımlıyabilirsin en büyük kaldırımlarını

Bu kentin,

Parklarda sabahlayabilirsin,üşümezsen,

Yasak değil...

Hoşgeldin taşralı Hüseyin

İyi etmedin geldiğine bilesin...

Sevebilirsin insanları

Sevebilirsin özgürlüğü bak:

Tutsak ederler ha karışmam

Yasak! ...

                            

                       1968 (Yılın Şiiri)', 'Hoşgeldin,taşralı Hüseyin İyi etmedin geldiğine bilesin... Oturabilirsin en büyük köşesine, En büyük kahvenin, Bir çay içebilirsin en demlis...', ARRAY['Türk Edebiyatı','Şiir','Vahittin Bozgeyik']::text[], 8.5, '{"poet":"Vahittin Bozgeyik","poet_slug":"vahittin-bozgeyik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yasak-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Sevgisi', 'allah-sevgisi-kerem-ulukir-ayje1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allah her zaman birdir

İnsanlar Allah''ı sevmelidir

Hiçbir zaman gurur yapma

Şeytan gibi kötülük yapma

Allah sevgisi çok güzeldir.

Yeryüzünü yaratmadımı Allah

Niye Allaha inanmıyorsun

Kendi sonunu hazırlıyorsun

Cennet cehennem hayatını

Peygamberleri Dünyayı

Canlı ve cansız varlıkları

Allah yaratmadımı

Allahın birliğini

Gücünü kudretini

Görmedinmi işitmedinmi

Sağır ve kör gibi

Evet işte böyle insanoğlu

İçkiyi kumarı oynar

Yapmadım diye yalan atar

Kandırıp kurtulmaya bakar

Sen hiçbir zaman olma böyle

Nankörlüğü ve israfı bir dolaba kilitle

İçkiyi ağzına bile deydirme

Kumara hiçbir zaman el sürme

Şimdi bu şiirden ders çıkarın

Hiçbir zaman kötülük yapmayın

Allaha ve birliğine inanın

Allah sevgisini kalbinizde barındırın', 'Allah her zaman birdir İnsanlar Allah''ı sevmelidir Hiçbir zaman gurur yapma Şeytan gibi kötülük yapma Allah sevgisi çok güzeldir. Yeryüzünü ...', ARRAY['Türk Edebiyatı','Şiir','Kerem Ulukır']::text[], 8.5, '{"poet":"Kerem Ulukır","poet_slug":"kerem-ulukir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/allah-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peygamberler', 'peygamberler-kerem-ulukir-tmic7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nur saçlı nur yüzlüler 

Çok acı çekmişler 

Her kavimde vardır Allah'' a inanmayan 

Peygamberlerde sonuçta bir insan 

Peygamberler aslında aracıdır 

Her zaman Allah yolunu anlatır 

Zalimlik de yapılsa ateşede atılsalar 

Bu davada geri adım atmazlar 

İbrahim Nuh Muhammed Adem 

Bir kaçıdır güzel Peygamberlerden 

Her zaman zorlukları yenmişler 

Hiçbir zaman isyan etmemişler 

Allah her zaman birdir 

Peygamberleri bilmem kaç bindir 

Böyle güzel insanlara 

Her zaman inan Allah''a', 'Nur saçlı nur yüzlüler  Çok acı çekmişler  Her kavimde vardır Allah'' a inanmayan  Peygamberlerde sonuçta bir insan  Peygamberler aslında ara...', ARRAY['Türk Edebiyatı','Şiir','Kerem Ulukır']::text[], 8.5, '{"poet":"Kerem Ulukır","poet_slug":"kerem-ulukir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/peygamberler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelinim', 'gelinim-i-brahim-ethem-bingul-k76i5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelinim,sevda bahçemi süslüyorum sana

Ağaçları,maviye boyadım ve bütün gülleri

Çimleri pembeye,sen seversin diye

Gökyüzüne gökkuşağını koydum,ucu bahçemde

Güneş ışıl ışıl üstümüzde

Ay karşımızda ayna

Gelin çiçeğin,yıldızlardan bir demet

Gelin tacın,deniz dibinden gelmiş inciden

Ve binlerce melek nedimen

Uzat elini gelinim,ben seninim..', 'Gelinim,sevda bahçemi süslüyorum sana Ağaçları,maviye boyadım ve bütün gülleri Çimleri pembeye,sen seversin diye Gökyüzüne gökkuşağını koydu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gelinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum (Akrostiş)', 'seni-dusunuyorum-akrostis-hasan-ozen-878am', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'S eni düşünüyorum ellerim şakaklarımda

E llerimin birinde kadeh diğerinde sigara

N asılda anımsıyorum seninle birlikte

 İ çinde dolaştığımızı ÇAĞLAYAN sokaklarında

D ramatik bir görüntü zannedip

Ü zülüyorum kendi kendime

Ş efkatini duyamadığım anlarda 

Ü şüyor ama çok üşüyorum

N iye terkettin beni

Ü züyorsun ÇAĞLAYAN sokaklarında

Y ine aklıma geliyor seninle 

O çabucak biten yürüyüşlerimiz

R enkli geçen tütün mecileri

U nutamam yıllar geçsede,Sen unutabilirmisin

M utluluk fışkırıyordu yüreğimizden', 'S eni düşünüyorum ellerim şakaklarımda E llerimin birinde kadeh diğerinde sigara N asılda anımsıyorum seninle birlikte  İ çinde dolaştığımız...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-dusunuyorum-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Koymuşum Adını', 'kader-koymusum-adini-hasan-ozen-cikw0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi senden de bir yara kaldı yüreğimde

Şimdi birbirimizden uzak şehirlerde olsak da

Şimdi sevmeyi denesek de ikimiz

Umut yok biliyoruz ki başka yar severiz

Hatırlıyorum o geceyi ÇAĞLAYAN''da

Suç arıyorum kendimde ayrılışımıza neden olan

Evet GÜLÜM tek suçum seni ölesiye sevmek

Gözlerimin önünde canlanıyor son dakika

Gözlerini çekiyorsun gözlerimden 

Mutluluklar diliyoruz birbirimize

Yarım kalan mutlulukları bir daha bulabilirmiyiz

Birbirimizden uzak iki şehirde 

O aşkın ateşini söndürebilirmiyiz

''Yeni AŞK eskisini söndürür'' derler

Yalan billahi yalan! ... Ama 

Böyle söylemekten başka çare yok 

Birkez araya ayrılık girmişken

Bir kuru elveda ile başladı kopuşumuz... Sonra,

Günlerce mektuplarınla selamını bekledim sıcak

Unutmak sevmek gibi olmuyor

Duy sesimi GÜLÜM bu ateş içimde daima yanacak

Başkasını sevmek, hatta sevmeyi denemek bahane

Belki de unutmak mümkün değil 

Alıp başımı gitsem de uzak diyarlara

Aşkın kalbimde, kalbim aşkına esir

Kim ne derse desin,Sen de unutmuş olsan

Benim için unutmak mümkün değil.', 'Şimdi senden de bir yara kaldı yüreğimde Şimdi birbirimizden uzak şehirlerde olsak da Şimdi sevmeyi denesek de ikimiz Umut yok biliyoruz ki ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kader-koymusum-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-hasan-ozen-vek3w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnız şu satırlardır 

Senden bana kalan

Seni bana hatırlatansa 

Yakıp kül ettiğin kalbimdir

Yalnız ızdıraptır 

Kalbimde yer eden

Şu sonsuz boşluktur

Senden bana kalan son hatıran

Senden önce gülmeyi bilmezdim

Ama bilmiyordum ağlamayı da 

Sen öğrettin bana gülmeyi

Izdırabın daha büyük oldu 

Verdiğin sevgiden

Bu ızdırap ateşi 

Yaktı kül etti Sevgini', 'Yalnız şu satırlardır  Senden bana kalan Seni bana hatırlatansa  Yakıp kül ettiğin kalbimdir Yalnız ızdıraptır  Kalbimde yer eden Şu sonsuz ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/isimsiz-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Anlamadın', 'bir-sen-anlamadin-hasan-ozen-2yz6h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir odam vardı seninle paylaştığım

Hasretinin gözümde tüttüğü

Özleminin içimi kemirdiği

Kendimi avutmak istediğim günler

Seni hayal edip kapandığım odam

Aşkım gibi temiz duygularla beslenen

İçinde AŞK perilerinin gezindiği

Buram buram sevda kokan

Bir dünyam vardı

Aşkımı içindeki eşyalarla paylaştığım

Duygulandığımda elime gelen kalemim

Masamdaki defterim,

Bittiğinde sigara söndürdüğüm kültabağım

Hepsi biliyordu seni nasıl sevdiğimi

Bir dile gelip konuşsalar Varya hani! ...

Ayaklarıma kapanırdın belki de

Yukarıda ''Allah'' da biliyor ya

Bir sen anlamadın ne kadar sevildiğini', 'Bir odam vardı seninle paylaştığım Hasretinin gözümde tüttüğü Özleminin içimi kemirdiği Kendimi avutmak istediğim günler Seni hayal edip kap...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-sen-anlamadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Desem', 'ne-desem-mahmut-dogan-gweig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buğulanmış Hasretlerim

Ne Kederlenebiliyorum

Ne De Sevebiliyorum

Tükenmiş Özlemlerim

Ne Uzaklara Gidebiliyorum

Ne De İçimdekileri Dökebiliyorum

Kanı Donmuş Tüm Yaralarımın

Ne Sızlanabiliyorum

Ne De Derman Arıyabiliyorum

Kesilmiş Tüm Mektuplarım

Ne Okuyabiliyorum

Ne De İçten Yazabiliyorum

Yağmalanmış Umutlarım

Ne Düşünebiliyorum

Ne De Heveslenebiliyorum

Ağırlaşmış Acılarım

Ne Taşıyabiliyorum

Ne De Hafifletebiliyorum

Gelmişim Bir Kere Dünyaya 

Ne İsyan Edebiliyorum 

Ne De Hayatı Değiştirebiliyorum

Böyle Gelmiş Böyle Gider

Ne Diyebiliyorum 

Ne De Diyemiyorum

Ne Desem, Ne Desem Bilemiyorum...', 'Buğulanmış Hasretlerim Ne Kederlenebiliyorum Ne De Sevebiliyorum Tükenmiş Özlemlerim Ne Uzaklara Gidebiliyorum Ne De İçimdekileri Dökebiliyo...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Doğan']::text[], 8.5, '{"poet":"Mahmut Doğan","poet_slug":"mahmut-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ne-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şakir', 'sakir-zafer-zengin-etnika-pap6r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şakir

fakir çocuk

çepleri el dolu

Şakir 

şair çocuk

şiir gibi

yazılır da büyümez

Şakir

para elinin kiri

şiir yüreğinin

yazdıkça güzelleşiyor şarkıların..akdenizini anlatsana içinin...

Şakir

iki büklüm yüreği

bir balad dinlerken küser sevgiliye...

Şakir

şair çocuk sevgilin yeter..akdeniz senin neyine

yumulan gözlerden sonra..sevgiliyi görmektir aşk...

Şakir 

şair çocuk

biraz kör akşam üstleri

bana geceyi anlatsana..akdeniz de..datça da...

Rakı kokuyor fidan duruşun..ellerin sanat boyası

denizi boyardı geceleri..kimseden habersiz

şakir şair çocuk...denizi boyardı...sessiz...sessiz....

Yüreği boyamakdır aşk..al kana..yakası mavi mintanı

iki yakan bir araya gelmesin şiir..bana kendini yazdırdınya...

22 Subat 2004', 'Şakir fakir çocuk çepleri el dolu Şakir  şair çocuk şiir gibi yazılır da büyümez Şakir para elinin kiri şiir yüreğinin yazdıkça güzelleşiyor...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sakir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısacası', 'kisacasi-hasan-ozen-e79e9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aramayın hiç boşyere bulamazsınız

Bulamazsınız prangalarımızı,zincirlerimizi

Sherlock Holmes''u getirseniz o da bulamaz

Bizi sevip sevilene sorun

Sorun da anlatsın size 

İçimizdeki ateşleri, fırtınaları

Yüreğimizin derinliklerindeki yangınları

Unutun diyorsunuz mümkün mü unutmak

Boşverin diyorsunuz mümkün mü boşvermek

Hani sevgi diyorsunuz ya hani! ...

Hani ne olduğu kelimelerle anlatılmayan

Bermuda Şeytan Üçgeni gibi

Sırrı asırlardır çözülmemiş bir duygu

Kalplerin derinliklerinde fırtınalar yaratan

Bir garibi diğerine bağlayan

Anahtarının sevilende olduğu

Bir diğer adına da AŞK dediğiniz

İşte ben o duygunun esiri olmuşum 

Kısacası ben bir AŞK MAHKUMUyum', 'Aramayın hiç boşyere bulamazsınız Bulamazsınız prangalarımızı,zincirlerimizi Sherlock Holmes''u getirseniz o da bulamaz Bizi sevip sevilene s...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kisacasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '! .MeKTuP.!', 'mektup-i-lyas-acer-fmpva', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaslamış bir ağaça mektup okuyor

Yaklaşmayın ona mektup hasret kokuyor

Kalbi hasret ile yanıyor

Hani asker ağlamazdı,işte ağlıyor

.

Kalbi ruhunda hayeller kuruyor

Kim bilir o hayallerde kimi arıyor

Belki sevgilisinin sevgisini arıyor

Hani asker ağlamazdı,işte ağlıyor

.

Bazen yollara bakıp dalıyor

Gözleri hasreti arıyor

Düşündükçe derinden hep ah,çekiyor

Of dedikçe ağlıyor bu garip asker..! !', 'Yaslamış bir ağaça mektup okuyor Yaklaşmayın ona mektup hasret kokuyor Kalbi hasret ile yanıyor Hani asker ağlamazdı,işte ağlıyor . Kalbi ru...', ARRAY['Türk Edebiyatı','Şiir','İlyas Acer']::text[], 8.5, '{"poet":"İlyas Acer","poet_slug":"i-lyas-acer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mektup-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık (Akrostiş)', 'asik-akrostis-hasan-ozen-6j65s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'A nla be gülüm anla ne olur

Ş iirler yazıyorsam, şarkılar söylüyorsam uğruna

 I  şıl ışıl oluyorsa gülmeyi unutan gözlerim seni görünce

K albimde bir ateş yaktığını anlayıver ne olur', 'A nla be gülüm anla ne olur Ş iirler yazıyorsam, şarkılar söylüyorsam uğruna  I  şıl ışıl oluyorsa gülmeyi unutan gözlerim seni görünce K al...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asik-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretteyin Ben', 'hasretteyin-ben-i-lyas-acer-mield', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretteyim Ben

.

Çöl çiçeği gibi hasretteyim ben

Kasıp kavurdu bu hasret beni

Çabuk çekildin yolumdan

Sen yarım bıraktın bu hikayeyi

.

Yağmur kuşları gibi

Gelip geçtin buradan

Duymadan acımı,haykırışımı

Benimsin sanmıştım

Uçtun avuçlarımdan

Silmedin gözümde(n)  akan yaşımı..', 'Hasretteyim Ben . Çöl çiçeği gibi hasretteyim ben Kasıp kavurdu bu hasret beni Çabuk çekildin yolumdan Sen yarım bıraktın bu hikayeyi . Yağm...', ARRAY['Türk Edebiyatı','Şiir','İlyas Acer']::text[], 8.5, '{"poet":"İlyas Acer","poet_slug":"i-lyas-acer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hasretteyin-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramayın', 'aramayin-hasan-ozen-wcepb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'A ramayın hiç boşyere

Y erde değil,gökte değil

Ş iirlerde gizli aşkım

E lde değil kalpte değil

S eviyorum de Sen bana 

E vet değil,Hayır değil

N eşe gelir senden bana

 İ llet değil, kahır değil

S evdadır bu yana yana

E vham değil,verem değil

V ersen tüm kalbini bana

 İ lim değil,irfan değil

Y anan benim sevdan ile

O rman değil,ağaç değil

R esmini ver, şu aşığa

U mut değil,keder değil

M ısralar yazar aşkına', 'A ramayın hiç boşyere Y erde değil,gökte değil Ş iirlerde gizli aşkım E lde değil kalpte değil S eviyorum de Sen bana  E vet değil,Hayır değ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aramayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Mektup', 'olume-mektup-i-lyas-acer-fzgom', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum gidiyorsun ölüme

o sessizliğe,o yaşama,o karanlığa,

Yaşamın sensizliğine sessizliğine

Biliyorum gidiyorsun ölüme,,,

.

Karşılık alamadığın bir sevda uğruna

Sevdanı haykıramadığın bu Dünya''ya

Sevilmeye,Sevişmeye,Üzülmeye,Ağlamaya

Ağladıkça Mavilere Bölünmeye

Biliyorum gidiyorsun ölüme,,,', 'Biliyorum gidiyorsun ölüme o sessizliğe,o yaşama,o karanlığa, Yaşamın sensizliğine sessizliğine Biliyorum gidiyorsun ölüme,,, . Karşılık ala...', ARRAY['Türk Edebiyatı','Şiir','İlyas Acer']::text[], 8.5, '{"poet":"İlyas Acer","poet_slug":"i-lyas-acer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olume-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımı Anla (Akrostiş)', 'askimi-anla-akrostis-hasan-ozen-c9p87', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'A dalet mi bu BİRTANEM

Ş iirlerimi anlamadıysan

K albimin sesini duyamadıysan

 I  srarla bana abi diyorsan

M ısralarım aydınlatsın

 I  şıksız köşelerini kalbinin

A dalet bu BİRTANEM

N e kadar sevildiğini bil

L eyla''dan fazla sevildiğini anla

A şkımın kıymetini bil', 'A dalet mi bu BİRTANEM Ş iirlerimi anlamadıysan K albimin sesini duyamadıysan  I  srarla bana abi diyorsan M ısralarım aydınlatsın  I  şıksı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askimi-anla-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daima Gül (Akrostiş)', 'daima-gul-akrostis-hasan-ozen-1a5k3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'D aha ismini bile bilmiyorum

A ma hiç önemi yok GÜZEL KIZ

 İ çinden geldiğince gülümse

M utluluğun gözlerinden okunsun

A ğlasan bile için için yüzün gülsün

G ülmek sana yakışıyor GÜZEL KIZ

Ü zülsen ağlasan kim anlıyor ki! ...

L akin ağlamak istersen, bu şiiri hatırla VAZGEÇ', 'D aha ismini bile bilmiyorum A ma hiç önemi yok GÜZEL KIZ  İ çinden geldiğince gülümse M utluluğun gözlerinden okunsun A ğlasan bile için iç...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/daima-gul-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adaletmi Bu BİRTANEM', 'adaletmi-bu-bi-rtanem-hasan-ozen-hgz90', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'A daletmi bu BİRTANEM

Y ıllar gibi günler yaşarken hasretinle

Ş iirlerimle dayanırken sensizliğe

E llerim tutunacak bir dal ararken

M aalesef sen görmeden gidiyorsun beni

Günlerdir senin özlemini çekiyorum BİRTANEM

Seni gelir diye bekliyorum hep gözüm yollarda

Bugün Temmuz''un 13''ü

Ben yine bekliyorum gelişini

Saatler gösteriyor 16:30''u

Traş olmak için ayrılıyorum nöbet yerimden

Ben diyeyim beş, sen de on dakika

Ve sen gelip geçiyorsun, ben berber koltuğunda

Derken bir arkadaş geliyor,telaşlı mı telaşlı

Senin geldiğini söylüyor beş civarında

Fırlıyorum hemen koltuktan

Dolaşıyorum arkadaşla sokak aralarında

Ama sen yoksun BİRTANEM

Sonunda vazgeçiyorum devriyeden

Yine nöbet yerime geliyorum

Bekliyorum elimde kalemim,masamda kağıt

Hazır Kıta bekliyorlar,yanımda da bir arkadaşım

Ortak noktamız aşkımız BİRTANEM

O bana aşkını anlatıyor, 

Ben ona seni anlatıyorum

Sonra seni görüp işaret ediyor,

Ben öyle sana bakıp dalıyorum

Sen ise gidiyorsun benden habersiz

Arabaya binip bekliyorsun

Derken Kahyanın düdük sesi geliyor

Ben üst katta isyanlardayım

Adaletmi bu BİRTANEM

Ben senin hasretinle yaşamaya 

Mahkum muyum? ...', 'A daletmi bu BİRTANEM Y ıllar gibi günler yaşarken hasretinle Ş iirlerimle dayanırken sensizliğe E llerim tutunacak bir dal ararken M aalese...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/adaletmi-bu-birtanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin gözyaşı', 'sairin-gozyasi-mutlu-ayar-76vg9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen erkekler neden ağlamaz bilir misin

bilir misin genelde şairler niye erkektir

ve bilir misin acı şiirlere neden yakışır 

şiirler şairlerin akıtamadığı göz yaşıdır', 'sen erkekler neden ağlamaz bilir misin bilir misin genelde şairler niye erkektir ve bilir misin acı şiirlere neden yakışır  şiirler şairleri...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sairin-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana İhtiyacım Var (Akrostiş)', 'sana-i-htiyacim-var-akrostis-hasan-ozen-veshm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'S ana ihtiyacım var BİRTANEM

A rının çiçeğe, çiçeğin yağmura olduğu gibi

N eşe ile gülüşüne hasret kaldım BİRTANEM

''Abi'' diye seslenişine bile kızmayacağım inan

 İ stersen ''Amca'' de, yeter ki gel de

H asretim bitsin gözlerine

T arama saçlarını farketmez

 İ stersen far da sürme ve hatta! ...

Y arım saat sonra çıkarım deyip 

A sırlarca beklet,kök salayım,çiçek açayım razıyım

C anını almaya geliyorum Azrail''inim de

 I zdıraplar çektireceğim şeytanınım de

M utlaka! ... ama mutlaka gel de...

V arım yoğum sensin BİRTANEM

A cılar,ızdıraplar versende hüzünle sevinci birlikte yaşatsan da

R ezil rüsva edeceksen bile sonunda; Gel! ...gel! ...Ne olur gel! ..Sana

ihtiyacım Var', 'S ana ihtiyacım var BİRTANEM A rının çiçeğe, çiçeğin yağmura olduğu gibi N eşe ile gülüşüne hasret kaldım BİRTANEM ''Abi'' diye seslenişine bi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-ihtiyacim-var-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İltica', 'i-ltica-oguzkan-bolukbasi-eq976', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'iltica edecek yerler dolu

gözler

yürekler

dudaklar

duygular

bana mülteciyim şimdi

kabul edemiyorum kendimi

açıktayım

iki arada bir deredeyim

neredeyim', 'iltica edecek yerler dolu gözler yürekler dudaklar duygular bana mülteciyim şimdi kabul edemiyorum kendimi açıktayım iki arada bir deredeyim...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iltica-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sevmeyi Ölesiye Sevmeyi Bilirmisin (Akrostiş)', 'sen-sevmeyi-olesiye-sevmeyi-bilirmisin-akrostis-hasan-ozen-r30m3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'S en Sevmeyi Ölesiye Sevmeyi Bilirmisin

E llerin hiç titredimi 10 nokta 10 şiddetinde

N utkun tutuldumu hiç anlatacak onca şey varken

S enin aşkından habersiz bir sevgiliye

E vlenme teklif ettin mi? hiç rüyalarında

V als yapmayı denedin mi? hayaliyle

M utluluktan öleceğim dediğin oldumu? 

E llerini tutmayı hayal ederken bile

Y üzünün al al olduğunu hissettin mi,

 İ ş olsun diye değil, ölesiye sevdin mi hiç? 

Ö lümü hiçe saydığın oldumu aşkın için

L aflar ağzında gevelenip kaldı mı,onu düşündüğünde

E vdekileri bir kalem de silip attın mı

S evdiğini söyleyemediğin hergün için içini yedi mi

 İ syanlarını şiirlerle anlatmayı denedin mi hiç

Y aşamının anlamı kalmadığını düşündün mü? 

E trafına neşe saçarken için kan ağladı mı? 

S en reddedilmenin ızdırabını bilirmisin

E llerini açıp Allah''a dua ettinmi aşkın için

V ücudunun her hücresinde aşkı hissettin mi? 

M ehtabı seyrederken hayaller kurmayı bilirmisin? 

E sen rüzgarlarda onun ismini duydunmu hiç,

Y ağan yağmurlarda kokusunu hissettin mi? 

 İ ş olsun diye değil ölesiye sevdin mi Hiç? 

B enim seni ölesiye sevdiğimi

 İ çmeden sarhoş olduğumu 

L afları ağzımda gevelediğimi

 İ liklerime kadar titrediğimi

R uhumun derinliklerindeki yangınları

M uhabbet esnasında ismin geçince 

 İ çim kan ağlarken gülmeye çalıştığımı

S abah ezanlarına kadar uyuyamadığımı bilirmisin

 İ ki yıl hiç kimseye birşey söylemeden 

N e zordur ölesiye sevmek bilirmisin.', 'S en Sevmeyi Ölesiye Sevmeyi Bilirmisin E llerin hiç titredimi 10 nokta 10 şiddetinde N utkun tutuldumu hiç anlatacak onca şey varken S enin...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sen-sevmeyi-olesiye-sevmeyi-bilirmisin-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Songül (Akrostiş)', 'songul-akrostis-hasan-ozen-8keaw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'S on gülü de soldu aşk bahçemin 

O ilelebet diye açan Songül''üm

N afileymiş sokak gezilerim

G öz göze gelmeye çekinmelerim

Ü ç gün görmeyince üzülmelerim

L anet olsun gözlerime, atmasın kalbim', 'S on gülü de soldu aşk bahçemin  O ilelebet diye açan Songül''üm N afileymiş sokak gezilerim G öz göze gelmeye çekinmelerim Ü ç gün görmeyinc...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özen']::text[], 8.5, '{"poet":"Hasan Özen","poet_slug":"hasan-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/songul-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Ne!', 'sana-ne-piranli-zaza-rexbn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Bir hata...Bir daha, bir daha olmayacak.) 

Şairim kirlettin; kalk da temizle

Vazifen olmayan işten, sana ne! 

Uzun burnun soktun elin işine,

Üstüne vazife değil; sana ne! 

‘OTUR! ’, dedim; ‘OTUR, yerli yerine! ’

Ne anlarsın aşktan; senin neyine? 

Sokma uzun burnun, elin işine; 

‘OTUR! ’, dedim; ‘OTUR, yerli yerine! ’

Sana ‘ahmak! ’ desem, anlamazsın ki; 

Adam olmak zordur; sen bilmezsin ki,

Köpek dili değil o ağzındaki,

Şairim, ‘SUS! ’, dedim; ‘OTUR YERİNE! ’

Şairim, hakim ol her dem diline,

Bir daha karışma elin işine

Şairim, tükürüp küçük beynine; 

Seni vermek lazım, cellat eline...

                                       21.02.2004 

                                           Kayseri', '(Bir hata...Bir daha, bir daha olmayacak.)  Şairim kirlettin; kalk da temizle Vazifen olmayan işten, sana ne!  Uzun burnun soktun elin işine...', ARRAY['Türk Edebiyatı','Şiir','Piranli Zaza']::text[], 8.5, '{"poet":"Piranli Zaza","poet_slug":"piranli-zaza","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sana-ne-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tabut', 'tabut-piranli-zaza-9bwxd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bedenim sanki tabut, 

Bir ceset taşımakta; 

Tabuttaki bu ceset

Bir yürekten ibaret! 

Tabut gidiyor, tabut, 

Ceset seni bulmalı, 

Seni bulmazsa eğer; 

Mezara hapsolmalı! 

Tabut mezar başında, 

Ceset hala içinde; 

Seni bulmayan ceset

Azrail pençesinde! 

Öldürüp yüreğimi, 

Sen yaktın cesedini; 

Bir gün gelir elbette

Ödersin bedelini! 

Ceset toprak altında, 

Zebaniler başında; 

Mahşer günü de olsa

İki elim yakanda! 

                       21/04/2003 

                         ANKARA', 'Bedenim sanki tabut,  Bir ceset taşımakta;  Tabuttaki bu ceset Bir yürekten ibaret!  Tabut gidiyor, tabut,  Ceset seni bulmalı,  Seni bulmaz...', ARRAY['Türk Edebiyatı','Şiir','Piranli Zaza']::text[], 8.5, '{"poet":"Piranli Zaza","poet_slug":"piranli-zaza","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tabut-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık', 'pismanlik-umit-kilislioglu-ozger-pcn82', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceleri sen yakardın yıldızları

Sabaha karşı söndürürdün

Şarkı söylerdin suya karşı

Susup dinlerdi peri kızları

Başımı döndürürdün.

Sen söylerdin, su söylerdi

Sen söylerdin, su söylerdi

Sonra vaz geçerdin

Su üzülmesin diye

Pes etmeyi seçerdin.

Ayaklarının ucuna basarak yürürdün

İncitmeden sabahları

Sevdan günü de, beni de sarardı

Ne güzel gözlerin vardı! 

Hayatı ne hoş açıklardın! 

Hiçbir şey kalmazdı yarım.

Anlamsız gelirdi kederler

Savrulup giderdi efkârım.

Kıymetini bilemediğim ne varsa,

Çekip gidin başımdan! 

Toplanıp gelmeyin üstüme sakın

Beni  öldürücü pişmanlığımla

Yalnız bırakın.

                   22.Şubat.2004', 'Geceleri sen yakardın yıldızları Sabaha karşı söndürürdün Şarkı söylerdin suya karşı Susup dinlerdi peri kızları Başımı döndürürdün. Sen söy...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/pismanlik-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Aşk Şiiri Yarışması', 'en-guzel-ask-siiri-yarismasi-oguzkan-bolukbasi-gcdic', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En güzel aşk şiiri

Aşkın en güzel ifadesi midir

En güzel aşkı mı anlatır

En güzel aşk şiiri var mıdır

Niye yarışması yapılır

İnsanın ödülü aşktır

Aşkın ödülü şiir

Şiirin ödülü …………………………? ? ? ? ? ? ?', 'En güzel aşk şiiri Aşkın en güzel ifadesi midir En güzel aşkı mı anlatır En güzel aşk şiiri var mıdır Niye yarışması yapılır İnsanın ödülü a...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/en-guzel-ask-siiri-yarismasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey can bulası dost(Kimsin deme bana)', 'ey-can-bulasi-dost-kimsin-deme-bana-sair-ahrazi-x4416', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey can bulası dost hali bilmeden,

Dertli deme bana derdim aşkımdır.

Gönlümle baş başa bir gün kalmadan,

Yurtsuz deme bana yurdum aşkımdır.

Nice cihân gezdim çula sığmayan,

Nice mekân kurdum dile değmeyen,

Ufku ne eylesin yola doğmayan? 

Yönsüz deme bana ardım aşkımdır.

Ahrâzi dil,zaman sözle süreli,

Göze âlem çokta fer’de yaralı,

Adım hasmım olmuş bende duralı,

Kimsin deme bana ferdim aşkımdır.', 'Ey can bulası dost hali bilmeden, Dertli deme bana derdim aşkımdır. Gönlümle baş başa bir gün kalmadan, Yurtsuz deme bana yurdum aşkımdır. N...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ey-can-bulasi-dost-kimsin-deme-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirazi Evlilik', 'kirazi-evlilik-goktu-kara-h4n15', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahar kendini gösteriyor

bayanlar baylar

evlilik zamanı

gecikmeseniz fena olmaz

elele tutuşun

gözleriniz bahar çiçeklerinde

yürekleriniz sizde kalsın

akşam kızıllık ve mavilikte

sabah evlerde sevişin

şaşırdınız mı

kirazi evlilik bu

özgürce takılın işte

benden söylemesi', 'Bahar kendini gösteriyor bayanlar baylar evlilik zamanı gecikmeseniz fena olmaz elele tutuşun gözleriniz bahar çiçeklerinde yürekleriniz siz...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirazi-evlilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a Dair', 'ask-a-dair-suskun-resital-ssvmb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamana az kaldı aşkı,

Yağmur gibi sağnak sağnak.

Aşkına susadığın sevgilinin 

Göğsüne yaslanarak...

Bedeninde,hiç dinmeyen, 

Fırtınalar koparacak.

Adını dudakların asla,

Unutmayacak! ...

Ne varsa aşka dair,

Bir gün hepsi,senin olacak...

Gözlerin her yerde, 

Onun hayalini kuracak.

Üşüdüğünde bedenini,

Yalnız o ısıtacak...

Leylaklar,güller kaplasa da her yanını 

O yalnız senin,

Bir tek senin olacak', 'Yaşamana az kaldı aşkı, Yağmur gibi sağnak sağnak. Aşkına susadığın sevgilinin  Göğsüne yaslanarak... Bedeninde,hiç dinmeyen,  Fırtınalar ko...', ARRAY['Türk Edebiyatı','Şiir','Suskun Resital']::text[], 8.5, '{"poet":"Suskun Resital","poet_slug":"suskun-resital","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-a-dair-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mordoğan''da gerçekler meyil verirmiş masallara', 'mordogan-da-gercekler-meyil-verirmis-masallara-mustafa-sen-hi6dp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rakıya bulanmıştı gözyaşlarımız

ellerimiz aşk

dudaklarımız perişan

Yakamozdu istediğimiz 

ıssız bir yaz köşesinde

Deniz

dalgalar

bizi çağırdı 

lacivert

ıslak bacaklarımızda hissettik

ama gitmedik

Şimdi düşünüyorumda

rüya mıydı? 

Yine de  selam olsun 

balıkçı meyhanesindeki tahta masalara

yılan balıklarına

yıldızlara, kayalıklara, yakomozlara

ve de masallara....', 'Rakıya bulanmıştı gözyaşlarımız ellerimiz aşk dudaklarımız perişan Yakamozdu istediğimiz  ıssız bir yaz köşesinde Deniz dalgalar bizi çağırd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şen']::text[], 8.5, '{"poet":"Mustafa Şen","poet_slug":"mustafa-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mordogan-da-gercekler-meyil-verirmis-masallara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yenilmeye Mahkumum Kaderime', 'ben-yenilmeye-mahkumum-kaderime-salih-ozalasan-9mrhv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acılar içindeyim

Hüsranlar çökmüş yüreğime

Ömrümün son demindeyim 

Sevdalar düşüyor gönlüme

İsyanlara çeyrek var

Sitemler dizilmiş kaderime

Dokunsan ağlamak üzereyim

Yaşanmış zamanda

Yaşanmadan geçen ömrüme

Geçen zamana mı ağlayıp yanmalıyım? 

Yoksa yaşamak için kalmayan zamana mı? 

Sevgiyle titreyen yüreğime mi inanmalıyım? 

Yoksa zamansız ağaran saçlarıma mı? 

Bedenimi taşıyan ruhum mu vefasız? 

Yoksa bedenimi harap eden zaman mı? 

Benim için neydi, yaşanmayan mutluluk

Yaşadıklarım mı; yoksa yaşanmamış zaman mı? 

Yaşanan ne var dolu, dolu neşeyle

Savaşmışım ya kaderle, yada dost görünenlerle

Çoğu kez ölmek için niyetlensem de

Bir umut kalıyor, var oldukça can bedende

Sevdiklerim kalmamış, yapayalnızım

Ben sevmiş olsam da, kimim var çevremde

Daha babanın ne olduğunu tanıyamamışım

Baba sevgisi kalmış yüreğimde bir uhde

Canımın cananı toprak olmuş

Bana kanından can veren, annem nerede

Nerede benim sevdiklerim

Beni canan edip sevenler nerede

Bir canım kalmış

Beş para etmez yıpranıp ihtiyarlamış

Yaşanmış zamanlar

Kaybedilmiş zamanlar bu bedende

Yüreğimde güller açmış bazı, bazı

Sokulup koklamak ne mümkün

Dikenler etrafında çepeçevre

Açmadan solmuşlar her mevsimde

Baharı yaşamayan zavallı gönlümde

Gül dalında güzel demişim

Heyhat! ! ! 

Dikenleri bile kalmamış benimle

Bir başıma yapayalnız

Her zaman yenilmişim kaderime

Sevdalara tutulsam, sığınacak limanım kalmamış

Rüzgar istemişim yelkenime fırtınalar patlamış

Gemim su alır olmuş, bana inat batmamış

Ben yenilmeye mahkumum kaderime

Y.Tarihi 22-02-2004

Salih ÖZALAŞAN', 'Acılar içindeyim Hüsranlar çökmüş yüreğime Ömrümün son demindeyim  Sevdalar düşüyor gönlüme İsyanlara çeyrek var Sitemler dizilmiş kaderime ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ben-yenilmeye-mahkumum-kaderime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaklar Koydum Güzelliklere', 'yasaklar-koydum-guzelliklere-salih-ozalasan-oq5d2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yasakladım seni artık gönlüme

Öpmeyeceğim bal dudaklarını

Kilit vurdum artık nefsime

Koklamayacağım gül yanaklarını

Mil çektim artık gözlerime

Görmeyeceğim ceylan bakışlarını

Sakatat gözüyle bakıyorum artık yüreğime

Yaşamayacağım seninle aşklarımı

Zincirler vurdum isyankar bölgelerime

Yarattım kırılmayacak prangalarımı

Bendini yıkacak azgın dalgalara dönse de

Çelik odalara hapsettim duygularımı

Toprak olsam; Artık kimseye olmayacağım mezar

Kapattım açmamacasına kucağımı

Temellerde taş olsam; Günahkar evlerinde

Güneşlere kapattım artık çatılarımı

Esmeyecek başımda kavak yelleri

Kimse için söylemeyeceğim artık şarkılarımı

Yasakladım dudaklarıma artık dualarımı

Tanrıdan başkasına kapattım avuçlarımı

Şimdi bir ben varım; Bana dahi faydası olmayan

İçmesin kimse, kuruttum aşk pınarlarımı

Bir beden var içerisinde yürek atmayan

Kestim sevgiye giden damarlarımı

Yasaklar koydum güzel olan her şeye

Cehennemde yaşamak istiyorum kalan zamanlarımı

Nefes almıyorum duymamak için kokunu

Sustum; Açmamak üzere kapattım dudaklarımı

Y.Tarihi 21+22:-2-2004

Salih ÖZALAŞAN', 'Yasakladım seni artık gönlüme Öpmeyeceğim bal dudaklarını Kilit vurdum artık nefsime Koklamayacağım gül yanaklarını Mil çektim artık gözleri...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yasaklar-koydum-guzelliklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bindokuzyüzkırküç', 'bindokuzyuzkirkuc-zafer-zengin-etnika-we1am', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'varşova

bin dokuzyüz kırk üç

kar  yağıyor

herşey çok özleniyor

herşey...

sığınacak bir dilim ekmek bile

hayat''tan çok özleniyor

varşova''da

kar yağarken

bin dokuzyüz kırk üç''de

isimlerini okuyorum savaşta...

olmayanlar

ölüyüm desin...

kar yağıyor varşovaya

herşey çok özleniyor...

hayat..hayat..hayat..

kar yağıyor...

insanlığın üstüne...unutuyoruz..ölümlerin tarihi ziyaretlerini...

22 Subat 2004', 'varşova bin dokuzyüz kırk üç kar  yağıyor herşey çok özleniyor herşey... sığınacak bir dilim ekmek bile hayat''tan çok özleniyor varşova''da k...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bindokuzyuzkirkuc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca merak benimkisi', 'yalnizca-merak-benimkisi-gok-tengri-pste2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '__________________________________Konuşurken solcusun

__________________________________Yaşarken karambolcusun

__________________________________Oportünizme bulaşmış

__________________________________Tipik bir orta yolcusun

______________________________________________Yusuf Hayaloğlu

Ey hümanistler

Kömünistler

Enteller

Danteller

Ve daha bilmem neler

Merak ettim de nerde ''Savaşa Hayır'' rozetleriniz

Yoksa o rozetler de kaldırıldı mı

Hiç okunmamaktan tozlanmış Dostoyevskilerin yanına? 

Merak etmeyin rozetler tozlanmaz ama

Amerika amca yarın yine savaş açar teröre (!) 

E siz de gösterirsiniz tepkinizi böylece (!) 

3Aralık2003 00.18', '__________________________________Konuşurken solcusun __________________________________Yaşarken karambolcusun _____________________________...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizca-merak-benimkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkını Öldürdüm', 'askini-oldurdum-gulay-yildiz-1f5wu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acımaktansa öldürdüm aşkını içimde, yerine ektim kan kırmızısı gülleri 

Yakaladım önce ve sonra gömdüm rüzgarla savrulan her bir yanını

Rhadamantys; cehennemin, cehenneminin yargıcı

Tutacak ellerinden, yargılayacak bana bıraktığın tüm acıları

Üşenmedim, gömdüm mezarına benden alamadığın ilhamı.

Ve; budur ki dileğim; 

Şiirleştiremediğin yaşamına, şiirler ekleyeceksin ölümünde,

Şarkılarına söz yapacaksın, çığlık ve acı arasında yaşattıklarını

Sapho''nun acısını döküşüne yansıtacaksın benden aldıklarını

O bile ağlayacak hasatten...

Örtüyorum bu gece son topraklarını

İki küçük zebani koyacaklar baş ucuna, 

Biri beni hatırlatacak, biri yalnızlığını

Birinde beni anlayacaksın, diğerinde hayatı

Gidişine vereceksin bu amansız sızılarını gecenin

Hades''in topraklarında, Hades''in kanunlarına ait olacak

Rhadamantys''ın yargılarında boğulacak

Sapho''ya beni anlatacaksın...

Yüreğindeki acın olacak oradaki adım

Sevdanı yaşayamayıp gizlediklerinde ağlayacaksın

*Rhadamantys; Cehennemlerde bulunan meşhur bir yargıç. Zeus ile Europa''nın oğlu ve Girit kralı Minos''un kardeşidir. 

**Sapho: Mitolojide; Lesbos adasında Erebos şehrinde doğmuş efsanevi bir kadın şair. 

***Hades:  Cehennemlerin, karanlık yeraltı aleminin, ölüler diyarının Tanrısı ve öteki dünyanın adı.', 'Acımaktansa öldürdüm aşkını içimde, yerine ektim kan kırmızısı gülleri  Yakaladım önce ve sonra gömdüm rüzgarla savrulan her bir yanını Rhad...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/askini-oldurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam ezanı okunurken aklımdan geçenlere dair', 'aksam-ezani-okunurken-aklimdan-gecenlere-dair-gok-tengri-xz7s2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Allahüekber diyor müezzin

Ben Yunanelinden gelen Sakız likörünü içerken

Türkelinden gelen türküleri dinliyorum

Günah mı? 

Böyle günaha can feda! 

Birileri kumdan binalar yaparken; 

Katli vacip diye fetva verirken birileri; 

Kullar giderken faili mechullere; 

Doktorlar para kazanma hırsıyla kandırırken cahil hastaları; 

Öğretmenler tanrıcılık oynarken öğrenciler üzerinde; 

Birileri Tanrı''ya şükredip

Mahvederken O''nun yarattığı dünyayı; 

Başka birileri daha ergen çocukları -yaşıtlarımı-

Küflenmiş Hasan Sabbah taktikleriyle kandırıp

bomba niyetine patlatırken; 

Birileri demokrasi getirirken füzelerle; 

Tüm derdi maddiyatken birilerinin; 

Birileri hala onurlu fakirlikleriyle ölüyorsa,

''Ne olursan ol gel'' diyenin öğrencileri/ Şeriat da şeriat

deyip sızlatıyorsa onun kemiklerini,

Birileri gelişmeyi otoasimilasyon olarak görüyorsa,

Birileri gavura birileri kabeye açarken ellerini

Gerçek kıblemizin Anadolu olduğunu unutuyorsa,

Birileri anlamadığı dilde Kur''an okuyup,

Birileri anlamadığı dilde Ezan dinleyip,

Birileri anlamadığı dilde Dua edip,

Birileri anlamadığı dilde İbadet ediyorsa,

Benimki gibi günaha

Dense dense can feda! 

12 Şubat 2004 19.25', 'Allahüekber diyor müezzin Ben Yunanelinden gelen Sakız likörünü içerken Türkelinden gelen türküleri dinliyorum Günah mı?  Böyle günaha can f...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aksam-ezani-okunurken-aklimdan-gecenlere-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Dörtlükler V', 'yeni-dortlukler-v-ahmet-aksoy-waweg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat Ağacı

kırmızı düş çengeli, soluksuz bir 

öpüş kadar uzun.hey! içinde yaşam,

içinde ölüm, üzerine asıldığım ağaç

ölmek bile güzel kollarında. 

Değmez Çekmeye Bir Sarhoşluk

ne zaman renkler rengini kaybeder

ne zaman gerçek rüya gelir

işte o vakit sıyrılır insan

zamanın kendine biştiği acıdan.

Kor Ölüm

ben sana bel bağladım demir yazgım

ne olur ağlama ne olur

bırak olması gereken olsun

henüz kurt vaktiyken rüzgar.

Savaş Korosu

özgürlüğün dişlerini kıran savaş borusu

kafesteki nem kan buğusu

örselenmiş güler dikenleri derilirken

kazanan hep canavarların borusu.

Değerce

birbirine değerler biçer insan

beş para on para diye

ve sayar sayar değerini

düşse de düşmese de', 'Hayat Ağacı kırmızı düş çengeli, soluksuz bir  öpüş kadar uzun.hey! içinde yaşam, içinde ölüm, üzerine asıldığım ağaç ölmek bile güzel kolla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yeni-dortlukler-v-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri Kızı', 'peri-kizi-oguzkan-bolukbasi-jes95', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şarabım kırmızı

Ey peri kızı

Al kadehi elimden

Aynı dudaktan söyleyelim şarkımızı

Bir gönül kervanıdır takıldığımız

O yürek senin 

Bu yürek benim

Çekinerek dolaştığımız 

Akşamlarda ateşler yaktığımız

Gök yorganın altında sevişmek gibiydi  raksını seyretmek

Kanatsız kuşların ağlamasını da bilmezsin şimdi sen

Yani aşkı

Aşk kanatsız bir kuş gibidir küçüğüm

İçinde uçmak hevesi

Şarabım kırmızı

Ey peri kızı

İnmeden bu oyunun son perdesi

Al kadehi elimden

Öp beni

Duyacaksın şarkımızı', 'Şarabım kırmızı Ey peri kızı Al kadehi elimden Aynı dudaktan söyleyelim şarkımızı Bir gönül kervanıdır takıldığımız O yürek senin  Bu yürek ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/peri-kizi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Ekim', 'on-ekim-ferit-teksoy-xjd95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kahve içimi sözle başladık

Ne zaman yetişti,ne güne sığdık

Geceler yetmedi,gündüze taştık

Zamana sığmadı sözümüz bizim

Ne özlem azaldı,ne sevgi bağı

Göğüsledik hastalığı,sağlığı

Yaşımıza özgü bu orta çağı

İyi yakaladı gönlümüz bizim

Uzak eksiltmedi özlemimizi

Yakın kapatmadı hasretimizi

Zaman zaman üzdük birbirimizi

Baktık,eskimedi yüzümüz bizim

Sivri uçlar törpülendi beraber 

Acı günler,tatlı günler beraber

On Ekim''den,on Ekim''e beraber

Yine de doymadı gözümüz bizim

Annelere dua,doğurdu diye

Tesadüfe dua,buldurdu diye

Tanrıya teşekkür,sevdirdi diye

Sevgiye hasretmiş özümüz bizim

Yarına ne mi var? ..sevgimiz işte

İki koca yürek,doludizgin gidişte

Sözümüz yol boyu,son mu? ..finişte

Mezardan,mahşere yönümüz bizim', 'Bir kahve içimi sözle başladık Ne zaman yetişti,ne güne sığdık Geceler yetmedi,gündüze taştık Zamana sığmadı sözümüz bizim Ne özlem azaldı,n...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/on-ekim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamam', 'anlatamam-menevis-koylu-iuujg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yine martılar

zaten bir onlar

bir de kargalar

ve yine Istanbul

yine yâr

yâr olunca da

tabii ki Üsküdar

sonra...

sonra...

sonrasını boş ver

bak 

kedi geçiyor', 'yine martılar zaten bir onlar bir de kargalar ve yine Istanbul yine yâr yâr olunca da tabii ki Üsküdar sonra... sonra... sonrasını boş ver b...', ARRAY['Türk Edebiyatı','Şiir','Meneviş Köylü']::text[], 8.5, '{"poet":"Meneviş Köylü","poet_slug":"menevis-koylu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlatamam-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğu', 'dogu-huseyin-cayikli-qdy1j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o büyük şehirde mağazalara girdiğinizde

vitrine bakan gözleri donuk olan

kürt çocuğuna hanginiz ismini sordu

hiçbiriniz', 'o büyük şehirde mağazalara girdiğinizde vitrine bakan gözleri donuk olan kürt çocuğuna hanginiz ismini sordu hiçbiriniz...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dogu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü Hediyesi', 'dogum-gunu-hediyesi-huseyin-cayikli-oq7ly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıllarımın sayfalara bıraktığı izdi felsefe kitapları

bir doğum günü hediyesi olarak 

kendime aldığım

kitaptı

Daskapital', 'yıllarımın sayfalara bıraktığı izdi felsefe kitapları bir doğum günü hediyesi olarak  kendime aldığım kitaptı Daskapital...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dogum-gunu-hediyesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehre Yazmak', 'sehre-yazmak-huseyin-cayikli-338xe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni düşündükçe biraz daha ürperiyor içim

üşüyorum sokağın başında

rüzgar saçlarımı dağıtıyor

mendil satan çocuklar

peşimden koşuşturuyor

bu şehirde bir şeyler eksik

içim içime sığmaz

daralıyor.

zaman akıp geçmiyor öyle kolay

zaman herşeyin ilacı diyenler

yalan söylüyor

biraz daha asileşiyorum yalnız kalırken

biraz daha ben oluyor içimde ki yabancı.

atlar geçiyor

suları soğuk olan bir nehir 

beni alıp götürmek istiyor.

sevmek istiyorum bu kenti

bu şehir sanki fahişe gibi

beni biraz daha aylak yapıyor.

dostu düşmanı takmaz olmuş bu kalem

bir kenti daha yazıyor

elleri kanayarak  biraz da acıyarak

eski şiirlere takılıyor dilim

ezbere bilsem 

düşünmem kimbilir

söyle bana 

suçu

vesikalık orospu olan şehir

Aşk kaç kişiliktir', 'seni düşündükçe biraz daha ürperiyor içim üşüyorum sokağın başında rüzgar saçlarımı dağıtıyor mendil satan çocuklar peşimden koşuşturuyor bu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sehre-yazmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usuldan', 'usuldan-zafer-zengin-etnika-7yf7d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Usuldan

ve 

nefes

almadan

seyrettim

uykusunda kadını

bebek

gibiydi

Büyünce

sevda 

olacak

Saçlarına

takılmış

gençliğim...öpmeye kıyamadığım.

22 Subat 2004', 'Usuldan ve  nefes almadan seyrettim uykusunda kadını bebek gibiydi Büyünce sevda  olacak Saçlarına takılmış gençliğim...öpmeye kıyamadığım. ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/usuldan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-huseyin-cayikli-zzetw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'senisevmek

bir başka deyimle

baştan tanımak hayatı

şarkıları sevmek

güzellikten başka birşey düşünmemek

seni sevmek

öyle oturup şiir yazmak filan değil

sadece şarkı dinlemek 

biraz cesaretlendirmek hayatı

seni sevmek 

tavana bakıp sigara filan içmek değil

küllüğü kaldırıp rafa atmak

seni sevmek

cildi bozulmuş bir kitabı onarmak

seni sevmek 

yoldan geçen bir kediyi okşamak

seni sevmek

bir arkadaşla kır kahvesinde çay içmek

seni sevmek

belkide hiç düşünmemek.', 'senisevmek bir başka deyimle baştan tanımak hayatı şarkıları sevmek güzellikten başka birşey düşünmemek seni sevmek öyle oturup şiir yazmak ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-sevmek-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay parçam', 'ay-parcam-zafer-alaftargil-37hw6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay parçam

Ay parçam şimdi uzaklardasın

Kim bilir belki başka sevdalardasın

Korkuyorum mahrem ufuklardasın

Ay parçam şimdi uzaklardasın

Bulutlarla kapalı gönül seması

Işıksız kaldı aşığının dünyası

Kalmadı gözlerimin feri takatı

Ay parçam şimdi uzaklardasın

Ne zaman çekilecek önümüzden bulutlar

Ne zaman silinecek kaderimizden ayrılıklar

Aylar geçti aklara mesken oldu saçlar

Ay parçam hala uzaklardasın

                         04/07/2003-Cuma', 'Ay parçam Ay parçam şimdi uzaklardasın Kim bilir belki başka sevdalardasın Korkuyorum mahrem ufuklardasın Ay parçam şimdi uzaklardasın Bulut...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ay-parcam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-zafer-alaftargil-nqgk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dilek

Hayalin dalgalanıyor buğulu gözlerimde

Coşkusunu duyuyorum sevdalı gönüllerin

Binbir yürek çırpınıyor karanlık denizlerde

İçimi acıtıyor yalnızlığı fenerlerin

Dağları yerlebir ederken kahbe karanlıklar

Bağrımda korlanıyor en büyüğü hasretlerin

Resmini çiziyor gökyüzünde serkeş yıldızlar

Seni dinliyorum sessizliğinde gecelerin

Aşk ile kavruluyor yakamoza hasret deniz

Yüreğimde sensizliğin hediyesi bir cinnet

Arzularımız bir tutsak, mutluluk beklemek yersiz

Senden tek dileğim sadece bir tebessüm lütfet.

                                         27/04/2003-Pazar', 'Dilek Hayalin dalgalanıyor buğulu gözlerimde Coşkusunu duyuyorum sevdalı gönüllerin Binbir yürek çırpınıyor karanlık denizlerde İçimi acıtıy...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dilek-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkeme', 'mahkeme-zafer-alaftargil-sghee', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendime müebbet verdim

Hapsettim senin gözlerine

Kalemime zincir vurdum

Aşkımızın son celsesinde

Dönüş yok karar verilmiştir

Dil,el,gözlerle birlikte

Gönülde hapsedilmiştir

Dava asla çıkamaz temyize

Şahit olarak sen dinlenip

İş bu tutanak tutulmuştur

Suçlu hasrete mahkum edilip 

Adalet yerini bulmuştur.

                    12/11/2002-Salı', 'Kendime müebbet verdim Hapsettim senin gözlerine Kalemime zincir vurdum Aşkımızın son celsesinde Dönüş yok karar verilmiştir Dil,el,gözlerle...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mahkeme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Söz', 'son-soz-zafer-alaftargil-hi2de', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son söz

Hasrete bir gemi daha kalktı gözlerimden

Yanaklarımdan süzülüp kalbine yol alacak

Kargosuna umutlarımı yükledim yüreğimden

Kim bilir hangi hor bakışında karaya oturacak

Bilmem bu kaçıncı yakarışım oldu kadere

Elimde canımı kurtaracak koz kalmadı

Son gülücükleri de teslim ettim kedere

Ömür bitti ama gönül çilem dolmadı

Can simidim bile yok aşk denizinde

Boyuma kadar çaresizliğe batmışım

Bir nefes umduğum her sözünde

Anladım ki dertlerime yenisini katmışım

Artık duysan bile kar etmez feryadımı

Sözlüm Azrail çoktan kapıya dayandı

‘Seni Seviyorum’la bitirmek isterdim hayatımı

Ne yazık dilime ‘eyvah’lar dolandı.

                                        13/09/2003-Cumartesi', 'Son söz Hasrete bir gemi daha kalktı gözlerimden Yanaklarımdan süzülüp kalbine yol alacak Kargosuna umutlarımı yükledim yüreğimden Kim bilir...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-soz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-zafer-alaftargil-qdiny', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İsimsiz 

Ufka demir attı, hayalinle güneş

Gözyaşlarımdır oluklardan dökülen

Canlanır bağrımda çürüyen leş

Bilmem ki nedir ümitleri öldüren

Camları mı yakar yoksa yüreğini mi

Gözlerimde can çekişen ışıklar

Boşuna didikleyip durma bedenimi

Seni benden ancak ölüm ayıklar

Sözler hep üçüncü kişiye gidiyor

Ne sana ne de bana mesaj yok

Başladığı  yerde hayat bitiyor

Azrail ölüme senden fazla tok

Hüzünleri söndürecek deniz bulunmuyor

Gülüşünün fırtınalı coğrafyasında

Bil ki hiçbir hasret avunmuyor

Cenazeye gelen çelengin papatyasında.

                                02/10/2002-Çarşamba', 'İsimsiz  Ufka demir attı, hayalinle güneş Gözyaşlarımdır oluklardan dökülen Canlanır bağrımda çürüyen leş Bilmem ki nedir ümitleri öldüren C...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isimsiz-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurtsuz Acı', 'yurtsuz-aci-melih-coskun-ds37v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçbir kente ait değildir hiçbir acı 

Her şehirde ayrı kanasan da 

Kendi yarandır senin 

Hatırladıkça daha da sancıyan. 

Hiçbir şehir merhem olmaz hiçbir yaraya 

Oluk oluk kanamakta senindir 

Tütün basıp sağaltmakta bu yarayı 

Belki hiç olmayacak dertler gelip bulmuştur seni 

Üşümüş, titremişsindir 

Kimse silmemiştir gözlerinden akan kanı 

En çok istediklerin 

En imkansızın olmuştur 

Dayayıp yorgun başımı vefalı bir omza 

Belki bir ömür 

Belki daha da fazlası 

Arındırarak ruhumuzu dünyanın kirinden, tasasından 

Belki imkansız ama

Aşk katında yaşamak isterdim

Aşk katında ve şiir tadında 

En kötü sonların bile mısralarda güzelleştiği 

Sevinçleri isimlerinin ilk hecesi olan kentlerde yaşamak 

Acılarının bile insanca yaşandığı bir dünyaya uyanmak

Belki zor ama imkansız değil 

Belki yürek gerekir böyle bir düşe ama tesadüfler değil

Belki de son sandığın 

Kaderin yeniden yazılışıdır 

Ve içinde derin izler bırakan her yara

Geçip gittiğin şehirlerden sana kalan bir anıdır...

Hiçbir kente ait olmadığı gibi hiçbir yara 

Kazanmak veya kaybetmek de sadece senin değil...', 'Hiçbir kente ait değildir hiçbir acı  Her şehirde ayrı kanasan da  Kendi yarandır senin  Hatırladıkça daha da sancıyan.  Hiçbir şehir merhem...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yurtsuz-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarın Hışırtısı', 'ruzgarin-hisirtisi-tunay-karaca-ltajq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karardı yine her yer

Güneş yorgunluğunu dağların ardına saklanarak gösterdi

Bir sessizlik çöktü buralara

Ne çocok sesi, ne ana sesi,  ne yarin sesi

Çünkü buralar çok uzaktı onlara

Onlar dağların,  ovaların,  ufukların

Taaa ufukların ötesinde bir yerdeydiler

Uzandım otların üzerine

Gökyüzüne, birbirine gözkırpan yıldızlara baktım

Onların sesi gelmiyordu buralara

Hayallere daldım, kah bir düğünde, kah bir eğlencede,

kah bir kalabalıktayım

Onlarda seslerini gizlediler benden

Yalnızdım, bir tek gecenin karanlığı

Ve bazen, sessizlği bozan,  rüzgarın hışırtısı

Rüzgarın hışırtısı, rüzgarın hışırtısı, rüzgarın hışırtısı,.............', 'Karardı yine her yer Güneş yorgunluğunu dağların ardına saklanarak gösterdi Bir sessizlik çöktü buralara Ne çocok sesi, ne ana sesi,  ne yar...', ARRAY['Türk Edebiyatı','Şiir','Tunay Karaca']::text[], 8.5, '{"poet":"Tunay Karaca","poet_slug":"tunay-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruzgarin-hisirtisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül İle Bülbül Olmak', 'gul-i-le-bulbul-olmak-omer-simsek-guzs6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gül ile bülbül olmak, bu kadar da zor muydu? 

Söyle, aşkım elinde yanıp duran kor muydu? 

Kalbimdeki bu koru sana verdim o gece. 

Sekiz yıllık cümlede o sadece bir hece.', 'Gül ile bülbül olmak, bu kadar da zor muydu?  Söyle, aşkım elinde yanıp duran kor muydu?  Kalbimdeki bu koru sana verdim o gece.  Sekiz yıll...', ARRAY['Türk Edebiyatı','Şiir','Ömer Şimşek']::text[], 8.5, '{"poet":"Ömer Şimşek","poet_slug":"omer-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gul-ile-bulbul-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahtım Vardı', 'ahtim-vardi-omer-simsek-38gx1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ahtım vardı, kalman için bu güne.

Bir daha kavuşmak, gül cemaline.

Kerem olup, yanıp bitmiş gönlüme,

Bir damla aşk ver muhtacım sevgine.', 'Ahtım vardı, kalman için bu güne. Bir daha kavuşmak, gül cemaline. Kerem olup, yanıp bitmiş gönlüme, Bir damla aşk ver muhtacım sevgine....', ARRAY['Türk Edebiyatı','Şiir','Ömer Şimşek']::text[], 8.5, '{"poet":"Ömer Şimşek","poet_slug":"omer-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ahtim-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaviye Farkı', 'zaviye-farki-bekir-mutlu-gokcesu-vruw6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gün

Gidip geldiğim

Yollardan

Gördüğüm insanlardan

Ki bir gün

Gitmesem veya gelmesem

Ya da görmesem

Sanki dünyamı duracak? 

Her gün baktığım

Bana en yakın ağaç

Ve bana en uzak dağdan

Ki bir gün bakmasam

Sanki ağaç dağa kaçıp

Dağ ağaca benimi soracak? 

İbaret değil 

Elbette yaşam

Kaldı ki

Onlara bakışım

Hep aynı açıdan

Kim bilir? 

Ben nasıl görünüyorumdur

Oralardan...', 'Her gün Gidip geldiğim Yollardan Gördüğüm insanlardan Ki bir gün Gitmesem veya gelmesem Ya da görmesem Sanki dünyamı duracak?  Her gün baktı...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zaviye-farki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşantısızların Selamı', 'yasantisizlarin-selami-vahittin-bozgeyik-dispu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklardan geliyorum, 

Siz bilmezsiniz oraları...

Üzümlerin 

Fıstıkların

Zeytinlerin

Kır bekçisi Osman''ın

Selamı var size...

Uzaklardan geliyorum, 

Siz bilmezsiniz oraları...

Türküler yakılır dostluk üstüne,

Mutluluktan yana türküler söylenir; 

Susam tarlalarında.

Susamların

Irgatların

Türkülerin 

Selamı var size...

Uzaklardan geliyorum, 

Siz bilmezsiniz oraları...

Ne bir dönüm tarlası var,

Ne damı var oturacak...

Gidemiyor ağanın işine,

İhtiyarladı.

Boynu bükük Recep''in

Selamı var size...

Uzaklardan geliyorum, 

Siz bilmezsiniz oraları...

Başlık parasına gitti,

Dönmedi öksüz Ömer.

Islak bakışlarıyla

Tutsak umutlarıyla birlik; 

Yeşil gözlü Zeynep''in

Selamı var size...

Uzaklardan geliyorum, 

Siz bilmezsiniz oraları...

Dağ yoluyla gidilir şehre günle-birlik

Yahya''lar,Tahir''ler gider gitmesine ya

Hasan Dayı''lar

Fatma Nine''ler gidemez.

Hasan Dayı''ların

Fatma Nine''lerin

Dağ yollarının 

Selamı var size...

Uzaklardan geliyorum, 

Siz bilmezsiniz oraları...

Büyükleri uğramaz oralara şehirlilerin

Gelse gelse tahsildar gelir yılda bir

Nasıl gelir 

Nasıl gider bilinmez

Size susamışların

Selamı var size...

Uzaklardan geliyorum, 

Siz bilmezsiniz oraları...

Silahlar konuşur,diller yerine

Gözler yitirmiştir dost bakışları

Halil''ler ölür

Mustafa''lar tutsak olur hiç yere

Kendi işlerini kendi bitirmişlerin 

Yaşamayı yitirmişlerin

Selamı var size...', 'Uzaklardan geliyorum,  Siz bilmezsiniz oraları... Üzümlerin  Fıstıkların Zeytinlerin Kır bekçisi Osman''ın Selamı var size... Uzaklardan geli...', ARRAY['Türk Edebiyatı','Şiir','Vahittin Bozgeyik']::text[], 8.5, '{"poet":"Vahittin Bozgeyik","poet_slug":"vahittin-bozgeyik","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/yasantisizlarin-selami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutman', 'unutman-tunay-karaca-8zx1m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yavaş yavaş gidişin, ardına bakmadan

Sensizliğimle baş başa bırakman ve yalnızlığım

Ve aşkımın bir anda sönüp bitmesini

Gözlerini ve gözlerimin çaresizliğini, düşünüpte ağlamam

Silmeden gözlerimi beni unutman

Mektupları yırtmadan, hatta mürekkebi bile kurumadan

Aşk sözcüklerinin daha kulaklarımdan kaybolmadan

Beni unutman

Geleceğin hayalini daha bitirmeden

Daha pembe halindeyken beni untman

Yoksa yalanımı öğrendin benimle

Yalan aşkları, yalan mektupları

Yalanmıydı aşkımızın gözyaşı

yalanmı!', 'Yavaş yavaş gidişin, ardına bakmadan Sensizliğimle baş başa bırakman ve yalnızlığım Ve aşkımın bir anda sönüp bitmesini Gözlerini ve gözleri...', ARRAY['Türk Edebiyatı','Şiir','Tunay Karaca']::text[], 8.5, '{"poet":"Tunay Karaca","poet_slug":"tunay-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahibini Bulur Söz!', 'sahibini-bulur-soz-naime-erlacin-9c9oc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'iki kalp

bir adam 

ve bir kadına

kanıyorsa eğer

değmeli bu! 

bir adam

bir kadına

ve bir kadın 

bir adama

yaslanıyorsa eğer

değmeli bu! 

(bu bölüm hayata dair!) 

söz 

tartısına sorumlu 

büyüktür vebali 

akıyla karasıyla

susuyorsa eğer bir tarih 

bir şaşkın karşısında

değdiği içindir! 

adamlığın da onuru var (olmalı) 

aşk kadar

yaşamak kadar

insanlık kadar

(bu bölüm ise sap ile sözü birbirine karıştıran birine ithaf olunur!) 

(23 Şubat 2004)', 'iki kalp bir adam  ve bir kadına kanıyorsa eğer değmeli bu!  bir adam bir kadına ve bir kadın  bir adama yaslanıyorsa eğer değmeli bu!  (bu ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sahibini-bulur-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelgit', 'gelgit-nilay-aksu-r9u3i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aynalar sırrı dökülmüş soluk 

artık bir iç yangınısın bana 

yazılmamış bir şiiri arar gibi 

paramparça 

yüreği ağzında 

          -beni böl, beni öğüt, ayazlara koy beni 

acıyı öğütmek harcı değil herkesin 

aşktır en çok bir gözdağı kendine 

bir gelgit telaşı bir onur savaşı 

bir kapıdır kilitli kalmak gitmek arası

         -beni sus, beni karıştır, darmaduman et beni 

en uzun susuşumdun ‘ben seni sevdim’ 

avucunda ısıttığın bir sözcüktü adım bana 

kaçardım yorulurdum dönerdim 

gelirdim ki sığınırdı gözlerim sana 

şimdi bitmemiş bir öpüşüm 

yarım kaldım ağzında 

         -beni yık, beni acıt, ucuruma sür beni 

ah bu ne uçurum bir yardır aramızda 

üşüdü soluğum 

açıldı kanıyor yara 

NİLAY AKSU', 'aynalar sırrı dökülmüş soluk  artık bir iç yangınısın bana  yazılmamış bir şiiri arar gibi  paramparça  yüreği ağzında            -beni böl,...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gelgit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antalya''dayım Aşkım', 'antalya-dayim-askim-i-brahim-ethem-bingul-12lfb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşık olduğum şehrime,

Aşık olmama sebepsin aşkım

Şimdi ben uzaktayım

Muhteşemliğinde senin aşkının

Aşkımla,aşklanıyorum', 'Aşık olduğum şehrime, Aşık olmama sebepsin aşkım Şimdi ben uzaktayım Muhteşemliğinde senin aşkının Aşkımla,aşklanıyorum...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/antalya-dayim-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-murat-berk-tjm4j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek cetvelle ölçülmez

Doğru olup olmadığı da bilinemez,

Kalbinde şablonunu çıkaramazsın

Bu bir duygudur önünde duramazsın,

Sadece yaşarsın....', 'Sevmek cetvelle ölçülmez Doğru olup olmadığı da bilinemez, Kalbinde şablonunu çıkaramazsın Bu bir duygudur önünde duramazsın, Sadece yaşarsı...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevmek-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavaş Bre Küheylan!', 'yavas-bre-kuheylan-naime-erlacin-jsgr3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu küheylân

kükreyerek geliyor doludizgin

ölümüne şahlanıp

çatlayası koşuyor kaderine

şehadet mührünü saklayarak yelesinde

bu küheylân

yeri göğü birbirine katarak nefesiyle

kaderin ufuk çizgisinde şeytanla dans ediyor

arş’ın uslanmaz

arş’ın arlanmaz yüzünde

bu küheylân 

acı çiviliyor nallarına

sakın dayanmasın şakağına kör bir namlu 

zamansız örselenip vurulmasın yeter ki 

yavaş bre küheylan! 

kırbaca dikkat

kırbaçlara 

yavaş bre! 

(23 Şubat 2004)', 'bu küheylân kükreyerek geliyor doludizgin ölümüne şahlanıp çatlayası koşuyor kaderine şehadet mührünü saklayarak yelesinde bu küheylân yeri ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yavas-bre-kuheylan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Sen', 'karanlikta-sen-engin-ertug-n0uzr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonsuz karanlığın ortasında

Dolaşıyorum boş sokaklarda

Bir hüzünlü fener

Aydınlatıyor ağır ağır

Bir elimde fener

Bir elimde sevgin

Arıyorum aşkımızın ayak izlerini

Bulamıyorum o mutlu günlerimizi

Hayır diye haykırıyorum

Hayır böyle bitmez

O an farkediyorum

Bir elimde sevgin

Bir elimde sen

Aydınlanıyor her yan', 'Sonsuz karanlığın ortasında Dolaşıyorum boş sokaklarda Bir hüzünlü fener Aydınlatıyor ağır ağır Bir elimde fener Bir elimde sevgin Arıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Engin Ertuğ']::text[], 8.5, '{"poet":"Engin Ertuğ","poet_slug":"engin-ertug","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/karanlikta-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözüm Türk Milletine!', 'sozum-turk-milletine-omer-simsek-srsjm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözüm ona buna değil, sözüm Türk milletine,

Hainlerle birlik olup, savaş açmış dinine.

Düşmanıyla dost olup, ihanet etmiş kinine.

Sözüm ona buna değil, sözüm Türk milletine,

Taşa tutmuş Üç Hilâli, Tevhid’i indirmiş yere.

Dinsizlerle beraber kapılmış aynı sele.

Mızrabım vurdukça deli gönlün teline.

Sözüm ona buna değil, sözüm Türk milletine,

19-09-99', 'Sözüm ona buna değil, sözüm Türk milletine, Hainlerle birlik olup, savaş açmış dinine. Düşmanıyla dost olup, ihanet etmiş kinine. Sözüm ona ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Şimşek']::text[], 8.5, '{"poet":"Ömer Şimşek","poet_slug":"omer-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sozum-turk-milletine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Pınarı', 'soz-pinari-naime-erlacin-00fvx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her şeyi bilensin sen

ben 

bilmeye çalışan

bilgelik 

ruhunda senin

pınarısın sözün

bense 

arayan

üzülme 

yorulmam sevdiğim

aramaktan 

bıkmam 

sözü kurutana inat

saçımı yine okşa sen

(23 Şubat 2004)', 'her şeyi bilensin sen ben  bilmeye çalışan bilgelik  ruhunda senin pınarısın sözün bense  arayan üzülme  yorulmam sevdiğim aramaktan  bıkmam...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/soz-pinari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Zamandan Bugüne', 'eski-zamandan-bugune-engin-ertug-j4xrh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen sen ol unutma Engini

Bu gülen neşeli sevgiyi

Ama düşünme yorma kendini

Eğer sıkarsa bu dünya seni

O zaman hatırla Engini

Eski zamanda sevdi seni', 'Sen sen ol unutma Engini Bu gülen neşeli sevgiyi Ama düşünme yorma kendini Eğer sıkarsa bu dünya seni O zaman hatırla Engini Eski zamanda se...', ARRAY['Türk Edebiyatı','Şiir','Engin Ertuğ']::text[], 8.5, '{"poet":"Engin Ertuğ","poet_slug":"engin-ertug","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/eski-zamandan-bugune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Sendir...', 'yuregim-sendir-i-brahim-ethem-bingul-3lbtk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilirim mesafeler,uzaklıklar gözdedir

Sevgi,aşk,muhabbet özdedir

Keşkeler,boşvermişlikler sözdedir

Haykıramadığım her avaz közdedir

Aşkınla sevindir

Benim yüreğim sendir.', 'Bilirim mesafeler,uzaklıklar gözdedir Sevgi,aşk,muhabbet özdedir Keşkeler,boşvermişlikler sözdedir Haykıramadığım her avaz közdedir Aşkınla ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yuregim-sendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Kurt', 'beyaz-kurt-engin-ertug-vqyte', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bembeyaz karlı yüce dağlar

İçinde beyaz bir kurt ağlar

Kalbini kaybetmiş onu arar

Şimdi yalnızdır ona ağlar

Artık kalpsiz vahşi bir kurttur

Denizde başıboş dalgadır

Nerede esse rüzgar oradadır

Yolu uzundur sonu yoktur', 'Bembeyaz karlı yüce dağlar İçinde beyaz bir kurt ağlar Kalbini kaybetmiş onu arar Şimdi yalnızdır ona ağlar Artık kalpsiz vahşi bir kurttur ...', ARRAY['Türk Edebiyatı','Şiir','Engin Ertuğ']::text[], 8.5, '{"poet":"Engin Ertuğ","poet_slug":"engin-ertug","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beyaz-kurt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Ayrıyım', 'senden-ayriyim-engin-ertug-ru9bv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüzünlü bir şiir gibi seni yaşıyorum

Geçmişte ve gelecekte aşkı tadıyorum

Hüzünlü bir şiir diyorum

Çünkü seni üzüyorum

Biliyorum mutlu son olmadığını

Seni mutlu görmekten kendimi alamadığımı

Aşkı sevgiyi aradığını

Bilmiyorsun seni anladığımı

Ben kötüyüm bu hüzünlü şarkıda

Çünkü ben gidiyorum

Yeşil gözler aklında

Sensiz yapabileceğim bir yer arıyorum

Bir gün yapayalnız kaldığımda

Bir çölün yada ormanın ortasında

Sen olmadan geçen her dakikada

İçimi çekeceğim ve bir daha öleceğim', 'Hüzünlü bir şiir gibi seni yaşıyorum Geçmişte ve gelecekte aşkı tadıyorum Hüzünlü bir şiir diyorum Çünkü seni üzüyorum Biliyorum mutlu son o...', ARRAY['Türk Edebiyatı','Şiir','Engin Ertuğ']::text[], 8.5, '{"poet":"Engin Ertuğ","poet_slug":"engin-ertug","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-ayriyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi Sonsuz Kılmak', 'geceyi-sonsuz-kilmak-murat-berk-jlliq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceyi sonsuz kılmak senin sıcaklığındaysa,

Gündüzü  cehenneme çevirmek de

dudaklarında,

Beyaza  kara deme nasıl alışkanlığınsa

Bunaltıyorsun

beni kendine özgü karmaşanda,

Böyle giderse 

Geceleri bilmem ama

Gündüzleri 

bulamazsın beni yanında...', 'Geceyi sonsuz kılmak senin sıcaklığındaysa, Gündüzü  cehenneme çevirmek de dudaklarında, Beyaza  kara deme nasıl alışkanlığınsa Bunaltıyorsu...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/geceyi-sonsuz-kilmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz İstanbulda', 'sensiz-i-stanbulda-engin-ertug-k98oi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimde bir sevda

Beyoğlunda kalabalıkta

Işıklı yalnız sokakta

Yürüyorum yavaşça

Işıklar uzuyor yol boyunca

Gözlerin gözlerimde

Soğuk bir hava

Boğaz kenarında

Yalnız bir bankta

Sevgilim uzakta

Rüzgar esiyor yüzüme

Saçların yüzümde

İstanbulda seni arıyorum

Olmadığını bile bile

Boğazdan dalgalarla kaçıyorum

Sevgilim seni seviyorum

Dalgalar çarpıyor yüzüme

Dudakların dudaklarımda', 'İçimde bir sevda Beyoğlunda kalabalıkta Işıklı yalnız sokakta Yürüyorum yavaşça Işıklar uzuyor yol boyunca Gözlerin gözlerimde Soğuk bir hav...', ARRAY['Türk Edebiyatı','Şiir','Engin Ertuğ']::text[], 8.5, '{"poet":"Engin Ertuğ","poet_slug":"engin-ertug","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sensiz-istanbulda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizlik+', 'caresizlik-bayram-tunca-k0qmf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Prangalıysa zincirsiz kolların 

Tarumar olmuşsa duyguların 

O vakit bencileyin çaresizsin 

Hem de garip ve kimsesizsin 

Umutların, ümitlerin, tükendiği an 

Kim fark eder ki ciğer olsa püryan 

Her şeyin bir anda olmuştur ziyan 

İhtimal bir dosttur arkadan vuran 

Bütün çıkış yollarının kapandığı an 

Hayal ve umutlarının tükendiği an 

Tüm kapıların üstüne kapandığı an 

Tüm zalimlerin üstüne abandığı an 

Şayet güzel hayal bile kuramıyorsan 

Şayet vefasızlardan vefa bekliyorsan

Eğer, kendini boşlukta hissediyorsan 

Çaresizsin ölüden medet umuyorsan 

Çaresizlik kör kuyuda naçar kalmaktır 

Çaresizlik balık karnında aciz kalmaktır 

Çaresizlik her an boyna geçen ilmektir 

Çaresizlik, ruhen ve bedenen ölmektir

Çaresizsin kalabalıklar içinde yalnızsan 

Feryatlarını hiç duyan yoksa çaresizsin 

Seni dinleyen, sadece sensen çaresizsin 

Çaresizsin acıyı iliklerinde hissediyorsan 

Yığılıp kalırsın artık asırlık çınar da olsan

Uçamazsın ki artık, kartal-şahin de olsan 

Kurumaya mahkumsun pınar/çınar olsan 

Ey âdem, ölüden farkın yoktur artık inan 

Zaten dost yarası değil mi ki insanı öldüren 

Bürütüsler değil mi deli divaneye döndüren 

Çıkar uğruna, vefasızlıkla ocaklar söndüren 

Kem düzen değil mi tilkiye aslanı boğduran 

Var mıdır ki çaresizliği tatmayan şu dünyada 

En tatmadım diyenler bile tadar ölüm anında 

Ah ahbap ah ölüm nedir ki çaresizlik yanında 

Bin kere aramışımdır ölümü çaresizlik anında 

Şayet bir komutansan, ordun tarumar olmuşsa 

Şayet bir devlet reisiysen, ülken işgal olmuşsa 

Şayet çoğu gibi yaşlanıp, ele ayağa düşmüşsen 

Bencileyin sahiden sen de talihsiz ve çaresizsin 

17.02.2004-17:02

''Aşk Ateşten Gömlek''', 'Prangalıysa zincirsiz kolların  Tarumar olmuşsa duyguların  O vakit bencileyin çaresizsin  Hem de garip ve kimsesizsin  Umutların, ümitlerin...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/caresizlik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum Yıkanır Yeni Başlangıçlarda…', 'ruhum-yikanir-yeni-baslangiclarda-arzu-dincer-5retf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhum Yıkanır Yeni Başlangıçlarda…

Ruhun derinliklerinden gelen,

Tasavvufi bir melodi..

Örselenmiş duygularımı saran

Kurşuna dizilmiş acılar

Geçmişten kalan

Bırak ellerimi hayat

Uçurumdur beni

Yeni başlangıçlara taşıyan….', 'Ruhum Yıkanır Yeni Başlangıçlarda… Ruhun derinliklerinden gelen, Tasavvufi bir melodi.. Örselenmiş duygularımı saran Kurşuna dizilmiş acılar...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruhum-yikanir-yeni-baslangiclarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrendim', 'ogrendim-abdulsamet-gokhan-dern2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Men bilmez idüm zâr-ı kurbağanın nemini

Medrese-i muhasebede kıraat ettüm çayın demini

Tesisat-ı Maarifim belletti mene âlem-i zemini

Aldım ilmi-bilmi, çıktım cihane gördüm ebemin emini...', 'Men bilmez idüm zâr-ı kurbağanın nemini Medrese-i muhasebede kıraat ettüm çayın demini Tesisat-ı Maarifim belletti mene âlem-i zemini Aldım ...', ARRAY['Türk Edebiyatı','Şiir','Abdülsamet Gökhan']::text[], 8.5, '{"poet":"Abdülsamet Gökhan","poet_slug":"abdulsamet-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ogrendim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anka Kuşu', 'anka-kusu-arzu-dincer-x6kt9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlat bana rüyalarımın Anka kuşu,

Mutluluğu….

Nerden gelir sonsuz mutluluk? 

Sonlar yeni adımları doğurmayınca….

Sevgiyi anlat,

Su gibi, hava gibi süreli sevgiyi…

Zamana yenilmeyen….

Renkleri anlat bana…

Ebemkuşağı misali,

Sarılıp ta yatabileceğim

Sevinçleri… haykırışlarla

Semayı öpebileceğim…

Hayatı anlat bana,

Yaşanıp ta, yaşanmamış kalan,

Duyguların arasında kaybolmuş…

Dostlukları…

Arkam dönük yaslanabileceğim…', 'Anlat bana rüyalarımın Anka kuşu, Mutluluğu…. Nerden gelir sonsuz mutluluk?  Sonlar yeni adımları doğurmayınca…. Sevgiyi anlat, Su gibi, hav...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anka-kusu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bir Kelime Ver', 'bana-bir-kelime-ver-hakki-hakan-kaya-v98rv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Diken senden gül benden,

Dilediğini al benden,

Sevgi dolu heybenden,

Bana bir kelime ver,

Aşkın elinde eriyorum,

Yardan aman diliyorum,

Sende seviyorsun biliyorum,

Bana bir kelime ver,

Ne söylesem inanmazsın,

Ben yazsam sen yazmazsın,

Gönülden damla almazsın,

Bana bir kelime ver,

Kapılmışım sevda seline,

Dünyayı değişmem yerine,

Gönül ister bir kelime,

Bana bir kelime ver,

Susuz kaldım aşk elinde,

Hasretin dolandı şark ilinde,

Hükm-ü fermanım dilinde,

Bana bir kelime ver.', 'Diken senden gül benden, Dilediğini al benden, Sevgi dolu heybenden, Bana bir kelime ver, Aşkın elinde eriyorum, Yardan aman diliyorum, Send...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-bir-kelime-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taziye', 'taziye-abdulsamet-gokhan-63d49', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağam! 

diyorlardı birbirlerine

büyük küçük gözetmeden.

Damarlarındaki kanın rengini bilmiyordum ama

esmerdi tenleri...

Zaten alıştırmıştık sabahı,

Bu kez de Nizip''te doğdu güneş üzerimize.

Güldük gülüştük, bir taziyede...

Nerde, niye olduğumuzu unuttuk; 

Susuzluğumuzu belli ederek birbirimize...

...

Gün bitti, önümüz yoldu

Yine suladık fidanımızı

Kaynağı ölüm oldu...', 'Ağam!  diyorlardı birbirlerine büyük küçük gözetmeden. Damarlarındaki kanın rengini bilmiyordum ama esmerdi tenleri... Zaten alıştırmıştık s...', ARRAY['Türk Edebiyatı','Şiir','Abdülsamet Gökhan']::text[], 8.5, '{"poet":"Abdülsamet Gökhan","poet_slug":"abdulsamet-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/taziye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damağımda', 'damagimda-abdulsamet-gokhan-w5yhm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Az rakı üzerine

nargile çektim Eyüp''te

Solgun olsada ay

güneşti lan işte...

Yağmur sabahla gelmiş İstanbul''a

Çay da içilmiş gece Boğaz''da

Bekle! 

Gelirim bir daha...', 'Az rakı üzerine nargile çektim Eyüp''te Solgun olsada ay güneşti lan işte... Yağmur sabahla gelmiş İstanbul''a Çay da içilmiş gece Boğaz''da Be...', ARRAY['Türk Edebiyatı','Şiir','Abdülsamet Gökhan']::text[], 8.5, '{"poet":"Abdülsamet Gökhan","poet_slug":"abdulsamet-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/damagimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanma', 'i-nanma-abdulsamet-gokhan-q5ogk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hava yavaş yavaş aydınlanmakta

Tan kızıllığını sabahla buluşturmakta

Karanlıkla kirlenen vücutlar

Günün ilk ışıklarıyla ağarmakta...

Milletin gözünde pireler voltalarken

Ben de masamda dut oldum desem

Düpedüz yalan olacak...

...

Halbuki saat öğleni iki geçiyor

Güneş zırıl zırıl tepemde

İllede de şaire

Gün talan, biraz yalan olacak...', 'Hava yavaş yavaş aydınlanmakta Tan kızıllığını sabahla buluşturmakta Karanlıkla kirlenen vücutlar Günün ilk ışıklarıyla ağarmakta... Milleti...', ARRAY['Türk Edebiyatı','Şiir','Abdülsamet Gökhan']::text[], 8.5, '{"poet":"Abdülsamet Gökhan","poet_slug":"abdulsamet-gokhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/inanma-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıllı Ol', 'akilli-ol-murat-demir-dyd8r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fazla havalanma, uçtun madem ki

Bak kalıcı değil, kimsenin erki

Yakarsan birini, yanarsın bil ki

Akıllı ol, kahpe dünya dönüyor

Ne yıldızlar vardı, kayıp gittiler

Ateştiler,küle dönüp bittiler

Onlar da sırayla,ant içmiştiler

Akıllı ol,kalpler bir gün duruyor 

Güneşin doğuşu,batmak içindir

Kimseyi yok sayıp,sanma ki hiçtir

Hesaplar sorulur,hesaplar bir bir

Akıllı ol,hesap günü geliyor

Yasa korur,yasa vurur,adama

Bir kalemle,insan gider idama

Kimse bakmaz,ne feryat ne figana

Akıllı ol, zaman senden gidiyor

Dost arkadaş yetmez,darda kalırsan

Sular fayda etmez,ateş alırsan

Sende zay olursun,zalım olursan

Akıllı ol, herkes birgün ölüyor

Her şeyin vebali,şu an sırtında

Hak hukuk çiğneyip,kalma altında

Kenar köşe değil,vatan sathında

Akıllı ol, millet seni görüyör

Hiç kimseye kalmaz,bu hikmet bu erk

Kim etmek ister ki,vatanını terk

Sanma ki yıkılır,bu cumhuriyet

Akıllı ol, ülke seni deniyor

Bilin ki diyen var,bir zaman, kısmet

Tarihten bir zattır,diyen ya İsmet

Artık geri gitmez,bu ulus millet

Akıllı ol, taş yerine uymuyor', 'Fazla havalanma, uçtun madem ki Bak kalıcı değil, kimsenin erki Yakarsan birini, yanarsın bil ki Akıllı ol, kahpe dünya dönüyor Ne yıldızlar...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/akilli-ol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü 1', 'turku-1-kubilay-enginol-86onx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir türkü tutturmuşum

Yanık bir türkü

Islığın izinden gitmişim

Kaybolmuşum

Kınalı saçlı analar var

Elleri çatlamış topraktan

Umutları filizlenmemiş

Gerisi allahtan

Kağnı gıcırtısını ninni etmiş bebeler

Anaların koynunda

Belliki hayatları geçecek

Tarla yolunda', 'Bir türkü tutturmuşum Yanık bir türkü Islığın izinden gitmişim Kaybolmuşum Kınalı saçlı analar var Elleri çatlamış topraktan Umutları filizl...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turku-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk; Titriyordu Yanan Mumda', 'ask-titriyordu-yanan-mumda-mine-ozdemirtas-w71k5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk vardır, yaşanmak için.

Aşklar vardır..... unutulmak için.

---

Onlar aşıktılar

..............Aşkı

Aşkın göz bebeğine vurgun

Ve düşmeye hazır

Kirpik ucundaki

Tuzlu bir damlaya

.............Aşıladılar.

Tuzu,çoğaldı damlaların

Ağırlaştı.......

Yanaklara  bulaştı

...........paylaştılar.

Bardaklarda Aşk,

............. Beyazdı,

..............Kırmızıydı,

..............Köpüklüydü.

Mezelere, karışmıştı

Ürkekti Aşk........

Titriyordu......   yanan mumda.

............................

Aşk.......

kaybolmuştu aslında.

..........................

Bulup çıkardılar.

Aşklar vardı

.................. Unutulmuş

 Hatırlandılar.

Yaşanası olanlar,

Özenle.. bir kenara

Ayırıldılar.

Tozlarından arındı anılar

Gül yapraklarına tarih düşüldü

Sadece kanayan kızılın

..................şerefine

Kadeh kaldırdılar.

Onlar, şairdiler.

Yürek.... Yürek

............  Bölündüler.

Eskisi; zaten, eskiydi aşkların

Yenisi ise; 

Henüz yaşanmamış olandı.

Umuda sığındılar.

................Çoğaldılar.

Onlar aşıktılar.

............ Şairdiler.

.Şiirleri vardı...Yazılmamış.

........... Yazılsa da okunmamış.

Biraz hüzünlüydüler,

Biraz da  şaşkın.

...................... hepsini,

Duyulmamış mısraların

ve de........

En keskinini kalem ucundaki

.....................bıçakların

Doğacak olanına sakladılar

Aşkın................

Şairdiler,

Ve Ölüydü aşklar

Hepsi,..................

.............  El verdiler

Mevtayı, baş üstünde

Sonsuzluğa taşıdılar.

Sonra......  Affettiler acıları

Özgürlüğe... saldılar

Ölüydü aşklar./ Bağışlandılar.

Ölüydü ya aşklar! ....

................................

................usulca,

Canlandılar.

21/02/2004  Anısına.. (Ölü Aşklar Derneğindeki şair yüreklere İthafım ve armağanımdır)', 'Aşk vardır, yaşanmak için. Aşklar vardır..... unutulmak için. --- Onlar aşıktılar ..............Aşkı Aşkın göz bebeğine vurgun Ve düşmeye ha...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/ask-titriyordu-yanan-mumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bölük Pörçük', 'boluk-porcuk-oguzkan-bolukbasi-7phre', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kirpiklerin mi

Sevdiğim bakışlarının tülleri

Buğulu

Ve derinden

Akan ırmaklara karışırım sanki

Uzaklarda çok uzaklarda denizden

Kıvrılır giderim üzerinden gün görmemiş toprakların

Kırılır ışıklarım bir damlasında göz yaşının

Hangi rengi yakışır sana gök kuşağının

Maviden kırmızıya

Ya görünmeyen dalga boyları

Isıtan

Yakan

Yok eden

Var eden

Neden küçüğüm neden

Tüm sırları saklayan bir bilinmezden söz ederken

Kirpiklerin tebessümüne arkadaş olmuyor

Bahara az kaldı

Buzlar çözülürken 

Kuşları bekleyeceğiz başka diyarlardan

İlk tomurcuğunda zerdalilerin

Ateşler yakacağız

Alevlerden taç yapacağız 

Sen adaklar adayacaksın 

Hızır

İlyas 

Hangi seslere koşacak bilinmez

Umut en yakınımızda

Yeni dostlukların zamanı

Yeni aşkların

Yaklaştığımda anlayacağım

Can tutuyor beni sen baktığında

Devasa bir aşk oluyorum 

Dağ gibi

Sessiz ve sedasız

Zirvelerim olmuyor karsız

İçim ise bir volkan gibi

Kar ve har 

Bir çelişkide arkadaşlar

Bir yanım yanar

Bir yanım donar

Anlıyor musun küçüğüm

Ben bölük pörçüğüm', 'Kirpiklerin mi Sevdiğim bakışlarının tülleri Buğulu Ve derinden Akan ırmaklara karışırım sanki Uzaklarda çok uzaklarda denizden Kıvrılır gid...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/boluk-porcuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevdadır Gülüşün', 'bir-sevdadir-gulusun-sair-khan-r2j0w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülüşün,Hiç kimsede olmadığı kadar içten,hiç  olmadığı kadar yumuşak.

       Gülüşün, gözlerine yansıyan ışık.

       Sen gülüyorsun, ben bir yardan diğerine Ben sürüklenen serüvenci oluyorum.

        Gülüşün çocuk, haylaz, yaramaz,umursamaz.Ve bir o kadar uslu, söz dinleyen, huzur veren...

Gülüşün damarlarıma işliyor, bağımlılık yaratıyor. Bir tutku, vazgeçmesi mümkün olmayan. Bir hayat senfonisi, her notasında aşkı saklayan.

Sevmeyi bilen gülüşün, sevdikçe sevdiren gülüşün...

Özlemin en koyusu senin gülüşüne konaklanmış. O gülüşü görmeden yaşamak öyle zor ki... Sınırsız okyanusların, en mavi denizlerin beyaz yelkenlisi... Umudun ta kendisi...

Menzili olmayan bir uçuş, sonsuzlukta kayboluş...Güven veren gülüşün, cesaret veren... Hayatın bütün kaypaklığına, ikiyüzlülüğüne ve acımasızlığına direnme gücü veren.

Yaşama sevincini her gördüğümde yeniden yüreğime yerleştiren gülüşün...

Sen güldükçe gülüyor çevremde kim varsa, ne varsa.

Sen güldükçe ışıl ışıl yanıyor yıldızlar, her birine senin adını verdiğim yıldızlar.

Şimdi sadece senin gülüşünle anıyorum onları.

Gülüşün, ayazı ısıtan bahar, sarı sıcağı serinleten rüzgar.

Alabileceğim en değerli armağan gülüşün, içinde her sevinci barındıran bir hazine.

En beklenmeyen sürpriz, hep beklenen mutluluk.

Gülüşün kötüye karşı en soylu başkaldırış. İyinin en kadim dostu.

Mücadele eden, yenilmeyen ve aşkın zaferini ilan eden...

Sevdiklerine alçakgönüllü, zarar vereceklere kalkan.

Soran sorgulayan ama asla yargılamayan gülüşün...

Bedenimi saran ateş, içimdeki ürperiş, ellerimdeki titreyiş gülüşün.

Tükenmeyecek heyecan, sonu gelmeyecek öykü, anlatılmaz bir duygu seli...

Seni anlatan en iyi tarif gülüşün, içinde ne varsa dışına yansıtan.

Saklamayı bilen ama gizemden hoşlanmayan. Baktıkça, ''İyi ki yaşıyorum'' dedirten...

Var oluşuma anlam katan gülüşün...

Baktıkça Tanrıya şükrettiren ve ''Hayatımdan hiç çıkmasın'' diye dua ettiren gülüşün. Damla damla yağan yağmur, yanımdan hiç ayırmayacağım uğur...

Gecenin dinginliği, gündüzün hareketi.

Renklerin en güzeli, çiçeklerin en tazesi...ve bu sevdanın sebebi... Gülüşün', 'Gülüşün,Hiç kimsede olmadığı kadar içten,hiç  olmadığı kadar yumuşak.        Gülüşün, gözlerine yansıyan ışık.        Sen gülüyorsun, ben bi...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-sevdadir-gulusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün', 'bir-gun-kubilay-enginol-r17xt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün

Sana kavuşacağımı biliyorum

Yudum,yudum içeceğiz birbirimizi

Geç kalmışlığın üzüntüsü sarsada

Kuvvetlendirecek sevgimizi

Tatlı sesinle fısıldarsın aşkını artık

Yapraktaki damla misali kirpiklerime

Göğsümde gürül,gürül yanan aşkımla

İçini ısıtırsın artık

Uzun bir şarkı gibi sevgim

Melodisi biraz hüzünlü

Yolun sonunu birlikte yürürüz

Elimi bırakmazssın artık', 'Bir gün Sana kavuşacağımı biliyorum Yudum,yudum içeceğiz birbirimizi Geç kalmışlığın üzüntüsü sarsada Kuvvetlendirecek sevgimizi Tatlı sesin...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gun-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Gitsin', 'birak-gitsin-murat-demir-15zyl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gönlümün kapısını

Boşa çalma giremezsin

Bıraktığın  acıların

Sızısını bilemezsin

Bir yakar ki ta derinden

Titretiyor temelimden

Gittiğin o günden beri

Kan geliyor yüreğimden

Yaptığını anlamamı

İsteme ki anlayamam

Yeterince yaktın beni

Daha fazla dayanamam

Ellerini ellerime

Uzatma ki tutamazsın

Sen bu aşkın lokmasını

Bal eğleyip yutamazsın

Bırak öyle dokunmadan

Nere gidecekse gitsin

Ben aşkınla yok olmadan

Bırak bitecekse bitsin', 'Sen gönlümün kapısını Boşa çalma giremezsin Bıraktığın  acıların Sızısını bilemezsin Bir yakar ki ta derinden Titretiyor temelimden Gittiğin...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birak-gitsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamet Kopacak', 'kiyamet-kopacak-adem-tiras-yjsxy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne yapsan ne etsen de, bu çark böyle dönecek

Gün doğup, gün batıp, ay olup yıllar geçecek

Büyük muhasebe defterin  kapatmak için; 

Son ay,songün,  son saatle kıyamet  kopacak.', 'Ne yapsan ne etsen de, bu çark böyle dönecek Gün doğup, gün batıp, ay olup yıllar geçecek Büyük muhasebe defterin  kapatmak için;  Son ay,so...', ARRAY['Türk Edebiyatı','Şiir','Adem Tıraş']::text[], 8.5, '{"poet":"Adem Tıraş","poet_slug":"adem-tiras","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kiyamet-kopacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-gizem-bilgin-3nle4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günün birinde

Aynalara onuruyla bakabilmesi için insanın

Bugünden silmesi gerek dokunabildiği her hüznü

Gözlerinden ve ellerinden bu toprağın çocuklarının', 'Günün birinde Aynalara onuruyla bakabilmesi için insanın Bugünden silmesi gerek dokunabildiği her hüznü Gözlerinden ve ellerinden bu toprağı...', ARRAY['Türk Edebiyatı','Şiir','Gizem Bilgin']::text[], 8.5, '{"poet":"Gizem Bilgin","poet_slug":"gizem-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayna-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku', 'uyku-gizem-bilgin-r25ws', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hangi güne baksanız

  içinizde daha fazla zamanlar arıyorsunuz.

Dünyanın en güzel geceleri için fazla yorgunuz,

uyuyakalmak zamanı şimdi...', 'Hangi güne baksanız   içinizde daha fazla zamanlar arıyorsunuz. Dünyanın en güzel geceleri için fazla yorgunuz, uyuyakalmak zamanı şimdi......', ARRAY['Türk Edebiyatı','Şiir','Gizem Bilgin']::text[], 8.5, '{"poet":"Gizem Bilgin","poet_slug":"gizem-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uyku-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyduğum Hisler', 'duydugum-hisler-koksal-akar-01528', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ürpertir içimi duyduğum sesler. 

Ağla gitsin diyor bende tüm hisler. 

Nasılsa sayılı bütün nefesler. 

Kararmış gökleri sevda dağının. 

Gülleri solmuşça durur bağının. 

Elde varı bitmiş gençlik çağının. 

Yandıkça yanacak ateş içinde. 

Bir vurgun yemiş ki savaş içinde. 

Azrail gelecek can telaş içinde.', 'Ürpertir içimi duyduğum sesler.  Ağla gitsin diyor bende tüm hisler.  Nasılsa sayılı bütün nefesler.  Kararmış gökleri sevda dağının.  Gülle...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/duydugum-hisler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldatmak', 'aldatmak-sirma-mersin-cwc3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.....................................Aldatanların çoğu yalancı sevgililerdir........

Ne sanalı, ne gerçeği; 

Herkes birbirini aldatıyor! 

Aldanmak ahmaklık olsada; 

Bikaç tatlı, yalancı sözlerin içine düşen; acemi, çocuksu duygularla ,

Çoğu kez ağlıyor, yürekler...

Aldatmak alçaklık deseler de; 

Genci, yaşlısı, evlisi, bekarı, uzak, yakın fark etmeden; 

Devam ediyorlar,

Sahte sevgi gösterilerine...

Oysa! Sahipsiz ve sevgiye susamış mutsuz benlikler; aldanmanın peşinde...

Defalarca yıkılan yürekler; 

Gerçekleri bir gün fark edecekler...

23.02.04

Not: Aldatanlar aslında kendilerini aldatıyorlar... Aldatanlarda; bir gün mutlaka  aldatılacaktır... Aldatmayın, aldanmayın...', '.....................................Aldatanların çoğu yalancı sevgililerdir........ Ne sanalı, ne gerçeği;  Herkes birbirini aldatıyor!  Al...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aldatmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Öldüm', 'hep-oldum-aziz-ahmet-bulut-o6j5g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep  öldüm

Bıcağın iki yüzünde.

Keskin yüzü aşktı

Kör yüzü diyet.

-soldu bende gül yüzün

yine güz yine hüzün-', 'Hep  öldüm Bıcağın iki yüzünde. Keskin yüzü aşktı Kör yüzü diyet. -soldu bende gül yüzün yine güz yine hüzün-...', ARRAY['Türk Edebiyatı','Şiir','Aziz Ahmet Bulut']::text[], 8.5, '{"poet":"Aziz Ahmet Bulut","poet_slug":"aziz-ahmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hep-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Günahında', 'askin-gunahinda-sirma-mersin-celmx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkın günahında yanmak istiyorsan...

Hadi gel! gecemin koynuna...

Ruhun ruhumla sevişsin,

Bir gece, diğer gününün içinde kaybolana kadar....

23.02.04', 'Aşkın günahında yanmak istiyorsan... Hadi gel! gecemin koynuna... Ruhun ruhumla sevişsin, Bir gece, diğer gününün içinde kaybolana kadar.......', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/askin-gunahinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Olmak', 'adam-olmak-suat-oktay-wtooi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sucum ADAM olmaksa eger

ölumlerden ölum begen...

biz insansak eger

her turlu ölum ADAM olmaya deger! 

Ister vursunlar,

ister assinlar, asip kessinler...

Sucum dusunmekse eger

ölumlerden ölum begen! 

dert etmem, 

yaz yagmuru gibi gelip gecer,

saman alevi gibi söner gider; 

dusunmekse sucum eger...

Sucum ADAM olmaksa eger

Dusunmek, dusundugunu yazip söylemek

inan herseye deger! 

23-02-04 (Nödinge/Göteborg)', 'Sucum ADAM olmaksa eger ölumlerden ölum begen... biz insansak eger her turlu ölum ADAM olmaya deger!  Ister vursunlar, ister assinlar, asip ...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adam-olmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan!', 'yalan-hakan-er-rfogt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalan! 

Hayat yalan,

Sen yalan.

Senin için yanan,

Ben yalan.

Şimdi saat yalnızlığın zifiri karanlığı,

Ayrılığa bir dost bile kalmamış.

Gelişime mana veren bu gidiş,

Ölümüme anlam katan diriliş,

Bir gülüş olur.

Ağlatır seni elbet!', 'Yalan!  Hayat yalan, Sen yalan. Senin için yanan, Ben yalan. Şimdi saat yalnızlığın zifiri karanlığı, Ayrılığa bir dost bile kalmamış. Geliş...', ARRAY['Türk Edebiyatı','Şiir','Hakan Er']::text[], 8.5, '{"poet":"Hakan Er","poet_slug":"hakan-er","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalan-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Yakala', 'zamani-yakala-hakki-hakan-kaya-re9zn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat bir maraton yarış

Ne önde durdum ne geride

Aşk engelli bir yol

Gülü de sevdim dikeni de

Bir tiyatro sahnesindeyiz

Roller dağıtılmış bir bir

Kimi oynuyorken zengini

Kimi olmuş sefil

Sevgiler paylaştırılmış

Okunmuş sufleler

Kimi mutluluktan ağlarmış

Kimine acıdan kuleler

Bol perdeli bir oyun

Her perde bir yaşammış

Bir perdede oynanan

Bir dahakinde oynanmamış

Zaman ince bir kum

Parmakların arasından akan

Ellerim yumuk yumuk doğmuşum

Yumruklarımı sıkışım ondan

Hayatı istediğin gibi yaşa

Sınırlıdır yaşananlar zamanla

Zaman tükenir er geç

Yaşama erken kal

Ölüme geç', 'Hayat bir maraton yarış Ne önde durdum ne geride Aşk engelli bir yol Gülü de sevdim dikeni de Bir tiyatro sahnesindeyiz Roller dağıtılmış bi...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zamani-yakala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Magazin Programları', 'magazin-programlari-mesut-kurt-zkbgv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tv uyutuyor tüm insanları.

Helede magazin programları.

Yozlaştırıyor tüm insanları.

Helede magazin programları.

Kendi geçmişini hatırlamaz millet.

Geleceğimiz ise tam bi felaket.

Onlara  kol kanat geriyor devlet.

Helede magazin programları.

Bilmez gençlik yaşayan evliyaları.

Mukaddes toprakları yada diyarları.

Bildikleri sanatçıların patlayan silikonları.

Hergele bu magazin programları.

(21 02 2004 tarihinde saat 21:50 de yazılmıştır)', 'Tv uyutuyor tüm insanları. Helede magazin programları. Yozlaştırıyor tüm insanları. Helede magazin programları. Kendi geçmişini hatırlamaz m...', ARRAY['Türk Edebiyatı','Şiir','Mesut Kurt']::text[], 8.5, '{"poet":"Mesut Kurt","poet_slug":"mesut-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/magazin-programlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbadet Yoksulu Gençlik', 'i-badet-yoksulu-genclik-mesut-kurt-0ppcm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaçmak ne kadar kolaymış ibadeten.

Gezeriz bol bol geri kalmayız ziyaretten.

Ne kazanırız sanki yanlış ticaretten.

Bu dünyaya aldanmayalım zaman geçmeden.

Yanlışa uyup yanlış yapmayalım.

Zamanın hesabını iyi yarlayalım.

Hayallerimize kapılıp uçmayalım.

Ahirete hazırlıksız yakalanmayalım.

(11 12 2003)', 'Kaçmak ne kadar kolaymış ibadeten. Gezeriz bol bol geri kalmayız ziyaretten. Ne kazanırız sanki yanlış ticaretten. Bu dünyaya aldanmayalım z...', ARRAY['Türk Edebiyatı','Şiir','Mesut Kurt']::text[], 8.5, '{"poet":"Mesut Kurt","poet_slug":"mesut-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ibadet-yoksulu-genclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son yolculuk', 'son-yolculuk-olcay-kose-yidwu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu son sigaram

ve bu son gidiş

hangi sokakta olduğumu bilmeden 

hangi yöne sapacağıma karar vermeden

bu son yolculuk yalnızlığa

kendime senden bir pay çıkartamadım

sana bir şey veremedim kendimden 

affet

oysa ayrılık böyle değil

böyle olmamalı

sakın ağlama

bıraktığım nefesimi dudağına

bir sitemse sevdiğim

elveda', 'bu son sigaram ve bu son gidiş hangi sokakta olduğumu bilmeden  hangi yöne sapacağıma karar vermeden bu son yolculuk yalnızlığa kendime send...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/son-yolculuk-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış İş', 'yanlis-i-s-mesut-kurt-8ooq0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nice programlar yapılmıştı gelmeden.

