INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Hasretin Yakanı Kaldı', 'i-cimde-hasretin-yakani-kaldi-murat-demir-ifj4l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül sevdasının aktım suyuna

Bir değil derdini çektim boyuna

Ben kimseye boyun eğmezdim ama

Sinemde bir gülün dikeni kaldı

Sardı yüreğimi sardı har gibi

Çöktü saçlarıma beyaz kar gibi

Alevi bitmeyen kızıl kor gibi

İçimde hasretin yakanı kaldı

Gazabıyla çektirdiği azaptan

Ateşim kül oldu uçtu ocaktan

Bir aşk ki aklımı alınca baştan

Bana acıların yıkanı kaldı

Kapısında koydu hanın hancının

Kölesi eğledi bir yabancının

Bir sevda sonunda derdin acının

Tokatını cana çakanı kaldı', 'Gönül sevdasının aktım suyuna Bir değil derdini çektim boyuna Ben kimseye boyun eğmezdim ama Sinemde bir gülün dikeni kaldı Sardı yüreğimi s...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/icimde-hasretin-yakani-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-ceyda-ayfer-oz-cub8g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çığırını aşmış bir dalga altında kalmak var soluksuz

Ya da son bir hamledir nefes alacak

Hayat ile ölüm arasında

Zordur vedalar bazen ağırsa yükün

Cebinde götürsün tüm sevgileri

Ayazda çıkarıp sokak ortasında

Ürkek bir kedi yavrusu gibi bakarken etrafa 

Sarılırsın sıcacık

Işık edersin caddelere koca şehirde

Zordur gitmesi uçurumlara ayaklarınla

Gözlerini kapatırsın

Salarsın kendini bilinmedik boşluklara 

Başın diktir hep

Sanırlar ki vurdun mu ses getirirsin

Titrek yürek sesini sadece martılara dinletirsin

Zordur bu gidişler……

Sığınmak istersin sevdiğinin kanadına

Buradayım desin istersin sadece, 

Burada…

Ama soğuktur, 

Sessizlikle üşütür bazen geceler…

Korkma der içindeki ses, sakın korkma…

Ve durma! 

Rüzgara bırakırsın kendini 

Çıkarsın yola…

Sesin yankılanır ardından

Elveda…', 'Çığırını aşmış bir dalga altında kalmak var soluksuz Ya da son bir hamledir nefes alacak Hayat ile ölüm arasında Zordur vedalar bazen ağırsa...', ARRAY['Türk Edebiyatı','Şiir','Ceyda Ayfer Öz']::text[], 8.5, '{"poet":"Ceyda Ayfer Öz","poet_slug":"ceyda-ayfer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/elveda-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşimdin', 'gunesimdin-gulay-yildiz-l4uy1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabahın en güzel anıdır güneş yüzümdeyken

Ben sensizlikten değil, güneşsizlikten ürkerim

Zira güneşimdin...

Giden ışık, ısı! nefes, dokunuş değil

Kalan bir yanık ten, yürek değil

09/03/04 10:30', 'Sabahın en güzel anıdır güneş yüzümdeyken Ben sensizlikten değil, güneşsizlikten ürkerim Zira güneşimdin... Giden ışık, ısı! nefes, dokunuş ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunesimdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seneler', 'seneler-ozden-cakmak-uc31c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimde bir bahçe var 

Lakin her yeri tarumar.

Terkederken o''nu umutlar ve sevgiler

Birer birer solmuş tüm çiçekler.

Ne yağan yağmur

Ne parlayan güneş kareder,

Nafile şakıma artık bülbül

Belli ki yanlış yaşanmış seneler.', 'Kalbimde bir bahçe var  Lakin her yeri tarumar. Terkederken o''nu umutlar ve sevgiler Birer birer solmuş tüm çiçekler. Ne yağan yağmur Ne par...', ARRAY['Türk Edebiyatı','Şiir','Özden Çakmak']::text[], 8.5, '{"poet":"Özden Çakmak","poet_slug":"ozden-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seneler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimedi hiç sevdan...', 'eskimedi-hic-sevdan-omer-faruk-girgin-nioad', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eskidi aylar, yıldızlar, mevsimler.

İnsanlar eskidi, ağaçlar, kuşlar eskidi.

Eskidi dertler, sevinçler, yıllar eskidi.

Bulutlar eskidi, denizler, gökyüzü eskidi...

Ama sevdan hiç eskimedi...

Mühür gözlerin, gülüşlerin eskimedi,

Bal peteği öpüşlerin eskimedi,

Delice sevişmelerin hiç eskimedi...

Güneş eskidi, kelimeler, sesler eskidi.

Eskidi yağmurlar, renkler, çiçekler eskidi.

Yalanlar, eskidi, kavramlar, şarkılar eskidi.

Şaraplar, kadehler, sazlar eskidi...

Ama sevdan hiç eskimedi...

Gül yaprağı dudakların, buğulu bakışların eskimedi.

Ballı ağzın, baygın kokun eskimedi,

Seni seven şu gönlüm ve şarkım hiç eskimedi...', 'Eskidi aylar, yıldızlar, mevsimler. İnsanlar eskidi, ağaçlar, kuşlar eskidi. Eskidi dertler, sevinçler, yıllar eskidi. Bulutlar eskidi, deni...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eskimedi-hic-sevdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam, Garip Anam', 'anam-garip-anam-galip-sinecikli-pji2e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ah benim garip Anam,

çilekeş anam,

dokuz ay karnında taşıdın

sancılandın benim için

acılar çektin

doğurdun

emzirdin

uykusuz kaldın benim için gecelerce

büyüttün

yağmurdan korudun

kardan korudun

yemedin yedirdin

içmedin içirdin

giymedin giydirdin

okutmak için beni

geceleri yemek hazırladın

çay demledin

ben ders çalışırken

benden fazla sen çabaladın

sanki benim yerime sen okudun 

şimdi büyüdüm

geldim otuzyedi yaşıma

ama beni severken

bebeğim diye seviyorsun

ben sende hiç büyümedim

beni hala kolluyorsun

başka bir ilde çalışıyorum

her sabah arayıp uyandırıyorsun

her akşam arayıp

''Sıkı giyin öyle yat'' diyorsun

anam benim 

çilekeş anam

senin hakkını ödeyemem anam

Cennet senin ayaklarının altında

ben ayağının altında toz olayım anam

ayağının altında beni Cennete götür

eksik etme duanı anam

oğluna hakkını helal et

cefakar anam

çilekeş anam

seni çok seviyorum

vefakar anam.

www.radyoerguvan.com

www.galipsinecikli.blogcu.com

[email protected]', 'ah benim garip Anam, çilekeş anam, dokuz ay karnında taşıdın sancılandın benim için acılar çektin doğurdun emzirdin uykusuz kaldın benim içi...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/anam-garip-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kortizon', 'kortizon-burak-cicek-jkyfr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana kortizon sözler iyi gelir,

Narkoza yamaya nazır.

Yatmaya hazır mısın benimle,

Condom? 

Bir taşla iki puşt! 

Gidip gelişlerimizin ucu doruğa, kıçı tavana vursun her defa.

Kordon -ki her bebeği annesine bağlayan

Bizde de var malesef ki ondan

lanet kıçını lanet kıçımı tutturan.

Şiirin suyu çıktı bugün,

Ne kafiye, ne relif

Aruz yerine transeksüel bir fahişe

SEN! 

Hece ölçüsü isteyene

güzel bir hediye

..kimin ölçüsü...', 'Bana kortizon sözler iyi gelir, Narkoza yamaya nazır. Yatmaya hazır mısın benimle, Condom?  Bir taşla iki puşt!  Gidip gelişlerimizin ucu do...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kortizon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Romantiğim Bu Sabah', 'bir-romantigim-bu-sabah-ozan-ozel-f80jw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir romantiğim bu sabah

Kıpır kıpır yüreğim

Yeni başlamış gibiyim hayata

Öfkelerden arınmışım, hafiflemişim

Gözlerim daha bir parlak bakıyor 

Kulaklarım kötü sözlere kapalı

Akşamdan kalan bel ağrım gitmiş

Sakalımdaki beyazlar eksilmiş

Pek de güzel görünüyorum aynada

Söylediğim gibi işte; 

Bir romantiğim bu sabah

Kendime aşık oldum tekrar!', 'Bir romantiğim bu sabah Kıpır kıpır yüreğim Yeni başlamış gibiyim hayata Öfkelerden arınmışım, hafiflemişim Gözlerim daha bir parlak bakıyor...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-romantigim-bu-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamsar Sansar', 'karamsar-sansar-burak-cicek-rimeu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çoğaldı yine niteliksiz,

niceliksiz tehtidler.

Aşka doğru orantı

Bırakıp da gitmeler.

''Vazgeçtim'' diye bir şarkı

sınırsız geçişler.

Nice olacak bu halimiz? 

Nicedir bu haldeyiz.

Biz dün tükeneceğiz, ömürler tüketeceğiz', 'Çoğaldı yine niteliksiz, niceliksiz tehtidler. Aşka doğru orantı Bırakıp da gitmeler. ''Vazgeçtim'' diye bir şarkı sınırsız geçişler. Nice ola...', ARRAY['Türk Edebiyatı','Şiir','Burak Çiçek']::text[], 8.5, '{"poet":"Burak Çiçek","poet_slug":"burak-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karamsar-sansar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durmayacak', 'durmayacak-erol-sen-9oq1b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son demlerini yaşayan kışlarım gibi

Sevgisiz geçen saymadığım günlere

Yeni gün de olacaklara umudum gibi

Kışlarda geçecek bahara gülüm

Durmayan günlerin mevsimleri değiştirmesi gibi

Ayların yıllara bağlanması

Geçen günün ayın ömür biçmesi

Son demlerini yaşayan kışın bitimi

İçimden gelen gördüğüm gözümle

Biten stok şiirlerime yenilerini eklemek gibi

İsyanın sözlere dökülmesini bilmek

Bunları beyaz satırlara karalamak

Biten aylar yıllar mı ömürlermi

Ömür biçen günleri tamamlamak

Sevinçlerimde var hüzünlerimde

Karmaşık duygularımda

Umuda giden yolların sonu olduğu gibi

Durmayacak düşüncelerle birlikte

Durmayacak hayatın akışı

Elbet sabah geceye ulaşacak.

09.03.2004', 'Son demlerini yaşayan kışlarım gibi Sevgisiz geçen saymadığım günlere Yeni gün de olacaklara umudum gibi Kışlarda geçecek bahara gülüm Durma...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/durmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimizin dünyası', 'i-kimizin-dunyasi-ayten-ozlem-yesilcali-r53mw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle küçük birdünya istiyorum.

Apak bir sayfa.

Ufacık tek katlı bir ev

Biryatak odamız olsun; 

minikbir oturabilecegimiz,

yer minderli bir oda

Ama başka hiçbirşey olmasın

sevgimizle dopdolu.

eşyalarımız sevgimiz olsun...

Penceresinde perde degil; 

Aşkımız olsun.

Düşlerimiz sevişmelerimiz olsun.

Menekşe rengi olsun 

Duvarlarımızın boyası...

Bahçesinde; 

Aşkımızla sevgimizle beslediğimiz.

Mimozalar,rengarenk gül fidanları.

Yediveren çiçekleri.

Pencerenin önünde 

Reyhan...

Nede güzel kokar bilirmisin? 

Hele aşkımız sevgimizle beslersek.

Gece ılık rüzgar estikçe

Odamız reyhan kokusuyla; 

O ılık rüzgarın esintisiyle.

Sevişmelerimiz  reyhan kokusuyla.

Hiç tartışmayalım bile aşkım.

hep sevelim sayalım birbirimizi

İncitmeyelim kalplerimizi.

Adresimiz ne olsun 

Biliyormusun? 

Hayal mahallesi

Sevenler Sokak.

Aşk malikanesi....

 ikimizin dünyası.', 'Seninle küçük birdünya istiyorum. Apak bir sayfa. Ufacık tek katlı bir ev Biryatak odamız olsun;  minikbir oturabilecegimiz, yer minderli bi...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ikimizin-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpmek Geldi Seni İçimden', 'opmek-geldi-seni-i-cimden-bekir-mutlu-gokcesu-68vj8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk kez

Rastladığımda

Sana ben

Saçların uçuşurken

Ne güzel bakıyordun

Gülen gözlerinle

Yürekli bir şiirin

Deniz manzaralı

Dizelerinden...

Basmadan sözcüklere

Usulca yürüdüm geçtim

Kelimelerin arasından

Mısra, mısra kaydım

Satır sonlarından

Olsa, olsa rüya dedim

Gözlerimi ovuştururken

Son dörtlüğe gelmeden

Ayağım takılıp da düşünce

Yumuşak g’nin üstüne

Bir noktalı virgülden

İçinde dudakların olan

Bir parantez açıp kapadın

Güldün gamzelerinden

Sen, fısıldarken içinden

Ve ben pür dikkat şiiri

Dudaklarından okurken

Öpmek geldi seni içimden...

Sonra en güzel sözcüklerden

Güller topladım, sen kokan

Hayranlığım ve sevgimden

Güzel olan ne varsa kattım

Naçizane azcık da benden

Bir buket yaptım sana

Etrafa saçılan harflerden...', 'İlk kez Rastladığımda Sana ben Saçların uçuşurken Ne güzel bakıyordun Gülen gözlerinle Yürekli bir şiirin Deniz manzaralı Dizelerinden... Ba...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/opmek-geldi-seni-icimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü Bozulmasın', 'buyu-bozulmasin-ozan-ozel-at7lu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırakma ellerimi, 

Sıcaklığına muhtacım

Kaçırma gözlerini

Bakışların ilham veriyor bana

Gülsün dudakların

Kahkahaların şuh ve arzulu

Ama ne olursun konuşma

''Büyü bozulmasın''', 'Bırakma ellerimi,  Sıcaklığına muhtacım Kaçırma gözlerini Bakışların ilham veriyor bana Gülsün dudakların Kahkahaların şuh ve arzulu Ama ne ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buyu-bozulmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çift Lafım Var!', 'bir-cift-lafim-var-necmi-unsal-embaj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aldın  beni  benden,  eşkıya mısın  çapulcu  mu? 

Ey  dünya!  Al  abdestini  ver  bana  pabucumu! 

Bir  parça  kabir  toprağıyla  doldurdun  avcumu.

Kefene  sardın!  Bezzaz mısın  yoksa  tapucu mu? 

                                    

15  Şubat  2004 Pazar,  Danimarka-Køge  23.15

9+6', 'Aldın  beni  benden,  eşkıya mısın  çapulcu  mu?  Ey  dünya!  Al  abdestini  ver  bana  pabucumu!  Bir  parça  kabir  toprağıyla  doldurdun ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-cift-lafim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-ozan-ozel-reudh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnız geçen bu gecede mutluluğu aradım

Karanlık odamın penceresinden bakarken

Yağmurun ıslattığı kaldırımlara yansıyan

Sokak lambalarının aydınlığını gördüm

Yalnız olmadığımı anladım

Sanki bütün ışıklar üzerimde toplanmıştı

Karanlık sahnede spotların aydınlattığı

Bir yıldız gibi hissettim kendimi

Onun seyircilerine gülümsediği gibi gülümsedim

Şarkılar söyledim karanlığa ve yağan yağmura

Yağmur zerreciklerinin yere vururken çıkarttıkları sesler 

Alkış oldu bana

O anda mutlu oldum, gülümsedim tekrar

Ve tıpkı onun gibi, yarım reverans yaparak

Selamladım yağmurun ıslattığı karanlık sokakları

Ardından uzandım yatağıma

Bu gecenin sabahında ıslak uyandım...', 'Yalnız geçen bu gecede mutluluğu aradım Karanlık odamın penceresinden bakarken Yağmurun ıslattığı kaldırımlara yansıyan Sokak lambalarının a...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-gece-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amacıma Ulaştım', 'amacima-ulastim-ozan-ozel-cjq0h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her zaman 

Sana yakın olmak

Seni sevdiğimi söylemek istedim

Ama sen buna engel oldun

Ben yaklaştıkça, sen uzaklaştın

Devamlı benden kaçtın

Yine de peşini bırakmadım

Sana yaklaştım 

ve kulağına

Seni sevdiğimi fısıldadım

''Sonunda amacıma ulaştım''', 'Her zaman  Sana yakın olmak Seni sevdiğimi söylemek istedim Ama sen buna engel oldun Ben yaklaştıkça, sen uzaklaştın Devamlı benden kaçtın Y...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/amacima-ulastim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Ana', 'mutluluk-ana-ozan-ozel-v7thr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ağlayan gözlerin

bir çiçeğin

bahar sabahına uyanması gibi

güler bir süre sonra

denizden yeni çıkmış balığın

üzerindeki yaldızlar gibi parlar

yalçın kayaları döven şelaleyi andırır

dudaklarından akan kahkahalar

ve ''mutluluk ana'' nın kucağına koşarsın...', 'ağlayan gözlerin bir çiçeğin bahar sabahına uyanması gibi güler bir süre sonra denizden yeni çıkmış balığın üzerindeki yaldızlar gibi parlar...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mutluluk-ana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kutup', 'i-ki-kutup-yusuf-canturk-1pqt5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgar  ekip  fırtına  biçtik, acep kimdi   suçlu? 

                Hâlâ  bana  döner  mi,  içimde  var,bir  kuşku? 

                Çeker iken  iki   kutup  itermiymiş  zamanla? 

                Manası  müphem  ise,  bir  bilene  sor  anla! 



                Ne  anlarsın  duygulardan,  güzellikten  ve  Gülden! 

                Sevmesini  bilir  misin,  içten  ve  gönülden? 

                Senin  arzun   bir  taht,bir  de  süslü  taç

                Kâlbimse,  inan,  sevgine,  aşkına  muhtaç.



                Yine  çok  üzgünüm,sana  özür  borcum  var,

                Hatalarım  olsa  da, sensin  gönlümdeki  yar.

                Desem  ki “Bana  gel,  bir  defacık  beni  sar”,

                Kabul  et  de  senden  bana  olsun  yadigar.

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Rüzgar  ekip  fırtına  biçtik, acep kimdi   suçlu?                  Hâlâ  bana  döner  mi,  içimde  var,bir  kuşku?                  Çeker i...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iki-kutup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Bir Ateşmiş', 'sevda-bir-atesmis-yusuf-canturk-6mkji', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu  gün  gönlüm  çok  firaklı,  neden  çok,

                Gözlerinde  özlem  gördüm, neyse,  acı  yok.

                Acep  düşüncende  neler  saklı  bilemem,

                Yüreğime  kazınmışsın,  izlerini,  silemem.



                Gölümde  hep  sen  varsın,  muhabbetin  yer  etmiş,

                Bir  tatlı  tebessümün  yıllarca  uzağa  gitmiş,

                Bu  gün  yine  yalnızım,  gözlerim  daldı,

                Seninle  buluşmak, belki  de  mahşere  kaldı.



                Kâlbimde   bir şeyler  akıp  gidiyor,

                Sevda  bir  ateşmiş  yakıp  gidiyor! 

                Bir  Ceylan,  bir  çift  göz  bakıp  gidiyor,

                Ardında  bin  bir  ümit  takıp  gidiyor.

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Bu  gün  gönlüm  çok  firaklı,  neden  çok,                 Gözlerinde  özlem  gördüm, neyse,  acı  yok.                 Acep  düşüncende  n...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevda-bir-atesmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıkları Sönmesin', 'isiklari-sonmesin-yusuf-canturk-62s9t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çileli  hayatın  hiç   kalır  mı   tadı? 

                Yegâne   dayanak  yine,  sevginin  adı.

                Göğsüme   olsaydın   altın  bir  kafes,

                Alsaydım  dudağından  taze  bir  nefes.



                Gözlerinin  yeşili,  yosunlara  aksetmiş,

                Saçlarının  kızılı,  güneş  ile  raks  etmiş,

                Gülüşünle  dudağın,  gelinciğe  bürünmüş,

                Dişlerinin  beyazı   sanki, incilere  sürünmüş.



                Sevgim  ateş  idi,  oldu  şimdi  bir  köz,

                Seni  değil,  yıllarca  beni  kavurdu,  yaktı.

                Unuttun  vermiştin,  nice  vaat,  nice  söz.

                Gönlüm  sana  kırılmakla  çok  haklı! 



                Sanki  seher  yıldızı, o  yemyeşil  gözlerin,

                Bakmakla  doyamam,  hayat  boyu  özlemim. 

                Ne  olur  bakışların  başka  yöne  dönmesin! 

                Yıldız  gibi  parlayan,  ışıkları  hiç  sönmesin

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Çileli  hayatın  hiç   kalır  mı   tadı?                  Yegâne   dayanak  yine,  sevginin  adı.                 Göğsüme   olsaydın   altın...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isiklari-sonmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Gibi', 'gunes-gibi-yusuf-canturk-v3tzv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakışların   sevda   yüklü,  gerek  yoktu  sözlere,

                Hayranlıkla  dalıp  gittim,  o  yemyeşil  gözlere.

                Sen  giderken  kâlbim  rikkatli  ve  çok  yufka,

                Güneş  batar  gibi,  sanki  kızıl   ufukta.



                Dudağından   bir  kerecik  sevgi  sözü   çıkmadı.

                Oysa  bakışların  hayalimi,  hiç  de  yıkmadı.

                Seni  her  görüşte  bir  başkadır,  yüreğimin  atışı,

                Sen  giderken   çabuklaşır,  güneşimin  batışı.



                Ölsem de  silemem  kâlbimden  seni.

                Yakında  giysem  de  beyaz  kefeni,

                Bu  âşk   yeni  değil,  belki,  ezelî,

                Mutluyum gerçekten, seni,  sevdim,  seveli

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Bakışların   sevda   yüklü,  gerek  yoktu  sözlere,                 Hayranlıkla  dalıp  gittim,  o  yemyeşil  gözlere.                 Sen  ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunes-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temizlik Duygusu', 'temizlik-duygusu-yusuf-canturk-3l2zv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adamışız  kendimizi  temizliğe,  işe  ve  güce,

                Çalar   iş  borusu,  toz   zerresi  görünce.

                Bazen  güneş  doğarken,  kapı,  pencere,  cam,

                Bir  an   durup   nefes  alırız,  okunurken  ezan.



                Bazen  şafak   sökerken   iş  başı  yaparız.

                Tâ  uzaklarda  da  olsa,  nezle,  grip  kaparız.

                Çevre  kirliliği  ise,  en  büyük  üzüntümüz.

                Kapımızın   dışında,  pek  geçmiyor   sözümüz.



                Temizlik  aslında,  çok  ince  bir   sanat,

                Özenli  ve  dikkatli  yapılmazsa,  kaldırıp da  at.

                Yorgunluktan   kırılsa  da  kollar  ve  kanat,

                Neticede   duyulur   artık,  huzur  ve  rahat.

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Adamışız  kendimizi  temizliğe,  işe  ve  güce,                 Çalar   iş  borusu,  toz   zerresi  görünce.                 Bazen  güneş  d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/temizlik-duygusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gune-Bakan', 'gune-bakan-yusuf-canturk-i4fsx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adın  niye  Güne Bakan, Güneş  midir  seni  yakan? 

                Güneşe  mi  tapıyorsun,  takip  edip  bakıyorsun?

                Başın  eğik,  bükük  boynun,  faydalıdır, bence  soyun.

                Kararmaya yüz  tutunca,  eksiliyor  hayat  suyun.

              

                Tarlaları,  ovaları,  bahçe  gibi  süsler  rengin,

                Faydalısın  insanlara,  pek  bulunmaz  senin  dengin.

                Sarı,  yeşil  renklerinle, haz  verirsin  bakanlara,

                Bağımlısın  toprağına, güneş  gibi,  yakanlara.



                Tanelerin  dolunca,  hasat  vaktin  gelmiştir.

                Rengin  siyah  olunca,  ömrün  sona  ermiştir.

                Kuruyup  sararırsın,  yıla  basmadan  yaşın,

                Bir  orakla  secdededir,boynu  bükük  kara  başın.



                Tarlalar,  düz  ovalar,  artık  kara  yastadır.

                Tanelerin  preslenir,gözler  gibi  yaştadır.

                Fakiri  de,  zengini  de  bekler  seni  her  yaşta,

                Artık  çok  hoş  lezzetin  var, her damakta,her  aşta.

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Adın  niye  Güne Bakan, Güneş  midir  seni  yakan?                  Güneşe  mi  tapıyorsun,  takip  edip  bakıyorsun?                 Başın ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gune-bakan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağı Gibi Gülümse', 'gokkusagi-gibi-gulumse-galip-sinecikli-1yge3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çılgın bir rüzgarın ardından beliren,

Gökkuşağı gibi gülümse hayata,

Boşver geçip gidenlere,

Sen bak bundan sonrasına,

Yıpratmasın seni acılar, kederler,

Sarsmasın seni elemler, dertler,

Gökkuşağı gibi mutluluk saç heryere,

Seni gören sevinsin sen geldin diye,

Her acının ardından patlat bir kahkaha,

Doğan yeni gün yeni umut demektir sana,

Her yeni umut yeni mutluluk demektir,

Mutluluğun anahtarı,

SEVMEKTİR.......', 'Çılgın bir rüzgarın ardından beliren, Gökkuşağı gibi gülümse hayata, Boşver geçip gidenlere, Sen bak bundan sonrasına, Yıpratmasın seni acıl...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gokkusagi-gibi-gulumse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrıl Diyorsun', 'ayril-diyorsun-engin-namli-osqjs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Esaretin olduğum aşktan ayrıl diyorsun

Ne beni dinliyor ne de bir söz ediyorsun

Gönlümdeki yerini görmeden gidiyorsun

Elveda anılara elveda aşkımıza 

Kolum da kanadım da sen dediğin sevgili

Tutmadı hiç ömründe bir gün yabancı eli

Maziyi kutsayacak aşkın bu mu bedeli

Elveda anılara elveda aşkımıza 

Çalınırsa kapım o titreyen ellerinle

Açılmayacak sana olsan da güllerinle

Avuttun hep yıllarca o tatlı dillerinle

Elveda anılara elveda aşkımıza 

Gidiyorum acısı belirsiz sensizliğe,

Sedasından kesilmiş bir garip sessizliğe

Varmalıyım en yakın yerden kimsesizliğe

Elveda anılara elveda aşkımıza 

  23:05 06.03.2004', 'Esaretin olduğum aşktan ayrıl diyorsun Ne beni dinliyor ne de bir söz ediyorsun Gönlümdeki yerini görmeden gidiyorsun Elveda anılara elveda ...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayril-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzular', 'arzular-yusuf-canturk-baa2n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömür  boyu  yaşasam,  seninle  bıkmam,

                Kul  köle   ol  desen,  hatırın  yıkmam; 

                İncitmek  istemem  seni,  kendi  dünyamda,

                Öpmeye  kıyamam  inan,  tatlı  rüyamda.



                Yalan  olsaydı,  seni  sevdiğim,  yalan! 

                Yaşayamam  yılları,  sensiz,  geri  kalan,

                Gülüşünle  beni  sen,  mecnun  gibi  edersin,

                İri  yeşil  gözlerinle,  dünyalara  bedelsin.



                  Gönül   arzularım  sonsuz,  yaşayamam  ben  Onsuz,

                Çölde  kalmış  gibi  susuz,  günler  kaldım  uykusuz.

                Gündüzüm  gece,  gecelerim  hep  gündüz,

                Dağlar  tepeler  aştım,  şimdi  yolum  hepten  düz

                 Yusuf  Cantürk(E:Hv Kur.Alb.)                                                       temmuz  1997  şarköy', 'Ömür  boyu  yaşasam,  seninle  bıkmam,                 Kul  köle   ol  desen,  hatırın  yıkmam;                  İncitmek  istemem  seni,  k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/arzular-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S/oyanbaş Durr', 's-oyanbas-durr-i-hsan-uncuoglu-1fzey', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'S/oyanbaş Durr                                               

Turna gözü öyle okla vurulmaz,hepsi eğri düz yok ki 

Atılsa bin def`a çeşit eğri biri bulurmu doğru yeri 

Yabanda çook gözüm açık diye, Dünyayı kandıran var 

Ortalıksız doğruda, kaç ölçek kaç değerli belirlimi. 

*** 

Parmak ucuyla nice dün bugün, hepsi kaç Renkli,Tilkili, 

Kaç sağsol orta diye kimin eğri gidişi sıfırlamış neyleri 

Karayollar yürümekle aşınmazmış! ,Taakım! ,DURRrr! iileri 

Uygunadıım! iileri! devam nereye köy habersiz Ağam döngeri. 

*** 

Kurnazca kaç seneler senesi her taşın altından kalkan 

Her meydanda atılmadık taş kalmamış, çoook öyle başolan 

Elpençe duran binler kısmetli aranan bunlar galiba enayi

Ayakta rüyada biri hiç olmazsa Soğanbaş! ,görsen Soyanbaş gibi.', 'S/oyanbaş Durr                                                Turna gözü öyle okla vurulmaz,hepsi eğri düz yok ki  Atılsa bin def`a çeşit eğ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/s-oyanbas-durr-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OlmAk Ya da OlmAmaK gibi Küçük Bir Sorun', 'olmak-ya-da-olmamak-gibi-kucuk-bir-sorun-mine-ozdemirtas-g7tet', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En büyük düşmanımız Zaman,

Ve; en yakın dostumuz gene o.

Acıyan yerimize ilaç olan.

-------------

Bir deli bir kuyuya bir taş attığında,

Kırk akıllı engel olamazken taşın boğulmasına

Kaçımız baş kaldırabiliyoruz ki yaşamlarımızın

Dolap beygirliğini kabulenişimizce Eyerlenip,nallanmasına.? 

Oysa ki,

Çarkın dönüyor olması, sadece çarkçının umurunda.

Ve,

Bu çarkçının kim olduğu sorgulandığında, 

İçimize dönüp bakmamız gerekirken, tam o anda,

Neden? kanayan yaralarımızın üzerine basmayı 

sürdürmeyi seçeriz ki? Gölgelerimizden ürken korkak adımlarla

Bu arada,

Mensup olduğumuz sürüden, mangal yürekli biri çıkarsa 

Üstelik, yok etmeye çalıştığımız bir var oluşun

Sesi olup ulaşırsa kuma gömdüğümüz başımızdaki kulaklara

Hemen 3 maymun kesilmeyi marifet sayarak...... hatta,

Kuru gürültü gibi, çamurumsu, yapışkan bir yaygara

Yerleştirmeyi sürdürdüğümüz müddetçe dudaklarımıza,

Biz farkında bile olmadan geçecek zaman. 

Ki aslında; 

Bir delinin bir kuyuya attığı çakıl taşı gibi kaybolmaktayız

Kendi kör kuyularımızın girdaplarında.

Ucuz değil asla. Meydan okumak kurallara.

Hele ki kadınsan, ve bir rahim taşıyorsan bacak aranda

Bir de..... Pantolon içinde özenle saklanan erkeklik için

Sen dersen ki ''asıl erkek olmak'' benim usumda.

Elbet ki birileri... seni...... arkandan iter uçuruma.

Ateşin üzerinde dans etmek. /Üstelik çıplak ayakla.

Her yiğidin harcı değil ha./ Öyle.......... kolay sanma.

Hiç kolay değil/ doğru bildiğin yolda

inançla..... inatla.... daima tek başına....Uzanmak bulutlara.

Bir kez,

Uyup ta yüreğinin çığlıklarına / tabii cesaretin varsa.

Çıkabilirsen o yola. Hemen farkına varırsın ki,

Sıra dışı olmanın yükü çok ağırdır aslında.

Ama,........... bilirsin ki o, tam düşeceğin anda; 

Seni kucaklayacak olan kuş. Ki, o''nun adı Zümrüt’ü Anka

Dolap beygiri olmamak gibi bir muştunun mührünü taşıyor kanatlarında.

09/03/2004 Kartal', 'En büyük düşmanımız Zaman, Ve; en yakın dostumuz gene o. Acıyan yerimize ilaç olan. ------------- Bir deli bir kuyuya bir taş attığında, Kır...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/olmak-ya-da-olmamak-gibi-kucuk-bir-sorun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağa', 'topraga-zafer-zengin-etnika-87xz1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğim 

düşünce 

toprağa

dayanılmazdı

bu ayırlığa

bir dost''un sesi olmasa...

Ayrılıp bizi yalnız koyanlara...sevdayla..yolunuz açık ola..eyvallah...', 'Yüreğim  düşünce  toprağa dayanılmazdı bu ayırlığa bir dost''un sesi olmasa... Ayrılıp bizi yalnız koyanlara...sevdayla..yolunuz açık ola..ey...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/topraga-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar', 'kadinlar-sirma-mersin-6h3f0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '......  Bayanlar üzerine yazdığım bir yazı...

Kadın var, kadıncağız var...

Söze nereden başlamak doğru bilmiyorum...

En iyisi dünya kadınlarını değil; 

Biz Türkiye''nin kadınlarına bakalım...

Doğu-Batı, Kuzey-Güney demeden dokunalım birkaçına...

Meryem: Daha onyedisinde iken, başlık parasınla 

evlendirilip, 2 öksüz, 1 beygirle takas edilmiş 

şimdi ise; büyükşehrin altın toprağına inanıp, ailesi ile göç etmiş...

6 kız, 1 oğlan anası..

Hacer: Kırsal kesimde  erken evlenen biri daha..Kocası kahvede oturan,

tarlada çalışan , kuması ile aynı evde yaşamak zorunda kalan kısır kadın..

Emine: Köyden kentte göçmüş, çocuklarının rızıkı için çalışıp, 

gündeliğe giden, kocasından dayak yiyen kadın...

Suna: Herhangi bir sektörde 3 kuruş maaşla kocasına destek olmaya,

2 çocuğunun geleceğini düşünen... evle iş  arasında koşup, duran bi başka ana ve aldatılan bir kadın...

Aleyna: Muhafazkar,tutucu bir ailenin baskısı altında, yobaz düşüncelerin

arasında kalmış içe dönük genç bi kız.

Devrim: Üniversite mezunu, çağdaş, laik bi ortamda yetişmiş,mevkii sahibi

olmuş, kültürlü çalışan genç bi bayan.

Alev: Lüks içinde yaşayan, sosyette sayfalarında  boy gösteren,zengin,

şımarık, evle ilgisi olmayan, bir bayan.

Toplumda sıkca rastladığımız; bayan tiplerinden bikaç örnekti...

Unutulmaması gereken birkaç şey! 

Kadın olmak; herşeyden önce, yuvasının dişi kuşu olmasından 

ötürü ailesine bağlı, çağdaş, kendine güveni olan, bir birey olduğunu 

bilmesi gerek..

Her kadın; zeki, güzel (çirkin yoktur, bakımsız kadın vardır.) , kültürlü

(kendisini geliştirmiş olması.)  olması yeter....

9.3.04

Not: 8 Mart gününüz kutlu olsun... herbiri çicek olan bayanlar...', '......  Bayanlar üzerine yazdığım bir yazı... Kadın var, kadıncağız var... Söze nereden başlamak doğru bilmiyorum... En iyisi dünya kadınlar...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kadinlar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller', 'guller-sirma-mersin-s65p7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra! 

Kocamış bir çınarın gövdesine dokunduğumda...

Seneler öncesi! 

Kazıdığım kalbimizin üzerini ellediğimde; 

Adın yankılanıyor, içimde...

O zamanlar! 

Aşkın heyecanı ile; gülen gözlerimizde canlanırdı, hayaller.

Açan gül goncaları bile; 

Sevgimizden alırdı, rengini...

Şimdi ise; 

Güllerin dikenlerini ellerime batırdıkca; kanasa da acımıyor, canım.

Nede olsa! 

Sensizliği kuruttum, yüreğimde...

6.3.04', 'Yıllar sonra!  Kocamış bir çınarın gövdesine dokunduğumda... Seneler öncesi!  Kazıdığım kalbimizin üzerini ellediğimde;  Adın yankılanıyor, ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/guller-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-gokhan-karaduman-r8zed', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel

Bir şubat sabahında

Şu yalnız karanlığıma

Bir güneş gibi doğ gel

Gel

Işığınla uyandır beni

Bakışınla yak tenimi

Beklenmeyen müjde gibi gel

Gel

istersen acı ver

İstersen tak başıma mutluluk tacını

Varsın ecelim ol

Yeterki gel, ne olur gel.

istersen brilikte gidelim ölüme

istersen bileti kes ömrüme

Ama yanımda ol.

Gel ne olur gel.

'' Bir gün geleceksin ama o gün...''', 'Gel Bir şubat sabahında Şu yalnız karanlığıma Bir güneş gibi doğ gel Gel Işığınla uyandır beni Bakışınla yak tenimi Beklenmeyen müjde gibi g...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam hikayeleri 3', 'aksam-hikayeleri-3-kubilay-enginol-i6t79', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstanbul alacakaranlık yine

İleride salaş bir birahane

Gözleri kıpkırmızı kız

Sanki kaymış bir yıldız

Sordu

Sen bira bardağında yüzdünmü hiç

Aşık oldunmu? sevdinmi? 

Kanının her damlasına yazdınmı adını

Ona adadınmı hayatını? 

Öğret bana aşık kız

Sen öğret bana aşkı

Beraber yırtalım,alacakaranlığı

Öyle öğret ki bana

Alacakaranlık dönsün aydınlığa

Gözlerinde yırtıldı karanlıklar

Yer,gök açıldı sanki

Aşk

Ne tarif edilir,ne anlatılır

Yaşanır ve yaşatılır', 'İstanbul alacakaranlık yine İleride salaş bir birahane Gözleri kıpkırmızı kız Sanki kaymış bir yıldız Sordu Sen bira bardağında yüzdünmü hiç...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aksam-hikayeleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımda Sen', 'aklimda-sen-halil-karatas-5yxh1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşıyaka karşımda duruyor,

Gözlerim ise seni arıyor,

Aklımda sen,yanıbaşımda sensizlik,yüreğim yanıyor,

Özlem denizine bir damla yaş daha akıyor.', 'Karşıyaka karşımda duruyor, Gözlerim ise seni arıyor, Aklımda sen,yanıbaşımda sensizlik,yüreğim yanıyor, Özlem denizine bir damla yaş daha a...', ARRAY['Türk Edebiyatı','Şiir','Halil Karataş']::text[], 8.5, '{"poet":"Halil Karataş","poet_slug":"halil-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aklimda-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünlerim Od İçine', 'dunlerim-od-i-cine-gokhan-karaduman-nijsm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsaf kalmamış alemde

İnfaz edildim hanemde

kırık, dökük anılar

Kaldı bak elimde.

Yanıyor yüreğim işte

Acılar vuruyor yine

Anılarım pas içinde

Sevdiklerim el sözünde

Vicdan yokmuş şu dünyada

İnfaz edildim yargısızca

Hak-hukuk varmış ama

Haklılar yok ortalıkta

İnsaf kalmamış alemde

Anam ağladı sevince

İnfaz edildim hanemde

Dünlerim od içinde', 'İnsaf kalmamış alemde İnfaz edildim hanemde kırık, dökük anılar Kaldı bak elimde. Yanıyor yüreğim işte Acılar vuruyor yine Anılarım pas için...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunlerim-od-icine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim', 'seni-sevdim-ozgur-deniz-6xmrn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yarinda seni sevecem

sen hayatimin degisilmezi

seninle cok mutluyum

inan seni olesiye seviyorum

sensiz yasayamayacagimi biliyorum

ve seni kaybetmek istemiyorum

dunde seni sevdim

bugunde seni

yarinda seni seveceyim

sen hayatimin anlamisin 

damarlarimdan dolasan kansin

hayat verenin canimsin

sensiz yasamaktansa

allah canimi alsin

dunde seni sevdim 

bu gunde seni

yarinda seni seveceyim

bir tek sevi sevdim

seni sevdim sevgili', 'yarinda seni sevecem sen hayatimin degisilmezi seninle cok mutluyum inan seni olesiye seviyorum sensiz yasayamayacagimi biliyorum ve seni ka...', ARRAY['Türk Edebiyatı','Şiir','Ozgur Deniz']::text[], 8.5, '{"poet":"Ozgur Deniz","poet_slug":"ozgur-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-sevdim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bir Şey Olmamış Gibi', 'hic-bir-sey-olmamis-gibi-atila-gunal-t071z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben unuttum her şeyi

Aydınlığın karanlığımı çözsün yine

Gel çıkalım göklere

En yükseklere

En baştan başlayalım her şeye

Hiçbir şey olmamış gibi', 'Ben unuttum her şeyi Aydınlığın karanlığımı çözsün yine Gel çıkalım göklere En yükseklere En baştan başlayalım her şeye Hiçbir şey olmamış g...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hic-bir-sey-olmamis-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Zamanlar/dı', 'hangi-zamanlar-di-reyhan-sur-9z0p4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana dokunduğumda 

buz tutardı bedenim çırpıntılarla

kelebekler davet ederdi düğünlerine

tüm üzümleri gözlerinin rengindeydi 

Babil’in Asma Bahçelerinin 

binlerce ateşböceği taşırdın ellerinde 

aklından neler geçerdi 

bal damlardı dilinden dilime 

ah...o ne arsız zamanlardı... 

imdi; 

iğrenç ve siyah tüylü ayaklarıyla 

ağzından dökülen binlerce karadul 

yalnızlığımı kemiriyorsun 

beş komodor ejderi tıslıyor sözlerinde 

hiçbir bakışın 

hiçbir pırıltı taşımıyor 

kara delikler gibi içerilerin 

ürkünç...bir o kadar tenha 

çözülür örgüleri siyah saçlarımın 

da.. son ışık tozları yok olur geceden 

dağ gülleri kokularını gönderir kıbleme 

kimdir o ağlayan tanyerinden 

hangi kızın hıçkırıklarını taşıyor kambur su 

-iki çinli cariye mi kaçıyor saraydan- 

omuzlarında ölümün kakavan dokusu

...

ve on iki kez vuruyorken gonglar

on iki harf sorgular geceyi

“nerde sevgili”

susmanın sırası değil 

artık... düşlerim deliriyor bak 

bir.. söz... söyle 

ya da bir şarkı; 

büyüle umarsız düşüncelerimi 

defolsun kahrolası örümcekler 

terk etsinler bedenimi...

ağulanır belki tüm karıncalar da

işte o zaman/lardır....elbet 

gövden serinletir gövdemi...', 'sana dokunduğumda  buz tutardı bedenim çırpıntılarla kelebekler davet ederdi düğünlerine tüm üzümleri gözlerinin rengindeydi  Babil’in Asma ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hangi-zamanlar-di-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haline Yan', 'haline-yan-atila-gunal-t3r06', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen gidince gün battı da

karanlıklarda mı kalırım sandın.

unuttum güzelim seni

daha mehtap var yaşanacak

sen bir de mehtap da gör beni

neleri bırakıp gittiğini

hiç bilmeyeceksin ya

haline yan duyarsan

14-02-2004', 'sen gidince gün battı da karanlıklarda mı kalırım sandın. unuttum güzelim seni daha mehtap var yaşanacak sen bir de mehtap da gör beni neler...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/haline-yan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-galip-karabatak-cwisk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşkta sınır yoktur sevgili 

aşk kendi başına buyruktur 

aşkta kural, 

yasak, 

tuzak da yoktur... 

aşk yaşanır sevgili 

aşk hiçbirşeyin parçası değildir 

herşey ondan türemiştir 

sadece aşk vardır 

ezelden ebede kadar olan 

geceleri uykunu çalan 

dünyaya başlar kaldıran 

korkutan, 

şaşırtan, 

ağlatan, 

güneşin altında tir tir ttreten 

ve 

buzullarda kavurandır o... 

aşkta kin yoktur 

gurur, 

kibir, 

sen, ben, o yoktur 

sadece aşk vardır orda olan 

yaşanan ve delice yaşatan... 

aşk keyfi değildir sevgili 

yani canın isteyince sevemezsin 

ve aynı şekilde 

canın isteyince unutamazsın 

aşkta acı vardır sevgili 

en saf duygular, 

en içten sözler vardır 

sözlerdir seni ağlatan 

sadece onun dilinden çıkan sözler 

ve aynı şekilde sözlerdir seni güldüren 

sadece onun dilinden çıkan sözler... 

yolları vardır aşkın gidilmeyi bekleyen 

aşkta göze almak vardır sevgili 

anaya, babaya, hayata rağmen göze almak 

cesaret vardır onda 

deli cesareti derler 

onu bir an olsun görebilmek için 

isyan vardır 

başkaldırı, 

gözükaralık... 

eğer istersen herşey olur sevgili 

hele aşıksan olmaz yoktur senin için 

imkansızı yapandır o 

ve herşeyi imkansız kılan... 

aşkta günah yoktur sevgili 

çünkü aşk ruhla yaşanır, bedenle değil 

onda menfaat te yoktur 

karşılıksız sever insan 

sadece sensin diye 

o güzel gözlerin, o tatlı sözlerin hatrına sever 

her aşk büyük bir savaştır 

fetetmek için değil, 

fetolmak için savaşırsın 

ve her aşık kendi başına kahramandır 

çünkü, 

şu koca dünyada bir aşk var, bir de sen varsın 

aşk Hakk tandır sevgili 

odur mecnunu mecnun yapan 

odur insanı yoktan yaratan 

hayata baksan göreceksin elbet 

toprak aşıktır suya 

yaprak aşıktır dala 

damar aşıktır kana 

ve bir şairse aşıktır aşka... 

kısacası aşk, 

benim içimdeki sensin 

ve unutmaki 

beni sevdiğin kadar değil 

benim sevdiğim kadar sevilirsin...', 'aşkta sınır yoktur sevgili  aşk kendi başına buyruktur  aşkta kural,  yasak,  tuzak da yoktur...  aşk yaşanır sevgili  aşk hiçbirşeyin parça...', ARRAY['Türk Edebiyatı','Şiir','Galip Karabatak']::text[], 8.5, '{"poet":"Galip Karabatak","poet_slug":"galip-karabatak","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/ask-218-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönülsüz Düş Gezgini', 'gonulsuz-dus-gezgini-vedat-didari-a4euu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Amy Peacock''a''

Kafesteki serçenin iç acıtan yalnızlığında

Özgürlük düşlerini mavi bulutlar sarar

Kırık düşüncelerinin parmaklıkları ardında

Tutsak yüreği bir bitmemiş sevdayı arar

Çabaladıkça kaçmaya düşsel kafesinden

Bir görünmez teldir boynuna dolanan

Umursamaz sâkinliğinde gizli öfkesinden

Kopan hıçkırıklarıdır gecede kaybolan

Pişmanlığını çoğaltır özüne kızgınlığı

Hatalarına duraksız özürler bulan

Görkemli derbederliğiyle yaşadığı

Bir özgürlüktür yaşamı olmayan

belki de budur neden olan

izin vermesine

zaman zaman

telin boynunu kesmesine', '''Amy Peacock''a'' Kafesteki serçenin iç acıtan yalnızlığında Özgürlük düşlerini mavi bulutlar sarar Kırık düşüncelerinin parmaklıkları ardında...', ARRAY['Türk Edebiyatı','Şiir','Vedat Didari']::text[], 8.5, '{"poet":"Vedat Didari","poet_slug":"vedat-didari","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonulsuz-dus-gezgini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah, bir gelsen şimdi...', 'ah-bir-gelsen-simdi-omer-faruk-girgin-ohhs8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ahh, bir gelsen şimdi,

   Şimdi bir gelsen, girsen kapıdan

,

   Bağıran gözlerini sunsan bana,

   Çeneme dokunup, yüzüne çevirsen yüzümü,

   Mahçup bakışlarımdaki sessizliği anlasan,

   Nerede bugünkü beni besleyen şiirim desen,

   O an sana hiç düşünmeden anlatsam,

   İçimde mevsimsiz açan baharımı; 

   Mor leylak salkımlarımı, gelincik çiçeklerimi, uzun saplı güllerimi

  Kuş cıvıltılarımı, papatyalarımı, 

   Sunabilsem sana içimdeki yaslı ve yaşlı sevdamı.

   Hayallerim bile olsa, bunlar hiç tükenmese,

   Ama yine ne iyi olurdu, gelseydin şimdi,

   Gelsen, girsen kapıdan bağıran gözlerle,

   Ama usulcacık bir sesle, baharı getirdim sana desen....

   Ah. Bir gelsen şimdi,

   Şimdi bir gelsen, girsen kapıdan....', 'Ahh, bir gelsen şimdi,    Şimdi bir gelsen, girsen kapıdan ,    Bağıran gözlerini sunsan bana,    Çeneme dokunup, yüzüne çevirsen yüzümü,   ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ah-bir-gelsen-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapatın Kapıları', 'kapatin-kapilari-oguzkan-bolukbasi-j10ql', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağladığım yere gel

Tutkularımı tutukla

Ne kaldı ki elimde

Daracık sokaklarda sıkıştığım bir akşamı anımsamaktan

Sormaya dilim varmıyor

Ben aynı adam değilim

Aynı şehir değil bu şehir

Sen aynı sözcüklerle sevmiyorsun beni

Şarabın adı başka

Tadı başka

Yakışmıyorum aynalarda gördüğüm adamın sevdalarına

Biraz kendimle kavgalıyım

Hülyalarımı kaybetmişim bir hengâmede

Kimse söylemese de 

Belli ediyorum

Ben uzak bir yerlere gidiyorum

Gelmeyin

Beklemiyorum 

Şehrin kapılarını kapatın', 'Ağladığım yere gel Tutkularımı tutukla Ne kaldı ki elimde Daracık sokaklarda sıkıştığım bir akşamı anımsamaktan Sormaya dilim varmıyor Ben a...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kapatin-kapilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana senin için değil', 'sana-senin-icin-degil-r-ramazan-gali-a1cu3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana seslenemesem de telefonda ruhumda senle görüşür senle sohbet ederim ben.

Beni göremesen de yanında senleyim hep nereye gitsende.

Sana yardım edemesem bile yanındayım hep ne yapsanda.

Uyurken yorganını çekemesem de üstüne yüreğimin sıcağıyla kaplarım, korurum seni 

Gecenin soğukluğundan.

O tokanda saçlarını koklar,

Rujunda dudaklarında dolaşırım ben.

Ağlarken gözyaşındayım içinde yüzerek,

Mutluluğun yada hüznün denizinde bir yunusa benzer.

Sakın düşürme göşyaşını, içinde ben varım,

Düşersem dudağına düşeyim - dilinle sil beni içinde kalayım.

Bileğindeki saat kolları bile seninle tanıştığımızdan beri geçen zamanı gösterir,

Her geçen saniye ile daha da yaklaştırır bizi.

Sokaktaki adama bak, beni görürsün onda, beni andırır o sana, beni düşündürür.

Çünkü benim senin içinde olan, kalbin en derin köşelerinde

Beni saklarsın sen.

Çünkü o kalpte benden olan bir parça var.

Unutma ki,

Kadınlar güzel olduğu için sevilmez,

Kadınlar güzeldir sevildikleri için.

Sen güzelsin bana her halinle,

Gülüşünle,

Bakışınla,

Sesinle,

Soluğunla,

Kokunla.

Sen varsın içimde,

Bir tek sen eksiğimi dolduran

Sana senin için değil,

Eksiğim olduğum için ihtiyacım var,

Ama,

Gerçekler hep acıdır.

Aynı duyguları sen yaşar

Farkına varamadan,

Bana benim için değil,

Eksiğin olduğun için ihtiyacın var.

Ancak,

Bununla yaşayabildiğinde,

Gerçekleri anlar,

Hayatı algılarsın,

Mutluluğun sırrını bil,

Kendini bul gerçeklerde,

Doğrular ayrıdır,

Gerçekler aynı.

Onlara bakıp doğruyu seçme,

Onları bilip doğruyu hisset.

Yaşa,

Zira anlamak yetmez bu dünyada,

Yaşamak algılamaktır.', 'Sana seslenemesem de telefonda ruhumda senle görüşür senle sohbet ederim ben. Beni göremesen de yanında senleyim hep nereye gitsende. Sana y...', ARRAY['Türk Edebiyatı','Şiir','R Ramazan Gali']::text[], 8.5, '{"poet":"R Ramazan Gali","poet_slug":"r-ramazan-gali","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sana-senin-icin-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatma Kaşlarını', 'catma-kaslarini-tunahan-ermihan-4jc89', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül sevdiğim, güller arasından hayata

Gül ki bülbülün boynu bükük kalmasın

Ve kavuşsun o sevdiği gülüne gülüşünle

Gül ki sevgi olsun adın sevdiğim

Yum gözlerini, tüm kötülüklere

Görme sen pamuk prensesi zehirleyen cadıyı

Ve hiç yatma o camdan tabutun içine

Yum gözlerini ki masal olmasın hiçbir şey

Çöz saçlarını, yağmurlar boşalsın

Gören gök delindi sansın

Topraklarım sevdanla sulansın son kez

Çöz saçlarını ki hasadımı toplayasın

Çatma kaşlarını, yıldırımlar çakmasın

Hasretinle batacaksa gün hiç doğmasın

Ve adına şiir yazmayan şairin kalemi kırılsın

Çatma kaşlarını ki ilhamım senden gelsin', 'Gül sevdiğim, güller arasından hayata Gül ki bülbülün boynu bükük kalmasın Ve kavuşsun o sevdiği gülüne gülüşünle Gül ki sevgi olsun adın se...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/catma-kaslarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutla Beni', 'kutla-beni-tunahan-ermihan-1hx0p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kutla beni sevdiğim

Seni hasretler arasında sevmeyi de öğrendim

Hayaller ötesinden sesleniyorum sana bu akşam

Büyük ihtimalle bu son nefesim

Ve bunu da senin için feda edeceğim

Sonra gözlerimi hasretine kapatıp

Sevdamın gözlerimden sessiz bir damla ile

Sonsuza akmasına seyirci kalacağım

Ne olursa olsun sonunda bu ömrü

Seni severek tamamlayacağım

Her ne kadar kavuşamasam da

Hasretini yaşamakta güzeldi

Keşke kavuşabilseydim', 'Kutla beni sevdiğim Seni hasretler arasında sevmeyi de öğrendim Hayaller ötesinden sesleniyorum sana bu akşam Büyük ihtimalle bu son nefesim...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kutla-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğulu Gözlü', 'bugulu-gozlu-tunahan-ermihan-qdxlu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanaklarından süzülen gözyaşımı yoksa

Hayatın bilinmeyen acıları mı

Düne kadar tanımadığım

Bu gün ise kıymete binen arkadaşım

ikinci sınıf bir albümde solmaya yüz tutmuş

Maziden gelen imkansız davetlerin sızısımı

Yoksa yaşanacak güzel veya çirkin anların heyecanımı

Ne olursa olsun saçların gibi yolun da hep dümdüz olsun

Gözlerinden gülücükten başka hiçbir şey süzülmesin

Ve eğer ağlayacaksan sadece mutluluktan ağla

Buğulu gözlü kanatları rengarenk kelebek', 'Yanaklarından süzülen gözyaşımı yoksa Hayatın bilinmeyen acıları mı Düne kadar tanımadığım Bu gün ise kıymete binen arkadaşım ikinci sınıf b...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bugulu-gozlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanadım Sensiz', 'kanadim-sensiz-tunahan-ermihan-z3jk0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana olan sevdamdır sebebim

Sende bilirsin sevdiğim

Kimi gün gözlerimden süzüldü

Bir yıldız gökten süzülür gibi

Bazı gün tebessüm oldu dudaklarımda

Sıcacık öpüşün gibi

Hep bir huzur bastı yüreğimi ellerimi tuttuğunda

Ama çok kanadım sensiz kör kuyularda

Çocuk derdin delikanlı oldum hasretinle

Sana olan sevdamdır sebebim

Kimi gün gözlerimden süzülen

Kimi gün dudaklarımdan dökülen

Ama hep senli hep senle', 'Sana olan sevdamdır sebebim Sende bilirsin sevdiğim Kimi gün gözlerimden süzüldü Bir yıldız gökten süzülür gibi Bazı gün tebessüm oldu dudak...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kanadim-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-tunahan-ermihan-xgmyz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulutlarım yağmur yüklü bu akşam

Serseri gecelerime hoş geldin

Nemlidir gözlerim aldırma sen

Bir köşe seç kendine ve otur

Birden derin nefes alma

Önce havadaki hasretin ağırlığına alış

İstersen sana bir şeyler ikram edeyim

Tozunu almayı unuttuğum hayal kırıklarımın arasından

Kırılmış hayaller şarap gibidir biliyor musun

Yıllandıkça önem kazanır

Yılını sen seç

Ne kadar eski olursa o kadar makbuldür derler

Ama boş ver, sen en iyisi pencereden dışarı bak

Benim penceremden hep yağmur yağar

Ah… pardon daha tanışmadık değil mi 

Gerçi ben yenide olsa tanıyorum seni

Yüreğini tutabiliyorum bazen ellerimle

Ve gözlerinden geçeni yakalayabiliyorum bazen

Neyse senin adın gelincik olsun

Bende Sonbahar', 'Bulutlarım yağmur yüklü bu akşam Serseri gecelerime hoş geldin Nemlidir gözlerim aldırma sen Bir köşe seç kendine ve otur Birden derin nefes...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hosgeldin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorsun', 'biliyorsun-tunahan-ermihan-6fl8d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazı gün ağladığımı biliyorsun sevdiğim kasım yağmurları misali

Ve sana aşık olduğumu biliyorsun

En kurak günümde içimi sana açtığımı

Ve senden ne olursa olsun nefret edemediğimi

Vazgeçemediğimi biliyorsun

Tüm kalelerimi savaşmadan teslim ettiğim tek kumandan olduğunu

Ve sancağını taşırken ölmek için can attığımı biliyorsun

Gözlerimden her zaman sana karşı aşk süzüldüğünü

Ve kalbimin senle attığını biliyorsun

Her ayrılıkta canımın ne kadar yandığını

Ve sana her seferinde ne kadar kanadığımı biliyorsun

Sevdiğim

Hepsi bir tarafa

Seni ne kadar sevdiğimi

Çok iyi biliyorsun', 'Bazı gün ağladığımı biliyorsun sevdiğim kasım yağmurları misali Ve sana aşık olduğumu biliyorsun En kurak günümde içimi sana açtığımı Ve sen...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biliyorsun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-tunahan-ermihan-0r4s0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mecbur bu veda anla sevdiğim

İçimden geçenler senle dolu

Kinimde, sevincimde, hüznümde

Mecbur bu veda anla sevdiğim

Belki bir gün bir yerde bile diyemem artık sana

Ve ellerini tutmadan nasıl yaşarım bilemem

Belki umut göçer hayatımdan belki gülüşüm

Ama anla sevdiğim mecbur bu veda

Bir borcum vardı sana hatırlarsın

Satır aralarına sakladığım ve senin bildiğin

Ömür boyu diye başlayan bir borç, ödeyemedim affet

Ve anla sevdiğim mecbur bu veda

Sana hep derdim ya başka kimliğin olamaz diye

Hayat savursa da bilinmeyen uçurumlara

Evet sevdiğim başka kimliğin olamaz

Bu veda mecburi olsa da

Seni severek geçirilen her ana

Yaşanılan her şeye

Gözlerimden uçacak olsa da verdiğin umuda

Hayatıma kattığın her renge teşekkür ederim sevdiğim

Beni affet mecbur bu veda', 'Mecbur bu veda anla sevdiğim İçimden geçenler senle dolu Kinimde, sevincimde, hüznümde Mecbur bu veda anla sevdiğim Belki bir gün bir yerde ...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/veda-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kibrit Yaksana', 'bir-kibrit-yaksana-tunahan-ermihan-vv4my', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz saatlerin darlığında çok düşündüm

Ve çok vurdum kafamı hatıralara

Dönmek mi istediğim mutluluğa

Yoksa kalmak mı genelin huzuru benim huzursuzluğumda

Varılacak sonuçlar arasında her daim

Yoruldum, hırpalandım, parçalandım

Sonra koptum hayattan ve düşünceden

Anlar zaman zaman sonsuzluk oldu

Zaman zamanda sonsuzluk an

Kendime gelmeye çalıştım gerçekten korktum

Ben bu muydum yoksa

Bu olmaktan korktum

Kalemler kırdım kendim için

Celladım olacak hatıra bulamadım

Ve sonuçta anladım ki

Ne seninle ne de sensiz

Hayat denilen zalimin zulmünde

Bir ömür geçirmeye mahkummuşum

Şimdi benim istediğim

İstemediğim mi olmalı yoksa istediğim mi beni istemeli

Veya kelime oyunlarıyla bastırılacak acılara

Kardeş mi olmalıyım tekrar

Severken böyle bitemez derdim

Bitmesini de hiç istemedim

Olmaktan korktuğum kişi olmak istemiyorum

İstemediğim hayatlarda hüküm sürmek istemiyorum

Bu oyunu yalnız oynamak istemiyorum

Birileri bir kibrit yaksın

Düşünceler arasında kaybolup 

Işıksız kalmaktan korkuyorum artık', 'Sensiz saatlerin darlığında çok düşündüm Ve çok vurdum kafamı hatıralara Dönmek mi istediğim mutluluğa Yoksa kalmak mı genelin huzuru benim ...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-kibrit-yaksana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtınalı Çağrı', 'firtinali-cagri-tunahan-ermihan-dk09u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlem ve vedaların gelgiti yıllardır yaşadığımız seninle

Eğer biz birer gemiysek

Hep fırtınalara yelken açtık seninle

Oysa o kadar toydu ki kaptanlığımız

Değil fırtınayı büyük bir dalgayı bile atlatamazdık

Tabi ki büyük yaralar alırdık

Sonra sen liman olurdun ben sende dinlenir tamir olur

Sonra rolleri değişirdik

Ve sen bırakırdın kendini ellerime

Şimdi yine fırtınalı deniz ve hava buz gibi

İçim kaynıyor yüreğim yerinden çıkacakmış gibi atıyor

Sanırım deniz bizi çağırıyor

El ele yürek yüreğe

Bizde sevda hep acıya mahkum oldu

Ama hep sevdalısı olduk birbirimizin

Şimdi söylesene

Gel desem gelir misin

Yaralanmaya kanamaya sevdaya', 'Özlem ve vedaların gelgiti yıllardır yaşadığımız seninle Eğer biz birer gemiysek Hep fırtınalara yelken açtık seninle Oysa o kadar toydu ki ...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/firtinali-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Satırları', 'huzun-satirlari-tunahan-ermihan-2bdts', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben acıları seçmişim kendime yar diye

Adını bilmediğim ülkelerde

Ve konuşmasını bilmediğim dillerde

Yakıştırmışım kendime gözyaşını

Şimdi şikayet etsem halimden ne fayda

Veya ne suçu var acının kederin gözyaşının

Yolu önüme koyan hayat

Seçimi yapan benim

Şimdi ben gözyaşı döksem

Gözümden süzülen yıllarım için ne fayda

Her günü acıyla dolmuş bir ömrün ardından ağlasam ne fayda

Bunlar senle alakalı değil sevgili alınma sakın

Bunlar hüznün satırları ve gözyaşının

Sen bunlardan münezzehsin

Ve en mükemmeli kırsan da acıtsan da bazen

Sen sevdiğimsin

Bunlar hüznün satırları ve gözyaşının', 'Ben acıları seçmişim kendime yar diye Adını bilmediğim ülkelerde Ve konuşmasını bilmediğim dillerde Yakıştırmışım kendime gözyaşını Şimdi şi...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzun-satirlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl Çiçeği', 'col-cicegi-tunahan-ermihan-ibmos', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerindi ulaşmak istediğim

Ve gözlerindi sonumun başlangıcı

Bir şiir yazdım sana önce

Sonra aşık oldum hasretine

İsimler taktım sana çiçek  kokulu

Ormanlarıma düştü yangının önce

Yanmayı öğrendim sönmek için

Bir damla öpüşün harladı yangınımı

Ben söndükçe sen yaktın

Sen yaktıkça ben yandım

Ve en son mis kokulu sevdanla kaldım baş başa

Ne orman var artık

Ne de içinde yaşayan

Bir sevdan bir ben (çöl çiçeği kaktüs) 

Şimdi sana ne isim takayım sevdiğim

Sen baharsın ılık mevsim yeni başlangıç

En iyisi senin adın yine bahar kalsın

Çöl çiçeğinin BAHARI', 'Ellerindi ulaşmak istediğim Ve gözlerindi sonumun başlangıcı Bir şiir yazdım sana önce Sonra aşık oldum hasretine İsimler taktım sana çiçek ...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/col-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yinede', 'yinede-i-brahim-saritas-bygp6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güvercinler konar çatıma 

Gökyüzü  gülümser bana 

Rüzgarlar taşırdı hislerimi yürekten

Özlemiyle yanılan yüreklere

Anlaşılmadığım insanlara

Kara kara bulutlarıyla

Sonbahar yapraklarıyla 

Çoktan dökülmüş olurdu hüznüm

Baharda çiçeklerle açılırdı

Ve bir daha da üzülmezdi gönlüm

Bir bilinseydim

Bilinseydi neyi ne kadar sevdiğim

Kim için kimler için ne fedakarlık yapmışım

Yüreğimin derinliklerinden gelirdi

En yüklü halleriyle yaşam sevinci

Yaşama bağlanma sevinci..

Kışın bembeyaz kefenini örtmesini istediğimde

PAYLAŞMANIN ve BAĞLANMANIN sevinciyle

Göz yaşlarıyla uğurlarken sevdiklerim beni

Yürekten gülümsemelerle terk ederim hayatı 

CAN olmasa da benden yana

Kapatırım gözlerimi 

Duygularımı boğan hayata

Elin ipi olsa da boğazımda 

Ferman elin olsada

Yüreğimdekiler yeter bana

Yalanda yaşatamadıklarımı 

Yaşatırım en tatlı uykularımı bölüp hayallerimde 

Yaşatırım ay ışığı yapıp karanlık gecelerimde

Yüreğimdekiler yeter bana

Beklediğim bu son yolculuğumda

En tatlı gülümsemelerimle 

Yalan dünyaya inat 

Terk ederim hayatı

Yeter ki belirtilsin

Terk ederim istenilmediğim yeri

Terk ederim istenilmediğim insanları

Terk ederim yalanı, ayrılıkları

Yinede..

PAYLAŞMANIN ve BAĞLANMANIN sevinciyle…', 'Güvercinler konar çatıma  Gökyüzü  gülümser bana  Rüzgarlar taşırdı hislerimi yürekten Özlemiyle yanılan yüreklere Anlaşılmadığım insanlara ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sarıtaş']::text[], 8.5, '{"poet":"İbrahim Sarıtaş","poet_slug":"i-brahim-saritas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yinede-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün Bende Kalsın', 'gulusun-bende-kalsin-deger-ulas-turan-ub974', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülmek istedim çünkü içimde sen varsın 

Çıkarmadım gülüşünü yüzümden 

Çok istedim hep bende kalsın 

Yüzümü kirlettim, acımı bilmeden. 

Bu çocuk ağlamayı öğrendi neden, 

Kendini aradı başka gülüşlerden 

Gülerken gönlünde bir seni, 

Güllerini aradı sahte gönüllerden 

Bir zaman geldi gülüşünü almaya 

İstedi yüzümü dökeyim, 

Canımı yakıp, yüzüme bir maske takayım 

Başladı ağlamaya, gülen maskenin ardından. 

Gülüşün bende kalsın, 

Bende olsun hasretinle 

Aynalarda seninle kalayım 

Gülüşün bende ağlasın. 

Yanakların kızarır gülerken, 

Güller daha kırmızı olur 

Sonra baharın gülüşünde açar 

Gülüşün, döküp yapraklarını solar. 

Baharın bende kalsın, 

gönlümde sen hep baharsın 

bu seferde götürme gülüşünü, 

yorgunum başka baharlara, bırak bende kalsın. 

Gözlerin aydınlık şimdi, 

Gökyüzü dökülüyor üstüme 

Gök senin gözlerin, 

Göğümü alıp götürme. 

Dudakların nasılda kırmızı, 

Bir gülüş mü yapar bunu 

Baharın en taze meyvesi dudakların 

Koparma kirazlarımı. 

Ve anlayacağın alıp götürme benden seni, 

Affet bu baharsız gönlümü. 

Maskeler olmasın, 

Gülüşler solmasın... 

Gülüşün bende, 

Ellerim ellerinde, 

Gönlüm gülüşünde; 

Kalsın diye diliyorum tüm gönlümce... 

Bahar affeder yaban otlarını; sende affet bu yabanı; 

Öğrenir elbet gül olmayı, 

Ya da bir kardelen misali tutunur toprağa 

Ve gülüşündeki o bahara... 

Yıkanır yağmurlarında, kalmaz korkuların. 

Ve sen canımın içi, bahar gülüşlüm 

Hep ‘gülümse’ 

GÜLÜMSÜN ÖMRÜME AÇAN...', 'Gülmek istedim çünkü içimde sen varsın  Çıkarmadım gülüşünü yüzümden  Çok istedim hep bende kalsın  Yüzümü kirlettim, acımı bilmeden.  Bu ço...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gulusun-bende-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Türkü', 'son-turku-cihan-uluisik-zlzct', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahar yeli yağız 

Bahar yeli hafif anam! 

Bir esinti çeker

Otuz yaş öncesi 

Bu sefer öyle değil 

Kuzgunun  türküsü

İnce bir sızı

Bağrında kaygısı

Ortağız hüzünlü nağmene

Ey ney

Hey ney hey! 

Sen bilirsin bu derdi bir

Bir de dost elinde

Kan ısıtan sıcak yarenlik

Gama döner

Söz yetmez

Mahşerin atlısı çalar

Mızrabın hayat aşkını', 'Bahar yeli yağız  Bahar yeli hafif anam!  Bir esinti çeker Otuz yaş öncesi  Bu sefer öyle değil  Kuzgunun  türküsü İnce bir sızı Bağrında ka...', ARRAY['Türk Edebiyatı','Şiir','Cihan Uluışık']::text[], 8.5, '{"poet":"Cihan Uluışık","poet_slug":"cihan-uluisik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-turku-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlacım Sensin', 'i-lacim-sensin-ozan-rari-614wl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle alışmıştım ki sana 

 Şu an da benim için sensizlik

 Hayatımda yaşayacağım en büyük bir felaket gibi bişey

 Halimi bir düşün 

 Şu an yine sensizim bu soğuk odam da

 Mutlu olmam mümkün değil senden ayrı

 Şimdi yanımda da yoksun derdim bitmez benim

 Her zaman seninle dolu olan gündüzüm gecem

 Şimdi bomboş

 Sen benim dünyamı doldurmuştun yanımdayken

 Kısa bir sürede olsa nasıl alışacağım sensizliğe

 Alışamıyorum,yapamıyorum sensiz

 Bir gelsen,bir sarsam seni,bir insem gözlerinin en derinine 

 O zaman bütün mutluluklar benim olur

 Öyle çok özledim ki seni Ruhum! 

 İlacımda sensin doktorumda sen...

 (EŞ RUHUM''A...NESLİHAN)', 'Öyle alışmıştım ki sana   Şu an da benim için sensizlik  Hayatımda yaşayacağım en büyük bir felaket gibi bişey  Halimi bir düşün   Şu an yin...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ilacim-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komşuluk Hali', 'komsuluk-hali-bekir-mutlu-gokcesu-t1t1a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir maniniz yoksa

5 dakika gelebilir miyim? 

Bizde mana bitmiş

Bir fincan alabilir miyim? 

Deseydin ya, lafı mı olurdu? 

Tüm manileri 

Kaldırmaz mıydım aradan? 

Karınca kararınca

Ne kadar mana varsa

Sana yağdırmaz mıydım buradan?', 'Bir maniniz yoksa 5 dakika gelebilir miyim?  Bizde mana bitmiş Bir fincan alabilir miyim?  Deseydin ya, lafı mı olurdu?  Tüm manileri  Kaldı...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/komsuluk-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim', 'hasretim-ozan-rari-gofez', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En zorudur sevgili özlemi

Yanında olmasını istersin ama yoktur

Onun da elinde değildir hiç birşey

Benimkisi de böyle bir hasret işte

Zaman geçsin diyorum

Lanet olasıca zaman da geçmek bilmiyor

Sabredeyim diyorum sabırla olacak bişey değil

Özlüyorum alışamıyorum yokluğuna

Geçici bir ayrılık ama

Onsuz bir gün bana bir yıl gibi geliyor

Bazen herkes konuşuyor boş boş

'' Az kaldı,dayan'' diye.

Ama birde bize sorsunlar

Nasıl geçiyor zaman bir sorsunlar

Öyle çaresizim ki şuan

Gecenin bu saati oldu gözüme hiç uyku girmedi

Niye mi? 

Cevabı kolay; 

Sevdiğim yok,

Aşkım yok,

Ruhum yok,

Kısacası mutluluğum,huzurum yok...

(Serdarım''a...Neslihan)', 'En zorudur sevgili özlemi Yanında olmasını istersin ama yoktur Onun da elinde değildir hiç birşey Benimkisi de böyle bir hasret işte Zaman g...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hasretim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorum', 'agliyorum-sair-errool-sfys1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün gece rüzgar eserken

Gökyüzüne bakıyordum. 

Yıldızlarda seni ararken 

Rüzgar seni fısıldıyordu. 

Kokunu alıp gelmişti bana 

Seni duyuyor 

Seni içime çekiyordum. 

Ruhumu yakıyordun 

Her nefes çekişimde. 

Gözümden süzülen yaş değildi 

Sen akıyordun. 

Dayanamıyorum artık 

Her gece her an 

Yakıyor hasretin 

Özlüyorum seni bebeğim. 

Biliyorum dönmeyeceksin 

Ama elimden bir şey gelmiyor 

Ne yapayım ben böyleyim işte

Sadece ağlıyorum 

ağlıyorum...', 'Dün gece rüzgar eserken Gökyüzüne bakıyordum.  Yıldızlarda seni ararken  Rüzgar seni fısıldıyordu.  Kokunu alıp gelmişti bana  Seni duyuyor ...', ARRAY['Türk Edebiyatı','Şiir','Şair Errool']::text[], 8.5, '{"poet":"Şair Errool","poet_slug":"sair-errool","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/agliyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızdır Bozkır Kurtları', 'yalnizdir-bozkir-kurtlari-nal-n-yildiz-vwagy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O ben değilim yani var olduğunu sandığın, aşık olmayı umduğun kişi. Beni tanıdığın doğru çünkü sana benziyorum, hem de çok...Bozkır kurtlarının birbirine benzediği kadar hem de... Ama yine de o ben değilim. Yani farzettiğin kişi. Bunu ben biliyorum sen de bil e mi? 

Niye mi bilmen gerekiyor? 

Kiraz ağaçlarının çiçek açtığı mevsimdi, 17 yaşındaydım ve ilk defa aşık oldum. 34 yaşındayım, mevsimler değişti ama ben hâlâ aynı adama aşığım çünkü... Adam değişmedi mi sanki? Hem de çok değişti ama aynı adamda başka sevgililer başka sevecek şeyler bulup yine ona aşık ettim kendimi sabit fikir olur da sabit duygu olmaz mı? Ben bu ömrümde bir tek kişiyi sevdim ve onu severek öleceğim. Telefonunun açılış mesajında, ''ömrüm seni sevmekle...'' yazıyor ve o güne her başladığında, gece kafasını her yastığa koyduğunda hatta telefonunu her açtığında bu şarkıyı onun için mırıldadığımı biliyor. 

İşte özeti niye ben olmadığımın zannettiğin kişi...

Sen de böyle bir aşkı hakkediyorsun yani ölümüne ve ölünceye kadar sevilmeyi ama ben bu hakkımı başkasında kullandım.

Bozkır kurtları yalnızdırlar haklısın. Çünkü karşılaştıklarında hep zaman yanlıştır. Biri giderken biri gelmiştir bazen de tek bulduğu ayak izidir diğerinin. Sakın bana darılma sevgili dost. Sana verebileceğim dostluğumu, arkadaşlığımı kabul edersen, seninle daha tanışmadan yerin hazırdı. Gel otur. Ama ötesi benim elimde değil üzgünüm. Gel görüşelim, gel konuşalım, gel helalleşelim gel aziz dost ama bunları bilerek gel. Peşin peşin özrümü diledim kırmışsam affola. Ama kurt kardeş sende halden anlamazsan kime anlatayım derdimi?', 'O ben değilim yani var olduğunu sandığın, aşık olmayı umduğun kişi. Beni tanıdığın doğru çünkü sana benziyorum, hem de çok...Bozkır kurtları...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizdir-bozkir-kurtlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcaklığımı', 'sicakligimi-murat-berk-rj33v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim sıcaklığımı; 

Ne itfaiyeler, 

Ne yangın  tüpleri 

Ve hatta 

Aysbergler bile söndüremezler.

İtfaiyeler, 

Yangın tüpleri bozulur,

Aysbergler erir, 

Ben yine de sönmem, 

Alev alev yanarım.

Bana yürek gerek, 

Bana gönül gerek,

İşte bunlar 

Beni söndürecek...', 'Benim sıcaklığımı;  Ne itfaiyeler,  Ne yangın  tüpleri  Ve hatta  Aysbergler bile söndüremezler. İtfaiyeler,  Yangın tüpleri bozulur, Aysber...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sicakligimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öteden Haber Gibi', 'oteden-haber-gibi-halil-i-brahim-ozdemir-wxe3v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaktan uzağa şakırdayan su,

	Bize ötelerden haberler verir.

	Toprakta çatlayan tohum kokusu

	Bahardan sımsıcak selam getirir.', 'Uzaktan uzağa şakırdayan su, 	Bize ötelerden haberler verir. 	Toprakta çatlayan tohum kokusu 	Bahardan sımsıcak selam getirir....', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/oteden-haber-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Akşamlar Ah', 'ah-aksamlar-ah-bekir-mutlu-gokcesu-qsfy9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Harika bir akşam

günler sonra.

Şimdi uzak telaşlar.

Tek bir kıpırtı yok,

öyle sakin ki ağaçlar.

Ah gözünü sevdiğim,

gecesine sardığım,

sabahını özlediğim

çakır keyif akşamlar.

Heybemde az güneş,

ıslattığım saçlarımda

Nisan yağmuru hazzı.

Gevşettiğim kravatımda

numunelik sallanır

günün umursamazlığı.

Bir de açınca

en üstten iki düğmeyi

mintanımın içinden

koynuma girmez mi

bahar havası.

Ah akşamlar ah...

Şimdi 

yeniden doğmam mı? 

yazmam mı ben aşkı?', 'Harika bir akşam günler sonra. Şimdi uzak telaşlar. Tek bir kıpırtı yok, öyle sakin ki ağaçlar. Ah gözünü sevdiğim, gecesine sardığım, sabah...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ah-aksamlar-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanlar ve Ezanlar', 'canlar-ve-ezanlar-ugur-oguz-sahin-ixblv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorgunum dostlar yorgunum canlar

Bir tarafımda çaldı durmadan çanlar

Diğer yanımda beş vakit okunan ezanlar

Çoktan geldi geçti otuz beşli yaşlar

Artık buruk doğuyor ruhumu okşayan sabahlar

Değişti hep doğduğum o eski sokaklar

Artık yok ahşap evler yıkıldı cumbalar

Çoçukluğum gençliğim de tarihe mal oluyor

Dostlar her şey elimizden bir bir uçup gidiyor

Yorgunum gözlerimde uçuşuyor siyahlar

Eskisi gibi bedeni taşımıyor ayaklar

Minare tepelerinde secde de hâlâ rüzgârlar

Patrikhaneyle Yavuz Selim camisi yıllardır bakışırlar

Rize nüfusunda kayıtlı Fatih Küçük Mustafa Paşa''da

Cibali karakol sokağında eski bir kare

Patrikhane altı Fener''de Köprü başında Balat''ta

Tarih içimde ben tarihin içinde yaşıyan idim

Bir avuç mutluluğum aşklarım hüzünlerim

Eyvah eyvah gençliğim

İlham kaynağım Altın boynuzum doyumsuzum

İyotunu soluduğum mavisinde kulaç attığım balık tuttuğum

Yakamozlarını seyredip hayallerimi ürettiğim

Grileşti maviler soldu umutlar yandı gemiler

Artık yorgunum yorgunum dostlar yorgunum hatıralar

Sarı sayfalarda geride kalanlar yarım yaşanmış yıllar

Bir bir ayrılıyor aramızdan canlar o eski dostlar

Birinde son yolculukta çalar çanlar diğerinde de okunur selalar', 'Yorgunum dostlar yorgunum canlar Bir tarafımda çaldı durmadan çanlar Diğer yanımda beş vakit okunan ezanlar Çoktan geldi geçti otuz beşli ya...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/canlar-ve-ezanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Tenceresi', 'umut-tenceresi-ugur-oguz-sahin-lyjch', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duy sesimi haykırışlarımı

Gel paylaş bitir yalnızlıklarımı

Unuttur kötü yazgımı yaşattıklarını

Güldür yüzümü düzelt çatık kaşlarımı

Eskisi gibi yine birlikte söyleyelim şarkımızı

Gel duvarlara tekrar yazalım adımızı

Bir kalp sen çiz bir kalp ben

İçine batıralım yine aşk oklarımızı

Kaldırdılar o eski sokak lambalarını

Hatırla kâr saydığımız karanlıkları

Unutmak ne mümkün o ateşli sarılışları

Ne güzel ıslatırdı bizi o yağmur damlaları

O deli rüzgâr eskisi gibi yine esse

Saçılsa o güzel saçların her tarafıma

Hayal hep hayal kuruyorum biliyorum

En çok o güzel gözlerini özlüyorum

Kimselere açmadım gönül evimi

Bir gün gelirsin diye bekliyorum

Veremedim ellere sevgimi

Hâlâ senden vaz geçemiyorum

Sebebi ne onu da bilmiyorum

Umut tenceresini hâlâ kaynatıyorum', 'Duy sesimi haykırışlarımı Gel paylaş bitir yalnızlıklarımı Unuttur kötü yazgımı yaşattıklarını Güldür yüzümü düzelt çatık kaşlarımı Eskisi g...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/umut-tenceresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile Çöllerinde', 'cile-collerinde-ugur-oguz-sahin-t8sgn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben çile çöllerinde yürüyorum

Hissetmem susuzluğu beklemem yağmuru

Toz bulutları örter hayallerimi durmadan

Ağlar halime kum fırtınaları

Yitirmiş tüm hissettiklerini ruhum

Nerede hayatın kristalindeki gök kuşağı

Ey bana sırtını dönmüş mutluluğum

Mutsuzluklar karşımda bir sıra dağı

Bakma gözlerime beni tanıyamazsın

Her tarafımdan akar hayatın kumları

O eski beni bende bulamazsın

Aldı götürdü onları çöl rüzgârları

Biter mi umutsuzluğum biter mi çöl yalnızlıkları

Nereden çıkacak birileri yaksın içimdeki ışıkları

Bir beyaz güvercin beklerim haber getirsin

Geri versinler bana yaşatmadıkları yılları', 'Ben çile çöllerinde yürüyorum Hissetmem susuzluğu beklemem yağmuru Toz bulutları örter hayallerimi durmadan Ağlar halime kum fırtınaları Yit...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cile-collerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun Adı Hayriye', 'onun-adi-hayriye-ugur-oguz-sahin-pmcg7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onun adı hayriye

Allahım güzellik vermiş

Doyasıya seyret diye

Gizli bir yara açıyor gönülde

Ne de güzel durmuş

Yüz hatları tesettürde

Sanki berrak durgun bir göl

Fırtınalar koparır içinde

İster yaşa ister öl

Onun adı hayriye

Boyu benziyor selviye

Böyle güzeli zamansız

Karşıma çıkarır

Mevlam ne diye

Onun adı hayriye

O layık her türlü sevgiye

Layık her türlü övgüye

Yüzünden eksilmesin hiç nurlar

Yaradan korusun bu güzelliği

Yaşatsın onu tüm mutluluklar', 'Onun adı hayriye Allahım güzellik vermiş Doyasıya seyret diye Gizli bir yara açıyor gönülde Ne de güzel durmuş Yüz hatları tesettürde Sanki ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/onun-adi-hayriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aborda Sevda', 'aborda-sevda-sezgin-ondersever-x296j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senden bahsetmek şiirlerce...

Şimdiki kadar yalın olmayacaksın,

Hiçbir şiirimde..

Limanın olması bile yetmiyordu yüreğindeki gemiye.

Yanaşamıyordun aşkın kıyılarına.

Hep aborda yapıyordun utanmadan.

Ne zaman bir gemi yanaşsa limanıma; 

Bir ikinci gemi sen oluyordun,

Birinciye aldırmadan.

Yolcular iniyordu içinden, üzerimden geçerek.

Adımımı atmadan güvertene, ayrılıyordun limanımdan.

Ayrılmak ve terk etmek sana çok yakışıyordu.

Sonra yapayalnız bir liman kalıyordu geride.

Sen gelince yalnız hissediyordum kendimi.

Ama gidince yapayalnız oluyordum sanki.

Şehirler dolaşıyor, hatıralar biriktiriyordun.

Düşünmüyordun geride bıraktıklarını.

Sözünde durmayan bir yemin gibiydin.

Güneşi olmayan bir dağdın belki.

Ya da hepsinden de beter,

Gemisi olan limanlara aborda yapan bir gemiydin.

Yüreğimde tek sen vardın o zamanlar.

Sen benden uzaklaştıkça bana yaklaşıyordun.

Ne zaman bir deniz feneri görsen uzaklarda,

Rotanı karanlıklara çevirip sonsuzluğa kaçıyordun.

Gemilerin de bir ruhu vardır derler.

Ruhunu uçsuz bucaksız korkulara teslim ediyordun.

Seni bekleyen yüreğimin ardından,

Kim bilir ne dümenler çeviriyordun.

Öylece geziniyordun okyanuslar ortasında.

Sonra kendi kendine yarattığın o girdapta,

Hem beni, hem kendini batırıyordun.

Artık indirebilirdin sancaklarını yarıya.

Aborda sevdalardır yüreklerdeki limanları tutuşturan.

Tutuşan terk edenden daha mesuttur bilinmez.

Her insanın içinde böyle bir aşk vardır... kanatılan.

Lakin kanadıkça kabuk bağlar sevgili yaraları.

Sen, aborda yapan korsan gemisi... kara göründü... kara göründü...

Ben, hüzünlü bir şiir neşteri... yara göründü... yara göründü...', 'Senden bahsetmek şiirlerce... Şimdiki kadar yalın olmayacaksın, Hiçbir şiirimde.. Limanın olması bile yetmiyordu yüreğindeki gemiye. Yanaşam...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Öndersever']::text[], 8.5, '{"poet":"Sezgin Öndersever","poet_slug":"sezgin-ondersever","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/aborda-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Hastalıktır', 'ayrilik-hastaliktir-sezgin-ondersever-qjdg2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu ayrılık denilen şey hastalık değil midir? 

Kiminin beyninde büyüyen bir tümördür sevgili.

Kiminin ağzında kanar tüm söyledikleri.

Şu ayrılık, tıpkı şu hastalık dedikleri.

Yüreğin sıkışır, çünkü anılardan yer kalmamıştır.

Yaşama isteğin acılar tarafından reddedilmiştir.

Hangi sonsuz aşkın vadesi dolmamıştır.

Ne fayda, kalan kalmış, giden gitmiştir.

Şu ayrılık dedikleri, belki de bir ölüm meleğidir.

Nefes aldırır yaşatmaz, süründürür öldürmez.

Beklemiyorum, biliyorum ki, gidenler geri dönmez.

Şu ayrılık, dünyada terk edilenlerin, dünyayı terk edişleridir.', 'Şu ayrılık denilen şey hastalık değil midir?  Kiminin beyninde büyüyen bir tümördür sevgili. Kiminin ağzında kanar tüm söyledikleri. Şu ayrı...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Öndersever']::text[], 8.5, '{"poet":"Sezgin Öndersever","poet_slug":"sezgin-ondersever","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrilik-hastaliktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Kadınların Şehrindeki Çirkin Adam', 'guzel-kadinlarin-sehrindeki-cirkin-adam-atakan-aktas-xpjbs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güzel şehirlerin güzel kadınları 

şehrinde sürme gözler 

kadınları çiçek bahçesi 

şehirlerin kalbi sıcak 

sütunları arzulu 

şehvet şarkıları söylüyor barlarında 

karlar yağmıyor sokaklara 

korlar yakıyor kadınlarını 

kadınlar şehvet naraları atıyor 

erkekler suskun 

yüreklerini gömmüşler o şehrin kadınları 

mezarlarına 

erkekler suskun arzular yollarda 

diyarlar bekler 

sen hala burdasın çirkin adam 

suskun arzulu 

bırakıp gidemezsin. 

diyara gidecek 

yürek lazım...', 'güzel şehirlerin güzel kadınları  şehrinde sürme gözler  kadınları çiçek bahçesi  şehirlerin kalbi sıcak  sütunları arzulu  şehvet şarkıları...', ARRAY['Türk Edebiyatı','Şiir','Atakan Aktaş']::text[], 8.5, '{"poet":"Atakan Aktaş","poet_slug":"atakan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/guzel-kadinlarin-sehrindeki-cirkin-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanattan Özgür Maviyle Yoldaş Tüyler', 'kanattan-ozgur-maviyle-yoldas-tuyler-atakan-aktas-3wusj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'özgürün adı kanat bilinir 

çırpınıştır oysaki 

acının iniltisi 

yorgun yürek çığlığıdır 

kanat semayla arkadaştır her zaman 

tüyse bırakıverir bir gün 

mavinin koynuna 

kendini 

kanadınsa benliği tutsaktır hep 

yeryüzüne...', 'özgürün adı kanat bilinir  çırpınıştır oysaki  acının iniltisi  yorgun yürek çığlığıdır  kanat semayla arkadaştır her zaman  tüyse bırakıver...', ARRAY['Türk Edebiyatı','Şiir','Atakan Aktaş']::text[], 8.5, '{"poet":"Atakan Aktaş","poet_slug":"atakan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kanattan-ozgur-maviyle-yoldas-tuyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar Ve Erkek Çocuklar', 'kadinlar-ve-erkek-cocuklar-atakan-aktas-f4m7t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tanrının yüreği erkeğe aktı 

erkeğinki kadına 

erkek varoldu 

tanrı kainata sus dedi. 

kadında erkeğe 

erkeğin yüreği çocuktu 

kadın anne oldu 

çocuk en çok oyuncaklarını sevdi 

sevgi ise esir aldı erkek çocuğu 

kim bilebilirdiki kaburgadan oyuncak yapıp 

sonrada oyuncaklarının esiri olacağını', 'tanrının yüreği erkeğe aktı  erkeğinki kadına  erkek varoldu  tanrı kainata sus dedi.  kadında erkeğe  erkeğin yüreği çocuktu  kadın anne ol...', ARRAY['Türk Edebiyatı','Şiir','Atakan Aktaş']::text[], 8.5, '{"poet":"Atakan Aktaş","poet_slug":"atakan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kadinlar-ve-erkek-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün Biraz Daha Uzak', 'her-gun-biraz-daha-uzak-elif-kerenciler-noa1d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağmurlar başladı yine

buruk yüreklerin ferahlaması duyulur

düşen damlalarla

kanat çırpmaktan alıkoyamaz kendini

yerin altındaki kuş

boğulurum korkusuyla

kaçmak ister yaşadığı lağımdan

özgürlüğünü ister özlemlerinde

oysa ne kadar yakındı onlara', 'yağmurlar başladı yine buruk yüreklerin ferahlaması duyulur düşen damlalarla kanat çırpmaktan alıkoyamaz kendini yerin altındaki kuş boğulur...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/her-gun-biraz-daha-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Kıyısında Gezinmemekse Eğer Hayat', 'yasamin-kiyisinda-gezinmemekse-eger-hayat-atakan-aktas-d5et4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşamın kıyısında gezinmemekse eğer hayat 

hevessizdir o zaman kızılla siyah 

kızıl gözde ki hayat olsa 

siyahın günahı ne o zaman umarsız 

hayatın iki oğlu 

biri öz kızıl 

biriyse üveyden kara', 'yaşamın kıyısında gezinmemekse eğer hayat  hevessizdir o zaman kızılla siyah  kızıl gözde ki hayat olsa  siyahın günahı ne o zaman umarsız  ...', ARRAY['Türk Edebiyatı','Şiir','Atakan Aktaş']::text[], 8.5, '{"poet":"Atakan Aktaş","poet_slug":"atakan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yasamin-kiyisinda-gezinmemekse-eger-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küskün Gündüze', 'kuskun-gunduze-atakan-aktas-j0h80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'puslu siyah sen ol 

maviler bana kalsın 

gecelerinde 

yüreksiz dostlara inat.. 

siyahlara dostum, 

mavilere rüya. 

sen siyah dostunla 

mavi rüyama gel 

yüreğimizi paylaşalım. 

gece üryan, sen ana kucağı 

yeniden can ver 

gece çocuk 

sen şevkat ol 

gündüzlere inat', 'puslu siyah sen ol  maviler bana kalsın  gecelerinde  yüreksiz dostlara inat..  siyahlara dostum,  mavilere rüya.  sen siyah dostunla  mavi ...', ARRAY['Türk Edebiyatı','Şiir','Atakan Aktaş']::text[], 8.5, '{"poet":"Atakan Aktaş","poet_slug":"atakan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kuskun-gunduze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlara Konuştum', 'yildizlara-konustum-elif-kerenciler-q0ihe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'garip bir çelişki hissettiğim

ne yapılacağı bilinmez durumlar 

ve

çarpıntılarımla beraber

alıp götürse birileri bedenimi

sıkıştırılmış defterimden

bir bir dökülür kelimeler

bugün bir yıldız parladı üzerime

bakmak istemedim...

14.10.2003 Salı

22:16

Biga', 'garip bir çelişki hissettiğim ne yapılacağı bilinmez durumlar  ve çarpıntılarımla beraber alıp götürse birileri bedenimi sıkıştırılmış defte...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yildizlara-konustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tanem', 'bir-tanem-serdar-safran-i6l4d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüm diyemedim,korkumdan

Solsan,farkın yoktur aslından

Güzellik üresin neslinden

Sevdim seni bir tanem…

Oluşsa yüzünde çizgiler zamanla

Yıpranır mı güzelliği gönlünün? 

Her güzellik geçici mi,acaba? 

Solmaz güzelliği gönlünün…

Oluruz kısmetse,beli bükük ihtiyar

El ele yaşar gideriz,bahtiyar

Sensiz,viran olur bana her diyar 

Sarayısın sen gönlümün …

(2004-Kastamonu)', 'Gülüm diyemedim,korkumdan Solsan,farkın yoktur aslından Güzellik üresin neslinden Sevdim seni bir tanem… Oluşsa yüzünde çizgiler zamanla Yıp...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-tanem-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavruma Nasihat', 'yavruma-nasihat-serdar-safran-wjng7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoktur asla,neslimde

Namertlik özde,sözde

Töreler  atamızda

Yönlendir kendin yavrum …

Yetim hakkı yemedik

Kimsesizi ezmedik

Garibe yardım ettik

Kadir kıymet bil yavrum…

Devleti sömürmedik

Rüşveti hiç bilmedik

Yeyipte semirmedik

Helâle dikkat yavrum…

Haram bize yaramaz

Yolda bulsan pul olmaz

Mert,namerde kul olmaz

Bunu böyle bil yavrum

Özün sözün bir olsun

Gönlün sevgiyle dolsun

Desturun hep bu olsun

Gururla yaşa yavrum…

İyi günde coş,eğlen

Kötü günde koş hemen

Böyle dost bilinmeyen

Bizden değildir yavrum…

Yılgın olma yoklukta

Böbürlenme çoklukta

Hizaya gel bu safta

Her şey Allah’tan yavrum…

(Şubat /2004-Kastamonu)', 'Yoktur asla,neslimde Namertlik özde,sözde Töreler  atamızda Yönlendir kendin yavrum … Yetim hakkı yemedik Kimsesizi ezmedik Garibe yardım et...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yavruma-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydin Sen?', 'neydin-sen-erol-yavuz-lxur5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O kadar uzun zaman oldu ki

Cennet yüzündeki meleği görmeyeli

Hasret gözlerimdeki perde 

Hayalin bu aşkın peygamberi şimdi

Bir aşk uğruna gönüllü olarak sürmüştüm kendimi

Ancak gönüllü bir sürgünün hissedebileceği,

Aşk ve fedakarlık gibi 

Görkemle yüklü duygular dolduruyordu içimi

Gitti 

Başka bir hikayeydi istediği

Bana kalan 

Yüreğimin anlam veremediği bir soru şimdi

Neydin sen? 

Zamanın o küçük kırıntıların da

Yüreğime bu ilkel acıyı hapseden

Neydin sen? 

Kimdin? 

Hikayeme girmeseydin

Keşke tanımasaydım seni

Keşke sevmeseydim

Mart 2004', 'O kadar uzun zaman oldu ki Cennet yüzündeki meleği görmeyeli Hasret gözlerimdeki perde  Hayalin bu aşkın peygamberi şimdi Bir aşk uğruna gön...', ARRAY['Türk Edebiyatı','Şiir','Erol Yavuz']::text[], 8.5, '{"poet":"Erol Yavuz","poet_slug":"erol-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neydin-sen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-ahmet-aksoy-t5z8q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bizler şairsek bize yakışır mı

sivriltilmiş pabuçlarla tekmelemek', 'bizler şairsek bize yakışır mı sivriltilmiş pabuçlarla tekmelemek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/eger-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyninin Sol Yanı', 'beyninin-sol-yani-melih-coskun-wu5wy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beynimin sol yanı 

Alıp başını gidecek nerdeyse bu şehirden

Damarlarımda kurumaya yüz tutmuşken o coşkun nehir 

Hatırlat bana kendini 

Ey göğsümü çatlatan heyecan 

Hatırlat bana kendini 

Ey yürekli sevda 

Bak türküler okuyor hala o güzel çocuklar 

Bakışlarını güneşin doğuşundan ödünç almışçasına

Hala öyle güzel bakıyorlar 

İnan bana hala öyle içten gülüyorlar o çocuklar 

Kan değirmenlerinde öğüttükleri yüreklerinde 

Nice yürekli sevdalar saklıyorlar 

Ama niyedir bilinmez

Damla yaş akmıyor göz pınarlarından... 

Eski hüzünler kaldırıldı yürürlükten 

Adam gibi şeylere ağlamak tarih kitaplarında bile yok 

Çünkü o kitaplar savaşları yazdı sadece 

Ağlayanları değil 

O kitaplar kazananı yazdı sadece 

Kaybedeni değil 

Kabarıp taşacak nerdeyse içimdeki asi deniz 

Tut kolumdan 

Çek götür beni bu limandan...', 'Beynimin sol yanı  Alıp başını gidecek nerdeyse bu şehirden Damarlarımda kurumaya yüz tutmuşken o coşkun nehir  Hatırlat bana kendini  Ey gö...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beyninin-sol-yani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendim İçin Yarım Bıraktım Bu Şiiri', 'kendim-i-cin-yarim-biraktim-bu-siiri-melih-coskun-ane63', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hangi dilde söylendiğini bilmediğim türküm benim

Uzak denizlerdeki yalnızlığım 

Şu anda hiçbir şeyi yazmak mümkün değil 

Mümkün değil anlatmak

Sadece kendim içim yarım bıraktım bu şiiri

Ve sadece tamamlamak için döneceğim geri...', 'Hangi dilde söylendiğini bilmediğim türküm benim Uzak denizlerdeki yalnızlığım  Şu anda hiçbir şeyi yazmak mümkün değil  Mümkün değil anlatm...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kendim-icin-yarim-biraktim-bu-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk', 'terk-umit-kilislioglu-ozger-pk12n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şeyi terkedince ellerin onsuz kalır,

Herşeyi terkedince elinde sonsuz kalır.

(Kapılar kitabından)', 'Bir şeyi terkedince ellerin onsuz kalır, Herşeyi terkedince elinde sonsuz kalır. (Kapılar kitabından)...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/terk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madımak ın anısına..', 'madimak-in-anisina-hidir-cam-53tcn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İKİ  TEMMUZ

Ben sende açtım gözlerimi dünyaya,

	bir zemheri poyrazıyla ey Sivas

Aç kurtlar gibi saldırdım, 

	anamın kara bağrındaki ak memelerine

Sen tattırdın bana

	 maden ocaklarının yorgun açlığını

Sen  koydun cebime 

	şeker yerine		

		otuz beş  kuruşluk

			kara tren harçlığını.

Sen öğrettin bana 

	yoklukların da  özlendiğini,

Bir görebilseydin

	sana olan  aşkımın

		tarih  defterlerimde

			 nasıl gizlendiğini.

Ben sende  öğrendim 

	en acımasız sorgularda  bile,

		 dimdik durmasını

Ben sende öğrendim

	topun, tüfeğin  karşısına

		türkülerimle, 

			kitaplarımla  kaleler kurmasını

		2

Ama  böylesini ne gördük,

	ne  duyduk  Sivas’ım 

 “Cehennemde bile  dal odun yokken”

	hiç böyle yanmadık kafirin koruyla.

Göklere mezarların kazıldığını,

	küllerle tarihlerin yazıldığını; 

Semahların, 

	halayların  yanıp tutuştuğunu,

Otuz üç canın

	turnalara katılıp

		göklerde uçuştuğunu

Biz sen de gördük ey Sivas

Yıl dokuz yüz doksan üçtü,

İki  Temmuz demesi daha da güçtü

“ Havada bulut yok,

	 bu ne dumandır”

Ecelle ölüm yok,

	 o ne figandır.

Duman değil  Sivas’ım

	göklerini  kucaklayan

		otuz üç candır.

Gurbanın olayım Sivas

	gurbanın olayım looy.

On yıldır üşüyorum

	beni de al,

		beni de korlarına  koy 

Yakışır mı sana,

	 hiç böyle ölümler

		Pir’lerin diyarı ey  Şanlı Sivas.

Nasıl aklanacak  şimdi, 

	anlında ki bu kara leke

		cinlerin diyarı ey  Kanlı Sivas.

Susmayın ne olur, 

	sizler  dile gelin 

		ey Uzun Yayla

			ey Yıldız Dağı

Nasıl biter bu yas,

	otuz üç canın,

		on yılın ahı.

		3

Sen, bizi tanırsın ey Sivas,

Biz  biliriz 

	Kızılırmağı,

		Kızıldağı,

			ve   Kızılbaşlığı

Biz biliriz hesabımızı

	yüreğimizdeki boşluğu.

Gün gelir yıkılır

	son bulur bu devran.

Can yağar toprağına,

	yeşerir her yan.

Bir gül boy atar Madımak’ta,

	dallarını süsler 

		otuz üç can.

Bu bir masal değil,

	bu bir düş değil.

Mehdi’ye  havale,

	mahşerlik  iş değil

Bak şafak kızardı 

	o günler  çok yakın

Akın var sana Sivas’ım

	bin yıllık akın

Aç kara bağrını,

	yeniden geliyoruz 

Yediden, yetmişe

	ana, oğul, kız.

Madımak önlerinde divanlar  kurmaya

Mervanlardan, kafirlerden hesaplar sormaya

Aç kara bağrını Sivas’ım 

	yeniden geliyoruz 

Yas günü değil 

	öç alma günü 

		İki  Temmuz….', 'İKİ  TEMMUZ Ben sende açtım gözlerimi dünyaya, 	bir zemheri poyrazıyla ey Sivas Aç kurtlar gibi saldırdım,  	anamın kara bağrındaki ak memel...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Çam']::text[], 8.5, '{"poet":"Hıdır Çam","poet_slug":"hidir-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/madimak-in-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanmak', 'uyanmak-umit-kilislioglu-ozger-7ttzh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir serin esintisin avucumda,

Bir ışıksın başucumda; 

Sana kavuşmak için yanmak gerek,

Yanmak için önce uyanmak gerek.

(Kapılar kitabından)', 'Bir serin esintisin avucumda, Bir ışıksın başucumda;  Sana kavuşmak için yanmak gerek, Yanmak için önce uyanmak gerek. (Kapılar kitabından)...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uyanmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sevgi Tatlısı*', 'sevgi-tatlisi-ramazan-ates-ftfl1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Malzemesi:

1 adet lekesiz gönül.

1 adet açık yürek.

500 gram güler yüz.

250 gram tatlı dil..

100 gram hürmet.

1 Çorba kaşığı sevgi,

1 Çay kaşığı hoşğörü.

1 su bardağı iyiniyet.

1 tutam samimiyet.

1 Ölçek dürüstlük.

Göz kararı saygı.

Hazırlanışı:

Gönülü duygu tasına atıp güler yüz ile karıştır. 

Ağzında yumuşattığın tatlı dili üzerine ilave ederken, sevgi ve saygıyı ince ince üzerine ekele.

Hürmet, iyiniyet ve hoşgörüden meydana gelen şurubu da buna kat.

Samimiyet ölçüsünde parçalara bölerek dürüstce hayata diz ve yüreğinde pişmesini bekle.

Yüreğinde pişirdiğin bu sevgi tatlısını karnın acıkınca değil, ruhun acıkınca ye. 

Mutluluk senin olsun.

Sevgi ve saygının yerini maddeye bıraktığı, hoşgörünün yerini kine ve düşmanlığa bıraktığı günümüzde bu tür tatlıyı yapmak oldukca zor bunu biliyorum. Önemli olan kolayı değil zoru başarmaktır. Öyleyse zora talip olup bunu başarmalıyız. Hoş görü dağarcığının dibi günden güne deliniyor, iyilikler, güzellikler bir bir yok oluyor, insanlık günden güne sanki vahşileşiyor, bu durumdan kurtulmak için, kendimize, ailemize, toplumumuza ve dolaysıyla insanlığa faydalı olabilmek için sevmeliyiz, saymalıyız, hoşgörülü olmalıyız. Bu yüzden size malzemesi kolay bulunan ama yapımı zor olan bir tatlı tarifini verdim. Umarım bu tatlıyı yapar, uygular ve faydasınıda görürsünüz.

Gülen yüzünüz solmasın, kötülük sizi bulmasın, hoş kalın, hoşca kalın, sevgi ve saygılarımla.

Ramazan Ates/Enschede-Hollanda', 'Malzemesi: 1 adet lekesiz gönül. 1 adet açık yürek. 500 gram güler yüz. 250 gram tatlı dil.. 100 gram hürmet. 1 Çorba kaşığı sevgi, 1 Çay ka...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgi-tatlisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirinin Sandalına Bindim Bu Akşam', 'siirinin-sandalina-bindim-bu-aksam-melih-coskun-41gpw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiirinin sandalına bindim bu akşam 

Al götür beni yine sularına, 

Yüreğim uslanmaz bir çocuk 

Haydi uslandır beni

Dalıp dalıp kaybolmayı özledim 

Gözlerinin sonsuz derinliğinde.

Çek çıkart beni düşüp kaldığım kuytuluklardan

Sana şiir yazmayı özledim...', 'Şiirinin sandalına bindim bu akşam  Al götür beni yine sularına,  Yüreğim uslanmaz bir çocuk  Haydi uslandır beni Dalıp dalıp kaybolmayı özl...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siirinin-sandalina-bindim-bu-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arı', 'ari-umit-kilislioglu-ozger-hsgl6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arıyla savaşma zehirlemesin,

Sonucu öfke belirlemesin.

Gel aklını kullan, beklemede kal,

O zaman ödülün petek petek bal.

(Kapılar kitabından)', 'Arıyla savaşma zehirlemesin, Sonucu öfke belirlemesin. Gel aklını kullan, beklemede kal, O zaman ödülün petek petek bal. (Kapılar kitabından...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla', 'bagisla-umit-kilislioglu-ozger-ukqqj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşe kendinden başla

Geçmişteki her şey olmasi gerektiği için oldu

Yaşayacaklarının ne sonu onlar, ne ilki

Kimse suçlu değil ki! 

Seni incitenler bugüne dek,

Kendilerine kızdılar aslında

Öfkeleri sana değildi

Suçlu olmadıklarını bilemediler

Savaşıyorlardı ekmekle, aşla

Kardeşim, sen onları bağışla.

Geçen gün rızkı açılsın diye

Komşunun oğlunun başında

Kilit kapatıp açtılar

Yazık! Bilgiye ne kadar açtılar

Nerelere getirmişlerdi işi! 

Oysa bir bilge kişi 

“ başınızdaki kilitleri açın “ demişti

“ olumlu düşünün, hayır dileyin

Sivrilikleri törpüleyin,

İyimser olun, arının

Güzel olması için yarının “

Kimseyi değiştirmeye çalışma! 

Bu senin elinde değil.

Sen önce kendine eğil.

Öfkeden gözleri kör olanlar

Üstüne yürüseler de sopayla taşla 

Sen yine de onları bağışla.

Unutma! Savaşla değil, hep barışla

Herkesi, herkesi bağışla.

Sen o’sun, o sen aslında

O, kusurlarini daha iyi göresin diye,

Büyüteçle karşına getirilmiş bir hediye.

Onu yargılamadan iyice incele

Eksiği gör, kendini tamamla

Sevgiyi ver ona yudum yudum, damla damla

Şimdi bak,

Üretebilmek, daha çok sevebilmek için

Ne çok zamanın olacak

Bazıları çok zor olsa da

Bir daha, bir daha dene

İster acıyla olsun, ister yaşla,

İnan ki buna değer, bağışla.

Bir genel af ilan et,

Bütün mahkumları sal.

Engelleri, setleri kaldır, 

Islıkla zafer marşını çal.

Çünkü onlar orada oldukça, 

Sensin asıl tutsak olan.

Kır zincirlerini,

Özgürlüğe kavuştur kendini.

Kanatlan, tat al, mutlu yaşa 

Ama önce herkesi, herşeyi

Bağışla.

(Kapılar kitabından)', 'İşe kendinden başla Geçmişteki her şey olmasi gerektiği için oldu Yaşayacaklarının ne sonu onlar, ne ilki Kimse suçlu değil ki!  Seni incite...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/bagisla-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürürüm Ömrümce', 'yururum-omrumce-bekir-mutlu-gokcesu-7u6fz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilemem

Bu açlığım niye? 

Sevgiye	

Yürüdüm şiirlerce

Bu gece

Yine sevgiliye

Çocuksu sevinçlerle

Biz de bu isteksizlik

Varken yengiye

Hep yürürüm daha

Binlerce gece...

Kendimden aşina

Bir yüreğe

Yengiden çok ala

Gönüllü mağlubiyetlerle...', 'Bilemem Bu açlığım niye?  Sevgiye	 Yürüdüm şiirlerce Bu gece Yine sevgiliye Çocuksu sevinçlerle Biz de bu isteksizlik Varken yengiye Hep yür...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yururum-omrumce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Dudakların Mor', 'senin-dudaklarin-mor-hamit-kunt-n5ku4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Komşunun  bacası tütüyor

senin dudaklarının moru

benim yüreğimi üşütüyor

anne

Neden senin dudakların

öğretmeniminki gibi

kırmızı değil? 

Neden karda yürürken

benim ayaklarım ıslanıyor

üşüyor? 

Omuzuma düşen yağmurlar

yüreğime değiyor sanki anne

Biliyorum

Bakışlarından anlıyorum

Yok oğlum diyorsun

Olsa almazmıyım diyorsun

Ama babam bizi neden terketti 

anne? 

Yoksa bizi sevmiyor mu? 

Yok yok

Babalar hiç sevmez mi! 

Gözlerime bak anne

Neden ağlıyorsun? 

Doğru söyle

Babam bizi seviyor değil mi? 

O da şimdi üşüyor mudur

bizim gibi? 

Üşümesin

Üzülürüm

Üşümesin anne

Ben

 senin geceleri

gizli gizli ağladığını

biliyorum 

Yataktan kalktın dün gece

Uzun uzun

sandıktan çıkardığın

bir resme baktın

Ve yine ağladın

ağladın

Sen beni görmedin ama 

ben de ağladım

 anne

Hani babamın

 elinden tuttuğun

o resim varya! 

Babama siyahlar

sana beyazlar

çok da yakışmış 

anne

Ama şimdi

babam yok

Niçin yok? 

Neden gitti? 

Arkadaşlarım soruyorlar

Cevap veremiyorum

Çok üzülüyorum 

Senin

odanın karanlık köşelerinde

ağladığın gibi

ben de

tuvalette ağlıyorum anne

Çok üşüyorum

Bu battaniye ısıtmıyor

Beni koynuna al

Sen annesin

yüreğin sıcaktır senin

Sar beni sevginle

anne

Kapı çalındı galiba

Ben bakarım

Belki de

babam gelmiştir

Ben açıyorum anne

Bir amca gelmiş

Sırtında

yanınca kırmızı ateş olan

o siyah şeylerden var

Bize getirmiş

Arabanın içinde

 zeytin de varmış

helva da varmış

ayakkabı varmış

çorap da varmış

her bi şey varmış

arabanın üstünde

“Deniz Feneri”yazıyor

anne

Yaşasın

artık karda yürürken

ayaklarım ıslanmayacak

Omuzlarıma düşen yağmurlar

vücudumu üşütemeyecek

Artık bizim de bacamızdan

duman tütecek

ama anne

her şey güzel de

senin dudakların hala neden mor

babam gelse

öpse

geçer mi

anne

                                        09/03/2004

                                         Üsküdar', 'Komşunun  bacası tütüyor senin dudaklarının moru benim yüreğimi üşütüyor anne Neden senin dudakların öğretmeniminki gibi kırmızı değil?  Ned...', ARRAY['Türk Edebiyatı','Şiir','Hamit Kunt']::text[], 8.5, '{"poet":"Hamit Kunt","poet_slug":"hamit-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/senin-dudaklarin-mor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köknar', 'koknar-k-muran-esen-5fzu1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçtiğimiz bahar

Dikmiştim seni

Evimizin

Arka bahçesine.

Kışın

Kucak kucak

Yağan kar

Yüklenince  üzerine,

Ben üşüdüm 

Sıcak evimde

Senin yerine.

Bahar gelip

Karlar eriyince

Boy verip

Taze yeşilden

Kınalar yaktığını gördüm

Ellerine.

Ah benim

Küçük köknar’ım! 

Parmak kadar boyunla

Nasıl kafa tuttun

Kara kışın azametine.

                10 / Mart / 2004', 'Geçtiğimiz bahar Dikmiştim seni Evimizin Arka bahçesine. Kışın Kucak kucak Yağan kar Yüklenince  üzerine, Ben üşüdüm  Sıcak evimde Senin yer...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/koknar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Boğazında', 'i-stanbul-bogazinda-i-brahim-dikmen-2-l87eo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bekledim,salt yıldızların altında,

Dolunayı seyrettim,morsalkımın altında.

Seni bekledim,kanat çırpan martılarla,

Gemileri seyrettim,İstanbul boğazında.

Geleceksen gel artık,bekletme beni,

Çok özledim sevgilim,o''sıcak nefesini.

Çocuklar gibi şen,yosunsu gözlerini,

Çok özledim birtanem,tatlı gülüşlerini.

Saatler geçti,gömüldüm karanlığa,

Dolunay terketti bak,yerini yağmurlara.

Nerede gemiler,ne oldu martılarıma,

Öksüz kaldım sevgilim,İstanbul boğazında.

                                                          Aydınlı İbrahim DİKMEN', 'Seni bekledim,salt yıldızların altında, Dolunayı seyrettim,morsalkımın altında. Seni bekledim,kanat çırpan martılarla, Gemileri seyrettim,İs...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istanbul-bogazinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Artık Beni', 'birak-artik-beni-ali-osman-yilmaz-kk351', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırak artık beni,

Kendi yalnızlığımda,

Bir sevgilinin güzelliğini,

Yaşıyorum hayalimde.

Ruhunu bağlayan aşk adına,

Yalvarıyorum sana,

Yüreğini sevginin duyarlığında,

Ve çocukça duygularıma yaklaştıran,

Aşk adına yakarıyorum sana,

Terk et beni ve düşlerimi,

Ben sabahı bekleyeceğim,

Ve sabah yargılayacaktır beni.

Kocaman bir yüreğim var benim,

Göğsümün karanlıklarından,

Çıkaracağım gün ışığına onu,

Yeni bir aşkın avucuna bırakacağım,

Yeniden insanlığımı yaşamak için.

Bırak beni,bırak artık,

Yeni sevdalara yol alayım,

Aşk kuşunun kanatlarında,

Yeniden uçmaya başlayayım,

Bırak beni,

Yada gitmemek üzere gel,

Yaşanmamışlığın günlerini,

Son bir kez yaşamak için,

Bırak kollarıma kendini,

Alıştım sensizlikle yaşamaya,

Beni yaşamaya yüreğin varsa,

Mazeretler uydurma,

Ya gel yaşa beni,

Ya da bırak,

Devam edeyim

Sensizliği yaşamaya.', 'Bırak artık beni, Kendi yalnızlığımda, Bir sevgilinin güzelliğini, Yaşıyorum hayalimde. Ruhunu bağlayan aşk adına, Yalvarıyorum sana, Yüreği...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/birak-artik-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost Vardı-Kadıköy-1990', 'bir-dost-vardi-kadikoy-1990-yusuf-canturk-0u4ug', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzatmak  istedim  kadîm  bir  dosta,  sıcak  elimi,

                Ölüm  haberiyle,  zamansız  büktü  kahpe  felek  belimi.

                Sen  olsaydın  da,  söyleseydim  tatlı  dilimi,

                Çare  bulsaydım  derdine,  öğrenip de  TIP  ilmini.



                Bana,  benden  çok  daha  yakın  huyumdun,

                Ne  akrabam,  ne  de  yakın  soyumdun,

                Kimse   yok  ki  dolduracak  senin  yerini.

                Dostsuz  kaldım,  öyle  büktün  güçsüz  belimi.



                Otuz  yıldır  ne  kırgınlık  ne  de  incinme,

                Kâlbim  paramparça,  yok  lime,  lime,

                Son  acı  feryadın,  kulağımda  hep   duruyor.

                Yaşlarım   pınarlardan  akmıyor,   yine   kuruyor

  Yusuf  Cantürk(E:Hv.Kur.Alb.)', 'Uzatmak  istedim  kadîm  bir  dosta,  sıcak  elimi,                 Ölüm  haberiyle,  zamansız  büktü  kahpe  felek  belimi.                ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-dost-vardi-kadikoy-1990-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hainler', 'hainler-yusuf-canturk-lyhbh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hainler  birleşmiş,  içte  ve  de  dışta.

                Emelleri   belli, ihanet   aziz  vatana.

                Saldırırlar  kahpece,  yaz  da  ve  de  kışta,

                Lânetler olsun  kendini   zulme  satana.



                Teröristler, çocuk,  yaşlı, demez  ırkını  yakar.

                Uşaklık  ederler,  ezelî  düşman,  Ermeni,  Rum’a.

                Masum  insanların, boşuna,  kanları  akar,

                Bir  Mehmet  çıkar  da,  bu  kanı  erdirir  sona.



                Terör  kurbanı,günahsız  aziz  şehidim! 

                Yaslı  anneler,  genç  Eşler,  çocuklar, bıraktın  yetim 

                Kucağında   yattığın  toprak,  seninle  vatan,

                Cennet  yolcusu,  güneşimiz,  ufukta  batan.

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Hainler  birleşmiş,  içte  ve  de  dışta.                 Emelleri   belli, ihanet   aziz  vatana.                 Saldırırlar  kahpece,  ya...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hainler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramıza Girmeyin- Kadıköy-1997', 'aramiza-girmeyin-kadikoy-1997-yusuf-canturk-lxhdl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Laikmiş,  değilmiş,  ayırdınız  yurttaşı,

                Kin  ve  garaz  ektiniz,azdırdınız  yandaşı.

                Otuz  beş  kişiyi  kundaklayıp  yaktınız,

                Neron  gibi,  alevlere  zevk  duyarak  baktınız



                Vatan  için  pek  çok  yiğit  verilirken  şehit,

                Tanrı   evinde, camilerde,  bölücü  militan  eğit! 

                Dünyayı  kana  bulayan  bir  deli  vardı “HİTLER”

                Olsa  gerek,benzerinin  yandaşı,  bölücü  teröristler! 



                Türlü  renkler  mevcut  iken,  sizde  hep  siyah,

                Kur’an  yazmaz  iken  sizce  her  şey  mi  günah? 

                Sakal  kara,  giysi  kara,  ruh   çok  daha  kara! 

                Sallanırsın,tutmuş  gibi,  iğrenç  bir  sara! 



                Tanrı  ile  aramıza  girmeyin  sakın! 

                Bir  gün  gelir  günahını,çok  çekersin! 

                Belli  olmaz  TANRI  sizden  bize, çok  daha  yakın,

                Rüzgar  ekip,  muhtemel  ki  fırtınalar  biçersin

Yusuf  Cantürk (E:Hv.Kur.Alb.)', 'Laikmiş,  değilmiş,  ayırdınız  yurttaşı,                 Kin  ve  garaz  ektiniz,azdırdınız  yandaşı.                 Otuz  beş  kişiyi  ku...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aramiza-girmeyin-kadikoy-1997-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz-1998', 'deniz-1998-yusuf-canturk-clytn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlem  duyar  yanan  beden,  billur  gibi  suyuna,

                Açıklarda  hırçınken,  sakin  olan  koyuna.

                Atılırdım  kucağına,  güvenseydim  huyuna,

                Duygularda  büyük  bir  zevk,  ulaşırdım  doyuma.



                Beyaz  köpüklerle  oynaşırken  sen,  Deniz! 

                Aynaya  bakmış  gibi,  aksederdim  Bendeniz,

                Görülürdü  içinde  küçük,  büyük  balıklar,

                Koşuşurdu  koynuna,çok  yüreği  yanıklar! 



                Mehtap  ile  yakamozlar okşar  iken  gözleri,

                Duyar  idim  küreğimin  çıkardığı  sözleri; 

                Artık  görülmüyor  balıklarla,sandalımın  gölgesi,,

                Uygun  düşmez  oldu şiirlerin  güftesiyle, bestesi..

              

                Suyun  kirlenmiş  amma,  yine  de  denizsin,

                Vereme  tutulmuş  gibi,solgun  benizsin; 

                Kimi  yerin  sığ,  çoğunlukla  hayli  derinsin,

                Yanan  bedenler  için,  hâlâ,  tatlısın,  serinsin.

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Özlem  duyar  yanan  beden,  billur  gibi  suyuna,                 Açıklarda  hırçınken,  sakin  olan  koyuna.                 Atılırdım  ku...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/deniz-1998-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlünce Yaşa-1998', 'gonlunce-yasa-1998-yusuf-canturk-6mtx3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlümce  yaşamadım  ömür  boyunca,

                Bütün  hayat  tuzaklarla  doluydu; 

                Güçlükleri  aşamadım  pek  de  kolayca,

                Elden  tutan  çok  değil,  tek  bir  Allah  kuluydu.



                Gönül  ister  esmeri,  daha  çok   sarışını,beyazı,

                Kâlbim  arzu ile  bekler,  ilk baharı  ve  yazı.

                Duysam  da  yüreğimde,  dinmeyen  bir  sızı,

                Çekilmez  güzellerin  kaprisleri  ve  nazı.



                Derdi  unut  yüreğim,  gez,dolaş,  oyalan,

                Gerçek  yaşam  orada,  bu  dünya hepten  yalan! 

                Sevsen  de  çiçekleri,  Gül’ü  sevme  tez  solan,

                Günleri  sayma  sakın,  ömürden  geri  kalan

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Gönlümce  yaşamadım  ömür  boyunca,                 Bütün  hayat  tuzaklarla  doluydu;                  Güçlükleri  aşamadım  pek  de  kolay...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonlunce-yasa-1998-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem (Kadıköy-1998)', 'ozlem-kadikoy-1998-yusuf-canturk-nwhm6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasretinle her nefes dudağımı yakıyor,

Gözlerim, bin bir ümit, yollarına bakıyor.

Sana malum olur mu, perişan halim,

Dualarım seninle, dönmen için, sağ,salim.

Çıkaramam kulağımdan, bülbül sesini,

Bir tutku ki gönlümdeki, aşkın eseri,

Durduramam ne arzularım ne de hevesim,

Ne baharlık, ne de yazlık, bil ki her mevsim.

Sensiz hissederim, içimde ölüm korkusu,

Seninle yaşarım bu günü, belki, sonsuzu; 

Elim telefona gitti de, her seferde, döndürdüm,

Sana dönük duygular, alevliyken söndürdüm.

Sana hasret kapanmasın yaşlı gözlerim! 

Kulaklarımda çınlarken sıcak, tatlı sözlerin.

Bil ki,yalnız Sana mahsus kaldı,sonsuz özlemim,

Görünüver bir daha, belki benim son demim.

Sesini duymak tutkusu, gider diye, hoşuma,

Basmak ister parmaklar, telefonun tuşuna; 

Düşünceler takılınca, o suna, bu suna,

Vazgeçerim aniden, uğraşlarım boşuna.

  Yusuf  Cantürk(E.Hv.Kur.Alb.)', 'Hasretinle her nefes dudağımı yakıyor, Gözlerim, bin bir ümit, yollarına bakıyor. Sana malum olur mu, perişan halim, Dualarım seninle, dönme...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Cantürk']::text[], 8.5, '{"poet":"Yusuf Cantürk","poet_slug":"yusuf-canturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozlem-kadikoy-1998-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değerini Bil', 'degerini-bil-ahmet-yalcin-9dhgg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kişiye gerektiğinden

Fazla değer verirsen

Ya onu kaybedersin 

Yada kendini kahredersin

Herşeyin belli bir değeri vardır', 'Bir kişiye gerektiğinden Fazla değer verirsen Ya onu kaybedersin  Yada kendini kahredersin Herşeyin belli bir değeri vardır...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yalçın']::text[], 8.5, '{"poet":"Ahmet Yalçın","poet_slug":"ahmet-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/degerini-bil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Çare', 'tek-care-filiz-sarikaya-2tqiw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonunu bulmak en güzeli

Acısız, kedersiz, sıcacık

Soğumadan kalpler

Sönmeden yanan ateş

Sonunu bulmak en güzeli

Sonunu bulmak en güzeli

Nefret bürümeden kalpleri

Çirkinleşmeden iyi niyetler

Sevgi çıkmadan benliğinden

Issızlık çökmeden seven gönüllere

Sonunu bulmak en güzeli

Sonunu bulmak en güzeli

Uzaklaşıp, soğumadan yüreklerimiz...', 'Sonunu bulmak en güzeli Acısız, kedersiz, sıcacık Soğumadan kalpler Sönmeden yanan ateş Sonunu bulmak en güzeli Sonunu bulmak en güzeli Nefr...', ARRAY['Türk Edebiyatı','Şiir','Filiz Sarıkaya']::text[], 8.5, '{"poet":"Filiz Sarıkaya","poet_slug":"filiz-sarikaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tek-care-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müebbet Hapis', 'muebbet-hapis-bekir-gedikoglu-1gl6x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbimin duvarını 

Yıkmak isteyen çoktu

Oynatsa da taşını 

Geçenler bulunmadı

Hududunu sen geçtin

Kalbimdeki sevginin

Artık kurtulamasın

Müebbet hapis yedin

Kalbimdeki bahçenin

Bülbülü olacaksın

Gece gündüz demeden

Durmadan şakıyasın

Şu kalbimin sesini

Kimseler dinlemedi

İnan sensin sahibi

Başka biri gelmedi

Ankara,8 Mart 2004

Bekir GEDİKOĞLU', 'Kalbimin duvarını  Yıkmak isteyen çoktu Oynatsa da taşını  Geçenler bulunmadı Hududunu sen geçtin Kalbimdeki sevginin Artık kurtulamasın Müe...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/muebbet-hapis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Protesto...', 'protesto-hikmet-feridun-demir-2clgg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgili SIIR SEVEN VE DUYGU DOLU SAIR DOSTLAR,

HALDUN HAKMAN DOSTUN YAZMIS OLDUGU SIIRE KONAN

SANSÜRDEN DOLAYI BENDE,

ANTOLOJI COM A KENDI ADIMA SANSÜR KOYUYORUM.

YORUMLARIM DISINDA BIR DAHA, ANTOLOJIYE SIIR GÖNDERMIYORUM. 

ISTERLERLERSE SIIRLERIMI SILEBILIRLER.. 

BU HAKLARINI GÖNÜL RAHATLIGI ILE KULLANABILIRLER.

BU BENI RAHATSIZ ETMEZ.

TAKI BU ZIHNIYETLERINI DEGISTIRENE KADAR.

SADECE EGER MÜSADE EDERLERSE VE ZAMAN BULURSAM 

YORUMLARIMLA SIZLERE MERHABA DEMEK ISTERIM.

DUYGULARA SANSÜR KONMASINA KARSIYIM... 

YOK SA SIIRLERIN ICERIGI BASKA BIR KONU...

NE ZAMANA KADAR DUYGULAR BASKLARININ DUYGULARI 

VE INACLARI TARAFINDAN KONTROL EDILECEK......

KIM NE ADINA KENDINI BU KADAR HAKLI GÖREBILIYOR.... 

BASKALARININ DUYGU, DÜSÜNCE VE INANCLARINA

NASIL GÖNÜL RAHATLIGI ILE SANSÜR KOYUYORLAR...

BEN GÜCLÜYÜM,

YAPARIM MANTIGI ORTA CAGDAN KALMA BIR MANTIK.... 

BEN DE ONLARA DERIM KI ONLAR,..

BIREY OLAMAMISLAR.......

ZAVALLILARRRRRRRRRRRRR.

SAYGILARIMLA...

ISTEYEN DOSTLAR HER ZAMAN mail adresine 

yazabilirler...

[email protected]

Tekrar saygilarimla...', 'Sevgili SIIR SEVEN VE DUYGU DOLU SAIR DOSTLAR, HALDUN HAKMAN DOSTUN YAZMIS OLDUGU SIIRE KONAN SANSÜRDEN DOLAYI BENDE, ANTOLOJI COM A KENDI A...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/protesto-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severek Ayrıldık', 'severek-ayrildik-mehmet-kaplan-keke-xiash', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çünkü ilk dansımızı bu şarkıyla yapmıştık

İşte bu nedenle sevmiştim bu şarkıyı.

Fakat nerden bilirdim ki, 

Kaderimizin; 

Bu şarkının sözleriyle aynı olacağını...', 'Çünkü ilk dansımızı bu şarkıyla yapmıştık İşte bu nedenle sevmiştim bu şarkıyı. Fakat nerden bilirdim ki,  Kaderimizin;  Bu şarkının sözleri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kaplan Keke']::text[], 8.5, '{"poet":"Mehmet Kaplan Keke","poet_slug":"mehmet-kaplan-keke","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/severek-ayrildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Tarihten Bana Uzanan Sevgili -1-', 'tarihten-bana-uzanan-sevgili-1-nigar-adak-20v7h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen şimdi mi varolduğunu sanıyorsun, ey sevgili? 

Tarihi adım adım gez de, gör asırlık kendini.

Keşfetmediğin gömülmüş uygarlıklarda, adın gizli.

Sen; Antik Dünya´da zaman maceraya dönüşürken,

Zeytin gözlünün, gümüş kupada sundugu şarap,

Aşk güneşiyle ermiş, elinde bir salkım üzümdün.

Firavun´un Nil diyarıyla bütünleşen, gizemli piramitleri,

Cleopatra´nın süt banyosunda, kadifeleşmiş teniydin.

Dere gibi uzanan, Çin Seddi´nin üstünde duran,

Çekik gözlünün, ipek siyah saçındaki kiraz çiçeğiydin.

Mozart´ın piyanosunda, fırtınalar yaratan akordu,

Müzikle aşkın kucaklaşan, ölümsüz senfonisiydin.

Mevlana´nın ruhundaki karanlıkları aydınlatan ışık,

Yunus Emre´nin şiirle özleşmiş yürek dergahıydın.

Köroğlu´nun gönül sazı, Karacaoğlan´ın ozan diliydin.

Yaşlı çınarın gölgesinde, çobanın çaldığı yanık kaval,

Al yanaklı yarinin, kalbiyle işlediği, oyalı mendiliydin.

Bir tas ayran uzatırken, kaçamak bakışın kirpiğiydin.

Ey asırlık sevgili; sen ezelden beri hep vardın.

Tarihin ucundan, gönül köprünle bana uzandın.

Seni sadece bir ömürlük sevmeyecegimi bilmeliydin.

Benim sevgim tarih olur, tarih sonrasını da görmeliydin..

Nigar Adak (Yıldız)

10.03.2004

Telif hakları Nigar Adak´a aittir.! 

Dikkat: Şiirlerimin hepsi noter tasdiklidir..! Şair adı olmadan alıntı yapılamaz..!', 'Sen şimdi mi varolduğunu sanıyorsun, ey sevgili?  Tarihi adım adım gez de, gör asırlık kendini. Keşfetmediğin gömülmüş uygarlıklarda, adın g...', ARRAY['Türk Edebiyatı','Şiir','Nigar Adak']::text[], 8.5, '{"poet":"Nigar Adak","poet_slug":"nigar-adak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tarihten-bana-uzanan-sevgili-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Mıydın', 'var-miydin-umit-kilislioglu-ozger-3gjiv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayal meyal geliyorsun aklıma

Uzaklardaan, uzaklardan...

Unutmuşum

Yaz mıydın, bahar mıydın.

Bir haz kaplıyor içimi

Seni düşününce 

Sadece arkadaşım mıydın,

Yoksa yar mıydın? 

Hatırlayamıyorum...

Olmadık bir şey istesem 

Olmadık bir zamanda

Yapar mıydın? 

Kimdin sen? 

Düş gücümle mi yarattım seni,

Yoksa sen,

Gerçekten var mıydın? 

(8. Mart 2004)', 'Hayal meyal geliyorsun aklıma Uzaklardaan, uzaklardan... Unutmuşum Yaz mıydın, bahar mıydın. Bir haz kaplıyor içimi Seni düşününce  Sadece a...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/var-miydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Taşımaz Bu Yükü', 'gece-tasimaz-bu-yuku-nilsu-sari-44cb1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gizlemekten

İlk kez aciz karanlık

İnsanoğlunun kirini

İlk sevdadan kalma

Çağ yorgunu gölgem

Emanet lambalara inat

Caddeye, caddeye akar                

Bu şehir

Habersiz bahardan

Ruhunu kim bilir

Hangi mevsimde unuttu

Ateşler içinde bu gece

Bir tek sensin

Bu adı yok direncin adı

Geçiyordum uğradım

Bir titreme değil yüreğimdeki

Kısık, kısık gözlerine

Yazgısı güneşe kalmış

Yıldız umutları kondurup

Kendi yok oluşuna gitmek için 

Çağlayan yukarı yüzerim

Anla ve

Üstüme, üstüme gelme artık

Bir tek yüreğim var benim

Bakamam gözlerine', 'Gizlemekten İlk kez aciz karanlık İnsanoğlunun kirini İlk sevdadan kalma Çağ yorgunu gölgem Emanet lambalara inat Caddeye, caddeye akar     ...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gece-tasimaz-bu-yuku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam hikayeleri 4', 'aksam-hikayeleri-4-kubilay-enginol-l2e32', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul sokaklarında

Puslu yanan sokak lambaları

Güzelliğini örtmemek için,istanbulun

Yanar yarı ölü,yarı canlı

Lambanın altında bir deli

Vardır mutlaka bir evveli

Belkide kendisiyle hesaplaşmakta

Gözü ne umutta,ne mutlulukta

Bir de parke taşları arkadaşları

Soldaki hasan,sağdaki ahmet

Kırılmış gitmiş ortadaki

Okuyamamış bile rahmet

Ayşe çoktan taşınmış

Hatice,hülyada yok artık

Hayatı da böyle işte

Herşeyiyle aşınmış', 'İstanbul sokaklarında Puslu yanan sokak lambaları Güzelliğini örtmemek için,istanbulun Yanar yarı ölü,yarı canlı Lambanın altında bir deli V...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aksam-hikayeleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmak kim mi', 'ahmak-kim-mi-murat-demir-y925h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hareket var meydanlarda, hareket,

Bayram havası gibi,

Renkli simalar, avcı olmuşlar, avlarıyla

Kenar mahalle kıraathanelerinde

Karşılıklı çay içme uydurmasıyle pazarlanıyorlar,

Tilki ile karga nın peynir hikayesi misali,

Arı gibi çalışıyorlar,vatanımız için

Kapı kapı gezerek,ahmağızya,

Ceketlerinin önleri düğmeli

Asıllarının karşısında eğilerek,

Hööörmet gösterisinde bulunuyorlar,

Propagandalarını sergileyerek,

Dünü hiç yaşamamışlar gibi,

Bak ne güzel ve doğru konuşuyor

Dedirtiyorlar, ahmaklara,

Ahmaklık değilmidir? 

Birkaç günlüğüne, 

İnsan sanıldığını sanmak,

Ahmaklık değilmidir be ahmak? 

Birkaç gün sonra aldanmak,

Aldandığını anlamak,

Dahası ağlamak,

Yoksa hakkın değilmidir

İnsan gibi yaşamak! 

Şairin,bilmiyormuşçasına,ahmak kim? 

Dediği gibi,

Ahmak kim mi? 

Ahmak ben, sen, o

Ahmak biz, siz, onlar

Ahmak çoooook! 

Neyiz ki biz koyunlar

Ahmak olmazsak,bu kadar olandan sonra

Karşımıza,nasıl çıkar ki bunlar.

			

Not: sayın Oğuzkan BÖLÜKBAŞI’nın ‘’AHMAK KİM’’isimli şiirine

Katkı olsun diye yazılmıştır.Ustat, lütfen yanlış anlamayınız.', 'Hareket var meydanlarda, hareket, Bayram havası gibi, Renkli simalar, avcı olmuşlar, avlarıyla Kenar mahalle kıraathanelerinde Karşılıklı ça...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ahmak-kim-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat bir tiyatrodur', 'hayat-bir-tiyatrodur-erol-sen-b7bts', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Değişse de zaman zaman roller

Hayat büyük bir tiyatrodur

Gerçek rolünü oynayanlar dışında

Sahte roller çoktur yaşamda

Derler ya işte gerçek yüzün

Onu görmek için kaç perde geçer yaşama

Bazen üzgün bazen kederli bazen sevinçli

Yaşamın akan saniyelerine karışan

Sözüm meclisden dışarı haşa

Gözlemlerim hayatın kişiliklerini

Bunları yazmak o kadar kolay ki

İnkar eden dünyalı değil

Hani bazen başlar ya hayatım şekerim

Bazende gerçek perde hadi lan

Biliriz rollerin yaşama karışmışlığını da

Kabullenemez seven yürekler

Roller başka gerçek başka

Açın yüzünüzdeki maskeyi

Çıkarın gerçek yüzlerinizi

Hayat böyle de yaşamaya değer…

10.03.2004', 'Değişse de zaman zaman roller Hayat büyük bir tiyatrodur Gerçek rolünü oynayanlar dışında Sahte roller çoktur yaşamda Derler ya işte gerçek ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayat-bir-tiyatrodur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam hikayeleri 5', 'aksam-hikayeleri-5-kubilay-enginol-oti2g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul,yine

Siyah örtülere büründüğünde

Yağmur,sevgi yağmuruna dönüşüyordu

Ücra köşelerinin birinde

Belki yakacakları yoktu ama

Üşümüyorlardı

Annenin yaptığı bir tencere sevgiyi

Kaşıklıyorlardı

Tavan akıyordu,ekmek azdı ama

Onlar birbirini seviyorlardı

Akşam, çiçeklere paydos vermişti

Onlar çiçek tarlasında yaşıyorlardı', 'İstanbul,yine Siyah örtülere büründüğünde Yağmur,sevgi yağmuruna dönüşüyordu Ücra köşelerinin birinde Belki yakacakları yoktu ama Üşümüyorla...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksam-hikayeleri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Resmim...', 'eski-resmim-nergis-demet-v6rvt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eski resimlere bakıyordum,

Dün.

Kimbilir,

Kötü geçen gecelerden,

Hangisinin sabahında,

Çekilmiş bu resim...

Gözlerimden...

Keder akıyor....', 'Eski resimlere bakıyordum, Dün. Kimbilir, Kötü geçen gecelerden, Hangisinin sabahında, Çekilmiş bu resim... Gözlerimden... Keder akıyor.......', ARRAY['Türk Edebiyatı','Şiir','Nergis Demet']::text[], 8.5, '{"poet":"Nergis Demet","poet_slug":"nergis-demet","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eski-resmim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne çıkar', 'ne-cikar-kubilay-enginol-86cc4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana düşman ol

Birde bunu deneyelim

Denemediğimiz kalmadı

Sen sevmedin,ben sevdim

Çiçek bahçeleri serdim

Olmadı

Sevgi ışıkları yaydım

Isıtmadı

Kase,kase gözyaşı sundum

Görmedi

Sen ban düşman ol ne çıkar

Unutmaki

En büyük aşklar düşmanlıktan doğar', 'Bana düşman ol Birde bunu deneyelim Denemediğimiz kalmadı Sen sevmedin,ben sevdim Çiçek bahçeleri serdim Olmadı Sevgi ışıkları yaydım Isıtma...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-cikar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Babam', 'canim-babam-galip-sinecikli-csvxn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Babam Habip Sinecikli'' ye

Bir fırında çalışmaya başlamış 15 yaşında,

Ateşin karşısında 45 yıl,

Dile kolay,

Dayanabilirmi insan,

Ama babam dayanmış,

Çocukları için dayanmış,

Ailesi için dayanmış,

Evi için dayanmış,

Halada dayanmakta,

Bir küreğin ucunda,

Ömrünü pişirmiş,

Senelerce,

Ekmek niyetine,

Benim babam Ateş Adam,

Tatlı dilli, 

Mangal yürekli,

Ellerinin nasırıyla okşarken bizi,

Pamuk gibi gelirdi,

Seviyordu Çocuklarını ve Eşini,

Aynı zamandada işini,

Bırak artık Baba,

Emekli oldun dinlen biraz,

Otur bir kenarda dedikçe kendisine,

''Zamanı gelince bırakırım'' diyordu bize,

Yıllar onu yıprattı belki,

Ama,

Yüreciğindeki sevgiyi yıpratmadı,

Bize öğrettiği çok şey var,

Namuslu olacaksın,

Dürüst olacaksın,

Öleceğini bilsende doğru olacaksın,

Erdemli olacaksın,

Aileni,

Çocuklarını,

Eşini ve İşini seveceksin,

Hiç kimseyi aldatmayacaksın,

Vatanını seveceksin,

Bunları öğretti bizlere,

Yıllarca böyle yetiştirdi bizi,

Umarım ona layık evlatlar olmuşuzdur,

Şimdi Altmış yaşında Babacığım,

Canım Babam,

Seni çok seviyorum,

[email protected]', 'Babam Habip Sinecikli'' ye Bir fırında çalışmaya başlamış 15 yaşında, Ateşin karşısında 45 yıl, Dile kolay, Dayanabilirmi insan, Ama babam da...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/canim-babam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğim Yok Olacak', 'sensizligim-yok-olacak-nilsu-sari-e4hxa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni deli eden kokun  ve tabiatı yorumlamam, 

Bir de üzerindeki kirpiklerde sensizlikle 

Beslenen göz yaşları, hasretim.

Kavuşabilme ihtimalleri ve karaya 

Vuran dalgalar, mutluluğum.

Taşınan köpükleri, uzaklardaki senimden  sızı 

Hırçınlık,  sensizliğim. 

Göremez olmuş kıyısında vuran köpükleri 

Yaşlı gözleri, yüreğim.

Gaddar bir yargıç hesap soran

Bir gece karşımda, benliğim. 

Bu titreyen aciz, hasreti taş tutarak nişan alan 

Sensizlik korkusuyla kıyısında

Vuran köpükleri, elim.

Üzerinde hasret köpüklü

Çıldırmış dalga, yılmayan.

Her seferinde bir o kadar çoğalıp

Gelen köpükler, taşlanan. 

Ve hasretim taşınan karşı sahile 

Her bir köpük, taşınan.

Bensizliği ve sensizliği değil hasreti 

Seferinde binlerce parçaya bölecek, taş. 

Bana gelen her köpükte sabit cesaret, sabır.

Yığacağım sensizlik ve hasret ve bir de benim arama.

Çoğalan mutluluğum,taşlanan sensizliğim,taşınan yüreğim 

Yılmayan benliğim,cesaret, sabır 

Ve bulacağım senimi o sahilde elim taş,

Başıma kadar seninle ıslak.

Sensizliğim yok olacak.', 'Beni deli eden kokun  ve tabiatı yorumlamam,  Bir de üzerindeki kirpiklerde sensizlikle  Beslenen göz yaşları, hasretim. Kavuşabilme ihtimal...', ARRAY['Türk Edebiyatı','Şiir','Nilsu Sarı']::text[], 8.5, '{"poet":"Nilsu Sarı","poet_slug":"nilsu-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sensizligim-yok-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimiz Yoldadır', 'gozlerimiz-yoldadir-zulfikar-yapar-kaleli-ywx4m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kurtarıcı neden halâ gelmedi

Bekliyoruz, gözlerimiz yollarda

Kaç asırdır Türk’ün yüzü gülmedi

Saklıyoruz, gözlerimiz yollarda

Riyakârlık tahtı kurdu cihana

Arzu heves kalmadı bizden yana

Çilemizi gece gündüz, gün güne

Ekliyoruz, gözlerimiz yollarda

Her orduyu dağıtırdı yelimiz

Bak şu anda ne perişan halimiz

Çok zamandan beri kuru gülümüz

Kokluyoruz, gözlerimiz yollarda

Bu millete milli gözle bakanı

Hainlerin plânını yıkanı

Ha geldi gelecek diye, hakanı

Yokluyoruz, gözlerimiz yollarda

                                   1980', 'Kurtarıcı neden halâ gelmedi Bekliyoruz, gözlerimiz yollarda Kaç asırdır Türk’ün yüzü gülmedi Saklıyoruz, gözlerimiz yollarda Riyakârlık tah...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerimiz-yoldadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Kimiz', 'biz-kimiz-zulfikar-yapar-kaleli-fqm00', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiçbir zaman tarafsızım dememiş

Ülkü saflarına dolanlardanız

Otuz altı saat yemek yememiş

Otuz beş kuruşu olanlardanız

Doğruya yardım vadeden Allah

Vatana ihanet en büyük günah

Cehalete karşı ilim tek silah

Başarı bundadır bilenlerdeniz

Ötüken’den,Altaylardan şan ile

Sulamışız bu vatanı kan ile

Oğuz Han, Fatihle, Alparslan ile

Şerefli maziden gelenlerdeniz

Sömüren düzeni hiç tutmamışız

Dünya nimetinden zevk tatmamışız

Komşusu aç iken tok yatmamışız

Fukara göz yaşı silenlerdeniz

Namus duygusuna bıçak bileyen

İşçiyi sömürüp, hakkını yiyen

Ben şu yurtseveri alt ettim diyen

Zibidi haline gülenlerdeniz.

                              1974', 'Hiçbir zaman tarafsızım dememiş Ülkü saflarına dolanlardanız Otuz altı saat yemek yememiş Otuz beş kuruşu olanlardanız Doğruya yardım vadede...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/biz-kimiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış Anlayışı', 'baris-anlayisi-zulfikar-yapar-kaleli-fqx5h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Topraklar vatan mı olur? 

Bayrakları olmadıkça.

Vatan selâmet mi bulur? 

Ser verenler dolmadıkça

Bu sırrı herkes bilemez

Herkes bu yola gelemez

Kimse yurtsever olamaz

Türklüğünü bilmedikçe

Kabul etmez onu lâhit

Kim olsa yalancı şahit

Her ölü olur mu şehit? 

Hak yoluna gelmedikçe

Açmadan solmakta gülüm

Yosmam, ay yıldızım, alım

Milleti yoluna ölüm

Kapısını çalmadıkça

Bülbül yanıp tütmeyecek

Artık baykuş ötmeyecek

Savaşımız bitmeyecek

Türk dünyası gülmedikçe', 'Topraklar vatan mı olur?  Bayrakları olmadıkça. Vatan selâmet mi bulur?  Ser verenler dolmadıkça Bu sırrı herkes bilemez Herkes bu yola gele...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baris-anlayisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaire Dostum İlayde/Sedef Ünal’a....', 'saire-dostum-i-layde-sedef-unal-a-tulay-sustam-2svu2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sonbahar akşamında; 

Sıcacık bir merhaban iliklerime kadar işledi.

Lâlezar oldu, gülistan oldu

Sevinçten gönül bahçem....

Aniden girdin hayatıma

Sıyrıldın yavaşca dostluk evrenimden

Yüreğimin kapısını usulca araladın

Koca yüreğimi onikiden vurdun....

Dedim ki; senin için kendi kendime

Sen dostluk için, aşk için gelmişsin dünyaya

Hoşgeldin hayatıma hoşgeldin dost...

Oysa ben senin ne yüzünü gördüm

Ne sesini duydum, ne de çığlıklarını duydum

Senin hakkında bildiğim tek bir şey vardı.

Yüreğinde benim gibi cesur bir yürekti.

Hoşgeldin yüreğime hoşgeldin dost...

Bana gönderdiğin en son mesajında...

“Yüreğimden bir gül demeti gönderiyorum sana” demiştin.

Oysa ben hayatımda bu kadar güzel bir gül demeti almadım

Bil ki dost; gönderdiğin güllere sonsuza dek sahip çıkacağım

Solmamaları için her gün gözyaşımla sulayacağım...

Bende sana bir “gelincik “ gönderiyorum...

Gelin olduğunda o tel tel saçlarına takarsın, beni hatırlarsın

Hoşgeldin dünyama hoşgelldin dost...

(İstanbul, 09.03.2004 22.15) 

***Şaire dostum ilayde/Sedef Ünal''a ithaf edilmiştir.***', 'Bir sonbahar akşamında;  Sıcacık bir merhaban iliklerime kadar işledi. Lâlezar oldu, gülistan oldu Sevinçten gönül bahçem.... Aniden girdin ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/saire-dostum-ilayde-sedef-unal-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşımsın... Gözyaşın Olmak İsterdim...', 'gozyasimsin-gozyasin-olmak-i-sterdim-tulay-sustam-le7pm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce gözyaşım oldun...

Gözbebeklerimden yanaklarıma sonra kara dudaklarıma akıp giden.

Sonra yağmur tanesi oldun...

Gökyüzünden bedenime akıp giden.

Şimdi bir okyanus oldun...

Köprü misali bir yürekten diğer yüreğe akıp giden.

Şunu bil ki sevgili; 

Ben yüzmesini bilmem...

Alışık değilim bu kadar su birikintisine

Oysa ben senin gözyaşın olmak isterdim.

Gözbebeklerinden yanaklarına sonra kara dudaklarına akıp giden.

(İstanbul, 09.03.2004 21.30)', 'Önce gözyaşım oldun... Gözbebeklerimden yanaklarıma sonra kara dudaklarıma akıp giden. Sonra yağmur tanesi oldun... Gökyüzünden bedenime akı...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozyasimsin-gozyasin-olmak-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakın Da Görün', 'bakin-da-gorun-zulfikar-yapar-kaleli-ysv8n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mecnunlar çöllere hükmetse, dişi

Sıkan biz oluruz, bakın da görün

İşten çıkarılsa on on beş kişi

Çıkan biz oluruz, bakın da görün

Bugünkü ukala geçinen çoğu

Yarın da yiyecek kaymağı, yağı

Sevmedim şu solu, istemem sağı

Akan biz oluruz, bakın da görün

Her gelen atanır, bakılmaz düne

Boynumuz bükülü gezeriz yine

Elimizle kendimizi mahzene

Tıkan biz oluruz, bakın da görün

                                          1991', 'Mecnunlar çöllere hükmetse, dişi Sıkan biz oluruz, bakın da görün İşten çıkarılsa on on beş kişi Çıkan biz oluruz, bakın da görün Bugünkü uk...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bakin-da-gorun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Refahtayız! ! !', 'refahtayiz-zulfikar-yapar-kaleli-e2hsk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne dolaplar gördük biz bu dünyada

Refah var dediler sökülenlerde

Moda, medeniyet gördün ya aha

Üstü başı yırtık dökülenlerde

Şu düzene şükret, başka çaren yok

Nasıl bir düzense, aklı eren yok

Herkes borçlu yaşar, borcu veren yok

Tek boynuz eksiktir bükülenlerde

Refah diye diye çıkar canımız

Sobanın yanında donar kanımız

Deriz ya, duyulmaz, vay amanımız

Hikmet var diyorlar çekilenlerde

Vurguncu vurgunu dağdan aşırır

Bir kalemde trilyonlar kaçırır

Namuslu ar eder, yolu şaşırır

Copu var önünde dikilenlerde

Bir yanda saltanat, bir yanda düğün

Hep deriz” Türk güven çalış ve öğün”

Kimin umurunda senin öldüğün

Şeytanın emri var ekilenlerde

                                    1990', 'Ne dolaplar gördük biz bu dünyada Refah var dediler sökülenlerde Moda, medeniyet gördün ya aha Üstü başı yırtık dökülenlerde Şu düzene şükre...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/refahtayiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Can Çekişir', 'canim-can-cekisir-zulfikar-yapar-kaleli-2pd4f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Yayla karı ılık yele tutulur

Can suyu akışır, ayaklarımda

Tepelerden eteklere atılır

Hissizlik bakışır, ayaklarımda

Damladan deryaya yürüyünce su

Can evime kurar amansız pusu

Yalnızlık yaman yol olur doğrusu

Bir volkan sıkışır, ayaklarımda

Ne okunsa, ne sürülse nafile

Artık benzer biber sürülmüş dile

Yalnızlığı bölüp yalnızlık ile

Dert tene yakışır, ayaklarımda

Bir anda gök düştü, çağ bombalandı

Halay, düğün, dernek yuğ bombalandı

Yanımı verdiğim dağ bombalandı

Taze kar kokuşur, ayaklarımda

Kuru pınar yayla sular, eşince

Bir sızı duyulur inceden ince

Ak bulutlar ara ara düşünce

Damla damla ışır, ayaklarımda

Masrafsız, ücretsiz mesai yoğun

Bu meret belâsı bu asrın, çağın

Neremi ellesen dert yığın, yığın

Canım can çekişir, ayaklarımda', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Yayla karı ılık yele tutulur Can suyu akışır, ayaklarımda Tepelerden eteklere atılır Hiss...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/canim-can-cekisir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatım', 'hayatim-sefer-kurt-8yzwz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbime sevgi çiçeği açtı 

Hep seni seveceğim hayatım

Sevmeyi sen öğrettin bana

Seni ömür boyu güldüreceğim hayatım

Canım oldun bedeninde sakladım seni

Soldurmam asla o sevgi çiçeğini

Kaderimsin değiştirmem kaderimi

Bu beden sensiz olamaz hayatım

Elin elime değdi yüreğin yüreğime

Gözüm yüzüne baktı kalbim kalbine

Ruhumda hep sen bedenin bedeninde

Bu aşka asla ihanet edemem hayadım

Söz verdik biz birbirimize

Bahcemiz olacak evimizin önünde

Mutluluk ekilecek aşk bahcemize

Kalbimde yaşıyorsun hayatım', 'Kalbime sevgi çiçeği açtı  Hep seni seveceğim hayatım Sevmeyi sen öğrettin bana Seni ömür boyu güldüreceğim hayatım Canım oldun bedeninde sa...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayatim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım Bu Şehirde', 'yalnizim-bu-sehirde-sefer-kurt-9bwgh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızım bu şehirde

Sokaklar sessiz sakin

Kimsecikler yok ortalıkta

Işıklar bile eskisi gibi yanmıyor

Sanki kuşlar küsmüş bana

Bu şehir dar geliyor şimdi

Sensizlik zor geliyor bana

Bu sitem sanadır yar

Bu isyan sanadır yar

Bu şehir sana dargın yar

Yoksun sen bu şehirde

Sanki hiç kimsecikler yok

Yalnızım bu şehirde

Tek başıma

Yalnızım bu şehirde

Yalnızım...', 'Yalnızım bu şehirde Sokaklar sessiz sakin Kimsecikler yok ortalıkta Işıklar bile eskisi gibi yanmıyor Sanki kuşlar küsmüş bana Bu şehir dar ...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizim-bu-sehirde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur Gitme', 'dur-gitme-sefer-kurt-11qvv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Işığımsın sakın sönme

Gitme gitme ne olur dur gitme

Güneşimsin yağmuru getirme

Gitme gitme ne olur dur gitme

Sımsıkı tut elimi geri çekme

Bak gözlerime kendini üzme

Sen can canımsın beni terk etme

Gitme gitme ne olur dur gitme

Kalbimi çaldın kalbim sende

Kalpsiz yaşayamam ki hayatım elinde

Yaşarken beni kara toprağa gömme

Gitme gitme ne olur dur gitme

Üzemem seni sende üzme beni

Kader deyip kalbinden silme beni

Zincirlere vursalar kır zincirleri

Gitme gitme ne olur dur gitme

Gitme gitme ne olur dur gitme dur

Atma beni karanlığa atma dur

Silme beni kalbinden silme dur

Yaşayamam sensiz ne olur gitme dur

NOT: Ben kızları anlayamıyorum hiç bir neden yokken zaman aşımı deyip ayrıldı. Onca gitme dememe rağmen gitti elveda aşkım.', 'Işığımsın sakın sönme Gitme gitme ne olur dur gitme Güneşimsin yağmuru getirme Gitme gitme ne olur dur gitme Sımsıkı tut elimi geri çekme Ba...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dur-gitme-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam ki', 'unutamam-ki-sefer-kurt-4ynk8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk aşkımdın kolaymı sensiz yaşamak

Unut diyorsun bana unutamam ki

Canımda candın kolaymı silip atmak

Unut diyorsun bana unutamam ki

Gecemdeydin hep sen şimdi hayalimdesin

Sen unutmuş olsanda hala yüreğimdesin

Dilim adını anmasada hep nefesimdesin

Unut diyorsun bana unutamam ki

Hani o tatlıuykusuz gecelerimiz varya

Düşündüğüm an sanki seni yaşıyorum o anda

Bedenim bedenimde yine sense uzaklarda

Unut diyorsun bana unutamam ki

Boşver gitsin diyorsun yapamam ki

Sil at kalbinden diyorsun seni silemem ki

Kaderine vur diyorsun buna gücüm yetmez ki

Unut diyorsun bana ben seni unutamam ki', 'İlk aşkımdın kolaymı sensiz yaşamak Unut diyorsun bana unutamam ki Canımda candın kolaymı silip atmak Unut diyorsun bana unutamam ki Gecemde...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutamam-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Sende', 'yok-sende-sefer-kurt-0jd0x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani çok çok seviyordun

Yok güzelim yok hiç vicdan yok sende

Seviyorum diyordun şimdi unut diyorsun

Yok güzelim yok hiç vicdan yok sende

Hani söz vermişdik birbirimize

Ebedi sevecekdik sözün nerede

Vurdun sırtımdan vurdun kahpece

Yok güzelim yok hiç gurur yok sende

Aşk farklı mutlulukla ölüm arası

Kainat içinde farklı alem aşk dünyası

Beni mutluluktan ettin geldi ölüm sırası

Yok güzelim yok hiç gurur yok sende

Senin mutluluğun için her şeyi göze aldım

Söyle vicdansız söyle sen benim için ne yaptın

Yaptın hemde en iyisini kalbime yara açtın

Yok güzelim yok hiç sevgim yok sende

Adaletsizmiş aşk adaletsizmiş dünya

Birde sen olunca bunların yanında

Tamamladınız birbirinizi beni bıraktın karanlıklara

Yok güzelim yok hiç vicdan yok sende', 'Hani çok çok seviyordun Yok güzelim yok hiç vicdan yok sende Seviyorum diyordun şimdi unut diyorsun Yok güzelim yok hiç vicdan yok sende Han...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yok-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Aşımı', 'zaman-asimi-sefer-kurt-rljh9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her başlangıçın bir sonu varmış

Her sevincin bir hüznü

Her yazın bir kışı varmış

Her hayatın bir ölümü

Ama aşkın sevginin sonu olmamalı

İnsanlar yıpranmamalı

Bir kez geliyoruz dünyaya

Evet sevgilim soruyorum sana

Aşkta zaman aşımı olur mu

Zaman aşımı dediğin ne ki

Son kullanma tarihi geçer mi aşkın

Zaman aşımı deme gülerler sana

Doğruyu söyle çekinme

Zaman aşımı değil son kullanma tarihi

Sen sevdin mi

Hayır güzelim

Sen sevmedin

Aşkımla dalga geçtin

Sen aşka yenildin

Senin ki ihanet değil

Duygusuz kalbinle beni üzdün

Sen sevmedin

Yalan yere göz yaşı döktün

Benim duygularımla oynadın

Anlayamazsın sen duygusuzsun

Sen sevmedin

Aşkın son kullanma tarihi yoktur

Olsada sonsuzdur

Sen sevmedin

Çünkü aşk zaman aşımına uğramaz', 'Her başlangıçın bir sonu varmış Her sevincin bir hüznü Her yazın bir kışı varmış Her hayatın bir ölümü Ama aşkın sevginin sonu olmamalı İnsa...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/zaman-asimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Git Hayatımdan', 'cek-git-hayatimdan-sefer-kurt-3u5zj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oynadın sen benim duygularımla oynadın

Yaktın içimi kor kor yaktın yıktın

Yara açıp yüreğime kalbimi kanattın

Çekip hançeri vurdun hemde sırtımdan

Durma git çek git git hayatımdan

Neler verdim senin uğruna neler çektim

Aşkımı sevgimi her şeyimi sana feda ettim

Bir ay için bin yıldızdan vaz geçtim

Aşkımın değerini bilmedin vurdun sırtımdan

Durma git çek git git hayatımdan

Sen aşkı ne bilirsin duygularla oynamak mı

Yoksa dalga geçmek mi oyalanmak mı

Zevgi sefa yapıp doruklara vurmak mı

Yanılırsın güzelim mutlu olamazsın ahımdan

Durma git çek git git hayatımdan

Aşkı vucutta arama yürekte olur yürekte

Kimi dem vurur kimi yanar hasretle

Her engeli aşıp geçer tükenmez enerjisiyle

Senin aşkın gerçek değildi ibaretti yalandan

Durma git çek git git hayatımdan

Zaman aşımı dedin bitti aşkım diyerek gittin

Aşkın son kullanma tarihi yoktur sen icat ettin

Yani senin ki şehvetti şehvetini eskittin

Taş kalplisin sevgi beklendin olmaz hayattan

Durma git çek git git hayatımdan

Kahpece vurdun ne duruyorsun gitsene

Aşk olamaz sende kendini başkalarıyla tatmin etsene

Beni yaktın bu dünyada hesap soracağım mahşerde

Aşk duygularımı görelttin beklendim kalmadı dünyadan

Durma artık durma durma çek git hayatımdan', 'Oynadın sen benim duygularımla oynadın Yaktın içimi kor kor yaktın yıktın Yara açıp yüreğime kalbimi kanattın Çekip hançeri vurdun hemde sır...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cek-git-hayatimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimi Yaktın', 'kalbimi-yaktin-sefer-kurt-cn495', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep yanımdaydın aslında

Ama keşfetememiştim seni

Umutsuzluk vardı yüreğimde

Hep yağmurluydu benim havalar

Bazen bulutlu

Güneş uğramazdı benim dünyama

Bu gün bulutlar çekildi buralardan

Güneş gözüktü uzaktan uzaktan

Güneş uzakta olsa bile gözüktü bana

Yol uzun olsa bile...

Aslında her şeyi sen yaptın

Sen baktın bana sevdalı gibi

Sen dağladın yüreğimi

Gülüşün yetti bana

Sanki dünyanın bütün çiçekleri yüzünde

Tıpkı cennet bahçesi

Artık güneşe yaklaşmalıyım

Tam yanında olmalıyım

Huzur bulmalıyım seninle

Evet sen yaktın kalbimi

Bir bakışınla hemde

Bir bakışın kalbimi yaktın sevgilim

Kalbimi yaktın', 'Hep yanımdaydın aslında Ama keşfetememiştim seni Umutsuzluk vardı yüreğimde Hep yağmurluydu benim havalar Bazen bulutlu Güneş uğramazdı beni...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kalbimi-yaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve ihanet...', 'ask-ve-ihanet-omer-faruk-girgin-d4066', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnandım sevdiğine; 

Kendimi ihanetin içinde buluncaya kadar

İnandım sevdiğine; 

Gücümün en son noktasına kadar,

Özümdeki can tükeninceye kadar.

Bana yaklaşan sonsuzluğa kadar...

İnandım sevdiğine; 

Kendimi aldatılmışlığın içinde buluncaya kadar.

Yüreğimin aldığı yaraya kadar

Gözlerim kapanıncaya kadar,

Ve inandım sevdiğine; 

Işığın bile sustuğu yere kadar...

..................................; 

Şimdi yıldızlar usulca fısıldayacak bu dizelerimde,

Hiç kimsenin bulunmadığı boş yüreklere dokunacak belki de,

Ve gecenin ince bir yerinde,

Yalnız bir kadın ağlayacak belki de...', 'İnandım sevdiğine;  Kendimi ihanetin içinde buluncaya kadar İnandım sevdiğine;  Gücümün en son noktasına kadar, Özümdeki can tükeninceye kad...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-ve-ihanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-sefer-kurt-k1a00', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine soğuk bir kış gecesi

Karanlıkta parlayan kar taneleri

Odamda yine loş bir ışık

Çaresizlikle bakan duvarlar

Soğuk mu yoksa kar taneleri mi

Odamdaki loş ışık mı

Veya dert ortağım dört duvar mı

Hankisi getirdi bu hüznü

Merhaba dostum hüzün merhaba

Ne dertler yazılmış şu gönlüme

Ne soğuk anlıyor ne de kış gecesi

Nasıl anlasın ki beni kar taneleri

Her kes kış geldi sanıyor

Soğuk benim gönlümden esiyor

Kar taneleri ihanet hecelerinden oluşuyor

Göz yaşlarım akıp akıp sel oluyor

Çileler kalbime taş basıyor

Neden geldi kış neden

Merhaba soğuk 

Merhaba kar taneleri

Merhaba ihanet merhaba', 'Yine soğuk bir kış gecesi Karanlıkta parlayan kar taneleri Odamda yine loş bir ışık Çaresizlikle bakan duvarlar Soğuk mu yoksa kar taneleri ...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/merhaba-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşadacağım', 'seni-yasadacagim-sefer-kurt-85c2y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani söz vermiştin dönecektin

Beni hep ama hep sevecektin

Döndün ama cansız bedebin

Kıydılar sana ben şimdi ne yapacağın

Sen olmasanda seni kalbimde yaşadaçağım

Söz vermiştin geliyordun gözüm yollardaydı

Gelişinle hasretin son bulacaktı

Ama olmadı bak gözlerim yine yaşlı

Kıydılar sana umutsuz yolları nasıl aşacağım

Sana söz aşkım seni yüreğimde yaşatacağım

Sevmek güzel ama sonu neden acı oluyor

Seven yüreğim gamla dertle doluyor

Birini kader diğerini kurşun elimden alıyor

Kıydılar sana şimdi ben boş gözlerlemi bakacağım

Bu kahpe dünyada söz seni benle yaşadacağım

Tam değecekti ellerim ellerine

Birde ne göreyim cansız bedenin önümde

Gelde etme nasıl isyan etme böyle kadere

Kıydılar sana şimdi sensiz hayalde mi yaşayacağım

Yıkılmış perişan olmuş kalbimde seni yaşadacağım

Ne olur aşkım ne olur bitanem alınma bana

Olmuyor ama ilk ve son şiirim sana

Rahat uyu sen hep olurum senin yanında

Anlamadım nasıl kıydılar sana ben ne yapacağım 

Adın kalbimde seni hep yüreğimde yaşatacağım', 'Hani söz vermiştin dönecektin Beni hep ama hep sevecektin Döndün ama cansız bedebin Kıydılar sana ben şimdi ne yapacağın Sen olmasanda seni ...', ARRAY['Türk Edebiyatı','Şiir','Sefer Kurt']::text[], 8.5, '{"poet":"Sefer Kurt","poet_slug":"sefer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-yasadacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-ufuk-huseyin-akyol-8gkx4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ufak bir damlacık; 

İçinde binbir acılar barındıran,

Bazende anlatılmayan duygular taşıyan.

Binbir duygunun tercümanı,

Bir ufak damla gözyaşı.', 'Ufak bir damlacık;  İçinde binbir acılar barındıran, Bazende anlatılmayan duygular taşıyan. Binbir duygunun tercümanı, Bir ufak damla gözyaş...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Hüseyin Akyol']::text[], 8.5, '{"poet":"Ufuk Hüseyin Akyol","poet_slug":"ufuk-huseyin-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozyasi-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huznumuzun Rengi', 'huznumuzun-rengi-neslihan-ayakta-rl5pa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilim, sevdigim, umut yelkenim..

Yalnizligim dogustan, kanima islemis..

Koymuyor yoklugun! 

Varligin heveslendiriyor yuregimi..

Buyuk bir bosluk, hic yok gibi..

Anlatmasi zor bitanem, cok zor..

Ozlem nedir bilmiyor gibiyim aslinda..

Vuslat var yuregimde sadece! 

Huznumuz gokkusaginda bir renk

Bizi biz yapiyor, tatlandiriyor..

Yuregime centik atmak zorunda misin her seferinde,

Gelecegi karartmak hosuna mi gidiyor? 

Hayallerden uzaklasmisim yeterince,

Yuregimin sularina korku capanini atmazsan olmaz mi yelkenim, olmaz mi? ? ? 

Onumuzde guzel bir hayat bekliyor, kabus etme duslerimi..

(16.05.03)', 'Sevgilim, sevdigim, umut yelkenim.. Yalnizligim dogustan, kanima islemis.. Koymuyor yoklugun!  Varligin heveslendiriyor yuregimi.. Buyuk bir...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huznumuzun-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gunahtan Kacamazsin', 'gunahtan-kacamazsin-neslihan-ayakta-969h3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ozur diliyorsun yeniden

Sende insansin, haklisin

Ben bastan cikaran gunahkar

Sen hakimiyetsiz dindarsin

Once kac kuytulara

Sonra kalalim karanlikta basbasa

Pazar gunu git gunah cikar klisede

Ardindan yine gunlerce arama

Bekle huzura ersin yuregin

Hic susma sesimi ozlemissin

Dinin butun, ben dusman gozunde

Sen bu aska dur diyemezsin

Sende insansin, haklisin

Yeni ay gelince karanliklardasin

Ben bastan cikaran gunahkar

Sen hakimiyetsiz dindarsin', 'Ozur diliyorsun yeniden Sende insansin, haklisin Ben bastan cikaran gunahkar Sen hakimiyetsiz dindarsin Once kac kuytulara Sonra kalalim kar...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunahtan-kacamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimlik Opusmeler', 'mevsimlik-opusmeler-neslihan-ayakta-u3e1h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevsim degisiyor

Kelebekler son gunlerini yasiyordu

Dugunleri animsatiyordu yaz sonu

Bir kosusturmaca, bir kalabalik

Kelebekler salina salina ucusuyor

Gelin oluyorlardi mevsime

Bitiyordu ozgurlukleri

Yalnizlikti ortak yanlarimizdan biri

Ve yapayalniz kalmak yetiryordu askimiz icin

Kalmiyordu ask opusmeler uzayinca

Beden oluyorduk sadece

Unutuyorduk kalplerimizi

Biribirimize asik oldugumuz yuzlerimiz

Hic gormedigimiz sekillere burunuyordu

Korkuyor muyduk yoksa yabanciliyor muyduk

Bir yabanciyi mi opuyorduk acaba

Mevsim degisiyordu

Kelebek oluyorduk

Son gunlerimizi yasiyor

Gelin damat oluyorduk 

Mevsimlik duslerimizde

Sonra beden oluyorduk

Yabancilasiyorduk opuslerde', 'Mevsim degisiyor Kelebekler son gunlerini yasiyordu Dugunleri animsatiyordu yaz sonu Bir kosusturmaca, bir kalabalik Kelebekler salina salin...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mevsimlik-opusmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Bes Duyuyla', 'sevmek-bes-duyuyla-neslihan-ayakta-yn336', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kelimelerimi sevmiyorum

Satirlarima dusmediginde

Bir doyumsuzluk var damagimda

Ve dokunuslari eksik hislerimin

Doku, duy,tat, kokla ve gor

Bes duyuyla seviliyor hayat

Eksikleriyle yasanilabildigi gibi yasaniyor

Ayakta kaliyorum

Ve kalan hislerim gucleniyor

Daha net goruyorum zamanla

Ama dokunamiyorum

Dokunuyor zaman zaman duygularima

Kokularin pesine dustugum oluyor 

Hayvansal taraflarimla

Hislerimde hic yanilmiyorum

Sadece duygularima dokunuyor

Bulamadiklarim, dokunamadiklarim

Bes duyuyla seviyor

Eksiklerimle sevilebilir miyim

Yasanilabildigim gibi

Ihtimaller doguyor doyumsuzluklarimizdan

Gozlerim kapaliyken sahip oldugum renklere

Dokunabilmek ve kokusunu aldigim o varligi 

Tatmak istiyorum.', 'Kelimelerimi sevmiyorum Satirlarima dusmediginde Bir doyumsuzluk var damagimda Ve dokunuslari eksik hislerimin Doku, duy,tat, kokla ve gor B...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevmek-bes-duyuyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldim Istanbul', 'geldim-istanbul-neslihan-ayakta-9pfog', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir seni boylesi kilan

Hangi rezaletini ozletiyorsun yine

Doyamiyorum sana

Nefretim olsan bile

Cikmiyor havan cigerlerimden

Yaptigin haksizliklar mi aglatiyor gozlerimi

Acitiyor yuregimi

Rezilsin Istanbul

Parcaliyorsun herseyi', 'Nedir seni boylesi kilan Hangi rezaletini ozletiyorsun yine Doyamiyorum sana Nefretim olsan bile Cikmiyor havan cigerlerimden Yaptigin haksi...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/geldim-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sehvet', 'sehvet-neslihan-ayakta-sueid', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanliklara renkler sacan yar

gunle ne gercekler aciga cikar

sevgi mevsimsiz bir yabani ot

koparma, daha cok biter

yaklasma belki de zehirler

uzaktan kokusu mayhos eder

sevmek buyuk magrifet

bilinmiyor degeri

sorgusuzca yurek dinlense

yitmez belki heyecani, sehveti

nasil buyuler o sehvet iksiri

tenden yayilan koku

gozlere yayilmis pariltilar

agizdan dokulen buyulu tonlar

neden gorunmez o hinzirin gercek yuzu

eller sessizlige burunur

dokunmak, tatmak, yazmak istemez

gozlerden suzulen damla ile

kan kirmizi guller biter siirlerde', 'Karanliklara renkler sacan yar gunle ne gercekler aciga cikar sevgi mevsimsiz bir yabani ot koparma, daha cok biter yaklasma belki de zehirl...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sehvet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıntı', 'kirinti-volkan-cosgun-oa0ol', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen tam karşımda, 

masamda...

öylece duruyor olsa masa...

o taze bakışı yok mu bayatlığının,

burada sensiz olmaktansa,

orada sensiz olamamak,

kör bir bıçak altında,

o taze inadı olmak bayatlığının...

...

sen bayatın tazeliğinde,

taze kalmaya çalışan son kırıntım,

benimsin ya,

acıt beni acıtabildiğin kadar,

şimdi yine sonsuzluğa ''şerefe'',

korkusuzca beraberliğimize,

ama gün gelir,

sakın korkma,

zaman öğretecektir ufalanmayı,

yabancı değilsin sen bu masaya,

alışırsın benim gibi Bir yokluğa,

yine de bir daha yok olmak üzere masamda varol!', 'sen tam karşımda,  masamda... öylece duruyor olsa masa... o taze bakışı yok mu bayatlığının, burada sensiz olmaktansa, orada sensiz olamamak...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kirinti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırılçıplak', 'cirilciplak-volkan-cosgun-fz685', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'masada sevişmiştik sevgilim düngece,

hatırlasana...

masada çıplak bir sen,

ve çıplak ayrılık mektubun,

ben ise çırılçıplak...', 'masada sevişmiştik sevgilim düngece, hatırlasana... masada çıplak bir sen, ve çıplak ayrılık mektubun, ben ise çırılçıplak......', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cirilciplak-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar', 'i-ntihar-volkan-cosgun-7o3kd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uçurumun kenarında masumiyet,

yükseklik kadar günahlık,

dibinde seni bekleyen bir melek,

kendini atmaya yeltenişin,

aslında korkmak,

doyasıya canına okumak korkuyla geçmişin...

...bir adım daha yaklaştın şimdi...

...boşluğun dumanı ciğerlerinde...

...hazırsın...

...hadi atla...', 'uçurumun kenarında masumiyet, yükseklik kadar günahlık, dibinde seni bekleyen bir melek, kendini atmaya yeltenişin, aslında korkmak, doyasıy...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/intihar-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Perde', 'son-perde-volkan-cosgun-6sux7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'terkedişinden sonra resmini yine de

odamın en güzel köşesine koydum,

kalbini de sakladığım yerde...

öyle bir hüzün çöktü ki içime,

önce ışıkları kapattım,

sonra hayata gözlerimi...', 'terkedişinden sonra resmini yine de odamın en güzel köşesine koydum, kalbini de sakladığım yerde... öyle bir hüzün çöktü ki içime, önce ışık...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/son-perde-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bomboş Kalabalık', 'bombos-kalabalik-volkan-cosgun-6vp6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir sokak bomboşken,

bomboş bir ben,

o bomboş sokakta ağladı durdu,

bomboş sokağın kalabalığını ararken...

etrafı da kalabalıktı halbuki

ama sokak kadar bomboş bir kalabalık,

o an gözyaşımı seyreden...', 'bir sokak bomboşken, bomboş bir ben, o bomboş sokakta ağladı durdu, bomboş sokağın kalabalığını ararken... etrafı da kalabalıktı halbuki ama...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bombos-kalabalik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek Ve Güneş', 'cicek-ve-gunes-volkan-cosgun-cotot', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zamanı gelmeden açan çiçek,

döküyor yapraklarını güneşe,

öyle ışıldıyor ki güneş,

öyle mis ki çiçeğin aşkı,

ama birden aşk bitiveriyor,

sonra çiçek sana solmayı öğretiyor,

güneş te için için yanmayı...', 'zamanı gelmeden açan çiçek, döküyor yapraklarını güneşe, öyle ışıldıyor ki güneş, öyle mis ki çiçeğin aşkı, ama birden aşk bitiveriyor, sonr...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cicek-ve-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorsun', 'korkuyorsun-volkan-cosgun-u2a2j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'senin,

doğru zaman adı altında,

saklamaya çalıştıkların,

sadece,

çelişkilerin,

ve SADEce yılgınlıkların,

ve hatta çılgınlıkların...

aslında sen,

sevmekten korkuyorsun...', 'senin, doğru zaman adı altında, saklamaya çalıştıkların, sadece, çelişkilerin, ve SADEce yılgınlıkların, ve hatta çılgınlıkların... aslında ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/korkuyorsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şeyler', 'bir-seyler-volkan-cosgun-jloi4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir yerde,

biriyle,

bir şeyleri 

paylaştım,

paylaşılanları,

bir yerde,

biriyle

harcadım,

harcananlar,

bir yerde,

biriyle,

bir şeylere 

gömüldü...

sonra

Bir şeyler acı verdi,

gömülenlerde...', 'bir yerde, biriyle, bir şeyleri  paylaştım, paylaşılanları, bir yerde, biriyle harcadım, harcananlar, bir yerde, biriyle, bir şeylere  gömül...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-seyler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-volkan-cosgun-x2d9q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'verilen kararlar ''son''sa,

dönüş olmamalı asla,

alınan kararlarda asla dönüş yoksa,

o zaman ''son'', son bulmalı,

verilmiş kararlardaki ''son''larda...', 'verilen kararlar ''son''sa, dönüş olmamalı asla, alınan kararlarda asla dönüş yoksa, o zaman ''son'', son bulmalı, verilmiş kararlardaki ''son''la...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüklük, ''Büyü de Gel'' der Gibi', 'buyukluk-buyu-de-gel-der-gibi-volkan-cosgun-28pfn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul ağlarken,

İzmir''in sesi hiç ama hiç duyulmaz,

mutsuzluk bile büyüklere...', 'İstanbul ağlarken, İzmir''in sesi hiç ama hiç duyulmaz, mutsuzluk bile büyüklere......', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/buyukluk-buyu-de-gel-der-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Gidenler', 'gidenler-umit-kilislioglu-ozger-4zc1p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dosttular, fidandılar, yiğittiler

Kapımızdan şöyle bir baktılar,

Sonra çekip, gittiler.

Gülümsemeleri kaldı, kokuları, ayak sesleri,

Nefesleri kaldı.

Çok yanıldık, çok öğrendik, 

Ne zaman yenildik, ne zaman yendik? 

Kâh isyan ettiler, kâh başlarını eğdiler

Onlar tam da bize göreydiler.

Ne iyiydiler! , ne hoştular! 

Tutamadık....

Son sürat,

Yıldızlara koştular.

(11.Mart.2004)', 'Dosttular, fidandılar, yiğittiler Kapımızdan şöyle bir baktılar, Sonra çekip, gittiler. Gülümsemeleri kaldı, kokuları, ayak sesleri, Nefesle...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gidenler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fenomena', 'fenomena-volkan-cosgun-ncl8t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yeni talar yeni hayatlar...

bir gece başlayan yaşamlar...

kendimi bulduğum sende yeni bir ben...

hayat bir akış, 

ama sonu ve başı nerede olduğu asla bilnmeyen...

bir ritim üzerinde yaşanan her şey,

o akışta bir sonsuzluk:

ama varı veyoğu çoktan bilinen bir bilinirlik...

bir düzlem üzerinde sıraladığımız yalanlar,

çoğul olmak,

ama aynı zaman da Bir olmak...

tadı damağında hissetmek,

nefes alırken belki de ölmenin ne demek olduğunu,

ve nefes verirken,

ölümsüzlüğün ne anlama geldiğinin farkına varmak...

uyuşuk beyinlerle yalancı sevişmeler...

...her şey ama her şey hayatta,

ve hayat kendi içinde olmayan bir yalan,

ve onun ecza reçetesi kabarık bir türlü alışamadığım kainat...

ve.

ve..

ve...', 'yeni talar yeni hayatlar... bir gece başlayan yaşamlar... kendimi bulduğum sende yeni bir ben... hayat bir akış,  ama sonu ve başı nerede ol...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/fenomena-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Kâzım Abi''ye (Hiciv)', 'k-zim-abi-ye-hiciv-mustafa-engin-karatay-n2kgh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Oberhausen''de ikâmet eden Kâzım Can Erdinç''e)  

Kâzım Abi, biri bize lâf atmış 

Tereciye hardal otunu satmış 

Martavalı sıralayıp anlatmış 

Tosladı bilmeden çetin cevize 

Karıştırmış sermâyenin rengini 

Toy belledi anlaşılan Engin''i 

Bulacaktır bir gün kendi dengini 

Kafiye fakiri, kuramaz dize 

Parselli sahada varsa yerimiz 

Bir bilelim, kimdir yeni-çerimiz? 

Serden geçtik, yüzülse de derimiz 

Ders verecek vaktimiz yok âcize 

Âkif''in, Üstâd''ın sözü mayamız 

Kurt ulutmaz, perçinlidir sayamız 

Sarp yerdedir, meşhûr Yalçın Kaya''mız 

Sakarya menşe''li, şecaat bize 

Çocuk dendik, bu iş yaştadır demek 

Lâftan evlâdır, büyük lokma yemek 

Bir kâğıda, On Dakîka''dır emek 

Devâm etsin turşu ile perhize 

İmamlık ayrı iş, şâirlik başka 

Tutulmuş zavallım, hayâl-i aşka 

Her kese harç değil, farklı, bambaşka 

Hollanda''da çokça bakmış denize 

Tavsiyeyi sen yap O''na istersen... 

Yiğidin yerini, tutup göstersen, 

Ârûz vezni ile nasihât versen, 

Odaklanır belki bizim merkeze 

Pöstekiden el atar uzaklara, 

Koyunsuz Meydan''da, çelebi ara! .. 

Yol vermeyiz Abdurrahmanlar''a, 

Eli yanar, niye uzatır köze? 

Gözlerim kapalı, bu tür hışıma 

Aldırma feverânlı çıkışıma... 

Sükût elzem, gün görmemiş yaşıma 

En''âniyyet fayda vermez ki öze... 

İşimiz çook, yolumuz da uzunca... 

Kemerleri kuşanın ben yazınca! .. 

Oynamam ki, şimdi her kes kızınca,   :))   

Tebessümlü olmak gerek her yüze... 

19.08.2000 Landsberg 14:40', '(Oberhausen''de ikâmet eden Kâzım Can Erdinç''e)   Kâzım Abi, biri bize lâf atmış  Tereciye hardal otunu satmış  Martavalı sıralayıp anlatmış ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kazim-abi-ye-hiciv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '? Nasıl Bilirdiniz?', 'nasil-bilirdiniz-recep-onal-wnpsk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Makam mevki için kendinden geçip

İncelikleri hakkında dersler alırdı

Sanatını alenen icra etseydi

Diplomalı dansözler işsiz kalırdı', 'Makam mevki için kendinden geçip İncelikleri hakkında dersler alırdı Sanatını alenen icra etseydi Diplomalı dansözler işsiz kalırdı...', ARRAY['Türk Edebiyatı','Şiir','Recep Önal']::text[], 8.5, '{"poet":"Recep Önal","poet_slug":"recep-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nasil-bilirdiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-halil-i-brahim-ozdemir-2dbbz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölen bir arkadaşım için...

Bir tohum toprakta çatladı gitti

Kara bir trene atladı gitti.

Sağnak sağnak  hüzün üstüme yağan

Acıyı,  dörtlere katladı gitti.', 'Ölen bir arkadaşım için... Bir tohum toprakta çatladı gitti Kara bir trene atladı gitti. Sağnak sağnak  hüzün üstüme yağan Acıyı,  dörtlere ...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/giderken-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şarkım var sana', 'bir-sarkim-var-sana-ali-osman-yilmaz-du78c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şarkım var sana,

Ruhumun en derinlerinde,

Sözcüklerden elbisesini,

Henüz giyinmemiş,

Bir şarkım var sana,

Tohumları yüreğimde çiçek açmış,

Henüz yazılmamış kağıtlara,

Pembe aşk peleriniyle dolanır,

Duygularımda yumuşacık,

Her an mırıldanır,söylerim sana,

Henüz söylenmeyecek,

Dilimden sana,

Bak iç çekişlerimde,duyacaksın,

Şarkımı senden başka,

Kime söyleyeceğim ki? 

Senden başka kim anlayabilir,

Aşkımın şarkısının anlamını,

Sağır kulaklar duyamaz beni,

Şimdilik sessizliğe gönderdiğim,

Yalnızlığımın şarkısı o,

Rüyalarımda, ki, seninle dolu,

Sözleri seslenir herkese,

Ey insanlar bu şarkı,

Benim aşkımın şarkısıdır,

Duyunca söyleyecek,

Tüm sevenler,sevdiklerine,

Aşıkların aşkını anlatan,

Tarihe miras kalacak,

Bir kitabe gibi daima,

Tüm gönüllerde saklanacak,

Bir şarkım var sana.', 'Bir şarkım var sana, Ruhumun en derinlerinde, Sözcüklerden elbisesini, Henüz giyinmemiş, Bir şarkım var sana, Tohumları yüreğimde çiçek açmı...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-sarkim-var-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapishane', 'hapishane-halil-i-brahim-ozdemir-p8iv6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dört beton, dört duvar, kapı demirden

	Bir nur ku yağıyor ilahi yerden

	Ranzalar arasına sıkılmış kurşun gibi

	Çarpar dört yana başlar yaralı kuştur sanki

	İnce bir ışık ki penceremden süzüldü

	Tutundum o iplğe bütün sırlar çözüldü...

	İçimde yer etmeyen işte sonsuz hakikat

	Ey Yusuf geliyorum yakınına kat be kat

	Gönlüme hüznün girmemiştir zerresi

	Mahpusun hakikat ey öteler ötesi

	İnce bir sızı aldı yüreğimi yeniden

	Nuh olsun kaptanın ki kurtulasın gemiden

	Işık artık ne gözümde ne de yeryüzündedir

	Güneşi güneş yapan şimdi tam özümdedir.', 'Dört beton, dört duvar, kapı demirden 	Bir nur ku yağıyor ilahi yerden 	Ranzalar arasına sıkılmış kurşun gibi 	Çarpar dört yana başlar yaral...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hapishane-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır zincirlerini...', 'kir-zincirlerini-nergis-demet-oyiy2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'önce zincirlerini kırmalısın, 

seni, 

sen olmaktan alıkoyan. 

kendi kendine, 

halka halka oluşturduğun, 

zincirlerini. 

koyduğun kuralları yıkmalısın, 

seni mutlu olmaktan, 

özgür olmaktan alıkoyan, 

sonra da... 

uçmayı öğrenmelisin, 

hayal dünyasına, 

gerçeklere doğru. 

engellerini aşmalısın bir bir, 

seni İNSAN olmaktan alıkoyan...', 'önce zincirlerini kırmalısın,  seni,  sen olmaktan alıkoyan.  kendi kendine,  halka halka oluşturduğun,  zincirlerini.  koyduğun kuralları y...', ARRAY['Türk Edebiyatı','Şiir','Nergis Demet']::text[], 8.5, '{"poet":"Nergis Demet","poet_slug":"nergis-demet","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kir-zincirlerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '&&&&& Yine Yoksun &&&&&', 'yine-yoksun-i-brahim-dikmen-2-vha24', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yarim sensiz,mevsim hazan,

Sensizlik ah! yaram_ı dağlar.

Yine yoksun,boş kollarım,

Ağlıyorsam,sebebi var.

Yıldızlar kadar uzaksın, 

Ah! şimdi bomboş kollarım.

Acı dolu,hüzün dolu,

Sensiz geçen yar, yıllarım.

Yarim, benden uzaklarda,

Mutlumusun,o adamla.

Yoksa,hep ağlıyormusun,

Kalbin kalmış sol yanımda.

Yıldızlar kadar uzaksın,

Ah! şimdi bomboş kollarım.

Acı dolu,hüzün dolu,

Sensiz geçen yar  yıllarım.', 'Yarim sensiz,mevsim hazan, Sensizlik ah! yaram_ı dağlar. Yine yoksun,boş kollarım, Ağlıyorsam,sebebi var. Yıldızlar kadar uzaksın,  Ah! şimd...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-yoksun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niyet', 'niyet-sair-ahrazi-yxx1u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsimsiz tohumu toprağa diktim, 

Özünün çıkması kırk gün sürmedi, 

Niyeti üzeri insanı ektim, 

İsmine benzeyen bir dal vermedi. 

* * * * 

Kim Kime yakın 

Bende sana anlatacak ''''Sen'''' varda, 

Sen anlat bana,sendeki ''''Ben'''' nerde?', 'İsimsiz tohumu toprağa diktim,  Özünün çıkması kırk gün sürmedi,  Niyeti üzeri insanı ektim,  İsmine benzeyen bir dal vermedi.  * * * *  Kim...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/niyet-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yıl Sevgililer Gününde', 'her-yil-sevgililer-gununde-i-brahim-dikmen-2-itj53', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her yıl,sevgililer gününde,

Seni bekledim,herzamanki o''yerde.

Yoksun ah,biliyorum gelmeyeceksin,

Öksüz kaldım sevgilim,çiçeklerimle.

Birdemet kırmızı gül,ve kasımpatı,

Benimle beraber,sensizliğe ağladı.

Yoksun ah,biliyorum gelmeyeceksin,

Akan yaşlar seloldu,ırmak gibi çağladı.

Her yıl,sevgililer gününde,

Seni aradım,saklandığın o''yerde.

Yoksun ah,biliyorum gelmeyeceksin,

Yaşamak inan zor,aşkım özleminle.', 'Her yıl,sevgililer gününde, Seni bekledim,herzamanki o''yerde. Yoksun ah,biliyorum gelmeyeceksin, Öksüz kaldım sevgilim,çiçeklerimle. Birdeme...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-yil-sevgililer-gununde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Limon Çiçeği', 'limon-cicegi-orhun-basat-ytjd1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'l 

ben yoktum gözlerindeki yağmurlarda, 

devingen bir ruhtum / ve susturulmuştum 

yalnız sokakların, 

unutulmuş sabahlarında.. 

yalındı adımlarım.. 

ya da başka biriydim, 

iz düşümlerinde gözlerinin 

ve ıslak kedi gölgelerimin.. 

bir uzak, bir sıcak özlem.. 

bir yakın, bir soğuk ölüm.. 

her kapıda izin vardı, 

her camda sana yazılı dizeler, 

neyi yaşıyordum, bilemedim. 

gece değildi, kış hiç değil, 

okşamaların bahardı / bu yüzden / 

limon çiçeği kokuyor hala tenim... 

fırtına dilli bulutlar dokunduğunda bir geceye, 

oynak bir fay gibi, 

coğrafyanda gezinmişti ellerim, 

ellerimi sende bıraktım. 

gece sızıp, gün bir cemre gibi düştüğünde yatağa, 

ve giyinip çıktığında, 

açık kalmıştı gecenin gözleri, 

kapadım.. 

ll 

takma kafanı, benim gözlüm; 

birkaç kadeh içtim de seni düşünüp, 

ondan bu denli deli akıyor 

bu vurgun adamın kanı.. 

çünkü çok zor be, güzelim, 

küçültüp, 

bir bakışına sığdırabilmek zamanı..', 'l  ben yoktum gözlerindeki yağmurlarda,  devingen bir ruhtum / ve susturulmuştum  yalnız sokakların,  unutulmuş sabahlarında..  yalındı adım...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/limon-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Aşk Hırsızım', 'sen-ask-hirsizim-i-brahim-dikmen-2-ala9k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen, benim yüreğimde, gönül sızımsın,

Kalbimi, benden çalan, sen aşk hırsızım.

Sensiz bir ömür, söyle nasıl geçecek,

Taparcasına sana, nasıl bağlandım.

Yüreğimde yanan,sevda ateşi,

Gecelerimde hep, güneş gibisin.

Beni, benden çalan, bir aşk perisi,

Düşlerimde gezen, melek gibisin.

Sen, benim sevdiğim, sen aşk iksirim,

Sen, benim kalbimin, tek sahibisin.', 'Sen, benim yüreğimde, gönül sızımsın, Kalbimi, benden çalan, sen aşk hırsızım. Sensiz bir ömür, söyle nasıl geçecek, Taparcasına sana, nasıl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ask-hirsizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Ve Gerçekliğin', 've-gercekligin-tolga-yildiz-mfib6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüzüne vuran rüzgar ne kadar gerçek

Ya eline aldığın gülün dikeni

Oturduğun sandalye, çalıştığın bilgisayarın

Yediğin yemek, ANNEN

Sevginin gerçekliği neyse

Babanla kavgaların, kardeşine hislerin

Köpeğin

Dostun sana ne kadar gerçek dostsa

Düşündüklerin ve yaptıkların sana ne kadar gerçek geliyorsa

AŞKIN gerçekliği senin için ne ise

Sen de benim o kadar GERÇEĞİMSİN.', 'Yüzüne vuran rüzgar ne kadar gerçek Ya eline aldığın gülün dikeni Oturduğun sandalye, çalıştığın bilgisayarın Yediğin yemek, ANNEN Sevginin ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Yıldız']::text[], 8.5, '{"poet":"Tolga Yıldız","poet_slug":"tolga-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ve-gercekligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut ve Geceye Dair', 'umut-ve-geceye-dair-tolga-yildiz-uncpt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki bir gün

Bir gün diyorum

Hani şöyle bir araya geldiğimizde

Ellerini tutup sımsıkı

Gözlerine bakacağım, gözlerimi yerden kaldırıp usulca

Bir gün geldiğimde

Umuda bulanmış yüreğimi

Al diyeceğim al o artık senin

İster at okyanusun tam ortasına kimse duymasın, bilmesin

İstersen çık meydanlara bağır

Hey! Bakın bakın işte bu benim

Ve ben kazandım diye ekle

Bekle küçüğüm bekle

Geleceğim umut ikliminin en sonsuz maviliğiyle

Ve “SEVGİ” her şeyin üstünde olacak.', 'Belki bir gün Bir gün diyorum Hani şöyle bir araya geldiğimizde Ellerini tutup sımsıkı Gözlerine bakacağım, gözlerimi yerden kaldırıp usulca...', ARRAY['Türk Edebiyatı','Şiir','Tolga Yıldız']::text[], 8.5, '{"poet":"Tolga Yıldız","poet_slug":"tolga-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umut-ve-geceye-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her yer Aynı!', 'her-yer-ayni-naime-erlacin-0y7mu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kalk gidelim 

gidelim ezik yüreğim

kısıldı hayaller

köşe başında köpek leşleri

bedenler güya canlı

bir yer olmalı

bir yer olmalı mutlaka her yerden farklı

boynumdaki ilmek sıkıyor beni

gündüze karıştı gece

tenim dağlanıyor

bu ne bu! 

bir yer olmalı 

dağ mı 

deniz mi 

kelebeğin kanadı mı

ne önemi var adresin

her yer aynı

kestim başımı! 

(11 Mart 2004)', 'kalk gidelim  gidelim ezik yüreğim kısıldı hayaller köşe başında köpek leşleri bedenler güya canlı bir yer olmalı bir yer olmalı mutlaka her...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/her-yer-ayni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dans', 'dans-tolga-yildiz-dek99', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin maviliğinde

Bir sen bir de hayalin

Ellerin ne hoş, ne yumuşak

Usulca omuzlarımdaki yerini alıyor

Belin ne kadar kıvrak, nazik

Ellerim belinde konuşlanıyor.

Sözlerin ne kadar sıcak

Ta... yüreğinden çağlayan

Gülüşünü hissediyorum

Duru, temiz

Ve radyo, dans ettiğimiz

O son günün şarkısıyla çınlıyor.

Dans ediyoruz.

Önce ayaklarımız usulca ritme uyuyor.

Daha sonra ruhların asiliği

Sonrasında dans dudaklarında bitiyor

Öyle güzel

Öyle istekli.', 'Gecenin maviliğinde Bir sen bir de hayalin Ellerin ne hoş, ne yumuşak Usulca omuzlarımdaki yerini alıyor Belin ne kadar kıvrak, nazik Elleri...', ARRAY['Türk Edebiyatı','Şiir','Tolga Yıldız']::text[], 8.5, '{"poet":"Tolga Yıldız","poet_slug":"tolga-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dans-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürpriz', 'surpriz-tolga-yildiz-z6aze', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen oturup da düşünürsün

Hayatını, yarınını, insanları

Ya bir anda biter kapkara film

Ya da Love Story ile çınlar kulakların

Yakaladıysan aşkın güzel hikayesini

Hayat sana bütün sürprizlerini sırasıyla veriyor

Hele sürprizlerin arasında hayatının insanı varsa

Değmesin kimse keyfine

Ama öyle de salıverme

Sürpriz bu, aniden gelir

Sen elinde tutmayı bilmezsen

Bir anda geldiği yere (puf...)', 'Bazen oturup da düşünürsün Hayatını, yarınını, insanları Ya bir anda biter kapkara film Ya da Love Story ile çınlar kulakların Yakaladıysan ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Yıldız']::text[], 8.5, '{"poet":"Tolga Yıldız","poet_slug":"tolga-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/surpriz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehirde Sen Benimle Değilsin', 'bu-sehirde-sen-benimle-degilsin-tolga-yildiz-6f67g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derdin benden değil bilirim

Bu hava, bu koku bu yollar seni mahvetti

Sen beni üzmezsin bilirim

Bu ışık, bu hasret, bu şehir seni değiştirdi.

Bu şehir uzak sana

Bu hava, bu deniz

Ne yakışır sana

Sana nasıl sevdirsem bu şehri

Desem ki dört yanı dağ

Dört yanı deniz

Caddeler var desem

Tek yürek çarpan

Sevdaların yürüdüğü

En derin aşkların yaşandığı

Yoluna candan geçilmiş

Güzellikleri var desem

Sana nasıl sevdirsem bu şehri

Bilirim sevmezsin

Bu şehirde sen benimle değilsin.', 'Derdin benden değil bilirim Bu hava, bu koku bu yollar seni mahvetti Sen beni üzmezsin bilirim Bu ışık, bu hasret, bu şehir seni değiştirdi....', ARRAY['Türk Edebiyatı','Şiir','Tolga Yıldız']::text[], 8.5, '{"poet":"Tolga Yıldız","poet_slug":"tolga-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-sehirde-sen-benimle-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Aramızda', 'var-aramizda-hilal-sayil-0jppd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kal Diyorsun 

Kalamam Ben 

Sen Gelsen

Sende Gelemezsin 

Ben Gelsem Bende Gelemem 

Ayrılık Var Aramızda 

Km''ler Var Aramızda 

Sevgi Var Aramızda 

Hayaller ve Rüyalar Var Aramızda

Aşk Var Aramızda

Görüşemeyiz Belki

Keşke Görüşebilsek', 'Kal Diyorsun  Kalamam Ben  Sen Gelsen Sende Gelemezsin  Ben Gelsem Bende Gelemem  Ayrılık Var Aramızda  Km''ler Var Aramızda  Sevgi Var Aramı...', ARRAY['Türk Edebiyatı','Şiir','Hilal Sayıl']::text[], 8.5, '{"poet":"Hilal Sayıl","poet_slug":"hilal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/var-aramizda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Sevgisi-3-*', 'i-stanbul-sevgisi-3-bayram-tunca-ziexn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kiminin ilk kiminin son durağı

Mazisi gizemli bir film yumağı

Tanık olmuştur onca dramları

Konuk etmiştir nice sultanları

Şu İstanbul ne büyük bir metropol 

Onda yaşamak için lazım güçlü kol 

Onsuz yaşamaksa, daha da bir zor 

Her ayrıldığımda hasreti olur akkor 

Bence, İstanbul’da yaşamak bir tutku 

Onu görenlerin nedense tutulur nutku 

Aç açık da olsa olur insan onda mutlu 

Şu İstanbul’da yaşayanlar ne de kutlu 

En homojen insan mozaği İstanbul’da

Her şeyin iyisi, kötüsü var İstanbul’da

Elbette cezbeden bir hikmet var bunda

Nice aşık maşuklar yaşamaktadır Onda

08.03.2004-08.08', 'Kiminin ilk kiminin son durağı Mazisi gizemli bir film yumağı Tanık olmuştur onca dramları Konuk etmiştir nice sultanları Şu İstanbul ne büy...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/istanbul-sevgisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşşek Şakası', 'essek-sakasi-ozan-ozel-xgu8k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni hiç sevmiyorum

Hatta tiksiniyorum

Dokunmak istemiyorum sana

Gözlerimin ahengini bozuyorsun

Anlayacağın seninle mutsuzum

Gelecekten umutsuzum

Sana aldığım güller için yanıyorum

Ne kadar da çok para harcamışım boş yere

Tanışma günümüz neydi sahi? 

Ne o bana kızıyor musun? 

Kızma! Anla işte şaka yapıyorum...', 'Seni hiç sevmiyorum Hatta tiksiniyorum Dokunmak istemiyorum sana Gözlerimin ahengini bozuyorsun Anlayacağın seninle mutsuzum Gelecekten umut...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/essek-sakasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-hilal-sayil-7pgot', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen Beni Üzdün Ağlattın 

Allah''ta Seni Ağlatsın 

Mutlu Olma 

Gün Yüzü Görme 

Açılan Kapılar Yüzüne Kapansın 

Sevgilisiz Kal 

Sevgilisiz Deli Gibi Dolaşırkan Sokaklarda 

Belki Belki Beni Hatırlarsın 

O Zaman O Zaman Hatanı Anlarsın Umarım', 'Sen Beni Üzdün Ağlattın  Allah''ta Seni Ağlatsın  Mutlu Olma  Gün Yüzü Görme  Açılan Kapılar Yüzüne Kapansın  Sevgilisiz Kal  Sevgilisiz Deli...', ARRAY['Türk Edebiyatı','Şiir','Hilal Sayıl']::text[], 8.5, '{"poet":"Hilal Sayıl","poet_slug":"hilal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beddua-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazsan, Yazsan Kaç Yazarsın', 'yazsan-yazsan-kac-yazarsin-bekir-mutlu-gokcesu-mw9kc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hey koca dünya

Üstüme gelsen

Tüm heybetinle

Ben de sussam

Ve böylece dursam

Sana en layık

Direnişimle

Şu zerre halimle

Yazsan, yazsan

Kaç yazarsın sen bana

Aklımca okurum anca 

Ayakların da kocaman

Amma

Bassan, bassan

Kaç basarsın sen bana

Gücün yeter, dişin geçer 

Amma 

Aklımın bastığı

Cismimin, canımın

Acıdığı kadarına...

Alsan, alsan

Neyim alacaksın

Bir nefesse

İstedik ki özgürce uçsun

Hiç olmazsa şu kafeste

Şahidimdir şiirler

Sana hep sevgi türetmekte

Fakat sen durulmuyorsun

Hep yazıyorsun da

Hiç okumuyorsun

Alıştık fırıl, fırıl dönüşüne

Amma 

Hasret koyuyorsun gülüşüne

Oysa misafirdik biz sana...

Alsan, alsan

Neyim alacaksın

Bir nefesse

Zaten günbegün tükenmekte

Memnuniyetle...', 'Hey koca dünya Üstüme gelsen Tüm heybetinle Ben de sussam Ve böylece dursam Sana en layık Direnişimle Şu zerre halimle Yazsan, yazsan Kaç ya...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yazsan-yazsan-kac-yazarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçim', 'secim-ozan-ozel-nttic', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine geldi dayandı kapımıza seçim 

Eller açıldı vatandaşa oy hesabıyla 

Sözler pervasızca çıkıyor ağızlardan 

Yeni dönemin işbilir! adayları sabırsız 

Hizmet aşkıyla yanıp tutuşuyor! 

Herkes ayrı tarafından bakıyor 

Aday diye ortaya çıkanları vatandaş tanımıyor 

Geçmişini bilenler, geleceği görüyor 

Gidenler yedi gitti, gelenler ne yapacak? 

Vatandaş yine mi ahlanıp vahlanacak?', 'Yine geldi dayandı kapımıza seçim  Eller açıldı vatandaşa oy hesabıyla  Sözler pervasızca çıkıyor ağızlardan  Yeni dönemin işbilir! adayları...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/secim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-hilal-sayil-dfccd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece Issız ve Karanlık Çok Geç Bir Vakit 

Ben Dışarı Çıktım 

Sokaklarda Seni Arıyorum 

Belki Belki Görürüm Diye 

Sağıma, Soluma, Arkama, Önüme Bakıyorum

Belki Belki Görürüm Diye 

Sokalarda Koşuyorum 

Belki Belki Seni Yakalar ve Seni Sevdiğimi Söylerim Diye

Sağa, Sola Soruyorum

Belki Belki Tanıyan Çıkarda Nereye Gittiğini Bilir Diye

Herkes Tanıyor 

Ama Nerede Olduğunu Bilmiyor 

Ben Biliyorum Nerde Olduğunu 

Sen Benim Kalbimdesin Gözbebeğim', 'Gece Issız ve Karanlık Çok Geç Bir Vakit  Ben Dışarı Çıktım  Sokaklarda Seni Arıyorum  Belki Belki Görürüm Diye  Sağıma, Soluma, Arkama, Önü...', ARRAY['Türk Edebiyatı','Şiir','Hilal Sayıl']::text[], 8.5, '{"poet":"Hilal Sayıl","poet_slug":"hilal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/belki-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Titanik', 'titanik-ali-aydin-j8xck', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pusulası bozuk, meçhule giden bir gemisin besbelli,

Darbeli gövdenle beyaz ırmaklar oluşturuyorsun arkanda,

Çıkardığın homurtularında yılların isyanları gizli,

Kaç limana yanaştın, ardında kaç sevgili bıraktın gözü yaşlı.

Pusulası bozuk, meçhule giden bir gemisin besbelli,

Böyle sessizce çekip gitmenden belli, aşklara yenik düştüğün.

Nerede son bulacak gayesiz yolculuğun, bilinmez! 

Belki de buzdağına çarpacaksın Titanik misali.

7 Mart 2004', 'Pusulası bozuk, meçhule giden bir gemisin besbelli, Darbeli gövdenle beyaz ırmaklar oluşturuyorsun arkanda, Çıkardığın homurtularında yıllar...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydın']::text[], 8.5, '{"poet":"Ali Aydın","poet_slug":"ali-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/titanik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suda Dolunay', 'suda-dolunay-reyhan-sur-m61b6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hasretlerini eğirip büken kirmanlarda

yakamozların desenlerinde öpüşen ikili

ayda ayna

gökyüzüne tutsak etmiş kendini

yıldızları toplar da şavkır şavkıtır delicesine

aynada ben buğulardaki çayımın demi

gözlerimden iç beni sevgili

bende sen sesimdeki armoni

sesim boynuma dolanan kanatlarında gizli..

ben sendeysem

beni sende bulursam

şafağına yakın umutlarımda

bende ayna,

açık eder yüreğimin kanayan rengini

sızıp gelirken kızıl bulutlarda

aynada ay

çiçeklenir gözlerimde büker boynunu

aya aşık günçiçekleri

ayda su

yorgun yaz sıcağında dolaşmaktan kumları

kış karından emdiği yalnızlığın sancısıyla dongun

sızar da sokulur toprağının koynuna 

yurt tutarken pöhrenkleri 

akar..akar... kıvrılarak sonsuzluğa

dolunaylı kavuşumlarda', 'hasretlerini eğirip büken kirmanlarda yakamozların desenlerinde öpüşen ikili ayda ayna gökyüzüne tutsak etmiş kendini yıldızları toplar da ş...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/suda-dolunay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felfelek', 'felfelek-sule-aydemir-34yyj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'zaman zamanın içinde

zaman  iken sen

karlardan süzülüp

çiçek tarhlarına

kelebek misali 

bir eflatun 

düştün ortasına

ağlayarak doğdun

isimler düşündüler

en son gelendin

söylemi damla

anlamı feyezan

dediler ki ''''Hakan''''

nice filiz ahulardan

toplayasın behreni

kucakla eksibe seneyi

kaderinin ana-hat çizgisini

güldür ağlatmadan

kır yaşamın keşkelerini

öyle bir yürü git ki 

deveranı olmadan 

...................................................................................................................................

_ kelebek 

____eflatun kanatlarını

______kuğunun beyaz boynunda bıraktı

____________________resimledi narince

______________________________ unuttu 

________________________________unutması bir saniye

__________________________________ bir başka eflatun gülümseyince

...................................................................................................................................', 'zaman zamanın içinde zaman  iken sen karlardan süzülüp çiçek tarhlarına kelebek misali  bir eflatun  düştün ortasına ağlayarak doğdun isimle...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/felfelek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Hükmünde', 'gunesin-hukmunde-naime-erlacin-h07h2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güneşle güneş olmak

bu yüzdendir güneşi sevmem

canhıraş bir zılgıtla zembereğin boşanması

aniden düşmesi yüzümün 

sırf zaruretten

güneş değince zümrüt yeşili olur yürek

_hanedanın yüz akı

__yüz karası

___alemin zadeganı insan ey! 

mührünü tartarak vur yüzüme

bin yıldır acılıdır bu yüz

çehremde yılların ceremesi

yol verme sakın! 

uğursuz delikte saklı yılan zehrine

güneşi boyamaktı niyetleri

tarihin tanıklığında vardı hedefe oklar

türkümüz 

kurbana yakılan aykırı ağıt

sorma gerisini 

eğreti ve yalnızdık

neydi menekşenin değeri:

- morla yeşil kucaklaşması -

anlamazdı ölü kent yabanileri

girilmezdi gözyaşının içine

vakur sesler suskun

can çekişirdi masumiyet

ihtişamlı ülkelerin konuğu değildik

muallak bir yangın avazındaydık biz

mahşeri rüzgar ruhuna çarpar adamın! 

yol kesen fırtınası adı bunun

_''konuş'' diyor yavru gezegen:

ibrişim sesinle haykır 

süz kalbini şahin gözlerinden

insansın çünkü

__güneşe borcun var

gözlerimi yitirdim Merkür

lanet olsun! 

içine ışık düşmemiş göz parlar mı ki? 

(11 Mart 2004)', 'güneşle güneş olmak bu yüzdendir güneşi sevmem canhıraş bir zılgıtla zembereğin boşanması aniden düşmesi yüzümün  sırf zaruretten güneş deği...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gunesin-hukmunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gidişler Neden?', 'bu-gidisler-neden-necmi-unsal-zkiw3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne  zaman  olsa  sılaya,  Türkiye’ye  sefer; 

Araba  küheylan  gibi,  altında  dört  teker.

Çıkıverdi  aniden  yola  Mustafa  Şeker.

Necmi,  Şekerlere  iyi  yolculuklar  diler.

Bir  akıncı  beyi  coşup  Belgrad’ı  geçti.

Kendisine  sıla  olarak  Sivas’ı  seçti.

Takım  tam  tekmil; bir er, bir hatun ve dört benât.

Çeker  arabayı  sanki,  yıldırım  dört bin  at.

Mışıl-mışıl  uyur  melek  kanadında  sabi.

Virajlar  ova  olur  inayetle  tabii.

Bu  gidişle  kesilmez  ters  akınların  ardı.

Taa  orada,  Danimarka’da  ne  işin  vardı? 

Diye  sorar,  İstanbul’da  yatan  fatih  deden.

Bu  gidişler  nereye,  ne  için  ve  neden? 

Gitti de  hiç  ses-soluk  çıkmadı  Sivaslıdan! 

Nasıl ki;  hiç  vazgeçmediyse  Kerem  Aslı’dan; 

Şeker de  eridi  gitti,  vuslata  erdi.

Havasına  girip,  unuttu  kederi  derdi.

Seni  şair  yaptı  Sivas’ın  o  meşhur  suyu! 

Kelimeler  bitmez,  şairlik  derin  bir  kuyu.

Ozanıyla  ünlü,  dünyada  Sivas’ın  adı.

Şeker’siz  kalmadı  burada  dünyanın  tadı.

Bitir  seyr-ü   seferi,  selametle  dön  geri.

Hazır  burada  Şekerin  o  muhteşem  yeri.

Keyfine  bak,  ye  etli  ekmeği  ve  döneri.

Kılıbıklık  sınırda  bitti,  bırak  son  eri! 

Temmuz 2003  Danimarka-Køge', 'Ne  zaman  olsa  sılaya,  Türkiye’ye  sefer;  Araba  küheylan  gibi,  altında  dört  teker. Çıkıverdi  aniden  yola  Mustafa  Şeker. Necmi, ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bu-gidisler-neden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Aşka Dolandı', 'gonlum-aska-dolandi-nevzat-bayramoglu-hurdemi-1b7zj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buğulu pencere önüne çöktüm 

Düşen damlaların kusuru gibi 

Daldım derinlere boynumu büktüm 

Maktu bir sevinin esiri gibi 

Gözleri o zaman başka yalandı 

Her bakışta gönlüm aşka dolandı 

İmgesi içimde uçan kelebek 

Haftalık bir ömür yaşarcasına 

Bakışı masumdu sanki bir bebek 

Yanaştı gönlüme koşarcasına 

Gözleri o zaman başka yalandı 

Her bakışta gönlüm aşka dolandı 

Savurup sallarken beni derinden 

Çıkışı olmayan o aşk dehlizi 

Hatıraydı bana duvar dibinden 

Alnımda beliren küpeşte izi 

Gözleri o zaman başka yalandı 

Her bakışta gönlüm aşka dolandı 

Hürdemi - 24 Şubat 2004 - Hasköy', 'Buğulu pencere önüne çöktüm  Düşen damlaların kusuru gibi  Daldım derinlere boynumu büktüm  Maktu bir sevinin esiri gibi  Gözleri o zaman ba...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Bayramoğlu Hürdemi']::text[], 8.5, '{"poet":"Nevzat Bayramoğlu Hürdemi","poet_slug":"nevzat-bayramoglu-hurdemi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gonlum-aska-bulandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siirler Kartal Kadar Özgürdür...', 'siirler-kartal-kadar-ozgurdur-hikmet-feridun-demir-i1jqr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siirlerim,

Özgür duygularimdir..

Bir Kartal kadar özgürdürler...

Özgür olmali Siirlerim....

Neden Siirlerimi,

Neden Duygularimi,

Esir Tüccarlarina teslim edeyim ki..! ! ! ! ! 

Ben kendime Hain miyim...

Sansür uygulayan Antoloji Yetkililerinden esinti...

11.03.2004

KÖLN-ALMANYA', 'Siirlerim, Özgür duygularimdir.. Bir Kartal kadar özgürdürler... Özgür olmali Siirlerim.... Neden Siirlerimi, Neden Duygularimi, Esir Tüccar...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siirler-kartal-kadar-ozgurdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günüm Bugün', 'dogum-gunum-bugun-hakki-hakan-kaya-x2u8k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yürürken 

basamaklarında hayatın

bir taş daha eklendi

geçmiş temel taşlarına

yanında 1,2,3 ler

gelip geçici misafirler

benimle birlikte yaşayacak

bir on sene daha

doğum günüm bugün

bizim bitişimiz 

benim başlangıcım

taze bir fidan gibi

uzanırken güneşe

kah filiz verdim 

tomurcuklandım

kah rüzgar kopardı dallarımı

uzandığım güneşten sarardım

fazla geldi sıcaklığı

bir kelebek kondu 

yeni filizlenen yaprağıma

güneşten sararmasın diye

kanatlarını gerdi

rüzgar koparmasın diye 

sımsıkı sarıverdi

bir sabah yok oluverdi

geride toz izleri

martı çığlığında

süprizi severdi

doğum günüm bugün 

hem gülüyorum 

hem ağlıyorum

zamanın içindeyken zaman

kanırtır paylaştığım

bizim bitişimiz 

benim başlangıcım...', 'yürürken  basamaklarında hayatın bir taş daha eklendi geçmiş temel taşlarına yanında 1,2,3 ler gelip geçici misafirler benimle birlikte yaşa...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dogum-gunum-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vapurda', 'vapurda-sirma-mersin-yq6dq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir vapurun güvertesinde...

Mavi beyaz dalgalarla dans eden, martıların süzülüşü ile,

köpük köpük hayallere dalarım.

Gecenin karanlığını dağıtan; inci inci parlayan adaların arasında, 

gidip geliyor ruhum...

Tatlı bir sevda rüzgarı! yüreğimi ürpertiyorken; kayan yıldızdan, seni getirmesini istiyorum.

Yakamozun büyüsüne takılıp; tüm yıldızları, kaydırsam yüreğime...

Gökyüzünü karanlığa bırakmışken! gelir misin? yanıma...

6.3.04', 'Bir vapurun güvertesinde... Mavi beyaz dalgalarla dans eden, martıların süzülüşü ile, köpük köpük hayallere dalarım. Gecenin karanlığını dağ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vapurda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum -1', 'seni-seviyorum-1-sirma-mersin-oamwf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dengesini kaybetmiş yürek! 

2 kelimenin arasına gizlediği duyguları ile; telafuz zor olan cümleleri birleştirmek isterken...

Suskunluğa düşer! 

Görmediği bir bakışla; hissettiklerini ifade edemez iken, zamanı bitirmişti.

Dili tutulmuş düşüncelerin içinde; söylemediği 2 kelime ise, birden bire çözülüverdi...

Öylesine! bir haykırışla yankılandı, yüreğin sesi...

SENİ SEVİYORUM...

Gölgen kaybolsada yüreğimden; seni sevmekten vazgeçmeyecek bu yürek! Bunu bil diye haykırdım sana...

Karanlığın tam ortasında; defalarca yankılanırken yüreğin sesi, sevginin gözyaşları boşaldı...

Karşılıksız sevmenin karşısında! 

Nede olsa yalnızdı, yürek...

7.3.04', 'Dengesini kaybetmiş yürek!  2 kelimenin arasına gizlediği duyguları ile; telafuz zor olan cümleleri birleştirmek isterken... Suskunluğa düşe...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-seviyorum-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusuf Olan Bulur Yusuf''u', 'yusuf-olan-bulur-yusuf-u-mehmet-husnu-asan-ksqbz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece neden se çok uzun 

Üstümüze güneş doğar mı bilmem 

Yusufun aşkı masum ki masum 

Kuyudan Yusuf çıkar mı bilmem

Bir züleyha aşık ki kendine

Züleyha yıldız gibi kaydı gönlüne

o karanlık kuyuya indi kendide

Kuyudan Yusuf çıkar mı bilmem

Bu gece o kuyu pek te bir derin

Başını taşlara vurma! hep derim 

Gönül kuyusunda vardır benzerin 

Kuyudan Yusuf çıkar mı bilmem 

Karanlıkta derinde sesler korkutur, 

Yusufum o derinler çok mu zorludur

Karanlıklar nedense sana doğrudur

Kuyudan Yusuf çıkar mı bilmem

Züleyha takmışta seni gönlüne

Mehtabı arar kendi kendine

Yanar her mum yanar da kendi içine

Kuyudan Yusuf çıkar mı bilmem

Gönlüne bir sevda ağacı dikiver 

Kimbilir köklenip kuyuya iner

Kuyunun suyundan damla içiver 

Kuyudan Yusuf çıkar mı bilmem

Gözlerim her yerde yusuf arıyor 

Bu gece çok uzun güneş doğmuyor

Ay karanlık kuyuda gece bitmiyor 

Kuyudan Yusuf çıkar mı bilmem

Gönül kuyusunda vardır yusuflar 

Züleyhalar her dem onu sayıklar 

Gönül pirinç çuvalı sen taş ayıklar 

Kuyudan Yusuf çıkar mı bilmem

Mehtaba yaklaştık evet epeyce

Tan yeri karanlık yine bu gece 

Kuyuda vardır gizli bilmece 

Kuyudan Yusuf çıkar mı bilmem

Öpmeli kuyu ağzını öpmeli

İnmeli kuyuya derinlere gitmeli

Yusufu bulmak için serler vermeli 

Kuyudan Yusuf çıkar mı bilmem 

Züleyha sabrıyla bekle yusufu 

Gönül bir yusuftur bulur yusufu 

O yusuf ki huzura alır yusufu 

Kuyudan Yusuf çıkar mı bilmem

Mehmet Hüsnü ASAN 

ŞIRNAK-2004', 'Bu gece neden se çok uzun  Üstümüze güneş doğar mı bilmem  Yusufun aşkı masum ki masum  Kuyudan Yusuf çıkar mı bilmem Bir züleyha aşık ki ke...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hüsnü Asan']::text[], 8.5, '{"poet":"Mehmet Hüsnü Asan","poet_slug":"mehmet-husnu-asan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/yusuf-olan-bulur-yusuf-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Çıkageldi', 'bir-siir-cikageldi-cigdem-bir-genc-0xd80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gittin

yittim

bir imge 

beyaz kanatlarıyla düşüverdi kağıdımın üzerine 

bir şiir çıkageldi

zamansız...', 'gittin yittim bir imge  beyaz kanatlarıyla düşüverdi kağıdımın üzerine  bir şiir çıkageldi zamansız......', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-siir-cikageldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Neki?', 'sevda-neki-i-brahim-dikmen-2-ufa4n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda neki? bir gonca,

Hayat dikendir onca.

Can görünmez,kuş olur,

Yaşam sana,doyunca.

Sanma gönlüm,bezenir,

Cılız bedenim,dinlenir.

Varsın bitsin,ömrümüz,

Kara toprak,yeridir.

Seni,herbir anışım,

Ölüm gibi,tanışım.

Can bedenden çıkınca,

Sanma,söner yanışım.

Gayrı bahtım karaymış,

Gülen yüzüm,sarıymış.

Veda vakti,gelince,

Çemen gözüm,yaşlıymış.

Yaşlı gözüm,sayrıdır,

Sevdiğinden,ayrıdır.

Albız görsün,yüzünü,

Gayrı gönlüm,yastadır.', 'Sevda neki? bir gonca, Hayat dikendir onca. Can görünmez,kuş olur, Yaşam sana,doyunca. Sanma gönlüm,bezenir, Cılız bedenim,dinlenir. Varsın ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevda-neki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmukabele.', 'bilmukabele-i-brahim-dikmen-2-0uj16', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kızgınsam aşka,yada,

Sana dargınsam,aldanma.

Geçer gider,eser gider başımda,

Sevgimin,büyüklüğündendir,zira,

İnsanoğlu,sevmese kızamaz,

Sevdiğine,öylesine kıyamaz.

Birdaha yüzüne bakamaz,

Sana kızışım,aşkımdandır,keza,

Seni sevmesem,hayatta işimne,

Sensiz yaşamak,eğer sevmekse,

Kalplerimiz nezaman,birleşirse,

Hayat,işte ozaman sevilir,yaşanır,

Bilmukabele.', 'Kızgınsam aşka,yada, Sana dargınsam,aldanma. Geçer gider,eser gider başımda, Sevgimin,büyüklüğündendir,zira, İnsanoğlu,sevmese kızamaz, Sevd...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilmukabele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Koyamadım', 'adini-koyamadim-hilal-sayil-xy0zw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlar Bazen İçinde Bir Duygular Hisseder

Ama Bu Duyguları Dile Getiremez 

Sanki O Anda Ağızları Kilitlenir 

Ne Söyleyeceklerini Unuturlar

Telaşlanırlar ve Haykıramazlar 

Utanırlar Hatta 

Ama Gözler Herşeyi Anlatır 

Ah Gözler Ah İçindeki Hisleri Anlatmaya Yeter 

Hemde Hep Doğruyu Söyler

Birinin Seni Sevip Sevmediğini Gözlerinden Anlarsın

İşte Gözler Hisleri Ortaya Koyar', 'İnsanlar Bazen İçinde Bir Duygular Hisseder Ama Bu Duyguları Dile Getiremez  Sanki O Anda Ağızları Kilitlenir  Ne Söyleyeceklerini Unuturlar...', ARRAY['Türk Edebiyatı','Şiir','Hilal Sayıl']::text[], 8.5, '{"poet":"Hilal Sayıl","poet_slug":"hilal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adini-koyamadim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet Marşı', 'cumhuriyet-marsi-abdulkadir-karaman-tdzap', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonsuza dek bağımsız hür olmak amacımız

Çağdaş yönetim, çağdaş nesillerle el ele.

Cumhuriyet, lâiklik her zaman baş tâcımız

Kucaklayıp milleti tükenmeyen sevgiyle.

Cumhuriyet, nuruyla ülkeyi aydınlatan

Sarılalım dört elle, nîmet, cumhuriyete

Cumhuriyet güneştir, doğunca hiç batmayan

Cumhuriyet ebedî sönmeyen tek meşâle.

Sarılıp, Ata’ mızdan mîras tüm ilkelere

Aydınlığı her yönden yaymalıyız ülkeye

Hedef: lâik, kalkınmış, demokratik Türkiye

Önderimiz Ata’ mız, rehberimiz bilimle.

Tâvizsiz, ermeliyiz tükenmez aydınlığa

Bilimle ışık yayıp cehâlet karanlığa

Yeniden örnek olup tükenen insanlığa

Bakarak geleceğe umut ile güvenle.

Dünyada îtibarlı, vâkur, başı dik, mağrur

Olmalıyız. İçimiz dolmalı dâim gurur

Sarmalı kâlbimizi ilk heyecan, ilk şuur

Gitmeliyiz ileri, ilerleyerek fende.

Şehitlerin kanıyla, canıyla filizlenen

Bir emsalsiz hazîne, emellerde közlenen

En mükemmel idâre aranılan, özlenen

Cumhuriyet yaraşır hem yıldız, hem hilâle.

Sarılalım dört elle, nîmet, cumhuriyete

Cumhuriyet, nuruyla ülkeyi aydınlatan

Cumhuriyet ebedî sönmeyen tek meşâle

Cumhuriyet güneştir, doğunca hiç batmayan.

29/10/1999', 'Sonsuza dek bağımsız hür olmak amacımız Çağdaş yönetim, çağdaş nesillerle el ele. Cumhuriyet, lâiklik her zaman baş tâcımız Kucaklayıp mille...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cumhuriyet-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahsa', 'gunahsa-hilal-sayil-xlu5e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni Sevmek Günahsa Günah

Günah Defterim Sevginle Dolsun 

Seni Sevmek Günahsa Sonunda 

Cehenneme Gitmek Varsa 

Senin İçin Giderim

Seni Sevmek Günahsa

Su İçmem Yemek Yemem 

Ama sadece Bir Şeyi Yapamam 

Oda Senden Ayrılmak', 'Seni Sevmek Günahsa Günah Günah Defterim Sevginle Dolsun  Seni Sevmek Günahsa Sonunda  Cehenneme Gitmek Varsa  Senin İçin Giderim Seni Sevme...', ARRAY['Türk Edebiyatı','Şiir','Hilal Sayıl']::text[], 8.5, '{"poet":"Hilal Sayıl","poet_slug":"hilal-sayil","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gunahsa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin bedeli', 'sevmenin-bedeli-ayten-ozlem-yesilcali-nbb3k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni özlemenin ne olduğunu bilmiyorsun.

Sen bilmezsin,cano

Sevmeyi bilmedigin gibi.

Hayatında kaç defa sevdin..

Sevmenin anlamını biliyormusun.

Sevgisiz yaşamanın; 

Bilemezsin.

Hiç sevilmedinki.

Kör kuylardayım...

Sensiz dardayım.....

Sen beni sevmekten vaz geçtin...

Neden neden diye sordum hep; 

Ben sana fazlamı geldim canom.

Gitme 

Bir saniye  öteye...

Seni özlemem hep hasret olur...

Artık.

Ne tabiatı,güneşi 

Nede ayı şahit göstermiyecegim sevgimize.

Sadece yirmidört saat şahit olucak; 

Sensiz seni ne kadar özledigime.

Yok artık sende ümidim....

Kestin tüm duygularımı; 

Dilim dilim...

Artık hayata sensiz  vedamı etmeliyim

Ne saniyeler şahittir sevgime

Yasakladım artık senin aşkını

Ben kendi kendime 

Sana verdigim sözü geri alıyorum

Ne verdiyse onu alacaktır kalbin.

Seni sevmenin bedelini; 

Pahalıya ödesem bile...', 'Seni özlemenin ne olduğunu bilmiyorsun. Sen bilmezsin,cano Sevmeyi bilmedigin gibi. Hayatında kaç defa sevdin.. Sevmenin anlamını biliyormus...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevmenin-bedeli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçekleri', 'kir-cicekleri-sadik-softa-ep4o9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bin bir çiçek ile süslenmiş dört yan,

Baharda çok nazlı kır çiçekleri.

Boyun kırar eda ile naz ile; 

Hele bir kırlarda gör çiçekleri.

Kokusu her yandan sarar insanı.

Bu sene de bulduk şükür nisanı.

Ayrı ayrı her birinin lisanı; 

Nasıl da severim mor çiçekleri.

Böyle nazik, nazlı yapmış yaradan.

İncitme, koparnma onu dalından.

Bunca zaman geçmiş iken aradan; 

Gel hele bir daha gör çiçekleri.

Her birisi ayrı ayrı renk verir.

Hayatta insana büyük zevk verir.

Duyguları yaprak yaprak devirir.

Kokmaya kıyamam gür çiçekleri.

Çankırı-24.04.1980', 'Bin bir çiçek ile süslenmiş dört yan, Baharda çok nazlı kır çiçekleri. Boyun kırar eda ile naz ile;  Hele bir kırlarda gör çiçekleri. Kokusu...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kir-cicekleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvensiz yaşanmaz', 'guvensiz-yasanmaz-erol-sen-404j8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gariptir insanoğlu hep bir ayrı

Sevdimi canını verir sevdiğine

Ömür nedir ki seven gönlüne

Güvenmiştir ona ve sevgisine

Yaşamın sınırları bitmiştir onunla

Sınırsız bir yaşamın kollarında

Günler geceler onun içindir

Yaşamak günün gecenin bitimsizliğinde

Beraber olmak gönüllerde güvenle

Güven sevgiden daha önemli 

Bunu hissetmenin huzuru bir başka

Yaşarken günün içinde huzurla

Herşey anlatılmıyor kelimelerin içinden

Seçip ayırmak ise zor geliyor yaşama

Yaşamın içinde sürerken hayatlar

Davranışlar anlatıyor vücut dilimi

Duygu ve hislerle donanmış ben de

Duygularımı bitirse de sevgisiz gönüller

Hislerim yeter güvencim de

Hayat güvensiz yaşanmıyor insan yanıma…

Bunu kazanabildiysen ömür günümde

Ömür günüm sonlansa da yaşam da

Bilinmezi var gelecek yaşamın

Elbet hesap günü gelecek güvenin….

11.03.2004', 'Gariptir insanoğlu hep bir ayrı Sevdimi canını verir sevdiğine Ömür nedir ki seven gönlüne Güvenmiştir ona ve sevgisine Yaşamın sınırları bi...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guvensiz-yasanmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Çıkmazı', 'sevgi-cikmazi-arif-cem-aydogan-ykogv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün insanlar el ele tutuşmuştu

Ben senin aşkınla yanıp tutuşmuştum

Ama O gün

Bir başkasının elini tutmuştum.', 'Bütün insanlar el ele tutuşmuştu Ben senin aşkınla yanıp tutuşmuştum Ama O gün Bir başkasının elini tutmuştum....', ARRAY['Türk Edebiyatı','Şiir','Arif Cem Aydoğan']::text[], 8.5, '{"poet":"Arif Cem Aydoğan","poet_slug":"arif-cem-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgi-cikmazi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Ellerini Yakamdan İstanbul!', 'cek-ellerini-yakamdan-i-stanbul-leyla-ayyildiz-5b8f3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çek ellerini yakamdan İstanbul. 

Çek ellerini üzerimden! ... 

Bakma gözlerime mavi mavi! 

Üşüdüm... 

Duymasın sokakların üşüdüğümü

Başkasının gözlerine vurgun olduğumu. 

Başka gözlerde kaybolduğumu, 

Çek İstanbul, çek ellerini üzerimden! ... 

Ne Hisar''ın görebilecek duygularımı, 

Ne Anadolu Kavağın, 

Ne de akıp giden Boğaz''ın göz yaşlarımı. 

Çek ellerini diyorum sana! ... 

Simidimin yarısını paylaştığım martılar 

Söylemeyecek kimselere. 

Vapurların düdüğü asla haykırmayacak, 

Duyurmayacak Sultanahmet''in müezzini aşkımı,

Çekeceksin ellerini yakamdan, 

Çekeceksin İstanbul! ... 

Aşkın poyrazı gezinmeyecek tenimde, 

Rüzgarın eteklerimi savurmayacak. 

Mavi gözlerinin öpüşlerinde kaybolmayacağım. 

Ve saçlarıma takmayacağım Emirgan''ın gülünü. 

Dokunma bana İstanbul! 

Kimseler bilmeyecek, kimseler işitmeyecek aşkımı... 

Güneşin yakmayacak omuz başımı. 

Yeni Camiinden havalanmış 

Bir güvercin gölgesi olup, 

Düşmeyeceksin üzerime. 

Altın Boynuz''unun üstünde 

Bir bulut kadar doluyum İstanbul. 

Başka bir aşkın değdiği fark edilmesin diye,

Gözlerimi kaçırıp, ağlayacağım. 

Yerebatan''ından küflü bir nefes çekip, öksüreceğim. 

Ellerim titreyecek, sigaram yere düşecek. 

En karanlığından zindanlara atılacak 

Yeni doğacak tüm aşklar. 

Söz vereceksin, bir daha hiç böyle bir bahar doğmayacak... 

Böyle doğmayacak güneş üstüne. 

Söz vereceksin İstanbul, 

Bir daha göz kırpmayacaksın Piyerloti''den... 

Ağlamayacağım İstanbul, ağlamayacağım... 

Ayaz çalacak, titreyecek bedenler. 

Bir sela işitecek tüm eş dost. 

Bu aşkı birlikte Karacaahmet''e götüreceğiz. 

Ne sen anlatacaksın İstanbul, ne de ben! ... 

Bilsen kaç haykırılmamış aşk yatıyor orada. 

Bilsen kaç çiçek filizlendi, hiç sulanmamış toprağında.', 'Çek ellerini yakamdan İstanbul.  Çek ellerini üzerimden! ...  Bakma gözlerime mavi mavi!  Üşüdüm...  Duymasın sokakların üşüdüğümü Başkasını...', ARRAY['Türk Edebiyatı','Şiir','Leyla Ayyıldız']::text[], 8.5, '{"poet":"Leyla Ayyıldız","poet_slug":"leyla-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/cek-ellerini-yakamdan-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kente Marşlarla Girmek', 'bir-kente-marslarla-girmek-sukru-ozmen-bsx68', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey külahı ters giydirilmiş 

Gençliğim

Ruhunu çalıyor 

İşte şu anda

Tarifsiz tafralarıyla 

Zaman

Eyvah ki  vah  o halde

Güvertelerdeki  sandıksız yolcular

Atılmalı denize

İksirsiz dualarıyla birlikte

Ya Rab! 

Sonumuzu hayreyle...

Eskiyor elimde 

Fizan’a  kadar

Taşıyacağımı sandığım

Gittikçe ağırlaşan 

Hazine  sandığım

Ağırlaşıyor gece

Üstüme çökerken

Le le yar

Li li yar

Bir türkü koşup

Derinliklere

Ya Rab! 

Aklımızı hıfzeyle...

La’l oluyor işte idrakim

Aynalar aynalar 

Her bir yerimde

Açılıyor kapattıkça

Bakmaya kıyışamadığım

Kirli yerlerim

Ya Rab! 

Ayb’ımızı setreyle...

Deminsiz,sonralar

Dünlü, dinsizler

Dinli, dünsüzler

Yanlı, yönsüzler

Canlı, kansızlar

Kanlı, cansızlar

Yetim, öksüzler

Bekliyor mu hala

Geçit resminde

Tebessümlerimizle 

Geçeceğimiz zannıyla

Gönlü arsızlar,

Ömrü yarsızlar,

Kadim hırsızlar

Bekliyor mu? 

Ey külahı ters giydirilmiş 

Gençliğim

Ruhunu çalıyor

Kuduz yarasalar

İşte şu anda

Marşlarla giriyorsan 

Eğer bir kente

Öyle gir ki

Çıkışın 

Depremlerle olsun 

Ya Rab! 

Gönlümüzü göl eyle...

Şubat 2004', 'Ey külahı ters giydirilmiş  Gençliğim Ruhunu çalıyor  İşte şu anda Tarifsiz tafralarıyla  Zaman Eyvah ki  vah  o halde Güvertelerdeki  sandı...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Özmen']::text[], 8.5, '{"poet":"Şükrü Özmen","poet_slug":"sukru-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/bir-kente-marslarla-girmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemleşmeliyim', 'annemlesmeliyim-ayten-ozlem-yesilcali-9qabg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl acı duyarsa bir yaralı.

Nasıl çıkarsa ölçüsüz haykırışlar gırtlağından

Öyle bağırayım bende

Sonsuzlaşsın yüreğim.

Bütün yaralı,herkese sevgi taşıyacak kadar.

Ve öylesine güzelleşsinki herşey.

Öylesine derin yumuşak bir ışıkta.

Öylesine bilgeleşeyimki.

Öylesine sevgiyle dolan kalbim..

Ölürken annemleşeyim.

Biliyorum var olmaz birdaha; 

Yok olan şeyler.

Maddenin biçim degiştirdigi

Ruh diye bir şeyin olmadıgı.

Ama gizli kalmış sevgiler

bulunup çıkarılırsa; 

Yüreklerinden insanların.

Çıkarılırsa karanlıgından; 

Unutuşun yaşanmış olan şeylerin.

Ve tek bir insan yüregi gibi çarpsa.

Bir günlük insanlık; 

Hiçbirşey yok olmamış olacaktır.

Düşünürsek sonsuz büyük; 

Bütün zamanları birleştiren 

Herzaman sevgidir....', 'Nasıl acı duyarsa bir yaralı. Nasıl çıkarsa ölçüsüz haykırışlar gırtlağından Öyle bağırayım bende Sonsuzlaşsın yüreğim. Bütün yaralı,herkese...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/annemlesmeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yaprağında Çiy Tanesi', 'gul-yapraginda-ciy-tanesi-galip-sinecikli-zvmbk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen beni anlamadın bebeğim,

Sen beni anlamadın,

Ben sana gül sunarken ellerimle,

Sen dikeni bana batırdın,

Ben bir dünya verirken sana başım üzerinde,

Sen dünyamı başıma yıktın,

Ben sana Kalbimi sunarken,

Kristal bir tepside,

Sen o kalbi aldın yerlere attın,

Hançer batırdın,

Sen beni anlamadın çiçeğim,

Sen beni anlamadın,

Ben bir çiy tanesiydim,

Gül yaprağında,

Sen geldin o gülün yapraklarını kopardın,

Sen beni anlamadın....', 'Sen beni anlamadın bebeğim, Sen beni anlamadın, Ben sana gül sunarken ellerimle, Sen dikeni bana batırdın, Ben bir dünya verirken sana başım...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-yapraginda-ciy-tanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Fayda', 'ne-fayda-hasan-arican-naitb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dert tasa bürümüş dört bir yanımı

Yaşam canavarı emdi kanımı

Acılar çoğaldı yaktı canımı

Zaman geri dönse bana ne fayda

Bana hazineydin saklayamadım

Kara talihimi aklayamadım

Sen benim gülümdün koklayamadım

Dünya gülle dolsa bana ne fayda

Sevda bir umuttur, umutlar uçtu

Gönlümde kurduğum binalar göçtü

Yaz-bahar aylarım boran-kış geçti

Mevsim bahar olsa bana ne fayda

Sensizlik bağrımı daha da yaksın

Akşamlarım sensiz rüyamda yoksun

Yeni sabahlarda olmayacaksın

Gelen sabahlardan bana ne fayda

Sahipli sahibin arayıp bulsun

Nerdesin bilinmez, kimlerden sorsun

Alevler sönse de yürekte korsun

Mutluluk var ise bana ne fayda.', 'Dert tasa bürümüş dört bir yanımı Yaşam canavarı emdi kanımı Acılar çoğaldı yaktı canımı Zaman geri dönse bana ne fayda Bana hazineydin sakl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Arıcan']::text[], 8.5, '{"poet":"Hasan Arıcan","poet_slug":"hasan-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-fayda-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim ADIM Muhammed', 'benim-adim-muhammed-muhammed-baki-unsal-bk8of', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim  ADIM  Muhammed.

Peygamberimizin  ismi.

Bir  ADI da  Ahmed

Gül  kokardi  cismi.

Ben  O''nu  cok  severim.

Kendi  canimdan  bile.

Yoluna  halilar  sererim.

Gözyasimi  sile-sile.', 'Benim  ADIM  Muhammed. Peygamberimizin  ismi. Bir  ADI da  Ahmed Gül  kokardi  cismi. Ben  O''nu  cok  severim. Kendi  canimdan  bile. Yoluna...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Baki Ünsal']::text[], 8.5, '{"poet":"Muhammed Baki Ünsal","poet_slug":"muhammed-baki-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benim-adim-muhammed-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri', 'serseri-mustafa-ustun-xmaij', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir gün motorla gece yarısı

çığlık çığlığa akıyorum

ne sen ayrımındasın kaçtığımın 

ne deniz fenerleri 

uzak limanlarda savruluyorum 

gözlüklerim kırık,umudum kırık

baştan kara dalıyorum sulara

köpek balıkları gibi soluyorum

bağlanma,bana kalma diyorum 

bu can seni taşıyamaz diyorum 

kilitleniyorum resmine

hayal meyal ağlıyorum

yine başım aldım,yine kaçıyorum

gecenin,karın,darlığın içindeyim

bileklerimi kestim kanın içindeyim

yerde miyim, gökte miyim,bilmiyorum..', 'bir gün motorla gece yarısı çığlık çığlığa akıyorum ne sen ayrımındasın kaçtığımın  ne deniz fenerleri  uzak limanlarda savruluyorum  gözlük...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/serseri-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarkaç', 'sarkac-mustafa-ustun-ciir4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gün gelir

yaşanır acılar

bir bir

gün geçer

hatırlanmaz telaş

içindeki elektrik

toprağa akar

gün biter 

ezanlar okunur

çanlar çalınır

solar senin güzel gözlerinin içi

gün

yeniden dolanır burçları

tüm sarkaçlarıyla hayat

yeniden başlar

yeniden biter

yeniden', 'gün gelir yaşanır acılar bir bir gün geçer hatırlanmaz telaş içindeki elektrik toprağa akar gün biter  ezanlar okunur çanlar çalınır solar s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sarkac-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sigara', 'son-sigara-emir-kemal-y21ll', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Henüz gece değil...

Akşam, son sigarasını yakmış beklemede...

Ben, gözlerim açık uyumada...

Ve sen rüyamda...

Aklıma firar türküleri söyleten sen...

Her şarkıda adına kafiyelenen satır sonları,

Ve her filmin senaryosundan senin için çalan ben...

Yeter artık nedir benden çekilen diyen sigaram,

Ve çekilen bir ipin ucundayım sanan ben...

Hatırına tüm şarkılarımı dinleyen bihaber dostlar,

Ve şarkıları beraber söylediğimiz sen...

Yalnızlığa cesaret edemediğim üşengeç akşam saatlerinde...

Açılmasını beklediğim bir kapının beyaz kolu... 

Narin bir el dürtüsüyle...

Ve bir türlü açamayan,

Açmaya engel yabansı korkuları olan sen...

Henüz gece değil,

Akşam, son sigarasını yakmış beklemede...

Bütün bir günü tertemiz gömdüğü için ağlayan ben...

Nedenini henüz anlayamadığın bir sarhoşlukla şaşıran sen...

Bir ileri iki geri gönül rıhtımımda gezerken...

Rıhtım dar; yolu uzun,

Deniz dalgalı; dibi derin,

Bir rüzgara duacı  açılan ellerim,

Düşmelisin tenhalarına seni bekleyen bu serseri denizin... 

Bir şair son şiirini yazmada elinde yüreği,

Bir aşık sazına vurmada,dilinde sevdiği...

Sazın telinde sen,yürekte sen,özde sen...

Bir kaçağın her korku çığlığını siper alıp kendine kalbine girmek isteyen ben...

Ve bir namlunun soğuk bakışından fırlayan sıcacık kurşun...

Sen....

Bir çiçeğin en güzel rengi,

Bense,

Her rengiyle çiçeği sevmeye yeltenen ben...

Henüz gece değil,

Akşam da nerede...

Bir izmarit bırakıp gitmiş... 

Üzerine basılmadan sönmesi istenen bir izmarit...

Ve basamayan ben...

Sönmeyen hayalin...

Ve gece...', 'Henüz gece değil... Akşam, son sigarasını yakmış beklemede... Ben, gözlerim açık uyumada... Ve sen rüyamda... Aklıma firar türküleri söylete...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/son-sigara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Süreçler', 'kirik-surecler-mustafa-ustun-1fqrk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ceylanım beni zorda bıraktı.

Kırık bir süreçti aslında,

beni aramadı,beni sormadı.

Yüreğimi telaşlarda bıraktı.

Gittide,emeğimi alıp gittide, 

ekmeğimi alıp gitti de

Bu adam ne yapar demedi.

ceylanım beni darda bıraktı.

Sonraki günlerde ayrıldık,

beni geç zamanlarda bıraktı.

Bir soğukluk yaşandı ve bitti

ceylanım içimi karda bıraktı.', 'Ceylanım beni zorda bıraktı. Kırık bir süreçti aslında, beni aramadı,beni sormadı. Yüreğimi telaşlarda bıraktı. Gittide,emeğimi alıp gittide...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirik-surecler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapatın Gitsin', 'kapatin-gitsin-faruk-emre-yildiran-hhhu1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yardım edin

Kapatın şu müziği

Duymak istemiyorum artık

	

Nerden gelir bilinmez

Kulaklarım içimi

İçimde kulaklarımı

Suçlar dururken

Yardım edin

Kapatın şu müziği

Duymak istemiyorum artık

(31-01-2004/Çengelköy)', 'Yardım edin Kapatın şu müziği Duymak istemiyorum artık 	 Nerden gelir bilinmez Kulaklarım içimi İçimde kulaklarımı Suçlar dururken Yardım ed...', ARRAY['Türk Edebiyatı','Şiir','Faruk Emre Yıldıran']::text[], 8.5, '{"poet":"Faruk Emre Yıldıran","poet_slug":"faruk-emre-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kapatin-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorarım Sana', 'sorarim-sana-faruk-emre-yildiran-zuen4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taşlarının bile

Ne zaman döşendiğini bilmediği

Bir tarih kadar eski

Beklide tarihin bile tanımlanmadığı

Ağlamaktan yosun tutmuş gözleri

Tepeden bakan binaların arasında

Ne işin var sorarım sana

Lodos rüzgarı vurmuş 

Balıkçı teknesi gibi

Bir sancağa

Bir iskeleye

Ne yatarsın

Sorarım sana

Yerini senin bile bilmediğin

İstanbul’un dar

İçinde bulunduğun çukurları hatırlatan sokakların

Yanmaz sokak lambalarının altında

Ne gezinirsin 

Ne işin var sorarım sana

İnsanlardan uzakta

(31-01-2004/Çengelköy)', 'Taşlarının bile Ne zaman döşendiğini bilmediği Bir tarih kadar eski Beklide tarihin bile tanımlanmadığı Ağlamaktan yosun tutmuş gözleri Tepe...', ARRAY['Türk Edebiyatı','Şiir','Faruk Emre Yıldıran']::text[], 8.5, '{"poet":"Faruk Emre Yıldıran","poet_slug":"faruk-emre-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sorarim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birkaç Mil Uzakta', 'birkac-mil-uzakta-faruk-emre-yildiran-wg5nl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Az kaldı hissediyorum

Kuşlar tarif etmeye başladı bile

Varacağım yeni diyarları

Şaşırıyorum gördüklerime

Gideceğim yerleri benden daha iyi biliyorlar

Hayatıma girmiş her canlı

Sanki birlikte yaşamışız

Önceki kan kokan zamanları 

Sanki birlikte içmişiz

Geçmişin acı şarabını

Az kaldı hissediyorum

Birkaç mil uzakta

Daha önce görmediğim

Başkalarıyla birlikte yaşadığım

Yeni diyarlar

(25-01-2004/Çengelköy)', 'Az kaldı hissediyorum Kuşlar tarif etmeye başladı bile Varacağım yeni diyarları Şaşırıyorum gördüklerime Gideceğim yerleri benden daha iyi b...', ARRAY['Türk Edebiyatı','Şiir','Faruk Emre Yıldıran']::text[], 8.5, '{"poet":"Faruk Emre Yıldıran","poet_slug":"faruk-emre-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birkac-mil-uzakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Sızıyordu', 'kan-siziyordu-faruk-emre-yildiran-n020c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapanırken yüreğimin yaraları

Usulcada olsa

Kan sızıyordu çeperinden

Sessizce kanıyordu

İsimsiz sevdaların ardından

Söylenen türküler gibi

Ağlıyordu bir başına

(02/2004/Çengelköy)', 'Kapanırken yüreğimin yaraları Usulcada olsa Kan sızıyordu çeperinden Sessizce kanıyordu İsimsiz sevdaların ardından Söylenen türküler gibi A...', ARRAY['Türk Edebiyatı','Şiir','Faruk Emre Yıldıran']::text[], 8.5, '{"poet":"Faruk Emre Yıldıran","poet_slug":"faruk-emre-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kan-siziyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Çiçek', 'i-ki-cicek-mustafa-ustun-zx6y1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonra 

birlikte yaşlanacağız

benim,üzünçler kraliçesi karıcığım

sonra birlikte öleceğiz.

Sonra

toprağım,toprağına karışacak

iki çiçek olarak aynı kırsalda

yeniden yaşıyacağız.

Sonra

rüzgarda eğilecek goncam

seni yeniden öpeceğim

canların canı,karım,sultanım

                                  14 Mayıs 2001

                                   Anneler Günü', 'Sonra  birlikte yaşlanacağız benim,üzünçler kraliçesi karıcığım sonra birlikte öleceğiz. Sonra toprağım,toprağına karışacak iki çiçek olarak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iki-cicek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkacaksın', 'korkacaksin-faruk-emre-yildiran-efwpl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaratıcının soluğuyla uçuşurken

Birbirlerinin karşısına çıkmayıp

Düzenlerini bozmadan aşağı süzülen

Kar taneleri gibi olacaksın.

Onlar gibi korkacaksın

Çamurun üstüne düşüp

Kirlenmekten

(25-01-2004/Çengelköy)', 'Yaratıcının soluğuyla uçuşurken Birbirlerinin karşısına çıkmayıp Düzenlerini bozmadan aşağı süzülen Kar taneleri gibi olacaksın. Onlar gibi ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Emre Yıldıran']::text[], 8.5, '{"poet":"Faruk Emre Yıldıran","poet_slug":"faruk-emre-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korkacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Bir Aşk Filmi', 'sessiz-bir-ask-filmi-ali-aydin-hkyve', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bensiz geçen yıllarını saymıyorum, 

Sessiz fotoğraflarını seyrediyorum.

Yüzün o kadar saf, o kadar masum ki; 

Hayatın bütün gizemini görüyorum gözlerinde.

Sen, uzaklardaki sevgilim; 

Seni sevmediğimi sanma? 

Sen susuz çöllerde kavrulurken, 

Yağmur bulutlarını ateşe veren bendim.

Sen, toprağa ektiğim umut tohumusun,

Koca ormanda filizleneceğiz, 

Gövdemde uyanacaksın ince dallarınla. 

Seni su gibi,

Hava gibi,

Ekmek  gibi,

Katıksız seviyorum...

11 Şubat 2004

(Dünyamızdaki ADA’dayım)', 'Bensiz geçen yıllarını saymıyorum,  Sessiz fotoğraflarını seyrediyorum. Yüzün o kadar saf, o kadar masum ki;  Hayatın bütün gizemini görüyor...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydın']::text[], 8.5, '{"poet":"Ali Aydın","poet_slug":"ali-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sessiz-bir-ask-filmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Normal İnsanlar', 'normal-i-nsanlar-faruk-emre-yildiran-ekdfz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birden gördüğümde karşımda

Niçin daha önce çağırdığına

Hayret etti aklım.

Bir insan niye isteyebilirdi ki

Gördüğünde pişman olacağı şeyleri

Anlayamadı

Neden istemiştim

Acaba bende normal birimiydim

Bunları yaşamadan önce

İyi oldu bunları yaşamam

Ölümün kıyısına gelip de

Tutunabildiğimde Allah’a

Bende anladım bazı şeylerin 

Tartışmasız nedenlerini

Bir şey kaybetmeden öğrendim

Geçmişime nispet yaparcasına

Normal insanlar gibi

(25-01-2004/Çengelköy)', 'Birden gördüğümde karşımda Niçin daha önce çağırdığına Hayret etti aklım. Bir insan niye isteyebilirdi ki Gördüğünde pişman olacağı şeyleri ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Emre Yıldıran']::text[], 8.5, '{"poet":"Faruk Emre Yıldıran","poet_slug":"faruk-emre-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/normal-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paltonun Eteği', 'paltonun-etegi-faruk-emre-yildiran-4olx3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kamış kadar ince

Çıplak bacakları titretiyordu

Yolların nam salmış hayaletleri

Yaşayanlar anlatıyor

Başlarına gelen 

Korku dolu anların anılarını

Kendi başına dolaşanları seçiyormuş

Yağmurun yeni dindiği

Kuşların gürültü çıkarmadan uçtuğu

Dar,gölgelerin yok olduğu vakitlerde

Yavaşça yaklaşıp

Çıt çıkarmadan çekiştiriyormuş

Akakiy Akakiyeviç’in hortlağı gibi

Soğuktan tir tir titreyen bedenin

Siper olarak seçtiği paltonun eteğini.', 'Bir kamış kadar ince Çıplak bacakları titretiyordu Yolların nam salmış hayaletleri Yaşayanlar anlatıyor Başlarına gelen  Korku dolu anların ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Emre Yıldıran']::text[], 8.5, '{"poet":"Faruk Emre Yıldıran","poet_slug":"faruk-emre-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/paltonun-etegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süreceksem', 'sureceksem-faruk-emre-yildiran-js68d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Süreceksem

Sadece anam kokan elbiselere 

                                                   süreyim

Padişahın önünde bekleyen

                                             yüzümü

(31-01-2004/Çengelköy)', 'Süreceksem Sadece anam kokan elbiselere                                                     süreyim Padişahın önünde bekleyen               ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Emre Yıldıran']::text[], 8.5, '{"poet":"Faruk Emre Yıldıran","poet_slug":"faruk-emre-yildiran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sureceksem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışmak', 'alismak-abdullah-turan-oguzhan-mjqaj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alışmak

Gülüm, sevmekte yoruldu kalbim.

Halbuki ben, sevmeden yaşayamam sanırdım.

Onca vefasızlıklara inat, sevmeye çalıştım.

Ama inan, zaman acımasızmış sevmemeye de alıştım.', 'Alışmak Gülüm, sevmekte yoruldu kalbim. Halbuki ben, sevmeden yaşayamam sanırdım. Onca vefasızlıklara inat, sevmeye çalıştım. Ama inan, zama...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Turan Oğuzhan']::text[], 8.5, '{"poet":"Abdullah Turan Oğuzhan","poet_slug":"abdullah-turan-oguzhan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/alismak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-ayten-ozlem-yesilcali-6vlq5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalar bazen düşünürüm memleketi; 

O yılları,yaşadığım şehri,

Havasını,suyunu,insanlarımı; 

Nede mutluydum ve mutluyduk.

Komşularımız vardı içten.

Lokmasını bölüşen.

Hastanı hastası belleyip didinen.

Seninle ağlayan,seninle gülen...

Fato,emo ayşo zelha; 

Ne güzel analarımızdılar

Bacımızdılar,kızlarımızdılar

Saflıgın temizligin simgesiydi bunlar.

Esnaflıgın en güzelli o yıllarda vardı

Dostluğun bedeli bedevaydı.

Kışın toprakdamlarda karları

Hep beraber atarlardı.

Elbirliğiyle damları loglar lardı.

Hiç unutmam gece geç saatlere kadar

Erkekli kızlı

Arpa çarpa oynadığım oyunları.

Saflık vardı,kimse kimseye bacıdan; 

Başka gözle bakmazdı...

Sevmek,

Uğruna ölünmekti.

Sesi çıkmayan komşunun; 

Ne oldu acaba deyip kapısını çalmaları.

Ve geldik kocaman şehre; 

Evinde ölsen,kapını çalan olmaz

Aç kalsan sana bakan çıkmaz.

Menfaatsiz dostluk olmaz.

Güzellikleri çok olsa ne olur ki

İnsanlığı kalmadıktan sonra...

Neye yarar ki; 

Benim diyarımın kışı boran

Yazı bayram...

Sonbaharı hazan.

İlkbaharı buram buram aşık olunan

Aşk kokardı.......', 'Dalar bazen düşünürüm memleketi;  O yılları,yaşadığım şehri, Havasını,suyunu,insanlarımı;  Nede mutluydum ve mutluyduk. Komşularımız vardı i...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/memleketim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-sair-tarikcan-fzbw5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şehr-i İstanbul çekti, kan çekti geldim.

Ben yağmurları ardımda bıraktım geldim.

Burada hem lodos hem poyraz esiyor.

Belkide kalbimi zindanından kurtarmak için geldim.Belkide hiçbiri! 

Bilmiyorum.Yalnız kalmak için geldim belkide, korktum göğümde uçurtma uçuramamaktan,bilmiyorum.Kalıcımıyım! Galiba evet.Ellerim titrek sözlerim gibi.Kararsız dokunmaya ve dokunulmaya.Belkide kaçtım senin gibi.(Evet yaşasın prens) 

Şiirler var mıdır bilmem bir insanı bütünleyen, ben bulamadım.Umutsutsuzlukta da var umut ta yüreğimde ve daha çok kızımın gülümseyişi, tanımlayamadığım gerçeklediğimin ötesinde.

Şarkılarıda özledimde geldim.

Yine yağmur yağacak, biliyormusun hep korunaklıydım 

Yine ıslanmıyacağım ben.', 'Şehr-i İstanbul çekti, kan çekti geldim. Ben yağmurları ardımda bıraktım geldim. Burada hem lodos hem poyraz esiyor. Belkide kalbimi zindanı...', ARRAY['Türk Edebiyatı','Şiir','Şair Tarıkcan']::text[], 8.5, '{"poet":"Şair Tarıkcan","poet_slug":"sair-tarikcan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mektup-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dagların yamacındayım', 'daglarin-yamacindayim-ayten-ozlem-yesilcali-5ja16', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağların yamacındayım,firardayım.

Özğürlük için çarpışmadayım.....

Eziklik,hor görülmek,yoklukla mücadeledeyim..

Kendim için,insanlıkiçin,gelecekteki çocuklarım için...

Kimileri yaslamış sırtını Ağa’ya

Devletide almış yanına.

Ortak olmuşlar tüm yalanlara...

Ana ağa devlet baba....

Vur vurabildiğin kadar abalıya...

Kar yagar dagın yamaçlarına.

Zifiri karanlıkta sovukhava  titreyen dudaklarımdan

Fısıltıyla çıkar türkülerimiz ezgilerimiz...

Anam,babam kardeşlerim gelir aklıma.

Kör kurşunlar vızıldar etrafımda...

Ağa adamlarıyla gelmiş beni vurmaya.

Cumhuriyettin kaçıncı yüzyılında.

Hala çanak tutar devlet ağaya.

Sormaz. 

Hani köylünün topragı,ekecegi. 

Neden olsunki,karın tokluguna çalışmak varken ağaya. 

Memleketin sahibi olamaz ne yerlisi ne devleti. 

Ağası varya aşireti. 

Diziler yapılır oldu ve bunu görür tüm milleti ve de devleti. 

Moda oldu ağalar artık meclisi doldurur oldu 

Yanımda candaşım vuruldu.

Can havliyle dayan dayanabidigin kadar

Varalım yüksek yamaçlara.

Vuruşalım,çarpışalım ağave adamlarıyla

Canımız akan kanımız helal olsun.

Özgürlük için akmaya...

Dagların yamacındayım.

Üzülme anam firardayım...', 'Dağların yamacındayım,firardayım. Özğürlük için çarpışmadayım..... Eziklik,hor görülmek,yoklukla mücadeledeyim.. Kendim için,insanlıkiçin,ge...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/daglarin-yamacindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peralı Yıllar', 'perali-yillar-mustafa-ustun-mjn9s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O

ne zaman tiyatro dese 

hemen koşar iki bilet alırdım.

O İstiklal caddesinde yiterdi

ben kırık kalırdım

O

bakara güllerini severdi.

hep bir gül taşırdım yanımda

O’na sunmak için.

Ya kısmet olmazdı,

ya solardı.

Cebim solgun gül yaprağı dolardı.

O

en hisli şarkımdı benim

notasıyla,ezgisiyle,neyiyle

Pera’da kaldı.

Yada kuş tüyüydü bir demet

dağıldı,dağıldı..', 'O ne zaman tiyatro dese  hemen koşar iki bilet alırdım. O İstiklal caddesinde yiterdi ben kırık kalırdım O bakara güllerini severdi. hep bir...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/perali-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim', 'annecigim-mustafa-ustun-485vj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lütfen bu şiddetten,bu işkenceden 

Beni kurtar annem,beni al n’olur.

Bıktım bu cennetten bu cehennemden

Kır zincirlerimi göğe sal n’olur.

Göçükte,depremde,grevde,yasta

Ya çöplükte bir leş ya ağır hasta

Belki göz altında belki mahpusta

Lütfen anneciğim beni bul n’olur.

Katılırım sevincine,tasana

Çay demler,odunlar kırarım sana

Karlar kenti ulu Erzurum’una

Lütfen,lütfen,lütfen beni al n’olur.', 'Lütfen bu şiddetten,bu işkenceden  Beni kurtar annem,beni al n’olur. Bıktım bu cennetten bu cehennemden Kır zincirlerimi göğe sal n’olur. Gö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/annecigim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz Akar Çaylar', 'buz-akar-caylar-mustafa-ustun-monud', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçmiş zamanın menekşeleri

koyuklarında deli çayların

kar altındadır.

Göçer kuşlar akmadadır 

günbatımına.

Göçerler süt beyaz bulutlardadır.

Akasyalardan buzlar sarkmadadır

karlı bahçelerde.

O bahçeler şimdi masallardadır.

Aylı gecededir küçüğüm.

Maviş gözlerinde aydınlıklar

üşümededir.', 'Geçmiş zamanın menekşeleri koyuklarında deli çayların kar altındadır. Göçer kuşlar akmadadır  günbatımına. Göçerler süt beyaz bulutlardadır....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/buz-akar-caylar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam', 'cam-mustafa-ustun-s6u5i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kargılan 

sak

da

sözünle,

karalan

sak

da.

Düşlem

ler

le de

olsa,

mut

lar

la da

ya.

Bir 

ben

ki

sorun,

olmaza

sığ,

bu nasıl

sa,

Yoksam

yazılım

lar

da da

yoktur,

donanım

lar

da da

ha.

Camdır bu yürek', 'Kargılan  sak da sözünle, karalan sak da. Düşlem ler le de olsa, mut lar la da ya. Bir  ben ki sorun, olmaza sığ, bu nasıl sa, Yoksam yazılı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solgun Bir Gül', 'solgun-bir-gul-mustafa-ustun-xdm8j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uçtu uçakları gecenin

uzak yıldızlara.

Gün batımlarında

son ışıltısıda bitti

turuncu güneşlerin.

Nasıl olsa gitti giden 

hiç sorma neden.

Uzak denizlerden 

bir uğultu kaldı geceye.

Loş kayıkhanelerde

su şıpırtılarıda 

kürek sesleri de yitti.

Nasıl olsa gitti giden 

hiç sorma neden.

Gece yarısı trenlerinden

boşluğa bırakılan

solgun bir gül oldu önce,

sonra aysız gecelerde

beni terketti.

Nasıl olsa gitti giden 

hiç sorma neden.', 'Uçtu uçakları gecenin uzak yıldızlara. Gün batımlarında son ışıltısıda bitti turuncu güneşlerin. Nasıl olsa gitti giden  hiç sorma neden. Uz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/solgun-bir-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-guler-ilgaz-yrdo5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessizliğin içinden 

Doğan sese merhaba

Yudum yudum

İçerken sessizliğin

Sesini

Sevgi dedi ki

Merhaba

Merhaba dedim

Sevgiye

Sessizliğin sevgiyle buluştuğu ana

Merhaba

Onurun, yaratıcılığın

İyiliğin, güzelliğin

Aydınlığın, özgürlüğün

Ses olarak

Dalga dalga

Sessizce

İçimden akan zamandan

Dalga dalga

An be an

Evrene yayıldığı

Şu ana

Merhaba

İçimden yankılanan

Evrende ses olan

Sessizliğe

Merhaba

Kışın ilkbaharın müjdesi olduğunu haykıran

Sessizliğe merhaba

Aydınlığın müjdesi olan 

Şafağa 

Merhaba

Merhaba karanlığı

Yırtan aydınlığa

Korkuları sevgiye

Dönüştüren 

Zamana merhaba', 'Sessizliğin içinden  Doğan sese merhaba Yudum yudum İçerken sessizliğin Sesini Sevgi dedi ki Merhaba Merhaba dedim Sevgiye Sessizliğin sevgi...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/merhaba-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyva Zamanı', 'meyva-zamani-mustafa-ustun-7nag8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgilim, 

gece kapımıza dayandığında

ellerimizle diktiğimiz asmalar

balkonumuza erişmiş olacak.

Sana belki üzümleri yemekte kısmet olur.

Cevizlerimiz

dallanacak,budaklanacak.

Cıva buharlı lambalara yağacak

güz yağmurları.

Karadeniz dalgalanacak

dalgalanacak.

Kasımpatılar açacak yağmurlardan sonra

turuncu,kızıl.

Trabzon hurmaları mordan ala dönecek.

Kış toprağa

düştü

düşecek

DİPNOT

Can da özür olmaz sevgili

özür doğanın içinde var

ölüm gibi.', 'Sevgilim,  gece kapımıza dayandığında ellerimizle diktiğimiz asmalar balkonumuza erişmiş olacak. Sana belki üzümleri yemekte kısmet olur. Ce...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/meyva-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür', 'ozgur-mustafa-ustun-ix6uy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sapkın 

yaşa

yasaksız.

Uçuk

kaçık

sıradışı.

Bağsız

yaşa

bağıtsız.

Suca 

ışıltılı,

tanca 

apak.

Sen

sen ol 

özgür ol.', 'Sapkın  yaşa yasaksız. Uçuk kaçık sıradışı. Bağsız yaşa bağıtsız. Suca  ışıltılı, tanca  apak. Sen sen ol  özgür ol....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozgur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-ozgur-umit-re4ij', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yokluğun: 

ipe çekilmişliğimin diğer adı

yüreğimin bana başkaldırışı.

yokluğun:

beyin hücrelerimin iflası

cehennemin bendeki şubesi

yokluğun:

kıyametin tek sanısı

yokluğun: 

dıyarbakır zındanının pkk zanlısı...', 'yokluğun:  ipe çekilmişliğimin diğer adı yüreğimin bana başkaldırışı. yokluğun: beyin hücrelerimin iflası cehennemin bendeki şubesi yokluğun...', ARRAY['Türk Edebiyatı','Şiir','Özgür Ümit']::text[], 8.5, '{"poet":"Özgür Ümit","poet_slug":"ozgur-umit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yoklugun-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım', 'yarim-osman-pala-5j8dp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vazgeçiş...

Hiçbir dilbiliminde yoktu ilişkimizin sonuna koyduğumuz kahpe işaret

Ve ne sonlanan bir öykü vardı bende sana dair,

Ne de korkularımızı yakacak çıra hatıralar...

Bir serçe kadar ürkeğiz artık, titrek değil

Ne ''bitti'' diyebildiğimiz,ne ''devam edecek'' yalanları kendimize söyleyebildiğimiz.

Tanrı kadar gerçek bitmediği...Erkekçe! 

Ve tam tamına benim kadar yarım yarıda kalanlar.

Yarınlarınsa olmadığı bu öykü ''öykümüz''

Bırak bu şiir gibi ''yarıda'' kalsın.', 'Vazgeçiş... Hiçbir dilbiliminde yoktu ilişkimizin sonuna koyduğumuz kahpe işaret Ve ne sonlanan bir öykü vardı bende sana dair, Ne de korkul...', ARRAY['Türk Edebiyatı','Şiir','Osman Pala']::text[], 8.5, '{"poet":"Osman Pala","poet_slug":"osman-pala","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yarim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirlenmiş duyguların', 'kirlenmis-duygularin-ozgur-umit-7r5u4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dünyan ve kirlenmiş benli duyguların 

sisli odası yüreğimin.

her köşesinde bir iz

bir döküntü senden.

penceremde soğuk yüzün, 

sobamda öfken ayrılık gecesinden kalma..

kilimlerde ayak izlerin

battaniyemde uykucu mızmız bedenin

ve birde ayrılık öncesi son bakışın gözlerimde

hala ıslak, hala sıcak...', 'dünyan ve kirlenmiş benli duyguların  sisli odası yüreğimin. her köşesinde bir iz bir döküntü senden. penceremde soğuk yüzün,  sobamda öfken...', ARRAY['Türk Edebiyatı','Şiir','Özgür Ümit']::text[], 8.5, '{"poet":"Özgür Ümit","poet_slug":"ozgur-umit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kirlenmis-duygularin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktı', 'askti-mustafa-ustun-y2b81', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sınırı aşan sulardı aşk

aktı.

Akağında

üzünçler bıraktı.

Uzakara

durgunluklar yaşandı.

Oysa yürek 

camdı,

kırılgandı,

darmadağındı.

Baştan ayağı

adı

aşktı.

Zamanlarda kaldı.', 'Sınırı aşan sulardı aşk aktı. Akağında üzünçler bıraktı. Uzakara durgunluklar yaşandı. Oysa yürek  camdı, kırılgandı, darmadağındı. Baştan a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kılınç Artığı', 'kilinc-artigi-mustafa-ustun-8w3ti', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yığıştı acılar

berkitti egemenliğini gecede

üstüne yürüdü 

krallığımızın.

Çalıntıdan bir sonbaharda 

umutlarımızı 

dinamitledi kökünden, 

direneklerini 

sevdamızın

ezdi 

geçti.

Moğol atlıları gibi

apansız

dayandı kapımıza,

sevinçlerimizi

yaktı

yıktı.

Şimdi

gülücüklerimiz yarım

ve kılınç artığıdır.', 'Yığıştı acılar berkitti egemenliğini gecede üstüne yürüdü  krallığımızın. Çalıntıdan bir sonbaharda  umutlarımızı  dinamitledi kökünden,  di...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kilinc-artigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapar insan', 'yapar-insan-yolcu-toprak-hu9gj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gece vakti insan ararmı sevdiğini

hiç bilmediği yerlerde,

yada hiç sorarmı tanımadığı insanlara,sevdiğini

bulamayacağını bile bile

bindiği otobüste para üstü almayı unuturmu,

yağmurlu havada şemsiye almazmı yanına.

veya,içerinin dışarıdan daha güzel olduğunu düşünürmü.

nekadar ağrı kesici varsa bildiği,

hepsini içermi anlamsızca

en sevdiği çiçeği   koparırmı dalından

yaparmı acaba? 

ben yapmiştım bir zamanlar,

ve hala yapıyorum 

yapacağımda galiba', 'gece vakti insan ararmı sevdiğini hiç bilmediği yerlerde, yada hiç sorarmı tanımadığı insanlara,sevdiğini bulamayacağını bile bile bindiği o...', ARRAY['Türk Edebiyatı','Şiir','Yolcu Toprak']::text[], 8.5, '{"poet":"Yolcu Toprak","poet_slug":"yolcu-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yapar-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anımsama', 'animsama-sair-barisbariskan-fxh4a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüzgara kapılacaksın sende birgün

ve hatırlayacaksın beni ansızın

Ürperecek umarsızca tüm vücudun

Sessizce zamana karışacak bedenin

Sızlarken senden geriye kalanlar acılar içinde

Yanacaksın cehennem misali kor ateşlerde

Yüreğin loş zindanlara mahkum olacak

ve bir an anımsayacaksın geçmişi göreceksin gözlerimde

Bilmekten korkarak gerçekler yüzleşecek

Kendinle ve o zaman anlacaksın

Nelere ölünmesi gerektiğini

Ah evet! Nasılda ölümdür aşk.................

Bile bile günaha girerken ve nasılda yaşamdır

Gözleri kapalı şekilde ölümüne severken', 'Rüzgara kapılacaksın sende birgün ve hatırlayacaksın beni ansızın Ürperecek umarsızca tüm vücudun Sessizce zamana karışacak bedenin Sızlarke...', ARRAY['Türk Edebiyatı','Şiir','Şair Barışbarışkan']::text[], 8.5, '{"poet":"Şair Barışbarışkan","poet_slug":"sair-barisbariskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/animsama-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece', 'sadece-sair-barisbariskan-n3w2j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sadece biraz gülümse yeter

Birgün bu kargaşa işkence biter

Aşk yakalar elinden kalbine doğru

Umutlar yeşerdikçe acılar diner

Sadece biraz konuş yeter

Anlatır hüzünlerini küçük kelimeler

Mutluluk saklıdır anılarda

Mutluluk dudaklarından dökülen kelimeler', 'Sadece biraz gülümse yeter Birgün bu kargaşa işkence biter Aşk yakalar elinden kalbine doğru Umutlar yeşerdikçe acılar diner Sadece biraz ko...', ARRAY['Türk Edebiyatı','Şiir','Şair Barışbarışkan']::text[], 8.5, '{"poet":"Şair Barışbarışkan","poet_slug":"sair-barisbariskan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sadece-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha iyiydi...', 'daha-iyiydi-hasan-basri-kale-vz5n4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anamdan yedim ilk dayağı..

Ne de olsa ana işte.

acımadı..

ağlamadım.! 

Sonra babam...

acıdı bu kez ama..

umurumda değildi..

ağlamadım.! 

Mahalle kabadayısı

zannettiğimde kendimi

abimden yedim üçüncüyü..

ağlamadım.! 

Gün geldi..

Sen çıktın karşıma birgün.

Allah kahretsin yaaa..

...........keşke dövseydin.!', 'Anamdan yedim ilk dayağı.. Ne de olsa ana işte. acımadı.. ağlamadım.!  Sonra babam... acıdı bu kez ama.. umurumda değildi.. ağlamadım.!  Mah...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daha-iyiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışmaya Çalışıyorum', 'alismaya-calisiyorum-aysegul-toker-2de8a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığa alışmaya çalışıyorum.

Biliyorum, avuçlarımı açsam, uçacaksın.

Özgürlüğe kanat açacaksın. 

Biliyorum. Çünkü ellerimi aralayacağım.

Yokluğuna alışmaya çalışıyorum.

Biliyorum. Hemen gitmek istemiyorsun.

Oysa gidersen, huzuru bulacaksın.

Biliyorum. Gitmen lazım. Hadi git.

Sessizliğe alışmaya çalışıyorum.

Biliyorum ki bir gün susacaksın.

Suskun ve sessiz yol alacaksın. 

Biliyorum.Sen de suskunlaşacaksın.

Ah be küçüğüm.

Sen henüz bilmiyorsun.

Sen daha anlamıyorsun.

Bu yürek yorgun ve mutsuz.

Dinlenmek istiyor aşklardan uzakta.

O artık yalnızlığa da alışıyor.

Ben artık sensizliğe alışıyorum.

9 Mart 2004', 'Yalnızlığa alışmaya çalışıyorum. Biliyorum, avuçlarımı açsam, uçacaksın. Özgürlüğe kanat açacaksın.  Biliyorum. Çünkü ellerimi aralayacağım....', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alismaya-calisiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktasın', 'uzaktasin-aysegul-toker-jbxer', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzaksın bana. Uzaktasın. 

Yüzünü göremiyor, ellerini tutamıyorum.

Uzaklardasın. Yalnızlığımı hissediyorum.

Üzüntümde, sevincimde yoksun.

Sesin yok, varlığın yok.

Kendi  başıma yaşıyorum hayatı.

''Seninleyim'' diyorsun ama.

Yanıma gelemiyorsun. 

Uzaksın işte.Uzaktasın.

Seninle değilim geçip giden günlerde.

Bir ben varım burada.

Kurduğum hayaller, 

Ve yalnız yaşanan gerçeklerle...

10 Mart 2004', 'Uzaksın bana. Uzaktasın.  Yüzünü göremiyor, ellerini tutamıyorum. Uzaklardasın. Yalnızlığımı hissediyorum. Üzüntümde, sevincimde yoksun. Ses...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Toker']::text[], 8.5, '{"poet":"Ayşegül Toker","poet_slug":"aysegul-toker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uzaktasin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Verilen Söz', 'verilen-soz-umit-kilislioglu-ozger-c9b1m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Verilen söz nerede? 

Galiba şu derede.

Sapa yollardan geçmiş,

Dereyi inek içmiş.

Sonra da kaçmış dağa

Koşmuşlar sola, sağa

Dağ da yanmış, kül olmuş,

Bahaneler pek bolmuş.

Bakmış ki bilge kişi,

Yıllardır bu insanlar,

Boş vaatle beslenmiş.

“Dağılın evinize! ”

Diye bir gün seslenmiş

“Herkes aldatılmış da,

Melûl melûl bakışır.

İnanmayın bunlara! ,

Söz adama yakışır”.

(Kapılar kitabından)', 'Verilen söz nerede?  Galiba şu derede. Sapa yollardan geçmiş, Dereyi inek içmiş. Sonra da kaçmış dağa Koşmuşlar sola, sağa Dağ da yanmış, kü...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/verilen-soz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Dörtlükler XIV', 'yeni-dortlukler-xiv-ahmet-aksoy-o653e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yontu

bar yalnızıyım tren süngüsünde

eflatun kaçamaklar yorgun

kızıla çalar bir hayat yontulduğunda

söz eder geçmiş geç zamanlarda

Irz

kaç katmana ayrılır ki geçen zaman

için kırılır fay

ve kaç asır geçer böyle yalnız

kanatırken ruhunu aşk

Olmak

kaç kuşak geçer hicrinden 

sen kızgın alevde erirken

kocaman ellerin kocaman ayakların

hiçbir tabuta sığmazken us

Ama(Kör) 

korktuğun başına gelir

....yalnız duvarlar ağlar

sen bir kere yaşlanmaya gör

...taht altından kayar

Sevgili

koy beni gitsin zamana

içinde büyüt usum olsun

sevgini akıt yüreğim olsun

kızıl saçlı ejderha', 'Yontu bar yalnızıyım tren süngüsünde eflatun kaçamaklar yorgun kızıla çalar bir hayat yontulduğunda söz eder geçmiş geç zamanlarda Irz kaç k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yeni-dortlukler-xiv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pasta', 'pasta-umit-kilislioglu-ozger-6z9l8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dokuz yaşında Mustafa.

Yoksul mu yoksul; 

Kendisi gibi yetim iki kardeşi var, annesi dul.

Soba soğumuş, dışarısı ayaz

Bir de televizyonları var köşede, siyah-beyaz 

İçler acısı mahalle halkının hali.

Ahali,

Bir parça ekmeği beşe, ona bölüyor; 

Hatta bazıları ucuz ekmek kuyruğunda ölüyor.

Annesi o gün yine hasta, yatıyor.

O da ne? Televizyonda  birileri birbirlerinin yüzüne pasta atıyor! 

Rahmetli babası anlatırdı:

 “ Ecdadımız yerde bulduğu bir lokma ekmeği öpüp başına koyardı; 

Ve ancak komşusunun karnı toksa doyardı.

Buğdaydan yapılan ekmek, börek, çörek,

Hepsi mübarek.

Saygı göstermek gerek”.

Kardeşleri görmesin diye önlerinde bir süre durdu,

Aslında onlar hep bu saatlerde uyurdu.

Kalktı, gitti; fişi çekti.

Sabahleyin erkenden

İşe gidecekti.

(Kapılar kitabından)', 'Dokuz yaşında Mustafa. Yoksul mu yoksul;  Kendisi gibi yetim iki kardeşi var, annesi dul. Soba soğumuş, dışarısı ayaz Bir de televizyonları ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/pasta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Elin Sesi', 'bir-elin-sesi-murat-sayim-267km', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evvel geçti zaman

Sen bir yol tut

Neydi o apansız

Acımasız seni salan

Giden gitsin

Hoş tut seni

Bil dokunursan toprağa

Açar güller kokusunu

Yağmurun sesi de

Dua olsun senin için

Bu karmaşaya

Sen katıl

Boş ver boşluğa

Boş ver boş doluluğu

Bir türkü tut yolda 

Sonu hiç gelmesin.', 'Evvel geçti zaman Sen bir yol tut Neydi o apansız Acımasız seni salan Giden gitsin Hoş tut seni Bil dokunursan toprağa Açar güller kokusunu ...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-elin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-murat-sayim-nujvv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökkuşağı rengarenktir görene

Akıl erdiremezler ki sevene

Sarıldı kollarım ela gözlüme

Uyandırmayın bizi bu rüyadan

Toplumun lekeli sesi dilinde

Çiçekler hep gölgeli bahçesinde

Solmadan gireyim içerisine

Uyandırmayın bizi bu rüyadan

Boğayım seni bilmedik renklere

Bu dünya haktır sevip sevilene

Demişler ki  bir içim su şu ömre

Uyandırmayın bizi bu rüyadan

Etme esir kendini şu nefsine

Cümle alem duysun bizi kime ne

Aşkımdan vazgeçmem ela gözlüme

Uyandırmayın bizi bu rüyadan.', 'Gökkuşağı rengarenktir görene Akıl erdiremezler ki sevene Sarıldı kollarım ela gözlüme Uyandırmayın bizi bu rüyadan Toplumun lekeli sesi dil...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruya-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruh III', 'ruh-iii-ahmet-aksoy-bjh2a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I

engin çayırlarda açan papatyalar gibi

yangın külüne mahsur

hey koca çınar dallarında hayat

yaprak yaprak sarkıyor gözlerinden mehtap

mürekkep akan damarlar kalem

yazıyor alın yazını

bir çınar bir çınar ki toprağında akrep

kimi dallarında kovan kimi dallarında bal

hey ağaç! hangi ormana açılır penceren

bir görsen semayı toprak olmadan

II

kendine bir beden edin hava

varsın ama kimse görmüyor seni

berrak bir rmaske takınsan da

ne kirin iz ne de bekaretin

hey koca hacim gir sen bir kalıba

nasıl da göze gelirsin farkınla', 'I engin çayırlarda açan papatyalar gibi yangın külüne mahsur hey koca çınar dallarında hayat yaprak yaprak sarkıyor gözlerinden mehtap mürek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruh-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimizdeki Nimet', 'elimizdeki-nimet-murat-sayim-4gbgb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkım elimizde çok büyük nimet var.

Ben senin için

Sen benim için,

Ben senin için

Sen benim içimsin.', 'Aşkım elimizde çok büyük nimet var. Ben senin için Sen benim için, Ben senin için Sen benim içimsin....', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/elimizdeki-nimet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vapurdayım', 'vapurdayim-murat-sayim-9vb8d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koltuğun üstünde bırakılmış

Eski bir gazeteyi okuyor biri.

Bir diğeri,

Tostunun içinden uzayan kaşarı edeplice yemeye çalışıyor.

Vapurdayım.

Deniz geri geri gidiyor.

Bir diğeri dalmış uzaklara

Bir tanesi martıları sayıyor

Yan gözle birbirlerine bakıyorlar.

Kiminin jöleli, kiminin ıslak saçları.

Sıcak çay dağıtıyor garson.

Vapurdayım.

Biri boynunu bükmüş,

Yandakinin gazetesini okuyor.

Bir cep telefonu çalıyor,

Kimse üstlenmiyor.

Vapurdayım.

Simidin susamları, koltuğun üstünde.

Minareler geçiyor pencereden

Dalgalar el uzatıyorlar,

“kurtarın”der gibi.

Vapurdayım.

Yalnızım.', 'Koltuğun üstünde bırakılmış Eski bir gazeteyi okuyor biri. Bir diğeri, Tostunun içinden uzayan kaşarı edeplice yemeye çalışıyor. Vapurdayım....', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/vapurdayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali Bey (Portre)', 'ali-bey-portre-umit-kilislioglu-ozger-djjyi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne mirasyediydi Ali bey, ne asilzâde

Ne kadınlar vardı yaşamında, ne bâde

Yaşadı, olabildiğince sade

Her türlü karmaşaden âzâde

Gitti bitince vâde

Yüzünde mutlu bir ifade.

(Kapılar kitabından)', 'Ne mirasyediydi Ali bey, ne asilzâde Ne kadınlar vardı yaşamında, ne bâde Yaşadı, olabildiğince sade Her türlü karmaşaden âzâde Gitti bitinc...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ali-bey-portre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esin II', 'esin-ii-ahmet-aksoy-eb7ky', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne zaman geçsen şakaklarımdan

bir tutam saç akar alnıma

ellerim kan olur dökülür

gözlerin geçer uğulduyarak rıhtımdan

ben seni sana yazmışım esin kıvamında

sevdiğim sen öl ben ölmeden

toprak ol bir yağmur damlası kadar

ruhum içinde saklanır

sevgilim sen öl ben ölmeden

toprağında büyüteceğim aşkı

ve bir bebek gibi olgunlaşacak hayat

cennete daha çok var aydınlık', 'ne zaman geçsen şakaklarımdan bir tutam saç akar alnıma ellerim kan olur dökülür gözlerin geçer uğulduyarak rıhtımdan ben seni sana yazmışım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/esin-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürrealist Gül', 'surrealist-gul-murat-sayim-ohmwg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kendi dikeniyle yırtıyor

Yapraklarını gül.

Kanamış rengi.

Solgun gözyaşı gamzesinde birikmiş

Melül sürrealist makyajı üstünde.

Varoluşçuluğu bile bile

Bekliyor ölümü.', 'Kendi dikeniyle yırtıyor Yapraklarını gül. Kanamış rengi. Solgun gözyaşı gamzesinde birikmiş Melül sürrealist makyajı üstünde. Varoluşçuluğu...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/surrealist-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzden İz', 'i-zden-i-z-murat-sayim-0d5z0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüzgar tüylerini 

Diken diken yapmış denizin.

Üşüyor.

Kafir ve çıplak.

Dışlanmış.

Ürpertiliği yaşıyor içinde.

Abus suratlı sevgilisinin 

Yeniden doğumunu bekliyor,

Sabaha ve aşka...', 'Rüzgar tüylerini  Diken diken yapmış denizin. Üşüyor. Kafir ve çıplak. Dışlanmış. Ürpertiliği yaşıyor içinde. Abus suratlı sevgilisinin  Yen...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/izden-iz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çıkar', 'ne-cikar-umit-kilislioglu-ozger-kxwbm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gerçek fikir adamı, sanatçı, politikacı

Gülme öyle acı, acı! 

Arayıp sormuyorlarsa seni

Duymuyor, duyurmuyorlarsa sesini,

Sabret; 

Bu iyiye işaret.

Hele bir bu dünyaya veda et,

Arkandan nutuklar,

Mezarına çiçekler atarlar,

Bir iki gün seninle kalkıp, seninle yatarlar.

Hatta alkışlarlar bile.

Haydi derler, çok değerli ınsandın, güle güle.

Cenazende yürürler önde başları,

Gözlerinde timsah gözyaşları.

Çoktan hakettiğin ödülleri alamamışsan,

Gündemlerinde bir gün bile kalamamışsan,

Üzülme, senin de gelir sıran.

Senin kalbini kıran,

Arkandan ağıtlar yakar.

Sen kusura bakma, 

Onlar hem bilgisizdir, hem sakar.

Sen kendi değerini biliyorsun ya,

Onlar anlamasalar ne çıkar? 

(Kapılar kitabından)', 'Gerçek fikir adamı, sanatçı, politikacı Gülme öyle acı, acı!  Arayıp sormuyorlarsa seni Duymuyor, duyurmuyorlarsa sesini, Sabret;  Bu iyiye ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-cikar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Sıcak', 'sicak-sicak-murat-sayim-2qwzh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buhran güneş

Yapışıyor tenime.

Kan-ter içinde gündüz

Vıcık vıcık bir rüzgar,

Sıcak diliyle yalıyor çehremi

Her adımda halvet içine giriyorum.

Ben mi esriğim,

Yoksa Yaz mı? 

Bu boğmaca yaz aylarında

Ağır ağır çıkıyorum merdivenleri.', 'Buhran güneş Yapışıyor tenime. Kan-ter içinde gündüz Vıcık vıcık bir rüzgar, Sıcak diliyle yalıyor çehremi Her adımda halvet içine giriyorum...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sicak-sicak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalışma Masam', 'calisma-masam-murat-sayim-e0in1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çalışma masam bakıyor bana

Rahmetli

Bir göz var budağında

İzliyor beni.

Neydin sen

Çam mı? Meşe mi? 

Belki de Gürgen? 

Hasret kaldığın neşe mi? 

Ağlama masam ağlama

Hakkını verecem senin 

Yazacam eski dostlarının üstüne

Yazdıklarımla bir sürü ağaç dikecem

Kurak beyinler üstünde.', 'Çalışma masam bakıyor bana Rahmetli Bir göz var budağında İzliyor beni. Neydin sen Çam mı? Meşe mi?  Belki de Gürgen?  Hasret kaldığın neşe ...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/calisma-masam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölme Ölme', 'olme-olme-murat-sayim-cwinm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kirpiklerime örs bağlamışlar 

Bu akşam,

Ama yine de yaşatacağım geceyi.

Biliyorum,

Sabah çalacak hantal sessizliği

Uza akşam uza...

Şöyle uzaya doğru

Yıldızlara değ de gel

Ben buradayım.', 'Kirpiklerime örs bağlamışlar  Bu akşam, Ama yine de yaşatacağım geceyi. Biliyorum, Sabah çalacak hantal sessizliği Uza akşam uza... Şöyle uz...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olme-olme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mülteci', 'multeci-murat-sayim-rv4yi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mülteci olmaya mı özendin? 

Hangi gemidesin 

Nereye, kimlerle gitmektesin,

Biliyor musun? 

Ey! TAŞ 

Kuruyemişimin içindesin', 'Mülteci olmaya mı özendin?  Hangi gemidesin  Nereye, kimlerle gitmektesin, Biliyor musun?  Ey! TAŞ  Kuruyemişimin içindesin...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/multeci-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiire Şair Kurban', 'siire-sair-kurban-murat-sayim-gcsaf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“bir şairin kadını olacaksın belki” dedim.

“birisinin bir şeyi olmak hoşuma gitmez  ” dedi.

“o zaman şiirlerimin kadını ol” dedim.

“bak o olur” dedi.

E! Böyle şiire şair kurban', '“bir şairin kadını olacaksın belki” dedim. “birisinin bir şeyi olmak hoşuma gitmez  ” dedi. “o zaman şiirlerimin kadını ol” dedim. “bak o ol...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siire-sair-kurban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyar', 'i-htiyar-murat-sayim-8ie2d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dizeler ihtiyarlamış

Zar zor yürüyorlar.

“aman yormayalım sizi

buyurun oturun şöyle

biraz soluklanın.”

...........................

...........................

-bırakın dinlensin.

...', 'Dizeler ihtiyarlamış Zar zor yürüyorlar. “aman yormayalım sizi buyurun oturun şöyle biraz soluklanın.” ........................... ............', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ihtiyar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-murat-sayim-flkwi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kesilmiş ipleri birbirine bağlayan düğümdür.

Aynadaki sessizliğin dilidir.

Yanındakine bir yıldızın kaydığını göstermeye çalışırken, geride kalan izdir.

Denizde sektirdiğin taşın son düşüşüdür.

Okuyanların ebe olduğu saklambaç oyunudur.  		

Çocuk doğduktan sonra anne rahminde kalan yalnızlıktır.

Sıçrayan balığın gördüğüdür.

Ağlarda arkadaşını arayan susamış balıktır.

Burada anlatmak isteyip de anlatamadığımdır.', 'Kesilmiş ipleri birbirine bağlayan düğümdür. Aynadaki sessizliğin dilidir. Yanındakine bir yıldızın kaydığını göstermeye çalışırken, geride ...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/siir-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-umit-kilislioglu-ozger-kdnyk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aslı yok ya,

Yaşadığımız mekânda

Farklı bir boyutta bir ülke 

Ve bu ülkede bir takım 

İnsanlar varmış.

Özel bir bölme varmış aramızda

Bir tarafı ayna, bir tarafı cam

Onlar yalnız kendilerini görüyormuş, biz onları

Pek seviyorlarmış aynalı salonları.

Ülkelerinin adı ''Ruya Ülkesi''ymiş

Bizi en çok rahatsız eden de

Kendilerinin duymadığı

Horultu sesiymiş.

Paraları öyle çok, öyle çokmuş ki! 

Karınları öyle tokmuş ki! 

Pazarları at biniyorlarmış,

Cumartesileri dansedip, 

Tepiniyorlarmış.

Geziyorlarmış sırtlarında son moda ceket,

Umurlarında değilmiş memleket.

Yazı görmeyen baharlar,

Sokak çocukları,

Dövülen kadınlar,

Cinayetler, intiharlar,

Yaşlılar yurtsuz, yersiz,

Yaşayıp gidiyorlarmış

Hepsinden habersiz.

Bilmem kaçıncı sevgilisinden ayrılmış da

Yenisini aramaya çıkmış kimi,

Kimi ise reklâm uğruna

Kandırmış hâkimi, hekimi.

Bilmiyorlarmış taksitmiş, sıraymış,

Her kapı onlara açılıyormuş,

Anahtarları paraymış.

Nasıl olmuş bilinmez,

İçlerinden biri bir gün uyanıvermiş! 

Birden arkası görünmüş aynanın,

Yananla birlikte canı yanıvermiş! 

Gönlünü kederlere salmış.....

Derken bir ninni sesi, biri gelip sallamış

Beş dakika geçmeden

Tekrar uykuya dalmış.

Masalın elbet var özü; 

Hakça kazanıp, iyi yaşayana değil sözü,

Bedenin bir yerine iğne battığında 

Acısını duymayana,

Bütün olduğumuzu görmeyene,

Gafile...

Ama ne dersek diyelim,

Biliyoruz ki

Nafile...

(Kapılar Kitabından)', 'Aslı yok ya, Yaşadığımız mekânda Farklı bir boyutta bir ülke  Ve bu ülkede bir takım  İnsanlar varmış. Özel bir bölme varmış aramızda Bir ta...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/masal-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun', 'suskun-murat-sayim-2cb07', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlıyor köpek geceye,

Melodisini bozarak kalbimin.

Gündüze aşık rüzgar

İtiyor geceyi.

Bense içerde, kuvöze konmuş bebek gibi

İzliyorum onları.

Karışmıyorum.

Hangisine laf anlatayım.', 'Ağlıyor köpek geceye, Melodisini bozarak kalbimin. Gündüze aşık rüzgar İtiyor geceyi. Bense içerde, kuvöze konmuş bebek gibi İzliyorum onlar...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/suskun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Dizeleri Yazdıran Sensin', 'bana-dizeleri-yazdiran-sensin-murat-sayim-06mil', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilseydin konu olacağını

Binlerce şiire

Sararır mıydın, baharının sonunda? 

Kim bilir ne hayallere vesilesindir, 

Sallana sallana düşerken yere.

Kimi ayrılık der sana

Kimi ölüm

Hüzün der biri

Bir diğeri yalnızlık

Ben ne diyeyim sana

Biliyorum istemezsin

Üzerine basa basa geçenin anmasını seni

Ama ne yapayım

Bana dizeleri yazdıran sensin.', 'Bilseydin konu olacağını Binlerce şiire Sararır mıydın, baharının sonunda?  Kim bilir ne hayallere vesilesindir,  Sallana sallana düşerken y...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bana-dizeleri-yazdiran-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Şiir İlişkisi', 'sair-siir-i-liskisi-murat-sayim-tgzsm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendini arar şiirinde şair

Hep yazar bulamadığı için

İlkin,

Şiir şairde saklıdır.

Sonra,

Şair şiirde.

Şairi bilen yalnızca şiir

Şair şiiri ne bilsin

Şiir saklar şairi şairden

Narsistir tüm şiirler

İsterler şairden kendilerinde benzer şiirler.', 'Kendini arar şiirinde şair Hep yazar bulamadığı için İlkin, Şiir şairde saklıdır. Sonra, Şair şiirde. Şairi bilen yalnızca şiir Şair şiiri n...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sair-siir-iliskisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz İle Kış', 'yaz-i-le-kis-murat-sayim-ogj7e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki sevgili bir kere olsun,

Buluşamamışlardır söz verdikleri yerde,

Biri gider diğeri gelir.

Şahittirler aralarındaki platonikler

Söyleyemezler gerçeği

Bir kovalamacadır gitmekte

Yıllar bir aşk uğruna yitmekte.', 'İki sevgili bir kere olsun, Buluşamamışlardır söz verdikleri yerde, Biri gider diğeri gelir. Şahittirler aralarındaki platonikler Söyleyemez...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yaz-ile-kis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-murat-sayim-6ytjo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uçurtmasının takıldığı

Elektrik telleridir

Çocuğa özgürlüğü anlatan.', 'Uçurtmasının takıldığı Elektrik telleridir Çocuğa özgürlüğü anlatan....', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ozgurluk-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum', 'mum-murat-sayim-2y9vn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yas mıdır gerçek olan

Bir mum ışığı sükunetinde? 

Dingin olan ben miyim

Çaçaron sessizliğin içinde? 

İri gölgeler, niye şimdi

Duvarlarda sallanırlar

Yankı gibi? 

Kalbim.  Duvarlar.  Yankı.

Ceninim odanın bir köşesinde

En büyük gölgem belli belirsiz

Mırıldanmakta son bestesini

Yankı.  Duvarlar.  Kalbim.

Halvetteyim

Bir mum attı beni içeri

Gölgemdeyim

Duvarlar.  Yankı...', 'Yas mıdır gerçek olan Bir mum ışığı sükunetinde?  Dingin olan ben miyim Çaçaron sessizliğin içinde?  İri gölgeler, niye şimdi Duvarlarda sal...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sensiz', 'seni-sensiz-murat-sayim-gzakm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duydum sesini sessizliğin

Canlıydı tüm nesneler

Konuştular bana seni

Seni sensiz anlattılar, olmadı.

Çıktım dışarı

Yumuk yumuk rüzgar çarptı 

Bana.

Eski bir ev geçti yanımdan

Çatısından kuşların sesi gelen

Özledim yaşamadığım duyguları

Sensiz seni anlattılar, olmadı.

Girdim içeri

Yumuk yumuk rüzgarla beraber

Kapadım kapıyı

Yok oldu gitti rüzgar

Seni sensiz anlattım, olmadı.', 'Duydum sesini sessizliğin Canlıydı tüm nesneler Konuştular bana seni Seni sensiz anlattılar, olmadı. Çıktım dışarı Yumuk yumuk rüzgar çarptı...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-sensiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Us Tüccarı IV', 'us-tuccari-iv-ahmet-aksoy-4xxiy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I

talan yemiş uzuvlar zamana tutsak

çözül bir çözül de gökten kendine bak

geldiğin gittiğin gibi olmayacak

üflesen nefes havaya karışacak

II

hangi tufandan sana kalmış hayat

engine uzanan damarlar kesik doğru

cansız bedenler toprakta hayat

bir nefeslik ömür suda buğu', 'I talan yemiş uzuvlar zamana tutsak çözül bir çözül de gökten kendine bak geldiğin gittiğin gibi olmayacak üflesen nefes havaya karışacak II...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/us-tuccari-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-murat-sayim-7g67v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boşluğa sormuşlar

“dolu ne demek” diye

benim çıplak halim demiş.', 'Boşluğa sormuşlar “dolu ne demek” diye benim çıplak halim demiş....', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bosluk-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-murat-sayim-92h3v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk başta

Şiirimin adını koydum

Azıcık yaşasın diye 

Son.', 'İlk başta Şiirimin adını koydum Azıcık yaşasın diye  Son....', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-murat-sayim-q6f04', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kucak kucağa güllerin kokuları

Geziniyorlar yazın sarısı içinde.

 Mıhlanmış duruyorum öylece

 Yaz geliyor dönüyor bende

Nefes nefes, nefis, nefs

Kokluyorum yazı

Uzakta mısın yoksa yakınımda mı? 

Aşk dedikleri sen misin? 

İçimde hissederken varlığını

Dışımda bulamadığım.', 'Kucak kucağa güllerin kokuları Geziniyorlar yazın sarısı içinde.  Mıhlanmış duruyorum öylece  Yaz geliyor dönüyor bende Nefes nefes, nefis, ...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yaz-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hantal Gece', 'hantal-gece-murat-sayim-wd9oq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece yavaşlıyor hayat

Hızlı düşünürken  kendisini

Boğuluyor sanki

Düşünceler ip gibi

Düşünceler

Asıyorlar geçmiş hayatımın 

Acılarını 

Bense şaşkın, geleceği umuyorum

Avcının dürbününden görünen ceylan gibi

Şimdiyim ben aslında biliyorum

 Gelecek geçmiş, geçmiş gelecek sanki

Kurtulmayı bekliyor hayat

Ağlara takılmış balık gibi

Düşünceler katil

Düş hayat.', 'Gece yavaşlıyor hayat Hızlı düşünürken  kendisini Boğuluyor sanki Düşünceler ip gibi Düşünceler Asıyorlar geçmiş hayatımın  Acılarını  Bense...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hantal-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-murat-sayim-zobnn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tüm sesleri duyuyorum

Seni beklerken

Erkenden enseme soluyor rüzgar

Üzgün sanıyorum herkesi, her şeyi

Erkeksi bir yalnızlıkla tutuyorum kendimi

Unutkanlık alıyor bir kuşun gözünden beni

Uslu uslu o da özlüyor seni

Yorgun arabalar geçiyor yanımdan

Çiğnenirim diye argolar savuruyorum

Avutuyorum kendimi bir çingene neşesiyle

Sonra

Sesini duyuyorum çok şükür

Önce ayak seslerin

Sonra gözlerin derken kokun

Ve tenin

Beklemek bitiyor seni

Beklerken.', 'Tüm sesleri duyuyorum Seni beklerken Erkenden enseme soluyor rüzgar Üzgün sanıyorum herkesi, her şeyi Erkeksi bir yalnızlıkla tutuyorum kend...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beklemek-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklara', 'cocuklara-murat-sayim-l5yt3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendi geleceğimden korkup

Sığınıyorum sizinkilere.

Gözlerinizde buluyorum

Pandora’nın kutusundan çıkan son hediyeyi.

Ne mutlu geleceğe bilmeden gidene', 'Kendi geleceğimden korkup Sığınıyorum sizinkilere. Gözlerinizde buluyorum Pandora’nın kutusundan çıkan son hediyeyi. Ne mutlu geleceğe bilme...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cocuklara-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Oğul İki Baba', 'i-ki-ogul-i-ki-baba-murat-sayim-lq5u3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Babam yitiriyor babasını

Gözleri korkudan uzak

Alışkanlık var hayata

Koparıp atamıyor sıcak yaşlarını gözlerinden

Soğuk bekleyişi sürüyor sessizce

Bense uzakta, izliyorum

Babamı yitirirken babasını

Korku kucaklamış gözlerimi

Alışamadım alacakaranlıktaki

Ahiret yolculuklarına 

Sıcak sıcak yaşlanıyorum

Yaslanıyorum sana baba.', 'Babam yitiriyor babasını Gözleri korkudan uzak Alışkanlık var hayata Koparıp atamıyor sıcak yaşlarını gözlerinden Soğuk bekleyişi sürüyor se...', ARRAY['Türk Edebiyatı','Şiir','Murat Sayım']::text[], 8.5, '{"poet":"Murat Sayım","poet_slug":"murat-sayim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-ogul-iki-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Fark Eder', 'ne-fark-eder-bekir-mutlu-gokcesu-v14hp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tutsaklığım sana

Özgürlüğün ta kendisi

Aslında

Seni senden çok 

Hissediyorum ya

Ruhumda

Bana benden yakınsın ya

Sonuçta

Ne farkeder

Ha buradasın

Ha orada...', 'Tutsaklığım sana Özgürlüğün ta kendisi Aslında Seni senden çok  Hissediyorum ya Ruhumda Bana benden yakınsın ya Sonuçta Ne farkeder Ha burad...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ne-fark-eder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyde Sabah', 'koyde-sabah-abdil-yildirim-8xm3t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ezan sesi ile yırtılır perde,

Ufuktan aydınlık dolmaya başlar.

Bir damla ışığın olduğu yerde,

Karanlığın rengi solmaya başlar.

Seherde zikr ile açılır güller,

Bülbül gözyaşını silmeye başlar.

Rızkını arayan nasırlı eller,

Rahmet kapısını çalmaya  başlar.

Kuşlar şarkı söyler, horozlar öter,

Köye bir canlılık gelmeye başlar.

Ocaklar yakılır, dumanlar tüter,

Artık köyde sabah olmaya  başlar.', 'Ezan sesi ile yırtılır perde, Ufuktan aydınlık dolmaya başlar. Bir damla ışığın olduğu yerde, Karanlığın rengi solmaya başlar. Seherde zikr ...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/koyde-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Dönmeyecekmiş Gibi Bırakıp Gitmek Bir Şehri', 'hic-donmeyecekmis-gibi-birakip-gitmek-bir-sehri-melih-coskun-3p8v5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç dönmeyecekmiş gibi bırakıp gitmek bir şehri

Bir ölüyü toprağa bırakıp gitmek gibidir

En çok onda kanasan da

Onda ağlasan da en çok 

Bir şehri terk etmek 

Eski bir sevdadan vazgeçmek demektir 

Dost gülüşlerinden 

Güneşinden ve ıslaklığından 

Bahaneler aramak ne kadar gereksiz artık 

Kader diyerek adına yaşanılan bütün saçmalıkların. 

Evet bırakıp gittim 

Aslında bırakıp gittim de diyemem 

Sadece gittim...

Sadece gülüşlerimi bıraktım size 

Çok ağlamıştım fakat hiçbiriniz görmemiştiniz...

Sadece gittim 

Mazeretler uydurmadım 

Ve nefret etmedim vazgeçtiğim hiçbir şeyden 

Fırtınaya kızıp ıssızlığa sığınmaktı belki de benimkisi

Sadece gittim 

Gitme kal diyen yoktu çünkü ardımda...', 'Hiç dönmeyecekmiş gibi bırakıp gitmek bir şehri Bir ölüyü toprağa bırakıp gitmek gibidir En çok onda kanasan da Onda ağlasan da en çok  Bir ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hic-donmeyecekmis-gibi-birakip-gitmek-bir-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rahmet Yağıyor', 'rahmet-yagiyor-abdil-yildirim-pd2qk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine duman çöktü gönül dağına,

Sağanak halinde hasret yağıyor.

Tutuldum ayrılık  fırtınasına,

Yufka yüreğime sıklet  yağıyor.

Dertli aşıkların şiirlerinden,

Istıraplar hissedilir derinden,

İnleyen neylerin nağmelerinden,

Ayrılıklardan şikayet yağıyor.

Fani aşklar cüz''i bir lezzet verir,

Gelir bin mihnetle karşımda duru,

Bir üzüm yedirir, yüz tokat vuru,

Bir zevkin peşinden bin dert yağıyor.

Geçmiş zaman ölü, gelecek muhal,

Ne mazi tad verir, ne de istikbal,

Ruhuma sıkıntı veriyor bu hal,

Düşüncelerime zülmet yağıyor.

Bir süre hayata bu gözle baktım,

Aldığım dehşetten çıldıracaktım,

İman gözlüğünü gözüme taktım,

Gördüm ki âleme rahmet yağıyor.', 'Yine duman çöktü gönül dağına, Sağanak halinde hasret yağıyor. Tutuldum ayrılık  fırtınasına, Yufka yüreğime sıklet  yağıyor. Dertli aşıklar...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/rahmet-yagiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğaçlama', 'dogaclama-bekir-mutlu-gokcesu-lqhg7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DOĞ duk/ fenamı oldu

AÇ tık/ yedik, içtik iyi de ettik

LA fladık/ laf lafı açtı

MA kasladık/ bak bu olmadı 

Doğaya uymadı...', 'DOĞ duk/ fenamı oldu AÇ tık/ yedik, içtik iyi de ettik LA fladık/ laf lafı açtı MA kasladık/ bak bu olmadı  Doğaya uymadı......', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dogaclama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekâmül', 'tek-mul-umit-kilislioglu-ozger-4gat5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen bir çocuktun sen,

Yaşlı biriydin bazen.

Törpülemeye şımarıklığı,

Gerekliydi biraz hayal kırıklığı

Tartıştığım komşunun sözündeydin

Kırgın bakan annemin gözündeydin

Düştüğüm, incindiğim, yandığım,

Her kazadaydın tesadüf sandığım.

Eskiden yükseklerden inmezdim

Azla yetinmezdim

Bana birazcık yokluğu gösterdin

Çünkü şükürde olmamı isterdin.

Acele ettiğimde beklettin uzun uzun

Ben bunu nelere, nelere yordum

Oysa bir parçasıydı yolculuğumuzun

Sabrı öğreniyordum.

En çok kızdığımı bana gönderdin

Çünkü beni adam etmekti derdin

Öfkemin sebebi bendim

Bunu nihayet öğrendim.

Eğitiyor beni çocuğum, kocam

Öğrencilik zormuş be Hocam! 

Başaramadıkça tekrarlanır durur sınav

Bazen karışır kim avcı, kim av.

Canım öğretmenim, artık biliyorum 

Saygıyla önünde eğiliyorum.', 'Bazen bir çocuktun sen, Yaşlı biriydin bazen. Törpülemeye şımarıklığı, Gerekliydi biraz hayal kırıklığı Tartıştığım komşunun sözündeydin Kır...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tekamul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vermeyi İstemese', 'vermeyi-i-stemese-abdil-yildirim-uh0q0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yolcuyum şu menzilde, bir nefeslik durmuşum,

Bu anahtar kapıyı açmak için verilmiş.

Beden denen kafese sığmıyor gönül kuşum,

Bu kanatlar sonsuza uçmak için verilmiş.

Vücudum bir fiskeyle yıkılacak bir konak,

Ölüm yeni bir hayat, kabir yeni bir durak,

Bu  çileli hayatın yükünden kurtularak,

İstirahat yerine geçmek için verilmiş,

Ömür sermayesi az, ihtiyaçlar bitmiyor,

İktidarımın eli, hiç bir şeye yetmiyor,

Ruhumun isteğini dünya tatmin etmiyor,

Eldekiler numune, tatmak için verilmiş.

Bir kerre tatmak için bu sofrayı sermezdi,

Başka sayfa açmasa bu sayfayı dürmezdi,

Vermek istemeseydi, istemeyi vermezdi,

Ölüm,ölümsüzlüğe geçmek için verilmiş.', 'Yolcuyum şu menzilde, bir nefeslik durmuşum, Bu anahtar kapıyı açmak için verilmiş. Beden denen kafese sığmıyor gönül kuşum, Bu kanatlar son...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vermeyi-istemese-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çokca Çalış', 'cokca-calis-sabit-i-nce-54zqz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '- Sevgili Öğretmenim Şükran Günay''a- 

yana yana pişeceksin, 

aşk oduna düşeceksin, 

her engeli aşacaksın, 

çalış, çalış çokca çalış 

şükür eden şakirt olur, 

şükretmeyen yolda kalır, 

erenler halinden bilir, 

çalış, çalış çokça çalış. 

kaynat kaynat pişir aşı, 

yoktur insanlığın yaşı, 

önce kendine vur taşı, 

çalış çalış çakça çalış. 

erene erenler varır, 

kendin bilen hakkı bilir, 

ince de bu yolda ölür, 

çalış çalış çokça çalış. 

sabit ince kayseri 10.03.2004', '- Sevgili Öğretmenim Şükran Günay''a-  yana yana pişeceksin,  aşk oduna düşeceksin,  her engeli aşacaksın,  çalış, çalış çokca çalış  şükür e...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cokca-calis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel & Nafile', 'gel-nafile-serdar-safran-hoym5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel ömrümün baharı,sensiz günüm kış oldu

Yetmedi teselliler,gönlüm sarardı soldu

Sensiz bahar gelse de yine, çiçekler açmaz 

Gel ey cân’ımın cân’ı,eşsiz  kelebek uçmaz 

Ekmeğim-aşım gibi,gözümde yaşım gibi

Gel gönlümün sultanı,ahret yoldaşım gibi

	

Gel ki şu yorgun gönlüm,çekmesin artık cefa

Gel dünyamı aydınlat,bulsun aşkında şifa

Nafile

Gelmez isen bu günde,söylediğim son sözüm

Bundan sonra faydasız,görmeyecektir gözüm…

Duymaz artık kulağım,gelsen de neye yarar

Kabrimdir son durağım,orda naaşım ağlar…

Ziyaret etsen bile,çiçek koysan üstüme

Fayda etmez, çaresiz …Ne yapsan da nafile…

(2004-Kastamonu)', 'Gel ömrümün baharı,sensiz günüm kış oldu Yetmedi teselliler,gönlüm sarardı soldu Sensiz bahar gelse de yine, çiçekler açmaz  Gel ey cân’ımın...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-nafile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağa çizildi', 'topraga-cizildi-cumhur-boratav-6sj4b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'toprağa çizildi.. gölgesinin uzunluğuna uyumlu biri gibi... buz tutmuş bir su kadar kırılgan ve keskin.. 

merdivenlerden in.. önce maskelerin üstüne kaplanmış gerçek yüzler göreceksin.. sağda solda karanlık.. düşer gibi gezin..sesin soracak, neredeyim? ..

(elin değdiğinde hissedeceksin, hafif bir sarsıntıyla dökülecek, bacakları kolları kırılmış plastik askerler, birkaç küçük yarış arabası, gözlerinden biri düşmüş bir bebek.. bir adım daha at.. ayağının altında çıtırdayacak...kırılmışlığı daha da kırılarak.. bir fırıldak.. duvara bak.. eski bir resim..eski bir araba...altında yorgun yıllar yazıyor olacak..biraz ilerle, yığılmış dosyalar arasındasın...hissettirilmeden paketlenmiş... paketin ağzında bir yazı: ''çizildi''... çizilince yağmuru emdi toprak.. yani kendini süzmek gibi..yani bir kağıt gibi eriyip kendine karışmak..) 

bir çocuk eliyle 

beceriksiz, eğrili büğrülü

ama ilginç bir haz alarak

kendi başına

toprağa çizildi', 'toprağa çizildi.. gölgesinin uzunluğuna uyumlu biri gibi... buz tutmuş bir su kadar kırılgan ve keskin..  merdivenlerden in.. önce maskeleri...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/topraga-cizildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilgaz', 'ilgaz-serdar-safran-3wrt8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin yarın Çankırı 

Yarın Kastamonu’da

Buluşurlar dorukta

Komşudur illerimiz

Dolambaçtır yolların

Karlıdır yamaçların

Başı dik ağaçların

Yuvası yeşil Ilgaz

Kurtuluş savaşında

Mermi taşır kağnıda

Donmuş Şerife bacım

Örtüsüz çocuğu da

Şimdi tatil yaparız

Pistte kayak kayarız

Oksijene doyarız

Gönlün şen olsun Ilgaz.

Bağlantıyı sen yaptın

Geçmişten geleceğe

Gönülde her hücreye

Taht kur sen,güzel Ilgaz…

(Mart/2004-Kastamonu)', 'Senin yarın Çankırı  Yarın Kastamonu’da Buluşurlar dorukta Komşudur illerimiz Dolambaçtır yolların Karlıdır yamaçların Başı dik ağaçların Yu...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ilgaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-abdil-yildirim-dr4j7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğime bir çekirdek bıraktın,

Açıldı gönlümde gül öğretmenim.

Karanlık dünyama bir ışık yaktın,

Aydınlandı birden yol öğretmenim.

Uygarlığın meşalesi elinde,

Kelimeler çiçek açar dilinde,

Sevgi diyarında, nur ikliminde,

Gönlümü okşayan el öğretmenim.

Sensin geleceği aydınlatan nur,

Çok hakkın var helal eyle ne olur,

Bir harf öğretene köle olunur,

Sana olmak gerek kul öğretmenim

Yirmidört Kasımlar bayramdır gerçek,

Bu bayramı candan kutlamak gerek,

Bulamadım sana layık bir çiçek,

Gönlümü getirdim, al öğretmenim.

Bayrağa sevdalı ezelden beri,

Canından kutsaldır yurdun her yeri,

İrfan ordusunun yiğit erleri,

Kimi şehit, kimi dul öğretmenim.', 'Yüreğime bir çekirdek bıraktın, Açıldı gönlümde gül öğretmenim. Karanlık dünyama bir ışık yaktın, Aydınlandı birden yol öğretmenim. Uygarlığ...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ogretmenim-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Şerefe', 'sensizlige-serefe-volkan-cosgun-8sowy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni görür,

sonra aşık olurum,

seni görür görür,

aşık olurum aşık olmama...

nefes alır alır,

seni üflerim aynaya nefes diye,

sonra seni aynada görür,

sonra tekrar tekrar

''şerefe'', derim,

sonra aynada izin yok olur,

sonra sonra,

''sensizliğe şerefe''...', 'seni görür, sonra aşık olurum, seni görür görür, aşık olurum aşık olmama... nefes alır alır, seni üflerim aynaya nefes diye, sonra seni ayna...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlige-serefe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'birin Bir''i', 'birin-bir-i-volkan-cosgun-z80lt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bırak uçurumlar yol alsın yanaklarından,

günden güne erisin hayatının buz dağı,

kendini sattırdıkça hayat,

bunu başardıkça,

bütün huzursuzluğu teslim et boşluğa,

yok olsun gitsin...

aynalarda her zaman kendini gör,

benim gibi bir bedelin esiri olma,

ben aynalara asla bakamamıştım,

korkmuştum kaybetmek ve kaybedilmekten,

başaramadım,

sonra hayat ummadığım kadar acıtmıştı bakışlarımı,

sen başar ki,

azıcıkta olsa benim acımı da hafiflet kendi acınırlığında,

hayatın acıtacak bir Bir''i olsun,

o bir, ben

o Bir''de sen ol!', 'bırak uçurumlar yol alsın yanaklarından, günden güne erisin hayatının buz dağı, kendini sattırdıkça hayat, bunu başardıkça, bütün huzursuzlu...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birin-bir-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-volkan-cosgun-an4qj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geceleyin parlak ışıklar arasındalar,

bakıyorum da ne kadar mutluluar? ! 

kimi el ele yine gezmeye,

kimi kol kola gezmekten bir yineliğe,

bunlar hep böyle mi olurlar? ! 

hepsinin yüzünde bir gülümseme,

hepsini de çalıntı bir armoni...

bir de bana bak o ışıkların altında,

yine bir yinelikte tanı bir de beni,

ama yüzüme değil,

kanayan kalbime...', 'geceleyin parlak ışıklar arasındalar, bakıyorum da ne kadar mutluluar? !  kimi el ele yine gezmeye, kimi kol kola gezmekten bir yineliğe, bu...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/insanlar-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyorsun Yine', 'yasiyorsun-yine-volkan-cosgun-x6ei5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'al bir tadımlık daha,

bir nefes daha çek atmosferden,

yine gece olsun,

bir gün eksilt hayatından,

kapa gözlerini,

Kafka...

ruhun esir,

salıver hepsini 

teker teker,

ve kimsecikler duymadan,

kimseciklerin olmadan,

huzura lime lime

boşal...', 'al bir tadımlık daha, bir nefes daha çek atmosferden, yine gece olsun, bir gün eksilt hayatından, kapa gözlerini, Kafka... ruhun esir, salıv...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasiyorsun-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Yazılıyorum', 'yanlis-yaziliyorum-volkan-cosgun-2upk9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yanlış yazılıyorum,

hiç bir kaygım yok; 

çünkü kendimi yazıyorum şimdi.

hiç bir kaygım olmamalı, 

hiç bir an  beni acıtmamalı...', 'yanlış yazılıyorum, hiç bir kaygım yok;  çünkü kendimi yazıyorum şimdi. hiç bir kaygım olmamalı,  hiç bir an  beni acıtmamalı......', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yanlis-yaziliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Hüzün... Bu Aşk Sana Emanet', 'i-ste-huzun-bu-ask-sana-emanet-volkan-cosgun-mf932', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'herşey''e herşeyin hüzünle başladığı gibi başlamak,

mutluyken bile

 kendini mutlu olarak inandırmaya çalışırken bile,

bir adım ötede bekleyen bir belirsizliğin haberini ruh''tan beden''e taşımak...

''ben mutlu bir adamım! ''

- mutlu insanlar topluluğu...

buna benzer binlerce serzeniş...

süre gelen bir akış içinde, döne giren olgularla, hayat

herşey''imi sen mahvettin,

ve bu yüzden Sen varken hiç okunmasın,

hiç bir ağza dolanmasın ben''li sevgi sözcüklerin...', 'herşey''e herşeyin hüzünle başladığı gibi başlamak, mutluyken bile  kendini mutlu olarak inandırmaya çalışırken bile, bir adım ötede bekleyen...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iste-huzun-bu-ask-sana-emanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller', 'guller-volkan-cosgun-dt6qc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sonsuz bir efkar bastı yine,

sevmediğim bir şarkı dilimin ucunda,

her anımda senin adın,

her an biraz daha senden uzak...

kıçı kırık bir hayatın sahibi,

benim,

şimdi elinde sana bir türlü veremediğim mutluluğun ardından,

ağlamaklı bir tebessümle

 bende bıraktıklarına selam ediyorum,

kıçı kırık o hayatın soluk gülleriyle...', 'sonsuz bir efkar bastı yine, sevmediğim bir şarkı dilimin ucunda, her anımda senin adın, her an biraz daha senden uzak... kıçı kırık bir hay...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guller-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''ndan', 'o-ndan-volkan-cosgun-hvjus', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çok uzaklardan geldi,

uzağın hasretini bıraktı,

ve gitti.', 'çok uzaklardan geldi, uzağın hasretini bıraktı, ve gitti....', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/o-ndan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi Yapmak', 'gibi-yapmak-umit-kilislioglu-ozger-illfp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '… gibi yaptık,

Bir yanlış yola saptık.

Yorgunken dinlenmiş gibi,

Yenilmişken yenmiş gibi.

Azken çok gibi,

Varken yok gibi.

Tokken açız dedik,

Gereğinden fazla yedik.

Gösterdik olmayanı olmuş gibi,

Öğretmenin anlattıklarından

Bir şeycikler anlamadık,

Gülümsedik bilgiyle dolmuş gibi.

Farkedemedik cehaletin ayıbını,

Gösteriş uğruna sineye çektik

Bilginin kaybını.

Borçlarımız da bu yüzden.

Harcadık varmış gibi,

Tasarruf armış gibi.

O kartlardan kullandık,

Borç parayla giyinip kuşandık; 

Allanıp, pullandık.

Sonra ödeyemedik,

Kimseye diyemedik.

Ne demişti vaiz? 

Haramdı faiz.

İçin için kaynadık, aştık bendimizi

Herkesi aldattık, en çok da kendimizi.

Bu iki yüzlülüğü bir türlü yenemedik.

Her şeyi denedik de,

Dürüstlüğü denemedik.', '… gibi yaptık, Bir yanlış yola saptık. Yorgunken dinlenmiş gibi, Yenilmişken yenmiş gibi. Azken çok gibi, Varken yok gibi. Tokken açız dedik...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gibi-yapmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru+n''lar Dizisi', 'soru-n-lar-dizisi-volkan-cosgun-7cbzy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'en basit alın yazısıyla kalemde hayat,

oynanan bir oyundur,

ve bu oyunun içinde insanlar,

ve bu insanlar içinde basit alın yazılı hayat rolleri...

her rolde biraz acı,

biraz ar,

biraz seks,

ve hayatta kalmaya yetecek kadar esrarengizleştirilmiş  bir rol olma zorunluluğu...

lakin sen bunları kaldıramayacak kadar zorsan,

o zaman hayatın anlamı kalmaz,

ve sonsuzluk aranmalıdır artık.

çoğu insan da sonsuzluğu arar zaten,

ama ''ölümde''.

-acaba ölüm mü sonsuzluk,

yoksa ölümsüzlük mü...

bu da ayrı bir soru+n', 'en basit alın yazısıyla kalemde hayat, oynanan bir oyundur, ve bu oyunun içinde insanlar, ve bu insanlar içinde basit alın yazılı hayat roll...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/soru-n-lar-dizisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrolsun Tango', 'kahrolsun-tango-volkan-cosgun-an6vb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'arkana bakmadan yürü hızlı hızlı,

sokaklar ihenetkar,

baksana,seni de ele verdiler geçmişe,

vitrinlerde fahişeliğinin kalıntıları,

vitrinler ondan sürekli indirimde...

sonu gelmeyen bir kader oyunu bu,

her sonda yeni başlayan bir son,

kendine yetebilecek kadar kendinsin,

kendinden bezebilecek kadar başkası...

teninde aradığın bir damla sadakat,

ama teninde bulduğunhep bir damla gözyaşı...

haydi şimdiden kaybet bu oyunu,

topukların titresin arnavut kaldırımında,

çöz bağlarını  bedeninin,

haydi başlasın şu fahişe tango,

karanlığınla aydınlat geçmişini,

karanlığına aydınlan şu ilk adımda,

herşey sonsuz ritm üzerinde,

zavallılığın esaretine dayalı,

ve dudaklarında bir kaç kelime:

''ben...ben...ben...ben...ben...! ! ! ''', 'arkana bakmadan yürü hızlı hızlı, sokaklar ihenetkar, baksana,seni de ele verdiler geçmişe, vitrinlerde fahişeliğinin kalıntıları, vitrinler...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kahrolsun-tango-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılmasak', 'yanilmasak-volkan-cosgun-i3m02', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''sonu olmayanlar''  hayatta  ''bir anlık'',

''bir anlıklar''            hayatta  ''daima'',

''daimalar''              hayatta   ''yanılgı'',

''yanılgılar''               hayatta   ''hep var'',

''hep varlar''            hayatta   ''keşke olmasa...''', '''sonu olmayanlar''  hayatta  ''bir anlık'', ''bir anlıklar''            hayatta  ''daima'', ''daimalar''              hayatta   ''yanılgı'', ''yanılgıla...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yanilmasak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reçete', 'recete-volkan-cosgun-9438v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'işte,

herşeyi yazıyorum,

bilmek istediğin herşeyi...

hiç gülmedim,

ağlamadım da,

bitirmedim,

ama aslında başlamadım da...

elinden gelse,

tekrar benim olsan,

yakardın bütün dünyayı,

yakardın bütün dünyamı...

sevdin,

sevilmedin,

şarkılar söyledin,

daha da üzüldün...

sabah kalkmıyorsun bile,

güneşi çekmiyorsun içine,

yağmurlu hep günlerin,

bir de ağlardın utanmadan...

yeni bir şarkı daha başladı,

yeni bir sen daha suçlu,

hatırlamak bile istemiyorsun,

ama hatırlıyor durmadan paranoyan...

tahmin et o sadece benim,

hadi sil bir kalemde,

ben seni çoktan sildim,

işte ondan böyleyim...

beni unut,

unut,

sadece unut,

o zaman göreceksin...

dokunuyorum ruhuna değil mi,

acıyorum sana,

acıtıyor bakışlarım,

sen de acıtıyorsun...

karanlık korkutuyor mu,

herkes uyumuştur sen uyanıkken,

yine şafak doğuyor mu,

utanmadan beni hatırlarken...

karala bütün yazdıklarını,

paramparça et tüm fotoğraflarımı,

beni endişenle boğ,

sonra sadece unut...

unut...

sadece...', 'işte, herşeyi yazıyorum, bilmek istediğin herşeyi... hiç gülmedim, ağlamadım da, bitirmedim, ama aslında başlamadım da... elinden gelse, tek...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/recete-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabaha Karşı 03.11', 'sabaha-karsi-03-11-volkan-cosgun-7ej7s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saat ilerledikçe daralmalar başlıyor.

 Yeni bir günü kaldıramayacak kadar yorgun oluyorum.

 Hep aklımda bir soru yatıyor.

 Sormaya utanıyorum,çünkü cevap alamayacağımı biliyorum.

 Taze çiçeklerin,mis gibi baharların arasında kalabilseydim keşke… 

Keşke sevebilseydim, hatta sevilseydim birince… 

Siz nerede olduğumu hiç öğrendiniz mi karanlıktan… 

Sevebildiniz mi karanlığı…

Yoksa korkuyor musunuz… 

İnanmıyorum… 

Korkmayın gelin siz de… 

Gelin bir de benim gözlerimle görün umutsuzluğu, karanlığı, aldanmışlığı…

Bir saat daha akıttım hayatımdan.

Yok olmaya yüz tutar zaman,aynı zamanda beni de yok eder. 

Birkaç anı hatırlıyorum.

Onlarla yaşıyorum nice zamandır.

Zaten onlarda olmasa kim tutardı ki hayatın ipini…

Bir anda keserdim yoksa…

 “Kes”diye içinizden mi geçiriyorsunuz … 

Korktuğumu sanmayın… 

Acı çekmeye alıştım ben.

Bir anlıkların birindeyim sadece. 

Bu da geçer diye avutmaya alıştırmışım kendimi.

Kendimi kızgın bir çöl yapmışım, sonra derin bir deniz. 

Ardından annesi olmayan küçük ve yardıma muhtaç bir kız… 

Her şiir de benden varmış, her bende bir şiir… 

Taze sıkılmış portakal suyundan, Pazar günü ailece pikniğe gitmekten, bir sevgilim olupta  elini tutmaktan kim korkar olmuş acaba… 

Yaşıyorum zannetmeyin sakın… 

Nefes alıyorum sadece… 

Bazılarınız onu da yapmıyordur ya,neyse… 

Apışıp kaldım bunları yazarken.

Yazmayı sever misiniz… 

Sever misiniz ha…

Bilmezsiniz değil mi… 

Zaten hiç bilmediniz… 

Okurken kim bilir neler geçiyordur aklınızdan. 

Kim bilir neler neler aklınıza geldi de bir türlü beğenemediniz yazdığımı… 

“Sadece kendim için yazarım.”dedim bir türlü anlamadınız… 

Zaten hiçbir şey anlamıyorsunuz ya… 

Boş veriyorum artık… 

Siz de boş verin… 

Vallahi… 

Çok iyi oluyor.

 Ama yine de bir türlü

“Ah geçen zaman…

 Ah geçirdiğim o eski güzel yıllar…” 

Demekten kendimi alamıyorum…

Hayır hiçbir günüm güzel geçmedi benim.

Kandırma kendini…

Yalan söylüyorsun… 

Hep içinde bir kaygı vardı senin… 

Yazmaya bile kaygın vardı,hatırlasana… 

Nasıl tutuştun şimdi,gönlüm… 

Vicdan azabı mı çekmeye yelteniyorsun… 

Cümlelerim hala ayakta… 

Hepsi devrik,ama olsun… 

Tek bir satır bile aklamak istemiyorum aklımdan yazarken.

Saniye saniye kaydedin bunları dostlarım… 

Çünkü lime lime burnunuzdan getireceğim bunları, burnunuzdan… 

N’oldu,yine mi hakkımda kötü düşündünüz… 

Kesin şöyle demişsinizdir; “Ne zoru var bunun”. 

Bi zorum yok canım.

Sıkılan varsa, sadece biraz eğleniyoruz burada diye aldatsın kendini...

Anlayan zaten anlamıştır beni. 

Eğer sıkıldıysan bunları okumayabilirsin de… 

İnan ki kırılmam, çünkü bunu sen hep yaparsın zaten… 

Ne dinlersin, ne yazarsın, ne de okursun yazdıklarımı… 

Of, seni çok mı kırdım…

İnan ki yapmak istemezdim, ama bir yanım çatlak işte… 

Siz zorlarken çatlamıştı… 

Ağlamak istiyorum haliniz için… 

Ama buna değmiyorsunuz bile…

Acaba gidip yatsam mı sizi unutmak için… 

Saat sabaha karşı 03.11. 

Hadi canım atma dersiniz ya şimdi… 

İnadına oturayım bari.

Yazmaya devam edeyim… 

“Siz…

Siz.. 

Ah siz…”', 'Saat ilerledikçe daralmalar başlıyor.  Yeni bir günü kaldıramayacak kadar yorgun oluyorum.  Hep aklımda bir soru yatıyor.  Sormaya utanıyoru...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/sabaha-karsi-03-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru İşareti', 'soru-i-sareti-volkan-cosgun-xo66s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir soru işareti…    - ama yarım,tıpkı benim gibi…

İnanır mısın dün bunun için neler neler  yazmıştım.

Ama hepsi silinmiş,kesin bir şey olmuştur… 

Hayatın yarım kalan yönleri de bizim bir şeyliğimizden kaynaklanmıyor mu sanki… 

Hep bir taraflar boş diyoruz.

Hep ''yok'' diyoruz. 

Aslında biraz ayıp etmiyor muyuz… 

Şimdi ben ayıp ediyorum değil mi bunları size hatırlatmakla… 

Korkuyorsunuz çünkü… 

Yüz yüze kalmak istemiyorsunuz…

Aman, neden bunları yazıyorum ki; zaten bunları siz biliyorsunuz. 

Hepinizin bilinç altı kim bilir nelerle gizli… 

Kim bilir kimi nerede,kimi kiminle,neyi neyle birleştirip,ayırtıyorsunuz utanmadan… 

Pardon,siz meleksiniz değil mi… 

Yerinizde cennetlik…

Eminim orasıdır. 

Benim orada olmayacağım kesin. 

Yine  de Tanrı’nın gücüne gitmesin(bu da ne banal bi söz…) . 

Siz oradasınızdır,hadi sevinin… 

Durmayın… 

Doya doya  sevinin.

Tatminkar egocu parçaları sizler… 

Hatta bu söylenenler için yadırgarsınız beni… 

Eğer yaparsanız,siz de o kastettiğimdensiniz zaten… 

Ayıp diyenler bilinçaltında haz dağlarını aşar, garipseyenler akşamki rüyasında orgazm vtr’sine dalıp çıkarlar sessizce…

İçlerinde en seksapelleri vardır ki onlar birer haz melankonileri yaratıp, ertesi gün hiçbir şey yapmamış gibi tinsel nutukları atmayı sürdürmeye devam ederler… 

Biz de koyun gibi dinler dururuz onları… 

Hem de hiç usanmadan…

Tamam bu kadarı ağır kaçtı galiba… 

Hadi biraz kendimize gelelim… 

O zaman kaldığınız yerden devam…

Alın işte, sizin alıştığınız soru işaretinin devamı.

(hiç bir zaman bu soru işareti yanıtlan(a) madı.)', 'Bir soru işareti…    - ama yarım,tıpkı benim gibi… İnanır mısın dün bunun için neler neler  yazmıştım. Ama hepsi silinmiş,kesin bir şey olmu...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/soru-isareti-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Başlıklı Kız', 'kirmizi-baslikli-kiz-volkan-cosgun-0cgbk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gölgeler ülkesinde küçük kırmızı başlıklı kız, 

şimdi ne kadar da sevinçli olmalı,

bugüne kadar bütün herkesi kandırdı…

ya şimdi,

-kurdun suçsuzluğuna insanlar inanabilir mi? 

-anneannesi ezelden olmayan bir kıza lanet okunabilir mi? 

taptaze sevmeli ağaçları

taptaze sevişmeli yalanlarla,

orman hep gizemli bir düş,,

şapkası hep kırmızı olmalı kızın,

yalanları hep kırmızı…', 'gölgeler ülkesinde küçük kırmızı başlıklı kız,  şimdi ne kadar da sevinçli olmalı, bugüne kadar bütün herkesi kandırdı… ya şimdi, -kurdun su...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kirmizi-baslikli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Yarım Bütünlükleri', 'hayatin-yarim-butunlukleri-volkan-cosgun-hkw9u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-keskin bir bıçak ucunda,

yarım kalmış bir kitabın okunmamış son sayfasında,

gidilmekten son anda vazgeçilmiş bir piknik alanının,

son anda ezilmekten kurtulmuş yavru bir kedinin,

rüzgarın savurduğu bir yelkenliğe,

sonu gelmez bir kaderin mutsuzluğuyla,

hayatın,

hayata,

hayatı,

hepsi b-u-n-l-a-r-ı-n-; 

-h—a-y—a-t- y-a-r—ı-m k-a-l-mı—ş –b—i-r- b-ü—t—ü-n-l-ü-k', '-keskin bir bıçak ucunda, yarım kalmış bir kitabın okunmamış son sayfasında, gidilmekten son anda vazgeçilmiş bir piknik alanının, son anda ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayatin-yarim-butunlukleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Yanlışsa', 'ya-yanlissa-volkan-cosgun-99ufu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ya yanlışsa sevmek,

kaybetmekse her şeyi,

unutamamaksa,

salt acıysa ruhunda,

yalnızlıksa kalabalıkta', 'ya yanlışsa sevmek, kaybetmekse her şeyi, unutamamaksa, salt acıysa ruhunda, yalnızlıksa kalabalıkta...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ya-yanlissa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Oluyorum', 'asik-oluyorum-volkan-cosgun-j2f63', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ses getiren anlarımdan yalnızlığa…

“bir sen olmalıyken düşümde,

bir acı kaplamalıyken sessizliğimi,

yaşanmamış acılar kadar kutsal,

yaşanmışlıklar kadar hüzünlü,

sahte,

sahte olduğu kadar da yeniden,

işte yine aşık  oluyorum,

mutsuzluk çoktan kapımda…”', 'ses getiren anlarımdan yalnızlığa… “bir sen olmalıyken düşümde, bir acı kaplamalıyken sessizliğimi, yaşanmamış acılar kadar kutsal, yaşanmış...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/asik-oluyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler ve Şiirler', 'sairler-ve-siirler-volkan-cosgun-a4pgm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bütün şairleri toplasınlar,

bütün şiirleri  teker teker yaksınlar,

yaksınlar ki izi kalsın bazı şeylerin,

izleri olsun ki,

o zaman değeri anlaşılsın kağıtlardaki dizelerin…', 'bütün şairleri toplasınlar, bütün şiirleri  teker teker yaksınlar, yaksınlar ki izi kalsın bazı şeylerin, izleri olsun ki, o zaman değeri an...', ARRAY['Türk Edebiyatı','Şiir','Volkan Coşgun']::text[], 8.5, '{"poet":"Volkan Coşgun","poet_slug":"volkan-cosgun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sairler-ve-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Günlerdi', 'ne-gunlerdi-bekir-mutlu-gokcesu-sl9g3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Az önce 

Peynir ekmek yedim

Bir de zeytin

Çıkmaz sokaktaydı ama

Gökyüzüne çıkardı terası

O bekar evinin

Sıkı arkadaşlarıydık

Üniversite günlerinin

Tadı kalmış

Şu anki kadar taze

Damağımda

Bir de sen vardın ya

Hani o zamanlarda

İzi kalmış

Zeytuni gözlerinin

Göz yaşımda...', 'Az önce  Peynir ekmek yedim Bir de zeytin Çıkmaz sokaktaydı ama Gökyüzüne çıkardı terası O bekar evinin Sıkı arkadaşlarıydık Üniversite günl...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-gunlerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefa', 'vefa-bekir-mutlu-gokcesu-frwpx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben dediğim

Ben değilim

Vallahi

Eğer

Sen olmasaydın

O gün

Bana 

O deli yüreğinden

Yürekler vermeseydin

Burada

Bugün

Şu an 

Ben olmazdım

Belki de inan

Ama bugün

Burada

Sen yoksun

Bu benim

İçime sinmiyor...', 'Ben dediğim Ben değilim Vallahi Eğer Sen olmasaydın O gün Bana  O deli yüreğinden Yürekler vermeseydin Burada Bugün Şu an  Ben olmazdım Belk...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/vefa-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tefekkür', 'tefekkur-halil-i-brahim-ozdemir-w9hyv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuşlar, ruzgar rüzgar, uçuyor  kanat kanat,

Seyredin kare kare, bak tekrarı her saat...

Yazılmamış poemler, okunmamış şiirler

Gökyüzünde alfabe Allahım ne bu sanat,', 'Kuşlar, ruzgar rüzgar, uçuyor  kanat kanat, Seyredin kare kare, bak tekrarı her saat... Yazılmamış poemler, okunmamış şiirler Gökyüzünde alf...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tefekkur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Diye Bildiğim...', 'yar-diye-bildigim-i-lke-ersoy-tj1zr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oradasın,

Biliyorum...

Beklemeye zamanın yok

Yelkovan kuşları çoktan havalanmış

Gecikmiş bahar, yolunu şaşırmış

Hava, su, toprak, yanarken ateşlerde

Ala gözlerine düşmüş dördüncü cemre...

Sevdan, ilk bağbozumu gibi Ege''nin

Karadeniz''in deli boranı,

Anadolu''nun türkü kokan elleri...

Koynunda açıverdiğinde

Yediverene dönüşen bozkır gelinciği

Sevdan,

Hasretinle törpülediğin takvim yongası

Günü geceye ekleyip de,

Uykularınla bilediğin seher yazgısı

Adın gibi bilirsin yarim,

İstanbul''un sokakları sana çıkmaz,

Her köşe başı sana vurgun...

Uzundur da İstanbul''un saçları

Tarayıp durduğun yokuş yukarı

Sabır taşlarınla döşediğin,

Tel tel kaldırımlarını...

Oradasın, beklemeye zamanın yok

Yelkovan kuşları çoktan havalanmış

Avuçlarında gün batımı kızıllığı

Yeşile durmuş salkım söğüt

Bulut kesilmiş gökyüzü; ağlamaklı

İki çift sözüm var sana,

Durmadan menevişleniyor şuracıkta,

Seni yar bildiğim günden bu yana.

Biri müjdesi şavkıyan vuslatın,

Diğeri sevdam; 

Yüreğimin sırça kanadında...', 'Oradasın, Biliyorum... Beklemeye zamanın yok Yelkovan kuşları çoktan havalanmış Gecikmiş bahar, yolunu şaşırmış Hava, su, toprak, yanarken a...', ARRAY['Türk Edebiyatı','Şiir','İlke Ersoy']::text[], 8.5, '{"poet":"İlke Ersoy","poet_slug":"i-lke-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yar-diye-bildigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Gelirim', 'yine-gelirim-halil-kesken-fjnt5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasret kalmış dediler,gözlerin gözlerime

Rüzgara bir tebessüm,salsan yine gelirim

Kimseyi alma sakın,yanındaki yerime

Bana bir darağacı,bulsan yine gelirim

Korkmam yol karanlıkmış,tehlike varmış her an

Sonunda sen varsın ya,kovsan yine gelirim

Çok mu versem sevdanın,yolunda bir kuru can

Kara toprak altında,olsan yine gelirim

Yıllardır arıyorum,bu sefer yerinde kal

Seni milyon kişiye,sorsam yine gelirim

Karar verdim birkere,artık dinlemem kural

Yasaklar koysan bana,vursan yine gelirim…', 'Hasret kalmış dediler,gözlerin gözlerime Rüzgara bir tebessüm,salsan yine gelirim Kimseyi alma sakın,yanındaki yerime Bana bir darağacı,buls...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-gelirim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçuk Kız', 'ucuk-kiz-halil-kesken-2dq4u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölürüm der sana başka şey demez

Gölge gibi hep peşimde kaçık kız

Hep neşeli ele avuca sığmaz

Saçını maviye boyar uçuk kız

Adını dakika geçmez andığım

Yalanına, doğrusuna kandığım

Saçlarının örgüsüne yandığım

Kaç kez aşkım dedim sayar uçuk kız

Allahım bana da sabırlar versin

İsterki sevgimiz asırlar sürsün

Ayrılığın adı geçmeye görsün

Başıma silahı dayar uçuk kız', 'Ölürüm der sana başka şey demez Gölge gibi hep peşimde kaçık kız Hep neşeli ele avuca sığmaz Saçını maviye boyar uçuk kız Adını dakika geçme...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ucuk-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılanlar', 'yilanlar-rahim-tas-hvodh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çare bul, 

Bir yol göster 

Ey denizdeki yılan 

Nasıl kurtulurum 

Koynumdaki yılandan…

12.3.2004', 'Bir çare bul,  Bir yol göster  Ey denizdeki yılan  Nasıl kurtulurum  Koynumdaki yılandan… 12.3.2004...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yilanlar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dem-an-sevdam', 'dem-an-sevdam-reyhan-sur-njgli', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kelebek kanadında ömürdü düşler 

kanadı 

düştü 

düşler... 

demdir dem 

andır an



kelebek kozadan 

örümcek ağdan 

çıkmayı bekler 

sözler ağızdan 

o-lu-şa-cak-lar 

bir kuzu doğar 

koşar memeye 

bir bebek ağlar 

sevgi nerede 

kokular saçar açılan çiçek 

aşk doğar aşk 

aşk doğar aşk 

kanatlanır da umuda uçar 

... 

küçük birer çıngıraktır yapraklar 

sallanır 

durur 

inlerken neyler 

kudümler 

okşanır teller 

yürekler coşar da 

türküye vurur 

demdir dem 

andır an 

dem

 bu dem 

an

 bu an 

huu de gel sevdam

(su)', 'kelebek kanadında ömürdü düşler  kanadı  düştü  düşler...  demdir dem  andır an kelebek kozadan  örümcek ağdan  çıkmayı bekler  sözler ağızd...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dem-an-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasta Ziyareti*', 'hasta-ziyareti-bayram-tunca-of6at', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alır almaz acı haberi düştüm yola 

Görenler lisanen dediler hayır ola 

Lisan-ı halimden kimi anlamış ola 

Dediler inşallah Rab’den şifa bula 

Elimde çam sakızı çoban armağanım 

Başımda dosta dair duygu harmanım 

Maniaları aşıp, can dosta varmalıyım 

Az teselli edip/azami ibret almalıyım 

Çelişkilerle dolu yol boyunca ilerledim 

Ağlayana rağmen gülenlere içerledim 

Ateşin, düştüğü yeri yaktığını gördüm 

Geçmiş olsun deyip, hal hatır sordum 

Nazarlarını dikmişti, taa öteler ötesine 

Neyi varsa koymuştu azığını heybesine 

İkindi güneşinin gizemi inmişti yüzüne 

Zaten bezemişti O, onun özünü iyilikle

O özümlemişti hastalıktaki sabrın mükafatını 

Hiç duymadım onun ağzından şikayet kelamı 

Duyduğum tek şeyse galiba yolun sonu geldi

Her halde biri söylemişti yolun sonu geldiğini

Ziyaretin kısası makbul diye, müsaade istedim 

İstemez olaydım, doldu gözleri/doldu gözlerim 

Söyle dost, bize düşen bir vazife var mı dedim 

Son isteği helallik/duaydı, onu bari verebildim 

25.02.2004-20.25', 'Alır almaz acı haberi düştüm yola  Görenler lisanen dediler hayır ola  Lisan-ı halimden kimi anlamış ola  Dediler inşallah Rab’den şifa bula...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hasta-ziyareti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çal Kemancı', 'cal-kemanci-i-brahim-dikmen-2-9quri', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Masalarda kadehleri

Kaldırırken şerefe

Dertli dertli,çal kemancı

Sarhoşum ben bu gece

Zaman akıp geçti gitti

Ne de çabuk ah yaşlandık

Durma çal çal be kemancı

Sevmekten mi  usandık

Sensiz bu kaçıncı gece

Mey ler artık arkadaşım

Yakıp gittin sen kalbimi

Kadehler oldu yoldaşım

Efsun efsun çal bu gece

Makamı fusenik olsun

Boşa geçmesin saatler

Kadehler hep meyle dolsun

İçli içli çal bu gece

Makamı nihavent olsun

Durduralım biz zamanı

Kalplerimiz aşka dolsun', 'Masalarda kadehleri Kaldırırken şerefe Dertli dertli,çal kemancı Sarhoşum ben bu gece Zaman akıp geçti gitti Ne de çabuk ah yaşlandık Durma ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kemanci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '“Otuz” a 1 kala,', 'otuz-a-1-kala-maide-sengul-finli', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son derece mühim, ciddi dökümanlar arasında,

bir-iki çiziklik, çala kalem karalama dünyası,

                               dünya kadar işin içinde...



kaçamak sanat yolculukları,

ruhsal sarsıntılar... 

“otuz” a 1 kala,

komik “kendini bulma seansları”

                                             

saçlarıma aklar düşmedi henüz,

çoluk – çocuğa da karışmadım daha...

herhalde bu yüzden olacak,

küçükken çok uzakmış, büyükmüş gibi gelen yaşlar,

aslında o kadar da iri görünmüyor yaklaştıkça,

hatta küçülüyor sanki,

yok olana dek küçülecekmiş gibi..



ne kadar hızlı zaman,

herşey ne kadar hızlı...

ben,

hıza inat, yavaşım sanki

                   gürültüye inat, sessizleştim bugün,

kahkahalara inat, ağlama krizleri geliyor içimden...

                                                 “otuz”a 1 kala,

ne gözümün yaşına,

ne yaşıma – başıma yakışmayan haller içindeyim bugün.', 'Son derece mühim, ciddi dökümanlar arasında, bir-iki çiziklik, çala kalem karalama dünyası,                                dünya kadar işin ...', ARRAY['Türk Edebiyatı','Şiir','Maide Şengül']::text[], 8.5, '{"poet":"Maide Şengül","poet_slug":"maide-sengul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/otuz-a-1-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Hep Yakındın,Ama Benden Uzak', 'bana-hep-yakindin-ama-benden-uzak-i-brahim-dikmen-2-4kthb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana hep yakındın,ama benden uzak,

Ağrıma gitti,sana dokunamamak.

Yinede sevdim seni,

Zoruma gitti,sana sarılamamak.

Sevdamı,şiirlere serptim,coştular,

Seni,yüceltti hep,sensiz geçen yıllar.

Yinede sevdim seni,

Seni anımsattı,aşk tüten şarkılar.

Hasret kokardı,yağan yağmurla rüzğar,

Seni,benden çalan,denizler ve dağlar.

Yüreğimde bir çığlık,

Seni seviyorum,neolur anla yar.

Kimi zaman,sigaramın dumanında,

Bazen,puslu  gecenin karanlığında.

Gülümserdin uzaktan,

Beni,benden çalan,sıcaklığınla.', 'Bana hep yakındın,ama benden uzak, Ağrıma gitti,sana dokunamamak. Yinede sevdim seni, Zoruma gitti,sana sarılamamak. Sevdamı,şiirlere serpti...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-hep-yakindin-ama-benden-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 2', 'rubai-2-i-smet-nadir-atasoy-7ai5e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaderimiz bu demek böyle gelip geçecek,

Eller edebimizde yok ki kıçta giyecek,

Dün nasıl unutuldu yalamadan yutanlar; 

Yarın da hortumcular unutulup gidecek.', 'Kaderimiz bu demek böyle gelip geçecek, Eller edebimizde yok ki kıçta giyecek, Dün nasıl unutuldu yalamadan yutanlar;  Yarın da hortumcular ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Nadir Atasoy']::text[], 8.5, '{"poet":"İsmet Nadir Atasoy","poet_slug":"i-smet-nadir-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-2-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Kuğu', 'islak-kugu-reyhan-sur-0qqxb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mermer tahammülüdür şu beyaz yontu

ışıklı gölde



dudak dudağa gelirken geceyle şafak

günlerin doğumuna şahadet eder

leylak kokulu bir parkın armonisiyle

kanatları ıslak kuğu

kırdım dizelerimi iki mevsim arası

kayıtsızlığımı doldurdum içine

solgun birer anıdır şimdi dünler

uzak ve yabani

öylesine..

yekinip gözlerimi

uykusuna banarım

doğmamış bir bebeğin

aynalar tutarım ölü fısıltılara

gizler ağzını rüzgar

geceler serin

döker eteğindeki portakal çiçeklerini

dudağımda köpüklenen

dozu yüksek şiirler içiyorum şimdi

bir yudumda

bir iksir gibi

ıslak kuğu

suyun bol olsun', 'mermer tahammülüdür şu beyaz yontu ışıklı gölde dudak dudağa gelirken geceyle şafak günlerin doğumuna şahadet eder leylak kokulu bir parkın ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sur']::text[], 8.5, '{"poet":"Reyhan Sur","poet_slug":"reyhan-sur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/islak-kugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler', 'golgeler-i-brahim-dikmen-2-o2u1l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin alaca karanlığında

Issız kuytu bir köşedeyim.

Yanımda sadece silahım

Ansızın öten bir baykuş

Binlerce böceğin sesi

Damarlarımda akan asil kan

Elimde modası geçmiş M_1

Yüreğimde Atam Oğuzlardan miras

Türk''ü yenilmez yapan cesaret var

Kalbimin ücra köşelerinde yarim

Korkudan eseryok yüreğimde

Sadece gecenin soğukluğu var bedenimde.

Hasretin ateşti nar oldu yüreğimde

Dediler ki iki dört nöbetin

Sis tepesi mabet yerin

Yanında olacak ayyıldızlı hilalin

Sis tepesi diyorlar adına

Şeytan durağı koymuşlar namına

Sadece ruhun olacakyanında

Birde gölgeler var gölgeler

Dördü gösterince saat

Kalbimde açıyor şafak

Ayak sesi var uzakta birkaç

Yaklaşınca devriye onbaşı

Dur eller havada yaklaş.

Parola hasret şaret ızdırap

Zaman bir panel gibi

Ansızın gerçeğe döndü

Uzaktan birkaç tüfekli göründü

Koruduğum sis tepesi değildi

Kalbimde yanan yarin aşkıydı

Ruhuma hilal gibi saplanan bakışıydı

Kolların diye tuttuğum M_1

Ellerin diye okşadığım kabza

Hayalinle konuştum iki dört nöbetimde

Karanlık dağıldıkça ruhumdan

Bedenimi kaplayıverdi sevdan

Yanımda senden kalan son hatıran

Birde gölgeler var gölgeler', 'Gecenin alaca karanlığında Issız kuytu bir köşedeyim. Yanımda sadece silahım Ansızın öten bir baykuş Binlerce böceğin sesi Damarlarımda akan...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/golgeler-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demem Artık Yara Bana', 'demem-artik-yara-bana-murat-demir-rvdcx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şaşırttırdın feleğimi

Gözün aydın ey sevgilim

Ne yaptım ki yüreğimi

Parçaladın dilim dilim

Sevda diye sevgi diye

Yara oldun yara bana

Yaram beni öldürsede

Demem artık yara bana

Ben bu derdin sancısını

Artık sensiz çekeceğim

Dünkü aşkın şarkısını

Dinledikçe içeceğim

Sevda diye sevgi diye

Yara oldun yara bana

Bu aşk beni oldürsede

Demem gel aşkıma yara

Acımadan aldın gittin

Beni benden nefes gibi

Görüyorsun işte bittim

Gülemeden herkes gibi

Sevda diye sevgi diye

Yara oldun yara bana

Yaram beni öldürsede

Demem gel yarama yara', 'Şaşırttırdın feleğimi Gözün aydın ey sevgilim Ne yaptım ki yüreğimi Parçaladın dilim dilim Sevda diye sevgi diye Yara oldun yara bana Yaram ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/demem-artik-yara-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki İnsan', 'i-ki-i-nsan-gokhan-oflazoglu-uqvx4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabah hızlı adımlarla insanlar

gidiyorlar, tam köşede iki kişi

arada bir duraksayarak konuşuyorlar.

Sanki yıllar sonra ilk kez karşılaşmışlar.

Belki yalnızca onlar var şimdi.

Diğerleri geçip gitmede... zamanın

saçlarına takılmış altın bir taç o an,

her ne konuşuyorlarsa... biz de işitsek

bir şey değişmeyecekti, o an hepimize

armağan; böyle insan olduk, konuşurken,

duyarken. Sonra zarif bir el sıkışması,

ayrılıyorlar, biten yalnızca söyleşi değil,

belki de zaman. Bu ne kadar çok tekrar

eder dünyamızda, ama, bizi biz yapan

işte o iki insan. Her ne konuşuyorlarsa.

Nasıl dile gelirse gelsin, dile geldiğimizde

temellenir yeryüzü ve insan, bizi barındırır

ve sonrasını.

Yavaşça boşalan, sakin yolda bir sabah

ve iki insan; o saatte söyleyecek neyi olur

insanın, ama, söylemeseler, umut da yok

o saatte, ne de insan.', 'Sabah hızlı adımlarla insanlar gidiyorlar, tam köşede iki kişi arada bir duraksayarak konuşuyorlar. Sanki yıllar sonra ilk kez karşılaşmışla...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/iki-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-kubilay-enginol-8g475', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çiçeklerimi,sevgimi

Yanıma alıp gidiyorum

Pişman olacaksın,üzüleceksin

Ama olsun

Ben

Yinede gidiyorum

Bulutlara söylerim,bundan sonra

Belkide yağmura

Şiirler yazarım belki

Gökkuşağının altında', 'Çiçeklerimi,sevgimi Yanıma alıp gidiyorum Pişman olacaksın,üzüleceksin Ama olsun Ben Yinede gidiyorum Bulutlara söylerim,bundan sonra Belkid...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidiyorum-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Mavi', 'yorgun-mavi-turgay-uceren-xdnr3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'a







Köpek uluması.Serviler.Köy mezarlığı.Duvarlarda 

dinlenen deniz rüzgarı.Yakın kumsal.Tuz.Zakkum nemi.

Kamp ateşi.Sönen gece.Denizin yıkadığı fısıltı.Şişeler.

Ruhların firarı.Kulaklarda kalan ezgi.Kum.Midye kırıkları.

Gömülen beden.Yakın şey.Karanlığın gümüş yüzü.

Darbeler altında.Tatlı sızı.Şekillenen kum.Uzakta şarkı.

İki sandal.Halat.Birbirlerine bağlı sözler.Sürtünen 

çığlık.Sıcak.Yaseminlerin terlediği saat.Şaşkın dil.

Gece.Güneş terleyen zeytin ağaçları.Tırnakların çıkmaz yolu.

Uçurumuna tırmanan ses.Düşmek için kumdan gök.

Çıplakların ayı.Sırtında yıldız yağmuru.Diğerini örten gövde.

Yaldızlanan göz.İncecik ten.

Ay.İpek örtü.Sabah yıldızı.Güneşten düşen gün.Gümüşten yatak.

Deniz.Geceyle gün arasında yorgundur mavi.', 'a Köpek uluması.Serviler.Köy mezarlığı.Duvarlarda  dinlenen deniz rüzgarı.Yakın kumsal.Tuz.Zakkum nemi. Kamp ateşi.Sönen gece.Denizin yıkadı...', ARRAY['Türk Edebiyatı','Şiir','Turgay Uçeren']::text[], 8.5, '{"poet":"Turgay Uçeren","poet_slug":"turgay-uceren","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yorgun-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim İnsanı', 'memleketim-i-nsani-esma-ozdemir-o6ki1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözü kara

Gönlü aktır

Memleketim insanının

Kalbi altın yaldızlı…

Her biri bir Gazi Osman Paşa

Her biri bir Kara Fatma

Her biri Mustafa Kemal’dir

Her biri aslan parçası…

Toprağı kızıl

Yolları tozlu

Dağları dumanlıdır, sıra sıra

Koyu mavi efkârlı...

Memleketim insanının

Elleri nasırlıdır; 

Yüreğinde 

Afacan bir çocuğun heyecanı...

Sevgi dolu gözlerinde 

Billurdan ışıklar saklı...', 'Gözü kara Gönlü aktır Memleketim insanının Kalbi altın yaldızlı… Her biri bir Gazi Osman Paşa Her biri bir Kara Fatma Her biri Mustafa Kemal...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/memleketim-insani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce gözlerin', 'once-gozlerin-gurbuz-vural-zglz0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce gözlerin,

gözlerin giriyor yüreğime.

Sonra tenin oluyor yüreğim.

İyiden iyiye sana kesiyorum.

Biraz da korkuyorum,

çıkıp gidersen

parçalanır yüreğim...', 'Önce gözlerin, gözlerin giriyor yüreğime. Sonra tenin oluyor yüreğim. İyiden iyiye sana kesiyorum. Biraz da korkuyorum, çıkıp gidersen parça...', ARRAY['Türk Edebiyatı','Şiir','Gürbüz Vural']::text[], 8.5, '{"poet":"Gürbüz Vural","poet_slug":"gurbuz-vural","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/once-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklugum', 'cocuklugum-ayten-ozlem-yesilcali-8fibq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi seni düşünüyorum

Sisli gecede,dışarıda yagmur çiselerken.

Sabahları kalkıp lastikayakkabıları giymeni.

Eline kitaplarını alıp okulun yolunu tutmanı.

Geceleri 12 direkli odada sekiz kardeşle

gaz lambasının önünde ders çalışmanı.

Ortahalli bir ailenin ferdiydin.

okula gidende sadece sendin.

Anenin ders çalışman için kardeşlerine; 

susmaları için bagırmasını.

Senin bazı geceler yorganın altında aglamalarını.

okuldan kalan zamanında 

Babanın yolkenarındaki seyar lokantasında 

garsonluk yapmanı.

Sanki çalışmak ayıpmış gibi kimselere söylememeni.

Okul müdürünün seni çalışırken yakaladıgında 

Yüzünün yanaklarının al al olması

Gözlerini kaçırıp gözpınarlarını dolması.

Yagan yagmurda ıslanmayı çok sevmeni,

Islak sokaklarda hüzünlenmeni.

Ve hiç evişleri degilde; 

sanki kendini evin erkegiymiş zannedip

erkekişlerine heves sarmanı.

kazanıp ailenin yükünü babanın üzerinden alma düşünceni.

Kazandıgını annene verdiginde gözlerindeki sevinçpırıltılarını.

Kaznamamın tadına varmanı.

Gözlerimde yaşlar.

agladıgımı sana göstermeden 

Sana kim oldugumu söylemiyorum...

Ama seni çok özledim.

Seni çok özlüyorum Çocuklugum.', 'Şimdi seni düşünüyorum Sisli gecede,dışarıda yagmur çiselerken. Sabahları kalkıp lastikayakkabıları giymeni. Eline kitaplarını alıp okulun y...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cocuklugum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Ancak Sen Yetersin', 'bana-ancak-sen-yetersin-murat-demir-5wz93', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kralla, ne de şahla

İşim olmaz, padişahla

Bu bende ki, bitmez aşkla

Bana ancak sen yetersin

Neye yarar, olsa bağım

Başı karlı yüce dağım

İçimde ki can sıcağım

Bana ancak sen yetersin

Fayda etmez acım tatlım

Ela gözlüm,sır sıratlım

Dünya değil,gül suratlım

Bana ancak sen yetersin

Hem işimde, hem aşımda

Bela olsan da, başımda

Olsam bile,yüz yaşımda

Bana ancak sen yetersin

Su gibisin, tam bir içim

Güzelliğin, biçim biçim

Yaşıyorsam senin için

Bana ancak sen yetersin

Güç tanımam, güle bakmam

Tüm ordular, vursa korkmam

Bu kalbe, kimseyi sokmam

Bana ancak sen yetersin', 'Ne kralla, ne de şahla İşim olmaz, padişahla Bu bende ki, bitmez aşkla Bana ancak sen yetersin Neye yarar, olsa bağım Başı karlı yüce dağım ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bana-ancak-sen-yetersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller.Gözler.Dudaklar', 'eller-gozler-dudaklar-ayten-ozlem-yesilcali-yfthn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kıraç topraklarda büyüdüm.

Yazın kavurucu sıcaklıgında.

Hani sıcaktan insanların dudakları çatlar ya

İşte benim dudaklarımda; 

Hep çatlar sana susuzlugundan.....

Yaz işçileri çalışır pamuk tarlasında.

Bilirmisin onları gördünmü? 

Hanımların elleri,

Pamuk toplamaktan,elde çamaşır yıkamaktan

Tohum ekmekten,toprakla ugraşmaktan nasırlaşır...

İşte benimde ellerim nasırlaştı; 

Senin elini tutmamaktan seni okşayamamktan.

O insanların gözlerine dikkat ettinmi hiç? 

sürmeli olur hepsinin gözleri.

Ama hep güneşte çalışmaktan.

Uyuyamamaktan agırlaşır gözkapakları.

Yollara bakmaktan kızarır göz pınarları.

İşte benim gözlerimde sürmesini kaybetti.

Senin yolunu gözlemekten..', 'Kıraç topraklarda büyüdüm. Yazın kavurucu sıcaklıgında. Hani sıcaktan insanların dudakları çatlar ya İşte benim dudaklarımda;  Hep çatlar sa...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/eller-gozler-dudaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Bir Şiir', 'i-simsiz-bir-siir-pinar-yilmaz-iv742', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamanım durmuş en büyük hızla zaman çıldırdığında

Ben durmuşum en hızlı adımlarla savrulurken

Herşeyi noktalamışım en büyük virgüllerle yaşam kıvrılırken

Koca bir soru işareti bırakmışım ardımda

Cevapları bulmayı unutmuş olan insanlığa', 'Zamanım durmuş en büyük hızla zaman çıldırdığında Ben durmuşum en hızlı adımlarla savrulurken Herşeyi noktalamışım en büyük virgüllerle yaşa...', ARRAY['Türk Edebiyatı','Şiir','Pınar Yılmaz']::text[], 8.5, '{"poet":"Pınar Yılmaz","poet_slug":"pinar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/isimsiz-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanım Durmuş', 'zamanim-durmus-pinar-yilmaz-mjzjo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanım durmuş en büyük hızla zaman çıldırdığında

Ben durmuşum en hızlı adımlarla savrulurken

Herşeyi noktalamışım en büyük virgüllerle yaşam kıvrılırken

Koca bir soru işareti bırakmışım ardımda

Cevapları bulmayı unutmuş olan insanlığa', 'Zamanım durmuş en büyük hızla zaman çıldırdığında Ben durmuşum en hızlı adımlarla savrulurken Herşeyi noktalamışım en büyük virgüllerle yaşa...', ARRAY['Türk Edebiyatı','Şiir','Pınar Yılmaz']::text[], 8.5, '{"poet":"Pınar Yılmaz","poet_slug":"pinar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zamanim-durmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Yağarken', 'kar-yagarken-necmi-unsal-on5pa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağarken  getirir bin bir   macerayı     lapa lapa.

Karla  kaplanır da  her yer,  bembeyaz  olur  serapa.

Yol iz  kapanır;  kar  etmez  kazma,  kürek  ve  çapa.

Ne güzeldir  geçit  vermez  yollar  açmak  kar  yağarken! 

Bembeyaz  kar  örtüsü bir yorgandır  cömert  toprağa.

Canına  can,  kanına  kan  her  bir  tomurcuk  yaprağa.

Tatlı  sular  biriktirir  yerde  ihtiyar  toprağa.

Ne güzel olur  kızak  ve  kayak  kaymak  kar  yağarken! 

Her  kar  tanesi  içinde  ayrı  bir  güzellik  saklar.

Bu kirlenen  dünyamızı  bembeyazlığıyla  aklar.

Olunca  diz boyu;  çıkar  yollara  tek-tek  kızaklar.

Ne güzel, evde bir  ocak  başı  kapmak  kar  yağarken! 

Süzülerek sayısız  kar  taneciği  konar  yere.

Isınınca hava  kalmaz  onunla coşmayan  dere.

Yürünür  yavaşça,  kimse  atmaz  kendini  sipere.

Çok güzeldir  çocukça  kar topu  atmak  kar  yağarken! 

Karlar  yuvarlanır,  büyük  bir  gövde  işte  bir  kafa! 

Gerçi  ömrü  kısadır,  yok  onda  eriyince  vefa.

Yağınca  yağmur  sopa  bir  yana,  şapka  bir  tarafa! 

Güzeldir  soğukta  kardan adam  yapmak  kar yağarken! 

Gelinlik  giymiş  gibi  her taraf  tertemiz  bembeyaz.

İçine  işler  insanın  akşamdan  kalan  sert  ayaz.

Çok  hoşuna  gidiyorsa  kar, haydi  durma  sen de  yaz! 

Güzeldir  onun  hakkında  şiir  yazmak  kar  yağarken! 

8 Ocak 2004  Perşembe,  Danimarka-Køge23:13

8+8', 'Yağarken  getirir bin bir   macerayı     lapa lapa. Karla  kaplanır da  her yer,  bembeyaz  olur  serapa. Yol iz  kapanır;  kar  etmez  kazm...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kar-yagarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mübtedi', 'mubtedi-refik-recep-pelit-449bj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahlaklı ol insan gibi haddini bil mübtedi

Kalender ol bu yakışır Ahveb-i cismanına

Beşer nazarında zinhar,sayılırsın Müfteri

Bakarsın ki baht''ın ölür adın çıkar abdal''a.

Mübtedi: Yeni talebe

Kalender: Hoşgörülü

Ahveb: Asi -Günahkar

Zinhar: Katiyet 

Müfteri: Yalancı - iftira eden

Abdal:  1:Aptal,Ahmak 2: Derviş', 'Ahlaklı ol insan gibi haddini bil mübtedi Kalender ol bu yakışır Ahveb-i cismanına Beşer nazarında zinhar,sayılırsın Müfteri Bakarsın ki bah...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mubtedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam hikayeleri 6', 'aksam-hikayeleri-6-kubilay-enginol-irxfv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Demin

Solgunlambaların altından

Bir sarhoş geçti

Hem içkiden,hem aşkından

Sarhoştu

Sevdiğinin sapsarı saçlarına içti belki

Pınar mavisi gözlerine

Yapamıyıruz,olmuyor diyen

Berrak sözlerine

Soluk lambaların altından

Geçti bir sarhoş

Dünya malı dünyada

Anladı bunu,gerisi boş', 'Demin Solgunlambaların altından Bir sarhoş geçti Hem içkiden,hem aşkından Sarhoştu Sevdiğinin sapsarı saçlarına içti belki Pınar mavisi gözl...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aksam-hikayeleri-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sri Lanka''da Fillerle Polo Yapan Binici!', 'sri-lanka-da-fillerle-polo-yapan-binici-naime-erlacin-9v4x3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne oyun teorisi ama

kazanmak yetmez

dayanmak lazım! 

ben kapattım kendimi

dağda bayırda denizde

hatta hapiste

bu 

şu 

o

herkes kapattı işte! 

çektim ipi artık 

tek kişiyim fillerle polo''da

gül serptim başınızdan

Oscar’ı verdim gitti

en teneke madalyaları da

ödülünüz daim olsun 

duydum ki 

kahramanlığa soyunmuşsunuz 

tebriklerimle! 

sahi 

kaç kişiydiniz siz

kaçar tane kaç kişi

“hem yiğit ol hem er”

bilir miydiniz acaba 

Pitagor’dan armağandır bu bize

güller size

polo bana

yetti bre

yetti bre! 

(11 Mart 2004)', 'ne oyun teorisi ama kazanmak yetmez dayanmak lazım!  ben kapattım kendimi dağda bayırda denizde hatta hapiste bu  şu  o herkes kapattı işte!...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sri-lanka-da-fillerle-polo-yapan-binici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun ve Yaşam I', 'oyun-ve-yasam-i-mehmet-sukru-kaplan-9ygx3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir ütopyamız vardı gün doğumu kızıllığında

kime rastlasak kimliğmizi yırtardık

bu yüzden adını deniz koymuştuk

ilk yaz akşamlarının

ah! ..içimde kırık mumlar

kırmızı şarapnel parçaları

bir sis çökmesi gecede

tüm odaları çift kişilik hayatın

ah! ..dirseğimde saklı mavi çocuk

diz çöken bir dağ gölgesi

ruhumu saran çamur kurusu

bir oyun bu oyuncusuz oynanan

yarı çıplak bir dans ritmiyle

iki kıyı arasındaki bir köprüde

ah! ..bir yanık kitabe içimdeki sancı

iki yaşam arasındaki bir noktada

iğreti adıyla çağıran adını

aykırı bir hüzün kapımı çalan

-soluk yün kokusu-

ah! ..ağır uykusuna vurgun gökyüzü

elbet kelebekler uçar bir gün

ipsiz uçurtmaların kasnağını süzerek

                                   ocak 2004

                                       silifke', 'bir ütopyamız vardı gün doğumu kızıllığında kime rastlasak kimliğmizi yırtardık bu yüzden adını deniz koymuştuk ilk yaz akşamlarının ah! ..i...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Kaplan']::text[], 8.5, '{"poet":"Mehmet Şükrü Kaplan","poet_slug":"mehmet-sukru-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oyun-ve-yasam-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sandın', 'sandin-halil-kesken-9h8c1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah gül bahçesinin güzel goncası

Geçici bir hismi sandın aşkımı

Dalını bir mevsim yuvası bilmiş

Göçebe bir kuşmu sandın aşkımı

Seni böyle sevip can vermeyecek

Toprağında taşmı sandın aşkımı

Güneş doğduğunda çekip gidecek

Yaprağında yaşmı sandın aşkımı

Bir öğle arası uykunda yazın

Gördüğün bir düşmü sandın aşkımı

Bundanmı kaprisin bundan mı nazın

Hep yalan mı boş mu sandın aşkımı?', 'Ah gül bahçesinin güzel goncası Geçici bir hismi sandın aşkımı Dalını bir mevsim yuvası bilmiş Göçebe bir kuşmu sandın aşkımı Seni böyle sev...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sandin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun ve Yaşam II', 'oyun-ve-yasam-ii-mehmet-sukru-kaplan-wquab', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir ütopyamız vardı gün doğumu kızıllığında

kime rastlasak kimliğmizi yırtardık

bu yüzden adını diren koymuştuk

tüm köy çocuklarının

ah! ..annemin çeyizlik sandığı

hep böyle kıtlık mı doğuracak

suyla sevişirken ay

adet midir keman teli

soyundan bir yüz takınıp

kurşunlamak havayı

ah! ..ne yapar gerdek gecesinde

mezarlıktan aşırılan bir düş

koynuna sokulan çocuksu gülüş

öptüğüm kedinin tüylerini sarartan

kısır dudaklarım paslı giyitleriyle

sahanlığa seriyor ruhunu

nereye kaçsam askılık

bir tabutun ön kapağında

asmak için çirkin çenemi

ah! ..o eski sevinçlerin ağında

küçük bir balık gibi devinen

ıslak mendil; yaşamı değil

kendini ser gök çekimli evlerin

kıvrak çitlerine

                    (şubat 2004) 

                        (silifke)', 'bir ütopyamız vardı gün doğumu kızıllığında kime rastlasak kimliğmizi yırtardık bu yüzden adını diren koymuştuk tüm köy çocuklarının ah! ..a...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Kaplan']::text[], 8.5, '{"poet":"Mehmet Şükrü Kaplan","poet_slug":"mehmet-sukru-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oyun-ve-yasam-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevilmek,Sensizlikse', 'sevilmek-sensizlikse-i-brahim-dikmen-2-uigr5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerim,gözlerinde,

Ararken mutluluğu.

Tadardım her damlada,

Sevgi denen duyguyu.', 'Gözlerim,gözlerinde, Ararken mutluluğu. Tadardım her damlada, Sevgi denen duyguyu....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevilmek-sensizlikse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Yaprak Sevdası', 'sari-yaprak-sevdasi-filiz-mercankosk-ysown', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sarı yaprak sevdası seninkisi,

Bir mevsimlik bilirim ömrü.

Harfler ıslak, harfler yerlerde

Böyle mi dersin sevda dökümü? 

Uzandığın yer, geçmişin koynu,

Bir zamanlar ne masallar okurdu,

Önce tutkuların ulurdu,

Zafer şarkıları söylerdin uluorta,

Geceye inat, aya sevdalı

O an gözlerin cennet olurdu...

Sarı yaprak sevdası seninkisi,

Bir mevsimlik bilirim ömrü.

Harfler ıslak, harfler yerlerde,

Böyle mi olur sevda dökümü? 

Adın kutlu, bahtın mutluydu,

Bu yüzden kıymetsizdi sevenlerin,

Bu yüzden yeşili hoyratça tükettin.

Dokundun, soldurdun..

Düşen her yaprakla daha güçlendin,

Kaç körpenin günahına girdin,

Kaç sevdayı cennetinden kovdun,

Onlar kururken sen sadece gittin.

İnanmam, inanamam  sana! 

Sarı yaprak sevdası seninkisi,

Bir mevsimlik bilirim ömrü.

Harfler ıslak, harfler yerlerde,

Böyle mi dersin sevda dökümü? 

(İstanbul/10.03.2004)', 'Sarı yaprak sevdası seninkisi, Bir mevsimlik bilirim ömrü. Harfler ıslak, harfler yerlerde Böyle mi dersin sevda dökümü?  Uzandığın yer, geç...', ARRAY['Türk Edebiyatı','Şiir','Filiz Mercanköşk']::text[], 8.5, '{"poet":"Filiz Mercanköşk","poet_slug":"filiz-mercankosk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sari-yaprak-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun ve Yaşam III', 'oyun-ve-yasam-iii-mehmet-sukru-kaplan-x2bx3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir sevinin acısını yükledim

bir dağın yazgısına/buz sarkıtları

kendi yağında sevişmekte örümcek

ah! ..koca bir ömrün ağır yükü

belleğimde çitilenen anımsama

gece çığlığında yazılan muska

ateşten bir süs dövmeli yakamda

ah! ..yüreğim yol yorgunu

evden kaçmış kızların artistik düşleri

yırtık resim kareleri ören yerinde

herkes kendi kokusuna tav

yağmur ıslağı bu sahnede

ah! ..bir oyunmuş yaşamak denilen

iki rekat arası bir molada

cenabet bir sorguya gülerek giden

                       (şubat 2004) 

              (silifke)', 'bir sevinin acısını yükledim bir dağın yazgısına/buz sarkıtları kendi yağında sevişmekte örümcek ah! ..koca bir ömrün ağır yükü belleğimde ç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Kaplan']::text[], 8.5, '{"poet":"Mehmet Şükrü Kaplan","poet_slug":"mehmet-sukru-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oyun-ve-yasam-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Geceme', 'dus-geceme-tevfik-mengulluoglu-uhpxx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rasgele,sevdalandın 

gece vakti! 

hemde yaşamın ölüme

sevdalandığı gibi

korkularına da 

Sevdalandın,

yalnızlığına da

düş yoluma...

kapıya dayanmış celladın

henüz baharındasın

aşkının,kendi ellerinle ver,

Gel yanıma..

Bir gecenin alaca

maviliğinde,karaya

oturan yalnızlığımın,

Elleri ol...

Hemde içine 

saklanabileceğim 

kadar küçük elleri.

Düş geceme.', 'Rasgele,sevdalandın  gece vakti!  hemde yaşamın ölüme sevdalandığı gibi korkularına da  Sevdalandın, yalnızlığına da düş yoluma... kapıya da...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dus-geceme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akşam,Meyhanede', 'bir-aksam-meyhanede-i-brahim-dikmen-2-v49ri', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir akşam,meyhanede,

Yıkılmış,viranede.

Ararken,mutluluğu,

Meyle dolu,kadehlerde.

Bebek gibi,yüzü vardı,

Yosun gibi,gözü vardı.

Şimdi yaşlı,ah o,gözler,

Gece gibi,yar karardı.

Oturduğum,ahşap masada,

Ağlıyorum,biten aşkımıza.

Yalvardımda,neoldu sanki,

Kalbim şimdi,paramparça.', 'Bir akşam,meyhanede, Yıkılmış,viranede. Ararken,mutluluğu, Meyle dolu,kadehlerde. Bebek gibi,yüzü vardı, Yosun gibi,gözü vardı. Şimdi yaşlı,...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-aksam-meyhanede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun ve Yaşam IV', 'oyun-ve-yasam-iv-mehmet-sukru-kaplan-0yfuq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ah! ..bir adımlık saltanat bu 

kireç köpüğünde taçlanan 

kemikten bir takı hayat 

ağıtçı kadınların uğursuz 

sözlerinde 

ah! ..dişlenen acı su günlerin 

belleğinde silinen ay izi 

zamanı kemiren ağ kurdu 

ölü gölgelerin uyanma saati 

ah! ..veda toprak kayması 

yağmurun kapıya bıraktığı 

bir anımsamanın korkunç yüzü 

-besleyen geceyi- 

neye dokunsam boşluk 

evcil çakal sesleri 

şarapsız mahzen uykusunda 

ah! ..içkili şehir mezarlığı 

ben mermerinde bir ruh kaçkını 

            (şubat 2004)

             (silifke)', 'ah! ..bir adımlık saltanat bu  kireç köpüğünde taçlanan  kemikten bir takı hayat  ağıtçı kadınların uğursuz  sözlerinde  ah! ..dişlenen acı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Kaplan']::text[], 8.5, '{"poet":"Mehmet Şükrü Kaplan","poet_slug":"mehmet-sukru-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oyun-ve-yasam-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl Saçlı Dilber', 'kizil-sacli-dilber-emir-kemal-rllfs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şarkı benden sana,

Hatıra olsun...

İçinde kanayan,

Bir sızı olsun...

Düşündükçe aklına bir gelen olsun...

Unut bunu sevgilim,

Canın sağ olsun...

Unut bunu sevgilim,

İstersen görüşmeyelim.

Kızıl saçlı dilberim,

Neden gülmüyor bana?', 'Bu şarkı benden sana, Hatıra olsun... İçinde kanayan, Bir sızı olsun... Düşündükçe aklına bir gelen olsun... Unut bunu sevgilim, Canın sağ o...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kizil-sacli-dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Deliyim', 'ben-bir-deliyim-emir-kemal-3gcmc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir deliyim...

Sınırsızlıklara bel bağlayan bir deli...

Ben bir aşığım sevdiği kendiyle kesişen; 

Tümleyeni hiç olmayan bir aşık...

Bir coğrafyanın çatlak toprağıdır kalbim,

Sulanmasını bekleyen bir toprak...

Heyecanları yaşadıklarına bir beden büyük gelen,

Bu yüzden hep büyük beden sevdalara yeltenen

Bir hayalperest...

Ağzıyla kuş tutsa,

“canını acıttım mı! ” 

Diyecek kadar sevinemeyen bir ben daha var mı acaba! ..

Bu kadar mutlu olmasını beceremeyen,

Mutlu olmasına engel,

Yabansı korkuları olan bir ben...

Ve...

Senden yetim bir ben daha...', 'Ben bir deliyim... Sınırsızlıklara bel bağlayan bir deli... Ben bir aşığım sevdiği kendiyle kesişen;  Tümleyeni hiç olmayan bir aşık... Bir ...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-bir-deliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Kıraç', 'islak-kirac-sule-aydemir-xcozq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '_________mimozaya takıldı serçecik

iki üç satır karalandı______________

_____________ ardından__________

adını minik koymuştu

dev adam

konuşmalarına gülmüştü 

sadece

gözyaşının kaynağını da 

bilmiyordu

inanılmazdı 

uyanıkken rüya görüyordu

adımları benim kadardı

gözleri bal kovanı

kahkahası dağlar kadardı

elleri pamuk tarlası

adını minik koymuştu

dev adam

dünyalar kadardı

ağladığını bilmeyen

duru ve yaşlı 

kıraçtı 

ıslak

bakışları', '_________mimozaya takıldı serçecik iki üç satır karalandı______________ _____________ ardından__________ adını minik koymuştu dev adam konuş...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/islak-kirac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-sirma-mersin-ws4yv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her hayal kırıklığına sığındığımda; 

Yeni bir başlangıç başlar, yüreğimde...

Bitmiş bir sevdanın ardından; 

Yepyeni bir sayfa açılır, hayatımda...

Yoklukların arasında; 

Varolan umut çıkar, karşıma...

6.3.04', 'Her hayal kırıklığına sığındığımda;  Yeni bir başlangıç başlar, yüreğimde... Bitmiş bir sevdanın ardından;  Yepyeni bir sayfa açılır, hayatı...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/umut-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı', 'cagri-emir-kemal-unra6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzünbaz bir yürek,

Sadık bir dost ararsan gel yanıma.

Acıtmaya gelmez hep bir yanı çocuk,

Hep bir yanı büyümeyen bir yürek...

Ağlamasını beceremeyen

Belki de bu yüzden ağlamaya muhtaç olan bir yürek istersen

Gel...

Hayata sıcacık bakan ama

Sırf bu yüzden dokunmayı beceremeyen,

Hayatın sürüklediği bir dost ararsan,

Zaman zaman körleşen

Ve bataklıkta gül yetiştirmeye çalışan bir ahmak ararsan

Gel yanıma...

Dokunmasın kimse saf duygularıma,

İşte ben de ağlamaklıyım,

Ben de deliyim,

Ben de en az senin kadar ahmağım diyebiliyorsan...

Her gece saat on ikiyi devirdiğinde,

Alıyorsan eline kalbini,

Ümitlerinle temizliyorsan,

Onlarca sevgiyi,

Aşkı sığdırabiliyorsan küçücük yüreğine,

Aklını yitirmekten korkmuyorsan

Gel...

Gerçek bilginin

Aslında hiçbir şey bilmediğini bilmek olduğunu biliyorsan,

Sana acıyanlara acıyor,

Ağlama diyenlerin haline de ağlıyorsan

Gel...

Sevgilini sevdiğinden dolayı terk ediyorsan,

Onu hak etmediğinden yani...

Yani hep bir yanını ezik görüyorsan

Gel...

Ne olursa olsun unutamıyorsan,

Unutman gerekse de,

Unutamadığın seni çoktan unutmuş olsa bile,

Bir çift söz için ömrün boyunca minnet duyuyorsan

Gel yanıma...

Kandırmıyorsan içinde büyütemediğin çocuğu,

Ölümden bile korkmuyorsan 

Gel...

Sana vurana “elin acımadı ya! ”diyecek kadar ezik,

Bataklıkta yetiştirmeye çalıştığın güle uzanan elleri

Kesecek kadar güçlüysen

Gel...

Ağladığımda elini göğsüne koyup ağlayacak,

Güldüğümde kahkahalar atacaksan,

Ve... 

Elime batan her dikende senin de canın acıyacaksa,

Bu fakirin sevgisine şaşırmayacaksan 

Gel,

İçinde ki çocuğa sor,

Öyle gel...', 'Hüzünbaz bir yürek, Sadık bir dost ararsan gel yanıma. Acıtmaya gelmez hep bir yanı çocuk, Hep bir yanı büyümeyen bir yürek... Ağlamasını be...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/cagri-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güne Açıldı Gülüm', 'gune-acildi-gulum-sema-oztabak-zu239', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güne açıldı gülüm soluyarak güneşi

Soyutlayıp dikenden uzattı ellerini

Silkindi bedeni

Yeşiller giyindi

Ardına saklı dikenler

Yavaşça boy gösterdi

Kan kırmızıya boyadı 

Öpüşleri

Sevişleri

Yeşiller... 

Acıya bezendi

Nedense...

Şevkle katlandı kalp 

Değişime

Ruh... 

Güneşli gülistanda gezindi 

18.03.2004', 'Güne açıldı gülüm soluyarak güneşi Soyutlayıp dikenden uzattı ellerini Silkindi bedeni Yeşiller giyindi Ardına saklı dikenler Yavaşça boy gö...', ARRAY['Türk Edebiyatı','Şiir','Sema Öztabak']::text[], 8.5, '{"poet":"Sema Öztabak","poet_slug":"sema-oztabak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gune-acildi-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yazmak', 'seni-yazmak-sirma-mersin-277em', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözcüklerin gücü karşısında,

Cümlelerin yorgun düşmüş olsa da....

Kalemim seni yazmaktan sıkılsada! 

Sayfalara dökeceğim, duygularımı...

Yüreğimin nerede olduğunu bilmeden; 

Hasret dolu yalnızlığımı çoğaltırken...

Zamanın karşısında  durmuyor,hüzün...

Gözyaşlarına boğulan, hayallerimin  arasında,

Kayboldu umudum! 

Seni yazarken; 

Yokluğunu hissetmek acı gelsede...

Beklenen sevgiyle beraber; 

Gelmen için dualarımla seslenirim, gecelerde sana...

7.3.04', 'Sözcüklerin gücü karşısında, Cümlelerin yorgun düşmüş olsa da.... Kalemim seni yazmaktan sıkılsada!  Sayfalara dökeceğim, duygularımı... Yür...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-yazmak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asl-ı Kemal', 'asl-i-kemal-emir-kemal-gogmt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat gecenin birinde,

Kederimle; 

Ben seninle uyuyorum...

Gölgen kalbime vurmakta,

Ve ben,

Aşk-ı kemâl e ermekteyim...

Sensizliği soluyor,

Seninle uyanıyorum.

Tüm çırpınışlarımı zincire vurup,

Seni sensizliğimde dinliyorum.

Yas vuruyor yüzüme,

Çalınıyor gözlerime elası...

Ve ben,

Yağmur olup yağıyorum 

Aşıkların yüreğine,

Şair olup söylüyorum

Sevdalıların dilinde...

Ve ben

Asl-ı kemâl e eriyorum bu günlerde...

Şarkılar uyduruyorum,

Demli,

Bir o kadar yürekli yüreğimle...

Ağlamak istiyorum hasretlerime,



Ve ben,

Sıla olup basıyorum gam teline,

Çiçek olup bitiyorum yüreğinde,

Diken olup koruyorum,

Sevgiliye derilen güllerimi,

Ve ben,

Galiba yine seviyorum,

Ben yine biliyorum,

Ben yine,

Asl-ı kemâl e eriyorum...', 'Saat gecenin birinde, Kederimle;  Ben seninle uyuyorum... Gölgen kalbime vurmakta, Ve ben, Aşk-ı kemâl e ermekteyim... Sensizliği soluyor, S...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/asl-i-kemal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-emir-kemal-22a69', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamak, 

Yaşlanmaktır birazda..

Önce ömür; 

Sonra gözler dolar yaşlarla...

Yakın olur bazı zamanlar

Ve

Davetsiz bir misafir gibidir...

Ölüm; 

Bir alfabenin en son harfidir,

Yalanlar kendinden önceki 28 harfi...', 'Yaşamak,  Yaşlanmaktır birazda.. Önce ömür;  Sonra gözler dolar yaşlarla... Yakın olur bazı zamanlar Ve Davetsiz bir misafir gibidir... Ölüm...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olum-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlüyorum', 'dusluyorum-emir-kemal-900kv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevda yüzlü insanlar düşlüyorum,

Her gülüşlerinde yeşerten baharı...

Ay yüzlü çocuklar diliyorum,

Versinler ellerinden çiçekleri...

Bir dağ düşlüyorum,

Her yanı bir yol...

Bir deniz düşlüyorum

Yakamozuyla içimizi parlatan...

Bir kadın düşlüyorum,

Kilitleri kırıp gelen...

Ve...

Bir acı düşlüyorum,

En mutlu günümüzde yitirilen.

Düşlerimde yoruluyorum seni sevmekten,

Ve bir seni düşlüyorum; 

Düşündükçe düşlerimden düşen...

Bir seni...', 'Sevda yüzlü insanlar düşlüyorum, Her gülüşlerinde yeşerten baharı... Ay yüzlü çocuklar diliyorum, Versinler ellerinden çiçekleri... Bir dağ ...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dusluyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaca karanlıkta', 'alaca-karanlikta-burhan-kucuk-ueo38', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alaca karanlıkta

Alaca karanlıkta beni vurdun

Sen vurdun,ben gördüm

Altın kaplamaydı silahın

Parladı bir ortasında gecenin

Ayak seslerini duymuştum

Hayatıma girerken senin

Nasılda, usulca yaklaşmıştın

Sessizce derinden girdin

Ben koca çınar dal uzattım

Geldin kondun dalıma

Çokta güzel yakışmıştın

Ben seni bülbül sanmıştım

Alaca karanlıkta beni vurdun

Sen vurdun,ben gördüm

Altın kaplamaydı silahın

Parladı bir ortasında gecenin

Burhan KÜÇÜK

Kdz.Ereğli', 'Alaca karanlıkta Alaca karanlıkta beni vurdun Sen vurdun,ben gördüm Altın kaplamaydı silahın Parladı bir ortasında gecenin Ayak seslerini du...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/alaca-karanlikta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldandım yine', 'aldandim-yine-burhan-kucuk-qqg8o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aldandım yine

Yağmurlu bir gecede çıktım yola

Karanlıktı her yer senin gibi

Bir ışık arar oldu gönlüm

Buldu derken uzaklarda

Serapmış meğer gördüğüm

Aldandı yine garip gönlüm

Burhan KÜÇÜK

Kdz.Ereğli', 'Aldandım yine Yağmurlu bir gecede çıktım yola Karanlıktı her yer senin gibi Bir ışık arar oldu gönlüm Buldu derken uzaklarda Serapmış meğer ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aldandim-yine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum 2', 'yorgunum-2-erol-sen-melte', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biten günden arda kalan

Yapılan bitmiş işlerin sevinci

Öksüz kalan da yarına kalacak işlerim

Ben ise yorgun bedenime yaslandım

Uzandım çantama gazetelerimi koydum

Odamın perdelerini çekerken yavaş yavaş

Bilgisayarımın kapanmasını bekledim

Aldım çantamı  çıkışa yöneldim

Akşamın karanlığında ilerlerken arabama

Bir nefes çektim doyasıya

Biten iş günü kendini yeni bir akşama bırakırken

Arabam yola koyuldu soğuk ve isteksiz

Çişeyen yağmuru severim gönlüme

Radyoda çalan güzel bir ezgiyle

Eyy insanlar sizden biriyim kendimce

Ama benim sevgilerim özlemlerim kendime

Bekleyenim var benim belki senin yok

Benim sevgilerim var kendime göre yaşadığım

Özlemlerim planlarım huzurum var kendimce

Ama yorulmuşum çalışmaktan

Akşam olmuş gece doğmuş güne sessizce

Paylaşılmış saatler gibi 

Kavga dövüş varmı bilinmez bir yerler de

Varsa bile ben bilmiyorum

Hakedene değerlerim var kendimce

Bitimsiz sevgim ve özlemim de

Paylaşılmış görevler yapılası işler

Geceye dinlenecek bedenim

Yeni doğacak güne güzellikler başlayacak 

Diye geceyi bitirirken

Yazılan şiirlerime gönlümle sarılmışken

Giden geceye yaşamla bitimsiz.

12.03.2004', 'Biten günden arda kalan Yapılan bitmiş işlerin sevinci Öksüz kalan da yarına kalacak işlerim Ben ise yorgun bedenime yaslandım Uzandım çanta...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yorgunum-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli değil', 'belli-degil-burhan-kucuk-9kt6q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belli değil

Dönüyor dünya,ne tarafa belli değil

Bilenlerde söylemiyor, aslı belli değil

Karışmış dünya iç içe, olacak iş değil

Gösteriyor ekranlar,seyredeni belli değil

Bir yol tutturmuş insanoğlu,yol belli değil

Kimin eli kimin cebinde,eller belli değil

Yol almış kervan gidiyor,hancı belli değil

Almış sazı eline söylüyor,ozan belli değil

Kural konmuş her yere,kural belli değil

Gemi kalkıyor limandan,rotası belli değil

Soğuk esiyor rüzgarlar,yönleri belli değil

Yel değirmeni kurmuş,kim olduğu belli değil 

Alev almış ormanlar,kibriti çakan belli değil

Petrole bulanmış denizler,bulayan belli değil

Fay hattına binalar kurulmuş,nedeni belli değil 

Haber yapmışlar gazetelerde,okuyan belli değil

Nehir olmuş dereler,çaylar,köprüleri belli değil

Sel olmuş yağmur tanesi,tutan baraj belli değil

Bir köy var uzakta,çocuğu bol,okulu belli değil

Dökmüş kağıda,kalemi Burhan, şair mi belli değil

Burhan KÜÇÜK

Kdz.Ereğli', 'Belli değil Dönüyor dünya,ne tarafa belli değil Bilenlerde söylemiyor, aslı belli değil Karışmış dünya iç içe, olacak iş değil Gösteriyor ek...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/belli-degil-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmezdim', 'bilmezdim-burhan-kucuk-oraib', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmezdim

Ben aşk nedir bilmezdim

Daha on beş yaşında çocuktum

Seni  gördüm, sana tutuldum

Yanmam derdim,yandım kül oldum

Aşkın çemberinden geçirdin

Attın rüzgarlara savurdun

Yaktın kalbimi kavurdun

Daha on beş yaşında çocuktum

Şimdi yangının eksik olmaz yüreğimden

Gülümsersin hep,gönül penceremden

Gönlüm geçse de bu dünyadan

Bil ki sen hep gönlümdesin

Burhan KÜÇÜK

Kdz.Ereğli', 'Bilmezdim Ben aşk nedir bilmezdim Daha on beş yaşında çocuktum Seni  gördüm, sana tutuldum Yanmam derdim,yandım kül oldum Aşkın çemberinden ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bilmezdim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esas Ayna', 'esas-ayna-burhan-kucuk-r0y9f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Esas Ayna

Durmuşsun aynanın karşısına

Bakıyorsun,üzerine başına

Tarıyorsun güzelce saçını

Güzel diyorsun görüntü iyi aynada

Dur sor bir defa istersen bana da

Söyleyeyim kıl kalmış burnunda

Burhan KÜÇÜK

Kdz.Ereğli', 'Esas Ayna Durmuşsun aynanın karşısına Bakıyorsun,üzerine başına Tarıyorsun güzelce saçını Güzel diyorsun görüntü iyi aynada Dur sor bir defa...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/esas-ayna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim dolar ağlayamam ben', 'gozlerim-dolar-aglayamam-ben-burhan-kucuk-6r1h3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim dolar  ağlayamam ben

Gideceğim bir gün,tasımı tarağımı toplayıp

Çekip gideceğim ardıma bakmadan

Bakarsam bir kez ardıma

Gidemem,adım atmaz olur ayaklarım

Gözlerim dolar  ağlayamam ben

Gideceğim bir gün,tasımı tarağımı toplayıp

Ve ardıma bakmadan,dönmeksizin

Ne güzel di aslında yaşadıklarımız

Geride bıraktıkça,gözlerimin önün de

Gözlerim dolar  ağlayamam ben

Gideceğim bir gün,tasımı tarağımı toplayıp

Sevmiştim ben sizleri çok

Sizde beni o sıralar çok

Yalan mıydı,yalan mıydı yoksa 

Gözlerim dolar  ağlayamam ben

Gideceğim bir gün,tasımı tarağımı toplayıp

Kahrolası zaman kahrolası

Ne de çabuk gelip geçtin böyle

Ve yıktın hep kumdan kalelerimi

Gözlerim dolar  ağlayamam ben

Burhan KÜÇÜK

Kdz.Ereğli', 'Gözlerim dolar  ağlayamam ben Gideceğim bir gün,tasımı tarağımı toplayıp Çekip gideceğim ardıma bakmadan Bakarsam bir kez ardıma Gidemem,adı...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozlerim-dolar-aglayamam-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-burhan-kucuk-tc8x6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani

Hani bir yaz mevsimidir

Çiçekler açar

Hani tırtıllar vardır

Kelebek olurlar

Hani ilk kanat çırpışlar

Yuvadan ayrılır ya kuşlar

Hani yağmur yağar

Buhar çıkar

Toprak kokar

Hani insanlar vardır

Ömrü bir mevsimdir

Dağ başında kar misali

Aslında erimek lazım

Akmak toprağa süzülerek

Ve yaşamak

Güzel yaşamak..

Burhan KÜÇÜK

Kdz.Ereğli-11.01.2004', 'Hani Hani bir yaz mevsimidir Çiçekler açar Hani tırtıllar vardır Kelebek olurlar Hani ilk kanat çırpışlar Yuvadan ayrılır ya kuşlar Hani yağ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hani-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-refik-recep-pelit-x1wz5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BEN''im deme,veren Allah, eksiltmez ki lütfunu 

Gözler görmez,gerçek sanır, söylenen hilafını

Fazla gurur büsbütün sarmış heyhat vücudunu 

Bidar isen,dün dinlen, ikfal etme dimağını.

BEN''den sana nasihat, üzme yazık güruhunu 

Mümtaz ol, O dindirir, kalbin acı sızısını 

Malik O''dur,  bil ki alır, söyletmez türüdunu.

Sadan olur, arz aleme, bir sinek vızıltısı.

Bidar: Uykusuz,Yorgun 

Dün : Gayrı 

İkfal: Kilitlemek 

Güruh: Cemaat,topluluk

Türud: Türkü,Şarkı', 'BEN''im deme,veren Allah, eksiltmez ki lütfunu  Gözler görmez,gerçek sanır, söylenen hilafını Fazla gurur büsbütün sarmış heyhat vücudunu  Bi...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılama', 'karsilama-basak-kanat-ffiso', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gerçek hayata hoşgeldiniz küçük hanım...

Ne kadar da mağrursunuz...

Oysa boynunuzu eğmeyi,

Eğebilmeyi öğrenmek için

İçin...

İçin...

İçin için ağlamayı bilmeliydiniz.

Hoşgeldiniz...

Hoş...

Hoşşafff....

''Üç tas has hoşaf'' diyebilmeyi öğrenmeliydiniz.

Hoşgeldiniz küçük hanım...

Nerelerdeydiniz? ..

Gelemediniz...

Bekledik.

Bekledik..

Bekle...

Dikte ettirecektik hayatı...

Gelmek bilmediniz...

Bilemediniz...

Oysa tam zamanında gelmeliydiniz.

Nerelerdeydiniz küçük hanım? ..

Gözümüz yollarda kaldı.

Gözümüz üstünüzde,

Gözümüz altınızda,

Sağınızda, solunuzda...

Gözümüz...

Göz...

İki gözümüz...

İki çeşme...

Üzgünüz...', 'Gerçek hayata hoşgeldiniz küçük hanım... Ne kadar da mağrursunuz... Oysa boynunuzu eğmeyi, Eğebilmeyi öğrenmek için İçin... İçin... İçin içi...', ARRAY['Türk Edebiyatı','Şiir','Başak Kanat']::text[], 8.5, '{"poet":"Başak Kanat","poet_slug":"basak-kanat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/karsilama-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masallar ''Kaçak Yolcu Fare''', 'masallar-kacak-yolcu-fare-deniz-uuu-rqy5n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir varmış.Bir yokmuş.Evvel zaman 

içinde.Kalbursaman içinde.

Bir Japon fare varmış.Bu fare evde çok 

sıkılmış...Bir gün kaçmaya 

Karar vermiş.Sokağa çıkmış.Giderken 

bir otobüs görmüş.Tam o 

Sırada bir kamyon geçiyormuş.

Fare kamyona atlayıp gitmeye 

başlamış.Giderken fare otobüsün mola 

verdiğini görmüş.

Hemen otobüse atlamış.Bagaja 

girmiş.Bir çantanın içine girmiş.

Ve bir şeyler atıştırmaya başlamış.Paris 

sınırında bizim fare nefes 

alamaz olmuş.''ÖHÖÖÖ ÖHÖÖÖÖ'' 

yapmaya başlamış.Garaja

girmişler, çantaları almaya başlamışlar,

eve gelmişler.ÖHÖÖÖÖ

ÖHÖÖÖÖ yapan fareyi duyan çocuk 

''Baba biri öksürüyor.''

demiş.Babası çantayı açmış fareyle 

burun buruna gelmişler.Fare hemen 

kaçmaya başlamış.Hemen adam

kovalamaya başlamış.

Kovalamaca yarım saat sürmüş

sonunda kaçmayı başarmış.

Sokakta sevinçle yürürken bir kedi

sessizce gelip fareyi yemiş', 'Bir varmış.Bir yokmuş.Evvel zaman  içinde.Kalbursaman içinde. Bir Japon fare varmış.Bu fare evde çok  sıkılmış...Bir gün kaçmaya  Karar verm...', ARRAY['Türk Edebiyatı','Şiir','Deniz Uuu']::text[], 8.5, '{"poet":"Deniz Uuu","poet_slug":"deniz-uuu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/masallar-kacak-yolcu-fare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Aşk', 'bitmeyen-ask-onur-kantarci-ig2wq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazı aşklar sadece zaman geçirmek için

Kısa süren aşklardır.

Bazıları ölene dek sürer

Ölüm kapıya dayandığında noktalanır.

Öyle aşklar vardır ki

Ölüm bile ayıramaz

Bir süreliğine bedenler ayrılır

Yalnızca...

Sonrası; 

Cennette yaşanır

Sonsuza dek ebediyen...', 'Bazı aşklar sadece zaman geçirmek için Kısa süren aşklardır. Bazıları ölene dek sürer Ölüm kapıya dayandığında noktalanır. Öyle aşklar vardı...', ARRAY['Türk Edebiyatı','Şiir','Onur Kantarcı']::text[], 8.5, '{"poet":"Onur Kantarcı","poet_slug":"onur-kantarci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bitmeyen-ask-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüyorum', 'oluyorum-mert-gucer-68aej', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürüyorum,

Bir yol var önümde,

Uzun,kısa yok,

Sadece hissediyorum.

Mavi bulutların ardındaki,

Kayıp yaşamları görüyorum.

Akan nehirlerin kaynağındaki,

Özlem dolu gözleri görüyorum.

Bir çocuk ağlıyor,

Bakıp bakıp özlemli ailesine.

Biri kadere inat bağırıyor,

''Aşkım,ben burdayım'' diye.

Bense zaten bitmiş hayatımdaki,

Uzatmaları oynuyorum.

Herkesten ayrı bir köşede,

Gözlerimi yumdum geliyorum.

Artık zaman bitti,

Ben ölüyorum..', 'Yürüyorum, Bir yol var önümde, Uzun,kısa yok, Sadece hissediyorum. Mavi bulutların ardındaki, Kayıp yaşamları görüyorum. Akan nehirlerin kay...', ARRAY['Türk Edebiyatı','Şiir','Mert Güçer']::text[], 8.5, '{"poet":"Mert Güçer","poet_slug":"mert-gucer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/oluyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buradayım (şiir)', 'buradayim-siir-aynur-uluc-lpd9z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'işte burdayım dört yanım duvar

arkasındaki ışığı bilmiyorum

burada dağınık sessiz sedasız

sökük heybe gibi oturuyorum

yılların tortusu dolu içimde

bir kussam kendimi

sağsam içimden

kırık aynayı alsınlar benden

batmasın artık ciğerlerime

delmesin göğsümü bu buruk resim

yeniden doğuşa salsınlar beni

razıydım suni sevişmelere

ne zaman yapıldı bu lanet lehim

bağırıyor bedenimde reçine

kurtarın diye kendimi benden 

yok mu çilingiri bu kilidin

bulutun çengeline hasretim

tatmadığım lezzetleri özledim', 'işte burdayım dört yanım duvar arkasındaki ışığı bilmiyorum burada dağınık sessiz sedasız sökük heybe gibi oturuyorum yılların tortusu dolu ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/buradayim-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaletler', 'hayaletler-naime-erlacin-yskdk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'birileri dolanıyor ortalıkta

kimini görür göz

kimini…. 

işte öyle! 

öyküler dinler dururum

yalan 

dolan 

gerçek

her neyse! 

membaınız nedir 

söylesenize

nerde gizlenirsiniz 

nasıl bir şeydir 

rumuzlara sığınmak

hikayecinin de bir sabrı var

isminiz nedir

cisminiz

ülkenizden vazgeçtim

neye benzersiniz

ne? 

Pizza kulesi neden eğri ki

ya düşecek olursa! ! ! ...

(11 Mart  2004)

Not: Yukarıdaki dizelerin, rumuz veya mahlas kullanan şairlerle bir ilgisi yoktur. Bana yöneltilen bazı sorulardan sonra bu açıklamayı yapmayı gerekli buldum. Pek çok kişi bana Antoloji Mesajlar Sevisi kanalıyla ulaşmakta ve gerçek isim belirtmedikleri takdirde ise yanıt alamamaktan şikayet etmekte veya farklı rumuzlarla yeniden, yeniden denemektedirler. Yazma teknikleri ve üsluplarından hemen anlaşılıyor zaten. Her şeye rağmen önemli ve makul bir gerekçeleri varsa eğer, yine de cevaplamaya gayret ediyorum. Ama vaktimin saçma sapan oyunlarla ziyan edilmesine karşı verdiğim doğal bir tepkidir bu...

''Pizza Kulesi'' ise düzenin kendisidir....Saygılarımla...(13 Mart 2003)', 'birileri dolanıyor ortalıkta kimini görür göz kimini….  işte öyle!  öyküler dinler dururum yalan  dolan  gerçek her neyse!  membaınız nedir ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayaletler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anamakıllı', 'anamakilli-abdullah-atay-tpcu9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdim mi; 

Bir ananın dokunuşu.

Bebeğin memeye sokuluşu.

Arının peteğe doluşu  gibi

Severim...

Sevdim mi; 

Anam gibi akıllı.

Anamakıllı...

Babam gibi.

Adam gibi,adam gibi.

Adamakıllı severim...', 'Sevdim mi;  Bir ananın dokunuşu. Bebeğin memeye sokuluşu. Arının peteğe doluşu  gibi Severim... Sevdim mi;  Anam gibi akıllı. Anamakıllı... ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anamakilli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Ta kendisi *', 'ta-kendisi-kubilay-enginol-hgzjv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamın kendisiyim ben

Bazen 

Bir atmacanın kanadında

Bazen

Suskunluğun gırtlağında

Gülümseyerek,izlerim

Olanı,biteni istanbul sokaklarında

Bir taş olurum bazen

Nefrete elçi olurum

Bir gül olur,vazoda kururum

Gözyaşı olurum,ten''den sulara karışırım

Irmak olurum,kendimi aşarım

Gecenin sessizliği olurum,susar

Aşk olur

Yokolurum', 'Akşamın kendisiyim ben Bazen  Bir atmacanın kanadında Bazen Suskunluğun gırtlağında Gülümseyerek,izlerim Olanı,biteni istanbul sokaklarında ...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ta-kendisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ferman', 'ferman-murat-tali-udugz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gönül 

fermansız bir tebliğ gibi 

sokaklarda davullarla ilan ediyor aşkını

duyduk duymadık demeyin

duyanlar duymayanlara söylesin

seviyorum diyor

fermanla 

ilanı aşk ediyor

duymayanlar duyanlardan duysun

seviyorum 

ferman gönlün

akıla uymak düşer

duyanada anlatmak', 'gönül  fermansız bir tebliğ gibi  sokaklarda davullarla ilan ediyor aşkını duyduk duymadık demeyin duyanlar duymayanlara söylesin seviyorum ...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ferman-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-i-smet-kemal-turkay-sc3ez', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmem ki kimlerle gönül eylersin,

çabuk unutturum sanma seni yar; 

kaç yıl oldun söyle gideli benden,

ayrılık kolaysa unutmak çok zor.

Sensizlik her saat her an başucumda,

hayalin kurulur canlanır aklımda; 

kifayetsiz herşey sen olmadığında,

yokluğun dost gibi düşmanım oldu.

Nice gönüllerden bakmadan geçtim, 

nice sabah oldu hep yolun gözledim; 

gülmeyi unuttum tebessüm görmedim,

inan bir tek senden geçemedim yar, 

vazgeçemedim.

Sensizlik her saat her an başucumda,

hayalin kurulur canlanır aklımda; 

kifayetsiz herşey sen olmadığında,

yokluğun hem dostum düşmanım oldu.', 'Bilmem ki kimlerle gönül eylersin, çabuk unutturum sanma seni yar;  kaç yıl oldun söyle gideli benden, ayrılık kolaysa unutmak çok zor. Sens...', ARRAY['Türk Edebiyatı','Şiir','İsmet Kemal Türkay']::text[], 8.5, '{"poet":"İsmet Kemal Türkay","poet_slug":"i-smet-kemal-turkay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensizlik-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban', 'yaban-esma-ozdemir-f9zof', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir boşlukta dolaşırsın biçare

Karanlığın ortasında divane

Kör, sağır, dilsiz kaldın, kime ne!

Özlemler, umutlar, arayışlar nafile... 

Nerde benim dünyam, insanlar nerede

Ailem, arkadaşlarım, aşklarım nerede

Neden bu suskunluk, bu şaşkınlık neden

Neden bu kadar yabancı insanlar birbirlerine

Mahşer günü mü geldi, alıp veremediğin kime?', 'Bir boşlukta dolaşırsın biçare Karanlığın ortasında divane Kör, sağır, dilsiz kaldın, kime ne! Özlemler, umutlar, arayışlar nafile...  Nerde...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yaban-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Promil / Gittikçe Cıvıtan Şiir', 'promil-gittikce-civitan-siir-orhun-basat-k0uix', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'l – (0 promil)

önümde boş bir kağıt / elimde bir kalem,

masanın üstünde içi boş bir kadeh / bir boşluk 

ve gecenin sıyrıkları..

birkaç imge, bir / iki imgelem..

ll – (50 promil)

saçlarımda kırağılar / sıkıntılar 

kaşığımda acı, çatalımda elem,

yüreğim yanardağ yamaçları..

tükendikçe ben / sanadır ve

tükenen içkiyedir özlem..

lll – (180 promil)

yalnızken içmemeli insan,

yalnız da kalmamalı / koku yapıyor 

kalkıp ekşimiş imgeleri ve acıları 

toplamalı masadan..

bakkaldan / bir şişe şiir daha alıp gelmeli, kapanmadan..

yepyeni acılara, tertemiz bir örtü sermeli,

kanım iyice buharlaşmadan..

lV – (260 promil)

(ilk imgeyi soymalı önce..

sıkıştırmalı iyice / gözlerine tutup geceyi,

ne demek istiyor / iyice anlamalı..

komserim kızar sonra, anlar şiirden,

“ intikamı meşhurdur “ komserimin,

bu şiir çok iyi olmalı..

V – (koma)

neden  düşüyor bu kalem elimden? 

sen de kimsin ablacım? ellerin ben de kalmıştı diyen! ! 

kim ısırdı şiirimin ucunu? 

komserim! bu durumu.. hıkk.. üst makamlara mı sormalı? 

en iyisi bu dizede kesmeli kavunu / pardon şeyi..? ! ! 

bitirmeye uğraşmamalı şişeyi,

şiiri, çöpe atıp yatmalı..

Vl – (ifade)

hayır, komserim.. ben..

şiirle vurdum adamın kafasına,

şişeyle değil / bir yanlışlık olmalı,

şiir öldürmez adamı..

yaaa! ! aşık mıymış adamcağız? ! ! 

nerden bilebilirdim, komserim..

neyse kesin cezamı..! !', 'l – (0 promil) önümde boş bir kağıt / elimde bir kalem, masanın üstünde içi boş bir kadeh / bir boşluk  ve gecenin sıyrıkları.. birkaç imge,...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/promil-gittikce-civitan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-hakki-hakan-kaya-vcu1a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşlerimdeki fırtınamdın,

Beni sevdalara uçuran,

Bir rüya gibi geldin,

Ve yine öylece gittin...', 'Düşlerimdeki fırtınamdın, Beni sevdalara uçuran, Bir rüya gibi geldin, Ve yine öylece gittin......', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/firtina-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel dersin....gelmez.', 'gel-dersin-gelmez-hasan-basri-kale-yawxm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel dersin....gelmez.

Gelme dersin....gelir,

ama gitmez..

Sev dersin....sevmez.

Sevme....diyemezsin,

yakışık almaz..

Başım belâda...anlayacağınız.

Deli diyecek kesin, şiiri okuyanlar

Birkaç güne kalmaz..', 'Gel dersin....gelmez. Gelme dersin....gelir, ama gitmez.. Sev dersin....sevmez. Sevme....diyemezsin, yakışık almaz.. Başım belâda...anlayaca...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gel-dersin-gelmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlık', 'yanlizlik-ayten-ozlem-yesilcali-fimf0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kar vurdu dağlarına memleketimin

Senin beni insafsızca  vurduğun gibi 

Üşüttü dondurdu insanlarımı.

Senin ateşinin beni yaktığı gibi; 

Beni sevmelerin yok mu; 

Gözlerimin önünde dans eder her gün.

Gözlerim her gün arar oldu seni.

İsyan etmeye başladım yanlızlığıma

Fırtınalar kopuyor yüreğimde; 

Yalnızlık çığ gibi büyür içimde.

Kör bir kuyudaymışım sanki.

Sevincim bitti,hasretler büyüdü.

Yalnızlık girdabında yitip gidecegim.

Boğazıma düğümlenir oldu kelimeler

Adını haykırmak isterim.

Sesim çıkmaz,nefesim tükenir.

Gözlerim bugulanır.

Artık bu sokaklarda aşık olmak yasaklanır.

Sevenler sevdiklerinden vazgeçmek zorunlulugunu yaşar.

Kimse sevdigine sevdasını söyleyemecek.

Aşk burada yirmidört saatlik.

Benim buralarda senin için aglamalarım.

Yalnızlıktan bıktım,bıktım sensiz yanlızlıgı; 

Seninle sensiz yaşamaktan....', 'Kar vurdu dağlarına memleketimin Senin beni insafsızca  vurduğun gibi  Üşüttü dondurdu insanlarımı. Senin ateşinin beni yaktığı gibi;  Beni ...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yanlizlik-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kopuk Kopuk', 'kopuk-kopuk-alaettin-isik-308zj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden bir bütünü severiz de,

	Yarım olan şeyi sahiplenmeyiz? 

	Neden her konuda güzelini,

	Ararız da, çirkini iteleriz? 

	Neden akları bir tarafa,

	Karaları öteye koyarız? 

	Biriken bunca itilmişleri,

	Bir arada görmek istemeyiz! 

	İçimizde hiç mi yok yanlış,

	Eksik ve kötülükler, kopuk kopuk..

               12/03/2004', 'Neden bir bütünü severiz de, 	Yarım olan şeyi sahiplenmeyiz?  	Neden her konuda güzelini, 	Ararız da, çirkini iteleriz?  	Neden akları bir t...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kopuk-kopuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Yaşıyorum', 'sensiz-yasiyorum-suskun-resital-gkee6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dilimden düşmeyen dua gibisin, 

İncitmesin seni kimse,

Hiç üzmesin! 

Leyla oldun gönlümde,

En çok seni seviyorum. 

Yüreğim sende ama gülüm,

Seni sensiz yaşıyorum....', 'Dilimden düşmeyen dua gibisin,  İncitmesin seni kimse, Hiç üzmesin!  Leyla oldun gönlümde, En çok seni seviyorum.  Yüreğim sende ama gülüm, ...', ARRAY['Türk Edebiyatı','Şiir','Suskun Resital']::text[], 8.5, '{"poet":"Suskun Resital","poet_slug":"suskun-resital","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensiz-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talih Kuşu', 'talih-kusu-yusuf-ziyaeddin-sivaslioglu-2jt1v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimi omuza

Talih kuşu konar

Kimine de

Talih kuşunun şeyi

Kimi omuza

Yaldızlı yıldız

Kimine de

Çökmeyen omuz

Tanrının lütfudur bu

Farkında olmalıyız.

(9 Mart 1982, Şanlıurfa)', 'Kimi omuza Talih kuşu konar Kimine de Talih kuşunun şeyi Kimi omuza Yaldızlı yıldız Kimine de Çökmeyen omuz Tanrının lütfudur bu Farkında ol...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/talih-kusu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-yusuf-ziyaeddin-sivaslioglu-pexc4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsanlar hep ölür

Ama insanlık hep yaşar

İnsanlık yap

Sen de hep yaşa

İnsansın,

İnsan kal,

Vurma eğri yollara

Dost elini uzat

Çevrende gördüğün insanlara

İnsan gibi yaşa

Zulmün hatıra kalmasın

İnsanlara

Bırakacağın miras

İnsanlıktır çocuklarına

(10 Mart 1982, Şanlıurfa)', 'İnsanlar hep ölür Ama insanlık hep yaşar İnsanlık yap Sen de hep yaşa İnsansın, İnsan kal, Vurma eğri yollara Dost elini uzat Çevrende gördü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/insanlar-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feneryolu', 'feneryolu-yusuf-ziyaeddin-sivaslioglu-ebme9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bağlandık,

İstanbul''un toprağına

Aşına,

Ev aldık,

Oturduk Feneryolu''na

Bağdat caddesi,

Köprü, Boğaz,

Geçtikçe anlıyorum

Biz de İstanbul''luyuz biraz

Kalabalık insanlar

Taş duvarı binalar

Tamiri bitmeyen kaldırımlar

Fukara dolu varoşlar

Hepsi İstanbul''da var

Özel, resmi tiyatrolar,

Vizyon oynayan sinemalar

Beyoğlu''nda barlar

Boğazda balık tutanlar

Hepsi İstanbul''dalar

Gençliğimin şehri

Boğazda bir ev

Hayallerimi süslerdi

Feneryolu''nda bir eve

Ancak paramız yetti.

(1 Haziran 2002, Feneryolu / İstanbul)', 'Bağlandık, İstanbul''un toprağına Aşına, Ev aldık, Oturduk Feneryolu''na Bağdat caddesi, Köprü, Boğaz, Geçtikçe anlıyorum Biz de İstanbul''luyu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/feneryolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mal Sahibi', 'mal-sahibi-yusuf-ziyaeddin-sivaslioglu-w4rs4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mal sahibi kendin sanır,

Can bedenden ayrılınca

Dünya malı dünyada kalır

İnsanoğlu tamah ederse mala

Veda ederken tatlı cana

Kefenin cebi yok koymaya

Yeteri  nedir? Fazlası nerede? 

Kimsenin aklı ermiyor fazlayı tesbite

Bildiğim yetim hakkı saklıdır vergide.

Mallar dünyanın, canlar fani

Gazetelerde okuduğın ölüm ilanları

Oynayan filmin en büyük şahidi.

(17 Şubat 2004, İstanbul)', 'Mal sahibi kendin sanır, Can bedenden ayrılınca Dünya malı dünyada kalır İnsanoğlu tamah ederse mala Veda ederken tatlı cana Kefenin cebi yo...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mal-sahibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serserice Sevmeler', 'serserice-sevmeler-yagmur-damlasi-6whgc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmeler yasak bana

Öyle diyorsun

Her gece dolun ayla

Tenin bana ulaşır biliyorsun

Kokun önden gelip

Tüm dünyamı dolaşır

Yalanlar

Karanlıklarla boğuşur

Doğru yanlışla yarışır

Ve gün doğarken penceremde

Aşkın yüreğimde 

Zulme bulaşır

Nefes almak için 

Camı açmak gerekse de

Yüreğimi kapatmamak için

Camı açmıyorum

Ve delice seviyorum ben seni

Adın aklıma gelince

Güvercinler uçuyor yüreğimde

Kanat seslerini duyuyorum

gagaların da sevda

Hep soruyorsun ya neden

Nasıl………

İşte her şeyin cevabı sende

Seviyorum seni 

Sersericesine', 'Sevmeler yasak bana Öyle diyorsun Her gece dolun ayla Tenin bana ulaşır biliyorsun Kokun önden gelip Tüm dünyamı dolaşır Yalanlar Karanlıkla...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/serserice-sevmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğaz Rüzgarları', 'bogaz-ruzgarlari-yusuf-ziyaeddin-sivaslioglu-ov0m5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzümde Boğaz rüzgarları

Süpürüyor karları,

Kalbimde aşk rüzgarları

Coşturuyor dalgaları

Vadilerden esen yel

Hüznünle beraber gel

Aşka uzanan eller

Tövbenle beraber gel

(2 Ocak 1992, İstanbul)', 'Yüzümde Boğaz rüzgarları Süpürüyor karları, Kalbimde aşk rüzgarları Coşturuyor dalgaları Vadilerden esen yel Hüznünle beraber gel Aşka uzana...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bogaz-ruzgarlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Geldin', 'yalniz-geldin-yusuf-ziyaeddin-sivaslioglu-pv78l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnız geldin dostum

Yalnız gideceksin

Tüm sevdiklerini bırakıp

Geldiğin yere döneceksin

Topraktan geldik

Toprağa döneceğiz

Doğarken biz ağladık

Ölürken dostlar ağlayacak

Bu yolculuğun

Gelişi tek biletli

Dönüşü de öyle

Aldırma dostum

Derdini toprağa söyle

(19 Temmuz 2002, İstanbul)', 'Yalnız geldin dostum Yalnız gideceksin Tüm sevdiklerini bırakıp Geldiğin yere döneceksin Topraktan geldik Toprağa döneceğiz Doğarken biz ağl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziyaeddin Sivaslıoğlu']::text[], 8.5, '{"poet":"Yusuf Ziyaeddin Sivaslıoğlu","poet_slug":"yusuf-ziyaeddin-sivaslioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalniz-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarım Var', 'dostlarim-var-sabit-i-nce-gc9dd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostlarım var, dostlarım var

gönül veren dostlarım var.

öyle dostlarım olsun ki,

sürsün taa mahşere kadar', 'Dostlarım var, dostlarım var gönül veren dostlarım var. öyle dostlarım olsun ki, sürsün taa mahşere kadar...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dostlarim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Damla', 'bir-tek-damla-cuneyt-sahinoz-qnj8o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni bırakın! 

Beni bana bırakın! 

Ben bir tek benle

Baş başa kalayım.

Bir  “of ” çekeyim

Derinden,biraz uzunca

Kara bulutlar üzerime

Yağmurlarını bıraksın

Buz mavisi yüreğimi

Lime lime eritsin.

Gözlerim sadece buğulansın

Yaş akmasın damlalarca

Dökülürse de yalnız

Bir tek damla düşsün

Süzülerek yanaklarımdan

Toprağı ıslatsın,sel olsun

O bir tek damlayla

Boğayım kederimi…', 'Beni bırakın!  Beni bana bırakın!  Ben bir tek benle Baş başa kalayım. Bir  “of ” çekeyim Derinden,biraz uzunca Kara bulutlar üzerime Yağmur...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Şahinöz']::text[], 8.5, '{"poet":"Cüneyt Şahinöz","poet_slug":"cuneyt-sahinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-tek-damla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sülfrik', 'sulfrik-ahmet-aksoy-v8out', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tahamülsüz aşk yeşeriyor uçurum kenarı

yürek dayanmaz zulüm tutku tufanında güçsüz

hey! kalk yıkıldığın duvarlar büyüyor yağmurda

ölüleri dirilten kalp mezarlığında keder', 'tahamülsüz aşk yeşeriyor uçurum kenarı yürek dayanmaz zulüm tutku tufanında güçsüz hey! kalk yıkıldığın duvarlar büyüyor yağmurda ölüleri di...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sulfrik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fecre İz Düşer', 'fecre-i-z-duser-ahmet-aksoy-29d8m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir düş gibi çökerken damıma fecir

söz olur engin çıban kanatır yalnızlığım

oysa hüzün aslımda benden yanadır

üstümden geçen tren zamanın ayak izleri

10 Mart 2004', 'bir düş gibi çökerken damıma fecir söz olur engin çıban kanatır yalnızlığım oysa hüzün aslımda benden yanadır üstümden geçen tren zamanın ay...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/fecre-iz-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zarf''a ne hacet', 'zarf-a-ne-hacet-refik-recep-pelit-33pln', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Demirden korksa idim, tren ezer geçerdi,

Bak gözlerin uyuşmuş, hemde gitmiş o feri

Senin gürültülerin, arş-ı alemde iken 

Ağlayanın sesine, karışmış gülme sesi. (12,03,2004 İstanbul 21,00)  

*****

Senin gölgenden korkan, olmalı senin gibi 

Derdim yok şükür olsun,anlatırdım inSANA 

Gururun yeter sana,Unutmuşsun sözleri,

Pabucun damda artık,yat istersen uykuna..(12,03,2004 İstanbul 21,01)', 'Demirden korksa idim, tren ezer geçerdi, Bak gözlerin uyuşmuş, hemde gitmiş o feri Senin gürültülerin, arş-ı alemde iken  Ağlayanın sesine, ...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zarf-a-ne-hacet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrep', 'akrep-yagmur-damlasi-hlxe4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamanla oynamak

Saatin görevi değil ki 

Tik tak

Tik tak

Başka çaresi yok belli

Zamanı tut 

Yada bırak

Tut bırak iyisi mi

Gün batımında

Kumsalda

Güneşi yıkarsın

Sabah tekrar kirlenir 

Ve  bıkarsın

Umutların tükenişine

Saate bakar gibi bakarsın

Tik tak 

Tik tak

Ölüm peşimi bırak', 'Zamanla oynamak Saatin görevi değil ki  Tik tak Tik tak Başka çaresi yok belli Zamanı tut  Yada bırak Tut bırak iyisi mi Gün batımında Kumsa...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/akrep-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Gölü Olsa da', 'kan-golu-olsa-da-fatih-kagan-yucel-wllwt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakışında yaşar ölümü tadan

Son nefesi bilir gözlerim seni

Eline aldığın bir cam aynadan

Bırakıncaya dek izlerim seni

Ayırdım yolumu vuslatın ile

Yuvanı gölgeme kursan nafile

Senden bin kat fazla sen olsam bile

Görmemişçesine özlerim seni

Yaratılmamış say kendini unut 

Varlığı bileyip sırata denk tut

Kuru sırra malik bu kalp bu vücut

Kan gölü olsa da gizlerim seni

Şah olup sesimi tutuklatsan da

Adını ağzıma yasaklatsan da

Cennetten bir konu açtığın anda

Dilinle anlatır sözlerim seni

7 Mart 2004', 'Bakışında yaşar ölümü tadan Son nefesi bilir gözlerim seni Eline aldığın bir cam aynadan Bırakıncaya dek izlerim seni Ayırdım yolumu vuslatı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kağan Yücel']::text[], 8.5, '{"poet":"Fatih Kağan Yücel","poet_slug":"fatih-kagan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kan-golu-olsa-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durma Gönül', 'durma-gonul-abdil-yildirim-r41ws', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Madem bekâ istiyorsun,

Fenâya yüz verme gönül.

İşte geldin gidiyorsun,

Hiç bir gönlü kırma gönül

Hayat kısa bir seyeran,

Bâki hayal kurma gönül.

Ne tez geçti bunca zaman,

Sorma gönül, sorma gönül.

Yollar çetin, geçitler dar,

Sırtına yük vurma gönül.

Arkamızdan gelenler var,

Yol üstünde durma gönül.

Fırsatlar elinde iken,

Nedamet et durma gönül.

Henüz bu can tende iken,

Fırsatı kaçırma gönül.', 'Madem bekâ istiyorsun, Fenâya yüz verme gönül. İşte geldin gidiyorsun, Hiç bir gönlü kırma gönül Hayat kısa bir seyeran, Bâki hayal kurma gö...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/durma-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm Sesine', 'olurum-sesine-sevinc-basbug-tyklr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölürüm sesine 

Ben bu

Motorlu kayıkların

Ve kayıkların 

Sırtına vuran 

Bu dalgaların...

Ölürüm kokusuna 

Ben bu sabah

Serinliğinin

Ve hışırtısına 

Bu yapraklı rüzgarın...

Sanki pembe bir 

Bulutta uyur gibi

Kayarken

Kaldırımlarında

Ben bu yeşil diyarın

Ölürüm telvesinde 

Lezzetinin

Fincanı ters

Fala yatmış

Türk kahvesine...

Gözlerimi dolduran

Dağlarına,

Bağrımı dağlıyan

Fransızca şarkılarından

Tellinden dumanlar

Çıkan 

Sazlarına

Benim utangaç

Aşık

Türkü dilli

Çocuklarıma

Ölürüm ben...

Ve yine uyanırım

Sabahında

Bir Aspendos türküsü

Gibi

Esen

Bahar yelinde,

Bir ceviz ağacı 

Gölgesi gibi

Portakal kokusuna...', 'Ölürüm sesine  Ben bu Motorlu kayıkların Ve kayıkların  Sırtına vuran  Bu dalgaların... Ölürüm kokusuna  Ben bu sabah Serinliğinin Ve hışırt...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Başbuğ']::text[], 8.5, '{"poet":"Sevinç Başbuğ","poet_slug":"sevinc-basbug","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/olurum-sesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedi Yar', 'gelmedi-yar-sadik-softa-mp8kx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel-gitlerde erimişiz sen ve ben; 

Kaf Dağı''nın iki yüzünde, iki ayrı diyar.

Ben diyorum: ''-Yar bekliyor, durmadan.''

Sen diyorsun: ''-Gelmedi! ... Bugün de yar.''

Çankırı-12.04.2004', 'Gel-gitlerde erimişiz sen ve ben;  Kaf Dağı''nın iki yüzünde, iki ayrı diyar. Ben diyorum: ''-Yar bekliyor, durmadan.'' Sen diyorsun: ''-Gelmedi...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gelmedi-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gelince', 'bahar-gelince-abdil-yildirim-b9l0v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlkbahar gelince çıksan bağlara,

Bülbül sesi gelir, su sesi gelir.

Tefekkür gözüyle baksan dağlara,

Dinlesen derinden Hû sesi gelir.

Vadileri arındırır sisinden,

Yamaçları dumanından pusundan,

Uyandırmak için kış uykusundan,

Ilık rüzgarların bûsesi gelir.

Kuru dallar çiçek açar canlanır,

Boz yamaçlar yeşillenir allanır,

Sanki cennetten bir çiçek yollanır,

Mor menekşelerin kokusu gelir.

Her yıl haşrin bir misâli görülür,

Sur üflenir cenazeler dirilir,

Sanki yeryüzüne mahşer kurulur,

Toprakta canlılar ordusu gelir.', 'İlkbahar gelince çıksan bağlara, Bülbül sesi gelir, su sesi gelir. Tefekkür gözüyle baksan dağlara, Dinlesen derinden Hû sesi gelir. Vadiler...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bahar-gelince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binlerce Şükür', 'binlerce-sukur-umit-kilislioglu-ozger-4k87f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şükürler olsun Tanrım sana binlerce,

Şükürler ki makbul bütün dinlerce,

Şükür ki nefsime hakimim,

Şükür ki öğreniyorum ben kimim.', 'Şükürler olsun Tanrım sana binlerce, Şükürler ki makbul bütün dinlerce, Şükür ki nefsime hakimim, Şükür ki öğreniyorum ben kimim....', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/binlerce-sukur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek Kelebek', 'bebek-kelebek-sevinc-basbug-ybp5k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapa gözlerini

Dedi,

Bebek.

Uyur gibi

Yap,

Uyuduğunu sansınlar

Seni uyutmak 

İçin can atanlar

Dedi,

Bebek.

Bırak sen ağlama

Diye

Bir emzik tıksınlar ağzına

Sen biriktir 

Duyulmayanları

Söylenmeyenleri

Dedi,

Bebek.

Sık yumruklarını

Bekle,

Yüreğinin en masum

Çırpıntısında

Aç gözlerini

Onlar uyuduğunda

Dedi,

Bebek.

Topla ağlarını

Sulardan,

Sal köklerini 

Uçurum eşikli

Kayalıklara

Ver çığlığını 

Yankılara

Dedi,

Bebek.

Derken

Bir vapur çığlığında

Uçup gitti

Bebek

Kelebek

soramadan

''Uçmak

Ne demek? ''...', 'Kapa gözlerini Dedi, Bebek. Uyur gibi Yap, Uyuduğunu sansınlar Seni uyutmak  İçin can atanlar Dedi, Bebek. Bırak sen ağlama Diye Bir emzik t...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Başbuğ']::text[], 8.5, '{"poet":"Sevinç Başbuğ","poet_slug":"sevinc-basbug","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bebek-kelebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-umit-kilislioglu-ozger-gmy9f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen karşına bin bir şekilde çıkarsın.

Bazen  sever, en çok da kızar, bıkarsın.

Onları başkası sandığın için

Rahat edemezsin ezmeden, vurmadan

Hiç merhametin yoktur, hırpalarsın durmadan

Sonra da düşünürsün kara kara

Ve yorgunluğunla yıpranmışlığını anlatır durursun

Dağlara taşlara.', 'Sen karşına bin bir şekilde çıkarsın. Bazen  sever, en çok da kızar, bıkarsın. Onları başkası sandığın için Rahat edemezsin ezmeden, vurmada...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanilgi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme', 'gelme-umit-kilislioglu-ozger-n4wei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılık sakın gelme! 

Bize yakın gelme! 

Gönül bağı incelme! 

Yıkmasın bizi

Ne tekme, ne çelme.', 'Ayrılık sakın gelme!  Bize yakın gelme!  Gönül bağı incelme!  Yıkmasın bizi Ne tekme, ne çelme....', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gelme-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelişme', 'gelisme-umit-kilislioglu-ozger-7zk4i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce üşüdü, dondu,

Çürük dallara kondu; 

Ne başlangıç, ne sondu.

Yön önce yanlış yöndü,

Bir yandıysa, bir söndü; 

Sonunda Hak''ka döndü.

(Kapılar kitabından)', 'Önce üşüdü, dondu, Çürük dallara kondu;  Ne başlangıç, ne sondu. Yön önce yanlış yöndü, Bir yandıysa, bir söndü;  Sonunda Hak''ka döndü. (Kap...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gelisme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-umit-kilislioglu-ozger-a611l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaçış bir aldanıştır,

Kendini özünle tanıştır.

Boşuna gitme uzak diyarlara,

Hakikati kendinde ara.

Bu iş başka bir iştir

İstersen otuz iş değiştir,

Aynı sorunları yaşarsın

Hatanı düzelttiğinde onları aşarsın.

Yedi kez evlensen de,

Aynı  soluğu hissedersin hep ensende.

Aynı öğretmendir o, değişik kılıklarla; 

Hep sana gereken karşılıklarla.

Dersini almadıkça sen,

Mutluluğun tadı  kalır hep damağında; 

Yüz yaşına da gelsen,

Sayıklarsın merdivenin aynı basamağında.

Bir yere varamazsın ev, mahalle, şehir değiştirerek,

Değişikliği içeride yapmak gerek.

(Kapılar kitabından)', 'Kaçış bir aldanıştır, Kendini özünle tanıştır. Boşuna gitme uzak diyarlara, Hakikati kendinde ara. Bu iş başka bir iştir İstersen otuz iş de...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kacis-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye', 'nereye-umit-kilislioglu-ozger-gwzek', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nereye koşuyorsun böyle? Ne bu acele? 

Olacağı öne alabilir misin? 

Çare bulabilir misin ecele? 

Fazladan bir dakika çalabilir misin? 

Birer ömür biçmiş Rabbim her fâniye

Ölümü geciktirebilir misin bir  tek saniye? 

Hamd edip çalışmak senin işin; 

Telâş içinde koşmak değil oradan oraya.

Güvenle, imanla olmalı gidişin,

Merhem olmalısın bir yaraya.

Neden sıkılı yumrukların? 

Öfkedense, bağışla / kendine bir iyilik yap.

Cimrilikse nedeni, / paylaşmayı dene bir de

Ne yapacaksın parayı kabirde? 

Fazlasını ihtiyacı olana uzat,

Bu mutluluğu sen de tat.

Veda et artık hüzüne

Avuçlarını kaldır gökyüzüne,

Bereketin yağmasına izin ver; 

Allah cömert kulları sever.

(Kapılar kitabından)', 'Nereye koşuyorsun böyle? Ne bu acele?  Olacağı öne alabilir misin?  Çare bulabilir misin ecele?  Fazladan bir dakika çalabilir misin?  Birer...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nereye-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Aşk Mısraları', 'son-ask-misralari-ayhan-fera-541xg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah

Ekmek attığım güvercinler de 

Terk etti bir sabah

Boş bir maviliğin

Yalancı griliğinde

Ve bedensiz vücudun

Sallanırken musalla taşında

Az ötede

Bahçe dibine gömülür

Senden bana kalan

Son aşk mısraları

Ve ellerin dokundukça yüzüme

Gözlerim isyankar davranır

Ölümü gündüz vakti

Geceye hediye eder gibi

Kimbilir bekli

Namludaki kurşundu

Kara toprağa kendini bırakan

Bilinmez belki de

Sözlerindi zehir olup

Kendini dağların 

isyankar yanına çarpan', 'Her sabah Ekmek attığım güvercinler de  Terk etti bir sabah Boş bir maviliğin Yalancı griliğinde Ve bedensiz vücudun Sallanırken musalla taş...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Fera']::text[], 8.5, '{"poet":"Ayhan Fera","poet_slug":"ayhan-fera","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/son-ask-misralari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Gün', 'yalanci-gun-ayhan-fera-v7is6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzün meydan okumasın ayaza

Ve geçerken

İstanbul''un kirli sokaklarından

Küçük bir çocuk

Gözyaşlarında ıslanır

Elinde dünden kalma

Bir şarap

Duvar dibinde

Sessizce oynar

Yalancı gün ışığı

Ve tenin hasretliğinde

Buluşur

Bir ömür

Islandıkça biter

Alevlenmiş bu kar', 'Yüzün meydan okumasın ayaza Ve geçerken İstanbul''un kirli sokaklarından Küçük bir çocuk Gözyaşlarında ıslanır Elinde dünden kalma Bir şarap ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Fera']::text[], 8.5, '{"poet":"Ayhan Fera","poet_slug":"ayhan-fera","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalanci-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boştu Sınıf', 'bostu-sinif-sevinc-basbug-mj6se', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boştu sınıf

Sıralar boş

Perdeler boş

Tahtada günden kalma

Karalamalar

Yerde sürünen tebeşirler...

Boştu sınıf

Sıralar boş

Ve dağınıktılar

Kimi sağa

Kimi sola yatmış

Ve kazılmıştı

Kalpler,

İsimler...

Ortasında idim

Duvarların

Kirli

Ayak izi dolu 

Duvarların...

Nefes almışlık

Kokuyordu

İçerisi

Tebessüm ederken

Arka boş sıralardan

Bir karşılık kondu 

Dudağımın 

Gevşemişliğine...

Ona benziyordu

Tıpkı,

Çantasını topluyordu

Geç kalmış

Törene

Tedirgindi sanki

İki yana 

Örgülüydü

Saçları,

Hayal meyal

Koşarak çıktı sınıftan

Tek sapı kopuk

Okul çantasının

Omzunu kesen acısıyla...

Yine boştu 

Sınıf..sessiz..

Ve seslendi 

Bir ses

ardımdan:

''Hocam 

Gelmiyor musunuz? ''

Çınladı içimde

Bu sıfat, bu zamir

Doğru ya,

Çantamı değiştirmiştim

Saçlarımı ise

Kestirmiş...

Ve yine geç kalmış

Törene

Telaşlanmıştım...

Ben çıkarken

Kalabalıktı sınıf

İrem

Gözde

Baran vardı

Doğum günümdü

Annem evde

Beni bekliyordu.

Gülüyordum

Üzerimde

Beyaz önlük

Topuklu ayakkabılarım

''Hakkıdır hakka tapan

Milletimin istiklal''

Dedirtildi kalabalık

Ve rahat dedi

Beden öğretmeni,

Mahmut

Ve Seli akıverdi coşmuşluğun

Cebimde

Kendi Çocukluğum...', 'Boştu sınıf Sıralar boş Perdeler boş Tahtada günden kalma Karalamalar Yerde sürünen tebeşirler... Boştu sınıf Sıralar boş Ve dağınıktılar Ki...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Başbuğ']::text[], 8.5, '{"poet":"Sevinç Başbuğ","poet_slug":"sevinc-basbug","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/bostu-sinif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim Yaşamak', 'sevdigim-yasamak-huseyin-cayikli-gitwa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaşamak

yaşatabilmek

yaşlanabilmek

ölebilmek', 'yaşamak yaşatabilmek yaşlanabilmek ölebilmek...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevdigim-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evimi Özledim', 'evimi-ozledim-umit-kilislioglu-ozger-965ci', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Antalya''dayım

Bir otel odasında.

Dışarıda müzik sesleri....

Gençler dansediyor

İçlerinde bütün hevesleri.

Hem onlara uyamıyorum,

Hem denizi duyamıyorum.

On ikiden sonra

Nasılsa ses kesilir,

Dalgaların şarkısı yine gelir.

Kalkıp aynaya bakıyorum bir hışım,

Amma kilo almışım! 

Özledim evimi, balkonumu.

Musluğumdan akan kireçli suyu,

Huysuz komşuyu.

Kasaba, manava uğramayı

Ve soğan doğramayı.

Fakültedeki odamı,

Kantindeki yaşlı adamı.

Bakmadan dinine, milliyetine

Her küçük çocuğa sarılır oldum

Torunum niyetine.

Evidir derler ya insanın sarayı,

Ben de işte, özledim Ankara’yı

Antalya’nın deniz kokan rüzgârı 

Ne kadar güzel esersen es,

Ben bülbül olurum ancak,

Sen altın kafes.

Dinlendiğim yeter, fazlası zarar

Evimi özledim

Zaten tatil dediğin

Bu işe yarar.', 'Antalya''dayım Bir otel odasında. Dışarıda müzik sesleri.... Gençler dansediyor İçlerinde bütün hevesleri. Hem onlara uyamıyorum, Hem denizi ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/evimi-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dal Kırılmasın', 'dal-kirilmasin-oguzkan-bolukbasi-k3uu0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana rastladığımda

Bana kar yağıyordu

Sen tomurcuklanıyordun henüz

Neye hükmümüz geçer ki

Yağmur yağar

Gün doğar

Aşk gelir konar bir dalına 

Yağmur durur

Gece olur

Kuş uçar gider

Bir anı

Bir acı kalır

Eh

En güzeli bu

Dal kırılmasın yeter ki', 'Sana rastladığımda Bana kar yağıyordu Sen tomurcuklanıyordun henüz Neye hükmümüz geçer ki Yağmur yağar Gün doğar Aşk gelir konar bir dalına ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dal-kirilmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma Böyle Güldüğüme', 'bakma-boyle-guldugume-bekir-mutlu-gokcesu-rgqsv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakma

Buralarda dolandığıma

Aldanma cismime

Kaç baharla

Alıp başımı gittim ben

Kaç aşkla eridim, bittim

Kaç çaresizliğime yandım

Bakma böyle güldüğüme

Akan yaşları sor gözlerime

Birde şiirlerle, yüreğime

Kaç yıldız kayışıdır kim bilir? 

Sayısız yitişim

Ve kaç halidir? 

Üstüme titreyen gözlerinin

Defalarca dirilişim...', 'Bakma Buralarda dolandığıma Aldanma cismime Kaç baharla Alıp başımı gittim ben Kaç aşkla eridim, bittim Kaç çaresizliğime yandım Bakma böyle...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bakma-boyle-guldugume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam Zamanı', 'tam-zamani-yagmur-damlasi-g1eq9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deniz kızı

Benim hiç martım olmadı

Oysa deniz çocuğuyum

Yakamoz hasreti ile doluyum 

Hep bozkırlarda at koşturdum

Çile üstüne çile

Gelişin sebebi 

Gidişin neticesine

Bağlı………………

Artık zamanı

Birileri durdurmalı

Bu senfoni çok uzadı

Bizim değil bu beste

Bu yalnızlık şarkısı

Aldığımız her nefeste

Hissettiğimiz acı

Boğulacaksam da razıyım

Bu gece

İnan hazırım

Koynuna girmeye

Ölüm hep ansızın gelmez ya', 'Deniz kızı Benim hiç martım olmadı Oysa deniz çocuğuyum Yakamoz hasreti ile doluyum  Hep bozkırlarda at koşturdum Çile üstüne çile Gelişin s...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tam-zamani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum..', 'i-stiyorum-kubilay-i-nciler-blnl9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi ne isterdim biliyormusun? 

       O sahilde saçlarındaki rüzgar olmak,

       kumsalda otururken tenini koklamak,

       eve hiç gitmemek seninle uyumak.

       Şimdi ne isterdim biliyormusun? 

       O tahta masaya adımızı kazıyor olmak,

       seni beklerken ki o heyecanda olmak,

       bir öpücüğü hiç birşeye değişilmez kılmak.

       Şimdi ne isterdim biliyormusun? 

       O havayı senle içe çekmek,

       o şarkıyı kulağına fısıldamak,

       o histe o sevinçte kalmak.

     

      Şimdi ne isterdim biliyormusun? 

      Sana,ilk günkü bakışta kalmak,

      kırıksız duygularda olmak,

      her seferinde sana kanmamak..', 'Şimdi ne isterdim biliyormusun?         O sahilde saçlarındaki rüzgar olmak,        kumsalda otururken tenini koklamak,        eve hiç gitme...', ARRAY['Türk Edebiyatı','Şiir','Kubilay İnciler']::text[], 8.5, '{"poet":"Kubilay İnciler","poet_slug":"kubilay-i-nciler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istiyorum-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyileşir mi?', 'i-yilesir-mi-bekir-mutlu-gokcesu-1vlcu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklımda sözcükler

Yapayalnız üşürler

Konu olmak isterler

İçleri titrer bir şiire

Laf anlatamam 

Biçarelere

Şiir kim, ben kimim

Can kuşum

Can çekişirken

Gecenin bu saatinde...

Biz onu çok seviyorduk

Ne olur yardım et

Allah’ım

Yine uçsun...

07/03/04  Gecenin Bir Vakti

Uğur Gitti, Muhabbet Bitti

Ve can kuş

Gitti bu gece

Öyle didindi ki

Yaşamak için

Ve o kadar

Çabaladım ki

Onu yaşatmak için

Olmadı

Mavi beyazdı

Umuttu

Uğur koymuştuk adını

Öyle iyiydi ki

Olmadı işte

Gitti

Çok ağlıyorum...

12/03/2004 Şimdi', 'Aklımda sözcükler Yapayalnız üşürler Konu olmak isterler İçleri titrer bir şiire Laf anlatamam  Biçarelere Şiir kim, ben kimim Can kuşum Can...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/iyilesir-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Bir Çizgi Kabuğunda', 'i-nce-bir-cizgi-kabugunda-cumhur-boratav-a0quq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'önce bıçak, 

sonra ince bir çizgi kabuğunun aralarına..

soyulmaya hazırsın, 

parmakların içine sokulmasına.

derin bir soluk aldın

hoşlanma ve tedirginlik..

(sıkılıyorsun, zaman geç, 

 bir ses, zaman dişlerinde ölüyor

 biraz kırık) 

zaman öldü, bir sessizlik..', 'önce bıçak,  sonra ince bir çizgi kabuğunun aralarına.. soyulmaya hazırsın,  parmakların içine sokulmasına. derin bir soluk aldın hoşlanma v...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ince-bir-cizgi-kabugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyim...', 'herseyim-i-brahim-ethem-bingul-9dfyu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahın eri

Analığa koşan kadının temiz teri

Bir çiçeğin narin busesi

Fısıldanan sözcüklerin titrekliği gibi

Sevgimin her rengine

Bin tual olan gönlünde

Buldum kendimi

Mutluluğun sesi her şeyim

İyi ki sensin', 'Sabahın eri Analığa koşan kadının temiz teri Bir çiçeğin narin busesi Fısıldanan sözcüklerin titrekliği gibi Sevgimin her rengine Bin tual o...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/herseyim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşe Ağacı', 'mese-agaci-umit-kilislioglu-ozger-pbjxk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayret! Ben miyim böylesine neşeyle rakseden? 

Benim hayalim mi bu, durgun sulara akseden? 

Sanki kırk yıl öncesinden gelmiş gibi,

Bedenim de ruhum da incelmiş gibi.

Başbaşa vermiş bir kaç nilüfer,

Sevginin, mutluluğun, huzurun zafer.

Dağ,söylediğim şarkıya kır çiçeklerinin kokusunu katıp

Ve onlardan bir senfoni yaratıp

Gönderiyor hızla geri

Burası dostluğun, paylaşmanın yeri.

Yorulunca altına atıyorum kendimi bir meşe ağacının,

Alınıp götürüldüğünü hissediyorum her acının.

Meşeden bana bir yaprak geliyor salına, salına

Sessizce düşüyor bu ateşli alına.

Biraz sonra bir tane daha, serin mi serin

Şiirler yazıp yazıp gönderiyor sanki

İlhamını paylaşıyor o anki

Yüceliğini haykırıyor bu ilahi eserin.

Ona bakıp gülümsüyorum ellerim toprakta,

Cevap yine bir yaprakta:

“yok sen, ben; 

İyice dinlen.

Yanında dostların var seni seven.

Bize güven”.', 'Hayret! Ben miyim böylesine neşeyle rakseden?  Benim hayalim mi bu, durgun sulara akseden?  Sanki kırk yıl öncesinden gelmiş gibi, Bedenim d...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mese-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Vakti', 'seher-vakti-umit-kilislioglu-ozger-czhrh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seher vakti bu selâm kimden? 

Ağlamak geliyor içimden.

Bu güzellik, bu ihtişam zorluyor usu,

Çiğ taneleri taşıyorum eve, kucak dolusu.

Bir kuşun kanadında yüreğim.

İçinde tüm ümidim, ereğim.

Kuşum, sen hemen yüksel! 

Yarın gün doğarken yine gel,

Yüreğimi de götür, sakın bırakma! 

Onsuz da olunur buralarda, bana bakma.

Çiğ tanelerim! Buhar olun uçun

Olmadığı yerlere kötülüğün, suçun.

Şafakta görüşürüz yine

Katılırız o muhteşem ayine.', 'Seher vakti bu selâm kimden?  Ağlamak geliyor içimden. Bu güzellik, bu ihtişam zorluyor usu, Çiğ taneleri taşıyorum eve, kucak dolusu. Bir k...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seher-vakti-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuma', 'kuma-umit-kilislioglu-ozger-bq7vw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeniden evlendiriyorlardı sümbül saçlı, kara gözlü Celâl’ini

On iki yıllık kocası, canı, helâlini.

“Üzülme Hatice’m, çocuk için “ demişti

“Köy yeri işte bilirsin,

ama üç kez de evlensem daima en önde sen gelirsin.

Hiç acımam döverim, ihtiyaç olursa iyi bir derse

Hele hele sana saygısızlık ederse! ”.

Ertesi gün düğün vardı

''Allahım canımı al! '' diye yalvardı.

Kocası onunla o gece çok az konuşmuştu

Belli ki suçluluk duyuyordu

Şimdi de mışıl, mışıl uyuyordu.

Hatice, sessizce tavanarasına çıktı,

Sandığının kilidi açıktı.

Gelinliğini bohçasından özenle çıkardı,

Şöyle bir önüne tuttu,

Bir an için acısını unuttu.

Kabarık etekleri vardı yerlere kadar uzun,

Kendini bir süre seyretti, arkasından aynadaki tozun.

Geçen yılları, mutlu günleri saydı,

O evde bir an bile durmazdı ana-babası sağ olsaydı.

Yere göğe sığamadı, dünyası yıkıldı; 

Odasına gidip yüzlerce rekât namaz kıldı,

Sonra Celal’inin üstünü örttü.

Vakit sabaha karşı dörttü.

Sonunda ne yazık o gece...

Canına kıydı güzelim Hatice.', 'Yeniden evlendiriyorlardı sümbül saçlı, kara gözlü Celâl’ini On iki yıllık kocası, canı, helâlini. “Üzülme Hatice’m, çocuk için “ demişti “K...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Kadın (Eğlencelik)', 'i-yi-kadin-eglencelik-umit-kilislioglu-ozger-peyu5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bitirince evin işlerini,

Alır eline şişlerini.

Kaçırmaz komşuların

Geliş gidişlerini.

Gezme koymamışsa usuna,

Yatar öğle uykusuna

Akşama doğru uyanır,

Bir güzel boyanır.

Gelmeden koca,

Allıklar, farlar 

Edilir boca.

Güzel bir karşılama töreni

Kıskandıracak cinsten göreni.

Yemekten sonra salona geçilir,

Kahveler içilir.

“İstersen güzelim,

Çıkıp biraz gezelim”

Hemen gözleri parlar,

Ortalığı bir çırpıda 

Toparlar.

Dönüşte ayakkabılar,

Sağa, sola fırlatılır,

Alelacele yatılır.

Uyanır uyanmaz alır eline fırçayı,

Taranır, süslenir

Sonra da demler çayı.

Taze ekmek alınır

Bizimki salınır,

Radyo  da nedense hep

Avaz, avaz çalınır.

Kapı aralığında yanağa 

Kondurulur küçücük,

Sıcacık bir öpücük.

Allah bazı erkeğe 

Böyle iyi eş yazar,

Aman değmesin nazar.', 'Bitirince evin işlerini, Alır eline şişlerini. Kaçırmaz komşuların Geliş gidişlerini. Gezme koymamışsa usuna, Yatar öğle uykusuna Akşama doğ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/iyi-kadin-eglencelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kukla', 'kukla-umit-kilislioglu-ozger-pvu26', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O adam değil senin muhatabın

Gerçek sahibi değil elindeki kitabın

İşi yok onun hedefle, ufukla,

O bir kukla.

Bilmez o yokuşu, inişi, sarpı, diki,

O hayatında hiç bir şey üretmedi ki! 

İki koyunu güdemez, değil şu koca kervanı; 

O bir kurnazın paravanı.

Koyunu bırak,  başa çıkamaz tavukla; 

Dedim ya, o bir kukla.

Çok olmuş dört işlemi unutalı

O hainin aptalı.

Neyin altına imza attığını bilmez çoğunlukla,

Farketmez onun için dünya da kurtulsa

Kan da aksa olukla.

İnsan değil ki o,

Sadece bir kukla.', 'O adam değil senin muhatabın Gerçek sahibi değil elindeki kitabın İşi yok onun hedefle, ufukla, O bir kukla. Bilmez o yokuşu, inişi, sarpı, ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kukla-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evde Yokum', 'evde-yokum-umit-kilislioglu-ozger-3df8i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzun uzun çalsın saat

Kim kurduysa...

Kapı zili, telefon, ne varsa...

.

Seslenmesin komşular

Ekmek de istemiyorum, tokum

Ben bugün evde yokum.', 'Uzun uzun çalsın saat Kim kurduysa... Kapı zili, telefon, ne varsa... . Seslenmesin komşular Ekmek de istemiyorum, tokum Ben bugün evde yoku...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/evde-yokum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ha Gayret', 'ha-gayret-umit-kilislioglu-ozger-4ffi6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen kinim galip geliyor,

Bazen dinim.

Peşine takılmışken süslü bir sözün,

Kendime getiriyor, büyüsü özün.

Karamsarlığın ortasındayken birden,

İçimi sevinç kaplıyor, hayret! 

Olacak, olacak

Ha gayret! 

(25.Kasım.2001)', 'Bazen kinim galip geliyor, Bazen dinim. Peşine takılmışken süslü bir sözün, Kendime getiriyor, büyüsü özün. Karamsarlığın ortasındayken bird...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ha-gayret-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâtibe', 'k-tibe-umit-kilislioglu-ozger-hz0jn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''YAZ KIZIM! '' dedi hâkim.

Parmakları uçuştu

kelebekler misali.

Üç beş de hata yaptı, dert etmedi kendine

Anlaşılırdı nasılsa

''....KANUNUNUN.....NCU BENDİNE...''

Aklı başka yerdeydi.         

                        (Akşama yemeğe misafir gelecekti

                         Kocasının ailesinden on beş kişi

                         Zordu işi.) 

''....GÖZ ÖNÜNDE TUTULARAK...

                        (Geceden yapmıştı yemekleri; tavuktu, börekti.

                         Keşke tülleri de yıkasaydım diye düşündü

                         Ne de olsa gelindi, ağızlara lâf gerekti.

                         İşi zordu...) 

Tam o sırada hâkim sanığa sordu: '' EKLEYECEĞİN BİR ŞEY VAR MI? ''

''Yok'' dedi sanık melûl, mahzun,

Özgürlüğüydü elinden giden

ve aniden

en masum pozunu takındı

                         (Evlenme yıldönümleri de yakındı

                          Yüzük, küpeden vaz geçmişti de

                          Bulaşık makinası istiyordu.) 

''YAZ KIZIM! '' dedi hâkim. yine

.......'' ON YEDİ YIL AĞIR HAPSİNE...

Sanığın gözü karardı,

Maktulün ablası arkalardan bir Oh! çekti; 

Hırsla mantosunu giydi,

Yetmezdi ama yine hiç yoktan iyiydi.

''Ve...LİRA AĞIR PARA CEZASINA ÇARPTIRILMASINA

TEMYİZ YOLU AÇIK OLMAK ÜZERE

                         (Yeni aldığı yolluğu sermeliydi akşama yere) 

KARAR VERİLDİ.''

...

Jandarmalar sanığın kolunu, abla mezarlığın yolunu tuttu.

Bir sonraki duruşmaya geçildi

Onun için önemli değildi suç ne, suçlu kim.

Yeniden ''YAZ KIZIM! '' diye seslendi hâkim.

(30.Ocak.2001)', '''YAZ KIZIM! '' dedi hâkim. Parmakları uçuştu kelebekler misali. Üç beş de hata yaptı, dert etmedi kendine Anlaşılırdı nasılsa ''....KANUNUNUN....', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/katibe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtilal', 'i-htilal-canan-ucer-fran8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece 

Hüzzam kırıyor

Udun nağmelerini.

Her telimde topal bir kısrak koşuyor........

Alaza düştü tenim

Unutulmuşluğunda

Geceye kan düştü sevdiceğim..

Ki gelişinle kıvrak bir hava esmeyecek

Kısraklar coşmayacak yeniden dirilip

Uzak dur artık tenimden

Hüzzam şarkı güzel durmayacak

Solgun göğsümde...

Zaman yitirir

Bıçak sırtı dokunuşlarını....

Kendi soluğumun buğusuyla

Düşlerime uyurum..

Ve her ihtilal de daha mutluyum.

..................', 'Bu gece  Hüzzam kırıyor Udun nağmelerini. Her telimde topal bir kısrak koşuyor........ Alaza düştü tenim Unutulmuşluğunda Geceye kan düştü s...', ARRAY['Türk Edebiyatı','Şiir','Canan Üçer']::text[], 8.5, '{"poet":"Canan Üçer","poet_slug":"canan-ucer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ihtilal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmam Deme', 'unutmam-deme-yagmur-damlasi-oppem', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen de git haydi

Ve bitsin gece

Zulme kucak açsın gün yine

Duymayayım sesini

Unutacaksın biliyorum

Adım bile kalmayacak aklında

Öyle olsun susuyorum

İnanmıyorum artık aşka

Sigaranı unutma

Beni özlemesen de

Onu mutlaka

Özlersin işte

Ve dönüşün olmayacak

Bu gidişle

Bende anıların kalacak

Resimlerin bir de

Bir de

Yaşanmamış günlerin

Gecelerin özlemlerin

Unutursun

Başın yastığa düşünce

biliyorsun

sen unutmam desen de', 'Sen de git haydi Ve bitsin gece Zulme kucak açsın gün yine Duymayayım sesini Unutacaksın biliyorum Adım bile kalmayacak aklında Öyle olsun s...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unutmam-deme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykunda Hapsim', 'uykunda-hapsim-yagmur-damlasi-rfptl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahın henüz ilk ışıkları

Güneş yeni yeni doğmakta

Seni az önce uyuttum

Penceremin önüne yalnızlığımı

Ve kurumuş ekmekleri 

Göz yaşımla

Islatıp ıslatıp koydum

Sürüyle güvercin  kanat çırpmakta

Ellerimden ekmek yiyorlar

Kanatlarında

Yeni sevdaların müjdesi 

Yüreklerinde yarınlar

Siz hiç sevdiniz mi

Sahi………………………….

Sizin de güvercinleriniz var mı..?', 'Sabahın henüz ilk ışıkları Güneş yeni yeni doğmakta Seni az önce uyuttum Penceremin önüne yalnızlığımı Ve kurumuş ekmekleri  Göz yaşımla Isl...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uykunda-hapsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan*', 'vatan-bayram-tunca-9m2ui', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(V) atan, uğrunda ölebilen varsa vatandır

(A) ta vatanı uğrunda ölümü göze alandır

(T) arihe ismini altın harflerle yazdırandır

(A) talarımızın armağanıdır bu vatan bize

(N) eferi olabilmek en güzel şereftir bize

13.02.2004-13.02', '(V) atan, uğrunda ölebilen varsa vatandır (A) ta vatanı uğrunda ölümü göze alandır (T) arihe ismini altın harflerle yazdırandır (A) talarımı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/vatan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şımarık', 'simarik-serhat-kiciklar-5gqdp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölümle bağdaştırdım sevgini, seni yaşarken,

Artık korkmuyorum ölümden,yasaklardan,

Gelip geçsede yıllar,gidecek olan bedenim,

Ruhum hep sende kalacak,seni yaşarken ki gibi

Sevginin korumasında büyüdüm ben.

Sevginin şımartısı ile büyüdüm ben,seni yaşarken,

Çocukken şımaramadığım günlerin acısını çıkarırcasına,

Delikanlı iken hislerimde yaşatılamayan aşkın aksine,

Havalara girdim sevginle ve seninle,

Ben aşkınla arsız oldum,seni yaşarken

Tatmadığım,bilmediğim duyguları gördüm inat edercesine

Esir olduğum,değer görmediğim günler acısına

Sanırım ben aşkınla şımarık olmak istedim,seni yaşarken

       13.03.2004', 'Ölümle bağdaştırdım sevgini, seni yaşarken, Artık korkmuyorum ölümden,yasaklardan, Gelip geçsede yıllar,gidecek olan bedenim, Ruhum hep send...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kıcıklar']::text[], 8.5, '{"poet":"Serhat Kıcıklar","poet_slug":"serhat-kiciklar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/simarik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suzan', 'suzan-serhat-kiciklar-46vhm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tamam,

Tamam Suzan,ismin içimdeki hisleri hareket ettirmesede

Ardındaki kimliğinin,yaşattıklarının içimde uyandırdıklarıyla

Yasaklım,aşkım senin olduğunu biliyorum.

Sen Suzansın ama değilsin.

Seni ben,içim,tenim,yaşadıklarım bir sır gibi tutuyor

Sırmakeş oldun,oldum beraber varolmak için

Ardındaki çilek tarlasındaki kokuna kavuşmak için

Ben Serhatım ama değilim

Şimdilik.....

13,03,2004', 'Tamam, Tamam Suzan,ismin içimdeki hisleri hareket ettirmesede Ardındaki kimliğinin,yaşattıklarının içimde uyandırdıklarıyla Yasaklım,aşkım s...', ARRAY['Türk Edebiyatı','Şiir','Serhat Kıcıklar']::text[], 8.5, '{"poet":"Serhat Kıcıklar","poet_slug":"serhat-kiciklar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/suzan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sofu I', 'sofu-i-mehmet-sukru-kaplan-usc6n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kum kemiren kanatsız kuşlardan kalıt

sırtımdaki toprağı örten ay ışığından çul

yıldızların ışığını ilk gören elma kurduyum

sırasını ben aldım ruhumdaki gölgenin

bu yüzden adım hep lanet annemin dudaklarında

kan pıhtısı zamanın kaygan rahminde

ıslaklığım bilge gecelerin aksanıyla

su kemiren kanatsız kuşlardan kalıt

bin yıllık testiden boynumdaki muska

sırıma vakıf olan karınca bacaklı çocuklar

el basarak çıkar sakalı tülden büstüme

-ah! ..dağların örtük sabrıyla aşılanan gençliğim

hangi dilsiz avgına sözledin kendini

henüz uç vermişken ağzındaki mor uçuk

sözün diş köklerinden yükselip 

                                    gözlerine inen 

                                                 akşam seli  

kendine düşman makas ağzı

nesli tükenmiş başsız çivi

hiçbir krokide gösterilmemiş durak-

kimler yazmadı ki adını zihnimin pastel duvarına

ey kızıl giyitli evlerin dövünen imi

çalıntı sevinçlerden devşirdim 

solaklığımın kireç yüzlü telaşını         

mevsimlerdir kül akan

        -düşlerimi emzirdiğim köy çeşmelerinde-

yakıyor içimi duvar diplerinin yalnızlığı

bir ağıt benimkisi/bir yakarış

terli sayıklamalar içinde

                      köz srgılı aavuçlarını açarak denize

buz kemiren kanatsız kuşlardan kalıt

kozalağını acıyla ören cebimdeki hayat

                                          (aralık 2003-silifke)', 'kum kemiren kanatsız kuşlardan kalıt sırtımdaki toprağı örten ay ışığından çul yıldızların ışığını ilk gören elma kurduyum sırasını ben aldı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Kaplan']::text[], 8.5, '{"poet":"Mehmet Şükrü Kaplan","poet_slug":"mehmet-sukru-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sofu-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sofu II', 'sofu-ii-mehmet-sukru-kaplan-y5zfc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ardımda saf tutar soluksuz kalmış yaban arıları

kutsallığım bedevi akşamların serinliğinden kalıt

hiçbir çiçeği koklamadım ihanet olur diye gençliğime

hiçbir çiçeği koklamadım ihanet olur diye gençliğime

ıslak dudaklı bir alev üstümdeki paltolu ruh*

göz çukurum kan içinde. yılların soğukluğu

yüzümdeki çiğdem yüklü hüzün

ben mi lanetliyim

yoksa kurduğum düşün laneti mi geçmiş bana

alınyazısını alaya alan bir gezginim 

toprak gökyüzüne çivilenir

gölge boyum her uzadığında

-atlarım kırçıl atlarım yelelerinde erken düşen karların izi

boyunca uzanmış hantal düşlerine-

tufan kendi yüreğini satmasıdır insanın

gözyaşını kurutmasıdır kendi yüzünde

ne tufanlar yaşadım göçerken bir kentten diğer kente

okunmuş suydum bir vakitler hamam taşlarını çürüten

çarmıha gerili kadınlar tırmalardı kalçalarını

omuzlarından göbeklerine usulca kayarken

ey sökük kirpiklerimin aleviyle yanan gök- yüzü-

dönüştür gölgeme havlayan köpek sürüsünü taşa

duyumsamak istiyorum karnımdaki çocuğun uykusunu

yaşamın tadı tuzla yoğrulurken ekmek teknesinde

ölüm tek gözlü bir karıncanın kendini gizlemesidir

incir kabuğuna/azık torbasına saplamasıdır kıskaçlarını

ne ölümler yaşadım bir bedenden diğerine göçerken

                              (ocak 2004-silifke)', 'ardımda saf tutar soluksuz kalmış yaban arıları kutsallığım bedevi akşamların serinliğinden kalıt hiçbir çiçeği koklamadım ihanet olur diye ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Kaplan']::text[], 8.5, '{"poet":"Mehmet Şükrü Kaplan","poet_slug":"mehmet-sukru-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sofu-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sofu III', 'sofu-iii-mehmet-sukru-kaplan-4k770', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'doruğunda günaha çağırıyor öğle sıcağı

ter kokuları içine oturarak koltuk altını 

yalayan bir kadının ayrık memeleri

suda şavkıyan kol düğmesi

tenime acılık veren dudak izi

var mı benim gibi dipsiz bir kuyuya 

ruhunu gömen yüz yıllık tortusuyla

yankısı kulaklarımda göğsünü döven

taç yaprakların, kasımpatıların

külünde kıvranan anka kuşunun

bir eski zaman ruhuyum sofu kılığında

dilim yedi başlı yılanların yatağında

ersiz dilencilerin dualarıyla lanetli

soykırım var geçtiğim her şehrin kaderinde

-sağım solum nişangah tahtasında barut-

vurulmadık yerim kalmadı adımı yuutuğumdan beri

ah! ..tenime acılık veren dudak izi

ölü tırnak uçların açtığı yara

başkaldırışı tenimdeki doğurgan hüznün

(ocak 2004-silifke)', 'doruğunda günaha çağırıyor öğle sıcağı ter kokuları içine oturarak koltuk altını  yalayan bir kadının ayrık memeleri suda şavkıyan kol düğme...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şükrü Kaplan']::text[], 8.5, '{"poet":"Mehmet Şükrü Kaplan","poet_slug":"mehmet-sukru-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sofu-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-ensar-cevval-u0jt9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suyun özü çekilmiş solgun damarlarımdan	

taşlar bedenimi yakıyor, ıslak toprağım		

susuz kuyularda bekler Yusufî dudağım	

ümitvarım yolu değiştirilen kervandan.		

Yaşam sayısız gülüş çekmiş yanaklarımdan	

sinsi rüzgarlar girmiş,  mecalsiz bacaklarım	

dilsiz camlarda bekler  züleyha bakışlarım	

umutvarım toprağa duman katmış yollardan.	

03Mart ''03 Üsküdar', 'Suyun özü çekilmiş solgun damarlarımdan	 taşlar bedenimi yakıyor, ıslak toprağım		 susuz kuyularda bekler Yusufî dudağım	 ümitvarım yolu değ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bekleyis-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Bir Şey Daha...(Wajeha''ya)', 'bir-sey-daha-wajeha-ya-naime-erlacin-y0npq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir ton yazıyor

iki ton atıyorum

çöp sepetim 

toplama kampı! 

nehirler geçiyor üzerimden

ilkel bir ezgi duyuluyor 

imbikten su damıtıyorum

aşk gibi 

ruh gibi 

yazma tutkusu gibi bir şey 

güruhu imha etmenin 

bir yolu olmalı

üç ton atmak meselâ 

anlamı yitirmeden

“bir şey daha var” diyor ses

bir şey daha: 

diri yakarışlarda çıldıran dansı 

unutmuş olmalıyım

bana bir 

savaş baltası hemen 

tüyler

nikotin çubuğum

ve sen 

içimdeki Wajeha*

sen! 

(13 Mart 2004)    

(*)        Wajeha Al-Huwaider: Ağustos 2003’den beri aktif olarak yazmaktan ve eserlerini yayımlamaktan MEN EDİLMİŞ Suud’lu bir kadın yazar (El Watan köşe yazarı) .', 'bir ton yazıyor iki ton atıyorum çöp sepetim  toplama kampı!  nehirler geçiyor üzerimden ilkel bir ezgi duyuluyor  imbikten su damıtıyorum a...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-sey-daha-wajeha-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlara', 'dostlara-ozkan-yildirim-ss0bq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostlar; 

Sizleri türküler

      

