INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Söylediğinde', 'sende-soylediginde-c-murat-guzelaydin-s2g5h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karadır gündüzler,gecenin olduğu yerde

Karanlık aydınlıktır seni sevdiğim sürece

Baykuşlar öter gündüz,bülbüller öter gece

Sonbaharda açar güller,solar ilk gecede

Yazın yağar kar,kışlar zaten soğuk kalbimde

Bir söz geçirebilsen o deli gönlüne

Aydınlanır yaşam herşey döner tersine

Sende, evet seviyorum bende dediğinde.', 'Karadır gündüzler,gecenin olduğu yerde Karanlık aydınlıktır seni sevdiğim sürece Baykuşlar öter gündüz,bülbüller öter gece Sonbaharda açar g...', ARRAY['Türk Edebiyatı','Şiir','C Murat Güzelaydın']::text[], 8.5, '{"poet":"C Murat Güzelaydın","poet_slug":"c-murat-guzelaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sende-soylediginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-c-murat-guzelaydin-go7rk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karadır geceler

Karadır.

Sazını el almış aşık

Nicedir.

Çal söyle derdini

Çaldıkca saz

İnletir.

Ozan Söyler

Dinletir.

Nicedir hali

Gören ağlatır.

Bu alem aşkı

Böyle biledir.', 'Karadır geceler Karadır. Sazını el almış aşık Nicedir. Çal söyle derdini Çaldıkca saz İnletir. Ozan Söyler Dinletir. Nicedir hali Gören ağla...', ARRAY['Türk Edebiyatı','Şiir','C Murat Güzelaydın']::text[], 8.5, '{"poet":"C Murat Güzelaydın","poet_slug":"c-murat-guzelaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-221-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heder Oldum', 'heder-oldum-c-murat-guzelaydin-3w5vt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey bu hana uğrayan aşk

Ben seni arar oldum

Hicran dolan yüreğimde

Ben hesap sorar oldum

Gazel oldu güller

Ötmez oldu bülbüler

Gecem yok gündüzüm yok

Kendi kendime sorar oldum.

Bir uçabilsem

Gezerim diyar diyar.

Bir konuşabilsem

Sorarım diyar diyar

Lal olmuş dilim

Kör olmuş gözüm

Kırılmış kanadım

Ben aşkdan heder oldum.', 'Ey bu hana uğrayan aşk Ben seni arar oldum Hicran dolan yüreğimde Ben hesap sorar oldum Gazel oldu güller Ötmez oldu bülbüler Gecem yok günd...', ARRAY['Türk Edebiyatı','Şiir','C Murat Güzelaydın']::text[], 8.5, '{"poet":"C Murat Güzelaydın","poet_slug":"c-murat-guzelaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/heder-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün', 'bir-gun-murat-cimen-2-vy093', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sabah seninle,

Yeniden başlıyorum hayata.

Ve her akşam 

Sensiz ölüyorum...

Bir gün,

Sensiz başlayacağım güne.

Akşamına sende olacaksın, 

Ben beyazlar içinde...

27 Şubat 2004', 'Her sabah seninle, Yeniden başlıyorum hayata. Ve her akşam  Sensiz ölüyorum... Bir gün, Sensiz başlayacağım güne. Akşamına sende olacaksın, ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çimen 2']::text[], 8.5, '{"poet":"Murat Çimen 2","poet_slug":"murat-cimen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-gun-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyim', 'sevgiyim-c-murat-guzelaydin-ded57', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben dost değilim gülüm

Sevgiyim

Bazen acı 

Bazen göz yaşı

Bazen bir gül

Bazen diken

Herşeye katlanırmış seven

Gülme halime

Ağlamada

Seviyorsan söyle

Sevmiyorsan saklamada

Ben oyuncak değilim

Gülüm.

Bazen sevdiğin

Bazen eğlendiğin

Oyuncak olamam.

Ben ya olurum

Ya olurum', 'Ben dost değilim gülüm Sevgiyim Bazen acı  Bazen göz yaşı Bazen bir gül Bazen diken Herşeye katlanırmış seven Gülme halime Ağlamada Seviyors...', ARRAY['Türk Edebiyatı','Şiir','C Murat Güzelaydın']::text[], 8.5, '{"poet":"C Murat Güzelaydın","poet_slug":"c-murat-guzelaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevgiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Bahar', 'i-ki-bahar-c-murat-guzelaydin-yztmd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir nisan ayında başlar aşklar

Toprak gibi nemli ve ılık

Hava gibi bir kapalı bir açık

Gün gibi bir aydınlık bir karanlık

O ne gündür ki hep ılık

açık ve aydınlık.

Bir sonbaharda  biter aşklar

Toprak gibi ıslak ve soğuk

Hava gibi hep kapalı

Gün gibi hep karanlık

O ne gündür ki hep ıslak

soğuk ve karanlık.', 'Bir nisan ayında başlar aşklar Toprak gibi nemli ve ılık Hava gibi bir kapalı bir açık Gün gibi bir aydınlık bir karanlık O ne gündür ki hep...', ARRAY['Türk Edebiyatı','Şiir','C Murat Güzelaydın']::text[], 8.5, '{"poet":"C Murat Güzelaydın","poet_slug":"c-murat-guzelaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-c-murat-guzelaydin-rhv3z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dost gibidir insana şiir

Kafiyelidir hayatı

Bazen anlamsız gelir

Bazen ağlatır insanları

Anlatır kalbindeki sırları

Aşk gibidir  insana şiir

Anlatır duygularını

İçindeki anlamsız fırtınaları

Bazıları güler 

Bazıları işte hayatım der.

Serap gibidir insana şiir

Kalbindeki o çölde bulur

Kimi zaman mutlu huzurlu

Kimi zaman kederli üzgün

Çöl göz yaşlarıyla serap olur.

Labirent gibidir insana şiir

Bazen içine girer kaybolur

Bazen kaybettiği duyguları bulur

Bazen arar arar durur

Okudukça içi huzur bulur.

Bir papatya gibidir insana şiir

Her kopardığında içi kıpır kıpır olur

Bazen seviyor çıkar mutlu olur

Bazen beklentileri kaybolur

Yılmaz insan yeni papatya bulur

Bir ana gibidir insana şiir

Sımsıcak sarar kollarıyla

Basar ayırt etmeden bağrına

Bazen insan iyi bazen kötü olsada

Sevgi aşılar duygu aşılar insana.', 'Dost gibidir insana şiir Kafiyelidir hayatı Bazen anlamsız gelir Bazen ağlatır insanları Anlatır kalbindeki sırları Aşk gibidir  insana şiir...', ARRAY['Türk Edebiyatı','Şiir','C Murat Güzelaydın']::text[], 8.5, '{"poet":"C Murat Güzelaydın","poet_slug":"c-murat-guzelaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/siir-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut', 'unut-c-murat-guzelaydin-k9xka', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görmeyeli unutmuşum yüzünü,

Duymayayı unutmuşum sesini,

Hissettim ya yeniden nefesini,

Canlandırdı küllenen mazimizi.

İçimde bir burukluk,kalbimde sızı,

Oldu ya yalan değil.

Ama O eski deli gönül bende değil.

Evlenmişsin,iki tatlı çocuk,

Unutmuşsun belli beni çabuk.

Kader der ya insan hemen,

Doğrudur belki,

Ya bizim, onların hiç mi suçu yok.

Kalbimize gömdük, gözlerimizi kapattık,

Bir beraberliği hep beraber noktaladık.

Sen unuttun belki sevgiyi

Unut bence de, mutlu ol

Ne bir çiçek, nede sevgimiz gibi sol.

Bahtında olsun hep açık bir yol

Sarıl sevgine çocuğunla çocuk ol.

Beni boş ver,anlatılanları unut.

Nasıl ayyaş ve berduş olduğumu

Senden sonra bulamadığım mutluluğu

Sokakları,parkları,yatağım o bankları

Hatırlama unut.', 'Görmeyeli unutmuşum yüzünü, Duymayayı unutmuşum sesini, Hissettim ya yeniden nefesini, Canlandırdı küllenen mazimizi. İçimde bir burukluk,ka...', ARRAY['Türk Edebiyatı','Şiir','C Murat Güzelaydın']::text[], 8.5, '{"poet":"C Murat Güzelaydın","poet_slug":"c-murat-guzelaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unut-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece, Gündüz ve Sevgi', 'gece-gunduz-ve-sevgi-ozan-ozel-tva42', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine sabah oldu 

Karanlıktan aydınlığa kavuştum 

Mahmur mahmur çevreme bakınıyorum 

Oğlum mışıl mışıl uyuyor 

Eşim mutfakta tıkırdıyor 

Günaydın diyorum ona bütün sevecenlğimle 

O da her zaman ki gibi gülümsüyor 

Sevgi nağmeleriyle uyandırıyorum oğlumu 

O da gülerek bakıyor yüzüme 

Ve günaydın babacığım diyor 

İçim gidiyor sesini duyunca 

Güne güzel başlıyorum böylece

Geceki kabuslara inat...', 'Yine sabah oldu  Karanlıktan aydınlığa kavuştum  Mahmur mahmur çevreme bakınıyorum  Oğlum mışıl mışıl uyuyor  Eşim mutfakta tıkırdıyor  Güna...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gece-gunduz-ve-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Akşamları', 'gurbet-aksamlari-erol-sen-pb4bs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Memleketimin toprak kokusu yok buralarda

Yaşam belki hızlı akıyor burda

Ama ben o yaşamda bir yabancı

Kabullenmek zor be gurbet seni

Belki güneşin güzel batıyor akşama

Bana özlem getiriyor memleketimden

Rüzgarın memleketim kokusu getiriyor

Boşuna mı dedim gurbet akşamı diye

Belki ilk günlerin güzel geliyor

Ama yavaş yavaş hasret birikiyor gönlüme

Farklısın işte doğduğum yere

Benim akşamım bile güzel oluyor gönlüme

Sabahın güneş doğarken başlamasa da

Dolaştığım yerlere yabancı gözüyle bakarken

Belki güzel geliyorsun bana belki değişik

Belki de gıpta ediyorum sana

Biterken dizeler yeni şiirime kadar

Sensiz de olmuyor belki gurbet

Dönüş yoluna çıkınca bu beden

Ayrı bir sevinçle ayrılıyor gurbet yolundan….

24.03.2004', 'Memleketimin toprak kokusu yok buralarda Yaşam belki hızlı akıyor burda Ama ben o yaşamda bir yabancı Kabullenmek zor be gurbet seni Belki g...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gurbet-aksamlari-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost...', 'dost-bekir-gedikoglu-0rlae', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ankara’nın içine 

Seriyorum postumu

Her geçenden soruyorum

Arıyorum dostumu

Dünya durmadan döner

Yare kavuşmak için

Gece gündüz arıyorum 

Arkadaş bulmak için

Toprağa ne ektiysem

Baharda filizlendi

Yıllardır bekliyorum

Can dostum çok gecikti

Kundaktaki bebeği

İhmal etsen büyümez

Kalbim herkese açık

Dost gelmese gelişmez

Güneş ışıldar durur

O herkesin dostudur

Gönlümün günüldaşı

Güneş kadar yok mudur

Ankara,23.03.2004', 'Ankara’nın içine  Seriyorum postumu Her geçenden soruyorum Arıyorum dostumu Dünya durmadan döner Yare kavuşmak için Gece gündüz arıyorum  Ar...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dost-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazlumun Haramiye Verdiği Baç', 'mazlumun-haramiye-verdigi-bac-zulfikar-yapar-kaleli-mod84', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Şu yer yüzü tiyatro, sahnelenen drama

Mazlumun haramiye verdiği baçtır sabır

“Sövene dilsiz gerek, dövene elsiz” ama

Haksızlığa susunca  dildeki suçtur sabır.

Acıyı yudum yudum içine sindirmektir

Sıkıntıyı terk edip, belâyı dindirmektir

Musibete katlanıp, sevaba yendirmedik

Dünyada yenilmeyen en büyük güçtür sabır

Hepiniz çobansınız, hepiniz mesulsünüz

Her meclisin özü siz, hepiniz asılsınız

Ve hepiniz şartsınız, hepiniz usulsunuz

Hakkı tavsiye güzel, güzele içtir sabır

Tutulmayan söz vermek, emek kalbi öldürür

Çok konuşmak, uyumak, yemek kalbi öldürür

“Herkes başka, ben başka” demek, kalbi öldürür

Kasapların elinde kurbanlık koçtur sabır

Ayrılıklar ağlardı, ayrılığı yaşasa

Musa’yı Tur’da gördüm, elinde aynı asa

Çok çirkef pazarlığa duçar olur piyasa

Kimine çöplük gülü, kimine taçtır sabır

Harcamazsan bu yolda  baharını, yazını

İliğinin içinde duyamazsan hazzını

En tatlı çile deyip çekemezsen nazını

Baykuşların özlemi, bitmeyen hiçtir sabır', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Şu yer yüzü tiyatro, sahnelenen drama Mazlumun haramiye verdiği baçtır sabır “Sövene dils...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mazlumun-haramiye-verdigi-bac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nilüfer Gibidir Sevgim', 'nilufer-gibidir-sevgim-cafer-tayyar-ozkan-msvwb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göle bezenmiş nilüfer gibidir sevgim,

Kapattım çehreni, başkası nazar etmesin.

Kalbe dolanmış sarmaşık gülüdür sevdam,

Hapsettim kalbini, başka kullar üzmesin...

Güne saklanmış yıldızlar gibidir aşkım,

Yalvardım güneşe, vuslata kadar batmasın.

Suya dadanmış ceylan gibidir cananım,

Ahdettim, tenine yaban kurşunu değmesin...

28.09.2003 Ankara', 'Göle bezenmiş nilüfer gibidir sevgim, Kapattım çehreni, başkası nazar etmesin. Kalbe dolanmış sarmaşık gülüdür sevdam, Hapsettim kalbini, ba...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nilufer-gibidir-sevgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormalı mı Sormamalı mı?', 'sormali-mi-sormamali-mi-ozan-ozel-afo1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu dünyayı nasıl yaşamalı? 

Düşünceli mi olamalı düşüncesiz mi? 

Yaşamı sorgulamalı mı sorgulamamalı mı? 

Gezerek mi öğrenmeli, okuyarak mı? 

Tembel mi olmalı çalışkan mı? 

Sevmeli mi sevmemeli mi? 

Evlenmeli mi evlenmemeli mi? 

Gülmeli mi ağlamalı mı? 

Sizce,

Bu soruları sormalı mı sormamalı mı?', 'Bu dünyayı nasıl yaşamalı?  Düşünceli mi olamalı düşüncesiz mi?  Yaşamı sorgulamalı mı sorgulamamalı mı?  Gezerek mi öğrenmeli, okuyarak mı?...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sormali-mi-sormamali-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenakuz', 'tenakuz-tulay-sustam-c5seh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne şiir ölür 

Ne de şair

Ne yürek susar

Ne de kalem

Yürek sustuğunda 

Şair ölür

Kalem susar

Şiir olmaz

Gün gelir şair ölür

Geriye şiir kalır

Şair şiirleşir

Yürekler de şiir olur

Kalemi; mezarında gül olur

Gülün dikeni şairin hayata isyanıdır

Ne şiir ölür 

Ne de şair 

(İstanbul, 11.01.2004)', 'Ne şiir ölür  Ne de şair Ne yürek susar Ne de kalem Yürek sustuğunda  Şair ölür Kalem susar Şiir olmaz Gün gelir şair ölür Geriye şiir kalır...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tenakuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebemkuşağı', 'ebemkusagi-necmi-unsal-3ufry', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte  bak,                                                                      

gökkuşağı!                                                                    

Başka  bir  adı;                         

ebemkuşağı.                                  

Yukardan  aşağı

                                                    

Tatlı  bir  kavis;                         

yerden  göğe!                            

Renkler  bitmez

öve-öve.                                    

                                                  

Hisler  tomur-tomur                   

Tüm  sırlarla                              

yağmur                                      

yağar  ince-ince.                        

Kara  bulutlar  gidince,

çıkar  aydınlık  güneş.              

Bulunmaz  ona  eş.                     

                                                   

Şimdi                                          

sanki  büyüdük! 

Eskiden  küçüktük.                   

İsterdik                                      

Altından  geçmek;                      

Dileklerden                               

Dilek  seçmek.

                                            

Olmadı  henüz  dileğim! 

Bilmem,

altından  nasıl  geçeyim! 

Ebemkuşağının  özü;                                  

 ışıkla  damla.                                  

O  ışıkla

 ağla da  ağla!   

 Işıkla  damla; 

 ikisi  aynı  anda,

benim  dünyamda.

 Renk  cümbüşü

 hasıl  olur.

Deme  sakın,

bu  nasıl  olur? 

Açık  açık

meydanda! 

 Dünyayı 

bir  güzellik  sarar.

Renkler

en  güzel  karar! 

 Damlalar

 bulunca  ışığını,

durma,  sen de  doldur

 kaşığını...

6 Mart 2004 Cumartesi, Danimarka-Køge  14.28', 'İşte  bak,                                                                       gökkuşağı!                                                 ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ebemkusagi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut beklemeli...', 'umut-beklemeli-yusuf-ziya-leblebici-imeui', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan yüzünün diğer yarısı

Hazanda delice esiyorsa,

Dökülmüş kuru bir yaprak gibi

Dünki mazilerin arasında

Yel misali uçuyorsa

Öbür yüzün de destek çıkmalı

Gelecek günleri karartmadan

Umutla açmalı yarınları

Umudu dost tutmalı kırmadan

Önündeki günleri yırtmadan

Bir yüzün her iki yarısı da

Yarına bakmalı usanmadan

Zamana çivi çakmışcasına

Boşa beklemenin faydası yok

Ayakların taşıyorsa seni

Yerinde durmanın anlamı yok

Yükü kaldırmak zor geliyorsa

Bu diyardan çıkıp gitmemeli

Uykudan şafakta uyanıyorsan

Gözün, günden umut beklemeli

İyi tutmalısın hayatını

Geçmişinden dersini alarak

Yeni sevdalara koşmalısın

Toprağı,zamanı dost tutarak

Kimvurduya giden dünlerinin

Yeşil yaprakları kuruduğunda

Geleceğini yeşertmelisin

Umutla bakmalısın yarına..', 'İnsan yüzünün diğer yarısı Hazanda delice esiyorsa, Dökülmüş kuru bir yaprak gibi Dünki mazilerin arasında Yel misali uçuyorsa Öbür yüzün de...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/umut-beklemeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gününe...', 'bir-gunune-yusuf-ziya-leblebici-66cqk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi yana baksam sen çıkıyorsun

Güneş gibi doğup ateş gibi yakıyorsun

Bırak bir gününe bir yılımı vereyim

Yeterki seninle geçsin saatlerim

Vazgeçersen çekip gitmekten

Sevgimi önüne sereyim

Dudaklarının arasından dökülen kelimeler

Benden yana dönerse eğer

O sözcükleri taç yapıp

Saçlarının arasına dizeyim

Bir günlüğüne gel dünyama

Ruhun benden uzak olsa da

Duygularımı hecelerim dudaklarına

Yıllarımı veririm yanaklarına...', 'Hangi yana baksam sen çıkıyorsun Güneş gibi doğup ateş gibi yakıyorsun Bırak bir gününe bir yılımı vereyim Yeterki seninle geçsin saatlerim ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-gunune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarım Seni Arıyor', 'ruyalarim-seni-ariyor-sadik-softa-j6vz4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece; 

Karanlıklar içinde,

Islak siyah gözlerin, 

Bakıyor... Beni arıyor; 

Davetkar dudakların,

Ellerin yalvarıyor,

Rüyaları sarıyor,

Sevgin yaşıyor.

Bu gece; 

Umutsuz sevgilerin.

Rüyalarımı doldurur gözlerin.

... Ve gönül zenginliğin,

Mağlup eder yalnızlığım,

Omuzlarıma çökmüş,

Rüyaları sarıyor,

Aşkın yaşıyor.

Bu gece; 

Bulutlar kabarıyor; 

Şarkılarda sen varsın,

Türküler seni arıyor; 

Yaşamak denirse buna,

Avare dolaşıyorum sokaklarda,

Ruhum karışıyor rüyalara,

Rüyalar seni arıyor,

... Ve seni yaşıyor.', 'Bu gece;  Karanlıklar içinde, Islak siyah gözlerin,  Bakıyor... Beni arıyor;  Davetkar dudakların, Ellerin yalvarıyor, Rüyaları sarıyor, Sev...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ruyalarim-seni-ariyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galiptir Bu Yolda Mağlup', 'galiptir-bu-yolda-maglup-burak-killioglu-5al5h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün daha bitti,

Bugün de hayattayım.

Kim galip, kim mağlup bilemem.

Ama ben, galipler safındayım.

Dedim ya, akşam oldu

Ve hala hayattayım.', 'Bir gün daha bitti, Bugün de hayattayım. Kim galip, kim mağlup bilemem. Ama ben, galipler safındayım. Dedim ya, akşam oldu Ve hala hayattayı...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/galiptir-bu-yolda-maglup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Sevdanın Ayak Sesi', 'olu-sevdanin-ayak-sesi-sirma-mersin-htcon', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölü bir kentin; 

Köşesi olmayan sokağında! 

Kayıp bir ruhun; ölü sevdasının ayak sesleri,duyuluyor! 

Adımlarını sayarak; karanlığın  dokunuşları ile...

Gece; gönül matemine bürünmüşken! 

Acıları,kuşatmış kabuslar takılır; virane kalbin peşine...

Herkes uykusunda pembe beyaz düşlerin içinde iken; 

Uykusuzluğun koynunda yürüyordu, 

Kayıp bir ruhun; ölü sevdasının ayak sesleri...

24.3.04', 'Ölü bir kentin;  Köşesi olmayan sokağında!  Kayıp bir ruhun; ölü sevdasının ayak sesleri,duyuluyor!  Adımlarını sayarak; karanlığın  dokunuş...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olu-sevdanin-ayak-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Ve Unutmak', 'sevmek-ve-unutmak-oktay-yivli-cs4ys', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek ve unutmak

geceleyin açan ağulu çiçek

göğümüze serpilmiş yıldız tozu

nasıl da içine, derine çeker

karanlık mağaralar, dipsiz kuyu

sevmek ve unutmak

Vahşî atlarla çocuklar

dingin gök sular gibi biri

öteki böğüren, ısıran

köpük köpük tutku

isteyişin acı meyvesi olmalı yitiriş

sevmek ve unutmak

Dişi kurdun uluması mıdır çoğalmanın çağrısı

ne düğün ne ölüm var aslında

bizi yanıltmıştır karanlığı delen ses

hiç kimseler yok orda, ormanda

bir çingenenin kesip unuttuğu

yarım bir kavun gibi aydan başka

Hem kazanan hem yitiren

hem arzu hem tiksinç

bir gülü kokladığımı sanmıştım

ısırgan otunu tenimde duyana dek

ölüme doğmak gibi bir şey

sevmek ve unutmak', 'Sevmek ve unutmak geceleyin açan ağulu çiçek göğümüze serpilmiş yıldız tozu nasıl da içine, derine çeker karanlık mağaralar, dipsiz kuyu sev...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevmek-ve-unutmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız', 'issiz-oktay-yivli-uhu5q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey yaşamanın çocuksuz dulu

büyük orman içre yiten ağaç

hangi pencereyi açarsan aç

korku, üzgü, ölüm

işte yazgın bu

Yer, gök, su ve ateşten kurgu

dört başlı yaratığın

kendi kendini boğuşu

seni bu uzak kıyıya sürmüş

ağlatan ağulu gülüş

Sonsuz olan ne

deniz mi, gök mü, teklik mi

hey sayrıyı iyi eden gece

fısıldar anne sesiyle

kurtuluşşşşşş', 'Ey yaşamanın çocuksuz dulu büyük orman içre yiten ağaç hangi pencereyi açarsan aç korku, üzgü, ölüm işte yazgın bu Yer, gök, su ve ateşten k...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/issiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pelikan', 'pelikan-oktay-yivli-ozuys', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göl üstüne serpilmiş

bir avuç darı:

                     kuşlar

ion atalarını arar', 'Göl üstüne serpilmiş bir avuç darı:                      kuşlar ion atalarını arar...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pelikan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Şiirleri -1', 'veda-siirleri-1-sirma-mersin-vak2n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1.Bölüm

.............. Felaketlerin Başkenti.......

Gecenin sonsuzluğuna düşmüşüm! 

Varoş sokaklarının loş ışıkları  altında; dudaklarımda  bir ayrılık türküsü  gönlüm susuyorken,

Başımı öne eğmiş, yürüyorum! adımlarımı saya saya...

Gölgelerde  konuşan geceye karşı; kelimelerin kifayetsiz kaldı...

Yüreğime yerleşmiş hüzün! 

Yalnızlığımı acılara teslim etmişken...

Felaketlerin başkentinde! 

Hayatıma atılan bir tokat gibi; 

Kirli sözlerin içindeki duygularım, cinnet geçirirken...

Enkaz zamanda; 

Özlemeyi özleyen ruhum; virane umudumun karşısında  yıkıldı! ...

2. Bölüm

............................ Ölüm...............

Hergün ! 

Namlunun ucunda ki kurşunlara, hedef olmaktansa...

Yada! 

Yaşayan bir ölü olarak; 

Ölümü beklemektense...

Bileklerimi keser; kandamlaları ile imza atarım, veda şiirlerine.

Azrailin gelmesini istemek için; 

Sıraya girmek zor...

Ölüm! 

Son perde inerken; 

Gözlerime elveda demek kolay...

24.03.04', '1.Bölüm .............. Felaketlerin Başkenti....... Gecenin sonsuzluğuna düşmüşüm!  Varoş sokaklarının loş ışıkları  altında; dudaklarımda  ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/veda-siirleri-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktan Öte', 'asktan-ote-oktay-yivli-ov40z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölsek aşkın eşiğinde

yok oluş değildir bu

bir kızıl, bir ak gülün

yayılır üstümüzden kokusu', 'Ölsek aşkın eşiğinde yok oluş değildir bu bir kızıl, bir ak gülün yayılır üstümüzden kokusu...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asktan-ote-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ve Arzu', 'ask-ve-arzu-oktay-yivli-w6waw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz Zeus''un ayırdığı tenleriz

bundandır gövdemin sana akışı

gel karışalım birbirimize

sen bedenime eklen

ben kaybolayım sende

Issız sokaklara dönmüş sensiz evim

nasılsa bütün odalar bomboş

bir gül penceremden yapraklarını dökmüş

hadi gel, sevişelim güzün kurduğu yatakta

Ölmek mi, yaşamak mı bu

yarımlık, büyüyen bir kaktüs içimde

yüzünde zehirleyen gülüş

seni yabancı bilmektense

iyisi mi unutuş ırmağı''na dalmak

Yetmez mi bin yıllarca çektiğim acı

türümün korkunç yazgısı mı bu

-senin elinden yasak meyveyi yiyen-

yok et beni nesnelere katılayım

ölümün ölümü bu kösnül ikilem', 'Biz Zeus''un ayırdığı tenleriz bundandır gövdemin sana akışı gel karışalım birbirimize sen bedenime eklen ben kaybolayım sende Issız sokaklar...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ask-ve-arzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalsiz Zihinler İmkansızmış', 'hayalsiz-zihinler-i-mkansizmis-ahmet-aksoy-tq9jc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiç bir silgi üreticisi yetişemedi

.............seni hayatımdan çıkarmaya

yüzsüz ölüler gibisin

........................inatçı ve kabulsüz', 'hiç bir silgi üreticisi yetişemedi .............seni hayatımdan çıkarmaya yüzsüz ölüler gibisin ........................inatçı ve kabulsüz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayalsiz-zihinler-imkansizmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpteki Acıların Mürekkep Lekeleri', 'kalpteki-acilarin-murekkep-lekeleri-ahmet-aksoy-ftt2r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

köprünün altından çok sular geçer 

bilemezsin  sen artık kim olduğunu 

dönmek dönmek istersin bir an olsun 

oysa yerinde yeller esmektedir ölü aşkın

II

bir gün biri çıkar biri çıkar karşına

gözlerindeki ışık ruhunu sarar

oysa bilirsin bilirsin artık

afroditin kendisi bile dindiremez acını', 'I köprünün altından çok sular geçer  bilemezsin  sen artık kim olduğunu  dönmek dönmek istersin bir an olsun  oysa yerinde yeller esmektedir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kalpteki-acilarin-murekkep-lekeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onca', 'onca-ahmet-aksoy-kzi8s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'daha ne kadar kırılabilir yüreğim

daha ne kadar şiir olur elemim

benki kayıp ruh halindeyim

benki okyanusta kırık bir gül

şafaklar açmaz iç kuş yükselişleri

hangi avcı bekler gözü arpacıkta

hangi havalanır umut vurulmamakta

benki çölde tenha bir vaha

ah açılsın artık dikense dikenlerim

ben batıyorum aslımda cenk

kaç zaman tutsak bırakır  anı

benki ölü bir acı anılarda', 'daha ne kadar kırılabilir yüreğim daha ne kadar şiir olur elemim benki kayıp ruh halindeyim benki okyanusta kırık bir gül şafaklar açmaz iç ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/onca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şarkı Gibisin', 'bir-sarki-gibisin-i-brahim-dikmen-2-vdmou', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şarkı gibisin,dudaklarımda,

Bir masal gibisin,kulaklarımda.

Boncuk olup dökülsün,yanaklarına,

İnci tanesi yaşlar,benim ahımla.

Özlemle bekledim,sevgilim seni,

Adını haykırıyor,sazımın teli.

Duydumki beni,unutmuşsun,

Aşkım dediğin,biricik sevgilini.

Şimdi çok,ama çok uzaklardayız,

Dillerden düşmeyen,ölümsüz şarkıyız.

Benim olcaksın,sevgilim benim,

Şarkılarda yaşanacak,aşkımız bizim.', 'Bir şarkı gibisin,dudaklarımda, Bir masal gibisin,kulaklarımda. Boncuk olup dökülsün,yanaklarına, İnci tanesi yaşlar,benim ahımla. Özlemle b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-sarki-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A k r o s t i ş', 'a-k-r-o-s-t-i-s-reside-sarikavak-glk3p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Martıları biz uçurmuştuk heybemizden 

Esrik, mahzun, tutuklu 

Neşemizde ekşi tatlar 

Ebruli çeşniler 

Vakit darlığında 

Şaklabanlıklar vardı 

El salladın, el salladık….gittin

....................oysa, yeni başlamıştı yolculuğumuz

Kısa vakitte dolup taşmıştı hatıralar 

Öyle ki ömür kadar 

Yolun yarısını bir geçe 

Loşluğunu bıraktı işte akşamlar 

Üzmedin ki, üzülmedik ki…bildik

....................olsun, mendilini bırakmıştı dostluğumuz', 'Martıları biz uçurmuştuk heybemizden  Esrik, mahzun, tutuklu  Neşemizde ekşi tatlar  Ebruli çeşniler  Vakit darlığında  Şaklabanlıklar vardı...', ARRAY['Türk Edebiyatı','Şiir','Reşide Sarıkavak']::text[], 8.5, '{"poet":"Reşide Sarıkavak","poet_slug":"reside-sarikavak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/a-k-r-o-s-t-i-s-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-tuncay-dudu-n8l59', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir sessizlik arasında

bin sensizlik doluyor içime

duman duman 

atmaktayım seni içimden

bitince sigaram

sende sende bitmektesin

sessizlikte

ama her an hatırımdasın çünkü 

ben sana tiryakiyim', 'bir sessizlik arasında bin sensizlik doluyor içime duman duman  atmaktayım seni içimden bitince sigaram sende sende bitmektesin sessizlikte ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Dudu']::text[], 8.5, '{"poet":"Tuncay Dudu","poet_slug":"tuncay-dudu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sessizlik-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Doğru', 'sonsuza-dogru-murat-demir-wgtjj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabrım tükeniyor umut gelmezde

Aklım rehin kalmış hatır bilmezde

Ne canda derman var ne de fer gözde

Savrulur giderim sonsuza doğru

Sağım solum dolu gül dikeniğle

Çekti yüreğimi aldı eliğle

Yaktı yaraladı sessizliğiyle

Kavrulur giderim sonsuza doğru

Dereden tepeden dağları aştım

Divaneler gibi döndüm dolaştım

Kader denen bir kahpeye bulaştım

Yoğrulur giderim sonsuza doğru

Gönülden gönüle, sürdüm atımı

Bilemedim yıkar onur çatımı

Sanki hayatımın güneş batımı

Kaybolur giderim sonsuza doğru', 'Sabrım tükeniyor umut gelmezde Aklım rehin kalmış hatır bilmezde Ne canda derman var ne de fer gözde Savrulur giderim sonsuza doğru Sağım so...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonsuza-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Artık', 'sen-yoksun-artik-ramazan-atasorkun-o2mmc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün..! 

Her şey seni sevmekle başladı.

Bir asırlık uykudan 

Seni sevmekle uyandı yüreğim.

Gökyüzünden düşen 

Her yağmur tanesine seni yüklerdim

Sırıl sıklam sen olmak için.

Seni üflerdim rüzgarlara

Çiçeklere, güllere seni aşılardım

Her nefesimde seni solumak için

Sol ayağıma seni, sağ ayağıma beni yazdım

Yürüdüğüm her köşede

Sen ve ben olmak için.

Bugün..! 

Sen yoksun artık, 

Seni düşünmek var...

Seninleyken de 

Seni düşünürdüm...

Bak, yine sabah oldu

Yine isyan başladı gözlerime

Uyanmasınlar senle dolu rüyalardan diye.

Yine gem vuruldu

Gözlerimdeki pırıltılara.

Kırıldı dalgalarım

Yine tutsak alındı sevinçlerim.

Bakışları uzaklara dalıp giden

Şarkılar yine beni söylüyordu

Seninle dolu  masum düşlerim

Yine sürgün edilmişti en uzak adalara

...ve zamansız yağan bir yaz yağmuru

Umutlarımı da alıp götürdü.

Şimdi sen yoksun artık

Seni düşünmek var.

Seni anılara sarıp içmek var...', 'Dün..!  Her şey seni sevmekle başladı. Bir asırlık uykudan  Seni sevmekle uyandı yüreğim. Gökyüzünden düşen  Her yağmur tanesine seni yükler...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Atasorkun']::text[], 8.5, '{"poet":"Ramazan Atasorkun","poet_slug":"ramazan-atasorkun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sen-yoksun-artik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miğferimde bir delik', 'migferimde-bir-delik-hakan-yasar-si5ln', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün yine seni düşündüm

Ellerim ısındı pamuk avuçlarında

Ah çocuk! 

Ellerin küçük

Ellerin sıcak

Bırak dereler aksın yanaklarımdan

Sen benimle büyük ol yine

Ben seninle çocuk.

Sen giderken

Derin,mavi bir boşluk bıraktın bana,

Ne zaman başımı kaldırsam

O sözler gelir aklıma; 

............Seni özleyeceğim

............ Beni unutma

............ Baba! 

Bir çınar gibi ayakta kalmak demiştim

Evet

Ama,

Yaşamak derken bunu kastetmemiştim! ...

Miğferimde

Bir delik gibi duruyor hasret,

Umutsuz yarınlarda tükeniyorum,

Şakağıma süzülen kan mı

...............................  ter mi,

Kelimeler bunu anlatmaya yeter mi?', 'Dün yine seni düşündüm Ellerim ısındı pamuk avuçlarında Ah çocuk!  Ellerin küçük Ellerin sıcak Bırak dereler aksın yanaklarımdan Sen benimle...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yaşar']::text[], 8.5, '{"poet":"Hakan Yaşar","poet_slug":"hakan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/migferimde-bir-delik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* * * YAŞAMAK DEDiĞiMiZ...!', 'yasamak-dedigimiz-baki-son-ibfi3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu büyük mavi

Bu evren deyiş,yok mu...? 

Bir uyanış,

Durmadan sevilesi.

Güzel ne varsa deyişlerde

Bir soluk

Sevgi üstüne beklediğimiz.

Belki de bu...

Yaşamak.! dediğimiz.

Uzakta

Çok uzaklarda

Diner mi...? 

Bir ömür yorgunluğumuz.

Yoksa ümit mi

Aranan

Küçükcük sevilerde...

Bu küçük ağaç dipleri

Sonra,bu

Büyük mavi...

Sevdiğimiz,

Ölesiye seviştiğimiz,

Bir kayboluş mu...? 

Anlamsız bu sürükleniş,

Bir ömür aranışta

Bu yokluğa...

Dokunuvermek,

En mutlu anlarda

Uçup giden,

Sevmek...! 

Bir deniz kıyısında

Belki akşam

Belki başlayış,

Sonsuz evrende

Belki de...

Kaybediş.! bir olmayışı

Küçücük sevilerde...!', 'Bu büyük mavi Bu evren deyiş,yok mu...?  Bir uyanış, Durmadan sevilesi. Güzel ne varsa deyişlerde Bir soluk Sevgi üstüne beklediğimiz. Belki...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yasamak-dedigimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfilin Morunda', 'karanfilin-morunda-onder-karadag-mvp87', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ellerini ıslatırken sevgili

durulanır dalgalar

bir bulut düşer yüzüne

karanfilin morunda

kaygılanır suları denizin

                    

                          (02 aralık 2001)', 'ellerini ıslatırken sevgili durulanır dalgalar bir bulut düşer yüzüne karanfilin morunda kaygılanır suları denizin                          ...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/karanfilin-morunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Akar Bu Gökyüzü', 'nereye-akar-bu-gokyuzu-onder-karadag-bkeb5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nereye akar bu gökyüzü

kirpiğine kadar mavi

tırnağına kadar esmer

bulutlar mor ötesi

güneş yağıyor

yağmur yerine

gözlerinin değdiği yerde

sevdalanıyor deniz! 

                   (10 şubat 2002 Lodos)', 'Nereye akar bu gökyüzü kirpiğine kadar mavi tırnağına kadar esmer bulutlar mor ötesi güneş yağıyor yağmur yerine gözlerinin değdiği yerde se...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nereye-akar-bu-gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden doğuş', 'yeniden-dogus-erol-sen-r3vqi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elleri ipek gibiydi minik ve narin

Hayata sarılır gibi tutuyordu elimi

Yaşamın tadını almıştı belli 

Bir de ben geldim der gibi çekiştirerek

Kokusu kendine göre hatta mis gibi

Gözlerinde belki ilk günlerin şaşkınlığı

Ama gelmişti ya başarmıştı

Yaşamın da yeni bir pencere vardı artık

Enteresan olaylar yaşayacak bedenler

Günler geçerken yaşamda

Belki arzular doğacak zirve isteyen

Yaşanmışlık pişman edecek belki de

Anlık duygulara sarsılacak bedeni

Zirve de yaşayacak belki de

Ya da yaşamın tek düze saplantılarında

Bilmek için falcı olmalı belki de

Silkinip kendini yaşama sarılacak

Belki solgun belki yılgın ve de amaçsız

Kimbilir günler neler getirecek sarı yapraklara

Bazen yeşil bazen mavi bazen kahve belki de yeşil…..

24.03.2004', 'Elleri ipek gibiydi minik ve narin Hayata sarılır gibi tutuyordu elimi Yaşamın tadını almıştı belli  Bir de ben geldim der gibi çekiştirerek...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yeniden-dogus-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-erol-sen-r1bd6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dışarı baktığımda aklıma geldi

Rüzgar neler getirip götürüyor hayata

Bazen fırtınalar bazende güneş

Bazen bulutlar alıyor önüne bembeyaz

Grileri getirme hayatıma eyyyyy rüzgar

Baharın dalları yeşersin yaşantılara

Sadece kendime değil isteklerim

Güzel insanları mutlu et sende gönlünce

Kırma gülümün yapraklarını hoyratça

Ya da suratıma çarpa yanlışlarımı

Meltem rüzgarları yaşat bizim gönlümüze

Ilık sevecen ve umutla.

Sen de bilirsin vefasızları hayatında

Yaşanmışlık var nereye bakarsan

Taş yerinde ağır derken bizim sevgimiz

Sen o taşları kopartır atarsın içimizden

Hayasız ve kibirli insanlara bakar

Belki de gülersin için için görürsün diye

Dayanamaz kopartır atarsın yaşamdan

Atarsın da anlamaz o insanlar……

24.03.2004', 'Dışarı baktığımda aklıma geldi Rüzgar neler getirip götürüyor hayata Bazen fırtınalar bazende güneş Bazen bulutlar alıyor önüne bembeyaz Gri...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ruzgar-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakma Beni', 'birakma-beni-erhan-saka-7fxs3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle bir sevmiş ki bu kalbim seni,

Yerinde durmuyor sanki bir deli,

Sarmışken her yanı bir sevda seli,

Yalvarırcasına bırakma beni.

Soldurma kalbimde aşk çiçeğimi,

Koparma sazımın sevda telini,

Kimse almayacak senin yerini,

Gidersen yaşamam bırakma beni.

Bulutlar üstünde gezer gibiyim,

Kış iken bahara dönen biriyim,

Nereye gidersen bende geleyim,

Önünde diz çöktüm bırakma beni.

07-10-2003', 'Öyle bir sevmiş ki bu kalbim seni, Yerinde durmuyor sanki bir deli, Sarmışken her yanı bir sevda seli, Yalvarırcasına bırakma beni. Soldurma...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birakma-beni-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Yanmasın', 'canim-yanmasin-erhan-saka-sxmkm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün gelir düşerse yolun buraya,

Gözlerin maziye sakın dalmasın,

Dokunma küllenmiş gizli yaraya,

Kanatma bir daha canım yanmasın.

Aldırma sen benim göz yaşlarıma,

Kalbimin zamansız atışlarına,

Anlamsız, ümitsiz bakışlarına,

Kanma ki bir daha canım yanmasın.

Bir yabancı gibi baksın gözlerin,

Yaşayan ne varsa silsin sözlerin,

Son defa elimi tutsun ellerin,

Gözlerime bakma canım yanmasın.

11-11-2003', 'Gün gelir düşerse yolun buraya, Gözlerin maziye sakın dalmasın, Dokunma küllenmiş gizli yaraya, Kanatma bir daha canım yanmasın. Aldırma sen...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canim-yanmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmeyi Boşadım', 'gulmeyi-bosadim-erhan-saka-1myby', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar var kapımı çalan olmadı,

Yokluğu yaşadım sensiz sevdiğim,

O mutlu günlerden eser kalmadı,

Gülmeyi boşadım sensiz sevdiğim.

Taş oldu yüreğim aşka sevgiye,

Yollara sarıldım gelirsin diye,

Köleyim seninle geçen maziye,

Hayata küskünüm sensiz sevdiğim.

Güldüler halime dost bildiklerim,

Gözünden yaşını ah sildiklerim,

Sonumu getirdi bak çektiklerim,

Güneşim doğmuyor sensiz sevdiğim.

13-11-2003', 'Yıllar var kapımı çalan olmadı, Yokluğu yaşadım sensiz sevdiğim, O mutlu günlerden eser kalmadı, Gülmeyi boşadım sensiz sevdiğim. Taş oldu y...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gulmeyi-bosadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Kabuğum', 'hayat-kabugum-hakki-hakan-kaya-5x38v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerinden akarken

dayanılmaz yürek yaşları

ölümünü sorgulamadan

ölümden korkmadan

yanar bağır yangınları

uçuruma koşarken 

ayaklarında deli tayları

bir tutam koparır yelesinden

savurur alnını tokatlayan rüzgara

gevşek avuçları açılır birden

delicesine yayılır parçaları

her biri bir tutam anı olur

anılar coşar ferah sel olur

yangın tutan geride kalanlara

ve şefkatli ellerde

davetsiz bir kitle

dev hücreli bir canavar

korku salar yüreklere

binlerce şimşek ölür beyninde

ve daha doğamadan 

toprağa verilir

nice umutlar ellerinle

yüreğine batan zehirli çıban

günden güne zerk eder zehirini

bir davetsiz kitle

cehenneme çevirir cennetini...', 'gözlerinden akarken dayanılmaz yürek yaşları ölümünü sorgulamadan ölümden korkmadan yanar bağır yangınları uçuruma koşarken  ayaklarında del...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hayat-kabugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem Sevgini', 'i-stemem-sevgini-erhan-saka-uyixb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalmasın bu aşktan bende bir eser,

Ne varsa bırakma al senin olsun,

Nasılsa bu kalbim birini sever,

Güzellik dediğin al senin olsun.

Gün gelir anlarsın sende hatanı,

İstemem aşkımı böyle satanı,

İçtiğim suyuma zehir katanı,

Mutluluk dediğin al senin olsun.

Sevgili dediğin seni sevecek,

Ömrüne karşılık ömür verecek,

Seninle ağlayıp senle gülecek,

İstemem sevgini al senin olsun.

14-11-2003', 'Kalmasın bu aşktan bende bir eser, Ne varsa bırakma al senin olsun, Nasılsa bu kalbim birini sever, Güzellik dediğin al senin olsun. Gün gel...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istemem-sevgini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Yağmuru', 'nisan-yagmuru-erhan-saka-ulzqd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana aşkımız hatırlatıyor,

Delice yağarken nisan yağmuru,

Kalbimde duygular umutlanıyor,

İçime doluyor nisan yağmuru.

Şarkımız çalınır cama vururken,

Anılar canlanır resmin dururken,

Gözümde hayalin hala dururken,

Beni ağlatıyor nisan yağmuru.

Tanıştık seninle böyle bir günde,

Sitemler belirdi bir, bir dilimde,

Yazdığın mektuplar kaldı elimde,

Hasreti getirir nisan yağmuru.

12-11-2003', 'Bana aşkımız hatırlatıyor, Delice yağarken nisan yağmuru, Kalbimde duygular umutlanıyor, İçime doluyor nisan yağmuru. Şarkımız çalınır cama ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nisan-yagmuru-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kelime', 'i-ki-kelime-erkan-kaner-x0yk8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni sevmek

iki kelime

biraz gitmek

biraz kalmak

yada ikisinin arasında kalmak

aşk iki kelime

seni sevmek

seni sevmek

iki kelime

ama söyleyemem

tek kelime

benim sevmek neyime...

                     (21 kasım 2003)', 'seni sevmek iki kelime biraz gitmek biraz kalmak yada ikisinin arasında kalmak aşk iki kelime seni sevmek seni sevmek iki kelime ama söyleye...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iki-kelime-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz', 'biraz-ferit-teksoy-933yf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocukların lunaparka gittiği gibi

Çığlık çığlık sesim sana yönlendim

Bastırsam içime sığmıyor içim

Özlemim git dedi..git dedim biraz

Beyaz hakim sana gelen yollara

Toprak beyaz,ağaç beyaz,dal beyaz

Beni bu beyazda yalnız bırakma

Sarıl ısınayım,üşüdüm biraz

Üstünü kar tutmuş otlar çaresiz

Sensizlik üşüttü kollar çaresiz

Sana kavuşturan yollar çaresiz

Erken gelecektim geç kaldım biraz

Sevgiyle karşıla bizim durakta

Ellerimi ısıt,gözlerime bak

Kanımı ateşle,göğsünde uyut

Rüyalarım beyaz renklendir biraz', 'Çocukların lunaparka gittiği gibi Çığlık çığlık sesim sana yönlendim Bastırsam içime sığmıyor içim Özlemim git dedi..git dedim biraz Beyaz h...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biraz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen''li-Ben''li', 'sen-li-ben-li-erkan-kaner-fdnb8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bende bıraktığın ben

sende bir sen

bir de götürdüğün ben

hiç sevilmedimse zaten

bu alış-vermeyiş neden

                    (21 eylül 2003)', 'bende bıraktığın ben sende bir sen bir de götürdüğün ben hiç sevilmedimse zaten bu alış-vermeyiş neden                     (21 eylül 2003)...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-li-ben-li-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susss', 'susss-erkan-kaner-cnn9x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'darası alındı aşkın

hüzünlere satıldı

sükunete davet edildi

bütün duygular

hiç biri katılmadı

                       (21 eylül 2003)', 'darası alındı aşkın hüzünlere satıldı sükunete davet edildi bütün duygular hiç biri katılmadı                        (21 eylül 2003)...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/susss-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak da uzak', 'unutmak-da-uzak-erkan-kaner-2gvty', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bırakmak,

hüzünlerimi eski sayfalarda

gitmek,

gidebildiğim kadar uzağa

ve seni unutmak,

bir damla kin kalmamacasına...

                      (21 kasım 2003)', 'bırakmak, hüzünlerimi eski sayfalarda gitmek, gidebildiğim kadar uzağa ve seni unutmak, bir damla kin kalmamacasına...                      ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/unutmak-da-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simit', 'simit-erkan-kaner-8feuz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tazeliği gitti

susamları döküldü aşkımızın

martılar bile istemedi

                       (3 aralık 2003) 

                               (izmir)', 'tazeliği gitti susamları döküldü aşkımızın martılar bile istemedi                        (3 aralık 2003)                                 (iz...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/simit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Zamanlar Çiçeği', 'kayip-zamanlar-cicegi-erkan-kaner-6z9p3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kırmızı akıyordu

şehrin tüm asfaltları

ve paletler eziyordu

tüm umutları

kurşun sesleri

eşlik ediyordu sevişmelere

ve çocuk gözlerde gülüşlere

ülkelerini seviyorlardı

tetikleri çekenler

hiç acımadan ''seviyorlardı''

yitiriyordu yarınlarını bütün güzellikler

birer birer soluyordu

sığınaklarda açmıyordu çiçekler

                         (23 aralık 2003)', 'kırmızı akıyordu şehrin tüm asfaltları ve paletler eziyordu tüm umutları kurşun sesleri eşlik ediyordu sevişmelere ve çocuk gözlerde gülüşle...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kayip-zamanlar-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayığındaki Sevda', 'kayigindaki-sevda-goktu-kara-xci3z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşamak yorgun bir rüzgar gibi eser kayalıklara

neden sandalcı akıntıya kürek çekiyorsun

söylesene ölüm kayıkçısı taşıdığın nedir

sevdamı mı götürüyorsun karanlık ülkene

artık bıktım 

ne yapmalı bilmiyorum

kayığına beni de alsana

(Çalap)', 'yaşamak yorgun bir rüzgar gibi eser kayalıklara neden sandalcı akıntıya kürek çekiyorsun söylesene ölüm kayıkçısı taşıdığın nedir sevdamı mı...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kayigindaki-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktan Ölmeli İnsan', 'asktan-olmeli-i-nsan-erkan-kaner-4u4nj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'madem ki öleceğim

yakışsın isterim ölüm bana

aşktan ölmeliyim

imkansız olmalı mesela

                       (29 aralık 2003)', 'madem ki öleceğim yakışsın isterim ölüm bana aşktan ölmeliyim imkansız olmalı mesela                        (29 aralık 2003)...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asktan-olmeli-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşan(a) mamış Bir Aşk İçin Ağıt', 'yasan-a-mamis-bir-ask-i-cin-agit-erkan-kaner-pm1rv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bırak susuşlarda kalsın zaman

ne sen beni yarala

ne de ben seni

ama istersen yargıla

yargıla hiç yaşanmamışları

ver gerekirse

müebbet acıları

gönül yetersizliğinden bırak gerekirse

yada beni unut

(ki en büyük cezam olsun) 

unut bu sevda kalbinde kirse

                     (3 ocak 2004)', 'bırak susuşlarda kalsın zaman ne sen beni yarala ne de ben seni ama istersen yargıla yargıla hiç yaşanmamışları ver gerekirse müebbet acılar...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasan-a-mamis-bir-ask-icin-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredeydin?', 'neredeydin-hakan-ciftci-6v66f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neredeydin? 

Ben en derinindeyken

Senli hayallerin,

Ve en sitem dolu yerindeyken hayatın,

Neredeydin? 

Uykular bitti

Kuşalar,çiçekler ve ağaçlar

Uyandılar artık,

En sarı

En yalnız

En karanlık mevsimimde,

Neredeydin? 

Dayanacak gücü kalmadı hatıraların,

Ve resimler eskidi artık,

Sana verdiğim çiçek

Hala arasında defterimin,

Kokun hala şiir defterimde,

Sabah ile vurdu ışıkları cama güneşin,

En sessiz

En mavi

En koyu gecelerimde,

Neredeydin? 

Neredeydin deli rüzgar? 

Ben dokunmak üzereyim bulutlara,

Şimdi bende esmekteyim

Çok uzak şehirlere,

Ah...

Neredeydin daha dün yanındayken?', 'Neredeydin?  Ben en derinindeyken Senli hayallerin, Ve en sitem dolu yerindeyken hayatın, Neredeydin?  Uykular bitti Kuşalar,çiçekler ve ağa...', ARRAY['Türk Edebiyatı','Şiir','Hakan Çiftçi']::text[], 8.5, '{"poet":"Hakan Çiftçi","poet_slug":"hakan-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/neredeydin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Seçme Sınavı', 'yalnizlik-secme-sinavi-erkan-kaner-pg0j0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir yanlış bütün doğruları götürüyordu

ama bütün doğrular bir aşkı geri getirmiyordu

çoktan seçmeli boktan bir yalnızlıktı, geriye kalan

dünün acılarıyla yarınları yitiriyorduk

yaralarımıza merhem olmuyor,

aleyhimize işliyordu geçen zaman

gittikçe daha da yalnızlaşıyorduk

ve karalıyorduk bir aşkı dışına taşırmadan

karalıyorduk, durmadan

                          (6 ocak 2004)', 'bir yanlış bütün doğruları götürüyordu ama bütün doğrular bir aşkı geri getirmiyordu çoktan seçmeli boktan bir yalnızlıktı, geriye kalan dün...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizlik-secme-sinavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Kal', 'oyle-kal-t-l-n-ayse-kayi-d70ip', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dizilirken yokluklar boğazıma,

Seni düşlerken buldum kendimi.

Dedim ki; 

Acıkmak bu olmalı

Kaybetmişken en sevdiklerimi,

Yine sen çıktın karşıma...

Dedim ki; 

Kader bu olmalı...

Öfkeleri doldurup içtim ardından.

En kuytu kahpelikleri,

En gizli gerçekleri,

En pahalı düşleri satın aldım bir çırpıda...

Seni gözbebeğime yazdım,

Göz bebeklerimi sana...

Sarmayı özlerken en soğuk yanlarını,

Seni kaybetmek çıktı falımda.

Dedim ki; 

Yalan bu olmalı...

Nasıl geldiysen hayatıma,

Öyle kal istedim! 

Ellerine verince güneşlerimi,

Her ah edişinde yıldızları ekledim...

Nasıl geldiysen hayatıma; 

Öyle kal istedim!', 'Dizilirken yokluklar boğazıma, Seni düşlerken buldum kendimi. Dedim ki;  Acıkmak bu olmalı Kaybetmişken en sevdiklerimi, Yine sen çıktın kar...', ARRAY['Türk Edebiyatı','Şiir','Tâlân Ayşe Kayı']::text[], 8.5, '{"poet":"Tâlân Ayşe Kayı","poet_slug":"t-l-n-ayse-kayi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oyle-kal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acemi Aşk', 'acemi-ask-erkan-kaner-mxe8r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'iki acemi aşıktık

ben geç kaldım

senin acelen vardı

olmadı, yapamadık

oysa yitirilen

sadece zamandı

ne ben yerimde saydım

ne de senin yetişeceğin bir yer kaldı

                                       (23 ocak 2004)', 'iki acemi aşıktık ben geç kaldım senin acelen vardı olmadı, yapamadık oysa yitirilen sadece zamandı ne ben yerimde saydım ne de senin yetişe...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/acemi-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerimi Geri Ver', 'siirlerimi-geri-ver-erkan-kaner-2sb7m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şiirlerimi geri ver

hazırlarını alır sana

yeni sevgililer

iliştirirler bir gül cesedine

kandırırsın kendini

yersin aşk niyetine

hem gül için ne farkedecek

ha sen yemişsin

ha romantik bir inek

şiirlerimi geri ver

sana gül alırım! ...

                        (9 ocak 2004)', 'şiirlerimi geri ver hazırlarını alır sana yeni sevgililer iliştirirler bir gül cesedine kandırırsın kendini yersin aşk niyetine hem gül için...', ARRAY['Türk Edebiyatı','Şiir','Erkan Kaner']::text[], 8.5, '{"poet":"Erkan Kaner","poet_slug":"erkan-kaner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siirlerimi-geri-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-hasan-akin-g6lc5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zayıf bedenini kemirirken kurtlar 

yarasalar gölgeni ezerken,

devrilme sakın baharın sazlıklarına.

suya giden yalınayak sevdanın

namuslu merhametinin bedeli

bu kadar ağır olsa da

bir evelik gibi koparma hayatı.

bilsem de yüzünde ki derin çizgilerin

ne anlamı olduğunu,

bakışında ağrıyan çığlığını duysam da,

kahır dolu olsa da sinende ki yorgunluk,

ahh...bir görsem de ağaçların oyuklarını,

temmuzlar alıp götürse de saçlarını

senin gibi bir oğlum olsun isterdim.

kara talihin çaresizliği düşse de üstüne

oğul tadında yaşamış olsun isterdim,

bir evelik gibi koparmasın hayatı isterdim,

seni bu kadar neden

neden yıktıklarını

bilsin isterdim.

bilmem ki yalan mıdır sana benzer yanlarım?', 'zayıf bedenini kemirirken kurtlar  yarasalar gölgeni ezerken, devrilme sakın baharın sazlıklarına. suya giden yalınayak sevdanın namuslu mer...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akın']::text[], 8.5, '{"poet":"Hasan Akın","poet_slug":"hasan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/baba-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve ben...', 'sen-ve-ben-omer-faruk-girgin-944vv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen,

Karlı dağların doruğunda

Gün vurmuş bir ışık pırıltısı gibisin.

Yine sen,

Tüm gecelerde

Yakamozlardan şarkılar söyleyen

Lacivert denizler gibisin…

Ben ise,

Senin yokluğunda,

Gece ve taş duvarların tam ortasında

Sensizliğimle çarpışırım amansızca

Ve sonra,

Kendimi yine sende bulurum

Ağa takılmış balık çırpınmalarında…', 'Sen, Karlı dağların doruğunda Gün vurmuş bir ışık pırıltısı gibisin. Yine sen, Tüm gecelerde Yakamozlardan şarkılar söyleyen Lacivert denizl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-ve-ben-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Kalsın Yüreğim', 'sende-kalsin-yuregim-hatice-kuzu-s8h70', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Attım anarşist duyguları 

En karanlığına arka sokağın.

Hiçbir şey üzmedi beni,

Yokluğunun üzdüğü kadar...

Gülmeyi yükleyip kuşun kanadına,

Acılarla yoldaş  oldum.

Ardına bakmadan giderken sen,

Gözümü kırpmadan öylece duruyordum...

Vurdu geçti sevdan,

Geride kalmak, ölümden beter...

Sok hançeri yüreğime

Çıkar çıkarabilirsen içinden seni.

Zaman kaybı düşünmek,

Öyleyse sus, 

Ve şiirlerimi geri ver...

Ziyanı yok, sende kalsın yüreğim....', 'Attım anarşist duyguları  En karanlığına arka sokağın. Hiçbir şey üzmedi beni, Yokluğunun üzdüğü kadar... Gülmeyi yükleyip kuşun kanadına, A...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kuzu']::text[], 8.5, '{"poet":"Hatice Kuzu","poet_slug":"hatice-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sende-kalsin-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Doğum Günü (On Sekiz)', 'bir-dogum-gunu-on-sekiz-alper-mutlu-nhhvx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün benim doğum günüm

Ne değişti dünden bugüne

Dün kalktı geldi bugüne

Ben aynıyım, insanlar aynı

Gönül aynı, yürek zaman içinde

Hayat benim, ben hayatın peşinde

Yaşadığım yalnızlık bile aynı

Farkı ben yaşıyorum sensizce, sessiz

Dün on yediydim, bugün on sekiz

Bugün benim doğum günüm

Kısa bir sene on iki uzun ay eksilen ömürden

Üç yüz altmış beş gönül yaprağı eskiyen

Yazarken geçiyor zaman sonra düşünürken

Zaman ırmağı durmadan akıyor bilinmeze

Değişen ne ki, gönül yine senin sevginde 

Soruyorum kendime: “Zamanın neresindeyiz.”

Dün on yediydim, bugün on sekiz

Bugün benim doğum günüm

Bir aralık sabahı başlayan yolculuk

Duracak sanki, gitmiyor. Tarih: Beş aralık

Ben zamandan çalıyorum, zaman ömürden

Ömrüm sevgiden çalıyor sevgi benden anlasana

Zaman sonsuza birikiyor ben sana duysana

Zaman hırsız, dünya ıssız, insan derya, deniz

Dün on yediydim, bugün on sekiz

Bugün benim doğum günüm

Zaman ah zaman sevginin katili

İnsanda yol alıyor yolcu misali

İnsan yalnız geldi, kendisini alıp gidecek

Bulursa bir de sevgi götürecek

Ben geldiğim gibi gideceğim, sensiz

Dün on yedi ise bugün on sekiz

Dün vardı, bugün var

Yarın belki de apansız...', 'Bugün benim doğum günüm Ne değişti dünden bugüne Dün kalktı geldi bugüne Ben aynıyım, insanlar aynı Gönül aynı, yürek zaman içinde Hayat ben...', ARRAY['Türk Edebiyatı','Şiir','Alper Mutlu']::text[], 8.5, '{"poet":"Alper Mutlu","poet_slug":"alper-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-dogum-gunu-on-sekiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim', 'sensizim-alper-mutlu-t0ous', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin olmadığın bu yerlerde 

Sevgimim gıdasıdır şiirler

Senin gelmediğin bu şehirlerde

Aşkımın yoldaşıdır şiirler

Senin basmadığın topraklarda

Mezarımdır şiirler, ölümümdür şiirler

Senin olmadığın bu yerlerde

Sevdalar büyütürüm gözü yaşlı

Gelmediğin bu şehirlerde

Dağ dağ gibi değildir, deniz deniz

Sevdalar da yalandır artık

Bir ben varım ağır sevdalı

Bir de ben gözü yaşlı, yüreği yaslı

Senin uğramadığın mekanlar, zindanım

Sevmediğin çiçekler bile, prangam

Yürümediğin yollar, çıkmaz ki sevdalara

Solumadığın havalar, boğar artık beni

Olmadığın bu yerlerde, ben yokum artık

Allah’a ısmarladık', 'Senin olmadığın bu yerlerde  Sevgimim gıdasıdır şiirler Senin gelmediğin bu şehirlerde Aşkımın yoldaşıdır şiirler Senin basmadığın topraklar...', ARRAY['Türk Edebiyatı','Şiir','Alper Mutlu']::text[], 8.5, '{"poet":"Alper Mutlu","poet_slug":"alper-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensizim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay, Yıldız, Sema', 'ay-yildiz-sema-alper-mutlu-ct9ka', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine size döndüm dostlar, yine size döndüm

Sizden vefalı dost yokmuş, yaşadım, gördüm

Yine sizinleyim, yine size döndüm

Sizin kadar kimse anlamazmış beni 

İhanet vurgunu yaradır yüreğimde ki

Beni aranıza alın dostlar, arkadaş kalın

Derdime yine siz sırdaş olun

Dostluk kurmak zor, yıkmak kolaymış

Herkes gider de insanın yanına dost kalırmış

İnsana en çok dost lazımmış, anladım, döndüm

İzin verin hep sizinle kalayım dostlar

Sevgi yüklü sema, umut yüklü hilal,yıldızlar

Sen söyle yıldız kardeş, ben de sizden değil miyim? 

Ben de sizler gibi yalnız değil miyim? 

Hep sizinleyim dostlar, geride kaldı yalnızlıklar

Gerçek dünyada hep hayalmiş dostluklar

Hayal dünyamın gerçek dostları sizinleyim

Ben bu dünyanın insanı olamam, değilim

Ben yıldızların yareni, ben hilalin bekleyeniyim

Ben semanın bekleyeniyim, o dünyaya aidim

Ben...

Yine size döndüm dostlar, yine size döndüm', 'Yine size döndüm dostlar, yine size döndüm Sizden vefalı dost yokmuş, yaşadım, gördüm Yine sizinleyim, yine size döndüm Sizin kadar kimse an...', ARRAY['Türk Edebiyatı','Şiir','Alper Mutlu']::text[], 8.5, '{"poet":"Alper Mutlu","poet_slug":"alper-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ay-yildiz-sema-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatılmaz', 'anlatilmaz-alper-mutlu-qis79', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne anlatayım sana, sen beni hiç anlamadın ki

Sevgimi söyleyim desem, sen beni hiç sevmedin ki

Hiç yoktum senin için değil mi

Hiç olmadım, belki de azdım

Ne yaptıysam senin için

Sabahladım, uykusuz kaldım senin için

Sonsuza uçtum, yalnız kaldım senin için

Aşkına yandım, şiirler yazdım senin için

Bu yaptıklarımın hepsi benim için

Sevmek benim için, umut, sevda, yalnızlık benim

Yaptığım tek şey senin için

Kendimden vazgeçmek

O da seni sevdiğim için', 'Ne anlatayım sana, sen beni hiç anlamadın ki Sevgimi söyleyim desem, sen beni hiç sevmedin ki Hiç yoktum senin için değil mi Hiç olmadım, be...', ARRAY['Türk Edebiyatı','Şiir','Alper Mutlu']::text[], 8.5, '{"poet":"Alper Mutlu","poet_slug":"alper-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anlatilmaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Aşk', 'i-simsiz-ask-alper-mutlu-418yb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnanır mısın, ismini bile bilmiyorum

Seni tanıyor gibiyim yüzün yabancı değil

Günler oluyor ki yüzünü görmüyorum

Ama güzel gözlerin uzak değil

Ben seni böyle seviyorum

Bu yaşadıklarım aşk olsa gerek

Aşkın kalbime dert değil

Ben seçtim bu derdi severek

Bu dert gönlüme yük değil

Taşıyorum bu yükü bilerek, isteyerek

Biliyorum sen aradığım gerçeksin

Sevdanın büyüsü tuzak değil

Seni seviyorum desem belki güleceksin

Benimkisi aşk, boş değil

Bunu sen anlamalı, sen bilmelisin

Karşında titriyorsam bil ki korkumdan değil

Seni sevdiğimdendir...', 'İnanır mısın, ismini bile bilmiyorum Seni tanıyor gibiyim yüzün yabancı değil Günler oluyor ki yüzünü görmüyorum Ama güzel gözlerin uzak değ...', ARRAY['Türk Edebiyatı','Şiir','Alper Mutlu']::text[], 8.5, '{"poet":"Alper Mutlu","poet_slug":"alper-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isimsiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlı Çınar Ve Çocuklar', 'yasli-cinar-ve-cocuklar-k-muran-esen-xrbci', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşlı çınarın

Yorgun yıllar omuzlarında

Ama

Gözlerinde ışık var

- ki - 

Yedi rengi içmiş

Gökkuşağından

Rengi / kardan beyaz.

Mevsim kışa  gebe

Dışarısı

Ayaz mı ayaz.

Her bir perçemine

İlişmiş

Bir çocuğun yüreği,

Ellerinde çiçekler

Gözlerinde özlem

Bağırıyorlar bir ağızdan

Avaz avaz.

“Öğretmenim! 

Sakın kapatma gözlerini

Düşeriz sonra göz bebeklerinden

Dinle bak

Yürek çırpıntılarımızı

Ellerimizi tut hele,

Sana geldik

Beş yıllık özlemle

Al eline kalemi

Haydi yaz! 

Çocuklarım, de

Sizi seviyorum, de

Aç

Kocaman yüreğinin kapısını

Üşüdük! 

Gözlerinden inip 

Sıcacacık yüreğinde

Konaklayalım biraz.”', 'Yaşlı çınarın Yorgun yıllar omuzlarında Ama Gözlerinde ışık var - ki -  Yedi rengi içmiş Gökkuşağından Rengi / kardan beyaz. Mevsim kışa  ge...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yasli-cinar-ve-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Duvarında Umut Yazıları', 'siir-duvarinda-umut-yazilari-atakan-aktas-bqpat', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'artık kitap oluruz değilmi

''kitap olur 

umut yazarız 

gönüllerden fırça çalar boya çalar 

şiir duvarlarını umuda boyarız 

geceleri şiir yazıp

gündüzleri küstürüp 

aşıkları kızdırıp 

illede şiirmi şiir yazarız 

yaz gönlünün yettiğince yaz 

sen kimseye uyma 

yüreğinden gülüşü eksik etme 

umudun adı bir tutam gülüştür 

paylaşımın tadı bir içimlik kahve gibidir ya

birazda bundan 

hani 40 yıllık hatır birazda acı keyif

yazmaktan utanmadan kormadan yazarız', 'artık kitap oluruz değilmi ''kitap olur  umut yazarız  gönüllerden fırça çalar boya çalar  şiir duvarlarını umuda boyarız  geceleri şiir yazı...', ARRAY['Türk Edebiyatı','Şiir','Atakan Aktaş']::text[], 8.5, '{"poet":"Atakan Aktaş","poet_slug":"atakan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siir-duvarinda-umut-yazilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiten Dostlarım Geldi Aklıma', 'yiten-dostlarim-geldi-aklima-melih-coskun-a6gwn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yiten dostlarım geldi aklıma

Gülen yüzleri hiç gelmedi gözlerimin önüne 

Herkesten çok şey bilmek

Herkesten biraz daha önce gitmeyi gerektiriyordu belki 

Dünyayı sevmek 

Gerçekten de onunda bizi sevmesini gerektirmiyordu. 

Kahraman olmanın tanımı bu olmalıydı: 

Sevilmemeyi göze alarak sevebilmek 

Uğruna hayatını göze aldıklarının 

Silahından çıkan bir kurşunla ölebilmek 

En son ne zaman gülmüştük doyasıya çoktan unutmuşuz 

Canlandıramıyorum gözümde 

En fazla ne kadar sürer

‘Çok mutlu olmak’ diye bir şey 

En fazla kaç gece

Uyuyabilir insan kafasını koyar koymaz yastığına 

Yiten dostlarım geldi aklıma 

Gülen gözleri bir kere bile gelmedi gözlerimin önüne...', 'Yiten dostlarım geldi aklıma Gülen yüzleri hiç gelmedi gözlerimin önüne  Herkesten çok şey bilmek Herkesten biraz daha önce gitmeyi gerektir...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yiten-dostlarim-geldi-aklima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yol Dosta Çıkar', 'her-yol-dosta-cikar-salih-ozalasan-c6mtt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatın varmıdır bir anlamı? 

İçmemişsen dost elinden bir bade

Boşa mekan eylemişsin Dünya denen hanı

Hayatın ne kadar geçse de sade

Eylemelisin bir kulu

Candan dost daim yüreğine

Dost kapısından geçer hakkın yolu

Kul kötü demek bir bahane

Dost elinden çeksen de bin bir çile

Satsa da vefasızca seni bir pula

Dost elinden sarılsan da bir çula

En vefakar dost kara toprak; sarar seni  koynuna

Her yol dosta çıkar sakın unutma

Y.Tarihi 24-03-2004

Salih ÖZALAŞAN', 'Hayatın varmıdır bir anlamı?  İçmemişsen dost elinden bir bade Boşa mekan eylemişsin Dünya denen hanı Hayatın ne kadar geçse de sade Eylemel...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/her-yol-dosta-cikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Gel', 'bize-gel-sabit-i-nce-iqzcr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arif olup şu cehalet dağını,

devirmek istersen gel gel bize gel.

koparıp kırdığın gönül bağını,

çevirmek istersen gel gel bize gel.

Kaypak zeminlerden kirli oyundan,

dönmek ister isen gel gel bize gel.

sevda pınarından aşkın suyundan,

kanmak ister isen gel gel bize gel.

Tutulup da bir Leyla''nın aşkına,

yanmak ister isen gel gel bize gel.

sevdanın çölünde dönsen şaşkına,

onmak ister isen gel gel bize gel.

Gönlümüz kapısız açtık ardına

girmek ister isen gel gel bize gel.

İnce bir yuva yap gönül yurduna,

görmek ister isen gel gel bize gel.

17.3.2004 Kayseri Sabit İnce', 'Arif olup şu cehalet dağını, devirmek istersen gel gel bize gel. koparıp kırdığın gönül bağını, çevirmek istersen gel gel bize gel. Kaypak z...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bize-gel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koyu Bir Sessizlikteyim..', 'koyu-bir-sessizlikteyim-nazife-abayli-s2ewk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koyu bir sessizlikteyim,

Seni beklemekteyim.

.......................................

Duyar gibiyim,

Yirmi üç otuz tramvayının uğultusunu.

Boğulmak üzereyken ben sensizlikten,

Dağıtır gecenin koyuluğunu.

....................................................

Ama...

Ne, yirmi üç otuz tramvayı görünür uzaktan,

Ne de sen! 

.........................................

Koyu bir sessizlikteyim,

Seni beklemekteyim.! !', 'Koyu bir sessizlikteyim, Seni beklemekteyim. ....................................... Duyar gibiyim, Yirmi üç otuz tramvayının uğultusunu. Bo...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/koyu-bir-sessizlikteyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Işık Kurtaracak Beni..', 'o-isik-kurtaracak-beni-nazife-abayli-dujny', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kör karanlığa yenilmiş,

Derin bir uykuya dalmışım.

Ana rahminde büyümeyi bekleyen,

Masum bir cenin gibi,

Büzülmüşüm.

Kaldıramıyorum başımı.

Bakamıyorum sağıma soluma.

Her yandan,

Korkunç yüzler,

Buruşmuş derili,kocaman çirkin eller,

Yakalayacaklar,çekecekler yuvalarına beni.

Top olmuş yuvarlanıyorum,uçuyorum adeta,

Korku tünelinde,dibi bilinmez bir boşluğa.

Bir ışık yansıyor gözüme,

Çok uzaklardan,

Tünelin bir ucundan.

Biliyorum,

O ışık kurtaracak beni,

Yaratıklardan,

Korkularımdan,

Çekilmez yalnızlığımdan...', 'Kör karanlığa yenilmiş, Derin bir uykuya dalmışım. Ana rahminde büyümeyi bekleyen, Masum bir cenin gibi, Büzülmüşüm. Kaldıramıyorum başımı. ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/o-isik-kurtaracak-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-gokhan-oflazoglu-5afq9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tanrım, nerde hata yaptın,

bunca acı; değer miydi..? 

Günlerimiz ateşin içinden 

geçer, sonra gelin buraya.

Ama, bir kelebek konar duvara

hepsini unuturuz, bahar gelir

kanatlarında; artık, yanına da

alsan kimin umurunda.', 'Tanrım, nerde hata yaptın, bunca acı; değer miydi..?  Günlerimiz ateşin içinden  geçer, sonra gelin buraya. Ama, bir kelebek konar duvara he...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kelebek-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık...!', 'gel-artik-hasan-basri-kale-aj2ei', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel artık........../Çık gel..! 

Kamaşsın gözlerim.

Bir gel de/tutulsun dilim

bitsin mürekkebim..

Göremesem de/konuşamasam da

yazamasam da.../razıyım

Gel de..

Takılsın gönlüm peşine 

ardında sürünsün..

Canlı/cansız..hepsi/herşey

sen olsun/sana bürünsün..

Silinsin hafızamda

senden başka ne varsa..

Yeter/bitsin kelimeler/dizeler..

Zamanıdır artık

sussun sonsuza kadar şiirler..!', 'Gel artık........../Çık gel..!  Kamaşsın gözlerim. Bir gel de/tutulsun dilim bitsin mürekkebim.. Göremesem de/konuşamasam da yazamasam da......', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-artik-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAVET Suvari Gönül', 'davet-suvari-gonul-mustafa-celebi-cetinkaya-q1cqi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suvari umutlar...

ve  sulh akınına çıkmış deli bir gönül

var olma telaşının en son deminde,

ki yitirip özveriden gayrı olan tüm serveti

yüreğimde efsunlu   bir sevda

ve gözlerimde Ömer’in  adaleti.

Silkinip atıversem bütün öfkeleri  üstümden 

sonra her mevsime bir destan dökse inayetim, 

kavuşmanın özlemiyle ateşe düşmüş anılar,

suvari umutlar...

Ve acı   ...

korsanı olmuş hayal  ufkumun 

sarıp sarmalamış avare sabahlar geceyi

kucaklayıp bir başımalığımı 

kucaklayıp  sonra vuslata uzanan karanlığı 

kanrevan içinde kalmış gözlerimden dökülen her damla yaş

ve her solukta aşkı zikreden bedenim

suvarin olayım; yollarında ölemedim.

işte tecelligahım, sevda  mabetim,

gönülde ittifak kurmuşş hissiyat

ve seninle yaşanır inan; Venüste, Mars’ta

dünyada seninle ranalaşıyor hayat

sar...

kollarınla sar,  kudretinle sar

firakın bağrında yanan öylesi bir köz,

killenmiş topraklardan oluşmuş bu bedende

bir damla suya ravi yüreğim 

bütün denizler sana varır  her demde

bütün nehirlerin kavuştuğu sensin bilirim...

Suvari  gönül! ...

öyle bir yangınla yanmalara doymadan 

ve ıramışlığın üzerine çekilen bentler

Gel hadi...

duy ki senin için davet çıkarmış mabetler....

2004', 'Suvari umutlar... ve  sulh akınına çıkmış deli bir gönül var olma telaşının en son deminde, ki yitirip özveriden gayrı olan tüm serveti yüre...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/davet-suvari-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Diyor!', 'kim-diyor-zafer-zengin-etnika-q24ec', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kim

Diyor 

Sana! 

Kahverengi

Gözlerinde

Dünya''nın

Işığını 

Sakla

Mumlara

Muhtaç 

Et

Bizi

Kim! 

Çekinme! 

Yanağıma

Sakla

Ellerini

Öpmem

Korkma...

24 mart 2004', 'Kim Diyor  Sana!  Kahverengi Gözlerinde Dünya''nın Işığını  Sakla Mumlara Muhtaç  Et Bizi Kim!  Çekinme!  Yanağıma Sakla Ellerini Öpmem Korkm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kim-diyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendisini Bekliyor!', 'efendisini-bekliyor-zafer-zengin-etnika-2im99', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Efendisini

Bekliyor! 

GECE

Sessizlik...

Sessizlik...

24 MART 2004', 'Efendisini Bekliyor!  GECE Sessizlik... Sessizlik... 24 MART 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/efendisini-bekliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür', 'sukur-i-brahim-ethem-bingul-xk2jq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baharım,hazanım oluyordu

Tam çiçeklerim açarken,soluyordu

Hayatımın yazı,kışa giriyordu

Bir hastalık alıp beni gidiyordu

Allah''ım lutfetti,merhamet etti

Bilinmez severlerin duasını kabul etti

Tekrar döndürdü

Bu dünyada biraz daha çek dedi

Yaradılış gayesine uymak

Sevilip,sevmek

Ne güzel böyle yaşamak

Ne  güzel böyle aranıza dönmek', 'Baharım,hazanım oluyordu Tam çiçeklerim açarken,soluyordu Hayatımın yazı,kışa giriyordu Bir hastalık alıp beni gidiyordu Allah''ım lutfetti,m...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sukur-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.::YENiDEN BAŞLASAK::.', 'yeniden-baslasak-baki-son-l2gwk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güçsüz bir yaşantıdan

Sonsuz

Kayboluşlar yığılır üstümüze

Bu dipsiz kuyularda 

Birikir...

Yalnızlığımız.! 

Bilinçsiz,

Yıllar kemirir ömrümüzü.

Ümitsiz çöl akşamları

Fırtına mı kopar,

Yer mi yarılır bin yerinden.? 

Yoksa

Bir yarın mı var unuttuğumuz...! 

Bu huzursuz kıvranışta

Aydınlık yarınlar,

Arasak,

Düşlerimize.! 

Bu bilinçsiz karanlığa

Işık arasak...

Güçsüz yaşantılar

Ve mutsuz aramalarda solar,

Kanat çırpışlarımız...

Dirensek,

Sonrasız yok oluşlar,

Yığılır üstümüze...

Yıldığımız,

Küçücük olduğumuzda,

Sözde mutluluk sunar

O büyük kaçış.

O güçsüz uyuklayış içinde,

Bir fısıltı,

Bir kutsal yüzdür

Eğilir üstümüze...

Soyunsak

Bu sinsi güçsüzlüğü,

Eski çağlara...

Bu büyük yorgunluk dinse.! 

Yıksa...

Kaybolan,kayboluşu

Aydınlık

Ve berrak uyanışlarla

Bir sabah dipdiri

Mutlu bir dünyaya 

/uyansak...! ! ! 

YENİDEN BAŞLASAK......', 'Güçsüz bir yaşantıdan Sonsuz Kayboluşlar yığılır üstümüze Bu dipsiz kuyularda  Birikir... Yalnızlığımız.!  Bilinçsiz, Yıllar kemirir ömrümüz...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yeniden-baslasak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-kenan-yesilyurt-i2hzg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasret nasil anlatilabilirki en iyi

Ben bile bilmiyorum

Bunca yillardan sonra

Hasret bence bir esarettir en iyi', 'Hasret nasil anlatilabilirki en iyi Ben bile bilmiyorum Bunca yillardan sonra Hasret bence bir esarettir en iyi...', ARRAY['Türk Edebiyatı','Şiir','Kenan Yesilyurt']::text[], 8.5, '{"poet":"Kenan Yesilyurt","poet_slug":"kenan-yesilyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hasret-153-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Şerbeti', 'askin-serbeti-hikmet-karakus-wqq3r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Farkında bile değilim; 

 akşamdan sabaha açan çiçeğin

     börtü böceğin

         yaşama sevincinin...

Kaotik bir yaşamın körlüğünde

       kim bilir daha neler kaçırıyorum? 

Oysa mutluluk için neler yapmazdım ki...

Belki sevgilimin gözlerinde tutuşurdum 

                                 kırmızı bir gül gibi...

Belki aşkın şerbeti olurdum

                bal gibi dudaklarda...

Belki de uğur böceği olurdum

          bir yürek gibi çırpınırdım

                bir avuçtan bir avuca

                                       aşk ile...

(Muğla 2003)', 'Farkında bile değilim;   akşamdan sabaha açan çiçeğin      börtü böceğin          yaşama sevincinin... Kaotik bir yaşamın körlüğünde        ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-serbeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Okulu Mezunlari 1.Kutlama Günü', 'dunya-okulu-mezunlari-1-kutlama-gunu-ahmet-kose-aqtz2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eski evimizin bahçesinde ilk baharın ilk damlalarında

erik ağacına yaslanmıştım...İtalyan eriği olanın hani...! 

diz çöküp

dudaklarımı  büzüştürüp

sıkılırken çocuk ruhum.

Sen çıktın geldin yanıbaşıma gülerek

her zamanki gibi..

tutuştuk el ele

- gülüşelim

- oynaşalım

dedin:

'''' bu onulmaz dünyada''''

Seni tuttum

sana baktım

son gördüğüm gibiydin

bu hayatın tarihi yüzünde

hangi tarihten başlayım der gibiydi ağzının duruşu.

Bir sürpriz geldi usuma

seni götürecektim bulutların yakınlarına

görmediğin

gitmediğin

ama sanırım bildiğin yerlere

insanlığa

sıcaklığa

ruhun mayasına

kucaklaşmaya

Nirvana ya

yaaaa...! 

bu da benim sürprizim

Budaaaa...! 

yaşayan erenlere

sana yakın gördüğüm aleme

dolaştık aralarında

sürtünerek

salıvererek ruhumuzu

dinleneyim dedin:

bi sigara molası...! 

Vakit geldi:

Süzüldük yollarımıza

indik ayrıldığımız kavşakta.

Elini usulca bırak dedim:

Sana.! 

bilinmesin ayrılığımız

o hissi bilmeyelim

di mi..? 

usulca

gittin

kokun gitmeden gözümden

burnumdan...yüreğimden

usulca,sessizce,görmeden

bakmadan arkamıza

uzak olduk birbirimize

kalmadan arkamızda gözümüz

beş yüz yirmibeş bin altı yüz dakika

sekiz bin yedi yüz altmış saat

üç yüz altmış beş gün

elli iki hafta

bir yıl.

Böldükçe küçülüyor ayrılığımız 

Sevgili Dünya Okulu Mezunu Babam...! 

Master yapma ne olur.....:(((((

Dünya Okulu Öğrencisi Oğlun...Kutluyorum Seni....

25/Mart/04/bitez-bodrum', 'Eski evimizin bahçesinde ilk baharın ilk damlalarında erik ağacına yaslanmıştım...İtalyan eriği olanın hani...!  diz çöküp dudaklarımı  büzü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/dunya-okulu-mezunlari-1-kutlama-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-funda-kocaoglu-lp89z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün biterse anlattigin masallar..

Açarsam bir furyadan gerçege gözlerimi.

Farkinda olursam,bir perdede yasadigimi bu aski.

Alkislari duymadan gidecegim sevgili..

Son oyunumuz seninle..son selam verisimiz insanlara beraber.

Gidecek seyirciler birazdan,kalacagiz bir basimiza.

Çare buysa eger,yalnizliksa lazim gelen..

Hasret girecek öyleyse,bir bütün aramiza.

Bahçemi sulamayi unutma,lalelerim sana emanet.

Bilirsin çiçeklerin çabucak kurudugunu.

Belkide bir  saksiya alman gerekebilir.

Nasilda unuttum,çiçeklere allerjin oldugunu.

Peki ben nasil alisacagim sensiz bir dünyaya? 

Zor biliyorum senin icinde çok zor.

Basarabilirmiyiz? saniyorsun amansiz bir vedayi? 

Içimde yanardaglar,DEPREMLER yer buluyor

Ve yine kan ter icinde sabah oluyor canim! 

Dilsiz oyunlarimin tek sufloru

Ve kara bir perdede,arat geçtik sevgimizi

Bir meçhule  gidiyor,bir zifirde sebebi, Günaydinim', 'Birgün biterse anlattigin masallar.. Açarsam bir furyadan gerçege gözlerimi. Farkinda olursam,bir perdede yasadigimi bu aski. Alkislari duym...', ARRAY['Türk Edebiyatı','Şiir','Funda Kocaoğlu']::text[], 8.5, '{"poet":"Funda Kocaoğlu","poet_slug":"funda-kocaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgili-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sardunyalar', 'sardunyalar-funda-kocaoglu-upadu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eger düsersen birgün yanaklarima bir ikindi günesi..

Ufka dogru bir bak,ve gör beni kanat çirpan martilarda.

Limana ramak kala batan denize girsin tenin.

Bul beni,o ISSIZ,o ACIMASIZ,o derin sularda.

Sardunyalar açmasin baharsiz bir yokluga.

Perdeni yarim birak,girecegim her sabah.

Zifirinde biraktim yüregini bir deli yalnizliga.

Bu senin hasretin olmamali,günah günah.

Ve lades agaçlari altinda bekliyorum gelmeni.

Belki bir melodi,belkide bir yagmurla dokun bana.

Çam kokusu gibi daglarimda esmelisin.

Bir anne kadar muhtacim sana.', 'Eger düsersen birgün yanaklarima bir ikindi günesi.. Ufka dogru bir bak,ve gör beni kanat çirpan martilarda. Limana ramak kala batan denize ...', ARRAY['Türk Edebiyatı','Şiir','Funda Kocaoğlu']::text[], 8.5, '{"poet":"Funda Kocaoğlu","poet_slug":"funda-kocaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sardunyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitsiz bir kus', 'umitsiz-bir-kus-funda-kocaoglu-vjtus', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir atom faciasi,bir açik yara...

Bir ihanet,bir yalan.

Bir gözyasi,bir yalnizlik elde var..

Istemem olmasin senden geriye kalan.

Gönül,isterki,elektirik tellerinde ölesi bir kus.

Konakalsin her özlediginde balkonuna.

Hani o siirlerin funda otelinde bir oda.

içi acilarla kurulu bir  yuva.

Ruhumu azad eden,kafesin sahibi..

Asil o kiydi,benim gibi kuslara..

Kanatlarima pranga takti unutuldum gercegi.

Çirpinamiyorum,ufku sonsuz yarinlara.

Yok bu siirin ne dünü,ne gelecegi.

Bir sapaninda olsa vuramazsin bir daha

En ulasilmaz yanlarindan sen vurdun bu serçegi.

Adiyorum kendimi,hapsettigim daglara..', 'Bir atom faciasi,bir açik yara... Bir ihanet,bir yalan. Bir gözyasi,bir yalnizlik elde var.. Istemem olmasin senden geriye kalan. Gönül,iste...', ARRAY['Türk Edebiyatı','Şiir','Funda Kocaoğlu']::text[], 8.5, '{"poet":"Funda Kocaoğlu","poet_slug":"funda-kocaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umitsiz-bir-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saatler', 'saatler-ersan-kurt-lfgiz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sığmadan yıllara gömülmüşüz saatlerin içine.

Farkında olmadığımız, çizgilerdir alnımızda taşıdığımız.

Bir de birlikte olamadığımız o koskoca saniyeler.

İçimizdeki aşkın saati durmadan,

birleşebilseydi akreple yelkovan! 

Mutluluğu tarif etmeye gerek kalır mıydı sence

saniyeler koşsa önlerinden.

Şubat 2004, Kuzey Denizi', 'Sığmadan yıllara gömülmüşüz saatlerin içine. Farkında olmadığımız, çizgilerdir alnımızda taşıdığımız. Bir de birlikte olamadığımız o koskoca...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saatler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sersi Tepelerinin Kartalı', 'sersi-tepelerinin-kartali-bora-alagoz-vetxh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ey otorite, başarının ulu tanrıçası 

sımsıkı sarsın ellerim yalazlı kılıcını 

ki tırkan topraklarında dik dursun başım 

ey uyumlu devingenliğin kırbacı 

ben başarının memesinden emzirilen 

uçurumların tepesinde mi yürüyorum 

yürüyeceğim 

bu hain sinsice bakan gözler 

boşuna arayacaklar 

uçurumların gölgesinde bedenimi 

ruhumun dingin süvarilerini çarmıha gerip 

büyük bir ateş yakacağım önlerinde 

bir papu dansörü gibi döneceğim etrafında 

yetişip çöl çakallarına yarı yolda 

yüzdürüp derilerinden davul yaptıracağım 

Nizip aptallarına 

ey sersi tepelerinin çelik kanatlı kartalı 

kalk tündüğün kayalıklardan kalk artık 

yüksel göğün maviliklerine doğru 

görsün görkemini çaylaklar kargalar yarasalar 

görsün gücün azametini', 'ey otorite, başarının ulu tanrıçası  sımsıkı sarsın ellerim yalazlı kılıcını  ki tırkan topraklarında dik dursun başım  ey uyumlu devingenli...', ARRAY['Türk Edebiyatı','Şiir','Bora Alagöz']::text[], 8.5, '{"poet":"Bora Alagöz","poet_slug":"bora-alagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sersi-tepelerinin-kartali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işığın Sürgünü', 'isigin-surgunu-hamit-kunt-m1dpv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece…Işığın sürgünde olduğu zaman dilimine verilen isim.Ama ışık sürgünde olduğu yerleri de aydınlatıyor şimdi.Batışla başlayan karanlık,doğuşla yok olacak.ve bu devran her gün sürecek.Mevsimler de öyle.Baharla uyanan,coşan doğa,yazla olgunlaşacak,güz çiçekleri yepyeni kıvılcımlar,sürpriz armağanlar,müjdeli haberler sunacak umut mahkumlarına.Ben ağlarken sen seviniyor,sen aç iken ben tok olabileceğim.Ruhunda bir yerlerin hiçbir şeyden tatmin olmadığını hissedeceksin hep.Bazen ağlamak,hıçkıra hıçkıra ağlamakla ferahladığını duyacaksın yüreğinin uğradığın ihanetlerden.İntikamla affetmenin er meydanına dönecek yüreğin.Ya intikamla yüreğini de öldürecek,ya da af enginliğinde ruhunda başka canlar dirilteceksin.Bir tek hücre değil mi varlığımızın orjini! O hücrenin kendini kendisiyle paylaşmasıyla değil mi  tamamlanmış insan oluşumuz! varlığı paylaşmak,temel borcumuz o zaman,kendimize ve insanlığa olan borcumuz.

       Eve geç geldim,biraz karaladım,ve paylaşmak istedim.sevgi yüreğinizden hiç eksik olmasın…

                                                                                               25-03-2004

                                                                                              Üsküdar 02,38', 'Gece…Işığın sürgünde olduğu zaman dilimine verilen isim.Ama ışık sürgünde olduğu yerleri de aydınlatıyor şimdi.Batışla başlayan karanlık,doğ...', ARRAY['Türk Edebiyatı','Şiir','Hamit Kunt']::text[], 8.5, '{"poet":"Hamit Kunt","poet_slug":"hamit-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/isigin-surgunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar Hey', 'yollar-hey-hamit-kunt-wh9ph', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar Hey

Şu üç günlük denen dünya yurdunda

Kimse bilmez kimler neyin derdinde

Bir sevenim varsa dağın ardında

Aşka doğru götür beni 

yollar hey…

Al beni

Kaçır beni

Dağlardan aşır beni

İçimden uçur beni 

Yollar hey…

                            21 Mart 2004

                              Üsküdar', 'Yollar Hey Şu üç günlük denen dünya yurdunda Kimse bilmez kimler neyin derdinde Bir sevenim varsa dağın ardında Aşka doğru götür beni  yolla...', ARRAY['Türk Edebiyatı','Şiir','Hamit Kunt']::text[], 8.5, '{"poet":"Hamit Kunt","poet_slug":"hamit-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yollar-hey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün', 'gulun-zafer-zengin-etnika-34a8e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülün

Rengini

Ben

Yazmadım

Rengi

Kan''dan

Adı

Bana

Yazılmış

Soy 

Ağacı

Candan...

25  Mart 2004', 'Gülün Rengini Ben Yazmadım Rengi Kan''dan Adı Bana Yazılmış Soy  Ağacı Candan... 25  Mart 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gulun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara (Şarkı Sözü)', 'ankara-sarki-sozu-umit-kilislioglu-ozger-9j7wf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Niye sevdim seni bilmem bu kadar, 

Çok alıştım gurbet elde duramam; 

Başka şehir, başka diyar bana dar,

Başka yerin hayalini kuramam.

Nakarat:

Ankara’da kar başkadır 

Yaz başka bahar başkadır

Gündüz başka, gece başka

Ankara''lı yar başkadır

		

Evim barkım, sevdiklerim, okulum,		

Hepsi sende ben ne şanslı bir kulum; 

Bütünleştim seninle çıkmaz izin,

Seviyorum olmasa da denizin.

Nakarat:

Ankara’da kar başkadır 

Yaz başka bahar başkadır

Gündüz başka, gece başka

Ankara''lı yar başkadır

Tarih sende okunuyor, çağ çağ,

Türkiye’nin kalbi sende atıyor; 

Bir tarafta başı karlı Elmadağ,

Gözbebeğim Atam sende yatıyor.

Nakarat:

Ankara’da kar başkadır 

Yaz başka bahar başkadır

Gündüz başka, gece başka

Ankara''lı yar başkadır

(Bu güfte, tarafımdan nihavend makamında bestelenmiştir)', 'Niye sevdim seni bilmem bu kadar,  Çok alıştım gurbet elde duramam;  Başka şehir, başka diyar bana dar, Başka yerin hayalini kuramam. Nakara...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ankara-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanmısınız?', 'i-nsanmisiniz-ali-osman-yilmaz-qwuq6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bütün kadınlar aynı,

Hiç fark yok,birbirlerine benzer,

Ya erkekler? Farklımı,

Onlarda aynı,tıpkısının kopyası,

Aynı hamurun parçaları,

Kadınlar ve erkekler,

Hık demişçesine  hemcinslerinin,

Sanki burunlarından düşmüşler.

Ama insanlar öyle mi? 

Hepsi başka başka bir resim,

Her biri başka bir şiir,

Bakarsın insanlara,

Özlemlerini,duygularını bulursun,

Bir de tenine dalarsanız,

İşte o an muhteşemdir,

Bir daha yaşanmaz gibi gelir zaman,

Yeniden yaşamak istersiniz onu,

Hatta,canınızı bile severek verirsiniz,

Çünkü insandır O.

O nu yaşamaktan zevk aldığınız,

O zevki,O anı,O hazzı yaşamak için,

Bakın kendinize bir,bakın,

Siz kadınlar,ve erkekler,

İnsan mısınız?', 'Bütün kadınlar aynı, Hiç fark yok,birbirlerine benzer, Ya erkekler? Farklımı, Onlarda aynı,tıpkısının kopyası, Aynı hamurun parçaları, Kadın...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/insanmisiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Çeşit İnsan Vardır', 'i-ki-cesit-i-nsan-vardir-ali-osman-yilmaz-ivzfu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyada iki çeşit insan vardır,

Doğru şeyi,doğru zamanda yapıp,

Güzel zevklerin tadını çıkaranlar,

Ve doğru şeyleri,doğru zamanda,

Yapmayı beceremiyenler,

Yaptıkları yanlışın üzerine,

Sürekli yanlışa,yanlış saldıranlar.

Ama ben genellikle,

Bir tarafın ağır bastığını bilirim,

Ben doğru kadını,O nu seviyorum,

‘O’ ise yanlışı,egosunu seviyor,

Çoğumuz da,iki türlü davranan,

İnsan karışımı değil miyiz? 

Bir bakın hele,Kime mi? 

Aynadaki  görüntünüze,

Ve dost bildiklerinizin yüzüne,

Aşka,sevdaya,sevginize,

Ne görüyorsunuz? 

Farklı bir şey göremiyeceksiniz,

Tıpkı kendiniz,tıpkı sevgiliniz,

Aynadaki siz,ananız,babanız,

Sokakta gördüğünüz herkes,

Ne kadar da benziyorlar değil mi? 

Aranmayın boşuna hiç,

Aradığınız o mutluluklar,

Aşk dolu güzellikleri,

Yalnız romanlarda veya,

Sinemalarda görebileceksiniz.', 'Dünyada iki çeşit insan vardır, Doğru şeyi,doğru zamanda yapıp, Güzel zevklerin tadını çıkaranlar, Ve doğru şeyleri,doğru zamanda, Yapmayı b...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/iki-cesit-insan-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi Tanımak', 'sevgiyi-tanimak-ali-osman-yilmaz-pe2vn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgiyi tanımak isterim,

İsterim de,olası mıdır tanımak? 

Yalın bir sevgi,

İçinde ben ve sevdiğim olan,

Benden doğan ve,

Beni anlatan,tanımlayan,

Bakıldığında herkes tarafından,

İşte O,İşte O,İşte sevgi bu dedirtecek.

O sevgiyi tanımak,

Aslında anlamak istiyorum.

Derin bir nefes al diyor,

Odamda dolanan bir ses,

Göğsümü yırtarcasına nefes alıp,

Ciğerlerimi dolduruyorum,

Gözlerimi kapıyorum o halde,

İçimdeki beni,

Egoizmden arınmış kendimi,

Bir nefeste dışarıya bırakıyorum,

Sonunda başarıyorum da,

Kafatasımın içindeki O,

Beynimden dalgalar halinde,

Nefesimle birlikte,

Mutluluk türküleri gibi,

Sevinç titreşimleriyle,

Ve aşka olan özlemlerim,

Ve içimde ne kadar,

Mutlu,güzel ve olumlu,

Duygularım birikmişse,

Hepsini nefesimin kanatlarına,

Bindirerek üflüyorum.

Şimdi bahar esintileriyle,

Dağılacak dört bir yana,

Tüm gönüllere dolanacak,

Ve sevgi çiçekleri açacak,

Aşkın tomurcukları kızaracak,

Tertemiz bir dünya ve insanlar,

Bir birlerini severek yaşayacak.

İşte tanımak istediğim,

Anlamak için can attığım,

Sevgi,bu olsa gerek.

Sevgi buysa,mutluluksa,

İnsanları güler yüzlü görmekse,

El ele,gönül gönüle gezinmek,

Göz göze geldiğinde

Şimşekler çakmadaysa,

Buldum ben aradığımı,

Anlamakta zorlanmayacağım artık,

İçimden bir nefesle yollladığım,

O muhteşem duyguyu,

Tanıdım,O sevgiymiş evet,

Sevgiymiş O.', 'Sevgiyi tanımak isterim, İsterim de,olası mıdır tanımak?  Yalın bir sevgi, İçinde ben ve sevdiğim olan, Benden doğan ve, Beni anlatan,tanıml...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sevgiyi-tanimak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Kadınlar', 'haydi-kadinlar-ali-osman-yilmaz-3jv75', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haydi kadınlar,

Ayağa kalkın artık,

Hamurunda ayılık mayası olan,

Bu erkek egemen dünyayı,

Düzeltmek sizin elinizde.

Çingenelerden,

Ayı oynatıcılardan esinlenin,

Yaşanılası bir dünya kurmak için,

Ama insan gibi yaşamak için,

Değiştirin bu ayılı gidişi.

Ama kendinizi de bir sırça köşkün,

Cumbasında bekleyen,O el deymemiş,

Sarayda,haremin kapısında,

Kraliçe yada sultan edilmeyi,

Beklemeden velakin,

Kalkın ayağa,hem kendiniz,

Hem bu erkekler için,

Hem siyasal,hem sosyal düzen için,

Aşkınız için,sevdanız için,sevgi için,

Siz bu kavgada ön almazsanız,

Ayı erkeklerle birlikte

Ayılıklar dünyasında yaşamaya,

Mahkumsunuz.', 'Haydi kadınlar, Ayağa kalkın artık, Hamurunda ayılık mayası olan, Bu erkek egemen dünyayı, Düzeltmek sizin elinizde. Çingenelerden, Ayı oyna...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/haydi-kadinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede Bu İnsanlar', 'nerede-bu-i-nsanlar-ali-osman-yilmaz-sk4l4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde yalnız gezen yıldızlar,

Yer yüzünde yalnızım sizin kadar,

Arıyorum her yerde,

Nerede bu insanlar? 

Altmış sekiz kuşağının,

Sahipsiz bırakılmış genciyim,

Yürek aynı yürek,Bilek aynı bilek,

Bu kavganın verilmesi için,

Adam gibi yürekli insanlar gerek,

Güzel bir dünyaya kavuşmak için,

Güzelliğe iman edenler gerek,

Arıyorum seni,çoban yıldızı gibi,

Gökte değil,yerde olman gerek,

Sevgiye,aşka,güzelliğe ulaşmak için,

Sevgiye aç,aşka aç,sevda ateşinde,

Yanmaya yürekli,sevgili gerek.

Ben varım güzelim,

Varımda; ya sen,

Nerelerdesin,

Kendinden haberin var mı? 

Ya istemlerine,arzularına,sevdana

Ulaşmak için neler yapmadasın? 

Çık kafesinden,kurtul zincirlerinden,

Seni yaşamak isteyen sevdam,

Seni yaşatmak isteyen aşkım,

Beklemekte arzularıyla 

aç gözlerini, gözlerime bak,', 'Gökyüzünde yalnız gezen yıldızlar, Yer yüzünde yalnızım sizin kadar, Arıyorum her yerde, Nerede bu insanlar?  Altmış sekiz kuşağının, Sahips...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/nerede-bu-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Vazgeçilmez Sananlar', 'kendini-vazgecilmez-sananlar-ali-osman-yilmaz-98w1w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir düşünseniz kadınlar,

Oranızın inanç kutusu olmadığını,

İman edilecek bir yer olmadığını.

Hoş biz erkekler de,

Kendimizi,o fazlalığımızı,

Bereket tanrısı görmekten,

Bir vazgeçebilsek eğer,

Onun bereket tanrısı değil de,

Yaşam anahtarı olduğunu,

Açacak bir kilit yoksa,

Hiçbir işe yaramadığını,

Bir bilebilsek,bir anlayabilsek,

Ne kadınlar dişliğiyle,

Ne adamlar erkekliğiyle,

Bulunmaz hint kumaşı olmadıklarını

Kimse,kendi cinselliğiyle,

Kendini vazgeçilmez sanmayacak,

Ama tarih boyunca bize yutturulan,

Erkek egemen toplumda,

Sokaklarda pazularıyla güçlü,

Yatakta bir kadının dişiliğinde,

Süt dökmüş kedi gibi,

Kendini teslim eden o zavallı,

Yaşanılası güzellikleri,İnkar edercesine,

Yataktan çıkınca yeniden,

Vahşi köpek,dayanılmaz ayı,

Ya da,kadınlığını,

Mısır kraliçesi Kleopatra gibi,

Görmeye çalışan kadın.

Hadi gelinde bunun,

Bir orta yolunu bulun.

Ne biz erkekler kadınsız,

Ne siz kadınlar erkeksiz,

Yek başına bir hiç değil miyiz? 

Bir bütün olmak için,

Atacağımız yalnızca bir adım,

Ne kaybedersin bir düşün? 

Ya da ne kazanacaksın? 

Ben erkekliğimi,Sen kadınlığını,

Asıl insanlığımızı kazanacağız.', 'Bir düşünseniz kadınlar, Oranızın inanç kutusu olmadığını, İman edilecek bir yer olmadığını. Hoş biz erkekler de, Kendimizi,o fazlalığımızı,...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kendini-vazgecilmez-sananlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Ve Tual', 'cocuk-ve-tual-k-muran-esen-2e5u2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elindeki tual

Dar geliyordu / çocuğun

Hayalindeki resme.

Sonra  / çocuk

Boşalttı / gözlerinden

Akdeniz dolusu maviyi

Eteklerine.

Ayakları

Tümsekteydi / dağ gibi

Yine de / güneş

Bir türlü doğmuyordu

Üzerine.

Dayadı

Göğsüme / başını,

Küskün dalgaları

Dövüyordu /  bedenimi

Dalga kıranlarım

Bir bir  yıkılıyordu.

Öptüm

Kara yazılı /  ağlamaklı yüzünden,

Nefesi  / açlık

Yanakları

Gözyaşı kokuyordu.', 'Elindeki tual Dar geliyordu / çocuğun Hayalindeki resme. Sonra  / çocuk Boşalttı / gözlerinden Akdeniz dolusu maviyi Eteklerine. Ayakları Tü...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cocuk-ve-tual-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerbet içmişim', 'serbet-icmisim-burhan-kucuk-o69zp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şerbet içmişim

Bu gece yine ben

Yalnızdım...

Yıldızlara baktım

Ay’ı izledim

“Bütünlük yalnızlıktır”

Ah! . iç geçirdim

Ki

Susamış gönlüm

Kalemin kapağını 

Tuttum açtım

Ay’ı okşadım

Yıldızları topladım

Yazdım ilk kelimem

Duvarları yıkan

Göç ettireceğim

Ay’ı, yıldızları

Bir kalemde

Eski çağdan,yeni çağa

Susamış gönlüm

Ah! . bu ay ışığı

Çöpe de vuruyor

Camına da odamın

Kelimeler sıyrılıyor

Eski sözlüklerden

Bir kement gibi

Savuruyorum 

Susamış gönlümün

Tek penceresinden

Ay’a kalemi

Her seferinde

Yıldız yakalıyorum

Odama asıyorum

Gece....

Ay..

Yıldız..

Bir bakış ta

Kana kana 

Şerbet içmişim

Geçiverdi susuzluğum

Burhan KÜÇÜK

Kdz.Ereğli-25.03.2004', 'Şerbet içmişim Bu gece yine ben Yalnızdım... Yıldızlara baktım Ay’ı izledim “Bütünlük yalnızlıktır” Ah! . iç geçirdim Ki Susamış gönlüm Kale...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/serbet-icmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sükût İstanbul', 'suk-t-i-stanbul-esma-ozdemir-f878w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uyuyor İstanbul

Geceyarısında sessiz, sakin

Kocaman İstanbul...

Dev bir kovana benzetiyorum O''nu

Binlerce canlıyı, insanı

İçine alışından.

Tünemiş arılara benzetiyorum O''nu

Bu saatte.

Yalnızca ta uzaklardan

Araç sesleri duyuluyor

Her yanda yıldızböceğini andıran

Işıklar görüyorum.

Mehtapsız bir gece can sıkıntısı veriyor.

Zamanla tüm ışıklar birer birer kayboluyor

Duyulan sesler, duyulmaz oluyor

Ve, kocaman İstanbul''u

Bir karanlık örtüsü kaplıyor

Tüm İstanbul sükût içinde uyuyor...

Bu karanlık gece de 

Sükût içinde aydınlığa kavuşuyor.

Herşey sükût içinde başlıyor

Ve sükût içinde sona eriyor.', 'Uyuyor İstanbul Geceyarısında sessiz, sakin Kocaman İstanbul... Dev bir kovana benzetiyorum O''nu Binlerce canlıyı, insanı İçine alışından. T...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sukut-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdüm', 'buyudum-halil-kesken-zkit0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaşları kemandı, gözleri boncuk

Dünyayı yaşanır görmüyor artık

Senin tanıdığın o küçük çocuk

Gülücükler atıp durmuyor artık

Toz pembe hayaller kurmuyor artık

Saçları kar yağmış bir tepe gibi

Gözleri sel gelmiş bir dere gibi

Ömrünce yakmışlar bir çıra gibi

Zorluklara karşı durmuyor artık

Toz pembe hayaller kurmuyor artık

Yaşamaktan bıkmış, kalmamış hali

Ne uçuk bir tavır, ne kavak yeli

Engeller durdurmuş bu büyük seli

Kıyısına dalga vurmuyor artık

Toz pembe hayaller kurmuyor artık

Kalbi isyanlardan bıkmış onunda

Ne aşk, ne dostluğu gitmiş yolunda

Yaşama hevesi bitmiş sonunda

Sevmeye kendini yormuyor artık

Toz pembe hayaller kurmuyor artık

Yalan söyleyeni asla sevmezdi

Doğruluktan başka birşey bilmezdi

Çocuk kalmak için neler vermezdi

Geleceğe güven duymuyor artık

Toz pembe hayaller kurmuyor artık

Bükülmezdi onun demir bileği

Yalnız sevgi idi bütün dileği

Çoktandır anladı acı gerçeği

Her sözde yüreği vurmuyor artık

Toz pembe hayaller kurmuyor artık

En çok inandığı tutmaz sözünü

Çoğunun gururu sarmış özünü

Yaşadığı aşklar açmış gözünü

Her güzele gönül vermiyor artık

Toz pembe hayaller kurmuyor artık', 'Kaşları kemandı, gözleri boncuk Dünyayı yaşanır görmüyor artık Senin tanıdığın o küçük çocuk Gülücükler atıp durmuyor artık Toz pembe hayall...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/buyudum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gebe Dünya', 'gebe-dunya-abdullah-atay-zo8u3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu dünyada her şey gebe; 

Kışlar bahara. 

Gece sabaha. 

Ana yavruya. 

Toprak tohuma. 

Yağmur buluta 

Çiftçi umuta 

Gurbet sılaya. 

Deniz nehire 

Şair şiire... 

Kurt kuş, 

Yılan çıyan, 

Kedi köpek, 

Börtü böcek, 

Dal çiçek, 

Kimbilir; 

Daha neler neler... 

Ha...Bir de; 

Nasrettin Hoca’nın kazanı bile...', 'Bu dünyada her şey gebe;  Kışlar bahara.  Gece sabaha.  Ana yavruya.  Toprak tohuma.  Yağmur buluta  Çiftçi umuta  Gurbet sılaya.  Deniz neh...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gebe-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-gulsum-tanriverdi-dktve', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yemin ederim başka birşey istemiyorum.

Tamam, baharlar da olmasın artık.

Dört mevsim kış olsun, kabulüm,

Acısın soğuktan ellerim, ayaklarım,

Yaşarsın gözlerim,

Aç kalayım günlerce.

Yeter ki sen gel...

Gel yalvarırım,

Yüreğimdeki kıtlığa son ver.

Gel ki,

Bu kez sevinçten aksın gözyaşlarım,

Sevinsin göz pınarlarım.

Yalvarırım gel,

Bir kez daha göreyim gözlerini; 

İsterse sonum olsun.

Neler verirdim o an için bilmiyorsun.

Bilmiyorsun, 

İçime saplandığını,

Boğazıma düğümlendiğini,

Beynimi söktüğünü,

Bu sızlanan dizelerdeki herbir harfin.

Yalvarırım gel,

Böyle bitmesin bu rüya.

Bak artık söylüyorum; 

Seni seviyorum

Seni,seviyorum! 

(İstanbul 27.Ocak.1992)', 'Yemin ederim başka birşey istemiyorum. Tamam, baharlar da olmasın artık. Dört mevsim kış olsun, kabulüm, Acısın soğuktan ellerim, ayaklarım,...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Tanrıverdi']::text[], 8.5, '{"poet":"Gülsüm Tanrıverdi","poet_slug":"gulsum-tanriverdi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gel-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Aşk-2-*', 'vefasiz-ask-2-bayram-tunca-jz7xx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vefasız aşk girdi mi kalbe 

Bedenimiz alır ağır darbe 

Hafızamız da uğrar kayba 

O aşktan sakınmalı daima 

Kimine derman, kimine ölüm fermanı 

Ah aldı götürdü dizlerimdeki dermanı 

Sevineceğim anda, tebliğ etti fermanı 

Durdurun inecek var şu aşk kervanını 

14.03.2004-14.03', 'Vefasız aşk girdi mi kalbe  Bedenimiz alır ağır darbe  Hafızamız da uğrar kayba  O aşktan sakınmalı daima  Kimine derman, kimine ölüm ferman...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vefasiz-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esir', 'esir-burak-killioglu-ithme', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşmanım ol benim.

Ancak, onursuz bir düşman gibi

Sırtımdan vurmayasın.

İstiyorsan esir et.

Hapsolayım nehir gözlerinde,

İlelebet!', 'Düşmanım ol benim. Ancak, onursuz bir düşman gibi Sırtımdan vurmayasın. İstiyorsan esir et. Hapsolayım nehir gözlerinde, İlelebet!...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/esir-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgıç', 'dalgic-burak-killioglu-1inf4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalıp gider oldum senin derdinle,

Diplerde geziyorum.

Yolda giderken veya bir dost meclisinde,

Dalıp dalıp gidiyorum.

Sesler ve yüzler tümüyle yok oluyor,

Ruhum o derinlerde gerçek aşkı buluyor.

Bütün bunlara rağmen; 

Bir el uzansa da,

Çekse beni derinden.

O ellerin sahibi,

Dön gittiğin yerden.', 'Dalıp gider oldum senin derdinle, Diplerde geziyorum. Yolda giderken veya bir dost meclisinde, Dalıp dalıp gidiyorum. Sesler ve yüzler tümüy...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dalgic-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Vurur, Vuslatın Ondurur Beni', 'ozlemin-vurur-vuslatin-ondurur-beni-muammer-celik-bnlwl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I

Çölde susuz kalmak gibidir

Sana muhtaç olmak…

II

Kuraklıkta aç kalmak gibidir

Sana muhtaç olmak…

III

Yağmur olup yağmak gibidir

Sana kavuşmak…

IV

Güneşle dudak dudağa olmak gibidir

Sana dokunmak…

V

Gül bahçesine düşmek gibidir

Seni koklamak…

VI

Ve Seni öpmek

hurilerin kucağında uyanmak gibidir…! 

BirDeli 

25.03.2004', 'I Çölde susuz kalmak gibidir Sana muhtaç olmak… II Kuraklıkta aç kalmak gibidir Sana muhtaç olmak… III Yağmur olup yağmak gibidir Sana kavuş...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozlemin-vurur-vuslatin-ondurur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kimdi ki?', 'o-kimdi-ki-sair-cunoba-c89jr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kehribar kaya belki...

Bir tek köpük bile bırakmadan, o bildik karadeniz dalgasının

üstünde patladığı...

Ya da tersine,

incecik dallar ardında üstüne sızan damlacıklara sevinen,

öylesine

kendi halinde

bir kehribar kaya işte.

Kuytular geldi şimdi aklıma.

Neden bilmiyorum.

Acı zehir yeşili mısır tarlaları... kuytular.

Memelerini açardı kızlar,

doyumsuz yuvarlak 

ve onca taze

ve onca ürperten 

kıpırtılarla.

Her şey o kadar ani ki,

dokunursam...

doruklar boşalır içimden

kütür kütür akarak.

Yılan kıvrımlı dik ve derin vadiler boyunca

kimse durduramaz gibiyim.

Ne kuytular görmüşüm.

Belki de yüreğim, dolmuştur gırtlağına kadar.

Şubat ayında

yamaçta

derenin ayazına ve karanlığa

türkü söyler gibiyim.

Sevda mı bu? 

Ne ki? 

Hiç bir betimlemeye uymaz.

Sadece

o koca dalgalardan kalan köpükcük,

o çiğ damlası,

o azgın sel,

o derenin ayazında karanlığa türkü söylemek kadar

birdenbire bir şeydi.

Hissedildi, o kadar.

O kimdi ki? 

Bir kehribar kayaydı belki.', 'Bir kehribar kaya belki... Bir tek köpük bile bırakmadan, o bildik karadeniz dalgasının üstünde patladığı... Ya da tersine, incecik dallar a...', ARRAY['Türk Edebiyatı','Şiir','Şair Cunoba']::text[], 8.5, '{"poet":"Şair Cunoba","poet_slug":"sair-cunoba","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/o-kimdi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-muammer-kurt-jqzqs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hangi iklimdesin allı pullu ilkbahar? 

Hangi karanfilin rengindesin kan kırmızı? 

Hangi menekşenin yürek morusun? 

Hangi gelincik tarlasındasın yılkı yılkı? 

Hangi yüreğin korusun alev alev? 

Hangi yürekte sevdasın? 

Hangi yürekte sızı? 

Hayalimdeki sen; 

bildiğim memleketimin kızı.

Su yolunda suna bir gelin,

burçak tarlasının burcu burcu toprak kokusu.

ekmeğin bedeli nasırlı elin,

yeminsiz yalansız o neyzen dilin,

ceylan ürkekliğinde o ince belin,

neyin olsun başka senin? 

neredesin bir bilseydim,

ya da sen gel deseydin,

bir gel diyebilseydin,

gelmeyi düşünürmüydüm sana

gelmeyi düşünürmüydüm sevdana.

Bunca sevdadan,

bunca çileden,

bunca yaradan sonra.

Düşünürmüydüm demiyorum; 

Sensiz geçen zaman 

ziyan olurdu....', 'Hangi iklimdesin allı pullu ilkbahar?  Hangi karanfilin rengindesin kan kırmızı?  Hangi menekşenin yürek morusun?  Hangi gelincik tarlasında...', ARRAY['Türk Edebiyatı','Şiir','Muammer Kurt']::text[], 8.5, '{"poet":"Muammer Kurt","poet_slug":"muammer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/neredesin-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mülteci', 'multeci-murat-tali-d1jgn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gönlün

öyle büyük olsun ki

oraya girecek 

tüm sevgiler 

mülteci gibi 

kalsın', 'gönlün öyle büyük olsun ki oraya girecek  tüm sevgiler  mülteci gibi  kalsın...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/multeci-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm ve Özgürlük', 'olum-ve-ozgurluk-murat-tali-y6dbh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'oy gülüm ölüm yine çalmış kapıyı

acı acı gıcırdar kapım

dağlanan yürek olur

kopup giden

tenimden bir parça

perdeler uçuşmaya başlar 

penceremden

ve pencerem

yuva olur serçelere

ürkek yürekleriyle 

kaçışır özgürlük gibi

özgürlük

kanatlanır gıcırdayınca kapım

ve 

her ölüm bir serçe kanatlanması olur 

her ölüm kanatlanmaktır

özgürlüğe', 'oy gülüm ölüm yine çalmış kapıyı acı acı gıcırdar kapım dağlanan yürek olur kopup giden tenimden bir parça perdeler uçuşmaya başlar  pencere...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olum-ve-ozgurluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
