INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşçı Ruhlar', 'savasci-ruhlar-ali-aydin-xg8fu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutsağın olmuşum, sorgusuz sualsiz, 

Paslı prangalar vurulmuş, cılız ayaklarıma. 

Yüreğimle sana koşarken, vahşi kısrak misali, 

Pervasız bir direnişin ortasındayım. 

Bak, alacalı kurtlar kemiriyor, kimsesiz kentleri, 

Yaralı martıların, ölüm çığlıkları düşüyor yollara. 

Tan yeri değil, her yer kızıla boyanmış, 

Dudaklarında beyaz karanfiller. 

İşgalci karanlıklar, çökmeden fersiz gözlerine, 

Ay doğmadan tütün rengi saçlarından, 

Yırtacağım zamanı demir pençelerimle, 

Bir gölge gibi süzülüp yatağına, 

Kedi sessizliğinde kıvrılacağım ayak ucuna. 

Artık kırağı düşmeyecek ezgisine, yanık türkülerin! ! !', 'Tutsağın olmuşum, sorgusuz sualsiz,  Paslı prangalar vurulmuş, cılız ayaklarıma.  Yüreğimle sana koşarken, vahşi kısrak misali,  Pervasız bi...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydın']::text[], 8.5, '{"poet":"Ali Aydın","poet_slug":"ali-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/savasci-ruhlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş''tü', 'dus-tu-hayri-yucel-xh16a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düştü umut

Düş’tü zaten...

Beklemek düş’tü

Kuzgunlar üşüştü.

Oysa sıcak bir gülüştü...

Bir parça ekmek,

Bir takım urba,

Sığınacak çatı,

Sarılacak sine,

Tutulacak daldı...

Asarken eşiklere

Kaydı ellerimizden,

Camdan bir naldı...

Parçalandı...

Belkiydi,

Olabilirdi,

Hatta olmalıydı,

Olacaktı da! ..

Ramak kaldı...

Düştü maskesi sevdanın

Düş’tü zaten...

Dalgalar gibi vururdu

Düşerken yüreklere. 

Hummalı,

Delice,

İyiydi be! ..

Ama yaşam,

Bütün melanetiyle

Dönüştü mendireklere.

Silerek izlerini

Koydu karşısına bütün gizlerini.

Kah suydu bir damla içilen,

Kah köprü gölgesinden geçilen,

Kah Samanyolu ulaşılmayan,

Kah açık denizde saldı...

Sevda masaldı...

Koşup durduk peşinden

Yakalayacaktık nerdeyse

Nerdeyse hani! ..

Ramak kaldı...

Düştü koruganı barışın,

Düş’tü zaten...

Düşerken

Teslim olduk çığlık çığlığa,

Gafletteydik,

Savunmasızdık,

Azdık...

Hesapları vardı kimilerinin

Akmalıydı kan! 

Fırlıyordu gözleri yuvalarından

Ve aktı...

Mavi, kayıplara karıştı.

Ne siyah - ne beyaz

Bütün renkleri gri kapladı...

Sırçaydı barış,

Kırılgandı,

Ulaşılmazdı...

Yine de uzattık elimizi,

Değerdi her şeye

Yaşanmalıydı...

Bir gece vakti

Gün doğarken,

Derin bir uykudayken

Haramiler çaldı...

Yarınsızdık,

Biçareydik belki

Ama nefretimiz vardı! 

Kırmadık inadı,

Direndik tutunabilmek için

Yakalayacaktık...

Ramak kaldı...

Düştü tetiği zamanın,

Düş’tü zaten...

Dokundu iğneye,

İğne fünyeye,

Akabi patlama sesi,

Peşinden barut kokusu,

Isındı namlu - yiv - set.

Kor ateşler içinde,

İvmelendi hararet...

Fırladı yuvasından kurşun

Hedefe doğru.

Hızlı bir hareket,

Döne döne,

İne çıka,

Şaşmadan hızını aldı...

Ölüm uzaktı

Ama şimdi...

Ramak kaldı...

Düştü yaşam,

Düş’tü zaten...

Umut düş’tü,

Barış düş,

Sevda düş…

Devran döndü dönüştü,

Bir ışık yandı söndü.

Oysa kutsaldı nefes,

An be an tadacaktık... 

Ramak kaldı...', 'Düştü umut Düş’tü zaten... Beklemek düş’tü Kuzgunlar üşüştü. Oysa sıcak bir gülüştü... Bir parça ekmek, Bir takım urba, Sığınacak çatı, Sarı...', ARRAY['Türk Edebiyatı','Şiir','Hayri Yücel']::text[], 8.5, '{"poet":"Hayri Yücel","poet_slug":"hayri-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/dus-tu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah Romanı', 'gunah-romani-ali-aydin-7ur4q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk gençliğimin günahlarını ektim, 

Yalnızlıktan kuruyan toprağın koynuna. 

Siz bilmezsiniz, 

Çocukluğumun, balta girmemiş ormanlarında buldum kendimi. 

Ulu bir çınarım olsun istedim hep, 

Tohumunu ellerimle ektiğim, 

Yalınayak koştum, 

Deli rüzgarına kapıldığım yılların ardından. 

Hey! Siz nereye gidiyorsunuz; 

Çığlığını rüzgara seren martı kuşları? 

Bakın soluk soluğa size koşuyor, 

Hayatın, yelelerinden sürüklediği ak taylar... 

Ömrümü; 

Bitirilmemiş bir romanın küf kokan satırlarına sakladım. 

İlk yağmur taneleri düştüğünde toprağın rahmine, 

Günahlarından arınan gençliğimdi filizlenen. 

Şeytanın esiri olan köhne kentler; 

Henüz yağmuru hak etmemişken, 

Nasıl da acımasızmış inandığım gök tanrıları, 

Yağmurun kokusunu bile esirgemiş kuru ekinlerden... 

Gökten bereketli şiirler yağsın üzerime, 

Damıtılmış şaraplar yıkasın, 

Günahkar çıplaklığımı. 

Gün ortasında korkular yaşıyorum, 

Ülkesi olmayan göçmen kuşlar misali... 

Kalbim, sen bunu sakın unutma, 

Meğer, bir göz yanılgısıymış ıslak tenin. 

Uğruna tozutmuşluğumu, 

Sana delice vurulmuşluğuma yor. 

İşte şimdi açıyorum düşlerimin bütün ağıllarını, 

Aşk üzerine türettiğim sözcükleri, 

Dargın sevdalıların küskün gözlerine ekiyorum, 

Çünkü; bütün günahlarımı, 

Küf kokan romanın satırlarına sakladım. 

2003', 'İlk gençliğimin günahlarını ektim,  Yalnızlıktan kuruyan toprağın koynuna.  Siz bilmezsiniz,  Çocukluğumun, balta girmemiş ormanlarında buld...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydın']::text[], 8.5, '{"poet":"Ali Aydın","poet_slug":"ali-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gunah-romani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
