INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şey', 'sey-ersan-kurt-k39yr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklıma girer durup dururken 

nereden çıkar bilmem hiç gereği yokken

uyurken uyanıkken

terlerken üşürken

yerken içerken

bazen aptalca şeylerden

ama ne yalan söyleyim

en çok da seni düşünürken

şey işte! 

1 Nisan 2004, Kuzey Denizi', 'Aklıma girer durup dururken  nereden çıkar bilmem hiç gereği yokken uyurken uyanıkken terlerken üşürken yerken içerken bazen aptalca şeylerd...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sey-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Anlatabilsem', 'bi-anlatabilsem-ersan-kurt-cmphx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'N’apalım güzelim gördük bi kere, dönüşü de yok ki! 

Her bakışta dağlar şimdi fotoğrafındaki bakış derindeeeen, incedeeen 

içerlerde bi yerlerde bişeyler akıyor, eriyip gidiyor da tarif etmesi öyle zor ki 

hani: “sarılsam beline, dünyayı veririm saçının tek teline” türünden bi şey

sevdanın seline kapılmak gibi, “bi öpsem de ölsem” dedirten cinsten bişey işte

bir mucize olsa da anlayabilsen! 

1 Nisan 2004, Kuzey Denizi', 'N’apalım güzelim gördük bi kere, dönüşü de yok ki!  Her bakışta dağlar şimdi fotoğrafındaki bakış derindeeeen, incedeeen  içerlerde bi yerle...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bi-anlatabilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkedeceksin', 'farkedeceksin-gulden-karabudak-fjn5l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yangınları sorduğunda içime 

Varlığınla serinlediğimi hissedeceksin

Susuz sabahlara uyandığında gözlerin

Çöl ortasında serap olduğumu göreceksin

Bir el uzansın derken gözyaşlarına 

Sırılsıklam oluşumu seyredeceksin

Avuçlarını sunduğunda semaya

Yağmur yağmur indiğimi göreceksin

Bir nefeslik ömrümün son karesinde

Birtek sen zikredileceksin…

Birtek “sen” o ömre değeceksin….', 'Yangınları sorduğunda içime  Varlığınla serinlediğimi hissedeceksin Susuz sabahlara uyandığında gözlerin Çöl ortasında serap olduğumu görece...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/farkedeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum seni ben..! ! ! !', 'seviyorum-seni-ben-nazife-abayli-ioh24', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu pencerenin önünde,

Dört numaralı masada,

Marmarayı izlerken ben,

Suyun dalgalarında,

Yüzünü görüyorum.

Gülümsemeni,

Gözlerini,

Duydu dolu bakışlarını görüyorum.

Turkuaz ışıltılarda,

Gözlerinin maviliğini görüyorum,

Gecenin karanlığında.

Değdikçe dudaklarım,

Süt beyaz rakıma,

Senin saflığını,

Yudumluyorum,tadıyorum ben...

Rakım gibi bembeyaz,

Suyum gibi berrak,

Seni seviyorum....

Seviyorum seni ben..! ! ! !', 'Şu pencerenin önünde, Dört numaralı masada, Marmarayı izlerken ben, Suyun dalgalarında, Yüzünü görüyorum. Gülümsemeni, Gözlerini, Duydu dolu...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seviyorum-seni-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* iLK * BAHAR * OLSA *', 'ilk-bahar-olsa-baki-son-flxtw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşabilsem...

İçimdeki yokluğu

Ve yeniden doğmuş gibi saf,

Tekrar başlayabilsem...! 

Bu yağmurlu sonbahar gecesinden,

İlk arzu doğsa sabahla

Ve bahar...

*************İlk bahar  olsa.

Kent den kente

Bu gölgeler ne.? 

Umutlu tüm uzaklıklarla

Aramdaki

Bütün benliğimle kaçabilsem,

Bu sinsi bakışlardan.

Heryerde anılarım

En güzeli sevdiğim de

Yalnızım...! 

Terkettiğim...

Yitirdiğim...

Arzular doğsa sabahla

Ve bahar

************İlk bahar doğsa,

Bir küçük şölen ertesi

Düşüm de...

Aşabilsem bu yalnızlığı

Bir mavi gök kubbede

Damla...Damla...

Dolaşabilsem...

Sonra...

Soğuk rüzgarlar,

Darmadağın...

Sarı yapraklar,

Karanlık bulutlarda

Yerini bulsa...

Ve tertemiz 

İlk bahar havası esse

Aşabilsem içimdeki yokluğu

Yeniden doğmuş gibi hür.! 

Tekrar başlayabilsem...!', 'Aşabilsem... İçimdeki yokluğu Ve yeniden doğmuş gibi saf, Tekrar başlayabilsem...!  Bu yağmurlu sonbahar gecesinden, İlk arzu doğsa sabahla ...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ilk-bahar-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kağıt', 'kagit-noyan-tuzuner-vqret', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“aynı kağıdın arka ve ön yüzleri gibiyiz

sonsuza dek beraber ama

hiçbir zaman birbirlerini görmeyen...”

''n.t.''', '“aynı kağıdın arka ve ön yüzleri gibiyiz sonsuza dek beraber ama hiçbir zaman birbirlerini görmeyen...” ''n.t.''...', ARRAY['Türk Edebiyatı','Şiir','Noyan Tüzüner']::text[], 8.5, '{"poet":"Noyan Tüzüner","poet_slug":"noyan-tuzuner","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kagit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüllere tac', 'gonullere-tac-halil-i-brahim-ozdemir-siqhg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben tokken komşular asla kalmasın aç

Allah dert vermesin aratmasın ilaç

Alandansa da veren olmak en iyisi

Dayanışma huzurdur gönüllere taç', 'Ben tokken komşular asla kalmasın aç Allah dert vermesin aratmasın ilaç Alandansa da veren olmak en iyisi Dayanışma huzurdur gönüllere taç...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gonullere-tac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gözlerini Arıyorum Yalnızca', 'ben-gozlerini-ariyorum-yalnizca-oguzkan-bolukbasi-epn78', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söylenmemiş duyguların 

bedende ifadesidir sana baktığımda tutuşması hayallerimin

Sıcaklığım 

Sanki alev topudur atmosferine girmiş gök taşlarının

Yanarak düşmesi en güzel yerlerine bakışlarımdaki özlemin

Demin şuracıkta öpme arzuları varken tüm yıldızları yanaklarından

Anladım

O yanaklar senin

Yalnızca hasret benim

/yörüngesinden çıkmış bir gezegendeyim

 hangi güneşin sistemine yakalanacağı bilinmez 

 ben gözlerini arıyorum yalnızca/', 'Söylenmemiş duyguların  bedende ifadesidir sana baktığımda tutuşması hayallerimin Sıcaklığım  Sanki alev topudur atmosferine girmiş gök taşl...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-gozlerini-ariyorum-yalnizca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Sevinci*', 'bahar-sevinci-bayram-tunca-25bcy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakınca bahardaki güneşe 

Ekser kulda olur pür neşe 

Açar bin bir çeşit menekşe 

Melekler de alkışlar bu işe 

Taçlandırılmış tüm çiçekler 

Yeşile bürünmüş arzdakiler 

Sanki duvak gökte bulutlar 

Ana rolünü almış topraklar 

Harman olmuş gül kokuları 

Mest ediyor bahar dokuları 

Aşka davet ediyor insanları 

Perçinletiyor aşkı sevenleri 

İbretle bir bak hele şu doğaya 

Amin der, tüm varlık bu duaya 

Hamd olsun hayatı veren Allah’a 

Kavuştursun bizi nice baharlara 

Bulutlar nazar boncuğu sanki bak 

Arzdaki sular durulup akar berrak 

Okşarcasına eser ılgıt ılgıt rüzgar 

Öpünce güneş arz mis gibi kokar 

Çiçekten çiçeğe, konar kelebekler 

Kimi Kerem’ini/kimi Aslı’sını bekler 

Yapılır has dualar, tutulur dilekler 

En hassas şekilde çarpar yürekler 

Dokusu/kokusu, mest ediyor insanı 

Çok şükür yine kavuştuk nisan ayını

Bak, her birinin ayrı ayrı libası/lisanı 

Gelince bahar kaynıyor insanın kanı 

Mevsimler ister kış, ister bahar olsun 

Yeter ki bahar gözlüm yanımda olsun 

O yanımdayken, her şey gül gülistan 

Yar yokken yanımda dünya kabristan 

01.04.2004-08.04-İst.', 'Bakınca bahardaki güneşe  Ekser kulda olur pür neşe  Açar bin bir çeşit menekşe  Melekler de alkışlar bu işe  Taçlandırılmış tüm çiçekler  Y...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bahar-sevinci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yere Düşen Yapraklar', 'yere-dusen-yapraklar-i-brahim-dikmen-2-45x0u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanışmıştık birtanem,

Seninle,bir sonbahar.

Aşkımıza şahitti,

Yere düşen,yapraklar.

Kanat çırpan,martılar,

Balıkçılar,sandallar,

Sahildeki,dalgalar,

Aşkımıza,şahitti.

Yine aynı yerdeyim,

Bekliyorum,sevgilim.

Yıllar geçsede,aradan,

İnan seni,seveceğim.', 'Tanışmıştık birtanem, Seninle,bir sonbahar. Aşkımıza şahitti, Yere düşen,yapraklar. Kanat çırpan,martılar, Balıkçılar,sandallar, Sahildeki,d...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yere-dusen-yapraklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-i-brahim-dikmen-2-m424q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün,neşem yerinde,

Aşığım,delicesine.

Gözlerimde,gözlerin,

Seviyorum,dercesine.

Bir coşku var,içimde,

Kavuştum,sevgilime.

Allah''ım,şükürler olsun,

Son verdin,hasretime.', 'Bugün,neşem yerinde, Aşığım,delicesine. Gözlerimde,gözlerin, Seviyorum,dercesine. Bir coşku var,içimde, Kavuştum,sevgilime. Allah''ım,şükürle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hasret-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımı', 'gun-batimi-i-brahim-dikmen-2-tv55u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seyrederdik,güneşi,

Neş''eyle,gülümserdik.

Şendik,çocuklar gibi,

O''gün batımında.

Şimdi hayal,hepsi anı,

Gözlerime,yaşlar doldu.

Titreyen,dudaklarım,

Adını,anar oldu.

Ne hayaller,kurmuştuk,

Gelecekten,rengarenk.

Çocuklarımız,olmuştu,

O''gün,batımında.

Tutuşurduk elele,şarkılar,söylerdik,

Öpüşürdük sevgilim,kendimizden,geçerdik.

Dudaklarım kanadı,yandı dudaklarında,

Seni aradım sevgilim,o''gün batımında.', 'Seyrederdik,güneşi, Neş''eyle,gülümserdik. Şendik,çocuklar gibi, O''gün batımında. Şimdi hayal,hepsi anı, Gözlerime,yaşlar doldu. Titreyen,dud...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-batimi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Bir. Adında Bir Şiir', 'nisan-bir-adinda-bir-siir-mine-ozdemirtas-4kbyw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimden öpme.... ayrılıktır dedin.

Öpmedim.

Artık ayrılamayız. Değil mi sevgilim? 

------------------------------

Günaydın! ! ! ! ! 

Günaydın aynada göz kırpan çocuk.

Günaydın içimin bütün kadınlarına.

Bu sabah,

Biraz mor damlatmayı deneyeceğim

Dilimin ucundaki toz pembe duygulara

Biliyorum,

Belki biraz çapkın belki  biraz da hercai

Yani,Ebruli bir şiir çıkacak ortaya.

Ona,

Sonsuzluk adını vermek istiyorum

Yok. Vazgeçtim. Şiirimin adı kesinlikle: Lila

Düşündüm de

Renklerin vergisi yoracak sanki  yüreğimi.

Telif hakkı  bağışım olmalı. Bütün aşıklara

Bu yüzden 

Ne rüzgara ne de Suya değil. Ama,

Nisan bir olarak............Yazdım duvara.

01/04/2004................Bu gün 1 Nisan &#61514 ;))))', 'Gözlerimden öpme.... ayrılıktır dedin. Öpmedim. Artık ayrılamayız. Değil mi sevgilim?  ------------------------------ Günaydın! ! ! ! !  Gün...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/nisan-bir-adinda-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tuzağı', 'ask-tuzagi-erhan-saka-cp12e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşersin bir zalim aşkın eline,

Sarılır ateşten kemer beline,

Kapılsa yüreğin duygu seline,

Hangimiz düşmedik aşk tuzağına.

Aşkın anlamını bilen bulunmaz,

Birini seversin oda yar olmaz,

Aşk dediğin yaşamaya doyulmaz,

Hangimiz düşmedik aşk tuzağına.

Gül dersin eline dikeni batar,

Bilmezsin koynunda yılanlar yatar,

Birini buldu mu birini satar,

Hangimiz düşmedik aşk tuzağına.

01-12-2003', 'Düşersin bir zalim aşkın eline, Sarılır ateşten kemer beline, Kapılsa yüreğin duygu seline, Hangimiz düşmedik aşk tuzağına. Aşkın anlamını b...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-tuzagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-hayri-yucel-0cn5z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fırtınaya kürek çekmeyeceksin güzelim,

Akışa da bırakmayacaksın...

Dimdik ayakta durabilmek için

Yaşama sarılacaksın...

Tabii ki hayat girdaplarla doludur,

Gel-gitler de yaşanacak mutlaka,

Ama hiçbir zaman yitirmeyeceksin umudunu.

Umut yaşamın kaynağıdır unutma! 

Her güne yeni bir aşk gibi sarılmalı,

Hedef olarak seçtiğin her güzellik,

Varılacak noktadır varılmalı! ..

İşte o an yenilersin kendini,

Güneş gibi parlar o tatlı yüzün,

Bir kumandan edasıyla yürürken

Söylenirsin; 

Elveda dünlerim,

Elveda hüzün...', 'Fırtınaya kürek çekmeyeceksin güzelim, Akışa da bırakmayacaksın... Dimdik ayakta durabilmek için Yaşama sarılacaksın... Tabii ki hayat girda...', ARRAY['Türk Edebiyatı','Şiir','Hayri Yücel']::text[], 8.5, '{"poet":"Hayri Yücel","poet_slug":"hayri-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayata-dair-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-hayri-yucel-l4oq2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu şehir,

Çılgınca akan bir nehir...

Her bir kolu acı dolu,

Her bir damlası zehir...

Yadıma hüzün fışkıran anılar gelir,

Elim...

Korkulu...

Kaç yiğit kayboldu girdaplarında,

Bilmem kaç cevahir...

Bilirim umurunda değil,

Bilirim yadsırsın yaptıklarını,

Ama an gelir be İstanbul! ..

An gelir...', 'Bu şehir, Çılgınca akan bir nehir... Her bir kolu acı dolu, Her bir damlası zehir... Yadıma hüzün fışkıran anılar gelir, Elim... Korkulu... ...', ARRAY['Türk Edebiyatı','Şiir','Hayri Yücel']::text[], 8.5, '{"poet":"Hayri Yücel","poet_slug":"hayri-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istanbul-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem Hatırlarmısın', 'bilmem-hatirlarmisin-i-brahim-dikmen-2-my5ku', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmem hatırlarmısın,

Sabahlara kadar,

Seviştiğimiz,

O''eski günleri.

Söyle unuturmuyum,

Hatırımdasın,dün gibi.

Anılarla,yaşıyorum,

Nasıl,unuturum seni.

Bilmem,hatırlarmısın,

Sabahlara kadar,

Seviştiğimiz,

O''eski günleri.

Çıkmıyor,hiç aklımdan,

Senin,o''bakışların,

Öpmeye doyamadığım,

O''ıslak,dudakların.', 'Bilmem hatırlarmısın, Sabahlara kadar, Seviştiğimiz, O''eski günleri. Söyle unuturmuyum, Hatırımdasın,dün gibi. Anılarla,yaşıyorum, Nasıl,unu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmem-hatirlarmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De(me) mek...', 'de-me-mek-hayri-yucel-ngjas', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Demek gidiyorsun,

Dindi fırtınaların,

Sonu geldi aşkımızda baharın,

Bakmak yok geriye,

Boşmuş masallar,

Periler yalan.

Demek düşmüş gördüklerim

Uzandıkça kaybolan.

Demek dalga geçtin benimle

Hiç utanmadan.

Demek kumdan kaleydi sığındığımız sevda

Yıkıldı dalgalardan.

Demek farkı yokmuş

Bana şarkı gibi gelen sesinin

Şu çirkin kargalardan...

Demek gözlerindeki hülya hikâyeydi,

Sokuluşun bir oyundu pespaye,

Öpüşlerindeki ateş hastalığındandı.

Kazıkladın beni,

Demek başkası kokluyor seni...

...ve ben hâla şaşkın ördek gibi

Sokup çıkartıyorum kafamı suya...

Demek aptalmışım ben,

Anlamadım bunca zaman.

Attın ya bu çalımı belimi kıran,

Gülüyorsun ya halime,

Külledin ya koskoca bir ateşi,

Helal olsun sana,

Helal olsun ulan!', 'Demek gidiyorsun, Dindi fırtınaların, Sonu geldi aşkımızda baharın, Bakmak yok geriye, Boşmuş masallar, Periler yalan. Demek düşmüş gördükle...', ARRAY['Türk Edebiyatı','Şiir','Hayri Yücel']::text[], 8.5, '{"poet":"Hayri Yücel","poet_slug":"hayri-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/de-me-mek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Gibi', 'bizim-gibi-hayri-yucel-ydb97', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlamışsındır

Daha ilk nefesinde,

İlk ağlayışında,

İlk açtığında gözlerini,

İlk dudakların kuruduğunda,

İlk saldırışında memeye,

İlk sütü tattığında,

Acıktığında.

Sorgulamışsındır yaşamı

		Kahırlanarak...

Öğrenmişsindir

İlk emeklediğinde sürünmeyi,

İlk adımda düşmeyi,

İlk yaramazlığında şiddeti,

İlk kavganda savaşı,

İlk busede barışı,

İlk elinden tutulunca dostluğu,

İlk göz göze gelişte sevmeyi,

İlk terk edilişte çaresizliği,

İçinde fırtınalar koparak...

...Ve yalnızlığı sonrası

		ufak ufak...

Dönencesinde puştluğun

		Fark etmişsindir mutlak...

Sende unutmuşsundur gülmesini,

Geçtikçe zaman,

Sıkılı dişlerin,

Yiten umutlarınla,

Doğan güne

		Anlamsızca bakarak...', 'Anlamışsındır Daha ilk nefesinde, İlk ağlayışında, İlk açtığında gözlerini, İlk dudakların kuruduğunda, İlk saldırışında memeye, İlk sütü ta...', ARRAY['Türk Edebiyatı','Şiir','Hayri Yücel']::text[], 8.5, '{"poet":"Hayri Yücel","poet_slug":"hayri-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bizim-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımıza Hasret Ekleme', 'askimiza-hasret-ekleme-erhan-saka-sswzm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırdın dallarını gönül bağımın,

Yalancı dünyana beni bekleme,

Gülleri açmıyor sevgi dağımın,

Bari aşkımıza kahır ekleme.

Aşkıma bir ümit vermeyeceksen,

Gittiğim yerlere gelmeyeceksen,

Birlikte ağlayıp gülmeyeceksen,

Bari aşkımıza hasret ekleme.

Her aşkın kendince gururu vardır,

Kalbini uykudan hemen uyandır,

İstersen kendini hep böyle kandır,

Yeter ki aşkıma yalan ekleme.

27-02-2004', 'Kırdın dallarını gönül bağımın, Yalancı dünyana beni bekleme, Gülleri açmıyor sevgi dağımın, Bari aşkımıza kahır ekleme. Aşkıma bir ümit ver...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askimiza-hasret-ekleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Taşıyamadım', 'ben-seni-tasiyamadim-erhan-saka-u9sts', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boşuna geçirdim bunca yılları,

Hayatı tadıyla yaşayamadım,

Yürüdüm gayesiz uzun yolları,

Sevgilim ben seni taşıyamadım.

Ne hasretim çektin, nede uslandın,

Gençliğe güvendin ona yaslandın,

Gözyaşım sel gibi yağdı ıslandım,

Sevgini kalbimde taşıyamadım.

Şimdi çok yalnızım titriyor elim,

Ümitsiz şarkılar söylüyor dilim,

Yoruldu bedenim, büküldü belim,

Sevgilim ben seni taşıyamadım.

01-03-2004', 'Boşuna geçirdim bunca yılları, Hayatı tadıyla yaşayamadım, Yürüdüm gayesiz uzun yolları, Sevgilim ben seni taşıyamadım. Ne hasretim çektin, ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-seni-tasiyamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yine Sensiz', 'ben-yine-sensiz-erhan-saka-5pwdl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutmam asla yıllar geçse de,

Sen benim dünyama doğan yıldızsın,

Beklerim ne çıkar ömür bitse de,

Sen benim güneşim tek ışığımsın,

Ben yine sensiz akşamlardayım,

Ben yine sensiz yarınlardayım,

Ben yine sensiz buralardayım,

Ben yine sensiz isyanlardayım.

Kim bilir şimdi sen nerelerdesin,

Hangi duygularla sen kiminlesin,

Soruyorum sana çok mu mutlusun,

Geleceğin var mı umutlu musun.', 'Unutmam asla yıllar geçse de, Sen benim dünyama doğan yıldızsın, Beklerim ne çıkar ömür bitse de, Sen benim güneşim tek ışığımsın, Ben yine ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-yine-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Adam Olmazsın Ayrılık', 'hic-adam-olmazsin-ayrilik-ahmet-agdere-79yth', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmem kaç kere dedim sana,

Kapıma bir daha uğrama.

Hiç bilir misin söz dinleme,

Dolaşır da gelirsin bana! 

Sahi nedir bu hıncın, söyle? 

Ne çok mutluydu günler öyle? 

Hiç adam olmazsın ayrılık,

Bari sen mutlu musun böyle? ! 

Sırtına vursam da kırk satır,

Sanki benden kalır bin hatır! 

Bağışlanmışken alem sana,

Hep gel, hep gel beni batır! 

Yoktur keçide böyle inat! 

Tüm acıları bende sınat! 

Bak gör dünya ne güzel sensiz,

Başka alemlere aç kanat! 

İstemem senden gelen hayır! 

Git biraz da dostunu kayır! 

Dilde tüy bitti söylemekten,

Bilmem kaç kere dedim hayır! ..', 'Bilmem kaç kere dedim sana, Kapıma bir daha uğrama. Hiç bilir misin söz dinleme, Dolaşır da gelirsin bana!  Sahi nedir bu hıncın, söyle?  Ne...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hic-adam-olmazsin-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sevmeyeceksin', 'beni-sevmeyeceksin-erhan-saka-ehzpw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şeyi yazmışsın son mektubunda,

Anladım ki ümit vermeyeceksin,

Ümitsiz bir roman her satırında,

Anladım ki bana dönmeyeceksin.

Bir sitem yolladım geçen günlere,

Üzüldüm, ağladım bu cümlelere,

Seninki ihanet tüm sevenlere,

Anladım ki kıymet bilmeyeceksin.

Yinede kötü söz söylemem sana,

Hasretin yolları göründü bana,

Ben zaten gülmedim sevdadan yana,

Anladım ki beni sevmeyeceksin.

25-01-2004', 'Her şeyi yazmışsın son mektubunda, Anladım ki ümit vermeyeceksin, Ümitsiz bir roman her satırında, Anladım ki bana dönmeyeceksin. Bir sitem ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beni-sevmeyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilsemki', 'bilsemki-erhan-saka-qxvwo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onunla her türlü cefaya varım,

Bilsem ki birisi candan sevecek,

Razıyım ekmeğim olsa da yarım,

Bilsem k, birisi candan sevecek.

Geçtiği yollarda izi olurum,

Dilinden dökülen sözü olurum,

İstesin kalbime kilit vururum,

Bilsem ki birisi candan sevecek,

Gözümün bebeği gibi bakarım,

Başına mutluluk tacı takarım,

Kalbinde sevgiye sevgi katarım,

Bilsem ki birisi candan sevecek.

18-11-2003', 'Onunla her türlü cefaya varım, Bilsem ki birisi candan sevecek, Razıyım ekmeğim olsa da yarım, Bilsem k, birisi candan sevecek. Geçtiği yoll...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilsemki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bensiz Yapamazsın', 'bensiz-yapamazsin-i-brahim-dikmen-2-8k3bi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denedim,aklıma gelen,herşeyi,

Seni unutmak,imkansız bebeğim.

Ne bugün,nede yarın,

Anladımki ben,sensiz bir hiçim.

Sanmaki gecelerim,sensiz sessiz,

Seninle,dopdolu geçer,düşlerim.

Ne bugün,nede yarın,

Sensiz yaşayamam,inan sevgilim.

Ne,ben seni unuturum,nede sen,

Lakin,sende,beni unutamazsın.

Ne bugün,nede yarın,

Biliyorum,sen,bensiz yapamazsın.', 'Denedim,aklıma gelen,herşeyi, Seni unutmak,imkansız bebeğim. Ne bugün,nede yarın, Anladımki ben,sensiz bir hiçim. Sanmaki gecelerim,sensiz s...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bensiz-yapamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Şehirde Sabah', 'yorgun-sehirde-sabah-ensar-cevval-jzho3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehrin insanları tuhaf bir bilmece

Kuşu,böceği; çiçeği de keza

Pencere kenarında dalıp giden gün

Atılan ekmeğe lakayıt martılar

Boğazdan gelip geçen gemiler

Ve işte, kadim şehirde ilk saatler.

Ne çok yüz görürüm sabahları

Ne çok gülüş,bakış; yürüyüş; 

Bir yandan öbürüne taşınan yüzler

Öte yanda hasretle bekleyen gözler; 

Kimbilir kaçı geri dönecek gidenlerin

Kaçının sesi silinecek köhne surlardan,

Kaçının adımları geçecek bu sokaklardan.

Ne çok yüz..! 

Ne çok göz de bakışlarım gitti

Gözbebebeklerimden aynalar

Hangi yüze döndümse yitirdiğim bakışlar

Yorgunluk sirayet etmiş handeler,gülüşler...

Ve işte kadim şehirde ilk saatler.

Sirkeci 30 Mart'' 04', 'Bu şehrin insanları tuhaf bir bilmece Kuşu,böceği; çiçeği de keza Pencere kenarında dalıp giden gün Atılan ekmeğe lakayıt martılar Boğazdan ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yorgun-sehirde-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birisi', 'birisi-erhan-saka-bw9os', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakmayın siz benim yaşlı gözüme,

Damla, damla yaktı beni birisi,

Kapılar kapandı bir, bir yüzüme,

Kalbime hasreti ekti birisi.

Tatlı bir rüya iken kabusa döndüm,

Onunla bir değil bin kere öldüm,

Aşkımız bir ömür sürecek bildim,

Hayatı zehire kattı birisi,

Tozlanmış bir yığın anı bıraktı,

Aydınlık dünyamın güneşi battı,

Aldığım nefese acılar kattı,

Ölmeden canımı aldı birisi,

18-10-2003', 'Bakmayın siz benim yaşlı gözüme, Damla, damla yaktı beni birisi, Kapılar kapandı bir, bir yüzüme, Kalbime hasreti ekti birisi. Tatlı bir rüy...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birisi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkım Değilmi', 'hakkim-degilmi-erhan-saka-9utbk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küstürdün hayata beni genç yaşta,

Yaşamak benimde hakkım değil mi,

Hasretin içimde yüreğim yasta,

Mutluluk benimde hakkım değil mi.

Yıllar zincirini  boynuma taktı,

Gittiğim yollarda ümitler battı,

Gözümden yaşlarım kan oldu aktı,

Yaşamak benimde hakkım değil mi.

Kalbimde duygudan eser kalmadı,

Kaç kere sevdiysem seven olmadı,

Sevginin ateşi beni bulmadı,

Sevilmek benimde hakkım değil mi.

18-01-2004', 'Küstürdün hayata beni genç yaşta, Yaşamak benimde hakkım değil mi, Hasretin içimde yüreğim yasta, Mutluluk benimde hakkım değil mi. Yıllar z...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hakkim-degilmi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masumca İnandım', 'masumca-i-nandim-erhan-saka-aca99', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Masumca inandım gülen yüzlere,

Ömrümü harcadım yalan sözlere,

Yıkıldım yenildim şimdi dertlere,

Kendimi zincire vursam yeridir.

Gördüm ki yanımda kimse kalmamış,

Dar günde halimi seven olmamış,

Yaşanan sevgiler hepsi hataymış,

Başımı taşlara vursam yeridir.

Yokluğa canımı verdim de geçtim,

Hayat mutfağında zehiri içtim,

Kendime çileyi arkadaş seçtim,

Kafama bir kurşun sıksam yeridir.

14-08-2003', 'Masumca inandım gülen yüzlere, Ömrümü harcadım yalan sözlere, Yıkıldım yenildim şimdi dertlere, Kendimi zincire vursam yeridir. Gördüm ki ya...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/masumca-inandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri Kızı', 'peri-kizi-muslum-cagli-jle26', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yıldızlardan taç yaptım saçlarına

gümüşten bir çiçek duvağına

bulutlardan bir gelinlik yaptırdım

elmaslı papuçlar ayaklarına

yüreğimi koydum ellerine her gece

her gece bir yağmur yağar öylece

ben zaten sırıl sıklam aşığım

dudaklarımda sen varsın hece hece

sen benim gözümde güzelsin 

benim aynalarımda peri kızı

sen benimsin bana özelsin

ey karanlık gecelerimin yıldızı

peri kızı', 'yıldızlardan taç yaptım saçlarına gümüşten bir çiçek duvağına bulutlardan bir gelinlik yaptırdım elmaslı papuçlar ayaklarına yüreğimi koydum...', ARRAY['Türk Edebiyatı','Şiir','Müslüm Çağlı']::text[], 8.5, '{"poet":"Müslüm Çağlı","poet_slug":"muslum-cagli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/peri-kizi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedik', 'bilemedik-ahmet-agdere-7xgj2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne sevgiler, ne sevgililer gördük,

Birbirinden güzel sözler sarfettik,

Her seferde vurdu beni ayrılık,

Bizler asıl sevgiyi bilemedik! 

Birimiz oldu Mecnun, birimiz Leyla,

Bizdeki güce sahip değildi Lala! 

Bak gör işte dost,  bizdeki gönüller pala,

Aslolan sevgiyi bilemedik haala! 

Bin sevgiyle yüreği hazan ettik,

Ayrıldık diğeriyle bayram ettik,

Sonunda bu gönülü kurak ettik,

Bizler asıl sevgiyi bilemedik..

.

Günler su gibi akıp gitti boşa,

Tasarruf varken israf gider mi hoşa? 

Güllük gülistanlıklar döndü varoşa,

Asıl sevgiyi bilemedik haala! ..', 'Ne sevgiler, ne sevgililer gördük, Birbirinden güzel sözler sarfettik, Her seferde vurdu beni ayrılık, Bizler asıl sevgiyi bilemedik!  Birim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilemedik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankaralım', 'ankaralim-ersan-kurt-8l8gx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç yıl önce seni beklesem gelir misin oraya 

çevirsem tarihi geriye beni bulur musun burada 

nedir nerededir bilmediğim 

hayalimde bile görmediğim 

taş mıdır toprak mıdır gezmediğim

o köyümüzün dağlarında 

çok yıl öncesinde bekleyeceğim seni

sen de bir hayal değilsin o dağ gibi

gelmeyeceğini bilsem de karam

cankaram, gözü karam, Ankaralım

gönlüm sende gözüm yolda 

takvimini bilmediğim zamanlarda 

birlikte gezelim o dağlarda. 

30 Mart 2004, Kuzey Denizi', 'Kaç yıl önce seni beklesem gelir misin oraya  çevirsem tarihi geriye beni bulur musun burada  nedir nerededir bilmediğim  hayalimde bile gör...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ankaralim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan', 'nisan-sule-aydemir-63157', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'deli ediyor bu 

denizden manzara 

oturtup yerime 

kanına giriyor ayaklarımın

çıldırtıyor asi ruhumu 

bahar vurgunu

nereden geliyorsa

geliyor bu nisanlar

nisan

ömrü nisan yağmurları kadar

bir uzayıp bir kısalırken 

fikrimde yollar

durgun kalıyor çağlayanlar

açılan çiçeklerde 

dökülüyor ağaçlardan

nisanda kırağıya 

vurduruluyor koruklar

belki bir haziran sabahı 

bizim oluyor sessizce

ağrısız doğumlar', 'deli ediyor bu  denizden manzara  oturtup yerime  kanına giriyor ayaklarımın çıldırtıyor asi ruhumu  bahar vurgunu nereden geliyorsa geliyor...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nisan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçiyor', 'geciyor-abdil-yildirim-k76j2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu fâni dünya bir kudret aynası,

Her gelen bir kerre bakıp geçiyor.

Her nefis geçici, yoktur bekası,

Hayat bir su gibi akıp geçiyor.

Gençliğe hayatın baharı derler,

Her bahar yerini güze terkeder,

Nihayet yapraklar sararıp gider,

Mevsimler boynunu büküp geçiyor.

Kudret eli ile dönüyor devran,

Gökte bir kaç yıldız sonüyor her an,

Vücut sarayını yıpratan zaman,

Her gün bir taşını yıkıp geçiyor.

Bir kararda kalmaz dünyanın hali,

Kışın fırtınası, baharın seli,

Hayat dediğin bir serap misali,

Ömür şimşek gib çakıp geçiyor.', 'Şu fâni dünya bir kudret aynası, Her gelen bir kerre bakıp geçiyor. Her nefis geçici, yoktur bekası, Hayat bir su gibi akıp geçiyor. Gençliğ...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geciyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-abdil-yildirim-yrwfe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün battı ufuklar kızardı yine,

Bir kâbus misali çöker geceler.

Kan kırmızı tepelerin üstüne,

Siyah saçlarını döker geceler.

Karanlığın zincirleri çözülür,

Uzaklardan hayaletler sezilir,

Gözlerimden ağır ağır süzülür,

Gelir düşlerime akar geceler.

Siyah kollarıyla sarmış her yanı,

Ormanlar esniyor, uyku zamanı,

Yıldızlarla yaldızlanmış yorganı,

Dünyanın sırtına çeker geceler.

Çeşmelerden akar zikir bestesi,

Bir ilâhi olur suların sesi,

Kararınca arzımızın kubbesi,

Nurlu kandilleri yakar geceler.', 'Gün battı ufuklar kızardı yine, Bir kâbus misali çöker geceler. Kan kırmızı tepelerin üstüne, Siyah saçlarını döker geceler. Karanlığın zinc...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geceler-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülyası da Gurbettir', 'hulyasi-da-gurbettir-abdil-yildirim-wvejx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gönle gariplik çöktükten sonra,

Hanesi de, sılası da gurbettir.

Hasretlik boynunu büktükten sonra,

Rüyası da, hülyası da gurbettir.

Farketmez gurbette ne yokuş, ne düz,

Görmeyene birdir gece ve gündüz,

Yokda çevresinde tanıdık bir yüz,

İki kaşın arası da gurbettir.

Şah damarı kadar yakın da olsa,

Uzaktır arada bir perde varsa,

Gönül arzuluyor, göz görmüyorsa,

Şu duvarın arkası da gurbettir.', 'Bir gönle gariplik çöktükten sonra, Hanesi de, sılası da gurbettir. Hasretlik boynunu büktükten sonra, Rüyası da, hülyası da gurbettir. Fark...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hulyasi-da-gurbettir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Mü?', 'mu-hurrem-yalcin-ak86s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onarmak

Mümkün mü? 

Kırılmış yüreği...

Geri almak

Mümkün mü? 

Geçmiş zamanı...

Diriltmek

Mümkün mü? 

Ölmüş canı...

Toplamak

Mümkün mü? 

Parçalanmış sırçayı...

Harcamak 

Mümkün mü? 

Sarfedilmiş parayı...

Duymamak 

Mümkün mü? 

Söylenmiş acı sözleri...

Kazanmak

Mümkün mü? 

Kaybedilmiş dostları...

Affetmek

Mümkün mü? 

Terkeden sevgiliyi...

Ve  daha  nice  yitikleri

Elde  etmek...

MÜMKÜN         **? 

31.03.2004', 'Onarmak Mümkün mü?  Kırılmış yüreği... Geri almak Mümkün mü?  Geçmiş zamanı... Diriltmek Mümkün mü?  Ölmüş canı... Toplamak Mümkün mü?  Parç...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliyim', 'deliyim-nal-n-yildiz-pbu1r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Habil''e...



Ruh hastalığı diyorlar yaşadığın zamanı beğenmeme haline ruh hastası olmak tarifsiz bir tad veriyor bana. Beyin dolusu laf etmek yerine ağız dolusu laf eden insanlarla konuşma mecburiyeti yoruyor beni. En bayağı saldırıları, en sıradan mukabelelerle geçiştirme hali bozuyor erdem muhasebemi...Hira''daki yalnızlığın bir saniyesi için neler vermezdim.

'' İktidarı '', Adolf Berle''nin dilinden onyedisinde okudum iflah olmam, hırçın kayıtsızlıklara mahkum edemez kimse beni. Yalan meşru, inkâr sıradan, yabancılığım iktidar retoriğinin koroya uymamasından. 

Beşeri zaafiyetlerimin omuzlarıma bindirdiği yalnızlık, maksuduna giden dervişin erbaini... 

Kirpiklerini ıslatacak kadar bir sevda gözlerime habire yağıyor. Sen gözlerinde gece uyuyorsun. Yok şehrinin dehşetli ayazında terkedilmiş bir istasyonda geçip gitmiş bir treni bekler gibiyim. Biletim donmuş parmaklarımda, vücudum depremli..Cebimde Foucault klâsik çağın delisi...

Hicazkâr bir saz semaisinin kanatlarıma taktığı o tatlı rüyanın ritmindeyim. 

Aşka beden biçilirken elest bezminde benim de hisseme düşen bu işte; sözlükleri parçalayan bir deli...

İçimde bir deniz kabarıyor, lodos dalgaları savuruyor, benim yüreğim dünyayı. Beynimde ıslak martılar ağlaşıyorlar, yağmur fırtınasında kaybettikleri eşlerini arıyorlar.

Üstüne sahaf eskilerimi örtüyorum üşüme diye. Sen, bensizliğine sarılıp rahatça uyuyorsun çünkü ben gürültüsü kendi içinde bir deliyim, belki bu yüzden ipliksiz iğneler yutmuş gibiyim.', 'Habil''e... Ruh hastalığı diyorlar yaşadığın zamanı beğenmeme haline ruh hastası olmak tarifsiz bir tad veriyor bana. Beyin dolusu laf etmek ...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/deliyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Gider', 'her-sey-gider-abdil-yildirim-wd4jb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman bir su gibi durmadan akar,

Hafta gider, mevsim  gider, yıl gider.

İlkbaharda renkler seyrana çıkar,

Sarı gider, yeşil gider, al gider.

Hasretlik içimde dinmeyen sancı,

Şu dünya hanında ben bir yabancı,

Hem han ihtiyarlar, hem de hancı,

Hancı gider, yolcu gider, yol gider.

Kâinat bir ağaç kudret bağında,

İnsan bir meyvedir dünya dalında,

Her şey akıp gider kendi yolunda,

Ağaç gider, meyve gider, dal gider.

Elbet bu nizamın var bir sahibi,

Sonsuza uzanır göklerin dibi,

Arzımız yürüyen merdiven gibi,

Deniz gider, nehir gider, göl gider.', 'Zaman bir su gibi durmadan akar, Hafta gider, mevsim  gider, yıl gider. İlkbaharda renkler seyrana çıkar, Sarı gider, yeşil gider, al gider....', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-sey-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalacak Olanlar', 'kalacak-olanlar-abdil-yildirim-w03f6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fânisin, gaflete dalma ey insan,

Baharın gidecek, kışın kalacak.

Saçlarına karlar yağdığı zaman,

Gözünde biriken yaşın kalacak.

Bel bağlama bir gecelik rüyaya,

Sım sıkı sarılma yalan dünyaya,

İndirir sırtandan, kalırsın yaya,

Geride evladın, eşin kalacak.

Ecel davet eder, yaşlı geç demez,

Kimse bu davete hayır diyemez,

İnsan nasibinden fazla yiyemez, 

Belki de tabakda aşın kalacak.

Dostların kabre dek eşlik ederler,

İmam ''nasıldı'' der, ''iyiyidi'' derler,

Toprağın bağrına koyup giderler,

Başucunda mezar taşın kalacak.', 'Fânisin, gaflete dalma ey insan, Baharın gidecek, kışın kalacak. Saçlarına karlar yağdığı zaman, Gözünde biriken yaşın kalacak. Bel bağlama ...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalacak-olanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkum', 'korkum-buket-sema-caner-04d9z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tutma  ellerimi gözlerimede bakma

Korkunç birsavaşın eşiğindeyim.

Aklım duygularıma yenik düşerse

Biliyorum sana gitme kal diyececeğim....

Toplumun köhne kurallarına eğip boynumu

Benden beklenenleri hep  vereceğim

Bir volkan gibiyken aşkınla dolu yüreğim

Bitti artık aşkımız hadi git diyeceğim..', 'Tutma  ellerimi gözlerimede bakma Korkunç birsavaşın eşiğindeyim. Aklım duygularıma yenik düşerse Biliyorum sana gitme kal diyececeğim.... T...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korkum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmak Vardı', 'olmak-vardi-necmi-unsal-zbgyr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nice  gözyaşı  özlemde  seller  gibi  doğar.

Gurbet  akşamları  ümit  kuşlarını  boğar.

Kalksın da  bütün  engeller,  kavuşsun  sevenler.

Şimdi  sevgiye  ulaşan  bir  yol  olmak  vardı! 

Dünya balta girmemiş bir orman gibi, kurt çok.

Rabbena hep bana, başka canı düşünen  yok.

Sevgi, sohbet  divanına  otursun  gelenler.

Şimdi  vahşete  atılan  bir  gol  olmak  vardı! 

Kölelerin  zikri; helal-haram  ver  Allahım! 

Aç  gözleri  hiç  doymaz;  bu  kulun  yer  Allahım! 

Millet malı,  yetim malı  hep  kussun  yiyenler.

Şimdi  hayatta  oynanan  bir  rol  olmak  vardı! 

Muhabbet  meydanlarında neşe  koştursun  at.

Burnu  sürtülsün  kalleşin,  âbat  olsun  polat.

Dosttan selam alınınca hoş  bulsun  verenler.

Şimdi  boyuna  sarılan  bir  kol olmak  vardı! 

13 Mart 2004 Cumartesi, Danimarka-Køge  23.40

8+6', 'Nice  gözyaşı  özlemde  seller  gibi  doğar. Gurbet  akşamları  ümit  kuşlarını  boğar. Kalksın da  bütün  engeller,  kavuşsun  sevenler. Şi...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olmak-vardi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak gibi', 'toprak-gibi-buket-sema-caner-ofa8q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söyle sevgili sevebilirmisin 

Bir başkasını benim üzerime

Okşarmı ellerin bir başka bedeni

Bakıpta gözlerinin içinde

Kendini bulurmusun 

Benim gözlerim gibi

Belki sevgilim belki.

Toprağım ayaklarının altında

Bugün basıp çiğnediğin

Belkide avuçladığın

Çiçek dikmek için saksıya koyduğun

O toprak ki şimdi umursamadığın

Gün gelip örtecekyorgun bedeninisenin....', 'Söyle sevgili sevebilirmisin  Bir başkasını benim üzerime Okşarmı ellerin bir başka bedeni Bakıpta gözlerinin içinde Kendini bulurmusun  Ben...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/toprak-gibi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-buket-sema-caner-78rc1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Negüzel şey senin gibiolmak

Hiç bir kötülük fesatlık yok içinde

Hayatın getireceği üzüntüler, insanların kalleşliklerini

Bilmeden yaşamakne güzel şey küçüğüm.

Dünyanın gidişatı,geçim sıkıntısıumrundadeğil

Negüzelşeysenin gibi olmak kküçüğüm

Dünyayı pembegözlüklerle görmek

İçten kahkalarla gülmek,sevgiler içinde büyümek

Yarının neler getireceğini bilmeden

Bu günlerini yaşa küçüğüm keyfince

Bilsenki yarın neler getirecek sana

O küçücük omuzlarına neler yüklenecek

Nelere boyun egiğnelere göğüs gereceksin

Nelere isyan edecek körpe yüreğin

Bir bilsen küçüğüm

Hiç büyümek istemezsin', 'Negüzel şey senin gibiolmak Hiç bir kötülük fesatlık yok içinde Hayatın getireceği üzüntüler, insanların kalleşliklerini Bilmeden yaşamakne ...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kucugum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam ''Otelde''', 'bir-adam-otelde-sirma-mersin-aow56', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sus pus düşüncelerimin...

Senli benli hayallerini kurarken, duygularım! 

Bir otel odasının kapısında; 

Bekleyen adam, yüreğinle yüreğimi çağırıyordu.

Kaçarken! 

Sevdanın tuzağına düşen bir adamın, 

Sevgi dolu sevişken yüreği idi,

Beni odasına alan...

Aklım dışarıda,

Ruhum onunla...

Gecelerin sonunda...

Tükenmemiş sevgi ile,

Çoğalan zaman,

Bir başka mekanda; 

Buluşmak üzere...

Verilmiş sözler,

Bitmemiş özlemlerin izi ile,

Yaşanacaklar yaşanır...

Çırılçıplak ruhlarda! 

31.03.04', 'Sus pus düşüncelerimin... Senli benli hayallerini kurarken, duygularım!  Bir otel odasının kapısında;  Bekleyen adam, yüreğinle yüreğimi çağ...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-adam-otelde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasan usta', 'hasan-usta-buket-sema-caner-p3k24', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dar gelirli bir ailenin oğluydu Hasan

Okuyamadı yoksulluktan

Bir fabrikanın makinasıyla 

Bütünleşiverdi gün geldi Hasan

Hergün birsene gibi geçti

Ağardı saçlarıbüküldü beli

Evde iki çocuk birde karısı

Boğaz tokluğuna yıllarca çalıştı

Yıllar geçerken ardıardına

Ümitlerini arzularını götürdüyüreğinden

Robotlaştı Hasan usta.

Öylesine verdiki kendini çalışmaya

Ölüverdi bir gün makina başında.', 'Dar gelirli bir ailenin oğluydu Hasan Okuyamadı yoksulluktan Bir fabrikanın makinasıyla  Bütünleşiverdi gün geldi Hasan Hergün birsene gibi ...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hasan-usta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahırdağ''da Kör Kurşun', 'ahirdag-da-kor-kursun-hakan-yasar-y3irw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(K.Maraşlı Ali Karaoğlan anısına)  

1

Ahırdağ''da hüzün boğuk boğuk

Alacakaranlık.

Baykuş suskun

Guam''ın dibinde Denizatı merkep.

Akrep korkunç gururlu

Yılan süte gelmez

Karnından kaçar aç Sırtlan

Suskun Ahirdağ,suskun.

Ahırdağ''ım nazlım,sebilim

Yazılı muskam,tılsımım.

Ulaşılmazında kartal yuvaları

Kuytuları sabır mahkumu

Doludizgin yürek.

Gurur şöyle dursun

Umut,onurdur ede''yi yaşatan

Gözleri cehennem

Elleri zebellah

Görmeye dursun hele

Diş döktürür porsuk''a alimallah.

2

Muskamın doruğundan bir ses yankılandı

Ciğeri ağzında gür

Etine yetmez bir civandı.

Bir yanı töre

Zihni can,

Bir eli ilaç

Diğeri kan.

Gerdeğe girecekti alacakanlıkta

Yarenler,kardeşler

Vurun sırtına! ..

Bu bizim karaoğlan.

Gözü pek

Delikanlı

Yiğit.

Uçtu kayalardan ahu edasıyla

Bir çırpıda Alikayası''na vardı

-nal izleri saklı-

Doruktan heybeti vurdu

Hey civanım

Mahşerin dört atlısı sanki.

Baktı ufkuna iç çekerek; 

Tilki kümeste kucak

Tavşan yılanla evli

Gül baygın,hayrat akmaz..

Can cana kardeş

Kan kana dost

Ve huzur hakim bir yaşam.

Hiçbiri olmaz halbuki

öfke dolu dolu

Musallattır bağrımıza...

Evvelin evveli budur karaoğlan

Karanfilden barış çubuğu olmaz

Dört kör kurşun gibidir sevişmek

Bitmektir ölüm,yok ettiğimiz değil.

3

Meltemi çılğındır muskamın

Bir başkadır aşk

Sarmaşıktır sevda

Sev sevebildiğince.

''kalk gidelim sevdiğim

........bu el bize yaramaz''

diyor türkü,

Türkü söyle sevdiğim

Söyleyebildiğince.

Şu gördüğün suna suyu Aksu''dur,

Huzur bilmemiş

Namuslu

Berrak

Ilgıt ılgıt karın doyurur.

Şu gördüğün de göllere gebedir

İkinci mememizdir Ceyhan.

Ne pamuk,ne tütün,ne de başak

Alınterinin yabancısı değildir,

Ova bizim..

Gez doyabildiğince

Suyundan iç

İç kanabildiğince.

4

Nazlımın ardından kaçtı

Dayanamadı

Yediremedi Güneş.

Bulut katar katar yürür

Karanlık cesur,daha kalleş.

Dere serçeleri çığırtkan

Mallar kıprak,huysuz.

Meltem kılık değiştirmiş

Şimşir sapsarı; 

Etme..

Öte git..

Destur! 

Vakitlerin en bedbahttı

Hayın

Peydahlanmış

Şehvane.

5

Ey ozan,

Dokuz ay,on gün dedik kemikleştik.

Turp gibiydim

Kızıl at''a bindim haymada.

Ne güz dedik ne de bahar

Gün geldi hakkımızı istedik,

Sabrettik..

Olmadı..

Piştik! 

Sevdim,

Şövalyeleri vardı

Koynuma salmak istemediler.

Sarmaşığıma yürüdüler hayın ayaklarıyla

Düğün vakti

Cengaverdim.

Gülemedik,

Bilemedik ki sancı tepmedik

İlk heyecanımıza demlenemedik.

Telli duvaklı gittim

Yüz görümlüğü veremedim

Öpüşemedik...

ekim ''93 ist.', '(K.Maraşlı Ali Karaoğlan anısına)   1 Ahırdağ''da hüzün boğuk boğuk Alacakaranlık. Baykuş suskun Guam''ın dibinde Denizatı merkep. Akrep korku...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yaşar']::text[], 8.5, '{"poet":"Hakan Yaşar","poet_slug":"hakan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":119,"source_url":"https://www.antoloji.com/ahirdag-da-kor-kursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım İmge, Güvenli Gelgit', 'yarim-i-mge-guvenli-gelgit-mehmet-tombuloglu-9tzi8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dudaklarımda öperek kutsadığım 

gümüş akıntısı gecenin içinden geçen

yorgun ama alkımlı gözleri 

aşkın tükenmez ateşiyle dağlı

bir oylum köz dü yaprağın yer çekiminde 

dökülsündü, döküldü külü 

iki kaş arası çatılmış ay ışığına

çift yönlü depremler gelip çöktüğünde

benim o:

sınırsız heyecanını 

düşlerin berrak suyunda deneyen

konukseverdir ya kelimeler hani açar kollarını

kıyıya güvenle ulaşmak için 

en uygun zamanını bekler gelgitin 

şafak sökünceye kadar da sürer düşü

ateşi harlanmış bu yarım imgeyi

benzersiz  biçimde içime çizen gölge

başıma ağrılar getiren sözsel dağarcığım

uykusuz geceler armağan eden bana	

ölümü yaklaştığında fil

bulur son nefesini vereceği kovuğu

ey baharın kollamasıyla alnımda göveren dal

artık bırak inme inmiş sözlerin peşini

son sözüm bu

tenhada soluklanmaya gidiyorum', 'dudaklarımda öperek kutsadığım  gümüş akıntısı gecenin içinden geçen yorgun ama alkımlı gözleri  aşkın tükenmez ateşiyle dağlı bir oylum köz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tombuloğlu']::text[], 8.5, '{"poet":"Mehmet Tombuloğlu","poet_slug":"mehmet-tombuloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yarim-imge-guvenli-gelgit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Adam ''Gecede''', 'bi-adam-gecede-sirma-mersin-l34xa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bi ilkbahar gecesinde! 

Karanlığın içine düşmüş; 

Bir bankın üzerinde, 

Bir adam...

Sevdaya özlemli yüreğinle; 

Bir yıldızın içine,

Hayallerini ve sevgilisini 

Sığdırmış iken...

Sevdasının sızısı,

Sessizliği sesini bozar...

''Tatlım, şuan uzaktasın'' diyen bir adam..

Telefonun karşısında; 

Sevdaya aç bi kadın sesi,

''Canım! o parlayan yıldıza bak, birazdan yüreğine kayacak'' der...

Gecede! 

Mutlu sona teslim olan, 2 yürek...

01.04.04', 'Bi ilkbahar gecesinde!  Karanlığın içine düşmüş;  Bir bankın üzerinde,  Bir adam... Sevdaya özlemli yüreğinle;  Bir yıldızın içine, Hayaller...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bi-adam-gecede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum', 'oglum-buket-sema-caner-1nq7h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin çakmak çakmaktı

Çocukluğun arkada kalmış

İnliyordu Erciyes sesinle

Namusum, şerefim diyordun

Anladım seni mavi berelim

Önce Vatan  diyordun

Karnımda taşıdığım daha dün gibi

Söyle bebeğimsöyle ne zaman büyüdün

Daha dün elinden tutup balonlar aldığım

Ağladığında gözlerini sildiğim

Mutluluğum evime neşe veren

Ne zaman büyüdün hiçfarkedemedim

Önce Erciyeste gürledisesin

Şimdi Siirtte tam bir askersin

Gururla dopdolu ana yüreğim', 'Gözlerin çakmak çakmaktı Çocukluğun arkada kalmış İnliyordu Erciyes sesinle Namusum, şerefim diyordun Anladım seni mavi berelim Önce Vatan  ...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oglum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sevmek', 'seni-sevmek-ayten-ozlem-yesilcali-2bkko', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yılın dört mevsiminde seni sevdim.

Bazen ezbere bildigim her şeyi unuttum.

Ama bir tek seni unutamadım.

Beynime damıttıgım umutları büyüttüm.

İçimde bir sabah beni sıcacık öpüşlerle; 

Uyandıracagın günü bekledim durdum.

Seni ben ne çok sevdim...

Sevdim seni; 

İnanılmaz yollardan geldim,puslu yollardan

Ellerim unutmadı ellerinin sıcaklıgını

Gün oldu yaşanmamış hüzünler ısmarladım sevgime

Teninde erimeye geldim,bedenim unutmadı sıcaklıgını.

Seni öyle sevdim.', 'Yılın dört mevsiminde seni sevdim. Bazen ezbere bildigim her şeyi unuttum. Ama bir tek seni unutamadım. Beynime damıttıgım umutları büyüttüm...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-sevmek-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak seninle', 'yasamak-seninle-ayten-ozlem-yesilcali-538ia', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni sensizde yaşarım gülüm.

Seni sevmek beynimdeki bir patlama,

olarak kalacaktır.Korkmuyorum gülüm.

Seni sensizde yaşarım.

Bazen sensizlik bedenimi damla damla eritir.

İçimdeki senle tükenirim kimseler bilmez.

Ben seni sensiz de yaşarım gülüm.

Ama sen beni yaşayamazsın yoksun olamazsın.

Gün olur teslim olurum korkularıma.

Görmezsin kendini seni korkularımda yaşarım.

Gecenin bir yarısı kanter içinde uyanırım.

Kimbilir kaçıncı yitirişimdir  rüyamda seni.

Haketmedigim yenilgilerimde; 

Seni yanlızlıklarımda yaşarım.

Bir kar tanesi düşmüş gibi,

rengini unuttugum çiçeklerin üzerine.

Bogazımda dügümlenen sancılarda yaşarım.

Ben seni sensizde yaşarım gülüm.

Bedeli kipriklerimdeki yaş olsa bile.', 'Ben seni sensizde yaşarım gülüm. Seni sevmek beynimdeki bir patlama, olarak kalacaktır.Korkmuyorum gülüm. Seni sensizde yaşarım. Bazen sensi...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yasamak-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Türkü', 'mavi-turku-sadik-softa-iyj8m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doruğunda duygunun, bin kere ölüyorum,

Yükü ağır gelse de, an be an çekiyorum,

Kahır bulaşmış güne, ben hala gülüyorum.

Saksı olmuş yüreğim, maviler ekiyorum.

Erirken devleşiyor, umut zirvede şimdi,

Yediveren dirilmiş, boyumca gövde şimdi.

Ayrılığa bir tırpan, gönder bir gülle şimdi,

Acıların üstünden, şöyle bir sekiyorum.

Gözlerim takılmıyor, resimlerimi yırttım.

Aynalar uzak bana, vurdum, kırdım, dağıttım.

Ömrümün ortasında, çağlayan bir ağıttım.

Gönlümde tomurcuklar, çiçekler ekiyorum.

Bir mavi türkü başlar, yürür günün üstüne.

Mavi atlas örtüler, serdim dünün üstüne.

Bahtımı açıyorum, ördüm ünün üstüne.

Geleceğe ip gibi, seninle çekiyorum.', 'Doruğunda duygunun, bin kere ölüyorum, Yükü ağır gelse de, an be an çekiyorum, Kahır bulaşmış güne, ben hala gülüyorum. Saksı olmuş yüreğim,...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mavi-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz olmaz', 'sensiz-olmaz-ayten-ozlem-yesilcali-21od8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece yine kendimle yanlız kaldığım,

gecelerden bir gece karanlık sensiz.

Evin menekşe renkli duvarlarında; 

Senin dalga dalga hayalin var.

Gülümsemelerin gecenin karanlıgında yitip giden.

Bir ses beklemek senden soluk beklemek.

Suskunlugun en acımazsız oldugu gecede 

Bu kadar uzun susmadın o dört duvarda.

Hiç uzun gitmedin bilmedigim yerlere.

Sevgimi götürmeden yanında.

Seni sevmek sonu olmayan eylem olabilirmiydi.

Aykırı bir yaşamsa aşk.

Ben her bedele razıyım anla bunu.

Senin uzakların benim yakınım olmuşsa; 

Ne yapabilirdim? 

İlk kez bu kadar çok vuruyorum kendime.

Aglamaktan başka seçenegim yok.

Bu gün yenildim sana bekledigim sensin.

Oysa hani sıcaklıgınla gelecektin.

Yaşamak belki seninle anlamlıydı.

Sensiz yanlızlıkları hakettimmiydi.

Sensiz olmuyor...', 'Gece yine kendimle yanlız kaldığım, gecelerden bir gece karanlık sensiz. Evin menekşe renkli duvarlarında;  Senin dalga dalga hayalin var. G...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensiz-olmaz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-mucize-bahar-utak5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni çok özledim, 

Herşeyinle benim olmanı istedim... 

Ben imkansızı sevdim, 

İmkansız olan sendin... 

Biliyorum sen hep içimdesin, 

Her saniye beynimdesin.. 

Seninle dolu yüreğim, 

Ellerini tutmak istiyor ellerim... 

Sen! Ruhumun Işığı, 

Sen! Gönlümün Baharı, 

Sen! Yüreğimin Sevdası, 

Sen! Hayatımın Aşkı... 

İmkansızda olsan bana, 

SEVİYORUM SENİ daima...', 'Seni çok özledim,  Herşeyinle benim olmanı istedim...  Ben imkansızı sevdim,  İmkansız olan sendin...  Biliyorum sen hep içimdesin,  Her san...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-355-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak...', 'aglamak-i-brahim-ethem-bingul-j52qw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağla dediler bana,bebekler bile ağlarmış doğarken

Bir ağladım, sessiz kaldılar dinlerken

İkincisinde ağladılar benimle beraber ben ağlarken

Bitmedi gözümün pınarında yaşlar

Ağladım üçüncüde sabahları bulamadım gecelerden

Ağla dediler bana,bebekler bile ağlarmış doğarken

Ağladım sayamadım üçten sonrasını

Ne gözüme iyi bakabildim,korudum ne de ondaki yaşını

Görenler dediler etmiş dört,gayri gözündeki perdeyi ört

Dinlemedim dostları tek elimle silemedim gözümün yaşını

Ağla dediler bana,bebekler bile ağlarmış doğarken

Arada kalmış bir yüreğim şimdi

Kalbi temizler ağla diyenler sağım,sıkılıp of çekenler sol yanımda gayrı

Ne bebekliğim kaldı masumca döktüğüm yaşımda

Ne beşi,altısı hatırımda

Ağla dediler bana,bebekler bile ağlarmış doğarken

Ağladım üçüncü sevda sancısında

Ağladım bir mahrum hasta yatağımda

Dört! ! yolun sonuna gelmiş biri sağımda biri solumda

Ağlamak sırası onlara gelmiş kalmamış yerim yalan dünyada', 'Ağla dediler bana,bebekler bile ağlarmış doğarken Bir ağladım, sessiz kaldılar dinlerken İkincisinde ağladılar benimle beraber ben ağlarken ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aglamak-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-mucize-bahar-j5oiw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarın çok geç olmadan, 

Güller henüz solmadan, 

Mevsim kış olmadan, 

Gel bana sevdiceğim, 

Gel bana sevdalım... 

Bekliyorum seni... 

Toprağın yağmuru, 

Gecenin gündüzü, 

Beklediği gibi.... 

Hiç bir sevgi hata değildir, 

İmkansızdır belki ama 

Hata değildir... 

Gel bana Cankuşum... 

Seviyorum Seni.... 

Bekliyorum Sevgini....', 'Yarın çok geç olmadan,  Güller henüz solmadan,  Mevsim kış olmadan,  Gel bana sevdiceğim,  Gel bana sevdalım...  Bekliyorum seni...  Toprağı...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bekliyorum-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir misin bana?', 'gelir-misin-bana-mucize-bahar-h55wm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daglarin ardindan esen deli ruzgar,

Getirir mi kokunu bana...

Cilgin,hircin,sevgili deniz,

Ativerir mi seni dalgalariyla gonlumun kiyisina...

Ya parlak yildizlar gecelerden gozlerini,

Cekip,alip gozlerime hapsederler mi...

Kizgin yakici gunes yuregini,

Koyar mi ates gibi yuregimin uzerine....

Opmek icin nemli dudaklarini

Uzatir mi islak yagmurlar dudaklarima......

Dokunmak icin tenine,

Girer misin koynuma............

Hasretim sana,

Gelir misin bana? ? ? ? ? ?', 'Daglarin ardindan esen deli ruzgar, Getirir mi kokunu bana... Cilgin,hircin,sevgili deniz, Ativerir mi seni dalgalariyla gonlumun kiyisina.....', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gelir-misin-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultan Ahmet''e Selam', 'sultan-ahmet-e-selam-mustafa-yalcin-i92qc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir serin rüzgar eser, 

Surların parçalanmış yüreğinden

Taaa Sultanahmete kadar,

Saray üşür, titrer Sultanahmet

Böyle alır selamını Hüdainin, Sultan Ahmet

Büyük sultan uyanır ve şöyle der:

Bitsin artık efendim bu hasret

Ve doğrularak mezarından

Üsküdara koşar Sultan Ahmet', 'Bir serin rüzgar eser,  Surların parçalanmış yüreğinden Taaa Sultanahmete kadar, Saray üşür, titrer Sultanahmet Böyle alır selamını Hüdainin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yalçın']::text[], 8.5, '{"poet":"Mustafa Yalçın","poet_slug":"mustafa-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sultan-ahmet-e-selam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben hazanım', 'ben-hazanim-ayten-ozlem-yesilcali-ti16m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni birşeylere benzetmek istersen eğer; 

Ben hazanım..

Kimi zaman döne döne düşen sarı bir yaprak.

Kimi gün sesiz sesiz ağlayan bir yağmur.

Kimi an deli gibi savuran bir rüzgar.

Ben hazanm.

Beni bir çiçege benzetmek istersen eğer; 

ben kardelenim..

Yüksek daglarda karların altından fırlayan.

Koparmak sitediginde elini kanatan.

Erişemeyeceğin kadar derinde.

Korkacagın kadar narin.

Ben Kardelenim...

Beni bir renge benzetmek istersen eğer; 

Ben kırmızıyım.

Ne beyaz kadar saf ve katkısız.

Ne bordo kadar net ve kasvetli

İkisinin ortasıym.

Ben kırmızıyım..

Beni illa bir şeylere benzetmek istersen eğer; 

Ben SEVĞİ yim.

Bir meleğin gülüşü kadar içten.,

Güneşin doğuşu kadar sıcak.

Gecenin rengi kadar etkileyici.

Yaşam kadar ürkütücü.

Ben SEVĞİ yim.

YASEN  BİBER TANEM...', 'Beni birşeylere benzetmek istersen eğer;  Ben hazanım.. Kimi zaman döne döne düşen sarı bir yaprak. Kimi gün sesiz sesiz ağlayan bir yağmur....', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ben-hazanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozlem', 'ozlem-mucize-bahar-7eki4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi seninle olmak vardı, 

Yanyana elele... 

Şimdi seninle olmak vardı, 

Gözgöze başbaşa... 

Birlikte olmak vardı sonsuza dek, 

Hiç ayrılmadan... 

Paylaşmak vardı herşeyi...', 'Şimdi seninle olmak vardı,  Yanyana elele...  Şimdi seninle olmak vardı,  Gözgöze başbaşa...  Birlikte olmak vardı sonsuza dek,  Hiç ayrılma...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ozlem-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimiş Şehir', 'eskimis-sehir-berrin-demirbilek-5h1fk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eskimiş bir şehrin duvar taşıyım

ezik kaldırımların kahrolmuş seliyim

akar yağmurtanem çileli hayatıma

dökülür bağrımın mühür taşına...

Unutulmuş sokakların ayak iziyim

her yerim karanlık gece gibiyim

savrulmuş aşkımın son yaprakları

bu eskimiş şehrin en son eseriyim...

Adresim zavallı, yıkık, perişan

silinmişdir bilirim onun aklından

son bir hatırlasın geçsin sokağımdan

bu eskimiş şehri canlandır yaradan...', 'Eskimiş bir şehrin duvar taşıyım ezik kaldırımların kahrolmuş seliyim akar yağmurtanem çileli hayatıma dökülür bağrımın mühür taşına... Unut...', ARRAY['Türk Edebiyatı','Şiir','Berrin Demirbilek']::text[], 8.5, '{"poet":"Berrin Demirbilek","poet_slug":"berrin-demirbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eskimis-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-mucize-bahar-tn537', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle yaşamak vardı doludizgin. 

Her gece birbirimizi yenilemek vardı, 

Odalara sığmamak vardı, 

Bir sel gibi taşmak vardı gecelerden.... 

Zamana kokun sinmişti, 

Elimi uzatsam tutabilirdim seni 

Öyle yakındın ruhuma... 

Öyle sığdırmıştım dudaklarıma... 

Seni hiç bırakmamak, hapsetmek  kalbime... 

Çıkmana izin vermemek, 

İçimden çağlayan gibi taşmanı engellememek.. 

Varmak seninle doruklara, 

Ve sadece sende erimek, gözlerinde kaybolmak, 

Teninde yok olmak isterdim.......', 'Seninle yaşamak vardı doludizgin.  Her gece birbirimizi yenilemek vardı,  Odalara sığmamak vardı,  Bir sel gibi taşmak vardı gecelerden.... ...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seninle-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allahaşkına', 'allahaskina-berrin-demirbilek-007ip', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mendillerim hep ıslak gözyaşlarımdan

deva gelir bana bir tel saçından

mutluluk bulurum her satırından

bir mektup yolla Allahaşkına...

Uzaktasın diye güneşim buz tuttu

gözüme uyku girmiyor beni unuttu

karanlık dostum oldu beni avuttu

bir ışık gönder Allahaşkına...

Uçurumlar koymuşsun sanki araya

çekilmiyor bu hayat bunca acıyla

yıldızlar bile senden yakın şimdi bana,

bir selam gönder, bir ışık gönder,

bir kendini gönder Allahaşkına', 'Mendillerim hep ıslak gözyaşlarımdan deva gelir bana bir tel saçından mutluluk bulurum her satırından bir mektup yolla Allahaşkına... Uzakta...', ARRAY['Türk Edebiyatı','Şiir','Berrin Demirbilek']::text[], 8.5, '{"poet":"Berrin Demirbilek","poet_slug":"berrin-demirbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/allahaskina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlar', 'bulutlar-abdil-yildirim-jbeuk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarların kanadına tutunmuş,

Bulutlar pürtelâş, nere gidiyor.

''Yağmur başına arş'' emrine uymuş,

Katar katar, sıra sıra gidiyor.

Rahmetini damla damla indirir,

Yeryüzünün çehresini güldürür,

Bahar vagonuna erzak dolduru,

Bir bahardan bir bahara gidiyor.

İmdadına koşar ovanın dağın, 

Dal ucunda titreyen bir yaprağın,

Hararetten bağrı yanan toprağın,

Yarasını sara sara gidiyor.

Bulutlar var, perde olmuş tül olmuş,

Bulutlar var, bir vadiye oturmuş,

Yamaçların eteğine tutunmuş,

Zirvelere doğru kara gidiyor.', 'Rüzgarların kanadına tutunmuş, Bulutlar pürtelâş, nere gidiyor. ''Yağmur başına arş'' emrine uymuş, Katar katar, sıra sıra gidiyor. Rahmetini ...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulutlar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar Sana Açılır', 'yollar-sana-acilir-abdil-yildirim-92euo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüzler soluk olsa da,

Kollar sana açılır.

Yolcusu olmasa da,

Yollar sana açılır.

Çiğdem, menekşe, zambak,

Her türlü çiçek, yaprak,

Kayaları yararak,

Güller sana açılır.

Önünde boyun eğen, 

Rahmetini dileyen,

Seherde amin diyen 

Eller sana açılır.

İnsan çekse de çile,

Hak ismin gelir dile,

Günahkâr olsa bile,

Kullar sana açılır.', 'Yüzler soluk olsa da, Kollar sana açılır. Yolcusu olmasa da, Yollar sana açılır. Çiğdem, menekşe, zambak, Her türlü çiçek, yaprak, Kayaları ...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yollar-sana-acilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-yildiz-ark-xtx7p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gemilerim battı fırtınalarında,

yok yere...

Kurtulabilecekken kıyılarında

Ve çok defa boğuldum,

bir kaşık sularında ihanetin

Ama acıtmadı inan, söylediği

bir küçük yalan kadar sevgilinin...', 'Gemilerim battı fırtınalarında, yok yere... Kurtulabilecekken kıyılarında Ve çok defa boğuldum, bir kaşık sularında ihanetin Ama acıtmadı in...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Ark']::text[], 8.5, '{"poet":"Yıldız Ark","poet_slug":"yildiz-ark","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalan-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül ve Yer', 'gul-ve-yer-murat-berk-27nnz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül, gülü yollarsa,

O gül de yolda solarsa,

Solan gülleri alır 

Koynumda saklarım,

Daha yeşil daha kırmızı yaparım.

Sen Gülsün, ben yer

Ben yerdeyim sen gökte,

Ben altta sen üstte.

Sen Gülsün ben yer,

Sen gülesin  ben ırak yerlerde ağlayayım, 

Yeter ki yanında kalayım.

Sen Gül, ben yer

birleşince, o gül ve yer 

Belki deli, belki de aşık 

Olur  Şener….', 'Gül, gülü yollarsa, O gül de yolda solarsa, Solan gülleri alır  Koynumda saklarım, Daha yeşil daha kırmızı yaparım. Sen Gülsün, ben yer Ben ...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gul-ve-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile', 'cile-bulent-toprak-q5zre', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zamansız zemherinin orospusu,

Gül döktü yollara bana kan kustu

Ben sustum sen sustun namlular konuştu

Ölümü özledim! ...Ölümü özledim! ...Ölümü özledim!', 'Zamansız zemherinin orospusu, Gül döktü yollara bana kan kustu Ben sustum sen sustun namlular konuştu Ölümü özledim! ...Ölümü özledim! ...Öl...', ARRAY['Türk Edebiyatı','Şiir','Bülent Toprak']::text[], 8.5, '{"poet":"Bülent Toprak","poet_slug":"bulent-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cile-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretinden', 'hasretinden-hifzi-ozbekmez-zm6l9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyku tutmuyor geceler

Dilim adını heceler

Çare olmadı niceler

Hasretinden yanıyorum

Aşkından ben öleceğim

Seni nasıl göreceğim

Duy sesimi kır çiçeğim

Hasretinden yanıyorum

Demek almışım ahları 

Çekiyorum eyvahları

Akşamları sabahları

Hasretinden yanıyorum

Bekliyorum aynı yerde

Mevlam düşürmesin derde

Geceleri seherlerde

Hasretinden yanıyorum

Bu yolda çoktur ölenler

Var mı hiç bahtı gülenler

Sabahlar erken öğlenler

Hasretinden yanıyorum

Latif perişan hallerde

Aşkı dolaşır dillerde

Diyarı gurbet ellerde

Hasretinden yanıyorum

27 KASIM 2003 PERŞEMBE  SAAT: 06:00', 'Uyku tutmuyor geceler Dilim adını heceler Çare olmadı niceler Hasretinden yanıyorum Aşkından ben öleceğim Seni nasıl göreceğim Duy sesimi kı...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hasretinden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımızı Yaşayalım', 'askimizi-yasayalim-hifzi-ozbekmez-aulaq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fırsat varken dolu dolu

Aşkımızı yaşayalım

Bundan başka var mı yolu

Aşkımızı yaşayalım

Araya girmeden hasret

Bezdirmeden bizi gurbet

Ben seninim ilelebet

Aşkımızı yaşayalım

Bu dünya fanidir yalan

Olmayalım hemen solan

Dolan sen boynuma dolan

Aşkımızı yaşayalım

Ciğerler parelenmeden

Gönüller yarelenmeden

Ayrılık günü gelmeden

Aşkımızı yaşayalım

Bıkmadan hiç usanmadan

Gönül narına yanmadan

Kimselere inanmadan

Aşkımızı yaşayalım

Gözümüzden yaş dökmeden

Sinemize dert ekmeden

Hasret ciğerim sökmeden

Aşkımızı yaşayalım

Geçmesin hiç hevesimiz

Bitmesin hiç nefesimiz

Alemler duysun sesimiz

Aşkımızı yaşayalım

Latifiyim koş gel bana

Bu can kurban olsun sana

Güzelim biz kana kana

Aşkımızı yaşayalım

27 KASIM 2003 PERŞEMBE  SAAT: 08:00', 'Fırsat varken dolu dolu Aşkımızı yaşayalım Bundan başka var mı yolu Aşkımızı yaşayalım Araya girmeden hasret Bezdirmeden bizi gurbet Ben sen...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/askimizi-yasayalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mermer Kız', 'mermer-kiz-bulent-toprak-ewhh5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yedek parçası olmayan şu vücudumun

Naçar kalbini neden kırdın esmer kız

Şanzumanı dağıldı tekeri patladı umudumun 

Sayende gidemez oldum mermer kız!', 'Yedek parçası olmayan şu vücudumun Naçar kalbini neden kırdın esmer kız Şanzumanı dağıldı tekeri patladı umudumun  Sayende gidemez oldum mer...', ARRAY['Türk Edebiyatı','Şiir','Bülent Toprak']::text[], 8.5, '{"poet":"Bülent Toprak","poet_slug":"bulent-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mermer-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyler misin...', 'soyler-misin-i-brahim-ethem-bingul-uxzk5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Diyorsun ki

Mevsim bahar

Neden üşüdüm deminden

Bu beyazlıklar,bu aklar

Saçlarımdaki kar neden

Diyorsun ki

Aşkımsın yar

Dünden kalan siteminden

Gözüm ağlar,gönlüm ağlar

Bak,bendeki hasar neden

Diyorsun ki

Güller yağar

Şen duruşundan,neşenden

Öyleyse, bakışındaki diken

Canımı yakan har neden

Diyorsun ki

Hava açar

Evet,senin ikliminden

Olsam da içinde buhar

Kaplasam gönlünü derim

Söyler misin,çaresi nedir...', 'Diyorsun ki Mevsim bahar Neden üşüdüm deminden Bu beyazlıklar,bu aklar Saçlarımdaki kar neden Diyorsun ki Aşkımsın yar Dünden kalan sitemind...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/soyler-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BüYüK ALDANMA.!', 'buyuk-aldanma-baki-son-szfai', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O...

Mutlu bekleyiş ki...

Sarılır ellerime

___________Gülümser

Bir rüya alemi,

___________Dudaklarda

O an...

Üşümez karanlıklardan

___________Ellerim

En mutlu

Günleri getirir

___________Hatılaralardan

Ve siner mutluluğa

___________Gözbebeklerim

Bir andır,geçiverir

Dalıp gittiğim

___________Hatıralarım

Sararıp,solmada

___________Yapraklar

Her geçen gün

Bir sayfa  koparılır

___________Hayatımdan.

O...

Büyük sabrediş yok mu.? 

___________O aldanış.! 

Sevgi mi

Tutku mu

Gizlenir bulutlara.

___________İniverir,

Ümit yoluna

Son titrek ışık.

___________İşte

___________ALDANDIK...! ! !', 'O... Mutlu bekleyiş ki... Sarılır ellerime ___________Gülümser Bir rüya alemi, ___________Dudaklarda O an... Üşümez karanlıklardan _________...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/buyuk-aldanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Doğumdan ölüme,ölümden...', 'dogumdan-olume-olumden-sair-ahrazi-68v8c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evvela ismine kavuşur beden,

Sonra bir nefesin peşine düşer.

Hayâtı dünyâyı henüz bilmeden,

İnsanlık sıfatı yaşına düşer,

***

Kader yoludur bu kendi boyunca,

Ameli yazılır rûhu ayınca,

Birgün dile gelip anne deyince,

Yalnızlık korkusu başına düşer.

***

Oyun uğraş vakti beher zamanda,

İsteği arzusu çabuk hemende,

Kızgınlığı görüp kaçtığı anda,

Ümitler gözünden yaşına düşer.

***

Okul çağı ile gençlik yılları,

Bambaşka hâl alır çocuk halleri,

İki göz arası sevdâ yolları,

Geceden sabâha düşüne düşer.

***

Nice yıllar geçti belki severek,

Şimdi hayât başka düşünmek gerek,

Ömür bir başına geçmez diyerek,

Hak emri üzeri eşine düşer.

***

Yeni yuva gibi yeni yaşantı,

Bazen telaş çöker bazen üşenti,

Fikri mahzûn eden hangi düşüntü,

Yarının dertleri aşına düşer.

***

Neylersin ki artık hâlin yanmada,

Medet bekler olmuş sabrı anmada,

Gözlerin boşluğa her uyanmada,

İhtiyâr ömrünün kışına düşer.

***

Cân Ahrâzim sende girsen nazâra,

Gizli bendi aşıp gitsen kazâra,

Eni sonu elbet dönüp mezâra,

İsmin yalan gibi taşına düşer.

**************        ***************

**************        ***************          

Sorgu suâl ânı yargı mekânı,

Sîmâsız görürsün sana bakanı,

Kolay bırakır mı kabir yakanı,

Amelin her neyse eline düşer.

***

Mevlâ kimdir söyle efrâdın nerden,

Neden sustun şaşkın farkın ne körden? 

Zikrin fikrin çıkar açılan serden,

Niyetin her neyse eline düşer.

***

İşte dönülmeyen bilinmeyen kısım,

Herkes bir sırada bak isim isim,

Kimi var Hak dostu kimiyse hasım,

Günâhın her neyse yoluna düşer.

***

Ya ateşte yada bahçe içinde,

Bekler insanoğlu farklı biçimde,

Kalk diyecek o ses eşik açanda,

Kıyametin mührü koluna düşer.

***

Tıpkı bir tohumun çıkması gibi,

Tıpkı gökyüzünün çekmesi gibi,

Vaktiyle rençperin ekmesi gibi,

Rûhun mekansızlık iline düşer.

***

Renkten renge göre ayrım eyleyen,

Her kefeye miktar miktar paylayan,

Tahlil esnasında doğru söyleyen,

Cennet bağlarının dalına düşer.

***

Ey ahrâzim sende Mevlâm diyesin,

Hüküm Hak hükmüdür başın eyesin,

Mecnûnî hasretle mühlet sayasın,

Yaprak sevdâlıysa yeline düşer.

---*----', 'Evvela ismine kavuşur beden, Sonra bir nefesin peşine düşer. Hayâtı dünyâyı henüz bilmeden, İnsanlık sıfatı yaşına düşer, *** Kader yoludur ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/dogumdan-olume-olumden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Faydası', 'denizin-faydasi-cihan-paca-evvi0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ne zaman sertliğimden hoşlanmasa

 alelacele sahile inerim en kestirmeden

 bilirim! denizin ılımanlaştırıcı etkisi vardır

 ah şu duygularım da yaşlanmasa

 yanımdaki gençler sığ sularda çözülüverirken

 beni eritecek su iki okyanus kadarıdır

 ne denizi kendim için kullanmak isterim

 ne de sert görünüp sevenleri kızdırmak

 sabah akşam hacıya hocaya giderim

 çare değil ki sertliğime muska yazdırmak

 bunun için halim hallerini severim balıkçıların

 bir hikaye işittim onlardan en son anlattıkları

 meğer sert yanıymış çocukluğunda her insanın

 taş diye ellerine alıp denize fırlattıkları', 'ne zaman sertliğimden hoşlanmasa  alelacele sahile inerim en kestirmeden  bilirim! denizin ılımanlaştırıcı etkisi vardır  ah şu duygularım d...', ARRAY['Türk Edebiyatı','Şiir','Cihan Paça']::text[], 8.5, '{"poet":"Cihan Paça","poet_slug":"cihan-paca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/denizin-faydasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpek Böceği', 'i-pek-bocegi-gulsen-senderin-zy1fv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İpek böceği dut yaprağını yer misali

Aşkı sevgiyi ördükce tükendi yeşilim

Kozasında bir mahkum,krizalit olma hali

Oluşum yeni bene, artık o  ben değilim...

Uyuyuş sürmeyecek,  birgün bitecek elbet

Gönül arayacaktır, özgünce  bir saadet

Başardığı an  başka,bambaşkadır nihayet

Başkalaşım sürse ya,  süremez  ilelebet...

Uyanan kelebek yeniden hayat bulacak

O da yeni tırtıllara bir ana olacak

Kim demiş ki yalan dünyaya baki kalacak

Aşkıyla sevgiisyle tek ölüme koşacak', 'İpek böceği dut yaprağını yer misali Aşkı sevgiyi ördükce tükendi yeşilim Kozasında bir mahkum,krizalit olma hali Oluşum yeni bene, artık o ...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ipek-bocegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Tasavvuru', 'bahar-tasavvuru-cihan-paca-tfcpq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yeni bir bahar tasavvuru üzerinde çalışıyorum

 gerekirse kova kova su taşırım gökyüzünden

 diye düşünürken,

 bu kezde güneşin itirazıyla karşılaşıyorum

 eski canlılığını kaybettiği anlaşılıyor gözünden

 ben tek solgun haline üzülüyorum mezraaların

 bu ölü hali mevsimlerin kahrediyor beni

 baharın üzerinde son kez gezdiriyorum elimi

 ses yok nefes yok kıpırdanmıyor

 ruhum bu hayali şehirden kendini dışarı atıyor

 imreniyorum sürekli dolup boşalan haline mezarların', 'yeni bir bahar tasavvuru üzerinde çalışıyorum  gerekirse kova kova su taşırım gökyüzünden  diye düşünürken,  bu kezde güneşin itirazıyla kar...', ARRAY['Türk Edebiyatı','Şiir','Cihan Paça']::text[], 8.5, '{"poet":"Cihan Paça","poet_slug":"cihan-paca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bahar-tasavvuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duydum ki Sevdalar Satışa Çıkmış..', 'duydum-ki-sevdalar-satisa-cikmis-sengul-deper-qdehh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duydum ki sevdalar satışa çıkmış,

Satılıyor,gram,gram,istediğini al.

Öylesine ucuz,öylesine bol...

Kullan,fırlat at, sorun mu.

Kim dinler yürek sancısını

Kim anlar,sevginin kutsallığını

Hep öne çıkan, ben yine ben.

Çıkarlarla besleniyor sevdalar,

Çıkarlarla öldürülüyor...

Vuran vurana

Sevdaya yazık, ölüyor işte

İnsan sevdası, doğa sevdası

Sevda sevdadır işte

Görmesini bilene

Duydum ki sevdalar satışa çıkmış

İyi niyet dilimlere bölünmüş

Ezilmiş sevgiler

Kalmamış, heyhat bitmiş insanlık.

Sevdalar satışa çıkmış

Kan gölünde paylaşılmış...', 'Duydum ki sevdalar satışa çıkmış, Satılıyor,gram,gram,istediğini al. Öylesine ucuz,öylesine bol... Kullan,fırlat at, sorun mu. Kim dinler yü...', ARRAY['Türk Edebiyatı','Şiir','Şengül Deper']::text[], 8.5, '{"poet":"Şengül Deper","poet_slug":"sengul-deper","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duydum-ki-sevdalar-satisa-cikmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gül Koparttım..', 'bir-gul-koparttim-sengul-deper-h3z6e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gül koparttım dalından,

Öyle güzel, öyle özel ki.

Yapraklarını okşadım, kokladım.

Ve sevgiyle öptüm sen diye.

Nedendir bilmem, kalbim sıkıştı.

Sonra bir güle, bir ağacına baktım.

O gül ağacında olmalıydı,yeri orası.

Orda daha güzel,daha mutlu

Güvendeydi,önemlisi; canlıydı.

Ben koparttım,

Ben öldürdüm.

Yüreğim sıkıştı ağladım,

Öptüm sen diye, titrerken ızdıraptan.

Biliyorum yok dönüşü

Elimde gül, başım eğik giderken,

Seni düşündüm,döküldü göz yaşlarım.

Uzak diyarlardan yolladım sevgimi.

Ama... Gün olur görürsen beni,

Başını çevirme ne olur.

Bilmeni istediğim tek şey,

Unutma...

Seni ne çok sevdiğimi...', 'Bir gül koparttım dalından, Öyle güzel, öyle özel ki. Yapraklarını okşadım, kokladım. Ve sevgiyle öptüm sen diye. Nedendir bilmem, kalbim sı...', ARRAY['Türk Edebiyatı','Şiir','Şengül Deper']::text[], 8.5, '{"poet":"Şengül Deper","poet_slug":"sengul-deper","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-gul-koparttim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah hüzün ah', 'ah-huzun-ah-zafer-zengin-etnika-pxfkx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah hüzün ah

Kimseden habersiz

Çalıyorsun kapıları

yaramaz çocuk

Varolma sebebi

Ne çok gülüyorsun ellerime...

Gülümse...

Gülümse...

01.04.2004', 'Ah hüzün ah Kimseden habersiz Çalıyorsun kapıları yaramaz çocuk Varolma sebebi Ne çok gülüyorsun ellerime... Gülümse... Gülümse... 01.04.200...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ah-huzun-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İktidar', 'i-ktidar-emin-baydil-98qyw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine binbir iltimas pençesinde bu millet

Gör ki neler çekiyor, kalk da  bir temaşa et.

Devlet kapısında hem bir tezgâhtır kurulmuş,

............... adına kan kusuyor adalet.

Öyle bir düzen ki bu, her şey yerli yerinde

Sayısız maznun ağlar, yukardan en derinde.

Gülenler şerefine, kaldırılan kadehler

Başında parçalanır, zulmün her seferinde.

Bu alevsiz yangınla bu duyulmaz zelzele

Akıllara sarılıp artarsa günden güne,

Geride en nihayet bir savrulan kül kalır

Kendince kül olanın, kim ağlar öldüğüne.! ..

İşte yine savrulur, nutuklar meydan meydan,

İşte yine duyulur, Edirne’den tâ Van’dan.

Hâlâ bir teranedir yurdun dört bucağında

Tutturulmuş gidiyor, hem de hiç sıkılmadan.

.......nci yıl ha öyle mi, hangi yüzle bu tören? 

Utanmak lâzım hele, elden dilenir iken.

Nurlu ufuklar hani, nerde güçlü Türkiye? 

Hiç olmazsa konuşma, meydan dilencisi sen...

Evet, sen sus konuşma, Allah’tan, kuldan utan! 

Ben değilim herhalde, vaadleri unutan.

Her gün bir başka yerde dağları erittiniz,

Tam elli yıldan beri, hizmet beklerken vatan.

Bunlar yetmezmiş gibi, çok işler başardık de,

Bu büyük bir gaflettir, hiyanet değilse de.

Hem Almanya, Japonya, bir baksana nerdeler,

Haykıran devlet gördüm, çünkü tam on senede.

Elli yıl dile kolay, bir asrın yarısıdır,

Şanınıza yakışan, size yüz karasıdır.

Bu millet, hiçbir zaman düşmanından çekmedi,

Bu milletin çektiği, iktidar belâsıdır...

Not: Bu şiir, otuz yıl önce yazılmıştı. Şimdi ise,.......', 'Yine binbir iltimas pençesinde bu millet Gör ki neler çekiyor, kalk da  bir temaşa et. Devlet kapısında hem bir tezgâhtır kurulmuş, ...........', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/iktidar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-ferit-teksoy-drboq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel de..

Benim romanımı yaz

Yazılmalı bu roman

Kaç asır geçti bilirmisin,aradan? 

Leyle ile Mecnun''lar yazılmadan

Yürekliyim ya,

En alâsından..

Ya sen gel,ya ben

Susamışlık bitmeden

Daveti kaçırmadan! ..', 'Gel de.. Benim romanımı yaz Yazılmalı bu roman Kaç asır geçti bilirmisin,aradan?  Leyle ile Mecnun''lar yazılmadan Yürekliyim ya, En alâsında...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/davet-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Yıllardan Önce Gözlerine Vurgundum', 'nice-yillardan-once-gozlerine-vurgundum-i-smet-kemal-turkay-0c6cf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nice yıllardan önce, 

gözlerine vurgundum,

aradan zaman geçti,

seni unutamadım.

Bilki herşeyimdin sen,

ümit doluydu kalbim,

birdenbire ayrıldık,

araya yıllar girdi.

Dedim demez olaydım,

aşkım sana derdimi,

sonu gelmeyen figan,

çekilecek çilemi.

Bilki herşeyimdin sen,

ümit doluydu kalbim,

birdenbire ayrıldık,

araya yıllar girdi.', 'Nice yıllardan önce,  gözlerine vurgundum, aradan zaman geçti, seni unutamadım. Bilki herşeyimdin sen, ümit doluydu kalbim, birdenbire ayrıl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Kemal Türkay']::text[], 8.5, '{"poet":"İsmet Kemal Türkay","poet_slug":"i-smet-kemal-turkay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nice-yillardan-once-gozlerine-vurgundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Durduğu An', 'zamanin-durdugu-an-nihat-albayrak-716z5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavi ufuk derinliğinde; saklı hüzünler,

Göçmen kuşlar yüreğimin manga dizilişi,

			özgürlüğe susuz,

Yarım kalan bir sevda masalı bu hasret,

Antik çağlardan günümüze kalan! ....

Sarhoş gecelerin sabahına dönmeyeceğim artık,

Sevda şarkıları söylemiyeceğim artık şafağa,

Artık gündoğumu yangınlarına koşmayacağım,

Sulara bırakılan bir demet iri beyaz gül,

		artık çoğaltmıyor umutlarımı,

İç evrenimde gizli kalmış bir sevda bu,

O yaz akşamından kalan! ....

Kadehlerde alev alev hatıralar,

Eski bir şarkıya yenik düştü umutlar,

Uzun bir yaz gününün ortasında,

	Sahildeki bir balıkçı lokantasında,

		Kilitlenmişti iki çift göz,

                                                     iki çift el,

Evrenin tüm ırmakları yüreğimizde buluşmuştu

Ve zaman durmuştu! ....

Nihat ALBAYRAK', 'Mavi ufuk derinliğinde; saklı hüzünler, Göçmen kuşlar yüreğimin manga dizilişi, 			özgürlüğe susuz, Yarım kalan bir sevda masalı bu hasret, ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Albayrak']::text[], 8.5, '{"poet":"Nihat Albayrak","poet_slug":"nihat-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zamanin-durdugu-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ak Ölüm', 'ak-olum-mustafa-ustun-xonyy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Orda 

yaralı kurt olur

gece,

ulur.

Kışlaklarda çığ

ak ölüm,

kar 

kefen olur.

Kızaklar kırık

dorular yılkılı

ezgiler

uzun bir hıçkırık olur.

Ayaz umutları dondurur.

Yazıklıları ininde

Tanrı’da unutur,

kulda unutur.', 'Orda  yaralı kurt olur gece, ulur. Kışlaklarda çığ ak ölüm, kar  kefen olur. Kızaklar kırık dorular yılkılı ezgiler uzun bir hıçkırık olur. ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Üstün']::text[], 8.5, '{"poet":"Mustafa Üstün","poet_slug":"mustafa-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ak-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pastel Yalnızlığın', 'pastel-yalnizligin-canan-ucer-ne9nn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir grup vakti gelirsin aklıma

Latin kadın şarkı söyler avuçlarında

Sesini kondurursun tuvallerine

Hangi yitik kentlerin resmini çizersin

Kadın dudaklarında.............

Elinde pastel boyaların, darbelere yıkanırsın

Annenin dualarını yarınına saklarken.........

O sen değilsin özlemlerinde yanan

Bir deli çocuk koşturur renklerin armonisine

Hangi gökkuşağına baksam, sen olursun el sallayan

Bana bir şarkı söyle çocuk, eski günlerden kalan.........

İçinde isyanlarına sarılırsın

Devrik cümleler kurup, bakışlarını kaçırırsın

Bir gül kendi dikeninde can verir

Kanayan suskunluğuyla.

Kelimeler anlamsız kalır yüzünün renginde....

Bir grup vakti gelirsin aklıma

Terlemiş bedeninle uyanırsın, arzularına

Ve yorulana kadar sevişirsin

Kirli bir çizgi olur dolanan bacakların, çarşaflarımda

Bir kedi sıcaklığı tırmalar tenini

Doymamış hazlarında kaybolursun.........

Ellerim asılı kalır renklerinde

Latin kadın şarkı söyler avuçlarının arasında..

Bir güneş sonrası gelirsin aklıma

Kahrolurum, yoksun...........', 'Bir grup vakti gelirsin aklıma Latin kadın şarkı söyler avuçlarında Sesini kondurursun tuvallerine Hangi yitik kentlerin resmini çizersin Ka...', ARRAY['Türk Edebiyatı','Şiir','Canan Üçer']::text[], 8.5, '{"poet":"Canan Üçer","poet_slug":"canan-ucer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/pastel-yalnizligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-murat-berk-4j7mu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşık olursan; 

Saçların, cildin bir başka yumuşak 

bir başka parlak, 

Göğüslerin daha dik ve daha isterik, 

Kalçan daha dolgun ve yuvarlak, 

Dudakların dayanılmayacak kadar sıcak,

Olacak.

Ellerin sende değil vücudumda kalacak,

Sıcaklığın daha da artacak,

Gözlerin benden başkasına bakmayacak,

Ayakların nereye giderse gitsin

Ama sözlerin benle başlayıp

Bende son bulacak...', 'Aşık olursan;  Saçların, cildin bir başka yumuşak  bir başka parlak,  Göğüslerin daha dik ve daha isterik,  Kalçan daha dolgun ve yuvarlak, ...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-224-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Yok mu.? iSTANBUL', 'sende-yok-mu-istanbul-baki-son-5fupl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanların kaynaştığı,

Sarmaştığı

Bir yer yok mu kucağında 

_____________İstanbul

Sıcacık yuva gibi

Isındığı

Bir yer yok mu bağrında 

_____________İstanbul

Methine koşup geldim.

Görünüşün pek güzel...

Ama,

Benim sevdiğim güzel

Sende yok mu.? 

_____________İstanbul

Cennet gibi bir yer buldum

Yüreğinde 

_____________İstanbul.

Benim dünyam gibi...

Küçücük,sakin,

Sıcacık,ince

Hayallerim kısa sürdü yine de

Benden uzak

İnsanların doldu odama

_____________Umudum...

Yere düşmüş,sırça oldu

_____________Dağıldı...! 

Sevgi nerede

Saygı nerede

Seven yok mu.? 

Aradığım mutluluk

Sende yok mu.? 

_____________İstanbul', 'İnsanların kaynaştığı, Sarmaştığı Bir yer yok mu kucağında  _____________İstanbul Sıcacık yuva gibi Isındığı Bir yer yok mu bağrında  ______...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sende-yok-mu-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerime baktın mı!', 'ellerime-baktin-mi-zafer-zengin-etnika-onyla', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerime baktın mı ! 

Nasıl yamyam duruşlu değil mi! 

Bir dokunsan

Yiyecek gözlerini

Yanaklarını saklayacak tırnaklarına

Darılacak 

Omzuna bir dokunuş olacak 

sesim belki

Ellerime baktın mı hiç

Gece vakti

Karanlıkta

Işık istedin mi yanına

Anlatmadımı şansını sana

Ellerime bakmadıysan

Bırak dokunma

Yemini var

Ağlamayacak bir daha

Anlattılar el ve parmaklardaki manaları..Onları dinledim..

Bilmediğim halde tüm anlatılanları sezdim..İlk gören göz ise..

İlk dokunan parmaklar ve eller..Gerisini gece söyler..Şair dinler...

01.04. 2004', 'Ellerime baktın mı !  Nasıl yamyam duruşlu değil mi!  Bir dokunsan Yiyecek gözlerini Yanaklarını saklayacak tırnaklarına Darılacak  Omzuna b...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ellerime-baktin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşü mavi mavi', 'gulusu-mavi-mavi-zafer-zengin-etnika-pp5xl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vurdular sarışın kızı

Orta yerinden/Yüreğinin

Saçları

İklimler gibi değişmişken

Ya gözleri

Ya mavi mavi gülüşleri...

Vurdular sarışın kızı

Bahar''a girerken

Yarı çıplaktı bedeni

Ölürken...

Ölüm nedeni; 

Ense köküne saplanan bir öpücük

Sakal batmış yarım günlük

El değmemiş tene

Salmış mor güllere

Dağılmış ağzındaki

Gülüşü mavi mavi

Resmine takılmış gözleri gri

Dudakları kehribar

Vurulmasa yaşayacak az ömrü var

İflah etmez

Aşk kurşunu

Yüreğine girdiğinde

örtün üstünü

Sarışın kız

Fanilası yere düşen

Gözleri 

mavi mavi gülen

Ölmüştü! 

Yarım günlük traşlı

Bıyıksız adam öperken...

Gülüşü vardı! 

Mavi...

Mavi...

26 Mart 2004', 'Vurdular sarışın kızı Orta yerinden/Yüreğinin Saçları İklimler gibi değişmişken Ya gözleri Ya mavi mavi gülüşleri... Vurdular sarışın kızı B...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gulusu-mavi-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Öyküler', 'kirik-oykuler-melih-coskun-p9hjr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nereye çevirsem başımı 

Hep kırık öyküler

Mevsimsiz açmış çiçekler gibi 

Herkesin boynu eğik 

Herkes kınında bir bıçak gibi 

Parmak tetiğe dayalı 

Çıktı çıkacak neredeyse ok yaydan

Namlu alnına dayalı 

Patlamaya hazır bir bomba gibi yaşamışız hep 

Ya zindan 

Ya kara sevda 

Tüm imkansızlıklar bizim 

Yarınlar onlarındı   

Bugün onların 

Bize kalan dünün yaşanmamışlığı

İkinci sınıf bir filmin 

Adi figürasyonu hikayemiz

Kırık bir öykü I: 

Zayıftı 

Yaşlıydı 

Ve titriyordu dizleri 

Bacakları daha fazla taşıyamadı bu yükü ve 

Yuvarlandı çamurun içine 

Soğuktu 

Hava sulu sepken 

Uzadıkça uzuyordu kuyruk

Tutup kaldırmak istedim 

Keder ve isyan o kadar ağırlaştırmıştı ki onu 

Kaldıramadım bu yükü tek başıma 

Düşmüştü

Ağlıyordu...

İşte ben o gün küfür etmeyi öğrendim! ... 

III.

Kırık bir öykü II: 

Yürüyordum 

Kederin fazla uğramadığını düşündüğüm 

Burjuvazinin yalancı ışıklarıyla süslenmiş o caddede

Bir kız çocuğuydu 

Elleri horoz şekerleriyle doluydu 

“Sizde bir tane almaz mısınız? 

Belki de bir hayat kurtulacak bu horoz şekerleriyle” dedi

Yapabilsem çıkarıp yüreğimi de verecektim o anda

Parlıyordu gözleri 

Sesinden umut yankılanıyordu caddeye 

Dedim ki kendi kendime; 

Hala bir şansımız var 

Hala gözleri ışıldayan birileri var bu coğrafyada

O gün anladım ki; 

Dostluk diye, 

Vefa diye bir şey hala var 

Bunca tükenmişliğe rağmen

Ve de anladım ki kederin giremeyeceği hiçbir cadde

Hiçbir sokak, 

Hiçbir ev yok, 

Ama umut diye bir şey var hala...

Kırılmış, hırpalanmış da olsa hikayemiz 

Mevsimsiz açmış çiçekler gibi 

Bükük kalmış olsa da boynumuz 

Kınından çıkmaya hazır bir bıçak gibi dursak ta

Namlu dayalı olsa da alnımıza

Yarına daha gün var 

Kırıldığı gibi onarılır da bu öykü

Yeter ki kırılan insanlığın olmasın...

20 Şubat 2003

20: 29', 'Nereye çevirsem başımı  Hep kırık öyküler Mevsimsiz açmış çiçekler gibi  Herkesin boynu eğik  Herkes kınında bir bıçak gibi  Parmak tetiğe d...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/kirik-oykuler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla Beni', 'bagisla-beni-nedim-saatcioglu-fr91u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni gözlerimden sildim…

Artık iki aynı harfin arasındaki yasak aşk değilsin 

Artık en güzel kırmızı değilsin benim için…

Hani bir desen gibi yüreğinde yerim vardı

Hani bir öyküm vardı dudaklarında…

Meğer hep bir varsayım hep bir ihtimalmişim

Meğer bir med-cezirmiş senin için gözlerim

Bağışla bağışla beni sana kandığım için…

Seni gözlerimden sildim…

Artık beş harfli karanfil yaprakları yok odamda 

Artık tenindeki kan bulaşmıyor yatağıma

Hani ufkundaki son gemindim son demindim

Hani yüreğindeki en büyük depremindim

Meğer ayrılık fermanıymış o mektubun yazdıkları

Meğer koskoca bir yalanmış parafinin gözyaşları

Bağışla bağışla beni sana kandığım için…', 'Seni gözlerimden sildim… Artık iki aynı harfin arasındaki yasak aşk değilsin  Artık en güzel kırmızı değilsin benim için… Hani bir desen gib...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bagisla-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ben Miyim?', 'bir-ben-miyim-volkan-tekin-i4c7e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ben miyim

Bu yoldan dönen? 

Bir ben miyim

Dağlarda gezen? 

Gökyüzünü, 

Yıldızları seyreden? 

Söyle bir ben miyim

Sevdalı? 

Alevler sarmış yüreğimi

Sönmüyor,

Durmuyor görmeden seni

Dünyaya meydan okusam 

Haykırsam dünyaya ismini

Anlatsam sana sevgimi

Ama suçluyum yine değil mi? 

Söyle bir ben miyim

Bu dünyada deli

Anla işte

Sevmişim bir kere seni...', 'Bir ben miyim Bu yoldan dönen?  Bir ben miyim Dağlarda gezen?  Gökyüzünü,  Yıldızları seyreden?  Söyle bir ben miyim Sevdalı?  Alevler sarmı...', ARRAY['Türk Edebiyatı','Şiir','Volkan Tekin']::text[], 8.5, '{"poet":"Volkan Tekin","poet_slug":"volkan-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-ben-miyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-sule-aydemir-eddxl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben

öyle uzun gidiyordum

kalakaldığım 

girdabın peşinden

zaman dileniyordum

kırdığım saatin 

sesinden

sen 

çölünün çukurunu

denizle doldururken', 'ben öyle uzun gidiyordum kalakaldığım  girdabın peşinden zaman dileniyordum kırdığım saatin  sesinden sen  çölünün çukurunu denizle doldurur...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ses-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki ''sen''...', 'bendeki-sen-sema-gorur-hlr3h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim hayattan bekledigim senmisin,

Yoksa senden bekledigim hayatin kendisimi? ! 

Düsünüyorum, geceyi gündüze bagliyorum,...

Cevap bulamiyorum! 

Benim ümitlerim yasaklimi,

Yoksa yasaklarmidir ümit vaad eden? ! 

Hayallerimi gözden geçiriyorum,...

Egrisini bulamiyorum! 

Bendeki ''sen'' gerçekmi,

Yoksa sen bendemi farklisin? ! 

Agliyorum, soruyorum,...

Sendeki ''sen''e ulasamiyorum! 

Sevgisini söylemekmi zor,

Yoksa onu hissetirmekmi? ! 

Saskinim, bilemiyorum.', 'Benim hayattan bekledigim senmisin, Yoksa senden bekledigim hayatin kendisimi? !  Düsünüyorum, geceyi gündüze bagliyorum,... Cevap bulamiyor...', ARRAY['Türk Edebiyatı','Şiir','Sema Görür']::text[], 8.5, '{"poet":"Sema Görür","poet_slug":"sema-gorur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bendeki-sen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SONSuZ', 'sonsuz-baki-son-hbiva', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bunca yıl,

Kahrını çektiğimiz...

Sonrası ne olacak

______________ Yaşananların...? 

Ne sevgililer gördük,

_______________Bağlandığımız...! 

Çılgınca sevdiğimiz,

_______________Vefasız...! 

Neler göreceğiz daha

Aldanmak pahasına...

Esmer,kumral,sarışın

Hepsi bir rüzgar,

_______________Ağustos da

Hapsi bir yalan,

_______________Çocukcasına

Boşuna aldanmalar artık.

Bunca yıl,

Kahrını çektiğimiz

Sonrası ne olacak

______________ Yaşananların...?', 'Bunca yıl, Kahrını çektiğimiz... Sonrası ne olacak ______________ Yaşananların...?  Ne sevgililer gördük, _______________Bağlandığımız...!  ...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sonsuz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum İsyankâr Ve Siyah', 'masum-i-syank-r-ve-siyah-derin-oger-qdioo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay kapanır

Sisine büyülenmişcesine

Gök gürültüsünü vurur yıldızların sırtına

Birleşir yağmurla deniz

Kurşun gibi patlar çılgın ve siyah

Sus bişey söyleme

Sana uyanan gözlerde

Birazdan başlar sağnak

Peçe peçe kirpikte aşkın sırları

Masum isyankâr ve siyah

Hep sessiz hep gizli

İlk kez yeryüzüne düşermiş gibi

Solgun yanaklardan  dudaklara

Su verir misali erguvanlara

Ne nehir olur ne ırmak..........', 'Ay kapanır Sisine büyülenmişcesine Gök gürültüsünü vurur yıldızların sırtına Birleşir yağmurla deniz Kurşun gibi patlar çılgın ve siyah Sus ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/masum-isyankar-ve-siyah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arta kalan', 'arta-kalan-burhan-kucuk-cntv7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arta kalan

Yollar uzun,sonu görünmeden biten

Irmaklar boz bulanık aksa da ardı duru

Sen göründüğün gibi misin güleç yüzlü

Ne karanlıklardan arta kalan

Görünen köy kılavuz da  ister,rehber de

Göründüğü gibi değil artık her baktığın

Var git bir bakış at  şu dağdan meraya

Gördüğün ot mudur toprağında biten

Dön bak aynaya sen bu musun

Yoksa aynada ki mi sensin

Kır aynaları, at her bir yana parçalarını

Dön bak çevrene,arta kalan sen misin

Burhan KÜÇÜK

Kdz.Ereğli', 'Arta kalan Yollar uzun,sonu görünmeden biten Irmaklar boz bulanık aksa da ardı duru Sen göründüğün gibi misin güleç yüzlü Ne karanlıklardan ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/arta-kalan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötelere Kapı Var', 'otelere-kapi-var-halil-i-brahim-ozdemir-s45yx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay yüzüne doğmadı, gün aydınlığı yüzün,

Sağırlar duydu seni, söylenmedi son sözün,

Beş duyusu kör olan sağır dilsiz hayattan

Ötelere kapı var orada olsun gözün…', 'Ay yüzüne doğmadı, gün aydınlığı yüzün, Sağırlar duydu seni, söylenmedi son sözün, Beş duyusu kör olan sağır dilsiz hayattan Ötelere kapı va...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/otelere-kapi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beraber', 'beraber-halil-kesken-w7vvp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üstümüzde kara bulutlar durur

İsterim ki güneş bize de doğsun

Eğer ki dinmeyen bu deli yağmur

Seni boğacaksa beni de boğsun

Belli ki ayrılık zor geldi sana

Sararıp benzedin kuru yaprağa

Bu acılar bir gün kara toprağa

Seni koyacaksa beni de koysun

Sanırsın ki sorun şanssızlığında

Hep suçu aradın bahtsızlığında

Kaderin bir anlık kızgınlığında

Seni yıkacaksa beni de yıksın

Böyle konuşma diyip hep kestin sözü

Beraber ölmenin neresi kötü

Felek kör bir avcı gözünde örtü

Seni vuracaksa beni de vursun.', 'Üstümüzde kara bulutlar durur İsterim ki güneş bize de doğsun Eğer ki dinmeyen bu deli yağmur Seni boğacaksa beni de boğsun Belli ki ayrılık...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beraber-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık İstasyonları*', 'ayrilik-i-stasyonlari-bayram-tunca-81q6w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kiminin istasyonu gar/kimininki liman 

Ayrılıkların her biri birbirinden yaman 

Aktörü anne/baba, eş/dost yani insan 

En acıklı olanı istasyonu musalla olan 

02.04.2003-08.04-İst.', 'Kiminin istasyonu gar/kimininki liman  Ayrılıkların her biri birbirinden yaman  Aktörü anne/baba, eş/dost yani insan  En acıklı olanı istasy...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayrilik-istasyonlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımı Sensiz Yaşamak', 'askimi-sensiz-yasamak-cafer-tayyar-ozkan-76aoc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne kadar zor bilir misin? 

Aşkımı sensiz yaşamak,

Hele geceleri hayalinle olup nefes almak,

Gözünden ışıltıların gitmeyeceğini bilsem,

En güzeli, seni gece kollarımda sarmalamak...

Ne kadar zor bilir misin? 

Sevdamı cana adamak,

Hele anıları bir kalemde kalpten silip atmak,

Ettiğin yeminlere sadık kalacağını bilsem,

En güzeli, seni yemyeşil rüyalarda yaşamak...

07.10.2003 İstanbul', 'Ne kadar zor bilir misin?  Aşkımı sensiz yaşamak, Hele geceleri hayalinle olup nefes almak, Gözünden ışıltıların gitmeyeceğini bilsem, En gü...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askimi-sensiz-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Çok Sevdiğim', 'en-cok-sevdigim-hafize-zuluflu-h2qm9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O kadar mı önemliydi o mekandaki o duruş

Sen, yine sensin kendinle, deneyimlerinde,

İçinle, herşeyinle! ....

Bu, kayıp gibi görünse de değil ki bir  yok oluş

Yoksa bu yediğin ilk darbe mi

İlk mi bu arkandan vuruluş? 

Oysa vurula vurula ben öylesine kanıksadım

Akmaz hiçbir ihanette ne gözyaşım, ne kanım

Sen, en çok sevdiğim hadi kendine gel

Görmezden gelsen de en kötü günlerinde

Ben yine yanındayım...', 'O kadar mı önemliydi o mekandaki o duruş Sen, yine sensin kendinle, deneyimlerinde, İçinle, herşeyinle! .... Bu, kayıp gibi görünse de değil...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/en-cok-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Mavi', 'sari-mavi-hafize-zuluflu-uol5x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu unutulmuşluk, bu yalnızlık

Bu terkedilmişlik hissi

Nisanmış, baharmış farkında değilim

Soldu yeşillerim

Açmıyor içimde çiçeklerim

Bilemezsin ben de senin kadar üzgünüm

Evlere kapandım, duvarlar arkasına saklandım

Çıkıp çıkıp indim aklımdaki köprülerin korkuluklarına

Uyudum uyandım seni gördüm her baktığımda

Bilemezsin kaç kez yuvarlandım içimin uçurumlarına

Kaç kez yaralandım, kaç kez kurtardılar bilemezsin

Acıyor içim sarı mavi…', 'Bu unutulmuşluk, bu yalnızlık Bu terkedilmişlik hissi Nisanmış, baharmış farkında değilim Soldu yeşillerim Açmıyor içimde çiçeklerim Bilemez...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sari-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağlayan Mevsiminde Aşk', 'caglayan-mevsiminde-ask-hakki-hakan-kaya-2ee7m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Serilir bir güzele, bütün arş-ı sema,

Secde eder ne kadar, gurur kibir varsa,

Döner bin kez alemi, yüreği elinde,

Söylenir bir türkü, yarin adı dilinde,

Kırılır kalkanı, açıktır aşka yürek, 

Birleşir gönüller, tutulur aynı dilek,

Dingin akar pınar, çağlayan yerinde,

Toplanır sevda suları, aşkın mevsiminde...', 'Serilir bir güzele, bütün arş-ı sema, Secde eder ne kadar, gurur kibir varsa, Döner bin kez alemi, yüreği elinde, Söylenir bir türkü, yarin ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/caglayan-mevsiminde-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemdi', 'annemdi-hafize-zuluflu-zmlw9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Paramparça şimdi kederlerim

Ruhum darmadağınık 

Bakma öyle göründüğüme

O yürüyen ben değilim yolda

Ben değilim bakan

Tanıdık tanımadık bütün yüzlere

Ne yaptığımı bilmiyorum

Eksildi yarı yanım

Bir hayatın gidişiyle

Sevdana bile tutunamadım

Kırklı yaşlarındaydı tanıdığımda

O bir çınardı

Ölümsüz

Öylece dururdu hayatın karşısında

Beş Hazirandı sabaha karşı

Ölüm geldi evimize

Annemdi…', 'Paramparça şimdi kederlerim Ruhum darmadağınık  Bakma öyle göründüğüme O yürüyen ben değilim yolda Ben değilim bakan Tanıdık tanımadık bütün...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/annemdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Vururlar Kuşları?', 'niye-vururlar-kuslari-necmi-unsal-i43x3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Niye  vururlar kuşları? 

Kolayca  aşarlar  yokuşları. 

Dağları,  taşları... 

Süzülürler  korkusuzca  ovalara. 

Denizlere,  ormanlara...

Özgürce  uçarak

Gökyüzünde, 

Kanat kanat  açarak 

Ruhun  özünde, 

Ederler  seyahat! 

Bu,  insanın özgürlüğe  duyduğu  kin mi? 

Yoksa, uçamadıkları  için mi? 

İnsanlar  neden düşman bu  kuşlara? 

Niçin  vahşi  hınçlar tüm  uçuşlara? 

Kuşlar,  özgürlüğün simgesi! 

Hafifliğin  hür  imgesi! 

Kanatlar dünyayı  kucaklarcasına

Açıldıkça  açılır.

Çırpıldıkça  hürriyete  kaçılır.

Niye  vururlar  kuşları? 

Yere  sokarlar bakışları! 

Kanatları  kırmak  için! 

Hayatları  yıkmak  için! 

Amaç  bir  çiğnem  et mi? 

Yoksa  vurmanın  verdiği  zevk mi? 

Kuşları  vuranları versinler  sehpalara! 

Vursunlar  urganlara! 

Sallansınlar  zevkine.

Salıncak  niyetine. 

İbret  olsun  duranlara! 

Niçin  vururlar kuşları? 

Onlar  da  özgür  olduğu  için! 

Niye  vururlar  kuşları? 

Onlarda söz,  ‘bir’  olduğu  için! 

7 Mart 2004 Pazar,  Danimarka-Køge  01.21', 'Niye  vururlar kuşları?  Kolayca  aşarlar  yokuşları.  Dağları,  taşları...  Süzülürler  korkusuzca  ovalara.  Denizlere,  ormanlara... Özgü...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/niye-vururlar-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Depresif estetiği ile şizofren imgelerde dokunduğum yer…', 'depresif-estetigi-ile-sizofren-imgelerde-dokundugum-yer-asya-gulgun-ozkan-xk1xk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '…………bütün şiirlerim sahipsiz aslında 

sen bir yalıçapkını 

bense albatros 

gülümsetiyorsun beni/ ama…………… 

……..” hüznün Arnavut kaldırımı sokaklarının apış aralarını arşınlayarak,adımlarını sessiz ve takatsizce sıklaştırarak gözden yitiyor yaşam”……… 

Ömür, yeniden çatırdayarak diz çöktüğünde 

“merhaba” dedi dilenci hüzün yeniden/…çekinmeden yüzsüzce 

gölgeli yanılsamalar dolanırken /… kımıl kımıl dalgalarla 

mum sönüşlü küllenmiş gözlerde /… sütlü kahve içimlik 

hayal gerçek arası meddücezirlerde /… sarsak aksak, biraz histerik 

izbe karanlığa kafa tutan buzul mavi /… yedi iklim açışlı 

inadına yumuşacık,pamuktan bir bulut misali /… varla yok arası,hissettiren 

saf,sevecen ve tüm içtenliği ile /… biraz da suskun 

dokunduğunda sevginin elleri / …derinden ama eriten 

kuştüyü yastık sanki, kabardı yalnızlık.. / …yüzleri eksik 

ay ışığı saç uçlarından damlarken /…damıtırken kendini 

gözyaşı billûrlarıydı, cehennem taşına dönüşen 

buz tutan sessizlikte / … ayan beyan 

gece abasını çıkardığında güne / … susabilen uğultusunda 

ağaran tan göz kırparak yıldızlara / … yan yana (yana yana)

hataların affı için güzelleşecek zaman / … ç(ağlarcasına)

işte tam bu lâhzada; 

kapat göz bebeklerini 

ve 

iyi geceler ömrüm.. / …efkâr kır 

bir gün daha solarken/sönerken/ömrümde 

bir yama daha dikiş tu/tmuştu/tuyordu yüreğime 

peki, 

dokunduğu/n/m yer ne renk!', '…………bütün şiirlerim sahipsiz aslında  sen bir yalıçapkını  bense albatros  gülümsetiyorsun beni/ ama……………  ……..” hüznün Arnavut kaldırımı so...', ARRAY['Türk Edebiyatı','Şiir','Asya Gülgün Özkan']::text[], 8.5, '{"poet":"Asya Gülgün Özkan","poet_slug":"asya-gulgun-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/depresif-estetigi-ile-sizofren-imgelerde-dokundugum-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-mehmet-i-mal-xy1cm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fırtınalı bir gecenin öyküsüydü

Zehirli sarmaşıklar sarmıştı dört bir yanımızı

Rüzgar sinsi yüzüyle okşuyordu tenimizi

Bizi ise aldırmadan sevişiyorduk kaderimizle

Her yeni cümlende ayrılık beliriyordu

Darma dağınıktık,toparlanamıyorduk

Sonra 

Bırakıp gittin sen.

Pasaklı bir ilişki daha gömülüyordu usulca

Ve en sonunda 

Sen yoksun

Bense hala gömemiyorum

Bendeki seni..._____________', 'Fırtınalı bir gecenin öyküsüydü Zehirli sarmaşıklar sarmıştı dört bir yanımızı Rüzgar sinsi yüzüyle okşuyordu tenimizi Bizi ise aldırmadan s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoksun-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kapının iki tarafı', 'bir-kapinin-iki-tarafi-mehmet-i-mal-wiyx8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Penceremden dışarı baktıkça,

Senli rüyalara dalıyorum geceleri.

Bir şato görüyorum her defasında.

O kocaman 

O ihtişamlı

O Benzersiz şatonun kapısındayım

ve

Bekliyorum

Evet,

belki bir gün çıkıp gelirsin diye bekliyorum.

Umutlarımı,mucizelere yüklüyorum

Ama yinede bekliyorum.

İnatçıyım.

Ama farkındayım

İçinde olduğun şatonun anahtarının kayıp oluşunun

Ve

Yine o anahtarın çalınmışlığının farkındayım....

Çıkamayacağını biliyorum,

Tek olasılık kaçman.

Kaçmanın zorluğunun bilincindeyim,

Tek olasılık arkana bakmaman.

Bakacağından eminim,

Tek olasılık durmaman...

Bırakmanın saçma olduğu eller var şimdi

Ama

Saçmalığın çare olduğu günlerde gelecek elbet

Her saçmalayışında bana geleceksin adım adım

Nasıl ki her saçmaladığında benden uzaklaştıysan 

Seni Saçmalıkla alan,yine saçmalıkla bırakacak belkide.

Alın yazın olmayacak belki yapacakların ama, 

Bir garip mutlu olacak sayende.

Tanıdık,bildik güvenilir bir garip.

Hiç usanmadan,

O şatonun kapısında bekleyen bir garip,

Bir zamanlar sevdiğin, onun için ağladığın bir garip

Gariplikten kurtulacak belkide sayende

Nasıl ki sayende garip olduysa...

Her defasında

Bir avuç açılacak gözlerine

Göz yaşların için

Ve yine kıskanılacak o yaşlar

Yerden,hatta mendillerden kıskanılacak

Anlatılamayacak yine duygular

Şimdi olduğu gibi

Anlatsamda artık duyamayacaksın

O büyük duvarların arkasından beni

Bekliyor olucam her zaman o kapının ardında.

BİLİYORUM Kİ

Sana bir, kapının iki tarafı kadar

YAKIN VE UZAĞIM...', 'Penceremden dışarı baktıkça, Senli rüyalara dalıyorum geceleri. Bir şato görüyorum her defasında. O kocaman  O ihtişamlı O Benzersiz şatonun...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/bir-kapinin-iki-tarafi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam', 'anlam-mehmet-i-mal-u0jie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlamsız gururlar var her bir yanımda,

Adeta bana sokulmaya çalışıyorlar.

Anlamsız bakışlar var etrafımda,

Hiçbir şey ifade etmiyorlar,

Bakıyorlar ama görmüyorlar,

Ne mutlular ne üzgün.

Anlamsız duygular çıkıyor çıkıyor yoluma,

Amaçsız ve çabasız,

Aciz ve niteliksiz.

Anlamsız fikirlerle doluyor beynim,

Düşünemiyorum çoğu zaman.

Anlamsız rüyalar kaplıyor gecelerimi,

Öyle ki yıldızları bile göremez oldum

Anlamsız güreşler tutuyorum her doğan günde yeniden

Ve 

Hayatımın en anlamlısı

Sende gidiyorsun ya benden

Gücüm kalmıyor artık

Git gide bende anlamsızlaşıyorum...', 'Anlamsız gururlar var her bir yanımda, Adeta bana sokulmaya çalışıyorlar. Anlamsız bakışlar var etrafımda, Hiçbir şey ifade etmiyorlar, Bakı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anlam-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşarım Mutluluğunu Seni Sevmenin...', 'yasarim-mutlulugunu-seni-sevmenin-bekir-mutlu-gokcesu-xpf4v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daralır hani yolları

Gecikir kimi şafakları

İçimin

Kulaklarım çınlar hani

Beni çağırır ya nefesin

Fırlarım dışarılara

Gecenin bir vakti

Veya bir seher

Alırım ya hani soluğu

Doğruca şiir sokağında

Her sefer

Dağılır kasvet tortuları

Durulur huzura suları

İçimin

Kokun sinmiş 

Bilirim az önce geçmişsin

Buğusu kalmış dizelerde

Gözlerinin

Yürürken peşi sıra

Ayak izlerinin

Mısra, mısra 

Yaşarım mutluluğunu

Seni sevmenin...', 'Daralır hani yolları Gecikir kimi şafakları İçimin Kulaklarım çınlar hani Beni çağırır ya nefesin Fırlarım dışarılara Gecenin bir vakti Veya...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasarim-mutlulugunu-seni-sevmenin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayetim Var', 'sikayetim-var-halil-kesken-xviaj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allahım bu sana son yalvarışım

Dilek değil bu kez şikayetim var

Zalim bir kuluna bilmeden bağlanmışım

İşte bu kulundan şikayetim var

Ben ona sadakat, o hasret verdi

Ben nişan yüzüğü, o gurbet verdi

Ben ona mutluluk, o hep dert verdi

İşte bu kulundan şikayetim var

Bir an geri dönsem, sıkar kurşunu

Seven sevdiğine yaparmı bunu

Allahım yanına alıver şunu

İşte bu kulundan şikayetim var

Ateşler içinde yattım gelmedi

Ağıtlar yakarken yaşım silmedi

Ne yaptımsa ona kıymet bilmedi

İşte bu kulundan şikayetim var', 'Allahım bu sana son yalvarışım Dilek değil bu kez şikayetim var Zalim bir kuluna bilmeden bağlanmışım İşte bu kulundan şikayetim var Ben ona...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sikayetim-var-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştü Yangınlara Gönül', 'dustu-yanginlara-gonul-sadik-softa-vyalt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül çerağını yaktı,

Sevda damla damla aktı,

Merak gözlerimden baktı,

Düştü yangınlara gönül.

İçimde umman uyandı,

Sevda kapıya dayandı,

Belliydi, ayan-beyandı,

Düştü yangınlara gönül.

Hayallerle besleniyor,

Aşk kalbime sesleniyor,

Sevda bende üsleniyor,

Düştü yangınlara gönül.

Uzanıyor ummanlara,

Baş gömülür dumanlara,

Fırsat kalmaz amanlara,

Düştü yangınlara gönül.', 'Gönül çerağını yaktı, Sevda damla damla aktı, Merak gözlerimden baktı, Düştü yangınlara gönül. İçimde umman uyandı, Sevda kapıya dayandı, Be...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dustu-yanginlara-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıvılcım', 'kivilcim-sirma-mersin-vyqzv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küllerinde doğan bir kıvılcım...

Heyecanın rüzgarında,

Alevlenirken...

Kıvılcım büyür ; 

Kor yangınlara döner,

Bu yürek! 

Ateşlere düşmüşken; 

Cayır cayır yanmak,

Acı vermez...

Bu yüreğe! 

01.04.04', 'Küllerinde doğan bir kıvılcım... Heyecanın rüzgarında, Alevlenirken... Kıvılcım büyür ;  Kor yangınlara döner, Bu yürek!  Ateşlere düşmüşken...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kivilcim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Olabilir?', 'kim-olabilir-halil-kesken-pcot1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şaşırma sevgilim mutluluğuma

Belki de anlatmak zor olabilir

Her an kollarımda seni buldukça

Benden daha mutlu kim olabilir? 

Bütün kötü günler mazi oldukça

Aradığım aşkı sende buldukça

Kalbinde herzaman yerim oldukça

Benden daha mutlu kim olabilir? 

Eğer ayrılsaydık dolmazdı yerin

Arkası gelmezdi kötü günlerin

Artık korkmuyorum aşkımız için

Benden daha mutlu kim olabilir? 

24.02.1997', 'Şaşırma sevgilim mutluluğuma Belki de anlatmak zor olabilir Her an kollarımda seni buldukça Benden daha mutlu kim olabilir?  Bütün kötü günl...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kim-olabilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin Çoşkusu', 'sevmenin-coskusu-sirma-mersin-xw2z5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onca yılın üstüne, biriktirdiğim hayallerimi; 

Özlem dolu yüreğine, sarmadan önce...

Gün ışığı görmemiş umudumun içerisinde; 

Nefes alıp veren, 

Yalnızlığımın sesi dağılırdı,odama! 

Sensizliğe ait söylenmemiş şarkılarla; 

Geceye fısıldanmış,devrik cümlelerin  arasına sıkmışken! 

Sakladığım duygularımı birbir  terketmeden önce; 

Gözleine bakarak,

Sevmenin çoşkusuna kapıldım...

02.04.04', 'Onca yılın üstüne, biriktirdiğim hayallerimi;  Özlem dolu yüreğine, sarmadan önce... Gün ışığı görmemiş umudumun içerisinde;  Nefes alıp ver...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevmenin-coskusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Aşar Gider', 'beni-asar-gider-sadik-softa-ctrpe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tüm yolları tutmuş gözlerin bakar,

Ne yana uzansam, süzer ha süzer.

Alıp yüreğimde saklayım desem,

Beni aşar gider, üzer ha üzer.

Ağırdır ışığı, ağırdır yükü,

Cefasına dursam, desem hep peki,

Gücüm ne, hükmüne yeter mi sanki? ! 

Beni aşar gider, ezer ha ezer.

Karartır günümü, sürer geceye; 

Perde perde eder, dürer geceye; 

Yüreğimi alır, serer geceye; 

Beni aşar gider, gezer ha gezer.

Sağanak sağanak yağar üstüme; 

Kemirir beynimi, ağar üstüme; 

Demirden bir dağdır, sığar üstüme; 

Beni aşar gider, çözer ha çözer.

16.03.2004', 'Tüm yolları tutmuş gözlerin bakar, Ne yana uzansam, süzer ha süzer. Alıp yüreğimde saklayım desem, Beni aşar gider, üzer ha üzer. Ağırdır ış...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beni-asar-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağdım Geceye', 'yagdim-geceye-yasemin-ayse-ozdemir-uvhcr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceye yağdım; ıslaktım

Silerken göz yaşlarımı kanadım

Berrak duygular yoktu artık

Bulanıktı gökyüzü 

Bulanıktı

Şiir kokan maviliğin içinde inadına parlayanlar 

Alsa-varsam bende

Papatya kokan saçlarına 

Sanki susuzluğum kanmıştı cana

Ne var ki aramızda ki uzaklık 

Yıldızlarda da öte yana 

Geceye yağdım; ıslaktım.

Toprak koktu ellerim 

Yeşermeye hazır delikanlı yüreğimi

Saçları kırmızı bir periye verdim

Gece rengini bulmuştu ben hala ıslaktım

Verdiklerimin yerini dolduramadım.

Ürperdim ve deri bir nefes aldım.

Yankısını dinledim sonra 

Acılarım yağdı geceye 

Gece ıslaktı 

Toprak tutan eller vardı.

Ve yüreğim sancılara takıldı

Islak bir İstanbul gecesinde 

Peri sonsuz bir uykuya daldı

Gökyüzüne asılmış bakışlarım 

Bulandı

Hiç durulmayan yaşamın hikayesinde 

Bunaldı

Gece ıslaktı; ben ıslandım; peri ıslanamadı.', 'Geceye yağdım; ıslaktım Silerken göz yaşlarımı kanadım Berrak duygular yoktu artık Bulanıktı gökyüzü  Bulanıktı Şiir kokan maviliğin içinde ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Ayşe Özdemir']::text[], 8.5, '{"poet":"Yasemin Ayşe Özdemir","poet_slug":"yasemin-ayse-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yagdim-geceye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Treni...', 'ask-treni-hurrem-yalcin-aouli', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ruh bedeni yırtıyorsa çıkmak istercesine,

inmişse gözündeki yaş dudağına,

titretmişse çeneni çırpınışı yüreğinin,

ve dahi

parçalamışsa gırtlağını çaresiz hıçkırığın,

kanatmışsa avucun içini tırnakların,

binmişsin sen aşk trenine,

Ulaş''mışsın sevdiceğine...



01.04.2004

Ablam''a.................................................................', 'ruh bedeni yırtıyorsa çıkmak istercesine, inmişse gözündeki yaş dudağına, titretmişse çeneni çırpınışı yüreğinin, ve dahi parçalamışsa gırtl...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-treni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldatan Aşk Olsun Beni', 'aldatan-ask-olsun-beni-oguzkan-bolukbasi-dp1g3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşanmışlık

Koca bir sanmışlık işte

Aşkı bulanlara sevgilerimi iletin

Ve teşekkürlerimi

Tek anlamı bu koca yanılsamanın

El değmemiş açılımlarını renkli kılan

Yalan

Yalan

Her şey yalan

Bari 

Aldatan aşk olsun beni', 'Yaşanmışlık Koca bir sanmışlık işte Aşkı bulanlara sevgilerimi iletin Ve teşekkürlerimi Tek anlamı bu koca yanılsamanın El değmemiş açılımla...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aldatan-ask-olsun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küfür', 'kufur-nal-n-yildiz-w8464', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ha canına su kattığımın delisi

Uykuların borcunu öde

Erken sabahlara.

İntihar rüyalardan sen sorumlusun

Öfke nöbetlerinden üç saat ötede

Delilerin

sözlükleri parçaladığı yere

Sakin bir göle atılan taşın ritminde

Gömül! 

İnebildiğin en derin yere

Diril! 

Unutulmuş bir lale içinde

İki gün aç, bin gül öl

Ha canına su kattığımın delisi

Git

Başka yerde delir', 'Ha canına su kattığımın delisi Uykuların borcunu öde Erken sabahlara. İntihar rüyalardan sen sorumlusun Öfke nöbetlerinden üç saat ötede Del...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kufur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavidir Gözyaşlarım', 'mavidir-gozyaslarim-galip-sinecikli-124l1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben 

her düştüğümde yere 

kalkarım ayağa

tozlu hayat yollarına 

kaldığım yerden yine başlarım 

vurulurum defalarca

kanım akar 

canım yanar 

her darbe güçlendirir beni

ben vuruldukça yaşarım

gecelerin karanlığı ürkütmez artık

ağlarım ben geceler içinde 

gözyaşlarım dirilişimdir benim

gecenin koynuna usulca düşer

mavidir gözyaşlarım', 'ben  her düştüğümde yere  kalkarım ayağa tozlu hayat yollarına  kaldığım yerden yine başlarım  vurulurum defalarca kanım akar  canım yanar  ...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mavidir-gozyaslarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısır Hamile', 'kisir-hamile-nal-n-yildiz-kwvu0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk bebeklerine 

Gebeyim

Havva''dan beri

Rahmimi taşladılar,

Erdemin kısır büyücüleri

Doğmamış ümitlerin

Kundaklanmış hayaletlerini

Fazilet havuzunda boğdular.

Yarin dudağına aş ermedeyim

Onu sosyal içerikli bir filme

Figüran yaptılar memur rolünde.

Aşk bebeklerine gebeyim

Daha doğmadan çocuklarıma 

Edepli isimler taktılar

Tevrat''tan alınmış

İblisin işbirlikçileri

Yumurtalıklarımı parçaladılar

Aşk bebeklerine gebeyim

Sonsuz hamilelikle lânetlendim', 'Aşk bebeklerine  Gebeyim Havva''dan beri Rahmimi taşladılar, Erdemin kısır büyücüleri Doğmamış ümitlerin Kundaklanmış hayaletlerini Fazilet h...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kisir-hamile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Halleri', 'ask-halleri-nal-n-yildiz-uta5q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk defa söyler gibi yine darmadağın

Yine o eski şarkıyı söylüyor yüreğin

Bildik,

Çok okunmuş duaların renginde

Ürkek bir kelebek oluyor sesin...

Boş sokaklara yağmurlar yağıyor

Susuyorsun

Biliyorum için acıyor

Hüznün en kızıl rengi sen misin? 

Gözlerin bütün yalanların şahidi', 'İlk defa söyler gibi yine darmadağın Yine o eski şarkıyı söylüyor yüreğin Bildik, Çok okunmuş duaların renginde Ürkek bir kelebek oluyor ses...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-halleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpek Kızın Söylediğidir', 'i-pek-kizin-soyledigidir-i-pek-gumus-l4had', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'omzum der içini kemiren asalak mavi 

yakınlaşır gittikçe kendi gölgesinde bir ölüm 

bu bir serzeniştir kimseler duymaz 

yutulur cinsten değil elimdeki her elma 

sana şiirler yazamayışım bundan 

övündükçe sıyrılırsın anlamsızlıktan 

klavyem baygın cesetlerle dolu 

papuçlarımda hala kaldırım tozu varken 

sen söylemeyi beceremedin 

sana şarkılar söylemeyişim bundan 

patlayacak biliyorum cebimdeki uykular 

gözünde devrilecek kavgalı pejmurdelik 

yasaklarsam eğer kalemimi okşatmayı 

incinir biliyorum saçlarında bir cenin 

sana yarim diyemeyişim bundan', 'omzum der içini kemiren asalak mavi  yakınlaşır gittikçe kendi gölgesinde bir ölüm  bu bir serzeniştir kimseler duymaz  yutulur cinsten deği...', ARRAY['Türk Edebiyatı','Şiir','İpek Gümüş']::text[], 8.5, '{"poet":"İpek Gümüş","poet_slug":"i-pek-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ipek-kizin-soyledigidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandırıldım', 'kandirildim-nal-n-yildiz-jeonn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fesleğen sabahlarda

Yaralı mazeretlerim olurdu hep

Kanayan bacaklarıma

Boyna düşer, boyna ağlardım

ve annemin sıcağında

Canım yandıkça büyüyeceğime inandırıldım', 'Fesleğen sabahlarda Yaralı mazeretlerim olurdu hep Kanayan bacaklarıma Boyna düşer, boyna ağlardım ve annemin sıcağında Canım yandıkça büyüy...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kandirildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyişim de Ayrı Bir Lezzet', 'bekleyisim-de-ayri-bir-lezzet-muammer-celik-stxjx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitmiyor, 

bitmeyecek asla 

sana olan arzularım

sönmüyor, 

sönmeyecek asla

sana olan tutkularım

çözülmüyor, 

çözülmeyecek asla

sana olan bağlarım

dinmiyor 

ve dinmeyecek asla

sana olan duygularım

hayallerim

düşlerim

rüyalarım

renklerim

zevklerim

gerçeklerim

ve

sevişlerim’le

hep seni 

gözlerim….

BirDeli 

02.04.2004', 'Bitmiyor,  bitmeyecek asla  sana olan arzularım sönmüyor,  sönmeyecek asla sana olan tutkularım çözülmüyor,  çözülmeyecek asla sana olan bağ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bekleyisim-de-ayri-bir-lezzet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Su', 'aci-su-rabia-saglam-bn80t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geleceği kadar gelsin acı su 

Kanatlandım kanatlanacağım kadar

Bundan sonra ne bir manası nesnenin

Ne güzelliği bir demin

Sonbahar duraklarında durdun

Yaklaştın,

Yaklaştıkça ıraktın

Şimdi senden geriye

Bir diken, bir çırpınışlarım.', 'Geleceği kadar gelsin acı su  Kanatlandım kanatlanacağım kadar Bundan sonra ne bir manası nesnenin Ne güzelliği bir demin Sonbahar durakları...', ARRAY['Türk Edebiyatı','Şiir','Rabia Sağlam']::text[], 8.5, '{"poet":"Rabia Sağlam","poet_slug":"rabia-saglam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aci-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Bitti', 'deniz-bitti-i-brahim-bayraktar-37c0w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Altı koldan beslenirdi,

Tüm akarları birbirine bağlayan,

Dalgaları dağları yaralayan,

Gürül gürül akan,

Çağıl çağıl çağlayan,

Engin bir deryaydı deniz.

Başını kuma soktu,

Kan kustu, kin kustu,

Köpürdü, hiddetlendi, kükredi! 

Yorumlara yorum ekledi,

Ata yadigarıdır dedi,

Kutsal saydığı değerlere yaslandı,

Yıllarca, altı koldan beslendi deniz.

Bir ışık belirdi, hemen yanı başında,

Aldırmadı, görmezlikten geldi,

Hep bir kusur aradı, sorguladı, 

Savunmasız mekanlarda; 

Bildik yasalarla yargıladı. 

Kotalar koydu sizli, bizli,

Altını oydu geçmişin gizli gizli,

Ne memnun oldu, ne pişman,

Ne dost olabildi, ne de düşman.

Gün geldi damarlar tıkandı,

Nehirler sustu, denize küstü, akmaz oldu,

Çorak toprağa döndü, verimsiz ve kısır,

Yalnız kaldı, yalnızlıktan tir tir titredi,

Gürül gürül akan altı koldan beslenen deniz,

Kurudu; bembeyaz oldu; bet, beniz,

Ve kurudu, bitti deniz, bay kaldı...

02.04.2004', 'Altı koldan beslenirdi, Tüm akarları birbirine bağlayan, Dalgaları dağları yaralayan, Gürül gürül akan, Çağıl çağıl çağlayan, Engin bir dery...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/deniz-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Severim', 'nasil-severim-cahit-sanver-g2c30', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taş olası dilim ah sana mı dokundu

Mancınıklara kor atarım onu

Ama nasıl alırım onsuz senin tadını

Nasıl söylerim onsuz sana aşkımı.

Avuçlarıma ateşler koyuyorsun sevgilim

Yakmak, kül etmek mi istiyorsun

Ama nasıl tutarım onsuz ellerini

Nasıl tararım onsuz saçlarını.

Bakışların kör ediyor gözlerimi

Parlaklığın mıhlıyor sanki

Ama nasıl ıslatırım onsuz saçını

Nasıl gezinirim sokaklarını.

Şimdide kalbimde mi gözün

Çarpıyorsun, çarpıntısını durduracak kadar

Ama nasıl...

Nasıl...', 'Taş olası dilim ah sana mı dokundu Mancınıklara kor atarım onu Ama nasıl alırım onsuz senin tadını Nasıl söylerim onsuz sana aşkımı. Avuçlar...', ARRAY['Türk Edebiyatı','Şiir','Cahit Şanver']::text[], 8.5, '{"poet":"Cahit Şanver","poet_slug":"cahit-sanver","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünü Unutma Yarına Umutla Bak', 'dunu-unutma-yarina-umutla-bak-salih-ozalasan-hteez', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünü unutma yarına umutla bak

Geçmişin geleceğin aynasıdır

Hayatın asla olmaz  geçmişi

Dün hayatın ayrılmaz parçasıdır

Unutmuşsan geçmişinde sevdiğini

Kırmışsan sana uzatılan gülü tutan elleri

Ağlatmışsan seni gördüğünde parlayan gözleri

Yarın sende ağlarsın sakın unutma

Çıkar senide ağlatan birileri

Yakar yıkar, biranda yürekleri

Dün harcamamışsan geçmiş diye emekleri

Yarın sende ağlarsın sakın unutma

Dünü unutma yarına umutla bak

Yüreklerde sevgi ateşini dünden yak

Dünü unutana verilmez asla bir hak

Yarın hakkını kaybedersin sakın unutma

Hak verilmez ya alınır; yada kazanılır

Dün aldıkların mutlak yarına kalır

İnsanız bazen şeytan aldatır

Yarın şeytan kurtaramaz sakın unutma

Sev sevil; dün bugün yarın 

Dün ne kazanmışsan bil ki bugünedir karın

Unutma kış vardır önünde baharın

Kış gelmeden bahar gelmez sakın unutma

Y.Tarihi 02-04-04 Saat 16,00

Salih ÖZALAŞAN', 'Dünü unutma yarına umutla bak Geçmişin geleceğin aynasıdır Hayatın asla olmaz  geçmişi Dün hayatın ayrılmaz parçasıdır Unutmuşsan geçmişinde...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dunu-unutma-yarina-umutla-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz Isıttı İçimi Bu Sabah', 'karadeniz-isitti-i-cimi-bu-sabah-yildiz-yildiz-avyr7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İncecik bir saç teline gizlemişti,

Dudaklarının öpülmemiş fısıltılarını.

Pervasız açılmış,

İç denizlerin çalkantılarında 

bir ceviz kabuğu tekne misali,

Yürek çırpıntıları bırakmıştı cebine sevdalısının.

Ve incecik ipek bir saç teliyle bağlamıştı

Yüreğini gönül limanlarına

Saklayamadı, 

Sığmadı ellerine, ne sevdası, ne yasakları.

Avuçlarına battı, hayal kırıkları.

Kabul görse limandan,

bir saç teli! ... yetermiydi bağlanmaya

bilinmez

Olsundu

Onun saçına güveni tamdı,

Kalbi de saçı gibi sağlamdı.

Vazgeçmedi hiç sevdasından

Vazgeçilmişlik oldu

O tek saç telini koparan.

02/04/2004

Geçti bizden sevdaluk

Geçti bizden sevdaluk

Al cebuuumm... 

Al cebumden saçlari...

Az önce dinledim bu güzel Karadeniz türküsünü Volkan Konak''tan

Ve ilk kez, ilk aklıma geldiği şekilde dinlendirmeden, demlendirmeden kaydettim yazdıklarımı buraya sıcağı sıcağına', 'İncecik bir saç teline gizlemişti, Dudaklarının öpülmemiş fısıltılarını. Pervasız açılmış, İç denizlerin çalkantılarında  bir ceviz kabuğu t...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/karadeniz-isitti-icimi-bu-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkekler Ağlamaz', 'erkekler-aglamaz-veli-yilanci-rjv60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani erkekler ağlamazdı

Ağlıyorsun 

Sen de işte

Gözlerindeki yaşlar

İçmediğin sigaradan değil ya,

Ya da

Kesmediğin soğandan? 

Ağlıyorsun işte! 

Hani erkekler ağlamazdı? 

Ağlıyoruz işte!', 'Hani erkekler ağlamazdı Ağlıyorsun  Sen de işte Gözlerindeki yaşlar İçmediğin sigaradan değil ya, Ya da Kesmediğin soğandan?  Ağlıyorsun işt...', ARRAY['Türk Edebiyatı','Şiir','Veli Yılancı']::text[], 8.5, '{"poet":"Veli Yılancı","poet_slug":"veli-yilanci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/erkekler-aglamaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-veli-yilanci-wftb3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göz yaşlarım 

Suyu oldu

Sana olan sevgimin

Sen ağlattıkça

Sevgim büyüdü...', 'Göz yaşlarım  Suyu oldu Sana olan sevgimin Sen ağlattıkça Sevgim büyüdü......', ARRAY['Türk Edebiyatı','Şiir','Veli Yılancı']::text[], 8.5, '{"poet":"Veli Yılancı","poet_slug":"veli-yilanci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozyasi-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl', 'yeni-yil-veli-yilanci-fba8o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeni bir yıla

Nasıl girersen

Öyle geçermiş

Bütün yıl.

Ben

Seni düşünerek girdim', 'Yeni bir yıla Nasıl girersen Öyle geçermiş Bütün yıl. Ben Seni düşünerek girdim...', ARRAY['Türk Edebiyatı','Şiir','Veli Yılancı']::text[], 8.5, '{"poet":"Veli Yılancı","poet_slug":"veli-yilanci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yeni-yil-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Bir Gözde Sen Kırpıver', 'hayata-bir-gozde-sen-kirpiver-salih-ozalasan-jhzqx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayata göz kırpmasını bilmiyorsan doğumdan ölüme

Uymuyorsan dost bildiklerin doğru sözüne

Bir gün mutlaka yaşlar dolar gülen yüzüne

İki elin vursan da ne fayda dizine

Hayata kırp gözünü sende gülümse

Gülerek karşıla hüznü neşeyi mümkünse

Ruhun bebek kalsın, yaş kemale erince

Hayata göz kırpmasını öğren doğumdan ölüme

Y.Tarihi 02-04-04 Saat 16,50

Salih ÖZALAŞAN', 'Hayata göz kırpmasını bilmiyorsan doğumdan ölüme Uymuyorsan dost bildiklerin doğru sözüne Bir gün mutlaka yaşlar dolar gülen yüzüne İki elin...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayata-bir-gozde-sen-kirpiver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmış', 'yalanmis-galip-karabatak-zhxjt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben aşkı yalnız senle tattım

Bir tek senle böyle korkak

Bir tek senle böyle cesur oldum

Yalnız sana yandım ateşlerle

Ve yalnız sana söndüm

Savaşçılar gibiydi benim aşkım

Sana çiçeklerimi

Kanlı meydanlardan topladım

Ondandır boyunları bükük

Ondandır solmazlar hiç...

Ama sen veremedin bana aşkımın en ufak zerresini

Ya ben,

Senin için yana yana

Boşver be

Boşver gerisini...

Ah ulan yanmam da onca emeklerime

Yalanmış işte her şey

Şimdi prangalar takıpta bileklerime

Gidiyorum

Düşlerimdi sende bıraktığım son şey...

Hani beraber minicik evimizde

Sulayacaktık çiçeklerimizi

Hani sen göğsüme yatıpta şöminenin başında

Şarkılar söyleyecektin bana...

Ya kızımız ulan kızımız! 

Minicik ayaklarıyla basarken yerlere,

Minicik elleriyle tutarken ellerimizi,

Beraber ağlayacaktık hıçkırarak...

Yalanmış diyorum ya yalanmış! 

Aşkımız,

Vurgun yemiş bir gemiden arta kalanmış! 

Yalanmış ulan yalanmış! 

Benim Allah’ım aşk,

Seninkisi paranmış...', 'Ben aşkı yalnız senle tattım Bir tek senle böyle korkak Bir tek senle böyle cesur oldum Yalnız sana yandım ateşlerle Ve yalnız sana söndüm S...', ARRAY['Türk Edebiyatı','Şiir','Galip Karabatak']::text[], 8.5, '{"poet":"Galip Karabatak","poet_slug":"galip-karabatak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yalanmis-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil', 'yesil-ozkan-ozdogan-vb2ks', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak yine saçlarına benzettim

yağmuru...

ve işte yeşile çalıyor

gözlerimin camdaki yansıması.

Ben değilim yalnız bu kez,

şehirdir benim hüznümle ağlayan.', 'Bak yine saçlarına benzettim yağmuru... ve işte yeşile çalıyor gözlerimin camdaki yansıması. Ben değilim yalnız bu kez, şehirdir benim hüznü...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yesil-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-ozkan-ozdogan-87jjf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sus,

dedim serçeye..

Bitir artık matemini..

Kapıdaki,

bağıra bağıra baharlayan,

mevsime uydur sesini,

ki yeşil ve mavi açsın

kır çiçekleri...', 'Sus, dedim serçeye.. Bitir artık matemini.. Kapıdaki, bağıra bağıra baharlayan, mevsime uydur sesini, ki yeşil ve mavi açsın kır çiçekleri.....', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahar-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hor Görme Babo', 'hor-gorme-babo-emir-kemal-6em4g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tozlu  yollarında yürüdüm hayatın,

Dikenli...

İnce uzun,

Bir o kadar çileli.

Aklım çalışmazdı yalana,

Dilim dönmezdi...

Hor görme,

Yirmi iki doğumluyum, eski hesaptan...

Ağlarsam sessiz ağlar,

Karalar bağlarsam, dünyayı inletirim.

Kederim, bir ananın şefkati kadar sadece...

Hor görme babo,

Yirmi iki doğumluyum, eski hesaptan...

Ellerimi öpün,

Nasırlı çatlak ellerimi,

Öpün, tiksinmeyin ha! 

Nicesine ekmek verdi bu eller,

Orak tuttu,ekin biçti,sap attı,

Ağustosta mendil oldu ter sildi,

Öpün tiksinmeyin,

Yirmi iki doğumluyum, eski hesaptan...

Gözlerimin içine bakın,

Puslu donuk gözlerime...

Nice güzel gördü sorun,

Ve dokunun kalbime,

Dokunun ellerinizle.

Hey be! Kimler geldi kimler getti,

Nafile...

Sakın ha! 

Kırmayasınız onu,

Ve kızmayın şükürsüzlüğüme,

Hor görme gardaş,

Dedim ya; 

Yirmi iki doğumluyum, eski hesaptan...', 'Tozlu  yollarında yürüdüm hayatın, Dikenli... İnce uzun, Bir o kadar çileli. Aklım çalışmazdı yalana, Dilim dönmezdi... Hor görme, Yirmi iki...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hor-gorme-babo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklın Ötesindedir Aşk', 'aklin-otesindedir-ask-goktu-kara-oc0am', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üç arkadaşız bizler

birimiz deniz kenarında mavi düşlerle bezenmiş

birimiz dağ başında karlarla örtük 

birimiz mavi caminin az ötesinde deryaya dalmış

üç arkadaşız bizler

üçümüzde aşkın aklın ötesinde olduğunu biliyoruz

ve yolculuğun tam sırası

ı

çakıl ayaklarımıza batmakta

ahlar gökyüzünde yankılanmakta

ıı

çamur

gömülmekte ayaklarımız

korku her yanımızı sarmış

ölüm sessizce sese değin

ııı

kayalar uzun

tırmanıyoruz

elimiz kesilmekte

çıldırasıya bir kartal saldırmakta yüreklerimize 

prometeyi anımsadık

ama ne çare

geri dönmek yok

................', 'Üç arkadaşız bizler birimiz deniz kenarında mavi düşlerle bezenmiş birimiz dağ başında karlarla örtük  birimiz mavi caminin az ötesinde dery...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aklin-otesindedir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amelelere dair', 'amelelere-dair-atalay-isik-j8737', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kazma,kürek,bir galon su,cigara

Yeter kaldırımcı amelelere

kırışık,terli alınları kara

bakılmıyor hiç o nurlu gözlere', 'kazma,kürek,bir galon su,cigara Yeter kaldırımcı amelelere kırışık,terli alınları kara bakılmıyor hiç o nurlu gözlere...', ARRAY['Türk Edebiyatı','Şiir','Atalay Işık']::text[], 8.5, '{"poet":"Atalay Işık","poet_slug":"atalay-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/amelelere-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus', 'sus-yasar-pullu-tle0i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk tohumdur

yanlızlık büyütür derinlerde

çiçeklenmeye başlarsa

güz vurur yüzüne.

Dünyadan insana

son ikramdır aşk

dalgali bir denizdir

kaval deliğinde yanlız

Hadi sus konuşma

yanlızlığımı bozma

____________sus', 'Aşk tohumdur yanlızlık büyütür derinlerde çiçeklenmeye başlarsa güz vurur yüzüne. Dünyadan insana son ikramdır aşk dalgali bir denizdir kava...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sus-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Bir Gül Bıraktım', 'mavi-bir-gul-biraktim-vedat-koparan-dsxef', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerden süzdün yine bunu 

Demenin alemi var mı ki 

Aslan ağızlı insanlar varken 

Köle pazarlarından geçen arenada 

Tutturmuşsun dilime dolanan müzik diyorsun 

Can hıraş sesler geliyor duyulmuyor mu? 

Sorarım sana zor mu bir açlığı bastırmak 

Gün pınarında saçlarını yıkamak 

Bir tutam bahar gönençli sevgide kalmak 

Bu kadar oynama beynimle 

Yarımdır aklım kalırmıyım aklında. 

Korsan yürüyüşleri hatırlatan 

Korsan bir hava var bu bahar da 

Yürüyüşçüler nerde kaldılar yoklar hala… 

Bak sende gidiyorsun zaman av zamanı 

Uzak olmayan bir yürekten yakın yüreğine 

Dik kaleminde sevdan her daim sevgileri demleye.. 

Gidişin gidişimdir dönülmezliğe 

Senin olan sana kalan 

Al yüreğim al mavi bir gül bıraktım..', 'Nerden süzdün yine bunu  Demenin alemi var mı ki  Aslan ağızlı insanlar varken  Köle pazarlarından geçen arenada  Tutturmuşsun dilime dolana...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mavi-bir-gul-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mertce', 'mertce-ferit-teksoy-s3otp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Falcılar söyler ya hep,

Üç zaman sonra diye

İkisi gitti gülüm

Üçüncü var sırada! ..

Üçüncüde sen varsan

Heyecanım olacak

Sen varsan sarılırım,

Hayat denen kahpeye

Tutarsan ellerimi

Bakarsan gözlerime

Verirsen heyecanı,

Bütün hücrelerime

Ferhat olur delerim,

Dağ dayanmaz o zaman

Mecnun olur geçerim,

Çöl dayanmaz o zaman

Haydi uzat elini

Sık avucumu sertce

Geldim de..ben de varım..

Delikanlıca..mertce...', 'Falcılar söyler ya hep, Üç zaman sonra diye İkisi gitti gülüm Üçüncü var sırada! .. Üçüncüde sen varsan Heyecanım olacak Sen varsan sarılırı...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mertce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdigimi biliyorsun', 'sevdigimi-biliyorsun-kamil-boyraz-3aiay', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdiğimi biliyorsun.

Bazen gaddar oluyorsun.

Kalbime kazdım adını,

Aynı yerde duruyorsun.

Beni benden çaldığında,

Sana aşık olduğumda,

Beni iyi biliyordun,

Benimle oynadığında.

Günler bitti aylardayım.

Yoksun ya isyanlardayım.

Bir kerecik aramadın.

Onun için yoklardayım.

Sana sevgiyi öğretmek,

Bu kadar zor umuş demek.

Sevmediğini söyle ki

Bendeki seni öldür ek.', 'Sevdiğimi biliyorsun. Bazen gaddar oluyorsun. Kalbime kazdım adını, Aynı yerde duruyorsun. Beni benden çaldığında, Sana aşık olduğumda, Beni...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdigimi-biliyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni düşümnekten', 'seni-dusumnekten-kamil-boyraz-l85rn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanımdan canımdan parça,parça kopuyorsun.

Gerçekleri hayal edip beni avutuyorsun.

Her gün karşıma sorunlarla çıkıyorsun.

Seni düşünmekten kendimi düşünemiyorum.

Varsayımlar,taslaklar kafamda geziniyor.

Öyle bir an geliyor ki canımdan bezdiriyor.

Gözlerine bakınca yüreğime su serpiliyor.

Seni düşünmekten kendimi bulamıyorum.

Gecemde,gündüzümde hep hayalimdesin.

Ben seni düşünürken sen nerelerdesin.? 

Masamda meyimde kadehimdesin.

Seni düşünmekten sarhoş olamıyorum.

Sustun yine gözlerin konuşmak istiyor.

Heyecanını yen artık dizlerin titriyor.

Kollarını dola boynuma canım seni istiyor.

Seni düşünmekten gecelerdir uykusuzluğum.', 'Kanımdan canımdan parça,parça kopuyorsun. Gerçekleri hayal edip beni avutuyorsun. Her gün karşıma sorunlarla çıkıyorsun. Seni düşünmekten ke...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-dusumnekten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara, beni bulacaksın', 'ara-beni-bulacaksin-memet-zeki-ates-jq1qb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kem gözlerin karasında

Ara beni bulacaksın

Hazin gönül yarasında

Ara beni bulacaksın

Gökten kayan her,yıldızda

Sitem, kokan özlü sözde

Feri sönmüş bir çift gözde

Ara beni bulacaksın.

Nargile''min meşe''sinde

Şarabımın şişesinde

Meyhane''nin köşe''sinde

Ara beni bulacaksın.

Zeki Ateş adım dilde

Mecnun''muyum gezem çölde

Keremin yandığı külde

Arabeni bulacaksın.', 'Kem gözlerin karasında Ara beni bulacaksın Hazin gönül yarasında Ara beni bulacaksın Gökten kayan her,yıldızda Sitem, kokan özlü sözde Feri ...', ARRAY['Türk Edebiyatı','Şiir','Memet Zeki Ateş']::text[], 8.5, '{"poet":"Memet Zeki Ateş","poet_slug":"memet-zeki-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ara-beni-bulacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi ve Ask', 'sevgi-ve-ask-mucize-bahar-1q2xk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi ruhu doyuran, 

Aşk yüreği yakan... 

Sevgi görebilen, 

Aşk kör olan... 

Sevgi evrensellik, 

Aşk bireysellik... 

Sevgi huzur, 

Aşk heyecan... 

Sevgi cömert, 

Aşk bencil... 

Sevgi herşey, 

Aşk tekşey... 

Ne sevgisiz, 

Ne aşksız, 

Yaşam boşşey...', 'Sevgi ruhu doyuran,  Aşk yüreği yakan...  Sevgi görebilen,  Aşk kör olan...  Sevgi evrensellik,  Aşk bireysellik...  Sevgi huzur,  Aşk heyec...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgi-ve-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köye Geri Dönemem', 'koye-geri-donemem-kamil-boyraz-7mqf4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dereleri çağlayıp akmıyor

Viran olmuş köye geri dönemem

Bıraktığın köyde baca tütmüyor.

Ağaçlar kurumuş çiçek açmıyor

Kuşlar eskisi gibi ötmüyor

Çoban artık davarını gütmüyor

Çiçekler eskisi gibi kokmuyor

Viran olmuş köye geri dönemem

Sabahları  horoz boşuna öter 

Hasretim anama burnumda tüter

Bu hasretlik bize ölümden beter

Viran olmuş köye geri dönemem

Torosları duman sarmış yol vermez 

Çıkarsın dağları yolları bitmez

Emmimin düğününe kimse gelmez

Viran olmuş köye geri dönemem

Ağa bile terk etmiştir o köyü

Bekir dayıya haciz gelmiş doğrumu

Hatta mafya olmuş dediler oğlu

Viran olmuş köye geri dönemem', 'Dereleri çağlayıp akmıyor Viran olmuş köye geri dönemem Bıraktığın köyde baca tütmüyor. Ağaçlar kurumuş çiçek açmıyor Kuşlar eskisi gibi ötm...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/koye-geri-donemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-mucize-bahar-s1wq7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece seni görmek istiyor gözlerim, 

Sıcak ellerini tutmak istiyor ellerim, 

Sevginle dolup taşıyor yüreğim, 

Bu gece seni ölesiye özledim... 

Sana hasretim birtanem...', 'Bu gece seni görmek istiyor gözlerim,  Sıcak ellerini tutmak istiyor ellerim,  Sevginle dolup taşıyor yüreğim,  Bu gece seni ölesiye özledim...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hasret-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden doğuyorum', 'yeniden-doguyorum-fuat-dogan-bjp2r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YENİDEN DOĞUYORUM

mevsim gösterdi yüzünü

baharlanıyorum

kuşak kuşak

asır asır

bügün yeniden doğuyorum

bir ben değilim

toprak ana çiçekleniyor

yeşeriyor tabiat

yürekler yenileniyor

ve ben özgürleşiyorum bugünde

                   Fuat  DOĞAN

                          2004', 'YENİDEN DOĞUYORUM mevsim gösterdi yüzünü baharlanıyorum kuşak kuşak asır asır bügün yeniden doğuyorum bir ben değilim toprak ana çiçekleniyo...', ARRAY['Türk Edebiyatı','Şiir','Fuat Doğan']::text[], 8.5, '{"poet":"Fuat Doğan","poet_slug":"fuat-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yeniden-doguyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ögretmenim', 'ogretmenim-kamil-boyraz-jm5a0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok küçüktüm biliyorum 

Bilgisizdim titriyordum 

A yi B yi bilmiyordum 

Sen öğrettin öğretmenim

Saçlarımı okşayışın 

Okumayı öğretişin 

Atatürk’ü gösterişin 

Hatırımda öğretmenim

Çırpınırsın bizim için 

Düşünürsün için,için

Güneşim olduğun için 

Aydınlığım öğretmenim 

Yine okulda ve derste 

Bilgin dolu her nefeste

Bugün senin günün işte

Kutlu olsun öğretme', 'Çok küçüktüm biliyorum  Bilgisizdim titriyordum  A yi B yi bilmiyordum  Sen öğrettin öğretmenim Saçlarımı okşayışın  Okumayı öğretişin  Atat...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogretmenim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son sabah', 'son-sabah-kamil-boyraz-8a5vt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sigarasız geçen gecemin 

Son karanlıkları şafakta.

Şehir yeniden aydınlanıyor.

Uyumak zor sensiz yatakta

Hani gidişin mermi gibiydi

Saplandı yüreğime

Yıkılır sandın ya ayrıldığında

İşte ben yine yaşıyorum.

Son sabah da olsa yeniden gelen.

Son güneş de olsa yeniden doğan.

Son sigaramda olsa elimde yanan.

Yıkılmayan bedenimi taşıyorum.

Hayat devam edecek sen olmasan da.

Yiyecek ekmeğim içecek suyum kaldıkça

Bitene dek yaşayacağım.

Sigaram olmasa da son sabahta.', 'Sigarasız geçen gecemin  Son karanlıkları şafakta. Şehir yeniden aydınlanıyor. Uyumak zor sensiz yatakta Hani gidişin mermi gibiydi Saplandı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapihane', 'hapihane-kamil-boyraz-y1g2b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşam olur kapılar kapanınca

Yemek yiyip sigaramı yakınca,

Bende kalan son resmine bakınca,

Hüzün çöker bitmek bilmez geceler.

Bir pencerem var avluya bakar.

Bahçelerde kuşlar ne güzel şakır.

Hep birlikte özgürlüğe uçarlar.

Güneş doğmaz dört duvar arasında.

Sabah olur görüş günü gelince,

Bize gelir Anne,bacı,görümce.

Tel örgüden gül yüzünü görünce

Gece bitmez dört duvar arasında.

Hep hayalle yaşanır bu alemde,

Başka işin yok ki hapis hanede 

Dolaşırsın dünyayı bir gecede,

Zaman geçmez dört duvar arasında.', 'Akşam olur kapılar kapanınca Yemek yiyip sigaramı yakınca, Bende kalan son resmine bakınca, Hüzün çöker bitmek bilmez geceler. Bir pencerem ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hapihane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekledim', 'seni-bekledim-mucize-bahar-nzq4t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gündüzlerimi gecelerime ekledim, 

Birtanem seni bekledim.. 

Neredesin gel artık bana.. 

Seni ölesiye özledim... 

Sevda dolu bakışlarını, 

Özlem kokan tenini, 

Ben senin herşeyini 

Özledim ve bekledim.. 

Bazen yürek sızısı, 

Bazen ruhumun yarası, 

Bazende gözlerinin karası 

Oldun içimde benim, 

Her ne olursan ol 

Seni ömrümün sonuna kadar beklerim... 

Bekledim, 

Bekleyeceğim...', 'Gündüzlerimi gecelerime ekledim,  Birtanem seni bekledim..  Neredesin gel artık bana..  Seni ölesiye özledim...  Sevda dolu bakışlarını,  Öz...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-bekledim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-kamil-boyraz-hgtjs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasret iyin ateşi çöktü gönlüme

Haykırmak istiyorum gök yüzüne

Ayrılık acısı bir hançer gibi

Saplandı kalbime yine bu akşam.

Elimde sigaram masamda şarap,

Ne günah işledim ey yüce ya rap.

Derdimle şu köşede ağlayarak.

Tek başıma uyudum yine bu akşam.

Sönmeyen kor ateştin yüreğimde,

Bitmeyen umuttun gözlerimde,

Sensiz dertlerimin çaresi sende.

Avut beni gel de bu akşam.

Şarkimiz çalınıyor uzaklarda.

Bitmeyen name gibi dudaklarda.

Beni öldüren bu ayrılık var ya,

Azrail misali geldi bu akşam.', 'Hasret iyin ateşi çöktü gönlüme Haykırmak istiyorum gök yüzüne Ayrılık acısı bir hançer gibi Saplandı kalbime yine bu akşam. Elimde sigaram ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-aksam-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-mucize-bahar-hu0ks', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum, 

Sen benim her şeyim, ışığımsın, 

Sen benim ruhumun ince gülüsün… 

Seninle gülümsüyorum hayata, 

Seninle her sabah yeniden doğuyor güneş, 

Seninle her akşam batiyor tekrar… 

Seninle gündüzüm, seninle gecem… 

Ben sensiz yoksun ve eksik, 

Ben sensiz bir hiçim…. 

Yaşamımın anlamı, hayatımın sırrısın... 

Sensiz bir yaşam düşünemem, 

Sen vazgeçemediğim Cankuşumsun… 

Seni çok seviyorum…..', 'Seni seviyorum,  Sen benim her şeyim, ışığımsın,  Sen benim ruhumun ince gülüsün…  Seninle gülümsüyorum hayata,  Seninle her sabah yeniden d...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-176-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleriyin Kaçışı', 'gozleriyin-kacisi-kamil-boyraz-j1729', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bin bir umutlarla koştum yanına.

Bir tebessüm mü çok gördün bana.

Söyle bir tanem ne oldu sana? 

Gözlerin,gözlerinden kaçıp gidiyor.

Maksadın eziyet etmekse söyle.

Seven insana yakışır mı böyle,

Bir dargın bir barışık olmuyor böyle

Gözlerin gözlerimden kaçıp gidiyor.

Sana yıllarımı vermek isterim.

Bilirsin seni ben ne çok severim.

Sen olmazsan yanımda derbederim.

Gözlerin gözlerimden kaçıp gidiyor.

Yıl dönümümüz gelecek ayda.

Seninle tanışmıştık bir sonbaharda,

Beraber olmamız zaten olayda.

Gözlerin gözlerimden kaçıp gidiyor.', 'Bin bir umutlarla koştum yanına. Bir tebessüm mü çok gördün bana. Söyle bir tanem ne oldu sana?  Gözlerin,gözlerinden kaçıp gidiyor. Maksadı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozleriyin-kacisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-kamil-boyraz-gljer', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu akşam sensiz ligin yerine içtim.

Bu akşam gözlerinin rengine içtim.

Bu akşam tek edip gidişine içtim.

Bu akşam hasret ateşine içtim.', 'Bu akşam sensiz ligin yerine içtim. Bu akşam gözlerinin rengine içtim. Bu akşam tek edip gidişine içtim. Bu akşam hasret ateşine içtim....', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sitem-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamsin', 'sevdamsin-mucize-bahar-6f1yb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen Sevdiğimsin.... 

Sen beklediğimsin..... 

Özlemin bir dağ oldu içimde..... 

Seni düşlüyorum.... 

Hayaller kuruyorum aşka dair..... 

Sevdanı büyütüyorum yüreğimde..... 

Sen herşeyim, 

Yüreğimden gelen sevdamsın...... 

Cankuşum.... 

23.02.2003 

17.00', 'Sen Sevdiğimsin....  Sen beklediğimsin.....  Özlemin bir dağ oldu içimde.....  Seni düşlüyorum....  Hayaller kuruyorum aşka dair.....  Sevda...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdamsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Aşk', 'yasak-ask-kamil-boyraz-euggg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kolay olmayacak seni unutmak.

İçimde kanayan yaram olacaksın.

Unutmam imkansız sevgilim seni

Gözümden akan yaşım olacaksın', 'Kolay olmayacak seni unutmak. İçimde kanayan yaram olacaksın. Unutmam imkansız sevgilim seni Gözümden akan yaşım olacaksın...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasak-ask-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildiğin Gibiyim', 'bildigin-gibiyim-kamil-boyraz-6quno', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unutulmak ölüm oldu unutulmak zulüm.

Unutmak kolaysa önce sen unut gülüm.

Bu günüm sensin,yarınım sen,sensin dünüm.

İşte benim yaşantım bildiğin gibiyim.

Çektiğim her sigara gibi nefesimdesin.

İçtiğim meyim gibisin kadehimdesin.

Gündüzümdesin gecemdesin hep benimlesin.

İşte benim yaşantım bildiğin gibiyim.

Çaresiz dertlerime çare olmuyorsan.

Çıkmazlara saplandım yol bulamıyorsam.

Benim bu derdimden sende anlamıyorsan.

İşte benim yaşantım bildiğin gibiyim.

Bu yalan dünyanın dümeni bozulmuşsa,

Sensizliğin hesabı benden sorulmuşsa

Kötü kaderim yeniden beni bulmuşsa,

İşte benim yaşantım bildiğin gibiyim.', 'Unutulmak ölüm oldu unutulmak zulüm. Unutmak kolaysa önce sen unut gülüm. Bu günüm sensin,yarınım sen,sensin dünüm. İşte benim yaşantım bild...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bildigin-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştım', 'alistim-kamil-boyraz-xarij', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alıştım sensiz yarınlara umutla bakmaya,

Alıştım saçlarını resminde okşamaya,

Alıştım rüyalarda seninle dolaşmaya,

Alıştım,alıştım bir tanem alıştım artık.

Alıştım gündüzleri  gecelere  eklemeye,

Alıştım gelmesen de  zamansız beklemeye

Alıştım içim kan ağlarken sahte gülmeye,

Alıştım, alıştım bir tanem alıştım artık.

Alıştım kader mahkumu gibi ağlamaya,

Alıştım tanrıya her gece hep yalvarmaya,

Alıştım içip kör kütük sarhoş olmaya,

Alıştım,alıştım bir tanem alıştım artık.

Varlığın en güzel hediyeydi yokluğun ölüm.

Bu şehir bomboş sen olmayınca gülüm.

Yaşantım yaşantı değil sensizlik hep ölüm.

Alıştım,alıştım bir tanem alıştım artık.', 'Alıştım sensiz yarınlara umutla bakmaya, Alıştım saçlarını resminde okşamaya, Alıştım rüyalarda seninle dolaşmaya, Alıştım,alıştım bir tanem...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alistim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozledim Seni', 'ozledim-seni-mucize-bahar-18ha6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaklarda bir yerlerde sakladim gonlumu,

Kimse arayip bulamadi....

Sozcuklerimin arasina seni koydum gizlice,

Kimse farkina varamadi.....

Ozledim O huzun dolu gozlerini,

Ozledim ellerini,tenini...

Ozledim benim olmayan dudaklarini,

Ozledim seni...

Ozledim hayallerimin Prensini........', 'Uzaklarda bir yerlerde sakladim gonlumu, Kimse arayip bulamadi.... Sozcuklerimin arasina seni koydum gizlice, Kimse farkina varamadi..... Oz...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ozledim-seni-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alcanımı', 'alcanimi-kamil-boyraz-0p0cb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyadaki dertler bana mı yazıldı

Uykularım kaçtı düzenim bozuldu.

Sevip taptıklarım bana el oldu.

Al canımı yarabbi istemiyorum.

Başımızla sonumuz belli değil ki,

Çektiğimiz ıstıraplar yetmedi mi ki

Daha çekeceklerim bitmedi mi ki

Al canımı yarabbi istemiyorum.

Bu kaderim benimle oyun oynuyor.

Kör talihim sesimi neden duymuyor.

Neyi dilesem,dileklerim tutmuyor.

Al canımı yarabbi istemiyorum.

Avuntuyla geçti gençliğim,yıllarım.

Çıkmaz sokak oldu seçtiğim,yollarım.

Çoktan kırıldı güvendiğim dallarım.

Al canımı yarabbi istemiyorum.

Kamil idim Kamil kalmaktı dileğim.

Kayıplara karıştı iyilik meleğim.

Sende bıraktın beni canım sevgilim.

Al canımı yarabbi istemiyorum.', 'Dünyadaki dertler bana mı yazıldı Uykularım kaçtı düzenim bozuldu. Sevip taptıklarım bana el oldu. Al canımı yarabbi istemiyorum. Başımızla ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alcanimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Gözüm', 'i-ki-gozum-kamil-boyraz-resn6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçime bir sıkıntı çöktü yeniden.

Gözlerim fırlayacak gibi yerinden.

Bu günde yanıyor yüreğim derinden.

Neredesin ki gözüm,neredesin  nerede.? 

Kabuslarım artıyor inan her gece,

Seni arzuluyorum şimdi delice,

Her yerde arıyorum seni gizlice.

Neredesin iki gözüm,neredesin nerede.? 

El ele dolaşıp gezdiğimiz o yerler.

Nerede  kaldı sevgi dolu o günler.

Ayırdı bizi bilmediğimiz güçler.

Neredesin iki gözüm, neredesin nerede.? 

Doluyor gözlerim ağlayamıyorum.

Sensiz günlerime alışamıyorum.

Ayrılık neden geldi  anlamıyorum.

Neredesin iki gözüm, neredesin nerede? 

Helal et hakkını göremezsem seni.

Bu hasretlik bir gün öldürecek beni.

Üzülme benim için üzme kendini.

Neredesin iki gözüm neredesin,nerede?', 'İçime bir sıkıntı çöktü yeniden. Gözlerim fırlayacak gibi yerinden. Bu günde yanıyor yüreğim derinden. Neredesin ki gözüm,neredesin  nerede....', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-gozum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-kamil-boyraz-ab0tn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çocuk ağlıyordu duvarın kenarında.

Göz yaşları kurumuş ümitleri tükenmiş,

Bir çocuk ağlıyordu duvarın kenarında,

Anne diye,Baba diye iki sinide kaybetmiş.

Bir çocuk ağlıyordu duvarın dibinde,

Dünya üzerine çökmüş sanki evleri değil.

Bir çocuk ağlıyordu duvarın dibinde,

Oyuncağını kaybetmiş kitabını değil.

Bir çocuk ağlıyordu duvarın dibinde,

Ayakkabısının biri elinde diğeri nerede? 

Bir çocuk ağlıyordu duvarın dibinde,

Kardeşini kaybetmiş ablası nerede? 

Bir çocuk ağlıyordu duvarın dibinde,

Arkadaşı burada komşuları yok.

Bir çocuk ağlıyordu duvarın dibinde,

Kayboluyor sesi makinelerin gürültüsünde.

Bir çocuk ağlıyordu duvarın dibinde,

Başında ağlayan arkadaşının ağıdına

Bir çocuk ağlıyordu duvarın dibinde,

Elini kaybetmiş,kağıt tan uçurtmasına.', 'Bir çocuk ağlıyordu duvarın kenarında. Göz yaşları kurumuş ümitleri tükenmiş, Bir çocuk ağlıyordu duvarın kenarında, Anne diye,Baba diye iki...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deprem-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevismek Seninle', 'sevismek-seninle-mucize-bahar-4hdi7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevismek seninle cilginca bir arzuyla,

Karismak tenine yildizlarin altinda,

Sevismek seninle gecenin sessizliginde,

Opuslerinle merhaba demek sabaha.....

Gokyuzunden bir yildiz kaydirmak safaga,

Derinden sevismek seninle bir daha,

Sevdali bulut olup islanmak yagmuruda,

Sevismelerinle kaybolup yok olmak sabaha.....', 'Sevismek seninle cilginca bir arzuyla, Karismak tenine yildizlarin altinda, Sevismek seninle gecenin sessizliginde, Opuslerinle merhaba deme...', ARRAY['Türk Edebiyatı','Şiir','Mucize Bahar']::text[], 8.5, '{"poet":"Mucize Bahar","poet_slug":"mucize-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevismek-seninle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Dön Bana Yada Ara', 'ya-don-bana-yada-ara-kamil-boyraz-8wj07', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç gecem geçti bilmem sensiz boş sokaklarda.

Her gecem gebe kaldı doğmamış şafaklara.

Şimdi neredesin bilmem benden çok uzaklarda

Ya dön baba ya ara,yada bir haber gönder.

Sensiz olmuyor inan bunu çok geç anladım.

Dönersin diye tanrıma her gece yalvardım.

Deli gönlümü bir başkasıyla avutamadım.

Ya dön bana,ya ara,yada bir haber gönder.

Tiryakin oldum,başkaları tatmin etmiyor.

Seni seven kalbime gücüm yetmiyor.

Ne gecem,ne gündüzüm sen olmazsan bitmiyor.

Ya dön,ya ara,yada bir haber gönder.

Sensiz dolaştım gezdiğimiz o yerleri.

Öyle özledim ki seninle dolu o günleri,

Bir başka oluyordu çatı barda geceleri.

Ya dön,ya ara yada bir haber gönder.', 'Kaç gecem geçti bilmem sensiz boş sokaklarda. Her gecem gebe kaldı doğmamış şafaklara. Şimdi neredesin bilmem benden çok uzaklarda Ya dön ba...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ya-don-bana-yada-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahbe', 'kahbe-kamil-boyraz-95naq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın adını sen koydum sen olacaksın.

Kap karanlık gece gibi gönlüme dolacaksın.

Sana melek diyorlar,Şeytan bile olamazsın.

Bir ömür boyu gönlümde öylece kalacaksın.

Rüyalarda korkulu kabusum olacaksın.

Sen kötü kaderim,alın yazım olacaksın.

Hep böyle anılacak hep böyle kalacaksın.

Gönül bahçemde açan siyah lalem olacaksın.

Yalnızlığın kaderini kendinde bulacaksın.

Mutluluğa gidemezsin yerinde sayacaksın.

Sokakların kadınısın,sokakta kalacaksın.

Sana beddua etmem Allah’ından bulacaksın.', 'Yalnızlığın adını sen koydum sen olacaksın. Kap karanlık gece gibi gönlüme dolacaksın. Sana melek diyorlar,Şeytan bile olamazsın. Bir ömür b...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kahbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayali Umutlaar', 'bir-hayali-umutlaar-kamil-boyraz-app78', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen yoktun bir zamanlar var olan kötülüklerdi,

Azgın otlardı naçar topraklarda büyüyen.

Tutup elimden beni karanlıklara sürükleyen.

En kirli güzelliklerde yaşayan ölülerdi.

Ben doluydum çaresizdim onlar gülerdi.

Sen yoktun bir zamanlar var olan kötülüklerdi.

Bir kalın perdeydi geceler kalın buruşuk,

Geçirirdik en güzel saatleri caddelerde,

Bütün ağırlıkların üstümüze çöktüğü yerde

Başlardı o çıldırtan uğultulu yolculuk.

Git gide en karanlıklarda erir,kaybolurduk.

Bir kalın perdeydi geceler kalın buruşuk.

Bir sonsuz aldanıştı o yerlerde yaşamak

Git gide terk etti bizi insanlığımız.

Büyüdü kederimiz arttı karanlığımız.

Bir yokluğa götürdü bizi böyle var olmak.

Ne sana çok yakın ne senden çok uzak,

Bir sonsuz aldanıştı o yerlerde yaşamak.

Sen yoktun inandık geleceğine yaşadıksa.

Önce ellerin dolaştı yüzümde senin

Sonra dudakları ve eşsiz gözlerin.

Sen geleceksin diye kapım hep açık.

Şimdi her şey en güzel her yer en aydınlıksa

Sen vardın,varsın inandık geleceğine yaşadıksa.', 'Sen yoktun bir zamanlar var olan kötülüklerdi, Azgın otlardı naçar topraklarda büyüyen. Tutup elimden beni karanlıklara sürükleyen. En kirli...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-hayali-umutlaar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik Kuş', 'minik-kus-kamil-boyraz-vkngn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kanadı kırılmış yavru bir kuş gibi,

Özlemlerin olacak kırık hayallerin.

Şöyle bir bakacaksın gök yüzüne,

Ta yüreğinde göğüs kabartacaksın mavi boşluğa.

Süzülür gibi dalacaksın boş hayallere,

Her çırpınışın bir yalvarış olacak tanrıya,

Yalvarışın kanat çırpışında kalacak.

Öylece mahzun,mahzun bakacaksın boşluğa,

Bir kambur gibi sırtında kanatların.

Uçamıyorsun ya işte sıkıntın bu...

Sabır taşın çat diye çatlayacak ortasından.

Belki isyan edeceksin gök yüzünün mavisine.

Akasya ağaçlarına, gül bahçelerine,

Bir gurup kuş uçacak uzak yerlere,

Öylece kala kalacaksın yer yüzünde.

İşte o zaman yüreğinde bir sızı.

Sabret güzel kuşum sabretmesini öğreneceksin.

Sende engin denizlere kanat çırpacaksın.

Gök yüzünün mavisine sende kanacaksın.

Seni nasıl sevdiğimi işte o gün anlayacaksın.', 'Kanadı kırılmış yavru bir kuş gibi, Özlemlerin olacak kırık hayallerin. Şöyle bir bakacaksın gök yüzüne, Ta yüreğinde göğüs kabartacaksın ma...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/minik-kus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıl Dönümü', 'yil-donumu-kamil-boyraz-yttat', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daha dündü unutmadık.

Bu olaydan ders almadık.

Taş üstüne taş koymadık.

Ölen bizim can canımız.

Gölcük ile Yalova da,

İzmit, Adaba zarında da,

İstanbul’da Avcılarda,

Ölen bizim can canımız.

Senesi geldi geçiyor.

Sorunları çare bekliyor.

Beyler buna ne diyor.? 

Ölen bizim can cananımız.

Allah başka bela vermesin.

Bir daha hiç göstermesin.

Akan göz yaşımız dinsin.

Ölen bizim can canımız.', 'Daha dündü unutmadık. Bu olaydan ders almadık. Taş üstüne taş koymadık. Ölen bizim can canımız. Gölcük ile Yalova da, İzmit, Adaba zarında d...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yil-donumu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitsiz Bekleyiş', 'umitsiz-bekleyis-kamil-boyraz-69055', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç bu kadar çaresiz kalmamıştım.

Çaresizliğimle yalvarmamıştım.

Resmine bakıp da ağlamamıştım.

Ümitsiz bekleyişim devam edecek.

Gök delinip yağa sa da üstüme,

Sağır karanlık çökse de üstüme,

Sözüm geçmese de deli gönlüme.

Ümitsiz bekleyişim devam edecek.

Özleminle yandığım gecelerimde,

Bir serap olurdun gözlerimde,

Hayalimdesin,düşümdesin,yüreğim de,

Ümitsiz bekleyişim devam edecek.

Kaç gece hayalinle sabahladım.

Kimseye derdimi anlatamadım.

Çaresizliğime derman aradım.

Ümitsiz bekleyişim devam edecek.

Umutsuzluğa bende boyun eğdim.

Hani sen,sen benimdin göz bebeğim.

Seni her halinle inan sevmiştim.

Ümitsiz bekleyişim devam edecek.

Gök delinip yağsa da üstüme.

Sağır karanlık çökse de gözüme.

Sözüm geçmese de deli gönlüme.

Ümitsiz bekleyişim devam edecek.', 'Hiç bu kadar çaresiz kalmamıştım. Çaresizliğimle yalvarmamıştım. Resmine bakıp da ağlamamıştım. Ümitsiz bekleyişim devam edecek. Gök delinip...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/umitsiz-bekleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Seni Bana Bırak..', 'sen-seni-bana-birak-hurrem-yalcin-riah5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen seni bana bırak giderken

Henüz vakit çok erken

Can bedensiz

Ben sensiz yaşarken

Sen seni bana bırak giderken

Bırak kalsın 

Sen ben''de

Al götür istersen 

Beni sende

Yüreğim durma

Sen delicesine sev

Sevi tinde

Sevgi tende

Sen ben''de

Ben sende

Bitmez 

Tükenmez

Sevgim

Yüreğimde....

17.02.2003', 'Sen seni bana bırak giderken Henüz vakit çok erken Can bedensiz Ben sensiz yaşarken Sen seni bana bırak giderken Bırak kalsın  Sen ben''de Al...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-seni-bana-birak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara Gelirim Bekle Demiştin', 'bahara-gelirim-bekle-demistin-kamil-boyraz-y29ma', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soğuk bir son bahar günüydü en acısı acılararın 

Harekete hazırlanan bir otobüs

Gözlerin gibi ağlayan bir yağmur.

Gizli bir güç seni benden koparırken,

Titreyen dudaklarınla,

Bahara gelirim bekle diyordun.

Acılarla dolu bu son bahar olduğunu nereden bilirdim.

Nereden bilirim bir daha bahar gelmeyecek.

Bir daha çiçekler açmayacak.

Hüzünle dolu kaç bahar geldi geçti,

Sen gelmedin hazanda geldi geçti.

Seni beklediğim baharlarda,

Sana benzeyen her şeyi sevdim.

Kaçamak aşklarla kendimi avuttum.,

Ama şu zavallı gönlümü avutamadım.

Kaçamak  aşkların   hiç biri sana benzemiyordu,

Ya gözleri küçük,ya dudakları büyük.

Ya da boyu kısaydı,saçları seninki gibi sarı olsa da.

Gözleri gözleriyin yeşilini andırsada

Hiçbir gözde görmedim.

Alev gibi bakışlarını,nede o tatlı gülüşünü.

Şimdi sen yoksun ya sevgili.......................

Belki bu baharda gelirsin.! 

Her şeyini unuttum biliyormusun.

Kaprislerini,yağmurda sokakta bekletildiğimi,

Telefonlara çıkmayışını,randevulara gelmeyişini,

Hemen her,şeyini.

Bir  seni,

Bir seni unutamadım sevgili.....................

On baharda geçse yüz baharda geçse,

Sanmıyorum unutayım.

Ağaçlar yine tomurcuklandı,

Yine bahar gelecek 

Gözlerin gibi bir baharda geleceksin eminim.

Bilirsin seni ne çok sevdiğimi,

Bilirsin seni beklediğimi.

Onun içindir her yağmur evi’yin önünde bekliyorum.

Islak kaldırımlarında olta atıyorum sokağınızın.

Ya sabır,ya sabır tespih çekiyorum parke taşlarıyla.

Soğukluğu bir şamar gibi indiğinde sabahın. 

ya bir sundurmanın  altında yada sandalların siperinde,

Buluyorum kendimi.

Eskiden düşlerim böyle dağınık değildi,

Gülüşlerim böyle yapmacık.

Bulutlar gibi kümeleşen acıları bir gülüşün dağıtırdı

Yüreğime çöreklenmezdi gece yarılarında özlerin.

Hiç bu kadar uzak olmamıştı gün ışığına hasretim.

Ve hiç bu kadar güç olmamıştı baharın gelişi.

Hasretin bu kadar büyümemişti göz bebeklerimde.

Hiç bu kadar çaresiz hissetmemiştim kendimi,

Özlemlerinin türküsünü bu baharda söyledim.

Geleceksin diye seni kaç bahar daha beklerim.! 

23.07.2001', 'Soğuk bir son bahar günüydü en acısı acılararın  Harekete hazırlanan bir otobüs Gözlerin gibi ağlayan bir yağmur. Gizli bir güç seni benden ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/bahara-gelirim-bekle-demistin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**aynalar', 'aynalar-ahmet-turan-altunsu-kh2oj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '/ey aşk

/ varlığındır beni umutlandıran

/ ve bütün uzuvlarımı kanatlandıran

/ yokluğun, umut lâhitlerinde hapsediyor beni

/ ruhsuz ve karanlık

/ kim bilir, belki de sana adıyor beni... 



adımlarımda sırdır yılların meşakkati 

ve yorgun yüreğimde rastlanır izlerine 

boşa geçmiş yılların tarumar ettiği ben 

yüklenir geçmişini yorgun omuzlarına

/ ne yâre kulaç oldum, ne kulaç oldu yârim 

/ ne yâr bahtiyar oldu, ne de ben bahtiyarım 

yüreğim kırık dökük, boğazım düğüm düğüm 

darmadağın bir surat aynalarda gördüğüm

ne kıymeti var şimdi bilerek öldürdüğüm 

ruhumun benim için? Bir ceset kadar varım 

/ ne yâre ilâç oldum, ne ilâç oldu yârim

/ ne yâr bahtiyar oldu, ne de ben bahtiyarım

kırık aynalardaki suretime bir bakın 

hangisinde, suretim suretinize yakın 

yok birbirinden farkı, seyretmeyi bırakın 

yâr gibi yâr bulmadan gelip geçmiş yıllarım 

/ ne yâre muhtaç oldum, ne muhtaç oldu yârim 

/ ne yâr bahtiyar oldu, ne de ben bahtiyarım', '/ey aşk / varlığındır beni umutlandıran / ve bütün uzuvlarımı kanatlandıran / yokluğun, umut lâhitlerinde hapsediyor beni / ruhsuz ve karanl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aynalar-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylülden Önce', 'eylulden-once-kamil-boyraz-721n0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kumsalları sermeyeceğim çıplak ayaklarına.

Papatyalardan taç yapmayacağım saçlarına.

Kirpik erimin ucundan dökülmeyecek yaşlar.

Eylülden önce gideceğim sen uyanmadan.

Yine bensizlik dolu gecelerin başlayacak.

Kabusların sıklaşacak korkun artacak.

Eskisi gibi öpücükler kondurmayacağım resmine,

Eylülden önce gideceğim sen uyanmadan.

Beni bulamayacaksın belki uyandığında,

Masada kalmış diye çıkacaksın sokaklara

O meyhanede olacağım belki de ama

Eylülden önce gideceğim sen uyanmadan.

Çağırtmaçlar çağıracak dört bir yana ismimi,

 Ne beni bulacaksın nede yırtık resmimi.

Gittiğim yerden sana seslenirim ama,

Eylülden önce gideceğim sen uyanmadan.

Raylar özlemimle daha bir başka uzayacak.

Rüzgar bensiz daha bir şiddetli esecek.

Saçlarını tutamayacağım dağılacak ama,

Eylülden önce gideceğim sen uyanmadan.

Fırtınalar dinecek belki yüreğinde,

Sakin bir deniz olacak göz bebeklerin.

Bensizliğe alışacaksın,unutmadan.

Eylülden önce gideceğim sen uyanmadan.

Son otobüste gelecek beldedeki durağına

Öpücükler konduran olmayacak dudağına,

Daha bir ürkek gireceksin yatağına.

Eylülden önce gideceğim sen uyanmadan.

Hani hep gideceğim derdinde gidemezdin.

Kopamazdın sevgi dolu sevdiklerinden.

Bir gün senin gidişi in acısını tatmadan.

Eylülden önce gideceğim sen uyanmadan.', 'Kumsalları sermeyeceğim çıplak ayaklarına. Papatyalardan taç yapmayacağım saçlarına. Kirpik erimin ucundan dökülmeyecek yaşlar. Eylülden önc...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/eylulden-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeterki Sen Gel', 'yeterki-sen-gel-kamil-boyraz-500t1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde bir sızı başladı yine

Nasıl çarpar kalbim kulak ver dinle.

En güzel günleri geçti seninle.

Bitirirsen eğer bende biterim.

Her gün olmasalda ayda bir gün gel.

Nasıl vuracağım gönlüme engel.

Hazan gönlümün baharısın sen gel.

Gideceksen eğer bende giderim.

Razıyım söylenen hakaretlere,

Bana bıraktığın bütün dertlere,

Çektirdiğin bütün eziyetlere,

Razıyım yeterki,yeterki sen gel.

İhtiyatta kalma küsmedim sana.

İnsan kıyarmı kızarmı canana

Yaptığın en iyi kötülük bana 

Kendini gizleyip gelmeyişindir.

Her gün olmasalda ayda bir gün gel,

Nasıl vuracağım gönlüme engel.

Hazan gönlümün baharısın sen gel

Gideceksen eğer bende giderim.', 'İçimde bir sızı başladı yine Nasıl çarpar kalbim kulak ver dinle. En güzel günleri geçti seninle. Bitirirsen eğer bende biterim. Her gün olm...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeterki-sen-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Gel Geleceksen', 'simdi-gel-geleceksen-kamil-boyraz-zi2ck', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklımdan çıkardım da gönlüm den atamadım.

Senin yerin başkaymış seni unutamadım.

Kaç kalbe girdimse mutluluğu bulamadım.

Şimdi gel geleceksen, sonra geç kalmayasın.

Yosundan yeşil gözlerine hasret kalmışken,

Sarı saçlarının rüzgarına kapılmışken,

Elma yanaklarının biraz tadı kalmışken,

Şimdi gel geleceksen,sonra geç kalmayasın.

Gözlerim den ırak da gönlümün tahtındayken.

Uykusuz gecelerimde sabahlarımdayken,

Seni beklediğim masada,kadehimdeyken,

Şimdi gel geleceksen,sonra geç kalmayasın.

Irak kalma hasret çektirme ne olur.

Sim siyah saçlarım,sonra beyaz bulursun,

Belki bir mezar taşında adimi okursun,

Şimdi gel geleceksen,sonra geç kalmayasın.', 'Aklımdan çıkardım da gönlüm den atamadım. Senin yerin başkaymış seni unutamadım. Kaç kalbe girdimse mutluluğu bulamadım. Şimdi gel gelecekse...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/simdi-gel-geleceksen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şevval Yıldızım', 'sevval-yildizim-kamil-boyraz-m92es', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece yıldızlar yok,

Yine yalnız kalacağım.

Hani şevval yıldızım,

Sensiz nasıl yatacağım.

Sendin benim sırdaşım,

Sendin benim arkadaşım.

Sendin benim yoldaşım,

Sensiz nasıl yatacağım.

Derdimi sen dinlerdin,

Bana hep hak verirdin.

Uzaklardan gülümserdin.

Sensiz nasıl yatacağım.

Hani sen yoksun diye,

Yine döndüm deliye,

Yarın gelirsin belki de,

Sensiz nasıl yatacağım.

Hani şevval yıldızım.

Bu gece ben yalnızım.

Olmasın bu alın yazım.

Sensiz nasıl yatacağım.

Duygularım içimde,

Yarın aynı biçimde,

Seni görsem gök yüzünde,

Sensiz nasıl yatacağım.', 'Bu gece yıldızlar yok, Yine yalnız kalacağım. Hani şevval yıldızım, Sensiz nasıl yatacağım. Sendin benim sırdaşım, Sendin benim arkadaşım. S...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevval-yildizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendiler', 'efendiler-kamil-boyraz-um873', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu milleti kandırması çok kolay,

Diyin efendiler şimdi diyin.

Devletin malını yemesi kolay,

Yiyin efendiler şimdi yiyin.

Beş yüz elli maraba var orada,

Oylayın efendiler şimdi oylayın.

Bu maaşınız yetmez’ ki daha

İsteyin efendiler şimdi isteyin.

Sözümüz meclisten girsin içeri,

Duyun efendiler şimdi duyun.

Seçim günleri gelecek geri,

Soyun efendiler şimdi soyun.

Hani diyorum elime geçersen,

Duyun efendiler şimdi duyun.

.........olsun bir daha seçen,

dinleyin efendiler şimdi dinleyin.

Karagöz perdesini açtığı zaman,

Seyredin efendiler şimdi seyredin.

Mazi ye bir bakın eskimez insan.

Bekleyin efendiler şimdi bekleyin.

Bu baharın birde kışı olacak.

Özleyin efendiler şimdi özleyin.

Yağmur olup üstünüze yağacak,

Titreyin efendiler şimdi titreyin.

İmralıya getirdiniz bir tosun.

Besleyin efendiler şimdi besleyin,

Şehit anaları saçını yolsun.

İzleyin efendiler şimdi izleyin.

Kamil derki a-ha geldim giderim.

Ağlayın efendiler şimdi ağlayın.

Ben halkımın dününü bilirim.

Sızlayın efendiler şimdi sızlayın.', 'Bu milleti kandırması çok kolay, Diyin efendiler şimdi diyin. Devletin malını yemesi kolay, Yiyin efendiler şimdi yiyin. Beş yüz elli maraba...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/efendiler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Başlıksız Şiirler Yazdım Hep', 'ben-basliksiz-siirler-yazdim-hep-nazli-busra-gyirv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben başlıksız şiirler yazdım hep,

Ne sonu vardı, ne de bir başı...

Ne olduğu belli değildi şiirlerimin.

Ben aşkı şiir gibi yaşadım hep,

Yaşayan sadece bendim...

Ne sonu geldi aşkımın,

Ne de başlığı bulunabildi.', 'Ben başlıksız şiirler yazdım hep, Ne sonu vardı, ne de bir başı... Ne olduğu belli değildi şiirlerimin. Ben aşkı şiir gibi yaşadım hep, Yaşa...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Büşra']::text[], 8.5, '{"poet":"Nazlı Büşra","poet_slug":"nazli-busra","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-basliksiz-siirler-yazdim-hep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül''ü Nazlı Dilber', 'gul-u-nazli-dilber-kamil-boyraz-k48lo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seher vaktinde başladımsa içmeye,

Sebebi sensin sen gül-ü nazlı dilber.

Hiç hakkın yok ki bu dünyaya küsmeye,

Sebebi sensin sen gül-ü nazlı dilber.

Ağardıysa sim siyah olan saçlarım,

Sebebi sensin sen gül-ü nazlı dilber.

Kalmadıysa dünyada yazım baharım.

Sebebi sensin sen gül-ü nazlı dilber.

Gök kubbe delinse de yağsa üstüme.

Sebebi sensin sen gül-ü nazlı dilber.

Perişan halimi şimdi düşünme,

Sebebi sensin sen gül-ü  nazlı dilber.

Aynaya bakmaya cesaretim yoksa,

Sebebi sensin sen gül-ü nazlı dilber.

Bedenim toprağı sarmak istiyorsa,

Sebebi sensin sen gül-ü nazlı dilber.

Mezar taşımda kadersiz yazıyorsa,

Sebebi sensin sen gül-ü nazlı dilber.

Toprağında çiçekleri açmıyorsa,

Sebebi sensin sen gül-ü nazlı dilber.', 'Seher vaktinde başladımsa içmeye, Sebebi sensin sen gül-ü nazlı dilber. Hiç hakkın yok ki bu dünyaya küsmeye, Sebebi sensin sen gül-ü nazlı ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gul-u-nazli-dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekler', 'bekler-kamil-boyraz-evtpr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göz bebeklerimde çeyrek parıltı,

Son ümit garın da treni bekler.

Kalbimde kıpırdar aşkın ateşi,

Ümidi kesmedi hep seni bekler.

Uzaktan duyulur kalbimin sesi,

Heyecandan kalmadı zevki neşe si 

Gece gibi gözleri in busesi,

Ufukta doğacak güneşi bekler.

Tarifsiz dertlerimin tarifi olmaz,

Bu kadar çilenin arifi olmaz,

Bilirsin bu dünya kimseye kalmaz.

Gül bahçem açacak gülünü bekler.

Ayrılalı ay değil asırlar oldu,

Göz pınarlarımın yaşı kurudu.

Deli dolu esen fırtınam duruldu.

Gönlümdeki ateş suyunu bekler.

Rötar yapıp bu tren gelemezse,

Kem talihim yüzüme gülemezse,

Taptıklarım kadir kıymet bilmezse,

O zaman bedenim ölümü bekler.', 'Göz bebeklerimde çeyrek parıltı, Son ümit garın da treni bekler. Kalbimde kıpırdar aşkın ateşi, Ümidi kesmedi hep seni bekler. Uzaktan duyul...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-kamil-boyraz-ot1cg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne güzel yaratmış Allah ım seni,

Yağmur tanesi yüzünde çili,

Kıvır,kıvır sanki balık gibi,

Geniş kalçaları incecik beli.

Gözler yosundan almış yeşili,

Altın sarısı saçının teli,

Göğüsler koparacak düğmeni,

Doksan,altmış,doksan bedeni.

O kadar dar ki eteği mini.

Gören gözler yiyecek seni,

Besbelli giyinmişsin bikini,

Günaha sokma topla kendini.

Yürürken o kadar fazla sallama,

Peşine düşer hırbo dal lama,

El alemle bu kadar oynama,

Benzersin sonra kendi anana.

Sütun gibi bacaklar sanki Eyfel,

Boyu bir sensen bir ömre bedel,

Eşi benzeri bulunmaz güzel.

Uzaklara gitme sen bana gel.', 'Ne güzel yaratmış Allah ım seni, Yağmur tanesi yüzünde çili, Kıvır,kıvır sanki balık gibi, Geniş kalçaları incecik beli. Gözler yosundan alm...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guzel-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafaya takmışsın gidersin', 'kafaya-takmissin-gidersin-kamil-boyraz-kvmmj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu halime hiç üzülmeyeceksin.

Nasıl bittiğini bilmeyeceksin.

Çağırsam peşimden gelmeyeceksin.

Kafaya takmışsın sen gideceksin.

Sarı güller seni çağrıştıracak,

Martılar sensizliğe alıştıracak.

Ömrümün son hazanı yaşanacak,

Kafaya takmışsın sen gideceksin.

Son güzün son hüzünlü türküsünü,

Dağlar örtmeden örtüsünü,

Maviş kesmeden ötüşünü,

Kafaya takmışsın sen gideceksin.

Sen ağlarken yağmurlar yağmayacak.

Sen yoksan bu beden uslanmayacak.

Dağlarda sesin yankılanmayacak.

Kafaya takmışsın sen gideceksin.', 'Bu halime hiç üzülmeyeceksin. Nasıl bittiğini bilmeyeceksin. Çağırsam peşimden gelmeyeceksin. Kafaya takmışsın sen gideceksin. Sarı güller s...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kafaya-takmissin-gidersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havalı', 'havali-kamil-boyraz-eypew', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elinde sigarası,

Kime bunun havası,

Nazlı,nazlı süzülüyor.

Kim bu kızın anası.? 

Havalısın,havalı

Yürüyüşü edalı,

Hele bir raksı var ki,

Hepisin den gaydalı,.

Gözlerini süzersin,

Beni benden edersin.

Naz yapıp ta kaçma öyle,

Sen hepsinden güzelsin.

Havalısın,havalı,

Yürüyüşü edalı,

Hele bir raksı var ki,

Hepisin den gaydalı.', 'Elinde sigarası, Kime bunun havası, Nazlı,nazlı süzülüyor. Kim bu kızın anası.?  Havalısın,havalı Yürüyüşü edalı, Hele bir raksı var ki, Hep...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/havali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İstemiştin', 'sen-i-stemistin-kamil-boyraz-t3x07', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle mahzun,mahzun bakma yüzüme.

Böyle olmasını sen istemiştin.

Aldanıp el alemin sözüne

Aşkımız burada bitti demiştin.

Şimdi çok pişmansın halinden belli.

Bende unutamam o ilk günleri.

Bir ömre bedeldi saçının teli.

Bende pişmanım gittin gideli.

Gel dönelim eski günlere desem.

Yine pencere in altına gelsem.

Yanaklarından bir buse versen.

Belki de vermezsin ben istesem.', 'Öyle mahzun,mahzun bakma yüzüme. Böyle olmasını sen istemiştin. Aldanıp el alemin sözüne Aşkımız burada bitti demiştin. Şimdi çok pişmansın ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-istemistin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaprisli Kız', 'kaprisli-kiz-kamil-boyraz-y3g52', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yükseklerden uçuyorsun,

Sen kime naz ediyorsun.

Sonunda kayıp ediyorsun,

Ben çekemem kaprisini.

Söz verince gelmiyorsun,

Sevenini bilmiyorsun,

Hep kendine ediyorsun,

Ben çekemem kaprisini.

Bana göre hava hoştur,

Başka kalpler bana boştur.

Şimdi sen peşimden koştur.

Ben çekemem kaprisini.

Demedim mi sana bunu,

Sonra çıkacak oyunu 

Bak büktün yine boynunu,

Ben çekemem kaprisini.', 'Yükseklerden uçuyorsun, Sen kime naz ediyorsun. Sonunda kayıp ediyorsun, Ben çekemem kaprisini. Söz verince gelmiyorsun, Sevenini bilmiyorsu...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaprisli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbette Ben', 'gurbette-ben-kamil-boyraz-o3tgu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akşam olur karanlıklar çökerken.

Hüzün dolar gönlümden sen geçerken.

Buram,buram kokar sıla burnuma,

Her nefeste sigaramı içerken.

Camilerde ezanını özledim,

Köyümüzde güzelini özledim.

Kayseri’de çemenini özledim.

Vatanımı toprağımı özledim.

Kavuşuruz vatan bir gün seninle,

Hasretini giderirsin benimle,

Belki torak sarar beni gelince,

Ölürsem de kolların da öleyim.

Erciyes de karını özledim.

Hisarcıkta bağlarını özledim.

Hacılarda Baharını özledim.

Vatanımı toprağımı özledim.', 'Akşam olur karanlıklar çökerken. Hüzün dolar gönlümden sen geçerken. Buram,buram kokar sıla burnuma, Her nefeste sigaramı içerken. Camilerde...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurbette-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sümbülüm', 'sumbulum-kamil-boyraz-tsvpr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine bahar gelecek,

Güller çiçeklenecek,

Kadrini kim bilecek

Bir demet gülümsün sen.

Sevdiğim sümbülümsün sen.

Yağmur olup yağayım,

Sana derman olayım,

Hep seninle kalayım.

Bir demet gülümsün sen,

Sevdiğim sümbülümsün sen.

Yaprağınla çiçeğin,

Çok güzelsin meleğim.

İste dağlar deleyim.

Bir demet gülümsün sen,

Sevdiğim sümbülümsün sen.

Arı olup bal verdin,

Derdime derman verdin,

Ömrüme ömür verdin,

Bir demet gülümsün sen,

Sevdiğim sümbülümsün sen', 'Yine bahar gelecek, Güller çiçeklenecek, Kadrini kim bilecek Bir demet gülümsün sen. Sevdiğim sümbülümsün sen. Yağmur olup yağayım, Sana der...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sumbulum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-kamil-boyraz-agopu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine bir mevsim bitirdim sensiz.

Sahil sensiz,kumsal sensiz,ben sensiz.

Bir gün şu köşeden gelsen habersiz.

Yatağım sensiz,yorganım sensiz,Ben sensiz.

Martılar ağlıyor bizden habersiz.

Deniz sensiz,güneş sensiz,ben sensiz.

Gün batar ay doğar senden habersiz.

Şehir karanlık sokakları sensiz.

O sahilde görsem seni habersiz.

Şarkı sensiz,name sensiz,ben sensiz.

Çıkıp ta gelsen benden habersiz.

Şehir sensiz,masam sensiz,ben sensiz.', 'Yine bir mevsim bitirdim sensiz. Sahil sensiz,kumsal sensiz,ben sensiz. Bir gün şu köşeden gelsen habersiz. Yatağım sensiz,yorganım sensiz,B...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk İkindi Yağmuru', 'kirk-i-kindi-yagmuru-kamil-boyraz-9hpen', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine kızıllık çöktü gök yüzüne

Yağmur düştü düşecek       

 Kırk ikindi yağmurunda

 Kaç gecemiz böyle geçecek. 

 Sen gelmezsen bu akşam üstü.

 Yağmur iliklerime işleyecek 

 Kırk ikindi yağmurunda 

 Kaç gecem seni bekleyecek.', 'Yine kızıllık çöktü gök yüzüne Yağmur düştü düşecek         Kırk ikindi yağmurunda  Kaç gecemiz böyle geçecek.   Sen gelmezsen bu akşam üstü...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kirk-ikindi-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bildin', 'sen-bildin-kamil-boyraz-ngm8x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Son baharım oldun son yaprağımda,

Bir gül olup geldin son hazanımda

On para etmezken aşk pazarında

Değerimi kıymetimi sen bildin...

Ölüm geceye öptürürken yüzünü

Kalkıp gitmek geliyor içimden.

Güneş sabaha göstermeden gözünü

Bir uyana bilsem korkunç düşümden', 'Son baharım oldun son yaprağımda, Bir gül olup geldin son hazanımda On para etmezken aşk pazarında Değerimi kıymetimi sen bildin... Ölüm gec...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-bildin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağrifeti Sevginin', 'magrifeti-sevginin-ahmet-agdere-z3x84', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mağrifeti sevginin, gönlün layıkındadır

İğnelemek değildir harici güzellikleri

Haykırdıkça yürekten titretmektir yürekleri 

Raksını sevginin, kelimelerde gizlemektir 

İşlerken izleri cani misali iliklere

Bahtiyar olmaktır her kan çıkışında

Ayrı düşerken anadan babadan birer birer

Nizama sokmaktır kendini aşkının yolunda..', 'Mağrifeti sevginin, gönlün layıkındadır İğnelemek değildir harici güzellikleri Haykırdıkça yürekten titretmektir yürekleri  Raksını sevginin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/magrifeti-sevginin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorarım kendime', 'sorarim-kendime-cevdet-erdem-3xnba', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah şu duvardaki saat...

Bakarımda yıllardır aynı şeyleri söyler durur

Ah şu yelkovan akrebi aynı eksende döndürür durur

Bıkmadan...usanmadan...

Sorarım kendime...

Şu zamanı gösteren saat gibi

Gösterdiği zamanda döner mi geri

Yine sorarım kendime...

Yıllar yılı ben döndüm durdummu eksenim etrafında

Yelkovan misali...

Ya şu ırmağa ne demeli...

Hep kıvrılır kıvrılırda...Gitmesi gereken yere varır yinede

Yolu hep eğridir..Bir sağa bir sola sapar

Lakin denize dökülmekten kurtulamaz bir türlü

İnsanda bu ırmak misali...

Ne yana dönsede ne yandan gitsede

Sonu hep aynıdır...

Önemli olanda o sonda bir başlangıç yapmaktır...', 'Ah şu duvardaki saat... Bakarımda yıllardır aynı şeyleri söyler durur Ah şu yelkovan akrebi aynı eksende döndürür durur Bıkmadan...usanmadan...', ARRAY['Türk Edebiyatı','Şiir','Cevdet Erdem']::text[], 8.5, '{"poet":"Cevdet Erdem","poet_slug":"cevdet-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sorarim-kendime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manolya'' nın doğum günü', 'manolya-nin-dogum-gunu-erdal-asik-xpm9z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün senin ve Manolya’nın doğum günü

Hani sözleşmiştik seninle, buluşacaktık

Doğum gününü kutlayacaktım 

Sana hediyeni verecektim, sende bana 

Sıkı sıkı sarılıp doya doya öpecektin beni

ama yoktun sen Manolya vardı yanımda

doğum gününü kutladım Manolya’ya sarıldım

doya doya öptü beni, ama sen yoktun

belki seni ilk defa aldatıyordum

hem de Manolya’yla, acı ama gerçek

hiç yanımdan ayrılmak istemedi

hep yanımda olmak istedi

yine mutluydum Manolyayla 

ama yoktun sen

işyerindeydim evet ve her zaman yaptığım gibi

kitap okuyordum kitabımın konusu belliydi

Manolyayı seçmiştim ama yoktun sen

ne kadar narin ne kadar eşsiz bir çiçekti o

sevgiyle sulanan mutluluğu sevgi olan

ama sen yoktun

bir şeyler içmek istedim, doldurdum 

bardağım sen, içine dolan sen 

kana kana seni içtim

ama sen yoktun

Manolya’ydı yanımdaki

seni senle sensiz yaşamak ne kötüymüş

Manolya için şiirler istedim o gece radyodan

sevgimizi anlatan şarkılar istedim bizi anlatan

ama yoktun sen

Manolya çok mutluydu ben çok mutluydum

seni sensiz Manolyayla yaşadım bugün 

sen yoktun yanımda

uykum geldi dedi Manolya

uyumak mutluluğu kollarımda

yaşamak istiyordu uyurken bile 

beni hissetmek istiyordu yanında

ama sen yoktun Manolya’ydı bunları isteyen 

sen değildin kollarımda 

başını göğsüme yaslayıp bizim rüyamızı gören

uyumam demiştim Manolya’ya

o anı mutluluğu yaşamak istiyordum sensiz Manolya’yla

gözlerimi açtığımda

senin gibi Manolya’da yoktu artık yanımda

işte bir doğum günümün sensizliği ve sen

seni seninle sensiz yaşadığım bir tutkusun

hayalin bile güzeldi...', 'Bugün senin ve Manolya’nın doğum günü Hani sözleşmiştik seninle, buluşacaktık Doğum gününü kutlayacaktım  Sana hediyeni verecektim, sende ba...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/manolya-nin-dogum-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KALABALIKLAR iÇiNDE...YAPAYALNIZ.!', 'kalabaliklar-icinde-yapayalniz-baki-son-x0hxv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sigara tutuşturmuş

Dudağına sıkıntı.

_____________Şaşırmış...

Kopuvermiş bildiklerinden.

Taşranın bu talihsiz çocuğu

Onbinler,yüzbinler arasında

_____________Kalakalmış...

Tekbaşına,bunalmış.! 

Bütün değerler kanatlanmış

_____________Ne dostluk,

_____________Ne insanlık,

_____________Ne de sevgi...

Boşalmış dolulukta.! 

Yapayalnız kalmakla

Erimiş,bitivermiş

_____________İnsanlık...

_____________Kapılarda.! 

Mavi...

Yine eski mavi

Deniz

Yine eskisi gibi

Ama...

_____________Sevgi..? 

Yıkılmışta 

_____________Dostluklar...

İnsan sevgisi

Sarıvermiş ortalığı sıkıntı.

Taşranın bu kadersiz çocuğu

_____________Şaşırmışta,

Dolulukta yapayalnız kalmakla

Bir sigara tutuşturmuş dudağına

_____________Sıkıntı...!', 'Bir sigara tutuşturmuş Dudağına sıkıntı. _____________Şaşırmış... Kopuvermiş bildiklerinden. Taşranın bu talihsiz çocuğu Onbinler,yüzbinler ...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kalabaliklar-icinde-yapayalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanetim Var', 'emanetim-var-serap-demirturk-8op7x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yılların özlemi miydi bunca çeken seni bana..

Yoksa nedeni bilinmez coşkum mu? 

Her canım deyişinde bin kere yok oluyorum. 

Sen aramadan bulduğum, 

Hazan gecelerin karanlığında karşıma çıkan ışıksın. 

Geceler neden böyle aydınlık demek anlamsız,

Sen varsın yanımda. 

3-5 nöbetinde beklerken yanında

Sevgi adına, dostluk adına, insanlık adına

Ne varsa bölüştük de 

Bir sana vedayı öğretemedim. 

Diyemedim ki gitmem gerek, 

Diyemedim ki yıldızım sönüyor. 

O kadar sevgi dolusun ki, 

Elinden oyuncağı alınmış bebek gibi 

Boynunu bükmeni istemiyorum.

Ne yapayım ben, 

Ne yapayım da sana veda edeyim? 

Nasıl diyeyim? 

Seni sana emanet ediyorum. 

Bu bir isyan, belki baş kaldırı.

Dilerim ya da umarım ki 

Hayat sadece bir göz kırpmıştır, 

Kandırmıştır beni. 

O an dünyalar benim olur. 

Varlığınla varlığıma can katan senin duaların 

Umarım yerine ulaşır

Ve ben gitmem henüz. 

Sanki vakit daha erken gibi.

Ne dersin? 

Canımsın.', 'Yılların özlemi miydi bunca çeken seni bana.. Yoksa nedeni bilinmez coşkum mu?  Her canım deyişinde bin kere yok oluyorum.  Sen aramadan bul...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/emanetim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Nasıl Ederim?', 'sensiz-nasil-ederim-serap-demirturk-thazq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizliğe mahkum ettiğin için beni, 

Sevmiyorum seni. 

Bir boşluktayım şimdi, 

Nerdesin? 

Özlemin kuduran dalgalarcasına, 

Haykırışım ulaşmıyor sana, 

Gel artık! 

Seni tanıdığım gün ne mutluydum. 

Bu gün o ben değilim. 

Gülüşünü arıyorum, 

Sesini duymuyorum, 

Gözlerini arıyorum. 

Niye böylesi sevdim seni? 

Niye bir rüzgar oldun,estin? 

Niye? 

Amacım oldun benim, 

Sensiz nasıl ederim? 

Anılar dolusu sen olmasan, 

Kurtulamam sensizlikten. 

Ama... yetmiyor ki anılar. 

Arayışın özlemi, 

Beklemenin acısı 

Yetti artık! 

Hakkımız değil mi mutluluk? 

Konuşsana bir tanem, 

Söylesene!', 'Sensizliğe mahkum ettiğin için beni,  Sevmiyorum seni.  Bir boşluktayım şimdi,  Nerdesin?  Özlemin kuduran dalgalarcasına,  Haykırışım ulaşm...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensiz-nasil-ederim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asın Gitsin!', 'asin-gitsin-serap-demirturk-w911b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanın donduramadığı tek şey sevgi.

Öyle sıcacık ki donmaz. 

Yüreğiniz sevgi ile dolmuşken

Tam, bir şahinin kanadında ise tüm yükünüz,

Silkinmek istersiniz...

Bir akgüvercin gelir konar yanınıza...

Bükmüştür boynunu...

Hüzün sarmıştır yüreğini...

Anlamak ister de anlayamaz yüreği 

Dostum dediğinin yüreğindeki kini. 

Neden diye haykırır da çığlığı,

Yırtıp geçer geceyi. Neden...neden bu acımasızlık..

Bu güvensizlik neden? 

Al ipi as dedi de umursamadı bile. 

Bak, bahar dalları açtı ağaçlarda...

Ama karardı yürek..

Bir yaprak düştü yere, 

Bir hazan yaprağı sanki...

Sararmış, incinmiş.

Ezmeyin, yazıktır... 

Bakın ne güzel renkleri var...

Kupkuru duruşuna bakma, 

Doludur yüreği...

Ağlayamaz...

-', 'Zamanın donduramadığı tek şey sevgi. Öyle sıcacık ki donmaz.  Yüreğiniz sevgi ile dolmuşken Tam, bir şahinin kanadında ise tüm yükünüz, Silk...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/asin-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlilik', 'evlilik-serap-demirturk-yekd7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'img src= '' http://www.radikal.com.tr/veriler/2004/01/26/kafes.gif''

Karışık duygular kompozisyonu... 

Bencillikle özverinin çarpışması, 

Zaman zaman kendini sümen altına koyup unuttuğun 

Bazen bir çiçeğin kokusunda sevildiğini hissettiğin, 

Bir küçücük eli tuttuğunda dertlerini unuttuğun, 

Koruma, kayırma görünce mutlu olduğun, 

Güvensizliklerde öfkene esir olduğun, 

Değişmeden bir olmak yalanını unutup 

Değiştiğin, 

Bazen kendini tanıyamadığın, 

Aşk denen olayı bir yerlere koyup 

Nerde diye düşünüp de bulamadığın, 

Bulamayınca ''sevgi'' ile idare ettiğin 

Bir bütünlük işte... 

Pamuk ipliği ile bağlı olmadıkça 

Kopmayan, 

Kopmadıkça... varlığına alıştığın, 

Yokluğunu düşünemediğin, 

Düşündüğünde işin içinden çıkamadığın bir kafes. 

Bir kafes ki... 

Kapağı açık olsa bile uçamadığın. 

Bence, 

Durum bu...

embed src=''http://mp3.mp3evi.com/Mp3EviComDogru7896/KurtlarVadisiVol1/15.wma''=''285'' height=''45'' autostart=''true'' loop=''true'' align=''absmiddle'' controller=''true''', 'img src= '' http://www.radikal.com.tr/veriler/2004/01/26/kafes.gif'' Karışık duygular kompozisyonu...  Bencillikle özverinin çarpışması,  Zama...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/evlilik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '++sevdamız', 'sevdamiz-zeki-ergin-7age9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sesime ses verse

yüzüme bir gülse 

başı dumanlı  dağlar

sevdamız

şiir olup şarkı olup

yankılansa dere boylarında

yürüyemezken düz bağlarda

elele verip

koşar olduk karlı dağlarda

sevdamızı alıp atımızın terkisine

_beyoğlu 3nisan2004', 'sesime ses verse yüzüme bir gülse  başı dumanlı  dağlar sevdamız şiir olup şarkı olup yankılansa dere boylarında yürüyemezken düz bağlarda e...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdamiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Senfoni', 'bitmeyen-senfoni-diren-dereli-qsjlz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hava keskin bir bicak gibi agir,

ay giderek yükselmekte..

cogalan tüm bulutlara inat! 

ve görkemini yitirmekte yalanci gece..

biliyorum

yalan bir sevda

bos bir hayalsin evrende

..

her nekadar bilsemde

dur gitme! 

ama birazdan,

baska gözlere sevda,

baska gönüllere hayal olacaksin

o hilekar benliginle..', 'hava keskin bir bicak gibi agir, ay giderek yükselmekte.. cogalan tüm bulutlara inat!  ve görkemini yitirmekte yalanci gece.. biliyorum yala...', ARRAY['Türk Edebiyatı','Şiir','Diren Dereli']::text[], 8.5, '{"poet":"Diren Dereli","poet_slug":"diren-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bitmeyen-senfoni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben şair değilim..', 'ben-sair-degilim-hasan-basri-kale-ctl1a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiirlerde bahar var 

Şairlerde neş''e 

Sen halâ 

hüzün savurmaktasın 

dört bir yana. 

Koşturmakta içinde 

halâ/feryadlar/dört nala 

Gönlünde/diz boyu/isyanlar

Sırtında dünyanın yükü

ezer geçer de ruhunu/ağyâr ağlar

Kaybedecek ne kaldı

yitirilecek/daha/neyin var...? 

Yuh olsun/sana/yazıklar olsun

Hissetmedin ya/baharın coşkusunu bile.

Halâ şiir yazdığını sanıyorsun

Şair olamadığını bile bile..

ağyâr:yabancı,el.', 'Şiirlerde bahar var  Şairlerde neş''e  Sen halâ  hüzün savurmaktasın  dört bir yana.  Koşturmakta içinde  halâ/feryadlar/dört nala  Gönlünde/...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-sair-degilim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşmak Lazım Ana', 'tasmak-lazim-ana-su-yaprak-nl8kl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Taşmak lazım ana, taşmak lazım! 

Yaşam şelalesine akmak lazım..

Duyguların üstündeki örtüleri,

Bir bir kaldırmak lazım.

Taşmak lazım ana, taşmak lazım! 

Bu işin çaresine bakmak lazım..

Yitik sevgiler oldu deste deste..

Belki gidip biraz kırptırmak lazım.

Aşmak lazım ana, aşmak lazım! 

Şu yüce dağları aşmak lazım..

Mutluluk denen şey orada mı,

Bir gidip bakınmak lazım.

Bakmak lazım ana, bakmak lazım! 

Herkesin içindeki güzele bakmak lazım..

''İnsan'' dediğin, Tanrı''nın eli,

Onu incitmeden sıkmak lazım..

Kaçmak lazım ana, kaçmak lazım! 

Sevgi yoksullarından kaçmak lazım..

Kendini sevmeyen kimseyi sevemez,

Bunu onlara bildirmek lazım..

Yazmak lazım ana, yazmak lazım! 

Dilinin ucunu sivriltmek lazım..

En güzel sevgi paylaşılandır,

Dostlara gidip paylaşmak lazım..

Susmak lazım Su Yaprak, susmak lazım! 

Sözlerin yorulduğunu anlamak lazım..

Sessizlik kıymetli toprak gibi,

Arada bir nadasa çekmek lazım.', 'Taşmak lazım ana, taşmak lazım!  Yaşam şelalesine akmak lazım.. Duyguların üstündeki örtüleri, Bir bir kaldırmak lazım. Taşmak lazım ana, ta...', ARRAY['Türk Edebiyatı','Şiir','Su Yaprak']::text[], 8.5, '{"poet":"Su Yaprak","poet_slug":"su-yaprak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tasmak-lazim-ana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Postacı', 'postaci-serafettin-keskinoglu-wlukv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çanta mektup dolu girerken köye

Sevinci neşeyi saçar postacı,

Halka, ''Selâmünaleyküm'' diye

Hemen çantasını açar postacı. 

Ana, baba, bacı, kardeş sevinir,

Her zaman hasretle yolu beklenir,

Halk dilinde o''na postacı denir,

Yaz demez, kış demez, koşar postacı. 

Uzaktan haberi getiren o''dur,

Her şeyi her yere götüren o''dur,

Ne bıkar, ne usanır, ne de yorulur,

Dağ demez, taş demez, aşar postacı...', 'Çanta mektup dolu girerken köye Sevinci neşeyi saçar postacı, Halka, ''Selâmünaleyküm'' diye Hemen çantasını açar postacı.  Ana, baba, bacı, k...', ARRAY['Türk Edebiyatı','Şiir','Şerafettin Keskinoğlu']::text[], 8.5, '{"poet":"Şerafettin Keskinoğlu","poet_slug":"serafettin-keskinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/postaci-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TERAPİ.Seans-1', 'terapi-seans-1-ahmet-kose-32mvz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç bu ruhla şiir yazılır mı...! 

ya..! bi okuyan olursa...

durduk yerde

bu ruhla

bu geceyle

bu yaralarınla...! 

Alma eline o kalemi...! 

kapat defterini

kalk..! birleştiğin sandalyenden

alma..! ağzına aşkı

dokunma yüreğine

yavaşça geç...! uyandırma duygularını

sakın..! hızlı soluk alma..! 

Açma hayatını

yum yüreğini...

sızmasın sevgi bağındaki şarapların

kıpırdama sen..kal yatağında

günler,aylar,güneşler,yağmurlarca.

Mahzenisin sen bu hayatının

karanlığını

rengini

dinginliğini

mayhoşluğunu

sarhoşluğunu

kekremsi tadını

ağırlığını

muhabbetliğini

asilliğini

ateşini

yıllarını bilen düşsün içeriye.

02/Nisan/04/bitez', 'Hiç bu ruhla şiir yazılır mı...!  ya..! bi okuyan olursa... durduk yerde bu ruhla bu geceyle bu yaralarınla...!  Alma eline o kalemi...!  ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Köse']::text[], 8.5, '{"poet":"Ahmet Köse","poet_slug":"ahmet-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/terapi-seans-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Dediğimiz', 'zaman-dedigimiz-melih-coskun-6imwq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman dediğimiz zembereği kırılmış eski bir duvar saati 

Şimdi nerelere saklar takvimler yarım kalan gülüşlerimizi 

Haylaz çocuklarının ellerinde kırılan tarih   

Bütün sürgün çehrelere bırakmıştır kırılganlığını

Yani saatler asla dönmeyecektir tersine 

Ve olmuş olan hiçbir şey çevrilmeyecektir geriye artık

Değiştirmeyecektir zaman ayağa kalkmış olsa da insan 

Bir kere düşmüş olduğu gerçeğini

Bilmek ve anlayabilmek 

Ve her şeye rağmen kabullenebilmek döngüyü. 

Ama ne olursa olsun 

Değiştiremez tarih güzellik adına yapılanları da

Ve bir parçasını bırakmıştır güzel insanlara 

Marifetli parmaklarıyla yontulup 

Mutlu, yalansız sabahlar yaratılsın diye yeniden 

Onların üreten 

Onların onurlu elleri üzerinde yükselsin diye gelecek

Kırıldığı yerden öpüp sarmak için 

Eksik gülüşlerimizi bulup çıkarmak için takvim karanlıklarından 

Yani tarih bize de biraz zaman vermiştir 

Yeniden insan olabilmemiz için...', 'Zaman dediğimiz zembereği kırılmış eski bir duvar saati  Şimdi nerelere saklar takvimler yarım kalan gülüşlerimizi  Haylaz çocuklarının elle...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zaman-dedigimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçgöç', 'i-cgoc-nilay-aksu-elir8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-seviyor ki yazıyor! 

susma

uzun soluklu bir ağıt olsun bu

unutulmasın ağızlarda kalan tadı

tutunsun kirpiğinde

gözlerinde yerleşik bir hüzün olsun adım

ben ki bir yankıyım artık

dehlizlerine çarpıp dağılan bir çığlık

ben şimdi unuttuğun bir dil

bulamadığın anlam

yolunu yitirmiş  sağanağım sana

-hangi sağanak bir sığınak arar? 

yalnızlığın örselenmiş rahmi 

ah o üşüyen koyak

şimdi bu kim

güpegündüz bir düş ölüsüyle sarmaşıp yatan? 

terli birer öfke oldu gözlerim

bir dağ ayazı yağmaladı sesimi

içimden bir tren kalkıp gitti 

hırçın bir uğurlayış olsun bu

sorma

eksilen kim?', '-seviyor ki yazıyor!  susma uzun soluklu bir ağıt olsun bu unutulmasın ağızlarda kalan tadı tutunsun kirpiğinde gözlerinde yerleşik bir hüzü...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/icgoc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Onurlu Kavgalar Yalnız Yaşanır', 'en-onurlu-kavgalar-yalniz-yasanir-melih-coskun-53hga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni düşünmek için 

Sana bile ihtiyacım yok artık...

Çünkü en onurlu kavgalar 

Yalnız yaşanır her zaman

Benim değil eksik kalmış bu hesap

Benim suçum değil 

Sevmek dünyayı en sevgisiz çağında

En vahşi çağında yeryüzünün

Bir ceylan olarak kalmak

Bizim suçumuz değil 

Bu erkenden alevlenen cehennem 

Duvarları delen 

Çıldırtılmış uranyum 

Hiroşima’da kül olurken bedeni 

Küçük bir kız çocuğunun 

(Ve dünyaya gelmekten başka suçu olmayan) 

On bin metrede Rock’n Roll yapan 

Kanatları kana bulanmış

O çelik yığını bizim değil 

Düşünüyorum ve utanıyorum kendimden

Tütmeyen ocakları, 

Aç ve arkasız akşamlarında

Korkunu bir yorgan gibi sermeni üzerine 

Üşümüş bedeninin, 

Düşünüyorum

Gökten binlerce kez üzerine yağan özgürlüğü 

Sevmek diyorum sonra 

Çıkarsızca 

Yüreğini söküp yerinden çıkartırcasına 

Ve kendinden başka kimseye ihtiyaç duymadan

Oluk oluk akarken çatlayan damarlarından kan

Tuz basarcasına yaralarına 

Sürgünlere gidip de dönmemecesine

Yetmez miydi insanca yaşamaya 

İnsanca ölmeye yetmez miydi biraz sevgi 

Kalın betonlar altında kalmadan 

Tatlı bir uykuya dalar gibi 

Bizim değil bu katliam 

Bu silahlar bizim değil

Birleştirmek varken 

Paramparça eden yeryüzünü 

Derin yarıklar arasında bekliyor yarınımız 

Ve sevgimizden başka 

Hiçbir şey yok 

Yarın çocuklarımıza bırakacağımız 

Bu tutsaklık bizim değil 

Çünkü en karanlık zindanda bile 

Bir parça hürriyet vardır 

Yarını düşünebilene... 

28 Mart 2003

22: 36', 'Seni düşünmek için  Sana bile ihtiyacım yok artık... Çünkü en onurlu kavgalar  Yalnız yaşanır her zaman Benim değil eksik kalmış bu hesap Be...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/en-onurlu-kavgalar-yalniz-yasanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Çocuk', 'mavi-cocuk-tolgahan-safak-etzid', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluk denen mavi çocuk

                           Hiç oynamadı

                                  Bahçemizde.....

Maviye hasret gönlüm

                           Yine turuncu kaldı

                                  Öylece.....

Ölen turuncu yaprak

                           Dirilecek elbet 

                                  Başka bir baharda...', 'Mutluluk denen mavi çocuk                            Hiç oynamadı                                   Bahçemizde..... Maviye hasret gönlüm    ...', ARRAY['Türk Edebiyatı','Şiir','Tolgahan Şafak']::text[], 8.5, '{"poet":"Tolgahan Şafak","poet_slug":"tolgahan-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mavi-cocuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakın Yakamı', 'birakin-yakami-hebil-akan-utmgv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşündüm de heyhat ne zaman yoktunuz

Zalimler adına mazlum yaktınız

Her an içimize nifak soktunuz

RİYALAR...! ! ! 

Bırakın yakamı bırakın benim

Kapılmışım renksiz silik renginize

Gerçeği görmeyip dadandım size

Gaflet uykusunda kanmışım size

RÜYALAR...! ! ! 

Bırakın yakamı bırakın benim

Doluda taşıpda boşta dolmayan

Bir sahte çiçeksin asla solmayan

Yıllardan beridir gerçek olmayan

HÜLYALAR...! ! ! 

Bırakın yakamı bırakın benim

Mevsim baharken dönmeden güze

Tövbekar yaşlarım dolmalı göze

Gaflet, nakışını vurmadan öze

OYALAR...! ! ! 

Bırakın yakamı bırakın benim

Bu sela banadır, bandır çağrı

Dinmiş yüreğimde sızlayan ağrı

Kuş olup uçmaya Allah''a doğru

YAYALAR...! ! ! 

Bırakın yakamı bırakın benim.', 'Düşündüm de heyhat ne zaman yoktunuz Zalimler adına mazlum yaktınız Her an içimize nifak soktunuz RİYALAR...! ! !  Bırakın yakamı bırakın be...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/birakin-yakami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliği Edemem...', 'sensizligi-edemem-i-brahim-ethem-bingul-in97m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benden kaçıyor musun

Gözlerin sönük,donuk

Yanağın pembe değil

Suskunsun saatlerdir

Beni yakan, kavuran

Sendeki bu hal nedir..

Benden kaçıyor musun

Elin,elimde değil

Gözün,gözümde değil

Mesafen yakın ama

Uzaklarda gibisin

Uzaksın günlerdir

Benden kaçıyor musun

Aşkım mı fazla geldi! 

Sevdiysem seni kalpten

Yoksa..yoksa

Vah,  eyvah! 

Sana mı nazar değdi

Benden kaçıyor musun

Aşkım mı göze geldi

Desem diye

Güle güle,git haydi

Bunu mu bekliyorsun..

Demem, sana git demem

Sensizliği edemem

Beni anlıyor musun

01.05.2002', 'Benden kaçıyor musun Gözlerin sönük,donuk Yanağın pembe değil Suskunsun saatlerdir Beni yakan, kavuran Sendeki bu hal nedir.. Benden kaçıyor...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensizligi-edemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardı', 'vardi-zafer-zengin-etnika-yte8g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'güzün 

gülü vardı

çocuğun adı

yarım kalanın sonu

bir cahilin yakışı

gidenin sözü

cahilin özü

merakta bırakır

adı olmayanı

3 Nisan 2004', 'güzün  gülü vardı çocuğun adı yarım kalanın sonu bir cahilin yakışı gidenin sözü cahilin özü merakta bırakır adı olmayanı 3 Nisan 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vardi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Kadın', 'bak-kadin-zafer-zengin-etnika-5stup', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak

Kadın ! 

Senin

Yalnızlığın

Kadar

Benim

Ömrüm

Vardı...

Saklamadım ! 

Ellerinden

Gel! 

Koparmayacaksan 

Sesimden...

3 Nisan 2004', 'Bak Kadın !  Senin Yalnızlığın Kadar Benim Ömrüm Vardı... Saklamadım !  Ellerinden Gel!  Koparmayacaksan  Sesimden... 3 Nisan 2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bak-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Dedikleri', 'sevda-dedikleri-hebil-akan-31s2t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açmamış bir taze, gül sanırdım hep.

Meyvadan eğilmiş, dal sanırdım hep.

Mutluluk sarhoşu hal sanırdım hep

Bir tatlı acıymış yar dedikleri.

Felek hazırlamış sinsi bir pusu

Bildim nedir artık işin doğrusu

Ateş yakıyormuş, söndürürmüş su

Meğer üşütürmüş kar dedikleri

Saçlarıma aklar düştü de gitti

Ömür yarısını aştı da gitti

Gençlik bir sevdalı yaştı da bitti

Küllenmiş bir sevda kor dedikleri', 'Açmamış bir taze, gül sanırdım hep. Meyvadan eğilmiş, dal sanırdım hep. Mutluluk sarhoşu hal sanırdım hep Bir tatlı acıymış yar dedikleri. F...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevda-dedikleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki Sen', 'bendeki-sen-tolgahan-safak-etlwu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tüm benliğimde sen var...

Damarlarımda akıp giden sen

Ben''den çıkıyor ve Ben''e geliyor.

Dışarı çıkmak istesem

Gözlerimden çıkıyorum

Gözlerine....

Tüm Ben''leri topla

SEN eder.....', 'Tüm benliğimde sen var... Damarlarımda akıp giden sen Ben''den çıkıyor ve Ben''e geliyor. Dışarı çıkmak istesem Gözlerimden çıkıyorum Gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Tolgahan Şafak']::text[], 8.5, '{"poet":"Tolgahan Şafak","poet_slug":"tolgahan-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bendeki-sen-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mey', 'mey-hebil-akan-c1sox', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bülbül hasret sultanı

Gülse vuslat dermanı

Gönlüm isyan ediyor

Dinlemiyor fermanı

Sevenler kavuşmazmış

Böyle yazılmış yazı

Peki söyle ne idi

Mecnunun çölde niyazı

Seven kavuşsun diye 

Yazılmamış her kader

Kavuşsam olurmuydum

Hasretinden derbeder

Ben susamış değilim

Boşa doldurma bade

Sarhoş etmez hiç bir mey

Leblerinden ziyade', 'Bülbül hasret sultanı Gülse vuslat dermanı Gönlüm isyan ediyor Dinlemiyor fermanı Sevenler kavuşmazmış Böyle yazılmış yazı Peki söyle ne idi...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madem ki...', 'madem-ki-seynur-i-nal-o5f2r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Madem ki,

Olmayacaksın gündüzlerimde

Sensizliğe alışsın yüreğim

Gelme hüzün rengi gecelerime...

Madem ki,

Aydınlatmayacaksın seherlerimi

Söndür bakışlarındaki kandilleri

Mecbur etme beni gözlerinin rengine...

Madem ki,

Tutunamayacak yapraklarım dallarına

İzin verme mevsiminde yeşermeme

Al git baharlarını, bırak beni zemherilerde...

Madem ki,

Savrulmayacak saçlarım rüzgârlarında

Okşamayacak yüzümü ılık meltemlerin

Deli deli esme, gönlümün derinlerinde...', 'Madem ki, Olmayacaksın gündüzlerimde Sensizliğe alışsın yüreğim Gelme hüzün rengi gecelerime... Madem ki, Aydınlatmayacaksın seherlerimi Sön...', ARRAY['Türk Edebiyatı','Şiir','Seynur İnal']::text[], 8.5, '{"poet":"Seynur İnal","poet_slug":"seynur-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/madem-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayet', 'sikayet-hebil-akan-fpggn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beklediğim bahar kışın ardında 

Hayalden de öte düşün ardında

Ömür artık kırklı yaşın ardında

Harcadın ömrümü boşa sevdiğim

Bahardan bir aşkla sana bakarken

Saçına çiçekten taçlar takarken

Kalbimi alevle,korla yakarken

Gözümü döndürdün kışa sevdiğim

Azmı yemin ettin az mı söz verdin

Terk edip giderken ne idi derdin

Ahde vefan yokmuş kalbimi kırdın

Kalbin benziyormuş taşa sevdiğim

İçimde baharın meltemi vardı

Gönlüm duman duman aşk ve efkardı

Şimdi yüreğimi bir hazan sardı

Değiştin gerçeği düşe sevdiğim', 'Beklediğim bahar kışın ardında  Hayalden de öte düşün ardında Ömür artık kırklı yaşın ardında Harcadın ömrümü boşa sevdiğim Bahardan bir aşk...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sikayet-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem', 'i-stemem-hebil-akan-eovx0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir hüznün yağmuruna gebe iken bulutlar.

Ne yağmurlar yağsın isterim, ne güneş doğsun

Sevenleri kalmayan gündüzler ve geceler

Akreple yelkovan gibi  bir  birini kovsun

Ne yağmurlar yağsın isterim, ne güneş doğsun

Gece ve gündüz yaşanıyorsa ayni anda,

Ya saatlerde anormallik var, ya zamanda

İnsan sevgisini bilmeyenler bu cihanda..

Bırak zebaniler gibi bir birini boğsun

Ne yağmurlar yağsın isterim, ne güneş doğsun

Mayan var, biliyorsun içimdeki zehirde,

Boğuldum gözyaşlarımdan oluşan nehirde

Yıllar önce seni kaybettiğim bu şehirde,

Yıldızları bir hain el, karanlığa sağsın

Ne yağmurlar yağsın isterim,ne güneş doğsun', 'Bir hüznün yağmuruna gebe iken bulutlar. Ne yağmurlar yağsın isterim, ne güneş doğsun Sevenleri kalmayan gündüzler ve geceler Akreple yelkov...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istemem-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Bitmeden', 'omur-bitmeden-hebil-akan-jdphr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hicran sardı canı bak kederdeyim

yitirdim yolumu bilmem nerdeyim

dolandım dolandım ayni yerdeyim

köşeler...yol verin ömür bitmeden

içip içip sensiz, dertten diyordum

anladım ömrümü boş yere yordum

aylarca yıllarca dost sandım durdum

şişeler...yol verin ömür bitmeden

bazan söz verip de ektiniz beni

hayalimi kırıp yıktınız beni

nafile aşklarla yaktınız beni

ayşeler.....yol verin ömür bitmeden

bu dem ki mevlaya ulaşmak demi

hazır ol kalkmadan can denen gemi

şimdi yüreğime serdim secdemi

neşeler.... yol verin ömür bitmeden', 'hicran sardı canı bak kederdeyim yitirdim yolumu bilmem nerdeyim dolandım dolandım ayni yerdeyim köşeler...yol verin ömür bitmeden içip içip...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/omur-bitmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendeki Ben...', 'sendeki-ben-i-brahim-ethem-bingul-51vi0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir köprü

Bir başında ben

Bir başında bendeki sen

Bir sesleniş

Bir avaz ben

Bir suskun bendeki sen

Bir sevda 

Bir yanık ben

Bir yangından habersiz sen

Sendeki açıklayamadığın Ben...', 'Bir köprü Bir başında ben Bir başında bendeki sen Bir sesleniş Bir avaz ben Bir suskun bendeki sen Bir sevda  Bir yanık ben Bir yangından ha...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sendeki-ben-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Torun', 'torun-umit-kilislioglu-ozger-gcr35', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgi bir ağaçtır

Büyür, meyva verirse,

Bu evlâttır.

Meselâ  bir nardır.

Sonra bu nar,

Size içinden

Çok tatlı bir

Meyva sunar.

Aldığınız en güzel ödüldür o

Ömrünüzde gördüğünüz 

En harika güldür o.

Boynunuza dolanan

İncecik, sıcacık kolları

Kanadınız olur, uçarsınız

Sayesinde,

Siz de bir çiçek olur,

Rengârenk açarsınız.

(3.4.2004)', 'Sevgi bir ağaçtır Büyür, meyva verirse, Bu evlâttır. Meselâ  bir nardır. Sonra bu nar, Size içinden Çok tatlı bir Meyva sunar. Aldığınız en ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/torun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Yazarım..!', 'adini-yazarim-nazife-abayli-8fohs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baharın serinliğinde,

Öğle sıcağında,

Kumsala inmeyi ne çok severim.

Denizin coşkusunun,

Kumların sakinliğinin tadını çıkarırım.

Renk cümbüşü ile,

Kendimden geçer,

Süzgün bakışlarla,

Uçuşan martıları,

Balıkçı teknelerini,

Yüz metre ilerideki,

Koşuşturan insanları,simitçileri seyrederim.

Dalgaların,kıyıya her çarpışında,

Çıkardığı melodik sesi dinlerken,

Sarı kumların üzerine,

Çakıl taşları ve,

Mavimsi pembe midye kabukları ile,

Kocaman kocaman harflerle,

Adını yazarım.

Onlarca,yüzlerce,binlerce....! !', 'Baharın serinliğinde, Öğle sıcağında, Kumsala inmeyi ne çok severim. Denizin coşkusunun, Kumların sakinliğinin tadını çıkarırım. Renk cümbüş...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/adini-yazarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskan!', 'kiskan-ahmet-agdere-rkacr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bekledim tüm yıl zamanın karşısında,

Bekledim de gelmedin  duygunun karşısında.

Karanlık, çiçek ve toprak sevgilim artık,

Kıskanıp ben, dur mezarımın karşısında! ...', 'Seni bekledim tüm yıl zamanın karşısında, Bekledim de gelmedin  duygunun karşısında. Karanlık, çiçek ve toprak sevgilim artık, Kıskanıp ben,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kiskan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-ahmet-agdere-mk7j3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilinmezlerden gelen bir yolcuyum kapında,

Elimde eski bir sevdadan kalma kadehim..

Gözlerim gözlediğim pencerenin camında,

Off be! Yanımda olsaydı olmayan ruhum da! ..

Güzelim bir bilsen ne kadar severdim seni,

Düşündükçe seni ne kadar çarpardı yürek...

Saf duygular, duru bir vicdan gerekti oysa,

Yaşanılan günler zalim bir gardiyan bana..

Eğer tadamazsan saf sevgiyi benden yana,

İstemem suçsuz yüreğin gezsin yana yana.

Sen manolya, ben yalnızlığa mahkum bir yolcu; 

Haramdır üstüne basıp basıp geçmek bana! ..

Bilinmezden geldim, bilinmeze gidiyorum,

Ayrılıyorum bu şehirden ve pencereden...

Ben yokken seni yalnız sana bırakıyorum,

Elveda! Sevdamdan büyük sevda dileyerek ..', 'Bilinmezlerden gelen bir yolcuyum kapında, Elimde eski bir sevdadan kalma kadehim.. Gözlerim gözlediğim pencerenin camında, Off be! Yanımda ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yolcu-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tezgahtar', 'tezgahtar-halil-i-brahim-ozdemir-o2wuc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çürümüş meyvelerle  pazarda zarar ettim

Alan da ben satan da tezgahımdan ar ettim

Topladım borç alacak verdim mal sahibine,

Hayatımı satardım, zararımdan kar ettim,', 'Çürümüş meyvelerle  pazarda zarar ettim Alan da ben satan da tezgahımdan ar ettim Topladım borç alacak verdim mal sahibine, Hayatımı satardı...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tezgahtar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülebilirsin...', 'uzulebilirsin-nergis-demet-qm2uz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanlış ata oynayıp da, 

Kaybedenler gibi, 

Üzülme! 

Kaybeden at dağil, 

Kaybeden ülken, 

İnsanların,sensin! 

Kaybedilen yarış değil! 

Lâiklik,çağdaşlık, 

Atatürkçülük... 

Eğer buysa üzüldüğün, 

Üzülebilirsin...', 'Yanlış ata oynayıp da,  Kaybedenler gibi,  Üzülme!  Kaybeden at dağil,  Kaybeden ülken,  İnsanların,sensin!  Kaybedilen yarış değil!  Lâikli...', ARRAY['Türk Edebiyatı','Şiir','Nergis Demet']::text[], 8.5, '{"poet":"Nergis Demet","poet_slug":"nergis-demet","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uzulebilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret Ettim', 'nefret-ettim-halil-kesken-elbi5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok gülerim ama hiç içten gülmem

Hep en sevdiğime hasret gittim ben

Ömrümce kaç defa dedimse bilmem

Elveda sözünden nefret ettim ben

Kimisi bir mektup, kimisi resim

Bırakıp gittiler çıkmadı sesim

Bir kez daha desem yetmez nefesim

Elveda sözünden nefret ettim ben

Ayrılmak sende de yerleşmiş huysa

Veda etmeden git niyetin buysa

Lügata koymazdım elimde olsa

Elveda sözünden nefret ettim ben', 'Çok gülerim ama hiç içten gülmem Hep en sevdiğime hasret gittim ben Ömrümce kaç defa dedimse bilmem Elveda sözünden nefret ettim ben Kimisi ...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nefret-ettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-aysun-acikalim-oh786', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutlar nerede söyle 

Gökyüzünü kaplamış kapkara bulutlar

Yok edin karanlıkları

Güneşi en tepeye çıkartın

Gökkuşakları çizin gökyüzüne 

Öylece; 

Sönmeden umutlar 

Yitirilmeden duygular 

Bitsin bu duygular 

Sessizce aydınlansın gökyüzü 

Parlasın karanlıklar....', 'Umutlar nerede söyle  Gökyüzünü kaplamış kapkara bulutlar Yok edin karanlıkları Güneşi en tepeye çıkartın Gökkuşakları çizin gökyüzüne  Öyle...', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umut-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim KaLan', 'benim-kalan-gulay-yildiz-rctej', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mana arıyorum gülüşlerin ardında

Sessizce çekilen rüzgarı sorguluyorum, nereye? 

Bir kalabalık ki sorma gitsin...

İçleri boş kafaların yankısını duyuyor kulaklarım.

İki kelime arzını beklerken dünümden,

Yarınımı kaçırdığım trenin yalnız raylarında gözyaşlarım

Üstünden geçen her bir ağır yükü omuzlayan,

Kocaman bir yürek olmuş içimdeki yumruk

Öyle bir başımı dik tutmuşum ki

İki kıvılcım sıçramış yüreğine gözlerimden

Ürkmüşsün, gitmişsin

İçinde kalanları kusmuşsun! 

Yanlızlığını paylaştığın yatağın batmış...

Benim mağrur duruşum ne sana ne başkasına sevgili

İçimde yıkılmayan kaleler bana annemden hatıra

Uğraşma boşuna...

Gözyaşlarım geçici, gülüşlerim kalıcı', 'Mana arıyorum gülüşlerin ardında Sessizce çekilen rüzgarı sorguluyorum, nereye?  Bir kalabalık ki sorma gitsin... İçleri boş kafaların yankı...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benim-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığa Sebep', 'ayriliga-sebep-yagmur-damlasi-veqok', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En deli çağımdı

Yüreğimi koyup bir tepsiye

Sana uzatışımdı

Gecelerim yazıda gündüzlerim  afişte

Ankara’da aylardan nisandı

Bulvarda parkama düşen yağmur

Rüzgarda saçlarının dalgalanışıydı

Sloganlar atıyordum gururlu ve mağrur

Hayat gidişinde ki vefasızlıktı

Ve her şey tersine aktı

Eylüle beş ay kala Mamak ta

Bir türlü anlatamadım seni savcıya

Başımı eğmediğim için

Falakada geçen geceleri sen bilmezsin

Dikenli telleri de senle aramıza 

Ben çekmedim ya

Neden hala gelmezsin…….', 'En deli çağımdı Yüreğimi koyup bir tepsiye Sana uzatışımdı Gecelerim yazıda gündüzlerim  afişte Ankara’da aylardan nisandı Bulvarda parkama ...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayriliga-sebep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Anadoluyum...', 'ben-anadoluyum-yusuf-ziya-leblebici-xpjbn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bozkırların rüzgarıyla savrulup

türkülerin yüreğinden fırladım.

Zeynep Hatun''un yemenisine desen olup

menekşeden sümbüle zıpladım.

Ben Anadoluyum; 

Davarın başında kaval çalan

elimde çubukla eşeği dama sokan

Her çığrıda otlaklara ıslık çaldıran.

Bacılarım süt sağarken ineğin altında

Ben orak sallarım tarlada.

Ben, Kara Bahattin''in oğluyum

karakıza, karakaçana meydan okuyan...

Ben Anadoluyum; Ege''de, Doğu''da

kimi zaman zeybek, 

kimi zaman halaydayım kolkola.

Davullar vururken yaylalarda

yüreğimi savururum kovanlarla.

Karadeniz''de gezerim kemençenin yayında

ezgiler dökülürken dudaklarımdan

Ben, divanece gezinirim

Anadolumun topraklarında...

Köy yerinde adettir ya,

Babam geç yazdırmış nüfusa

Ha Ali, ha Hasan,

Adım ne olursa olsun

Ben bu yaylaların çocuğuyum

Kanıma işlemişken ''ay'' ile ''yıldız''

Bu uğurda can verenlerin torunuyum...', 'Ben bozkırların rüzgarıyla savrulup türkülerin yüreğinden fırladım. Zeynep Hatun''un yemenisine desen olup menekşeden sümbüle zıpladım. Ben A...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-anadoluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstediğim Olmadı Gece Oldu', 'i-stedigim-olmadi-gece-oldu-sair-cunoba-chbb2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok erken bir saatti

Tan ağardı ağaracak...

Karanlıklar susmuştu

Bütün istediğim,

kuytularda bir kayaya tutunmuş yoğun yeşil yosuna ulaşmaktı.

Üşüyordu, yoğun yeşil yosun

Burnunu çekti, beyaza battı

''yeşilim'' dedi,

''kayam'' dedi.

Soğuktu

Ağlamadı

Burnunu çekti, kayasına sarıldı.

Bu sefer tam battı beyaza

Usulca salındı

üşüdü... ''tamam'' dedi, ''gecem'' dedi.

Korktu

Korktuğu oldu

Uyudu... gece oldu.

İstediğim olmadı.', 'Çok erken bir saatti Tan ağardı ağaracak... Karanlıklar susmuştu Bütün istediğim, kuytularda bir kayaya tutunmuş yoğun yeşil yosuna ulaşmakt...', ARRAY['Türk Edebiyatı','Şiir','Şair Cunoba']::text[], 8.5, '{"poet":"Şair Cunoba","poet_slug":"sair-cunoba","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/istedigim-olmadi-gece-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamı Görmek İçin', 'sevdami-gormek-i-cin-fatih-konuk-00fyz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEVDAMI GÖRMEK İÇİN

Sevdama giden yolları

Yorulmadan,usanmadan

Yürüdüm yürüdüm durdum

Sevdamı görmek için

Onu uzaktan görmeye bile

Ellerin diline düşmeye bile

Onun uğrunda ölmeye bile

Razıydım sevdamı görmek için

Onu bir kere görmek için için

Dostumu kırdım,dostuma küstüm

Evinden çıkıp göreceğim diye

Köşe başlarında bekledim durdum

Onu uzaktan görmeye bile

Ellerin diline düşmeye bile

Onun uğrunda ölmeye bile

Razıydım sevdamı görmek için

Yağmur çamur demeden

Yaz,kış,soğuk demeden

Yürüdüm yürüdüm durdum

Sevdamın yollarını', 'SEVDAMI GÖRMEK İÇİN Sevdama giden yolları Yorulmadan,usanmadan Yürüdüm yürüdüm durdum Sevdamı görmek için Onu uzaktan görmeye bile Ellerin d...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdami-gormek-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Ayrılık', 'zalim-ayrilik-fatih-konuk-1ggvk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ensemde nefesinin sıcaklığı ılık ılık

Bizi zamansız buldu bu zalim ayrılık

Bağlıydık birbirlerimize ilmik ilmik 

Bizi zamansız ayırdı bu zalim ayrılık

Seni isteyeceğine canımı isteseydi verirdim

Düşünmezdim bile sonra başıma gelecekleri

Neyim var neyim yok önüne sererdim 

Kapımızı zamansız çaldı bu zalim ayrılık

Söyle ayrılık yardan nasıl geçem 

Onunla doluydu gündüzüm gecem

Senin elinden ben nerelere gidem

Aramızı zamansız açtı bu zalim ayrılık', 'Ensemde nefesinin sıcaklığı ılık ılık Bizi zamansız buldu bu zalim ayrılık Bağlıydık birbirlerimize ilmik ilmik  Bizi zamansız ayırdı bu zal...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zalim-ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-fatih-konuk-eqgx2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar eser sokakta

Bir aşk acısı sızlar içimde

Sen varsın gönlümde,gözümde

Sen varsın ahh sen varsın

Özlem seviyorum seni

Özlem seviyorum seni

Özlem duyuyorum sana

Ben sana aşığım

Ben sana tutkunum

Ben sana sevdalı

Ben sana mecburum

Özlem özlem özlemim

Canım canım tek aşkım', 'Bir rüzgar eser sokakta Bir aşk acısı sızlar içimde Sen varsın gönlümde,gözümde Sen varsın ahh sen varsın Özlem seviyorum seni Özlem seviyor...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlem-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Çokta Afili', 'hani-cokta-afili-halil-manap-9di6r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şen şakrak albenili

Birazcık çatlak ürkek bir deli

Hani çokta afili

Gölgesiyle gülüşecek kadar da neşeli

Bakışları bir hançer yarası

Gözleri özgürlük ateşi

Saçları yumuşak altın renkli

Masum öpüşlü bir kız

Ona hayallerimde

Sevgiden bahçeler diktim

Ve onun ateşiyle eriyip bittim...

.............', 'Şen şakrak albenili Birazcık çatlak ürkek bir deli Hani çokta afili Gölgesiyle gülüşecek kadar da neşeli Bakışları bir hançer yarası Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Halil Manap']::text[], 8.5, '{"poet":"Halil Manap","poet_slug":"halil-manap","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hani-cokta-afili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Buluta Tutunmuştum', 'bir-buluta-tutunmustum-sair-cunoba-5tn5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baktım

Bir beyaz derya.

İlkin, 

sırnaşır okşar gibi

sonra...

hasret gibi

kavuşur gibi

dalların kollarından tutup 

çekti içine.

Çullandı üstüne, örttü.

Beyaz bir derya yükseliyordu

Koro halinde 

ıslık çalan çamlar susmuştu.

Baktım

Bağırdım 

kendime zor duyurduğum sesimle 

oyyyy dağlar.

Baktım

Şaşırdım

cevap verdi karşı yamaçlar

oyyyy dağlar.

Mevsim yaz

Biraz ayaz

Dalmışım, 

baktım

beni de sarmış o serin beyaz.

Birşeyler kayıyordu

Yamaçlar mı çamlar mı? 

Bir şeyler kayıyordu

bir şeyler kayıyordu ki,

ben o serin beyazla yükseliyordum.

Yankılarını sevdiğim yamaçlar da susmuştu.

Hareket bütün ve biteviye

Mevsim yaz

Doruklar biraz daha ayaz

Güneşi gördük

Beyazları bölüştük

Biri az büyük, öteki daha beyaz

Bir buluta tutunmuştum memleketimde ben

geçtiğimiz yaz.', 'Baktım Bir beyaz derya. İlkin,  sırnaşır okşar gibi sonra... hasret gibi kavuşur gibi dalların kollarından tutup  çekti içine. Çullandı üstü...', ARRAY['Türk Edebiyatı','Şiir','Şair Cunoba']::text[], 8.5, '{"poet":"Şair Cunoba","poet_slug":"sair-cunoba","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-buluta-tutunmustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolu Dizgin', 'dolu-dizgin-sadik-softa-spk8b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde dolu dizgin, çağlayıp akar sular; 

Tutamam mecrasında, taşarak akar sular; 

Sınır ve bent tanımaz, dağıtıp yıkar sular; 

...İçimdeki deryayı, çağlatır sevda seli.

...O deryada kayboldum, seni sevdim seveli.

Gözlerim sır saklamaz, kelimeleri açar; 

Suları damla eder, yanaklarıma saçar; 

Dilimin feryadı yok, ucundan sesler kaçar; 

...İçimdeki deryayı, çağlatır sevda seli.

...O deryada kayboldum, seni sevdim seveli.

Gecelerde yürüdüm, kulaç attım yarına; 

Duygulara yol açtım, saygıyla kararına; 

Deli bir fişek gibi, sevdanın kollarına; 

...İçimdeki deryayı, çağlatır sevda seli.

...O deryada kayboldum, seni sevdim seveli.

Sessiz sedasız geldi, gönül sesin, bağlandım; 

Piştim, yandım, kavruldum, yüreğimden dağlandım; 

Yolların sırat oldu, kalpten kalbe bağlandım; 

...İçimdeki deryayı, çağlatır sevda seli.

...O deryada kayboldum, seni sevdim seveli.

Öyle bir hale düştüm, hayallerin çağırdı; 

Dinlemedi mantığım, şiddet ile bağırdı; 

Duygularım yoğundu, dinlemedi, sağırdı; 

...İçimdeki deryayı, çağlatır sevda seli.

...O deryada kayboldum, seni sevdim seveli.

Şükür pişirdi beni, Yunusların gözünde; 

Döne döne Mevlana, ışık tuttu sözünde; 

Sevda beşer de olsa, ilahidir özünde; 

...İçimdeki deryayı, çağlatır sevda seli.

...O deryada kayboldum, seni sevdim seveli.

Çankıtı-31.03.2004', 'İçimde dolu dizgin, çağlayıp akar sular;  Tutamam mecrasında, taşarak akar sular;  Sınır ve bent tanımaz, dağıtıp yıkar sular;  ...İçimdeki ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dolu-dizgin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tadilat', 'tadilat-galip-ozdemir-09iyp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu çığlığı söküp alacağım yüreğimden

Ve dekorumu alıp gideceğim

Sen; dağsız, bulutsuz

                    Ve güneşsiz 

ve uçutmasız kalacaksın

Rüzgar? ! 

Rüzgar nefesimdi zaten.

Galip ÖZDEMİR', 'Bu çığlığı söküp alacağım yüreğimden Ve dekorumu alıp gideceğim Sen; dağsız, bulutsuz                     Ve güneşsiz  ve uçutmasız kalacaks...', ARRAY['Türk Edebiyatı','Şiir','Galip Özdemir']::text[], 8.5, '{"poet":"Galip Özdemir","poet_slug":"galip-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tadilat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilki', 'bilki-necmi-unsal-5opc0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarın  üstüne  güneş  doğmazsa,

Gündüzün  geceni  kovmazsa,

Bil  ki  bu  dünyada  yoksun  sen...

Gecen  gündüzü  soldurmazsa,

Evini  gün  ışığı  doldurmazsa,

Bil  ki  hayattan  kopuksun  sen...

Dökülüp  yıldızlar  sararmışsa,

Masmavi  gökler  kararmışsa,

Bil ki  ondan  sonra da  yoksun  sen...

Senin  varlığını  kimse  görmezse,

Cismin  hayat  sefasını  sürmezse,

Bil ki  artık  bir  ruhsun  sen...

Kutsal  ışık  seni  sarmışsa,

Bahçe  sana  son  konuşsa,

Bil ki  orda  da  hoşsun  sen...

Gayesiz  boşlukta  geçmişse  ömrün,

İyiliğin  az,  dağlar  kadarsa  cürmün,

Bil ki  bir  öbek  gubursun  sen...

İnanmamışsan  Allah’a  peygambere,

Koymamışsan  alnını  secde  için  yere,

Bil ki  güneşi  yitmiş  gurûbsun   sen... 

                 14 Ocak 2004  Çarşamba, Danimarka  s.00:35', 'Yarın  üstüne  güneş  doğmazsa, Gündüzün  geceni  kovmazsa, Bil  ki  bu  dünyada  yoksun  sen... Gecen  gündüzü  soldurmazsa, Evini  gün  ış...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bilki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlice Seviyorum Seni', 'gizlice-seviyorum-seni-oguzkan-bolukbasi-i5icd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gizlice seviyorum seni

Görmeden 

Arkan dönük

Saçların dağınık

Gözlerimi kapıyorum, kapıların ardına saklanıyorum

Barikatları yıkıyorum sularını tutan içimin nehirlerinin

Dünyadaki tüm karaları kat edip

Okyanusa dökülüyorum

Büyük sularda saklanıyor zerrelerim

Sen kıyılarımda

Benimle olduğunu bilmeden 

Ateşler yakıyorsun

Çıplak ayaklarınla üzerime basıyor

Maviliklerimde yıkanıyorsun

Limana yaklaşan gemilerde umutlarını aradığını hissediyorum

/Sana dokunup

Ben olduğumu anlatamamak

Bana dokunduğunda ben olduğumu bilmemen

Boşlukta bağırmak gibi bir şey/

Başkaldırıyor hayatımda ne varsa

Benim başımda hala kavak yelleri esiyor

İsyanlara teslim olmak yok

Sahipsiz dağılsa da duygularım

En kuytularda fırtınalar yaşanıyor

Çocukluğum

Gençliğim 

Ve yorgunluğum

Yelkenim olmuş direniyor

İşte bu manasız satırlarda 

Dalgalarla boğuşur gibiyim

Rota yok

Pusula yok

Islanmışım donuyorum

Ateş yok

Işık yok

Kayboldum

Beni gören varsa haberim olsun

/Sana dokunuyorum yine

Sen kimin yüreği sandın

Da bana bakmadın/', 'Gizlice seviyorum seni Görmeden  Arkan dönük Saçların dağınık Gözlerimi kapıyorum, kapıların ardına saklanıyorum Barikatları yıkıyorum sular...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gizlice-seviyorum-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Böylesi', 'ozlemin-boylesi-aysun-acikalim-ulik7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum 

Seni düşünmek ne kadar acı versede! ...

Ve özlüyorum

Canım acıdıkça özlüyorum seni 

Ve korkuyorum 

Korktukça can çekişiyor 

Can çekiştikçe özlüyorum...

Geceleri gözlerime yaşlar doluyor

Vücudumun her yeri çekiliyor 

Yokluk sarıyor yatağımın her yanını 

Yokluk ki 

Evin her yanını sarıyor.

Uyumaya çalışıyorum sonra 

Gözlerimi kapatıyprum 

Gözlerim acıyor...

Konuşmak, haykırmak istiyorum 

Dudaklarım can çekişiyor.

Ve seni özlüyorum 

Özledikçe korkuyor 

Korktukça can çekişiyor

Can çekiştikçe 

İnadına özlüyorum.......', 'Seni düşünüyorum  Seni düşünmek ne kadar acı versede! ... Ve özlüyorum Canım acıdıkça özlüyorum seni  Ve korkuyorum  Korktukça can çekişiyor...', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ozlemin-boylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Dedi', 'sev-dedi-aysun-acikalim-nd5oc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umudum kalmamıştı ki aşktan 

Bırakmıştım her şeyi kendi haline 

Yaşayacaktım hayatımı en baştan 

Ama

Hayat bu kez onu çıkardı önüme 

Sev dedi onu 

Ölesiye sev

Ve öyle sev ki

Bütün dünya aşkınıza şahit olsun

Ve öyle sev ki

Ömür boyu yüreği, yüreğin olsun 

Ve öyle sev ki 

Umuduna umut

Sesine ses 

Nefesine nefes olsun

Ve öyle sev ki

Canına can, hayatına yoldaş olsun...', 'Umudum kalmamıştı ki aşktan  Bırakmıştım her şeyi kendi haline  Yaşayacaktım hayatımı en baştan  Ama Hayat bu kez onu çıkardı önüme  Sev ded...', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sev-dedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umarsızca', 'umarsizca-aysun-acikalim-tulk3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık bir sokaktayım,

Kışın en soğuk günlerinden bir gün 

Yürüdüğüm kaldırımlarda 

Ayak sesleri yankılanıyor; 

Sokak kedileri bile soğuktan 

Nereye gideceğini bilemiyor.

Yürüyorum kendimden habersiz....

Düşünüyorum...

Bazen kendime gülüyorum

Bazende kendi kendime kızıyorum.

Soğunun insanın içine işlediği,

Kemiklere vurduğu anda bile 

Ben hep onu düşünüyorum,

Çünkü umarsızca 

İhmal...

Beni öylesine kızdırıyor ki; 

Ayak parmaklarımdaki kanın 

Sıcaklığını bile o olmadan hissedemiyorum....', 'Karanlık bir sokaktayım, Kışın en soğuk günlerinden bir gün  Yürüdüğüm kaldırımlarda  Ayak sesleri yankılanıyor;  Sokak kedileri bile soğukt...', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umarsizca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son İstasyon', 'son-i-stasyon-aysun-acikalim-zxoe4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O trendi kurtuluşumuzun 

Müjdecisi 

O trendi Hürriyetin sesi 

Hep güzeldi o trenin sesi

Alışmıştık güzelliklerine 

Belliydi rotası 

İstanbul''dan Ankara''ya gelirken 

Hiçte alışmadığımız,bir sesi vardı....', 'O trendi kurtuluşumuzun  Müjdecisi  O trendi Hürriyetin sesi  Hep güzeldi o trenin sesi Alışmıştık güzelliklerine  Belliydi rotası  İstanbul...', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-istasyon-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deneme tahtası', 'deneme-tahtasi-ayten-ozlem-yesilcali-0wubu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seviyorum dedin oysa hiç sevmedin.

Bin vaat verdin çekip gittin...

Hep yüzüme güldün alay ettin.

Deneme tahtası oldu bu sevgim.

Hepi ayrı ayrı yaraladın.

Dertleri ömrüme sıraladın.

Yazdın çizdin paraladın.

Sevmeyi bana karaladın.

Deneme tahtası oldu bu sevgim.

Ne senden ne aşktan gülmedi yüzüm.

Nerden esir oldum sana üzgünüm.

Kalmadı kendime diyecek sözüm.

Denem tahtası oldu bu gönlüm..

Kahır ederek sevmeye artık.

Gerçek sevenede kapıyı kapattım.

Aşkı bana sen yaşatmadın.

Deneme tahtası oldu bu sevgim..', 'Seviyorum dedin oysa hiç sevmedin. Bin vaat verdin çekip gittin... Hep yüzüme güldün alay ettin. Deneme tahtası oldu bu sevgim. Hepi ayrı ay...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/deneme-tahtasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşerim Üstüne', 'duserim-ustune-yasar-pullu-q64zs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bacalarından ömürler tüten

bir yerde yaşıyorum

seyyar satıcıların uğramadığı

Sabaha terli uyanmış sevişmelere

bıçak sallıyorum Bursa işi

Yüzümde yalancı bir sevinçle yaşıyorum

konuşuyorum

çakallar ulumaya başlıyor

kargalar tedirgin oluyor

Yalan söylüyorum

kimse bilmeyebilir

hakimler önünde nasıl suskunum

bir ömrün vurulduğu

bir insanın sağırlığı olmalı suskunluğum

Soluğumu taşırken yoruluyorum

Aşırı oksijenden

hep minik ellerden, ama hep minik

bir ömrün tarihinden korkuyorum

yazılmamış tarihten

yazılınca bitiyor zaten

Sokakların tortusunu taşıyorum

-----alırmısın sevgilim-----

öpüşmek istemiyorum

öpüştükçe kirleniyorum

(o hep illegal,,, o hep uzun bir yol) 

kaçak tütünlere savruluyorum

kimseler bilmesede 

özler dururum Mayıs umutlarını

asılı kalmış olsada tel örgülere

yasal yollarda yorulmuşum

sus sevgilim konuşma ki

kor gibi düşerim üstüne', 'Bacalarından ömürler tüten bir yerde yaşıyorum seyyar satıcıların uğramadığı Sabaha terli uyanmış sevişmelere bıçak sallıyorum Bursa işi Yüz...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/duserim-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim', 'gelirim-aysun-acikalim-41z0w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üzülme, ağlama 

Geriye dönmem diye 

Ayaklarımın altında mayın patlasa bile,

Geriye dönerim yarim.

Arkamda,

Elleri kınalı

Gözleri yaşlı

Gecesini gündüzüne katmış 

Yarim var.

Beni ne keder boğar,

Ne de acımasız kurşunlar yıkar.

Beni yıkarsa ayrılık acısı yıkar.

Bekle beni yarim,

Bir sabah koynumda çiçeklerle 

Gelirim.....', 'Üzülme, ağlama  Geriye dönmem diye  Ayaklarımın altında mayın patlasa bile, Geriye dönerim yarim. Arkamda, Elleri kınalı Gözleri yaşlı Geces...', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gelirim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost Arıyorum', 'bir-dost-ariyorum-aysun-acikalim-x8hq7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dost arıyorum,

Acılarıma ortak olacak,

Bir dost arıyorum, 

Acımda kederimde yanımda olacak.

Bir dost arıyorum,

İçimdeki hüznü mutluluğa kavuşturacak

Yıkılmış bir dünyam var 

Dünyama ayna tutacak.

Bana ümit verecek.

Bir dost arıyorum....', 'Bir dost arıyorum, Acılarıma ortak olacak, Bir dost arıyorum,  Acımda kederimde yanımda olacak. Bir dost arıyorum, İçimdeki hüznü mutluluğa ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-dost-ariyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçten', 'i-cten-aysun-acikalim-08g1c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Babam öldükten sonra 

Kardeşim hiç konuşmadı.

Soru sordular ona 

Ağladı.

Hiç mi hiç konuşmadı.

Konuşacakları hep içinde kaldı.

Bir gün; 

Ortadan kayboldu.

Günlerce gelmedi.

Bulunduğunda; 

Babamın mezarı başındaydı.

Elinde bir mektup vardı.

Seni çok seviyorum babacığım yazılıydı.

Hatıralarıyla saklı bir ebede daldı.

Gittiği yerdense bizi hiç mi hiç,

Aramadı.', 'Babam öldükten sonra  Kardeşim hiç konuşmadı. Soru sordular ona  Ağladı. Hiç mi hiç konuşmadı. Konuşacakları hep içinde kaldı. Bir gün;  Ort...', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/icten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-aysun-acikalim-va74u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir keresinde; 

Bir düş görmüştüm rüyamda,

Hayata dair.

Yaşadığım için çok mutluydum, 

Kimsesiz çocukları gördüğüm ana kadar....', 'Bir keresinde;  Bir düş görmüştüm rüyamda, Hayata dair. Yaşadığım için çok mutluydum,  Kimsesiz çocukları gördüğüm ana kadar.......', ARRAY['Türk Edebiyatı','Şiir','Aysun Açıkalım']::text[], 8.5, '{"poet":"Aysun Açıkalım","poet_slug":"aysun-acikalim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dus-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elâ Gözlüye', 'el-gozluye-osman-velioglu-8okcg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykusuz gecenin kara yüzüne 

Çizdiğim resimsin elâ gözlü yar, 

Gönül defterimin beyaz özüne 

Yazdığım isimsin elâ gözlü yar, 

Dudak ibâdeti, bakış hacısın, 

Kalbin atışına sebep, gücüsün, 

Onurla taktığım sevda tacısın, 

Solmayan süsümsün elâ gözlü yar, 

Benim bedenimde ikinci cansın, 

Gözüm bebeğinde tatlı bir bensin 

Aşkın hançerini saklayan kınsın, 

Çıkmayan sesimsin elâ gözlü yar. 

Bir umut öyküsü, bir yaman türkü 

Aks-ı sedâsına yandığım şarkı, 

Vel’oğlu’nun sana geçiyor erki 

Asırlık yasımsın elâ gözlü yar …', 'Uykusuz gecenin kara yüzüne  Çizdiğim resimsin elâ gözlü yar,  Gönül defterimin beyaz özüne  Yazdığım isimsin elâ gözlü yar,  Dudak ibâdeti,...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ela-gozluye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-tolgahan-safak-uw3at', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dört duvarla çevrili hayatımı 

Sen başlattın Hey Ankara! 

Soğuk gecelerde

Sıcaklığa hasret bıraktın...

Sigara kutularından ev yapmayı

Sende öğrendim.

Metroyu daha az kullanmak için 

Yürümeye alıştım..

Yürümenin ardından

Polislerden kaçmayı da...

Hayatın yaşamakla eşdeğer olmadığını 

Yaşanmayan gecelerinde gördüm.

Arkama bakmadan yürümeyi...

Kendimi görememeyi...

Kızılay''da bağırmayı...

Kızlarla beraber olmayı,

Kız arkadaşıma bağırmayı...

Sende gördüm

Hey Gidi Ankara! 

Yaşanmayan hayatımı sende gördüm.

Ben sende başladım sevişmelere...

Yine sende aldandım sevmelere

Ve sende aldatıldım kor gecelerle...

Hey Gidi Ankara Hey! 

Beni de benden aldın ya...

Ben sende başladım sigaraya.

Öksürmeden hayatı çeke çeke içime.....

Ankara! 

Seni sana bırakıyorum

Sevişmelerimle,

Aldanmışlığımla,

Sevmelerimle...

Seni gönderiyorum

Aklımın alamadığı en ücra köşelere....

Seni şu son mısrayla terkediyorum Ankara; 

Güle Güle..............', 'Dört duvarla çevrili hayatımı  Sen başlattın Hey Ankara!  Soğuk gecelerde Sıcaklığa hasret bıraktın... Sigara kutularından ev yapmayı Sende ...', ARRAY['Türk Edebiyatı','Şiir','Tolgahan Şafak']::text[], 8.5, '{"poet":"Tolgahan Şafak","poet_slug":"tolgahan-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ankara-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak Olur Dudaklar, Gül Göbeğinde Açarlar', 'yaprak-olur-dudaklar-gul-gobeginde-acarlar-muammer-celik-fxzwq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk akıtıyordur adeta dudakların biliyorum

kamçılıyordur bu tireyişi uzaklara kilitlenen

ufkukları delip geçen bakışların biliyorum

İşte, gözlerinde sevişmek vardı o zaman

çırılçıplak bakışlarındaki ruhunla gözlerim…

İnanılmaz  yoğun bir şehvetle sevişirsin biliyorum

dişi bir amazonun aç gözleriyle okşarsın bakarken

Baktığın yeri kül eder, alev alev yakarsın biliyorum

alev kırmızısı olur dudakların, ısırırsın. kanatırsın 

dolanır dilinle dillerim… biliyorum! 

Aşk kırmızısı gülün göbeğinde yapraklar gibi açılır

Bükülürek içten dışa doğru, yuvarlacık olur, saçılır 

Dudakların… dudaklarıma yayılır....

Sarılır kollarınla bedenlerim… BİLİYORUM...

BirDeli

03.04.2004', 'Aşk akıtıyordur adeta dudakların biliyorum kamçılıyordur bu tireyişi uzaklara kilitlenen ufkukları delip geçen bakışların biliyorum İşte, gö...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaprak-olur-dudaklar-gul-gobeginde-acarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-nuri-sedat-fum39', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hüzünlü bir şarkı gibidir yaşamak

    bazen de dağdan kopup gelen bir çığ,

    yada erik dalından yağmur sonrası yere süzülen damladır

    yaşamak

    sanırsın pamuk gibi yumuşacık 

    ve kuşun cıvıltısındadır 

    anlarsın kaktüsün dikeninde 

    ya da alev gibi yakıcıdır yaşamak

    bazen de nefessiz kalmaktır

    yaşarken boğulmaktır 

  

    uğur böceğinin papatyasının dalına konmasıdır

    yaşamak

    hissetmesidir kokusunu

    duymasıdır dokunuşunu

    sarmasıdır kollarını sevdiğine 

    acısını paylaşmasıdır

    kahkahasında var olması

    hüznünde göz yaşıdır yaşamak

    bazen de seni sana bağlayandır

    ve anlamaktır duygularını karşındakinin

    sevmektir, hissetmektir

    ağlamaktır, haykırmaktır

    acı çekmektir beklide

    yaşamak

    bazen içki kadehleri çınlarken

    akılda var olmaktır

    duymaktır şarabın tadında

    düşlerin en güzel yerinde 

    sevdiğinin yüreğinde olmaktır

    yaşamak', 'hüzünlü bir şarkı gibidir yaşamak     bazen de dağdan kopup gelen bir çığ,     yada erik dalından yağmur sonrası yere süzülen damladır     y...', ARRAY['Türk Edebiyatı','Şiir','Nuri Sedat']::text[], 8.5, '{"poet":"Nuri Sedat","poet_slug":"nuri-sedat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yasamak-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretilmedi', 'ogretilmedi-ergun-kivrakdal-5j6cr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öğretilmedi bize çizgisiz kağıtlar yazı yazmak,

Ya da diş macunun ortasından sıkmamak. 

Hep ''nohut büyüklüğü kadar'' derlerdi,

Nereden bilebilirdik ki? 

Görmemiştik çünkü o büyüklüğü bile çizgisiz kağıtlar üzerinde.

Aşk ta öğretilmedi bize,,

Bazen, tek odalı gecekondumuzdan kurtuluş sandık,

Bazen de ekmeğin yanında peynirdi aşk,

Ya da,,ya da cebimizdeki üç-beş kuruşla bakkala koşuşumuzdu....

Sonra büyüdük; 

derin denizlerde,karlı ovalarda,yüksek vadilerde aradık aşkı,,,

İçimizde delice çırpınırken o..

bir sabah bulduk sandık,,sımsıkı sarıldık,,

Avuçlarımızı açtığımızda; 

Nohut büyüklüğündeydi aşk,,,,

Ve,, kağıtlar çizilmişti....', 'Öğretilmedi bize çizgisiz kağıtlar yazı yazmak, Ya da diş macunun ortasından sıkmamak.  Hep ''nohut büyüklüğü kadar'' derlerdi, Nereden bilebi...', ARRAY['Türk Edebiyatı','Şiir','Ergün Kıvrakdal']::text[], 8.5, '{"poet":"Ergün Kıvrakdal","poet_slug":"ergun-kivrakdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogretilmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Bahar Diyorum', 'ben-sana-bahar-diyorum-kamil-aydemir-lk29j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'beni hiç yanıltmadı

                           kelepçe taşır da bileğim

                           siparış almaz yüreğim

ben sana bahar diyorum

bahardan da güzelsin biliyorum

gülüşlerin güneşin dünyayla sevişmesi

hayatın lirik sesi

beni girdapında yutan

ve her adımda beni yeniden büyüten

yürüyüşlerin yok mu

beni düş zengini eden yürüyüşlerin

yalçın dağların sarı çiçek oynaması

soğuk gecelerimin yorganı saçların

dudakların soyunuşu narın

buharlanacağı yer istanbul’u örtebilecek karın

tabularını çeper etme önüne

yüreğin dokunsun yüreğime

ben sana bahar diyorum

bayramıdır renklerin

güzellikleri giyinişi doğanın

gülüşü doğada var olanın

tıpkı senin gibi

en dişi kokuşu

ve uyanışıdır toprağın

bahar mevsimlerin balı

onsekizli yaş hali insanın

buzlar işgal etti sevinçlerimi

kuzeyime ser gülüşlerini

bana sakla en erotik düşlerini

zakkum zakkum bakışlarında kaybolmak

sevgi tarlası yürğinde çiçeğe durmak istiyorum

ben sana bahar diyorum

nerene dokunsam aşk kokuyorum

ben sana bahar diyorum

gözlerin hasretim gibi derin

sevdam gibi umman

ve en büyük okyanusu yeryüzünün

geçemem karşı yakasına

bir ömür yüzsem

harmandalı oynuyor kaşların

koynundaki iki tomurcuğun atabarı

uzat sevgi sevgi dokunan ellerini

vereyim de konuştur

içimin bir köşesinde tozlanan hitarı

ürkütmeyeceğini biliyorum

sevda şarkılarına vokalistlik edecek martıları

mutlu çocuklar doldursun patikalarımı

sevinçlerim çerçisini doksun ortaya

gözlerin yanında göl kalan hayattan

herkesin düşleri takılsın oltaya

seninle son verdi yüreğim ağlamaya

sevinçlerim kara yazma bağlamaya

ben sana bahar diyorum

biliyorum topal kalıyor bu dize seni yakalamaya

sıra gelince seni tanımlamaya 

sözcükler lâl oluyor

benim için mevsimlerin en güzelidir bahar

kadınların en güzeli sen

ben sana bahar diyorum

sen güzelden yana her şey olduğunu anla', 'beni hiç yanıltmadı                            kelepçe taşır da bileğim                            siparış almaz yüreğim ben sana bahar diyo...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/ben-sana-bahar-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşı Şiir', 'karsi-siir-mustafa-kaya-vvhle', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Balıkadamın Rivayeti)

mitolojik denizlerin sürgün kızları 

hay  ho! 

dudaklar kırmızı saçlar sapsarı

abazan ruhlu denizcilerin

kadınsızlığa yaşatıp durdukları

denizkızının tuzlu hikayesi...

fırtınaların çözdüğü

gemilerle beraber

kaybolmuş denizciler

denizin dibindeki şehirlerde

denizoğlanlarına  esirdirler

yüzyıllardır yunusların dilindeki şiir

onların esaretiyle ilgilidir

(Açılım dergisi -1998 Ç.Ü. yayınları)', '(Balıkadamın Rivayeti) mitolojik denizlerin sürgün kızları  hay  ho!  dudaklar kırmızı saçlar sapsarı abazan ruhlu denizcilerin kadınsızlığa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaya']::text[], 8.5, '{"poet":"Mustafa Kaya","poet_slug":"mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karsi-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acın Acısıydı Halkın', 'acin-acisiydi-halkin-kamil-aydemir-wb4pi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kaç kez ölüm selam verdi almadım

pimi çekik günlerde

eğilmeden ilerledim

adım

adım

gözlerini güneşte yakaladım

yıldızlar düşlerin

kırık zeytin dalıydı gülüşlerin

yurdumun üzerinde uçan 

güvercindi zaten yüreğin

kaç kez munzur’a vardım

kaç kez kaçkarlarda aradım

beşparmak dağlarında

toroslarda

varoşlarda dolandım

bildiğim madden ocaklarına daldım

acını dicle’den fırat’tan

seyhan’dan çoruh’dan kızılırmak’dan

acını akdeniz’den karadeniz’den

eğe’den marmara’dan topladım

acın acısıydı halkın

en sonunda seni

dilleriyle susan

yürekleriyle konuşan

mutluluğun dalından hep düşen

ve bu teknoloji çağında perişan

insanların yüreklerinde buldum

senin gibi

ak alınlı yiğidi yetiştirdiğinden

gururluydu yurdum

kalmamıştı kaybedecek çok şeyimiz

bize kalan canımız

yarımağız yaşamımız

ve yerden kalkmayan başımız

gün durma günü değildi

ne de kurtarıcı arama

onların mutluluk masaları

yine kuruktu harama

ama

şimdi tükenen insan

güzel olan ne kalırki geriye

insanda tükendiği zaman

tanığımsın yurdum

yürüdüm

tutunup insanlık onurumdan

aramızda olsan

insanca yaşanası günlere

sende yürümemizi isterdin güzel insan

öğrendim ki hayat denen öğretmenden

sen aslında birer bizdin

bizler sen

kendinin kurtarıcısı olmalı her insan

vererek elele

yürümeli o güzel günlere

daha fazla acılara savrulmadan

çarpacağı kadar çarptı toprağı kan', 'kaç kez ölüm selam verdi almadım pimi çekik günlerde eğilmeden ilerledim adım adım gözlerini güneşte yakaladım yıldızlar düşlerin kırık zeyt...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/acin-acisiydi-halkin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik Hesaplaşmalar..Dönüyorum', 'lirik-hesaplasmalar-donuyorum-pelin-onay-n0rpy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şarkılar kadar sevdiysen, bu deniz kucaklar seni (assos’lu bir balıkçı)

dönüyorum sardunya zamanlarıma 

ilkyaz çiçekleri kokularını salsın 

belki unutulmuştur adım, 

tozlu çekmecelerde saklanan sevda mektuplarında 

ya da yürek dağlayan bir şarkının dalga kıran ritminde 

olsun...yine de dönüyorum, 

kadınlığımın ağrıyan uyluklarında barınan düş tomurcuklarına 

aldandığım mavileri geri alsın Ege 

dualarla yıkadım ruhumu 

ve arındım soytarı vedalardan....dönüyorum 

bir aşk mevsiminde öldürülmüştüm 

geri dönmedi katilim cinayet yerine 

çıplaklığımın göz yaşlarını ellerimle sildim 

temiz çıktı acılarımın otopsisi 

sonuç:....kâfidir bu sümüklü serzenişler 

rahminden doğuyorum yıkıntılarımın....dönüyorum 

bağışladım anılarımı soğuk bir otel odasında 

balıkçı teknelerinin ninnisinde ağıt yaktım 

otuz beşlik bir hüzün getirdi garson 

yudum yudum içtim....şarkılarımı ıslattım 

Assos! ....felsefenin ve aşk’ın mistik kenti 

akıtamadım tapınaklarından sevda dileklerimi 

sen de bağışla ve kutsa ayrılıklarımı 

bak işte sana geldim ve artık susuyorum 

denizinde sakladığın liman şehrinden çıkart gülüşlerimi 

bahara yetişmem lazım....dönüyorum 

geç oldu ama anladım....kimse giderken götürmüyor sevgileri yanında 

yanılgılarımı yüzüme vurmayın, 

içimdeki çocuğun masal saatine denk geldi aşk 

anladım dedim ya....daha fazla yormayın 

şarkılar kadar sevmiştim....ama bitti 

ciddiyetini yitiren vaatler utansın, 

ben utanmıyorum öznesi tutku olan sevişmelerimden 

yürüyüp geçtiğim yollar bir zahmet karşılasın beni 

vedalar vesikamdır artık....dönüyorum', 'şarkılar kadar sevdiysen, bu deniz kucaklar seni (assos’lu bir balıkçı) dönüyorum sardunya zamanlarıma  ilkyaz çiçekleri kokularını salsın  ...', ARRAY['Türk Edebiyatı','Şiir','Pelin Onay']::text[], 8.5, '{"poet":"Pelin Onay","poet_slug":"pelin-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/lirik-hesaplasmalar-donuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın ve Saklambaç', 'yangin-ve-saklambac-esra-guzelipek-shzae', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şubat gecesine saklanıp 

Aralık kapısında kalan adama: 

Ona kadar sayacağım 

Önüm arkam 

Sağım solum AŞK

Saklanmayan ”sobe! ” 

I 

Dualı köy yollarından 

Meleklerin sofralarına uzanan 

Hem herkes hem hiç kimse olduğun 

Efsunlanmış bir rüyanın 

Cennetten indirildiği 

Yolculuktur aşk. 

Aşk gelir 

Yangın başlar... 

(Yangın ısıtır, yangın acıtmaz.) 

II 

Yanına bir adam gelir 

Ve 

Gelincikler artık 

Son yazda da açmaya karar verir. 

Söyleme aşkı sus! 

Sus gözünü seveyim 

Aşk kocaman bir gizdir. 

Haramlar helal 

Helaller haram 

Hem de kızböceklerinin 

Kanadından saydam! 

(Yüreğin kamaşır 

Yangın minnacık bir sızı bırakır.) 

III 

Onun öpüşlerinde seversin 

Kaç yıllık dudağını... 

Onun kollarında fark edersin 

Yıldızların 

Akşam olmadan da çıktığını... 

Yangında ne de güzelsin! 

(Yangın azıcık acıtır.) 

IV 

Lavanta mavisi sabahların 

Kendine nazar değdiren güzelliği... 

Yaşamayan anlayamaz 

Kaç kez sevişirsin 

Zaman seni yakalayamaz 

Ve özlem 

Sevişirken de ayrılmaz. 

İçinde bir yerler 

Durmadan bağırır... 

(Yangın adamakıllı acıtır.) 

V 

Bir sabah 

Bildiğin bütün kelimeler 

Birbirine şaşkın şaşkın bakındığında 

Yangın gözlerine yürür. 

Gözündeki yaş 

Artık en güzel süsündür. 

Her sevişme 

Özlemle başlayıp 

Özlemle biten özündür. 

Bir tek sen bilirsin ki 

Tanrı seni seyretmektedir. 

Göreceği veya görmeyeceği 

Yiğitliğindir... 

(Yangın gittikçe şiddetlenir.) 

VI 

Aslında hiç başlamamış ve bitmeyecek 

O deli tango sürerken 

Bütün kucaklaşmaların yüzü düşer. 

İkiz inciler 

“Mecburen” ayrılır... 

Adam ve kadın gider. 

Deniz bu işe söylenir 

Nefrete yetiş denir 

Unutmak bir ihtimaldir... 

Sonradan öğrenilir 

Bazen bir yüreği terk etmek 

O yüreğe yerleşmektir... 

(Yangın? Rüzgara kuvvet!) 

VII 

Bol gözyaşı 

Az hayat... 

Tek bir tane keşke''li cümle 

Kuramazsın 

Şarkınız çalar ve 

Sen yine 

Kıyamazsın... 

(Yiğit olmak ha? ? ? 

Tutuştun sen artık.) 

VIII 

Zor zamanlardasın şimdi... 

Öğrenirsin 

Patlamış bir volkanın 

Kaynayan lavlarında yüzmeyi 

Ve asla yüzünü ekşitmemeyi... 

Elsiz dudaksız sevişmeler başlar 

Hasrettir adı... 

Öğrenirsin 

Acıyı 

Gözlerinle yüreğine üleştirmeyi... 

(İçin dışın yangın.) 

IX 

Hayat ömürde aşk temelli 

Neler neler anlarsın... 

Ne varsa hayatın getirdiği kirli 

Aşka basarsın... 

(Sen yangınsın.) 

X 

Onnn... 

Kara adam işte ordasın! 

Sözüm var yaralarıma 

Titremeyeceğim... 

Ben oyunu bıraktım 

Sobelemeyeceğim..', 'Bir şubat gecesine saklanıp  Aralık kapısında kalan adama:  Ona kadar sayacağım  Önüm arkam  Sağım solum AŞK Saklanmayan ”sobe! ”  I  Dualı ...', ARRAY['Türk Edebiyatı','Şiir','Esra Güzelipek']::text[], 8.5, '{"poet":"Esra Güzelipek","poet_slug":"esra-guzelipek","theme":"Türk Şiiri","is_hero":false,"total_lines":113,"source_url":"https://www.antoloji.com/yangin-ve-saklambac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vây Gönül', 'v-y-gonul-mustafa-tanrikulu-onq4d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'vây gönül eyvây gönül vây gönül vây vây gönül 

mahkemede kendini aşk mahkumu say gönül

düşersen eğer bir gün mahkeme-yi kübraya

mahkemeye derdini korkma bir bir say  gönül

dilerlerse illa ki yakmak ateşte seni

''yâ nârî kûnî berden...''  ayetini yay gönül

vây gönül eyvây gönül eyvây gönül vây gönül', 'vây gönül eyvây gönül vây gönül vây vây gönül  mahkemede kendini aşk mahkumu say gönül düşersen eğer bir gün mahkeme-yi kübraya mahkemeye de...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/vay-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mersiye-i Şeyh Ahmed Yasin', 'mersiye-i-seyh-ahmed-yasin-mustafa-tanrikulu-knyxv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'E yvah ki yine türâb-ı Filistin kan oldu

bir füzeyle çekilen bir bedenden cân oldu.

cennet dedikleri yer Yasin''e mekân oldu

yüz bin yıldır ki her şey  yer ile yeksan oldu

Yerlerde sürünmeyen İman ve Kur''an oldu

...

L evh-i mahfuzda sana yazılmış ki şehadet...

emr-i ilahidir '' Allah yolunda cihad et''

ey şehit görülmüş mü kimsede bu salâbet

işte Cafer  misali tayyar oldun nihayet

Ahiret denen yolda yarenin iman oldu

...

Vallahi billahi de şehadetine yanmam......

nitekim bilirim ki muradın oldu tamam

alçakça öldürüldün işte ona dayanmam

yoksa hüznün kahrın adını bile anmam

Selametle şehitler yollara revan oldu.

...

Elveda kutlu şehit cennet bekliyor seni

kondur yed-i beyzâya o nurani bûseni

sen öperken elini o da koklasın seni

versinler mülk-i cennetten o vakit hisseni

İkram u kerem yine kât-ı Sultan''dan oldu

...

Dünyadan bir kanatsız  güvercin uçtu gitti

deryâda bir yelkenli yelkenin açtı gitti

giderken etrafına beyazlık saçtı gitti

kutlu bir dava için başından geçti, gitti

Ni''met-i şehadet tattı; ehl-i şükran oldu

...

Ah edemez Mustafa şehit olmuşsun diye

zira kavuştun işte mübarek sevgiliye

bundan sonra mahal yok nalişe, iniltiye

rah-ı hakda ölmekle verilen bu hediye

İman hakikatine hakiki  bürhan oldu', 'E yvah ki yine türâb-ı Filistin kan oldu bir füzeyle çekilen bir bedenden cân oldu. cennet dedikleri yer Yasin''e mekân oldu yüz bin yıldır k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/mersiye-i-seyh-ahmed-yasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Çeşni*', 'cesni-gulsen-senderin-dgfue', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün bir yabancıydın bana tanımadığım

Bugün tatlı bir özlemsin aşamadığım

Yak kahverengi gözlere ateşlerini

Yeşillerde  olmasın hiç yaşamadığım! 

     Sevdin beni sevdim seni özlemin niye

      Yazık olur bu sevgiye bakma çeşniye...

Işıdı sabahlar sevgini süslemekten

Kurudu dudaklar neyini üflemekten

Kat yaşanmamış düşlere sevgilerini

Güneş Gülleri açsın vazgeç sislemekten! 

Yoruldu akşamlar yolunu beklemekten

Çöktü dert sepetim hasretin yüklemekten

Gel bak bekletme ne beni ne akşamları

Eriyor sevgi potam ateş yüklemekten! 

Mavi sulara kattın da al kırmızıyı

Eflatuna lilaya arattın maziyi

Çal firçanı tuvaline renkler raksetsin

Silme kitaba bassınlar kutsal yazıyı! 

Sanma ki vazgeçer gönül seni sevmekten

Usanmaz, acın tatlanır hasret çekmekten

Sal da aşk yelkenini sevgim ummanına

Sevginsiz yaşanmışlıklar beter ölmekten! 

   Sevdim seni sevdin beni hasretin niye

   Yazık olur aşkımıza bakma çeşniye...', 'Dün bir yabancıydın bana tanımadığım Bugün tatlı bir özlemsin aşamadığım Yak kahverengi gözlere ateşlerini Yeşillerde  olmasın hiç yaşamadığ...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cesni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SAYILI SANiYELER', 'sayili-saniyeler-baki-son-xbnal', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir perde kapanır akşamları,

Akşamları...

_________Bir soğuk rüzgar eser.

Gölgeler,

_________Gölgeler aydınlığı

Kısık bir ses gibi lambalardan,

_________Son ışıklar düşer.

Sonra unutulur...

Sonra kirlenir...

_________Ve

Eskimiş duvarlarda

_________Silinir gider.

Bir perde kapanır akşamları

Akşamları,

_________Hayalet bir evren doğar.

Gölgeler,

_________Yığılır omuzlara

Yorgun bir gün ağırlığıyla

_________Son uyku çöker.

Sonra unutulur,silinir...

_________Ve 

Yaşamın kargaşasında,

_________Kaybolur gider...

Bir perde açılır akşamları

Akşamları,

_________Rastgele biri,dolaşır.

Kısık bir ses gibi,

_________Lambalardan

Son bir çığlık düşer...

_________''''Yeniden Başlasak...'''' diyen

Nemli bir çift göz,

_________Parlar...

_________Söner...!', 'Bir perde kapanır akşamları, Akşamları... _________Bir soğuk rüzgar eser. Gölgeler, _________Gölgeler aydınlığı Kısık bir ses gibi lambalard...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sayili-saniyeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz ve dünya', 'biz-ve-dunya-mustafa-tanrikulu-8uegi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne ben varım alemde ne sen varsın dünyâda 

yalnız bir  keder içinde çırpınan biz varız...

mazisi geçmiş,atisi karanlık bir rüyâda

birlik meyinden içtik; şimdi vahdet-süvarız', 'ne ben varım alemde ne sen varsın dünyâda  yalnız bir  keder içinde çırpınan biz varız... mazisi geçmiş,atisi karanlık bir rüyâda birlik mey...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/biz-ve-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Çığlık', 'adi-ciglik-goktu-kara-moxom', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'haykırmak istiyorum 

ağlamak,hiç susmamak istiyorum

ama ezilmeden,ezdirmeden

eğilmeden

ah sessizlik! 

karanlıkların adı çığlık

karanlığa çarpmak nedir bilir misiniz? 

deniz,becerikli ve kuyudaki genç

anmak gerek sizleri

haykırmak istiyorum adınızı

ne yazık ki adı çığlık', 'haykırmak istiyorum  ağlamak,hiç susmamak istiyorum ama ezilmeden,ezdirmeden eğilmeden ah sessizlik!  karanlıkların adı çığlık karanlığa çar...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adi-ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Gibi Kadın', 'siir-gibi-kadin-suskun-resital-cx4t1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baktığım, en mavi denizdi gözlerin,

Özleminle yana yana,

En derinlerine gömüldü, gemilerim.

Duyduğum, en serin rüzgardı nefesin,

Estikçe estin, savurdun küllerimi,

Aklımı başımdan aldı, kavak yellerin.

Kokladığım, en nadide çiçekti tenin,

Soluk soluğa savrulduk, durulduk,

Kenetlendi ellerime, zarif ellerin.

Uyuduğum, en sükutlu uykuydu dizlerin,

Rüyalar aleminden gelen,

Hayalinle açıldı, aşksız gözlerim.

Aldığım, en anlamlı armağandı gülüşlerin,

Öyle güzeldin ki, içimi eritirdin

Edalı bir ceylana benzerdi, salınarak yürüyüşlerin...

İçtiğim, en tuzlu yağmurdu gözyaşların,

Islandıkça yüzün; anlardın,

Yaramı dağlardı, dökülen damlaların.

Tattığım, en eşsiz meydi dudakların,

Titreyip dururken karşımda; ansızın! 

Saçlarına geçti tüm parmaklarım...

Beni benden alan, en güzel resimdi çıplaklığın,

Çağlaya çağlaya aktık, kenetlendik,

Denizlerine karıştı, ırmaklarım.

Boynumu büken, en acı vedaydı ayrılıkların,

Beklemekten usandım, yokluğundan bıktım,

Mısralara ulaştı, sessiz kalan çığlıklarım..

Yaşadığım en ölümsüz aşktın, 

Öyle kazındın ki kalbime,

Sen gittin, beynimde çakılı kaldı adın! 

Eyy! zarafeti gülüşünde saklı,

şiir gibi kadın....', 'Baktığım, en mavi denizdi gözlerin, Özleminle yana yana, En derinlerine gömüldü, gemilerim. Duyduğum, en serin rüzgardı nefesin, Estikçe est...', ARRAY['Türk Edebiyatı','Şiir','Suskun Resital']::text[], 8.5, '{"poet":"Suskun Resital","poet_slug":"suskun-resital","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/siir-gibi-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eridin', 'eridin-yakup-salihoglu-pmk36', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kar tanesiydin avuçlarımda

Eridin kalbimin sıcaklığında

Karışır gibi toza toprağa

Kayboldun denize akmadan dere yataklarında

Neydi bende arayıp bulamadığın

Neydi avutmayan seni yüreğinde

Neydi bana çok isteyipte soramadığın

Neydi dilediğin Rabbime dileklerinde

Git sevgili benden uzağa

Ne önemi var yaşam sevicinin

Düşmüşsün bilmeden yakın tuzağa

En sonunda bende incidim

Ne bekliyor seni hayta bilmek istedim

Kırılmıştı kanadın kolun

Göz yaşını silmek istedim

Bitmiş adım atamıyorum sana gelen yolun

Şimdi bir mendil uzatmak isterdim 

Kalmadı bir sevgin benim yüreğimde

Ben ıssız virane bir kalp dilemdim

Asla sevgilim senin yüreğinde

Hep sen başkaları için mi yaşayacaksın

Ben baş kaldırıyorum bu masum kadere

Dileğin bumu tek başına yaşlanacaksın

Düşmüşsün sen yalnızlık derdine

Ne kazandın gül yüzlüm yalnızlıktan

Seni yalnız bırakanlara yokmuydu sözün

Çok mu hoşlanıyorsun ayrılıktan

Kalmadı mı yüreğinde bir parça kordan közün 

Artık neye yarar sevgili gerilere dönmek

İstediğin buydu

Beni de birisi sevdi deyip övünmek

Benim kalbim sana sevgi doluydu

Akamadın sevgilim engin denizlere

Akarken kayboldun dere yataklarında

Ayrılık mı düşmeliydi bizlere

Hüzün mü olmalıydı güzel yanaklarında

Bitir sevgili yalnız kendini bitir

Yitir yalnızlık ta ilahi aşkları

Söyle kelebek Rabbimden dileğin nedir

Söylemek mi yoksa bir hayat yalnızlık şarkıları

Dileğin buysa verir sana yaratan

Sana sevgi dolu yüreğimi kanatan

Bir gidiş bir gelişlerindi

İstediğin buydu olacak bir gün bir an', 'Bir kar tanesiydin avuçlarımda Eridin kalbimin sıcaklığında Karışır gibi toza toprağa Kayboldun denize akmadan dere yataklarında Neydi bende...', ARRAY['Türk Edebiyatı','Şiir','Yakup Salihoğlu']::text[], 8.5, '{"poet":"Yakup Salihoğlu","poet_slug":"yakup-salihoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/eridin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil-Figar', 'dil-figar-ahmet-capa-id8su', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Asude Ömrüm Gül-i Ruhsar''a Kandı.

Abı-Bade Reng İle Ağladım Durdum.

Karha-i Akile Açtıda Kalbimde,

Bir Sözü İle Ben Dil-Harab a Döndüm.

---------------------------

Gül-i Ruhsar = Gül Yanaklı

Ab-ı Bade Reng = Kanlı gözyaşı

Karha-i Akile = Büyüyen Yara

Dil-Figar = Gönlü Yaralı

Dil-Harab = Gönlü Harap

(Mart 2004 İst.)', 'Asude Ömrüm Gül-i Ruhsar''a Kandı. Abı-Bade Reng İle Ağladım Durdum. Karha-i Akile Açtıda Kalbimde, Bir Sözü İle Ben Dil-Harab a Döndüm. ----...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çapa']::text[], 8.5, '{"poet":"Ahmet Çapa","poet_slug":"ahmet-capa","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dil-figar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al,mor,sarı', 'al-mor-sari-atalay-isik-li1qs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Al,mor,sarı

Gönlüm birgün al

Gönlüm birgün mor

Gönlüm birgün sarı...', 'Al,mor,sarı Gönlüm birgün al Gönlüm birgün mor Gönlüm birgün sarı......', ARRAY['Türk Edebiyatı','Şiir','Atalay Işık']::text[], 8.5, '{"poet":"Atalay Işık","poet_slug":"atalay-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/al-mor-sari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Anla', 'artik-anla-i-brahim-ethem-bingul-swacz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hoşçakal

Eğer istersen esenle de kal

Ama bensiz kal

Bensiz kal da anla

Aslında her nefesi beraber aldığımızı

Güneşin,ayın,gündüzün

Gecenin,yakamozların

Aşkımın birer yansıması olduğunu

Her bahar bakınca seni gördüğüm

Koklayınca seni çektiğim

Beyaz frezyanın coşkusunun

Aslında aşkımın neşesi olduğunu

Aşk içinde yaşarken anlatılamaz ya

Ve anlaşılamaz

Bensiz kal da anla

Benim aşkımın denizinde yaşamış olduğunu', 'Hoşçakal Eğer istersen esenle de kal Ama bensiz kal Bensiz kal da anla Aslında her nefesi beraber aldığımızı Güneşin,ayın,gündüzün Gecenin,y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/artik-anla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceylanıdır O', 'ceylanidir-o-sabit-i-nce-t2mm0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Mustafa Ceylan''a- 

Ne zaman çalışır, nerede yazar, 

Edebiyatımın yorulmaz Ceylanıdır O. 

Ne usanma bilir, ne işten bezer, 

oklarla vurulmaz Ceylandır O. 

Vefa ve dostlukta bulunmaz eşi, 

Akdenizimizin sönmez güneşi, 

şair ve ozanın yılmaz kardeşi, 

Dostların darılmaz Ceylanıdır O. 

Eserleri sıra sıra dizili, 

aşk ve sevda yüreğinde kazılı, 

Yunus olmuş o ezili, ezili 

sonsuzdur, varılmaz Ceylandır O. 

Ankara Elmadağ mekanı, yurdu, 

aşkla, aşıkla bitmiyor derdi, 

varını, yoğunu dostlara verdi, 

İNCE''nin kırılmaz Ceylanıdır O. 

Sabit İnce Kayseri 03.04.2004

NOT:Türkü olarak bestelenmiştir', '-Mustafa Ceylan''a-  Ne zaman çalışır, nerede yazar,  Edebiyatımın yorulmaz Ceylanıdır O.  Ne usanma bilir, ne işten bezer,  oklarla vurulmaz...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ceylanidir-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '! lham Duası...', 'lham-duasi-hurrem-yalcin-91s52', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ilham

için

yüreğimi

açtım 

sana....

Ulu Tanrım

İlham Perimi

gönder

bana....

01.04.2004

ŞiirDostu Kardeşim ve Ustam Hakkı Hakan Kaya''ya armağandır.....', 'ilham için yüreğimi açtım  sana.... Ulu Tanrım İlham Perimi gönder bana.... 01.04.2004 ŞiirDostu Kardeşim ve Ustam Hakkı Hakan Kaya''ya armağ...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/lham-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Yakınlarda Bir Yerdeydi Sevgi', 'cok-yakinlarda-bir-yerdeydi-sevgi-melih-coskun-9b0l9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok yakınlarında bir yerdeydi

Sevgi,

Ve sen farkında değildin bunun 

Uzak dağların ardında aradığın 

O kayıp ülke 

Kurulmamıştı oysa hiçbir zaman 

Bulutların arkasındaki gökyüzü

Mavi değildi sandığın kadar 

Ve binlerce milyonlarca kez tekrarladığımız sözcükler 

Unutmak içindi herkesi ve her şeyi

Kendimize bile anlatamadık

Kurumuş derelerde aradık suları

Yanı başımızda gürül gürül akarken hayat

(“Çünkü yanmalıydı birileri 

Çıksın için karanlıktan aydınlığa”) 

Ama uğruna yandıkların

Kurumuş bir dal gibi,

Uğruna soldukların, 

Yanlış mevsimlerde açmış bir bahar çiçeği gibi, 

Bugün nefret dolu yüzlerle bakıyorlarsa yüzüne

Yılmamalısın 

Çünkü bu sınanmasıdır yüreğinin, 

Şefkatin zulümle

Sevginin sevgisizlikle

Umudun çaresizlikle sınanmasıdır.

Sevdan kalkan olmuştur artık göğsünde 

Hasretinden eriyecek kadar uzak 

Ve gözlerinin içine bakacak kadar yakındadır

Ve sen farkında değilsindir bunun, 

Binlerce, milyonlarca kez tekrarladık aynı sözleri

Unutmak için herkesi ve her şeyi 

Unutamadık

Farkına varamadık

Oysa sevgi çok yakınlarda  bir yerdeydi hala...

16 Mart 2003

17: 58', 'Çok yakınlarında bir yerdeydi Sevgi, Ve sen farkında değildin bunun  Uzak dağların ardında aradığın  O kayıp ülke  Kurulmamıştı oysa hiçbir ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/cok-yakinlarda-bir-yerdeydi-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Günleri', 'gurbet-gunleri-asili-eros-u9354', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlatılmaz yalnızlıklar

Nedensiz hasretler ve hüzünler

Kadınsa hep mutlu bakardı

Bense gurbete çıktım

Ona ne kadar uzaktan baksam

Korkuya bir hasret salar

Kadınsa ağlar rimelleri akardı

Issız bir köy yolundayım şimdi

Kadınsa bildik hayatına devam eder

Umrunda olmayan herşey aslında umrunda

Ama belli etmez gururludur

Ben bir köy türküsü tutturdum

Sen yıllarına tutkun olduğum kadın

Geçen onca zamana rağmen ağzımda hala tadın

Bir korulukta sigara gibi resmen tadın

Biz sadece sigaramızı içerdik

Bindiğim gurbet treni

Kim bilebilirdi posta treni olacak

Sana yazılmış yüzlerce cevapsız mektubum var

Kadın ağlamaklı ama duyarsız.', 'Anlatılmaz yalnızlıklar Nedensiz hasretler ve hüzünler Kadınsa hep mutlu bakardı Bense gurbete çıktım Ona ne kadar uzaktan baksam Korkuya bi...', ARRAY['Türk Edebiyatı','Şiir','Asılı Eros']::text[], 8.5, '{"poet":"Asılı Eros","poet_slug":"asili-eros","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gurbet-gunleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karar Verdim', 'karar-verdim-nazli-busra-0jkkb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk ne kadar gerçek ha? 

Mesela

Bugün seni sevmemeye karar versem,

Seni sevdiğim tüm günlerin üstünü çizsem,

Lanetlesem,

Kim tutacak beni? 

Aşk ne kadar sürekli? 

Seni sevmemeye karar versem kim tutacak beni? 

Düz mantık yaşama derdine düşen sen mi? 

Sen mi anlayacaksın beni? 

Benim karman çorman, belki de saçma sapan hislerimi...

Seni unutmaya karar verdim! 

Buğunla dolu günleri kurutmaya...

Kim tutacak beni?', 'Aşk ne kadar gerçek ha?  Mesela Bugün seni sevmemeye karar versem, Seni sevdiğim tüm günlerin üstünü çizsem, Lanetlesem, Kim tutacak beni?  ...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Büşra']::text[], 8.5, '{"poet":"Nazlı Büşra","poet_slug":"nazli-busra","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/karar-verdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Güzel Söz', 'i-ki-guzel-soz-nazli-busra-atz8k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sarhoş adamlarla çirkin kadınların aşk öykülerini dinlemek lazım...

Aşkı güzel bir şehirde yaşamak lazım...

Bir deniz diyarında...

Ya da yağmurlu bir sokak lambasının altında...

Yüreğindeki fon müziği ile başbaşa...

Aşkı iki kişi yaşamak lazım...

Zira,

Omuzlarım çöküyor...

Bir gecenin yarısı

Gözyaşlarımı tutamayacağım diye korkuyorum.

Ben artık aşkı tek yaşayamıyorum.

Onu tek taşıyamıyorum...

Öyle bir boşluktayım ki,

İki güzel söze tav olabilirim...

İki güzel söz yeter bana.', 'Sarhoş adamlarla çirkin kadınların aşk öykülerini dinlemek lazım... Aşkı güzel bir şehirde yaşamak lazım... Bir deniz diyarında... Ya da yağ...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Büşra']::text[], 8.5, '{"poet":"Nazlı Büşra","poet_slug":"nazli-busra","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/iki-guzel-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-hifzi-ozbekmez-mvoez', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seviyorum dedin yalan söyledin

Aşkımı sevdamı aldın da gittin

Beni buralarda rezil eyledin

Derdin deryasına saldın da gittin

Aşkımız yıllarca sürecek derdin

Bu garip gönlüme ilhamı verdin

Sevda bahçesine aşkını serdin

Ne çabuk gönlümde öldün de gittin

Sevdayın narına her gün yanarken

Hayalde rüyada seni ararken

Önümüzde mutlu bir hayat varken

Demek başkasını sardın da gittin

Seni sevmiştim ben ölecek kadar

Yoluna canımı verecek kadar

Göz yok mu gerçeği görecek kadar

Demek ki gözlerin kördün de gittin

Aşığınım derdin demek yalanmış

Sevda gülün senin erken solanmış

Latifim ortada garip kalanmış

Seninle rüyamı böldün de gittin

2 Nisan Cuma Saat:05.00', 'Seviyorum dedin yalan söyledin Aşkımı sevdamı aldın da gittin Beni buralarda rezil eyledin Derdin deryasına saldın da gittin Aşkımız yıllarc...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gittin-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Güneşti Yarına', 'ozgurluk-gunesti-yarina-hikmet-karakus-sx56w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep birlikte,

Meşaleleri ellerinde

yemin ettiler dostluğa

Ve yürüdüler kör karanlığa.

Yangına verdiler zamanı,

Sevda sancılı,

Ölümün ılık nefesinde

umut kapkaraydı

yürek kandı,

yürek isyandı,

Ama özgürlük güneşti yarına

güneş..

(İst.1979)', 'Hep birlikte, Meşaleleri ellerinde yemin ettiler dostluğa Ve yürüdüler kör karanlığa. Yangına verdiler zamanı, Sevda sancılı, Ölümün ılık ne...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozgurluk-gunesti-yarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Yarası', 'gonul-yarasi-hifzi-ozbekmez-egu4j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gönül yarası vardı derinde

Nice merhemleri sürdüm olmadı

Fırtınalar koptu aşk mabedinde

Ağladım olmadı güldüm olmadı

Gülünce yüzüme güneş doğardı

Sevdayla gönlüme güller yağardı

Vefasız yüzünden saçlar ağardı

Deli gibi sevdim öldüm olmadı

Gönlümü verdim ben taparcasına

Sevdamın sultanı yaparcasına

İçimden ciğerim koparcasına

Canımı yoluna verdim olmadı

Ağlatmak revamı kulları her gün

Gönlümün kırılır dalları her gün

Umutsuz beklerim yolları her gün

Uçan kuşlara da sordum olmadı

Latifim bu aşkın yoktur çaresi

Onarılmaz artık gönül yaresi

Bitsin istedim de hayat çilesi

Başımı taşlara vurdum olmadı

11 Mart', 'Bir gönül yarası vardı derinde Nice merhemleri sürdüm olmadı Fırtınalar koptu aşk mabedinde Ağladım olmadı güldüm olmadı Gülünce yüzüme güne...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonul-yarasi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Ölüyorum Her Gece', 'sensiz-oluyorum-her-gece-hikmet-karakus-qwe9y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seyrederken yıldızları

soyunuk gecenin sessizliğinde

yüreğimi dinliyorum,

Kötü vurgunum ne yazar? 

Özünden ayrı 

hasret mahkümu gibi

hayallerden sessiz geçiyorum

ve sensiz ölüyorum her gece...

(İst.1979)', 'Seyrederken yıldızları soyunuk gecenin sessizliğinde yüreğimi dinliyorum, Kötü vurgunum ne yazar?  Özünden ayrı  hasret mahkümu gibi hayalle...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensiz-oluyorum-her-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-onur-yilmaz-rv9qq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni arıyorum, 

Daha önce bakmadığım tüm yerlerde! 

Ve seni bulamıyorum,

Yaşadığım tüm sevgilerde! 

Nerdesin, nerelerdesin? 

Seni bir rüzgar çığlığında bulmuşken,

Beni bir fırtına ıslığında terketmiştin! 

Seni arıyorum,

Daha önce yaşamadığım tüm annelerde! 

Renklerde, sevgilerde, ve tüm şefkatlerde...

Ve seni bulamıyorum,

Bulmak istediğim tüm alemlerde!', 'Seni arıyorum,  Daha önce bakmadığım tüm yerlerde!  Ve seni bulamıyorum, Yaşadığım tüm sevgilerde!  Nerdesin, nerelerdesin?  Seni bir rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Onur Yilmaz']::text[], 8.5, '{"poet":"Onur Yilmaz","poet_slug":"onur-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerdesin-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Diye mi?', 'gittin-diye-mi-baki-son-l3a3u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine gittin diye mi? 

İçimde bir sıkıntı, 

Gün kararıyor.

Gittin diye mi? 

Akşam oluyor..! 

Bu karanlık, 

Neden yığılır üzerime? 

Dudakların diye içtiğim şarap 

Bir de gözlerin vardı, 

Aydınlığımdı...! 

Yine gittin diye mi? 

Düş uzayıp duruyor. 

Gittin diye mi? 

Akşam oluyor..! 

Bir yalnızlık çöker 

Sen yoksan, 

Bir gariplik sarar beni, 

Terkettin diye mi? 

Evren matem tutuyor. 

Gittin diye mi? 

Akşam oluyor..!', 'Yine gittin diye mi?  İçimde bir sıkıntı,  Gün kararıyor. Gittin diye mi?  Akşam oluyor..!  Bu karanlık,  Neden yığılır üzerime?  Dudakların...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gittin-diye-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümde İlkbahar', 'koyumde-i-lkbahar-serafettin-keskinoglu-tmjkb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgâr ılık-ılık esmeye başlar

Köyümde ilkbahar geldiği zaman,

Yem yeşil yeşerir kırlar ağaçlar

Köyümde ilkbahar geldiği zaman. 

Menekşeler tutam-tutam toplanır

Toplanır da, burcu-burcu koklanır,

Koyun kuzu meralarda otlanır

Köyümde ilkbahar geldiği zaman. 

Coşar, ''Kısık Çayı'' durmadan çağlar

Süslenir çiçekle bahçeler bağlar

Cennetten bir köşe ovalar dağlar

Köyümde ilkbahar geldiği zaman.', 'Rüzgâr ılık-ılık esmeye başlar Köyümde ilkbahar geldiği zaman, Yem yeşil yeşerir kırlar ağaçlar Köyümde ilkbahar geldiği zaman.  Menekşeler ...', ARRAY['Türk Edebiyatı','Şiir','Şerafettin Keskinoğlu']::text[], 8.5, '{"poet":"Şerafettin Keskinoğlu","poet_slug":"serafettin-keskinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/koyumde-ilkbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmam artık', 'i-nanmam-artik-zafer-zengin-etnika-dsmjn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnanmam artık! 

Dağların

Duvarların

Ve öfkelerin yıkılışına

Yıktın işte

Körpe elleri

Ve cesaret aşılarken çocuğa

Silahsız bıraktın

Kolundan tutmakla...

İğrendim

Ellerinden

Dokunma bana

Dokunma yalnızlığıma

Dokunma arsızlığıma

Çaresiz bıraktın

Beni kayırmakla

Anlat şimdi derdini

Koca dağlara

Dokunma bana

Dokunma Yalnızlığıma

Dostunu iyi şeç! ! ! ! 

Kötüler yok sanki dünyada

İyilik yaptın

ne mutlu sana

Meydanı kötülere bırakmakla

Mutlu ol

Meydan senin

Kutla! 

Kutla! 

Yalnızlığınla

Senin bir yanın kadar

Şevkat görmemiş kötüler

Günlük seyahatlerinde

Yarenlik ediyorlar sana

Unutma! ! ! 

03 Nisan 2004', 'İnanmam artık!  Dağların Duvarların Ve öfkelerin yıkılışına Yıktın işte Körpe elleri Ve cesaret aşılarken çocuğa Silahsız bıraktın Kolundan ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/inanmam-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eflatunum Ben Bu Gece', 'eflatunum-ben-bu-gece-bekir-mutlu-gokcesu-oxyfd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece

Eflatunum kendimce

Bu gece bitmez

Uzar gider ismince

Baharı gözledim

Rüzgarı dinledim

Seni özledim

Bugün saatlerce

Kıpırtılı çiçeklerde

Gidip geldi aklım

Alı al, moru mor

O renkten bu renge

En çok da uçuk pembede

Kalmışım ki neticede

Eflatunum ben bu gece

Sana atıyor yüreğim

Aşka duruyorum 

Kendimce...

Saatimi kuruyorum

Sabahın mavisine...', 'Bu gece Eflatunum kendimce Bu gece bitmez Uzar gider ismince Baharı gözledim Rüzgarı dinledim Seni özledim Bugün saatlerce Kıpırtılı çiçekle...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eflatunum-ben-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sefil Selimi''ye', 'sefil-selimi-ye-sabit-i-nce-cu9j7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Kul yanmasın'' diye diye

Sen mi yandın ey Selimi.

Bizi böyle öksüz niye,

sözden caydın ey Selimi.

Ustamızdın, pirimizdin,

Ozanlardan er''imizdin,

ölümüzdün, dirimizdin,

Birden kaydın ey Selimi.

Otururduk, halleşirdik,

dilden dile dilleşirdik,

bülbül gibi gülleşirdik,

Bize kıydın ey Selimi.

Sensiz ben Sivas iline,

Gurbanım tatlı diline,

Çoban Mehmed''in seline,

sen de doydun ey Selimi.

Sesini sesime kattım,

sohbetine doydum, tattım,

son defa evinde yattım,

Bizi saydın ey Selimi.

Ne yazayım  kalem yetmez,

Seni anlatmakla bitmez,

İnce''yim dumanım tütmez,

Nara koydun  ey Selimi.

Sabit ince Kayseri 3.4.2004

NOT:Türkü olarak bestelendi.', '''Kul yanmasın'' diye diye Sen mi yandın ey Selimi. Bizi böyle öksüz niye, sözden caydın ey Selimi. Ustamızdın, pirimizdin, Ozanlardan er''imiz...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sefil-selimi-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost isen!', 'dost-isen-zafer-zengin-etnika-jo1h8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dost isen! 

Öneride bulun sadece

Ezmeden zihnimin yumağını...

Dayatma! 

Kelepçe takma! 

Ömrüme..

Zaman gidiyor deyip! 

Benliğimi köreltme...

Bana zehir içirme

Gelemem gözlerine...

03. Nisan 2004', 'Dost isen!  Öneride bulun sadece Ezmeden zihnimin yumağını... Dayatma!  Kelepçe takma!  Ömrüme.. Zaman gidiyor deyip!  Benliğimi köreltme......', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dost-isen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunma Sessizliğime', 'dokunma-sessizligime-zafer-zengin-etnika-zwgeg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dokunma sessizliğime

İliştirme gözlerini gönlüme

Mırıldandığım ne bilmem

Kopup geliyor işte

Kimsenin bilmediği yalnızlıklar

Sana gelir gibi

Nasıl kalabalık aklım bilsen

Kızılay meydanı ayaklanmış sanki

Alt geçitlere sürüyorlar adımlarımı

Çarşı pazar kesmiyor

Beyaz mintan giyme isteğimi

Saçlarım kadar

Bıyıklarım kadar 

Uzatıyorum

Dalgınlıklarımı

Kırmızı ışıklar durduruyor

Acele kaçışlarımı

Ne kadar renkli bu şehir

Siyah beyaz kayboluyorum

Kimseyi sevmeyen kaldırımlarında

Dalıyorum işte

Yeniden alt geçitlerine

İçim karanfil sokak

Tipler buluyor

Yemek masasına bıraktığım

Gülümsemem

Nasıl açmışım

Huzurun yorgunluğuna

Bu seni kaçıncı düşünmem

Artık bilmiyorum

Alt geçitlerden geçiyorum

Aydınlığı görmeye tahammülüm kalmadı

İlk fırsatta terk ediyorum

Bu şehrin yollarını

GİDİYORUM

En sevdiğim şarkıları yanıma alıp

Gidiyorum

3 Nisan 2004  ''İçimin Kitabı ''', 'Dokunma sessizliğime İliştirme gözlerini gönlüme Mırıldandığım ne bilmem Kopup geliyor işte Kimsenin bilmediği yalnızlıklar Sana gelir gibi ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dokunma-sessizligime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yollar Seveni Buluyor Ağlatıyor', 'bu-yollar-seveni-buluyor-aglatiyor-rukiye-selimoglu-mys63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pencereden bakıp akıp giden yola; 

Eyüpten,Ramiden,Kağıthaneden..

Usulca sesleniyorum sana,arka koltukta.....

Sus kimse duymasın....

Yavaşça gözlerim kayıyor utanarak...

Gittiğimiz bu yollar beni kesiyor adeta...

Dilimde sezen tam bir istanbulluyum...

Avutuyorum kendimi...

Hani derler ya; insan insana halini aksettirirmiş..

Konuşmasada....

Bu yollarda beni kesiyor...

Kimbilir,kimler ağladıki benide ağlaıyor...

BU YOLLARSEVENİ BULUYOR,SONRADA AĞLATIYOR..', 'Pencereden bakıp akıp giden yola;  Eyüpten,Ramiden,Kağıthaneden.. Usulca sesleniyorum sana,arka koltukta..... Sus kimse duymasın.... Yavaşça...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Selimoğlu']::text[], 8.5, '{"poet":"Rukiye Selimoğlu","poet_slug":"rukiye-selimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-yollar-seveni-buluyor-aglatiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemileri Yak da Gel', 'gemileri-yak-da-gel-hamit-kunt-9scs2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece ben yorgunum

Hızır gibi çık da gel

Dönülmez bir yoldayım

Gemileri yak da gel

Sakın bir soru sorma

Ayrılma gözlerimden

Keskin bir kılıç gibi

Şu kınından çık da gel

Aklını rafa kaldır

Kalbini avucuna

Bahar rüzgarlarını

Yüreğine tak da gel

Onulmaz bir yaredir

Özlemin yüreğimde

Kaldır şu perdeleri

Sınırları yık da gel

                Üsküdar 

              05/04/2004', 'Bu gece ben yorgunum Hızır gibi çık da gel Dönülmez bir yoldayım Gemileri yak da gel Sakın bir soru sorma Ayrılma gözlerimden Keskin bir kıl...', ARRAY['Türk Edebiyatı','Şiir','Hamit Kunt']::text[], 8.5, '{"poet":"Hamit Kunt","poet_slug":"hamit-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gemileri-yak-da-gel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Gün Gelir (Veda) ...', 'gun-gelir-veda-naime-erlacin-atoqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bütün defterler açık

şiirler yarım

gün gelir tersine akar su

bir omza başını koyar

diğerine tövbelerle vebali 

tarihin yinelendiği yolda 

lambaya geri dönen cin misali 

tüm zamanlardan yürür gidersin

gölgeler uykuda 

bulut gökyüzüne emanet

bir damla gözyaşında yelken olup 

şahlanıp kıyılara

saçını rüzgâra verir gidersin

solar anılarda resimler

rengini yitirmiş anka kuşu 

acıyla gülümser 

gün gelir 

söz vurur 

vuruşkan ölür

tarçın esmerliğinde

yüzü yere dönük gül gibi

dalından kopar gidersin

her yerde var olup

hiçbir yerde olmamaktır yaşamak

bütün yollar çıkmaz 

lâkin patikalar gidilesi

bir kış sabahına gizlenir merhaba

vakitsiz bir bahar akşamına düşer veda

zaman dolar 

dikilir kapıya ayrılık

acı bir tebessümle dudaklarında

yürür gidersin! 

(4 Nisan 2004)', 'bütün defterler açık şiirler yarım gün gelir tersine akar su bir omza başını koyar diğerine tövbelerle vebali  tarihin yinelendiği yolda  la...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gun-gelir-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Umuda Bakış', 'dosta-umuda-bakis-zafer-zengin-etnika-8x1r4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana

Sövmesinler

Ben Deliriyorum

Ne varsa

Salsınlar üstüme

Yeterki

Sövmesinler gülüme

/ GÜLE RENK KATMIŞLAR İNSANI

Koluma taktım dost deyip

Ustayım bize kolay olmaz deyip

Ne kadar edepsizliği varsa

Saklıyor ardına

Elbet vuracak ilk fırsatta

Bilmezim sanma

Hersey mayasında

Ozan '' pirim '' demiş hani

'' dostun attığı gül yaralar beni..İnan dosttun tüm kötü huylarını bilirim..

Bir yanım iyisini görür..bir yanım umud eder..düzelir der..

Bana söylediğin..umudu ter etmektir..Ona üzülmek

Ona ana baba sevgisi göstermek gibi gelir..

Vicdansız olmayı kendi şeçmemiştir..

Her cahilliğin başı

Sevgisizlik ve fakirlik derken

Paradan bahsetmedim sadece

Bilmem

Diyebildim mi

Diyeceklerimi

On iş

On mahalle değiştirsende

Kötüler bulur seni her yerde

Kaçmam o yüzden

Bilirim kötü benim dilimde

Umud dünyası

Düzelir belki de

Şimdilik gözü görmesede

Yüreği kendini bilmesede

Düzelecek elbette

Kendi yanlarını

İyilerle törpülemede

Onlarıda kaybedince

Kaktüslere sarılır

Bütün gece

İyiye söz demem..kötüye gücenmem..izlerim sadece..umud bitmesin diye..

4 Nisan 2004 '' İçimin Kitabı ''', 'Sana Sövmesinler Ben Deliriyorum Ne varsa Salsınlar üstüme Yeterki Sövmesinler gülüme / GÜLE RENK KATMIŞLAR İNSANI Koluma taktım dost deyip ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dosta-umuda-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadın mı Hiç ?', 'yasadin-mi-hic-hasan-huseyin-ozak-vmttk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen! 

Evet sen.. sana söylüyorum

Bakınma öyle etrafına, kimse yok bizden başka

Sen, güpe gündüz, ulu orta

kendin olmayı denedin mi hiç ? 

Başkaları ne dermiş amaaan boş ver dedin mi ? 

Yaşına başına bakmadan,

kaldırım taşlarında sek sek oynadın mı, sokakta

Yarınki nafakanı düşünmeden, 

cebindeki son parayla canının istediğini aldın mı? 

Akşam ki ekmek paranla dondurma alıp yedin mi hiç? 

İnatla, hayır ben hayatımdan memnunum derken

içindeki asi atların nal seslerini duydun mu derinden

Hıçkıra hıçkıra gülüp,

kahkahalarla ağladın mı hiç? 

Biz bizeyiz burada, her şey aramızda

Söylesene,

Sen,

Yaşadın mı hiç....?', 'Sen!  Evet sen.. sana söylüyorum Bakınma öyle etrafına, kimse yok bizden başka Sen, güpe gündüz, ulu orta kendin olmayı denedin mi hiç ?  Ba...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yasadin-mi-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkla Yaşadım', 'askla-yasadim-i-brahim-ethem-bingul-mhduc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlatamadım kendimi sana

Hele sevgimi asla

Bir de onu anlatmaya kalksam

Şöyle enine,boyuna

Aman Allah''ım var yaa! 

Benim aşkla yoğrulmuş hamurum

Aşkla dolu sağım,solum

Bir de aşkı anlatmaya kalksam

Şöyle ucunu,köşesini açsam

Aman Allah''ım var yaa! 

Ben aşkı seninle tanıdım

Ben aşkı seninle,sensiz yaşadım

Ben aşkı sen olduğun için

Aşkla yaşadım

Bir de bunu bilsen var yaa!', 'Anlatamadım kendimi sana Hele sevgimi asla Bir de onu anlatmaya kalksam Şöyle enine,boyuna Aman Allah''ım var yaa!  Benim aşkla yoğrulmuş ham...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/askla-yasadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Titredim', 'titredim-zafer-zengin-etnika-ym8g5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki 

Yaz

Kadar

Yaklaştın! 

Bana..

Unuttuğum

Ne 

Varsa

Bıraktın

Avuçlarıma...

En çok

Sessizliğinin

sesini sevdim...

Herkese 

Dedim

Yalan 

Yok...

Senle dans etmek istedim/Gülüvermedi zaman bana..Darılmadım...

Üç uyku düşündüm adını

İşte o uykular da

Yasakladım hatıraları...

Ne garip şeydi seni görmek

Elimde sigara 

t i t r e m e k...

Ne garipti..b i l e m e d i m

seni çok  i s t e d i m...

Yalan

y o k...

4 Nisan 2004  '' İçimin Kitabı ''', 'İki  Yaz Kadar Yaklaştın!  Bana.. Unuttuğum Ne  Varsa Bıraktın Avuçlarıma... En çok Sessizliğinin sesini sevdim... Herkese  Dedim Yalan  Yok...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/titredim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslata Giyotin', 'vuslata-giyotin-hayrettin-turk-kugld', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zifiri karanlık gecede

Ayaz yol kesmekte

Korku tek yoldaş,

Beklenen sevgili değil

Sıcak bir nefeste değil 

Sadece sabah…

Tamtamlar haber verir kıyametten

Ölüm orucu bitmekte olmalı

Sehpayı mecnun çakmakta

İse,

Ucunda 

İllede ben sallanmalı…

Yokluğun gece

Uzaklığın korku

Ve 

Di li geçmiş zamanlar içinde

Sabahla bir beklediğim

En gerçek vuslat ölümdü…

Sepete düşen benim kellemdi

Giyotin önünde

Ki; 

O sepet benim miracımdı,

Şimdi

Doğduğunu bile görmediğim

Güneşten yükseklerdeyim…

Zifiri karanlık gecede

Korku yol kesmekte

Bilmem artık

Hangi yürek

Ayazlı fırtınalarla

Sabahı beklemekte…', 'Zifiri karanlık gecede Ayaz yol kesmekte Korku tek yoldaş, Beklenen sevgili değil Sıcak bir nefeste değil  Sadece sabah… Tamtamlar haber ver...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/vuslata-giyotin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlemenin Kitabını Yazabilirim', 'seni-ozlemenin-kitabini-yazabilirim-k-muran-esen-4avch', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni özlemenin 

Ne demek olduğunu sor bana, 

Yetmişiki dilde  anlatabilirim

Kitabını yazabilirim / sayfalarca.

Yalnızlığın rezilliğini

Kokuşmuşluğunu

Ve çıplaklığını da.

Ama hiç kimse

Kavuşmanın güzelliğini

Sormasın bana / anlatamam.

Ben sana hiç kavuşmadım ki! 

Bilmiyorum

Dudakların nasıldır.

Sıcak mı / ateş topu  kadar, 

Yoksa soğuk  mu

Buza kesmiş bir bardak su gibi? 

Kıvrımlarına, 

Kırmızı karanfiller mi tutunmuş, 

Küle gizlenmiş kor mu var? 

Tenime değdiğinde dudakların

Cemre mi düşer bedenime, 

Mızrap değen bir saz teli gibi

Titrer mi yüreğim  / bilmiyorum.

Ben hiç dudaklarına dokunmadım ki! 

Bir kadını  sardığında kolların, 

Ürkek ceylânlar

Nasıl kurtulur tuzağından? 

Dolu  yemiş  yaprak gibi

Nasıl titrer bir yürek? 

Ellerin nasıl  okşar  bir bedeni, 

Goncalar

Nasıl güle döner / sıcaklığınla 

Bilmiyorum.

Hiç sana sarılıp yatmadım ki! 

Kısacası:

Tatmadım kavuşmayı / anlatamam.

Ama, 

Seni özlemenin kitabını yazabilirim.

Anlatabilirim daldaki kuşa /

Topraktaki solucana.

Yokluğunda / yıllardır

Özlemine dayanmayı öğrendim

Yokluğuna  katlanmayı

Aşağılık avunmayı  öğrendim / nasılsa

Ustası  oldum beklemenin

Tükenmek pahasına.

Ama hiç kimse / kavuşmayı, 

İki derenin birbirine karışıp

Sarmaş dolaş aktığı yatağın yorgunluğunu

Sormasın bana / anlatamam.

Çünkü  senle ben, 

Ayrı kaynaktan doğmuş

Sularında hasretleri taşıyan 

Başka denizlere koşan iki ırmağız.

Birbirimize uzak topraklarda tüketirken yılları

Aynamızda ayrı gökleri yansıtırız.

İşte onun için

İki dere nasıl karışır birbirine

Nasıl sığar iki nehir bir yatağa / bilmiyorum.

Seninle

Hiç aynı yatakta  coşmadım ki! 

Sen  bana / yalnızca

Ve sadece

Kahpe sensizliği sor

Rezil beklemeyi /  özlemeyi  sor.

Tanrı şahidimdir

Kurda / kuşa

Dağa / taşa  bile anlatabilirim.

Demem o ki / uzaktaki yakınım:

Vuslatlara yabancıyım, 

Ama, 

Senin özleminin kitabını yazabilirim.', 'Seni özlemenin  Ne demek olduğunu sor bana,  Yetmişiki dilde  anlatabilirim Kitabını yazabilirim / sayfalarca. Yalnızlığın rezilliğini Kokuş...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/seni-ozlemenin-kitabini-yazabilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancının Mumu?', 'yalancinin-mumu-ali-osman-yilmaz-n0m6f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Koskoca bir deniz,

Ortasında bir ada,

Yalanlar ve yalancılar adası,

Meydanda büyükçe bir ateş,

Ortada kocaman bir kazan,

İçinde pişirilmeye hazır,

Beni koymuşlar.

Sanki bu güne kadar,

Tüm kazanlarda,

Beni pişirmemişler? 

Ellerinde tamtamlar,

Bir yanda Mi,Bir yanda kader,

Kazanın içine doldurulmuş,

Yalan kaynağından,

Tertemiz yalan suyu,

Ateşe de habire,

Atıyorlar odun,

Canlansın ateş,kaynasın kazan,

Yalan suyunda Mi ile kader,

Kendi yalanlarında beni,

Yani  koca adamı,

Pişirecekler.', 'Koskoca bir deniz, Ortasında bir ada, Yalanlar ve yalancılar adası, Meydanda büyükçe bir ateş, Ortada kocaman bir kazan, İçinde pişirilmeye ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalancinin-mumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanetin Bedeli', 'i-hanetin-bedeli-ali-osman-yilmaz-y0d3q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece yarısı,

Kan ter içinde uyandım.

Dört yanım kanıyordu.

Dört yanımdan vurmuş beni,

Dört ihanet bıçağıyla,

Hançerlemiş yüreğimden,

Hınçla çektim,

Yüreğime saplanmış,

İhanet hançerini,

Taa gözbebeğinden,

Gözlerinin yüreğinden,

İhanetini bedelini,

Ödetmek için,

Vurdum bende onu,', 'Gece yarısı, Kan ter içinde uyandım. Dört yanım kanıyordu. Dört yanımdan vurmuş beni, Dört ihanet bıçağıyla, Hançerlemiş yüreğimden, Hınçla ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ihanetin-bedeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Yağmurları', 'bahar-yagmurlari-ali-osman-yilmaz-0neo2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorsun değil mi? 

Şimdi bizim oralara,

Bahar gelmiştir.

Her yer yem yeşildir,

Sana özlemim gibi.

Sarı güller,karanfiller açacak,

Onları,umutlarım olarak,

Kırmızı güllerle birlikte,

Ellerimle sana sunacağım.

Şimdi bizim oralarda,

Yağmurlar yağıyordur,

Saçına düşen damlalar,

Bil ki benim göz yaşımdır.

Şimdi bizim oralara,

Bahar gelmiştir sevgilim,

Bense kutup soğuklarında,

Buz kesmiş,donmaktayım.

Sana sıcak umutlarımı,

Ve hasret göz yaşlarımı,

Bahar yağmurlarıyla,

Gönderiyorum.', 'Biliyorsun değil mi?  Şimdi bizim oralara, Bahar gelmiştir. Her yer yem yeşildir, Sana özlemim gibi. Sarı güller,karanfiller açacak, Onları,...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bahar-yagmurlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Düşlerim.', 'mavi-duslerim-ali-osman-yilmaz-55272', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aynı gözlerin gibi,

Sana inat hep,

Maviye çalar düşlerim,

Her zaman seni,

Gök kuşağında düşlerim.

Renk renk boyarım seni,

Saçlarını,umutlarımı,

Ama düşlerime karıştırmam seni,

Onlar her zaman,

Gözlerin gibi mavi,

Mas mavi.', 'Aynı gözlerin gibi, Sana inat hep, Maviye çalar düşlerim, Her zaman seni, Gök kuşağında düşlerim. Renk renk boyarım seni, Saçlarını,umutları...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mavi-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyeceğim Seni.', 'ozleyecegim-seni-ali-osman-yilmaz-4ui5a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine çıldıracak gökler,

Kükreyecek her yana,

Sevdaya,aşka olan,

Öfkelerimi.

Kaybolacak sonra ışıklar,

Her yan karanlığa boğulacak,

Aynı yalnızlığım gibi.

Ben yine sabahı bekleyeceğim,

Güneşi,ışıklarını,

Sonra esen bahar yelinde,

Kokunun gelmesini bekleyecek,

Seni,sarı saçlarını,

Mas mavi gözlerini,

Teninin tuzunu,

Ben seni,sevgilim seni,

Özleyeceğim.', 'Yine çıldıracak gökler, Kükreyecek her yana, Sevdaya,aşka olan, Öfkelerimi. Kaybolacak sonra ışıklar, Her yan karanlığa boğulacak, Aynı yaln...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozleyecegim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Zifiri Karanlık', 'gece-zifiri-karanlik-ali-osman-yilmaz-21rl1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani,o köşede  duran,

Canım şu gözleri görmeyen,

O adam var ya; 

O söyledi,bu gece,

Kap karaymış gece.

‘’Neden diye’’sordum? 

Gözleri görmeyen o,

Bizim köşede duran adama.

‘’Sevda ve aşk,bu gece,

Terk etti buraları’’dedi.

 O yüzden karanlıkmış gece,

Ve o yüzden,zifire dönmüş,

Kararmış umutlarım.

Görecek bir şey kalmadı,

Her yıldız bir sevdaydı,

Ay, aşkımın ışıklarını yayardı,

Sevdam yok,aşkım yok,

Gitmişler uzaklara,

Hiç ışık kalmamış gökyüzünde,

İşte o nedenle bu gece,

Işıksız ve zifiri karanlık.', 'Hani,o köşede  duran, Canım şu gözleri görmeyen, O adam var ya;  O söyledi,bu gece, Kap karaymış gece. ‘’Neden diye’’sordum?  Gözleri görmey...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gece-zifiri-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık.', 'gel-artik-ali-osman-yilmaz-wxsi2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel artık,

Usanmadın mı oralarda? 

Bensiz ve yalnız yaşamaktan? 

Yeter de artık,

Yeter de,ve gel güzelim,

Gel artık yanıma.

Bak buralarda,

Seni bekleyen,

Sevda dolu,aşk dolu,

Özlemlerimle arzu dolu

Ben varım.', 'Gel artık, Usanmadın mı oralarda?  Bensiz ve yalnız yaşamaktan?  Yeter de artık, Yeter de,ve gel güzelim, Gel artık yanıma. Bak buralarda, S...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gel-artik-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Haber Gönder', 'bir-haber-gonder-ali-osman-yilmaz-111ap', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelmeyeceksen,

Arada bir,

Sevda kuşlarıyla,

Bir haber gönder.

İyiyim de,

İyi olduğunu bileyim,

Sensizliğin içinde,

Sensiz yalnızlığımda,

İyi haberlerine,

Sevineyim.', 'Gelmeyeceksen, Arada bir, Sevda kuşlarıyla, Bir haber gönder. İyiyim de, İyi olduğunu bileyim, Sensizliğin içinde, Sensiz yalnızlığımda, İyi...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-haber-gonder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahlarını Bana Yazdım', 'gunahlarini-bana-yazdim-ali-osman-yilmaz-yo25q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acı çekmeye güzelim,

Yüreğin yeterse eğer,

Ölüm sana vız gelir.

Benimse,Sana olan hasretim,

Cehennemimdir.

Korkma artık,

Gideceğin yer cennetimdir,

Çünkü senin,

Tüm günahlarını,

Senin defterinden silip,

Kendi defterime yazdım.

Tertemiz ve günahsızsın artık,

Cennetimde bensiz,

Ve günahsız yaşayacaksın.', 'Acı çekmeye güzelim, Yüreğin yeterse eğer, Ölüm sana vız gelir. Benimse,Sana olan hasretim, Cehennemimdir. Korkma artık, Gideceğin yer cenne...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gunahlarini-bana-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Bakan Gözlerin.', 'mavi-bakan-gozlerin-ali-osman-yilmaz-pzslx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni tanıyıncaya,

Aşk bana yabancıydı.

Seni tanıdıktan sonra,

Aşklar da yalancı olmuş,

Tıpkı senin gibi.

Neden böylesin? 

Yalanlar ve ihanetler,

Yoldaşın olmuş senin.

Sana sarıldığımda,

Yalan kokardı tenin.

Aynı aşkın gibi,

Yalanlarına benzemiş,

Mavi bakan gözlerin.', 'Seni tanıyıncaya, Aşk bana yabancıydı. Seni tanıdıktan sonra, Aşklar da yalancı olmuş, Tıpkı senin gibi. Neden böylesin?  Yalanlar ve ihanet...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mavi-bakan-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Patlayacağım', 'bir-gun-patlayacagim-ali-osman-yilmaz-h2ygx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlemlerimle,arzularımla dolu,

Sevda dolu bu yürek,

Bir gün öyle patlayacak ki,

Henüz yapılamadı,

Böyle patlayacak tüfek.

Bir patlamaya görün,

Aşkınla dolu bu yürek,

Ortalık nükleer enerji dolacak,

Binlerce yıl temizlenemedi,

Binlerce yıl da,

Temizlenemiyecek.', 'Özlemlerimle,arzularımla dolu, Sevda dolu bu yürek, Bir gün öyle patlayacak ki, Henüz yapılamadı, Böyle patlayacak tüfek. Bir patlamaya görü...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-gun-patlayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tutam Aşk,Bedava.', 'bir-tutam-ask-bedava-ali-osman-yilmaz-e9yel', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi şiiri okusam,

Hangi şaire kulak versem,

Hatta nereye baksam,

Sevdasına,aşkına,

Har olmuş yananları,

Görüyorum.

Gece duvarda saat,

On ikiyi vuruyor.

Senden tek ses yok,

Kulakların da sağır,

Ne şarkımı duyuyor,

Ne yüreğin atıyor.

Öldün mü yoksa? 

Sabah olunca,

Gözlerim açılıyor.

Şehri dolaşmaya çıkıyorum,

Bir pazar yerinde,

Bir tezgahtar bağırıyor; 

Üç kuruşa sevda satıyor,

Yanında da bir tutam aşkı,

Bedava veriyor.', 'Hangi şiiri okusam, Hangi şaire kulak versem, Hatta nereye baksam, Sevdasına,aşkına, Har olmuş yananları, Görüyorum. Gece duvarda saat, On i...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-tutam-ask-bedava-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa...!', 'yoksa-bayram-tunca-cbucm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidenlerle sana elciler gönderdim

Gelenlerden de cevabını bekledim

Şu sineme taş basıp pes etmedim

Avcı misali tepelerden gözetledim

Daima adını andım sen anmadın mı

Aşkından yandım, sen yanmadın mı

Aşkımızı ilân ettim, sen etmedin mi

Yoksa, seni sevdiğimi inanmadın mı

Kuşlarla selam gönderdim almadın mı

Kokumu yolladım rüzgarla almadın mı

Sevda yüklü ak bulutları görmedin mi

Aşk ixsirli yağmurlarla yıkanmadın mı

Aşk mayalı pınarlardan su içmedin mi

Ben benden geçtim sen geçemedin mi

Gönderdiğim elcilerle ikna olmadın mı

Yoksa aşkım sende ma kez bulmadı mı

B. Tunca/04.04.2004-04.04-İst.', 'Gidenlerle sana elciler gönderdim Gelenlerden de cevabını bekledim Şu sineme taş basıp pes etmedim Avcı misali tepelerden gözetledim Daima a...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yoksa-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gözlüm', 'bahar-gozlum-erhan-saka-lns7d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç yıl oldu görmeyeli,

Neredesin bahar gözlüm,

Kalbimdeki izin belli,

Silemedim bahar gözlüm.

Seni sensiz yaşıyorum,

Dertlerimle coşuyorum,

Kalbimdesin taşıyorum,

Atamadım bahar gözlüm.

Unutmadım sözlerini,

Çok özledim gözlerini,

Bıraktığın güllerini,

Kurutmadım bahar gözlüm.

Son mektubun şu an bende,

Gözyaşın var kelimende,

Düğümlendi söz dilimde,

Diyemedim bahar gözlüm.

21-10-2003', 'Kaç yıl oldu görmeyeli, Neredesin bahar gözlüm, Kalbimdeki izin belli, Silemedim bahar gözlüm. Seni sensiz yaşıyorum, Dertlerimle coşuyorum,...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bahar-gozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Derdim Başka', 'benim-derdim-baska-erhan-saka-0nx4i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aldırma çatık kaşıma,

Benim derdim başka gülüm,

Neler geldi bu başıma,

Benim derdim başka gülüm.

Düzen bozuk dünya yalan,

Sensiz hayat bana haram,

İçimdeki ağır yaram,

Benim derdim başka gülüm.

Değer verdim insanlara,

Kucak açtım tüm dostlara,

Karşı koydum düşmanlara,

Benim derdim başka gülüm.

Gitmez oldu ayaklarım,

Çıkmaz sokak tüm yollarım,

Sana açık bu kollarım,

Benim derdim başka gülüm.

13-01-2004', 'Aldırma çatık kaşıma, Benim derdim başka gülüm, Neler geldi bu başıma, Benim derdim başka gülüm. Düzen bozuk dünya yalan, Sensiz hayat bana ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benim-derdim-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-erhan-saka-sisxk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neredesin benim gül yüzlü yarim,

Acılar hayatı karatmadan gel,

Sensizlik kaderim, yalnızlık karım,

Saçımda aklarım çoğalmadan gel,

Habersiz gidişin neye yaradı,

Her geçen gün gözler seni aradı,

Güzel günler varken dünyam karardı,

Gözümde yaşları kurutmaya gel.

Yaşarız dünyada bizler kiracı,

Her günüm ızdırap, her günüm acı,

Mutluluk ne demek bana yabancı,

Gözlerim hayata kapanmadan gel.

09-04-2004', 'Neredesin benim gül yüzlü yarim, Acılar hayatı karatmadan gel, Sensizlik kaderim, yalnızlık karım, Saçımda aklarım çoğalmadan gel, Habersiz ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gel-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Küsmüşüm', 'hayata-kusmusum-erhan-saka-bfh6e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni bir başıma koyup gittiniz,

Dertlerin eline nasıl düşmüşüm,

Sitemler az gelir neler ettiniz,

Ben zaten sizlere çoktan küsmüşüm.

İyi gün dostlarım neredesiniz,

Kaybolup gittiniz çıkmaz sesiniz,

Bilirim sizleri hep böylesiniz,

Ben zaten hayata çoktan küsmüşüm.

Ne kadar dert varsa sineye çektim,

Mutluluk dururken çileyi seçtim,

Kimseye gücenmem ben kendim ettim,

Ben zaten dünyaya çoktan küsmüşüm.

09-03-2004', 'Beni bir başıma koyup gittiniz, Dertlerin eline nasıl düşmüşüm, Sitemler az gelir neler ettiniz, Ben zaten sizlere çoktan küsmüşüm. İyi gün ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayata-kusmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Zamansız', 'hep-zamansiz-erhan-saka-594s0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir aşka düştüm amansız,

İnanmadın sen imansız,

Sende beni sevdin ama,

Gidiyorsun bak zamansız.

Unuttun mu sözlerini,

Hiç kaçırma gözlerini,

Gitme kal diyemem sana,

Kaçıyorsun sen zamansız.

Sana değil isyanlarım,

Kaderime ben ağlarım,

Yalnızlıktan korkmuyorum,

Ayrılığın çok zamansız.

Kör olsun bu aşkın gözü,

Dilimdeki  sevgi sözü,

Hem baharı hem de güzü,

Yaşıyorum hep zamansız.

25-12-2003', 'Bir aşka düştüm amansız, İnanmadın sen imansız, Sende beni sevdin ama, Gidiyorsun bak zamansız. Unuttun mu sözlerini, Hiç kaçırma gözlerini,...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hep-zamansiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Ne Sanıyorsun', 'kendini-ne-saniyorsun-erhan-saka-2phn6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzelliğin baki kalmaz,

Güneş her gün sana doğmaz,

Ardından hep biri koşmaz,

Kendini ne sanıyorsun.

Benim sevgim bana yeter,

Benim sevgim burda biter,

Unutmaya gücüm yeter,

Kendini ne sanıyorsun.

Senin sevgin bana fazla,

Gücüm yetmez dönmem asla,

Sağlam iken oldum hasta,

Kendini ne sanıyorsun,

Mavi gözler bir gün söner,

Umutlar küllere döner,

Sevdiklerin bir bir gider,

Kendini ne sanıyorsun.

30-09-2003', 'Güzelliğin baki kalmaz, Güneş her gün sana doğmaz, Ardından hep biri koşmaz, Kendini ne sanıyorsun. Benim sevgim bana yeter, Benim sevgim bu...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kendini-ne-saniyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanış', 'uyanis-melek-midikoglu-h7ana', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çiğ tanesinin gölgesinde

Değiştirdim kendimi

Sen yeni filizlenen tomurcuğum

Çok aramadan bul beni

Tebessümüne kurulup,

Rüyalarına taşındım

Bir çiğ tanesinin gölgesinde de

Yaratana vuruldum', 'Bir çiğ tanesinin gölgesinde Değiştirdim kendimi Sen yeni filizlenen tomurcuğum Çok aramadan bul beni Tebessümüne kurulup, Rüyalarına taşınd...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uyanis-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Hayalmiş', 'mutluluk-hayalmis-erhan-saka-uqskr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözyaşım sel oldu aktı gözümden,

Her şeyi unutup hiç gülemedim,

Yıllarım boş yere geçti önümden,

Mutluluk hayalmiş hiç bilemedim.

Sevecek birini aradım durdum,

Gönlümü zincirden zincire vurdum,

Boş yere ümitsiz hayaller kurdum,

Mutluluk hayalmiş hiç bilemedim 

Gün gelip beni de bulacak sandım,

İnsanın o gülen yüzüne kandım,

Ne yazık gerçeği çok geç anladım,

Mutluluk hayalmiş hiç bilemedim.

07-03-2004', 'Gözyaşım sel oldu aktı gözümden, Her şeyi unutup hiç gülemedim, Yıllarım boş yere geçti önümden, Mutluluk hayalmiş hiç bilemedim. Sevecek bi...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutluluk-hayalmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Gönlüm', 'unut-gonlum-erhan-saka-0wtp4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unut gönlüm unut onu,

Yandığını bilmesin,

Görünen, bu aşkın sonu,

Gözyaşını silmesin.

Herkes kendi yoluna,

Ümit taşı yarına,

Can mı kattı canına,

Sil dünyana girmesin.

Bir gün pişman olacak,

Alev, alev yanacak,

Sana geri dönecek,

Tanıma ki anlasın,

Çek git haber vermeden,

Sana geri dönmeden,

Son sözünü demeden,

Öldüğünü bilmesin.

28-01-2004', 'Unut gönlüm unut onu, Yandığını bilmesin, Görünen, bu aşkın sonu, Gözyaşını silmesin. Herkes kendi yoluna, Ümit taşı yarına, Can mı kattı ca...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unut-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suç Benim mi?', 'suc-benim-mi-erhan-saka-mmu2r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluğu sende gördüm,

Seni sonsuz sevgi bildim,

Her şeyimi sana verdim,

Seni sevdim suç benim mi.

Nefes oldun ciğerimde,

Bir can oldun bedenimde,

Yazı gibi kaderimde,

Seni sevdim suç benim mi.

Dilimde bitmez şarkısın,

Kim bilir belki haklısın,

Sevgilere yasaklısın,

Seni sevdim suç benim mi.

Hayatımın bin bir rengi,

Yüreğimde sonsuz sevgi,

Özgür uçan kuşlar gibi,

Seni sevdim suç benim mi.

11-01-2004', 'Mutluluğu sende gördüm, Seni sonsuz sevgi bildim, Her şeyimi sana verdim, Seni sevdim suç benim mi. Nefes oldun ciğerimde, Bir can oldun bed...', ARRAY['Türk Edebiyatı','Şiir','Erhan Saka']::text[], 8.5, '{"poet":"Erhan Saka","poet_slug":"erhan-saka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/suc-benim-mi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosun Gözlerin', 'yosun-gozlerin-i-brahim-dikmen-2-yz27a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçmişimi aradım,dün gece anılarda,

Seninle paylaştığım,o''eski günleri hatırladım.

Yosun gözlerini gördüm,denizin enderin mavisinde,

Hatırladıkça maziyi,oturup çocuklar gibi ağladım.

Dolunay arkadaşımdı,ıssızdı dün gece,

Dalgalar,hıçkırıklarımı gizlediler,dev cüsselerinde.

Yakamozlar,bana eşlik ettiler,sevdama ağlarken,

Senin gibi,dokunup kaçtı,vefasızdı med_cezirler.

Tıpkı sana benziyor,kocaman azgın dalgalar,

Ne varsa önünde,ezip geçiyor,geride iz bırakmadan.

Senin yaptığın gibi,çekip gidiyorlar,apansız,

Benide götür diyen,yüreğimin çığlıklarını,duymadan.

Kumsalda gördüğüm,bir yığın çöp enkazı,

Sanırım,kaderimiz aynı,onlarla.

Onlar,azgın dalgaların,kıyıya terkettikleri,

Bense,senin terkettiğin,bir ölü buralarda.

Saatin kaç olduğu,umurumda bile değil,

Henüz şarabımı,açmadımki! 

Kaçıncı paketti açtığım,sarı uçlu sigaranın,

Saymadım aşkım,saysam ne olacakki! 

Seni içime çeker gibi çektim,sigaramın dumanını,

Ciğerimin köşesine hapsettim,kaçmasın diye.

Olurya,senin gibi,onlarda kaçarlarsa apansız,

Bir yudum,bir yudum daha,şarabımdan içtim,sen diye.

Yosun gözlerini gördüm,denizin enderin mavisinde,

Ölümcül sevdaymış aşkın,işlemişsin benliğime olanca.

Ne sigara,nede şarap,unutturamadı hiçbirşey seni,

Kaybolup gittin yine,sabahın ilk ışıklarıyla.', 'Geçmişimi aradım,dün gece anılarda, Seninle paylaştığım,o''eski günleri hatırladım. Yosun gözlerini gördüm,denizin enderin mavisinde, Hatırla...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yosun-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değdi Mi?', 'degdi-mi-halil-kesken-3m4k9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söyle martı, o güzelim kanadın

Hiç bir zaman bulutlara değdimi? 

Gün gelipte, taş sandığın yüreğin

Umutsuz bir aşka boyun eğdimi? 

Söyle martı, sen hiç aşık oldunmu

Deli gibi tüylerini yoldun mu? 

Sevdiğini ariyordun, buldun mu? 

Denizleri aştığına değdi mi? 

Hep didindin rüzgarları yardında

Tüm hayatın bir balığın ardında

Ne kazandın diyarına vardında

Yorgun düşüp, solduğuna değdi mi? 

Canını da feda ettin aşkına

Gönül verdin, neler geldi başına

Bir karanfil koymaz oldu taşına

Onun için öldüğüne değdi mi? 

Halil kesken       14/07/2000', 'Söyle martı, o güzelim kanadın Hiç bir zaman bulutlara değdimi?  Gün gelipte, taş sandığın yüreğin Umutsuz bir aşka boyun eğdimi?  Söyle mar...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/degdi-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Günün Düşündürdükleri', 'i-ki-gunun-dusundurdukleri-gurkal-gencay-2gndr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'annemden sakladığım bir gözaltının

işkence sonrası düştün yine usuma.

yağır yaraydı hücrem,

ve ben pusatsız uykuların özlemindeydim.

açtım, sigarasızdım,

şiir güzelliğince yağıyordu içime yokluğun

kağıtsızdım, kalemsizdim,

sevda ürünü tarlalarda göğeren hasretimdin

menzile yatarken zulmün burcunda,

öfkemin kabzasına

bir sensizlik daha işledim.

gece çıplaktı, ay çıplak

duvarlar,

parmaklıklar,

ve ben çıplaktım.

canımla uğraşıyordum sorgularda,

bir de; 

silah sesli konuşmalardan sakladığım

yokluğunla.

döşümde çöreklenen yumruk yalımı,

bileklerimde kelepçe ağrısı,

gözlerimde cam kırığı hasretinin

sancısı kanıyordu.

..ve ben kavganın esmer güzelliğinde

sarışın direngenlikle karşı koymaktaydım

kurşun yaralı kayaların üzerime devrilmesine..

hey! direncimin kutsanmış çocuk gülüşlü kızı,

özgürlüğe bilenmiş göklerin yıldızı,

sevdam,

sen, elimde pimi çekilmiş bombam,

yiğidim,

gözümün Nur''u

gecemin ay''ı

senindir artık bu gökkuşağı

yeşiliyle, sarısıyla, kırmızıyla,

senindir bu yağmalanmış kanayan yürek.

nikotin kınalı parmaklarım,

geçip de yakılmış bahçelerden,

ve darmadağın edilmiş hanelerden

kapına duru bir aşk söylencesi getirecek.

ki, feryadı sende kaldı,

eğilmezliği boynumun,

ve bakışlarımda dokunduğun yalnızlığımın.

açıldı çelikten kelepçeler,

iki geceye,

ve üç gündüze sığdırdığım 

has ölümler sınandı,

kanatlanıp gitti canımın ağrısı,

sönmesiz bir yangın yeri şimdi

yüreğime astığın sitemin ağıtı.

ürküler,ne filizlenir tenimde

ne alnım çatından yiter ölümün uçurumları,

serp tohumu kara bağrına toprağın

ve sula gözüm yaşı ile,

kanım ile,

terim ile,

yaban çiçekleri umutlansın.

mevsiminde asit yağmurları,

akar tüm sokaklar öznesine

ve sevdan,

gencecik bir servi dal misali

boy verir yüreğimde.

gürültülerin sırtıma kamburlanışından

öğrendim dalga dalga seni,

çığlık katarı soykırımların

dudağımı ısıran tanımından...                         

*

hey! gülüşsüz sevinçlerimin çocuk sesli kızı,

karanlık denizlerin ışık yüzlü yıldızı,

sevdam,

bir gözümdeysen; 

diğer gözüme emanet edemediğim

yiğidim,

yüreğimin Nur''u,

aynı solukta türkülere durduğum.

bir yıldızdır alnımda kurşun kurşun

sevdamın tek kanatlı kuşu

ve aşkımın tek taraflı tutuşuşu.

öfkesi var sevdamın,kanıyor asırlardır.

kafesten yeni kurtulmuş bir kuş gibi,

maltaları,

havalandırmaları yarıpta

şaşkın ve ürkek

bilinmeze kanat açmak

ve bir hayale çıldırasıya sevdalanmak

elbette cezasız kalmayacaktı.

denizlerin bütün tekneleri batacaktı,

birer birer düşecekti asmaların yaprakları,

şarkılar susacaktı; 

..ve bütün kuşlar vurulacaktı...

kırılsın kalem,

kesilsin cezam,

suçluyum.

ki, ben seviyorum yalnızca 

bu deli oyunda biliyorum,

yani cezalı çocuğuyum oyunun,

ebesiyim

ve ortağı yok suçumun.

şarkılardan falları ben tutuyorum,

ve belki de,

anlamak istediklerimi anlamaya zorluyorum,

düşün; 

kendimi bile aldatıyorum.

suçluyum elbette; 

suçluyum,

yasak sevdalar büyütüyorum yüreğimde

ben ki,

yaşamın hep ''''yaramaz çocuğuydum''''

ve hep şikayet edileni oldum.

oysa,

güneşi ellerinde taşımaya

             bedenlenmişti gözlerim,

hiçbir ayrılığın resmine

yakıştırmayacaktı kendini ümitlerim,

bebeğinden,

Bishnoi mavisi bakacaktı gözlerinin.                          

                                  

ama,

başımda esen hardal rüzgarları

koca çınarları devirecekti,

ve mağrur ölümler ile

dışlanmışlığın mezarına

platonik kanatlı kuşlar diri diri gömülecekti.

avuçlarımda

umut yaralı bir güvercin,

ana karnında vurulan karaca,

postuna sebep doğmadan boğazlanan kuzu,

yaşamın kademsiz sokak aralarında yitecekti.

sesimin kurşun kurşun oluşuyla,

kara tufan düşer de çığrıma,

bekler kınında cembiyeler; 

kamalar, hançerler,

şom keskinliklere bilenecekti...

baktıkça eskir yüzleri ergen kızların,

yani,

üstüme çöreklenen uğursuzlukların 

                 haramiliğine

inatla sıkılmıştı yumruklarım,

dayatmıştı,

ama hiçbir diken

ayaklarımızı yırtmadan

boy atmamıştı,

ve sevdam; 

yüreğimi böylesine kanatmamıştı.               

başımda bin bir türlü bela,

bir o kadar da uğursuzluk var,

üryanlığından utanan dağlara sorsunlar,

yeminimi, kasemimi,

madem ki cenkteyim

bu savaşı kazanacağım,

ya bir hocaya gidip

kafamdan aşağı kurşun döktüreceğim

yani,

uğursuzluklardan kurtulacağım,

ya da; kafama

bir kurşun sıkacağım! ..', 'annemden sakladığım bir gözaltının işkence sonrası düştün yine usuma. yağır yaraydı hücrem, ve ben pusatsız uykuların özlemindeydim. açtım, ...', ARRAY['Türk Edebiyatı','Şiir','Gürkal Gencay']::text[], 8.5, '{"poet":"Gürkal Gencay","poet_slug":"gurkal-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":155,"source_url":"https://www.antoloji.com/iki-gunun-dusundurdukleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik An-ı-ları', 'sensizlik-an-i-lari-ensar-aktas-ualgb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Serabın geçiyor gözlerimin önünden kare kare

Seçemiyorum gözlerinin rengini, kareler hare hare

Gözgöze gelmek, donmak istiyorum gözlerinde

Ben yine yetişemiyorum sana, yüreğim pare pare

İki damla yaş vardı son gördüğümde, gözlerinde 

Renkleri, denizin buğulu türkuaz kıyılarına çalıyordu

Bir küçük umut ışığı arıyordum sitemkar sözlerinde

Ben yetişemiyordum sana, ellerim mendil sallıyordu

Şimdi eller boş, sözler boş, gözler boş, herşey boş

Şimdi bakışlar bir hoş, gülüşler sarhoş, anılar loş

Haybeden kırılan kalplerde aşkımız sanki bir varoş

Semaya yükseliyor bu gece de son pişmanlık nidaları

Ve donuyor duvardaki çerçevede sensizlik an-ı-ları

Rotterdam, 25.01.2004', 'Serabın geçiyor gözlerimin önünden kare kare Seçemiyorum gözlerinin rengini, kareler hare hare Gözgöze gelmek, donmak istiyorum gözlerinde B...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensizlik-an-i-lari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşböceği', 'atesbocegi-ozkan-ozdogan-eybv0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökte asılı kandiller,

balıkçıların fenerleri

ve kör bir kedinin gözlerine rağmen,

karanlıktır gece.

Değiştiremez bunu işte,

hiçbir kahraman

ateşböceği!', 'Gökte asılı kandiller, balıkçıların fenerleri ve kör bir kedinin gözlerine rağmen, karanlıktır gece. Değiştiremez bunu işte, hiçbir kahraman...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/atesbocegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Sende', 'aklim-sende-umit-kilislioglu-ozger-rs8sd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnce uzun parmaklım,

Sende aklım..

Işığına tutunuyorum

Sarmaşıklar misali

Üç sürgün öncesinden beri.

Gül yanaklım, bal dudaklım

Seni sevdiğimi herkes biliyor

Su damlası gibiyim ben,

Yok ki saklım! 

(4.4.2004) 

(Doğa''ya...)', 'İnce uzun parmaklım, Sende aklım.. Işığına tutunuyorum Sarmaşıklar misali Üç sürgün öncesinden beri. Gül yanaklım, bal dudaklım Seni sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aklim-sende-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öykümüz bir sevda öyküsü/ Mekanımız...', 'oykumuz-bir-sevda-oykusu-mekanimiz-gok-tengri-3rmw7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oğlan daha gençti

Otuzların başında ya vardı ya yoktu

Mekanımız morgdur

Öykümüz bir sevda öyküsü...

Bir kız vardı kızlar içinde

Gözleri ne güzel, dudağı, yanağı, elleri

Yüreği ne güzel bir kız vardı

Kızın yaşamdan en büyük dileği doktorluktu

Doktorluk için yaşamadı gençlik yıllarını

Sevmedi,sevişmedi (istemedi)

Ama öyle çok sevildi ki

Hani Tanrı bile kıskanacaktı nerdeyse

Bir kula bu kadar da sevda duyulmaz diye

Zaten bir Tanrı''nın sevgisini anlayamazsınız

Bir de bu kızın..

Kız kendini öyle delice,

Öyle hergün kendini öldürürcesine,

Öldürür de ölmezcesine seven oğlanın

Bir kez olsun tutmadı elini

Bir kez olsun göstermedi sevgisini

Oğlanı da, sevgisini de, 

Birlikte geçirecekleri tüm güzel günleri de 

Heba etti ''büyük dileği'' uğruna..

Ama başardı..

Kız doktor oldu a dostlar,

Kız doktor oldu

Dedik ya oğlan daha gençti

Otuzların başında ya vardı ya yoktu

İstemli sefalet ve gönüllü serserilik

Ve Yunan-Latincilere isyanla geçti gençlik yılları

Bir ay-yıldıza, bir de yazmaya aşıktı oğlan

Oğlanın sevgilileri de oldu arasıra

Ama vazgeçti hepsinden

Kimleri sevmekten vazgeçti de

''Kız''dan geçemedi oğlan

Kız sevgilisi bile değildi..

Kız doktor oldu a dostlar,

Kız doktor oldu

Oğlan ne oldu? 

Ne olduğunun pek önemi yok

Çünkü oğlan benzi solmuş,

Soğuk bir et yığınıdır şimdi

Nasıl öldüğünün pek de önemi yok

Daha gençti oğlan

Otuzların başında ya vardı ya yoktu

Mekaznımız morgdur

Öykümüz bir sevda öyküsü a dostlar

Oğlan tutardı arasıra kızın elini

Kız hep o elin sıcaklığından şikayet ederdi

Mekanımız morgdur a dostlar

''Doktor kız'' mekandadır..

Kız bir cesedi seviyordu

Okşuyordu saçlarını, öpüyordu ellerini

O eli ilk defa ellerinin arasına aldı kız

Ve  ilk defa o el soğuktu..

O el bir daha tutamayacak, dokunamayacak, kavrayamayacaktı

Kızın yanağında gezinme saadetinde bulunamayacaktı bir daha o el

Artık bir et yığınından farksızdı..

Kızın yanaklarından birer damla yaş süzüldü

Süzüldü ve düştü artık hissetmeyen oğlanın üstüne

Ama bu masal değil a dostlar

Bu bir sevda öyküsü

Bu bir masal değil a dostlar

Oğlan canlanmadı..

Kız tutup elinden yarı kaldırdı oğlanı

Ve kız o et yığınına, o taş soğukluğuna

''Bundan sonra kimsenin kendisini o denli sevemeyeceği duygusunun

gerçekliği kadar'' sıkı sarıldı

SIKI..

SIMSIKI..

İlk defa oğlan kızın hareketine yanıtsız kalmıştı a dostlar

Çünkü bu bir masal değildi

Öykümüz bir sevda öyküsüdür

Mekanımız morg...

12Aralık2003 23.29', 'Oğlan daha gençti Otuzların başında ya vardı ya yoktu Mekanımız morgdur Öykümüz bir sevda öyküsü... Bir kız vardı kızlar içinde Gözleri ne g...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/oykumuz-bir-sevda-oykusu-mekanimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sükut Eden Dağa', 'sukut-eden-daga-ali-kadioglu-eg9c0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daldım yine suyuna insafsız bir hicranın

En zalim şarkısıydı bu,bin yıllık devranın.

Sarınca bedenimi amansız bir heyelan

Karanlığın en ıssız sınırlarına dalan

Bu gam yüklü hamalın hayalleri bunaldı

Hüzünlü mısralardan geriye kahır kaldı! .

Saz telinden ayrıldı,kamış ney''ine küstü

Mimarından ruh alan saray kaldı yüzüstü..

Züleyha''nın sesiyle aşkı diken kuşattı

Yûsuf''un güzelliği dikeni güle kattı..

Kuru bir Leylâ''sıyla Mecnûn efsane oldu

Görseydi bu halimi,derdi ''''Sana ne oldu? 

Kimmiş tarumar eden yürek saltanatını

Çekemedim ben senin derdinin zekatını! ''''

Takvim yaprağı gibi tarihin sırlarına 

Karışıp gidiyorum,bakamadan yarına..

Bir avcı yenik düştü ormandaki ceylana 

Bir aslan bir balıktan kan içti kana kana..

Ondan kalan hatıra gözümdeki nem oldu

Adındaki üç hece ruhuma kefen oldu! ..

Hiçbir tarif yetmedi gülümü anlatmaya

Ruhuma kök salan tek dalımı anlatmaya..

Bengisu ırmağında boğulup da ölmüşüm

Sonsuzu arar iken gölgelerde kalmışım..

Bu sırrımı çözecek bir O vardır dünyada

Bana kalan sermaye bu kadardır dünyada! ..

Ey gurbet aleminde sevda vatanım benim

N''olur bir duy sesimi,sönmesin tânım benim! ..', 'Daldım yine suyuna insafsız bir hicranın En zalim şarkısıydı bu,bin yıllık devranın. Sarınca bedenimi amansız bir heyelan Karanlığın en ıssı...', ARRAY['Türk Edebiyatı','Şiir','Ali Kadıoğlu']::text[], 8.5, '{"poet":"Ali Kadıoğlu","poet_slug":"ali-kadioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sukut-eden-daga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediye', 'hediye-ferit-teksoy-3xhuw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tanrı herşeyini güzel yaratmış

Herhalde tatil günüydü o gün

Bir heykeltraş''a bakmış olmalı

Belki bir ressam''a,uzmanlığı nü! ..

Bir kalp cerrahından yardım isteyip

Sana takmış sanki en güzelini

Her ayrıntı çok harika işlenmiş

Epeyce uğraşmış yaparken ellerini

Sanırım gözlerini ceylandan almış

Takmış yerlerine mücevher gibi

Saçların..evet onlar güneş sarısı

Güneşten çıkarıp almış,demek ki! ..

Yüz şeklin de çok mükemmel oturmuş

Kaşlar ve kirpikler tabii sürmeli

Burun küçük,kulaklar da sevimli

Ya ayaklar..bilmem ki ne demeli? ..

Bana da zavallı bir yürek vermiş

Baksın baksın sana..erisin diye

Yine de şanslıyım herşeye rağmen

Özenip yaratmış..etmiş hediye! ..', 'Tanrı herşeyini güzel yaratmış Herhalde tatil günüydü o gün Bir heykeltraş''a bakmış olmalı Belki bir ressam''a,uzmanlığı nü! .. Bir kalp cerr...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hediye-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zannettim', 'zannettim-hifzi-ozbekmez-kumwe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tuhaf oldum ben başım dönüyor

Azrail kapıyı çaldı zannettim

Gözümün ışığı sanki sönüyor

O anda canımı aldı zannettim

Nefesim kesildi karıştı aklım

Ne gizlim kaldı nede hiç saklım

Hayalime geldi o kor dudaklım

Gönlümün goncası soldu zannettim

Hayatın filmini seyrettim gözle

Latifi anlatır derdini sözle

Ömrümü geçirdim baharla yazla

Geride ahretim kaldı zannettim

2003', 'Bir tuhaf oldum ben başım dönüyor Azrail kapıyı çaldı zannettim Gözümün ışığı sanki sönüyor O anda canımı aldı zannettim Nefesim kesildi kar...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zannettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-gurkal-gencay-s985y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '..kimlik kartım mavi değil miydi benim? 

*        

yüzümde bıyıklarım yok muydu

ve yok muydu sakalım.

sesim kalın,

gömleğimin düğmeleri, cebi

merdane usulü dikili değil miydi,

ve çişimi ayakta yapmıyor muydum.

sünnet olmuş,

askerlik yapmış,

şimdi sayısını da,yüzlerini de unuttuğum

onca kadına-kıza takılmış,

yüzlerce badireyi atlatmış,

ve bir o kadar belayı da savmamış mıydım.

bunların hepsi doğru; 

biliyorum.

mağrur,

ciddi,

ve yenilmez,

yaşamın sokaklarında

                                   yiğitçe koşturup duruyorum.

üstelik, nüfus kağıdım da mavi.

yani,bütün bunlara bakılırsa,

ben de erkekten sayılıyorum.

peki; 

o zaman,

adını söylediklerinde ben,

                                   niye böyle ağlıyorum?', '..kimlik kartım mavi değil miydi benim?  *         yüzümde bıyıklarım yok muydu ve yok muydu sakalım. sesim kalın, gömleğimin düğmeleri, ceb...', ARRAY['Türk Edebiyatı','Şiir','Gürkal Gencay']::text[], 8.5, '{"poet":"Gürkal Gencay","poet_slug":"gurkal-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mavi-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nesin', 'nesin-sair-ahrazi-pzche', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nesin? 

Bak,İyi bak,

Neredesin? 

Bir ayıbın ortasında mı,

Yoksa insanlığın yasında mı? 

Neredesin söyle,kimlerlesin? 

---bulamadım seni.

Deki,vaktim yok dostluğa/anlarım,

Anlamadığım/gönlünde mi yok üstâdım? 

..

..

Nesin? 

Kendine gel,gel ki

Kimim diyesin.

Âna esir düşen birimi,

Yoksa mert bir gönül eri mi? 

---bilemedim seni.

Yaşarsın amma sevip sevilmeden,

Neden şu bencillik kalp kırmak neden? 

..

..

Mâdem ki sözler beyhude,

Oku o vakit,boşsun dese de.

/Arzın hiddeti Arşa karşı değil,

Sallar kendini ancak arşı değil./', 'Nesin?  Bak,İyi bak, Neredesin?  Bir ayıbın ortasında mı, Yoksa insanlığın yasında mı?  Neredesin söyle,kimlerlesin?  ---bulamadım seni. Dek...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nesin-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zincir', 'zincir-ozkan-ozdogan-1uli8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Savaşa hayır; 

diye bağırıyor Beyazıt Meydanı.

Kaldırım taşları sökülüyor yerinden,

minareler eğiliyor,

ağaçlar yanıyor,

ve bulutlar dönüyor başları üzerinde

o binlerin..

Onbinlerin..

Sesleri vuruyor

çelikten ölümün demine..

Gözleri kamaşıyor hainlerin,

kan tutan elleri uyuşuyor...

Geç kalıyor çünkü

zincirin başındaki halka hedefine...', 'Savaşa hayır;  diye bağırıyor Beyazıt Meydanı. Kaldırım taşları sökülüyor yerinden, minareler eğiliyor, ağaçlar yanıyor, ve bulutlar dönüyor...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zincir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-yuksel-gemalmaz-j08ne', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gökten mavi topladım

daldan yeşil kopardım

şafaktan pembe çaldım

geceden siyah

bir süt beyaz üstüne serpiştirdim hepsini

karşima sen çıktın

ne hoş değil mi?', 'gökten mavi topladım daldan yeşil kopardım şafaktan pembe çaldım geceden siyah bir süt beyaz üstüne serpiştirdim hepsini karşima sen çıktın ...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Gemalmaz']::text[], 8.5, '{"poet":"Yüksel Gemalmaz","poet_slug":"yuksel-gemalmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-356-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim', 'kalbim-emin-baydil-zz2nx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her sabah uyanırken, yeniden vurur kalbim.

Bir düş kurarım; taze, yeni bir güne inat.

Tik-taklarını sayıp, her anında yaşarım.

Her ânı şu kalbimin, taktığı altın kanat.

Bulutlarda yüzer o, yağmurlarla ıslanır,

Bir bahar çiçeğinin yaprağına konunca.

Bir damla çiğdir kalbim, beni benden kıskanır,

Sabahla doğan günün, saçları dokununca.

Ey benim dar günümde yokuşlarda susamış,

Sevdikçe seven kalbim, ömre kös vuran kalbim! 

Demedim mi? Her bahar, güzel, fakat kısaymış

Baharı her geçenden, durmadan soran kalbim.', 'Her sabah uyanırken, yeniden vurur kalbim. Bir düş kurarım; taze, yeni bir güne inat. Tik-taklarını sayıp, her anında yaşarım. Her ânı şu ka...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalbim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '+Çiçekler Açan Yüzün', 'cicekler-acan-yuzun-zeki-ergin-166sy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'savursun bahar yeli

şarkılar söyleyen eteklerini

çiçekler açan 

saçların uçuşsun

yüzün ürpersin ılık rüzgarlarda

dallarda öten kuşlara inat

yüreğin 

en güzel sevda şarkıları söylesin

ben yalnızlık cinnetleri geçirirken

şarap kırmızısına çalmışken yüreğim

düğümlenir sözlerim

seni düşünür buğulanır gözlerim

_erenköy 4nis''04', 'savursun bahar yeli şarkılar söyleyen eteklerini çiçekler açan  saçların uçuşsun yüzün ürpersin ılık rüzgarlarda dallarda öten kuşlara inat ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cicekler-acan-yuzun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komşunun hikayesi', 'komsunun-hikayesi-ali-hamdi-eray-hqdh8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''İki ateş arasında''

Dinlerken eşinin son sözlerini,

Başı önüne eğik,

Bir hıçkırık düğümlendi hançerelerinde adamın,

Sevğilisi geçti gözlerinin önünden,

Sevgi dolu,şevkat dolu,ağlamaklı.

Ama o, susuyordu.

Evet diyordu kadın,

Kalbim senin,

Varlığım,ruhum,herşeyim senin,

Bir tanecik eşimsin sen benim,

Diyordu titrek sesiyle.

Ne kadarda mesuttuk,vaktiyle,

Yavrumuzun neşemizin kaynağı 

O küçücük evimizde,

Ne kadarda mesuttuk.

Ama şimdi,

Nicelerinin hayallerinde yaşayan,

Bir evimiz bir yuvamız var,

Her şeyimiz var,

Ama neye yarar,

Neye yarar,

İlğimiz başka başka.', '''İki ateş arasında'' Dinlerken eşinin son sözlerini, Başı önüne eğik, Bir hıçkırık düğümlendi hançerelerinde adamın, Sevğilisi geçti gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/komsunun-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey!', 'ey-celal-sahin-0t7ql', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey! Ellerinin sıcaklığını  hissedemediğim

Ey! Kadife yanaklarına dokunamadığım

Ey! Mavi gözlerinde yüzemediğim 

Ey! Siyah zülüflerini tarayamadığım

Ey! Derdini dert edinip paylaşamadığım

Ey! Teninin kokusunu  duyamadığım 

Ey! Yüreğimden sevgisini silemediğim

Sevda şehrine yolculuğun, mutluluk durağından geçsin dileğim.', 'Ey! Ellerinin sıcaklığını  hissedemediğim Ey! Kadife yanaklarına dokunamadığım Ey! Mavi gözlerinde yüzemediğim  Ey! Siyah zülüflerini taraya...', ARRAY['Türk Edebiyatı','Şiir','Celal Şahin']::text[], 8.5, '{"poet":"Celal Şahin","poet_slug":"celal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ey-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sihirli Bir Değneğim Olsa..!', 'sihirli-bir-degnegim-olsa-nazife-abayli-1k8bh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sihirli bir değneğim olsa,

Dokunuversem yerkürenin bir köşesine,

Küskünleri barıştırıversem,

Düşmanlıkları yok ediversem diyorum.

Bütün yüreklere sevgi ekip,

Tüm insanları gülümsetiversem sonra.

Açları doyurup,

Parasızların cebini dolduruversem.

Evsizlerin evi,işsizlerin işi,

Oluverse diyorum..

Nankörlükleri,ikiyüzlülükleri,

Yok ediversem.

Uzakları yakın edip,

Özlem duyan sevgililerin,

Gözyaşlarını siliversem,

Kavuşturuversem diyorum..

Sonra,bizim için kullansam,

Sihirli değneğimi.

Yanında oluversem örneğin,

Bir dokunuşla.

Ya da seni alıversem yanıma,

Doyasıya seviversem.

Seviversem diyorum..', 'Sihirli bir değneğim olsa, Dokunuversem yerkürenin bir köşesine, Küskünleri barıştırıversem, Düşmanlıkları yok ediversem diyorum. Bütün yüre...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sihirli-bir-degnegim-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öleceğim Özlemimden..! !', 'olecegim-ozlemimden-nazife-abayli-gvbmf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzün sardı,

Her yanımı....

Yine....

Hazan oldum....

Ağlamak geliyor içimden....

Hıçkıra hıçkıra,

Katıla katıla,

Ağlamak.....

Öleceğim özlemimden...

Nerdesin sen.....?', 'Hüzün sardı, Her yanımı.... Yine.... Hazan oldum.... Ağlamak geliyor içimden.... Hıçkıra hıçkıra, Katıla katıla, Ağlamak..... Öleceğim özlem...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olecegim-ozlemimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onunlayım Her An', 'onunlayim-her-an-zeki-ergin-daiww', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yazamayışım kağıtlara tutkularımı

rezilce yaşamaların bedbahtlığını

gözlerin göremeyişi

kırmızı gülleri

sarhoşça

güzelse soluk resimler

oluyorsam ağlamaklı

geçmişin derinliğinden gelen

bir sesi olmalı

işte beni bitiren 

o

_Çorlu Ekspres  25ekim1974 sayı:3682', 'yazamayışım kağıtlara tutkularımı rezilce yaşamaların bedbahtlığını gözlerin göremeyişi kırmızı gülleri sarhoşça güzelse soluk resimler oluy...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/onunlayim-her-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizlere', 'sizlere-ozkan-yildirim-nee39', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sizlere,

yıldızları bırakıyorum

Gece vakti güneşe,

Ateşlerini topladığım yıldızları.

Sizlere,

güneşi bırakıyorum

Her şafakta, 

Dünyaları aydınlatan  güneşi.

Sizlere,

Sevdalarımı bırakıyorum.

Insanlığın tarihinden beri var olan

                         

                                    / sevdalarını.

Sizlere,

Kavgamı bırakıyorum,

Spartaküs`le başlayan kavgamı.

Sizlere,

Gençliğimi bırakıyorüm,

Mapuslarla,

ayrılıklarla,

yenilgilerle demlenen gençliğimi.

Sizlere,

Düşlerimi bırakıyorum,

Düşlerim Haziran…

Temmuz`a özlem düşlerimi.

…………………………….

…………………………….', 'Sizlere, yıldızları bırakıyorum Gece vakti güneşe, Ateşlerini topladığım yıldızları. Sizlere, güneşi bırakıyorum Her şafakta,  Dünyaları ayd...', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sizlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayın Bakmayı Gökyüzüne', 'unutmayin-bakmayi-gokyuzune-ozkan-yildirim-r8i69', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşersem aklınıza

Ve gurbetteysem

Ve mapustaysam

Kaldırın başınızı; 

Yada,

Evinizdeyseniz,

Pencerenizden  uzatın gözlerinizi.

Veya,

Mapustaysanız,

Bir tünelcinin enerjisiyle

                                          /delin tavani.

Ve bakın.

Gökyüzündeki en parlak

/biz oln yıldızlara...', 'Düşersem aklınıza Ve gurbetteysem Ve mapustaysam Kaldırın başınızı;  Yada, Evinizdeyseniz, Pencerenizden  uzatın gözlerinizi. Veya, Mapustay...', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutmayin-bakmayi-gokyuzune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal Diyemem ki...', 'kal-diyemem-ki-halil-kesken-09izt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok acı gelecek gidişin bana

Beni de yanına, al diyemem ki

Engelde olamam mutluluğuna

Bu senin seçimin, kal diyemem ki

Sevdamın uğrunda ölmem gerekir

Kalbimi ikiye bölmem gerekir

Sevdanı kalbime gömmem gerekir

Bu senin seçimin, kal diyemem ki

Benim senden olan dileğim başka

Git, gitte her şeye yeniden başla

Dilim başka söyler, yüreğim başka

Bu senin seçimin, kal diyemem ki

Acılara karşi kurdum kalemi

Çoktan vurdum bile gönlüme gemi

Aşkın idamlıktır, kırdım kalemi

Bu senin seçimin, kal diyemem ki

Halil kesken                    17/07/2000   20:40', 'Çok acı gelecek gidişin bana Beni de yanına, al diyemem ki Engelde olamam mutluluğuna Bu senin seçimin, kal diyemem ki Sevdamın uğrunda ölme...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kal-diyemem-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım', 'yarim-alphan-dikmen-k8u1t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bölünüyorsam eğer ikiye

ve

sayısızsa gözlerin bir o kadar,

yarım sendedir bilinsin! 

gözlerine bakmışsan eğer birinin

ansızın,

ve gözlerinde göz izi varsa bir o kadar

yarım sende ölsün,silinsin!', 'bölünüyorsam eğer ikiye ve sayısızsa gözlerin bir o kadar, yarım sendedir bilinsin!  gözlerine bakmışsan eğer birinin ansızın, ve gözlerinde...', ARRAY['Türk Edebiyatı','Şiir','Alphan Dikmen']::text[], 8.5, '{"poet":"Alphan Dikmen","poet_slug":"alphan-dikmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyusam Yanağında', 'uyusam-yanaginda-zafer-zengin-etnika-860e3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Telaşlarımdan

uzak 

sevdim

seni

Ağır

ağır

çöktün

içime

Bak

kıpıradamıyor

tütüne

boğulan

gözlerim



Ağır 

ağır

saçların

saklanıyor

gövdeme

Bir uyusam yanağında..ölüm olur mu..! bir söyleseydin...

Her kilometrede senin düşünmem..Aklımı başıma toplar

İstanbul..İstanbul demezdim..Habersiz öperken canımı

kaçıp gitmezdim..İstanbul..istanbul demezdim..

Hoş geldin içime..Gamzelim..

Biliyorsun..Gündüz gözüyle sevmek yasak bana..Seni geceye saklıyorum anlasana

Nasıl öperdim seni..meraktayım hala..Ya beğenmezsen sıcaklığımı

Ya üşürsen içimde...

Gözlerinden öperim...

Duyuyormusun! 

4 Nisan 2004  '' İçimin Kitabı ''', 'Telaşlarımdan uzak  sevdim seni Ağır ağır çöktün içime Bak kıpıradamıyor tütüne boğulan gözlerim Ağır  ağır saçların saklanıyor gövdeme Bir ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/uyusam-yanaginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Bir Dil Sürçmesi', 'sen-bana-bir-dil-surcmesi-nilay-aksu-y0t0d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çözemediğim bir düğümdür yüzün 

gövdemdeki iz gizlediğim mühür 

kanırtan bir soru olup kendime 

seni sorup duruyorum 

-orda mısın? 

şimdi bu sen değil 

kendine yerleşmis bir yorgun gölge gibi 

hoyrat ellerde dolaşan bir unutuş öyküsü 

durma sökül ayazını içinde kar tutan öfkenin 

mermi ol 

vur devrik tümcelerimi 

de ki bütün anlamlar boş 

-sen bana bir dil sürçmesi 

yüzünü erittim yüzümde 

yüzün ki alazlı bir dikendi 

can çekirdeğimde 

‘geriye sadece kuytular kaldı! ’* 

(son dize) * Hilmi Yavuz', 'çözemediğim bir düğümdür yüzün  gövdemdeki iz gizlediğim mühür  kanırtan bir soru olup kendime  seni sorup duruyorum  -orda mısın?  şimdi bu...', ARRAY['Türk Edebiyatı','Şiir','Nilay Aksu']::text[], 8.5, '{"poet":"Nilay Aksu","poet_slug":"nilay-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-bana-bir-dil-surcmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Yolculuğu', 'i-stanbul-yolculugu-naci-orpak-o9y9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sayısız yolculuklar yaşadığım

                             -üç gün arası-

Uzun yollar aldığım zamandan kaçırdığım

                             -saatsiz ve sensiz-

Susturamadığım sevdalarımı boğduğum

                            -kansız bıçaksız-

İsatnbulun korkulası kapılarında

                              -onlar ki sayısız-

Her geçişimde seni hatırladığım

İşte İstanbul yolculuğum.......7/1/1984 22''02''''57''''''', 'Sayısız yolculuklar yaşadığım                              -üç gün arası- Uzun yollar aldığım zamandan kaçırdığım                           ...', ARRAY['Türk Edebiyatı','Şiir','Naci Orpak']::text[], 8.5, '{"poet":"Naci Orpak","poet_slug":"naci-orpak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-yolculugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi gözlü İSTANBUL', 'mavi-gozlu-i-stanbul-naci-orpak-pfjrg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman baksam daracık penceremden

Gece karanlığında sayısız....suskun....

Işık ve dert küpü pencerelerine

Bakaıp bakıp güldüğünü sanırım şaşkınlığıma

Mavi gözlü İstanbulum', 'Ne zaman baksam daracık penceremden Gece karanlığında sayısız....suskun.... Işık ve dert küpü pencerelerine Bakaıp bakıp güldüğünü sanırım ş...', ARRAY['Türk Edebiyatı','Şiir','Naci Orpak']::text[], 8.5, '{"poet":"Naci Orpak","poet_slug":"naci-orpak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mavi-gozlu-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Gel  (Bestelendi)', 'neredesin-gel-bestelendi-memet-zeki-ates-fp9ey', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sendin heyecanım,sendin hevesim,

Yolunu gözledim,dört yıl,dört mevsim.

Adını duyunca,İnan nefesim,

KESİLİR oldu neredesin gel.

....hadi gel kuşum

....kurban olmuşum

.... neredesin gel....

Boynu bükük açar,güller bağımda,

Ceylanlarda gezmez oldu dağımda.

Hüzün sol omuzda,keder sağımda,

ASILIR oldu neredesin gel.

 ....hadi gel kuşum

 ....kurban olmuşum

 ....neredesin gel....

Her yanım anıdır adını yazar,

Gün,gün eriyorum bak azar,azar.

Ha,öldü ölecek,aşkına mezar,

KAZILIR oldu neredesin gel.

 ....hadi gel kuşum 

 ....kurban olmuşum

 ....neredesin gel....

Gözümde kalmasın gelki muradım

Yer yüzün bitirip gökte aradım

Dertliler içinde benimde adım 

Yazılır oldu neredesin gel

.....hadi gel kuşum

.....kurban olmuşum

.....neredesin gel

Ne dizde derman,ne gözde fer''im

Nazlı yar emrinde garip neferim

Zekiyim basında acı haberim

Yazılır oldu neredesin gel

   hadi gel kuşum

   kurban olmuşum

   neredesin gel.', 'Sendin heyecanım,sendin hevesim, Yolunu gözledim,dört yıl,dört mevsim. Adını duyunca,İnan nefesim, KESİLİR oldu neredesin gel. ....hadi gel ...', ARRAY['Türk Edebiyatı','Şiir','Memet Zeki Ateş']::text[], 8.5, '{"poet":"Memet Zeki Ateş","poet_slug":"memet-zeki-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/neredesin-gel-bestelendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin İşgalde', 'yuregin-i-sgalde-mehmet-isik-1vvpe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğini işgal ettiğim için 

Senin affına sığınıyorum...

Biliyorum ki bu işgal 

Top ile tüfek ile yapılan bir işgal değil..

Sadece sevgi ile, 

Çiçek ile 

Ve muhabbetle yapılan bir işgaldir..

Ve bu işgal,

Yüreği senin izin verdiğin ölçüde

Ele geçirecektir..

Ve sanırım

Bu işgal

Sonsuza dek sürecektir...', 'Yüreğini işgal ettiğim için  Senin affına sığınıyorum... Biliyorum ki bu işgal  Top ile tüfek ile yapılan bir işgal değil.. Sadece sevgi ile...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Isik']::text[], 8.5, '{"poet":"Mehmet Isik","poet_slug":"mehmet-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yuregin-isgalde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim Ak Güvercinimdi..', 'o-benim-ak-guvercinimdi-mehmet-isik-q7z00', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güvercinler kapımda sıra sıraydı.. 

Buğday atardım, ekmek atar beslerdim.. 

Sonra su verir oynardım onlarla.. 

Uçmak istediklerinde kapıyı açardım.. 

Kimi zaman ak güvercin, 

Kimi zaman ak pençeli şahin olurlardı.. 

Ben seyrederken onlar çok uzaklara gider gelirlerdi.. 

Hiç aksamazdı dönüşleri.. 

Hep bir halka içinde döner dururlardı.. 

Tekrar konduklarında dünyayı fethetmiş gibi olurlardı.. 

Bir sevinç bir sevinç kaplardı gürültülerini. 

Ak güvercin,kınalı, şahin bakışlı birbirine karışırdı.. 

Ama içlerinde hep seçilen ak güvercindi... 

O benim ak güvercinimdi..', 'Güvercinler kapımda sıra sıraydı..  Buğday atardım, ekmek atar beslerdim..  Sonra su verir oynardım onlarla..  Uçmak istediklerinde kapıyı a...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Isik']::text[], 8.5, '{"poet":"Mehmet Isik","poet_slug":"mehmet-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/o-benim-ak-guvercinimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-ali-osman-tasci-qjpel', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen yoksun diye

Yüreğim bile terketti beni

Kör bir zindandayım

Her taraf bana sağır

Sen gittin diye 

Yüreğim de peşinden gitti

Dünyayı peşine taktım

Ne seni buldular

Ne de kalbimi

Sen yoksun diye 

Herkes bırakıp gitti

Seneler okşadı saçlarımdan

Martılar bile üzülüp ağladılar arkandan

Bak,şarkımız çalıyor

Her gün onu dinliyorum

Üzerinde ismimin yazdığı plaktan

Sigaramı bile kıskanırdın

Hiç düşmezdi diye dudaklarımdan

Sana gelmek istedim

Prangalar tuttu ayaklarımdan

Sen yoksun yine

Elimde bir kadeh şarap

Aklımda son sözlerin

Kadehler değil beni sarhoş eden

Beni sarhoş eden 

GÖZLERİN', 'Sen yoksun diye Yüreğim bile terketti beni Kör bir zindandayım Her taraf bana sağır Sen gittin diye  Yüreğim de peşinden gitti Dünyayı peşin...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Taşçı']::text[], 8.5, '{"poet":"Ali Osman Taşçı","poet_slug":"ali-osman-tasci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gozlerin-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şımarma', 'simarma-zafer-zengin-etnika-53bfd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimseyi

Şımartmadı

Ellerim...

Sevebileceğim

Kadar

Sevdi...

Seni biraz fazla...

4 Nisan 2004  '' İçimin Kitabı ''', 'Kimseyi Şımartmadı Ellerim... Sevebileceğim Kadar Sevdi... Seni biraz fazla... 4 Nisan 2004  '' İçimin Kitabı ''...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/simarma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-tayyib-atmaca-4f3cg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'daha ten çıkmadan kentin dışına

başını alır da gider yalnızlık

kalabalıklarda yalnız başına

karanlık koynunda yatar yalnızlık

şekile kalıba oturmaz boyu

kabarır köpürür azar gün boyu

sofraya varmadan ekmeği suyu

can ocakta kaynar tüter yalnızlık', 'daha ten çıkmadan kentin dışına başını alır da gider yalnızlık kalabalıklarda yalnız başına karanlık koynunda yatar yalnızlık şekile kalıba ...', ARRAY['Türk Edebiyatı','Şiir','Tayyib Atmaca']::text[], 8.5, '{"poet":"Tayyib Atmaca","poet_slug":"tayyib-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlik-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyiki Nursun', 'i-yiki-nursun-turgay-kadiroglu-amfpb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen,

 yarına adanmış visalin 

 rahminde can tutan,

 kaf dağına sürülmüş alevleri ısıtan

 vuslat nehrini hüzünle paklayan nur,

 sanır mısın bu şehrin sularında

 akar ürkek ve titreyen bulut...

 nasıl ki ellerinde tutuşur karanfil

 doğunun gökleri yanar,

 nasıl ki sabahlar seninle uyanır

 gecenin örtüsü yıldız yıldız parıldar,

 gözlerinle bakar martılar

 sen gör diye aydan gelir yakamozlar,

 bu şehirde her eylül

 bulutlar değil,

 bilmem kaç güneş ağlar...

 sen,

 iyiki varsın,

 iyiki nursun

 aşk diye doğansın,

 tutun kalemine,

 derinlere bırak yüreğini

 istanbul ellerine doğsun...', 'sen,  yarına adanmış visalin   rahminde can tutan,  kaf dağına sürülmüş alevleri ısıtan  vuslat nehrini hüzünle paklayan nur,  sanır mısın b...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iyiki-nursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Topal Gazi Dedem  ( Gerçek yaşamdan )', 'topal-gazi-dedem-gercek-yasamdan-atilla-yildiz-0vqeg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En güzel anlatır Çanakkale''yi Mehmet Akif

Yapamazlar o gözlemi gitse binlerce kaşif

Amacım değil,kubbenin üstüne püskül takmak

İsterim sadece bir örnek,bir anı yaşatmak...

Ne muazzamdır Çanakkale Harbi herkes bilir

Akif  kadar yapılamaz anlatım,ne de tasvir

Dilerim Allah''tan tekrar göstermesin o devir

Düşersek gaflete,zevke korkarım geri gelir...

Elbette vardır daha binlerce anı hatıra

Hepsi değerli birbirinden ala ve müstesna

Zaten hepsi yazıldı Türk Milleti''nin şanına

Yeter ki unutulmasın o an kalsın yarına...

Dedem de her Türk genci gibi yazılır askere

Bırakır zevc ve iki kızını götürüp köye

Arkadaşları dağılır çeşit çeşit cepheye

Kendi gider bilmeden dönüşü Çanakkale''ye...

Nefer olur kendisi Elli Yedinci Alay''a

Kahramanca koşar herkes gibi ordan oraya

Şehitler gibi yükselmek ister arş-ı alaya

Ne yazık ki çatar dizanteri denen belaya...

Kaldırırlar sahra hastanesi denen çadıra

Yatar günlerce ter içinde ayıla bayıla

Rüyalar görür melekli aylı yormaz hayıra

Meğer şehit rütbesi verilmiş tüm Alay''ına...

Zaferle bitirir Türk askeri muazzam harbi

Yüzbinlerce şehit vermişiz subayı neferi

Alıkoymuş şehadetten dedemi dizanteri

Sağ kalan askerler alınırlar cepheden geri...

Cephe bir değil ordumuz çarpışıyor her yerde

Dedem sırtında kaput yoldadır kara trenle

Bulgaristan Romanya derken ulaşır bir gece

Roman Rus hududunda Galiçya denilen yere...

Gönderirler cepheye Alman müttefik düşman Rus

Sebebi sorulmaz böyle sadakat Türk''e mahsus

Bilir ki vatan için çarpışmak izzet-i nefis

Ancak böyle bitecek tüm vatanda günler makus...

Tanışır neferler tümü Anadolu çocuğu

Şarapnel düşer parçalanır dedemin topuğu

Kendi bayılır,kurtarır arkadaşı Çorum''lu

Ayak kopuk,görünür kağnı ile Bükreş yolu...

Altı ay kalır Bükreş''in Alman hastanesinde

Ayağını keserler dizinden gurbet elinde

Çorba ekmek yer,et yemez domuz eti var diye

İyileşir gönderirler İstanbul''a trenle...

Kemik iltihabı,takma ayak,bir yılda öyle 

Gelir Ulukışla''ya bin dokuz yüz yirmi birde

Refakatçı asker ve eşekle döner evine

Yedi yılda kavuşur ayaksız memleketine...

Bağlanır takavit maaşı verirler madalya

Geçirir kalan ömrünü gazi tahta ayakla

Bin dokuz yüz elli yedide verildi toprağa

Cennetlik olsun diye dua ederim Allah''a...

Zevc:......Erkekler için eş

Kaput:....Asker paltosu

Müttefik:.İşbirliği içinde olan

Takavit:..Emekli

Makus:...Kötü', 'En güzel anlatır Çanakkale''yi Mehmet Akif Yapamazlar o gözlemi gitse binlerce kaşif Amacım değil,kubbenin üstüne püskül takmak İsterim sadec...', ARRAY['Türk Edebiyatı','Şiir','Atilla Yıldız']::text[], 8.5, '{"poet":"Atilla Yıldız","poet_slug":"atilla-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/topal-gazi-dedem-gercek-yasamdan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bat-tı', 'bat-ti-ozkan-ozdogan-sknkp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş battı.. 

ve akşamın çanları çalmaya başladı. 

En sevdiği oyundur günün, 

beni öldüresiye karanlıkta bırakmak. 

Gölgeler silinir, 

yalnızlığı büyür 

yok olmaya gün sayanların. 

Bütün maviler solar, 

en son kızıllıklar görünür ufukta, 

umutlardan arta kalan..', 'Güneş battı..  ve akşamın çanları çalmaya başladı.  En sevdiği oyundur günün,  beni öldüresiye karanlıkta bırakmak.  Gölgeler silinir,  yaln...', ARRAY['Türk Edebiyatı','Şiir','Özkan Özdoğan']::text[], 8.5, '{"poet":"Özkan Özdoğan","poet_slug":"ozkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bat-ti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler 2', 'dortlukler-2-safure-yildirim-mscgt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçi boş bir kabım

ne koysan alacağım

senin gibi birine

yeniden sunacağım

kapkaranlık geceyim

bir yıldız aradığım

ay yol gösterirse

sabaha varacağım.

bilinmeyen gerçeğim

benim öğrenmek istediğin

her yolun sonunda

seni bekleyeceğim...

26.6.03  İlkim', 'İçi boş bir kabım ne koysan alacağım senin gibi birine yeniden sunacağım kapkaranlık geceyim bir yıldız aradığım ay yol gösterirse sabaha va...', ARRAY['Türk Edebiyatı','Şiir','Safure Yıldırım']::text[], 8.5, '{"poet":"Safure Yıldırım","poet_slug":"safure-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dortlukler-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyüm Benim', 'koyum-benim-atilla-yildiz-6zmno', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah o yıllar köyümde geçen

Tüter burnumda buram buram

Mis kokar toz toprak

İster sulak ister çorak

Buğday,burçak,arpa,çavdar

Bereket dolu o tarlalar

Doğup büyüdüğüm

Sarı öküzle harman sürdüğüm

Dağlarında koyun güttüğüm

Genç olup askere gittiğim

Atalarımı toprağa verdiğim

Anılarımı gömdüğüm

Unutulmaz köyüm benim', 'Ah o yıllar köyümde geçen Tüter burnumda buram buram Mis kokar toz toprak İster sulak ister çorak Buğday,burçak,arpa,çavdar Bereket dolu o t...', ARRAY['Türk Edebiyatı','Şiir','Atilla Yıldız']::text[], 8.5, '{"poet":"Atilla Yıldız","poet_slug":"atilla-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/koyum-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusula', 'pusula-i-brahim-ozcan-6zf9u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Burası Çukurova olmalı...

Şaşırdım pusulamı

Buralara kar yağmayalı

Unuttum adını

Unutmusum adını

Buralara kar yağmayalı

Şaşırdım pusulamı

Burası Çukurova olmalı...

2002/Adana', 'Burası Çukurova olmalı... Şaşırdım pusulamı Buralara kar yağmayalı Unuttum adını Unutmusum adını Buralara kar yağmayalı Şaşırdım pusulamı Bu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/pusula-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yare Selam (Şarkı sözü)', 'yare-selam-sarki-sozu-atilla-yildiz-esqzt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yare selam salarım

Bilmem neden gidemez

Aşık oldum yanarım

Bilmem neden sönemez

Gülerken hep ağlarım

Bunu kimse bilemez

Sensin bunun sebebi

Kalbim sana doyamaz

Gülerken hep ağlarım

Bunu kimse bilemez', 'Yare selam salarım Bilmem neden gidemez Aşık oldum yanarım Bilmem neden sönemez Gülerken hep ağlarım Bunu kimse bilemez Sensin bunun sebebi ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Yıldız']::text[], 8.5, '{"poet":"Atilla Yıldız","poet_slug":"atilla-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yare-selam-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda''ın Son Treni', 'veda-in-son-treni-i-brahim-ozcan-4pta4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Firardaydı kolumdaki yedi kazık sırmalar 

Kıvranırken şehvetten 

Hüznün koynundaki hafif - meşrep raylar 

Yıldızlar doğrardı 

Vedanın son treninde. 

Kondüktörün, meşrutiyet mirası çapraz makası 

Arz çamurdu, gök de pas 

Bir tek bana kısmetmiş yokluğun 

Ey yıldızını elletmemiş, su yeşili atlas! .. 

21.03.2004 

Adana - Mersin Treni', 'Firardaydı kolumdaki yedi kazık sırmalar  Kıvranırken şehvetten  Hüznün koynundaki hafif - meşrep raylar  Yıldızlar doğrardı  Vedanın son tr...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/veda-in-son-treni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-gulden-karabudak-ncot8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gel, sevdamın ince sızısı

gel, gecemin siyah yarısı

gel, mavilerimin tercümanı

gel,sende kalmış içimin darası

gel,yeminlerini bozarak

gel, canıma can katarak

Kandillerimi yakarak gel...

Evrenin sonsuzluğuma ışık olsun

Gel! ! !', 'gel, sevdamın ince sızısı gel, gecemin siyah yarısı gel, mavilerimin tercümanı gel,sende kalmış içimin darası gel,yeminlerini bozarak gel, c...', ARRAY['Türk Edebiyatı','Şiir','Gülden Karabudak']::text[], 8.5, '{"poet":"Gülden Karabudak","poet_slug":"gulden-karabudak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gel-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derinlerden', 'derinlerden-ozgur-arslan-11036', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedenki, tüm bana  bütün hüzünler

neden beni bulur ayrılıklar

sana alışmışken neden gitmeler

duygular dinlermi hiç yasağı.

Bana bütün engelleri sunma

bana caz maz, naz hiçmi hiç yapma

yüreğinle beraber koş ama

seni seveni artık çok yorma.', 'Nedenki, tüm bana  bütün hüzünler neden beni bulur ayrılıklar sana alışmışken neden gitmeler duygular dinlermi hiç yasağı. Bana bütün engell...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arslan']::text[], 8.5, '{"poet":"Özgür Arslan","poet_slug":"ozgur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/derinlerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe....', 'serce-hurrem-yalcin-7jusa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ökselendi serçe

Hapsoldu kafese....

Öfkelendi serçe

Vurdu kendini

Telden tele....

Hüzün dedi 

Serçe....

Esaret dedi

Serçe...

Esaret çok zor...

Hüzünlendi serçe

Vurdu kendini telden tele....

Her vuruş kesti sesi soluğu

Kırıldı kanadı kolu

Sinesi kan gölü

Tele her vuruşunda ağladı kanla

Damla damla

Sonunda dayanamadı

Güçsüz sinesi parçalandı

Gide gele tellerin arasında

Düşüverdi yere

Kınalı kanatları, 

Hür tüyleri

Sere serpe her yerde

Boncuk gözleri asılı kaldı....

Pencereden giren

Taze Baharda.....

04.04.2004', 'Ökselendi serçe Hapsoldu kafese.... Öfkelendi serçe Vurdu kendini Telden tele.... Hüzün dedi  Serçe.... Esaret dedi Serçe... Esaret çok zor....', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/serce-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR BAŞlMA...', 'bi-r-baslma-baki-son-wirt4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yetti mi bana ettiğiniz.? 

Yıktınız üzerime, 

_____________Dertlerinizi

Yetti mi bana ettiğiniz.? 

Bir başıma....! ! ! 

Yalnız bırakıp gittiniz.! 

Kentler dolu,dolu şimdi

Dolu,dolu tüm insanlar.

Belli ki...

Unutmak istiyorlar

_______________Birşeyleri.! 

Yaşamak...

__________Var olmak

Ya da

__________Ölmek gibi

Unutmak istiyorlar

_______________Herşeyi.! 

Tüm doğruları örtüp,

_______________Dertleri 

Yok etmiş gibi

Koskoca,bir nehirde 

________________Damlalar gibi

Ve

Sonsuz,gökyüzünde

_______________Kuşlar gibi

Hür sanıp kendilerini...! 

Unutmak istiyorlar...

Yokken bir sebep ortada

Yaşamak...

Ve ölmek gerçeği.! 

Ve tüm dertleri,silkeleyip

____________________Kurtulmak,

Bir rüya aleminde...! 

Yaşamak

________İstiyorlar...

Doğru mu bana ettiğiniz.? 

Yıktınız üzerime, 

_____________Dertlerinizi

Doğru mu bana ettiğiniz.? 

Yalnız bırakıp gittiniz.! 

_____________   Bir başıma....! ! !', 'Yetti mi bana ettiğiniz.?  Yıktınız üzerime,  _____________Dertlerinizi Yetti mi bana ettiğiniz.?  Bir başıma....! ! !  Yalnız bırakıp gitti...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-baslma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedim ki', 'dedim-ki-guler-ilgaz-m9t73', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dedim ki

Tomurcuğum

Renklerimin, kokumun

Şeklimin içinde

Saklı olduğu

Dedim ki

Su damlasıyım

Akan, duran,

Köpüren, vuran

Dedim ki

Sesim

Sessizliğin içinde

Gözyaşına

Ya da kahkahaya

Karışan

Dedim ki

Nefesim

Alan, veren

Ilık ılıkken

Bir anda kasırgaya

Dönüşen

Dedim ki tamam

Boşluğum yine

Dedim ki

Boşluğun içinden

Varolan

Yaratan 

Diyen kim? 

Ben miyim? 

Sen misin? 

O mu?', 'Dedim ki Tomurcuğum Renklerimin, kokumun Şeklimin içinde Saklı olduğu Dedim ki Su damlasıyım Akan, duran, Köpüren, vuran Dedim ki Sesim Sess...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dedim-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstadım', 'ustadim-guler-ilgaz-lsc2v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üstadım

Al beni

Evir, çevir

Tüm korkularıma rağmen

Sen korkma

Korkularımı, güvene

Güvenimi, teslim olmaya

Çevir

Çevir ki

Tavanları, duvarları

Bir görüp ellerinde

Yürüyebileyim

Güvenle senin ellerinde

Uçabileyim', 'Üstadım Al beni Evir, çevir Tüm korkularıma rağmen Sen korkma Korkularımı, güvene Güvenimi, teslim olmaya Çevir Çevir ki Tavanları, duvarlar...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ustadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağ bağlasa da', 'bag-baglasa-da-guler-ilgaz-u8433', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bağ bağlasa da

Çözülmez görülmez

Bağla bağla ki

İçinde

Eriyip

Su gibi içinde

Akarken sudan yoğun

İçimde

Çözülmeden, görülmeden

Bileyim

Diyebileyim ki

Varlığım bütündür

Ne denli çözülür

Görülürse de

Varlığımın içinde', 'Bağ bağlasa da Çözülmez görülmez Bağla bağla ki İçinde Eriyip Su gibi içinde Akarken sudan yoğun İçimde Çözülmeden, görülmeden Bileyim Diyeb...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bag-baglasa-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Surlarım', 'surlarim-zafer-zengin-etnika-30w0f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Surlarım

Dayanmıyor

Teslim olacağım

Bu sene

Gülümseyip gelene...

İyot kokluyorum...

Yalnızım

Sahile saplıyorum

Şarap şişesini

O karanlıkta

Denizkızı gelir diye

Umud ediyorum...

Yakıyorum

Sigaramın zırhını

Şehir benden habersiz

Ben senden habersiz

Gedikler açıyorum ellerime...

Yazmasam ölüm geliyor

Sen ölümden habersiz...

4 nisan 2004  '' İçimin kitabı ''', 'Surlarım Dayanmıyor Teslim olacağım Bu sene Gülümseyip gelene... İyot kokluyorum... Yalnızım Sahile saplıyorum Şarap şişesini O karanlıkta D...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/surlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Sen Hali', 'askin-sen-hali-i-brahim-ethem-bingul-wzpzy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkın ben hali varmış

Ben geçeli çok oldu

Aşkın ben halinde...

...kaybolmuş hüsranlı senler varmış

Ben hüsranı unutalı çok oldu

Ben sende,seni buldum

Aşkın bende,ben yoktum

Ben sende aşkı buldum

Aşkın bende seninle yoktum

Ben aşkın sen haliyim...', 'Aşkın ben hali varmış Ben geçeli çok oldu Aşkın ben halinde... ...kaybolmuş hüsranlı senler varmış Ben hüsranı unutalı çok oldu Ben sende,se...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askin-sen-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuyruksuz Maymun', 'kuyruksuz-maymun-hasan-huseyin-ozak-3v7cg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapkara bir karanlığın en orta yerinde,

kuyruksuz bir maymun

Elindeki pisliğini sürerken suratına

daha çok benzemekte en son nesli insana', 'Kapkara bir karanlığın en orta yerinde, kuyruksuz bir maymun Elindeki pisliğini sürerken suratına daha çok benzemekte en son nesli insana...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kuyruksuz-maymun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lunapark', 'lunapark-hasan-huseyin-ozak-x64a3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lunapark ne güzeldir değil mi ? 

Atlı karıncılarla, çarpışan arabalarla,

babandan kopardığın üç beş kuruş harçlığına dokunmadan

Veli''nin oğluyla beraber', 'Lunapark ne güzeldir değil mi ?  Atlı karıncılarla, çarpışan arabalarla, babandan kopardığın üç beş kuruş harçlığına dokunmadan Veli''nin oğl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/lunapark-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz', 'cikmaz-rukiye-selimoglu-i32ed', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne diye biraraya geldikki tekrar? 

Ne faydası var? 

Daha söylenenler unutulmamışken...

İkimizde bu kadar  gururlu,ikimizde bu kadar inatçı iken...

İlk defa karşımda tespih sallıyosun...

Ve ilk defa; ,

Bacak bacak üstüne atmış,karşında oturuyorum...

Şimdiden belli ne kadar kırıcı olacağı..

bütün yılları kırıp yıkacağı....

Tavrın net: ''Ben ARTIK onu seviyorum''...

Çığlık çığlığa bir suskunluk var havada...

Kalbim kırılmış mırıldanıyor sessiz sessiz...

Aşkta ARTIK olurmu? ? 

İki sene birini sevip,ertesi gün diğeri sevilebilir mi? 

Varsa böyle birşey..banada öğret ne olur...

bu son isteğim...söz...

Yarın.....

Aşksız kalmayı sevmek istiyorum...', 'Ne diye biraraya geldikki tekrar?  Ne faydası var?  Daha söylenenler unutulmamışken... İkimizde bu kadar  gururlu,ikimizde bu kadar inatçı i...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Selimoğlu']::text[], 8.5, '{"poet":"Rukiye Selimoğlu","poet_slug":"rukiye-selimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cikmaz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanım', 'vatanim-serafettin-keskinoglu-t5dkt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Azmış mahlûkların, sözüne uyup

Doğru giden yoldan sapanlar olur.

Herşeyi yaratan Allah''ı koyup

Lenin''e Engels''e tapanlar olur. 

Göklere uzanan minârelerin,

Batar gözlerine hâinlerinin

Mü''minlerle dolan Câmilerinin

Avlusuna bomba atanlar olur... 

Sana kurban olsun bu tatlı canım,

Kanısın, canısın şehit atamın,

Vatanım, vatanım, güzel vatanım,

Korkarım bir pula satanlar olur... 

Sabret, Keskinoğlu, bekle yarını

Uçuşan bolşevik baykuşlarını

Paça-parça edip yuvalarını

Bir gün kanadından tutanlar olur...', 'Azmış mahlûkların, sözüne uyup Doğru giden yoldan sapanlar olur. Herşeyi yaratan Allah''ı koyup Lenin''e Engels''e tapanlar olur.  Göklere uzan...', ARRAY['Türk Edebiyatı','Şiir','Şerafettin Keskinoğlu']::text[], 8.5, '{"poet":"Şerafettin Keskinoğlu","poet_slug":"serafettin-keskinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vatanim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni andım ya..', 'seni-andim-ya-rukiye-selimoglu-dadq2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başım ağrıyor,korkuyorum ve üşüyorum...

İşte yine başlıyor karanlıklar...

Sen anıldın ya,gözlerim kapanıyor..

Uyku mu? ölüm mü? bu üzerime çöken..

Yoksa sen mi? 

Bu duyguyu kim anlıyabilir ki? ? 

Olanlar karşısında kayıtsız kalmak..

Gözlerinin açık kalmaktan sızlaması...

Ağzının zamplıymış gibi açlımamısı..

Güçlü olmaya çalışmak kaç kişinin erdemi? 

Yada...

Gönlünce yağmura bulanmak...

Seni andım ya..

Sağım.. 

Solum....

Acı!', 'Başım ağrıyor,korkuyorum ve üşüyorum... İşte yine başlıyor karanlıklar... Sen anıldın ya,gözlerim kapanıyor.. Uyku mu? ölüm mü? bu üzerime ç...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Selimoğlu']::text[], 8.5, '{"poet":"Rukiye Selimoğlu","poet_slug":"rukiye-selimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-andim-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-serafettin-keskinoglu-hxgtv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eyy! .. kan kırmızı

Ayyıldızlı bayrağım,

Asırlarca dalgalandın

Ebediyyen dalgalan,

Ben yokken de sen vardın,

Senin gölgende doğdum

Senin gölgende yaşıyorum.

Seninle bağımsızım

Seninle hürüm,

Yeter ki sen; 

Şanla şerefle dalgalan

Ölsem de gölgende

Rahat uyurum...', 'Eyy! .. kan kırmızı Ayyıldızlı bayrağım, Asırlarca dalgalandın Ebediyyen dalgalan, Ben yokken de sen vardın, Senin gölgende doğdum Senin göl...', ARRAY['Türk Edebiyatı','Şiir','Şerafettin Keskinoğlu']::text[], 8.5, '{"poet":"Şerafettin Keskinoğlu","poet_slug":"serafettin-keskinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bayragim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha genci vardır', 'daha-genci-vardir-zafer-zengin-etnika-b5xz7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her

zaman

daha 

genci 

vardır

Hayatımızı

Parçalayan...

Gücü

Olandır

Ayakta

kalan...

Gideceğimiz yolda belki bir gün karşılaştığımızda

Toplayıp burnuna sürdüğümüz o güllerin hatırına

Selam diyeceğiz..Gözlerimiz gülümserse..içimizdeki güç

işte bu diyeceğiz..

4 Nisan 2004 '' İçimin kitabı ''', 'Her zaman daha  genci  vardır Hayatımızı Parçalayan... Gücü Olandır Ayakta kalan... Gideceğimiz yolda belki bir gün karşılaştığımızda Toplay...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daha-genci-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-serafettin-keskinoglu-wu13d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mektubum gecikince unuttu sanma anam, 

Amca başka, dayı başka, hala başkadır anam. 

Sen unuttu deselerde buna inanma anam, 

Çoluk başka, çocuk başka, ana başkadır anam. 

Beni yoktan bu dünyaya, getiren sensin anam, 

Yiyemezken yemeğimi, yediren sensin anam, 

Giyemezken elbisemi giydiren, sensin anam, 

Ben ağlarken acı duyar, gülsem gülersin anam. 

Sen ninniler söyleyerek, beni uyuttun anam, 

Bilmez iken yürümeyi beni yürüttün anam, 

Küçüktüm ufacıktım beni büyüttün anam, 

Benim huyum ve ahlâkım, senin mayandır anam. 

Senin sevginle doluyum, başka sevgiyle dolmam, 

Sen yapraksın ben çiçek, sen oldukca ben solmam, 

Üç şey vardır bu Dünyada: O olmazsa ben olmam, 

Biri VATAN, biri BAYRAK, biri ANA''dır ANAM! ..', 'Mektubum gecikince unuttu sanma anam,  Amca başka, dayı başka, hala başkadır anam.  Sen unuttu deselerde buna inanma anam,  Çoluk başka, çoc...', ARRAY['Türk Edebiyatı','Şiir','Şerafettin Keskinoğlu']::text[], 8.5, '{"poet":"Şerafettin Keskinoğlu","poet_slug":"serafettin-keskinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anam-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tefekkür', 'tefekkur-serafettin-keskinoglu-obbvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonsuzluk içinde bir mâvi kubbe 

Bir lâmba ortada yanar durmadan, 

Nakkaş-ı Ezelî''nin yaptığı tipte 

Boşlukta bir hâne döner durmadan. 

Misafirhânedir o hâne bize 

Yıldızlar kıvılcım ay pervânedir, 

Gelenler hep gitmiş kalır mı bize 

Bu akış içinde gaflet neyedir? 

Gelenler eli boş gelmiyorlar mı, 

Getirdi mi ağacın fihristesini? 

Elinde bir tohum çekirdek var mı, 

Kim temin ediyor maişetini? 

Niçin tükenmiyor bu yenen rızık? 

Bir tohum tonlarca yemiş getirir, 

Bir dâne vagonlar dolusu azık, 

Düşündün mü, bunlar nereden gelir? 

Kuru çıplak daldan çiçek açtıran, 

Zehirli sinekten bal yediren kim? 

Kim elsiz böceğe ipek yaptıran, 

Bunca hizmet kime, emir veren kim? .. 

Felâh''a götüren doğru yol varken, 

Çıkmaz sokaklarda kıvranmak neden? 

Güneş kadar parlak hakikat varken, 

Görmek istemeyip göz yummak neden? 

Ey, yolcu! Nereden-nereye böyle? 

Şaşırma kendini bul doğru yolu, 

Var mıdır, başka Hak, doğru yol: Söyle? 

KUR''AN va''zediyor en doğru yolu! ..', 'Sonsuzluk içinde bir mâvi kubbe  Bir lâmba ortada yanar durmadan,  Nakkaş-ı Ezelî''nin yaptığı tipte  Boşlukta bir hâne döner durmadan.  Misa...', ARRAY['Türk Edebiyatı','Şiir','Şerafettin Keskinoğlu']::text[], 8.5, '{"poet":"Şerafettin Keskinoğlu","poet_slug":"serafettin-keskinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tefekkur-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerde Çadır Hapsi', 'askerde-cadir-hapsi-serafettin-keskinoglu-dwbws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yirmidört Mayıs bindokuzyüzaltmışiki; 

Hiç suçum yoktu bugün benim, halbuki, 

Sabah saat sekizde çıkmıştık, içtimaya

Üç saf olup dizilip bakmıştık hep hizaya. 

Batarya komutanı Teğmen Zafer Orus''du,

Talimata aykırı gidene bozulurdu. 

Tekmil alınca baktım, çok çatıktı kaşları,

Sıra''çıl komutuyla muayene başladı. 

O anda bir arkadaş, çıktı geldi oraya

Yanımıza gelip de katılmadan sıraya, 

Teğmen gördü, seslendi: -''Nereden geliyorsun? 

Devriyesiz nöbeti nasıl terk ediyorsun! ? . 

Haberim yoktu ama ben idim devriyesi,

Yiyeceğiz sopayı yoktur artık çaresi. 

''-Hani senin devriyen; nerede? '' Diye sordu.

İki yumruk dört tokat çenemize kondurdu. 

Daha bitmedi ceza, bakın devam ediyor,

Çadırlar kucaklarda, kurulmaya gidiyor. 

Ne olur vazifeyi tam lâyıkıyle yapsak,

Mapusluk çok zor imiş, üç gün bitse de çıksak. 

Kim bu cezayı gören diye olursa soran; 

Onbaşı Şerafettin, er Ömer Demirkıran...', 'Yirmidört Mayıs bindokuzyüzaltmışiki;  Hiç suçum yoktu bugün benim, halbuki,  Sabah saat sekizde çıkmıştık, içtimaya Üç saf olup dizilip bak...', ARRAY['Türk Edebiyatı','Şiir','Şerafettin Keskinoğlu']::text[], 8.5, '{"poet":"Şerafettin Keskinoğlu","poet_slug":"serafettin-keskinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/askerde-cadir-hapsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırsat', 'firsat-serafettin-keskinoglu-estzd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sarı kız sarışın kız! Dur, 

Sana bir kaç sözüm var: 

Niçin devam etmiyor 

Eski günlerimiz? 

Hani seninle, 

Bir odada ikimiz 

Derse çalışırdık! 

Sen bana sual sorar, 

Ben sana cevap verirdim, 

Kaleminin ucunu açar, 

Hesabını yapar, 

Yazını yazıverirdim! 

Sonra, El-ele tutar 

Hoplar zıplardık, 

Diz-dize oturur 

Göz-göze gelirdik, 

Belkide o zaman 

Çocukca sevişirdik! .. 

Niçin şimdi yine 

Öyle değiliz, 

Niçin devam etmiyor 

Eski günlerimiz? .. 

Çağırdığım zaman 

Yanıma gelmiyorsun, 

Niçin benden kaçıyorsun? 

Niçin beni görünce 

Kaşlarını eğip geçiyorsun? .. 

Darıldın mı yoksa bana? 

Darılacak bir şey söylemedimki 

''''Seviyorum'''' dedim 

Sevmek kötü bir şey mi? .. 

Konuşsana kız! 

Niçin konuşmuyorsun, 

Birşey soracak diye mi? 

Arılar mı kondu diline? 

Demek öyle; 

Fırsat geçti eline! .. 

Eğme gözünü kaşını, 

Doğrultsana başını, 

Çözüversene bilmecemi, 

Demek şimdi; 

Fırsat sende mi? .. 

Anladım, anladım.', 'Sarı kız sarışın kız! Dur,  Sana bir kaç sözüm var:  Niçin devam etmiyor  Eski günlerimiz?  Hani seninle,  Bir odada ikimiz  Derse çalışırdı...', ARRAY['Türk Edebiyatı','Şiir','Şerafettin Keskinoğlu']::text[], 8.5, '{"poet":"Şerafettin Keskinoğlu","poet_slug":"serafettin-keskinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/firsat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Susuşlarım', 'benim-sususlarim-yildiz-ark-7phzv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim susuşlarım bil ki...

Acı bir yalvarıştır

Bil ki hırçınlıkla ördüğüm başına

Azaptan bere

O yokluğundandır...

Sen yine anlama beni 

               ama yargılama.

                            Söyletme

                                      anla....', 'Benim susuşlarım bil ki... Acı bir yalvarıştır Bil ki hırçınlıkla ördüğüm başına Azaptan bere O yokluğundandır... Sen yine anlama beni      ...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Ark']::text[], 8.5, '{"poet":"Yıldız Ark","poet_slug":"yildiz-ark","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benim-sususlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızlar Yüreğim Derinden...', 'sizlar-yuregim-derinden-nazife-abayli-6b4vi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığında,

Yine düştü,

Turuncu ışıklar,

Marmara''nın kapkara sularına.

Karşı kıyıdan,

Kartal''dan kalkan,

Yirmi bir otuz vapuruda,

Yanaştı Yalova limanına.

Türküler dile geldi şimdi,

Hüseyin''in gitarında,

Barış''ın bağlamasında.

Çağrıştılar ikisi birden,

''Gitme,aklım sende kalır,

Uyuyamam geceleri'' derken,

____ sen....

________gelirsin.....

_____________aklıma.....

_________________sızlar..! ! 

_____________________ sızlar..

_________________________yüreğim......

_______________derinden......

____derinden....! ! ! !', 'Gecenin karanlığında, Yine düştü, Turuncu ışıklar, Marmara''nın kapkara sularına. Karşı kıyıdan, Kartal''dan kalkan, Yirmi bir otuz vapuruda, ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sizlar-yuregim-derinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekinge', 'cekinge-yildiz-ark-kqgg8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gemilerimi sayıyorum....

Kaçı gidip döndü yolundan geri

Varamadı kapına,

Açmazsın diye belki', 'Gemilerimi sayıyorum.... Kaçı gidip döndü yolundan geri Varamadı kapına, Açmazsın diye belki...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Ark']::text[], 8.5, '{"poet":"Yıldız Ark","poet_slug":"yildiz-ark","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cekinge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda...', 'yoklugunda-yildiz-ark-5c2pv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuşatıldım, sorgusuz infaz edildim

         Son dileğim sorulmadı.

                  Zaten sen de yoktun...

                           Ölüm gücüme gitmedi.', 'Kuşatıldım, sorgusuz infaz edildim          Son dileğim sorulmadı.                   Zaten sen de yoktun...                            Ölüm ...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Ark']::text[], 8.5, '{"poet":"Yıldız Ark","poet_slug":"yildiz-ark","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yoklugunda-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüm Ayrılığa', 'kustum-ayriliga-zafer-zengin-etnika-ns6eb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapı ardına sakladığım

Pencere açtığımda

Özgür  bıraktığım

O çocuk

Bendim işte

Saçlarım sarıyken

Konuşmazdım

Köprü ayaklarına

Mıhlarlardı ellerimi

Tüm sokaklar benimdi

Tüm türkülerde

Ben söyler

Ben koşardım

Konserve kutuları tekmelerdim

Ellerim cebimde

Beni düşünen

Sokak kedilerine et atardım

Kaburgalarımdan

Kavgalar cıkar

Döven ben

Dayak yiyen ben

Kaçan ben olurdum

Kafamda izler

Renginde seni gizler/Kan bir yanı

Tüm bahçelere

Tüm domateslere

Tüm ayçekirdeklerine

Ben saldırdım

Tuzunu sevdim en çok

Tahta bahçelere saklanmış

Çocukluğumun

Birşey eksikti her zaman

Senmiydin adını saklayan

Kadife pantolon

Bordo kazak 

Beyaz gömlek içine koydukça seni

Göğsümün üst köşesine

Ben gibi olurdu sesin

Saklanırdım dibe köşeye

Seni kimse görmesin diye

/Bundandır geç büyümem

Vedasız gittim hep/Küstüm ayrılığa

5 Nisan 2004  '' İçimin Kitabı ''', 'Kapı ardına sakladığım Pencere açtığımda Özgür  bıraktığım O çocuk Bendim işte Saçlarım sarıyken Konuşmazdım Köprü ayaklarına Mıhlarlardı el...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kustum-ayriliga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet De...', 'evet-de-yildiz-ark-2yc9k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırlarım olup açar mısın bana

          Eser misin saçlarıma

                  Gelincik olup değer misin

                          Yağmur olup ılık ılık yağar mısın yüzüme', 'Kırlarım olup açar mısın bana           Eser misin saçlarıma                   Gelincik olup değer misin                           Yağmur ol...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Ark']::text[], 8.5, '{"poet":"Yıldız Ark","poet_slug":"yildiz-ark","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/evet-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Koyun', 'kara-koyun-yusuf-ter-mibpa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurtlar kaptı seni dağın yollunda 

Uluşurda karabaş köpekler anam

Kargalar dolmuş kuzunun başına

Kuzusuna meller durur koyunum

Dağ çobanı gezer ellinde kavalı

Omzu silahlı beli gamalı

Göynük elbisesi çokca yamalı

Kuzusuna meller durur koyunum

Yusuf um kızılırmak boylarında 

Yayılır kara koyunlar merasında

Çocukluk düşleri kurar ruyasında

Kuzusuna meller durur koyunum

Göynük:acısı olan 

Yusuf Ter 03.04.04

Saat 19:09 İsviçre', 'Kurtlar kaptı seni dağın yollunda  Uluşurda karabaş köpekler anam Kargalar dolmuş kuzunun başına Kuzusuna meller durur koyunum Dağ çobanı ge...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kara-koyun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Çocuk', 'i-cimdeki-cocuk-galib-blotto-mtp54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bir çocuk saklı

Göğüs kafesimde hapis

Dışarı çıkamaz yasaklı

Ona bu cezayı verdik biz.

Ağlar içimdeki bu çocuk

Tekme atarak ciğerlerimde

Sesi kısık ve boğuk

Beni de ağlatır gecelerimde

(2001)', 'İçimde bir çocuk saklı Göğüs kafesimde hapis Dışarı çıkamaz yasaklı Ona bu cezayı verdik biz. Ağlar içimdeki bu çocuk Tekme atarak ciğerleri...', ARRAY['Türk Edebiyatı','Şiir','Galib Blotto']::text[], 8.5, '{"poet":"Galib Blotto","poet_slug":"galib-blotto","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/icimdeki-cocuk-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Güvercinler', 'siyah-guvercinler-galib-blotto-xezyg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlığın dalları arasında 

yuva yapan siyah güvercinler

soğuk yanlız yuvaları etrafında

uçuşurken karabasanlar ecinniler

aşağılara baktıkça uçamaz olur

yüreklerini döver

aşağıya bakmayın

aşağılar körler

semada yıldızlar

bakınca anlarsınız ki

yerdedir koskoca gökler

her sene yerden biter

yıldızlar birer birer

yuvanıza dökülürler

ağaçların yapraklarında

hatıralar birer birer

karanlık ensenize üfler

bir yaprağın daha döküldüğünü

boşluğa kanatların söküldüğünü

uzakta bir sesin 

yavaş yavaş öldüğünü

sözün sıkı düğümünü

bakırdan, soğuk güyümünü

güneşin tanla sökümünü...

karanlıkta güvercinler

bir şehzadenin

bir yıl daha

bir yıl daha

her kanat çırpışta

daha uzaklara düştüğünü

görür, korkar, uçar

siyah güvercinler', 'Karanlığın dalları arasında  yuva yapan siyah güvercinler soğuk yanlız yuvaları etrafında uçuşurken karabasanlar ecinniler aşağılara baktıkç...', ARRAY['Türk Edebiyatı','Şiir','Galib Blotto']::text[], 8.5, '{"poet":"Galib Blotto","poet_slug":"galib-blotto","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/siyah-guvercinler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perî', 'per-galib-blotto-ngqfc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Harâbe mabedin her taşında

Efsun tüten dumânım

Siyeh-i Perînin soluklanışında

Mükererdir bir ânım', 'Harâbe mabedin her taşında Efsun tüten dumânım Siyeh-i Perînin soluklanışında Mükererdir bir ânım...', ARRAY['Türk Edebiyatı','Şiir','Galib Blotto']::text[], 8.5, '{"poet":"Galib Blotto","poet_slug":"galib-blotto","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/peri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Claire de Lune', 'claire-de-lune-galib-blotto-ltab1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 've şimdi claire de lune

geçmek bilmez bir gün

               çalar içimdeki besteyi

               tekrar karar desteyi

bitmek bilmezken sonat

bırak artık vehimlere

               geceye saçılan betimlere

               unutulan bir son ad

(2003)', 've şimdi claire de lune geçmek bilmez bir gün                çalar içimdeki besteyi                tekrar karar desteyi bitmek bilmezken son...', ARRAY['Türk Edebiyatı','Şiir','Galib Blotto']::text[], 8.5, '{"poet":"Galib Blotto","poet_slug":"galib-blotto","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/claire-de-lune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buh(u) r(d) an', 'buh-u-r-d-an-galib-blotto-cdtxr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''-İp üstünde hep başım döndü, şimdi çoktan düştüm, heryanım kırık...''

Ölüm kolgeziyor

nefret, seslenirken

biz zalimlere

heran, paslanmış bıçaktan

isli yürekten öc alan

yağmur, yağmur

temizler ancak

delik deşik yürekten

akan, isli kan

ve toprak kusar

gözlerimden akan...

üstü üstüne dizilen

birçok kadeh yalan

tekinin içinde iffet

diğerlerinde kan...

üstüne sıçratmadan

saplamak paslı bıçağı

akıtmak, içtiğim

her kadehteki yalanı...

ölüm bizlere

sunarken sessiz armağanı:

ölmeden ölmeli

ölmeden öldürmeli

diri gömüldüğümüz 

ıslak topraktan

sökmeden sökülmeli

ne sonuncusu ne de ilki

uğultu gölgesinde

pusuda bir tilki

kuruntunun ekmeginde

sövüş edilen bıcakla kan

ve herzaman Azizun Zuntikam', '''-İp üstünde hep başım döndü, şimdi çoktan düştüm, heryanım kırık...'' Ölüm kolgeziyor nefret, seslenirken biz zalimlere heran, paslanmış bıç...', ARRAY['Türk Edebiyatı','Şiir','Galib Blotto']::text[], 8.5, '{"poet":"Galib Blotto","poet_slug":"galib-blotto","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/buh-u-r-d-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçe', 'bahce-galib-blotto-kjtc9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık arka bahçede

serin rüzgarla cezbede

iki ağaç salınıyor.

Loş ışıklı pencerede

sıkışık cam cenderede

yapraklarıyla dolanıyor.

iki ağaç üstünde

iki dal, uzanırken

birbirleriyle, iki ağaç

cezbede, kazınırken

kabukları, rüzgarda

iki dal, iki ayrı ağaca

hiç kavuşmamacasına

saplanmış, sanki dik yamaca

saplanmışcasına, iki dalın

uzanan uçlarında

sînedir tomurcukları

bahar kokusuyla

ay ışığında

su dolar toprağı

loş ışıklı pencereden

süzünle göz yaşıyla...', 'Karanlık arka bahçede serin rüzgarla cezbede iki ağaç salınıyor. Loş ışıklı pencerede sıkışık cam cenderede yapraklarıyla dolanıyor. iki ağa...', ARRAY['Türk Edebiyatı','Şiir','Galib Blotto']::text[], 8.5, '{"poet":"Galib Blotto","poet_slug":"galib-blotto","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bahce-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marché Funebré', 'march-funebr-galib-blotto-p8wmg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Allegro: 

ve gök arşa devrilirken

melekler davullarını

patlatırcasına dövüyor

kayıp  doruklardan

mazi  dökülürken

vuruyor! vuruyor! 

zemin gonguna yıldızlar

aria:

uyanıyor! uyanıyor!

ağlarken gömülen diri kızlar! 

kendi nal seslerine 

koşan firari yağızlar

sıcak nefeslere

ve kum tanelerine 

boşalan okyanuslar

Allegretto:

üflüyor! üflüyor! 

ruhları söken besteyi

son bir emir

deviriyor kubbedeki son desteği

kavuşuyor ilik ve omur

baştaki kan ve suda

artık degil Pusuda

Es-Sabûr,

azabını buyurur! 

Finale: requiem

unutulur! unutulur! 

cenazesi arşın

hesabın yanıbaşında

Kitabı mezar taşında

defnolunur içine marşın', 'Allegro:  ve gök arşa devrilirken melekler davullarını patlatırcasına dövüyor kayıp  doruklardan mazi  dökülürken vuruyor! vuruyor!  zemin g...', ARRAY['Türk Edebiyatı','Şiir','Galib Blotto']::text[], 8.5, '{"poet":"Galib Blotto","poet_slug":"galib-blotto","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/marche-funebre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar Ve Şimdi', 'bir-zamanlar-ve-simdi-k-muran-esen-53jy3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar

Dört nala giden

Doru bir  at gibi

Coşkuluyken  rüyalarımız,

Çakır dikeni bir yorganı

Örttüler üzerimize

Sılaya   kapatıp gözlerimizi

Gurbetlere uyanıyoruz şimdi.

Bir zamanlar

Kavak yelleri başımızda

Koşarken zaman tünelinde,

Kamçı gibi

Yüzümüze indi de yıllar,

Gönlümüz  düştü enginlere

Yaralı bir keklik gibi

Ovalarda sekiyoruz şimdi.

Bir zamanlar

Başımız bulutlarda

Yumuşak zemindeyken  parmak uçlarımız

Dağ doruklarından / ovaya

Çağıldayarak inerken sarmaş dolaş,

Kurak mevsimler

Çöreklendi üzerimize

Sularını

Kıraç topraklarda eksiltmiş

Cılız bir dereyiz şimdi.

Gençliğimiz göz bebeklerimizde

Düş tarlalarında dolaşırken bir zamanlar

Buğday başakları gibi

Sallanırken /  onsekiz  rüzgârlarında

Vururdu / altın sarısı bedenimize parıltılar.

Sonra / indi de

Keskin bir tırpan belimize

Başka başka değirmenin çarklarında

Öğütülüyoruz şimdi.

Nefesimiz birbirine

Karışırken bir zamanlar

Sevişirken

Karanlık / kör gecelere inat,

Sarsılan vücutlarımıza

Yansıyorken sevgimiz,

Ve gözlerimiz

Aynı uykulara  kapanırken birlikte,

-Ne oldu

Nasıl oldu, anlamadım ama- 

Ölesiye birbirimizi

Özlüyoruz şimdi.', 'Bir zamanlar Dört nala giden Doru bir  at gibi Coşkuluyken  rüyalarımız, Çakır dikeni bir yorganı Örttüler üzerimize Sılaya   kapatıp gözler...', ARRAY['Türk Edebiyatı','Şiir','Kâmuran Esen']::text[], 8.5, '{"poet":"Kâmuran Esen","poet_slug":"k-muran-esen","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-zamanlar-ve-simdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susun Biraz', 'susun-biraz-ali-osman-yilmaz-0s3sl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susun biraz,

Göklerin tanrısı çıldırmış olmalı,

Bak,nasılda gümbürdüyor,

Gök gürültüsüyle aşkımın,

Şah damarını kesiyor.

Her yana fışkırıyor,

Acılarım,hüzünlerim,anılarım.

Beni bu kadar üzen,

Hatta kahreden,

Anılarımı bu kadar,

Sevdiğimi bilmezdim.

Acılarım şimdi başka güzel,

Hüzünlerim kır çiçekleri gibi,

Görünmekte gözüme.

Bir başka seviyorum artık,

Acılarımı,hüzünlerimi,anılarımı,

Seni ve ihanetlerini,

Sevmiyorum artık,

Ve ben  seni,

Asla affetmiyorum.', 'Susun biraz, Göklerin tanrısı çıldırmış olmalı, Bak,nasılda gümbürdüyor, Gök gürültüsüyle aşkımın, Şah damarını kesiyor. Her yana fışkırıyor...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/susun-biraz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanların.', 'yalanlarin-ali-osman-yilmaz-7g88w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suya yazılan sözler gibi,

Bana söylediklerin,

Daha yazılırken silinmede,

Ne sen okuyabiliyorsun,

Nede ben okuyabiliyorum.

Tutamayacağın o sözleri,

Öyleyse neden veriyorsun? 

Bak sancılanmakta yer küre,

Belli ki yeni aşklara gebe,

Yaşanacak yeniden mevsimler,

Kışlar yine sert ve soğuk,

Baharlar yine solgun ve ölgün,

Yazlar yine cehennem gibi,

Güz şarapları bir başka acı,

Yine Hayyam’ları konuşturacak.', 'Suya yazılan sözler gibi, Bana söylediklerin, Daha yazılırken silinmede, Ne sen okuyabiliyorsun, Nede ben okuyabiliyorum. Tutamayacağın o sö...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalanlarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Biter mi?', 'ask-biter-mi-ali-osman-yilmaz-ksun5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biten aşklar,

Yeniden başlamazmış,

Haklılar belki de? 

Bir çiçeğin yaprağında,

Kızıl gülün kırmızlığında,

Yeni aşklara yol bulunmuyor,

Zaman solduruyor çiçekleri,

Yaprakları,kızıl gülleri,

Güneş kavuruyor her yanı,

Çiçekleri,yapraklarını,

Sense güzelim,

Kavuruyorsun yüreğimi.', 'Biten aşklar, Yeniden başlamazmış, Haklılar belki de?  Bir çiçeğin yaprağında, Kızıl gülün kırmızlığında, Yeni aşklara yol bulunmuyor, Zaman...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-biter-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Çok Zor Geçiyor Zaman', 'sensiz-cok-zor-geciyor-zaman-ali-osman-yilmaz-f8vh2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz çok zor geçiyor zaman,

Kışlar daha sert ve soğuk,

Bahar,doğumlara duyarsız,

Yaz bir başka sıcak,

Cehennem sıcakları ortalıkta,

Güz Hayyam’a inat,

Daha bir güzel,

Aşk şarapları,daha lezzetli,

Ama aşk acısı markalı,

Taaa Hayyam’dan kalan.

Sensiz geçmiyor zaman,

Bilseydim sensizliği yaşayacağımı,

Onlarca aşk biriktirirdim,

Sensizlikte yaşarken,

Biriktirdiğim aşklarla avunur,

Sensizliğe çare bulurdum.

Sensiz mi geçmiyor zaman? 

Yoksa aşksız mı,bilmem? 

Sensiz de zor,aşksız da zor,

Yalnız yaşamak zor,

Tüm mevsimler sensiz,

Bir başka kahır içinde geçiyor,

Ama,sensiz ve aşkından yoksun,

İnan güzelim,asırlar gibi,zaman,

Çok zor geçiyor inan.', 'Sensiz çok zor geçiyor zaman, Kışlar daha sert ve soğuk, Bahar,doğumlara duyarsız, Yaz bir başka sıcak, Cehennem sıcakları ortalıkta, Güz Ha...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sensiz-cok-zor-geciyor-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime öğütler...', 'kendime-ogutler-nergis-demet-008oy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KENDİME ÖĞÜT (1) 

haketmeyenlere verdiğin sevgiler,

beklentilere yol açtı yüreğinde.

yıllardır...

bu karşılıksız sevmeler,

sevginin kıymetini bilmeyenler,

inancını sarstı insanlığa.

sevgi verip,

hep ısrarla.

nefret aldıkların yüzünden,

huyun bozulacak vazgeçmezsen,

en iyisi beklememen.

gelirse de baştacı etmen.

''insanlık ölmedi,ölmeyecek'' demen.

umudunu kaybetmeden...

KENDİME ÖĞÜT (2) 

umuda dönüştür gözyaşını,

izin verme! 

seni küstürmelerine.

fırsat verme! 

kötüye yanacıya haine.

biliyorsun,

senin de bekleyenin var,

sana ihtiyacı olan.

yılma! 

görevin,

ayakta durmak.

umudu diri tutmak.

sözlerin hep,

inatla,

''bir gün mutlaka,

bir gün mutlaka iyilik kazanacak''

demek olacak...

KENDİME ÖĞÜT (3) 

hep onlar kazanacak sanma! 

dünya Sultan Süleyman''a kalmamış.

sonsuza dek ne yaşar ki evrende? 

gün gelecek...

bir gün...

biz de marşlar söyleyeceğiz...

türküler,şarkılar...

''kötülüğü yokettik,

iyilik kazandı''

demenin sevinciyle...', 'KENDİME ÖĞÜT (1)  haketmeyenlere verdiğin sevgiler, beklentilere yol açtı yüreğinde. yıllardır... bu karşılıksız sevmeler, sevginin kıymetin...', ARRAY['Türk Edebiyatı','Şiir','Nergis Demet']::text[], 8.5, '{"poet":"Nergis Demet","poet_slug":"nergis-demet","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kendime-ogutler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğum Varlığımdır', 'yoklugum-varligimdir-halil-i-brahim-ozdemir-io3re', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hafızamda bir yerlere koymuştum,

Köşe bucak koştum taradım seni

Hasretinden gün gün seni saymıştım

Saç teli  sayısı, aradım seni

Gün oldu zamanı baskıya aldım

Yaşamadım asla günleri sensiz

Gönlümü kapattım askıya aldım

Kapandım odama yıkık çaresiz..

Gölgeler şehrinde kahraman aşık,

Hasreti vuslatı hepsi hayaldi,

Varlığın yokluktan çok’a bulaşık

Ansızın hayalden vara yöneldi…', 'Hafızamda bir yerlere koymuştum, Köşe bucak koştum taradım seni Hasretinden gün gün seni saymıştım Saç teli  sayısı, aradım seni Gün oldu za...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoklugum-varligimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel kadın çirkin yürek...', 'guzel-kadin-cirkin-yurek-emir-kemal-l4lre', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Güzel kadın, çirkin yürek-

Hava kapalı,

Belki yağmur gelici...

Sıklaşan adımlarda düşen bir damla,

Sonra ıslanmaya başlayan bir beden...

Ve bir gayret atılan son adım,

Girişi dar, derince bir mağarada son bulurken...

-Güzel kadın, çirkin yürek-

Bir mum ışığında düşeyezan bir gölge

Ve...

Umutlara vuran yalın bir suret...

Uzaklardan belirir sessizce

Ve dalga dalgadır simaları kederlerin,

Seçemezsin erimeye sürgün bir mumun ışığında...

Yaklaşır kararsız adımlar,

Ve kaçınılmazdır kaçışlar...

Arkanı dönersin, her yanın duvar,

Islak bir mağarada kalakalırsın,

Mum... gölge... duvar...

Korkutulan bir yüreğin sensizliğe açılan kapısıdır.

-Güzel kadın, çirkin yürek-

Kaygan bir basamak,

Daralan bir nefes,

Islak bir beden...

Kesilen yağmurun sesi...

Kör eden karanlık,

Yanması çok görülen bir mumun son vasiyetidir..

Bir adım,

Bir adım daha...

Ürperten üşümeler...

Yarasalar dolanır başında,

Karanlıkları aydınlığa yeğdir onlarca...

Karşı duramazsın,

Çıkılmazdadır çıkışlar...

Koşamaz,

Kaçamaz,

Bulamazsın...

Her yer ıslak,

Her yer karanlık...

Nefes kesik, ses cılız...

Kaygan basamaklar,

Her yan taş duvar...

Ve çıkılmaza çıkarmaya çalışan kör yarasalar..

Sönen bir mum,

Buz tutan eller...

Bağlanıp kalırsın,

Güzel bir kadının, çirkin yüreğinde...', '-Güzel kadın, çirkin yürek- Hava kapalı, Belki yağmur gelici... Sıklaşan adımlarda düşen bir damla, Sonra ıslanmaya başlayan bir beden... Ve...', ARRAY['Türk Edebiyatı','Şiir','Emir Kemal']::text[], 8.5, '{"poet":"Emir Kemal","poet_slug":"emir-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/guzel-kadin-cirkin-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldım Burada', 'kaldim-burada-hifzi-ozbekmez-jpami', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen aklıma geldin doldu gözlerim

Elim kolum bağlı kaldım burada

Yalan oldu şimdi benim sözlerim

Elim kolum bağlı kaldım burada

İçimden hasreti atamıyorum

Hüznüme mutluluk katamıyorum

Uykular tutmuyor yatamıyorum

Elim kolum bağlı kaldım burada

Arada hasret var uzadı yollar

Açmadan soluyor bak gonca güller

Gönül bahçesinde ötmez bülbüller

Elim kolum bağlı kaldım burada

Latifi söylesem dinlenmez sözüm

Yarin özlemiyle ağlıyor gözüm

Karakış oldu hep baharım yazım

Elim kolum bağlı kaldım burada

07 ARALIK 2003 PAZAR  SAAT: 09:00', 'Sen aklıma geldin doldu gözlerim Elim kolum bağlı kaldım burada Yalan oldu şimdi benim sözlerim Elim kolum bağlı kaldım burada İçimden hasre...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaldim-burada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Söyleyin*', 'selam-soyleyin-bayram-tunca-srdfs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Selam söyleyin sıladaki eşe dosta 

Deyin ki, hasretinizden şair yasta 

Hayli zamandır gelmez oldu posta 

Sitemlidir şair Bayram bu hususta 

Selam söyleyin benden o nazlı yare 

Hasretinden ciğerim oldu pare pare 

Mecnun gibi geziyorum avare avare 

Ya Rab ne olur kavuştur beni o yâre 

Selam söyleyin benden bütün can dostlarıma 

Ne vakit isterlerse, gelip otursunlar postuma 

Unutmasınlar, çatlarcasına onlara koştuğumu 

Anne, baba, kardeş gibi onlara kucak açtığımı

Selam söyleyin benden cihandaki tüm kullara 

Prensip edinsinler, yurtta sulh, cihanda sulha

Girsinler, birbiriyle ilim/irfan sahasında yarışa 

En güzel budur doğrusu yakışan âdemoğluna 

Selam söyleyin benden istikbaldeki nesillere 

Sahip çıksınlar şu alemdeki kültür eserlerine 

Yâd etsinler dünyada daima eser sahiplerine

Razı olsun O, sahip çıkanlardan yüz bin kere 

Alsınlar heybemdeki çerezlerden doyana dek 

İçsinler pınarımdan avuç avuç kanıncaya dek 

Devşirsinler bahçedeki güllerden deste deste 

Yeter ki adımı yad edip paylaşsınlar herkesle 

04.04.2004-04.04-İst.', 'Selam söyleyin sıladaki eşe dosta  Deyin ki, hasretinizden şair yasta  Hayli zamandır gelmez oldu posta  Sitemlidir şair Bayram bu hususta  ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/selam-soyleyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairliğimden Utandım', 'sairligimden-utandim-abdil-yildirim-ribdh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çözemedim zihnimdeki düğümü,

Kısır düşüncemin acizliğinden,

Hayatın sırrını bilmediğimi,

Bildim de utandım cahilliğimden.

Görünce baharın sekeratını,

Farkettim ölümün nasihatını,

Solgun yaprakların tesbihatını,

Duydum da utandım gafilliğimden.

Zamanı kuşatmış görünmez bir el,

Avucunun içinde ebed ve ezel,

Hayatın ahengi şiirden güzel,

Gördüm de utandım şairliğimden.', 'Çözemedim zihnimdeki düğümü, Kısır düşüncemin acizliğinden, Hayatın sırrını bilmediğimi, Bildim de utandım cahilliğimden. Görünce baharın se...', ARRAY['Türk Edebiyatı','Şiir','Abdil Yıldırım']::text[], 8.5, '{"poet":"Abdil Yıldırım","poet_slug":"abdil-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sairligimden-utandim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'RüzGar AlıYoR ŞaMDaN,', 'ruzgar-aliyor-samdan-mine-ozdemirtas-dalu9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir aşkı düşlesem,

Ya, çizme giymeye kalkıyor kırkayaklar

Ya,  bir pireyi ısırıyor şahmeran.

Ya da....................................................! 

Elime maydanozun dikeni batıveriyor.

Ter içinde uyanıyorum uykulardan.

Törenlerle girdiğim süslü yapılardan

Bir elimde yastık bir elimde yorgan,

Sessizce arka kapıdan

Kaçışım ondan.

Ne zaman kendimi bir düşe yerleştirsem.

Ya, zehirli elmayı ısırmamı istiyor cadılar

Ya,  kül kedisi dil çıkarıyor aynalardan.

Ya da...................................................! 

On ikiyi vurmaya hazırlanıyor zaman

İndirerek yere, prensleri beyaz attan.

Çıplak ayak çıkıyorum masallardan.

Ellerinde terliğimin teki ve yayan

Gölgelerin ardımdan

Koşuşu ondan.

Ne zaman,

Bir aşkı yaksam ucundan......

Şiirler damlıyor yanan mumdan.

Uçuşuyor perdeler, rüzgar alıyor şamdan

Sönüşüm ondan.

2/04/2004', 'Ne zaman bir aşkı düşlesem, Ya, çizme giymeye kalkıyor kırkayaklar Ya,  bir pireyi ısırıyor şahmeran. Ya da....................................', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ruzgar-aliyor-samdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Bu', 'dunya-bu-abdullah-atay-2fdy8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya bu işte! ..

Ben sana; 

Canımı,hayatımı,

Sevgimi,aşkımı,

Ve bir de; 

Bahçemdeki en değerli

Gülü verdim.

Oysa sen bunlara karşılık

Sadece bana gülüverdin...', 'Dünya bu işte! .. Ben sana;  Canımı,hayatımı, Sevgimi,aşkımı, Ve bir de;  Bahçemdeki en değerli Gülü verdim. Oysa sen bunlara karşılık Sadec...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dunya-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simitçi Çocuk', 'simitci-cocuk-rahim-tas-c7r58', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'oyun çağında bir çocuk 

saçları dağınık 

yüzünü yıkamamış 

gözleri çapaklı 

elleri çatlak çatlak 

kapkara 

üstü parlıyor kirden 

ve sabah ezanının ardından 

onun sesi duyulur 

siiiiimiiiiit vaaaarrrr....... 

oyun çağında bir çocuk

belki de en pembe rüyası 

bisiklet pedalı çevirmek 

öksüz mü yetim mi kimbilir

gözlerinden uyku akıyor 

üşümüş elleri

paranın üstünü sayamıyor bile 

esniyor 

ve esneyerek bağırıyor 

siiiiimiiiit vaaaaaaaar..... 

nisan 1989

Rahim TAŞ', 'oyun çağında bir çocuk  saçları dağınık  yüzünü yıkamamış  gözleri çapaklı  elleri çatlak çatlak  kapkara  üstü parlıyor kirden  ve sabah ez...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/simitci-cocuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebebeğim', 'bebebegim-halit-demir-l2zob', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba yeni dünyam...

Merhaba benim canım....

Merhaba benim gülen gözlü yavrum..

Hoş geldin...

Her  çocuk dünyaya gelirken ağlarmış

Sen, dudağındaki tebessümlerle geldin

Gözlerindeki gülümsemeyle...

Ne güzelmiş, dünyaya gülen gözlerle gelebilmek

Sevdiklerine tebessümlerle bakabilmek

Tıpkı senin gibi...

Hayatın anlamını, sen doğunca öğrendim

Tebessümü, gülen gözle bakmayı

Artık boş gözlerle bakamıyorum hayata

Çünkü! sen girmiştin artık  hayatıma.

Biliyorum bebeğim,  hiç kimsenin üzülmesini istemediğini

İstiyordun herkesin gülerek gezmesini...

Biliyorum bebeğim, 

Küçük olmana rağmen çoğu kez de üzüldüğünü..

Üzüldüğünü anlayarak saatlerce ağladığını

Ne zaman donuk bir gözle karşılaşsan

Anlıyorum üzüldüğünü

Ne yaparsın bebeğim! 

Ne yaparsın bitanem! 

Herkes senin gibi olamaz.ki.? 

Herkes senin gibi bakamaz.ki.? 

Konuşamasan da durgunluğundan anlıyorum

Sessiz çığlığınla bana “Hayır bakmalı baba” bakmalı dediğini

O insanlarda Gülmeli, gülmeli dediğini

İstiyorsun bitanem! 

Tüm insanların senin gibi olmasını

Bir tebessümünle neler yapabileceğini bilseler

Ve senin gözlerindeki o ışıltıyı görseler

Belki hiç somurtmak istemezlerdi

Dertlerle yoğrulurken insana

Ab-ı Hayat verdiğini bilmeliler bitanem...

Gülen gözlerinle buzları erittiğini, bilmeliler

Sevgisiz kalplere sevgi bahşettiğini de bilmeliler

Ve en güzeli ise kalpleri birleştirdiğini bilmeliler

BİTANEM! Onlarda senin gibi olmak isterler

Belki onlarda senin gibiydi

Belki onlarda tebessümle gelmiş

Gülen gözlerle hayata girmişlerdi

Belki de bu iki şeyi hayata atılırken kaybetmişlerdi

Ama hayatın kısa olduğunu bilseler di

Onlarda hiç eksik etmezlerdi gülümsemeyi

Evet bebeğim, Evet bitanem.

Hayat böyle işte..

Benim gözleri gülen, dudakları tebessüm dağıtan kızım

Bil ki “SENİ ÇOK SEVİYORUM”', 'Merhaba yeni dünyam... Merhaba benim canım.... Merhaba benim gülen gözlü yavrum.. Hoş geldin... Her  çocuk dünyaya gelirken ağlarmış Sen, du...', ARRAY['Türk Edebiyatı','Şiir','Halit Demir']::text[], 8.5, '{"poet":"Halit Demir","poet_slug":"halit-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bebebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerim', 'beklerim-i-brahim-ugur-toprak-h95ch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Meğer) , 

Ne kadar da zor (-muş) . 

Kendini ifade edebilmek.

Olası bir yanlış anlaşılmaya

Mahal vermeden.

(Meğer) ,

Ne de güç oluyor (-muş) . 

Sevdiğini söyleyebilmek.

Onlarca kez tekrar etmiş olmana,

Senelerce susmuşluğuna/

/Susamışlığına rağmen. 

(Meğer) , 

Ne kadar da zor (-muş) .

İki kelimeye indirgeyebilmek

Sevgi sözcüklerini, ama

Bir tek hecesini bile basitleştirmeden.

(Meğer) , 

İnsan, kalbine sığdırıyor (-muş) , 

Yanardağ gibi parlayan,

Pınar gibi çağlayan,

O eşsiz sevgisini.

Yere göğe sığdıramazken.

Asırlar bile yetmezken,

Hani, bir insanı tanımaya.

Pek de adil olmasa gerek,

Sadece üç dakikada

Sevgi için hüküm vermek.

Eğer ki; 

Zaman istiyorsan,

Zaman senindir sevdiceğim.

Ben Beklerim! ..

01.04.04/Perşembe

23:38/İzmir', '(Meğer) ,  Ne kadar da zor (-muş) .  Kendini ifade edebilmek. Olası bir yanlış anlaşılmaya Mahal vermeden. (Meğer) , Ne de güç oluyor (-muş)...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beklerim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esarete Tahliye', 'esarete-tahliye-hakki-hakan-kaya-ru79d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'prangalara takılmış gözleri

esarette hislerimin

siyahın kırmızısı akmış

paslı demir kopçasına...

penceresinden baktığında

karanlık kodesinin

anlarsın en yakın dostunun 

isim verdiğin, şekil benzettiğin

yalansız riyasız, pamuk tarlası

doruk karları beyazlığında

ihanetsiz bulutlar olduğunu

ne çok şey anlattılar bana

hep yarım kalan sohbetlerinde

göründüğü kadar 

iki kepenk arasında

duydum, en son söylediler

tahliyesi gelmiş baharın....', 'prangalara takılmış gözleri esarette hislerimin siyahın kırmızısı akmış paslı demir kopçasına... penceresinden baktığında karanlık kodesinin...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/esarete-tahliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Hava Dönmez Yaza', 'bu-hava-donmez-yaza-necmi-unsal-kj1k4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutma  güzelim,  bu  hava  dönmez  yaza! 

Mana  ikliminde  kılınmadıkça  karar.

Bu  alemden  kara  giden  dönmez  beyaza.

Hesaplanmalı her geçen gün kârla  zarar.

Unutma  güzelim,  tam  çözülmez  kördüğüm! 

Gayret, sökün sökün  tam şaha  kalkmayınca.

Acayip,  manada  çözülmez hep gördüğüm.

Perde kalkıp sırrı gönlümü yakmayınca. 

Unutma  güzelim,  güller  hep  güzel  kokar.

Uyandı  tepenin  ardındaki  tüm  kuşlar.

Gül  bahçelerine  giren  hep  güzel  bakar.

Aşılmalı  yolda  bütün  iniş yokuşlar.

Unutma  güzelim,  bitmez  süfli  hevesler.

Doldurur  toprak,  aç;  doymak  bilmez  gözleri.

Can  çıkmazsa  bitmez bu sayılı  nefesler.

Soldurur  ölümün  pençesi  şuh  yüzleri.

Unutma  güzelim,  sütte  bulunmaz  kara.

Sütün fıtratıdır beyazlık   buna  inan! 

Gönül  yarasından  kötü  bulunmaz  yara.

Felaha  kavuşur  kalp  kırmaktan  sakınan.

1 Mart 2004  Pazartesi,  Danimarka-Køge   00.52

6+7', 'Unutma  güzelim,  bu  hava  dönmez  yaza!  Mana  ikliminde  kılınmadıkça  karar. Bu  alemden  kara  giden  dönmez  beyaza. Hesaplanmalı her ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-hava-donmez-yaza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahardan Bahar Olalım', 'bahardan-bahar-olalim-bekir-mutlu-gokcesu-q7i7j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana hasretim gibi

Günler ve geceler

Daha doymadı yağmurlara

İçime sığdıramadığım gibi seni

Bu Nisan da sığmaz sokaklara

Haydi başını göğsüme yasla

Yitip giden mevsime

Benimle son kez ağla

Sıyır hüznü gözlerinden

Irmağının yatağı olsun

Doya, doya ak tenimden

Çelişkilerimi, ukdelerimi

Sök at yüreğimden

Yunsun, yıkansın ruhlarımız

Karışan göz yaşlarımızın selinden

Sızsın keder göz kapaklarımızda

Sımsıkı tut ellerimden...

Uyuyup uyanalım Mayısa

El değmemiş bir çiçek tarlasında

Diz boyu çimenler hizasında

Uzandığımız yerden bakalım

Esintiyle sevişen ve harmanlanan

Kırmızı, mor, sarı çiçek tozlarına

Başını yasladığın yerden

Uzansın dudakların dudaklarıma

Bahardan bahar olalım

Doyalım aşka...', 'Sana hasretim gibi Günler ve geceler Daha doymadı yağmurlara İçime sığdıramadığım gibi seni Bu Nisan da sığmaz sokaklara Haydi başını göğsüm...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bahardan-bahar-olalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkına Susamışım', 'askina-susamisim-cafer-tayyar-ozkan-ih5pt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçını okşamışım, tarar durur ellerim,

Sabrını saklamışım, arar durur gözlerim,

Sevgine sarılmışım, kokar durur güllerim,

Aşkına vurulmuşum, hüzün yazar dillerim...

Gönlüne girmişim, çıkmaz son nefese kadar,

Adını andıkça, hasretten yüreğim sızlar,

Kahrını çekerim, kara gecenin koynunda,

Bir kere gönül verdim, hayır desen ne yazar...

Ayazlarda kalmışım, sar ısıt bedenimi, 

Aşkına susamışım, öp ıslat dudağımı,

Sevgiliyi bulmuşum, vur titret yüreğimi,

Hasretine doymuşum, yak fethet şu gecemi...

Masayı kurdum, mey kadehte gibi durmuyor,

Geceye daldım, kabuslarım rahat vermiyor,

Yatağa yattım, lakin senin gibi sarmıyor,

Dudakta bıraktın, vuslata izin çıkmıyor.

09 Ağustos 2003 Ankara', 'Saçını okşamışım, tarar durur ellerim, Sabrını saklamışım, arar durur gözlerim, Sevgine sarılmışım, kokar durur güllerim, Aşkına vurulmuşum,...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askina-susamisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her şey Senin İçindi...', 'her-sey-senin-i-cindi-volkan-tekin-sqnc5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şey Senin İçindi...

Her şey senin içindi

Bir damla aşk

Bir damla özgürlük içindi.

Her şey senin içindi

Bir sevgi

Bir üzüntü içindi

Her şey senin içindi.

Bir savaş 

Bir inat içindi

Her şey senin içindi

Yıllar senin için, 

Hayaller senin için,

Yarın senin içindi.

Her şey senin içindi

Seni sevdiğim içindi

Bir rüya içindi

Bir rüzgar

Bir dalga içindi.

Ben senin içindim

Ama gittin

Günü bitirdin

Sabahı terk ettin

Yollar da senin içindi

Her şeyin olduğu gibi..', 'Her şey Senin İçindi... Her şey senin içindi Bir damla aşk Bir damla özgürlük içindi. Her şey senin içindi Bir sevgi Bir üzüntü içindi Her ş...', ARRAY['Türk Edebiyatı','Şiir','Volkan Tekin']::text[], 8.5, '{"poet":"Volkan Tekin","poet_slug":"volkan-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/her-sey-senin-icindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırlangıçlar', 'kirlangiclar-volkan-tekin-ob8j4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özgürlük kokuyor kaldırımlarım

Beyaz sayfalarda kalmış yarınlarım

Kabuslarla dolu rüyalarım

Alevler sarmış gözlerim

Söyle şimdi ben, ben miyim? 

Kaçıyorlar bizden kırlangıçlar

Anlamıyor kimse, görmüyorlar

Bugün bir çocuk öldü

Gün kıyamete döndü

Üzülen yok, korkuyorlar

Ah... bir bilsen

Hemen unutuyorlar.

Sen ben gerçek miyiz sahiden? 

Gerçek mi kanatlarında yarınlarım

Kırlangıçlar, güz mü geldi sahiden? 

Yoksa yalan mı söylüyor yapraklar...', 'Özgürlük kokuyor kaldırımlarım Beyaz sayfalarda kalmış yarınlarım Kabuslarla dolu rüyalarım Alevler sarmış gözlerim Söyle şimdi ben, ben miy...', ARRAY['Türk Edebiyatı','Şiir','Volkan Tekin']::text[], 8.5, '{"poet":"Volkan Tekin","poet_slug":"volkan-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirlangiclar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlak gün', 'mutlak-gun-mutlu-ayar-jz94x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bırak da zorba hayat, gideyim güneşe doğru

Hapsetme beni sislerin soğuk kelepçesiyle! 

Kanar gözlerim çürük bir çınar gölgesinde

Çözüver günlerimi, kaçırmayayım son vapuru! ..

Çiçekler renkli, çimenler yeşil, dere yeşil, 

Ben eski bir film, denizler mavi, gök mavi, 

Kokuyla sevişiyor kuşlar, yalnızlar bile neşeli,

Dünya aynı dünyada, bu ben eski ben değil! .. 

Ben böyle olunca, dünya ilelebet mahpus

Geçmişin pişmanlığı ve özentisi hissiyle,

Geleceğin endişesi ve korkusu kafesinde,

Şimdi mutlu olmak, yalnız şairlere mahsus!', 'Bırak da zorba hayat, gideyim güneşe doğru Hapsetme beni sislerin soğuk kelepçesiyle!  Kanar gözlerim çürük bir çınar gölgesinde Çözüver gün...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mutlak-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-volkan-tekin-e3jly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah bir anlayabilsen! 

Bir sitem var kadere içimde.

Bir çocuk gördüm mendil satan

Bir kenara bırakmış mendilleri

Ders çalışıyor.

Bir kor düştü sanki içime o an

Yanımdan süslü hanımefendiler geçti

Konuştukları elbiseleriydi. 

Bir isyan var kadere içimde.

Ah bir anlayabilsen!', 'Ah bir anlayabilsen!  Bir sitem var kadere içimde. Bir çocuk gördüm mendil satan Bir kenara bırakmış mendilleri Ders çalışıyor. Bir kor düşt...', ARRAY['Türk Edebiyatı','Şiir','Volkan Tekin']::text[], 8.5, '{"poet":"Volkan Tekin","poet_slug":"volkan-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/isyan-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme Artık', 'gelme-artik-filiz-turan-fx0ei', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelme artık 

Ne geceme nede düşlerime

Bir gün gittiğin gibi ansızın

Git artık düşlerimden

Anılarıda götür yanında

Hiçbir şey kalmamalı ardında

Seni hatırlatan yüreğimi acıtan

Ne varsa al götür

Yeni bir sayfa açılsın önümde

Seni hatırlatmayan

Senden izler taşımayan

Desem de..

Biliyorum ki bu mümkün değil

Evet sen gittin ansızın

Ama ardında bana çok şey bırakarak

Heryerde izlerin var

Heryerde anılar

Hergün seni hatırlıyorum

Hergün acıyor yüreğim

Hasretin büyüyor içimde

Neredesin sevdiğim

Keşke mümkün olsaydı

Tüm izleri bir bir silmek

Anıları yok etmek

Seninle birlikte hepsini maziye gömmek

Belki bir gün bunu başarabilirim

Kim bilir belki bir gün bende seni unutabilirim

İşte o zaman artık acı vermez anılar

İşte o zaman belki yeniden 

Hayata gülümseyebilirim..

Hatta belki yeniden de sevebilirim..', 'Gelme artık  Ne geceme nede düşlerime Bir gün gittiğin gibi ansızın Git artık düşlerimden Anılarıda götür yanında Hiçbir şey kalmamalı ardın...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gelme-artik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Dair..', 'dosta-dair-filiz-turan-bi41d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatın tüm zorluklarına

Ve acılarına rağmen

Sevgi doluysa yüreğin

Ve o güzel yüreğinle bakabiliyorsan hayata

Ve görmeyi başarabiliyorsan

Üzeri örtülü tüm güzellikleri

Hele birde Can dediğin

Seninle hayatı paylaşan

Seninle ağlayan seninle gülen

Yüreğinde yer eden bir dostun varsa

İşte o zaman kaybolur hayatın tüm acıları

Çok daha güzel olur var olan herşey

Ve gelen her yeni gün

 Güzellikler getirir kapına

Gülümsersin hayata tüm kötülüklere inat

Ve sevgi dolar yüreğin 

Tüm dünyaya yetecek kadar', 'Hayatın tüm zorluklarına Ve acılarına rağmen Sevgi doluysa yüreğin Ve o güzel yüreğinle bakabiliyorsan hayata Ve görmeyi başarabiliyorsan Üz...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dosta-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap', 'sarap-zahir-kilic-et4kq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kızıyorlar bazen bana anıyorum adını diye

Seviyorum işte sırt çevirmek olmuyor ki

Övüyorlar bazen de yine anıyorum adını diye

Nasıl bir ikilemdir anlayamıyorum ki

Kimi kültür diyor kokuna 

Kokluyor bir çiçeği koklar gibi

Kimi günah diyor tadına

Tutuyor ince belli kadehi günah gibi

Yeri geliyor ağzımda tadım oluyorsun

İniyorsun kavura kavura

Yeri geliyor şiirime can oluyorsun

Okutuyorsun savura savura

Bana kızmasınlar şarap isteyince

Gitarıma yakışmıyor başka eş çünkü

Dar ağacı bile olsa bu isteğin sonu

Şiirim de asılsın benimle

Başka eş olamaz,yok çünkü.', 'Kızıyorlar bazen bana anıyorum adını diye Seviyorum işte sırt çevirmek olmuyor ki Övüyorlar bazen de yine anıyorum adını diye Nasıl bir ikil...', ARRAY['Türk Edebiyatı','Şiir','Zahir Kılıç']::text[], 8.5, '{"poet":"Zahir Kılıç","poet_slug":"zahir-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sarap-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocukları', 'sokak-cocuklari-zahir-kilic-o8889', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey! Size söylüyorum,size

Görmemezlikten gelmeyin gerçeğim ben de

Ne yapmalıyım görmeniz için 

Bakmalı mıyım ki gözlerinize 

Parçalama niyetinde

Hey! Niye görmüyorsunuz, niye? 

Kaderim cellat olmuş yürüyorsa üstüme

Kurbanı mı oynamam gerek hep önünüzde

Sonunda belki beni görürsünüz diye

Hey! Kaçmayın beni gördüğünüzde,kaçmayın

Benimde iyi duygularım vardır

Dışım viran olsa bile

Yanlış yollara mı girmem gerek

Doğrusu bu diye

Kaç yoldan geçtim de 

Kırdılar kolumu kanadımı her seferinde

Hey! Bakın bir kere olsun bedenime,bakın

Bu muydu hak ettiğim yer

Dünya denen düzende

Oysa herkes gibi umutlarım vardı benim de

Kaç kez uyandım umutlardan 

Düş dediğim gerçeklikte

Hey! buradayım senin onun gibi,buradayım

Merak etmeyin ağlayamıyorum

Göz yaşlarım gidiyor tersine,kalbime

Her yeni gün size avuç açsam da

İteliyorsunuz yine geriye

Artık silemiyorum alnımdaki damgayı

Dilenci demesenizde

Hey! görün ama gülmeyin yine,görün

Benim sıcak hiçbir şeyim olmadı

Arkadaşlarım,ailem de

Yaşayamadım güzel duyguları

Gönlümün istediği gibi özgürce

Bir kedim vardı ısıtan

Onu da belediye zehirledi bir gece

Hey! söyleyin dürüstçe olanları bana,söyleyin

Ne seçtim kaderimi

Ne de kararını verdim hayata getirilmemde

Keşke ben de doğmuş olsaydım

Sizin gibi sıcak bir evde

En az sizin kadar mutlu olurdum

Mutluluğunuzun farkında olmasanız bile

Hey! Deneyin konuşmayı bir kere,deneyin

Nerede ezilmişlik,yıkılmışlık varsa 

Gidecektir sözlerim o yere

Biliyorum iğrendirici olsam bile 

Pırıl pırıl umutlar var hala içimde

Milyon kere avuç açsam da

Belki bir tutan olacaktır bir gün ellerimi de

Hey! Kurtarın beni uçurumdan,kurtarın

Adam olmak insan olmak istiyorum

Herkes gibi ben de

Uçuruma atmayın 

Ailem,param pulum,şöhretim yok diye

Zaten bin tokat yemiş bu yürek 

İyileştirin onu sevginizle

Hey! Geçip gitmeyin yanımdan,geçip gitmeyin

Buradayım diyorum ama 

Boğuyorsunuz beni her geçişinizde 

Sağır sultanı oynuyorsunuz

Benim kurbanı oynadığım gibi siz de

Hayat madem bir tiyatro

Perdeyi kapayın kahkahalarınızla öyleyse

Çünkü artık ben dayanamıyorum 

Bu komedi düzene 

Çünkü ben sokak çocuğuyum 

Kader mahkumuyum,her ne dersen de

Geçip gidin yanımdan 

Siz de cezamı verin önemsememenizle

Önemsemeyin zaten

Elbet gelecektir tanrı huzurunda hesap günü de

İşte bu son perde! ! ! 

				Sokak çocuklarına….', 'Hey! Size söylüyorum,size Görmemezlikten gelmeyin gerçeğim ben de Ne yapmalıyım görmeniz için  Bakmalı mıyım ki gözlerinize  Parçalama niyet...', ARRAY['Türk Edebiyatı','Şiir','Zahir Kılıç']::text[], 8.5, '{"poet":"Zahir Kılıç","poet_slug":"zahir-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/sokak-cocuklari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adına Islanıyor Saçlarım', 'adina-islaniyor-saclarim-ali-osman-donmez-fh3x9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yabancı bir şehrin sokaklarında 

Meçhule uzayan adımlarımdasın 

Dışımda bulut akar, gece akar, zaman akar, 

İçimdeyse sen akarsın! 

Bilirsin ki; 

Kuzey rüzgarları beslenir saçlarımda 

Ve yangın havasında yağar benim kar''ım 

Serseri yağmurlar altında 

Adına ıslanıyor saçlarım 

Sokak lambaları fersiz yanar 

Binbir fısıltıyı besler yapraklar 

Işık yılı uzaklığınca 

Çaresizliğe kodlanmıştır numaralar 

Telefon tuşlarında kalıyor yarım 

Serseri yağmurlar altında 

Adına ıslanıyor saçlarım 

Zamane atlıları çalar aklımı 

Duvarlarda iz sürer gölgem 

Bulutlara yaslanır soylu isyanlarım

İçimde dalgalanır karmakarışık mekanlar 

Bir ışık ses verir, her şey ses olur 

Seslerin kaynağında sen varsın ben varım 

Serseri yağmurlar altında 

Adına ıslanıyor saçlarım 

Gün doğacak, gün batacak, zaman akacak 

Bulutlar okşayacak gecenin saçlarını 

Damla damla anılar birikecek hücrelerimde 

Nice kaldırımlar öpecek ayaklarım 

Sessiz çığlıklar büyütecek dudaklarım 

Ve yine yangın havasında yağacak benim kar''ım 

Serseri yağmurlar altında 

Adına ıslanacak saçlarım 

Adına ıslanacak saçlarım

(Adına Islanıyor Saçlarım''dan)', 'Yabancı bir şehrin sokaklarında  Meçhule uzayan adımlarımdasın  Dışımda bulut akar, gece akar, zaman akar,  İçimdeyse sen akarsın!  Bilirsin...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Dönmez']::text[], 8.5, '{"poet":"Ali Osman Dönmez","poet_slug":"ali-osman-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/adina-islaniyor-saclarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Kalır', 'gozlerin-kalir-ali-osman-donmez-7ip72', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüzne bir anlam verilir; 

Adı:geri dönülmeyen veda olmuştur

Üşümüştür çam ağaçları dağlarda

Yenilgiye demir atmıştır, gönül limanında martılar

Sokak lambalarının ürkek ışığında 

Yürümüştür yıldızlardan hücrelere doğru mekan

Daralmıştır gökyüzü, olmuştur karanlık bir tavan

Umutların sıkıldığı bu anda

Sen bir anlamsındır kocaman 

Her veda mevsiminin garında

Hıçkırık sesleri vardır duyulmayan

Borular çalınmıştır, emir verilmiştir

Ordular yol almadadır çorak ülkelere

Eski tılsımını yitirmiştir saatler

Bomboş bir akıştır artık zaman

Ve ışıyordur karanlığın çaresiz penceresinde

Hayatın bu yitik diliminde

Sen bir özlemsindir kocaman

Geceler kana bulanmıştır

Akıyordur denizlerin serin koynuna

Ne nehirler vardır damarlarımı zorlayan

Deltası da benimdir, vadisi de

Gözlerim kapanmıştır, gökyüzü karanlıktır

Saçlara un elenmiştir

Dizlerimde 7.4’lük zelzele

Cılız birkaç nefes kalmıştır hayata bakan

Aslında bu bir hicrettir umudun veda garından

Terekemde birkaç mısrayla

Gözlerin kalır

Ve bir meçhul olursun kocaman

(Adına Islanıyor Saçlarım''dan)', 'Hüzne bir anlam verilir;  Adı:geri dönülmeyen veda olmuştur Üşümüştür çam ağaçları dağlarda Yenilgiye demir atmıştır, gönül limanında martıl...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Dönmez']::text[], 8.5, '{"poet":"Ali Osman Dönmez","poet_slug":"ali-osman-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gozlerin-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-ali-osman-donmez-ncohu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Ettik o kadar ref-i taayyün ki Neşâti 

Ayine-i pür tab-ı mücellâda nihânız.'' 

                                         - Neşati 

Ruhumuzun titrek heykeli değil 

Cismin kabuğu bakar aynalarda 

Üst üste helezon, üst üste şekil 

Varlığın küfü akar aynalarda 

Bir dem gelir, tadı kalmaz hayatın 

Gözde, ülfeti tüter kâinatın 

Bir dem gelir, değişmez hakikatin 

Sessiz şimşeği çakar aynalarda 

Bir gün kös vurulur, sallar yapıyı 

Son rüzgâr, son kez aralar kapıyı 

Şafaktan ziyade guruba kıyı 

Solgun şeklimiz sarkar aynalarda

sızıntı ekim2002

edebiyat ikliminde seyahat-3-2004', '''Ettik o kadar ref-i taayyün ki Neşâti  Ayine-i pür tab-ı mücellâda nihânız.''                                           - Neşati  Ruhumuzun ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Dönmez']::text[], 8.5, '{"poet":"Ali Osman Dönmez","poet_slug":"ali-osman-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aynalar-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenen Kalem', 'tukenen-kalem-ali-osman-donmez-q0dtd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Meltem meltem nefesimle

Kıyınızda dolaştım bir ömür

Kalplerinize duygu,

Duygularınıza dil oldum.

Çoşkun ırmaklar gibi

İkliminize aktım damar damar

Kışlar bitti,

Ben bittim.

Şimdi, behçelerde şen şakrak bir bahar.

Miadım dolmuşsa bana kim bakar! 

Bir sürgünse bu, sürgündeyim

Dilimdeki anlamlar yalnız beni yakar

Volkanlar kaynar kuytularımda

Yadımdaki pınarlar susar

Ve benim için

Her limandan,

Meçhule bir gemi kalkar 

Gidiyorum…

Geride bir şey değişmeyecek

Yağmurlar yağacak

Çiçekler açacak

Bahçeleri süsleyecek yine şen şakrak bir bahar

Lakin

Gök kubbeden sesim kesilecek,

Öksüz kalacak hatıralar

Ve bir dünya eksilecek içinizden

Sadece ben kadar

sızıntı aralık2002', 'Meltem meltem nefesimle Kıyınızda dolaştım bir ömür Kalplerinize duygu, Duygularınıza dil oldum. Çoşkun ırmaklar gibi İkliminize aktım damar...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Dönmez']::text[], 8.5, '{"poet":"Ali Osman Dönmez","poet_slug":"ali-osman-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tukenen-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin Neden ıslak?', 'ellerin-neden-islak-mine-ozdemirtas-gtxcs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yum demeden

yummuştum gözlerimi.

Oysa ki,

usulca uzatıp ellerini

yerinden söktüğün

Benim Yüreğimdi.

Okşarken sevdanın yeli

acımadı hiç

kanamadı yeri

Bunun için sana

teşekkürler sevgili.

Sendeyken yüreğim; sahibinden izinliydi.

İç cebinde bunca zaman keyifle gezindi 

Kabul et ki,

Ayak sürüyüp te dönmek için geri

Hiç tutturmadı /Seni hiç üzmedi  değil mi? 

Demek ki... o artık... itibar''ı iadeyi  hak etti.

Şimdilerde 

gördüğüm o ki,

giymiyorsun nicedir

eskittiğin ceketi.

ya İç cebinde ki? 

Ne olacak şimdi? 

Tamam... susuyorum sevgili.

Kısaca diyelim ki............... bitti.

Emaneti aldığın gibi usulcacık

koyman için geri

yumdum yine gözlerimi

Umarım, bu seferde

acıtmadan

kullanırsın  ellerini.

Peki......

Ellerin neden ıslak?

Yoksa.....! ! ! ! ! 

ağlattım mı seni? 



5/4/2004', 'Yum demeden yummuştum gözlerimi. Oysa ki, usulca uzatıp ellerini yerinden söktüğün Benim Yüreğimdi. Okşarken sevdanın yeli acımadı hiç kanam...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ellerin-neden-islak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam ''Sahnede''', 'bir-adam-sahnede-sirma-mersin-4q21y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatın doğurduğu bir kukla! 

Her gece aynı mekanda; 

Onca kalabalığı güldürürken...

Gökkuşağından saçları,

Kocaman kırmızı burnu,

Kendinden büyük ayakkabıları ile,

Hokkabazlık yapıp; 

Şansının kumarını oynayan kaderle, dalga geçerken,

Güldürürken düşündüren,

Bir adam! 

Bir adam; sahnede ışıkların altında, 

Rolünü oynarken; ömrünü tüketiyordu, zamana karşı...

Aslında! 

O adam hayallerine ağlıyordu,

Her gece...

05.04.04', 'Hayatın doğurduğu bir kukla!  Her gece aynı mekanda;  Onca kalabalığı güldürürken... Gökkuşağından saçları, Kocaman kırmızı burnu, Kendinden...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-adam-sahnede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim Ve Sen', 'hayallerim-ve-sen-sirma-mersin-hgfcm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yılan gibi aramıza giren, ayrılık...

Hayallerimi, kanlı kabuslara döndüren zaman... 

Kopardı, bizi bizden! 

Yüreğime, sensizliğin hançerini batırdıkca; 

Özlemin acı çığlıkları yankılandı, kulaklarımda...

Oysa! 

Bir beyaz güvercin kanadında; 

Mavi bulutların arasında, gelen mektupta...

Şafak günü sayan bir askerin; 

Özlem dolu satırlarındaki bekleyişte,

Seni düşünmek...

Bir bebeğin; 

Ninnilerle uykuya dalan gözlerinde,

Seni görmek...

Ruhuma dokunan ellerinle; 

El değmemiş duygularımla,

Seni yaşamak...

Hayallerin, en güzeli idi....

Zamansız ayrılıkların; 

Özlemleri çoğaltığı bir anda,

Gerçeğe düşen gözyaşları,

Seni bana getirecek...

05.04.04', 'Bir yılan gibi aramıza giren, ayrılık... Hayallerimi, kanlı kabuslara döndüren zaman...  Kopardı, bizi bizden!  Yüreğime, sensizliğin hançer...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayallerim-ve-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Hanımın Şoförü', 'kucuk-hanimin-soforu-mine-ozdemirtas-fjmr9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık,Bana nanik yapamayacaksın

Aynalardaki Küçük Hanım.! ! ! 

Bundan sonra........sen de benim gibi yayasın. 

Haberin olsun...... Şoförü işten çıkardım.', 'Artık,Bana nanik yapamayacaksın Aynalardaki Küçük Hanım.! ! !  Bundan sonra........sen de benim gibi yayasın.  Haberin olsun...... Şoförü iş...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kucuk-hanimin-soforu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban Gülü ve Genç Şair', 'yaban-gulu-ve-genc-sair-hasan-arican-fue0m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koskocaman yaban gülü çalılığı

Çiçekleri açmış yarı beyaz yarı pembemsi

Uzaklardan görünümü kocaman bir gül demeti 

Yağmur çiseliyor uzun süreden beri

Bir genç, abasına bürünmüş yaban gülünün altında oturuyor

Böyle bir ortamda ilham gelmiş; 

Sevdiği için şiir yazıyor

Yerinden kopan gülün yaprakları üzerine dökülüyor gencin

Genç ve körpe bir yaşam yaşlanmaya ilk adımlarını atıyor

Yaşlılıkta bu görünümü anmak, bir an olsa da gençliği tekrar yaşatıyor.', 'Koskocaman yaban gülü çalılığı Çiçekleri açmış yarı beyaz yarı pembemsi Uzaklardan görünümü kocaman bir gül demeti  Yağmur çiseliyor uzun sü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Arıcan']::text[], 8.5, '{"poet":"Hasan Arıcan","poet_slug":"hasan-arican","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yaban-gulu-ve-genc-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dervişin Fikri mi, Zikri mi', 'dervisin-fikri-mi-zikri-mi-i-brahim-bayraktar-0z2ph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir mektup aldım, gönül ehlinden,

Fakire, fukaraya selâmı varmış,

Çok doluymuş gamdan, kederden,

Size arz edecek meramı varmış.

Zorbalar kaçar olmuş haktan, yasadan,

Garipler; yorgan, döşek yatar tasadan,

Bu ağır hasta kalkmaz diyor masadan,

Daha söyleyecek kelâmı varmış.

Düşkün bir anını bekler olmuşlar,

Değişik isimlerle içine dolmuşlar,

Her zaman kendilerine yer bulmuşlar,

Henüz bitmemiş, devamı varmış.

Kuşlar konmazmış artık dalına,

Kendi güler olmuş kendi haline,

Çare bulmak için düşüp yoluna,

Geride kalanlara selâmı varmış.

Hangi posta girse ot teper gidermiş,

Çobansız köylerde aylak gezermiş,

Sıkılmadan demokratlık güdermiş,

Her Derviş’in bir de Kemâl’i varmış.

Dört yandan sarmışlar akın akın,

Sinsice yaklaşıyor kargalar bakın,

Geleni bir kıvılcım sanmayın sakın,

Bundan daha büyük belâ mı varmış? 

05.04.2004', 'Bir mektup aldım, gönül ehlinden, Fakire, fukaraya selâmı varmış, Çok doluymuş gamdan, kederden, Size arz edecek meramı varmış. Zorbalar kaç...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dervisin-fikri-mi-zikri-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Helvası', 'dus-helvasi-i-brahim-bayraktar-ivmh7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbimin derinliklerinde doğan,

Bir ışıktın sen,

Hayallerimle ektiğim,

Aşkımla besleyip,

Gönlümde büyüttüğüm.

Halbuki; 

Kaf dağının ardındaymış sana kavuşmak,

Cümle alem bilirmiş de; 

Ben, farkında değilmişim.

Onunla dolu onsuz geçerken günlerim, 

Dilinde hep aynı şarkı vardı:

“Benden sana yar olmaz.”

Derdi de inanmazdım,

İnanmak istemezdim,

Sadece şarkı der geçerdim,

Oysa; düşümde yaptığım helvanın,

Şerbeti ayrılıkmış.

05.04.2004', 'Kalbimin derinliklerinde doğan, Bir ışıktın sen, Hayallerimle ektiğim, Aşkımla besleyip, Gönlümde büyüttüğüm. Halbuki;  Kaf dağının ardınday...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Bayraktar']::text[], 8.5, '{"poet":"İbrahim Bayraktar","poet_slug":"i-brahim-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dus-helvasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümseme', 'gulumseme-murat-cimen-2-gq5ks', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimse bilmez,

Ne fırtınalar koptuğunu yüreğimde,

Ve kaç umut battı gönlümde.

Batık umutlar mezarlığım var benim.

Kapılarını sadece tek başımayken,

Kendime açtığım.

O mezarlığın etrafında hayat çok güzel; 

Yeşillikler dolu bir bahçeyle çevrili

Ve işte siz beni hep o bahçenin arkasından görüyorsunuz.

Bu yüzden yüzümde bir gülümseme var.

Sadece sizin gördüğünüz.

Benimse orda olduğunu bile bilmediğim', 'Kimse bilmez, Ne fırtınalar koptuğunu yüreğimde, Ve kaç umut battı gönlümde. Batık umutlar mezarlığım var benim. Kapılarını sadece tek başım...', ARRAY['Türk Edebiyatı','Şiir','Murat Çimen 2']::text[], 8.5, '{"poet":"Murat Çimen 2","poet_slug":"murat-cimen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulumseme-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalandır Ayrılığın', 'yalandir-ayriligin-galip-karabatak-hbcva', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünce fikrime o yıldız gözlerin

Ne önemi kalırki artık kancık sözlerin

Ne yana baksam dururken izlerin

Yalandır ayrılığın, 

Ben yalan söyleyemem...

Ne güzeldi günlerim, yaşıyorken seninle

Sevmiştik birbirimizi tertemiz bir yeminle

İşte söylüyorum ki şimdi, beni iyi dinle

Yalandır ayrılığın,

Ben yalan söyleyemem...

Kaçtığını sanıyorsun benden kendince,

Oysa kaçmak çok zor iş, böyle sevince

Mecun çölü aşıp, ferhat dağı delince,

Yalandır ayrılığın,

Ben yalan söyleyemem...

Sen gitsen de benden, durma hadi git

Söylenmemiş bir yalan gibi, sen de tüken bit

Elbet beni andığın o çaresiz vakit

Yalandır ayrılığın,

Ben yalan söyleyemem....', 'Düşünce fikrime o yıldız gözlerin Ne önemi kalırki artık kancık sözlerin Ne yana baksam dururken izlerin Yalandır ayrılığın,  Ben yalan söyl...', ARRAY['Türk Edebiyatı','Şiir','Galip Karabatak']::text[], 8.5, '{"poet":"Galip Karabatak","poet_slug":"galip-karabatak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalandir-ayriligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç-Toprak-Kitap', 'agac-toprak-kitap-goktu-kara-8v9qx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şeyin aynı olması normal

bu dünyada

çekilmez oluyor bazan hayat

işte o zaman sarıldığım hazinelerimdir onlar

bugün serin bir rüzgar eserken yüzüme

bunları düşündüm

eğilmem gerekmez insanlara

ben sizler için eğileceğim

yatağımda yalnız sizler olacaksınız

ve her zaman yanıbaşımda', 'Her şeyin aynı olması normal bu dünyada çekilmez oluyor bazan hayat işte o zaman sarıldığım hazinelerimdir onlar bugün serin bir rüzgar eser...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/agac-toprak-kitap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin?', 'neredesin-ersan-kurt-gp626', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Avaz avaz susuyorum, 

sesimi duyuyor musun? 

Kalemim seni arıyor, çok keskin

sen nerelerdesin? 

Bir susuyor bir bağırıyorum

birinden birini duyarsın diye

bende kalan yüreğini dağlıyorum 

belki acısını duyarsın diye.

Kalemim seni arıyor, diş biliyor

sen nerelerdesin? 

5 Nisan 2004, Kuzey Denizi', 'Avaz avaz susuyorum,  sesimi duyuyor musun?  Kalemim seni arıyor, çok keskin sen nerelerdesin?  Bir susuyor bir bağırıyorum birinden birini ...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/neredesin-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-sair-sehzade-wyzuz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duyun beni cevap verin aynalar,

Nerde gözüm gibi baktığım saçlar.

Gençliğimi geri verin aynalar,

Gelsin kır çiçeği taktığım saçlar.

Ne oldu bir anda vurgunmu yedi,

Hepsi teker teker boynunu eğdi,

Gözemi geldiler nazarmı değdi,

Nerde al kınalar yaktığım saçlar.

Ne vakit sevdanın rüzgarı esti,

Canım güzellikten umudu kesti,

Makasa darıldı tarağa küstü,

Soldu süslemekten bıktığım saçlar.

Her gün avuç avuç ele geldiler,

Sanki isyan edip dile geldiler,

Bu haline yola yola geldiler,

Bir ömür ah ile çektiğim saçlar.

Kalbimde küllenmiş bir aşk yatıyor,

Gizlenmiyor hemen göze batıyor,

Bir tek iz var onu hatırlatıyor,

İşte o uğruna döktüğüm saçlar.', 'Duyun beni cevap verin aynalar, Nerde gözüm gibi baktığım saçlar. Gençliğimi geri verin aynalar, Gelsin kır çiçeği taktığım saçlar. Ne oldu ...', ARRAY['Türk Edebiyatı','Şiir','Şair Sehzade']::text[], 8.5, '{"poet":"Şair Sehzade","poet_slug":"sair-sehzade","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aynalar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlünde Beni Bulacaksın', 'gonlunde-beni-bulacaksin-nigar-adak-khlkk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senle yeşermişti baharım

Sendin gönlümün efsanesi

Senle güçlüydü kanatlarım

Aşkımın kanayan perdesi

Coşarak dolardım gecene 

Gözlerim gözlerine tapardı

Çılgındım hudutsuz sevgine 

Okşayışların zincirleri kırardı

Baktığın manalı gözlerde

İhtirasla ona dokunurken

Beni bulacaksın hayalinde

Pişmanlık ruhunu sararken

Ardında enkazlar bıraktın

Sanma ki mutlu olacaksın

Olsa da sonsuz saltanatın

Gönlünde beni bulacaksın

05.04.2003

Nigar Adak 

Dikkat: Şiirlerimin hepsi noter tasdiklidir..! Şair adı olmadan alıntı yapılamaz..!', 'Senle yeşermişti baharım Sendin gönlümün efsanesi Senle güçlüydü kanatlarım Aşkımın kanayan perdesi Coşarak dolardım gecene  Gözlerim gözler...', ARRAY['Türk Edebiyatı','Şiir','Nigar Adak']::text[], 8.5, '{"poet":"Nigar Adak","poet_slug":"nigar-adak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gonlunde-beni-bulacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fısılda', 'fisilda-zafer-zengin-etnika-psllb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazma 

Şiirini ! 

Kulağıma

Fısılda...

Tutmuşum

Nefesimi...

Sessiz bir 

Göç var içimde...

Kıpırdama / A Ğ L A M A...

5 Nisan 2004   '' İçimin Kİtabı ''', 'Yazma  Şiirini !  Kulağıma Fısılda... Tutmuşum Nefesimi... Sessiz bir  Göç var içimde... Kıpırdama / A Ğ L A M A... 5 Nisan 2004   '' İçimin ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/fisilda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayakta Öl', 'ayakta-ol-umit-kilislioglu-ozger-8ders', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinlenmeler yazılmamış ona

Yumuşacık divanlarda; 

Çalış, çabala demiş kader,

Çırpın, didin, 

Sonunda, ayakta öl....

'' Ne yapalım yani! 

Hastaysan hastasın, yastaysan yastasın

Bunlar duraklaman için bahane mi! 

Çekip çevirmelisin hanemi.''

Genç kızlık hayallerini her hatırlayışta ağla,

Yediğin her dayakta öl...

''Anlaşıldı, gidicisin,

Pek zamanın kalmadı...

Ama kadın! , karnım aç! , ev soğuk! 

Yemeği ısıt,

Sobayı yak da öl...''

(5.4.2004)', 'Dinlenmeler yazılmamış ona Yumuşacık divanlarda;  Çalış, çabala demiş kader, Çırpın, didin,  Sonunda, ayakta öl.... '' Ne yapalım yani!  Hast...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kilislioğlu Özger']::text[], 8.5, '{"poet":"Ümit Kilislioğlu Özger","poet_slug":"umit-kilislioglu-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayakta-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cellat', 'cellat-metin-oz-gkjhr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir cellat vursun başımı

Görmeyin kanımla karışmış,göz yaşımı

İşte tam şuramda yaram

İstersen çıkar 

Korkma kanasın

Aksın parmaklarının arasından

Yüreğim kalsın avuçlarında

Sen göm beni ellerinle,kefensiz toprağa

Doldur toprağı yüreğimin boş kalan yerine

Şimdi bu dünyadan

Başka bir sonsuzluğa

Yüreğimi sende bırakarak gideceğim.', 'Bir cellat vursun başımı Görmeyin kanımla karışmış,göz yaşımı İşte tam şuramda yaram İstersen çıkar  Korkma kanasın Aksın parmaklarının aras...', ARRAY['Türk Edebiyatı','Şiir','Metin Öz']::text[], 8.5, '{"poet":"Metin Öz","poet_slug":"metin-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cellat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heybet kelimesinin mânâ bulduğu, Molla Gürânî Hazretleri', 'heybet-kelimesinin-m-n-buldugu-molla-gur-n-hazretleri-mustafa-engin-karatay-pcd4t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1440’lar filandır. Hani II. Murat Hân''ın hüküm sürdüğü yıllar. Devrin âlimlerinden Molla Yegân hacca gider. Dönüşünde Kâhire’de mola verir. İlim meclislerine katılır. Üç beş gün de olsa, dağarcığını doldurmaya çalışır.

İşte bu sohbetlerden birinde, genç ama heybetli bir âlim dikkatini çeker. Az konuşur, öz konuşur. İfâdeleri sâde, ama sağlamdır. İnsanların zor kavrayacağı mevzûlardan konuşur, ama onu çocuklar bile anlar. Tek cümleye ciltleri sığdırır sonra. Söz ona geldiğinde cemaât taş kesilir, nefesini tutar. Edeple hisse kapmaya bakarlar.

Molla Yegân bu vakara, bu heybete âşık olur. Çıkışta cesâretini toplayıp yaklaşır, “Senin” der, “Buralarda zâyi olmana dayanamam. Eğer ilminin kıtalar ötesinde yankılanmasını istiyorsan, hiç düşünme, gel benimle! ”

Genç âlimin dünyâlıkta gözü yoktur. Ancak “hizmet! ” denilince akan sular durur. Hem böylesine samîmi bir teklife nasıl “hayır” denir ki? 

Molla Yegân Edirne''ye varınca Sultân''ı ziyâret eder. Murat Hân lâtifeyle takılır: “Bize oralardan ne getirdin? ”

Molla Yegân “Öyle bir âlim getirdim ki Sultânım.” der, “Târifi gayri kâbil, meğer ki tanışsanız gerek! ” Padişâh merâkla sorar:

-Nerede? 

-Dışarıda efendim.

-Aman ha, bekletmek ne haddimize.

Ve buyur ederler. Mübâreğin önce gölgesi düşer eşiğe. Sonra dağ gibi bir adam girer. Başı âdetâ tavana değer, esmerdir. Sarığından taşan saçları heybet verir ona. Sakalı simsiyahtır, hattâ siyah ötesi. Ama dişleri inci incidir ve gözleri ateş gibi. Mütebessimdir, lâkin düğme ilikletir insana. O koca koca ağalar, vezirler toparlanma ihtiyâcı hissederler. Sükûtu Molla Yegân bozar. “İsmi Ahmed bin İsmâil efendim” der. “Ama Araplar onu Molla Gürânî diye tanırlar. Sûriyelidir.” Murat Hân''ın içi ılıcık olur, bu âlime kanı kaynar. Önce Hüdâvendigâr medresesine tâyin eder, ardından Yıldırım Medreselerini de ona bağlar. Zaman Molla Yegân’ı haklı çıkarır. Bu kutlu ocaklardan pırıl pırıl âlimler yetişir ve diğerlerine fark atarlar. Öyle ya Molla Gürânî’de okumak bir ayrıcalıktır.

ZOR ŞEHZÂDE

Şehzade Mehmet (Fâtih)   çok zekîdir, ancak ele avuca sığmaz. Derslerini bellemekte zorlanmaz, ama hiç çalışmaz. Hele ezberle işi olmaz. Çok hocada okur, ama tamamını yıldırır. Zaman zaman öğretmenlerini makaraya alır.

Hatta bir keresinde hocasını durdurur:

-Aman efendim, ne yapıyorsunuz? der.

-Anlayamadım? 

-Mermere basıyorsunuz! 

-Eee ne var bunda? 

-Az evvel okuttunuz ya hocam. Meryem Vâlidemiz İsâ Aleyhisselâm’ı taş üstünde getirmedi mi Dünyâ''ya. Öyleyse mermere hürmet gerek.

-Yaa... Öyleyse çıkar bakayım çorabını! 

-Niye hocam? 

-Bilmiyor musun aynı Meryem Vâlidemiz. İsâ Aleyhisselâm''ın beşiğini de yün ile örttü. Öyleyse örgüye hürmet gerek.

Ama bütün hocalar böyle hazır cevap olamazlar. Mehmed bir padişâh oğludur ve kendisi istemedikten sonra kimse diz çöktüremez O''na.

Murat Hân sıkıntının farkındadır. Evet Molla Yegân, Molla Fenâri, Molla Ayas muhteşem âlimlerdir. Ancak bu haşarı Şehzâde''yle uğraşmak, on medrese yönetmekten zor olmalıdır. “Acaba onu kim yola getirebilir? ” diye düşünürken Molla Gürânî’nin sîmâsı belirir gözünde. O âna kadar nasıl da aklına getiremediğine şaşar. Tabii, öyle ya. Dudaklarına alaycı bir tebessüm yayılır. “Hadi bakalım” diye mırıldanır, “Şimdi derslerini kır da, göreyim seni”

SENİ ÖYLE BİR DÖVERİM Kİ! 

Padişâh Molla Gürânî hazretlerini yollarken “Eti de senin” der, “kemiği de. O bundan böyle senin oğlun. Var bildiğin gibi işle! ”

Mübârek Manisa’ya vardığı saat, Şehzâde''yi derse çağırır. Uşaklara bile itibâr eder, ama geleceğin Sultânı''nı görmezden gelir. Talebesine sıradan biri gibi davranır ve “Otur! ” der, “Hayır oraya değil, şuraya! ” O güne kadar emretmeye alışan Şehzâde şaşakalır. Belki de hayâtında ilk kez diz çöker. Molla emsileyi açar ve emreder: “Darabe (Dövmek)   fiilini çek bakayım! ” Fâtih fiili kafasına göre çeker. Çat pat bir şeyler söyler işte. Molla Gürânî’nin kaşları yıkılır, kafasını “olmadı” gibilerden sallar, bakışlarıyla azarlar. Sonra üstüne basa basa fiili çeker ve sesini yükselterek misâllendirir: “Döverim, seni döverim, seni öyle bir döverim ki! ..”

Fâtih ağlamaklıdır. Dudakları uçuklaya yazar. Korkudan sesi titrer. İçinden son cümleyi tekrâr eder. “Darabtühü cidden şedîden.” İnanın döver mi döver. Bundan böyle saray halkına rezîl olmak da vardır işin içinde.

Şehzâde artık geceleri ödev yapmaya başlar ve ezberlerini aksatmaz. Daha doğrusu aksatamaz. Ama gün gelir ilmin tadını alır. Eski haşarılıklarından utanır. Çok değil üç beş ay sonra bambaşka biridir o. Molla Gürânî Hazretleri “Arabî ve Fârisî bilmek yetmez” der, “Düşmanlarının da lisânını öğrenmelisin! ” Nitekim Fâtih; Latince, Sırpça ve Rumca öğrenir. Hem konuşur hem yazar.

Ardından “kâfirdir” demez, Şehzâde''yi İtalyan asıllı Anconal Giriaco’nun önüne oturtur, Avrupa Târihi''ni okutturur. Dahası neme gerek dedirtmez, aritmetiğe, geometriye, astronomiye zorlar. Hepsi bir yana ufkunu açar. İnanç aşılar. Eğer istenirse gemilerin karadan, kağnıların sudan yürüyebileceğine inandırır.

Bir ara Manisa’ya gelen Sultân Murat, oğlunu tanıyamaz. Fâtih görünüşte çocuktur, ama çok olgundur. Ufku geniştir sonra. Hedefleri, ideâlleri vardır. Ki, İstanbul bunlardan biridir sadece. İşte belki de bu yüzden tahtını düşünmeden bırakır O''na.

Sultân Murat, Molla Gürânî’ye şükrânlarını sunarken kelime seçmekte zorlanır. Hatta gözü kapalı vezirlik teklif eder. Mübârek boş versene gibilerden omuzunu silker. “Onu isteyene verin Sultânım” der, “Yıllardır bu makâma ulaşmak için çalışanları kırmayın. Dostlarınızdan olmayın sonra! ”

Ancak kadılığı reddetmek gibi bir şansı olmaz. Nitekim bir müddet devlet erkânıyla çalışır. Ancak fırsatını bulduğu an ayrılır, apar topar Kâhire’ye döner. Belki de vebâlden kaçar.

HASRET

Mısır Sultânı Kayıtbay, Molla Gürânî Hazretleri''nin kıymetini iyi bilir. Kâhire ne zamandır bu gür sese hasrettir ve Mısır''lılar O''nu ne kadar özlediklerini anlarlar.

Fâtih, Hocası''nın Mısır’a döndüğünü duyunca yıkılır. İşte tam o günlerde de koca devlet kalmaz mı eline. Şimdi kolu bacağı kesilmiş gibidir. Ona öyle çok, ama öyle çok ihtiyâcı vardır ki. Bu güçlü ses yanında olmadan ideâllerine kim inanır? Hem ne kadarını gerçekleştirebilir ki? 

Hemen alır eline diviti, Kayıtbay’a bir mektup yazar. Ağlamaklı bir üslûpla Hocası''nı ister.

Kayıtbay, Molla Gürânî Hazretleri''ne hem haberi iletir, hem de “Gitmeyin hocam! ” der, “size ne vaâd ediyorsa, fazlasını vereyim! ”

Molla Gürânî acı acı güler, zor duyulan bir sesle “Sizin veremiyeceğinizi vaâd ediyor” der, “Evlatlık! ” Ardından “ Müsaade edin gideyim” der, “Benim yüzümden aranıza husûmet girmesin.” Fâtih, Molla Gürânî Hazretleri''ni görünce çocuklar gibi sevinir. Hocası''na eserlerini rahatlıkla yazabileceği mekânlar sağlar, ardından Şeyh-ül İslâm''lık makâmına getirir.

Aradan yıllar geçer. Fâtih, her sultâna nasip olmayan zaferler kazanır. Çağlar açar çağlar kapar. Şimdi ayakları yere sağlam basan bir imparatorluğu vardır. Etrafında usta askerler, bilge vezirler ve güçlü sanatkârlar dolanır. Dahası bütün dizginler elindedir artık. Ama en şaşaâlı günlerinde bile Molla Gürânî Hazretleri''yle karşılaşınca dizlerinin bağı çözülür. Adımlarını şaşırır. Zîrâ; mübârek O''na, Cihân Padişâhı gibi değil, Manisa’da ders okuyan haylaz Şehzâde gibi davranır. Yanlışlarını evirip çevirmeden söyler yüzüne.

SARAYDA İŞİM NE? 

Osmanlı sarayında sıradan hadiseler bile birer törendir. Bırakın divân ve elçi karşılama faslını, Padişâh''ın oturması kalkması, yemesi içmesi dahi merâsimdir. Ancak Molla Gürânî Hazretleri kurallara itibâr etmez, ama mevcûd düzeni çiğnemek de istemez. Sırf bu yüzden ayağını atmaz saraya. Ama bir Arefe Günü Fâtih, “Sizinle bayram başka güzel. Teşrif ederseniz bu fakiri sevindirirsiniz” diye haber yollar. Molla Gürânî Hazretleri saray ulağına garip talebeleri gösterir.

“Biz bayramı bunlarla birlikte yapmayı düşünüyoruz” der, sonra elini umursamaz tavırlarla sallayıp “Hem bu yağmurda çamurda sarayda işim ne? ”

Fâtih mahzûn olur. Çocuk gibi içini çeker, halbuki der, “biz onların gelmesiyle bayram yapardık, bilmezler mi? ”

Mübârek bunu hissetmiş olmalı, ansızın çıkagelir. Ancak alkış, şiir, medhiyye, mehter, nevbet fasıllarına aldırmaz bile, bahçeyi atıyla geçerek bütün kâideleri alt üst eder. Belki de lisân-ı hâl ile “Gururlanma Padişâhım” der, “senden büyük Allah var! ”

HAYIRLI SON

Molla Gürânî Hazretleri Dünyâ makâmlarına rağbet etmez, ancak gençleri yükselmeye teşvik eder. Nitekim gün gelir müderrisliği de bırakır ve mütevâzı dergâhında bildiği usûllerle talebe yetiştirir. Özellikle kıraât (Kur’ân-ı Kerîm’i doğru okuma)   üzerinde çok durur.

Büyük Velî, gecelerini ibâdetle geçirir ve gündüzleri dâimâ oruçludur. Döner dolaşır ölümü anlatır ve ona hazırlanır. Nitekim bir gün talebelerini toplar. “Şimdi! ” der, “üzerinizde olan hakkımı ödeme zamanıdır. Açın bakayım Yâsin-i Şerif''i! ” Genç mollalar onun son yolculuğa çıkacağını anlar ve çok ağlarlar. Molla Gürânî her zamanki gibi sâkin ve mütebessimdir ama bir başka heybettir belirir yüzünde. “Bayezid’e söyleyin adâlet üzere olsun, insanları himâye, beldeleri muhâfaza etsin! ” buyurur. “Namazımı bizzat o kıldırsın ve borçlarımı (aslında borcu yoktur)   sâhiplensin. Size vasiyyetim şudur ki: 

-Beni garipler gibi defnedin. Mezarıma ayaklarımdan çeke çeke sürükleyin! 

Beyazıd Hân hem vasiyyete, hem de edebe riâyet etmek ister. O''nu yine çeke çeke sürüklerler, ama zarîf bir hasır üstünde.

Millet Caddesi''nden gün boyu otobüsler, tramvaylar geçiyor. Topkapı’ya, Eminönü’ne Milyonlar akıyor. Ama Molla Gürânî Hazretleri''nin Kabri''ni bilen o kadar az ki. Hani diyorum, Fındıkzâde yolumuzun üstü. Hiç değilse geçerken bir Fâtihâ okusak. İnanın buna O''ndan ziyâde, bizim ihtiyâcımız var. Allah-u Teâlâ, böylesi bir Gönül Ehli''ne nice şefaât izni verir bilemeyiz. Ama olur ya, belki o Dehşet Günü''nde bizi de hatırlar... Kim bilir? ..', '1440’lar filandır. Hani II. Murat Hân''ın hüküm sürdüğü yıllar. Devrin âlimlerinden Molla Yegân hacca gider. Dönüşünde Kâhire’de mola verir. ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/heybet-kelimesinin-mana-buldugu-molla-gurani-hazretleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara...', 'ara-zafer-zengin-etnika-f5k8z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnadına 

açıyorum 

gözümü 

karanlıkta

Türkün çıkıyor karşıma...

Sesin

siper

elime

Bakıyorum acele etmeden...

İyi ki

varsın 

diyorum

Baş edemem yoksa ayrılıkla...

Uykusuz

geceleri

sayıyorum

Seni düşününce ayrılıktan korkmuyorum...

Korkan 

içimdeki

afacankan

Beni deliyim biliyorsun...

Yaz 

diyorum

şaşkınlığımı

Genç geliyor gülüşün...

Teslimiyet

tanımıyor

yüreğim

Sen öl deyince ölüyorum...

Gülümserken

ölen

serçeyim

Kimliğim akdeniz kokuyor...

Gidiyorum

yangınlara

koşup

Tuzlu su içip ciğerimi kanatıyorum...

Elinde

kağıtlarını 

unutmadım

Kimseyi takmadan yaktığın...

Sen 

okurken

yazıtını

Ben sigaramla ağlıyordum...

Dumanıydı 

gözyaşım

isli

Saçlarına ellerimi saklamışım...

Unutup 

rengini 

tarama

Beni serçenin renginde ara/ara...

5 Nisan 2004  '' İçimin Kitabı ''', 'İnadına  açıyorum  gözümü  karanlıkta Türkün çıkıyor karşıma... Sesin siper elime Bakıyorum acele etmeden... İyi ki varsın  diyorum Baş edem...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ara-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamazsın', 'anlayamazsin-serdar-safran-zakeu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bebeğim,canım bir tanem sen

Kaygısız,tasasız büyüdün

İçimde kopan fırtınayı

Anlayamaz,anlayamazsın…

El bebek,gül bebek büyürken

Dünyaya toz pembe bakarken

Sen,damarımdan  kan çekilmiş

Anlayamaz,anlayamazsın…

Senin için günlüktür hayat

Başkasının çizdiği bu hat

Sığmıyor benim yüreğime

Anlayamaz,anlayamazsın…

Satılmak isterken vatanım

Dağlanır,yanar benim canım

Sızlar kemikleri,ecdâdım

Anlayamaz,anlayamazsın…

Çıkmak ister  bu can meydane

Bir şerbet içmektir bahane

Düğündür ölüm o an,cane

Anlayamaz,anlayamazsın…

(Mart/2004-Kastamonu)', 'Bebeğim,canım bir tanem sen Kaygısız,tasasız büyüdün İçimde kopan fırtınayı Anlayamaz,anlayamazsın… El bebek,gül bebek büyürken Dünyaya toz ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Safran']::text[], 8.5, '{"poet":"Serdar Safran","poet_slug":"serdar-safran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anlayamazsin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*~*~*~*~*GÜZELLiĞiN iÇiMDE...', 'guzelligin-icimde-baki-son-6uvcs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gemiler geçer boğazdan,

Gümüş rengi bulutları

Bırakır  arkalarında.

Sarar insanları

Günün hay-huyu

Akşam oluverir

Bu uykularda...

Akar gider,

Renklerle oynaşan SU.! 

Bahar olur

Hayallerde...

Mutlu yaşamak.

Akşam olur

________İstanbul''da

________________Boğaz da.

________________________Uzaklıklar da

Yine gemiler geçer

Mavi sulardan.

Yine bulutlar geçer.

Zaman...

Geçiverir,günlük  yaşanılarda

Güzellikler içinde,

Şiirden yoksun...! 

Solar gider 

Ömrümüzün baharı

Akşam...! 

________Oluverir

Bu uykularda...! ! !', 'Gemiler geçer boğazdan, Gümüş rengi bulutları Bırakır  arkalarında. Sarar insanları Günün hay-huyu Akşam oluverir Bu uykularda... Akar gider...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/guzelligin-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* İdam! *', 'i-dam-erdal-asik-tbe5i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni unuttum artık/

gözlerimi kapattığımda 

hayalini görmüyorum,

düşlerimde düşüncemde yoksun, 

seni unuttum...

geceleri rüyamda görmüyorum seni,

yoksun yanımda 

unuttum diyorum seni yazıyorum

ve bu sebepten,

seni unutmak için kalemimi kırıyorum! 

seni unuttum...', 'seni unuttum artık/ gözlerimi kapattığımda  hayalini görmüyorum, düşlerimde düşüncemde yoksun,  seni unuttum... geceleri rüyamda görmüyorum ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Aşık']::text[], 8.5, '{"poet":"Erdal Aşık","poet_slug":"erdal-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/idam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğuna', 'yokluguna-tamer-sonmezisik-ikfdq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hecelemek ismindeki sesli harfleri,

Sessizlerle gecelemek mum ışığında.

Yankısıyla terlemek,kısa bi mesajı kısıp

Beklemek sabahı; 

Sabahın ağrısız kanamasını...', 'Hecelemek ismindeki sesli harfleri, Sessizlerle gecelemek mum ışığında. Yankısıyla terlemek,kısa bi mesajı kısıp Beklemek sabahı;  Sabahın a...', ARRAY['Türk Edebiyatı','Şiir','Tamer Sönmezışık']::text[], 8.5, '{"poet":"Tamer Sönmezışık","poet_slug":"tamer-sonmezisik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yokluguna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar', 'martilar-tamer-sonmezisik-7q6zx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suskunluğumdu beni esir alan,

Bir eski zamanda kayıptı vadideki uçurumlar.

Tebessümün bin liralık bir ömrü kalmıştı yitiklikte; ve

Kasımda ağlarsam susuyordu martılar...', 'Suskunluğumdu beni esir alan, Bir eski zamanda kayıptı vadideki uçurumlar. Tebessümün bin liralık bir ömrü kalmıştı yitiklikte; ve Kasımda a...', ARRAY['Türk Edebiyatı','Şiir','Tamer Sönmezışık']::text[], 8.5, '{"poet":"Tamer Sönmezışık","poet_slug":"tamer-sonmezisik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/martilar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben...', 'ben-hurrem-yalcin-6yujr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben

cesur

bir

korkağım...

korkularımı

korkutmağa

çabalarım...

ama

en

çok

da...

korkak

korkaklardan

korkarım....

02.04.2004', 'ben cesur bir korkağım... korkularımı korkutmağa çabalarım... ama en çok da... korkak korkaklardan korkarım.... 02.04.2004...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşümem', 'usumem-zafer-zengin-etnika-5fiim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabırsız şarkılar gibi

Bitirip bitirip seni

Yeni baştan söylüyorum 

Sözümü

Sesli okuyorum 

Bildiğim harfleri...

Bilmediklerim sesin

Bana sen öğreteceksin...

Akordu bozulmuş

Bağlamam gül diyor

Gülüyorum

Yirmidördüme girmeden 

Gurbete gidiyorum...

Sevmediğim yağmurlar yağıyor başıma

Baharda

Sonbaharı yaşıyorum...

Bir mevsim uydursam ellerime

Artık varsın

Üşümem

Üşümem diyorum...

Üşümüyorum...

Gözlerim yaşarıyor

Yeşilin mevsiminde...

5 Nisan 2004  '' İçimin Kitabı ''', 'Sabırsız şarkılar gibi Bitirip bitirip seni Yeni baştan söylüyorum  Sözümü Sesli okuyorum  Bildiğim harfleri... Bilmediklerim sesin Bana sen...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/usumem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dedikleri', 'ask-dedikleri-salih-ozalasan-wfue2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk dedikleri bu olsa gerek

Yaralı bir kuş çırpınıyor yüreğimde

Derdine derman yar olsa gerek

Yardıma muhtaç titriyor tüneğinde

Sevdalara açılmak için ne gerek

Deniz değil ki yüzmesini öğrensek

Aşk denizlerden derin olsa gerek

Denizaltı olup dalıp gitmek gerek

Y.Tarihi 05-04-04 Saat 23,28

Salih ÖZALAŞAN', 'Aşk dedikleri bu olsa gerek Yaralı bir kuş çırpınıyor yüreğimde Derdine derman yar olsa gerek Yardıma muhtaç titriyor tüneğinde Sevdalara aç...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-dedikleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Tarifsizim', 'sana-tarifsizim-bekir-mutlu-gokcesu-f18lo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu an

Seviyorsam

Ben biliyorsam

Ve mutluysam

Sebebi

Sensin can

Sana teklifsizim...

Bilmiyorsan

Ve sevdiğimi

Hissettiremiyorsam

Say ki dilsizim

De ki ifadesizim

Ama bil ki 

Sana tarifsizim

Bu yaşta ve saatte

Böylesi

Daha makul

Ve çok daha makbul

Geliyor

Bana aşk...', 'Şu an Seviyorsam Ben biliyorsam Ve mutluysam Sebebi Sensin can Sana teklifsizim... Bilmiyorsan Ve sevdiğimi Hissettiremiyorsam Say ki dilsiz...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-tarifsizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçleme 3:...Ve Ağıt', 'ucleme-3-ve-agit-osman-velioglu-t1e14', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir haber erişti vurulmuş Ziya’m

Kabusa dönüştü o tatlı rüyam,

Ziyasız geceler nasıl uyuyam

Vay ben ölem Ziya’m, toprak başıma,

Anılar karışır kanlı yaşıma,

Kayanın dibine bir dağ yığılmış,

Zaman duralamış,toprak boğulmuş,

Her sevenin sonu böyle değilmiş,

Vay ben ölem Ziya’m, toprak başıma,

Anılar karışır kanlı yaşıma.

Ahlatın dalında bir kuş ötüyor,

Kurumuş çalılar yüzen batıyor,

Cemil de yaralı baygın yatıyor,

Vay ben ölem Ziya’m toprak başıma,

Anılar karışır, kanlı yaşıma,

Bir yiğit devrilmiş, yürekler yansın

Bu yorgun yüreğim nasıl dayansın

Seni saklamayan dağlar utansın,

Vay ben ölem Ziya’m toprak başıma,

Seneler karışır kanlı yaşıma…

Budur ki dileğim sevdiğim senden,

Ceylan gözlerini saklama benden,

Onlar uğurlasın canı bu tenden,

Diyen diller susmuş,toprak başıma,

Bakışın sızıyor kanlı yaşıma.

Gün günü kovalar, gün akşam olur,

Gayriye lüzum yok yar beni bilir.

Ziya’mdan geriye sevdası kalır,

Vay ben ölem Ziya’m toprak başıma,

Anılar karışır kanlı yaşıma.', 'Bir haber erişti vurulmuş Ziya’m Kabusa dönüştü o tatlı rüyam, Ziyasız geceler nasıl uyuyam Vay ben ölem Ziya’m, toprak başıma, Anılar karış...', ARRAY['Türk Edebiyatı','Şiir','Osman Velioğlu']::text[], 8.5, '{"poet":"Osman Velioğlu","poet_slug":"osman-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ucleme-3-ve-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetinemesem', 'yetinemesem-ahmet-hakan-yilmazturk-mc5ki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinle sevsen

yetmese, hırslansam

daha çok sevgi istesem

sense hiç veremesen

Mazur göremesem 

çocukmuşum, anlayamasam

başımı elinin altına koysam

bu da bana yetmese

Seni ceviz ağacının altında hatırlasam

Santa Lucia söylesen gecelerime 

bana hiç dokunmasan

uzaktan bile sevmesen

çakınla sapan oysan

kuş vuramasam

Seni yine görsem

daha ne kadar göreceğimi bilemesem

kara kazanlar kaynasa

bir cenaze yıkansa mutfakta

ya da ben yıkansam

defne dalları yolsak 

tutsak yolunu yanmış mezarlığın,

bir bayram sabahı 

bir cüce ibrik taşısa, korksam

senin yanımda olduğunu hatırlasam

rahatlasam 

Sonra seni kaybetsem, hiç bulamasam

portakal soyarken, 

ellerini hatırlamaya koyulsam

kaybolsa hayalin

Yetimliğimi ellere versem

başımı elinin altına koysam

bu da bana yetmese

yetinemesem…

05.04.2004', 'Gözlerinle sevsen yetmese, hırslansam daha çok sevgi istesem sense hiç veremesen Mazur göremesem  çocukmuşum, anlayamasam başımı elinin altı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yetinemesem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanmak Olmasa', 'uyanmak-olmasa-hasan-huseyin-ozak-rh4rc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçmek, içmek.....

Kendinden geçinceye dek,

her şeyi unutuncaya dek içmek

Ya da, yürümek sahilden denize doğru

yürümek, yürümek....

Nefesin tükeninceye dek yürümek, derinliklere doğru

Ah! birde sabah yeniden uyanmak ve suyun kaldırma gücü olmasa

Sabah acınacak duruma düşmek de var,

sarhoş cesedin sahile vurduğunda ! !', 'İçmek, içmek..... Kendinden geçinceye dek, her şeyi unutuncaya dek içmek Ya da, yürümek sahilden denize doğru yürümek, yürümek.... Nefesin t...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uyanmak-olmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşgalim gözyaşımda saklı', 'esgalim-gozyasimda-sakli-tamer-sonmezisik-38pqv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sınırların yok olduğu vakitteyim,bir sensizlik anının tanıklığında.

Mührünü gözyaşımla imzaladığım yüzün,yamacımda.

Ruhumun derinliğinde; ''Sende-yim-liğim-''...', 'Sınırların yok olduğu vakitteyim,bir sensizlik anının tanıklığında. Mührünü gözyaşımla imzaladığım yüzün,yamacımda. Ruhumun derinliğinde; ''S...', ARRAY['Türk Edebiyatı','Şiir','Tamer Sönmezışık']::text[], 8.5, '{"poet":"Tamer Sönmezışık","poet_slug":"tamer-sonmezisik","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/esgalim-gozyasimda-sakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kollarında uyusam...', 'kollarinda-uyusam-i-brahim-ethem-bingul-vagjd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir

Senin eşsizliğin

O eşsiz güzelliğin

Anlam katar sözüme

Geceme,gündüzüme

Saf gerçek,Tartışmasız

Sevgin,sevecenliğin...

Bir

Baksan bu tarafa

Gözün değse gönlüme

Doğar dolunay gibi

Gök kubbeme,gögüme

Olurum bir anda sen

Sen derim,gördüğüme...

Bir

Sabah yahut gece

Sen aşkını sunarken

Kollarında uyusam

Gerçek üstü gerçeği

Anlatırken gözlerin

Bu kez kalbimle duysam...', 'Bir Senin eşsizliğin O eşsiz güzelliğin Anlam katar sözüme Geceme,gündüzüme Saf gerçek,Tartışmasız Sevgin,sevecenliğin... Bir Baksan bu tara...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kollarinda-uyusam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matruşka', 'matruska-reside-sarikavak-i33ss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her ücra köşeden sen çıkıyorsun bu gece 

her kalabalıktan ben 

her benden bir yalan çıkıyor bu gece 

her yalandan sen...', 'her ücra köşeden sen çıkıyorsun bu gece  her kalabalıktan ben  her benden bir yalan çıkıyor bu gece  her yalandan sen......', ARRAY['Türk Edebiyatı','Şiir','Reşide Sarıkavak']::text[], 8.5, '{"poet":"Reşide Sarıkavak","poet_slug":"reside-sarikavak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/matruska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pay-laşmak', 'pay-lasmak-ersan-kurt-lqex1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarım mı kaldı, 

hepsi bu kadar mıydı bilmem, 

ama zaman çoğalıyor, 

kucağın huzurla doluyordu paylaşırken,

sen huzurlu oluyordun, ben mutlu, 

bir bütünü seninle paylaşıp 

bütünleşiyorduk yine, 

ama yalnızca seninle. 

Mutluluğu, çocukluğu, 

dünyaya gelmeyi, getirmeyi seninle, 

ama yalnızca seninle,

duygular, yüzün, sen, ben... 

tanıdık gelmişti birşeyler yani, 

paylaşmak istedim,

acısıyla, tatlısıyla... 

iyi günde, kötü günde...

ama yalnızca seninle! 

Paylaşmak,

pay olmak seninle...

5 Nisan 2004, Kuzey Denizi', 'Yarım mı kaldı,  hepsi bu kadar mıydı bilmem,  ama zaman çoğalıyor,  kucağın huzurla doluyordu paylaşırken, sen huzurlu oluyordun, ben mutlu...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/pay-lasmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Neşter Bizde Yürek Yarası', 'sende-nester-bizde-yurek-yarasi-hamit-kunt-1wapn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ağlama

yüreciğin acımasın

bebeğim

Ben ağlarım

annen ağlar

senin kalbin sancımasın

bebeğim

Gel artık

gül artık

gül bakışın kaybolmasın

bebeğim

Mevsim bahar

sana adını öğreteceğim

çiçekler var

böcekler var

kuşlar var

O minik ellerinde

iğneden ince 

damarları nasıl bulmuşlar? 

Bulmuşlar da ince ince delmişler

Seni neşter

bizi yürek acısına salmışlar 

Papatyadan seraplar görüyorum

kısacık saçlarında

Gel artık bebeğim

Çiçeklerden ilaçlar yapıp

şu yarana süreyim

O minik ellerini

yarım bakan gözlerini

gül kokan yüzlerini…

Tek kelimeyle 

seni

tenini

çok özledik

bebeğim

Gel artık

Gül artık

Güldüğünü hiç görmedik

Gel boş kaldı beşiğin

Bohçalara hazırlanmış

mini mini

cicili bicili

elbiseler…

Küçük ablan

Büyük ablan

Hasretler içinde kıvranan

Annen ve baban...

Uzatma ayrılığı

gel artık

bekleniyorsun

Bebeğim.

                              06/04/2004

                               üsküdar', 'Sen ağlama yüreciğin acımasın bebeğim Ben ağlarım annen ağlar senin kalbin sancımasın bebeğim Gel artık gül artık gül bakışın kaybolmasın be...', ARRAY['Türk Edebiyatı','Şiir','Hamit Kunt']::text[], 8.5, '{"poet":"Hamit Kunt","poet_slug":"hamit-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/sende-nester-bizde-yurek-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Düşlerimde', 'gul-duslerimde-bekir-mutlu-gokcesu-m1d2o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aradım seni gecede

Üç beş yıldız gördüm

Gökyüzünde...

Bir sürü ışık

Koca şehir 

Gözlerimin önünde...

Ümitlendim her birine

Fakat yoktun hiç birinde...

Olsun

Bana görünsen de

Görünmesen de

Beni sevsen de

Sevmesen de

Tek sen gül yeter

Düşlerimde...', 'Aradım seni gecede Üç beş yıldız gördüm Gökyüzünde... Bir sürü ışık Koca şehir  Gözlerimin önünde... Ümitlendim her birine Fakat yoktun hiç ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gul-duslerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmeyi dene....', 'gormeyi-dene-mine-gul-zwtef', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir dur..., yavaşla!  Evet sana söylüyorum.

Gözlerini kapat ve derin bir nefes al,  hisset ciğerlerine soluduğun havayı.

Sonra aç gözlerini, çevrene bak, gökyüzüne çevir başını, seyret...

Gözlerin açıkken ne kadar da kolay değil mi bakmak? 

Rengarenk çiçekler, mavi, yeşil, güneşin ısıtan ışıkları...

Baktığın her yerde ve her şeyde ayrı bir renk, ayrı bir güzellik var,

ayrı bir destan anlatıyorlar sanki sana.

Ama farkında mısın? 

Sen yalnız bakıyorsun.

Görebiliyor musun tüm bu güzellikleri? 

Hiç görmeyi denedin mi? 

Görmüyorsun biliyorum...

Gözlerin kapalıyken içinde karanlıktan başka ne var? 

Hiç..., değil mi? 

Simsiyah bir karanlık ve kocaman bir hiç.

Yanılıyorsun... 

asıl görmen gereken ne varsa o karanlığın ardında.

Belki farkında değilsin bunun, belki de farkında olmak istemiyorsun,

belki de o karanligin ardında karşılaşacaklarından korkuyorsun.

O karanlık perdesini yırtmak senin elinde,

ha cesaret... elini uzat ve arala o perdeyi, korkma..

Yabancı değilsin aslında orada karşılaşacaklarına.

İçini ürpertebilir belki ilk gördüklerin veya hissettiklerin,

sakladığın bir gizli kutu var orada, sakladığın özlemlerin,

bastırdığın duyguların ve isteklerin var,

unutmaya çalıştığın acılar var belki de,

belki de solmaya yüz tutmuş umutların.

Neden onları görmek istemiyorsun ki,

onları en kuytu köşelerde gizliyorsun,

kimden korkuyorsun, gizlemen niye? 

Başkalarının hayatlarını yaşamak zorunda olduğundan mı

kendini gizleme isteği, sevdiklerini incitebileceğinden mi korkuyorsun,

onların isteklerine uymadığın zamanlar, seni sevmiyeceklerini mi düşünüyorsun...? Seni sevenler böyle bencil olmamalı, seni,

senin onları sevdiğin kadar sevebilmeli ve yeri gelince

senin kadar fedakar olabilmeliler, öyle değil mi? 

Kendini saklamayı başarırsın yıllar boyunca,

hatta içinde bir gizli BEN bulunduğunu dahi unutabilirsin,

ama o seni asla unutmaz...

Belki baştan sana küser, sesini çıkarmaz ve herşeyi oluruna bırakır,

belki bir gün, belki yakında... diye bekler.

Günler aylar ve seneler geçer, içindeki SEN kıpırdamaya başlar,

kıpırdadıkça içindeki küllenmiş ateşler yeniden alevlenmeye,

kor olmaya başlar, fırtınalar esmeye başlamıştır içinde.

İçindeki çatışmayı izlersin sadece ve neye uğradığını anlıyamazsın,

nasıl davranacağını da bilemezsin,

müthiş bir acı saplanır yüreğine 

ve kendini bir yerlerde unuttuğunu farkedersin o an...

İçindeki sen kendi varlığını sana gösterdiği an beyninden vurulmuşa dönersin, kurduğun yapay dünyan başına yıkılır, pişmanlık duyarsın

ve kendini kendinden gizlemenin ne kadar büyük bir yalnış olduğunu anlarsın. 

Yıllarını yaşamamışsındır,  yılların boşuna geçmiştir, kendini kandırmışsındır

ve bu da içini sızlatır...

Tüm pişmanlıklara rağmen şanslısındır bir bakıma... 

Görmenin ne demek olduğunu anlamadan,

bir ömrü gözü kapalı geçirmekte vardı, öyle değil mi? 

(15 Aralik, 2003)', 'Bir dur..., yavaşla!  Evet sana söylüyorum. Gözlerini kapat ve derin bir nefes al,  hisset ciğerlerine soluduğun havayı. Sonra aç gözlerini,...', ARRAY['Türk Edebiyatı','Şiir','Mine Gül']::text[], 8.5, '{"poet":"Mine Gül","poet_slug":"mine-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/gormeyi-dene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnfazsız Yargı', 'i-nfazsiz-yargi-ersan-kurt-ol63m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözünden yaş dökeceksen sen,

her şiir yazdığımda ben, 

kırarım o kalemimi, 

infazsız yargılarım şiirlerimi.

5 Nisan 2004, Kuzey Denizi', 'Gözünden yaş dökeceksen sen, her şiir yazdığımda ben,  kırarım o kalemimi,  infazsız yargılarım şiirlerimi. 5 Nisan 2004, Kuzey Denizi...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/infazsiz-yargi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalansiz', 'yalansiz-ozgur-arslan-qtss4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Velhasıl, Gün döner

Akşam olur ve batarsın

Hayat buymuş meğer,

sanki bir dönme dolap

bir iner bir çıkarsın

yada bir güneş gibi

ya doğar ya batarsın', 'Velhasıl, Gün döner Akşam olur ve batarsın Hayat buymuş meğer, sanki bir dönme dolap bir iner bir çıkarsın yada bir güneş gibi ya doğar ya b...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arslan']::text[], 8.5, '{"poet":"Özgür Arslan","poet_slug":"ozgur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalansiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye İtafen', 'sevgiye-i-tafen-ozgur-arslan-yit78', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi, tanrı gibidir. 

Belki de ta kendisidir. 

Özgür ve bağımsız. 

Ne zaman kavramı 

Vardır onda.. 

Ne de mekân. 

Ne sahibi 

Vardır onun, 

Ne de sahibesi. 

O.. 

Ne alınır.. 

Ne satılır.. 

Ne yenir.. 

Ne de içilir. 

O.. 

Sadece ve sadece 

Karşılıksız verilir. 

Verimiyorsa

asla SEVGİ değildir.', 'Sevgi, tanrı gibidir.  Belki de ta kendisidir.  Özgür ve bağımsız.  Ne zaman kavramı  Vardır onda..  Ne de mekân.  Ne sahibi  Vardır onun,  ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arslan']::text[], 8.5, '{"poet":"Özgür Arslan","poet_slug":"ozgur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgiye-itafen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basla...', 'basla-zafer-zengin-etnika-dp4u9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sahipsiz

Düşlerin

Saklandığı 

Yer

Kim 

Bulsa

Kendini

Korsan

Sanıyor

Bir gizdir/Kendine saklanmak...

Define

Gülen yüzün hikayesi

Bir güzel çocuk

Bahar kuşanmış sanki...

Kıyamam sana

Tomurcuklar açınca

Gülüşünü bana sakla

Tak koluna umudu

Saldır hayata

Başla...

Unutmam gül kokulu koşmalarını...

Güzel mektuplarını okurken..Gidip gelmeyenlerden haber vardır diye..

Gözlerimi açıp okuyorum..Yalnızlığı hafifletmek ve anlaşılmak için..

Dizeler tutturuyorum gece vakti..Aydınlanıyor gülüşüm..Sevinçliyim..

Bahar kadar..O tomurcuklar sen de var..Senin adın bahar..

6 Nisan 2004  '' İçimin Kitabı ''', 'Sahipsiz Düşlerin Saklandığı  Yer Kim  Bulsa Kendini Korsan Sanıyor Bir gizdir/Kendine saklanmak... Define Gülen yüzün hikayesi Bir güzel ço...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/basla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Art Niyet', 'art-niyet-ersan-kurt-q740l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Art niyetliyim

Evet art niyetliyim 

Geceni 

gündüzünü

tüm mutluluğunu

gözlerini 

gülüşünü

sevgini 

hüznünü

sahibi olduğun herşeyin 

kiminin hepsini 

kiminin yarısını 

[ç]almak istiyorum.

İçinde bulunduğun her anı

geçmişindeki her anını

yaşayacağın tüm zamanını

herşeyinin yarısını

[ç]almak istiyorum. 

Art niyetliyim

evet art niyetliyim

6 Nisan 2004, Kuzey Denizi', 'Art niyetliyim Evet art niyetliyim  Geceni  gündüzünü tüm mutluluğunu gözlerini  gülüşünü sevgini  hüznünü sahibi olduğun herşeyin  kiminin ...', ARRAY['Türk Edebiyatı','Şiir','Ersan Kurt']::text[], 8.5, '{"poet":"Ersan Kurt","poet_slug":"ersan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/art-niyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıyorum... Şiir...Şiir...', 'yaziyorum-siir-siir-baki-son-7dzll', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde gezinirken,

Güzelliğe ve sevgiye rastladım

Sonra,

Dışarıya çıkıp bunları tanımak için

Yollara düştüm.

Önce İstanbul çıktı karşıma,

Tüm güzellikleri ile

Algılamaya çalıştım

Tek yönlü.! 

________Sevgiyi

Tanıdım...

Sonra Ankara''da

'''' O ''''

Çıktı karşıma...

Bambaşka bir güzelliği

Ve 

Çift yönlü.! 

________Sevgiyi

Tanıdım...

Önce ürktüm.! 

İstanbul''a sığındım...

İstanbul

Ona ulaşmama yardımcı oldu.

Evlendim...

Şimdi

Tüm insanları seviyorum...

Zamanı aşabilmek için

Sevdiğimden

Ve İstanbul''dan

Algıladığım 

Tüm güzel duygularımı

Yazıyorum...

________Şiir...Şiir...', 'İçimde gezinirken, Güzelliğe ve sevgiye rastladım Sonra, Dışarıya çıkıp bunları tanımak için Yollara düştüm. Önce İstanbul çıktı karşıma, Tü...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yaziyorum-siir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnkar Yiğidin Kalesidir...', 'i-nkar-yigidin-kalesidir-vedat-koparan-2drnw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman.? 

Tabi ki; 

Kendisine zarar verildiğini gördüğü her an.. 

Yalanın bini bin para

Duman tüter.. Ocaksız bacalardan...

İzninizle infazdayım 

Sizler yazın 

Ben okuyup

Çoğalarak çağlayayım

İçimden geçer yarılan denizler

Yalanların,yanlışların, 

Kırdıklarınızın isyanındayım...', 'Ne zaman.?  Tabi ki;  Kendisine zarar verildiğini gördüğü her an..  Yalanın bini bin para Duman tüter.. Ocaksız bacalardan... İzninizle infa...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/inkar-yigidin-kalesidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimler', 'resimler-abdullah-atay-tkfpw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün gece

Efkarlandım ben yine...

Mum ışığı altında

Masamı donattım resimlerinle...

Anıları garson yaptım

Şarkıları meze...

Okyanus mavisi gözlerini içtim

Kadehimde...

Boşaldı kadehim

Sen doldun içime...

Dönüyor başım 

Sarhoş oldum yine...', 'Dün gece Efkarlandım ben yine... Mum ışığı altında Masamı donattım resimlerinle... Anıları garson yaptım Şarkıları meze... Okyanus mavisi gö...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/resimler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara', 'ara-halil-i-brahim-ozdemir-n586l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sadece onu bil ve ona eğil,

Solmaz ve eskimez o sözü ara

Ama bakışıyla bakanı değil

Ruhları hisseden o gözü ara…', 'Sadece onu bil ve ona eğil, Solmaz ve eskimez o sözü ara Ama bakışıyla bakanı değil Ruhları hisseden o gözü ara…...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ara-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yaprağından Birkaç Satır', 'huzun-yapragindan-birkac-satir-onder-cagiran-99ryq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne sesi var, avlaklarda kekliğin

-Sanki kendi yurdum bana yabancı-

Ne de ıtrı, şu dağlarda kekiğin.



Nakışlar ağlıyor duvar taşında

-Güzellik hissini kuşatmış sancı-

Menkıbeler dindi ocak başında.



Nefsine har verir nice külhancı

Sanki kendi yurdum bana yabancı.', 'Ne sesi var, avlaklarda kekliğin -Sanki kendi yurdum bana yabancı- Ne de ıtrı, şu dağlarda kekiğin. Nakışlar ağlıyor duvar taşında -Güzellik...', ARRAY['Türk Edebiyatı','Şiir','Önder Çağıran']::text[], 8.5, '{"poet":"Önder Çağıran","poet_slug":"onder-cagiran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/huzun-yapragindan-birkac-satir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-halil-i-brahim-ozdemir-oodmf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ucu yanan mektup bendendir dosta

Bir işaret olsun yanan ruhumdan

Ulaşmazsa  eli yakan o posta

Yer gök mahzun olur ahımdan

Kapında beklesem bir ömür boyu

Yüz sürsem  eşiğe içeri  girsem,

Masaldır rüyadır düğünü toyu

Zamanı toplayıp emrine versem…', 'Ucu yanan mektup bendendir dosta Bir işaret olsun yanan ruhumdan Ulaşmazsa  eli yakan o posta Yer gök mahzun olur ahımdan Kapında beklesem b...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlem-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimi Açtım Sana', 'yuregimi-actim-sana-meral-yagcioglu-0a93k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dipten çıkarırım midyeleri

Bir,bir ellerimle

Kan revan içinde ellerim

Görmedin gözlerimde

Tane,tane incileri irili ufaklı

Belki de görmezden geldin.

Yüreğimi açtım sana

Sevda bahçesinde

Türlü, türlü çiçekler yetiştirdim

Gübreli topraklarla

İtinayla besledim

Göz pınarlarımdan

Can suyu oldum oluk, oluk

Çabamı görmedin ıslanmadı ellerin

Belki de görmezden geldin

Yüreğimi açtım sana

İçimdeki yumak, yumak

Sevdayı çözelim

Karışalım birbirimize

Tek yürek olalım birlikte atalım dedim

Duymadın

Belki de duymazdan geldin

Yüreğimi açtım sana

Keman çalan gönül telim

Sevda şarkılarında ki

Aşka davet melodisinde

Düet yapalım istedim

Yüreğinin ritmini esirgedin

Belki de hiç ritmik değildi

Duyguların

Yüreğimi açtım sana

Güvercin kanadına

Yükledim tüm hislerimi

Özel ulak uçurdum yüreğimden yüreğine

Gönül kapını açmadın

Belki de açmak istemedin', 'Dipten çıkarırım midyeleri Bir,bir ellerimle Kan revan içinde ellerim Görmedin gözlerimde Tane,tane incileri irili ufaklı Belki de görmezden...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yuregimi-actim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orta Köyde Bir Çay Bahçesi', 'orta-koyde-bir-cay-bahcesi-meral-yagcioglu-cmsyl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmem

Belki de beş altı yıl önceydi

Hani o ilk buluştuğumuz

Mayıs ayında bir gün

Nasılda titriyordum heyecandan

Fark ettirmek istemiyordum ama

Ne mümkündü saklamak heyecanımı 

Aslında sen de birazcık heyecanlıydın belki

El ele yürüyorduk Beşiktaş da 

Yolumuz bizi Orta köy’ e sahile götürdü

Deniz kenarında yürüdük 

Martıların kanatları arasında uçuyorduk adeta

Güneş sanki güzel bir başlangıcın

Müjdecisi gibi pırıl, pırıl

Ve ısıtıyordu içimizi.

Kaldırım kenarında açılan gümüş

Tezgahlarından bir yüzük alıp

Vermiştin bana.Farkında mıydın bilmem

İlk hediyen di bu bana

Utana sıkıla almıştım yüzüm al, al

Yorulunca dolaşmaktan

Sahilde bir çay bahçesinde denize karşı

Hasır tabureli küçük bir masada

Uzuca bir zaman oturup

Hani o ilk unutulmaz sohbetimizi yapmıştık

Birbirimizi tanımak,sindirmek için yüreğimizde

Hafif melodi gibi gelen dalga seslerini dinleyip

Martılarla birlikte şarkılar seslendirmiştik

Nefis tavşan kanı çaylarımızı yudumlarken.

Elimi tutup yanağıma minicik bir buse

Sıcacık bir buse kondurunca kızaran yüzüme

Bakın sımsıcak bir çift gözle

Aydınlanmıştı dünyam.

Yüreğimin sesini dinlemiştin.

Hatırlıyorum seneler sonra şimdi

Tesadüfen yine ben Orta köy’ deyim

Hem de yine bir mayıs günü ve 

Aynı çay bahçesinde çayımı yudumluyorum

Bir başıma

Çay bahçesi aynı,garsonlar tanıdık

Soran gözlerle baktılar gözlerime

Çay aynı nefis çay değil sanki

Dalgaların sesi bile kırık bir melodi çalıyor

Martıların şarkılarıysa kulağımı tırmalıyor

Uzaklara ufka bakıyorum 

O ilk buluştuğumuz mayıs aklıma geliyor

Güneş ısıtıyor kıştan uyanan bedenimi

Yüreğimse hala buz zemheri

Bir yandan ısınıyor bedenim bir yandan da

Titriyor yüreğim.

Göz yaşlarım boncuk,boncuk damlıyor maviye

Daha saatlerce oturup o günü

Sindire, sindire hayal etmek isterdim ama

Otobüsümün geldiğini gördüm

Garsona içip bitiremediğim

Gece gibi karanlık çayımın parasını ödedim

Para üstü beklemek mi üstü kalsın be arkadaş

Yüreğim burada kalmış para kalmış çok mu

Koşar adım ayrıldım çay bahçesinden

Bir şeyleri bırakıp ardımda

Eminim

Sadece bu ilk gelişimde hatırlamayacağım

Çok uzun yıllar geçse de

Orta köy’ e her gelişimde unutamadığım

Unutamadığım o gün ve anılarım yüreğimin bir köşesinde

Çırpınırken yalnız olmayacağım

Birlikte geleceğiz bu çay bahçesine

Bir, bir canlanacak anılarımız

Bana acı bir haz verecek her gelişimde

Ama yine geleceğim,yine geleceğiz

Yüzüğüm mü hala parmağımda', 'Bilmem Belki de beş altı yıl önceydi Hani o ilk buluştuğumuz Mayıs ayında bir gün Nasılda titriyordum heyecandan Fark ettirmek istemiyordum ...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/orta-koyde-bir-cay-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlar mı', 'anlar-mi-hafize-zuluflu-aqn5s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözyaşı aksa yanaktan

Karışsa deryaya

Derya anlar mı

Anlar mı gözlerden

Bir gece yarısı aniden

Arar mı', 'Gözyaşı aksa yanaktan Karışsa deryaya Derya anlar mı Anlar mı gözlerden Bir gece yarısı aniden Arar mı...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlar-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-metin-oz-q8glv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşse sonsuz bir sızıyla yerlere bedenim

Tanınmıyacak kadar silikleşaede yüzüm

Kir pas içinde kalsada ruhum

Ne olur, kucakla kaldır beni anne

Sevgisizlik üzerimde yük 

Yüz bin ton sanki

kalkamıyorum

Ne olur,kucakla kaldır beni anne

Çisi çisi yağmur yıkıyor naşımı

İmamım gök kübbe

Cemaatim damlalar olmuş

Sahipsiz bilmesin melekler

Ne olur, kucakla kaldır beni anne

Bu son yolculuk belli

Bir tarafım sende kalacak

İşte şimdi istiyorum tanrıdan

Utanarak,yanında biraz daha kalmak 

Al bu cansız başımı sıcak sinene bastır

Ne olur,kucakla kaldır beni anne.', 'Düşse sonsuz bir sızıyla yerlere bedenim Tanınmıyacak kadar silikleşaede yüzüm Kir pas içinde kalsada ruhum Ne olur, kucakla kaldır beni ann...', ARRAY['Türk Edebiyatı','Şiir','Metin Öz']::text[], 8.5, '{"poet":"Metin Öz","poet_slug":"metin-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anne-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksiklik', 'eksiklik-metin-oz-2p0t0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eksiklik üzerine bir şarkım var,dinlermisin 

Melodisi iç burkan 

Ben her gece kendi konserimi veriyorum

Çalanıda,söyleyenide,dinleyenide benim

Ve birtek şarkı çalıyor

Oda eksiklik üzerine.', 'Eksiklik üzerine bir şarkım var,dinlermisin  Melodisi iç burkan  Ben her gece kendi konserimi veriyorum Çalanıda,söyleyenide,dinleyenide ben...', ARRAY['Türk Edebiyatı','Şiir','Metin Öz']::text[], 8.5, '{"poet":"Metin Öz","poet_slug":"metin-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/eksiklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dere Kenarındaki Söğüt', 'dere-kenarindaki-sogut-i-brahim-ocak-cw0fu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen dostluğu ne bilirsin

Dostluğu çıkar ve makam ile ölçersin

Sen dere kenarındaki söğüt gibisin

Rüzgar nereden eserse o yöne eğilirsin

Unutma dostum işte bu yüzden

Söğüt bir türlü dik durmayı beceremez

Yazlık dostlar gölgesi varken ayrılıktan hiç söz etmez

Yapraksız söğüde onlar selam bile vermez

İlkbaharda koşa koşa sana gelenler

Sonbaharda bir bir terk edecekler

Çünkü artık ne güneş gökyüzünde parlar

Ne de gölgelik arayan yazlık dostlar var

Ah dostum hatırlıyor musun bir zamanlar çok gururluydun

Yazlık dostlarınla çok mutluydun

Artık kış geldi sen de unutuldun

Kibirli ve vefasız dostum ne ektiysen onu buldun

Şimdi yüreğinden kabarmış taşmış duygular

Gözlerinde de yağmur yüklü bulutlar

Gönül vefayı dostluğu asıl şimdi arar

Üzgünüm dostum ama seni bekleyen uzun bir yalnızlık var', 'Sen dostluğu ne bilirsin Dostluğu çıkar ve makam ile ölçersin Sen dere kenarındaki söğüt gibisin Rüzgar nereden eserse o yöne eğilirsin Unut...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ocak']::text[], 8.5, '{"poet":"İbrahim Ocak","poet_slug":"i-brahim-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dere-kenarindaki-sogut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zırhlılar', 'zirhlilar-sair-dogushan-njuc3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Esme deli rüzgar, uçurma beni

Eskiyi görünce, sanma sen yeni

Ah o kaytan bıyıklar, öldürür beni

Zırhını niye giymedin saf yeniçeri

Gülleler gelirse, havadan yerden

Sakın hemen kafanı, ayır keserden

Ekmeği migrostan al, benzini shellden

Zırhlılar gözüktü, kaçışma birden

Şahin gibi bakma, dalarım sana

Dün gece üttüm diye, küstün mü bana

Bisiklete binerken, kep tak kafana

Zırhlılar bayılır, cümbüşe kemana', 'Esme deli rüzgar, uçurma beni Eskiyi görünce, sanma sen yeni Ah o kaytan bıyıklar, öldürür beni Zırhını niye giymedin saf yeniçeri Gülleler ...', ARRAY['Türk Edebiyatı','Şiir','Şair Doğuşhan']::text[], 8.5, '{"poet":"Şair Doğuşhan","poet_slug":"sair-dogushan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zirhlilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yansıtma*', 'yansitma-bayram-tunca-ec0wt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cisimler nispetlerince ısıyı/ışığı yansıtır 

Kalemşörler de yaşadıkları çağı yansıtır 

Herkes karınca kararınca, özverileriyle 

Kimi sesli/kimi sessiz, oynadıkları rolle 

05.04.2004-05.04-İst.', 'Cisimler nispetlerince ısıyı/ışığı yansıtır  Kalemşörler de yaşadıkları çağı yansıtır  Herkes karınca kararınca, özverileriyle  Kimi sesli/k...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yansitma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canların Sultanıyız', 'canlarin-sultaniyiz-cafer-tayyar-ozkan-m2yqp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yakını uzak kılan, yasakların kurbanıyız,

Feryatları türkü yakan, canların sultanıyız,

Aşkı uğruna bir değil, bin cefaya katlanan,

Yüreği sevgi nuru saçan, gönül canlarıyız.

Dertlere derman veren, Tanrının aciz kuluyuz,

Her nefeste aşkı içen, dağların yolcusuyuz,

Candan dileyince, kalbini sonuna dek açan,

Muratlara ferman yazan, kulların torunuyuz.

20.09.2002 Ankara.', 'Yakını uzak kılan, yasakların kurbanıyız, Feryatları türkü yakan, canların sultanıyız, Aşkı uğruna bir değil, bin cefaya katlanan, Yüreği se...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/canlarin-sultaniyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik Aşkım', 'platonik-askim-i-brahim-ocak-ibh7o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yağan yağmur damlalarının saflığında 

Bebeğini emziren annenin ak sütünde saklısın

Sen engin denizlerin hırçın dalgalarında

Yeni ufuklara yol alan geminin yelkenindeki rüzgarda saklısın

Sen rüzgarların aşk nağmelerinde

Göçmen kuşların özlemlerinde saklısın

Sen gelincik çiçeklerinin adındaki güzellikte

Gülizardaki hasret kokulu goncanın renginde saklısın

Sen en asil ve onurlu sevgilere layık yüreğinle

Kara gözlü gözlü ceylanın gözlerinde saklısın

Sen eşsiz güzelliğinle kır çiçeklerinin

Yapraklarına konan kelebeğin kanadında saklısın

Sen garip bülbülün ötüşünün hazzında 

Gönlümde akan gizemli nehrin coşkusunda saklısın

Sen gecenin mehtabında ağlayan şairin gözyaşında

Bildik aşklara benzemeyen bir aşkın doğum sancılarında saklısın

Sen sevgi ufkunun mavi sonsuzluklarında 

Aşkın tarifinin yeniden yapıldığı yerde saklısın

Sen bir şafak vaktinin kızıllığında 

Güne merhaba diyen martıların çığlıklarında saklısın

Sen semaya çevrilmiş yakaran ellerimle 

Mutluluk dualarımın sebebinde saklısın

Sen muhlis dostluğunla kırık kalbimin tek tesellisinde

Şiir tadında yaşadığım platonik aşkımın ilhamında saklısın', 'Sen yağan yağmur damlalarının saflığında  Bebeğini emziren annenin ak sütünde saklısın Sen engin denizlerin hırçın dalgalarında Yeni ufuklar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ocak']::text[], 8.5, '{"poet":"İbrahim Ocak","poet_slug":"i-brahim-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/platonik-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benide', 'benide-tevfik-mengulluoglu-91nzp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haydi git 

kendini de al 

kendimden Aşkını da. 

Kaygılarını,özlemlerini 

atlat ta git.

Bir avuç mavi bırak yanıma,

her gece

mayalansın düşlerim...

Haydi geç oldu artık

Sabahlarının hepsini topla

bırak gecelerim 

dağınık kalsın.

Güneş toplar hepsini

Hadi oyalanma,

benide götür

Sana ait 

hiçbir şey kalmasın,

buralarda...', 'Haydi git  kendini de al  kendimden Aşkını da.  Kaygılarını,özlemlerini  atlat ta git. Bir avuç mavi bırak yanıma, her gece mayalansın düşle...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benide-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
