INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Erotik *', 'erotik-kubilay-enginol-2j0c8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce beyazı giydi

Sonra siyah''ı

Ayakuçlarından beline kadar

Ürperti sarıldı

Siyah inatçıydı

Beyaz görünüyordu yinede

Belli belirsiz

Siyahın gerisinde

Terledi siyah,beyaza dokunmadı

Serinledi siyah,beyazı üşütmedi

Her zamanki gibi

Siyah beyazın üzerinde titredi

Önce siyahı çıkardı

Sonra beyazı

İkisini de gelişigüzel attı

Bekleyeceklerdi hasretle sabahı', 'Önce beyazı giydi Sonra siyah''ı Ayakuçlarından beline kadar Ürperti sarıldı Siyah inatçıydı Beyaz görünüyordu yinede Belli belirsiz Siyahın ...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erotik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meselem', 'meselem-yusuf-dagitmac-2fusl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En büyük meselem ruha hitap etmekte,

Hangi dudak aşınmış, el ve alın öpmekle', 'En büyük meselem ruha hitap etmekte, Hangi dudak aşınmış, el ve alın öpmekle...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Dağıtmaç']::text[], 8.5, '{"poet":"Yusuf Dağıtmaç","poet_slug":"yusuf-dagitmac","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/meselem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadehim Kahroluyor', 'kadehim-kahroluyor-murat-demir-tnjdm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Masamın üzerinde 

Üzümler salkım salkım

Kadehlerle yan yana

Seni bekliyor rakım

Gel artık gel nerdesin

Yerin bomboş duruyor

Kadehinin yanında

Kadehim kahroluyor

Dargın gibiler bana

Beyaz peynirle cacık

Gel ne olur yanımda

Oturda git azıcık

Saniyeler geçtikçe

Karanfil boyun büker

Gözüme baka baka

Benim ile yaş döker

Gel artık gel nerdesin

Gel ki mumlar sönüyor

Kadehinin yanında

Kadehim kahroluyor', 'Masamın üzerinde  Üzümler salkım salkım Kadehlerle yan yana Seni bekliyor rakım Gel artık gel nerdesin Yerin bomboş duruyor Kadehinin yanınd...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kadehim-kahroluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Baharımda Kayan Yıldızıma...', 'i-kinci-baharimda-kayan-yildizima-metin-bilgen-3eb4y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Güzelbahçe akşamında

Kayboluyor yıldızım,

Ben seni

Rüzgarların tufanı için mi sevdim? 

Gelen hırpalıyor

Giden hırpalıyor

Adeta bir başka bahardaymışsın gibi

Gözlerin donuk ve matlaşmış sanki...

Nedendir bilmiyorum,

Gönüllerin eziği

Belki bir gün dönersin

Yaşamımdaki o tarifi olmayan

Güzelliği yaşar da yaşatırsın...

Umutların bittiği,

Hüzünlerin belleği

delip delip de geçtiği

Ufkundayız dönülmez akşamların belki

Beni de ağlatıp ağlatıp da

Bırakıp gittiği gibi...', 'Bir Güzelbahçe akşamında Kayboluyor yıldızım, Ben seni Rüzgarların tufanı için mi sevdim?  Gelen hırpalıyor Giden hırpalıyor Adeta bir başka...', ARRAY['Türk Edebiyatı','Şiir','Metin Bilgen']::text[], 8.5, '{"poet":"Metin Bilgen","poet_slug":"metin-bilgen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ikinci-baharimda-kayan-yildizima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-sadik-softa-fo7mg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güle sitem, gönle sitem,

Sitemlerde yürüyoruz; 

Sana değil nazlı gülüm,

Gönle sitem ediyoruz.

Güle akar, öz dinlemez,

Yakar yakar, köz dinlemez,

Gücüm yetmez, söz dinlemez,

Gönle sitem ediyoruz.

Diken batar, gül yaralar; 

Bülbüle düşer karalar; 

Sevdan umutlar sıralar; 

Gönle sitem ediyoruz.

Bülbülde hazan hiç gitmez; 

Çeker çeker çile bitmez; 

Seviyorum demek yetmez; 

Gönle sitem ediyoruz.

Bülbül güle, gül bülbüle; 

Hasretlik iki gönüle; 

Günüm geçmez güle güle; 

Gönle sitem ediyoruz.

Çankırı-05.04.2004', 'Güle sitem, gönle sitem, Sitemlerde yürüyoruz;  Sana değil nazlı gülüm, Gönle sitem ediyoruz. Güle akar, öz dinlemez, Yakar yakar, köz dinle...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sitem-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seni-terk-ediyorum', 'seni-terk-ediyorum-buket-sema-caner-qzlys', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hırçın dalgaların oyduğu

Kayalar gibi şimdi yüreğim.

Çiviler çakılmış gözlerime

Ağlayamıyorum.

Seni bu kalleş şehirde

Sahte sevgilere

Bırakıyorum.

Kalbim aşkınla dopdolu

Gözlerinden, ellerinden

Kaçıyorum.

Saymadan kilometreleri

sendenve bu şehirden

Gidiyorum', 'Hırçın dalgaların oyduğu Kayalar gibi şimdi yüreğim. Çiviler çakılmış gözlerime Ağlayamıyorum. Seni bu kalleş şehirde Sahte sevgilere Bırakı...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-terk-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci', 'dilenci-sair-x-factor-5x3ko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR GÜLÜS DİLENCİSİ 

Bu gün... 

Bir tek gülücük gönder bana 

Sıcacık olsun! 

Bir gülüşe dilenmek ile tanıştığım bugün bir tek gülücük 

gönder ki bana. 

Bari bugün üşümeyeyim! 

Bu gün... 

Bir tek gülücük gönder bana. 

Avucuma koyarken gülüşünü, sıcacık, tanımaya çalışmayacağım 

seni, senin beni bildiğin kadar. 

Söz, sormayacağım ismin ne, kimsin ve neredensin? .. 

Belki... 

Belki sadece tutunacağım bakışlarına, savrulmamak için! 

Ve bil ki soracağım sadece 

Ne istersin benden, gülüşüne karşılık? 

Bu gün, bir gülücük gönder bana sıcacık olsun... 

Bu gün sevdiğin insanların isimlerini getir hatırına 

aralarında ismim olsun! 

Bugün, bulutlara dolanmış iplerini çöz kalbimin. 

Ve altın bir kelebek gibi, ellerinle tak saçlarına! .. 

Hadi... 

Hadi bir tek gülüşünü gönder bana bugün... 

Ve eğer hiçbirine mecali yoksa gönlünün bari çok 

sevdiklerini hatırla ve aralarında ismim olsun! 

Bari, sadece sevdiklerini hatırla, aralarında ismim olan... 

Yahut Sevenlerini hatırla, yani seni sevenleri, 

Ki adım, var elbette onların arasında', 'BİR GÜLÜS DİLENCİSİ  Bu gün...  Bir tek gülücük gönder bana  Sıcacık olsun!  Bir gülüşe dilenmek ile tanıştığım bugün bir tek gülücük  gönde...', ARRAY['Türk Edebiyatı','Şiir','Şair X_factor']::text[], 8.5, '{"poet":"Şair X_factor","poet_slug":"sair-x-factor","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dilenci-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen oğlum', 'sen-oglum-buket-sema-caner-sdglr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben hep aşk dolu

Ayrılık kokan  şiirler yazardım önceleri.

Şimdi seni anlatıyorum

Ve yalnız sana olan hasretimi

Ne giden sevgililer

Bu kadar önemliydi

Ne eş nede dostlar.

Sen sen varya oğul

Göznurum bebeğim

Kahrediyor beni hasretin...', 'Ben hep aşk dolu Ayrılık kokan  şiirler yazardım önceleri. Şimdi seni anlatıyorum Ve yalnız sana olan hasretimi Ne giden sevgililer Bu kadar...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-oglum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Tarifi', 'askin-tarifi-sair-x-factor-pw6uo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçici hevesle değil delice bağlanmaktır 

Bir tel saça bir ömür verip fütursuzca yanmaktır 

Başını taştan taşa vurup çağlayan ırmaktır 

Bir yıldıza tutulup hayaliyle avunmaktır....', 'Geçici hevesle değil delice bağlanmaktır  Bir tel saça bir ömür verip fütursuzca yanmaktır  Başını taştan taşa vurup çağlayan ırmaktır  Bir ...', ARRAY['Türk Edebiyatı','Şiir','Şair X_factor']::text[], 8.5, '{"poet":"Şair X_factor","poet_slug":"sair-x-factor","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/askin-tarifi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana yeniden anlat', 'bana-yeniden-anlat-buket-sema-caner-ut7t3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unuttuğum her şeyi

Bana yeniden anlat.

Sevmek neydi aşk neydi

Bana bir bir hatırlat.

Rüzgarmıydı dağıtan

Bembeyaz saçlarımı,

Gözlerimden süzülen

Yağmurmuydu yaşmıydı.

Yaşama sevincimi 

Sende buldum yeniden

Alevler sardı birden

Yaşlanmış yüreğimi.

Unuttuğum her şeyi

Bana yeniden anlat.

Sevmek neydi? aşk neydi? 

Bana tekrar hatırlat...', 'Unuttuğum her şeyi Bana yeniden anlat. Sevmek neydi aşk neydi Bana bir bir hatırlat. Rüzgarmıydı dağıtan Bembeyaz saçlarımı, Gözlerimden süz...', ARRAY['Türk Edebiyatı','Şiir','Buket Sema Caner']::text[], 8.5, '{"poet":"Buket Sema Caner","poet_slug":"buket-sema-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-yeniden-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ Yürekli Kız', 'dag-yurekli-kiz-melek-midikoglu-uujxv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Buldum; Sen güneşsin! 

Birgün gelir de parlamaz ya

Olur mu öyle şey dersin

Olur... Olur... Tutulmuşsun! 

Güneş bu, alır gözlerimizi

Sanışımız oysa ki 

Bizim onu göremeyişimizdi! 

Sevişimiz yetmedi, yetmezdi...

Sesinde okyanusun dinginliği

İçinde fırtınaların mahkumiyeti

Sen dağ yürekli kız! Zaman bu; 

Çiçeklerin serilince, Ayıltacaksın...', 'Buldum; Sen güneşsin!  Birgün gelir de parlamaz ya Olur mu öyle şey dersin Olur... Olur... Tutulmuşsun!  Güneş bu, alır gözlerimizi Sanışımı...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dag-yurekli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-i-brahim-dikmen-2-edgya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün geçmiyorki,seni düşünmeden yattığım,

Adını anmadan uyuyakaldığım.

Sensiz geçen,soğuk karanlık gecelerde,

Çocukça oturup ağladığım.

Karanlığın,soğuk yüzünü gösterdiği bir gecede,

Belliki,yine yoksun yanımda.

Hasretin,bir okadar sıcak,yanıyor,ta şuramda,

Yıldızlar şahidimdirki,

Yokluğun,çığlık çığlığa ağlar koynumda.

Söylesene,ben sensiz yaşamaya,mecburmuyum,

Sensizliğe hapsolmuş,

Müebbet mahkummuyum.

Hiçmi telafisi yok,bir ümit,bir affın,

Bana verdiğin cezanın.

Ömür boyu,ben sensiz nasıl yaşayacağım.

Her gece,düşlerimde görünüp,

Beni çıldırtmakmı,niyetin.

Oysa,bana okadar yakınsınki,

Bazen içimdesin,bazende uzaklardasın,

Gökteki yıldızlar gibi.

Öyle biran geliyorki,tam benimsin dediğim anda,

Düşlerimden sıyrılıp,yok oluyorsun.

Yasak bir aşktan,daha ne bekliyorsun desene,

Düşlerimde bile olsa,sana sahip olmak,

Seni delicesine sevmek,doyasıya öpmek,

Öpmek kiraz kırmızısı,dudaklarından.

Zevkin doruğuna çıkmak,coşmak beraberce.

Hayali bile ne kadar mutlu ediyor beni,

Yırtılırcasına gırtlağım,bağırmak,

Haykırmak istiyorum,seni seviyorum diye,

Tüm benliğimle.

                           Sana gülüm diyemem,

                              Gün gelirde solarsın.

                                 Gözlerimde yaş olsan,

                                    Irmak olur taşarsın.                  

                                   Sen hiç solmayacak 

                                 Yüreğimde acan papatyasın.', 'Gün geçmiyorki,seni düşünmeden yattığım, Adını anmadan uyuyakaldığım. Sensiz geçen,soğuk karanlık gecelerde, Çocukça oturup ağladığım. Karan...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/dus-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamım', 'adamim-seref-yildirim-cnobn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taşlar gibi sessiz kalarak....

Utanıyorum insanlığımdan

Donuyorum Temmuz sıcaklığında

Bencil,umarsız,kayıtsızca

Havyar yiyip viski içip geğiren o fosillere 

Kızmıyorum,tiksiniyorum sadece

Biri var...

Şaşkın ürkek gözlerle bakan 

Başı dimdik onurlu

Sanat eseri gibi,nadide...biri var...

Gariban dedikleri,aşağıladıkları adamım...

Biri var...

İnsan olmaya çalışan 

Yıldızların içinde tek parlayan

Simidini dostlarıyla paylaşan

Çıplak ayaklarına,yırtık pantolonuna aldırmadan.

Tebessüm etmesini bilen

Yanık sesiyle türküler söyleyip coşan,

Öğünlerine umutlarını katık eden adamım...

Susma! ! ! 

Haykır insanlığını

Duysun gökyüzü toprak

Duysun dağlar taşlar

Duysun emeğini sömüren, ağalar beyler

Hadi be! Adamım

Kalk ayağa silkin! 

Hep yanında olduğumu bilerek...', 'Taşlar gibi sessiz kalarak.... Utanıyorum insanlığımdan Donuyorum Temmuz sıcaklığında Bencil,umarsız,kayıtsızca Havyar yiyip viski içip geği...', ARRAY['Türk Edebiyatı','Şiir','Şeref Yıldırım']::text[], 8.5, '{"poet":"Şeref Yıldırım","poet_slug":"seref-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/adamim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelbahçe Gurubunda Metin ve Cihan...', 'guzelbahce-gurubunda-metin-ve-cihan-metin-bilgen-mdf08', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzelbahçe gurubunda yine

Kayboluyorum yavaş yavaş

Gözlerim kapanıyor heyhat

Ben akşamları bir başka seven METİN

Her şeyi dört gözle gören

Ve sevdiğine, inadına yine seven

Üzüntüm sana CİHAN

Erken mi erken benim için

Seni böyle görmek...

Üzülme geçmiş bizi daima gören

O yeşil gözler anlamsız anlamsız süzülse de

Ve yaşlar bir şelale gibiyse

Huzurlu ol CİHANIM

Mutluluğun ebediyyette...', 'Güzelbahçe gurubunda yine Kayboluyorum yavaş yavaş Gözlerim kapanıyor heyhat Ben akşamları bir başka seven METİN Her şeyi dört gözle gören V...', ARRAY['Türk Edebiyatı','Şiir','Metin Bilgen']::text[], 8.5, '{"poet":"Metin Bilgen","poet_slug":"metin-bilgen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/guzelbahce-gurubunda-metin-ve-cihan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Monoloğa Davet-', 'monologa-davet-derin-deniz-27yzn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yanım sen isen

                              -ki hala öyle sanırım-

o yanımı,

sevsem

             isot yine

yersem

            daha çok acı...

Ve diğer yanım

                      hala kendimdeyse de,

şimdilerde

                 şaşkın

ve yine sersem...

Desem; 

-bir dinamitlesen kendinde ki kaygıları...-

ahh,sonra...

sonra bir bulabilsen,

yürek bahçende

saklambaç oynarken

aramayı

             unuttuğun

                             çocuğu...

Dilegelsen

çelişkilerinin nedenlerini anlatsan.

ki,zaman ilerlemiş

çocuk,büyümüştür artık

                                bilmeli

                                  anlamalısın...

Ne desem.............

                kandırılamayacak kadar

                                                yetişkin(sin) 

çünkü  (bilirsin!) 

''acılar olgunlaştırır insanı...''

Unutuşlarını hatırlamanın

                     vakti gelmedi mi daha? 

ki,günlerden ilkbahar

aylardan güneş

                mevsimlerden umut

                                          yıllardan gökyüzü mavisi...

                                                         lütfen duyumsa...

Ve hala

özlem vaktinde bekleşir

                                       o çocuk.

Hiç bir şey bitmemiştir daha

                                           bilir  (bilgedir!) 

ve bitti gibi gözüken her şeye,

                                                   belkide

yeni başlanmıştır

                              yahut başlanacaktır

                                                               kim bilir? 

bundandır ya

bir garip hüzünle karışık

                                       sevinç...

Görebilsen

                  (bitişte

                                olan  ''arasıra''lar

                                   hatırına

                                                       işte) 

Sonra sarılsan

                        bırakmasan...

sırrına ersen,

yüzlerce yıl da geçse

                      çocukluğunun

                                          en olgun yanın

                                                                olduğunun...

ahh,ille de anlayabilsen işte

neler saklı

                  aramayarak

dahası unutarak

kanattığın o çocukla

yaşanacak

                    yaşanmış,

                                      gelecekte

                                                       ve geçmişte...

bunu

bir yaşayabilsen işte...

Lütfedip anlasan...

zahnet olacak ama

son bir davettir

                         sana...

alınma

            ve yanılsama

sadece davettir...', 'Bir yanım sen isen                               -ki hala öyle sanırım- o yanımı, sevsem              isot yine yersem             daha çok ...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/monologa-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde...', 'i-cimde-derin-deniz-aro81', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde,

körfez manzaralı

            kocaman bir hüzün

sıyrılsam şu kelepçeden

                     atlasam körfezin mavi hüznüne

kulaçlasam,

                       aşılmaz denilene doğru...

...', 'İçimde, körfez manzaralı             kocaman bir hüzün sıyrılsam şu kelepçeden                      atlasam körfezin mavi hüznüne kulaçlasam...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/icimde-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derviş...', 'dervis-derin-deniz-7e1zl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seyrek kara sakallı

zulası yakut şaraplı

sergerde bir dervişmişim

öyküsü üçbinyıllık...

Uzak pusulara düşmüşüm

sıcak zor zamanlarda

soğuk dolunay gecelerinde...

İçmişim,

tarihin kuytuluk

                          köşelerinde

dağlarında,çöllerinde...

Aslan olmaktansa kafeste

karnı tıka basa tok

sırtlan olmayı seçmişim

aç-susuz,diyar diyar gezen...

Serdengeçti dervişmiim

                içmişim....

Hayyami cennetler

                 peşine düşmüşüm...

Duyun kardeşler

tellallar ferman çağırmakta

öyle ya,

efendiler böyle buyurmakta

Alamut düşeli binyıl küsur geçmiş

ama çağdaş fedailer yaşamakta

Keçiler, Abduraman çelebi kesildi...

ve ama çağdaş eşkiyalr

asminlerde çoğalmakta...

...', 'Seyrek kara sakallı zulası yakut şaraplı sergerde bir dervişmişim öyküsü üçbinyıllık... Uzak pusulara düşmüşüm sıcak zor zamanlarda soğuk do...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dervis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Düşerse Kalbe', 'ask-duserse-kalbe-cafer-tayyar-ozkan-vq8py', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevlam sevdiği kuluna verirmiş,

Cana kastettiren sevda yükünü,

Aşk umudunu yazgıya bağlarmış,

Belki çok yakın vuslatın düğünü...

Kim demiş ki sevenler ölmez diye,

Bir gün aşk düşerse kalbe, görürsün

Bu dünyanın kaç bucak olduğunu,

Her sabah doğup, gece öldüğünü...

02.10.2003 Bursa', 'Mevlam sevdiği kuluna verirmiş, Cana kastettiren sevda yükünü, Aşk umudunu yazgıya bağlarmış, Belki çok yakın vuslatın düğünü... Kim demiş k...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ask-duserse-kalbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mapusta', 'mapusta-derin-deniz-2lpci', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir yüek dolusu

sesim

ve nefesim kadar

sıcacık/anı anaforu/kafamda

ama sensizliğim

hiç de kısacık 

                       değil...

hala duygu dengesizliği denkleminde

çırpınıyor nabzım...

bir çığlık,

bir uzun avazım,

anılar deminde seyrim...

zemheride güneşi beklerim

gözlerimde narkoz sessizliği

bütün nesneler donuk

hasret oluk oluksa 

mekan dar gelir

                    koyar mapusluk...

...', 'bir yüek dolusu sesim ve nefesim kadar sıcacık/anı anaforu/kafamda ama sensizliğim hiç de kısacık                         değil... hala duyg...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mapusta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Kalbimi', 'al-kalbimi-i-brahim-dikmen-2-onaaf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Al kalbimi,

Götür buralardan.

Yüreğinin,

Gittiği yere kadar.

Al kalbimi,

Kaçır rüzğarlardan.

Hislerinin,

Gittiği yere kadar.', 'Al kalbimi, Götür buralardan. Yüreğinin, Gittiği yere kadar. Al kalbimi, Kaçır rüzğarlardan. Hislerinin, Gittiği yere kadar....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/al-kalbimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden...', 'neden-derin-deniz-ymd43', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalan

riyayı meslek seçenden

                                       kalan...

gerçekler bu kadar acı

                                     neden? 

doğrular o kadar kötü

                                    madem

çirkinlikler siyah siyah

acıtır içimizi, neden? 

kendi kendine ihanet eder insan 

kandırır kendi kendini

                                   neden? 

alınderisi köseleleşen adam

mutluluk duyuyorsa yalandan

gerçekliğin ihtilalciliğinden kaçar

                                               uçaraktan

                                                                neden ? 

yorulmaz mı

aldığı onca yenilgiden

miğdesi hiç bulanmaz mı? 

kaybeden hep kendisidir oysa

bunu bilmez 

neden...?', 'Yalan riyayı meslek seçenden                                        kalan... gerçekler bu kadar acı                                      ned...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/neden-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalma...', 'kalma-derin-deniz-6ec16', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şarabi ömürlere davetliyiz

             esrari hüzünlere...

Acı kadar yakın

acı acı kanayan

             vakitlerden sakın...

                                             kendini...

Yalnış adresler git

                           çat kapı

zamansız trajedilerle tanış

gör,

acı öfke ile kolkola

kendine kanama

               kendine sarıl

kendinden fazlasıyla sıyrıl

artıklarda takılı kalma...', 'Şarabi ömürlere davetliyiz              esrari hüzünlere... Acı kadar yakın acı acı kanayan              vakitlerden sakın...               ...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kalma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşkiya...', 'eskiya-derin-deniz-msdjv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eşkiya Geçmişten Kalan

Sevdam kara...

sevdanın karası (ömür belam) 

                ağlatır.

ve melonkoli(sevdamın esmer kardeşi) 

                kanatır...

Ağlayan

ve kanayan

                    insan

sersem bir bohomse,

sevdasını durmadan

                  (kara kara düşünerek 

                                           çoğu zaman) 

durmadan eşkiyaca

üretir

        yaratır

                  çoğaltır

yetmiyorsa yaşanılan...

Eşkiyalık sevdadandır...

ama yaşayan

yitik bir eski zamandan

                                 kalan...

...', 'Eşkiya Geçmişten Kalan Sevdam kara... sevdanın karası (ömür belam)                  ağlatır. ve melonkoli(sevdamın esmer kardeşi)           ...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/eskiya-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız-ma! kız...', 'kiz-ma-kiz-derin-deniz-viyrw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Anlatılan geçmişler de...-

düşlenen yarınlar

anlatılan geçmiler kadar

                                        uzak...

olsa da

kız-ma! kız...

soluk soluğa bir hız

                              seni bekliyor,

yılgınlık bir tuzak...

Yaşam

bizimle gülümsüyor

tüm bahislerini

                        üzerimize oynuyor...

Susuşlarını saklama

biriktirdiğin çığlıklar

dindirilemeyen öfkeler estirsin...

rüzgarlar seni dinlesin

tufan ol

yanakları kırmızı elma

kızgınlığı hızlı kız

kız-ma, 

            anla,

düşler,yine de gebe

özlenen/beklenen yarınlara...

                                düşleri(ni)  dinle...

Umut,

Her zamankinden daha sıcak...

...', '-Anlatılan geçmişler de...- düşlenen yarınlar anlatılan geçmiler kadar                                         uzak... olsa da kız-ma! kız.....', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kiz-ma-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'San''a...(o biliyor kim(e) olduğunu)', 'san-a-o-biliyor-kim-e-oldugunu-derin-deniz-7l76u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim kan çanağı / şarap kırmızısı...

Dişlerimde tütün sarısı / ciğerlerimde katran karası,

Kalırım bir başıma / nefeseimde tedirginlik kokusu...

Yalnızlığın dayanılmaz sancısı / yüreğimde anlamsızlıklar acısı...

Yağmur bulurları gibi doldu gözlerim

ağlasam,ortalık kan deryası / kıyamet sızısı

gülsem; doğacak çılgınlığımın / yiğit anası (üzülür...) 

Sanki bir tek kaldın / bir tek sen varsın sanki

Sende sürgüleme kapını / beni böyle bir başıma koyma /

buyur et,yürek odalarından birine

''hoşgedinde'' de!', 'Gözlerim kan çanağı / şarap kırmızısı... Dişlerimde tütün sarısı / ciğerlerimde katran karası, Kalırım bir başıma / nefeseimde tedirginlik k...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/san-a-o-biliyor-kim-e-oldugunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Limanlarda', 'limanlarda-naci-orpak-7w7gm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanık bir toprak kokusu

Her yağmur yüreğime değdiğinde

Bir tomurcuk, bir filiz patlamasıdır

Gölgelemesine izin verdiğim mutluluklar

Unutulmazlık sonsuzluğuna kattığım anılardır.

Kendi içimde kendimden saldığım

Yelkenlilerin aradığı o kaybolmuş limanlar

Bir türlü demir atamadığım yalnızlıkların

Sahipsiz dostluklarıdır.', 'Yanık bir toprak kokusu Her yağmur yüreğime değdiğinde Bir tomurcuk, bir filiz patlamasıdır Gölgelemesine izin verdiğim mutluluklar Unutulma...', ARRAY['Türk Edebiyatı','Şiir','Naci Orpak']::text[], 8.5, '{"poet":"Naci Orpak","poet_slug":"naci-orpak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/limanlarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AliS HaRiKaLaR DiYaRıNdA', 'alis-harikalar-diyarinda-mine-ozdemirtas-o7xy9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bardağı taşıracak o son damlanın akıntısına direnen zavallı bir gül yaprağı gibi,

ağzına kadar dolu bir su kabında  acemice kulaç atarken düşlüyorum kendimi.

Olmayan ellerimle çaresizce tutmaya çalışırken kaygan suyun parıldayan yüzeyini,

eğleniyorum aslında. Ama,bir tek gerçek var ki karartıyor / kanırtıyor belleğimi.

Ne gülünç bir çabadır bu harcadığım? Yaprağın şansı ne ola? Gülün ömrü ne ki.

04/04/2004', 'Bardağı taşıracak o son damlanın akıntısına direnen zavallı bir gül yaprağı gibi, ağzına kadar dolu bir su kabında  acemice kulaç atarken dü...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/alis-harikalar-diyarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-erhan-ergun-sh8d3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutabilmek ne kadar zormus! 

Biktim seni gecelerimde ve gündüzlerimde

düsünmeye, dayanamiyorum sensizlige.

Aceba sen beni unuttun''mu yalan melegim? 

Beni aklindan silip attin''mi bile,

yoksa sende benim gibi, gecenenin yagmurlari

gibi agliyormusun durmadan, yalan melegim? 

Sende benim gibi diyormusun, unutabilmek 

ne kadar zormus?', 'Unutabilmek ne kadar zormus!  Biktim seni gecelerimde ve gündüzlerimde düsünmeye, dayanamiyorum sensizlige. Aceba sen beni unuttun''mu yalan ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Ergün']::text[], 8.5, '{"poet":"Erhan Ergün","poet_slug":"erhan-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/unutmak-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Çiçeğim', 'yagmur-cicegim-mehmet-emin-fidan-mezbk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YAĞMUR ÇİÇEĞİM

> yeni bir günü anımsatan ışıkların ardından

> senin icin ama yalnız senin için

> mecidiye den yeni duygularımla yöneliyorum

> şehrin kokusu zaman ve mekan her şey bir yana

> yalnız sen rahmet gibi yağ, güneş gibi doğ benim dünyama

> yağmur çiçeğim, nisan yağmurum

>

> arkadaşlıklar, dostluklar, ürkek yakınlıklar,

> bir geceni serinliğinde yaşanır

> duygularım duman duman yol alırken

> sıra dağların ardından yetişen hayelin

> hayalimde büyüttüğüm sevgilim

> yağmur çiçeğim, rahmet gözyaşım

>

> tertemiz düşüncelerimle sana uzanıyorum

> çünkü ben

> saadet ikliminin ılık rüzgarlarını sende buldum

> her sıkıntımda. fırtınalı anımda. sana yöneldim.

> saçının her telinde bakışlarımı yıkadım

> harran ovası gibi, dobruca gibi bereketli göğsünden

> sevda yüklü aşklar emdim

> yağmur çiçeğim, rahmet çiçeğim, benim çiçeğim

>

>', 'YAĞMUR ÇİÇEĞİM > yeni bir günü anımsatan ışıkların ardından > senin icin ama yalnız senin için > mecidiye den yeni duygularımla yöneliyorum ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Fidan']::text[], 8.5, '{"poet":"Mehmet Emin Fidan","poet_slug":"mehmet-emin-fidan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yagmur-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Kaldı Gelecek', 'beyaz-kaldi-gelecek-hakki-hakan-kaya-7vacy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'toplandı bulutları

nemli gözlerimin

açıldı avuçları 

ıslanan yüreğimin

titreyen ellerimde

ateşli kışlığı

yankılandı sokağında

sarhoşun ıslığı

bir hayal çizildi

ufkumun perdesinde

beyazı öldürdü karanlık

son hamlesinde

alıştığım resimler

gözlerimde yandı

kağıda yansıyan hayat

hareketsiz bir andı

karalandı geçmişin

siyah el yazıları

aralandı geleceğin

beyaz sayfaları...', 'toplandı bulutları nemli gözlerimin açıldı avuçları  ıslanan yüreğimin titreyen ellerimde ateşli kışlığı yankılandı sokağında sarhoşun ıslığ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beyaz-kaldi-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Giz', 'i-cimdeki-giz-mehmet-emin-fidan-63sdk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimdeki Giz

Bir gülüşün vardı resimlerde unuttuğun

Bir gülüşün vardı resimlerde sakladığın

Gül kokulu saçlarının buğusu alazlanmış yüzün

Yaşama muştusu tebessüm çehren ve o gözlerin

Rüzgarin saçlarımı taladığı akşam üzerleri

Yapayalnızım ben ve o an, sen gönlümdesin, gözlerim gözünde

Bir haber muştusu seni bana getirende

Şimdi gözümde ten kokulu sıla mektupların

Arkadaş sohbetlerinde zifiri karanlık susuyorum romanlara özgü

Biraz da sen öğrettin bana sabahı zor, geceleri karşılamayı

Şimdi daha iyi anlıyorum gurbetlerde büyüyen yalnızlığımı

İçimdeki giz leyla ya muhtaç', 'İçimdeki Giz Bir gülüşün vardı resimlerde unuttuğun Bir gülüşün vardı resimlerde sakladığın Gül kokulu saçlarının buğusu alazlanmış yüzün Ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Fidan']::text[], 8.5, '{"poet":"Mehmet Emin Fidan","poet_slug":"mehmet-emin-fidan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icimdeki-giz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsmi Yok Şiirimin', 'i-smi-yok-siirimin-hurrem-yalcin-68i17', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dost gözlerime baktı

Sen uzaklara...

Dost gözünde ben vardım

Senin gözünde saydam....

Dost yüreğimde okudu beni

Sen yüreğime yazdın kendini...

Anladım 

Görünce öfke gözlerini

Esrik yüreğini....

Sen benim dostum olamazdın....

Zaten hiç olmadın! ...

06.04.2004', 'Dost gözlerime baktı Sen uzaklara... Dost gözünde ben vardım Senin gözünde saydam.... Dost yüreğimde okudu beni Sen yüreğime yazdın kendini....', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ismi-yok-siirimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstesen de...', 'i-stesen-de-i-brahim-ugur-toprak-ky6vc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle bir yer verdim ki sana sevdiğim 

Emin ol ki; 

Bundan daha iyisini bulamazsın 

Seni sol göğsümün altında gizledim 

Anahtarı, arasan da bulamazsın 

İstersen bir ipucu vereyim 

Ama bil ki; 

Anahtarı bulsan da, kilidi açamazsın 

Emrindedir kalbim her daim 

Ama ne var ki; 

Ardına kadar açsam da kapıyı 

Gidip de dönmemen için 

Öylesine alışmıştır ki artık kalbin 

Kaçmak istesen de kaçamazsın

05.04.04/P.tesi

17:07/İzmir', 'Öyle bir yer verdim ki sana sevdiğim  Emin ol ki;  Bundan daha iyisini bulamazsın  Seni sol göğsümün altında gizledim  Anahtarı, arasan da b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Uğur Toprak']::text[], 8.5, '{"poet":"İbrahim Uğur Toprak","poet_slug":"i-brahim-ugur-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istesen-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlediği Aşka', 'dusledigi-aska-cafer-tayyar-ozkan-v4o3s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevda yeli değil ki kapıldığım,

Sürüklenip gideyim estiği yere...

Bir coşku seli değil ki yaşadığım,

Heveslenip öpeyim verdiği yüze...

Bu gönülden eksik olmaz ki vefa,

Kaybolup gideyim özlediği yara...

Bu yürekten eksik olmaz ki sefa,

Ağlayıp güleyim düşlediği aşka...

18.10 2002 Ankara', 'Bir sevda yeli değil ki kapıldığım, Sürüklenip gideyim estiği yere... Bir coşku seli değil ki yaşadığım, Heveslenip öpeyim verdiği yüze... B...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dusledigi-aska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demiyorum', 'demiyorum-mustafa-kaya-g1smt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1

Hayat böyledir yavrum,demiyorum

Yeteneklerinin sana acı vermesine

izin verme

kaza anını bir tek sana anlatmazlar öldüğünde

çünkü küçükken çocuk olmak tehlikeli ve yasaktır

2

uzakta değil

Pasifik''te

canı sıkılınca Sam amcaların 

canı çıkar Ortadoğu''da çocukların

hayat böyledir demiyorum yavrum

ya vururlarsa seni her gün gözünün önününde

bir daha 

bir daha 

bir daha', '1 Hayat böyledir yavrum,demiyorum Yeteneklerinin sana acı vermesine izin verme kaza anını bir tek sana anlatmazlar öldüğünde çünkü küçükken ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaya']::text[], 8.5, '{"poet":"Mustafa Kaya","poet_slug":"mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/demiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çölle Düet', 'colle-duet-mustafa-kaya-t2x26', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her yanılgı bir kum tanesi,ertelenmiş her aşk

bir çöl devrediyor.

sonunda son anda gördüğüm

halisülasyonum /evrensel bir seraba dönüşüyor

ve içine  kapananları putlaştırıyoruz

önce inancımızı sonra kendimizi kaldırdık rafa

serabı tuzağa düşüremediler

bu yüzden

belki de binlerce yüzden  gidip çölü intihara zorladı martılar

ama unuttukları bir şey vardı

binlerce çığlığın hatırlatmaya çalıştığı

yanılgılarımızı unutmadığımız için kazanacağız 

yeteneklerimizi yetinmek için

birleştiriyoruz

işte her şey bundan sonra başlayacak

mutluluk o ki

bzi de mutlu etsin', 'her yanılgı bir kum tanesi,ertelenmiş her aşk bir çöl devrediyor. sonunda son anda gördüğüm halisülasyonum /evrensel bir seraba dönüşüyor ve...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaya']::text[], 8.5, '{"poet":"Mustafa Kaya","poet_slug":"mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/colle-duet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuklu Kaldım', 'tutuklu-kaldim-cafer-tayyar-ozkan-v8zmw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecelerim zindan oluyor artık,

Bir sahibin elinde ümitsiz kaldım,

Sabır taşım canan biliyor artık,

Bir dileğin kalbinde tutuklu kaldım...

Rüyalarım hüsran oluyor artık,

Ne çare tabuların içinde boğuldum,

Dilek taşım, aşkım seviyor artık,

Feleğin çemberinde çaresiz bir kuldum...

26.10.2002 Tarsus', 'Gecelerim zindan oluyor artık, Bir sahibin elinde ümitsiz kaldım, Sabır taşım canan biliyor artık, Bir dileğin kalbinde tutuklu kaldım... Rü...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tutuklu-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benzeri Topraklar', 'benzeri-topraklar-i-brahim-asli-n5cya', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir tin benzeri işte 

yoksun ama varlığını kanıtı kendinsin.

gösterdikçe acı 

gösterdikçe azap külleri

dönüp arkana bir kere bağırsaydın

aynalara

senin benzerin işte 

bu ayakkabıyı aldığın

bu kolyeyi hediye ettiğin yer.

basmadığın toprak yatacağın yer mi? 

orası kendinin yeri mi? 

ama ora herkesin yeri.', 'bir tin benzeri işte  yoksun ama varlığını kanıtı kendinsin. gösterdikçe acı  gösterdikçe azap külleri dönüp arkana bir kere bağırsaydın ayn...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Aslı']::text[], 8.5, '{"poet":"İbrahim Aslı","poet_slug":"i-brahim-asli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benzeri-topraklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedenim cân gibi düşlesin beni', 'bedenim-c-n-gibi-duslesin-beni-sair-ahrazi-sdoxu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaderin nakışı ömürse mâdem,

İsmine harf gibi işlesin beni.

Nefesin nasîbi emirse mâdem,

Yâdına söz gibi eşlesin beni.

Sevdânın simâsı gönül ayânı,

İki damla yaştır belki ziyânı,

Neyleyim hüzünü gamlı rüyânı,

Hasretin el gibi dışlasın beni.

Seyrine tutunup yaşam boyunca,

Adanmış yılları güne koyunca,

Hayât denen o ki Cânân deyince,

Durduğu an gibi yaşlasın beni.

Ahrâzi dilimde sükût üzeri,

Lisâna kavuştu aşkın nazarı,

Yârinden ayrıya hâli mezarı,

Bedenim can gibi düşlesin beni.', 'Kaderin nakışı ömürse mâdem, İsmine harf gibi işlesin beni. Nefesin nasîbi emirse mâdem, Yâdına söz gibi eşlesin beni. Sevdânın simâsı gönül...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bedenim-can-gibi-duslesin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-i-brahim-asli-1jk4q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'denizin sesine kulak tıkadım dün gece

bir taburenin üstünde

küçük kutulara vurdum sesim olsun diye

rüzgarlarında alevlendim

yanak yanağa haykırış bu 

belki si yok aynısı bu.

şimdilerde hallerin üzerimde etkisi var.

konuşsan suç

sussan suç

yesen aç

yemesen tok

zor bir gecenin izleri mi? 

hep soru mu? 

hep cevap mı? 

yalan mı? 

boşu ver,dolu senin olsun.

ben yokum da sen var ol.

sağol', 'denizin sesine kulak tıkadım dün gece bir taburenin üstünde küçük kutulara vurdum sesim olsun diye rüzgarlarında alevlendim yanak yanağa hay...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Aslı']::text[], 8.5, '{"poet":"İbrahim Aslı","poet_slug":"i-brahim-asli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sessizlik-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erir Oldum', 'erir-oldum-cafer-tayyar-ozkan-cf1we', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir söze çok ser gitmişse bu dünyada, 

Bir seviyorum sözüne kalbim yanar,

Mutluluk arar yelkenim sonbaharda,

Eş ruhumuz sevda için neleri bekler...

Yaralı yüreğim, eski sevdayı bekleme,

Bir kıvılcımla gelecek aşkla canlanır,

Kısacık anlara bu sevda sığar mı deme,

Göz açıp kapanıncaya dek neler yaşanır... 

Seni çok ama çok seviyorum derken, 

Gözlerime derinden bakabilir misin? 

Aynı sözü bana defalarca söylerken,

İçin titremeden, nefes alabilir misin? ... 

Ne zaman yağmur bulutu görsem, 

Kadınımdan gelir diye sevinir oldum,

Seni andığımda nedense üzerime düşen 

Yağmur tanelerinden, sen diye erir oldum...

06.11.2002 Ankara', 'Bir söze çok ser gitmişse bu dünyada,  Bir seviyorum sözüne kalbim yanar, Mutluluk arar yelkenim sonbaharda, Eş ruhumuz sevda için neleri be...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/erir-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doymalı', 'doymali-murat-berk-50212', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamımız daraldı

Doyumsuz duygulara

Zincir vurmamalı,

Koşmalı aşka, 

Doymalı sarılmaya,

Doymalı koklamaya,

Tek şeye doymamalı,

O da

Bana ve sana....', 'Yaşamımız daraldı Doyumsuz duygulara Zincir vurmamalı, Koşmalı aşka,  Doymalı sarılmaya, Doymalı koklamaya, Tek şeye doymamalı, O da Bana ve...', ARRAY['Türk Edebiyatı','Şiir','Murat Berk']::text[], 8.5, '{"poet":"Murat Berk","poet_slug":"murat-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/doymali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiceğim', 'sevdicegim-fatih-konuk-5pgfs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutluluğun M sini bile hiç tatmadım

Seni hep içerimde sakladım atmadım

Bir gece resmini öpmeden yatmadım

Söküp atamam ben seni kalbimden

Sevdiceğim gül çiçeğim

Sensiz öleceğim

sevdiceğim,güldiceğim

sensiz öleceğim

Nefretin N sini bile duyamadım sana

Gitme ne olur daha doyamadım sana

İçimdeki duyguları diyemedim sana

Silip atamam ben seni kalbimden', 'Mutluluğun M sini bile hiç tatmadım Seni hep içerimde sakladım atmadım Bir gece resmini öpmeden yatmadım Söküp atamam ben seni kalbimden Sev...', ARRAY['Türk Edebiyatı','Şiir','Fatih Konuk']::text[], 8.5, '{"poet":"Fatih Konuk","poet_slug":"fatih-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdicegim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yığın Söz Et Anne', 'bir-yigin-soz-et-anne-derin-oger-yixrm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bahar geçmiş kış gelmiş

Ben bahçede saklambaç oynarken anne

Nerede başlamış nerede bitmiş

Arkamı döndüğümde yoktular anne

Yüreğimdeki filiz ağaçlaşmış

Acılarla ayrılıklarla ölümlerle anne

İçimde inançsızlık birikmeye başlamış

Dalımda yapraklar bir bir soluyor anne

Üstüme yuvarlanıyor kış

Kırıyor göğe uzanan dallarımı kar anne

Öğüdüne kapanıyor göz kapaklarım

Sular acı hayaller darmadağınık anne

Ardımda yarınlar kuyruğa girmiş

Göğsümü sancılar körüklüyor anne

Yalan iyice mantarlaşmış

Gözümden kulağımdan  çek anne

Kim aklı akıl kimi bilmiş

Çocukluğum uzaklaştıkça anladım anne

Sarıl bana tut ellerimi bir yığın söz et

Sevecen bir dokunuş saçlarının aklarında anne..', 'Bahar geçmiş kış gelmiş Ben bahçede saklambaç oynarken anne Nerede başlamış nerede bitmiş Arkamı döndüğümde yoktular anne Yüreğimdeki filiz ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-yigin-soz-et-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünmek', 'dusunmek-abdul-kadir-koseoglu-joqyn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hiç yaşanmamış bir aşkın ardından

sevilmemiş bir sevgiliye ağlıyorum

yalnızlığın

en ağır cezasını verdiği

bu sıkıcı bahar akşamında

gök yüzündeki tüm yıldızlar öyle güzeller ki

bu gece

ay,

sanki yakından gözlerime tutulmuş bir projektör gibi

Düşman mıydılar bana

yoksa sevenlere hediyemi

anlayamadım

Ezik bir yüzle kaldırdım başımı

gökyüzüne bakmaya çalışıyordum

yorgun ve ıslaklıktan açılamayan garip gözlerimle

Niye diye sorarken ben onlara

onlar ise bana

biz tüm güzelliklerimizle sevenlere mutluluk dağıtıyoruz

sen hala yalnız mısın

yazık sana der gibiydiler

İçimden haklı olduklarını kabul ediyordum

ama

ne yapsın garip beynim kabullenmek ölüm geliyor

Zehirlerin en kuvvetlisi saydığım

bitmiş bir sevginin arkasından

korkuyordum beklide

yeni bir zehri yeniden içmeye

bitmeyecek sandığım gecenin Ortasın dayken

yine derin düşüncelere dalmışım farkında olmadan

konu hep aynı

yalnızlık

bir kor alev gibi yakıyordu beynimi

içimden haykırıyordu tüm hücrelerim yalnızım diye

suçlu bendim her zamanki gibi

sanki ben isteyerek yalnızmışım gibi

bilmiyordu kimse

kaderin bir çıkmazında olduğumu

anlayamıyorlar

sevmek isteyip sevemediğimi

sevdiğimi ama sevilmediğimi

anlayamıyorlar

ne kadar acı çektiğimi

ölmek isteyip ölemediğimi', 'hiç yaşanmamış bir aşkın ardından sevilmemiş bir sevgiliye ağlıyorum yalnızlığın en ağır cezasını verdiği bu sıkıcı bahar akşamında gök yüzü...', ARRAY['Türk Edebiyatı','Şiir','Abdul Kadir Köseoğlu']::text[], 8.5, '{"poet":"Abdul Kadir Köseoğlu","poet_slug":"abdul-kadir-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/dusunmek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim', 'yuregim-mehmet-seyidhasanoglu-8tv8o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sensizken karanlık bir geceyim, 

Elemim bitmez, bitmez derdim kederim, 

Sen geldin mi; gece biter, olurum gündüz, 

İçim kıpır kıpır olur heyecanla dolar, 

Cesaretim kırılır, yüzüm kızarır... 

En büyük sevdanın adısın yüreğim! ... 

                                              (gıcık_şair)', 'Ben sensizken karanlık bir geceyim,  Elemim bitmez, bitmez derdim kederim,  Sen geldin mi; gece biter, olurum gündüz,  İçim kıpır kıpır olur...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seyidhasanoğlu']::text[], 8.5, '{"poet":"Mehmet Seyidhasanoğlu","poet_slug":"mehmet-seyidhasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuregim-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yanardağ Fışkırması', 'bir-yanardag-fiskirmasi-mustafa-ceylan-mvxtz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yanardağ fışkırması

Benim gönlüm deli gönlüm.

Ceylanların hıçkırması

Benim gönlüm deli gönlüm

Dost dağının büyük çığı,

Çiğdemlerin hıçkırığı,

Su köpüğü, gün ışığı

Benim gönlüm, deli gönlüm.

Neye yarar çok ile az? 

Biraz sevda, biraz da naz

Yunus’ a can, Veysel’ e saz

Benim gönlüm, deli gönlüm.

Yükseklerde harman olur,

Dertlilere derman olur,

Aşk denince ferman olur

Benim gönlüm, deli gönlüm.

Kanatlanıp göğe uçar,

Kendisinden kendi kaçar,

Hasret hasret çiçek açar

Benim gönlüm, deli gönlüm.

                Beste: İsmail İPEK

        	Düzenleme: Musa EROĞLU', 'Bir yanardağ fışkırması Benim gönlüm deli gönlüm. Ceylanların hıçkırması Benim gönlüm deli gönlüm Dost dağının büyük çığı, Çiğdemlerin hıçkı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-yanardag-fiskirmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu Türküleri', 'anadolu-turkuleri-mustafa-ceylan-4lxub', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Türküler söylenir Anadolu’ da

“Güzeller güzeli Reyhan! ” diyerek.

Aşıklar inletir çalar sazı da

“Avcı vurmuş garip ceylan! ” diyerek.

Türküler söylenir şehirde, köyde

Davulda, halayda, çekilen hey’ de

Kadehlere dolan köpüklü mey’ de

Dertlenip ah çekip “aman! ” diyerek.

Anneler düğünde başlar ağıda,

Türküler aşığı yaşatan gıda,

Bazen mısralanır geçer kâğıda

“Dağların başında duman” diyerek.

Kederde, neşede türkü söylenir,

Pınarın başında kalır eğlenir.

Mecnun’ da, Ferhat’ ta coşar dillenir

“Aşıklık çekmesi yaman! ” diyerek.', 'Türküler söylenir Anadolu’ da “Güzeller güzeli Reyhan! ” diyerek. Aşıklar inletir çalar sazı da “Avcı vurmuş garip ceylan! ” diyerek. Türkül...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anadolu-turkuleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antalyaspor Marşı', 'antalyaspor-marsi-mustafa-ceylan-hi1ej', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çıkmış Akdeniz’ den dalgalar gibi

Geliyor, geliyor şimşek geliyor...

Kırmızı, beyazlı bayraklar gibi

Geliyor, geliyor şimşek geliyor...

Antalya seninle gurur duyacak,

Her maçın sevinçle dolup taşacak,

Peşpeşe golleri şimdi atacak

Geliyor, geliyor şimşek geliyor...

Peşpeşe golleri atacak şimdi,

Zafere zaferler katacak şimdi,

Bir şimşek misali çakacak şimdi

Geliyor, geliyor şimşek geliyor...

Antalya seninle gurur duyacak,

Her maçın sevinçle dolup taşacak,

Peşpeşe golleri şimdi atacak

Geliyor, geliyor şimşek geliyor...

                Beste:Gültekin ÇEKİ

        	Makam: Nihavent

        	Usül: Sofyan', 'Çıkmış Akdeniz’ den dalgalar gibi Geliyor, geliyor şimşek geliyor... Kırmızı, beyazlı bayraklar gibi Geliyor, geliyor şimşek geliyor... Anta...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/antalyaspor-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kimseyi Sevemem', 'ben-kimseyi-sevemem-aysel-sevim-wugid', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz yaşı gülüyüm ben

Yağmursuz çölde biten

Etmeyin bana sitem

Ben kimseyi sevemem

Acıyla yetişmişim

Aşk ile tutuşmuşum

Sevdayla atışmışım

Aşk derdini çekemem

Bülbülden uzaktayım

Yalnız yaşamaktayım

Karardı gece ayım

Günü değiştiremem

Ad koydum hüzün gölü

İstemem şen bülbülü

Hakikat olmuş ölü

Artık oyuna gelmem.', 'Göz yaşı gülüyüm ben Yağmursuz çölde biten Etmeyin bana sitem Ben kimseyi sevemem Acıyla yetişmişim Aşk ile tutuşmuşum Sevdayla atışmışım Aş...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-kimseyi-sevemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönül', 'deli-gonul-mustafa-ceylan-176rg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yâr yâr diye kuzu gibi

Meler gider deli gönül.

Uykuları orta yerden

Böler gider deli gönül.

Göz göz oldu yâreleri,

Ağlatıyor gökle yeri

Yorgun, dargın seneleri

Siler gider deli gönül.

Kaderi yazılı gülde,

Gül demeti olan elde.

Mecnun gibi çölü çölde

Eler gider deli gönül.

Hasret elinde çerağı,

Ateş savurur dudağı

Ferhat gibi yüce dağı

Deler gider deli gönül.

Dost elinden çeker aman,

Gözü yaşlı, başı duman

Yârini bulduğu zaman

Güler gider deli gönül.', 'Yâr yâr diye kuzu gibi Meler gider deli gönül. Uykuları orta yerden Böler gider deli gönül. Göz göz oldu yâreleri, Ağlatıyor gökle yeri Yorg...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deli-gonul-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun Yemişçesine', 'kursun-yemiscesine-aysel-sevim-bkrzr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün yolun buralara düşecek

Aklına ilk gelen şey beni sormak olacak

O gitti diyecekler

Vurulmuşa döneceksin,dudakların uçuklayacak

Şaşıracaksın ne yaptığını bilemeyeceksin

Beni kaybetmenin acısını

Ta yüreğinde hissedeceksin

Beni başka kollarda düşündükçe

Kendini yiyip bitireceksin

Pişman olacaksın yaptıklarına

Yenik düşeceksin arzularına isteklerine

Beni arayacaksın her defasında

Yalancı elleri her tuttuğunda

Benim sıcaklığımı arayacaksın

Dudakların yalancı dudaklarda

Benim tadımı bulamayacak

Nihayet bir gün yollara düşeceksin

Ummadığım beklemediğim bir zamanda

Kapımı çalacaksın

Kapıyı açan kızım belki oğlum olacak

Kim bilir belki beni can gibi 

Kucaklayan eşim olacak

Ve sen yıkılacaksın kurşun yemişçesine

Kapımdan döneceksin.

Çoban yıldızı gibi o anda söneceksin.', 'Bir gün yolun buralara düşecek Aklına ilk gelen şey beni sormak olacak O gitti diyecekler Vurulmuşa döneceksin,dudakların uçuklayacak Şaşıra...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kursun-yemiscesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüncelerim Harman', 'dusuncelerim-harman-aysel-sevim-xhl3z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umutlar yığın yığın, düşüncelerim harman

Geçer bir gün diyorlar ama geçmiyor zaman', 'Umutlar yığın yığın, düşüncelerim harman Geçer bir gün diyorlar ama geçmiyor zaman...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/dusuncelerim-harman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzular Aşka Katık', 'arzular-aska-katik-aysel-sevim-a6vig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben yoruldum, ben bittim, gücüm kalmadı artık

Duygular yavan kaldı, arzular aşka katık', 'Ben yoruldum, ben bittim, gücüm kalmadı artık Duygular yavan kaldı, arzular aşka katık...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/arzular-aska-katik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum Tutsak', 'umudum-tutsak-aysel-sevim-psg3c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülümse neye yarar

Biz birbirimize yasak

Bir umudum daha var

Çağlar altında tutsak', 'Gülümse neye yarar Biz birbirimize yasak Bir umudum daha var Çağlar altında tutsak...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/umudum-tutsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Hançer saplandı', 'kor-hancer-saplandi-aysel-sevim-8j18r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat bana işkence etmekten yorulmadı

Kafam karma karışık, duygular durulmadı

Yüreğime kör hançer saplandıkça saplandı

Kaderim oyun etti, talihimse yenildi.', 'Hayat bana işkence etmekten yorulmadı Kafam karma karışık, duygular durulmadı Yüreğime kör hançer saplandıkça saplandı Kaderim oyun etti, ta...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kor-hancer-saplandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberim Yok', 'haberim-yok-mustafa-ceylan-ld5zc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kapıdan içeriye

Girmişim de haberim yok.

Bin odayı bir kilide

Vermişim de haberim yok.

Ne ki Ceylan’ ımın sözü? 

Kan, yaş ile dolmuş özü,

Bir aynada on bin yüzü

Görmüşüm de haberim yok.

Dağ dayanmaz feryâdıma,

Ceylan diyorlar adıma,

En sonunda muradıma

Ermişim de haberim yok.

Düşüp sonsuz deryalara,

Daldım, gülden dünyalara.

Yüreğimi bulvarlara

Sermişim de haberim yok.

Bir ışıkta bin görünen,

Çiçekten “urba” bürünen,

Milyon parçaya bölünen

Bir’ mişim de haberim yok.

Beste: Şenol YAĞAR', 'Bir kapıdan içeriye Girmişim de haberim yok. Bin odayı bir kilide Vermişim de haberim yok. Ne ki Ceylan’ ımın sözü?  Kan, yaş ile dolmuş özü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/haberim-yok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatsız Uçuyorum', 'kanatsiz-ucuyorum-aysel-sevim-c51v1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir boşlukta gibiyim, yaşamaktan habersiz

Duygularım isyankâr,umutlarım çaresiz

Sınır dışına çıktım, kimsesizim kimsesiz

Kanatsız uçuyorum, kuşlar bana imrenir.', 'Bir boşlukta gibiyim, yaşamaktan habersiz Duygularım isyankâr,umutlarım çaresiz Sınır dışına çıktım, kimsesizim kimsesiz Kanatsız uçuyorum, ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kanatsiz-ucuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıtma Yorgun Gözlerimi', 'akitma-yorgun-gozlerimi-aysel-sevim-9rd1w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anla beni sevgilim

Gözlerine bakarken nasıl titrediğimi

O güzel bakışlarının bana neler hissettirdiğini

Anla sevgilim.

Sana yaklaşırken

Elini tutmaya hazırlanırken

Kalbimin yerinden çıkarcasına teklediğini

Dudakların dudaklarıma yaklaştığında

O an ölecekmişim gibi irkildiğimi

Seni her şeyden çok sevdiğimi

Anla sevgilim.

Hatırla geçmişteki günlerimizi

Saatlerce bakışıp anlamazdık zamanın nasıl geçtiğini

Ve seninle her şeyin farklı güzelliklerini

Anla sevgilim.

Ben biliyorum anlıyorum

Benimle ilgili neler düşündüğünü

Senin de beni çılgınlar gibi sevdiğini

Anla sevgilim.

Gizleme artık bana karşı hislerini

Artık itiraf et aşkının gizemli hecelerini

Akıtma ağlamaktan yorgun gözlerimi

Seninle ne kadar mutlu 

Bir çift olabileceğimizi

Anla sevgilim.', 'Anla beni sevgilim Gözlerine bakarken nasıl titrediğimi O güzel bakışlarının bana neler hissettirdiğini Anla sevgilim. Sana yaklaşırken Elin...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/akitma-yorgun-gozlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun Elleri', 'yagmurun-elleri-aysel-sevim-k9l0y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüznün yağmurlarıyla ıslanıyorum

Çile darbesiyle süsleniyorum

Yine boş bir umuda yaslanıyorum

Karanlık dünyamı aydınlatır diye

Gülen bu gözlerimde

Gizli bir kin yatıyor

Kalbim sevgi yerine 

Kinle kucaklaşıyor

Kaderim günden güne

Bir yokluğa batıyor

Çırpınıp duruyorum yüze çıkayım diye

Ne aşktan ne sevdadan

Beklentim olmayacak

Girdiğim bomboş odam 

Derdimi paylaşacak

Yalnızlıksa en dürüst 

Arkadaşım olacak

Sırrımı içinde saklar mı diye? 

Bir çiçeği koklamak

Bir havayı solumak

Yumuşacık yağmurun

Elleriyle ıslanmak

İstediğim tek şey bu

Doğayla kucaklaşmak

Yalnız seni sevip anayım diye', 'Hüznün yağmurlarıyla ıslanıyorum Çile darbesiyle süsleniyorum Yine boş bir umuda yaslanıyorum Karanlık dünyamı aydınlatır diye Gülen bu gözl...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yagmurun-elleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-mustafa-ceylan-wwerj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevda yollarında gönül kervanım

Dağ olur önüme düşer ayrılık.

Ne kadar özlerse özlesin canım

Çığ olur önüme düşer ayrılık.

Başıma kar yağmış, sinemde duman

Demen dostlar bana, delirmiş demen! 

Yâre kavuşmama yetmiyor zaman

Çağ olur önüme düşer ayrılık.

Tükettim umudu gönül dağımda,

Hüzün şarkıları dudaklarımda.

Zalim takvimlerin yapraklarında

Ağ olur önüme düşer ayrılık.', 'Sevda yollarında gönül kervanım Dağ olur önüme düşer ayrılık. Ne kadar özlerse özlesin canım Çığ olur önüme düşer ayrılık. Başıma kar yağmış...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrilik-155-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim yanmaktadır', 'gozlerim-yanmaktadir-aysel-sevim-vn74b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yumuşak meltem değdi dudaklarıma

Dokundukça kayboldu karanlığın koynunda

Yalnız geçirdiğim her akşamın sabahında

Sen varsın sanki yanımda

Gözlerimi her açtığımda

Seni yakalamaya çalıştım

Asla ulaşamadığım

Bir yolun sonundasın

O kadar yorgun düştük ki bu yolculukta

Ne kadar koşsam da ardın sıra

Biliyorum ulaşılmazsın.

Kalbinin derinliklerinde bir sızı hissettiğinde

Bil ki o an seni anmaktan yorgun

Bir kalp atmakta

Gözlerinden ani ve zamansız yaşlar döküldüğünde

Bil ki o an sana ağlamaktan

Ve resmine bakmaktan

Başka hiçbir şeyi umursamadım

Her sokakta her köşede

Seni gören ve arayan

Gözlerim yanmaktadır', 'Bir yumuşak meltem değdi dudaklarıma Dokundukça kayboldu karanlığın koynunda Yalnız geçirdiğim her akşamın sabahında Sen varsın sanki yanımd...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gozlerim-yanmaktadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgünümü Anlamadın', 'surgunumu-anlamadin-aysel-sevim-wk483', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkın ile gece gündüz

Yandım piştim anlamadın

Senin için her şeyimi

Feda ettim anlamadın

Sensiz olmak ölümden zor

Seninleyse hiç olmuyor

Bilmem gönlün ne istiyor

Sordum ama anlamadın

Bakışımda gezeli

Gönülden gelen sesleri

Senin için deli deli

Gezip durdum anlamadın

Nasıl bağlanmışım sana

Başkası haramdı bana

Ömrüm adadım yoluna

Sürgün oldum anlamadın

Ah! Bir anlasaydın beni

Anlasaydın hislerini

Aşkın yaktı canda teni

Hala daha anlamadın', 'Aşkın ile gece gündüz Yandım piştim anlamadın Senin için her şeyimi Feda ettim anlamadın Sensiz olmak ölümden zor Seninleyse hiç olmuyor Bil...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/surgunumu-anlamadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç Etmek İstiyorum', 'goc-etmek-i-stiyorum-aysel-sevim-2tc5q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göç etmek istiyorum ben artık bu yerlerden

Kurtulmak istiyorum

Bu bitmez çilelerden

Unutmak istiyorum bütün yaşananları

Yok etmek istiyorum geçmişte olanları

Ben kaybettim artık bu yarışmayı

Çözemedim hayatı

Hayatın anlamsız sorularını

Yalnız ve kimsesizim, bitkin ve çaresizim

Varlığımdan habersiz kaybolmuşum

Kime ne diyebilirim ki bu imiş alın yazım

Vefasız riyakârılar arasında yok yüzüm.

Yalan en bayat düşman

Karşılık ölüm olsa

Sözdür bu benim sözüm.

Utanmaz şerefsizle savaşmak büyük arzum

Lakin dünyanın pisliklerini 

Temizlemeye de gücüm yok

Kurtulabilmek için ile de ölmek lazım

Yok yok! ! ! 

Değiştim ben dostlarım', 'Göç etmek istiyorum ben artık bu yerlerden Kurtulmak istiyorum Bu bitmez çilelerden Unutmak istiyorum bütün yaşananları Yok etmek istiyorum ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/goc-etmek-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Yaşını Silmeliyim', 'goz-yasini-silmeliyim-mustafa-ceylan-q026i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nazlı yârin yanağından

Göz yaşını silmeliyim.

Takvimlerin yaprağından

Göz yaşını silmeliyim.

Ağlayan mor menekşenin,

Gurbet ellere düşenin,

Hicran yolunda koşanın

Göz yaşını silmeliyim.

Dalında gonca güllerin,

Öksüz kalan bülbüllerin,

Yâre giden mendillerin

Göz yaşını silmeliyim.

Mecnun gibi aşıklardan,

Yunus gibi eşiklerden,

Bir yavrunun beşiklerden

Göz yaşını silmeliyim.

Çeşmeye bakan taşların,

Buluta değen kuşların,

Caddelerde ağaçların

Göz yaşını silmeliyim.', 'Nazlı yârin yanağından Göz yaşını silmeliyim. Takvimlerin yaprağından Göz yaşını silmeliyim. Ağlayan mor menekşenin, Gurbet ellere düşenin, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/goz-yasini-silmeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ohh Beeee! ! ! !', 'ohh-beeee-mustafa-ceylan-5xdtt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göklere çevirip şu gözlerimi

Yakmışım ateşi başımda oh be! 

Dinlettim dünyaya tüm sözlerimi

Barış çiçek açar döşümde oh be! 

        Kızgın güneşlerin bağrına vurdum,

        Bebek elleriyle dünyalar kurdum,

        Susuz ülkelere bulut savurdum

        Umut, toprağımda-taşımda oh be! ,

Dağıttım gözleri saran efkârı,

Cümle alınları çektim yukarı,

Aşkımla erittim bembeyaz karı

Bahar alkış tutar koşumda oh be! 

        Yok oldu uçurum, karanlık bitti

        Evlerin önünde horozlar öttü.

        Uyandı çocuklar, okula gitti

        Mutluluk evimde, aşımda oh be! 

Yunuslardan aldım güzellikleri,

Yıkadım, arıttım bütün elleri.

Bal kaymak tasına soktum dilleri

Sevda tatlısı var dişimde oh be! 

     Sel olup, şeytanı sildim, süpürdüm

    Girdim gönüllere coştum, köpürdüm.

    Ceylan’ ı  Ceylan’ dan alıp götürdüm,

    Artık bin huzur var, işimde oh be!', 'Göklere çevirip şu gözlerimi Yakmışım ateşi başımda oh be!  Dinlettim dünyaya tüm sözlerimi Barış çiçek açar döşümde oh be!          Kızgın ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ohh-beeee-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeç Benden', 'vazgec-benden-aysel-sevim-asjd3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu aşkın günahını çekeceksin sevgilim

Beni bulaştırma sakın

Çünkü artık ben yokum

O büyük sevgide yok

Bitti her şey bunu kabullen artık

Sana olan borcumu

Sevgimle ödedim ben

Ama sen usanmadın

Beni kırıp incitmekten

Sevgi bir anlık heves değildir

Hayat bomboş olsa bile

Sen benim hayatımda bir varlıktın

Ama şimdi bir hiçsin

Sorarsan neden diye

Benim için yaşamıyorsun artık

Bir zamanlar yalnızca seni seviyordum

Seni arıyor seni soruyor seni bekliyordum

Ne yazık ki her ümidin peşinde 

Bir boşluğa savruldum 

Mutluluk kenarları örülmüş bir duvar

Aşılması güç artık

Beni beklemekten vazgeç

Ve sonsuza kadar unut beni

Düşünme artık', 'Bu aşkın günahını çekeceksin sevgilim Beni bulaştırma sakın Çünkü artık ben yokum O büyük sevgide yok Bitti her şey bunu kabullen artık Sana...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vazgec-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavru Ceylan', 'yavru-ceylan-mustafa-ceylan-nzlm3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey güzeller güzeli

Yavru ceylan gibisin.

Aşkından oldum deli,

Yavru ceylan gibisin.

Gözün yeşil, kaşın yay

Taze göğsün bir saray.

Aşığım... Vay güzel vay! 

Yavru ceylan gibisin...

Hoplar, zıplar, sekersin

Her bakışı çekersin.

Bal kaymaksın, şekersin

Yavru ceylan gibisin...

Girdin ele-avuca

Son verdirip oruca.

Dudakların doluca

Yavru ceylan gibisin...

Ayna ayna taran gel,

Şu gönlümü vuran, gel! 

Bir gün değil, her an gel! 

Yavru ceylan gibisin...', 'Ey güzeller güzeli Yavru ceylan gibisin. Aşkından oldum deli, Yavru ceylan gibisin. Gözün yeşil, kaşın yay Taze göğsün bir saray. Aşığım... ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yavru-ceylan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim Duman Duman', 'hasretim-duman-duman-aysel-sevim-zwgsu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalvarıyorum sana

Ne olur dön geriye

Duy artık beni n’olur

Nerdesin söyle nerde? 

Hasretim duman duman

Ağlarım zaman zaman

Kopmuşum bu dünyadan

Rüyalarımda her an

Ahrete göçüyorum

Yaşarım hayallerle

Ayık olmak tek çare

Ah bir gelsem kendime

Fırsat geçse elime

Neler planlıyorum.

Gönlüm bir aşk yuvası

Dinmiyor hiç ağrısı

Bundan daha fazlası

Sevenlerin cezası

Ne kadar bilmiyorum.

Bu sevdadan kopamam

Kendimi aldatamam

Hiç kimseye bakamam

Başkasıyla olamam

Ben seni seviyorum.', 'Yalvarıyorum sana Ne olur dön geriye Duy artık beni n’olur Nerdesin söyle nerde?  Hasretim duman duman Ağlarım zaman zaman Kopmuşum bu dünya...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hasretim-duman-duman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-mustafa-ceylan-329h8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alev dudakların hep böyle kalsın,

Aşkımı ellere duyurma canım.

Yosun bakışların tek beni bilsin

Gözümden gözünü ayırma canım.

Aşk bu yaştan sonra cin gibi çarpar,

Kader dallarını sallayıp çırpar,

Bana öfkelenir, sana göz kırpar,

Bırak tokat atsın, kayırma canım.

Yaktın ciğerimi eyledin kebap,

Kanaryam, civcivim, öldüren mehtap

Kız seni dinlemek sevap mı sevap,

Yumuşacık söyle, buyurma canım.

Alnıma yazılan yazıya küstüm,

Hasret potasında eriyip, piştim

Acıktım sevdana, çöllere düştüm,

Öleyim açlıktan, doyurma canım.

Çiçeğimsin, sarı gülüm, nevruzum

Kavalıma destan olan süt kuzum,

Bulutlar içinde duran yıldızım,

Sesinden bulutu sıyırma canım.', 'Alev dudakların hep böyle kalsın, Aşkımı ellere duyurma canım. Yosun bakışların tek beni bilsin Gözümden gözünü ayırma canım. Aşk bu yaştan ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunla Başladı Çaresizliğim', 'yoklugunla-basladi-caresizligim-aysel-sevim-ocpfr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokluğunla başladı benim çaresizliğim

Sen yokken her şey yok oldu gözlerimde

Bir umuttun, bir bekleyiş, bir saplantıydın bende

Aşkın azalmak yerine hep çoğaldı içimde

Her şey seninle başladı,gönlümün sahnesinde

Her şey seninle güzeldir, denemede, sikeçte

Hayat seninle özeldi sen vardın düşlerimde

Bırakıp gittin neden

Bu oyunun en heyecanlı yerinde

Sen gidince söndü ışıklar

Kapandı perde.

Şimdi soruyorum hep kendi kendime

Sevmişim seni meğer delicesine

Ağlıyorum her gece sığınıp hayaline

Gözlerinin karanlığında kaybolmak istiyorum

Daha da derinleşip

Seni bulmak, sarılmak istiyorum.', 'Yokluğunla başladı benim çaresizliğim Sen yokken her şey yok oldu gözlerimde Bir umuttun, bir bekleyiş, bir saplantıydın bende Aşkın azalmak...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yoklugunla-basladi-caresizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin?', 'nerdesin-mustafa-ceylan-lbnaj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Goncasın açılacak,

Açılıp saçılacak,

Yalnız benim olacak

Sevdiğim neredesin? 

Yollarını beklerim,

Bitmiyor gecelerim,

Adını hecelerim

Sevdiğim neredesin? 

Maviler mavi değil,

Yeşiller yeşil değil,

Özlüyorum seni bil! 

Sevdiğim neredesin? 

Kurumuş bir daldayım,

Sana giden yoldayım,

Bir bilsen ne haldeyim? 

Sevdiğim neredesin? 

Ayrılık cana yetti,

Yalnızlık deli etti,

Ceylan aklı kaybetti

Sevdiğim neredesin? 

Beste: Şenol YAĞAR', 'Goncasın açılacak, Açılıp saçılacak, Yalnız benim olacak Sevdiğim neredesin?  Yollarını beklerim, Bitmiyor gecelerim, Adını hecelerim Sevdiğ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nerdesin-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okursun Diye', 'okursun-diye-mustafa-ceylan-xmm9y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkımı dağlara, taşlara yazdım

Gelip de geçerken okursun diye.

Şu deli gönlümü pazar eyledim,

İplik iplik alıp dokursun diye.

Yılları saçımdan fırlatıp attım,

Seninle hayatı anladım, tattım.

Gönül ağacımdan dallar uzattım,

Bülbüller misali şakırsın diye.

Yorgun seneleri yollara yıksam,

Alın yazın olsam, hep sana baksam.

Şarkılar söyleyip seni anlatsam,

Goncada gül gibi kokarsın diye.

Gel bana, gül bana uzat elini! 

Ey menekşe gözlüm, Türkmen gelini! 

Döktüm mısralara bütün kalbimi

Şarkılar söyleyip okursun diye.

Beste: Şenol YAĞAR', 'Aşkımı dağlara, taşlara yazdım Gelip de geçerken okursun diye. Şu deli gönlümü pazar eyledim, İplik iplik alıp dokursun diye. Yılları saçımd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/okursun-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsan', 'olsan-ebru-temizkan-b3mle', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gözümde yaş olsan

yaşlarla seni anlasam

her görüntü sen olsan

gözlerimde buluşsak seninle...

beynimde bir düşünce olsan

kemirsen tüm hücrelerimi

damarlarımda varlığın dolaşsa

sadece seni düşünsem...

kulağımda ses olsan

duysam dünyanın en güzel senfonisini

en güzel aşk şarkılarını

ve hep seni dinlesem...

dilimde ses olsan, tat olsan

sadece seni söylesem

sadece senin sevdanı anlatsam,

seni tatsam...

sen benim olsan 

dokunsam sana 

benimle bir bütün olsan...

olur musun? ? ?', 'gözümde yaş olsan yaşlarla seni anlasam her görüntü sen olsan gözlerimde buluşsak seninle... beynimde bir düşünce olsan kemirsen tüm hücrele...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olsan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yayla Gülüne', 'yayla-gulune-mustafa-ceylan-4yeuh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sevdanın ateşi

Beni bende yakacak.

Gözlerinin güneşi

Dağlarımdan çıkacak.

Dağa kurup merdiven,

Gel çıkalım senle ben! 

Göz gözeyiz yeniden,

Yeniden gün doğacak.

Meskenimiz doruklar,

Yorganımız bulutlar,

Yastığımız umutlar,

Yarınlar aşk olacak.

Dağın karı erisin,

Yel essin, su yürüsün.

Yaylamızın gülüsün

Burcu burcu kokacak.

Ceylan gözlüm, kekliğim

Sarı çiğdem, kekiğim,

Hayatım, tek sevdiğim

Benimsin, benim ancak.', 'Bu sevdanın ateşi Beni bende yakacak. Gözlerinin güneşi Dağlarımdan çıkacak. Dağa kurup merdiven, Gel çıkalım senle ben!  Göz gözeyiz yenide...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yayla-gulune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solistler Geçidi', 'solistler-gecidi-ebru-temizkan-pc6px', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hava puslu

Ne yağmur hali var nede güneşli sıcak bir gün”

Radyoda bir fasıl inceden,

Eskilerden bir aşk şarkısı söylüyor Müzeyyen SENAR

Koltuk eski ama rahat

Tek eksiği çıtırdayan bir soba olmaması

Var ama vakti değil mevsim yazla-güz arası

‘Benzemez kimse sana tavrına hayran olayım’

Benzemez gerçekten

Sevda bir kor gibi işlemiş yüreğine

Mıhlanmış kalmış gitmeye niyeti bile yok

Vazgeçmeye çalışsa da o benden vazgeçmiyor.

Nırı nırı nırı nım 

‘Bakışından süzülen işvene kurban olayım’

dese de  Müzeyyen Abla ben kurbanlığımı yıllar önce ilan etmişim.

Şimdi ise yalnızım.

Yoksun.

Lutfunada eremeden öyle yalnız bir köşede oturuyorum.

Nırınırınırınım...

Bulutlar gökyüzünü kapladı ha patladı ha patlayacak yağmur

Radyo da fasıl dava etmekte ve beni deli etmekte,

Tanımadığım solist başlamaz mı şarkıya 

İşte o an yağmurla beraber benim gözyaşları da dayanamayıp başladı akmaya

‘Ben gamlı hazan sense bahar dinle de vazgeç’

Demesi kolay diyor içimden bir ses ne bahar gördü bu sevda ne kış ne yaz

Ama bana mısın demiyor inatçımı inatçı! 

Ne taze baharlar diledi bu yürek seçmek için kendine 

                  buldu bulmasına buldu da gönül hazanda vazgeçmiyor sevdi.

‘Olmaz meleğim böyle bir aşk bende vakit geç’

Bende diyorum olmaz diye meleğim bak hayır yok onda vakit epey geç 

Ama ne Nuh dinliyor,nede Peygamber.

Nırınırınırınım...

Ben iyisi mi ne yardan geçerim ne serden geçerim diyerek hepsinden vazgeçeyim.

Dışarıda yağmur bardaktan boşanırcasına yağıyor.

Fasıl beni mahvediyor karar verdim kalktım tam kanal değiştireyim derken

Başlamaz mı 

‘Bir bahar akşamı rastladım size’

Buyur buradan yak.

Elim uzandı kanal ayar düğmesine ama parmak tutmuyor öyle kaldı havada,

Kalbim pırpır.

‘Sevinçli bir telaş içindeydiniz,ama ne telaş herşey hazır

‘Derinden öyle bir arzu uyandırmıştı ki,dedim yıllardır aradığım bu

Ve şimdi soruyorum bükük boynumu

Ah o an ne diye sordum ‘daha önceleri neredeydiniz’diye

Nırınırınırınım...

Neyse hava epey hareketli yağmur iyi indirdi akşam olmaya başladı dememe kalmadan

‘Akşamın olduğu yerde bekle diyorsun,gelmiyorsun’ demezmi? 

Kaç akşam geçti kaç gece inledim ama gelmedin! ! ! 

Ben ise hala bekliyorum.

Ama ‘Neyleyim köşkü,neyleyim sarayı,içinde salınan yar olmayınca’

         Diyerek ne köşk aldım ne saray hala kiradayım.

Hala köşkümüzün ışıkları yanarken 

Huysuz ve tatlı kadın edasında 

Endülüs’te raksı unutaraktan

Gözlerimin içine başka hayal girmesin diye

Ağlatırsa Mevla’m birgün güldürür ümidiyle

Kara bulutlarıda aradan kaldırarak 

Vardar ovasından uçan kuşların rahat yol almasını sağladım.

Ama sen Dönülmez akşamın ufkundayım vakit çok geç diye başlayıp

Hiç ayrılamam derken kavuşmak hayal olduyla devam edip

Makberi bile ekledin ardına.

Ben ise hala ‘Doymadım sana ağlarım’ diye tutturuyorum,yazık bana

Nırınırınırınım..

Yağmur dindi bulutlar çekildi

Akşam güneşi yüzünü gösterdi

Radyodan bir ses yükseldi; 

‘SOLİSTLER GEÇİDİNİ DİNLEDİNİZ’

DİLİ-DİLİ-DİNK.....', 'Hava puslu Ne yağmur hali var nede güneşli sıcak bir gün” Radyoda bir fasıl inceden, Eskilerden bir aşk şarkısı söylüyor Müzeyyen SENAR Kolt...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/solistler-gecidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gibisin', 'bahar-gibisin-mustafa-ceylan-k5dwc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömrümün son demine

Düşen bahar gibisin.

Her saat gözlerime

Dönüp bakar gibisin.

Aşkın tüter tenimden

Gizlice bedenimden

Tutarak ellerimden

Öpüp koklar gibisin.

Şu çileli ömrümü

Boynu bükük gönlümü

Sana açan gülümü

Öpüp koklar gibisin.

Silerekten yılları

Tüm dertli şarkıları

Çiçeklenmiş dalları

Öpüp koklar gibisin.

Deliren takvimleri

Çıldıran mevsimleri

Şimdi tüm kadehleri

Öpüp koklar gibisin.

Bindim ya aşk gemine

Davet etme yemine

Ömrümün son demine

Düşen bahar gibisin.', 'Ömrümün son demine Düşen bahar gibisin. Her saat gözlerime Dönüp bakar gibisin. Aşkın tüter tenimden Gizlice bedenimden Tutarak ellerimden Ö...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bahar-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '3'' 2 Geçeleri Sevmiyorum', '3-2-geceleri-sevmiyorum-ebru-temizkan-t2j1j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulutların ardından göz kırpıyordu güneş,

Grimsi mavilikteydi gökyüzü

Kuşlar belki uzaklara giden kaz sürüsü

                  yada yeni gelen kaplamıştı her yanı.

Dünya sakin bir güne merhaba demişti  bile

İnsanlar hareketliydi ama sessizdi

Sadece bir-iki sokak kedisinin 

                yolda buldukları tenekeyle oynarken 

                            çıkardıkları ses hakimdi mahalleye.

O mevsim hep beklemekle geçti zaman

Pencerenin kıyısında oturup seyretmekle geçti.

Hep o an tekrar gelip çalacakmışçasına 

        amade bir hayat sürmeye başlamıştım

              tıpkı diğerleri gibi.

Diğerleri unutmak için ellerindeki her imkanı kullanıyorlardı

            yada gerçekten unutmuşlardı.

Peki ya ben? 

Unutabilecek miydim...

Bir dakika hatta saniyeler önce sağlam bir vücuda sahipken

60 saniye sonra yarım bir insan oluşumu

ya karımı ve yavrumu toprağın altında bırakışımı? 

Dostlarımla bir gece önce gülüşürken

Sabahına artık onlarla olamayışımı unutabilir miyim? 

Unutabilir miyiz? 

Artık yıldız görmek istemiyorum

Çünkü o yıldızların karıma seni seviyorum demiştim

Yavrumla kayan yıldızla ilk dileğimizi tutmuştuk

Bilebilir miydim son dileğimiz oluşunu? 

Nasıl unutabilirim? 

Artık ağustosu sevmiyorum

Sıcakta denize girmiştik ailem ve dostlarım

Çılgınlar gibi eğlenmiş

Balıklar gibi yüzmüştük

Aklıma gelmezdi son olacağı

Şimdi ne eğlenebilir ne de yüzebilirim

Nasıl unutabilirim? 

Artık 17’leri sevmiyorum

Çünkü o gün benim doğum günümdü 

Ama ölüm günüm oldu

Bilebilir miydi enkaz altında can veren anam

          Benim için o günün felaketim olacağını

Bilseydi doğurur muydu beni? 

Nasıl unutabilirim? 

Artık saatte 3’2 geçeleri sevmiyorum

Tüm sevdiklerimi kaybettiğim zamanı hatırlatıyor bana

Ama saatin suçu ne

Nereden bilsin dünyayı üzeceğini

Ama ben 3’1 geçeyi seviyorum

Çünkü karım canımın parçası son kez 

             Seni seviyorum demiş öpmüştü beni

Şimdi onunla avunup hep o anı düşünüyorum.

Ve ben o anla yaşama bağlanmaya çalışıyorum.

Gökyüzü artık bulutlu değil

Güneş gülen yüzünü göstermiş

Kuşlar  yok 

Gökyüzü masmavi

İnsanlar mutlu 

Kedilerin kovaladığı teneke kutu yalnız

Kediler köpekler tarafından kovalanıyor şimdi

Ah şimdi sokak ortasında duran 

O yalnız teneke kutuya 

Bir tekme vurmak için neler vermezdim! 

Bilemezsiniz..', 'Bulutların ardından göz kırpıyordu güneş, Grimsi mavilikteydi gökyüzü Kuşlar belki uzaklara giden kaz sürüsü                   yada yeni gel...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/3-2-geceleri-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antalyalı Güzel', 'antalyali-guzel-mustafa-ceylan-yfkmn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saçların dalgalı Akdeniz gibi

Antalyalı mısın söyle be güzel? 

Bu deli kalbimin sensin sahibi

Antalyalı mısın söyle be güzel? 

Şelale benzeri gümbür gümbürsün

Mor dağlar, bulutlar kadar özgürsün

Deniz kıyısında ne düşünürsün? 

Antalyalı mısın söyle be güzel? 

Gözlerin yeşille mavi arası

Yüreğin sevginin çiçek serası

Sessiz ağlamanın şimdi sırası

Antalyalı mısın söyle be güzel? 

Gülüşün yakışır elma yanağa

Vur dudak mührünü şu geçen çağa

Dikmişsin gözünü neden uzağa? 

Antalyalı mısın söyle be güzel? 

Afrodit çıldırır seni görünce

Dünya toz dumandır kalbe girince

Acaba ne dersin Ceylan sarınca? 

Antalyalı mısın söyle be güzel? 

	Beste: Şenol YAĞAR', 'Saçların dalgalı Akdeniz gibi Antalyalı mısın söyle be güzel?  Bu deli kalbimin sensin sahibi Antalyalı mısın söyle be güzel?  Şelale benzer...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/antalyali-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem', 'birtanem-ebru-temizkan-7etvn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tanem; 

         Yüreğime kazıdığım ismini

          Nasıl sök at dersin 

          Bilmez misin ki ben onu kazıyabilmek için

          Kaç yıl,kaç ay,kaç gün

          İğne oyası gibi özenle işledim bulunduğu yere

          Nasıl dersin ki sil onu 

          Reva mıdır? 

Nar tanem; 

          Beynime kazıdım yüzünü 

          Nasıl dersin unut diye

          Bilmez misin ki ben o yüz varsa yaşıyorum

          O gözler,gülüşün,ifaden

          Sanır mısın ki kolay girdi beynime

          Ne mücadele ne savaş verdi

          Nasıl dersin ki unut diye

          Hak mıdır? 

Gül tanem;  

          Kulaklarımda hala sözlerin 

          Bilmez misin ki ben onları anmadan yaşayamam

          O sözleri duyabilmek için 

          Kaç gün, kaç ay,kaç saat bekledim ben

          O sözlerle doğdum ben

          Nasıl dersin yalan diye

          Yalan mıdır? 

Yarenim,sevdiceğim, hayalim; 

         Beklemedi mi bu beden bir ömür seni,

         Tek bir ümit,tek bir ışık,tek bir kavuşma olmaksızın

         Hayalinle yaşamadım mı bugüne

         Her damla yaşta dağlanmadı mı yüreğim sanıyorsun

         Yüreğimin her damlasında beynim ölmedi mi? 

          Kulaklarım sağır olmadı mı? 

          Nasıl dersin ki unut beni? 

          Hangi can dayanır? 

          Hayır...', 'Bir tanem;           Yüreğime kazıdığım ismini           Nasıl sök at dersin            Bilmez misin ki ben onu kazıyabilmek için           ...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/birtanem-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım Antalya'' da', 'yalnizim-antalya-da-mustafa-ceylan-ptis0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Erdinç Mutlu Ağabeye...

Sahiller bomboş bugün,

Yalnızım Antalya’ da.

Başım da sarhoş bugün,

Yalnızım Antalya’ da.

Akdeniz sensiz bugün,

Düdenler şevksiz bugün,

Caddeler sensiz bugün,

Yalnızım Antalya’ da.

Yeşili görmüyorum,

Denize girmiyorum,

Nedendir bilmiyorum? ! 

Yalnızım Antalya’ da.

Ne gökte, ne yerdeyim? 

Buluttan bir perdeyim,

Çılgın caddelerdeyim,

Yalnızım Antalya’ da.

Kuşlarda kanat kırık,

Boğazımda hıçkırık,

Yeter, bunca ayrılık! 

Yalnızım Antalya’ da.

Parklar, bahçeler bomboş

Yollar, caddeler sarhoş,

Gel artık, gel, durma koş! 

Yalnızım Antalya’ da.', '-Erdinç Mutlu Ağabeye... Sahiller bomboş bugün, Yalnızım Antalya’ da. Başım da sarhoş bugün, Yalnızım Antalya’ da. Akdeniz sensiz bugün, Düd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalnizim-antalya-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Tesadüflerden İbarettir', 'hayat-tesaduflerden-i-barettir-ebru-temizkan-fn4q4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat  tesadüflerden ibarettir

Tesadüfen gelirsin dünyaya

Annenle baban belki isteyerek belki de neyse

Sahip olmuşlardır sana.

Sen tek çocukken yine tesadüfen bir kardeşin olmuştur

Tesadüfen taşındığınız mahallede bulunan ilkokula yazılmışsındır

Ve ne tesadüftür ki karşı komşunun kızıyla aynı sınıftasındır

Tesadüfler sonucu yaz tatillerinde hep büyükannenleri ziyarete gitmiş

Hep aynı köprüden geçmiş

Hep aynı kiraz bahçelerinin arasından koşup sarılmışsındır Büyükbabana

Okulun şehrin bilinen liselerinden biridir

Sen sıkı bir gurup kurup en eğlenceli günleri geçirmektesindir

Ve ne tesadüftür ki  ya okulun basketbol takımındasındır 

                                   yada en popüler insanısındır

Veya en silik tipi 

Ama her iki koşulda da sen yine sensindir.

İlk tecrübelerini yaşamaktasındır

Tesadüfen tanıştığın insan senin sevdiğin olmuş

Ve sen muhtemelen geceleri uyuyamamakta ona sevgini anlatacak şiirler yazmaktasındır

Tesadüfen gittiğiniz piknikte elini tutmuş

Ayrı insanlarla gittiğiniz sinemada tesadüfen karşılaşıp 

Şans eseri yan yana koltuklara düşmüşsünüzdür

Belki de ilk öpüşmeniz burada olmuştur(! bu bizi ilgilendirmez! ! !)

Karşı mağazanın vitrinine bakarken tesadüfen

Arkandan geçenin sevdiğin olduğunu fark etmiş

Baktığında onun başkasıyla olduğunu görmüşsündür

O an yıkılmıştın dimi? 

Neyse ilk ayrılık hiç unutulmaz  zaten

Ama hala onun sözleri kulaklarında çınlamaktadır

“Yemin ederim Tesadüfen yolda karşılaştık eski bir arkadaşım.

   Lütfen inan bana”

Ne komik.

Sen hırslanıp kendini derslere vermişsindir

Ve hatta tesadüfen girdiğin üniversiteden onca şeye rağmen

                                                  mezun olup işe bile girmişsindir.

O, senin gördüğün tesadüfen karşılaştığı insanla evlenmiştir

Tesadüfen...

Sen artık bazı şeylere daha mantıklı yaklaşmaya başlamışsındır

Bir gün senin tesadüfen uğradığın evinde

Anneni ağlarken bulmuşsundur yada babanı

O sana yaşlı gözlerle bakarak “ÖLDÜ” demiştir

Sen mıhlanıp kalmışsındır

Acı çok acı

HAYAT DEVAM EDİYOR

Ve sen yaşıyorsun

Tüm yaşamı anlatmaya kalkamayız

Birazda sürpriz olmalı

Ne dersin? 

Malum hayat tesadüflerden ibarettir! 

Peki kader? 

Yok hayır, kader değil

   HAYAT TESADÜFLERDEN İBARETTİR! ! !', 'Hayat  tesadüflerden ibarettir Tesadüfen gelirsin dünyaya Annenle baban belki isteyerek belki de neyse Sahip olmuşlardır sana. Sen tek çocuk...', ARRAY['Türk Edebiyatı','Şiir','Ebru Temizkan']::text[], 8.5, '{"poet":"Ebru Temizkan","poet_slug":"ebru-temizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/hayat-tesaduflerden-ibarettir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet mi dedim?', 'gurbet-mi-dedim-mustafa-ceylan-vh6s7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Parça parça edip deli gönlümü

Kuşlara, kurtlara yem et mi dedim? 

Araya araya bulduğum güller

Sana emanetti, kaybet mi dedim? 

Ne umursamazsın, ne de kaygısız! 

Geçmiyor bir günüm, dertsiz-tasasız.

Cadılar cadısı Ayşe adlı kız

Çağırdın da beni, “sabret mi” dedim? 

Bir telefon etsen, “Hadi gel! ” desen,

Bakıp gözlerime, “Biraz gül! ” desen,

“Öleceksen bile, bende öl! ” desen

Vuslat bahçesine ahret mi dedim? 

Dolgun dudakların tebessümle hoş,

Baksam ardın sıra olurum sarhoş,

Tuttu “Sayısal” ım, haydi bana koş! 

Aşkımız bir oyun misket mi dedim? 

Bir baksan, ceylanlar kör olur gider

Afrodit tahtından istifa eder...

Senden ayrılık mı ölümden beter! 

Araya girecek gurbet mi dedim?', 'Parça parça edip deli gönlümü Kuşlara, kurtlara yem et mi dedim?  Araya araya bulduğum güller Sana emanetti, kaybet mi dedim?  Ne umursamazs...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gurbet-mi-dedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahhhhh Bir Aşık Olsam', 'ahhhhh-bir-asik-olsam-mustafa-ceylan-e0tgo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“Haydi gel! ” diyordun goncayla, gülle

Mutlaka gelirim bu kıştan sonra! 

Neler söylemezdim belâlı dille? ! 

Ah bir aşık olsam, bu yaştan sonra! 

      

Yolları düz eder, dağı delerdim

Ardı sıra kuzu olur melerdim,

Ayrılığı parça parça bölerdim

Ah bir aşık olsam, bu yaştan sonra! 

Günde yirmi kere olurdum traş,

Kaplardı içimi heyecan, telâş

Gül olur, beynimi parçalayan taş

Ah bir aşık olsam, bu yaştan sonra! 

Zamanı-mekânı aşardım hemen,

Kınaman dostlarım, delirmiş demen

İnerdi yelkenler, tutmazdı dümen 

Ah bir aşık olsam, bu yaştan sonra! 

Torunumu alır parka koşardım,

Bir an göremesem derde düşerdim,

Sevda denen kızgın saçta pişerdim,

Ah bir aşık olsam, bu yaştan sonra! 

Lunapark olurdu içimle dışım,

Şaşırır kalırdı evimde eşim,

Ne yandan doğarsa doğsun güneşim

Ah bir aşık olsam, bu yaştan sonra! 

Evde çocuklarım bayram yapardı,

Benden çıkan yollar yâre sapardı,

Kalbim yuvasından bin kez kopardı,

Ah bir aşık olsam, bu yaştan sonra! 

Moralim yükselir, işim düzelir

Alacaklı bile, getirir verir.

Kuruyan dallarım birden yeşerir,

Ah bir aşık olsam, bu yaştan sonra! 

Şiirler yazardım, türkü söylerdim,

Yâre akmıyorsa suyu eğlerdim.

Sevgilim, bir tanem, ceylanım derdim

Ah bir aşık olsam, bu yaştan sonra!', '“Haydi gel! ” diyordun goncayla, gülle Mutlaka gelirim bu kıştan sonra!  Neler söylemezdim belâlı dille? !  Ah bir aşık olsam, bu yaştan son...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ahhhhh-bir-asik-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Var Neyleyim?', 'kis-var-neyleyim-mustafa-ceylan-duhk8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mevsimleri kilitledim takvimde

Anahtarı kayıp ettim neyleyim? ! 

Hiç kimseye göstermeden kalbimde

Saklamıştım, ayıp ettim neyleyim? ! 

Bir de baktım, kış mevsimi dışarda

Bana doğru saldırıyor ard arda...

Şakaklarım, yüz hatlarım efkârda

Aynalara sayıp-döktüm neyleyim? ! 

Soğukları gençliğime götürdüm,

Götürdüm de çatılarda yatırdım.

İçimdeki sıcakları yitirdim

Ocak idim, şimdi söndüm neyleyim? ! 

Yaramaz kış dinlemiyor hiçbir lâf,

Dost evinin kapısında eder gaf...

Boyun büküp istemez mi benden af? 

Yüreğini oyup, yaktım neyleyim? ! 

Ateşimle eritmiştim buzları,

Arkasından göründü hep kızları; 

O kızlar ki, buz dağıdır sözleri,

Seslerini duyup kaçtım neyleyim? !', 'Mevsimleri kilitledim takvimde Anahtarı kayıp ettim neyleyim? !  Hiç kimseye göstermeden kalbimde Saklamıştım, ayıp ettim neyleyim? !  Bir d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kis-var-neyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsam', 'olsam-mustafa-ceylan-igcgl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fettan fettan bakıyorsun

Kız yoluna kurban olsam.

Yanmıyorsun, yakıyorsun

Ocağında duman olsam.

Sensin ceylan, sensin canan

Aldın benden yüzbin puan,

Rüzgâr ile dalgalanan

Dizlerinde fistan olsam.

Peşin sıra gider salım,

Gök kuşağım, morum, alım.

Parça parça, dilim dilim

Ağızında pastan olsam.

Taptazesin kız sen körpe,

Al yanağın yağmur öpe.

Çekinmeden sere serpe

Gezeceğin bostan olsam.

Sarılmışım ellerine,

Koma beni el yerine.

Yosun renkli gözlerine

Bakan göze düşman olsam.', 'Fettan fettan bakıyorsun Kız yoluna kurban olsam. Yanmıyorsun, yakıyorsun Ocağında duman olsam. Sensin ceylan, sensin canan Aldın benden yüz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olsam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavga', 'kavga-mustafa-ceylan-le60v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüm içindeki beni öldürdü

Ben benden davacı, ben bana mahkum

Serseri dilimle kavgaya düştü,

Azcık konuşmasa yas’ tan sanıyor.

Eline geçirse duman edecek

Tutup yâr ile hemen gidecek

“Sus artık, sus artık, sus be! ” diyecek

Sanki lisan bilmez taş’ tan sanıyor.

Aşk dendi mi yakın eder ırağı? ! 

Yosun gözlülere bitmez merakı.

Aynada dans eden başında ak’ ı

Kendinden değil de kış’ tan sanıyor.

Yârin sehpasında can vermiş gönül,

Kurumuş bahçeler, boyun bükmüş gül.

Altına çift döşek, tepeye püskül

Yapıştırmış gider, baş’ tan sanıyor.', 'Gönlüm içindeki beni öldürdü Ben benden davacı, ben bana mahkum Serseri dilimle kavgaya düştü, Azcık konuşmasa yas’ tan sanıyor. Eline geçir...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kavga-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekler misin İstanbul', 'bekler-misin-i-stanbul-firat-celik-ungbi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni anlatmak çok zor, yaşamadıkça

Seni yaşamak çok zor, alev alev yanmadıkça

Sen ki göklerde yıldız, dünyamıza aysın

Yedi yüzyıllık aşkın havasını taşıyansın

Sensin dünyadan zulmü kovanlara kucak açan 

Mübarek dudaklarda müjdelenmiş sevdamızsın

Allah diyen gönüllerle yanıp tutuşan

Unutulmuş tarihimize ışık tutansın

Sensin İstanbul’um o güzel günleri bize anlatan

Üç asırdır hüzünlüsün gözü yaşlı

Seni anlayan yok diye bir hayli sancılısın

Üzülme İstanbul’um elbet bir gün..

Filistin’de, Çeçenya’da ve Irak’taki kanlarımızla

Dört bir yanda ağlayan analarımızla

Dinmek bilmeyen gözyaşlarımızla

Alem-i İslâma ve tüm insanlığa

Ve hatta gülü hiç koklamamış milyonlara

Verebilmek için güzel bir hediye

Hep beraber geliyoruz manevi fethe

Yeter ki sen İstanbul’um bizi bekle

Ahh...sen gül kokulu şehrim, bağrımı yaktın 

Aşk dolu günleri bir nebze olsun hatırlattın

Yine bekler misin İstanbul’um aşk dolu günleri

Heyecanlı bakışlarla gelen Sultan Fatih’i

Bizlere küs olan Ayasofya’nın kapılarını

Eski heybetin ve ihtişamınla

Üç kıtada dalgalanmış bayrağınla

Bizlere açar mısın ey İstanbul? 

26/Ekim/2003

Malatya', 'Seni anlatmak çok zor, yaşamadıkça Seni yaşamak çok zor, alev alev yanmadıkça Sen ki göklerde yıldız, dünyamıza aysın Yedi yüzyıllık aşkın h...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çelik']::text[], 8.5, '{"poet":"Fırat Çelik","poet_slug":"firat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bekler-misin-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şarkısın Antalya-1', 'bir-sarkisin-antalya-1-mustafa-ceylan-9ttzl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ruhumuzu okşayan,

Sevgileri taşıyan,

Gönüllerde yaşayan

Bir şarkısın Antalya.

Gonca gonca güllerde,

Çiçek çiçek dallarda,

Sana tutkun dillerde

Bir şarkısın Antalya.

Buram buram özlenen,

Sevildikçe nazlanan,

Asırlarca söylenen

Bir şarkısın Antalya.

Aşkınla kalbimizde,

Masmavi Akdeniz’ de,

Her zaman dilimizde

Bir şarkısın Antalya.

Torosların başında,

Damlayan göz yaşında,

Sevenlerin düşünde

Bir şarkısın Antalya.', 'Ruhumuzu okşayan, Sevgileri taşıyan, Gönüllerde yaşayan Bir şarkısın Antalya. Gonca gonca güllerde, Çiçek çiçek dallarda, Sana tutkun diller...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-sarkisin-antalya-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat-ı Mücerred', 'vuslat-i-mucerred-eymen-erdem-akca-al6jy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'VUSLAT-I MÜCERRED

Mücerred hakikatler kalıplara döküldü

Hüsn-ü cemâli aşkın maâni darıldılar

Müteal buûdların çeperleri söküldü

En âdi çırpınışlar Yüceye sarıldılar

İki kavis yan yana geldi zamansız an’da

Mevcûdâtın duası melek sûreti giydi

Özleri aydınlatan o mukaddes mekânda

Hıçkırığı duyulan neydi ah bilmem neydi

Kurbiyyetle bu''diyyet iç içe yaşıyorlar

Sükûtun kollarında haykırışın gözyaşı

Adâvet ve muhabbet hak yükü taşıyorlar

Bir âlem ki esâsı zıddiyetler savaşı

Kırılır mana gibi prizmalarda ışık

Kolları yana düşen yeisin sonu yakın

Hakikatler, perişan yalanlarla bulaşık

Ölüm sancıları bu can veren iftirakın

Fırtınalar sükûnu müjdeler..iyi dinle! 

Rahmetin ebeveyni zahmet ile sabırdır

Kâinatı yeşerten sevgin esirdir...inle! 

Bir mazlûmun duası Arş''tan bile ağırdır

Ağlıyorken esâret gülleri bahçelerde

Dağlanır âsumânın gözyaşı köleleri

Titrenerek okunan isyandır hecelerde

Biter mi mânâların asırlık çileleri

Hakîkatü''l-Hakàik! Nusretini yar eyle

Sübûtu arzulayan mümkinâta imdâd et

Ebediyyet yurdunu bizlere diyar eyle

Bir daha bir kez daha vuslatını vaad et', 'VUSLAT-I MÜCERRED Mücerred hakikatler kalıplara döküldü Hüsn-ü cemâli aşkın maâni darıldılar Müteal buûdların çeperleri söküldü En âdi çırpı...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/vuslat-i-mucerred-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşalım Antalya'' da', 'bulusalim-antalya-da-mustafa-ceylan-z2i18', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdiceğim, iki gözüm

Buluşalım Antalya’ da.

Ağlamasın, gülsün yüzün

Buluşalım Antalya’ da.

Dinsin artık göz yaşımız,

Bahara dönsün kışımız,

Çiçek çiçek, yıldız yıldız

Buluşalım Antalya’ da.

Zaman geçmeden haydi! 

Ömür bitmeden gayri,

Yeşil yeşil, mavi mavi

Buluşalım Antalya’ da.

Tut elimden can çiçeğim,

Tut bir tanem, tut meleğim! 

İki gözüm, sevdiceğim

Buluşalım Antalya’ da.

Dolunayı seyredelim,

Sarılalım, dans edelim.

Haydi canım, gel gidelim! 

Buluşalım Antalya’ da.', 'Sevdiceğim, iki gözüm Buluşalım Antalya’ da. Ağlamasın, gülsün yüzün Buluşalım Antalya’ da. Dinsin artık göz yaşımız, Bahara dönsün kışımız,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bulusalim-antalya-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kütür Kütür Can Eriği Sevdiğim', 'kutur-kutur-can-erigi-sevdigim-mustafa-ceylan-ot5sr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kütür kütür can eriği sevdiğim

Bayram yapar ağızımda dişlerim.

Yeni doğmuş ay parçası gözümde

Görmesem de onu böyle düşlerim.

İncecikten fidan biter özümde,

Yağmur yüklü bulut yatar özümde,

Gerdan kırar, göbek atar özümde,

Şıkır şıkır oynar, oynar hoş’ larım.

Yeni dünyam, şeker parem, kirazım

Ak topuklum, gelinlikten beyazım.

Dilimdeki ezel-ebed niyazım

Eksilmiyor gözlerimden yaşlarım.

Hem ağlattın, hem oynattın Ceylan’ ı,

Deli deli hep söylettin Ceylan’ ı.

İnim inim sen inlettin Ceylan’ ı,

Gitmez oldu yüreğimden kışlarım.', 'Kütür kütür can eriği sevdiğim Bayram yapar ağızımda dişlerim. Yeni doğmuş ay parçası gözümde Görmesem de onu böyle düşlerim. İncecikten fid...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kutur-kutur-can-erigi-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ravza-yı Fuadiye', 'ravza-yi-fuadiye-eymen-erdem-akca-b42zt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tayr-ı hümayun-u aşk gönlünde tayrân etsin

Eşk-i bârın saçılsın sadefler seyrân etsin

Sükût-u yâr-ı Kadîm çekse yüz bin hicâbın

Savtının tecellisi uşşâkı  hayrân etsin

Kurbun ateş-i sûzan, bu''dun cehennem-misal

İhtirak dü ahvalde şu gönlü virân etsin

Ey sahipler velisi, ey garipler celîsi

Sermedî tebessümün canları canan etsin

Hakikat-i künh-ü Hakk fiil-i aşk-ı mahzdır

O müstesna kurbetin gurbeti vatan etsin

Bîhemta kelâm-ı yâr şol fuad-ı mecrûhu

Mest ü mahmûrluk içre canlara sultan etsin

Pervâne-yi cünûnum, her hâlim cinnet kokar

Semâzen-i Hakk olan meşk ile cevlân etsin

Kalem-i dervişânî çizsem sutûr-u dehri

Âhımın eyvahından baharı hazan etsin

Müştekîyim ânımdan, cinânî saadetten

Gaflet-i cürm ü isyan sekrimi mîzan etsin

Ne meş''um bir devirdir zulmânî çehresiyle

Ufkumu karartıyor... zehrini kurban etsin

Samedânî  o kalbler fütûhlara gebedir

Kahhâr-ı Zülcelâl''im şükrümü kervan etsin

Sonsuz ufuklar bana yol olsun perde perde

Ferdâniyet kokulu zamanı giryân etsin

Kesret soluklarıyla boğulan vahdet gülü

Gül-ü gülşen-i tevhid içre seyelan etsin

Dökülsün zulm-u zulmet, bitsin kürbet-i ahzân

Her şey bulsun Herşey''i, iftirâk-ı can etsin', 'Tayr-ı hümayun-u aşk gönlünde tayrân etsin Eşk-i bârın saçılsın sadefler seyrân etsin Sükût-u yâr-ı Kadîm çekse yüz bin hicâbın Savtının tec...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ravza-yi-fuadiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-eymen-erdem-akca-2x85z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dile gelirdi taşlar avucunun içinde

Canlanırdı sesinle toprağa dönen kızlar

Gül kokusuyla süslü o simsiyah saçında

Halid''in yüreciği helecanlarla sızlar

Seni arardı gözler hangi meclise girsen

Sevginle divaneydi Hubeyb, darağacında

Herkes sana uyardı... Ay''a bir bölün dersen

Görünürdü dağların o kudsi yamacında', 'Dile gelirdi taşlar avucunun içinde Canlanırdı sesinle toprağa dönen kızlar Gül kokusuyla süslü o simsiyah saçında Halid''in yüreciği helecan...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgili-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yayla Güzeli', 'yayla-guzeli-mustafa-ceylan-f19z8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Sayın M. ERTAŞ’ a...

Meydana toplanmış Barçın Yaylası,

Bir güzel seçmiş ki başlar belâsı...

Dedim kulağına “Benim olası! ”

Tirim tirim titrer, yayla güzeli.

“Gök öncek” belinden dize uzanmış,

Şal kuşağı yedi renkle bezenmiş,

Mevlâ boş vaktinde tutmuş özenmiş

Güldür katmer katmer, yayla güzeli.

Boncukla süslenmiş saçı taralı,

Zümrüt gerdanında takı sıralı...

Çil keklik... Pınara vardı varalı

Çakıllardan çirper, yayla güzeli.

Dudak al-kırmızı, inciden dişi,

Yüce dağ başında ay olmuş kaşı.

Ala-şafakların sevdalı kuşu,

Yârine göz kırpar, yayla güzeli.

Eller gümüş çubuk, kollar bilezik,

Beli, boynu ince, o kadar nazik.

Ateş içindeyken bana der: “Yazık! ”

Bir serinlik serper, yayla güzeli.

Fısıldar gönlünü “sır ebesi” ne,

Çiğdemlerin sesi sinmiş sesine,

Menekşeyle kekik onun nesine? 

Türüm türüm tüter, yayla güzeli.

Yaylalar içinde Barçın Yaylası,

Karac’oğlan yapar, beni böylesi.

Yaz-bahar ayında, Cuma öğlesi

Ceylan’a gülümser, yayla güzeli.', '-Sayın M. ERTAŞ’ a... Meydana toplanmış Barçın Yaylası, Bir güzel seçmiş ki başlar belâsı... Dedim kulağına “Benim olası! ” Tirim tirim titr...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yayla-guzeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-mustafa-ceylan-whcpl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Feryâdımı duyacak da

Gelecektir biliyorum.

En sonunda bu kucakta

Ölecektir biliyorum.

Özlemişim her yanını,

Gülüşünü, havasını...

Kaybettiği Ceylan’ını

Bulacaktır biliyorum.

Çatlamakta sabır taşı,

Gözlerimin akar yaşı.

Beni, ömür boyu eşi

Bilecektir biliyorum.

Hasret kaldım şimdi ona,

Geziyorum yana yana...

Çıkıp aşkın doruğuna

Gülecektir biliyorum.

Hayatım, varlığım, canım

Sevda bağım, aşk bostanım...

Bu gidişle mutlak benim

Olacaktır biliyorum.', 'Feryâdımı duyacak da Gelecektir biliyorum. En sonunda bu kucakta Ölecektir biliyorum. Özlemişim her yanını, Gülüşünü, havasını... Kaybettiği...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biliyorum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgem', 'golgem-mustafa-ceylan-5i85h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ömür peşimde gezinip durdun,

Yorulmadın kara gölgem nedense? 

Yollarda başını taşlara vurdun

Acıdım haline dinle be gölgem.

Ben büyüdüm, sense her gün kısaldın,

Ayaklar altında, yerlerde kaldın.

Bana bağlanmakla belayı buldun,

Yan gelip yatmadın şöyle be gölgem.

Düştüm zindanlara beni bekledin,

İlerledi yaşım, sen de tekledin...

Gizli sırlarımı tutup sakladın,

Yârimin gezdiği köyde be gölgem.

Bazen önümdesin, bazen arkamda

Yıkıldım... Yıkıldın, her bir adımda.

Ne buldun bilemem, sen bu adamda? 

Senle yaşıyorum, senle be gölgem.', 'Bir ömür peşimde gezinip durdun, Yorulmadın kara gölgem nedense?  Yollarda başını taşlara vurdun Acıdım haline dinle be gölgem. Ben büyüdüm,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/golgem-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sen', 'yine-sen-safure-yildirim-16l7t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana yazdım bu şiiri

oku lütfen! 

gecenin bu saati 

yine sen.

günü bitirdim 

senle gezinirken,

gecenin bu saati

yine sen,

kitap aldım elime

açtım durdum sayfalarını

ukuyamadım

senin yüzünden,

gecenin bu saati 

yine sen.

ışığı kapatsam,

yatağıma yatsam,

uyuyabilir miyim

hayalin karşımdayken? 

gece de bitti

yine sen! ..

05.04.04  İlkim', 'sana yazdım bu şiiri oku lütfen!  gecenin bu saati  yine sen. günü bitirdim  senle gezinirken, gecenin bu saati yine sen, kitap aldım elime ...', ARRAY['Türk Edebiyatı','Şiir','Safure Yıldırım']::text[], 8.5, '{"poet":"Safure Yıldırım","poet_slug":"safure-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yine-sen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustağrak', 'mustagrak-eymen-erdem-akca-g7ife', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mustağrak-ı aşkınım... yandım yandım kavruldum

Mutantan  sevdalarla yaprak gibi savruldum

İncizaplar içinde terk eyledim dünyayı

Müzeyyen hayallerle süslemiştim hülyayı

Şerha şerha gönlümü yardım yardım kanattım

Münkesir ahvalimle çırpınan bir kanattım

Acube-i hilkatim ruhum bedenden acib

Müstetir zamanlarda akl u hayalim gaib

Süveyda-i kalbimden damla damla kan sızar

Azrail defterinde ismim şakîden yazar

Şekavet-i uhrevi beni derdest eyleyen

Sahk u mahkla hark edip şevklerle mest eyleyen

Çarh-ı felekle dönen garip pervaneyim ben

Sürur-u keder ile nalan viraneyim ben

Sezadır garip cana yana yakıla dönmek

Bir lamiin nuruyla ebedlere dek sönmek

Şerareler savuran haristanın gülü sen

Gül kokulu sabanın susmayan bülbülü ben

Talattufla sürmeli gözlerimde son sabah

Müsenna anlarımdan başlar büyük intibah

Şavkı yansır ahımın mücella çehrelerde

Bir münevvir nur saçar müessif katrelerde

Şuh bir nazar yükselir semavattan yerlere

Nur akar oluk oluk inleyen seherlere

Mualla hissiyata kayıt vuran geceler

Muğterib isyanlara kılıç çalan heceler

Tenahiler karışır namütenahilere

Mülevves mesaibden kurtuluşu kim vere

Tur-u Sina kan ağlar, bağrından ırmak akar

Günahkar bedenleri ancak temizler sekar

Müşteki günlerimin geceleri mübeyyaz

Süeda güruhuna ilhak eyle ey Feyyaz

Sürur-u layezali vicdanları kuşatan

Saadet-i ebedi ruhu baki yaşatan

Serzenişim yol açar maveraya veradan

Kulub huruç eylemez manevi sur seradan

Sahabet-i Nebevi(ASM)     can evimden aks eden

Müptela bir ruhum var tecellinle raks eden

Müjde sunar geceler anlamsız hecelere

Muammalar karışır en zor bilmecelere

Mukaddes zamanlardan sonsuzluğa uzanan

Bir muktehir hayalin vuslatlarıyla yanan

Müteellim çehreme seherde aks edendir

Izdırabımla yanan sürurla raks edendir

Müntesibim gececi ruhbanlar güruhuna

Hayranım ol mukaddes Ruhların gül ruhuna

Susamış toprak gibi vuslatını anarım

Suziş-i nağmelerde yüreğimle yanarım

Kulub-u müftehire sana mübtela-meftun

Muarra isyanlarda sevdan eyler tavattun

Mücezzi arzularla uşşakın parça parça

Mutahhar hayalinle kalbler gümüşten sırça

İftirakınla yanan kalblerde en son sabah

Gel ne olur sevgili kalbte başlasın tebah

Müntebih gönüllerin özlenen mahbubu sen

Muzlim leyl ü neharın nurun ala nuru sen', 'Mustağrak-ı aşkınım... yandım yandım kavruldum Mutantan  sevdalarla yaprak gibi savruldum İncizaplar içinde terk eyledim dünyayı Müzeyyen ha...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/mustagrak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitecek', 'bitecek-safure-yildirim-iwp8s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben hep bitişlerde konuşurum

yazarım,çizerim,söylerim

son sözümü hep 

çıkarken söylerim,

seni şaşırtacak diyeceğim,

sana da yazmaya başladım...

05.04.04   İlkim', 'ben hep bitişlerde konuşurum yazarım,çizerim,söylerim son sözümü hep  çıkarken söylerim, seni şaşırtacak diyeceğim, sana da yazmaya başladım...', ARRAY['Türk Edebiyatı','Şiir','Safure Yıldırım']::text[], 8.5, '{"poet":"Safure Yıldırım","poet_slug":"safure-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bitecek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğa Açılan Sayfa', 'mutluluga-acilan-sayfa-aysel-sevim-9hqfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapama gözlerini, aç  beni dinle.

Anla neler hissettiğimi

Sensiz kaldığım günden beri

Nefesimi bile zor alıp verdiğimi

Anla sevgilim

Yaşamın en güzel yüzünü

Sevginin süslediğini.

Bırak boş düşünceleri

Çırpınma uçurumlarda, tut ellerimi

Kurtar kendini.

Aşkla arındır karanlık düşüncelerle 

Kovduğun düşlerini.

Sen de yaşa bir kere

Hayatın güzelliklerini

Koşma umutsuzluk peşinden

Sömürme duygularını

Korkulu kuşkularla

Bölme rüyalarını

Hiçbir zaman karamsar olma

Her şeyi iyiye yorumla

Bu hayat böyle arkadaş

Bu dünya böyle.

Sen ağladıkça, o daha çok ağırlaşır

Umursama gül geç acılara

O zaman kazanan sen olursun.

Mutlu olmak kolay aslında.

Bizler kendi kendimizin kurbanı olmadıkça.

Mutluluk asla geçmez kapıdan

Unut derdi tasayı

Değiştir artık bu yasayı

Bizler süsleyelim

Mutluluklara açılan sayfayı.', 'Kapama gözlerini, aç  beni dinle. Anla neler hissettiğimi Sensiz kaldığım günden beri Nefesimi bile zor alıp verdiğimi Anla sevgilim Yaşamın...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/mutluluga-acilan-sayfa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahretsin Unutamıyorum', 'kahretsin-unutamiyorum-aysel-sevim-v47w9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun zaman oldu

Seninle görüşmeyeli

Meğer nasıl özlemişim

Senle o güzel günleri

Yüreğimi parçaladın

Kalbim aşk için çarpıyor

Binlerce teklif alsam da

Gönlüm illa seni istiyor.

Karla örtülü etrafım

Bahara ulaşamıyorum

Gelmeni bekliyor kapım

Kahretsin unutamıyorum.

Bir bahane bul n’olur

Bir kez gel kollarıma

Istırabım son bulsun

Bakıyorum yollarına

Bir kez olsun güven bana

Sana hasret gitmeyeyim

Tenim ecel kucağında

Senin olup da öleyim.', 'Uzun zaman oldu Seninle görüşmeyeli Meğer nasıl özlemişim Senle o güzel günleri Yüreğimi parçaladın Kalbim aşk için çarpıyor Binlerce teklif...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kahretsin-unutamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Geldin Diye', 'sen-geldin-diye-aysel-sevim-0di03', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün kapım çalındı

Açtım sen geldin diye.

Etrafa gülücükler

Saçtım sen geldin diye.

Açtı gül demetleri

Esti sevda yelleri

Sevdiğin yemekleri

Yaptım sen geldin diye.

Bir anda kalbim durdu

Acılarım son buldu

Gönlüm sanki kuş oldu

Uçtum sen geldin diye.

Açtın kalbimde yara

Beni düşürdün zara

Sevinçle bir sigara

Yaktım sen geldin diye.

Bir yabancıymış gelen

Tıpkı sana benzeyen

Ve bir daha peşinden

Gittim sen geldin diye.', 'Bu gün kapım çalındı Açtım sen geldin diye. Etrafa gülücükler Saçtım sen geldin diye. Açtı gül demetleri Esti sevda yelleri Sevdiğin yemekle...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-geldin-diye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Kapıldım', 'gozlerine-kapildim-aysel-sevim-feoo2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sessiz bir denizin hırçın sularına 

Kapılır gibi... 

Bir Nisan yağmurunun okşayışıyla

Islanır gibi,

Sonsuz seraplara götürdü beni

Siyah gözlerine kapılıp gittim.

O mahzun bakışların çıkmıyor

Çıkmıyor aklımdan hiç.

O saf duygularında başka bir içtenlik var.

Herkesten daha farklı yaratılmışsın sanki...

Bitmesini istemediğim tatlı bir rüya gibi

Siyah gözlerine kapılıp gittim.

Al beni ne olur bu karmaşanın içinden

Kurtar beni bu aşkın ıstırabını çekmekten.

Ben bir an vazgeçmedim inan 

Seni sevmekten.

Gel ne olur sevgilim

Her zaman benimle ol, asla ayrılma benden.

Sen okşa saçlarımı,ben dizinde uyurken.

Sen öp dudaklarımı boynuna sarılırken.

Seninim ben sevgilim

Al götür artık beni

Hayallerin içinde kaybolup gittim.', 'Sessiz bir denizin hırçın sularına  Kapılır gibi...  Bir Nisan yağmurunun okşayışıyla Islanır gibi, Sonsuz seraplara götürdü beni Siyah gözl...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozlerine-kapildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşabilir misin Hayallerimle?', 'konusabilir-misin-hayallerimle-aysel-sevim-qrhyq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bağırsam ardın sıra, bir haykırsam,

Duyabilir miydin çığlıklarımı

Hissedebilir miydin duygularımı

Konuşabilir miydin hayallerimle

Tutabilir miydin düşlerimi ellerinle

Kucaklayabilir miydin beni

Büsbütün benliğinle.

Sarabilir miydin yaralarımı

Yan etkisiz bir merhemle.

Susturabilir miydin göz yaşlarımı

Yılların ardında kalan

Sımsıcak gülüşünle.

Dindirebilir miydin kalp sancılarımı

İlham veren sözlerinle.

Yatıştırabilir miydin korkularımı

Reçetesiz bir teselli ile.

Sevebilir miydin beni sorgusuz, sualsiz.

Görebilir miydin baktığın her yerde.

Ben kendimi sana adadım sevgilim. 

Hayatım senin ellerinde,

Kararı sen vereceksin. 

Ya beni ilk hamlede öldüreceksin

Yada hiç vakit kaybetmeden,yanıma geleceksin.

Bu aşkın kaderini kendin çizeceksin.', 'Bir bağırsam ardın sıra, bir haykırsam, Duyabilir miydin çığlıklarımı Hissedebilir miydin duygularımı Konuşabilir miydin hayallerimle Tutabi...', ARRAY['Türk Edebiyatı','Şiir','Aysel Sevim']::text[], 8.5, '{"poet":"Aysel Sevim","poet_slug":"aysel-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/konusabilir-misin-hayallerimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekletme', 'bekletme-i-brahim-ethem-bingul-e5j0c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiirlerin mana denizinde

Gözlerindi kılavuz

Anlaman için sevgili

Sevgini kazanmış yüreğim

Gözlerini çalmış gözlerim

Öyle diyor yedinci hissim

Ben seni seninle çözdüm

Anladığını da biliyorum

Bekletme kendini,seni bekliyorum', 'Şiirlerin mana denizinde Gözlerindi kılavuz Anlaman için sevgili Sevgini kazanmış yüreğim Gözlerini çalmış gözlerim Öyle diyor yedinci hissi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bekletme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dermanım yok', 'dermanim-yok-zafer-zengin-etnika-nya6i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç

Dermanım

Yok

Bugün

Sessiz 

Kalsam

Nefes

Bile

Almasam

Hiç

Dermanım

Yok

Bugün

Sen sevsen beni..yüzümü örtmesem..izlesem seni...

Yakma 

Saçlarımı

Niyetinle

Oyala

Hiç dermanım yok.. Dokunsana...Uyutsana

Mümkünü

Varsa

Ninni okusana..adamına...

6 Nisan 2004 '' İçimin Kitabı ''', 'Hiç Dermanım Yok Bugün Sessiz  Kalsam Nefes Bile Almasam Hiç Dermanım Yok Bugün Sen sevsen beni..yüzümü örtmesem..izlesem seni... Yakma  Saç...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dermanim-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Incitmesinler Gülü', 'incitmesinler-gulu-sedef-unal-9xpe6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yanım gizlenmiş sükunet 

Diğer bir yanım körpe senliklerde 

Geçici heveslere serzeniş dolu gönlümce 

Gizlenirim kelimelerin gizemine 

Hor gördüğüm dikenler bekçi olsa da güle 

İncitirler gülü günaha renk veren ışıklar

Hangi kelime onu anlatmaya yeter ki? 

Renkli bir yelpazenin açılışı gibi

Bir ”ZUHAL YILDIZI’NIN” görkemini

Yüreğime işledin NUR ve AY desenli bahar libasını

Bir şiire sığdırmak istiyorum, 

Elimde kalan bir avuç sessizliğimi...

05.04.2004 

PS: Sevgili Nuray Alper İthaf Edilmiştir;', 'Bir yanım gizlenmiş sükunet  Diğer bir yanım körpe senliklerde  Geçici heveslere serzeniş dolu gönlümce  Gizlenirim kelimelerin gizemine  Ho...', ARRAY['Türk Edebiyatı','Şiir','Sedef Ünal']::text[], 8.5, '{"poet":"Sedef Ünal","poet_slug":"sedef-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/incitmesinler-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batımı', 'gun-batimi-sair-aeris-9oe1s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatımız tıpkı bir gün batımı.

Güzeldir dışarıdan bakınca,

Sıkar bizi içinde olunca,

Yaşıyoruz onu galiba amaçsızca,

Hayatımız tıpkı bir gün batımı.

Hayallerimiz ve amaçlarımız,

Tek bir anda yaşayabiliriz,

Asla gerçekleştiremeyebiliriz.

Hayatımız tıpkı bir gün batımı.

Sıkıca tutursan bir ucundan,

İstesen de bırakamıyorsun,

Başlarsan bir kez, mutlaka bitiriyorsun.', 'Hayatımız tıpkı bir gün batımı. Güzeldir dışarıdan bakınca, Sıkar bizi içinde olunca, Yaşıyoruz onu galiba amaçsızca, Hayatımız tıpkı bir gü...', ARRAY['Türk Edebiyatı','Şiir','Şair Aeris']::text[], 8.5, '{"poet":"Şair Aeris","poet_slug":"sair-aeris","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gun-batimi-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biline', 'biline-mehmet-ali-kalkan-a7m5m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİLİNE 

        Karaya beyaz denilmez,                   

                  Doğrudan geri dönülmez                    

Yiğit kendine yenilmez,

Biline...

Rüzgar yoksa yaprak esmez,

Dost,dost ise dosta küsmez,

Bıçak ki kınını kesmez,

Biline...

Görklü ağacın dalıdır,

Kimi boş, kimi doludur,

İnsan, ihsanın kuludur,

Biline...

Oklar hedefsiz atılmaz,

Yaydan çıkan ok tutulmaz,

Kılıç ile at satılmaz,

Biline...

Boş laf ile öğüt olmaz,

Toy gününde ağıt olmaz,

Yarası yok yiğit olmaz,

Biline...

Söz odur ki sırra döner,

Sır odur ki sura döner,

Sır gâhi kusura döner,

Biline...

Sen küçüksen dünya büyük,

Sen büyüksen dünya küçük,

Görebilsen yollar açık,

Biline...

Kan,kanla yunmaz denilir,

Affedenler affedilir,

Bilgi bilmezler yenilir,

Biline...

Oğuz’da yer yaygı olur,

Er de sıra saygı olur,

Saygı yoksa kaygı olur,

Biline...

Kar yağanda yaza kalmaz,

Gökçe çimen güze kalmaz,

Dünya denen bize kalmaz,

Biline...

Erlik mayada,süttedir,

Yapacağı niyettedir,

Kayı boyu nöbettedir,

Biline...', 'BİLİNE          Karaya beyaz denilmez,                                      Doğrudan geri dönülmez                     Yiğit kendine yenilme...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/biline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Anlamı', 'hayatin-anlami-ahmet-aksoy-zls3s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ay yadsırken gökteki yerini

.................sürdürülemez mutluluk

çalıntı akşamlar çalarken sessizliği

................dinlenemez us

kimbilir belki de bu şiirde gizli

..................hayatın anlamı', 'ay yadsırken gökteki yerini .................sürdürülemez mutluluk çalıntı akşamlar çalarken sessizliği ................dinlenemez us kimbil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hayatin-anlami-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğreneceksin', 'ogreneceksin-i-brahim-ethem-bingul-1t5ye', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sevda kelimesinde

Buldum ben seni

Değildi sevdam kelimeye

Sevdalanmıştım söyleyene

Aşkım sana gebe

Sevdam bana kaderimce

Sen sevgime nakkaşe

Kalbim sana açık beklemede

Bilirsin de bilmezsin

Belkide korkarsın

Tutturuculuğun,bir de inadın

Söyletmiyor sana müdanasızlığın

Öğreneceksin dilaram

Bensiz yaşayamıyacağını

Marifet mi sandın susmayı

Öğreneceksin koru elinde yaşatmayı

     nakkaşe:nakış yapan kadın

     dilara:gönül sürükleyicisi', 'Bir sevda kelimesinde Buldum ben seni Değildi sevdam kelimeye Sevdalanmıştım söyleyene Aşkım sana gebe Sevdam bana kaderimce Sen sevgime nak...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ogreneceksin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ALIP GÖTÜRÜYOR BENi...!', 'alip-goturuyor-beni-baki-son-bo3cz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnce

Altın bir yay gibi

.........................Ay,

Yaklaşan kara gecenin içine

Dost gibi

Uzattı ellerini.

Bir kaç kara bulut

............................Silindi.

Sustuğum

Oturup kaldığım

Yalnızlığın içinde

Ümit gibi birşeyler

............................Kımıldadı.

Koşup geldi...

Önce gözlerin,

Sonra dudakların,

Ellerin,senin ellerin...

Avuçlarımda.

Ve sesin...

.............Sımsıcak

Sarıldı benliğime.

Şimdi; 

Senin o çocuksu gülüşünde

Bir rüzgar,

Alıp götürüyor beni

............................Sevinçlere.

Korkırmızı

..............Dudaklarında bir öpücük

Alıp götürüyor beni

Unutulmuş mutluluklara.

Gözlerin,

Bir ışık gibi 

Umut...dolu

Sesin,

Ilık bir rüzgar gibi

Huzur...veriyor

Ve saçların

İçimde ürpertiyor,

............................Tüm sevgileri.! 

Sonra; 

Alıp götürüyor beni ellerin,

Beyaz bir bulut gibi

Işıktan ve umuttan

............................Diyarlara.!', 'İnce Altın bir yay gibi .........................Ay, Yaklaşan kara gecenin içine Dost gibi Uzattı ellerini. Bir kaç kara bulut ................', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/alip-goturuyor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle ögrendim', 'senle-ogrendim-selvi-celik-qvyj9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizligin çaresizligi olmadigini,

Ayriliklarin hakli yüzünü,

Yalan umutlarin varligini,

Senle ögrendim, senle yasadim.

Zamanla gözyaslariyin alevini,

Yanaginda fersiz kurudugunda,

Artik son nokta gibi,kaldiysan cümlenin ardinda.

Bitisin kral hissi verdigini,

Senle ögrendim,senle yasadim.

Bosa savrulmus vaatlerin,

Bir yalanci bahar gibi geçtigini,

Senle ögrendim,senle yasadim.

Kirilmis onurun tamiri olmadigi gibi

 dönülmüs yola devam edemessin.

Yollar irak,amac uzak gelir.

Íste bunlari yorulmadan,

Senle ögrendim senle yasadim.

Unutmaki zaman birgün duracak.

Bahaneler son noktasini bulacak.

Hep arayislar karmasiga düsecek.

Yani akilli olmayi,

Senle ögrendim,senle yasadim....', 'Sensizligin çaresizligi olmadigini, Ayriliklarin hakli yüzünü, Yalan umutlarin varligini, Senle ögrendim, senle yasadim. Zamanla gözyaslariy...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senle-ogrendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir, Bir Destan ve Bir Hayat', 'bir-siir-bir-destan-ve-bir-hayat-melih-coskun-en7o5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir destan,

Eski zamanlardan, 

Kahramanları hiç yaşamadılar 

Hiç görmediler 

Nasıl parladığını güneşin 

Sevmediler ölesiye

Ve ölmediler beyaz yorganlar altında... 

Bir şiir, 

Son dizeleri ölmekte olan bir ozanın 

Kanadı kanlar içindeki bir kuşun 

Son kez kanat çırpışı gökyüzüne 

Ve son satır:

Ölüm öldürmez ki şairi

Her sesin yankısı vardır elbet

Bir hayat, 

Günden güne su alan bir gemi

Tüm kahramanları hain ilan edilir 

Ve hainleri kahraman 

Zaman ihanetten yana çevirmiştir yüzünü 

Bu sebeptendir ki zaman 

Elleriyle kapatır yüzünü 

Bu şiir hayatın kıyısında yaşanan bir destandır 

Herkes içindedir biraz 

Ve biraz dışında 

Görmek isteyen görür çünkü yalnızca 

Nasıl parladığını güneşin 

Ölüm öldürmez şairi

Her sesin yankısı vardır elbet...', 'Bir destan, Eski zamanlardan,  Kahramanları hiç yaşamadılar  Hiç görmediler  Nasıl parladığını güneşin  Sevmediler ölesiye Ve ölmediler beya...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-siir-bir-destan-ve-bir-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül', 'kul-atila-gunal-bmv96', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kor bir ateş gibi düştün bağrıma

İçimi ısıtır 

Buzlarını eritirsin sanmıştım yalnızlığımın

Öyle bir yangın çıktı ki yüreğimde

Üfleyecek kül bırakmadın bir avuç

06-04-2004', 'Kor bir ateş gibi düştün bağrıma İçimi ısıtır  Buzlarını eritirsin sanmıştım yalnızlığımın Öyle bir yangın çıktı ki yüreğimde Üfleyecek kül ...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kul-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben sana köylü kokumla gelmiştim', 'ben-sana-koylu-kokumla-gelmistim-ayten-ozlem-yesilcali-lyw5e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sana köylü kokumla gelmiştim.

Ben seni daglarımın yamacıyla sevmiştim.

Bırakıp gitmeyi,terk etmemeyi ögrendim.

Köyümün kokusuyla..

Sen kültürlü,büyük mektepler bitirmiş insansın,

hayllerin büyük,hayatın büyük.

güzel ve süslü sözler duymak istiyorsun; 

sana yaldızlı ve parlak yalanlar söylemelidim.

seni yitirmemek için..

Seni kaybetmemek için geşmiçimi gizlemeliydim....

Duymak istediklerini konuşmamalıydım.

Yüreginde istedigin süslü insanı oynamamlıydım sana

Kendimi degil..

Sen serçe sevmek istedin.

Oysa ben kartaldım,kartalla yaşadım.

Ama serçeyi oynamalıydım sana,

Seni kaybetmemek için..

Sen yüregindeki süslüden nefret ettin.

Serçeden nefret ettin..

Kartalı hiç tanımadınkiiiiiiiii

Heyacan derim sana hep tarifini.........

İsmini duyunca hep kalbimdeki çırpıntı.

Hüznün tarifini sen yapmıyorsun.

Ben sana yapayım.

Yanımda olmayıpta,gözlerimde  bıraktıgın hayal.

Ben hüznü..

Akrabasının elbisesini bayramlık diye giyen; 

Aynadaki kendi yüzümde gözlerimde gördüm.

Ben bunları sana anlatamazdım.

kaç gecedir seni köyümü annemi görüyorum rüyamda.

Hattayken beni hiç yanlız bırakmayan annamıı

Şimdi sen istersen ya serçeyi sev....

yada kartalıı..

kartalı seveceksen; 

Önce köyümün kokusunu,daglarımı baglarımı sev.....', 'Ben sana köylü kokumla gelmiştim. Ben seni daglarımın yamacıyla sevmiştim. Bırakıp gitmeyi,terk etmemeyi ögrendim. Köyümün kokusuyla.. Sen k...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ben-sana-koylu-kokumla-gelmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne fayda!', 'ne-fayda-zafer-zengin-etnika-rtnvk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzün düştü

Ellerin ellerime

Bitmedi hüznüm

Görmedi kimse

Bahar gelmiş 

Ne fayda...

Ömre darı ekiyor yalnızlık

Sen türkülerini söyle

İçine hasret kat 

Memleket mesela

Zorluk birazda

Beni öyle anla

İşte bu yüzden

Sana yaklaştıkça

Kaçma...

Sır olma...

Uzaktan bakışına sakladım gönlümü

Sevda gelir gençliğinle

Gel saçı ışıklım

İçimde gülümse

Hüzün bitsin seherde...

Çıkıp gelsem yanına

Kafam uyusur mu! 

Bilmediğim sorular sorarmısın diye merak ederim

Sorgularmısın beni! 

Dünyayı çözdüğüme dair sorularınla...

Bilirim! 

Sen kadar acemiyim aslında

Aşk ustalık dinlemiyor

Çiğneyip geçiyor...

Kulunçlarında 

Bahar patlıyor yüreğimizin

Ahh sevda..vah sevda

Bizi iri gözlerinle hırpala

Çocuktur deyip acıma

Sok koynumuza ateşini

Dağla... dağla...

Çıkmayalım sabaha....

Ağlamışız ne fayda...

6 Nisan 2004', 'Güzün düştü Ellerin ellerime Bitmedi hüznüm Görmedi kimse Bahar gelmiş  Ne fayda... Ömre darı ekiyor yalnızlık Sen türkülerini söyle İçine h...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ne-fayda-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlı', 'delikanli-ayten-ozlem-yesilcali-5z27g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni ne kadar sevdiğimi bilemeyecek kadar aptalsan,

Sen zaten ben de ölüsün.

Senin için çırpındığımı,anlamayacak kadar zavallıysan,

Sen benim için zaten ölmüşsün.

Benim için belki uzakta kalmış sevdigimsin.

Ama hiç alınma bende insanım..

İlk benim olman dın 

Ama sende çok körkütüktün...

Seni ne ne de çok sevdigmi bilirdin..

Senin için ömrümü verirdim.

Ama her dafa beni sabırla avuttun.

Sabır edecek halim kalmadı sende bilirsin

Çaglayan misaliydim sana ama sende kördün..

Beni artık suçlama...

Sevmek seninle olmak benimde düşündügüm dün..

Ama  maalesef dönülmez yollara soktun sevgimi

Çırpınmam aglamam boş muş boş oldugunu gördüm..

Ne yaptısam çabam boşmuş.

Ama bu kadarda hafife alma  delkanlım..', 'Seni ne kadar sevdiğimi bilemeyecek kadar aptalsan, Sen zaten ben de ölüsün. Senin için çırpındığımı,anlamayacak kadar zavallıysan, Sen beni...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/delikanli-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamazingo! ! ! !', 'zamazingo-mustafa-ceylan-egvpo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ZAMAZİNGO

Ne faiz fazlam var, ne kayıt dışım

Vallahi birdir içimle dışım! ..

Şu son hükümetin bütçesi olamadım; 

Bekle beni, dediğim yerde, olur mu “dingo”? ! 

Zamazingo! ... Zamazingo! ...

Ne borsadan kaptım, ne birini çarptım

Zeytin, peyniri bile zor buldum inan…

Vurmaz benim gibi adama, ne loto, ne piyango! 

Ne olur ne olmaz, sen beni bekle orada,

Zamazingo! ... Zamazingo! ...

Haram yemedim, yalan demedim

Hep emeğimdir alnımdaki terim…

Kara para aklayanlar akrabam değil; 

At boynunda at yarışı, kramponda toto; 

Ne olur ne olmaz, sen beni bekle olur mu? 

Zamazingo! ... Zamazingo! ...

Dibine vurduğum Dünya bu, belli olmaz

Ya Hoca’ nın gölü maya tutar, eşeği anırırsa? 

Biliyorum ardımdan en çok ağlayacak sensin

“Yiyemedim, diyemedim” diyerek…

Hiç kimse dökmeyecek gözyaşını senin kadar,

Sonra gidip oynayacaksın, benim için de “bingo”

Zamazingo! ... Zamazingo! ...

Haram ne, günah ne, herhal seninle olduğum? ! 

Başka bir şey bilmiyorum ki ben! 

Sen üzüm çaldığım bağ, kuş vurduğum dağımsın

Sen ilkten ilk günahımsın, içi dolu bardağımsın

Islığım, ayna tuttuğum yüz, sen, bence helâlimsin

Saçların ıslak ta olsa, başını göğsüme ko! 

Zamazingo! ... Zamazingo! ...

Zambak kadar mor ve mavisin,

Zambak kadar buyurgan.

Mezarlığın kapısında beklerken seni kırmızı oto

Kabrime zambak soğanı dikesin e mi? ! 

Zamazingo! ... Zamazingo! ...

Sorgu sualde önce sen gelmelisin önüme

“Bu kim? ” dediklerinde yıkılmalıyım…

Cehenneme tunçtan bir kapı gerekmiş, duydum; 

Senin yüzünden,

İlk ben çakılmalıyım…

Senin gibi birisini sevdiğim için,

Ve de “adam” sanıp değer verdiğim için,

Cayır cayır yakılmalıyım…

Sonra sen çıkıp meydana, oynamalısın tango; 

Zamazingo! ... Zamazingo! ...', 'ZAMAZİNGO Ne faiz fazlam var, ne kayıt dışım Vallahi birdir içimle dışım! .. Şu son hükümetin bütçesi olamadım;  Bekle beni, dediğim yerde, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/zamazingo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-mustafa-ceylan-ibmh5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gül yaprağı, buz kalıbı akan su

Her kalıba giren tanımdır zaman.

Dayım, param, gücüm, yok ya biliyor

Sanki hafif meşrep hanımdır zaman.

Onu tutamadım kaçtı elimden

Bir baktım kuş olup uçtu elimden

Rüzgârdı, eserek geçti elimden

Resimlerde kalan anımdır zaman.

Şansken başkasında, yokluktu bende

Neyim varsa alıp geçti gidende

Gene de umudu yorgun bedende

Çileyle yoğuran canımdır zaman..

Yüzde derin çizgi, saçlarımda kar

Olduğundan belli, etmemişim kâr.

Koşup durmadayım edemem inkâr

Damarımda akan kanımdır zaman.

Durmadı, devamlı bastı pedala

Takvimi çevirdi kuruyan dala

Sessizce yatırıp tahtadan sala

Bir cami önünde sonumdur zaman.

Ceylan’a verilen en büyük öğüt

El değmez, göz görmez denir ki soyut

Boynuma dolanan üçüncü boyut

Gün doğar, gün batar konumdur zaman.', 'Gül yaprağı, buz kalıbı akan su Her kalıba giren tanımdır zaman. Dayım, param, gücüm, yok ya biliyor Sanki hafif meşrep hanımdır zaman. Onu ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zaman-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim! ! !', 'zalim-mustafa-ceylan-y8lf4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüce dağ başını duman, sis sarmış

Ne dumanı anlar, ne sisi zalim.

Karşımda Moskof’un kalesi zalim

			Sözde yârim,

Baktım ki sırtıma hançer sokarmış…

Yüce dağ başında fırtına, bora

Dost olan sokar mı dostunu zora? 

Döndüm sayenizde susuz pınara

			Böyledir halim

Beni deli-dolu söyletir zalim.

Yüce dağ başında lâpa lâpa kar

Kardelen, kardelen neredesin sen? 

	Sözde yârim, kuru çalım

Tutar da başımı belâya sokar

	Alın yazım mısın, nesin sen?', 'Yüce dağ başını duman, sis sarmış Ne dumanı anlar, ne sisi zalim. Karşımda Moskof’un kalesi zalim 			Sözde yârim, Baktım ki sırtıma hançer s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zalim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaç Yağı', 'zac-yagi-mustafa-ceylan-kn6m3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kader kader derler adına senin

Alnıma yazılmış yazımsın benim.

Elli yıldır buna gülmedin gittin

Yaz- bahar ayında güzümsün benim.

Cümle umutlarım bitti hüsranla

Türkülerim sona erdi hicranla

Bir de bu garibi düşünüp anla

Bakıp da görmeyen gözümsün benim.

Maşallah kapkara giysilerdesin

Al, yeşil olunca acep nerdesin? 

İşim düşse bulunmazsın, sırdasın

İçi ağıt dolu sözümsün benim

Elde fingir fingir oyunlardasın

Her zaman sımsıcak koyunlardasın

Ceylan’ ı görünce bitmiyor dansın

Kel başımda duran sızımsın benim.', 'Kader kader derler adına senin Alnıma yazılmış yazımsın benim. Elli yıldır buna gülmedin gittin Yaz- bahar ayında güzümsün benim. Cümle umut...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zac-yagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Be can!', 'be-can-mustafa-ceylan-vug53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göğü yumruklamak nafile

Suç arama kendinde be can

Alın yazısı böyledir işte

Bir de bakmışsın

Hüznünle yapayalnızsın

Yanlış bir düğmede çatallanır,

Oturur,

Çocuklar gibi ağlarsın...

Zamana kurşun sıkmak nafile

Su misali akacaktır meret, durduramazsın

Nice pehlivanları yenmiş,

Sürüklenmiş içinde nice sultan

Sen de, ben de gideceğiz

Neylersin be can? 

Elinden ne gelir ki

Kadere küsmek veya isyan etmekten başka? 

Beyhude geçen günlere yanarsın,

Unutamadıklarının adını anarsın arada- sırada

Döner akrepleşir, kendini sokarsın

Duramazsın...', 'Göğü yumruklamak nafile Suç arama kendinde be can Alın yazısı böyledir işte Bir de bakmışsın Hüznünle yapayalnızsın Yanlış bir düğmede çatal...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/be-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehirli Dal Çiçeğine', 'zehirli-dal-cicegine-mustafa-ceylan-1d9t4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gördüğüm uşaklar, bugün gökte uçaklar

Dişli çarklar dönüyor, ben nasıl anlatayım? 

Nasıl olsa gövdemden başımı alacaklar

Bırakın da fesimi göklere fırlatayım...

Tezgâhla dümenleri işlek yere kurmuşlar

Kurmuşlar da mübârek için için sarmışlar

Üç senelik bir yola tam üç günde varmışlar

Ayna tutun gözüme aklımı tırlatayım.

Milyarlar, trilyonlar düşmüyor dillerinden

Bir çıkmaz sokaktalar anladım hallerinden

Koklayamam çiçeği zehirli dallarından

Nasıl olur gülümle onları bir tutayım? 

Çileyse benim çilem, böcekse bana korkunç

Varsın büyük dağları kaplasın ayva - turunç

Hiç kimseye yâr olmaz, öfke nefret ve de hınç

Geçmişteki günleri ben nasıl unutayım? 

Çöp bidonları benim, oh ne rahat, ne rahat! 

Olmaz olsun ey dostum, böylesi bir safahat! 

Vardı balın kaymağın, yeme de yanında yat

Bilemem dostum seni ben nasıl avutayım? 

Ceylan’ ımın sözünü gel yabana atma sen! 

Elin parası ile beleş hava satma sen! 

Safi sütün içine çeşme suyu katma sen! 

Suyu safi süt diye ben nasıl okutayım? 

				Eylül-2003', 'Dün gördüğüm uşaklar, bugün gökte uçaklar Dişli çarklar dönüyor, ben nasıl anlatayım?  Nasıl olsa gövdemden başımı alacaklar Bırakın da fesi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zehirli-dal-cicegine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayâl Meyhanesi', 'hay-l-meyhanesi-mustafa-ceylan-hbwww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'HAYAL MEYHANESİ

-I-

Hayâl meyhanesine oturdum bugün

Yeşil şarap istedim sakiden inan

Gözlerimin önüne gözlerin geldi

Daha ne desin Ceylan? ..

Önce şaşırdı saki, yüzüme baktı

“Abi sen tayyaresin” dedi bıraktı

Ruhuma çağıl çağıl ırmaklar aktı

Dedim: Nerdesin Ceylan? 

Öteki masalarda sımsıcak sohbet

Ben mi? Yapayalnızım içimde gurbet

Saki, hani şarabım? Dedi ki: Sabret! 

Nasıl sabretsin Ceylan? 

Duvarda titrek ışık, tıpkı ben gibi

Bir bardak şarap geldi göründü dibi

Hayâl meyhanesi n’apsın garibi? 

Valla hayretsin Ceylan! 

-II-

Mor, mavi, pembe pembe, renkler cümbüşü

Kendimde değilim bak,

Gözlerimde gözlerinin gülüşü

Demem, söylemem ey ipek tenli yâr! 

Hiç kimseye belli etmem, gördüğümüz düşü...

İlkin ney sesi, beynimin pimi çıktı galiba

Ardından muz kokan teninin çağrısı

Terketti meyhaneyi öbür masalardaki insanlar

Bir saki, bir de ben kaldım

Bunda ne var? ..

Ve

Ve buz kesti zaman, hissettim! ..

Ve

Ve kapandı gözlerim gözlerinin üstüne...

Uyandığımda

“Günaydın” dedi bir polis

Bir baktım ki ne göreyim? 

Eşya, doğa yemyeşil sis...

Kavis içinde kavis...

		Ağustos / 2003', 'HAYAL MEYHANESİ -I- Hayâl meyhanesine oturdum bugün Yeşil şarap istedim sakiden inan Gözlerimin önüne gözlerin geldi Daha ne desin Ceylan? ....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hayal-meyhanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgüledim Kalbimi', 'surguledim-kalbimi-mustafa-ceylan-x2mvp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çapraz çizgiler attım yüreğime

Ne sevebilir, ne de sevilir artık

Müjde! Müjde diyorum sana

Bayramın olsun...

Oysa bu yürek var ya bende

Söz dinlemez, öğüt duymaz sanıyordum

Deli fişek

Çapraz çizgileri görünce susuverdi

Dili tutuldu zavallının...

Vurdum kelepçeyi elime, ayağıma

Üç kurşunla hallettim dilimi,

Söz verdim kendi kendime

Bir daha, bir daha asla

Islatmayacağım mendilimi...

Sürgü çektim kapısına kalbimin

Hiçbir el açamayacak

Uçurumumu yaşamalıyım artık

Gönül kuşunun kanadını kopardım

O bile uçamayacak...', 'Çapraz çizgiler attım yüreğime Ne sevebilir, ne de sevilir artık Müjde! Müjde diyorum sana Bayramın olsun... Oysa bu yürek var ya bende Söz ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/surguledim-kalbimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
